import fs from 'fs';
import os from 'os';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const projectRoot = path.resolve(__dirname, '..');

export const EMBEDDED_CONTENT = {"content/protocols/01-water-purification.json":"{\n  \"protocolId\": \"PR-01\",\n  \"category\": \"WATER\",\n  \"title\": \"흙탕물을 깨끗한 마실 물로 바꾸는 법 (숯과 모래로 만드는 자연 정수기)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[필수 생존]\",\n  \"summary\": \"야생에서 흙탕물을 그대로 마시면 심한 배탈과 설사로 탈수 위험에 빠집니다. 나뭇가지 삼발이에 고깔을 달고 숯, 모래, 자갈을 차례로 쌓으면 흙탕물을 투명하게 걸러낼 수 있습니다. 걸러낸 물을 모닥불에서 큰 거품이 일도록 3분 이상 펄펄 끓이면 미세 세균까지 완전히 사멸되어 안전하게 마실 수 있습니다.\",\n  \"timeRequired\": \"25분 (물 거르기 15분 + 가열 10분)\",\n  \"successRate\": \"99.9% (순서대로 적층 후 3분 이상 끓일 때)\",\n  \"difficulty\": \"보통 (자연물만으로 누구나 제작 가능)\",\n  \"outputPerHour\": \"시간당 1.5 ~ 2리터 정수\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"참나무 숯 (콩알 크기 두 줌)\",\n      \"desc\": \"불순물과 악취를 흡수하여 걸러냅니다. 쌀알보다 크고 콩알 크기(5~8mm)로 부수어 준비합니다.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"세척한 고운 강모래 (두 줌)\",\n      \"desc\": \"미세한 흙먼지를 걸러냅니다. 냇물에 두세 번 헹구어 진흙을 제거한 깨끗한 모래를 사용합니다.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"작은 둥근 자갈 (한 줌)\",\n      \"desc\": \"손톱 크기의 작은 돌입니다. 굵은 불순물을 막고, 물을 부을 때 모래가 파이지 않도록 수압을 분산합니다.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"자작나무 껍질 고깔 또는 대나무 통 1개\",\n      \"desc\": \"길이 30~40cm로 아래가 좁아지는 원통형 용기입니다. 여과 재료를 고정하고 물방울을 한곳으로 모읍니다.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"손가락 굵기 나뭇가지 3개 (길이 50cm)\",\n      \"desc\": \"윗부분을 묶어 바닥에 세우는 삼발이 거치대입니다. 고깔 아래에 물받이 그릇을 놓을 수 있게 지탱합니다.\"\n    },\n    {\n      \"id\": \"mat-06\",\n      \"name\": \"깨끗한 물이끼 또는 헝겊 조각\",\n      \"desc\": \"고깔 맨 아래 배출구를 막아 숯과 모래가 아래로 쏟아져 내리지 않도록 받쳐주는 필터 마개입니다.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"1단계: 나뭇가지 3개로 삼발이를 세우고 고깔 달기\",\n      \"description\": \"1. **삼발이 조립**: 손가락 굵기 나뭇가지 3개의 윗부분을 [야생 칡덩굴 밧줄](/protocol-05.html)이나 끈으로 단단히 묶어 바닥에 세웁니다.\\n2. **고깔 수직 거치**: 자작나무 껍질 고깔이나 대나무 통을 삼발이 중심에 흔들리지 않게 수직으로 묶습니다.\\n3. **하단 배출구 마개 밀착**: 물이 빠져나올 맨 아래 구멍에 깨끗한 물이끼나 헝겊을 손가락으로 꾹 눌러 채웁니다. 마개가 헐거우면 여과재가 쏟아져 내립니다.\",\n      \"actionNote\": \"> 마개 점검: 마개가 느슨하면 숯가루가 새어 나옵니다. 손가락으로 밀었을 때 빠지지 않도록 단단히 밀착하세요.\",\n      \"svgFileName\": \"pr01-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PURIFICATION STEP 1: 프레임 거치 및 하단 마개\",\n        \"나뭇가지 3개 삼발이 거치대\",\n        \"고깔 모양 자작나무 껍질 여과관\",\n        \"바닥 구멍을 꽉 막은 물이끼 마개\",\n        \"[1단계 핵심] 흔들리지 않는 삼발이 & 튼튼한 바닥 마개\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"2단계: 숯을 콩알 크기로 깨서 맨 아래에 8cm 채우기\",\n      \"description\": \"1. **숯 분쇄 및 선별**: 식은 [참나무 숯](/protocol-09.html)을 돌로 가볍게 두드려 **콩알 크기(5~8mm)**로 깹니다. 밀가루 같은 미세 분말은 물길을 막으므로 골라내어 버립니다.\\n2. **숯층 8cm 충진**: 고깔 안쪽 마개 위에 부순 숯을 넣고, 나뭇가지 끝으로 살살 눌러 **손가락 4마디 높이(약 8cm)**로 평평하게 채웁니다.\",\n      \"actionNote\": \"> 입자 규격: 쌀알보다 크고 콩알 크기의 알갱이를 사용합니다. 미세 가루는 필터 유속을 저하시킵니다.\",\n      \"svgFileName\": \"pr01-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // PURIFICATION STEP 2: 숯 흡착층 형성\",\n        \"콩알 크기로 부순 까만 숯 알갱이\",\n        \"나쁜 냄새와 독소를 빨아들이는 숯 구멍\",\n        \"손가락 네 마디 높이 (8cm) 채우기\",\n        \"[2단계 핵심] 콩알 크기 숯을 8cm 채우고 살살 다지기\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD SCIENCE\",\n        \"title\": \"숯이 물속 오염 물질을 걸러내는 원리\",\n        \"text\": \"나무가 고온에서 타며 산소가 차단될 때 숯 내부에 수억 개의 미세 구멍이 생깁니다. 이 미세 구멍들이 물속에 녹아 있는 악취 분자와 유기 오염 물질을 표면에 물리적으로 강하게 붙잡아 둡니다.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"3단계: 씻은 고운 모래를 숯 위에 6cm 두께로 덮기\",\n      \"description\": \"1. **강모래 세척**: 냇가의 고운 모래를 물에 두세 번 헹구어 진흙 찌꺼기를 제거합니다.\\n2. **모래층 6cm 적층**: 씻은 모래를 숯 위에 붓고 **손가락 3마디 높이(약 6cm)**로 채웁니다.\\n3. **수평 다듬기**: 납작한 돌이나 손바닥으로 표면을 평평하게 다듬습니다. 모래층이 기울어지면 얇은 쪽으로만 물이 흘러 정수 효과가 떨어집니다.\",\n      \"actionNote\": \"> 수평 유지: 모래 표면이 평평해야 물이 전 영역으로 균일하게 스며듭니다.\",\n      \"svgFileName\": \"pr01-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // PURIFICATION STEP 3: 미세 모래층 적층\",\n        \"물에 깨끗이 헹군 고운 강모래\",\n        \"미세한 흙먼지 찌꺼기 촘촘히 차단\",\n        \"손가락 세 마디 높이 (6cm) 채우기\",\n        \"[3단계 핵심] 숯 위에 모래를 6cm 평평하게 깔기\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"4단계: 작은 자갈을 4cm 얹고 흙탕물 붓기 (첫 1~2컵 폐기)\",\n      \"description\": \"1. **자갈 완충층 4cm 적층**: 모래 위에 손톱 크기 자갈을 **손가락 2마디 높이(약 4cm)**로 얹고, 넓은 잎 한 장을 덮습니다.\\n2. **흙탕물 주입**: 잎 위로 흙탕물을 천천히 붓습니다. 자갈과 잎이 수압을 분산시켜 모래 파임을 방지합니다.\\n3. **초기 세척수 폐기**: 하단에서 떨어지는 **첫 1~2컵(약 300ml)**은 내부 숯가루가 씻겨 나오는 세척수이므로 **반드시 버립니다**.\\n4. **맑은 물 채취**: 물이 유리알처럼 투명하게 떨어지기 시작하면 깨끗한 그릇으로 받습니다.\",\n      \"actionNote\": \"> 첫물 폐기 수칙: 첫 1~2컵은 필터 내부를 청소하는 물입니다. 맑은 물이 나올 때까지 음용하지 마세요.\",\n      \"svgFileName\": \"pr01-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // PURIFICATION STEP 4: 자갈층 및 초기 세척\",\n        \"수압을 분산하는 손톱 크기 자갈층 (4cm)\",\n        \"숯가루 청소 물 (첫 1~2컵 버리기)\",\n        \"1초에 한 방울씩 떨어지는 맑은 물방울\",\n        \"[4단계 핵심] 자갈로 모래를 지키고 첫 1~2컵 버리기\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"5단계: 걸러낸 맑은 물을 불에 올려 3분 이상 펄펄 끓이기\",\n      \"description\": \"1. **가열 용기 안착**: 투명하게 걸러진 물을 돌 그릇이나 대나무 통에 담아 [활비비 마찰 발화 모닥불](/protocol-02.html) 위에 올립니다.\\n2. **3분 이상 가열 유지**: 물 전체에 큰 거품이 솟구치며 끓기 시작하면, 최소 **3분 이상(해발 1,000m 이상 고지대는 5분 이상)** 가열을 유지합니다.\\n3. **방랭 후 음용**: 충분히 식힌 뒤 안전하게 마십니다.\",\n      \"actionNote\": \"> 필수 가열: 투명해 보인다고 끓이지 않고 마시면 안 됩니다. 물리 여과 후 끓여야 세균이 사멸됩니다.\",\n      \"svgFileName\": \"pr01-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // PURIFICATION STEP 5: 100℃ 비등 멸균\",\n        \"주먹만 한 큰 거품이 솟구치는 펄펄 끓는 물\",\n        \"최소 3분 이상 가열 유지 (산속은 5분)\",\n        \"눈에 안 보이는 나쁜 세균 99.9% 완전 박멸\",\n        \"[5단계 핵심] 투명한 물도 반드시 3분 이상 펄펄 끓이기\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD SCIENCE\",\n        \"title\": \"투명한 물도 반드시 끓여야 하는 이유\",\n        \"text\": \"숯과 모래 필터는 눈에 보이는 흙탕물 입자와 냄새를 걸러내지만, 미세 기생충 포낭과 바이러스는 통과할 수 있습니다. 100℃에서 3분간 가열하면 병원균의 단백질이 파괴되어 99.9% 무력화됩니다.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"치명적 실수: 걸러낸 투명한 물을 끓이지 않고 그대로 마시는 행위\",\n    \"description\": \"숯과 모래는 눈에 보이는 흙탕물과 냄새만 걸러낼 뿐입니다. 미세 기생충과 세균은 물속에 그대로 남아 있습니다. 아무리 물이 차갑고 투명해 보여도 끓이지 않고 마시면 몇 시간 후 심한 복통과 설사로 급격한 탈수에 빠집니다.\",\n    \"consequence\": \"결과: 심한 배탈과 설사로 급격한 탈수가 발생하여 생명 위험\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"야생에서 흙탕물 그냥 마시면 배탈 나서 사흘 안에 쓰러집니다! 자연물 정수기 만드는 법!\",\n    \"body\": \"나뭇가지 삼발이에 고깔을 달고 바닥을 이끼로 막으세요. 그 위에 콩알 크기 숯 8cm, 고운 모래 6cm, 작은 자갈 4cm를 차례로 쌓고 흙탕물을 붓습니다. 첫 2컵은 숯가루 청소 물이니 버리고 투명한 물만 받으세요. 가장 중요한 규칙! 투명해도 끓이지 않으면 세균 때문에 탈이 납니다. 반드시 불에 올려 3분 이상 펄펄 끓여야 안전한 물이 됩니다!\",\n    \"outro\": \"인터넷이 끊겨도 볼 수 있는 오프라인 생존 도면은 프로필 링크에서 확인하세요.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr01-outcome.svg\",\n    \"title\": \"숯·모래 3중 여과 자연 정수기 완성 형태\",\n    \"description\": \"나뭇가지 삼발이에 매단 용기 내부에 숯, 고운 모래, 자갈, 섬유 마개가 층별로 적층되어 상단의 흙탕물이 하단에서 맑고 투명한 물로 여과되는 구조입니다.\"\n  },\n  \"createdAt\": \"2026-10-09T16:00:00.000Z\",\n  \"updatedAt\": \"2026-10-15T15:29:10+09:00\",\n  \"contentHash\": \"8e86ecfb1c03de78\"\n}","content/protocols/02-friction-fire.json":"{\n  \"protocolId\": \"PR-02\",\n  \"category\": \"FIRE\",\n  \"title\": \"나뭇가지 마찰로 불 피우는 법 (활비비 불피우기)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[중요도: 필수 생존]\",\n  \"summary\": \"라이터나 성냥이 없을 때 바싹 마른 나뭇가지와 끈을 이용해 불을 피우는 기술입니다. 활을 앞뒤로 당겨 가운데 막대를 빠르게 회전시키면 마찰열로 400℃의 까만 불씨 가루가 만들어집니다. 이 불씨를 마른 풀 뭉치에 넣고 부드럽게 바람을 불어넣으면 600℃의 큰 불꽃이 타오릅니다.\",\n  \"timeRequired\": \"20분\",\n  \"successRate\": \"85% (바싹 마른 나무 사용 시)\",\n  \"difficulty\": \"보통 (연습 필요)\",\n  \"outputPerHour\": \"20분당 불씨 1개 완성\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"활대와 질긴 천연 끈\",\n      \"desc\": \"길이 60~70cm의 살짝 휜 튼튼한 나뭇가지와, 칡덩굴이나 가죽을 꼬아 만든 질긴 끈입니다. 회전 막대를 강하게 돌려주는 구동 활입니다.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"가운데 회전 막대 (비비는 나무)\",\n      \"desc\": \"엄지손가락 굵기(지름 약 2cm), 길이 25cm의 곧고 바싹 마른 나뭇가지입니다. 아래쪽은 연필 모양으로 깎아 마찰판에 맞물립니다.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"바닥 받침 나무와 마른 풀 뭉치\",\n      \"desc\": \"두께 1.5~2cm의 평평하고 건조한 나무판과, 불씨를 받아 감쌀 새둥지 모양의 마른 풀·억새 솜털 뭉치입니다.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"1단계: 바닥 받침 나무에 불씨가 모일 45도 V자 홈 파기\",\n      \"description\": \"1. **홈 시작 구멍 파기**: 받침 나무 가장자리에서 안쪽으로 **1~1.5cm 지점**에 회전 막대 끝으로 비벼 작은 오목한 자리를 냅니다.\\n2. **45도 V자 홈 절삭**: 돌칼을 이용해 나무 가장자리에서 시작 구멍 한가운데까지 피자 한 조각 모양의 **45도 각도 V자 홈**을 파냅니다.\\n3. **받침 잎 깔기**: 파낸 V자 홈 바로 밑바닥에 불씨 가루를 온전히 받아낼 마른 넓은 나뭇잎을 꼼꼼히 깔아둡니다.\",\n      \"actionNote\": \"> 홈 정밀도: V자 홈의 뾰족한 끝점이 반드시 구멍 한가운데에 닿아야 합니다. 어긋나면 마찰로 갈려 나오는 뜨거운 가루가 밖으로 빠져나오지 못하고 막대 주변에 갇혀 불씨가 생기지 않습니다.\",\n      \"svgFileName\": \"02-step-01.svg\",\n      \"svgLabels\": [\n        \"불씨 받침 나뭇잎\",\n        \"45° V자 홈 (막대 중심까지 파기)\",\n        \"두께 2cm 가운데 회전 막대\",\n        \"판 두께: 1.5~2cm\",\n        \"바닥 받침 나무\",\n        \"V자 홈 끝점 (구멍 한가운데와 일치)\",\n        \"핵심 준비 포인트:\",\n        \"V자 홈 끝이 막대 중심에 딱 닿아야 함\",\n        \"까만 불씨 가루가 모이는 자리\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PHYSICS\",\n        \"title\": \"V자 홈의 쐐기형 산소 공급 및 탄화 분말 포집 동역학\",\n        \"text\": \"원형 구멍 안에서는 마찰면에 공기가 통하지 않아 목재가 타지 못합니다. 45도 쐐기 홈은 신선한 산소를 지속적으로 흡입하면서, 마찰로 깎인 **400℃ 이상**의 미세 탄화 가루를 한곳에 흩어짐 없이 모아 스스로 타는 불씨 덩어리로 뭉치게 합니다.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"2단계: 위에서 체중으로 누르며 활대를 앞뒤로 길게 당기기\",\n      \"description\": \"1. **활줄 1회 감기**: 활대의 끈 한가운데에 회전 막대를 **1바퀴 단단히 감아** 미끄러지지 않도록 팽팽하게 겁니다.\\n2. **체중 12~15kg 누르기**: 왼발로 받침 나무를 밟아 바닥에 고정하고, 손잡이 돌이나 나무로 막대 윗부분을 **수직으로 강하게** 누릅니다.\\n3. **전장 왕복 활질**: 활대를 수평으로 유지하며 앞뒤 끝까지 길게 당기고 밉니다. 처음에는 천천히 돌리며 자리를 잡습니다.\\n4. **연기 발생 후 전력 질주**: 짙은 하얀 연기가 피어오르기 시작하면 속도를 높여 **마지막 5초 동안 15회 이상 온 힘을 다해** 빠르게 왕복합니다.\",\n      \"actionNote\": \"> 발열 한계 돌파: 연기가 조금 난다고 바로 멈추면 열기가 식어 불씨가 되지 않습니다. 하얀 연기가 자욱하게 뿜어져 나온 뒤에도 10~15번 더 끝까지 밀어붙여야 400℃ 발화점에 도달합니다.\",\n      \"svgFileName\": \"02-step-02.svg\",\n      \"svgLabels\": [\n        \"손잡이 누름판\",\n        \"위에서 체중 실어 누르기 (12~15kg)\",\n        \"활대 (길이 65cm 휘어진 나뭇가지)\",\n        \"활대 끝에서 끝까지 길게 당기고 밀기\",\n        \"빠르게 양방향 회전\",\n        \"바닥 받침 나무\",\n        \"하얀 연기가 피어오름\",\n        \"불씨 만드는 핵심:\",\n        \"마찰 열기: 400°C 이상\",\n        \"누르는 힘: 약하게 → 세게\",\n        \"활대 전체 길이를 끝까지 사용\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"왕복 기계 에너지의 마찰열 변환과 400℃ 탄화 임계점\",\n        \"text\": \"활대의 왕복 운동 에너지는 회전 막대 끝의 미세한 접촉면에서 급격한 열에너지로 바뀝니다. 나무는 **250℃부터** 까맣게 그을리기 시작하지만, 스스로 발열을 유지하며 타오르는 잉걸불(Coal) 덩어리가 되려면 접촉부 온도가 **400℃를 반드시** 넘어야 합니다.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"3단계: 마른 풀 둥지에 불씨를 넣고 45도 위로 들어 불붙이기\",\n      \"description\": \"1. **불씨 뭉침 대기**: 활질을 멈추고 V자 홈 아래 나뭇잎에 모인 까만 숯가루 덩어리를 건드리지 말고 **30초간 가만히** 둡니다. 연기가 피어오르며 단단한 잉걸불로 뭉쳐집니다.\\n2. **부싯깃 둥지 안치**: 마른 풀과 억새 솜털을 둥지 모양으로 오목하게 만든 뒤, 불씨 덩어리를 한가운데에 조심스럽게 쏟아 넣습니다.\\n3. **45도 상향 거치**: 둥지를 눈높이보다 높은 **45도 각도**로 비스듬히 들고, 연기를 피하며 불씨를 향해 **길고 부드럽게** 입김을 불어넣습니다.\\n4. **불꽃 점화**: 산소가 공급되면서 붉은빛이 번지고 **15~20초 안에 600℃ 불꽃**이 확 피어오르면 즉시 준비된 잔가지 모닥불로 옮깁니다.\",\n      \"actionNote\": \"> 앙각 송풍 법칙: 둥지를 눈높이보다 45도 위로 들면 피어오르는 연기가 눈을 찌르지 않습니다. 또한 대류 현상으로 뜨거운 열기가 부싯깃 내부를 빠르게 예열하여 점화 성공률이 2배 높아집니다.\",\n      \"svgFileName\": \"02-step-03.svg\",\n      \"svgLabels\": [\n        \"달궈진 불씨 덩어리 (450°C)\",\n        \"길고 부드럽게 입김 불기\",\n        \"불꽃이 확 피어오름\",\n        \"45도 기울여 들기\",\n        \"입김 불어 불붙이는 온도 변화\",\n        \"시간 (초)\",\n        \"온도 (°C)\",\n        \"600°C 불꽃이 타오르는 온도\",\n        \"400°C 불씨가 유지되는 온도\",\n        \"30초 기다린 뒤 옮기기 (0초)\",\n        \"불꽃 점화 (15~20초)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD AERODYNAMICS\",\n        \"title\": \"대류 열전달과 600℃ 기체 연소 화염 전이 메커니즘\",\n        \"text\": \"불씨 덩어리(450℃)는 고체 상태의 불완전 연소 잉걸불입니다. 부드러운 산소 기류가 공급되면 숯 표면에서 일산화탄소와 가연성 가스가 뿜어져 나오며, 국소 온도가 **600℃에 도달하는 순간** 기체 연소인 '자유 화염(Flame)'으로 폭발적으로 번져나갑니다.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"절대 피해야 할 실수: 갓 모인 불씨 가루에 급하게 센 바람 불기\",\n    \"description\": \"활대질을 멈추자마자 마음이 급해 나뭇잎 위의 까만 가루에 입김을 강하게 불어버리면, 아직 단단하게 뭉치지 못한 불씨 가루가 사방으로 흩어져 열기가 순식간에 식어버립니다.\",\n    \"consequence\": \"조치: 가루에서 연기가 나기 시작하면 손대지 말고 30초 동안 스스로 열을 모아 단단한 잉걸불이 될 때까지 기다린 뒤 부싯깃으로 옮기세요.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr02-outcome.svg\",\n    \"title\": \"보우 드릴 마찰열 발화 및 불씨 착화 완성 형태\",\n    \"description\": \"화판의 45도 V홈에 마찰열로 생성된 검은 숯가루 잉걸불(400℃)이 붉게 타오르며 연기를 피워 올리고, 이를 마른 껍질 부싯깃 둥지로 안전하게 옮겨 불꽃을 피워 올린 실전 발화 완성 상태입니다.\"\n  },\n  \"createdAt\": \"2026-10-09T16:05:00.000Z\",\n  \"updatedAt\": \"2026-10-15T15:45:00+09:00\",\n  \"contentHash\": \"006f8f1c7593c632\"\n}","content/protocols/03-프로토콜-03-데브리-헛-debris-hut-a프레임-단열-은신처-구축법.json":"{\n  \"protocolId\": \"PR-03\",\n  \"category\": \"SHELTER\",\n  \"title\": \"불 없이 체온을 지키는 낙엽 움막 만드는 법 (데브리 헛)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[중요도: 필수 생존]\",\n  \"summary\": \"찬 바람과 비가 치는 야생에서 맨몸으로 밤을 보내면 3시간 안에 체온이 떨어져 위험해집니다. 불을 피울 수 없을 때 주변의 나뭇가지와 마른 낙엽을 두껍게 쌓아, 두꺼운 침낭처럼 내 몸의 온기를 가두어 따뜻하게 자는 방법입니다.\",\n  \"timeRequired\": \"90~120분\",\n  \"successRate\": \"92% (낙엽 두께 60cm 이상 쌓았을 때)\",\n  \"difficulty\": \"보통 (도구 없이 가능)\",\n  \"outputPerHour\": \"1인용 보온 움막 1개 완성\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"중심 기둥 나무 (긴 통나무 1개)\",\n      \"desc\": \"어른 키의 두 배 정도 길이(3.0~3.5m), 팔뚝 굵기(10~15cm)의 튼튼하고 곧은 마른 나무 1개입니다.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Y자 기둥 나무 2개와 양옆에 기댈 나뭇가지들\",\n      \"desc\": \"끝이 Y자로 갈라진 가슴 높이(1.5m) 나무 2개와, 양옆 벽을 만들 팔 길이(1~1.5m)의 나뭇가지 40~50개입니다.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"바싹 마른 낙엽과 마른 풀 (최대한 많이)\",\n      \"desc\": \"물기가 전혀 없는 마른 낙엽, 솔잎, 마른 풀을 큰 자루 수십 개 분량으로 넉넉히 모읍니다.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"1단계: Y자 기둥 2개를 세우고 중심 통나무 올리기\",\n      \"description\": \"1. **Y자 지지대 맞물림 결속**: 끝이 Y자로 갈라진 튼튼한 나무 2개를 마주 세워 윗부분을 맞물려 **높이 80cm~1m** 삼각 다리를 만듭니다.\\n2. **중심 용마루 거치**: 길이 **3.0~3.5m** 굵은 통나무 한쪽 끝을 삼각 다리 위에 얹고, 반대쪽 끝은 바람 불어오는 쪽 바닥에 단단히 고정합니다.\\n3. **체형 맞춤 규격 점검**: 누웠을 때 어깨 양옆으로 주먹 하나 크기인 **여유 공간 약 10cm**만 남도록 내부 폭을 좁게 유지합니다.\",\n      \"actionNote\": \"> 체적 최소화 법칙: 움막 안이 넓으면 사람 체온만으로 공기를 데울 수 없습니다. 몸에 딱 맞게 좁아야 침낭처럼 훈훈한 온기가 유지됩니다.\",\n      \"svgFileName\": \"pr03-step-01.svg\",\n      \"svgLabels\": [\n        \"움막 크기 핵심 규칙:\",\n        \"몸이 겨우 들어갈 크기 (어깨 옆 주먹 1개 여유)\",\n        \"바람 불어오는 쪽 (바닥에 고정)\",\n        \"중심 기둥 나무: 길이 3.0~3.5m\",\n        \"Y자 기둥 2개 맞물려 묶기\",\n        \"내부 공간: 몸 둘레 + 10cm (주먹 1개 여유)\",\n        \"입구 높이: 0.8~1.0m\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"내부 체적 최소화와 인체 복사열 자가 축열 법칙\",\n        \"text\": \"무난방 야전 은신처의 유일한 열원은 사람의 체온(**약 100W 복사열**)입니다. 내부 공간이 넓으면 체온으로 공기를 데우지 못해 저체온증에 빠집니다. 체형에 딱 맞게 체적을 최소화해야 공기 순환을 막고 체온만으로 침낭처럼 훈훈한 온기를 가둘 수 있습니다.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"2단계: 양옆에 나뭇가지를 촘촘히 기대고 바닥에 낙엽 두껍게 깔기\",\n      \"description\": \"1. **늑골 가지 45도 배열**: 중심 통나무 양옆에 나뭇가지 40~50개를 **45~60도 각도**로 빈틈없이 촘촘하게 기댑니다.\\n2. **바닥 냉기 차단재 투입**: 바닥에 바싹 마른 낙엽을 무릎 높이인 **두께 40cm 이상** 수북하게 깔아줍니다.\\n3. **체중 압축 후 잔여 두께 확인**: 사람이 누워 눌렸을 때도 최소 한 뼘인 **압축 두께 20cm 이상**이 유지되는지 확인합니다.\",\n      \"actionNote\": \"> 전도 냉기 방어: 차가운 맨땅은 찬 공기보다 체온을 20배 빠르게 빼앗습니다. 지붕보다 바닥 낙엽 이불이 두꺼워야 얼지 않습니다.\",\n      \"svgFileName\": \"pr03-step-02.svg\",\n      \"svgLabels\": [\n        \"바닥 냉기 차단 핵심:\",\n        \"마른 낙엽을 두껍게 깔아 눌린 뒤에도 20cm 유지\",\n        \"중심 기둥 나무 (단면)\",\n        \"양옆 나뭇가지: 45°~60° 각도로 촘촘히 세우기\",\n        \"낙엽 이불: 40cm → 눌린 뒤 20cm\",\n        \"땅에서 올라오는 찬 기운 완벽 차단\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PHYSICS\",\n        \"title\": \"지표면 전도 열손실과 건조 낙엽의 정적 공기 단열층\",\n        \"text\": \"차가운 땅과의 직접 접촉에 의한 전도 열손실은 공기 중 대류보다 **20배 이상** 빠릅니다. 마른 낙엽 내부의 수많은 미세 공기층은 열전도율이 **0.025W/m·K**로 매우 낮아, 땅바닥에서 올라오는 냉기를 완벽히 차단합니다.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"3단계: 지붕에 낙엽을 팔 길이만큼 쌓고 무거운 가지로 덮기\",\n      \"description\": \"1. **잔가지 거름망 안치**: 나뭇가지 벽 위에 마른 잔가지를 엮어 낙엽이 안으로 쏟아지지 않게 받침망을 만듭니다.\\n2. **외벽 낙엽 60~90cm 적층**: 마른 낙엽을 바닥부터 처마 끝까지 팔 전체 길이인 **두께 60~90cm**로 산더미처럼 두껍게 덮습니다.\\n3. **바람막이 겉가지 누름**: 강풍에 낙엽이 날아가지 않도록 무거운 나뭇가지를 격자 형태로 얹어 꾹 눌러줍니다.\\n4. **낙엽 마개로 입구 밀폐**: 안으로 들어간 뒤 입구를 마른 낙엽 뭉치로 막아 외부 찬 바람의 유입을 완벽히 차단합니다.\",\n      \"actionNote\": \"> 건조 낙엽 엄수: 젖은 낙엽을 섞어 쓰면 수분이 증발하면서 오히려 체온을 빼앗아 갑니다. 반드시 바싹 마른 낙엽만 골라 쓰세요.\",\n      \"svgFileName\": \"pr03-step-03.svg\",\n      \"svgLabels\": [\n        \"지붕 낙엽 쌓기 & 입구 막기:\",\n        \"지붕에 낙엽을 팔 길이(60~90cm)로 쌓고 입구 막기\",\n        \"마른 낙엽 벽: 60~90cm 두께\",\n        \"바람에 안 날리게 무거운 가지 덮기\",\n        \"빗물이 타고 흐르는 경사면\",\n        \"따뜻한 공기가 갇힌 내부 & 낙엽 마개\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD ARCHITECTURE\",\n        \"title\": \"급경사 빗물 배수와 다층 낙엽의 자연 방수 구조\",\n        \"text\": \"낙엽을 **45도 이상** 가파른 경사로 **60cm 이상** 쌓으면, 나뭇잎 표면의 왁스 성분과 겹겹이 층을 이룬 구조가 기와처럼 작용하여 빗물이 내부로 스며들지 않고 바깥으로 흘러내립니다.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"절대 하면 안 되는 실수: 편하게 앉으려고 움막을 크게 짓거나 젖은 낙엽 쓰기\",\n    \"description\": \"텐트처럼 안에서 앉아 있으려고 천장을 높이고 공간을 넓게 만들면, 사람 몸에서 나오는 열기만으로는 그 넓은 공간의 찬 공기를 절대 데울 수 없습니다. 또한 젖은 낙엽을 깔면 밤새 냉기가 올라와 체온이 급격히 떨어집니다.\",\n    \"consequence\": \"결과: 반드시 몸이 겨우 들어갈 만큼 좁게 만들고, 바싹 마른 낙엽만 두껍게 쌓아야 밤새 체온을 지킬 수 있습니다.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr03-outcome.svg\",\n    \"title\": \"A-프레임 데브리 헛 (낙엽 단열 은신처) 완성 외관\",\n    \"description\": \"2.5m 굵은 용마루와 45도 갈비뼈 가지 프레임 위에 1미터 두께의 마른 낙엽층을 압축 적층하고 겉가지 격자를 덮어 강풍과 비바람을 막는 무난방 체온 보존 은신처 완성 외관입니다.\"\n  },\n  \"createdAt\": \"2026-10-09T16:08:00.000Z\",\n  \"updatedAt\": \"2026-10-15T16:00:00+09:00\",\n  \"contentHash\": \"5c83ac034006645f\"\n}","content/protocols/04-stone-axe-making.json":"{\n  \"protocolId\": \"PR-04\",\n  \"category\": \"TOOLS\",\n  \"title\": \"깬 돌과 칡덩굴로 나무 베는 돌도끼 만드는 법\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[중요도: 핵심 도구]\",\n  \"summary\": \"맨손으로는 움막 기둥이나 땔감으로 쓸 굵은 나뭇가지를 자를 수 없습니다. 강가에서 주운 단단한 돌 두 개를 45도 각도로 부딪쳐 날카로운 돌날을 떼어내고, 나무 자루 틈에 송진과 젖은 칡덩굴로 단단히 묶어 튼튼한 돌도끼를 만드는 방법입니다.\",\n  \"timeRequired\": \"60분\",\n  \"successRate\": \"90% (45도 각도로 모서리를 칠 경우)\",\n  \"difficulty\": \"보통 (초보자 가능)\",\n  \"outputPerHour\": \"돌도끼 1자루 완성\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"단단한 강돌 1개와 둥근 망치돌 1개\",\n      \"desc\": \"깨졌을 때 유리처럼 날카로운 모서리가 생기는 단단한 강돌(어른 주먹 2개 크기) 1개와, 손에 쥐고 내리칠 둥글고 묵직한 망치돌 1개입니다.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"팔뚝 길이의 단단한 나무 자루 (참나무·물푸레나무)\",\n      \"desc\": \"세게 내리쳐도 부러지지 않는 단단한 생나무 가지(길이 40~50cm, 손목보다 조금 가는 지름 3.5~4cm 굵기) 1개입니다.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"물에 적신 칡덩굴 속껍질과 소나무 송진\",\n      \"desc\": \"마르면서 스스로 오그라들어 꽉 조여지는 젖은 [칡덩굴 야생 밧줄](/protocol-05.html)(길이 3m 이상)과, 나무 상처에서 굳은 [소나무 송진 방수 접착제](/protocol-10.html) 한 주먹입니다.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"돌과 돌을 45도 각도로 부딪쳐 날카로운 돌날 떼어내기\",\n      \"description\": \"1. **하부 받침돌 수평 거치**: 바닥에 **너비 15~20cm** 크기의 큰 강돌을 흔들리지 않게 단단히 받쳐 놓습니다.\\n2. **타격 지점 설정**: 모서리 끝에서 손가락 한 마디인 **1~2cm 안쪽**을 정확한 타격 지점으로 조준합니다.\\n3. **45도 경사 모서리 가격**: 손에 쥔 둥근 망치돌로 강돌 가장자리 모서리를 **45도 각도**로 비스듬히 강하게 내리칩니다.\\n4. **박리 돌날 선별**: 손바닥 크기에 날 두께가 **1~2cm**이고 끝이 면도날처럼 날카로운 돌날 조각을 떼어냅니다.\",\n      \"actionNote\": \"> 타격 각도 엄수: 평평한 한가운데를 90도 수직으로 치면 충격파가 분산되어 돌 전체가 부서집니다. 반드시 모서리를 45도 사각으로 쳐야 얇고 예리한 날이 떨어져 나옵니다.\",\n      \"svgFileName\": \"pr04-step-01.svg\",\n      \"svgLabels\": [\n        \"① 둥근 망치돌 (내리치는 돌)\",\n        \"② 모서리 45° 비스듬히 치기\",\n        \"날카로운 돌날 (두께 1~2cm)\",\n        \"④ 쪼개져 나온 도끼날 돌조각\",\n        \"③ 바닥에 받친 큰 강돌 (너비 15~20cm)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD GEOLOGY\",\n        \"title\": \"패각상 단구(Conchoidal Fracture)와 충격파 분산 역학\",\n        \"text\": \"석영과 규암은 결정 격자가 없어 강한 타격 시 조개껍데기 물결 모양으로 깨지는 **패각상 단구** 특성을 보입니다. 타격 각도를 **45도**로 설정하면 충격 에너지가 표면으로 유도되어, 두께 **1~2cm**의 극도로 예리한 절삭날이 박리됩니다.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"나무 자루 윗부분을 쪼개어 돌날 끼우고 송진 채우기\",\n      \"description\": \"1. **자루 갈라짐 방지 가결속**: 자루가 세로로 쪼개지는 것을 막기 위해 상단에서 **10cm 아래쪽**을 [질긴 야생 밧줄](/protocol-05.html)로 먼저 단단히 묶습니다.\\n2. **상단 세로 쪼개기**: 단단한 생나무 자루 윗부분을 날카로운 돌로 **깊이 5~7cm** 홈을 파 세로로 쪼갭니다.\\n3. **돌날 중심 삽입**: 쪼갠 틈 사이에 돌날의 두꺼운 뒷부분을 끝까지 깊숙이 밀어 넣습니다.\\n4. **송진 복합 접착제 충진**: 불에 녹인 [소나무 송진](/protocol-10.html)에 곱게 빻은 [참나무 숯가루](/protocol-09.html)를 **1:1 비율**로 섞어 자루 틈새 빈 공간에 가득 채웁니다.\",\n      \"actionNote\": \"> 복합재 혼합 법칙: 순수 송진만 바르면 식었을 때 유리처럼 바스러집니다. 불 피우고 남은 [참나무 숯가루](/protocol-09.html)를 섞어야 충격 흡수력이 생겨 부서지지 않는 [천연 방수 에폭시](/protocol-10.html)가 됩니다.\",\n      \"svgFileName\": \"pr04-step-02.svg\",\n      \"svgLabels\": [\n        \"① 위에서 아래로 돌날 끼우기\",\n        \"나무 자르는 앞날\",\n        \"② 쪼갠 나무 자루 틈 (5~7cm)\",\n        \"③ 녹인 송진 + 숯가루 채우기\",\n        \"④ 더 안 갈라지게 아래쪽 먼저 묶기\",\n        \"생나무 자루 굵기: 지름 3.5~4cm\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD CHEMISTRY\",\n        \"title\": \"테르펜 수지와 탄소 분말 복합재(Composite Epoxy) 물성\",\n        \"text\": \"소나무 송진의 테르펜(Terpene) 성분은 건조 후 고분자화되지만 충격에 매우 취약합니다. 미세한 탄소(숯) 분말을 혼합하면 탄소 입자가 균열 전파를 물리적으로 차단하여, 현대의 **카본 에폭시 복합재**와 동일한 충격 흡수 탄성을 발휘합니다.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"젖은 칡덩굴 줄기로 X자 모양으로 단단히 감아 말리기\",\n      \"description\": \"1. **속껍질 수분 침지**: [질긴 칡덩굴 속껍질 로프](/protocol-05.html)를 물에 충분히 적셔 부드럽게 유연성을 확보합니다.\\n2. **X자 대각선 결속**: 돌날과 나무 자루를 대각선 X자 모양으로 번갈아 교차하며 **최소 10바퀴 이상** 힘껏 당겨 감습니다.\\n3. **하부 수평 압박 결속**: 남은 줄로 자루 아랫부분을 수평으로 촘촘하게 감아 풀리지 않게 매듭짓습니다.\\n4. **그늘 송풍 건조**: 직사광선을 피해 통풍이 잘되는 그늘에서 완전히 건조시켜 결속력을 극대화합니다.\",\n      \"actionNote\": \"> 그늘 건조 원칙: 빨리 말리려고 모닥불에 쬐면 섬유가 열에 의해 바스러져 끊어집니다. 반드시 바람 부는 그늘에서 자연 건조해야 섬유 조직이 30% 수축하며 강철처럼 조여집니다.\",\n      \"svgFileName\": \"pr04-step-03.svg\",\n      \"svgLabels\": [\n        \"① 젖은 칡 속껍질 X자로 감기\",\n        \"② 날카로운 도끼 앞날\",\n        \"③ 자루 아래쪽 가로로 칭칭 감기\",\n        \"④ 마르면서 30% 줄어들며 꽉 조임\",\n        \"완성 상태: 세게 내리쳐도 돌날이 빠지지 않는 일체형 돌도끼\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BOTANY\",\n        \"title\": \"인피 섬유의 수분 증발에 따른 체적 수축과 영구 장력 고정\",\n        \"text\": \"칡껍질과 같은 인피(Bast) 식물 섬유는 수분을 머금었을 때 세포벽이 팽창했다가, 건조 과정에서 수분이 빠져나가며 **최대 30% 체적 수축**을 일으킵니다. 이때 발생하는 강력한 수축 장력이 돌날과 자루를 금속 볼트처럼 일체화합니다.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"절대 하면 안 되는 실수: 평평한 돌 한가운데를 치거나 마른 덩굴로 묶기\",\n    \"description\": \"돌의 평평한 한가운데를 90도로 내려치면 날카로운 날이 만들어지지 않고 돌 전체가 쓸모없는 자갈로 부서집니다. 또한 물에 적시지 않은 마른 덩굴이나 거친 겉껍질로 묶으면, 나무를 찍는 순간 줄이 끊어지면서 무거운 돌날이 얼굴이나 눈으로 튀어 크게 다칠 수 있습니다.\",\n    \"consequence\": \"결과: 반드시 강돌 모서리를 45도로 쳐서 날을 만들고, 물에 불린 질긴 속껍질로 X자로 감아 그늘에서 말려야 안전하게 나무를 벨 수 있습니다.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr04-outcome.svg\",\n    \"title\": \"깬 돌과 칡덩굴 결속 원시 돌도끼 완성 형태\",\n    \"description\": \"단단한 참나무 Y자 자루 홈에 양면 타제된 날카로운 수석 날을 깊숙이 물리고, 질긴 칡덩굴과 송진 접착제로 X자 십자 결속하여 나무를 거침없이 베어 넘기는 실전 석기 돌도끼 완성 형태입니다.\"\n  },\n  \"createdAt\": \"2026-10-09T16:10:00.000Z\",\n  \"updatedAt\": \"2026-10-15T16:31:51+09:00\",\n  \"contentHash\": \"1c29ec86b6976738\"\n}","content/protocols/05-natural-cordage.json":"{\n  \"protocolId\": \"PR-05\",\n  \"category\": \"TOOLS\",\n  \"title\": \"나무껍질과 칡덩굴을 꼬아 끊어지지 않는 야생 밧줄 만드는 법\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[필수 생존]\",\n  \"summary\": \"움막 기둥을 묶거나 돌도끼를 고정하고 활비비로 불을 피우려면 튼튼한 끈이 꼭 필요합니다. 줄기를 그냥 묶으면 마르면서 뚝 부러지거나 풀려버리지만, 식물 속껍질 섬유를 발라내어 두 가닥을 서로 반대 방향으로 비틀어 꼬면 어른 몸무게도 거뜬히 버티는 질긴 야생 밧줄을 만들 수 있습니다.\",\n  \"timeRequired\": \"40분\",\n  \"successRate\": \"95% (역방향 꼬기 준수 시)\",\n  \"difficulty\": \"보통 (맨손 작업 가능)\",\n  \"outputPerHour\": \"5m / 40분\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"살아있는 칡덩굴 또는 참피나무·버드나무·쐐기풀 줄기 (팔 길이 10~15줄기)\",\n      \"desc\": \"구부렸을 때 부러지지 않고 부드럽게 휘어지며, 손톱으로 겉을 긁었을 때 연두색 물기가 도는 싱싱한 줄기를 골라야 질긴 속껍질을 얻을 수 있습니다.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"겉껍질을 긁어낼 날카로운 돌조각 1개\",\n      \"desc\": \"줄기 바깥의 거칠고 잘 부서지는 갈색 겉껍질만 긁어 벗겨낼 때 씁니다. 너무 날카로워 속껍질 섬유까지 끊어지지 않도록 모서리가 적당히 각진 돌을 고릅니다.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"섬유를 두드릴 평평한 바닥 돌과 주먹만 한 둥근 돌\",\n      \"desc\": \"물에 불린 뻣뻣한 속껍질을 바닥 돌 위에 올려놓고 둥근 돌로 두드려, 가늘고 부드러운 실 결로 풀어줄 때 사용합니다.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"속껍질을 불릴 냇물 또는 고인 물\",\n      \"desc\": \"갓 벗긴 속껍질을 20~30분 동안 담가 두어 뻣뻣한 나무 진액을 빼고, 꼬는 동안 섬유가 꺾이지 않게 촉촉한 상태를 유지하는 데 씁니다.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"1단계: 휘어지는 줄기 골라 거친 겉껍질 긁어내고 하얀 속껍질 벗기기\",\n      \"description\": \"1. **생줄기 유연성 시험**: 줄기를 반으로 천천히 구부려 부러지지 않고 **90도 이상** 탄력 있게 휘어지는 생줄기를 선별합니다.\\n2. **거친 외수피 제거**: 돌 모서리를 줄기에 비스듬히 대고 바깥의 거칠고 잘 부스러지는 **갈색 겉껍질**만 조심스럽게 긁어냅니다.\\n3. **인피 섬유층 노출 확인**: 겉껍질 아래에서 물기를 머금은 **하얗고 질긴 속껍질 섬유**가 드러나는지 눈으로 확인합니다.\\n4. **목질부 속심 분리 박리**: 줄기 아래쪽 끝을 손톱으로 젖힌 뒤 줄기 방향으로 길게 당겨 가운데 **딱딱한 속심을 분리**하고 리본 모양 속껍질만 떼어냅니다.\",\n      \"actionNote\": \"> 채취 원칙: 바닥에 떨어져 말라버린 줄기는 섬유가 삭아 손으로 당기면 부서집니다. 반드시 살아있는 가지나 갓 꺾인 생줄기에서 속껍질을 채취하세요.\",\n      \"svgFileName\": \"pr05-step-01.svg\",\n      \"svgLabels\": [\n        \"① 돌 모서리로 거친 겉껍질만 살살 긁어내기\",\n        \"② 잘 부러지는 갈색 겉껍질 (긁어내어 버림)\",\n        \"③ 질기고 하얀 속껍질 섬유층 (밧줄 핵심 재료)\",\n        \"④ 가운데 딱딱한 나무 속심 (빼내고 버림)\",\n        \"⑤ 구부렸을 때 부러지지 않고 휘어지는 살아있는 줄기\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BOTANY\",\n        \"title\": \"사부 조직(Phloem) 인피 섬유의 인장 강도와 펙틴 분해\",\n        \"text\": \"식물의 외수피(겉껍질)와 목질부(속심) 사이의 **사부 조직(인피 섬유)**은 평행 배열된 셀룰로오스 사슬 구조로 인해 단위 면적당 인장 강도가 연강(Mild Steel)의 **약 50%**에 달합니다. 겉껍질을 분리해야 섬유 손상 없이 순수 인피만을 채취할 수 있습니다.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"2단계: 냇물에 20분 불린 뒤 돌로 두드려 실처럼 부드럽게 풀기\",\n      \"description\": \"1. **수분 침지 펙틴 용출**: 벗겨낸 속껍질 리본을 냇물에 **20~30분 동안** 완전히 담가 뻣뻣한 진액을 녹여냅니다.\\n2. **모루돌 거치**: 물기를 머금은 속껍질을 흔들림 없는 **평평한 바닥 강돌** 위에 넓게 펼쳐 놓습니다.\\n3. **망치돌 연타 섬유 분섬**: 둥근 돌로 위에서 아래로 가볍게 밀며 두드려 거친 결을 부수고 **미세 섬유 다발**로 풀어줍니다.\\n4. **균일 2분할 배분**: 손으로 당겨보아 끊어지지 않는 유연한 섬유 다발을 **굵기가 똑같은 2가닥**으로 균등하게 나눕니다.\",\n      \"actionNote\": \"> 연타 강도 조절: 도끼를 치듯 강하게 내리치면 섬유가 절단됩니다. 둥근 돌로 부드럽게 문지르며 다져야 긴 섬유 조직이 온전히 보존됩니다.\",\n      \"svgFileName\": \"pr05-step-02.svg\",\n      \"svgLabels\": [\n        \"① 냇물에 20분 이상 담가 부드럽게 불린 속껍질\",\n        \"② 둥근 돌로 살살 두드려 섬유 결 쪼개기\",\n        \"③ 머리카락처럼 부드럽게 풀어진 섬유 다발\",\n        \"④ 손가락 굵기로 똑같이 나눈 두 가닥\",\n        \"⑤ 바닥에 흔들리지 않게 받친 평평한 강돌\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"3단계: 바깥으로 비틀고 안쪽으로 넘기는 '역방향 꼬기' 반복하기\",\n      \"description\": \"1. **시작 루프 반접음**: 긴 섬유 다발의 중앙을 왼손 엄지와 검지로 잡고 반으로 접어 **위쪽 가닥**과 **아래쪽 가닥**을 만듭니다.\\n2. **개별 외측 꼬임**: 오른손으로 위쪽 가닥을 잡고 내 몸 바깥 방향(↑)으로 팽팽해질 때까지 **시계 방향 회전**으로 비틉니다.\\n3. **전체 내측 교차**: 바깥으로 꼰 위쪽 가닥을 아래쪽 가닥 너머 내 몸 쪽(↓)으로 감아 넘겨 **반시계 방향 교차**를 완성합니다.\\n4. **지속 잠금 전진**: 왼손 엄지를 전진시켜 교차점을 꽉 쥐고, 새로 위로 올라온 가닥을 **외측 비틀기 후 내측 넘기기** 동작으로 계속 반복합니다.\",\n      \"actionNote\": \"> 역방향 잠금 법칙: 두 줄을 같은 방향으로 꼬면 손을 떼는 순간 즉시 풀립니다. 개별 줄을 바깥으로 꼬고 전체는 안쪽으로 넘겨야 비틀림 힘이 서로 상쇄되어 영구 결속됩니다.\",\n      \"svgFileName\": \"pr05-step-03.svg\",\n      \"svgLabels\": [\n        \"① 위쪽 가닥: 몸 바깥쪽(↑)으로 단단히 비틀기\",\n        \"② 서로 되감기며 톱니처럼 맞물린 밧줄 무늬\",\n        \"③ 왼손 엄지·검지로 꼬인 자리 꽉 눌러 잡기\",\n        \"④ 비튼 위 가닥을 아래 가닥 너머 몸 쪽(↓)으로 넘기기\",\n        \"⑤ 손을 놓아도 절대 풀리지 않는 역방향 잠금 구조\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD MECHANICS\",\n        \"title\": \"역방향 꼬기(Reverse-Wrap)의 회전 토크 상쇄 및 자동 잠금 역학\",\n        \"text\": \"개별 가닥을 시계 방향(Z-꼬임)으로 비틀고 두 가닥 전체를 반시계 방향(S-꼬임)으로 교차시키면, 두 반대 방향의 비틀림 탄성 에너지가 서로 상쇄되는 **토크 평형(Torque Equilibrium)**을 이룹니다. 이 기계적 맞물림 덕분에 매듭 없이도 손을 떼었을 때 풀리지 않습니다.\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"4단계: 짧은 섬유를 10cm씩 겹쳐 꼬아 원하는 길이만큼 끝없이 잇기\",\n      \"description\": \"1. **잔여 길이 10cm 감지**: 한쪽 가닥이 닳아 끝부분이 **약 10cm** 정도 남았을 때 보충 시점으로 판단합니다.\\n2. **신규 섬유 중첩 배치**: 새 섬유 다발 끝을 기존 가닥 옆에 **10cm 길이**로 나란히 겹쳐 밀착시킵니다.\\n3. **일체형 동시 꼬기**: 겹쳐진 두 섬유를 하나의 가닥으로 잡고 동일하게 바깥으로 비틀어 안쪽으로 **3~4회 연속 교차**합니다.\\n4. **이음매 시차 분산 간격**: 위 가닥과 아래 가닥의 연결부가 같은 위치에 겹치지 않도록 **최소 15cm 이상 거리**를 두고 잇습니다.\",\n      \"actionNote\": \"> 이음매 분산 원칙: 두 줄의 연결 부위가 같은 자리에 겹치면 그 부분만 불룩해지고 하중을 받을 때 절단됩니다. 반드시 15cm 이상의 시차를 두고 번갈아 이어야 합니다.\",\n      \"svgFileName\": \"pr05-step-04.svg\",\n      \"svgLabels\": [\n        \"① 끝이 10cm쯤 남아 가늘어진 기존 가닥\",\n        \"② 새 섬유 다발을 10cm 나란히 겹쳐 대기\",\n        \"③ 겹친 두 줄을 한 가닥처럼 함께 비틀어 감기\",\n        \"④ 불룩해지지 않고 매끄럽게 이어진 연결부\",\n        \"⑤ 위·아래 이음매 위치를 한 뼘(15cm) 어긋나게 배치\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD TENSION\",\n        \"title\": \"이음매 시차 분산(Staggered Splice)과 마찰 전단력 전달\",\n        \"text\": \"두 가닥의 연결부를 동일 지점에 두면 국소 단면적이 급변해 인장 하중 작용 시 응력 집중으로 파단됩니다. 이음매를 **최소 15cm 이상** 어긋나게 분산 배치하면, 인접한 연속 섬유가 전달하는 **표면 마찰 전단력(Shear Friction)**에 의해 원래 굵기와 강도를 100% 보존합니다.\"\n      }\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"5단계: 끝부분 풀림 방지 매듭 묶고 나무 기둥에 걸어 몸무게로 당겨보기\",\n      \"description\": \"1. **말단 홀치기 매듭 마감**: 목표 길이(5m 이상)에 도달하면 끝부분 **3cm 지점**을 고리로 감아 당겨 기본 매듭으로 묶습니다.\\n2. **돌날 잔털 전정 정리**: 밧줄 표면에 삐져나온 거친 잔털을 [날카로운 돌날](/protocol-04.html)로 긁어 **직경 5mm**의 매끄러운 원형 단면으로 다듬습니다.\\n3. **하중 지지대 결착**: 팔뚝 굵기 이상의 굵고 튼튼한 생나무 기둥에 완성된 밧줄을 2회 이상 감아 고정합니다.\\n4. **전신 하중 50kg 인장 검증**: 두 손으로 밧줄 끝을 쥐고 **몸무게 50kg 이상**의 체중을 온전히 실어 강하게 당겨 연결부의 미끄러짐이 없는지 확인합니다.\",\n      \"actionNote\": \"> 하중 검사 및 활용: 체중을 실었을 때 이음매가 미끄러지면 얇은 섬유를 한 겹 덧감아 보강하세요. 검증을 통과한 밧줄은 [A프레임 움막 기둥 결속](/protocol-03.html), [돌도끼 자루 고정](/protocol-04.html), [활비비 마찰 발화 활줄](/protocol-02.html), [버드나무 어로 통발 엮기](/protocol-11.html)에 즉시 투입합니다.\",\n      \"svgFileName\": \"pr05-step-05.svg\",\n      \"svgLabels\": [\n        \"① 끝부분 3cm를 접어 묶은 풀림 방지 마감 매듭\",\n        \"② 삐져나온 잔털을 돌날로 깔끔하게 정리\",\n        \"③ 나무 기둥에 걸고 몸무게(50kg+)를 실어 당겨보기\",\n        \"④ 완성된 5mm 굵기 야생 밧줄 (5m 길이)\",\n        \"⑤ 움막 기둥 묶기·돌도끼 고정·활비비 줄로 즉시 활용\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"절대 하면 안 되는 실수: 껍질을 벗기지 않은 초록색 생줄기를 그대로 묶어 쓰기\",\n    \"description\": \"급하다고 칡덩굴이나 나뭇가지를 통째로 감아 움막 기둥이나 돌도끼를 묶으면, 당장은 단단해 보여도 반나절만 지나 수분이 마르면 부피가 줄어들면서 헐거워지고 작은 충격에도 과자처럼 바스라져 부러집니다. 반드시 겉껍질과 나무 속심을 버리고 질긴 속껍질 섬유만 발라내어 역방향으로 꼬아서 써야 마른 뒤에도 끊어지지 않습니다.\",\n    \"consequence\": \"결과: 자는 도중 움막 지붕이 무너지거나 나무를 찍던 돌도끼 날이 빠져 큰 부상을 입음\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"산속에서 끈이 하나도 없을 때, 절대 끊어지지 않는 야생 밧줄을 맨손으로 꼬는 법입니다.\",\n    \"body\": \"죽은 가지는 부러져서 못 씁니다. 휘어지는 칡덩굴의 거친 겉껍질을 돌로 긁어내고 하얀 속껍질만 길게 벗기세요. 물에 20분 불려 돌로 두드리면 실처럼 부드러워집니다. 이제 반으로 접어 위 가닥은 몸 바깥쪽으로 비틀고, 아래 가닥 너머 몸 쪽으로 넘기세요. 짧아지면 새 섬유를 10cm 겹쳐 꼬아 끝없이 이을 수 있습니다.\",\n    \"outro\": \"나무에 걸고 몸무게를 실어 당겨도 안 끊어집니다. 움막 짓기와 돌도끼 고정에 바로 써보세요.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr05-outcome.svg\",\n    \"title\": \"2가닥 역방향 꼬임 천연 밧줄 완성 코일 다발\",\n    \"description\": \"나무 내피와 칡 줄기 섬유를 시계 방향으로 꼬고 반시계 방향으로 교차 엮어 인장 강도 90kg 이상을 견디는 촘촘하고 매끄러운 2가닥 천연 생존 밧줄 코일 완성 다발입니다.\"\n  },\n  \"createdAt\": \"2026-10-13T13:20:00.000Z\",\n  \"updatedAt\": \"2026-10-16T13:34:53+09:00\",\n  \"contentHash\": \"474efda727971489\"\n}","content/protocols/06-clay-hearth.json":"{\n  \"protocolId\": \"PR-06\",\n  \"category\": \"SHELTER\",\n  \"title\": \"진흙과 돌을 쌓아 비바람을 막고 열기를 가두는 원시 화덕 만드는 법\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[체온·식량 필수]\",\n  \"summary\": \"야생에서 바닥에 맨 불을 피우면 바람에 불티가 날려 위험하고 열기의 80%가 허공으로 날아가 장작이 세 배 넘게 듭니다. 찰흙과 모래, 마른 풀을 섞어 이긴 진흙 반죽으로 돌을 감싸 돔 형태의 화덕을 쌓으면, 비바람이 몰아쳐도 꺼지지 않고 밥을 짓거나 밤새 은은한 온기를 품는 훌륭한 생존 열원이 됩니다.\",\n  \"timeRequired\": \"3시간\",\n  \"successRate\": \"90% (초벌 건조 준수 시)\",\n  \"difficulty\": \"보통 (흙 반죽과 돌 쌓기)\",\n  \"outputPerHour\": \"1기 완성 (영구 사용 가능)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"점토질 붉은 찰흙 2바가지 (개울가나 흙벽에서 파낸 끈끈한 흙)\",\n      \"desc\": \"손으로 쥐었을 때 차진 찰떡처럼 뭉쳐지고 손가락 사이에 끈적하게 달라붙는 흙을 고릅니다. 화덕 벽체를 하나로 굳혀주는 주원료입니다.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"굵은 강모래 1바가지 (돌 알갱이가 섞인 마른 흙)\",\n      \"desc\": \"찰흙만 쓰면 마를 때 부피가 줄어들며 산산조각 갈라집니다. 굵은 모래를 섞어주면 단단한 뼈대가 되어 균열을 막아줍니다.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"손가락 길이로 자른 마른 풀잎 또는 짚 1바가지\",\n      \"desc\": \"진흙 반죽 속에서 섬유질 철근 역할을 하여, 불의 뜨거운 열기에도 벽체가 쪼개지거나 부서지지 않게 질기게 잡아줍니다.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"물기 없는 단단한 깬 돌 15~20개 (주먹~머리 크기)\",\n      \"desc\": \"물속에 잠겨 있던 강돌은 열을 받으면 폭발하므로, 물가에서 10m 떨어진 마른 언덕의 햇볕에 바짝 마른 돌만 골라 씁니다.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"1단계: 찰흙 2, 모래 1, 마른 풀 1을 물과 함께 발로 밟아 차진 반죽 만들기\",\n      \"description\": \"1. **재료 황금 배합**: 평평한 땅 위에 **붉은 찰흙 2바가지**, **굵은 모래 1바가지**, 손가락 길이로 자른 **마른 풀 1바가지**를 고루 붓습니다.\\n2. **점진적 가수 혼화**: 물을 한 번에 쏟지 않고 소량씩 끼얹어가며 발뒤꿈치로 힘을 실어 **10분 이상** 치댑니다.\\n3. **폴딩 압축 반죽**: 흙더미를 반으로 접어 다시 밟는 과정을 반복하여 균일한 점토 기질을 만듭니다.\\n4. **점도 탄성 검증**: 주먹 크기 공 모양으로 뭉쳐 손바닥에 얹었을 때 표면에 **실금이 생기지 않는 상태**를 확인합니다.\",\n      \"actionNote\": \"> 반죽 수분 조절: 물이 너무 많으면 반죽이 흘러내려 벽을 쌓을 수 없고, 부족하면 푸석해져 부서집니다. 만두피처럼 뻑뻑하면서도 찰기가 도는 상태가 최적입니다.\",\n      \"svgFileName\": \"pr06-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // CLAY TEMPERING & FIBER MATRIX BLUEPRINT\",\n        \"① 붉은 찰흙 2바가지\",\n        \"끈끈한 점력의 기본 바탕재\",\n        \"+\",\n        \"② 굵은 모래 1바가지\",\n        \"마를 때 오그라듦 방지\",\n        \"+\",\n        \"③ 잘게 자른 마른 풀잎\",\n        \"뼈대 역할을 하는 보강 섬유\",\n        \"④ 물을 조금씩 부어가며 발로 치대기\",\n        \"한 번에 많이 붓지 말고 뒤집으며 밟기\",\n        \"⑤ 차진 반죽 덩어리 완성\",\n        \"주먹 크기로 둥글게 뭉쳐도\",\n        \"겉면에 실금이 가지 않는 상태\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD CERAMICS\",\n        \"title\": \"내화 템퍼링(Refractory Tempering)과 수축 균열 방지 매트릭스\",\n        \"text\": \"순수 점토(찰흙)는 건조 수축률이 **10~15%**에 달해 소성 시 심각한 균열이 발생합니다. 비소성 규사(모래)와 유기물 섬유(마른 풀)를 **2:1:1 부피비**로 혼합하면 모래 입자가 골재 역할을 하고, 탄화된 섬유가 미세 기공을 형성하여 열팽창 응력을 흡수하는 **내화 복합체**가 됩니다.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"2단계: 마른 땅 위에 주먹 크기 돌을 U자 모양으로 놓아 바닥 기초 다지기\",\n      \"description\": \"1. **흡입구 방향 설정**: 바람이 불어오는 반대쪽을 향해 어른 한 뼘 너비인 **폭 약 20cm**의 화구 공간을 비워둡니다.\\n2. **U자형 석재 안치**: 주먹보다 큰 마른 깬 돌들을 바닥에 **U자형 말발굽 형태**로 둘러놓습니다.\\n3. **지면 단열층 포설**: 내부 바닥에 마른 모래와 잔자갈을 **두께 2~3cm**로 깔아 지표면 냉기와 습기를 차단합니다.\\n4. **간극 점토 충진**: 돌 사이 틈새마다 1단계의 점토 반죽을 주먹으로 밀어 넣어 공기 누출 구멍을 메웁니다.\",\n      \"actionNote\": \"> 방풍 각도 준수: 입구가 맞바람을 마주하면 강풍에 불티가 역류해 위험합니다. 반드시 바람을 등지거나 비스듬한 사각으로 입구를 내세요.\",\n      \"svgFileName\": \"pr06-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // FOUNDATION LAYOUT & AIR ENTRY SCHEMATIC\",\n        \"① 앞쪽 장작 넣는 입구 (한 뼘 너비 20cm)\",\n        \"불길 조절과 공기 공급에 알맞은 입구 폭\",\n        \"② U자형 주먹만 한 마른 돌\",\n        \"기초를 지탱하는 1차 뼈대\",\n        \"③ 틈새를 메운 진흙 반죽\",\n        \"돌 사이 공기 누출 완전 차단\",\n        \"④ 바닥 마른 모래·자갈 단열층\",\n        \"차가운 땅바닥 습기와 냉기 차단\",\n        \"⑤ 바람 불어오는 반대쪽으로 입구 배치\",\n        \"강풍에 불티가 역류하거나 꺼지지 않도록 보호\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"3단계: 돌과 진흙을 엇갈려 쌓으며 무릎 높이의 돔형 벽체 올리기\",\n      \"description\": \"1. **점토 쿠션층 도포**: 기초 돌 위에 진흙 반죽을 손바닥 두께인 **두께 약 5cm**로 두껍게 깝니다.\\n2. **지그재그 엇갈림 적층**: 다음 단 돌을 아래 돌 틈새 위에 지그재그로 얹으며 내외벽을 점토로 메웁니다.\\n3. **내향 수렴 돔 조형**: 위로 올라갈수록 벽체를 안쪽으로 오므려 가며 무릎 높이인 **높이 약 45cm**의 둥근 돔을 올립니다.\\n4. **내벽 수막 미장 마감**: 손에 물을 묻혀 연소실 안쪽 벽면을 반질반질하게 문질러 매끄러운 곡면으로 다듬습니다.\",\n      \"actionNote\": \"> 붕괴 방지 골조 원칙: 점토만 쌓으면 자체 무게로 무너집니다. 반드시 돌을 뼈대로 삼고 점토로 두껍게 감싸듯이 일체화해야 합니다.\",\n      \"svgFileName\": \"pr06-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DOME CHAMBER CROSS-SECTION & THERMAL CURVATURE\",\n        \"45cm\",\n        \"① 엇갈려 쌓은 벽체 단면\",\n        \"돌 틈에 진흙을 채워 무너짐 방지\",\n        \"② 손바닥 두께(약 5cm) 진흙벽\",\n        \"바깥으로 새는 열 손실 완벽 차단\",\n        \"③ 매끄러운 열 반사 곡면\",\n        \"손에 물을 묻혀 반질반질하게 다듬기\",\n        \"④ 열기가 모여 회전하는 둥근 연소실 내부\",\n        \"⑤ 무릎 높이(약 45cm) 외형선\",\n        \"취사 안정성과 축열 용적 최적화\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"반구형 돔 내부의 복사열 집중과 650°C 축열 역학\",\n        \"text\": \"반구형 돔(Dome) 내벽은 흑체(Black Body) 복사 거동에 따라 방출되는 적외선을 초점 구역인 상단 조리 화구로 반사 집중시킵니다. **두께 5cm**의 고밀도 점토벽은 비열이 높아, 화염이 꺼진 뒤에도 내부 온도를 **300~650°C**로 수 시간 동안 축열 유지합니다.\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"4단계: 화덕 윗부분에 냄비 받침 구멍을 내고 뒤쪽에 굴뚝 구멍 뚫기\",\n      \"description\": \"1. **상단 조리 화구 개구**: 돔 천장 중앙에 조리용 냄비를 얹을 수 있는 **지름 15~20cm** 크기의 둥근 개구부를 남깁니다.\\n2. **삼각 받침 통기 돌기**: 냄비 바닥에 불길이 막히지 않도록 구멍 둘레에 작은 돌 3개를 박아 **1cm 통기 간극**을 만듭니다.\\n3. **후면 배기 연도 천공**: 화덕 뒤편 상단에 손목 굵기 나뭇가지를 비스듬히 찔러 넣어 연기가 원활히 빠져나갈 **배기 굴뚝**을 뚫습니다.\\n4. **기류 순환 통로 점검**: 하부 흡입구에서 상부 굴뚝으로 이어지는 상승 기류 유로에 걸림돌이 없는지 확인합니다.\",\n      \"actionNote\": \"> 연돌 공기 순환 원리: 굴뚝이 없으면 연기가 앞쪽 장작 입구로 쏟아져 나와 불이 꺼집니다. 뒤쪽 굴뚝을 앞 입구보다 높은 위치에 두어야 공기가 원활히 순환합니다. 만약 진흙을 말릴 시간이 없거나 폐허 도심을 이동 중이라면 [빈 깡통 이중 연소 우드 가스 스토브](/protocol-12.html)로 즉시 무연 화덕을 만드세요.\",\n      \"svgFileName\": \"pr06-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // AIR DRAFT PERSPECTIVE & EXHAUST BLUEPRINT\",\n        \"① 앞쪽 하부 공기 흡입구 (산소 유입)\",\n        \"차가운 신선한 공기가 빨려 들어가는 길목\",\n        \"② 윗부분 평평한 조리용 구멍\",\n        \"냄비나 평평한 돌판을 얹는 화구\",\n        \"③ 뒤편 상단 굴뚝 구멍\",\n        \"매운 연기를 뒤로 뽑아내는 배출구\",\n        \"④ 솟구치는 열기 순환선\",\n        \"연소실 안을 회전하며 냄비 바닥을 달굼\",\n        \"⑤ 냄비 받침 통기 틈새 돌기\",\n        \"냄비를 얹어도 불길이 막혀 꺼지지 않는 여유 공간\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD AERODYNAMICS\",\n        \"title\": \"연돌 효과(Stack Effect)와 벤투리 흡기 유체역학\",\n        \"text\": \"화덕 하부 입구와 상부 굴뚝 간의 높이차 및 온도차에 의해 강한 **연돌 효과(Chimney Effect)**가 발생합니다. 가벼워진 고온 연기가 배기구로 빠르게 빠져나가며 연소실 내부에 음압을 형성, 하부 흡입구로부터 신선한 산소를 자동으로 연속 흡입합니다.\"\n      }\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"5단계: 작은 잔가지 불씨로 3시간 서서히 말려 벽돌처럼 단단하게 굽기\",\n      \"description\": \"1. **미세 열원 착화**: 마른 잎과 작은 잔가지로 주먹 크기의 작은 불씨를 만들어 입구 근처에서 피웁니다.\\n2. **저온 서냉 건조**: 처음부터 큰 불을 피우지 않고 **3~4시간 동안** 미온의 열기를 서서히 전달하여 수분을 증발시킵니다.\\n3. **색조 변화 관찰**: 외벽의 짙은 고동색이 밝은 **황토색으로 변환**되고 흰 수증기 배출이 멈추는지 점검합니다.\\n4. **미세 크랙 덧바름 보수**: 건조 중 외벽에 발생한 미세 실금에 남은 점토 반죽을 얇게 펴 발라 완전 밀폐합니다.\",\n      \"actionNote\": \"> 급열 금지 원칙: 처음부터 큰 장작을 때면 점토 속 수분이 급격히 비등하여 외벽이 파열됩니다. 반드시 약한 불로 3시간 이상 서서히 구워내야 세라믹처럼 단단해집니다.\",\n      \"svgFileName\": \"pr06-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // CONTROLLED DEHYDRATION & CERAMIC HARDENING\",\n        \"① 입구 작은 잔가지 불씨 (약한 열기)\",\n        \"강한 불 대신 은은한 열기로 시작\",\n        \"② 외벽 수증기 증발선\",\n        \"내부 수분이 천천히 기화\",\n        \"③ 색상 변화 관찰\",\n        \"짙은 고동색 → 밝은 황토색\",\n        \"④ 따뜻한 건조 완료 판정\",\n        \"축축함 없이 외벽 전체가 훈훈\",\n        \"⑤ 미세 실금 덧바름 보수\",\n        \"남은 진흙 반죽으로 틈새 메우기\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"절대 하면 안 되는 실수: 물속에 젖어 있던 강돌을 화덕 불길 닿는 자리에 쌓기\",\n    \"description\": \"물가에서 방금 주워 온 강돌이나 자갈은 겉이 말라 보여도 돌 내부의 미세한 틈새에 물 분자가 갇혀 있습니다. 이 돌에 300도 이상의 뜨거운 불길이 직접 닿으면 갇힌 수분이 급격히 팽창하여 수류탄처럼 굉음을 내며 산산조각 폭발합니다. 날카로운 돌 파편이 눈과 얼굴로 날아와 실명하거나 큰 부상을 입을 수 있습니다. 반드시 물가에서 10m 떨어진 마른 언덕의 돌만 쓰고, 돌 표면을 진흙 반죽으로 5cm 이상 두껍게 덮어 불길이 돌에 직접 닿지 않도록 감싸야 합니다.\",\n    \"consequence\": \"결과: 돌 내부 수증기 폭발로 날카로운 파편이 비산하여 실명 및 중증 열상 유발\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"야생에서 바닥에 불을 피우면 열기의 80%가 날아갑니다. 비바람에도 꺼지지 않는 화덕 만드는 법입니다.\",\n    \"body\": \"찰흙 2, 모래 1, 마른 풀 1을 물과 함께 10분간 발로 밟아 차진 반죽을 만드세요. 주먹만 한 마른 돌을 U자로 놓고 앞쪽에 장작 입구를 둡니다. 돌과 진흙을 엇갈려 무릎 높이까지 돔으로 쌓고, 윗부분엔 냄비 구멍, 뒤편엔 연기가 빠질 굴뚝을 뚫으세요. 작은 불로 3시간 서서히 말려 수분을 빼면 벽돌처럼 단단해집니다. 절대 젖은 강돌을 불길에 직접 대지 마세요. 수증기 압력으로 돌이 폭발합니다.\",\n    \"outro\": \"비바람이 몰아쳐도 밥을 짓고 밤새 은은한 온기를 지킬 수 있습니다.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr06-outcome.svg\",\n    \"title\": \"점토 미장 돌 화덕 (원시 화덕 및 조리구) 완성 형태\",\n    \"description\": \"U자형 강돌 기초 위에 볏짚과 황토 반죽을 5cm 두께로 매끄럽게 미장하고, 상단 조리용 내열 상판과 후면 배기 굴뚝을 구비하여 650°C 고열을 가두는 원시 화덕 완성 형태입니다.\"\n  },\n  \"createdAt\": \"2026-10-14T10:15:00.000Z\",\n  \"updatedAt\": \"2026-10-16T13:10:22+09:00\",\n  \"contentHash\": \"3786963cf3f53637\"\n}","content/protocols/08-figure-four-deadfall.json":"{\n  \"protocolId\": \"PR-08\",\n  \"category\": \"FOOD\",\n  \"title\": \"나뭇가지 3개와 바위로 짐승 잡는 법 (숫자 4 모양 돌 덫)\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[단백질·식량 확보]\",\n  \"summary\": \"야생에서 짐승을 맨손으로 쫓아다니면 금방 지쳐 쓰러집니다. 손가락 굵기 나뭇가지 3개에 홈을 파서 '숫자 4' 모양으로 끼워 맞추면, 끈 하나 없이도 15kg 무거운 바위를 스스로 떠받칩니다. 안쪽 막대에 먹이를 꽂아두면, 쥐나 산짐승이 먹이를 톡 건드리는 순간 막대기가 툭 빠지면서 0.1초 만에 바위가 쾅 떨어지는 가장 확실한 생존 덫입니다.\",\n  \"timeRequired\": \"30분 (나뭇가지 깎기 20분 + 균형 맞추기 10분)\",\n  \"successRate\": \"95% (건드리면 바로 떨어지게 세팅 시)\",\n  \"difficulty\": \"보통 (각진 홈을 파내는 요령 필요)\",\n  \"outputPerHour\": \"시간당 2기 제작 설치 가능\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"손가락 굵기의 단단한 마른 나뭇가지 3개\",\n      \"desc\": \"무거운 바위를 받쳐도 부러지지 않는 단단한 참나무 가지를 준비합니다. [1번 세움대(20cm)], [2번 빗장대(25cm)], [3번 먹이대(30cm)]로 사용합니다.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"넓적하고 무거운 바위 1개 (10~15kg)\",\n      \"desc\": \"바닥에 닿는 면이 넓고 평평해야 짐승이 피하지 못하고 단번에 덮칩니다. 짐승 몸무게보다 훨씬 무거워야 합니다.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"홈을 파낼 날카로운 돌날 1개\",\n      \"desc\": \"나뭇가지를 깎아 서로 딱 물리는 홈과 걸림턱을 만들기 위한 날카로운 돌칼입니다.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"유인용 먹이 (산딸기, 벌레, 씨앗)\",\n      \"desc\": \"먹이대 안쪽 뾰족한 끝에 단단히 꽂아두어 짐승이 입을 대고 살짝 당기도록 유도하는 먹이입니다.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"1단계: 나뭇가지 3개 다듬기 (세움대·빗장대·먹이대에 홈 깎기)\",\n      \"description\": \"1. **기둥 세움대 가공**: 땅에 수직으로 세울 **20cm 세움대** 윗머리를 일자 드라이버 모양 쐐기로 깎고, 중앙에 네모난 홈을 팝니다.\\n2. **대각 빗장대 가공**: 바위를 비스듬히 받칠 **25cm 빗장대** 상단에 세움대 머리를 물어줄 V자 홈을 파고, 하단 끝을 비스듬한 쐐기로 다듬습니다.\\n3. **수평 먹이대 가공**: 미끼를 꽂을 **30cm 먹이대**에 세움대 홈에 걸칠 맞물림 턱과 빗장대 하단을 받칠 걸림 홈을 파내고, 안쪽 끝을 연필처럼 뾰족하게 깎습니다.\\n4. **직각 물림 각도 점검**: 세 부재의 결합 홈이 둥글지 않고 칼로 파낸 **직각 모서리**를 유지하는지 확인합니다.\",\n      \"actionNote\": \"> 깎을 때 꿀팁: 홈을 둥글게 파면 미끄러져서 무너집니다. 칼로 반듯하게 직각으로 파내야 세 막대가 서로를 꽉 물어줍니다.\",\n      \"svgFileName\": \"pr08-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // 3 STICKS ANATOMY & NOTCHES\",\n        \"POST (1번 세움대 - 윗머리 납작 쐐기 & 네모 홈)\",\n        \"STRUT (2번 빗장대 - 윗머리 V홈 & 아랫머리 쐐기)\",\n        \"BAIT STICK (3번 먹이대 - 걸림턱 & 홈 & 뾰족한 끝)\",\n        \"[핵심] 서로 딱 물리는 직각 홈과 걸림턱 깎기\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD MECHANICS\",\n        \"title\": \"정적 마찰 평형과 헤어트리거(Hair-Trigger) 임계 감도\",\n        \"text\": \"4자 덫(Figure-4 Trap)의 3개 부재는 직각 홈의 **정적 마찰 계수**에 의해 바위 하중을 지탱합니다. 접촉 턱의 물림 깊이를 **2~3mm**로 얕게 가공할수록, 수평 트리거를 해제하는 데 필요한 이탈력이 **50g 미만**으로 급감하여 극도의 민감도를 확보합니다.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"2단계: 1번 세움대 윗머리에 2번 빗장대 걸치기\",\n      \"description\": \"1. **지면 수직 기립**: 단단하고 평평한 바닥에 1번 세움대를 기울어짐 없이 똑바로 세웁니다.\\n2. **상단 V홈 결합**: 2번 빗장대의 상단 V홈을 1번 세움대의 납작한 쐐기 머리에 **45도 경사각**으로 맞물립니다.\\n3. **축 정렬 점검**: 위에서 손으로 가볍게 눌렀을 때 빗장대가 좌우로 비틀리지 않고 **기둥 축선과 일치**하는지 확인합니다.\",\n      \"actionNote\": \"> 각도 확인: 빗장대가 45도 각도로 기울어져 있어야 바위의 무거운 무게를 가장 안정적으로 받아냅니다.\",\n      \"svgFileName\": \"pr08-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // TOP NOTCH INTERLOCK\",\n        \"1번 세움대 납작 윗머리\",\n        \"2번 빗장대 V자 홈 결합\",\n        \"45도 각도로 딱 맞물림\",\n        \"[핵심] 미끄러지지 않고 딱 물리는 상단 결합\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD VECTOR PHYSICS\",\n        \"title\": \"45도 사각 지지와 압축-전단 분력 배분\",\n        \"text\": \"빗장대 경사각을 **45도**로 설정하면 상부 바위의 수직 중력 하중이 수직 기둥의 압축 응력과 수평 먹이대의 인장 마찰력으로 이상적으로 양분됩니다. 이 기하학적 각도가 자립 지탱과 즉각 해제의 최적 임계점입니다.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"3단계: 3번 먹이대를 끼워 '숫자 4' 모양으로 혼자 서게 만들기\",\n      \"description\": \"1. **먹이대 수평 안착**: 3번 먹이대를 지면과 수평으로 들고, 전면 걸림턱을 1번 세움대의 **중앙 직각 홈**에 겁니다.\\n2. **하단 빗장대 맞물림**: 2번 빗장대의 하단 쐐기 끝을 먹이대 **뒷면 홈에 가볍게 접촉**시켜 걸어줍니다.\\n3. **자립 3각 평형 유지**: 손을 천천히 떼며 세 부재가 서로를 밀어내는 마찰력만으로 **숫자 4 형태**로 스스로 자립하는지 확인합니다.\",\n      \"actionNote\": \"> 균형 확인: 손을 놓았을 때 흔들림 없이 스스로 서 있어야 합니다. 기우뚱거리면 1번 세움대 밑바닥을 평평하게 다시 다듬으세요.\",\n      \"svgFileName\": \"pr08-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // NUMBER 4 LOCK ASSEMBLY\",\n        \"세움대-먹이대 맞물림 턱\",\n        \"빗장대-먹이대 뒷홈 걸림\",\n        \"끈 없이 혼자 서는 숫자 4\",\n        \"[핵심] 세 막대가 서로 밀어내며 스스로 자립\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"4단계: 바위 기대어 얹기 & 먹이 달고 0.1초 반응 확인하기\",\n      \"description\": \"1. **미끼 고정**: 먹이대 안쪽 뾰족한 끝에 곤충이나 열매를 단단히 꽂아 고정합니다.\\n2. **10~15kg 바위 거치**: 한 손으로 바위 옆을 잡고 조심스럽게 들어 올려 2번 빗장대 상단 끝에 **40~45도 각도**로 기대어 놓습니다.\\n3. **손가락 안전선 확보**: 바위를 얹는 동안 손이나 신체 일부를 절대 **낙하 바위 하부**에 넣지 않습니다.\\n4. **0.1초 트리거 작동 점검**: 가느다란 가지로 먹이를 가볍게 건드렸을 때 부재가 **0.1초 만에 즉시 풀리며** 바위가 투하되는지 시험합니다.\",\n      \"actionNote\": \"> 안전 제일: 바위를 얹을 때 절대 바위 밑으로 손가락을 넣지 마세요. 만에 하나 무너져도 다치지 않게 바위 옆을 잡아야 합니다.\",\n      \"svgFileName\": \"pr08-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // ROCK LOAD & 0.1S COLLAPSE\",\n        \"15kg 평평한 바위 안착\",\n        \"먹이대 끝 미끼 장착\",\n        \"톡 건드리면 0.1초 만에 바위 낙하\",\n        \"[핵심] 스치기만 해도 와르르 무너지는 민감도\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD KINEMATICS\",\n        \"title\": \"0.1초 중력 가속도 자유낙하와 종단 충격량\",\n        \"text\": \"트리거가 이탈되는 순간 바위는 중력 가속도에 의해 **0.1초 이내**에 지표면에 도달합니다. **15kg** 바위가 낙하하며 전달하는 순간 충격량은 소형 포유류가 반응하여 탈출할 시간(청각-운동 반응 시간 약 0.15~0.2초)을 완벽히 차단합니다.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"치명적 실수: 결합 홈을 너무 깊게 파서 뻑뻑하게 만들거나, 너무 가벼운 돌을 얹는 것\",\n    \"description\": \"홈을 너무 깊게 파서 꽉 끼어버리면 짐승이 먹이를 세게 흔들어도 덫이 안 무너져 먹이만 털립니다. 반대로 돌이 너무 가벼우면 짐승이 다치기만 하고 도망쳐 버립니다.\",\n    \"consequence\": \"결과: 고기는 못 얻고 힘만 빠지며, 숲속 짐승들이 덫을 눈치채고 피해 다님\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"야생에서 짐승 잡으려고 뛰어다니면 굶어 죽습니다! 나뭇가지 3개로 만드는 0.1초 돌 덫!\",\n    \"body\": \"나뭇가지 세 개에 홈을 파서 '숫자 4' 모양으로 끼우면 끈 하나 없이 15kg 바위를 스스로 받칩니다. 안쪽 막대에 먹이를 꽂아두면, 쥐나 산짐승이 먹이를 톡 건드리는 순간 균형이 깨지면서 0.1초 만에 바위가 떨어집니다. 핵심 비밀! 홈은 걸릴 듯 말 듯 얕아야 스치자마자 바로 떨어집니다!\",\n    \"outro\": \"전기 없이 오프라인에서도 작동하는 생존 도면은 프로필 링크에서 확인하세요.\"\n  },\n  \"outcome\": {\n    \"imageFileName\": \"pr08-outcome.png\",\n    \"svgFileName\": \"pr08-outcome.svg\",\n    \"title\": \"완성된 숫자 4자 돌 덫 전체 모습\",\n    \"description\": \"손가락 굵기 막대기 3개가 서로 맞물려 15kg 무거운 바위를 비스듬히 떠받치고 있으며, 바위 안쪽의 먹이를 건드리는 즉시 0.1초 만에 뼈대가 풀려 바위가 덮치는 모습입니다.\"\n  },\n  \"createdAt\": \"2026-10-14T15:35:00.000Z\",\n  \"updatedAt\": \"2026-10-15T16:00:00+09:00\",\n  \"contentHash\": \"51e4bec4273ad957\"\n}","content/protocols/09-pit-charcoal-kiln.json":"{\n  \"protocolId\": \"PR-09\",\n  \"category\": \"FIRE\",\n  \"title\": \"흙구덩이 속에서 공기를 막아 나무를 단단한 숯으로 굽는 법 (원시 숯가마 제작법)\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[무연 고열 연료 & 정수 필터 숯 확보]\",\n  \"summary\": \"모닥불에 나무를 그냥 태우면 산소와 완전히 반응해 하얀 재만 남고 아무것도 남지 않습니다. 땅에 **50cm** 원뿔형 구덩이를 파고 참나무를 빽빽하게 세운 뒤, 흙과 잔디로 덮어 공기 유입을 **95%** 차단하면 나무가 활활 타지 않고 고열에 쪄지면서 단단한 숯이 됩니다. 연기 없이 따뜻하게 밤을 지새우거나, 정수용 숯 필터로 쓰거나, 불씨를 며칠씩 보관할 수 있는 야생의 검은 보석입니다.\",\n  \"timeRequired\": \"5시간 (구덩이 파기 및 장작 세팅 1시간 + 탄화 3시간 + 밀폐 냉각 1시간)\",\n  \"successRate\": \"90% (공기 차단과 냉각 시간 엄수 시)\",\n  \"difficulty\": \"보통 (연기 색상 판별 요령 필요)\",\n  \"outputPerHour\": \"1회 가동 시 단단한 고급 숯 3~5kg 수확\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"손목 굵기의 마른 참나무 토막 15~20개 (길이 30~40cm)\",\n      \"desc\": \"밀도가 높고 단단한 참나무나 활엽수로 준비합니다. 공기를 차단한 상태에서 구워져 오래 타는 고급 숯이 됩니다.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"깊이 50cm, 지름 60cm 원뿔형 흙구덩이\",\n      \"desc\": \"아래로 갈수록 좁아지는 원뿔형으로 파내어 열기를 한곳으로 모으고 공기 순환을 통제하는 지하 가마입니다.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"구덩이를 덮을 굵은 나뭇가지 틀과 넓은 잎\",\n      \"desc\": \"수직으로 세운 통나무 위에 얹어 흙이 무너지지 않도록 지탱해 주는 격자 뼈대와 흙 유입 방지용 나뭇잎입니다.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"젖은 진흙과 잔디 뗏장 (두께 10cm)\",\n      \"desc\": \"가마 상부를 완전히 덮어 공기 유입을 95% 차단하고 가마 내부를 400도 이상 고열로 쪄내는 단열 덮개입니다.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"초벌 건조용 마른 잔가지와 불씨\",\n      \"desc\": \"구덩이 바닥 흙의 습기를 바짝 말리고 가마 하단에 불길을 번지게 할 점화재입니다.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"1단계: 50cm 원뿔형 흙구덩이 파기 및 바닥 초벌 불씨 조성\",\n      \"description\": \"1. **원뿔형 구덩이 굴착**: 비가 고이지 않는 단단하고 건조한 흙땅을 골라 **윗지름 60cm, 깊이 50cm** 크기로 땅을 팝니다.\\n2. **하부 경사 테이퍼 가공**: 아래로 내려갈수록 지름이 **30cm** 정도로 좁아지는 원뿔(V자) 형태로 다듬어 열기를 중앙으로 모읍니다.\\n3. **바닥 습기 건조**: 바닥에 마른 잔가지와 낙엽을 넉넉히 깔고 불을 피워 구덩이 흙의 습기를 **15분 이상** 바짝 말립니다.\\n4. **빨간 숯불 밑천 형성**: 불길이 잦아들고 바닥 전체에 **빨갛게 이글거리는 숯불층**이 형성되었는지 확인합니다.\",\n      \"actionNote\": \"> 파기 요령: 구덩이 바닥에 습기가 남아있으면 나무가 쪄지지 않고 썩은 냄새가 나며 불이 꺼집니다. 바닥 흙이 바짝 마를 때까지 초벌 불씨를 충분히 달구세요.\",\n      \"svgFileName\": \"pr09-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PIT EXCAVATION & PRE-DRYING\",\n        \"상부 지름 60cm 원뿔형 흙구덩이\",\n        \"깊이 50cm (바닥 지름 30cm)\",\n        \"바닥 초벌 건조 잔가지 & 숯불 밑천\",\n        \"[핵심] 흙 습기 완전 건조 및 고온 불씨 형성\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"원뿔형 구덩이 축열과 지중 단열 보온\",\n        \"text\": \"지하 구덩이는 지표면보다 외기 열 손실이 적고 지중 단열 효과가 뛰어납니다. 하부로 갈수록 좁아지는 원뿔형 구조는 열대류를 중앙에 집중시켜 **400℃ 이상**의 고온 축열 상태를 **3시간 이상** 일정하게 유지합니다.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"2단계: 손목 굵기 참나무를 틈새 없이 수직으로 빽빽하게 적재하기\",\n      \"description\": \"1. **참나무 기둥 수직 거치**: 바닥의 붉은 불씨 위에 **길이 30~40cm, 굵기 5~8cm**의 마른 참나무 토막들을 기둥처럼 똑바로 세웁니다.\\n2. **방사형 밀집 배열**: 중앙에서부터 바깥쪽으로 참나무를 **빈틈없이 빽빽하게** 채워 넣습니다.\\n3. **잔가지 쐐기 결속**: 통나무 사이사이의 남은 틈새에 **손가락 굵기 잔가지**를 쐐기처럼 찔러 넣어 공기 주머니를 없앱니다.\\n4. **수평 평탄도 확인**: 세운 나무들의 상단 높이가 구덩이 입구와 **수평을 이루는지** 점검합니다.\",\n      \"actionNote\": \"> 적재 비법: 가마 안은 나무로 꽉 차서 빈틈이 거의 없어야 합니다. 밀도가 높을수록 단단하고 묵직한 쇠 소리가 나는 최고급 숯이 됩니다.\",\n      \"svgFileName\": \"pr09-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // DENSE VERTICAL TIMBER STACK\",\n        \"손목 굵기(5~8cm) 참나무 수직 적재\",\n        \"빈틈을 쐐기처럼 메운 잔가지\",\n        \"하단 초벌 불씨에서 번지는 열기\",\n        \"[핵심] 빈틈 최소화로 무산소 탄화 밀도 극대화\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PYROLYSIS\",\n        \"title\": \"수직 밀집 적재와 산소 차단 탄화 원리\",\n        \"text\": \"장작 사이의 공극(빈틈)을 최소화하면 내부 산소가 조기에 소진되어 불꽃 연소가 중단됩니다. 이후 외부 고열에 의해 목재 성분 중 수분과 연기 성분만 배출되고 순수한 **탄소(Carbon)** 골격만 결정화되어 단단한 숯이 형성됩니다.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"3단계: 나뭇가지 틀을 얹고 젖은 흙과 잔디 뗏장으로 95% 공기 차단하기\",\n      \"description\": \"1. **격자 나뭇가지 지지틀 거치**: 수직 통나무 상단에 굵은 나뭇가지들을 **우물 정(井) 자 격자**로 얹어 덮개 하중을 받칩니다.\\n2. **나뭇잎 차단층 형성**: 뼈대 위에 넓은 잎과 풀을 촘촘히 깔아 흙이 내부로 쏟아지지 않게 차단합니다.\\n3. **진흙 및 뗏장 10cm 도포**: 젖은 진흙과 잔디 뗏장을 **10cm 두께**로 덮어 공기 유입을 **95% 차단**합니다.\\n4. **흡기구 및 배기 굴뚝 천공**: 바람받이 쪽 바닥에 **손가락 굵기 흡기구 2개**를 뚫고, 상부 중앙에 **주먹 크기 굴뚝 1개**를 만듭니다.\",\n      \"actionNote\": \"> 밀폐 점검: 굴뚝 외에 흙 틈새로 연기가 새어 나오는 곳이 있다면 즉시 진흙을 덧발라 틀어막아야 나무가 활활 타지 않습니다.\",\n      \"svgFileName\": \"pr09-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // MULTI-LAYER ANAEROBIC SEAL\",\n        \"격자 가지틀 + 넓은 잎 지지층\",\n        \"10cm 젖은 진흙 & 잔디 뗏장 덮개\",\n        \"하단 흡기 구멍 2개 (손가락 굵기)\",\n        \"중앙 배기 굴뚝 (주먹 크기)\",\n        \"[핵심] 산소 95% 차단 불완전 연소 가마 완성\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"4단계: 연기 색상 변화 판별 및 완전 밀폐 냉각 후 숯 수확하기\",\n      \"description\": \"1. **짙은 흰 연기 배출 확인**: 초기 **1~2시간** 동안 굴뚝에서 수분이 증발하며 뿜어져 나오는 짙은 흰 연기를 관찰합니다.\\n2. **푸른 연기 전이 감지**: 점화 후 **2~3시간** 경과 시 연기가 **맑고 옅은 푸른빛**으로 바뀌면 탄화가 완료되었음을 판별합니다.\\n3. **통기구 100% 진흙 밀폐**: 푸른 연기를 확인하는 즉시 진흙 반죽으로 굴뚝과 흡기구를 **100% 빈틈없이 틀어막아** 공기를 차단합니다.\\n4. **6시간 서랭 후 숯 수확**: 가마 외벽이 완전히 차갑게 식을 때까지 **최소 6시간** 기다린 뒤 흙을 걷어내고 은빛 광택의 단단한 숯을 꺼냅니다.\",\n      \"actionNote\": \"> 불길 솟구침(역화) 주의: 아직 가마 속이 뜨거울 때 성급하게 흙을 파헤치면 신선한 공기가 들어가 불길이 폭발하며 숯이 순식간에 재가 됩니다. 반드시 흙이 완전히 차갑게 식은 뒤 여세요.\",\n      \"svgFileName\": \"pr09-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // SMOKE PHASE & CHARCOAL HARVEST\",\n        \"1단계: 짙은 백색 연기 (수분 증발)\",\n        \"2단계: 옅은 청색 연기 (탄화 완료)\",\n        \"모든 구멍 진흙 밀폐 후 완전 냉각\",\n        \"쇳소리 나는 고밀도 참나무 숯 수확\",\n        \"[핵심] 푸른 연기 즉시 밀폐 & 잔열 완전 냉각\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"가마 역화 폭발 방지와 서랭(Slow Cooling) 냉각\",\n        \"text\": \"탄화가 완료된 가마 내부는 산소가 고갈된 초고온 상태입니다. 이때 외부 공기가 급격히 유입되면 잔류 가연 가스가 폭발적으로 발화(역화 현상)하여 숯이 순식간에 재로 산화합니다. 통기구를 완전 밀폐하고 **6시간 이상** 천천히 식혀야(서랭) 고밀도 탄소체가 안정화됩니다.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"치명적 실수: 열기가 남아있을 때 성급하게 흙 덮개를 열거나, 연기 구멍 밀폐를 깜빡하는 것\",\n    \"description\": \"가마 안이 400도 이상 달궈진 상태에서 흙 덮개를 벗겨내면, 신선한 공기 속 산소가 한꺼번에 밀려들어가며 거대한 화염이 솟구치는 가마 역화 폭발(불길 솟구침)이 일어납니다. 또한 푸른 연기가 날 때 구멍을 막지 않고 방치하면 통나무 전체가 하얀 재로 산화되어 버립니다.\",\n    \"consequence\": \"결과: 몇 시간 동안 애써 구운 나무가 순식간에 재로 사라지고 화상을 입을 위험\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"모닥불에 나무 태우면 하얀 재만 남습니다! 땅속에 묻어서 쇠 소리 나는 단단한 숯 굽는 비법!\",\n    \"body\": \"흙구덩이에 참나무를 빽빽하게 세우고 흙과 뗏장으로 덮어 공기를 95% 차단하세요! 처음엔 짙은 흰 연기가 뿜어져 나오다가, 2~3시간 뒤 옅은 푸른 연기로 바뀌면 나무가 순수한 숯으로 변한 겁니다. 이때 진흙으로 모든 구멍을 틀어막고 완전히 식히면, 연기 없이 고열을 내는 최고의 생존 숯이 완성됩니다!\",\n    \"outro\": \"전기 없는 재난 상황에서도 작동하는 원시 생존 도면은 프로필 링크에서 확인하세요.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr09-outcome.svg\",\n    \"title\": \"완성된 원시 지하 숯가마 단면 및 단단한 숯 제원\",\n    \"description\": \"50cm 원뿔형 흙구덩이 속에서 공기를 95% 차단한 채 고온으로 구워내어, 연기 없는 고열 연료이자 식수 정화 필터로 사용 가능한 단단한 참나무 숯의 완성 단면입니다.\"\n  },\n  \"createdAt\": \"2026-10-15T05:30:00.000Z\",\n  \"contentHash\": \"916099d408d4f948\",\n  \"updatedAt\": \"2026-10-15T14:41:20+09:00\"\n}","content/protocols/10-pine-resin-pitch-glue.json":"{\n  \"protocolId\": \"PR-10\",\n  \"category\": \"MEDICINE\",\n  \"title\": \"소나무 송진을 녹여 굳히는 상처 소독 연고 및 만능 방수 접착제 (원시 송진 정제법)\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[야생 세균 감염 차단 & 도구 방수 결속]\",\n  \"summary\": \"야생에서 돌날이나 나뭇가지에 손을 베였을 때 소독하지 못하면 세균 감염으로 상처가 덧나 목숨을 위협받습니다. 또한 돌도끼 자루나 토기 틈새를 단단하고 물이 새지 않게 메워줄 접착제가 절실합니다. 소나무가 스스로를 보호하기 위해 분비하는 송진을 숯불 잔열로 은근하게 녹여 불순물을 거르면 상처를 보호하는 천연 항균 연고가 되고, 여기에 미세한 숯가루를 **1:1**로 섞어 반죽하면 식으면서 돌처럼 단단하게 굳는 천연 방수 수지 접착제(Pitch Glue)가 됩니다.\",\n  \"timeRequired\": \"40분 (송진 채취 15분 + 은근한 가열 용융 15분 + 숯가루 배합 및 성형 10분)\",\n  \"successRate\": \"95% (직화 금지 및 숯가루 1:1 비율 엄수 시)\",\n  \"difficulty\": \"쉬움 (화재 및 화상 주의)\",\n  \"outputPerHour\": \"1회 작업 시 항균 연고 30ml + 방수 결속 막대(Pitch Stick) 2개 완성\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"노송(소나무) 상처 부위에서 채취한 마른 생송진 덩어리 100g\",\n      \"desc\": \"주먹 1개 크기의 마른 호박색 덩어리로 준비합니다. 바짝 굳은 투명한 덩어리가 불순물이 적고 녹였을 때 맑은 상급 연고가 됩니다.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"송진을 녹일 오목한 돌 접시 또는 조개껍데기\",\n      \"desc\": \"직화 열기를 피하고 숯불 잔열을 머금어 송진을 안전하게 녹여내는 천연 내열 용기입니다.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"나뭇가지 끝을 빗처럼 엮은 거름망과 덜어낼 조개껍데기\",\n      \"desc\": \"녹은 송진 위로 떠오른 나무껍질 불순물을 빠르게 건져내고 순수 연고를 분리하는 도구입니다.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"미세하게 빻은 참나무 숯가루 50g\",\n      \"desc\": \"[지하 흙구덩이 숯가마](/protocol-09.html)에서 구워낸 참나무 숯을 곱게 빻아 송진의 유리 같은 취성을 없애주고 돌처럼 단단하게 굳혀주는 천연 경화제 역할을 합니다.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"달궈진 참나무 숯불 잔열과 반죽용 나뭇가지\",\n      \"desc\": \"화염 불꽃 없이 원적외선 열기로만 은근하게 녹여주는 안전한 야전 열원입니다.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"1단계: 소나무 줄기에서 마른 호박색 생송진 덩어리 채취하기\",\n      \"description\": \"1. **호박색 송진 선별**: 소나무 줄기나 부러진 가지 주변에 눈물방울 모양으로 굳은 **마른 호박색 송진 덩어리**를 찾습니다.\\n2. **돌칼 긁어내기**: 뾰족한 [돌칼이나 돌도끼](/protocol-04.html) 또는 단단한 나무 부스러기로 나무껍질이 깊게 파이지 않도록 **표면 덩어리만 살살** 긁어냅니다.\\n3. **주먹 1개 분량 확보**: 잡목 껍질이 적게 섞인 깨끗한 송진으로 **주먹 1개 분량(약 100g)**을 모아 넓은 잎에 담습니다.\\n4. **큰 이물질 1차 선별**: 눈에 띄는 굵은 흙먼지나 나무 부스러기는 손끝으로 미리 골라내어 버립니다.\",\n      \"actionNote\": \"> 수종 식별 및 채취 요령: 붉은빛 거북등 껍질과 바늘잎 **2개**가 뭉쳐 나는 **소나무**(송진 채취용)와 세로로 깊게 갈라진 흑갈색 껍질·톱니 잎·도토리가 특징인 **참나무**(숯가루 경화제용)를 아래 실사 도감으로 정확히 구분하세요. 바짝 굳은 투명한 호박색 송진 덩어리가 가장 맑은 상급 연고가 됩니다.\",\n      \"svgFileName\": \"pr10-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // RAW PINE RESIN HARVESTING\",\n        \"소나무 줄기에 응고된 호박색 생송진\",\n        \"돌칼로 나무껍질 손상 없이 표면 채취\",\n        \"주먹 1개 분량 (약 100g) 선별 확보\",\n        \"[핵심] 바짝 굳은 투명한 덩어리 위주 채취\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BOTANY\",\n        \"title\": \"야생 핵심 수종(소나무·참나무) 육안 식별 및 송진 방어 기전\",\n        \"text\": \"소나무는 외피가 찢기면 상처 부위를 밀폐하고 세균 번식을 막기 위해 테르펜 성분이 농축된 진액(Resin)을 분비합니다. 반면 참나무는 조직이 치밀하고 단단한 활엽수로, 구웠을 때 송진의 깨지기 쉬운 성질을 잡아주는 최고급 탄소 숯가루와 오래가는 숯불 열원을 제공합니다.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"소나무\",\n            \"scientificName\": \"Pinus densiflora\",\n            \"categoryTag\": \"침엽수(Softwood) / 송진·착화재\",\n            \"imageFileName\": \"id-pine-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-01A // MACRO OPTIC\",\n            \"hudStatus\": \"RESIN GLAND: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"수피/BARK\",\n                \"value\": \"줄기 위쪽은 붉은빛(적갈색)을 띠며, 아래쪽은 **거북 등껍질 모양의 마름모꼴 균열**로 두껍게 갈라집니다.\"\n              },\n              {\n                \"label\": \"잎/LEAF\",\n                \"value\": \"잎자루 밑동에서 **항상 2개씩 뭉쳐 자라는 뾰족한 사계절 푸른 바늘잎**(길이 **8~14cm**)이 특징입니다.\"\n              },\n              {\n                \"label\": \"징후/SIGN\",\n                \"value\": \"줄기 상처 부위에 눈물방울처럼 굳은 **황금빛·호박색 송진 덩어리**와 가지 끝의 목질 **솔방울**로 즉시 구별됩니다.\"\n              }\n            ],\n            \"fieldUse\": \"상처 소독 연고, 만능 방수 접착제(Pitch), 초고열 부싯깃\"\n          },\n          {\n            \"name\": \"참나무\",\n            \"scientificName\": \"Quercus\",\n            \"categoryTag\": \"활엽수(Hardwood) / 고밀도 숯·구조재\",\n            \"imageFileName\": \"id-oak-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-01B // MACRO OPTIC\",\n            \"hudStatus\": \"FISSURE DEPTH: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"수피/BARK\",\n                \"value\": \"어둡고 짙은 흑갈색~암회색 표면 위로 **세로 방향의 깊고 거친 수직 골(홈)**이 길게 패여 있습니다.\"\n              },\n              {\n                \"label\": \"잎/LEAF\",\n                \"value\": \"잎 가장자리에 **물결 모양이나 뾰족한 톱니 모양**이 뚜렷하게 나 있는 손바닥 길이의 넓은 잎입니다.\"\n              },\n              {\n                \"label\": \"징후/SIGN\",\n                \"value\": \"가지나 나무 밑둥 바닥에 떨어진 **도토리 열매와 비늘 모양 모자(깍정이)**를 찾으면 **100%** 참나무입니다.\"\n              }\n            ],\n            \"fieldUse\": \"방수 접착제 경화용 미세 숯가루, 무연 고열 참나무 숯, 돌도끼 자루\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"2단계: 오목한 돌판에 담아 숯불 잔열로 은근하게 녹이기 (직화 금지)\",\n      \"description\": \"1. **돌판 중앙 송진 거치**: 오목한 돌판이나 큰 조개껍데기 한가운데에 모아둔 **송진 덩어리 100g**을 얹습니다.\\n2. **숯불 가장자리 배치**: 붉게 달아오른 숯불 화염을 피해 숯 가장자리 **10cm 거리**에 돌판을 거치합니다.\\n3. **간접 잔열 가열**: 솟구치는 불꽃이 절대 닿지 않도록 주의하며 **5~8분간** 뭉근한 잔열로만 송진을 녹입니다.\\n4. **맑은 액체화 확인**: 송진 덩어리가 완전히 풀려 **황금빛 맑은 시럽 형태**로 녹아내리는지 관찰합니다.\",\n      \"actionNote\": \"> 화재 주의: 송진 증기에는 기름 성분이 많아 모닥불 불꽃이 스치기만 해도 펑 하고 불이 붙습니다. 반드시 직화를 피하고 은근한 숯불 잔열로만 녹이세요.\",\n      \"svgFileName\": \"pr10-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // GENTLE EMBER MELTING PROCESS\",\n        \"오목한 돌판 속 황금빛 액상 송진\",\n        \"숯불 가장자리 10cm 간접 거치\",\n        \"직화 불꽃 차단 및 은근한 복사열 가열\",\n        \"[핵심] 인화 방지를 위한 100% 잔열 용융\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PHARMACOLOGY\",\n        \"title\": \"테르펜(Terpene) 분자의 강력한 항균 살균 기전\",\n        \"text\": \"송진의 주성분인 알파-피넨(Alpha-Pinene)과 테르펜 유도체는 미생물의 세포막 지질층을 파괴하고 대사 효소를 무력화합니다. 고온 직화로 태우지 않고 얕은 열로 녹여야 약효 유효 물질이 파괴되지 않고 유지됩니다.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"3단계: 잔가지 빗으로 불순물을 걸러내고 순수 항균 연고 덜어내기\",\n      \"description\": \"1. **잔가지 빗 제작**: 얇은 잔가지 끝을 나란히 모아 **빗 모양 거름틀**을 만듭니다.\\n2. **표면 불순물 빗질**: 녹은 송진 위로 둥둥 떠오른 나무껍질과 흙먼지를 잔가지 빗으로 **빠르게 훑어 건져냅니다**.\\n3. **항균 연고 30ml 분리**: 맑게 정제된 황금빛 송진액의 **3분의 1(약 30ml)**을 작은 조개껍데기나 납작한 돌에 따로 떠냅니다.\\n4. **자연 냉각 보관**: 그늘진 서늘한 곳에서 **10분간** 식혀 손끝으로 찍어 바를 수 있는 쫀득한 천연 소독 연고로 보관합니다.\",\n      \"actionNote\": \"> 연고 보관: 식으면 젤리처럼 쫀득해집니다. 야생에서 상처가 났을 때 체온으로 살짝 녹여 바르면 세균을 막아주는 천연 방수 밴드가 됩니다.\",\n      \"svgFileName\": \"pr10-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DEBRIS REMOVAL & OINTMENT EXTRACTION\",\n        \"잔가지 빗으로 불순물 찌꺼기 여과\",\n        \"상처 소독용 순수 송진액 30ml 분리\",\n        \"조개껍데기에 덜어내어 10분간 자연 냉각\",\n        \"[핵심] 맑은 황금빛 소독 연고 분리 확보\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"4단계: 미세 숯가루를 1:1로 섞어 돌처럼 단단한 방수 결속 막대(Pitch Stick) 만들기\",\n      \"description\": \"1. **미세 숯가루 투입**: 돌판에 남은 뜨거운 송진액에 곱게 빻은 [참나무 숯가루](/protocol-09.html) **50g**을 조금씩 나누어 넣습니다.\\n2. **빠른 교반 반죽**: 나뭇가지로 덩어리가 뭉치지 않도록 **1~2분간** 빠르게 저어 검고 끈적한 엿 상태로 만듭니다.\\n3. **막대 끝 감아올리기**: 굵은 나뭇가지 끝에 뜨거운 반죽을 **사탕 모양으로 도톰하게** 돌려 감아올립니다.\\n4. **찬물 급랭 경화**: 찬물에 담그거나 상온에서 **5분간** 식혀 손톱자국도 나지 않는 단단한 흑요석 질감의 접착제 막대를 완성합니다.\",\n      \"actionNote\": \"> 배합 비율: 숯가루가 너무 적으면 유리처럼 쉽게 깨지고, 너무 많으면 접착력이 떨어집니다. 부피 기준 1:1 비율을 지키는 것이 가장 질기고 단단하며, 완성된 접착제는 [돌도끼 자루 방수 결속](/protocol-04.html)과 [야생 밧줄 매듭 코팅](/protocol-05.html)에 즉시 활용됩니다.\",\n      \"svgFileName\": \"pr10-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // CHARCOAL ADMIXTURE & PITCH STICK\",\n        \"미세 참나무 숯가루 1:1 비율 투입\",\n        \"나뭇가지로 고속 교반 및 점성 반죽\",\n        \"나뭇가지 끝에 둥글게 도포 후 5분 급랭\",\n        \"[핵심] 균열 없는 천연 방수 에폭시 막대 완성\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD MATERIALS\",\n        \"title\": \"탄소 입자 첨가에 의한 취성 극복과 천연 에폭시화\",\n        \"text\": \"순수한 송진은 냉각되면 유리처럼 부서지기 쉽습니다(취성). 수많은 미세 구멍을 가진 탄소 입자인 참나무 숯가루를 균일하게 분산시키면 균열의 전파를 차단하는 보강 골격 역할을 하여, 둔탁한 충격에도 깨지지 않고 물을 **100%** 튕겨내는 원시 천연 에폭시(Pitch Glue)가 됩니다.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"치명적 실수: 송진을 빨리 녹이려고 모닥불 화염 위에 직접 올려놓는 것\",\n    \"description\": \"송진은 고인화성 테르펜 탄화수소로 가득 차 있습니다. 모닥불 불꽃에 직접 닿게 하거나 과열하면 휘발성 유증기가 발생해 펑 하는 폭발음과 함께 걷잡을 수 없이 불이 붙어 화상을 입고 송진 전체가 잿더미가 됩니다.\",\n    \"consequence\": \"결과: 송진 전소 및 안면·손등의 중증 화상 위험\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"야생에서 베인 상처 곪으면 패혈증으로 끝납니다! 소나무 송진으로 천연 항생제와 돌 접착제 만드는 비법!\",\n    \"body\": \"소나무 상처에 굳은 호박색 송진을 긁어모아 오목한 돌판에 올리세요! 불꽃에 닿으면 폭발하니 숯불 잔열로만 은근하게 녹입니다. 맑게 녹은 액체를 조개껍데기에 덜어 식히면 세균을 100% 막아주는 상처 소독 연고가 됩니다. 남은 송진에 미세한 숯가루를 1:1로 섞어 막대 끝에 굳히면 돌도끼 자루를 고정하고 물을 튕겨내는 돌처럼 단단한 만능 방수 접착제가 완성됩니다!\",\n    \"outro\": \"전기 없는 문명 붕괴 시대를 대비하는 원시 생존 기술은 프로필 링크에서 무료로 확인하세요.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr10-outcome.svg\",\n    \"title\": \"완성된 소나무 송진 항균 소독 연고 및 방수 수지 결속 막대(Pitch Stick) 제원\",\n    \"description\": \"오목한 돌판과 조개껍데기에 담긴 황금빛 천연 항균 보호막 연고와, 참나무 숯가루를 1:1 배합하여 나뭇가지 끝에 굳힌 흑요석 광택의 방수 결속 막대(Pitch Stick), 그리고 돌도끼 자루 결속부 방수 방벽 단면입니다.\"\n  },\n  \"createdAt\": \"2026-10-16T11:40:00.000Z\",\n  \"contentHash\": \"db453b0037c7d451\"\n}","content/protocols/11-willow-funnel-fish-trap.json":"{\n  \"protocolId\": \"PR-11\",\n  \"category\": \"FOOD\",\n  \"title\": \"버드나무 가지를 엮어 들어간 물고기가 빠져나오지 못하는 원시 깔때기 통발 (원시 통발 어로법)\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[자율 단백질 수렵 & 체력 보존]\",\n  \"summary\": \"맨손이나 나무 작살로 빠른 물고기를 쫓아다니면 귀중한 체력만 바닥나고 빈손으로 지치기 쉽습니다. 강가에 흔한 휘어지는 버드나무 잔가지로 입구는 넓고 안쪽은 좁아지는 역깔때기 통발을 엮어 여울목 물길에 설치해 두면, 물고기가 미끼 냄새를 따라 들어왔다가 안쪽으로 모인 잔가지 끝단에 걸려 다시 빠져나가지 못합니다. 잠을 자거나 은신처를 짓는 동안에도 스스로 물고기를 잡아주는 고효율 원시 어로 장치입니다.\",\n  \"timeRequired\": \"50분 (버드나무 가지 채취 10분 + 뼈대 및 몸통 엮기 25분 + 역깔때기 결합 및 여울목 설치 15분)\",\n  \"successRate\": \"92% (깔때기 안쪽 입구 직경 손가락 3마디 유지 및 상류 방향 고정 시)\",\n  \"difficulty\": \"보통 (날카로운 가지 끝 눈 찔림 및 미끄러운 강바닥 주의)\",\n  \"outputPerHour\": \"1회 설치 후 하룻밤 기준 민물고기 3~8마리 자율 포획\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"휘어지는 버드나무 또는 개암나무 생가지 40~50개 (팔 길이 70~80cm)\",\n      \"desc\": \"[돌도끼나 날카로운 돌칼](/protocol-04.html)로 강가에서 갓 베어낸 새끼손가락 절반 굵기(약 5mm)의 탄력 있는 생가지입니다. 구부렸을 때 부러지지 않는 싱싱한 가지를 고릅니다.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"원형 테두리 뼈대(림)용 굵은 덩굴 또는 버드나무 가지 4개\",\n      \"desc\": \"둥글게 말아 통발의 동그란 형태를 지탱해 줄 연필 굵기(약 8~10mm)의 튼튼한 생가지 4개입니다.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"물에 강한 야생 칡덩굴 속껍질 끈 (총 길이 15m)\",\n      \"desc\": \"[야생 칡덩굴 밧줄 만드는 법](/protocol-05.html)으로 꼬아 만든 질긴 식물 끈입니다. 물속에서도 풀리지 않도록 매듭 부위에 [소나무 송진 방수 접착제](/protocol-10.html)를 살짝 발라두면 더욱 튼튼합니다.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"통발을 강바닥에 가라앉힐 주먹 크기 강돌 2개와 고정 말뚝 4개\",\n      \"desc\": \"나무로 만든 통발이 물에 둥둥 뜨거나 물살에 굴러가지 않도록 무게중심을 잡아주는 어른 주먹 크기 조약돌과 팔뚝 길이 나무 말뚝입니다.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"돌로 으깬 민물 다슬기·우렁이 또는 강바닥 지렁이 한 줌\",\n      \"desc\": \"물살을 타고 하류로 비릿한 냄새를 퍼뜨려 물고기를 통발 안쪽으로 유인하는 천연 미끼입니다. 넓은 나뭇잎에 감싸 구멍을 뚫어 넣습니다.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"1단계: 굵은 가지를 둥글게 말아 크기순 원형 뼈대 테두리(림) 4개 만들기\",\n      \"description\": \"1. **생가지 탄성 점검**: 강가에서 채취한 연필 굵기 버드나무 가지 4개를 손으로 천천히 휘어보아 뚝 부러지지 않고 부드럽게 휘어지는지 확인합니다.\\n2. **4단계 크기별 원형 림 성형**: 가지를 둥근 고리 모양으로 말아 **한 뼘 반(직경 25cm)**, **한 뼘(직경 20cm)**, **주먹 두 개 폭(직경 15cm)**, **주먹 한 개 폭(직경 10cm)** 크기의 원형 테두리 4개를 만듭니다.\\n3. **겹침 부위 끈 결속**: 각 고리의 양 끝이 **손가락 두 마디(약 4cm)** 이상 겹치도록 맞대고 [야생 칡덩굴 끈](/protocol-05.html)으로 열 바퀴 이상 칭칭 감아 묶습니다.\\n4. **크기순 간격 배치**: 바닥에 큰 고리부터 작은 고리까지 **한 뼘(약 15cm) 간격**으로 나란히 세워 원뿔형 몸통 비율을 맞춥니다.\",\n      \"actionNote\": \"> 재료 식별 및 손 보호: 바짝 마른 죽은 가지는 구부리는 순간 날카롭게 부러져 손이나 눈을 찌를 수 있습니다. 아래 실사 도감으로 물가의 유연한 **버드나무 생가지**와 **천연 다슬기 미끼**를 정확히 구분해 준비하세요.\",\n      \"svgFileName\": \"pr11-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // GRADUATED HOOP RINGS (4 SIZES)\",\n        \"① 입구 대형 림 (한 뼘 반 / 직경 25cm)\",\n        \"② 중간 림 2개 (직경 20cm · 15cm)\",\n        \"③ 꼬리 소형 림 (주먹 폭 / 직경 10cm)\",\n        \"④ 겹친 끝단 칡 끈 결속 (15cm 간격 배열)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BOTANY\",\n        \"title\": \"버드나무 생가지의 휨 탄성과 수중 내구성 및 천연 미끼 선별\",\n        \"text\": \"물가에서 자라는 버드나무(Salix)는 목질 섬유가 길고 수분 함량이 높아 둥글게 구부려도 부러지지 않으며, 물속에 잠겨도 쉽게 썩지 않습니다. 또한 강바닥 돌 밑에 붙어 사는 다슬기와 우렁이는 껍데기를 깨뜨렸을 때 아미노산 체액이 물살을 타고 멀리 퍼져나가 민물고기를 강력하게 유인합니다.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"버드나무 생가지\",\n            \"scientificName\": \"Salix koreensis\",\n            \"categoryTag\": \"수변 활엽수 / 고탄성 통발 뼈대·살\",\n            \"imageFileName\": \"id-willow-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-11A // MACRO OPTIC\",\n            \"hudStatus\": \"FLEX ELASTICITY: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"가지/TWIG\",\n                \"value\": \"황록색~연갈색의 가늘고 긴 가지가 처지며 자라고, **U자 모양으로 완전히 구부려도 꺾이지 않는 탄력**을 지닙니다.\"\n              },\n              {\n                \"label\": \"잎/LEAF\",\n                \"value\": \"창끝처럼 **좁고 길쭉한 피침형 초록 잎**(길이 **5~12cm**) 가장자리에 잔잔한 톱니가 나 있습니다.\"\n              },\n              {\n                \"label\": \"징후/SIGN\",\n                \"value\": \"강가나 냇물 바로 옆 젖은 자갈밭·모래톱에서 무리 지어 자라며, 껍질을 긁으면 **버들 특유의 상쾌한 풀 냄새**가 납니다.\"\n              }\n            ],\n            \"fieldUse\": \"원시 어로 통발 엮기, 고탄성 활대, 진통·해열용 버드나무 껍질 차\"\n          },\n          {\n            \"name\": \"민물 다슬기·지렁이 미끼\",\n            \"scientificName\": \"Semisulcospira / Lumbricina\",\n            \"categoryTag\": \"수중 생물 미끼 / 후각 유인제\",\n            \"imageFileName\": \"id-river-snail-bait.jpg\",\n            \"hudCode\": \"FIG. BIO-11B // MACRO OPTIC\",\n            \"hudStatus\": \"SCENT PLUME: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"외형/SHELL\",\n                \"value\": \"물속 이끼 낀 바위 뒷면에 붙어 있는 **검고 길쭉한 원뿔 나사 모양 껍데기**(길이 **1.5~3cm**)가 특징입니다.\"\n              },\n              {\n                \"label\": \"가공/CRUSH\",\n                \"value\": \"강돌로 껍데기를 **살짝만 으깨어 속살 진액이 배어 나오게** 해야 물속에서 냄새가 3시간 이상 오래 퍼집니다.\"\n              },\n              {\n                \"label\": \"대체/ALT\",\n                \"value\": \"다슬기가 없다면 강가 축축한 흙이나 낙엽 아래를 파서 잡은 **붉은 지렁이나 메뚜기**를 뭉쳐 넣어도 효과가 뛰어납니다.\"\n              }\n            ],\n            \"fieldUse\": \"통발 내부 후각 유인 미끼, 낚시 바늘 미끼, 비상시 고단백 끓인 식량\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"2단계: 버드나무 잔가지 30~40개를 세로로 촘촘히 엮어 원뿔 몸통 완성하기\",\n      \"description\": \"1. **세로 살 균일 배치**: 팔 길이(70~80cm)의 곧은 버드나무 잔가지 30~40개를 가장 큰 고리 바깥쪽부터 가장 작은 고리까지 **손가락 한 마디(약 1~1.5cm) 간격**으로 빙 둘러 대어 줍니다.\\n2. **고리 교차부 감쳐 묶기**: 긴 칡 끈을 이용해 원형 테두리 고리와 세로 가지가 만나는 자리마다 **한 번씩 엇갈려 감으며** 흔들리지 않게 고정합니다.\\n3. **원뿔 격자 장력 유지**: 큰 입구에서 작은 꼬리 쪽으로 내려갈수록 가지들이 자연스럽게 모이도록 손으로 오므려 주며 네 개의 고리를 모두 엮습니다.\\n4. **꼬리 배출구 풀림 매듭 마감**: 가장 작은 꼬리 고리 뒤로 모인 가지 끝단을 하나로 모아 끈으로 단단히 묶되, 나중에 잡힌 물고기를 꺼낼 수 있도록 **당기면 풀리는 고리 매듭**으로 마감합니다.\",\n      \"actionNote\": \"> 살 간격 기준: 세로 가지 사이 틈이 손가락 한 마디(1.5cm)보다 넓으면 들어온 물고기가 옆구리 틈으로 빠져나갑니다. 손가락이 겨우 들어갈 정도로 촘촘하게 엮으세요.\",\n      \"svgFileName\": \"pr11-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // CONICAL WICKER BODY WEAVING\",\n        \"버드나무 세로 살 30~40개 (간격 1~1.5cm)\",\n        \"4개 원형 림과 세로 살 교차 감쳐 묶기\",\n        \"물살 저항을 줄이는 유선형 원뿔 바구니\",\n        \"[핵심] 꼬리 끝 물고기 수거용 개폐 매듭\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD MECHANICS\",\n        \"title\": \"유선형 원뿔 격자의 수류 저항(Drag) 분산 역학\",\n        \"text\": \"1~1.5cm 간격의 촘촘한 세로 살 격자는 강물의 흐름을 막지 않고 자연스럽게 통과시켜, 통발이 빠른 여울 물살에 떠내려가는 수류 저항(항력)을 **70% 이상 감소**시키면서도 몸통 폭 **2cm 이상**의 민물고기는 절대 빠져나가지 못하게 가둡니다.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"3단계: 안쪽으로 좁아지는 역깔때기 입구(체크 밸브)를 만들어 몸통 앞에 결합하기\",\n      \"description\": \"1. **역깔때기 잔가지 편성**: 팔뚝 길이(약 30~35cm)의 가늘고 탄력 있는 버드나무 잔가지 **16~20개**를 둥글게 모아 작은 고깔 모양을 잡습니다.\\n2. **입구·출구 직경 설정**: 바깥쪽 넓은 입구는 몸통 첫 번째 고리에 맞도록 **한 뼘 반(직경 25cm)**으로 벌리고, 안쪽 끝은 **손가락 세 마디(직경 5~6cm)** 크기로 좁아지게 맞춥니다.\\n3. **안쪽 탄성 가시 끝단 유지**: 좁아지는 안쪽 끝부분 **손가락 두 마디(5cm)** 구간은 끈으로 묶지 않고 잔가지 끝이 안쪽으로 자유롭게 모여 있도록 두어, 물고기가 밀고 들어갈 때는 열리고 나올 때는 찔려서 못 나오는 일방향 문을 만듭니다.\\n4. **몸통 입구 삽입 및 봉합**: 완성한 역깔때기를 Step 02 원뿔 몸통의 넓은 입구 안쪽으로 밀어 넣고, 맞닿는 바깥 테두리를 [칡덩굴 끈](/protocol-05.html)으로 빈틈없이 꿰매어 하나로 합칩니다.\",\n      \"actionNote\": \"> 역깔때기 구멍 크기: 안쪽 좁은 구멍이 주먹보다 크면 물고기가 도로 헤엄쳐 나갑니다. 손가락 세 개를 모은 굵기(직경 5~6cm)로 좁혀 두어야 물고기가 들어올 때만 가지가 벌어지고 뒤로는 잠깁니다.\",\n      \"svgFileName\": \"pr11-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // ONE-WAY INVERTED FUNNEL VALVE\",\n        \"역깔때기 외측 입구 (직경 25cm 몸통 결합)\",\n        \"안쪽으로 오므라든 탄성 가지 끝단 (직경 5~6cm)\",\n        \"물고기 진입 시 벌어지고 역진 시 걸리는 구조\",\n        \"[핵심] 일방향 침입 허용 & 역방향 탈출 원천 차단\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PHYSICS\",\n        \"title\": \"탄성 잔가지 쐐기의 일방향 체크 밸브(Check-Valve) 기전\",\n        \"text\": \"물고기가 앞쪽으로 전진하며 깔때기를 통과할 때는 유선형 머리가 탄성 있는 잔가지 끝을 바깥으로 부드럽게 밀어내어 통로가 열립니다. 그러나 일단 내부로 진입한 뒤 뒤돌아 나가려 하면, 모여서 뾰족하게 마주 보고 있는 잔가지 끝단이 물고기의 아가미 덮개와 지느러미에 걸려 역방향 탈출을 기하학적으로 차단합니다.\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"4단계: 통발 안에 강돌과 미끼를 넣고 여울목 물길에 말뚝으로 고정하기\",\n      \"description\": \"1. **침강용 강돌 및 미끼 주머니 투입**: 꼬리 쪽 매듭을 열어 통발이 물에 뜨지 않게 눌러 줄 **주먹 크기 강돌 2개**와, 구멍 뚫은 넓은 잎에 싼 **으깬 다슬기·지렁이 미끼**를 넣은 뒤 꼬리 끝을 다시 단단히 묶습니다.\\n2. **바위 틈 여울목 지점 선정**: 강물이 바위 사이로 좁아지며 흐르는 **무릎 깊이(수심 30~50cm)**의 물길이나 수초 그늘 옆자리를 설치 장소로 고릅니다.\\n3. **깔때기 입구 상류 방향 정렬**: 미끼 냄새가 하류로 흘러 내려가 물고기를 불러 모으도록, 통발의 **깔때기 입구가 물이 흘러내려 오는 상류(위쪽) 또는 물길 대각선 방향**을 향하게 바닥에 가라앉힙니다.\\n4. **말뚝 4개 및 바위 3점 고정**: 통발 양옆 바닥에 **팔뚝 길이 나무 말뚝 4개**를 깊숙이 박고 윗부분을 끈으로 묶거나 묵직한 강돌로 양옆을 괴어, 밤새 거센 물살에도 통발이 구르지 않게 고정합니다.\",\n      \"actionNote\": \"> 수거 및 조리: 다음 날 아침 꼬리 매듭만 풀면 잡힌 물고기를 손쉽게 쏟아서 거둘 수 있습니다. 포획한 민물고기는 기생충 감염 예방을 위해 반드시 [다코타 무연 화덕](/protocol-06.html)이나 [참나무 숯불](/protocol-09.html)에 속까지 완전히 익혀 드세요.\",\n      \"svgFileName\": \"pr11-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // STREAM CHANNEL ANCHORING & BAIT PLUME\",\n        \"통발 내부 침강용 강돌 2개 & 으깬 다슬기 미끼\",\n        \"상류에서 하류로 흐르는 물살 & 냄새 확산 경로\",\n        \"나무 말뚝 4개 및 양옆 바위 고정 지지대\",\n        \"[핵심] 냄새를 따라 거슬러 올라와 통발에 갇힌 물고기\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD ECOLOGY\",\n        \"title\": \"담수 어류의 양성 주류성(Positive Rheotaxis)과 후각 유인\",\n        \"text\": \"대부분의 강물고기는 아가미 호흡 효율을 높이고 떠내려오는 먹이를 잡기 위해 물살을 거슬러 상류 쪽으로 머리를 두는 **양성 주류성** 본능을 가집니다. 상류를 향해 설치된 통발에서 미끼 냄새가 하류로 퍼지면, 하류의 물고기들이 냄새 줄기를 따라 거슬러 올라와 스스로 통발 안으로 진입합니다.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"치명적 실수: 무게추 강돌 없이 가벼운 통발만 물에 던져 넣거나 포획한 민물고기를 날것으로 먹는 행위\",\n    \"description\": \"버드나무로 엮은 통발은 부력이 커서 내부에 무거운 강돌을 넣지 않고 말뚝으로 고정하지 않으면 몇 분 만에 물살에 둥둥 떠내려가 유실됩니다. 또한 통발로 잡은 민물고기를 불에 익히지 않고 회로 먹으면 간흡충 등 치명적인 기생충과 수인성 세균에 감염되어 극심한 복통과 고열로 생존이 불가능해집니다.\",\n    \"consequence\": \"결과: 통발 유실로 인한 식량 확보 실패 및 민물 기생충·세균 감염에 의한 중증 질환 발생\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"강가에서 물고기 잡으려고 뛰어다니면 힘만 빠집니다! 잠자는 동안 물고기가 알아서 걸려드는 버드나무 통발 만드는 법!\",\n    \"body\": \"물가의 휘어지는 버드나무 가지를 둥글게 말아 한 뼘 반부터 주먹 크기까지 원형 테두리 4개를 만드세요. 여기에 긴 잔가지 40개를 손가락 한 마디 간격으로 촘촘히 엮어 원뿔 바구니를 만듭니다. 핵심은 입구에 끼우는 역깔때기입니다! 안쪽 구멍을 손가락 세 마디 크기로 좁혀 끼우면, 물고기가 으깬 다슬기 냄새를 맡고 밀고 들어왔다가 가시에 걸려 절대 빠져나가지 못합니다!\",\n    \"outro\": \"주먹 만한 돌 두 개를 넣어 여울목 바위 틈에 고정해 두면 아침마다 신선한 물고기가 가득합니다. 자세한 도면은 프로필 링크에서 확인하세요.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr11-outcome.svg\",\n    \"title\": \"완성된 버드나무 이중 역깔때기 어로 통발 및 여울목 수중 포획 단면 제원\",\n    \"description\": \"4단 원형 테두리와 촘촘한 버드나무 세로 살로 엮은 유선형 원뿔 몸통, 일방향 탄성 가지 끝단을 가진 역깔때기 입구(체크 밸브), 바닥 침강용 강돌 2개와 다슬기 미끼 주머니, 그리고 물길 바위 틈에 말뚝으로 고정되어 물고기를 자율 포획하는 수중 단면 구조입니다.\"\n  },\n  \"createdAt\": \"2026-10-16T13:38:00.000Z\",\n  \"contentHash\": \"037d4ce0763a3aa2\"\n}","content/protocols/12-twin-can-wood-gas-stove.json":"{\n  \"protocolId\": \"PR-12\",\n  \"category\": \"FIRE\",\n  \"title\": \"버려진 빈 깡통 2개와 폐전선·잔가지로 연기 없이 물을 끓이는 이중 연소 우드 가스 스토브 (폐자재 화덕)\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[무연 고열 조리·살균 & 연료 80% 절감]\",\n  \"summary\": \"문명이 멈춘 도시나 황무지에서는 굵은 장작을 구하기 어렵고, 일반 모닥불을 피우면 검은 연기가 치솟아 주변에 위치가 노출될 뿐만 아니라 열기가 바람에 흩어져 버립니다. 폐허에서 흔히 주울 수 있는 크기가 다른 빈 철제 깡통 2개를 겹쳐 이중 벽체 화덕을 만들고 안 쓰는 전기선의 구리·철 심선으로 고정하면, 나뭇가지에서 뿜어져 나오는 연기(목재 가스)까지 다시 한번 불태우는 무연 가스레인지가 됩니다. 손가락 굵기 마른 잔가지 두 줌만으로도 연기 없이 8분 만에 물 1리터를 펄펄 끓일 수 있습니다.\",\n  \"timeRequired\": \"35분 (빈 깡통 코팅 태우기 10분 + 통풍 구멍 뚫기 15분 + 이중 결합 및 점화 10분)\",\n  \"successRate\": \"95% (철제 깡통 사용 및 상단 점화 원칙 준수 시)\",\n  \"difficulty\": \"보통 (날카로운 깡통 절단면 손 베임 및 유독 코팅 연기 주의)\",\n  \"outputPerHour\": \"잔가지 두 줌(200g)으로 20분간 무연 고열 화염 유지 (식수 1.5리터 살균)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"버려진 큰 철제 깡통 1개와 그 안에 들어가는 작은 철제 통조림 깡통 1개\",\n      \"desc\": \"외부 몸통용 큰 철제 깡통(한 뼘 높이, 직경 12~15cm)과 내부 연소실용 작은 깡통(직경 8~10cm)입니다. 고열에 녹아내리는 얇은 알루미늄 음료수 캔 대신 자석이나 무게감으로 확인되는 단단한 주석 도금 강철 깡통을 골라야 합니다.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"안 쓰는 굵은 폐전선(피복 벗긴 구리·철 심선) 50cm\",\n      \"desc\": \"[날카로운 돌칼이나 돌도끼](/protocol-04.html)로 바깥 비닐 피복을 완전히 벗겨낸 금속 알맹이 철사입니다. 두 깡통이 흔들리지 않게 묶어 고정하고 냄비 받침대(오덕)를 만드는 데 씁니다.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"깡통에 구멍을 뚫을 뾰족한 고철 못(또는 송곳 돌)과 망치돌\",\n      \"desc\": \"깡통 바닥과 옆면에 공기 구멍을 뚫고 윗면을 동그랗게 따낼 때 쓰는 뾰족한 금속 핀이나 단단한 돌조각입니다.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"엄지손가락 길이로 꺾은 마른 잔가지 두 줌과 송진 부싯깃\",\n      \"desc\": \"내부 깡통에 세로로 빽빽하게 채워 넣을 바짝 마른 나뭇가지와, 위쪽에서 첫 불씨를 붙일 [소나무 송진 덩어리](/protocol-10.html) 및 마른 수피입니다.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"1단계: 내열 철제 깡통 2개와 폐전선을 선별하고 유독성 내부 코팅을 먼저 태워 날리기\",\n      \"description\": \"1. **강철 깡통 및 규격 선별**: 손으로 옆면을 세게 쥐었을 때 찌그러지지 않고 가로 주름(보강 홈)이 잡혀 있는 단단한 철제 깡통 2개를 고릅니다. 큰 깡통 안에 작은 깡통을 넣었을 때 양옆에 **손가락 한 마디(약 1.5~2cm)** 공기 통로가 남아야 합니다.\\n2. **폐전선 플라스틱 피복 박리**: 버려진 전기선 겉면의 고무·비닐 피복을 [날카로운 돌날](/protocol-04.html)로 길게 그어 벗겨내고, 불에 타지 않는 **순수 구리선 또는 철사 심선 50cm**만 챙깁니다.\\n3. **깡통 내부 에폭시 코팅 공소(태우기)**: 구멍을 뚫기 전에 두 빈 깡통 안에 마른 낙엽과 잔가지를 넣고 **5분간 먼저 불을 피워**, 깡통 안쪽에 발라진 투명 플라스틱(에폭시) 코팅막과 겉면 페인트를 완전히 태워 날립니다.\\n4. **연기 소멸 및 냉각 확인**: 코팅 타는 매캐한 냄새가 사라지고 깡통 안쪽이 **무광 흑회색**으로 변하면 불을 끄고 찬물이나 그늘에서 완전히 식힙니다.\",\n      \"actionNote\": \"> 유독 가스 및 알루미늄 주의: 코팅을 미리 태우지 않고 바로 물을 끓이면 환경호르몬과 유독 연기를 마시게 됩니다. 또한 얇은 알루미늄 맥주·음료수 캔은 660℃에서 종이처럼 녹아내리므로 아래 실사 도감으로 **주름 잡힌 강철 통조림 깡통**과 **피복 벗긴 폐전선**을 정확히 구분해 쓰세요.\",\n      \"svgFileName\": \"pr12-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // STEEL CAN SELECTION & LINER BURN-OFF\",\n        \"외부 대형 철제 깡통 (직경 12~15cm) & 내부 소형 깡통\",\n        \"내외측 벽면 사이 손가락 한 마디 (1.5~2cm) 공기 틈\",\n        \"사용 전 5분 공소로 내부 에폭시 코팅 완전 제거\",\n        \"[핵심] 고열 강철 깡통 선별 & 피복 벗긴 폐전선 확보\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"URBAN SALVAGE\",\n        \"title\": \"강철 깡통(1,500℃ 내열) vs 알루미늄 캔 선별 및 에폭시 열분해 안전 수칙\",\n        \"text\": \"통조림이나 분유통에 쓰이는 주석 도금 강철(Tinplate Steel)은 녹는점이 약 **1,500℃**에 달해 우드 가스 스토브의 고열(800~900℃)을 반복해서 견딥니다. 반면 탄산음료에 쓰이는 알루미늄 캔은 녹는점이 **660℃**에 불과해 2차 연소 열기에 즉시 녹아 무너집니다. 또한 통조림 내부의 부식 방지용 비스페놀(BPA) 에폭시 수지는 개방된 야외에서 미리 한 번 태워 탄화시켜야 조리 시 유독 가스가 발생하지 않습니다.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"고열 내구 강철 통조림·분유 깡통\",\n            \"scientificName\": \"Tin-Coated Corrugated Carbon Steel\",\n            \"categoryTag\": \"도시 금속 폐자재 / 이중 연소실 본체\",\n            \"imageFileName\": \"id-steel-tin-can.jpg\",\n            \"hudCode\": \"FIG. SALV-12A // MACRO OPTIC\",\n            \"hudStatus\": \"MELT POINT 1500C: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"외형/RIB\",\n                \"value\": \"원통 옆면에 **가로 방향의 볼록한 보강 주름(비드 홈)**이 여러 줄 찍혀 있어 손으로 쥐어도 찌그러지지 않습니다.\"\n              },\n              {\n                \"label\": \"단면/RIM\",\n                \"value\": \"위아래 테두리가 두껍게 말려 접합되어 있으며, 돌로 두드리면 **묵직하고 맑은 쇳소리**가 납니다.\"\n              },\n              {\n                \"label\": \"전처리/PREP\",\n                \"value\": \"낙엽 불로 5분간 미리 구워내면 내부의 반짝이는 코팅이 사라지고 **안전한 무광 암회색 강철 표면**이 드러납니다.\"\n              }\n            ],\n            \"fieldUse\": \"이중 연소 우드 가스 스토브, 야전 정수 끓이기 용기, 숯 보관함\"\n          },\n          {\n            \"name\": \"피복 벗긴 폐전선 & 마른 잔가지\",\n            \"scientificName\": \"Stripped Copper/Steel Core & Dry Hardwood\",\n            \"categoryTag\": \"도시·자연 하이브리드 / 내열 결속재·연료\",\n            \"imageFileName\": \"id-salvage-wire-twigs.jpg\",\n            \"hudCode\": \"FIG. SALV-12B // MACRO OPTIC\",\n            \"hudStatus\": \"INSULATION STRIPPED: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"심선/CORE\",\n                \"value\": \"돌날로 바깥 플라스틱 피복을 벗겨낸 **붉은 구리 단선 또는 은회색 철사 심선**(굵기 **1.5~3mm**)입니다.\"\n              },\n              {\n                \"label\": \"연료/FUEL\",\n                \"value\": \"구부렸을 때 '딱' 소리를 내며 부러지는 **손가락 굵기·엄지 길이의 바짝 마른 활엽수 잔가지**입니다.\"\n              },\n              {\n                \"label\": \"착화/TINDER\",\n                \"value\": \"잔가지 맨 위에서 첫 불길을 빠르게 내려보낼 **호박색 소나무 송진 조각과 마른 나무껍질**을 함께 씁니다.\"\n              }\n            ],\n            \"fieldUse\": \"화덕 이중 벽체 결속, 십자 냄비 받침대(오덕), 무연 고열 목재 가스 연료\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"2단계: 작은 내부 깡통 바닥과 위쪽 옆면에 1·2차 공기 구멍 뚫기\",\n      \"description\": \"1. **내부 깡통 손 보호 고정**: 구멍을 뚫을 때 깡통이 찌그러지지 않도록 작은 깡통 안쪽에 단단한 나뭇조각이나 흙을 채워 받쳐 둡니다.\\n2. **바닥면 1차 공기 구멍 타공**: 작은 깡통 바닥면에 뾰족한 고철 못이나 돌송곳을 대고 망치돌로 두드려 **새끼손가락 굵기(직경 8mm) 구멍 12~15개**를 소쿠리처럼 골고루 뚫습니다.\\n3. **상단 옆면 2차 가스 노즐 타공**: 작은 깡통 맨 위쪽 테두리에서 **손가락 한 마디(약 1.5cm) 아래** 옆면 둘레를 따라 **엄지손가락 굵기(직경 10~12mm) 구멍 8~10개**를 빙 둘러 뚫습니다.\\n4. **날카로운 철판 가시 다듬기**: 구멍 안쪽으로 말려 들어간 날카로운 철판 거스러미를 돌 모서리로 두드려 납작하게 펴서 손을 베이지 않게 정리합니다.\",\n      \"actionNote\": \"> 상단 구멍의 역할: 작은 깡통 위쪽 옆면에 뚫은 8~10개의 구멍이 바로 연기를 불꽃으로 바꾸는 '가스레인지 화구(2차 연소 노즐)'가 됩니다. 구멍 크기를 엄지손가락 굵기로 시원하게 뚫어주어야 화력이 강해집니다.\",\n      \"svgFileName\": \"pr12-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // INNER BURN CHAMBER PERFORATION\",\n        \"내부 소형 깡통 바닥 1차 흡기공 (8mm × 12~15개)\",\n        \"상단 테두리 1.5cm 아래 2차 가스 노즐 (10~12mm × 8~10개)\",\n        \"고철 못과 망치돌 타공 후 날카로운 단면 평탄화\",\n        \"[핵심] 하단 재 배출 & 상단 고온 예열 산소 분사구 완성\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"1차 열분해(Pyrolysis)와 2차 가스 연소 노즐의 단면적 설계\",\n        \"text\": \"내부 깡통 바닥의 작은 구멍들은 잔가지가 타는 데 필요한 최소한의 1차 공기를 공급하고 재를 아래로 떨어뜨립니다. 반면 상단 둘레의 큼직한 구멍들은 이중 벽체를 타고 올라온 뜨거운 공기를 연소실 상부로 강하게 뿜어내어, 위로 솟구치는 가연성 목재 가스(일산화탄소·메탄)와 혼합시켜 완전 연소를 유도합니다.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"3단계: 큰 외부 깡통 하단에 흡기구를 뚫고 작은 깡통을 끼워 이중 벽체 완성하기\",\n      \"description\": \"1. **외부 깡통 하단 주 흡기구 타공**: 큰 외부 깡통의 맨 아래쪽 옆면 둘레를 따라 바닥에서 **손가락 한 마디(1.5cm) 위**에 **엄지손가락 굵기(직경 12mm) 공기 흡입 구멍 8~10개**를 일정한 간격으로 뚫습니다.\\n2. **외부 깡통 상단 끼움 구멍 개방**: 큰 깡통의 윗면 뚜껑 한가운데를 작은 깡통의 몸통 지름(8~10cm)에 딱 맞게 돌칼이나 정으로 동그랗게 오려냅니다.\\n3. **내외측 깡통 수직 결합**: 큰 깡통 상단 구멍으로 작은 내부 깡통을 위에서 아래로 꽉 밀어 넣어, 작은 깡통 바닥이 큰 깡통 바닥에서 **손가락 두 마디(약 3~4cm) 떠 있도록** 걸어 줍니다.\\n4. **폐전선 결속 및 냄비 받침대 설치**: 피복을 벗긴 **폐전선 철사**로 두 깡통의 맞닿는 윗부분을 단단히 동여매고, 남은 철사나 납작한 돌 3개를 입구 위에 올려 불길이 빠져나올 **손가락 두 마디 높이의 냄비 받침대(오덕)**를 만듭니다.\",\n      \"actionNote\": \"> 밀폐 틈새 점검: 큰 깡통과 작은 깡통이 만나는 맨 위쪽 테두리 틈으로 공기가 새면 아래쪽 2차 노즐로 공기가 나오지 않습니다. 틈이 벌어졌다면 진흙이나 [소나무 송진·숯 반죽](/protocol-10.html)으로 윗부분 틈새를 메워 주세요.\",\n      \"svgFileName\": \"pr12-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DOUBLE-WALL COAXIAL ASSEMBLY\",\n        \"외부 대형 깡통 하단 찬 공기 흡입구 (12mm × 8~10개)\",\n        \"상단 원형 개방구에 내부 연소실 깡통 수직 삽입\",\n        \"바닥에서 3~4cm 띄워 재 받이 및 공기 분배 공간 확보\",\n        \"[핵심] 폐전선 철사로 상단 고정 및 냄비 받침대 거치\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FLUID MECHANICS\",\n        \"title\": \"이중 벽체 굴뚝 효과(Stack Draft)와 예열 공기의 상승 가속\",\n        \"text\": \"내부 깡통이 달궈지면 내외측 깡통 사이의 1.5~2cm 좁은 환형 공간(Annular Gap)에 있는 공기가 급격히 가열되어 밀도가 낮아집니다. 이로 인해 부력에 의한 강력한 상승 기류가 발생하여, 외부 하단 구멍으로 찬 공기를 스스로 빨아들이고 상단 노즐로 **500℃ 이상의 예열 산소**를 뿜어내는 무동력 터보 화덕이 됩니다.\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"4단계: 마른 잔가지를 세워 채운 뒤 위에서부터 불을 붙여(Top-Down) 무연 화염으로 물 끓이기\",\n      \"description\": \"1. **마른 잔가지 수직 충전**: 내부 작은 깡통 안에 엄지 길이로 꺾은 마른 잔가지들을 **상단 2차 구멍 바로 아래 높이까지** 세로 방향으로 촘촘히 세워 채웁니다.\\n2. **상단부 역방향 점화(Top-Down)**: 잔가지 더미 맨 꼭대기에 송진 조각과 마른 껍질을 올리고 [활비비 마찰 불씨](/protocol-02.html)로 **반드시 위쪽에서부터** 불을 붙입니다.\\n3. **무연 2차 가스 화염 확인**: 점화 후 **2~3분**이 지나면 이중 벽체가 달궈지면서 상단 옆구리 구멍 8~10개에서 꽃잎 모양의 **밝은 황금빛·푸른빛 2차 화염 제트**가 뿜어져 나오고 연기가 완전히 사라집니다.\\n4. **식수 가열 살균 및 바이오차 수거**: 받침대 위에 [자연 여과기로 걸러낸 물](/protocol-01.html)을 담은 용기를 올려 **3분 이상 펄펄 끓여** 식수를 확보하고, 조리 후 바닥에 남은 붉은 숯은 흙으로 덮어 다음번 [정수 필터 및 연료용 숯](/protocol-09.html)으로 챙깁니다.\",\n      \"actionNote\": \"> 위에서 불 붙이기(Top-Down) 원칙: 아래쪽에서 불을 붙이면 위쪽 잔가지들이 한꺼번에 연기를 내뿜어 불이 질식합니다. 양초를 태우듯 반드시 맨 위에서 불을 붙여야 연기가 상단 불꽃을 통과하며 100% 깨끗하게 불타 없어집니다.\",\n      \"svgFileName\": \"pr12-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // TOP-DOWN IGNITION & WOOD GAS JET\",\n        \"상단 노즐 아래까지 마른 잔가지 수직 적재\",\n        \"맨 위 부싯깃 점화 (Top-Down 하향 연소)\",\n        \"이중 벽체 예열 공기 분사 & 무연 2차 가스 화염\",\n        \"[핵심] 연기 제로 고열로 8분 만에 식수 비등 살균\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"COMBUSTION SCIENCE\",\n        \"title\": \"하향식 열분해(Top-Down Gasification)와 바이오차(Biochar) 생성\",\n        \"text\": \"상단에서 불이 시작되면 아래쪽 잔가지들은 산소가 부족한 상태에서 위쪽의 복사열만 받아 가연성 목재 가스(Wood Gas)를 서서히 방출합니다. 이 가스가 위로 올라오며 상단 노즐의 예열 산소와 만나 **850℃ 이상의 깨끗한 화염**으로 완전히 연소하며, 연소실 바닥에는 순수한 탄소 덩어리인 참나무 숯(바이오차)이 남습니다.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"치명적 실수: 내부 플라스틱 코팅을 태우지 않은 깡통이나 알루미늄 음료수 캔을 그대로 조리에 사용하는 행위\",\n    \"description\": \"통조림 깡통 내부에는 녹 방지용 에폭시 플라스틱 막이 코팅되어 있어, 사전에 빈 깡통을 한 번 태워 날리지(공소) 않고 바로 조리하면 맹독성 연기와 환경호르몬이 식수에 스며듭니다. 또한 얇은 알루미늄 캔은 고열에 순식간에 녹아내려 끓는 물이 쏟아지며 심각한 화상을 입힙니다.\",\n    \"consequence\": \"결과: 유독 가스 흡입 중독 및 화덕 붕괴로 인한 끓는 물 전신 화상 위험\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"버려진 빈 깡통 2개만 있으면 잔가지 한 줌으로 연기 하나 없이 물을 끓이는 괴물 화덕을 만들 수 있습니다!\",\n    \"body\": \"먼저 크기가 다른 철제 깡통 2개를 골라 낙엽 불로 안쪽의 유독성 코팅을 깨끗이 태워 날리세요. 작은 깡통 바닥에 구멍을 촘촘히 뚫고, 위쪽 옆면 둘레에 엄지 굵기 구멍 8개를 뚫습니다. 큰 깡통 아래쪽에도 공기 구멍을 뚫은 뒤 작은 깡통을 위에서 쏙 끼워 이중 벽체를 만드세요! 이제 마른 잔가지를 채우고 맨 위에서 불을 붙이면, 이중 벽체를 타고 올라온 뜨거운 공기가 연기까지 다시 불태우며 가스레인지 같은 불꽃이 뿜어져 나옵니다!\",\n    \"outro\": \"연기가 안 나서 위치가 노출되지 않고 8분이면 물이 펄펄 끓습니다. 정밀 도면은 프로필 링크에서 무료로 확인하세요.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr12-outcome.svg\",\n    \"title\": \"완성된 빈 깡통 이중 연소 우드 가스 스토브(Wood Gas Stove) 열유체 단면 제원\",\n    \"description\": \"외부 대형 철제 깡통과 내부 소형 연소실 깡통 사이의 1.5~2cm 이중 공기 통로, 하단 냉기 흡입구와 상단 2차 예열 산소 분사 노즐, 폐전선 결속 오덕 받침대, 그리고 목재 가스가 무연 고열 화염으로 완전 연소되는 열역학 단면 구조입니다.\"\n  },\n  \"createdAt\": \"2026-10-17T10:12:00.000Z\",\n  \"contentHash\": \"00b85f08738b5163\"\n}","content/protocols/13-wood-ash-lye-soap.json":"{\n  \"protocolId\": \"PR-13\",\n  \"category\": \"MEDICINE\",\n  \"title\": \"참나무 재 양잿물과 기름을 끓여 감염을 막는 천연 살균 잿물 비누 만들기 (야전 소독 비누)\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[야전 위생·상처 소독 & 세균성 패혈증 차단]\",\n  \"summary\": \"상하수도와 병원이 멈춘 야생이나 재난 환경에서는 작은 찰과상이나 오염된 손으로 음식을 먹는 것만으로도 이질과 파상풍, 패혈증에 걸려 목숨을 잃습니다. 모닥불이나 [빈 깡통 우드 가스 스토브](/protocol-12.html)에서 나오는 하얀 참나무 백탄 재를 깡통 여과기에 모아 끓인 물을 부어 걸러내면 탄산칼륨이 녹아 나온 미끌미끌한 양잿물(Lye)이 됩니다. 여기에 사냥한 동물의 비계 기름이나 버려진 폐식용유를 1:1로 섞어 약한 불에서 걸쭉해질 때까지 나무 주걱으로 저어주며 끓이면, 세균의 세포막을 녹여 파괴하는 강력한 천연 살균 비누가 완성됩니다.\",\n  \"timeRequired\": \"70분 (재 거르기 20분 + 비누화 끓이기 45분 + 식히기 5분)\",\n  \"successRate\": \"95% (생감자 부력 1단계 농도 준수 및 1:1 연속 교반 시)\",\n  \"difficulty\": \"보통 (강염기 양잿물 피부 화상 및 눈 튐 주의)\",\n  \"outputPerHour\": \"재 한 양동이와 기름 2컵으로 비누 3~4장(한 달치 야전 살균 비누) 제조\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"완전히 하얗게 탄 참나무 백탄 재 한 양동이\",\n      \"desc\": \"[참나무 숯가마](/protocol-09.html)나 화덕 바닥에서 검은 숯 조각을 골라내고 체로 쳐서 모은 밀가루처럼 부드러운 하얀 잿가루입니다. 칼륨 성분이 가장 풍부한 활엽수 백탄 재를 써야 짙은 양잿물이 추출됩니다.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"바닥에 구멍 뚫은 철제 깡통 여과기와 억새풀·자갈 필터\",\n      \"desc\": \"[자연 간이 정수기](/protocol-01.html)의 여과 원리를 적용한 깡통 거치대입니다. 유독 코팅을 불에 미리 태워 날린 큰 철제 깡통 바닥에 물 빠짐 구멍을 뚫고, 조약돌과 마른 억새풀을 깔아 재가 아래로 쏟아져 내리지 않도록 받쳐줍니다.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"양잿물 농도 측정용 생감자 조각 (또는 날달걀)\",\n      \"desc\": \"염기 농도를 눈으로 확인하는 부력 시험체입니다. 양잿물에 띄웠을 때 가라앉지 않고 수면 위로 엄지손톱만큼 머리를 내밀면 비누를 만들기에 완벽한 농도입니다.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"정제한 동물 비계 기름(우지·돈지) 또는 버려진 폐식용유 2컵\",\n      \"desc\": \"사냥한 동물의 지방 덩어리를 냄비에 약한 불로 녹여 찌꺼기를 걸러낸 기름이나, 폐허에서 수거한 식물성 식용유입니다. 불순물이 섞이지 않아야 비누가 상하지 않고 단단하게 굳습니다.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"항균 강화용 고운 소나무 송진 가루 1큰술과 소금 1작은술\",\n      \"desc\": \"[소나무 송진 연고](/protocol-10.html)에 쓰이는 맑은 송진 덩어리를 빻은 가루입니다. 천연 피톤치드 성분으로 세균 소독력을 극대화하고, 소금 성분은 비누를 비누 틀에서 분리하기 쉽게 굳혀줍니다.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"1단계: 하얗게 탄 참나무 재를 깡통 여과기에 담고 끓인 물을 부어 황금빛 양잿물 걸러내기\",\n      \"description\": \"1. **백탄 재 선별 및 이물질 제거**: 검은 숯 덩어리를 집어내고, 완전히 타서 먼지처럼 뽀얀 **하얀 참나무 재 한 양동이**를 모아 굵은 나무껍질을 털어냅니다.\\n2. **바닥 억새풀·자갈 필터 적층**: 유독성 내부 코팅을 불로 미리 태워 날린 큰 깡통 바닥에 못으로 작은 구멍들을 뚫은 뒤, 맨 밑바닥에 엄지손가락 굵기 자갈을 깔고 그 위에 마른 억새풀을 **손가락 두 마디(약 3cm) 두께**로 꽉 눌러 채웁니다.\\n3. **참나무 재 장전 및 온수 침출**: 필터 위에 하얀 재를 깡통의 **손뼘 하나 높이(80%)**까지 꾹꾹 눌러 담은 뒤, [펄펄 끓여서 식힌 물](/protocol-01.html)을 찰랑거릴 때까지 천천히 붓습니다.\\n4. **황금빛 양잿물 수거**: 바닥 구멍을 통해 한 방울씩 떨어지는 진한 호박색의 미끌미끌한 양잿물(탄산칼륨 수용액)을 깨끗한 밑받침 그릇에 모읍니다.\",\n      \"actionNote\": \"> 강염기 화상 주의: 참나무 재를 통과한 양잿물은 단백질을 녹이는 강염기성이므로 맨손으로 만지면 피부가 벗겨져 화상을 입습니다. 반드시 나뭇가지 주걱을 쓰고, 손에 튀었을 땐 즉시 맑은 찬물로 5분간 씻어내세요. 아래 식생 도감으로 **참나무 백탄 재**와 **소나무 송진**을 정확히 확인하세요.\",\n      \"svgFileName\": \"pr13-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // WOOD ASH LYE EXTRACTION LEACHER\",\n        \"참나무 백탄 재 (상단 80% 적층)\",\n        \"바닥 억새풀 섬유층 & 자갈 완충 필터\",\n        \"침출 추출되는 짙은 호박색 알칼리 양잿물\",\n        \"[1단계 핵심] 숯 조각 제거 & 끓인 온수 침출 여과\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD CHEMISTRY\",\n        \"title\": \"탄산칼륨(K2CO3) 수용액 침출과 고순도 알칼리 수율 조건\",\n        \"text\": \"단단한 활엽수인 참나무를 태우면 목질에 축적된 칼륨 이온이 공기 중의 이산화탄소와 반응하여 탄산칼륨(K2CO3) 염으로 전환됩니다. 찬물보다 70~80℃의 온수를 부으면 용해도가 2배 이상 급증하여 진한 양잿물이 빠르게 추출됩니다. 검은 숯이 많이 섞이면 탄닌 성분이 녹아 나와 비누가 물러지므로 반드시 순백색 재만 선별해야 합니다.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"참나무 백탄 완전 연소 재\",\n            \"scientificName\": \"Quercus Acutissima White Wood Ash\",\n            \"categoryTag\": \"야전 화학 원료 / 탄산칼륨 염기 공급원\",\n            \"imageFileName\": \"id-oak-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-13A // MACRO OPTIC\",\n            \"hudStatus\": \"POTASSIUM CONTENT HIGH: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"빛깔/COLOR\",\n                \"value\": \"검은빛이 전혀 없이 밀가루처럼 **새하얗거나 밝은 은회색**을 띱니다.\"\n              },\n              {\n                \"label\": \"촉감/TEXTURE\",\n                \"value\": \"손가락으로 문지르면 알갱이 걸림 없이 **부드러운 분말 가루**로 바스러집니다.\"\n              },\n              {\n                \"label\": \"추출액/LYE\",\n                \"value\": \"물을 통과시키면 붉은빛이 감도는 **투명한 황금빛 호박색 액체**가 나옵니다.\"\n              }\n            ],\n            \"fieldUse\": \"양잿물 추출 살균 비누 원료, 산성 토양 중화, 곡물 잿물 탈각\"\n          },\n          {\n            \"name\": \"소나무 송진 결정\",\n            \"scientificName\": \"Pinus Densiflora Natural Oleoresin\",\n            \"categoryTag\": \"야전 방부제 / 천연 피톤치드 항균재\",\n            \"imageFileName\": \"id-pine-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-13B // MACRO OPTIC\",\n            \"hudStatus\": \"TERPENE PURITY: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"외형/RESIN\",\n                \"value\": \"소나무 상처에서 흘러나와 굳은 **반투명한 호박색 또는 황백색 결정**입니다.\"\n              },\n              {\n                \"label\": \"향기/AROMA\",\n                \"value\": \"손끝으로 으깨면 코를 찌르는 **상쾌한 솔향(피톤치드 테르펜)**이 강하게 풍깁니다.\"\n              },\n              {\n                \"label\": \"항균/EFFECT\",\n                \"value\": \"비누에 섞으면 거품이 단단해지고 **포도상구균 등 병원균 번식을 억제**합니다.\"\n              }\n            ],\n            \"fieldUse\": \"살균 비누 첨가제, 상처 방수 소독 연고, 화덕 결속 접착제\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"2단계: 생감자 조각을 띄워 양잿물 농도를 맞추고 동물 비계나 폐식용유 정제하기\",\n      \"description\": \"1. **생감자 부력 농도 판정**: 걸러낸 양잿물 그릇에 **엄지손톱 크기(직경 2cm)의 생감자 조각(또는 신선한 날달걀)**을 조심스럽게 띄웁니다.\\n2. **수면 노출 높이 점검**: 감자 조각이 바닥으로 가라앉으면 농도가 묽은 것이므로 냄비에 담아 **부피가 반으로 줄어들 때까지 끓여 농축**합니다. 감자가 수면 위로 **엄지손톱만큼 동동 떠오르면** 비누 제조에 적합한 황금 농도입니다.\\n3. **동물 비계 열탕 정제**: 사냥한 동물의 기름진 비계 덩어리를 잘게 썰어 냄비에 넣고, [우드 가스 스토브](/protocol-12.html)의 약한 불에서 은근히 녹여 맑은 액체 기름을 뽑아냅니다.\\n4. **찌꺼기 여과**: 녹아 나온 기름을 깨끗한 헝겊이나 억새풀 필터로 걸러 타버린 고기 찌꺼기와 수분을 완전히 제거하고 **맑은 기름 2컵**을 확보합니다.\",\n      \"actionNote\": \"> 부력 척도 원칙: 감자가 물 표면 위로 절반 이상 너무 많이 솟구치면 알칼리가 지나치게 강해 비누가 완성된 후 피부가 따갑습니다. 물을 반 컵 부어 희석하고, 정확히 감자 등이 수면 위로 살짝 드러나는 상태를 맞추세요.\",\n      \"svgFileName\": \"pr13-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // POTATO BUOYANCY SPECIFIC GRAVITY TEST\",\n        \"수면 위로 엄지손톱 크기만큼 부유하는 생감자\",\n        \"비중 부족 시 약불 농축 & 과도 시 온수 희석\",\n        \"동물 비계 열탕 용출 및 맑은 정제유 2컵 확보\",\n        \"[2단계 핵심] 감자 부력 검증 & 유지 불순물 완전 분리\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"SPECIFIC GRAVITY\",\n        \"title\": \"비중계 없는 야전 비중 측정(Specific Gravity 1.05~1.10)의 유체역학\",\n        \"text\": \"적정 농도의 양잿물은 비중이 약 1.08 g/cm³에 도달합니다. 신선한 생감자의 평균 밀도는 1.06~1.09 g/cm³이므로, 알칼리 농도가 충분할 때만 아르키메데스의 부력 원리에 의해 위로 떠오릅니다. 비중이 1.05 미만이면 기름과 섞었을 때 비누화 반응이 일어나지 않고 층 분리가 발생합니다.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"3단계: 양잿물과 기름을 1:1로 섞고 죽처럼 걸쭉해질 때까지 나무 주걱으로 저으며 끓이기\",\n      \"description\": \"1. **철제 냄비 투입 비율**: 깡통 냄비에 정제한 기름 2컵과 농도를 맞춘 양잿물 2컵을 **1:1 부피 비율**로 붓습니다.\\n2. **약한 잔열 가열**: 화덕의 센 불을 피하고, 숯불의 은은한 온기 위에서 액체 가장자리에 **작은 기포가 보글보글 일어나는 약한 열기**를 유지합니다.\\n3. **한쪽 방향 연속 교반**: 납작한 나뭇가지 주걱으로 액체를 **한쪽 방향으로만 40~50분간** 쉬지 않고 원을 그리며 천천히 젓습니다. 도중에 방향을 바꾸면 기름과 양잿물이 다시 분리됩니다.\\n4. **트레이스(죽 상태) 판정 및 송진 투입**: 주걱으로 반죽을 떠서 떨어뜨렸을 때 바닥에 떨어진 자국이 **3초간 그대로 남는 땅콩버터나 걸쭉한 미음 상태**가 되면, 빻아둔 [소나무 송진 가루 1큰술](/protocol-10.html)과 소금 1작은술을 넣고 골고루 섞은 뒤 불에서 내립니다.\",\n      \"actionNote\": \"> 3초 흔적(트레이스) 신호: 주걱을 들었을 때 반죽이 물처럼 흩어지지 않고 뚜렷한 리본 자국을 남겨야 화학적 비누화가 완성된 것입니다. 이때 소나무 송진을 섞어주면 천연 소독 향이 배어들고 거품이 단단해집니다.\",\n      \"svgFileName\": \"pr13-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // SAPONIFICATION REACTION & STIRRING\",\n        \"양잿물과 정제 기름 1:1 부피 비율 혼합액\",\n        \"납작한 나무 주걱으로 한 방향 45분 연속 교반\",\n        \"주걱 자국이 3초 유지되는 걸쭉한 트레이스 완성\",\n        \"[3단계 핵심] 약불 은근한 가열 & 송진 가루 혼합\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"SAPONIFICATION\",\n        \"title\": \"트라이글리세라이드 가수분해와 글리세린 생성 화학 메커니즘\",\n        \"text\": \"유지의 주성분인 에스터 화합물이 강염기 탄산칼륨과 만나면 지방산 분자가 칼륨 이온과 결합하여 '지방산 칼륨염(천연 액상 비누)'을 형성하고 글리세린이 부산물로 분리됩니다. 한 방향 교반은 비혼화성 액체 간의 표면적을 극대화하여 분자 접촉 확률을 높이는 필수 기계적 공정입니다.\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"4단계: 나무껍질 틀에 부어 그늘에서 굳힌 뒤 손등 거품 테스트로 안전성 확인하기\",\n      \"description\": \"1. **나무껍질 거푸집 준비**: 안쪽 면이 매끄러운 자작나무나 소나무 껍질을 접어 **손바닥 크기 직사각형 상자 틀**을 만들거나, 납작한 돌판 테두리에 진흙 턱을 둘러 틀을 만듭니다.\\n2. **비누 반죽 타설 및 기포 제거**: 걸쭉한 비누 반죽을 틀에 붓고 바닥을 땅에 톡톡 두드려 내부의 공기 방울을 뺍니다.\\n3. **48시간 서늘한 그늘 건조**: 직사광선이 닿지 않고 바람이 잘 통하는 그늘진 바위틈에 두고 **이틀(48시간) 동안** 단단하게 굳힙니다.\\n4. **손등 안전 거품 시험**: 굳은 비누를 칼로 주먹 반 크기로 자른 뒤, 물을 묻혀 손등에 문질러 봅니다. 피부가 따끔거리지 않고 **새하얗고 미세한 거품**이 풍성하게 일어나면 완성입니다.\",\n      \"actionNote\": \"> 피부 자극 점검: 만약 손등에 문질렀을 때 붉어지거나 따끔거리면 아직 양잿물이 중화되지 않은 상태입니다. 물에 다시 씻어내고 3~4일간 그늘에서 더 말려 숙성시키면 자연적으로 공기 중의 이산화탄소를 흡수하여 순한 비누로 변합니다.\",\n      \"svgFileName\": \"pr13-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // MOLD CASTING & FOAM SAFETY TEST\",\n        \"자작나무 껍질 사각 거푸집 성형 및 타설\",\n        \"48시간 서늘한 바람 그늘 자연 응고 경화\",\n        \"손등 문지름 시 따끔거림 없는 풍성한 미세 거품\",\n        \"[4단계 핵심] 완전 건조 숙성 & 피부 안전성 통과\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"ANTIMICROBIAL SCIENCE\",\n        \"title\": \"지질 이중층 용해와 병원균 세포막 사멸 원리\",\n        \"text\": \"비누 분자는 친유성(기름을 좋아하는) 탄화수소 꼬리와 친수성(물을 좋아하는) 머리로 이루어져 있습니다. 상처 주변의 세균이나 바이러스에 닿으면 친유성 꼬리가 병원균의 세포막 지질 이중층을 쐐기처럼 찔러 넣어 외피를 터뜨리고, 물로 헹굴 때 미세 거품 속에 가두어 완벽하게 씻어냅니다.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"치명적 실수: 강염기 양잿물을 맨손으로 만지거나 덜 굳은 비누를 상처 부위에 직접 바르는 행위\",\n    \"description\": \"참나무 재를 거른 양잿물은 단백질을 녹이는 강염기성 액체이므로 맨손으로 만지면 피부가 벗겨지는 화학 화상을 입고 눈에 튀면 실명합니다. 또한 비누화 반응이 완전히 끝나지 않고 숙성되지 않은 생비누를 깊은 상처에 바르면 세포가 괴사합니다. 피부에 묻었을 땐 즉시 차가운 맑은 물로 5분 이상 충분히 씻어내고, 48시간 이상 그늘에서 말려 거품 테스트를 거친 순한 비누만 식기 세척 및 환부 주변 소독에 사용하세요.\",\n    \"consequence\": \"결과: 피부 화학 화상, 각막 손상 실명 및 덜 숙성된 잿물로 인한 피부 세포 괴사 위험\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"병원도 약도 없는 야생에서 상처에 흙탕물이 닿으면 사흘 안에 패혈증으로 쓰러집니다! 참나무 재로 천연 살균 비누 만드는 법!\",\n    \"body\": \"하얗게 탄 참나무 재를 깡통에 담고 끓인 물을 부어 양잿물을 거르세요. 생감자를 띄워 엄지손톱만큼 동동 뜨면 완벽한 농도입니다! 여기에 정제한 동물 기름을 1:1로 섞어 우드 가스 스토브의 약한 불에서 40분간 주걱으로 저어줍니다. 주걱을 들었을 때 떨어진 자국이 3초간 남는 땅콩버터 상태가 되면 나무껍질 틀에 부어 이틀간 그늘에서 굳히세요! 하얀 거품이 풍성하게 일어나는 순간 세균을 죽이는 특급 살균 비누가 완성됩니다!\",\n    \"outro\": \"인터넷이 끊겨도 볼 수 있는 오프라인 도면은 프로필 링크에서 무료로 확인하세요.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr13-outcome.svg\",\n    \"title\": \"완성된 참나무 재 천연 살균 잿물 비누 제조 공정 및 비누화 반응 단면 제원\",\n    \"description\": \"참나무 백탄 재 여과 컬럼에서 추출된 황금빛 양잿물, 생감자 부력 농도 측정, 냄비 속 1:1 비누화 교반 공정, 그리고 나무껍질 거푸집에서 응고된 사각형 천연 살균 잿물 비누 블록의 종합 화학 단면입니다.\",\n    \"svgLabels\": [\n      \"FIG. 13-M // NATURAL WOOD ASH LYE SOAP PRODUCTION OVERVIEW\",\n      \"좌측: 참나무 백탄 재 여과 및 생감자 부력 비중 측정\",\n      \"중앙: 약불 가열 1:1 비누화 반응 & 송진 첨가 교반\",\n      \"우측: 수목 수피 거푸집 응고 사각 살균 비누 블록\",\n      \"[PR-13 최종 완성] 병원균 세포막 사멸 야전 소독 비누\"\n    ]\n  },\n  \"createdAt\": \"2026-10-21T05:30:00.000Z\",\n  \"contentHash\": \"84750b222b4c5546\",\n  \"updatedAt\": \"2026-10-21T05:32:17.564Z\"\n}","content/protocols/14-bone-needle-sinew-sewing.json":"{\n  \"protocolId\": \"PR-14\",\n  \"category\": \"TOOLS\",\n  \"title\": \"동물 다리뼈와 마른 힘줄로 찢어진 가죽옷과 신발을 꿰매는 법 (야전 골침과 건사 봉제술)\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[혹한기 체온 유실 방어 & 발 동상·저체온증 차단]\",\n  \"summary\": \"혹한의 겨울 야생이나 문명 붕괴 재난지에서 방한 가죽옷이나 가죽 신발 밑창이 찢어지면, 체온이 급격히 빠져나가 2시간 안에 치명적인 저체온증에 걸리거나 발에 동상이 생겨 걸을 수 없게 됩니다. 금속 바늘과 나일론 실이 없는 원시 야전에서는 [동물 덫과 사냥](/protocol-08.html)으로 얻은 사슴이나 멧돼지의 다리 정강이뼈를 [단단한 돌도끼](/protocol-04.html)로 쪼개고 규암 숫돌에 갈아 바늘귀를 뚫은 '뼈바늘(Bone Needle)'과, 다리 힘줄을 말려 두드려 풀어낸 초강력 섬유 '건사(Sinew Thread)'를 결합하여 바느질 키트를 자급해야 합니다. 마른 힘줄 실은 침을 묻혀 꿰맨 뒤 마르면서 3~5% 스스로 수축해 가죽 구멍을 꽉 메우므로, [달군 소나무 송진 고약](/protocol-10.html)을 바르면 비바람과 눈보라가 전혀 스며들지 않는 완벽한 방한 장비가 복원됩니다.\",\n  \"timeRequired\": \"60분 (뼈바늘 연마 30분 + 힘줄 실 가공 15분 + 가죽 봉제 15분)\",\n  \"successRate\": \"95% (부싯돌 송곳 예비 천공 및 힘줄 실 침 코팅 준수 시)\",\n  \"difficulty\": \"보통 (손가락 굵기 치밀골 선별 및 부싯돌 천공 주의)\",\n  \"outputPerHour\": \"뼈바늘 2개와 힘줄 실 10가닥으로 찢어진 가죽 장화 1켤레 또는 방한 외투 1벌 완전 수선\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"사냥한 큰 동물(사슴·노루·멧돼지)의 다리 정강이뼈 파편 1~2개\",\n      \"desc\": \"[동물 덫 사냥](/protocol-08.html)이나 [잿물 비누](/protocol-13.html)용 기름을 정제하고 남은 다리뼈입니다. 뼈의 중심부 원통형 치밀골(Cortical Bone)은 강철 못에 맞먹는 인장 강도와 굽힘 탄성을 지녀 가죽을 뚫어도 쉽게 부러지지 않습니다.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"거친 규암 연마 숫돌과 구멍 뚫기용 뾰족한 부싯돌 송곳\",\n      \"desc\": \"[돌칼과 돌도끼 가공](/protocol-04.html)에 쓰이는 입자가 거친 규암 바위 판자와, 뼈에 2mm 바늘귀를 뚫기 위한 날카로운 원뿔형 차돌/부싯돌 송곳(Flint Awl)입니다.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"다리 관절에서 채취하여 바짝 말린 동물 힘줄(Sinew) 다발\",\n      \"desc\": \"사슴이나 소의 아킬레스건 부위에서 떼어내 바람이 잘 통하는 그늘에서 딱딱하게 말린 황백색 반투명 힘줄 끈입니다. 방망이로 가볍게 두드리면 머리카락 굵기의 고강도 천연 섬유 수백 가닥으로 분리됩니다.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"송곳 타격용 손바닥 크기 나무 방망이와 솔기 밀봉용 소나무 송진\",\n      \"desc\": \"힘줄 섬유를 분쇄하고 가죽을 천공할 때 쓰는 단단한 참나무 몽둥이와, [소나무 송진 연고](/protocol-10.html)로 쓰는 방수 밀봉용 송진 덩어리입니다.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"1단계: 동물 정강이뼈를 돌로 쪼개고 규암 숫돌에 갈아 손가락 길이의 뾰족한 뼈바늘 블랭크 만들기\",\n      \"description\": \"1. **치밀골 선별 및 세로 쪼개기**: 사슴이나 큰 동물의 다리 정강이뼈를 골라 [돌도끼나 단단한 강돌](/protocol-04.html)로 세로 충격을 주어 **손가락 길이(약 7~8cm), 두께 3~4mm**의 길쭉한 뼈 조각을 쪼개냅니다.\\n2. **규암 숫돌 거친 연마**: 물을 묻힌 거친 규암 바위 표면에 뼈 조각을 45도 각도로 눕혀 문지르며 울퉁불퉁한 골수 잔여물을 깎아내고 매끄러운 둥근 막대 형태로 다듬습니다.\\n3. **바늘촉 예각 연마**: 한쪽 끝을 돌 표면에 30도 각도로 세워 돌려가며 갈아 가죽을 뚫을 수 있을 만큼 **바늘처럼 날카로운 송곳 촉**을 완성합니다.\",\n      \"actionNote\": \"> 골편 파편 주의: 뼈를 돌로 쪼갤 때 튀는 미세한 뼛가루 파편이 눈에 들어가지 않도록 얼굴을 45도 돌리고 타격하세요. 거친 숫돌에 물을 묻혀 갈면 마찰열로 뼈가 타서 물러지는 현상을 방지할 수 있습니다.\",\n      \"svgFileName\": \"pr14-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // BONE SPLINTER BLANK PREPARATION\",\n        \"사슴 정강이뼈 치밀골 세로 쪼개기\",\n        \"물 묻힌 거친 규암 숫돌 표면 연마\",\n        \"손가락 길이 (7~8cm) & 원형 막대 성형\",\n        \"[1단계 핵심] 30° 회전 연마로 날카로운 촉 완성\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BIOMECHANICS\",\n        \"title\": \"포유류 하지골 수산화인회석(Hydroxyapatite) 구조와 전단 강도\",\n        \"text\": \"사슴이나 멧돼지 등 대형 포유류의 정강이뼈(Tibia)와 중족골은 체중을 지탱하기 위해 미세 기공이 거의 없는 고밀도 치밀골(Cortical Bone)로 이루어져 있습니다. 칼슘 복합체인 수산화인회석 결정과 유연한 콜라겐 섬유가 층상 구조(Lamellae)를 형성하고 있어, 연마 시 강철 못에 필적하는 굽힘 저항력과 매끄러운 침투력을 가집니다.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"포유류 정강이뼈 치밀골 골편\",\n            \"scientificName\": \"Mammalian Tibia Cortical Bone\",\n            \"categoryTag\": \"야전 골각기 가공재 / 고강도 뼈바늘 소재\",\n            \"imageFileName\": \"id-deer-metatarsal-bone.jpg\",\n            \"hudCode\": \"FIG. BIO-14A // MACRO OPTIC\",\n            \"hudStatus\": \"DENSITY & FLEXURAL STRENGTH: HIGH\",\n            \"traits\": [\n              {\n                \"label\": \"빛깔/COLOR\",\n                \"value\": \"골수 속살은 누런빛을 띠고 겉면은 **유백색 내지 연한 크림색**을 띱니다.\"\n              },\n              {\n                \"label\": \"조직/DENSITY\",\n                \"value\": \"스펀지 같은 기공이 없고 **유리 단면처럼 매끄럽고 치밀한** 단단한 층입니다.\"\n              },\n              {\n                \"label\": \"소리/ACOUSTIC\",\n                \"value\": \"돌로 가볍게 두드렸을 때 둔탁하지 않고 **맑은 쇳소리(챙- 맑은 공명음)**가 납니다.\"\n              }\n            ],\n            \"fieldUse\": \"두께 3~4mm 세로 파편을 선별하여 규암 숫돌 연마용 뼈바늘 블랭크로 투입\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"2단계: 부싯돌 송곳 끝으로 뼈바늘 머리에 회전 구멍(Eye)을 뚫고 표면 활석 다듬기\",\n      \"description\": \"1. **양면 회전 천공**: 날카로운 부싯돌 송곳(Flint Awl) 끝을 뼈바늘 뭉툭한 머리 끝에서 **새끼손톱 반(약 5mm) 안쪽 지점**에 대고, 양손으로 돌려가며 뼈의 양쪽 면에서 마주 보게 원뿔형 구멍을 팝니다.\\n2. **바늘귀 관통 및 버(Burr) 제거**: 구멍이 관통되면 얇은 나뭇가지나 마른 가시를 통과시켜 회전시켜 구멍 내부의 거친 뼈 부스러기를 긁어내 실이 끊어지지 않게 매끄럽게 만듭니다.\\n3. **미세 연마**: 고운 점토석이나 강 모래로 뼈바늘 전면을 문질러 가죽을 통과할 때 걸림이 없도록 **유리알처럼 매끄럽게 광택**을 냅니다.\",\n      \"actionNote\": \"> 머리 파손 방지: 구멍을 한쪽에서만 깊게 파면 뼈 머리가 쪼개집니다. 반드시 앞면에서 절반을 파고 뒤집어 뒷면에서 마주 뚫는 '양면 마주 천공법'을 엄수하세요.\",\n      \"svgFileName\": \"pr14-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // DUAL-CONE EYE DRILLING & FINISHING\",\n        \"부싯돌 송곳(Flint Awl) 양면 회전 천공\",\n        \"머리 끝 5mm 안쪽 바늘귀(Eye) 관통 구멍\",\n        \"잔가시 회전 내부 버(Burr) 제거\",\n        \"[2단계 핵심] 고운 강 모래 연마로 유리알 광택 마감\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"3단계: 마른 동물 힘줄(Sinew)을 나무 방망이로 두드려 머리카락 굵기의 강철 실 분리하기\",\n      \"description\": \"1. **햇볕 건조 힘줄 준비**: 도축 직후 채취하여 바람이 통하는 그늘에서 딱딱하게 말린 황백색 반투명 힘줄 끈을 납작한 돌받침 위에 올립니다.\\n2. **목질 방망이 타격**: 둥근 나무 방망이로 힘줄을 톡톡 가볍게 두드려 콜라겐 섬유 다발 사이의 결합을 분쇄합니다 (강하게 내리치면 섬유가 끊어지므로 주의).\\n3. **단섬유 빗질 및 침 코팅**: 두드려 하얗게 일어난 힘줄 뭉치를 손끝으로 잡아당겨 **머리카락 3~4가닥 굵기의 긴 섬유 가닥**들을 뽑아냅니다. 실 끝에 침을 살짝 발라 비비면 섬유질이 하나로 뭉쳐지며 바늘귀에 부드럽게 들어갑니다.\",\n      \"actionNote\": \"> 타격 강도 조절: 도끼날이나 날카로운 돌로 내리치면 힘줄 가닥이 조각나 쓸모없어집니다. 뭉툭한 참나무 방망이의 둥근 모서리로 '두드려 펴는 느낌'으로 섬세하게 타격하세요.\",\n      \"svgFileName\": \"pr14-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DRIED ANIMAL SINEW FIBER SEPARATION\",\n        \"납작한 돌받침 위 건조 힘줄(Sinew) 배치\",\n        \"참나무 방망이 경타격 (콜라겐 다발 분쇄)\",\n        \"머리카락 3~4가닥 굵기 고인장 섬유 빗질\",\n        \"[3단계 핵심] 침(Saliva) 코팅으로 바늘귀 부드러운 통과\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIBER SCIENCE\",\n        \"title\": \"동물 힘줄 콜라겐(Collagen Type I)의 건조 수축과 자가 체결력\",\n        \"text\": \"힘줄(Tendon)을 이루는 Type I 콜라겐 원섬유는 인장 강도가 약 50~100 MPa에 달하여 동일 굵기의 무명실보다 4배 이상 질깁니다. 침이나 물에 젖은 상태에서는 유연하게 바느질 구멍을 통과하며, 체류 후 자연 건조되면 3~5% 부피가 수축하면서 가죽의 바늘구멍을 사방에서 꽉 압착하여 매듭이 풀리지 않는 완벽한 자가 체결(Self-Locking)을 완성합니다.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"바짝 말린 동물 힘줄(건사)\",\n            \"scientificName\": \"Dried Mammalian Tendon (Sinew)\",\n            \"categoryTag\": \"야전 천연 섬유 / 초고장력 봉제사\",\n            \"imageFileName\": \"id-dried-animal-sinew.jpg\",\n            \"hudCode\": \"FIG. BIO-14B // MACRO OPTIC\",\n            \"hudStatus\": \"TENSILE STRENGTH RATING: MAXIMUM\",\n            \"traits\": [\n              {\n                \"label\": \"외형/TEXTURE\",\n                \"value\": \"빛에 비추었을 때 **황백색 뿔처럼 반투명하고 딱딱한** 막대 형태입니다.\"\n              },\n              {\n                \"label\": \"분리/SEPARATION\",\n                \"value\": \"방망이로 두드리면 **명주실처럼 보드랍고 은백색인 미세 섬유**로 풀립니다.\"\n              },\n              {\n                \"label\": \"수축/SHRINKAGE\",\n                \"value\": \"침을 묻혔을 때 부드러워지고, 마르면 **강철 철사처럼 팽팽하게 수축**합니다.\"\n              }\n            ],\n            \"fieldUse\": \"머리카락 굵기로 찢어내어 뼈바늘에 꿰어 가죽 봉제 및 돌도끼 자루 결속에 투입\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"4단계: 부싯돌 송곳으로 가죽에 예비 구멍을 뚫고 새들 스티치(이중 꿰매기)로 봉제 후 송진 밀봉하기\",\n      \"description\": \"1. **가죽 가장자리 송곳 예비 천공**: 찢어진 가죽 양쪽 단면을 **손가락 한 마디 겹치게** 맞대고, 뼈바늘이 부러지지 않도록 단단한 부싯돌 송곳으로 **5mm 간격의 바늘구멍**을 일렬로 먼저 뚫습니다.\\n2. **새들 스티치(양방향 교차 봉제)**: 힘줄 실 양 끝에 뼈바늘 2개를 꿰거나, 한 바늘로 구멍을 통과한 뒤 다음 구멍에서 앞뒤로 엇갈리게 통과시키며 단단히 당겨 꿰맵니다.\\n3. **건조 수축 및 송진 방수 코팅**: 바느질을 마친 뒤 [달군 소나무 송진 고약](/protocol-10.html)을 봉제선 솔기 위에 얇게 문질러 바르면 건조 수축된 힘줄 실과 함께 눈과 빗물이 전혀 스며들지 않는 **완전 방한·방수 가죽 장비**가 완성됩니다.\",\n      \"actionNote\": \"> 송곳 예비 천공 엄수: 뼈바늘은 관통력이 뛰어나지만 두꺼운 가죽을 무리하게 뚫다가는 바늘귀가 부러집니다. 구멍은 반드시 부싯돌 송곳으로 먼저 뚫고, 뼈바늘은 실을 통과시키는 가이드로만 쓰세요.\",\n      \"svgFileName\": \"pr14-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // SADDLE STITCHING & PITCH SEALING\",\n        \"부싯돌 송곳 5mm 간격 예비 가죽 천공\",\n        \"힘줄 실 양방향 교차(Saddle Stitch) 봉제\",\n        \"소나무 송진 고약 솔기 방수 코팅\",\n        \"[4단계 핵심] 힘줄 건조 수축으로 바늘구멍 완전 밀폐\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"치명적 실수: 부싯돌 송곳 예비 천공 없이 두꺼운 젖은 가죽을 뼈바늘 머리를 쥐고 억지로 힘주어 밀어 넣는 행위\",\n    \"description\": \"두꺼운 생가죽을 무리하게 뼈바늘로 뚫으려 하면 바늘귀나 몸체가 부러지며, 예리한 골편이 손바닥이나 손가락 깊숙이 박혀 심한 관통 자상과 야전 파상풍 감염을 유발합니다. 두꺼운 가죽은 반드시 단단한 부싯돌 송곳과 나무 방망이로 5mm 간격 예비 관통 구멍을 먼저 뚫은 뒤, 뼈바늘은 실을 안내하여 넘기는 용도로만 부드럽게 통과시키세요.\",\n    \"consequence\": \"결과: 뼈바늘 파손, 손바닥 깊은 골편 자상 및 야전 파상풍 패혈증 감염 위험\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"영하 20도 혹한의 야생에서 신발 밑창이나 방한 가죽옷이 찢어졌다면? 2시간 안에 얼어 죽습니다. 지금 당장 뼈바늘을 만드세요!\",\n    \"body\": \"사냥한 동물의 다리 정강이뼈를 돌로 쪼개 규암 숫돌에 갈아 손가락 길이 뼈바늘을 만듭니다. 부싯돌 송곳으로 뼈 머리 양쪽을 마주 돌려 바늘귀를 뚫으세요. 그다음 마른 힘줄을 나무 방망이로 두드리면 명주실보다 질긴 콜라겐 실이 나옵니다. 침을 묻혀 바늘에 꿰고, 부싯돌로 가죽에 구멍을 뚫어 양방향으로 꿰매주면 끝! 힘줄 실이 마르면서 구멍을 스스로 꽉 조이고, 소나무 송진을 문지르면 완전 방수 가죽옷이 부활합니다.\",\n    \"outro\": \"문명이 무너져도 우리에겐 뼈와 힘줄이 있습니다. 생존 교범을 구독하고 야전 기술을 확보하세요!\"\n  },\n  \"outcome\": {\n    \"title\": \"야전 수선 완료된 방한 가죽 장화와 뼈바늘·힘줄 실 바느질 키트\",\n    \"badge\": \"완성 검수 규격 // FIELD REPAIRED GEAR\",\n    \"standard\": \"뼈바늘 표면이 걸림 없이 매끄럽고, 바늘귀가 힘줄 실 2가닥을 견고히 수용하며, 새들 스티치로 결속된 가죽 솔기가 손으로 강하게 잡아당겨도 1mm의 벌어짐 없이 팽팽하게 체결되어 있을 것\",\n    \"svgFileName\": \"pr14-outcome.svg\",\n    \"svgLabels\": [\n      \"PR-14 OUTCOME // BONE NEEDLE & SINEW SEWING KIT\",\n      \"완성된 유백색 고밀도 치밀골 뼈바늘 (길이 7.5cm)\",\n      \"부싯돌 송곳 양면 천공 정밀 바늘귀 (직경 1.8mm)\",\n      \"나무 방망이로 두드려 분리한 은백색 고인장 힘줄 실 다발\",\n      \"새들 스티치 이중 결속 & 소나무 송진 방수 밀봉 솔기 단면\",\n      \"완전 복원된 방한 가죽 장화 (체온 유실 100% 차단)\",\n      \"FIELD VERIFIED // TENSILE STRENGTH RATED & WATERPROOF\"\n    ]\n  },\n  \"faqs\": [\n    {\n      \"question\": \"힘줄 실(건사)이 바느질 도중 자꾸 굳어서 바늘귀에서 빠져요.\",\n      \"causeDiagnostic\": \"바느질 중 공기 중에 노출되어 침이나 수분이 증발하면서 콜라겐 섬유가 뻣뻣하게 굳는 자연스러운 현상입니다.\",\n      \"resolution\": \"손끝에 침이나 물을 살짝 묻혀 힘줄 실 끝을 2~3초간 살살 문지르십시오. 콜라겐 섬유가 즉시 말랑말랑해지며 바늘귀에 다시 부드럽게 들어가고 실밥 갈라짐이 사라집니다.\"\n    },\n    {\n      \"question\": \"가죽을 꿰맨 바늘구멍 사이로 찬바람과 물방울이 스며듭니다.\",\n      \"causeDiagnostic\": \"부싯돌 송곳으로 뚫은 예비 구멍의 직경이 아직 건조 수축되지 않은 힘줄 실 두께보다 약간 커서 생긴 미세 틈새입니다.\",\n      \"resolution\": \"당황하지 마십시오. 젖은 힘줄 실은 상온에서 자연 건조되면서 3~5% 부피가 팽팽하게 수축하여 구멍을 스스로 꽉 조입니다. 바느질 하루 뒤 달군 소나무 송진 고약(PR-10)을 솔기 위에 얇게 펴 바르면 완전한 방한·방수 피막이 형성됩니다.\"\n    }\n  ],\n  \"createdAt\": \"2026-10-22T08:09:29.733Z\",\n  \"updatedAt\": \"2026-10-22T08:14:43.819Z\",\n  \"contentHash\": \"614132e570544622\"\n}","content/protocols/locales/01-water-purification.de.json":"{\n  \"protocolId\": \"PR-01\",\n  \"category\": \"WATER\",\n  \"title\": \"Wie man schlammiges Wasser in sauberes Trinkwasser verwandelt (Naturfilter aus Kohle und Sand)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[WICHTIGES ÜBERLEBEN]\",\n  \"summary\": \"Unbehandeltes schlammiges Wasser in der Wildnis zu trinken führt zu schweren Magenkrämpfen, Durchfall und lebensgefährlicher Dehydrierung. Durch ein Ast-Dreibein mit Rindentrichter und schichtweisem Aufbau aus Kohle, Sand und Kies wird trübes Wasser glasklar gefiltert. Durch anschließendes sprudelndes Kochen für 3+ Minuten werden mikroskopische Keime vollständig zerstört und das Wasser sicher trinkbar.\",\n  \"timeRequired\": \"25 Min. (15 Min. Filtration + 10 Min. Kochen)\",\n  \"successRate\": \"99.9% (Nach schichtweiser Filtration und 3+ Min. Kochen)\",\n  \"difficulty\": \"Mittel (Ausschließlich aus Naturmaterialien herstellbar)\",\n  \"outputPerHour\": \"1.5 bis 2.0 Liter sauberes Wasser pro Stunde\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Holzkohle (Zwei Handvoll, erbsengroß)\",\n      \"desc\": \"Adsorbiert gelöste Verunreinigungen und Gerüche. Auf Stücke zerkleinern, die größer als Reiskörner und erbsengroß sind (5–8 mm).\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Gewaschener feiner Flusssand (Zwei Handvoll)\",\n      \"desc\": \"Hält feine Schlammpartikel zurück. Vor der Verwendung zwei- bis dreimal in fließendem Wasser auswaschen.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Kleine runde Kieselsteine (Eine Handvoll)\",\n      \"desc\": \"Daumennagelgroße saubere Steine. Fangen groben Schmutz ab und dämpfen den Wasserstrahl, damit die Sandschicht nicht ausgewaschen wird.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Birkenrindentrichter oder hohles Bambusrohr (1 Stück)\",\n      \"desc\": \"Ein 30–40 cm langer, nach unten schmaler werdender Behälter. Hält die Filterschichten und leitet die Wassertropfen ab.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"Drei fingerdicke gerade Äste (50 cm lang)\",\n      \"desc\": \"Oben zusammengebunden als stabiles Dreibein. Hält den Trichter hoch genug für ein Auffanggefäß darunter.\"\n    },\n    {\n      \"id\": \"mat-06\",\n      \"name\": \"Sauberes feuchtes Moos oder Stoffrest\",\n      \"desc\": \"Fest in den Auslauf gestopft, um Kohle und Sand abzustützen, ohne dass Partikel ins Auffanggefäß fallen.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Schritt 1: Dreibein aufstellen und Rindentrichter montieren\",\n      \"description\": \"1. **Dreibein montieren**: Drei fingerdicke Äste oben mit Schnur fest zusammenbinden und zu einem stabilen Dreibein aufstellen.\\n2. **Trichter aufhängen**: Den Birkenrindentrichter oder das Bambusrohr senkrecht in der Mitte des Dreibeins befestigen.\\n3. **Bodenstopfen einsetzen**: Sauberes, feuchtes Moos fest mit dem Finger in die untere Öffnung drücken. Ein lockerer Stopfen führt zum Auslaufen der Filterschichten.\",\n      \"actionNote\": \"> Stopfen prüfen: Sitzt der Stopfen zu locker, rieselt Kohlestaub heraus. Drücken Sie ihn fest hinein.\",\n      \"svgFileName\": \"pr01-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PURIFICATION STEP 1: DREIBEIN & STOPFEN\",\n        \"TRIPOD FRAME (DREIBEIN)\",\n        \"CONE FUNNEL (TRICHTER)\",\n        \"MOSS PLUG (MOOSSTOPFEN)\",\n        \"[SCHRITT 1] STABILES DREIBEIN AUFSTELLEN\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Schritt 2: Kohle auf Erbsengröße zerkleinern und 8 cm einfüllen\",\n      \"description\": \"1. **Zerkleinern & Sortieren**: Vollständig kalte Holzkohle mit einem Stein vorsichtig in **erbsengroße Stücke (5–8 mm)** klopfen. Mehlfeinen Staub entfernen, der den Wasserdurchfluss verstopfen würde.\\n2. **8 cm Kohlebett einfüllen**: Die Kohle über den Moosstopfen schütten und mit einem Stöckchen leicht andrücken, bis eine ebene Schicht von **vier Fingerbreiten (ca. 8 cm)** erreicht ist.\",\n      \"actionNote\": \"> Korngröße: Die Stücke müssen größer als Reiskörner sein. Feiner Staub hemmt die Fließgeschwindigkeit.\",\n      \"svgFileName\": \"pr01-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // PURIFICATION STEP 2: KOHLEFILTERBETT\",\n        \"CHARCOAL CORE (AKTIVKOHLE)\",\n        \"PORE ABSORPTION (ADSORPTION)\",\n        \"THICKNESS: 8CM (DICKE)\",\n        \"[SCHRITT 2] 8CM KOHLEKOMPONENTE EINFÜLLEN\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD SCIENCE\",\n        \"title\": \"Wirkungsweise der Kohleadsorption\",\n        \"text\": \"Wird Holz unter Sauerstoffmangel erhitzt, bilden sich im Inneren Millionen mikroskopischer Poren. Diese Mikroporen üben starke Van-der-Waals-Kräfte aus, die gelöste organische Toxine und Gerüche an der Kohleoberfläche binden.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Schritt 3: 6 cm sauberen Flusssand über die Kohle füllen und einebnen\",\n      \"description\": \"1. **Sand ausspülen**: Feinen Flusssand zwei- bis dreimal im Wasser auswaschen, um gelösten Schlamm zu entfernen.\\n2. **6 cm Sandschicht einbringen**: Den gewaschenen Sand langsam über die Kohle gießen, bis eine Schicht von **drei Fingerbreiten (ca. 6 cm)** entsteht.\\n3. **Oberfläche glätten**: Die Oberseite mit einem flachen Stein oder der Handfläche eben streichen. Eine schiefe Schicht führt dazu, dass Wasser unvollständig an der dünneren Stelle abfließt.\",\n      \"actionNote\": \"> Schicht einebnen: Eine waagerechte Oberfläche gewährleistet eine gleichmäßige Filtration über die gesamte Säule.\",\n      \"svgFileName\": \"pr01-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // PURIFICATION STEP 3: SANDSCHICHT\",\n        \"RIVER SAND (FLUSSSAND)\",\n        \"PARTICLE FILTER (FILTER)\",\n        \"THICKNESS: 6CM (DICKE)\",\n        \"[SCHRITT 3] KOHLE SICHERN & SCHMUTZ FANGEN\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Schritt 4: 4 cm Kiesel auflegen, Schlammwasser gießen und Erstspülung verwerfen\",\n      \"description\": \"1. **4 cm Kieselschicht auflegen**: Daumennagelgroße Steine **zwei Fingerbreit (ca. 4 cm)** auf den Sand legen und mit einem breiten Blatt abdecken.\\n2. **Schlammwasser eingießen**: Das Trübwasser langsam über das Blatt gießen. Kiesel und Blatt dämpfen den Strahl und verhindern Aushöhlungen im Sand.\\n3. **Erste 1-2 Tassen wegschütten**: Die ersten **1–2 Tassen (ca. 300 ml)** spülen gelösten Kohlestaub aus und **müssen verworfen werden**.\\n4. **Klares Wasser auffangen**: Sobald die Tropfen glasklar fallen, ein sauberes Auffanggefäß unterstellen.\",\n      \"actionNote\": \"> Erstwasser wegschütten: Die ersten Becher reinigen das Filterinnere. Nicht trinken, bis das Wasser glasklar tropft.\",\n      \"svgFileName\": \"pr01-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // PURIFICATION STEP 4: KIESEL & SPÜLEN\",\n        \"PEBBLE LAYER (KIESEL)\",\n        \"FLUSH FIRST CUPS (SPÜLEN)\",\n        \"CLEAR DRIP (KLARTROPF)\",\n        \"[SCHRITT 4] SAND SCHÜTZEN & ERSTWASSER WEG\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Schritt 5: Das gefilterte klare Wasser 3+ Minuten sprudelnd kochen\",\n      \"description\": \"1. **In Kochbehälter füllen**: Das glasklar gefilterte Wasser in einen Steintopf, Tonkessel oder Bambusbehälter füllen und über die Glut stellen.\\n2. **3 Minuten sprudelnd kochen**: Sobald große Blasen über die gesamte Oberfläche steigen, das Kochen mindestens **3 Minuten lang (über 1.000 m Höhe 5 Minuten lang)** aufrechterhalten.\\n3. **Abkühlen lassen**: Vor dem Trinken vollständig abkühlen lassen.\",\n      \"actionNote\": \"> Kochen zwingend erforderlich: Klares Wasser ist KEIN keimfreies Wasser. Erst Filtration und anschließendes Abkochen gewährleisten 99.9% biologische Sicherheit.\",\n      \"svgFileName\": \"pr01-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // PURIFICATION STEP 5: 100°C KOCHEN\",\n        \"BOILING 100°C (KOCHEN)\",\n        \"TIME: 3+ MIN (MINUTEN)\",\n        \"PATHOGEN FREE (KEIMFREI)\",\n        \"[SCHRITT 5] 3+ MINUTEN SPRUDELND KOCHEN\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD SCIENCE\",\n        \"title\": \"Warum selbst klares Wasser abgekocht werden muss\",\n        \"text\": \"Kohle- und Sandfilter entfernen sichtbare Schlammpartikel und Gerüche, aber mikroskopische Zysten (Giardien, Kryptosporidien) passieren einfache Poren. Dauerhaftes Kochen bei 100°C denaturiert die Proteine der Krankheitserreger und inaktiviert 99.9% aller Keime.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Tödlicher Fehler: Das gefilterte klare Wasser ohne Abkochen zu trinken\",\n    \"description\": \"Kohle und Sand fangen nur sichtbaren Schlamm und Geruch ab. Mikroskopische Parasiten und Viren bleiben im Wasser aktiv. Wer ungekochtes Wasser trinkt, erleidet nach wenigen Stunden schwere Magenkrämpfe und Durchfall, was in der Wildnis zu lebensgefährlicher Austrocknung führt.\",\n    \"consequence\": \"Folge: Schwere Magen-Darm-Infektion und lebensbedrohliche Dehydrierung\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Wildes Schlammwasser zu trinken führt in 3 Tagen zu tödlichem Durchfall! So reinigst du es ohne Plastik!\",\n    \"body\": \"Dreibein binden, Rindentrichter aufhängen und Auslauf mit Moos stopfen. 8 cm Kohle, 6 cm Sand und 4 cm Kiesel einfüllen. Schlammwasser darübergießen! Die ersten 2 Becher mit Kohlestaub wegschütten. Wichtigste Regel: Klares Wasser ist noch nicht sicher! Du musst es mindestens 3 Minuten lang sprudelnd kochen, um mikroskopische Erreger zu töten!\",\n    \"outro\": \"Genaue Offline-Überlebenspläne ohne Internet gibt es über den Link im Profil.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr01-outcome.svg\",\n    \"title\": \"Fertiger Naturwasserfilter aus Kohle und Sand\",\n    \"description\": \"An einem Dreibein aufgehängte Filtrationssäule aus Holzkohle, Flusssand, Kieselsteinen und Moosstopfen, die schlammiges Wildwasser in glasklares, abkochbares Trinkwasser verwandelt.\"\n  },\n  \"createdAt\": \"2026-10-09T16:00:00.000Z\",\n  \"updatedAt\": \"2026-10-15T15:29:10+09:00\",\n  \"contentHash\": \"8e86ecfb1c03de78\"\n}","content/protocols/locales/01-water-purification.en.json":"{\n  \"protocolId\": \"PR-01\",\n  \"category\": \"WATER\",\n  \"title\": \"How to Turn Muddy Water into Clean Drinking Water (Natural Filter with Charcoal & Sand)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[MUST-HAVE SURVIVAL]\",\n  \"summary\": \"Drinking untreated muddy water in the wild leads to severe cramps, diarrhea, and dangerous dehydration. By building a three-branch tripod, hanging a bark cone, and layering charcoal, sand, and pebbles in order, turbid water is filtered clear. Boiling this filtered water vigorously for 3+ minutes destroys residual microscopic bacteria, making it safe to drink.\",\n  \"timeRequired\": \"25 min (15 min filtration + 10 min boiling)\",\n  \"successRate\": \"99.9% (When layered in sequence and boiled for 3+ min)\",\n  \"difficulty\": \"Moderate (Built purely from natural materials)\",\n  \"outputPerHour\": \"1.5 to 2.0 liters of clean water per hour\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Hardwood charcoal (Two handfuls, pea-sized)\",\n      \"desc\": \"Adsorbs dissolved impurities and foul odors. Crush to chunks larger than rice grains and pea-sized (5-8mm).\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Clean rinsed river sand (Two handfuls)\",\n      \"desc\": \"Filters fine silt and suspended particles. Rinse two or three times in running water to clear mud before use.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Small round pebbles (One handful)\",\n      \"desc\": \"Fingernail-sized clean stones. Traps coarse debris and buffers inflow so the sand bed is not displaced.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Birch bark cone or hollow bamboo tube (1 piece)\",\n      \"desc\": \"A 30-40cm cylindrical or conical container narrowing at the bottom. Holds filtration layers and funnels drips.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"Three straight finger-thick branches (50cm long)\",\n      \"desc\": \"Tied together at the top to form a stable tripod. Holds the cone high enough to place a collection cup below.\"\n    },\n    {\n      \"id\": \"mat-06\",\n      \"name\": \"Clean wet moss or cotton cloth plug\",\n      \"desc\": \"Packed into the narrow bottom spout to support charcoal and sand without letting them spill into the clean cup.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Step 1: Set up a 3-stick tripod and mount the cone funnel\",\n      \"description\": \"1. **Assemble Tripod**: Lash three finger-thick straight branches together near the top and spread the legs to form a sturdy tripod.\\n2. **Suspend Cone**: Mount the rolled birch bark cone or hollow bamboo stalk vertically at the center of the tripod.\\n3. **Insert Base Plug**: Firmly pack clean, rinsed river moss or a cloth scrap into the narrow bottom spout. A loose plug will allow filter media to dump out.\",\n      \"actionNote\": \"> Plug Check: Ensure the plug is firmly wedged. A loose plug will blow out under water pressure, leaking black charcoal dust.\",\n      \"svgFileName\": \"pr01-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PURIFICATION STEP 1: TRIPOD FRAME\",\n        \"TRIPOD FRAME (3-POINT)\",\n        \"CONE FUNNEL (VESSEL)\",\n        \"MOSS PLUG (BASE)\",\n        \"[STEP 1] STABLE 3-POINT TRIPOD SETUP\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Step 2: Crush charcoal to pea size and pack an 8cm active bed\",\n      \"description\": \"1. **Crush & Grade**: Take cool, fully carbonized campfire charcoal and tap gently with a stone into **pea-sized chunks (5-8mm)**. Discard fine flour-like dust that would clog the water flow.\\n2. **Pack 8cm Bed**: Pour the charcoal over the base moss plug and tamp down gently with a stick to form a level bed **four finger widths deep (about 8cm)**.\",\n      \"actionNote\": \"> Grain Rule: Charcoal chunks must remain coarser than rice grains. Fine powdered dust clogs percolation.\",\n      \"svgFileName\": \"pr01-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // PURIFICATION STEP 2: CHARCOAL CORE\",\n        \"CHARCOAL CORE (ACTIVE)\",\n        \"PORE ABSORPTION (TOXINS)\",\n        \"THICKNESS: 8CM\",\n        \"[STEP 2] PACK 8CM OF PEA-SIZED CHARCOAL\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD SCIENCE\",\n        \"title\": \"Charcoal Adsorption Mechanics\",\n        \"text\": \"When wood is pyrolyzed in low-oxygen heat, millions of microscopic pores form. These micropores exert strong van der Waals forces, trapping dissolved organic toxins and chemical odors onto the carbon surface.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Step 3: Layer clean rinsed river sand to a flat 6cm barrier\",\n      \"description\": \"1. **Rinse River Sand**: Rinse fine river sand two to three times in water to flush out loose organic silt.\\n2. **Layer 6cm Depth**: Slowly pour clean sand over the charcoal bed to a depth of **three finger widths (about 6cm)**.\\n3. **Level Surface**: Gently pat the top surface flat with a smooth stone or your palm. A slanted bed causes water to bypass through the shallow side.\",\n      \"actionNote\": \"> Level Bed: Keep the sand surface perfectly horizontal to ensure uniform percolation across the entire filter column.\",\n      \"svgFileName\": \"pr01-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // PURIFICATION STEP 3: SAND LAYER\",\n        \"RIVER SAND (FINE)\",\n        \"PARTICLE FILTER (SILT)\",\n        \"THICKNESS: 6CM\",\n        \"[STEP 3] LOCK CHARCOAL AND TRAP SILT\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Step 4: Add 4cm pebbles, pour muddy water, and discard initial flush\",\n      \"description\": \"1. **Add 4cm Pebble Buffer**: Place thumbnail-sized gravel over the sand bed to **two finger widths (about 4cm)** and cover with a broad green leaf.\\n2. **Pour Turbid Water**: Slowly pour raw muddy water over the leaf. The pebbles and leaf buffer the inflow, preventing erosion holes in the sand.\\n3. **Discard Initial Flush**: The first **1-2 cups (approx. 300ml)** wash out residual charcoal dust and **must be discarded**.\\n4. **Collect Clean Water**: Once drips turn crystal clear, position a clean collection vessel beneath the spout.\",\n      \"actionNote\": \"> Flush Rule: Never drink the initial 1-2 cups. Let the column flush itself clean until transparent drips appear.\",\n      \"svgFileName\": \"pr01-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // PURIFICATION STEP 4: PEBBLE & FLUSH\",\n        \"PEBBLE LAYER (BUFFER)\",\n        \"FLUSH FIRST CUPS (DISCARD)\",\n        \"CLEAR DRIP (COLLECT)\",\n        \"[STEP 4] BUFFER WATER & DISCARD FLUSH\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Step 5: Boil filtered water for 3+ minutes to destroy all microbes\",\n      \"description\": \"1. **Heat in Boiler**: Transfer visually transparent filtered water into a clay pot, stone bowl, or bamboo boiler and place over campfire coals.\\n2. **Maintain Rolling Boil**: Once large rolling bubbles erupt vigorously across the entire surface, maintain a continuous boil for at least **3 full minutes (5 minutes at altitudes above 1,000m)**.\\n3. **Cool & Consume**: Allow the sterile water to cool before drinking.\",\n      \"actionNote\": \"> Compulsory Boiling: Clear water is NOT sterile water. Mechanical filtration followed by thermal boiling achieves 99.9% biological safety.\",\n      \"svgFileName\": \"pr01-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // PURIFICATION STEP 5: 100°C BOIL\",\n        \"BOILING 100°C (ROLLING)\",\n        \"TIME: 3+ MIN (TIMER)\",\n        \"PATHOGEN FREE (99.9%)\",\n        \"[STEP 5] ROLLING BOIL FOR 3+ MINUTES\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD SCIENCE\",\n        \"title\": \"Why Visually Clear Water Must Be Boiled\",\n        \"text\": \"Charcoal and sand remove suspended sediment and organic odors, but microscopic cysts (Giardia, Cryptosporidium) pass through primitive pore spaces. Sustained 100°C boiling denatures pathogen proteins, inactivating 99.9% of microbes.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Fatal Mistake: Drinking filtered clear water without thermal boiling\",\n    \"description\": \"Charcoal and sand filters remove particulate silt and odors, but microscopic parasites and viral pathogens remain active. Drinking unboiled clear water causes severe gastroenteritis within hours, leading to dangerous wilderness dehydration.\",\n    \"consequence\": \"Outcome: Severe waterborne gastrointestinal infection and lethal wilderness dehydration\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Drinking wild muddy water will cause lethal diarrhea within 3 days! Here is how to purify it without plastic!\",\n    \"body\": \"Lash a tripod, suspend a bark cone, and plug the base with moss. Layer 8cm of pea-sized charcoal, 6cm of river sand, and 4cm of pebbles. Pour muddy water in! Discard the first 2 cups of dusty wash water. Critical rule: Clear water is NOT safe water! You must boil it vigorously for 3+ minutes to destroy invisible pathogens!\",\n    \"outro\": \"Access full offline survival blueprints with zero cell data via the profile link.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr01-outcome.svg\",\n    \"title\": \"Completed Natural Charcoal & Sand Water Filter\",\n    \"description\": \"A field-tested primitive filtration column suspended on a timber tripod, layering charcoal, river sand, and pebbles to turn turbid wild water into crystal clear boilable drinking water.\"\n  },\n  \"createdAt\": \"2026-10-09T16:00:00.000Z\",\n  \"updatedAt\": \"2026-10-15T15:29:10+09:00\",\n  \"contentHash\": \"8e86ecfb1c03de78\"\n}","content/protocols/locales/01-water-purification.es.json":"{\n  \"protocolId\": \"PR-01\",\n  \"category\": \"WATER\",\n  \"title\": \"Cómo convertir agua turbia en agua limpia para beber (Filtro natural con carbón y arena)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[SUPERVIVENCIA VITAL]\",\n  \"summary\": \"Beber agua turbia no tratada en la naturaleza provoca cólicos severos, diarrea y deshidratación peligrosa. Al montar un trípode de ramas, suspender un cono de corteza y colocar carbón, arena y grava en secuencia, el agua turbia se filtra transparente. Hervir esta agua enérgica y continuamente durante 3+ minutos elimina las bacterias microscópicas, haciéndola segura para beber.\",\n  \"timeRequired\": \"25 min (15 min filtrado + 10 min hervido)\",\n  \"successRate\": \"99.9% (Al colocar en secuencia y hervir 3+ min)\",\n  \"difficulty\": \"Media (Construido únicamente con materiales naturales)\",\n  \"outputPerHour\": \"1.5 a 2.0 litros de agua limpia por hora\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Carbón vegetal de leña (Dos puñados, tamaño guisante)\",\n      \"desc\": \"Absorbe impurezas y malos olores. Triturar en trozos mayores que granos de arroz y del tamaño de un guisante (5-8 mm).\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Arena fina de río lavada (Dos puñados)\",\n      \"desc\": \"Filtra el polvo fino y partículas en suspensión. Lavar dos o tres veces con agua corriente para eliminar lodo antes de usar.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Piedritas redondas de río (Un puñado)\",\n      \"desc\": \"Piedras limpias del tamaño de una uña. Retienen restos gruesos y amortiguan el flujo de agua para no erosionar la arena.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Cono de corteza de abedul o tubo de bambú hueco (1 unidad)\",\n      \"desc\": \"Recipiente cilíndrico o cónico de 30-40 cm que se estrecha abajo. Sostiene las capas y canaliza el goteo.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"Tres ramas rectas del grosor de un dedo (50 cm de largo)\",\n      \"desc\": \"Atadas por la parte superior para formar un trípode estable. Sostienen el cono elevado para colocar un vaso debajo.\"\n    },\n    {\n      \"id\": \"mat-06\",\n      \"name\": \"Musgo limpio húmedo o trozo de tela para tapón\",\n      \"desc\": \"Compactado en la boquilla inferior para sostener el carbón y la arena sin que caigan al recipiente limpio.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Paso 1: Montar el trípode con 3 ramas y fijar el cono\",\n      \"description\": \"1. **Ensamblar Trípode**: Junte tres ramas rectas del grosor de un dedo, ate la parte superior con lianas o cuerda y abra las patas formando un soporte firme.\\n2. **Suspender Cono**: Monte el cono de corteza o el tubo de bambú en posición vertical en el centro del trípode.\\n3. **Insertar Tapón Inferior**: Empuje musgo limpio o un trozo de tela en la boquilla estrecha con el dedo. Un tapón suelto provocará la caída de los materiales filtrantes.\",\n      \"actionNote\": \"> Control del tapón: Si queda flojo, saldrá polvo negro de carbón. Asegúrese de que no se mueva al empujar.\",\n      \"svgFileName\": \"pr01-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PURIFICATION STEP 1: TRÍPODE Y TAPÓN\",\n        \"TRIPOD FRAME (TRÍPODE)\",\n        \"CONE FUNNEL (CONO)\",\n        \"MOSS PLUG (TAPÓN)\",\n        \"[PASO 1] MONTAJE DE SOPORTE DE 3 PUNTOS\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Paso 2: Triturar carbón al tamaño de guisante y llenar 8 cm abajo\",\n      \"description\": \"1. **Triturar y Seleccionar**: Tome carbón negro completamente frío de la fogata y golpéelo suavemente con una piedra en **trozos de tamaño guisante (5-8 mm)**. Deseche el polvo fino tipo harina que obstruiría el flujo.\\n2. **Empacar Lecho de 8 cm**: Vierta el carbón sobre el tapón de musgo y compáctelo suavemente con una vara formando un lecho nivelado de **cuatro dedos de altura (unos 8 cm)**.\",\n      \"actionNote\": \"> Regla de grano: Use trozos mayores que granos de arroz. El polvo fino bloquea el paso del agua.\",\n      \"svgFileName\": \"pr01-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // PURIFICATION STEP 2: LECHO DE CARBÓN\",\n        \"CHARCOAL CORE (ACTIVO)\",\n        \"PORE ABSORPTION (ABSORCIÓN)\",\n        \"THICKNESS: 8CM (GROSOR)\",\n        \"[PASO 2] EMPACAR 8CM DE CARBÓN TRITURADO\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD SCIENCE\",\n        \"title\": \"Mecanismo de adsorción del carbón\",\n        \"text\": \"Cuando la madera se carboniza a alta temperatura sin oxígeno, se generan millones de poros microscópicos. Estos microporos ejercen intensas fuerzas de van der Waals que atrapan toxinas orgánicas disueltas y malos olores en la superficie del carbón.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Paso 3: Colocar 6 cm de arena limpia sobre el carbón y nivelar\",\n      \"description\": \"1. **Lavar Arena**: Enjuague arena fina de río dos o tres veces con agua para eliminar partículas de lodo.\\n2. **Colocar Capa de 6 cm**: Vierta lentamente la arena limpia sobre el carbón hasta alcanzar **tres dedos de profundidad (unos 6 cm)**.\\n3. **Nivelar Superficie**: Alise suavemente la superficie superior con una piedra plana o la palma. Si la arena está inclinada, el agua se desviará por el lado menos profundo.\",\n      \"actionNote\": \"> Lecho horizontal: Mantenga la superficie de arena plana para garantizar una filtración uniforme en toda la columna.\",\n      \"svgFileName\": \"pr01-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // PURIFICATION STEP 3: CAPA DE ARENA\",\n        \"RIVER SAND (ARENA)\",\n        \"PARTICLE FILTER (FILTRO)\",\n        \"THICKNESS: 6CM (GROSOR)\",\n        \"[PASO 3] FIJAR CARBÓN Y ATRAPAR LIMO\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Paso 4: Poner 4 cm de grava, verter agua turbia y purgar primeras tazas\",\n      \"description\": \"1. **Colocar 4 cm de Grava**: Coloque piedritas sobre la arena hasta **dos dedos de altura (unos 4 cm)** y cubra con una hoja ancha.\\n2. **Verter Agua Turbia**: Vierta despacio el agua turbia sobre la hoja. La grava y la hoja amortiguan el flujo y previenen agujeros en la arena.\\n3. **Purgar Primeras Tazas**: Las primeras **1-2 tazas (unos 300 ml)** limpian los residuos de carbón y **deben desecharse**.\\n4. **Recoger Agua Clara**: Cuando las gotas caigan cristalinas y transparentes, coloque un recipiente limpio debajo.\",\n      \"actionNote\": \"> Regla de purga: Nunca beba las primeras 1-2 tazas. Deje que el filtro se autolimpie hasta que el goteo sea cristalino.\",\n      \"svgFileName\": \"pr01-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // PURIFICATION STEP 4: GRAVA Y PURGA\",\n        \"PEBBLE LAYER (GRAVA)\",\n        \"FLUSH FIRST CUPS (PURGA)\",\n        \"CLEAR DRIP (GOTEO)\",\n        \"[PASO 4] AMORTIGUAR Y PURGAR PRIMERAS TAZAS\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Paso 5: Hervir el agua limpia durante 3+ minutos continuos\",\n      \"description\": \"1. **Transferir al Recipiente**: Vierta el agua filtrada y transparente en una vasija de barro, piedra o bambú sobre las brasas de la fogata.\\n2. **Hervido Enérgico Continuo**: Cuando se formen burbujas grandes en toda la superficie, mantenga el hervor durante al menos **3 minutos completos (5 minutos a más de 1.000 m de altitud)**.\\n3. **Enfriar y Beber**: Deje enfriar el agua antes de beberla con seguridad.\",\n      \"actionNote\": \"> Hervido obligatorio: El agua transparente NO es agua estéril. La filtración física seguida de ebullición térmica garantiza un 99.9% de seguridad biológica.\",\n      \"svgFileName\": \"pr01-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // PURIFICATION STEP 5: HERVIDO A 100°C\",\n        \"BOILING 100°C (HERVOR)\",\n        \"TIME: 3+ MIN (MINUTOS)\",\n        \"PATHOGEN FREE (99.9%)\",\n        \"[PASO 5] HERVIR CON FUERZA POR 3+ MINUTOS\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD SCIENCE\",\n        \"title\": \"Por qué el agua transparente debe hervirse\",\n        \"text\": \"Los filtros de carbón y arena eliminan sedimentos y olores, pero los quistes microscópicos (Giardia, Cryptosporidium) y virus atraviesan los poros. La ebullición continua a 100°C desnaturaliza las proteínas de los patógenos, inactivando el 99.9% de los microorganismos.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Error fatal: Beber el agua filtrada transparente sin hervirla térmicamente\",\n    \"description\": \"El carbón y la arena solo retienen el lodo visible y el mal olor. Los parásitos y bacterias microscópicas siguen vivos en el agua. Aunque parezca limpia y fría, beberla sin hervir provoca gastroenteritis severa en pocas horas, causando deshidratación grave en la naturaleza.\",\n    \"consequence\": \"Resultado: Infección gastrointestinal severa y deshidratación letal en supervivencia\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"¡Beber agua con lodo en la naturaleza causará diarrea letal en 3 días! ¡Mira cómo purificarla sin plástico!\",\n    \"body\": \"Monta un trípode, cuelga un cono y tapa la base con musgo. Coloca 8 cm de carbón partido, 6 cm de arena limpia y 4 cm de piedritas. ¡Vierte el agua turbia! Tira las 2 primeras tazas de lavado con polvo de carbón. Regla crítica: ¡Agua transparente NO significa agua segura! Debes hervirla enérgicamente durante 3+ minutos para destruir microbios invisibles.\",\n    \"outro\": \"Consigue los manuales de supervivencia sin internet en el enlace de mi perfil.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr01-outcome.svg\",\n    \"title\": \"Filtro natural de carbón y arena terminado\",\n    \"description\": \"Columna de filtración rústica suspendida en un trípode de ramas con capas de carbón, arena limpia, piedritas y tapón de musgo que convierten agua turbia en agua cristalina apta para hervir y beber.\"\n  },\n  \"createdAt\": \"2026-10-09T16:00:00.000Z\",\n  \"updatedAt\": \"2026-10-15T15:29:10+09:00\",\n  \"contentHash\": \"8e86ecfb1c03de78\"\n}","content/protocols/locales/01-water-purification.ja.json":"{\n  \"protocolId\": \"PR-01\",\n  \"category\": \"WATER\",\n  \"title\": \"泥水をきれいな飲み水に変える方法（炭と砂で作る自然の浄水器）\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[必須サバイバル]\",\n  \"summary\": \"野外で泥水をそのまま飲むと、激しい腹痛と下痢で脱水症状に陥ります。木の枝3本で三脚を立て、コーン状の筒に炭、砂、小石を順に重ねることで、濁った泥水を透明にろ過できます。ろ過した水をたき火で大きな泡が立つまで3分以上沸とうさせれば、目に見えない細菌まで完全に死滅し、安全に飲むことができます。\",\n  \"timeRequired\": \"25分（ろ過 15分 + 沸とう 10分）\",\n  \"successRate\": \"99.9%（順番に重ねてろ過し、3分以上沸とうさせた場合）\",\n  \"difficulty\": \"普通（自然物だけで誰でも製作可能）\",\n  \"outputPerHour\": \"1時間にきれいな水 1.5〜2リットル\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"木炭（えんどう豆サイズ、両手2杯）\",\n      \"desc\": \"不純物と悪臭を吸着してろ過します。米粒より大きく、えんどう豆サイズ（5〜8mm）に砕いて準備します。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"洗浄した細かい川砂（両手2杯）\",\n      \"desc\": \"微細な泥粒子を遮断します。川の水で2〜3回すすいで泥を洗い流した砂を使用します。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"小さな丸い小石（片手1杯）\",\n      \"desc\": \"爪サイズの小石です。大きなゴミを止め、水を注ぐ際に砂が掘れないよう水圧を分散します。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"白樺樹皮のコーンまたは竹筒 1本\",\n      \"desc\": \"長さ30〜40cmの下部が狭まる筒型容器です。ろ過材を保持し、水滴を1か所に集めます。\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"指の太さの木の枝 3本（長さ50cm）\",\n      \"desc\": \"上部を縛って地面に立てる三脚スタンドです。コーンの下に水受けの器を置けるよう高く支えます。\"\n    },\n    {\n      \"id\": \"mat-06\",\n      \"name\": \"清潔な水ゴケまたは布のきれはし\",\n      \"desc\": \"一番下の出口を塞ぎ、炭や砂が下にこぼれ落ちないように支えるフィルター栓です。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"ステップ1: 枝3本で三脚を組み立ててコーンを固定する\",\n      \"description\": \"1. **三脚の組み立て**: 指の太さの枝3本の上部をつる草やひもで縛り、地面に安定した三脚を立てます。\\n2. **コーンの垂直固定**: 白樺樹皮のコーンまたは竹筒を三脚の中心にまっすぐ固定します。\\n3. **底栓の密着挿入**: 水が落ちる最下部の穴に、水ゴケや布きれを指で強く押し込みます。栓が緩いとろ過材が抜け落ちます。\",\n      \"actionNote\": \"> 栓の確認: 栓が緩いと炭粉が漏れ出します。指で押しても抜けないよう固く詰めてください。\",\n      \"svgFileName\": \"pr01-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PURIFICATION STEP 1: フレーム設置・下部栓\",\n        \"木の枝3本の三脚スタンド\",\n        \"コーン型白樺樹皮ろ過筒\",\n        \"底穴をしっかり塞ぐ水ゴケ栓\",\n        \"[ステップ1] 倒れない三脚＆丈夫な底栓の設置\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"ステップ2: 炭を豆粒大に砕いて最下層に8cm充填する\",\n      \"description\": \"1. **炭の破砕と選別**: 完全に冷えた木炭を石で叩き、**えんどう豆サイズ（5〜8mm）**に砕きます。小麦粉のような微粉末は水詰まりの原因になるため取り除きます。\\n2. **炭層8cmの充填**: 底栓の上に炭を入れ、小枝の先で軽く押し込みながら**指4本分の高さ（約8cm）**まで平らに詰めます。\",\n      \"actionNote\": \"> 粒度規格: 米粒より大きく豆粒大の塊を使用します。微粉末はろ過速度を低下させます。\",\n      \"svgFileName\": \"pr01-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // PURIFICATION STEP 2: 炭による吸着層\",\n        \"豆粒サイズに砕いた黒炭の粒\",\n        \"臭いと毒素を吸着する炭の微細孔\",\n        \"指4本分の高さ（8cm）まで充填\",\n        \"[ステップ2] 豆粒炭を8cm詰めて軽くならす\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD SCIENCE\",\n        \"title\": \"木炭が水中の汚染物質を吸着する原理\",\n        \"text\": \"木材が無酸素状態で高温加熱されると、炭の内部に無数の微細な細孔が形成されます。この細孔表面にファンデルワールス力が働き、水中に溶けた悪臭分子や有機毒素を物理的に強力に捕らえます。\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"ステップ3: 洗浄した砂を炭の上に6cm積層して水平にならす\",\n      \"description\": \"1. **川砂の洗浄**: 川辺の細かい砂を水で2〜3回すすぎ、混ざっている泥を洗い流します。\\n2. **砂層6cmの積層**: 洗浄した砂を炭の上に静かに注ぎ、**指3本分の高さ（約6cm）**まで重ねます。\\n3. **表面の水平整地**: 平らな石や手のひらで表面を水平にならします。砂が傾いていると水が薄い側に偏流し、ろ過効率が低下します。\",\n      \"actionNote\": \"> 水平維持: 砂の上面を平らに保つことで、ろ過層全体に水が均一に浸透します。\",\n      \"svgFileName\": \"pr01-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // PURIFICATION STEP 3: 微細砂層の積層\",\n        \"水で洗ったきれいな川砂\",\n        \"細かい泥やゴミをしっかりブロック\",\n        \"指3本分の高さ（6cm）まで充填\",\n        \"[ステップ3] 炭の上に砂を6cm平らに敷く\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"ステップ4: 小石を4cm敷き泥水を注ぐ（最初の1〜2杯は廃棄）\",\n      \"description\": \"1. **小石緩衝層4cmの積層**: 砂の上に爪サイズの小石を**指2本分の高さ（約4cm）**敷き、幅の広い葉を1枚かぶせます。\\n2. **泥水の注入**: 葉の上から泥水をゆっくり注ぎます。小石と葉が水圧を分散し、砂の侵食を防ぎます。\\n3. **初期洗浄水の廃棄**: 下部から垂れてくる**最初の1〜2杯（約300ml）**は内部の炭粉を洗い流す水のため、**必ず廃棄します**。\\n4. **清澄水の採取**: 水滴が水晶のように透きとおって落ち始めたら、清潔な器で受けます。\",\n      \"actionNote\": \"> 初水廃棄の鉄則: 最初の1〜2杯はフィルター内部を清掃する水です。透明な水が出るまで飲用しないでください。\",\n      \"svgFileName\": \"pr01-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // PURIFICATION STEP 4: 小石層と初期洗浄\",\n        \"水圧を分散する小石層（4cm）\",\n        \"炭粉を洗い流す初水（1〜2杯廃棄）\",\n        \"1秒に1滴ずつ落ちる澄んだ水滴\",\n        \"[ステップ4] 小石で砂を守り初水は必ず捨てる\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"ステップ5: ろ過した透明な水を火にかけ3分以上煮沸する\",\n      \"description\": \"1. **加熱容器の設置**: 透明にろ過された水を石器、土器、または竹筒に入れ、たき火の炭火上に置きます。\\n2. **3分以上の煮沸維持**: 水面全体から大きな泡が湧き上がって沸とうし始めたら、最低**3分以上（標高1,000m以上の高地では5分以上）**加熱を継続します。\\n3. **放冷後飲用**: 十分に冷ましてから安全に飲用します。\",\n      \"actionNote\": \"> 必須加熱: 透明に見えても煮沸せずに飲んではいけません。物理ろ過後に加熱することで病原体が死滅します。\",\n      \"svgFileName\": \"pr01-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // PURIFICATION STEP 5: 100℃煮沸殺菌\",\n        \"大きな泡がボコボコ立つ沸とう水\",\n        \"最低3分以上しっかり加熱（山は5分）\",\n        \"見えない悪い細菌を99.9%完全死滅\",\n        \"[ステップ5] 透明な水も必ず3分以上沸とうさせる\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD SCIENCE\",\n        \"title\": \"透明な水でも煮沸が必須な科学的理由\",\n        \"text\": \"炭と砂のフィルターは目に見える泥や臭気を除去しますが、微小な寄生虫のシストやウイルスは通過します。100℃で3分間煮沸することで病原体のタンパク質が変性し、99.9%不活性化されます。\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命的過失: ろ過した透明な水を煮沸せずにそのまま飲む行為\",\n    \"description\": \"炭と砂は目に見える泥や臭気を取り除くだけです。微細な病原菌や寄生虫は水中に生存しています。どれほど透明に見えても煮沸せずに飲むと、数時間後に激しい腹痛と下痢で急激な脱水症状に陥ります。\",\n    \"consequence\": \"結果: 激しい下痢と腹痛で急激な脱水症状を起こし生命の危険\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"野外で泥水をそのまま飲むと3日で倒れます！自然の素材だけで作る浄水器の作り方！\",\n    \"body\": \"枝3本で三脚を立ててコーンをつるし、底をコケで塞ぎます。豆粒大の炭8cm、きれいな砂6cm、小石4cmを順に重ねて泥水を注ぐだけ！最初の2杯は炭粉の洗浄水なので捨て、透明な水だけを集めます。一番大事な規則！透明でも煮沸しなければ細菌で倒れます。必ず火にかけて3分以上沸とうさせてください！\",\n    \"outro\": \"電波圏外でも閲覧できるオフライン設計図はプロフィールのリンクから確認できます。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr01-outcome.svg\",\n    \"title\": \"炭・砂3重ろ過自然浄水器の完成形態\",\n    \"description\": \"木の枝の三脚につるした容器内に木炭、川砂、小石、繊維栓が層状に配置され、上部の泥水が下部出口から澄んだ透明な水へとろ過される構造です。\"\n  },\n  \"createdAt\": \"2026-10-09T16:00:00.000Z\",\n  \"updatedAt\": \"2026-10-15T15:29:10+09:00\",\n  \"contentHash\": \"8e86ecfb1c03de78\"\n}","content/protocols/locales/01-water-purification.pt.json":"{\n  \"protocolId\": \"PR-01\",\n  \"category\": \"WATER\",\n  \"title\": \"Como transformar água barrenta em água limpa para beber (Filtro natural com carvão e areia)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[SOBREVIVÊNCIA VITAL]\",\n  \"summary\": \"Beber água barrenta não tratada na natureza provoca fortes cólicas, diarreia e desidratação perigosa. Ao montar um tripé de galhos, suspender um cone de casca e dispor carvão, areia e pedregulhos em sequência, a água turva é filtrada até ficar transparente. Ferver essa água vigorosamente por 3+ minutos destrói bactérias microscópicas, tornando-a segura para beber.\",\n  \"timeRequired\": \"25 min (15 min filtragem + 10 min fervura)\",\n  \"successRate\": \"99.9% (Ao dispor em sequência e ferver por 3+ min)\",\n  \"difficulty\": \"Médio (Construído puramente com materiais naturais)\",\n  \"outputPerHour\": \"1.5 a 2.0 litros de água limpa por hora\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Carvão vegetal de fogueira (Dois punhados, tamanho de ervilha)\",\n      \"desc\": \"Adsorve impurezas dissolvidas e odores. Quebre em pedaços maiores que grãos de arroz e do tamanho de ervilhas (5 a 8 mm).\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Areia fina de rio lavada (Dois punhados)\",\n      \"desc\": \"Filtra poeira fina e partículas em suspensão. Lave duas ou três vezes em água corrente para remover lodo antes de usar.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Pedregulhos redondos de rio (Um punhado)\",\n      \"desc\": \"Pedras limpas do tamanho de uma unha. Retêm detritos grossos e amortecem o fluxo de água para não erodir o leito de areia.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Cone de casca de bétula ou tubo oco de bambu (1 unidade)\",\n      \"desc\": \"Recipiente de 30 a 40 cm que afunila embaixo. Sustenta as camadas de filtragem e canaliza o gotejamento.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"Três galhos retos da grossura de um dedo (50 cm de comprimento)\",\n      \"desc\": \"Amarrados em cima para formar um tripé estável. Sustentam o cone alto o suficiente para posicionar um copo embaixo.\"\n    },\n    {\n      \"id\": \"mat-06\",\n      \"name\": \"Musgo limpo e úmido ou pedaço de pano\",\n      \"desc\": \"Compactado no bico inferior para sustentar o carvão e a areia sem que caiam no recipiente de água limpa.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Passo 1: Montar o tripé com 3 galhos e fixar o cone\",\n      \"description\": \"1. **Montar Tripé**: Amarre o topo de três galhos retos da grossura de um dedo e abra as pernas para firmar um tripé resistente no chão.\\n2. **Suspender Cone**: Prenda o cone de casca ou o tubo de bambu na vertical no centro do tripé.\\n3. **Inserir Tampão Inferior**: Empurre musgo lavado ou um pedaço de pano no bico estreito com o dedo. Um tampão frouxo fará os materiais caírem.\",\n      \"actionNote\": \"> Verificação do tampão: Se ficar frouxo, sairá pó preto de carvão. Aperte bem para que não saia ao empurrar.\",\n      \"svgFileName\": \"pr01-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PURIFICATION STEP 1: TRIPÉ E PLUGUE\",\n        \"TRIPOD FRAME (TRIPÉ)\",\n        \"CONE FUNNEL (CONE)\",\n        \"MOSS PLUG (MUSGO)\",\n        \"[PASSO 1] AMARRAÇÃO DE TRIPÉ DE 3 PONTOS\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Passo 2: Quebrar o carvão no tamanho de ervilha e encher 8 cm no fundo\",\n      \"description\": \"1. **Triturar e Peneirar**: Pegue carvão totalmente frio da fogueira e bata de leve com uma pedra até obter **pedaços do tamanho de ervilha (5 a 8 mm)**. Descarte o pó fino que entupiria a passagem da água.\\n2. **Preencher Leito de 8 cm**: Despeje o carvão sobre o musgo e compacte levemente com uma vara até atingir **quatro dedos de altura (cerca de 8 cm)**.\",\n      \"actionNote\": \"> Regra de granulação: Use pedaços maiores que grãos de arroz. O pó fino bloqueia a velocidade de filtragem.\",\n      \"svgFileName\": \"pr01-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // PURIFICATION STEP 2: LEITO DE CARVÃO\",\n        \"CHARCOAL CORE (CARVÃO)\",\n        \"PORE ABSORPTION (ABSORÇÃO)\",\n        \"THICKNESS: 8CM (ALTURA)\",\n        \"[PASSO 2] EMPACOTAR 8CM DE CARVÃO EM GRÃOS\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD SCIENCE\",\n        \"title\": \"Mecanismo de adsorção do carvão\",\n        \"text\": \"Quando a madeira é queimada em alta temperatura sem oxigênio, milhões de microporos são formados no carvão. Esses microporos exercem forças de van der Waals que retêm toxinas orgânicas e maus odores na superfície do carbono.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Passo 3: Colocar 6 cm de areia limpa sobre o carvão e nivelar\",\n      \"description\": \"1. **Lavar Areia**: Enxágue a areia fina de rio duas a três vezes para retirar o lodo solto.\\n2. **Colocar Camada de 6 cm**: Despeje devagar a areia lavada sobre o carvão até cobrir **três dedos de altura (cerca de 6 cm)**.\\n3. **Nivelar Superfície**: Alise a superfície superior com uma pedra chata ou a palma da mão. Um leito inclinado faz a água escorrer pelo lado raso sem filtrar.\",\n      \"actionNote\": \"> Manter nivelado: Mantenha a superfície da areia plana para garantir percolação uniforme em toda a coluna.\",\n      \"svgFileName\": \"pr01-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // PURIFICATION STEP 3: CAMADA DE AREIA\",\n        \"RIVER SAND (AREIA)\",\n        \"PARTICLE FILTER (FILTRAGEM)\",\n        \"THICKNESS: 6CM (ALTURA)\",\n        \"[PASSO 3] FIXAR CARVÃO E RETER LIMO\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Passo 4: Pôr 4 cm de pedregulhos, despejar água e descartar primeira água\",\n      \"description\": \"1. **Pôr Camada de Pedregulhos**: Coloque pedrinhas sobre a areia até **dois dedos de altura (cerca de 4 cm)** e cubra com uma folha larga.\\n2. **Despejar Água Turva**: Verta aos poucos a água barrenta sobre a folha. As pedras e a folha amortecem o impacto e evitam crateras na areia.\\n3. **Descartar Primeira Água**: Os primeiros **1 a 2 copos (cerca de 300 ml)** lavam o pó residual de carvão e **devem ser descartados**.\\n4. **Recolher Água Limpa**: Quando os pingos caírem cristalinos, posicione um recipiente limpo embaixo.\",\n      \"actionNote\": \"> Regra do descarte inicial: Nunca beba os primeiros 1 a 2 copos. Deixe o filtro se autolimpar até gotejar água cristalina.\",\n      \"svgFileName\": \"pr01-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // PURIFICATION STEP 4: SEIXOS E PURGA\",\n        \"PEBBLE LAYER (SEIXOS)\",\n        \"FLUSH FIRST CUPS (PURGA)\",\n        \"CLEAR DRIP (PINGOS)\",\n        \"[PASSO 4] AMORTECER E DESCARTAR ÁGUA INICIAL\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Passo 5: Ferver a água limpa por mais de 3 minutos contínuos\",\n      \"description\": \"1. **Transferir para Fervedor**: Coloque a água filtrada e transparente em um vaso de barro, pedra ou bambu sobre as brasas da fogueira.\\n2. **Manter Fervura Intensa**: Quando bolhas grandes subirem por toda a superfície, mantenha a fervura por pelo menos **3 minutos completos (5 minutos em altitudes acima de 1.000 m)**.\\n3. **Resfriar e Beber**: Espere a água esfriar antes de bebê-la com total segurança.\",\n      \"actionNote\": \"> Fervura obrigatória: Água transparente NÃO é água estéril. A filtragem física somada à fervura térmica garante 99.9% de segurança biológica.\",\n      \"svgFileName\": \"pr01-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // PURIFICATION STEP 5: FERVURA A 100°C\",\n        \"BOILING 100°C (FERVURA)\",\n        \"TIME: 3+ MIN (MINUTOS)\",\n        \"PATHOGEN FREE (ESTERILIZADO)\",\n        \"[PASSO 5] FERVER COM FORÇA POR 3+ MINUTOS\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD SCIENCE\",\n        \"title\": \"Por que água transparente deve ser fervida\",\n        \"text\": \"Filtros de carvão e areia retêm sedimentos e odores, mas cistos microscópicos (Giardia, Cryptosporidium) e vírus passam pelos poros. A fervura constante a 100°C desnatura as proteínas dos patógenos, inativando 99.9% dos micróbios.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Erro fatal: Beber a água filtrada transparente sem fervura térmica\",\n    \"description\": \"O carvão e a areia retêm apenas o barro visível e o cheiro ruim. Parasitas microscópicos e vírus continuam vivos na água. Beber água transparente sem ferver causa gastroenterite severa em poucas horas, levando à desidratação perigosa na selva.\",\n    \"consequence\": \"Resultado: Infecção gastrointestinal grave e desidratação letal na selva\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Beber água com barro na floresta causa diarreia letal em 3 dias! Veja como purificá-la sem plástico!\",\n    \"body\": \"Amarre um tripé, pendure um cone e feche a base com musgo. Coloque 8 cm de carvão em grãos, 6 cm de areia de rio e 4 cm de pedregulhos. Despeje a água barrenta! Descarte os 2 primeiros copos com pó de carvão. Regra crucial: Água transparente NÃO é água segura! Ferva intensamente por 3+ minutos para destruir micróbios invisíveis.\",\n    \"outro\": \"Acesse os manuais de sobrevivência sem internet no link do meu perfil.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr01-outcome.svg\",\n    \"title\": \"Filtro natural de carvão e areia concluído\",\n    \"description\": \"Coluna de filtragem rústica montada em um tripé de galhos com camadas de carvão, areia de rio, pedregulhos e tampão de musgo que transformam água barrenta em água cristalina pronta para ferver e beber.\"\n  },\n  \"createdAt\": \"2026-10-09T16:00:00.000Z\",\n  \"updatedAt\": \"2026-10-15T15:29:10+09:00\",\n  \"contentHash\": \"8e86ecfb1c03de78\"\n}","content/protocols/locales/01-water-purification.zh-TW.json":"{\n  \"protocolId\": \"PR-01\",\n  \"category\": \"WATER\",\n  \"title\": \"如何將泥水變成乾淨的飲用水（用木炭與細沙自製天然淨水器）\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[必備求生]\",\n  \"summary\": \"在野外未經處理直接飲用泥水，會引發劇烈腹痛、腹瀉並導致危險的脫水。用三根樹枝立成三腳架，懸掛樹皮錐筒並依序鋪設木炭、細沙與礫石，可將渾濁泥水過濾為透明清澈水。接著將過濾水劇烈滾煮3分鐘以上，可徹底消滅微小細菌，確保飲用安全。\",\n  \"timeRequired\": \"25分鐘（過濾15分鐘 + 滾煮10分鐘）\",\n  \"successRate\": \"99.9%（依序分層過濾並滾煮3分鐘以上）\",\n  \"difficulty\": \"普通（僅用自然材料即可完成）\",\n  \"outputPerHour\": \"每小時可產出 1.5 至 2.0 公升乾淨水\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"闊葉木木炭（雙手捧兩把，豌豆大小）\",\n      \"desc\": \"吸附溶解雜質與異味。敲成大於米粒、如豌豆大小（5~8毫米）的顆粒備用。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"洗淨的細河沙（雙手捧兩把）\",\n      \"desc\": \"攔截微細泥塵與懸浮微粒。使用前在流動溪水中淘洗兩至三次以去除泥漿。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"圓形小礫石（單手抓一把）\",\n      \"desc\": \"如指甲大小的乾淨小石子。攔截粗雜質並緩衝注入水流，避免細沙層凹陷沖散。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"樺樹皮圓錐筒或中空竹筒 1 支\",\n      \"desc\": \"長約30~40公分、下方漸窄的漏斗容器。用於固定過濾層並集中滴水。\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"約手指粗細的筆直樹枝 3 根（長50公分）\",\n      \"desc\": \"頂端綁牢立於地面的穩定三腳架。將漏斗架高以利於下方放置接水容器。\"\n    },\n    {\n      \"id\": \"mat-06\",\n      \"name\": \"乾淨濕水苔或布塊濾塞\",\n      \"desc\": \"緊緊塞在最下方窄孔，支撐上方木炭與細沙而不掉落至乾淨容器中。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"步驟1：架設3根樹枝三腳架並安裝漏斗錐筒\",\n      \"description\": \"1. **組裝三腳架**：將三根手指粗細的筆直樹枝頂端用藤蔓綁緊，撐開立成穩固的三腳架。\\n2. **垂直懸掛漏斗**：將樺樹皮圓錐筒或中空竹筒筆直固定在三腳架中央。\\n3. **填入底部濾塞**：用手指將乾淨濕水苔或布塊緊塞入底部窄孔。濾塞若鬆動會導致過濾材料漏出。\",\n      \"actionNote\": \"> 濾塞檢驗：若濾塞過鬆，黑色炭粉會滲出。請確保用手指推擠時不會鬆脫。\",\n      \"svgFileName\": \"pr01-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PURIFICATION STEP 1: 架台與底塞\",\n        \"TRIPOD FRAME (三腳架)\",\n        \"CONE FUNNEL (過濾管)\",\n        \"MOSS PLUG (苔蘚塞)\",\n        \"[第1階段核心] 穩固三點支撐架結合\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"步驟2：將木炭搗成豌豆大小並於底層填入8公分厚\",\n      \"description\": \"1. **搗碎與篩選**：將完全冷卻的黑木炭用石塊輕敲成**豌豆大小（5~8毫米）**。篩除如麵粉般的極細微粉，避免阻塞水流。\\n2. **鋪設8公分炭層**：將木炭倒在水苔塞上方，用小木棍輕壓鋪平成**四個手指寬的高度（約8公分）**。\",\n      \"actionNote\": \"> 顆粒標準：炭粒須大於米粒、約豌豆大小。微細塵粉會嚴重降低過濾流速。\",\n      \"svgFileName\": \"pr01-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // PURIFICATION STEP 2: 木炭吸附層\",\n        \"CHARCOAL CORE (活性炭)\",\n        \"PORE ABSORPTION (毒素吸附)\",\n        \"THICKNESS: 8CM (厚度)\",\n        \"[第2階段核心] 搗碎至豌豆大並填充8cm\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD SCIENCE\",\n        \"title\": \"木炭吸附水中污染物的科學原理\",\n        \"text\": \"木材在缺氧高溫下炭化時，內部會形成數以億計的微米級細孔。這些微孔產生強大的凡德瓦力，能將溶解在水中的有機毒素與異味分子牢牢物理吸附在表面。\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"步驟3：將洗淨細沙平鋪於木炭上方達6公分厚度\",\n      \"description\": \"1. **淘洗河沙**：將細河沙在清水中沖洗兩至三次，漂去游離泥塵。\\n2. **鋪設6公分沙層**：將洗淨細沙緩緩倒在木炭上方，厚度達**三個手指寬（約6公分）**。\\n3. **平整表面**：用扁平石塊或手掌將沙層表面拍平。若沙層傾斜，水流會偏向較薄一側流失而降低淨化效果。\",\n      \"actionNote\": \"> 保持水平：沙層表面必須平整，才能確保水流均勻滲透整個過濾柱。\",\n      \"svgFileName\": \"pr01-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // PURIFICATION STEP 3: 細沙層鋪設\",\n        \"RIVER SAND (細沙)\",\n        \"PARTICLE FILTER (泥屑攔截)\",\n        \"THICKNESS: 6CM (厚度)\",\n        \"[第3階段核心] 鋪設平整並攔截細泥\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"步驟4：鋪上4公分礫石，倒入泥水並倒掉初洗水\",\n      \"description\": \"1. **鋪設4公分礫石層**：在細沙上方放入指甲大小的小石子達**兩個手指寬（約4公分）**，表面覆蓋一片寬大樹葉。\\n2. **注入泥水**：將濁泥水緩緩倒在樹葉上。礫石與樹葉能分散水流衝擊，防止沙層被沖凹。\\n3. **倒掉初洗水**：最先滴出的**前1至2杯水（約300毫升）**含有沖洗出的殘餘炭粉，**必須倒掉廢棄**。\\n4. **承接清澈水**：當水滴變得透亮如水晶時，在下方放置乾淨容器承接。\",\n      \"actionNote\": \"> 初水廢棄守則：前1~2杯水是用於清潔濾芯內部的。在水質徹底清澈之前切勿飲用。\",\n      \"svgFileName\": \"pr01-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // PURIFICATION STEP 4: 礫石與清洗\",\n        \"PEBBLE LAYER (石子緩衝)\",\n        \"FLUSH FIRST CUPS (倒掉初水)\",\n        \"CLEAR DRIP (清澈水滴)\",\n        \"[第4階段核心] 緩衝水流並倒掉初水\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"步驟5：將過濾出的清澈水持續劇烈滾煮3分鐘以上\",\n      \"description\": \"1. **置入加熱容器**：將透明的過濾水倒入石碗、陶罐或竹筒中，放在營火炭火上方。\\n2. **維持劇烈滾煮**：當整個水面翻騰冒出大氣泡時，持續維持滾煮至少**3分鐘以上（海拔1,000公尺以上山區為5分鐘以上）**。\\n3. **冷卻後飲用**：充分放涼後即可安全飲用。\",\n      \"actionNote\": \"> 強制滾煮：看起來清澈的水不等於無菌水。物理過濾配合高溫滾煮才能達成99.9%的生物安全。\",\n      \"svgFileName\": \"pr01-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // PURIFICATION STEP 5: 100°C 沸水殺菌\",\n        \"BOILING 100°C (劇烈滾煮)\",\n        \"TIME: 3+ MIN (持續3分鐘)\",\n        \"PATHOGEN FREE (消滅壞菌)\",\n        \"[第5階段核心] 大火劇烈滾煮3分鐘以上\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD SCIENCE\",\n        \"title\": \"清澈水為何仍必須高溫滾煮的科學依據\",\n        \"text\": \"木炭與細沙只能去除泥沙顆粒與異味，微小的寄生蟲囊胞（賈第蟲、隱孢子蟲）與病毒仍會穿透孔隙。在100℃下持續加熱3分鐘可使病原體蛋白質變性，令99.9%的微生物徹底失去活性。\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命錯誤：將過濾出的透明水未經加熱直接飲用\",\n    \"description\": \"木炭和細沙僅能攔截可見泥塵與異味。微小寄生蟲與細菌依然在水中存活。即使水質冰涼清澈，未經加熱飲用將在數小時內誘發急性腸胃炎與痢疾，在野外迅速陷入危險的脫水狀態。\",\n    \"consequence\": \"後果：引發急性腸胃感染與嚴重腹瀉，在野外陷入致命脫水危險\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"在野外喝泥水三天內會脫水倒下！教你不用塑膠自製天然淨水器！\",\n    \"body\": \"立起三腳架，掛上漏斗並在底層塞入水苔。鋪入8公分碎木炭、6公分河沙與4公分礫石。倒進泥水！倒掉前2杯洗出炭粉的水。關鍵守則：清澈不代表安全！務必放在火上大火劇烈滾煮3分鐘以上消滅微小病原體！\",\n    \"outro\": \"無網路也能查看的離線求生手冊，請點擊個人簡介連結。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr01-outcome.svg\",\n    \"title\": \"炭砂三重過濾天然淨水器完成圖\",\n    \"description\": \"懸掛在樹枝三腳架上的天然過濾器，內部由木炭、細河沙、礫石及水苔塞層層堆疊，將上方濁黃的泥水轉化為底部滴落的透亮可飲用水。\"\n  },\n  \"createdAt\": \"2026-10-09T16:00:00.000Z\",\n  \"updatedAt\": \"2026-10-15T15:29:10+09:00\",\n  \"contentHash\": \"8e86ecfb1c03de78\"\n}","content/protocols/locales/02-friction-fire.de.json":"{\n  \"protocolId\": \"PR-02\",\n  \"category\": \"FIRE\",\n  \"title\": \"Feuer machen durch Holzreibung (Bogenbohrer-Methode)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[GEFAHRENSTUFE: KRITISCH]\",\n  \"summary\": \"Eine grundlegende Überlebenstechnik, um mit trockenen Ästen und einer Schnur ohne Streichhölzer oder Feuerzeug Feuer zu machen. Durch das Vor- und Zurückbewegen des Bogens dreht sich die Spindel rasend schnell und erzeugt durch Reibung 400°C heißen glimmenden Kohlestaub. Wird diese Glut in ein trockenes Grasnest gebettet und sanft angeblasen, entflammt ein 600°C heißes offenes Feuer.\",\n  \"timeRequired\": \"20 MINUTEN\",\n  \"successRate\": \"85% (Trockenholz)\",\n  \"difficulty\": \"Stufe 2 (Fortgeschrittene Technik)\",\n  \"outputPerHour\": \"1 Feuer / 20 Min\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Bogenstab und reißfeste Natursehne\",\n      \"desc\": \"Ein 60~70cm langer, leicht gebogener stabiler Ast mit einer Schnur aus Baumrinde oder Tierhaut, um die Spindel kraftvoll anzutreiben.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Mittlere Drehspindel (Bohrstab)\",\n      \"desc\": \"Ein daumendicker (ca. 2cm Durchmesser), 25cm langer, gerader und knochentrockener Ast, unten wie ein Bleistift zugespitzt.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Bodenfeuerbrett und trockenes Grasnest\",\n      \"desc\": \"Ein 1.5~2cm dickes, flaches und trockenes Holzbrett sowie ein vogelnestartiges Bündel aus trockenem Gras und Schilfwolle.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Schritt 1: Eine 45-Grad-V-Kerbe in das Feuerbrett schnitzen\",\n      \"description\": \"1. **Ansatzloch eindrehen**: Drücken und drehen Sie die Spindelspitze **1~1.5cm vom Brettrand** entfernt ein, um eine flache Mulde einzubrennen.\\n2. **45-Grad-V-Kerbe einschneiden**: Schneiden Sie mit einem Steinmesser eine pizzastückförmige **45-Grad-V-Kerbe** vom Rand bis exakt zur Mitte der Mulde.\\n3. **Auffangblatt unterlegen**: Legen Sie ein breites, trockenes Blatt direkt unter die Kerbe, um den herabfallenden heißen Kohlestaub sauber aufzufangen.\",\n      \"actionNote\": \"> Kerbengenauigkeit: Die Spitze der V-Kerbe muss exakt die Mitte der Mulde treffen. Weicht sie ab, kann das heiße Pulver nicht austreten, staut sich um den Stab und bildet keine Glut.\",\n      \"svgFileName\": \"02-step-01.svg\",\n      \"svgLabels\": [\n        \"GLUTAUFFANGBLATT [RINDENBASIS]\",\n        \"45° V-KERBE (Spitze am Achszentrum)\",\n        \"Ø 20mm SPINDELACHSE\",\n        \"DICKE: 15~20mm\",\n        \"FEUERBRETT (HEARTH BOARD)\",\n        \"KERBENSPITZE (Exakt im Bohrlochzentrum)\",\n        \"KRITISCHE AUFBAUREGEL:\",\n        \"V-Kerbenspitze muss Achszentrum berühren\",\n        \"KOHLESTAUB-SAMMELZONE (GLUTBETT)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PHYSICS\",\n        \"title\": \"Belüftungs- und Sammeldynamik der keilförmigen V-Kerbe\",\n        \"text\": \"In einem geschlossenen Rundloch erstickt der Sauerstoffmangel die Verkohlung. Die 45-Grad-V-Kerbe saugt kontinuierlich frischen Sauerstoff an und sammelt den über **400°C heißen** Kohlestaub an einem Punkt, sodass er zu einem eigenständigen Glutkern verschmilzt.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Schritt 2: Mit Körpergewicht andrücken und den Bogen lang sägen\",\n      \"description\": \"1. **Sehne 1-mal umwickeln**: Wickeln Sie die Bogensehne **1 volle Umdrehung** fest um die Spindel, damit sie nicht rutscht.\\n2. **12~15kg Vertikaldruck**: Treten Sie mit dem linken Fuß fest auf das Brett und drücken Sie die Spindelspitze mit dem Handstück mit **12~15kg Körpergewicht** senkrecht nach unten.\\n3. **Volle Hublänge sägen**: Halten Sie den Bogen waagerecht und ziehen und schieben Sie ihn über die gesamte Länge gleichmäßig hin und her.\\n4. **Endspurt bei dichter Rauchentwicklung**: Sobald dicker weißer Rauch quillt, beschleunigen Sie in den **letzten 5 Sekunden mit 15+ kraftvollen Zügen** auf Höchstgeschwindigkeit.\",\n      \"actionNote\": \"> Hitzeschwelle durchbrechen: Hören Sie nicht auf, nur weil etwas Rauch aufsteigt. Erst wenn 10~15 kraftvolle Züge nach dichtem Rauchaustritt durchgezogen werden, erreicht der Staub die 400°C Zündtemperatur.\",\n      \"svgFileName\": \"02-step-02.svg\",\n      \"svgLabels\": [\n        \"DRUCKLAGER (HANDSTÜCK)\",\n        \"F_DOWN: 12~15 kg (Vertikallast)\",\n        \"BOGENSTAB (65cm Hartholz)\",\n        \"VOLLHUB-PENDELBEWEGUNG (Volle Bogenlänge)\",\n        \"ω: 300~400 RPM\",\n        \"FEUERBRETT\",\n        \"WEISSER RAUCH (Dichter Rauch)\",\n        \"KRITISCHER SCHWELLENWERT:\",\n        \"Zündtemp.: 400°C+\",\n        \"Druck: Start 30% → Ende 100%\",\n        \"Hub: 100% Bogenlänge nutzen\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"Umwandlung mechanischer Energie in Reibungswärme bei 400°C\",\n        \"text\": \"Die Hin- und Herbewegung des Bogens wandelt sich an der winzigen Kontaktfläche schlagartig in thermische Hitze um. Holz beginnt bei **250°C** zu verkohlen, doch ein sich selbst erhaltender glimmender Glutkern entsteht erst, wenn die Kontaktzone **400°C überschreitet**.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Schritt 3: Glut ins Zundernest legen, um 45 Grad neigen und anfachen\",\n      \"description\": \"1. **Glutkern ruhen lassen**: Halten Sie an und lassen Sie den rauchenden Kohlestaub auf dem Blatt für **30 Sekunden unberührt** ruhen, bis er zu einem festen Glutklumpen zusammenbackt.\\n2. **Ins Zundernest betten**: Formen Sie aus trockenem Gras ein schalenförmiges Vogelnest und schütten Sie den Glutkern vorsichtig in die Mitte.\\n3. **45-Grad-Neigung**: Halten Sie das Nest im **45-Grad-Winkel** leicht über Augenhöhe und blasen Sie **lang und sanft** direkt in die Glut.\\n4. **Flammenausbruch**: Der Sauerstoff facht das Glühen an, bis innerhalb von **15~20 Sekunden eine 600°C heiße Flamme** emporlodert; setzen Sie diese sofort in das vorbereitete Reisigfeuer.\",\n      \"actionNote\": \"> Steigungswinkel-Regel: Das Nest um 45 Grad über Augenhöhe zu halten verhindert, dass Rauch in die Augen sticht. Zudem heizt die aufsteigende Konvektionswärme die umgebenden Fasern vor und verdoppelt die Zündwahrscheinlichkeit.\",\n      \"svgFileName\": \"02-step-03.svg\",\n      \"svgLabels\": [\n        \"GLUTKERN (450°C)\",\n        \"SANFTER KONTINUIERLICHER LUFTSTROM\",\n        \"FLAMMENZÜNDUNG (Durchzündung)\",\n        \"45° HALTEWINKEL\",\n        \"TEMPERATURANSTIEG & ZÜNDMATRIX\",\n        \"ZEIT (Sek)\",\n        \"TEMP (°C)\",\n        \"600°C FLAMMEN-ZÜNDSCHWELLE\",\n        \"400°C GLIMMPUNKT (KOHLE)\",\n        \"30s Reifen & Einsetzen (0s)\",\n        \"Flammenausbruch (15~20s)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD AERODYNAMICS\",\n        \"title\": \"Konvektiver Wärmeübergang und Phasenübergang zur 600°C Flamme\",\n        \"text\": \"Der 450°C Glutkern ist feste glimmende Kohle. Sanft zugeführter Sauerstoff treibt Kohlenmonoxid und brennbare Holzgase aus. Sobald die Temperatur **600°C erreicht**, geht die Glimmverbrennung schlagartig in eine gasförmige offene Flamme über.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Tödlicher Fehler: Hastig und stark in den frisch entstandenen Kohlestaub blasen\",\n    \"description\": \"Wer sofort nach dem Bohren heftig auf das lose schwarze Pulver bläst, verweht die noch ungebundenen Kohleteilchen im Wind und löscht die Kernhitze augenblicklich aus.\",\n    \"consequence\": \"Gegenmaßnahme: Wenn Rauch aus dem Pulver aufsteigt, berühren Sie es nicht, sondern warten Sie 30 Sekunden, bis es sich zu einem festen Glutkern verdichtet hat.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr02-outcome.svg\",\n    \"title\": \"Vollendete Bogenbohrer-Reibungszündung mit Glut\",\n    \"description\": \"Eine 400°C heiße Holzkohleglut aus der 45°-V-Kerbe, die sicher in das trockene Zundernest überführt und zu einer offenen Flamme entfacht wurde.\"\n  },\n  \"createdAt\": \"2026-10-09T16:05:00.000Z\",\n  \"updatedAt\": \"2026-10-15T15:45:00+09:00\",\n  \"contentHash\": \"006f8f1c7593c632\"\n}","content/protocols/locales/02-friction-fire.en.json":"{\n  \"protocolId\": \"PR-02\",\n  \"category\": \"FIRE\",\n  \"title\": \"How to Make Fire with Friction (Bow Drill Method)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[THREAT LEVEL: CRITICAL]\",\n  \"summary\": \"A vital primitive survival technique to create fire using dry branches and cordage without matches or lighters. Sawing the bow back and forth rapidly spins the center spindle, generating 400°C glowing coal dust through friction. Transferring this coal into a dry tinder nest and blowing gently ignites an open 600°C flame.\",\n  \"timeRequired\": \"20 MINUTES\",\n  \"successRate\": \"85% (Dry Timber)\",\n  \"difficulty\": \"Tier 2 (Skilled Primitive)\",\n  \"outputPerHour\": \"1 Fire / 20 min\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Bow Stick & Heavy-Duty Cord\",\n      \"desc\": \"A 60-70cm slightly curved sturdy branch lashed with tough wild vine cord or rawhide string to drive the spindle.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Center Spindle Stick (Drill)\",\n      \"desc\": \"A thumb-thick (2cm diameter), 25cm long straight bone-dry wooden rod tapered to a pencil point on the lower friction tip.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Hearth Board & Dry Tinder Nest\",\n      \"desc\": \"A 1.5-2cm thick flat dry softwood board paired with a bird's-nest bundle of dry grass and reed down to catch the ember.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Step 1: Carve a 45-degree V-notch in the hearth board\",\n      \"description\": \"1. **Spindle Socket Seating**: Press and spin the drill tip **1-1.5cm inward** from the hearth board edge to burn in a small circular depression.\\n2. **45-Degree V-Notch Carving**: Use a stone knife to slice a pizza-wedge-shaped **45-degree V-notch** from the board edge directly to the socket center.\\n3. **Base Collector Placement**: Tuck a flat, dry wide leaf directly beneath the notch to catch all falling hot carbon dust.\",\n      \"actionNote\": \"> Notch Alignment: The apex of the V-notch must touch the exact center of the drill hole. If misaligned, hot wood dust cannot exit and gets trapped around the spindle, preventing ember formation.\",\n      \"svgFileName\": \"02-step-01.svg\",\n      \"svgLabels\": [\n        \"EMBER CATCHER LEAF [DRY BARK/LEAF]\",\n        \"45° V-NOTCH (Apex Meets Axis Center)\",\n        \"Ø 20mm SPINDLE AXIS\",\n        \"THICKNESS: 15~20mm\",\n        \"HEARTH BOARD (SOFTWOOD)\",\n        \"NOTCH APEX (Aligned with Socket Center)\",\n        \"CRITICAL SETUP RULE:\",\n        \"Notch apex must touch spindle axis center\",\n        \"CARBON DUST ACCUMULATION ZONE (EMBER BED)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PHYSICS\",\n        \"title\": \"V-Notch Oxygen Draft & Carbon Dust Coalescence Dynamics\",\n        \"text\": \"Inside a round closed socket, lack of airflow suffocates carbonization. The 45-degree wedge notch creates an aerodynamic vent that draws in fresh oxygen while channeling **400°C+ pulverized charcoal** into a dense, self-insulating pile that coalesces into a living ember.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Step 2: Press down with body weight and saw the bow full length\",\n      \"description\": \"1. **Single Cord Wrap**: Wrap the bowstring **once completely around** the spindle to maintain tight, non-slip friction.\\n2. **12-15kg Downward Pressure**: Step firmly on the hearth board with your left foot and press down on the spindle top with a bearing block using **12-15kg of vertical body weight**.\\n3. **Full-Stroke Sawing**: Keep the bow horizontal and saw back and forth using the full length of the stick. Start smooth and steady.\\n4. **Smoke Acceleration Burst**: When thick white smoke billows out, accelerate to maximum effort for the **final 5 seconds with 15+ rapid strokes**.\",\n      \"actionNote\": \"> Thermal Threshold: Never stop at the first trace of smoke. You must maintain 10-15 powerful acceleration strokes after dense smoke appears to cross the 400°C ignition threshold.\",\n      \"svgFileName\": \"02-step-02.svg\",\n      \"svgLabels\": [\n        \"BEARING BLOCK (HAND SOCKET)\",\n        \"F_DOWN: 12~15 kg (Vertical Load)\",\n        \"BOW STICK (65cm Curved Limb)\",\n        \"FULL-STROKE RECIPROCATING MOTION (Full Bow Length)\",\n        \"ω: 300~400 RPM\",\n        \"HEARTH BOARD\",\n        \"WHITE SMOKE (Dense Smoke Plume)\",\n        \"CRITICAL THRESHOLD:\",\n        \"Ignition Temp: 400°C+\",\n        \"Load: Start 30% → Final 100%\",\n        \"Stroke: Use 100% Bow Length\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"Mechanical Friction Conversion and 400°C Carbonization Limit\",\n        \"text\": \"Reciprocating kinetic energy from the bow converts instantaneously into thermal heat at the microscopic contact point. Wood begins charring at **250°C**, but sustained self-heating coals require the contact interface to surpass **400°C** under dense packing.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Step 3: Transfer ember into tinder nest and elevate 45 degrees to ignite\",\n      \"description\": \"1. **Ember Coalescence Delay**: Stop sawing and let the smoking black dust rest untouched on the base leaf for **30 seconds** until it fuses into a solid glowing coal.\\n2. **Tinder Nest Deposition**: Form dry grass into a cup-shaped bird's nest and gently dump the ember block into the core.\\n3. **45-Degree Elevation**: Hold the nest at a **45-degree angle** slightly above eye level and blow **long, gentle breaths** directly into the coal.\\n4. **Flame Flashover**: Oxygen fans the glow until an open **600°C flame** bursts within **15-20 seconds**; immediately transfer to your prepared campfire kindling.\",\n      \"actionNote\": \"> Updraft Angle Rule: Holding the tinder nest at a 45-degree elevation prevents smoke from stinging your eyes while convective updrafts preheat surrounding fibers, doubling ignition reliability.\",\n      \"svgFileName\": \"02-step-03.svg\",\n      \"svgLabels\": [\n        \"EMBER CORE (450°C)\",\n        \"GENTLE CONTINUOUS BREATH (Steady Low Airflow)\",\n        \"FLAME IGNITION BURST (Flashover Stage)\",\n        \"45° ELEVATION CUPPING\",\n        \"TEMPERATURE RISE & IGNITION MATRIX\",\n        \"TIME (sec)\",\n        \"TEMP (°C)\",\n        \"600°C FLAME IGNITION THRESHOLD\",\n        \"400°C CARBON SMOLDER POINT\",\n        \"Coalesce 30s & Transfer (0s)\",\n        \"Flame Ignition (15~20s)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD AERODYNAMICS\",\n        \"title\": \"Convective Heat Transfer and 600°C Flame Phase Transition\",\n        \"text\": \"The 450°C coal is a solid-state smoldering mass. Supplying a laminar stream of gentle oxygen drives off volatile carbon monoxide and wood gases. As local temperature exceeds **600°C**, gas-phase combustion takes over, erupting into a self-sustaining open flame.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Critical Mistake: Blowing rashly on loose, freshly formed ember dust\",\n    \"description\": \"Blowing hard on the black dust immediately after stopping will blow the uncoalesced particles away, scattering heat and extinguishing the core instantaneously.\",\n    \"consequence\": \"Remedy: When smoke rises from the dust pile, wait 30 seconds for the embers to fuse into a solid glowing coal before transferring to tinder.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr02-outcome.svg\",\n    \"title\": \"Completed Bow Drill Friction Fire & Ember Ignition\",\n    \"description\": \"A glowing 400°C charcoal ember generated in the 45° V-notch smoking heavily, transferred safely into a dry tinder nest and fanned into an open flame.\"\n  },\n  \"createdAt\": \"2026-10-09T16:05:00.000Z\",\n  \"updatedAt\": \"2026-10-15T15:45:00+09:00\",\n  \"contentHash\": \"006f8f1c7593c632\"\n}","content/protocols/locales/02-friction-fire.es.json":"{\n  \"protocolId\": \"PR-02\",\n  \"category\": \"FIRE\",\n  \"title\": \"Cómo hacer fuego por fricción con ramas (Método del taladro de arco)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[NIVEL DE AMENAZA: CRÍTICO]\",\n  \"summary\": \"Una técnica esencial de supervivencia para encender fuego con ramas secas y cuerda sin fósforos ni encendedor. Al mover el arco hacia adelante y atrás, el huso gira a gran velocidad generando polvo de carbón incandescente a 400°C por fricción. Al colocar esta brasa en un nido de hierba seca y soplar suavemente, brota una gran llama a 600°C.\",\n  \"timeRequired\": \"20 MINUTOS\",\n  \"successRate\": \"85% (Madera Seca)\",\n  \"difficulty\": \"Nivel 2 (Habilidad Técnica)\",\n  \"outputPerHour\": \"1 Fuego / 20 min\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Arco y cuerda natural resistente\",\n      \"desc\": \"Rama flexible y firme de 60~70cm con cuerda de fibras de enredadera o cuero para accionar el huso con fuerza.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Huso giratorio central\",\n      \"desc\": \"Rama recta y muy seca del grosor del pulgar (unos 2cm de diámetro) y 25cm de largo. Punta afilada como lápiz.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Tabla base y nido de hierba seca\",\n      \"desc\": \"Tabla de madera plana y seca de 1.5~2cm de grosor junto a un nido de hierba seca para recibir y envolver la brasa.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Paso 1: Tallar una muesca en V de 45 grados en la tabla base\",\n      \"description\": \"1. **Marcar hueco inicial**: Presione y gire la punta del huso a **1~1.5cm del borde** de la tabla hasta crear una pequeña concavidad.\\n2. **Tallar muesca en V de 45 grados**: Con un cuchillo de piedra, talle una ranura en V de **45 grados** en forma de trozo de pizza desde el borde hasta el centro del hueco.\\n3. **Colocar hoja recolectora**: Coloque una hoja ancha y seca justo debajo de la muesca para recoger todo el polvo de carbón caliente sin que caiga al suelo.\",\n      \"actionNote\": \"> Precisión del corte: La punta de la V debe coincidir exactamente con el centro del hueco. Si se desvía, el polvo caliente no podrá salir, se atascará y no formará brasa.\",\n      \"svgFileName\": \"02-step-01.svg\",\n      \"svgLabels\": [\n        \"HOJA RECOLECTORA [BASE DE BRASA]\",\n        \"MUESCA EN V 45° (Vértice en Centro)\",\n        \"EJE HUSO Ø 20mm\",\n        \"ESPESOR: 15~20mm\",\n        \"TABLA BASE (HEARTH BOARD)\",\n        \"VÉRTICE (Alineado al Centro del Huso)\",\n        \"REGLA CRÍTICA DE AJUSTE:\",\n        \"El vértice en V debe tocar el centro del eje\",\n        \"ZONA DE ACUMULACIÓN DE POLVO DE CARBÓN\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PHYSICS\",\n        \"title\": \"Dinámica de ventilación y acumulación de carbón en la muesca en V\",\n        \"text\": \"En un hueco cerrado sin ranura, la falta de aire sofoca la combustión. La muesca en V de 45° actúa como conducto de ventilación que aspira oxígeno fresco y canaliza el polvo de carbón a **más de 400°C** en un punto concentrado para formar una brasa sólida.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Paso 2: Presionar con el peso del cuerpo y mover el arco a toda longitud\",\n      \"description\": \"1. **Enrollar cuerda 1 vuelta**: Enrolle la cuerda del arco **1 vuelta completa** alrededor del huso para lograr un agarre firme y sin deslizamiento.\\n2. **Presión vertical de 12~15kg**: Pise la tabla firmemente con el pie izquierdo y presione la parte superior del huso con un apoyo usando **12~15kg de peso corporal** vertical.\\n3. **Movimiento de sierra completo**: Mantenga el arco horizontal y desplácelo de extremo a extremo a lo largo de toda su longitud con ritmo constante.\\n4. **Aceleración final al ver humo**: Cuando empiece a brotar humo blanco espeso, aumente la velocidad al máximo durante los **últimos 5 segundos con más de 15 carreras rápidas**.\",\n      \"actionNote\": \"> Cruce del umbral térmico: No se detenga solo porque salga un poco de humo. Es indispensable dar 10~15 pasadas potentes adicionales tras la densa humareda para alcanzar los 400°C de ignición.\",\n      \"svgFileName\": \"02-step-02.svg\",\n      \"svgLabels\": [\n        \"BLOQUE DE APOYO (SOCKET MANUAL)\",\n        \"F_DOWN: 12~15 kg (Carga Vertical)\",\n        \"ARCO TÁCTICO (Rama 65cm)\",\n        \"MOVIMIENTO RECÍPROCO DE CARRERA COMPLETA\",\n        \"ω: 300~400 RPM\",\n        \"TABLA BASE\",\n        \"HUMO BLANCO (Emisión Densa)\",\n        \"UMBRAL CRÍTICO:\",\n        \"Temp. Ignición: 400°C+\",\n        \"Presión: Inicio 30% → Final 100%\",\n        \"Carrera: 100% Longitud del Arco\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"Conversión de energía mecánica a calor y límite de carbonización a 400°C\",\n        \"text\": \"La energía cinética del arco se transforma en calor extremo en la pequeña superficie de contacto. La madera comienza a carbonizarse a **250°C**, pero para lograr un carbón incandescente autosuficiente, la temperatura de contacto debe superar obligatoriamente los **400°C**.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Paso 3: Pasar la brasa al nido de yesca y elevar a 45 grados para soplar\",\n      \"description\": \"1. **Esperar unión de la brasa**: Detenga el arco y deje reposar el montón de polvo negro sobre la hoja sin tocarlo durante **30 segundos** hasta que se compacte en un carbón ardiente.\\n2. **Traslado al nido de yesca**: Forme un nido en forma de taza con hierba seca y vierta cuidadosamente la brasa en el centro.\\n3. **Elevación a 45 grados**: Sostenga el nido a un ángulo de **45 grados** ligeramente por encima de los ojos y sople de forma **larga y suave** directamente a la brasa.\\n4. **Brote de llama viva**: El oxígeno aviva el brillo y en **15~20 segundos** surge una potente **llama a 600°C**; trasládela de inmediato a su fogata preparada.\",\n      \"actionNote\": \"> Regla del ángulo de elevación: Sostener el nido a 45° por encima de los ojos evita que el humo irrite la vista y permite que el calor ascendente precaliente las fibras de yesca, duplicando el éxito de ignición.\",\n      \"svgFileName\": \"02-step-03.svg\",\n      \"svgLabels\": [\n        \"NÚCLEO BRASA (450°C)\",\n        \"SOPLO SUAVE Y CONTINUO (Flujo Lento)\",\n        \"IGNICIÓN DE LLAMA (Brote Térmico)\",\n        \"ELEVACIÓN A 45°\",\n        \"MATRIZ DE TEMPERATURA E IGNICIÓN\",\n        \"TIEMPO (s)\",\n        \"TEMP (°C)\",\n        \"600°C UMBRAL DE LLAMA ABIERTA\",\n        \"400°C PUNTO DE BRASA ACTIVA\",\n        \"30s Cohesión y Traslado (0s)\",\n        \"Ignición Llama (15~20s)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD AERODYNAMICS\",\n        \"title\": \"Transferencia de calor por convección y transición de fase a llama de 600°C\",\n        \"text\": \"La brasa a 450°C es una masa incandescente sólida. Al suministrar un flujo suave de oxígeno, la superficie libera monóxido de carbono y gases combustibles. Cuando la temperatura local alcanza los **600°C**, ocurre una rápida transición a combustión gaseosa formando una llama abierta.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Error fatal: Soplar fuerte y apresuradamente sobre el polvo recién formado\",\n    \"description\": \"Soplar con fuerza inmediatamente después de parar el arco dispersará las partículas de carbón que aún no se han unido, apagando el calor central al instante.\",\n    \"consequence\": \"Solución: Cuando el polvo humee, no lo toque y espere 30 segundos a que se compacte en un carbón encendido antes de moverlo a la yesca.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr02-outcome.svg\",\n    \"title\": \"Ignición de Brasa por Fricción con Arco Completada\",\n    \"description\": \"Una brasa incandescente a 400°C generada en la ranura en V, transferida con éxito al nido de yesca seca y avivada hasta producir una llama viva.\"\n  },\n  \"createdAt\": \"2026-10-09T16:05:00.000Z\",\n  \"updatedAt\": \"2026-10-15T15:45:00+09:00\",\n  \"contentHash\": \"006f8f1c7593c632\"\n}","content/protocols/locales/02-friction-fire.ja.json":"{\n  \"protocolId\": \"PR-02\",\n  \"category\": \"FIRE\",\n  \"title\": \"木の枝の摩擦で火を起こす方法（ボウドリル摩擦発火法）\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[危険等級: 致命的(CRITICAL)]\",\n  \"summary\": \"ライターやマッチがないとき、乾いた木の枝とひもを使って火を起こすサバイバル技術です。弓を前後に引いて中央の丸棒を高速回転させると、摩擦熱で400℃の黒い火種粉末が作られます。この火種を乾いた草の巣に移し、優しく息を吹き込むと600℃の大きな炎が燃え上がります。\",\n  \"timeRequired\": \"20分 (20 MINUTES)\",\n  \"successRate\": \"85% (乾燥材基準)\",\n  \"difficulty\": \"第2等級 (熟練技術)\",\n  \"outputPerHour\": \"1 Fire / 20 min\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"弓の枝と強靭な天然ひも\",\n      \"desc\": \"長さ60~70cmのしなやかで頑丈な木の枝と、クズのつるや木の皮をよって作った丈夫なひもです。回転棒を強力に駆動します。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"中央の回転棒（スピンドル）\",\n      \"desc\": \"親指の太さ（直径約2cm）、長さ25cmのまっすぐでカラカラに乾いた木の枝です。下側を鉛筆のように削って摩擦板に噛み合わせます。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"下敷きの火床板と乾いた草の巣\",\n      \"desc\": \"厚さ1.5~2cmの平らで乾燥した木の板と、火種を受け止めて包む鳥の巣型の乾いた草・ススキの綿毛の束です。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"ステップ1：火床板に火種が集まる45度V字の溝を彫る\",\n      \"description\": \"1. **くぼみ穴の削り出し**: 火床板の縁から内側に**1~1.5cmの位置**に、回転棒の先端を押し当てて小さなくぼみを作ります。\\n2. **45度V字溝の切削**: 石器のナイフを使い、板の縁からくぼみの中央に向かってピザ1片の形をした**45度のV字溝**を切り込みます。\\n3. **受け葉の敷設**: 切り込んだV字溝の真下に、落ちてくる熱い木粉をこぼさず受ける幅広の乾燥葉を敷いておきます。\",\n      \"actionNote\": \"> 溝の正確さ: V字溝の尖った頂点は必ずくぼみ穴の中心に届いていなければなりません。ずれると熱い粉末が外に排出されず、棒の周りに詰まって火種ができません。\",\n      \"svgFileName\": \"02-step-01.svg\",\n      \"svgLabels\": [\n        \"EMBER CATCHER LEAF [火種受け葉]\",\n        \"45° V-NOTCH (溝頂点: 軸中心に接触)\",\n        \"Ø 20mm スピンドル軸\",\n        \"板厚: 15~20mm\",\n        \"HEARTH BOARD (火床板)\",\n        \"ノッチ頂点 (ソケット中心と一致)\",\n        \"重要セットアップ規則:\",\n        \"V溝の頂点はスピンドル軸中心と正確に接触\",\n        \"CARBON DUST ZONE (炭化火種集積区域)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PHYSICS\",\n        \"title\": \"V字溝のくさび型酸素供給と炭化粉末捕集の力学\",\n        \"text\": \"丸い穴の内部では摩擦面に空気が通らず、木材が燃焼できません。45度のくさび溝は新鮮な酸素を持続的に吸い込みながら、摩擦で削られた**400℃以上**の微細な炭化粉末を一箇所に集積させ、自活する火種の塊へと凝集させます。\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"ステップ2：体重を真上からかけながら弓を前後に大きく引く\",\n      \"description\": \"1. **弓弦を1回転巻き付け**: 弓のひもの中央に回転棒を**1回きつく巻き付け**、滑らないようピンと張ります。\\n2. **体重12~15kgでの垂直加圧**: 左足で火床板をしっかり踏み固定し、ハンドブロックで棒の先端を**真上から強く**押し込みます。\\n3. **全ストロークでの弓引き**: 弓を水平に保ち、端から端まで長く押して引きます。最初はゆっくり回して軸を安定させます。\\n4. **発煙後のスプリント**: 濃い白煙が立ち上り始めたら回転速度を上げ、**最後の5秒間、15回以上全力で**素早く往復させます。\",\n      \"actionNote\": \"> 熱量限界の突破: 煙が少し出たからといってすぐに止めてはなりません。濃い煙が吹き出した後も必ず10~15回以上押し切ることで、400℃の発火点に到達します。\",\n      \"svgFileName\": \"02-step-02.svg\",\n      \"svgLabels\": [\n        \"BEARING BLOCK (ハンドソケット)\",\n        \"F_DOWN: 12~15 kg (垂直荷重)\",\n        \"BOW STICK (長さ65cm 弓枝)\",\n        \"FULL-STROKE MOTION (弓全長での往復ストローク)\",\n        \"ω: 300~400 RPM\",\n        \"HEARTH BOARD\",\n        \"WHITE SMOKE (濃密な白煙放出)\",\n        \"臨界しきい値:\",\n        \"発火温度: 400°C+\",\n        \"加圧比率: 初期30% → 終期100%\",\n        \"ストローク: 弓全長100%使用\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"往復力学エネルギーの摩擦熱変換と400℃炭化臨界点\",\n        \"text\": \"弓の往復運動エネルギーは、回転棒先端の微小な接触面で急激な熱エネルギーへと変換されます。木材は**250℃から**黒く焦げ始めますが、自ら熱を保ち燃え続ける熾火(Coal)を形成するには、接触部が**400℃を確実に**超える必要があります。\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"ステップ3：乾いた草の巣に火種を移し、45度上に向けて息を吹き込む\",\n      \"description\": \"1. **火種の凝集待機**: 弓引きを止め、葉の上に集まった黒い粉末を触らずに**30秒間そのまま**置きます。煙を上げながら固い火種の塊へとまとまります。\\n2. **火口の巣への移植**: 乾いた草と綿毛を鳥の巣のように丸め、その中央に火種の塊をそっと移します。\\n3. **45度上方への保持**: 巣を目線より少し高い**45度の角度**で斜めに掲げ、煙を避けながら火種に向けて**長く優しく**息を吹き込みます。\\n4. **火炎の着火**: 酸素が送り込まれると赤熱が広がり、**15~20秒以内に600℃の炎**が吹き上がります。すぐに用意した焚き火の小枝に移します。\",\n      \"actionNote\": \"> 仰角送風の法則: 巣を目線より45度上に掲げると、立ち上る煙が目に染みません。また上昇気流による対流熱伝達で周囲の繊維が急速に予熱され、着火成功率が2倍に向上します。\",\n      \"svgFileName\": \"02-step-03.svg\",\n      \"svgLabels\": [\n        \"火種コア (450°C)\",\n        \"GENTLE BREATH (均一な低速送風)\",\n        \"FLAME IGNITION (自然発火・着火段階)\",\n        \"45° 上方保持\",\n        \"温度上昇＆着火マトリックス\",\n        \"時間 (秒)\",\n        \"温度 (°C)\",\n        \"600°C 火炎発火しきい値\",\n        \"400°C 炭化燻焼ポイント\",\n        \"30秒凝集後に移植 (0秒)\",\n        \"火炎着火 (15~20秒)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD AERODYNAMICS\",\n        \"title\": \"対流熱伝達と600℃気体燃焼火炎への相転移メカニズム\",\n        \"text\": \"火種の塊(450℃)は固体の不完全燃焼状態です。穏やかな酸素気流を送り込むと炭の表面から一酸化炭素や可燃性ガスが放出され、局所温度が**600℃に達した瞬間**、気体燃焼である『自由火炎(Flame)』へと爆発的に転移します。\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"絶対に避けるべき失敗：できたばかりの火種粉末に急いで強い息を吹き込む\",\n    \"description\": \"弓引きを止めた直後に焦って葉の上の黒い粉末に強く息を吹きかけると、まだ固まっていない火種の粒子が四方八方に飛び散り、熱が瞬時に失われてしまいます。\",\n    \"consequence\": \"対策：粉末から煙が立ち上り始めたら手を出さず、30秒間自ら熱を蓄えて固い熾火になるのを待ってから火口に移してください。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr02-outcome.svg\",\n    \"title\": \"ボウドリル摩擦発火および火種着火の完成形態\",\n    \"description\": \"火床板の45度V溝に摩擦熱で生じた黒い炭粉の熾火(400°C)が赤く燃え上がり、これを乾燥した火口の巣に移して炎を立ち上げた実戦発火の完成状態です。\"\n  },\n  \"createdAt\": \"2026-10-09T16:05:00.000Z\",\n  \"updatedAt\": \"2026-10-15T15:45:00+09:00\",\n  \"contentHash\": \"006f8f1c7593c632\"\n}","content/protocols/locales/02-friction-fire.pt.json":"{\n  \"protocolId\": \"PR-02\",\n  \"category\": \"FIRE\",\n  \"title\": \"Como Fazer Fogo por Fricção com Galhos (Método do Arco)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[NÍVEL DE AMEAÇA: CRÍTICO]\",\n  \"summary\": \"Uma técnica essencial de sobrevivência para fazer fogo usando galhos secos e uma corda sem fósforos ou isqueiro. Ao puxar e empurrar o arco para frente e para trás, o fuso gira em alta velocidade gerando pó de carvão em brasa a 400°C por atrito. Colocando essa brasa em um ninho de palha seca e soprando suavemente, surge uma chama viva a 600°C.\",\n  \"timeRequired\": \"20 MINUTOS\",\n  \"successRate\": \"85% (Madeira Seca)\",\n  \"difficulty\": \"Nível 2 (Habilidade Técnica)\",\n  \"outputPerHour\": \"1 Fogo / 20 min\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Arco e corda natural resistente\",\n      \"desc\": \"Galho firme e levemente curvo de 60~70cm com corda de fibras de cipó ou couro para tracionar o fuso com força.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Fuso giratório central\",\n      \"desc\": \"Galho reto e bem seco da grossura do polegar (cerca de 2cm de diâmetro) e 25cm de comprimento. Ponta inferior afiada como lápis.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Prancha base e ninho de palha seca\",\n      \"desc\": \"Prancha de madeira seca e plana de 1.5~2cm de espessura com ninho em forma de taça feito de capim seco para acolher a brasa.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Passo 1: Esculpir entalhe em V de 45 graus na prancha base\",\n      \"description\": \"1. **Fazer depressão inicial**: Pressione e gire a ponta do fuso a **1~1.5cm da borda** da prancha para queimar uma pequena cavidade.\\n2. **Cortar entalhe em V de 45 graus**: Com uma faca de pedra, abra um entalhe em V de **45 graus** em formato de fatia de pizza, da borda até o centro da cavidade.\\n3. **Posicionar folha coletora**: Coloque uma folha larga e seca logo abaixo do entalhe para recolher todo o pó de carvão quente sem derramar.\",\n      \"actionNote\": \"> Alinhamento do entalhe: A ponta do entalhe em V deve tocar exatamente o centro da cavidade. Se desviar, o pó quente não sai, fica preso ao redor do fuso e não forma brasa.\",\n      \"svgFileName\": \"02-step-01.svg\",\n      \"svgLabels\": [\n        \"FOLHA COLETORA [BASE DE BRASA]\",\n        \"ENTALHE EM V 45° (Vértice no Centro)\",\n        \"EIXO FUSO Ø 20mm\",\n        \"ESPESSURA: 15~20mm\",\n        \"PRANCHA BASE (HEARTH BOARD)\",\n        \"VÉRTICE (Alinhado ao Centro do Fuso)\",\n        \"REGRA CRÍTICA DE MONTAGEM:\",\n        \"O vértice em V deve tocar o centro do eixo\",\n        \"ZONA DE ACÚMULO DE PÓ DE CARVÃO (BRASA)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PHYSICS\",\n        \"title\": \"Dinâmica de aeração e aglomeração de pó de carvão no entalhe em V\",\n        \"text\": \"Em um furo redondo fechado, a falta de ar sufoca a queima. O entalhe em V de 45° atua como conduto de ventilação que aspira oxigênio fresco e canaliza o pó a **mais de 400°C** para um ponto compacto, formando uma brasa consolidada.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Passo 2: Pressionar com peso do corpo e serrar o arco em curso total\",\n      \"description\": \"1. **Dar 1 volta com a corda**: Enrole a corda do arco **1 volta completa** em torno do fuso para obter tração firme sem derrapar.\\n2. **Pressão vertical de 12~15kg**: Pise firme na prancha com o pé esquerdo e empurre o topo do fuso com o bloco de apoio usando **12~15kg de peso corporal** vertical.\\n3. **Serrar em curso total**: Mantenha o arco na horizontal e empurre-puxe de ponta a ponta com ritmo uniforme em todo o comprimento.\\n4. **Arrancada final com fumaça**: Quando fumaça branca densa brotar, acelere ao máximo nos **últimos 5 segundos com mais de 15 passadas rápidas**.\",\n      \"actionNote\": \"> Ultrapassagem do limite térmico: Não pare assim que a fumaça surgir. É essencial manter 10~15 passadas vigorosas adicionais após a fumaça densa para atingir o limiar de ignição de 400°C.\",\n      \"svgFileName\": \"02-step-02.svg\",\n      \"svgLabels\": [\n        \"BLOCO DE APOIO (SOQUETE MANUAL)\",\n        \"F_DOWN: 12~15 kg (Carga Vertical)\",\n        \"ARCO TÁTICO (Galho 65cm)\",\n        \"MOVIMENTO RECÍPROCO DE CURSO TOTAL\",\n        \"ω: 300~400 RPM\",\n        \"PRANCHA BASE\",\n        \"FUMAÇA BRANCA (Emissão Densa)\",\n        \"LIMIAR CRÍTICO:\",\n        \"Temp. Ignição: 400°C+\",\n        \"Pressão: Início 30% → Final 100%\",\n        \"Curso: 100% do Arco\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"Conversão de energia mecânica em atrito térmico e limite a 400°C\",\n        \"text\": \"A energia cinética do vaivém do arco se converte em calor extremo na microárea de atrito. A madeira começa a escurecer a **250°C**, mas para formar uma brasa capaz de sustentar a queima, a zona de contato deve superar obrigatoriamente os **400°C**.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Passo 3: Passar a brasa para o ninho de isca e soprar a 45 graus para acender\",\n      \"description\": \"1. **Aguardar união da brasa**: Pare o arco e deixe o monte de pó preto descansar sobre a folha por **30 segundos** sem tocar, até se aglutinar em uma brasa sólida.\\n2. **Acomodar no ninho de isca**: Molde o capim seco em formato de ninho de pássaro e despeje cuidadosamente a brasa no centro.\\n3. **Inclinar a 45 graus**: Levante o ninho a um ângulo de **45 graus** um pouco acima dos olhos e sopre de forma **longa e suave** diretamente na brasa.\\n4. **Ignição em chama aberta**: O oxigênio aviva a brasa e em **15~20 segundos** irrompe uma forte **chama a 600°C**; transfira imediatamente para a fogueira preparada.\",\n      \"actionNote\": \"> Regra de ângulo de elevação: Erguer o ninho a 45° acima dos olhos evita que a fumaça irrite a visão e permite que a corrente de calor ascendente pré-aqueça as fibras da isca, dobrando o sucesso do fogo.\",\n      \"svgFileName\": \"02-step-03.svg\",\n      \"svgLabels\": [\n        \"NÚCLEO BRASA (450°C)\",\n        \"SOPRO SUAVE E CONTÍNUO (Fluxo Lento)\",\n        \"IGNIÇÃO DE CHAMA (Combustão)\",\n        \"ELEVAÇÃO A 45°\",\n        \"MATRIZ DE TEMPERATURA E IGNIÇÃO\",\n        \"TEMPO (s)\",\n        \"TEMP (°C)\",\n        \"600°C LIMIAR DE CHAMA ABERTA\",\n        \"400°C PONTO DE BRASA ATIVA\",\n        \"30s Coesão e Transplante (0s)\",\n        \"Ignição Chama (15~20s)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD AERODYNAMICS\",\n        \"title\": \"Transferência convectiva de calor e transição de fase para chama a 600°C\",\n        \"text\": \"A brasa a 450°C é uma massa sólida incandescente. O fluxo suave de ar libera monóxido de carbono e gases inflamáveis da madeira. Quando a temperatura local atinge **600°C**, a queima passa para a fase gasosa, gerando chamas abertas.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Erro fatal: Soprar forte e com pressa sobre o pó de brasa recém-formado\",\n    \"description\": \"Soprar com força logo após parar o arco espalhará as partículas de carvão ainda soltas pelo ar, apagando o núcleo de calor instantaneamente.\",\n    \"consequence\": \"Solução: Quando o pó começar a soltar fumaça, não toque nele e aguarde 30 segundos até que se compacte em uma brasa antes de mover para a isca.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr02-outcome.svg\",\n    \"title\": \"Ignição por Fricção com Arco e Brasa Concluída\",\n    \"description\": \"Uma brasa incandescente a 400°C gerada na ranhura em V, transferida com sucesso para o ninho de mecha seca e soprada até formar chamas vivas.\"\n  },\n  \"createdAt\": \"2026-10-09T16:05:00.000Z\",\n  \"updatedAt\": \"2026-10-15T15:45:00+09:00\",\n  \"contentHash\": \"006f8f1c7593c632\"\n}","content/protocols/locales/02-friction-fire.zh-TW.json":"{\n  \"protocolId\": \"PR-02\",\n  \"category\": \"FIRE\",\n  \"title\": \"利用樹枝摩擦生火的方法 (弓鑽鑽木取火法)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[威脅等級：致命 (CRITICAL)]\",\n  \"summary\": \"在沒有打火機或火柴時，利用乾燥樹枝和繩子取火的必備生存技術。前後拉動弓桿使中心鑽軸高速旋轉，利用摩擦熱產生400℃的高溫炭化火種粉末。將此火種放入乾燥乾草巢中溫和吹氣，即可引燃600℃的旺盛明火。\",\n  \"timeRequired\": \"20分鐘 (20 MINUTES)\",\n  \"successRate\": \"85% (乾燥木材基準)\",\n  \"difficulty\": \"第2級 (進階求生技術)\",\n  \"outputPerHour\": \"1 Fire / 20 min\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"弓桿與強韌天然繩\",\n      \"desc\": \"長60~70公分微彎的結實樹枝，搭配葛藤或皮革編成的強韌繩子，用以強力帶動鑽軸旋轉。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"中心旋轉鑽軸\",\n      \"desc\": \"大拇指粗細(直徑約2公分)、長25公分的筆直乾燥木棒。底端削成鉛筆狀以與底板嵌合。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"鑽火底板與乾草引火巢\",\n      \"desc\": \"厚1.5~2公分平整乾燥的木板，搭配鳥巢狀乾燥乾草與芒草絨毛束以承接包裹火種。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"第1步：在鑽火底板切出聚集火種的45度V型槽\",\n      \"description\": \"1. **磨出起始凹槽**: 在底板邊緣往內**1~1.5公分處**，用鑽軸前端用力下壓旋轉磨出淺凹坑。\\n2. **切削45度V型槽**: 用石刀從底板邊緣切出一道呈披薩切片狀的**45度角V型槽**，槽頂點必須精準貫穿至凹坑中心。\\n3. **墊上集屑樹葉**: 在切好的V型槽正下方緊貼墊上一片乾燥寬樹葉，以完整收集落下之高溫木屑。\",\n      \"actionNote\": \"> 槽口精準度：V型槽尖端必須精準觸及凹坑中心。若有偏差，摩擦產生之高溫粉末無法順暢排出，會堵塞在鑽軸周圍而無法聚集成火種。\",\n      \"svgFileName\": \"02-step-01.svg\",\n      \"svgLabels\": [\n        \"EMBER CATCHER [火種收集葉片]\",\n        \"45° V型槽 (槽頂點接觸鑽軸中心)\",\n        \"Ø 20mm 鑽軸 (SPINDLE)\",\n        \"板厚: 15~20mm\",\n        \"鑽火底板 (HEARTH BOARD)\",\n        \"V槽頂點 (與凹槽中心點完全重疊)\",\n        \"關鍵設置法則:\",\n        \"V型槽頂點必須精準接觸鑽軸中心\",\n        \"碳化木屑堆積區 (火種凝聚處)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PHYSICS\",\n        \"title\": \"V型槽楔形供氧與炭化粉末匯聚力學\",\n        \"text\": \"封閉的圓孔內缺乏空氣循環，木材無法順利炭化。45度楔形槽持續吸入新鮮氧氣，同時將摩擦產生的**400℃以上**微細炭化木屑集中堆積於一處，使其聚合成能自持燃燒的火種塊。\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"第2步：以體重垂直下壓並全行程拉動弓桿\",\n      \"description\": \"1. **弓弦纏繞1圈**: 將弓繩在鑽軸中央**緊密纏繞1圈**，保持拉緊不打滑。\\n2. **垂直加壓12~15公斤**: 左腳踩穩底板固定於地面，用手塊或凹石由正上方以**12~15公斤體重**垂直用力壓住鑽軸。\\n3. **全行程水平拉弓**: 保持弓桿水平，由前至後以完整長度穩定推拉。初期先慢速旋轉穩定軸心。\\n4. **冒白煙後全力衝刺**: 當濃密白煙開始大量竄出時全力加速，在**最後5秒內全力快速往復拉動15次以上**以達到最高發熱量。\",\n      \"actionNote\": \"> 突破發熱極限：冒出些許白煙時切勿立即停手。冒煙後必須再全力加速推拉10~15次，才能確保木屑突破400℃著火燃點。\",\n      \"svgFileName\": \"02-step-02.svg\",\n      \"svgLabels\": [\n        \"頂壓手塊 (BEARING BLOCK)\",\n        \"F_DOWN: 12~15 kg (垂直下壓力)\",\n        \"弓桿 (長65cm 堅韌木枝)\",\n        \"全行程往復拉動 (100%弓長推拉)\",\n        \"ω: 300~400 RPM\",\n        \"HEARTH BOARD\",\n        \"濃密白煙 (炭化達標訊號)\",\n        \"臨界指標:\",\n        \"燃點溫度: 400°C+\",\n        \"加壓比例: 初期30% → 末期100%\",\n        \"行程: 使用100%弓桿全長\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"機械往復動能之摩擦熱轉換與400℃炭化極限\",\n        \"text\": \"弓桿往復動能在鑽軸底端的微小接觸點瞬間轉化為劇烈熱能。木材自**250℃開始**炭化變黑，但要形成能自持放熱的火種餘燼(Coal)，接觸面溫度必須**確實突破400℃**。\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"第3步：將火種移入乾草巢中並呈45度仰角吹氣點火\",\n      \"description\": \"1. **靜置凝聚火種**: 停止拉弓，讓落於樹葉上的黑色木屑堆**靜置30秒**勿碰觸，使其聚合成穩固冒煙的火種塊。\\n2. **移入引火草巢**: 將乾草做成凹陷鳥巢狀，小心將整塊火種倒在中央。\\n3. **45度仰角托舉**: 將草巢托舉至略高於視線的**45度仰角**避開濃煙，對準火種**均勻緩慢**吹入長氣。\\n4. **燃起明火**: 氧氣注入使紅光擴散，在**15~20秒內爆發出600℃明火**；立即轉移至準備好的小樹枝營火中。\",\n      \"actionNote\": \"> 仰角吹氣法則：將草巢持於視線上方45度角，可避免濃煙嗆傷眼睛，且上升熱對流能預先烘熱周圍草絲，使點火成功率倍增。\",\n      \"svgFileName\": \"02-step-03.svg\",\n      \"svgLabels\": [\n        \"火種核心 (450°C)\",\n        \"平穩緩慢吹氣 (均勻低速供氧)\",\n        \"火焰爆發點燃 (自燃階段)\",\n        \"45° 仰角托舉\",\n        \"溫度攀升與點火矩陣\",\n        \"時間 (秒)\",\n        \"溫度 (°C)\",\n        \"600°C 明火點燃臨界線\",\n        \"400°C 碳粉悶燒點\",\n        \"凝聚30秒後移植 (0秒)\",\n        \"明火點燃 (15~20秒)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD AERODYNAMICS\",\n        \"title\": \"熱對流傳導與600℃氣體燃燒明火相變機制\",\n        \"text\": \"450℃火種屬於固態不完全燃燒狀態。當注入平穩氧氣流時，炭表面釋放出有一氧化碳與可燃性木瓦斯。一旦局部溫度**突破600℃**，燃燒即相變躍升為氣體燃燒的『自由明火(Flame)』。\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"絕對不可犯的錯誤：對剛生成的火種粉末急躁吹猛氣\",\n    \"description\": \"拉弓停止後若急躁地對樹葉上的黑粉猛力吹氣，尚未聚集成塊的脆弱微粒會瞬間被風吹散，使核心熱量瞬間散失殆盡。\",\n    \"consequence\": \"處置：粉末開始冒煙時切勿碰觸，耐心等待30秒讓其自聚為結實火種塊後，再小心移入草巢。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr02-outcome.svg\",\n    \"title\": \"弓鑽摩擦生火與火種點燃完成形態\",\n    \"description\": \"火板45度V型槽內藉由摩擦熱生成的400°C黑炭灰餘燼劇烈冒烟，安全轉移至乾燥引火鳥巢並吹拂出明火的實戰生火完成狀態。\"\n  },\n  \"createdAt\": \"2026-10-09T16:05:00.000Z\",\n  \"updatedAt\": \"2026-10-15T15:45:00+09:00\",\n  \"contentHash\": \"006f8f1c7593c632\"\n}","content/protocols/locales/03-프로토콜-03-데브리-헛-debris-hut-a프레임-단열-은신처-구축법.de.json":"{\n  \"protocolId\": \"PR-03\",\n  \"category\": \"SHELTER\",\n  \"title\": \"Laubhütten-Isolierunterstand ohne Feuer bauen (Debris Hut)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[GEFAHRENSTUFE: KRITISCH]\",\n  \"summary\": \"Wer in der Wildnis bei Regen und Kälte ungeschützt die Nacht verbringt, riskiert binnen 3 Stunden eine lebensgefährliche Unterkühlung. Wenn kein Feuer möglich ist, hält eine dicke Schicht aus Ästen und trockenem Laub wie ein Daunenschlafsack die eigene Körperwärme fest und sichert das Überleben.\",\n  \"timeRequired\": \"90–120 MINUTEN\",\n  \"successRate\": \"92% (Laubstärke ≥ 60cm)\",\n  \"difficulty\": \"Stufe 1 (Ohne Werkzeug machbar)\",\n  \"outputPerHour\": \"1 Isolierunterstand für 1 Person / 2 Std.\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Zentraler Firstbalken (Langer Stamm)\",\n      \"desc\": \"Ein gerader, stabiler Ast (3.0~3.5m lang, 10~15cm stark), der das Gesamtgewicht tragen kann.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"2 Y-Stützhölzer und Rippenäste\",\n      \"desc\": \"Zwei brusthohe (1.5m) Gabeläste und 40~50 armlange (1~1.5m) Äste für die seitliche Rippenwand.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Staubtrockenes Laub und Gras (Große Mengen)\",\n      \"desc\": \"Völlig feuchtigkeitsfreies Laub, Kiefernnadeln und trockenes Gras in großen Mengen.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Schritt 1: Y-Gabelstützen aufstellen und Firstbalken auflegen\",\n      \"description\": \"1. **Y-Stützen verzahnen**: Stellen Sie zwei stabile Y-Gabelhölzer gegenüber auf, um ein Dreibein in **0.8~1.0m Höhe** zu bilden.\\n2. **Firstbalken auflegen**: Legen Sie ein Ende des **3.0~3.5m langen Stammes** in die Gabel und verankern Sie das andere Ende fest im Boden gegen den Wind.\\n3. **Körpernahes Sargmaß prüfen**: Halten Sie den Innenraum so eng, dass neben den Schultern nur **eine Faustbreite (ca. 10cm Spielraum)** frei bleibt.\",\n      \"actionNote\": \"> Volumen-Minimierung: Ist der Raum zu groß, reicht die Körperwärme nicht aus, um die Luft zu erwärmen. Nur ein eng anliegender Raum hält warm wie ein Schlafsack.\",\n      \"svgFileName\": \"pr03-step-01.svg\",\n      \"svgLabels\": [\n        \"CRITICAL VOLUME RULE [INNENVOLUMEN]:\",\n        \"Striktes Sargmaß: max. +10cm (1 Faust) Körperabstand\",\n        \"WINDWARD (Windseitiger Anker)\",\n        \"MAIN RIDGEPOLE: 3.0~3.5m (Firstbalken)\",\n        \"Y-BIPOD & VINE LASHING (Y-Stützverbindung)\",\n        \"COFFIN CLEARANCE: +10cm (Max. 1 Faust Spielraum)\",\n        \"HEIGHT: 0.8~1.0m\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"Innenvolumen-Minimierung und metabolische Strahlungswärme\",\n        \"text\": \"Die einzige Wärmequelle im ungeheizten Notunterstand ist die eigene Körperwärme (**ca. 100W Strahlungsleistung**). Ein zu großer Innenraum führt zu konvektivem Wärmeverlust. Ein passgenaues Sargmaß stoppt Luftströmungen und isoliert die Wärme optimal.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Schritt 2: Rippenäste im 45°-Winkel anlehnen und 40cm Laubmatte packen\",\n      \"description\": \"1. **Rippen im 45-Grad-Winkel aufstellen**: Lehnen Sie 40~50 Äste beidseitig im **Winkel von 45°~60°** lückenlos dicht an den Firstbalken.\\n2. **40cm Bodenisolierung einbringen**: Füllen Sie den Boden kniehoch mit trockenem Laub (**mindestens 40cm Dicke**).\\n3. **Komprimierte Stärke prüfen**: Legen Sie sich hinein; stellen Sie sicher, dass unter Körpergewicht noch **mindestens 20cm komprimierte Isolierschicht** verbleiben.\",\n      \"actionNote\": \"> Kälteschutz von unten: Der gefrorene Erdboden leitet Wärme 20-mal schneller ab als Luft. Die Bodenmatte ist wichtiger als das Dach.\",\n      \"svgFileName\": \"pr03-step-02.svg\",\n      \"svgLabels\": [\n        \"THERMAL CONDUCTION SHIELD [BODENISOLIERUNG]:\",\n        \"Bodenkälte blockieren: ≥15~20cm komprimierte Matte\",\n        \"RIDGEPOLE SPINE (Firstbalken-Schnitt)\",\n        \"RIB LATTICE: 45°~60° (Rippengitter)\",\n        \"MATTRESS: 40cm → 20cm (Laubmatratze)\",\n        \"GROUND COLD CONDUCTION BLOCKED\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PHYSICS\",\n        \"title\": \"Boden-Wärmeleitung und ruhende Luftpolster-Isolierung\",\n        \"text\": \"Direkter Bodenkontakt entzieht Körperwärme **20-mal schneller** als ruhende Luft. Trockenes Laub schließt zahllose mikroskopische Luftpolster ein, deren Wärmeleitfähigkeit mit nur **0.025 W/m·K** extrem gering ist und Bodenfrost abwehrt.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Schritt 3: 60~90cm Laub aufschichten und Eingang verschließen\",\n      \"description\": \"1. **Reisig-Unterlage flechten**: Flechten Sie feine Zweige über die Rippen, damit kein Laub in den Schlafraum rieselt.\\n2. **60~90cm dicke Laubwand aufhäufen**: Schichten Sie trockenes Laub von unten bis zum First in **armlanger Dicke (60~90cm)** auf.\\n3. **Mit schweren Ästen beschweren**: Legen Sie schwere Äste gitterförmig darüber, damit der Wind das Laub nicht verweht.\\n4. **Eingang mit Laubpfropfen dichten**: Kriechen Sie hinein und verschließen Sie den Eingang mit einem dichten Laubballen gegen Kaltluft.\",\n      \"actionNote\": \"> Nur trockenes Laub verwenden: Nasses Laub verdunstet Feuchtigkeit und entzieht dem Körper rasch Wärme. Verwenden Sie ausschließlich rascheltrockenes Laub.\",\n      \"svgFileName\": \"pr03-step-03.svg\",\n      \"svgLabels\": [\n        \"INSULATION & SEALING [WANDAUFBAU]:\",\n        \"60~90cm trockene Laubschicht + Eingangspfropfen\",\n        \"DEBRIS WALL: 60~90cm (Laubdämmung)\",\n        \"DEADWOOD ARMOR (Windschutz-Äste)\",\n        \"WATER SHEDDING SLOPE (Regenablauf)\",\n        \"DEAD AIR CORE & PLUG SEAL (Thermokammer)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD ARCHITECTURE\",\n        \"title\": \"Steildach-Wasserabführung und natürliche Schindelwirkung\",\n        \"text\": \"Wenn Laub auf einer steilen **45-Grad-Neigung** über **60cm dick** aufgeschichtet wird, wirken die wachsartigen Blattoberflächen und die Überlappung wie Dachziegel, die Regenwasser außen ableiten.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Fataler Fehler: Zu große Hütte für Sitzkomfort bauen oder feuchtes Laub nutzen\",\n    \"description\": \"Wer die Decke für Sitzkomfort erhöht, erzeugt ein großes Kaltluftvolumen, das die Körperwärme (ca. 100W) nicht heizen kann. Feuchtes Laub verwandelt die Hütte zudem in einen Eiskeller.\",\n    \"consequence\": \"Folge: Leitungs- und Konvektionsverluste senken die Körperkerntemperatur im Schlaf unter 30°C und führen zum Kältetod.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr03-outcome.svg\",\n    \"title\": \"Vollendeter A-Rahmen-Laubhütten-Isolierunterstand\",\n    \"description\": \"Ein 2.5m schwerer Firstbalken und ein 45°-Rippenrahmen, bedeckt von 1 Meter komprimiertem trockenem Laub und Schutzästen, die Körperwärme bei Minustemperaturen ohne Feuer halten.\"\n  },\n  \"createdAt\": \"2026-10-09T16:08:00.000Z\",\n  \"updatedAt\": \"2026-10-15T16:00:00+09:00\",\n  \"contentHash\": \"5c83ac034006645f\"\n}","content/protocols/locales/03-프로토콜-03-데브리-헛-debris-hut-a프레임-단열-은신처-구축법.en.json":"{\n  \"protocolId\": \"PR-03\",\n  \"category\": \"SHELTER\",\n  \"title\": \"A-Frame Debris Hut Thermal Shelter (Emergency Primitive Bivouac)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[THREAT LEVEL: CRITICAL]\",\n  \"summary\": \"Surviving sub-zero wilderness without fire requires trapping your metabolic body heat like a heavy down sleeping bag. By interlocking an A-frame ridgepole spine and banking a 1-meter mound of dry forest leaves, this debris hut maintains internal warmth even in freezing rains and howling gales.\",\n  \"timeRequired\": \"90–120 MINUTES\",\n  \"successRate\": \"92% (Leaf Depth ≥ 60cm)\",\n  \"difficulty\": \"Tier 1 (Zero Modern Tools)\",\n  \"outputPerHour\": \"1 Survival Shelter / 2 Hours\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Main Ridgepole (Spine Timber)\",\n      \"desc\": \"One straight, sturdy hardwood limb (3.0–3.5m length, 10–15cm diameter) capable of bearing deadweight\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Y-Bipod Fork Sticks & Rib Poles\",\n      \"desc\": \"Two 1.5m chest-high Y-forked branch posts and 40–50 arm-length (1–1.5m) rib branches for the wall lattice\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Dry Forest Debris (Thermal Mass)\",\n      \"desc\": \"2–3m³ of bone-dry leaves, pine needles, dry ferns, and shredded bark\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Step 1: Erect A-Frame Bipod and Seat Ridgepole\",\n      \"description\": \"1. **Interlock Y-Bipod Posts**: Stand two sturdy Y-forked branches facing each other to create a stable tripod apex **0.8–1.0m above ground**.\\n2. **Anchor Ridgepole Spine**: Seat one end of the **3.0–3.5m hardwood ridgepole** securely into the bipod fork and ground the tail end firmly into the windward soil.\\n3. **Verify Coffin Sizing**: Ensure the interior width leaves only **one fist of clearance (about 10cm)** around your shoulders when lying down.\",\n      \"actionNote\": \"> Volume Minimization Rule: An oversized interior cannot be heated by human body warmth. Keep the interior strictly form-fitting to trap thermal air pockets.\",\n      \"svgFileName\": \"pr03-step-01.svg\",\n      \"svgLabels\": [\n        \"CRITICAL VOLUME RULE [INTERIOR SPEC]:\",\n        \"Strict Coffin Spec: max +10cm (1 fist) body clearance\",\n        \"WINDWARD (Ground Anchor)\",\n        \"MAIN RIDGEPOLE: 3.0~3.5m (Hardwood Spine)\",\n        \"Y-BIPOD & VINE LASHING (Apex Joint)\",\n        \"COFFIN CLEARANCE: +10cm (1 Fist Max Gap)\",\n        \"HEIGHT: 0.8~1.0m\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"Interior Volume Minimization & Metabolic Radiative Heat Trapping\",\n        \"text\": \"The sole thermal heat source in a non-heated emergency shelter is human basal metabolic radiation (**approx. 100W**). An oversized interior creates a convective sink that exhausts body heat. Sizing the cabin strictly like a coffin eliminates air draft and holds trapped air at a comfortable temperature.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Step 2: Lay Rib Poles at 45° and Pack 40cm Dry Leaf Bed\",\n      \"description\": \"1. **Lay 45-Degree Rib Lattice**: Lean 40–50 rib sticks against both sides of the spine at a steep **45°–60° angle** like closely spaced ribs.\\n2. **Pack 40cm Dry Leaf Mattress**: Pile bone-dry leaves, pine needles, and dry grass over the bare ground to **at least 40cm depth**.\\n3. **Verify Compressed Thickness**: Lie down to compress the bed; verify that **at least 20cm of dead-air insulation** remains between your back and the soil.\",\n      \"actionNote\": \"> Conductive Heat Shield: Bare frozen soil conducts body heat away 20 times faster than air. A thick dry mattress is even more vital than the roof.\",\n      \"svgFileName\": \"pr03-step-02.svg\",\n      \"svgLabels\": [\n        \"THERMAL CONDUCTION SHIELD [FLOOR INSULATION]:\",\n        \"Block ground conduction: keep ≥15~20cm compressed bed\",\n        \"RIDGEPOLE SPINE (Cross-Section)\",\n        \"RIB LATTICE: 45°~60° (Branch Grid)\",\n        \"MATTRESS: 40cm → 20cm (Leaf Bed)\",\n        \"GROUND COLD CONDUCTION BLOCKED\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PHYSICS\",\n        \"title\": \"Ground Thermal Conduction & Dead Air Space Insulation Mechanics\",\n        \"text\": \"Direct contact with cold soil drains core body heat **20 times faster** than still air. Dry leaves contain countless microscopic dead-air pockets with an exceptionally low thermal conductivity of **0.025 W/m·K**, creating an impenetrable barrier against ground frost.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Step 3: Mound 60–90cm Debris Walls and Seal Entrance\",\n      \"description\": \"1. **Weave Twig Underlay**: Cover rib poles with fine dry twigs to prevent leaves from falling through into the sleeping space.\\n2. **Bank 60–90cm Debris Wall**: Mound dry leaves from the ground up to the ridgepole to a **depth of 60–90cm (full arm's length)**.\\n3. **Weight Down with Armor Branches**: Lay heavy dead branches across the mound in a crosshatch pattern to pin down leaves against storm gusts.\\n4. **Seal Entrance with Leaf Plug**: Crawl inside feet first and pull a dense bundle of dry leaves into the doorway to block all outside drafts.\",\n      \"actionNote\": \"> Bone-Dry Rule: Mixing wet leaves ruins insulation and causes severe evaporative chilling. Use exclusively crisp, dry forest floor debris.\",\n      \"svgFileName\": \"pr03-step-03.svg\",\n      \"svgLabels\": [\n        \"INSULATION & SEALING [WALL SPEC]:\",\n        \"60~90cm dry leaf mound + full entrance plug seal\",\n        \"DEBRIS WALL: 60~90cm (Dry Leaves)\",\n        \"DEADWOOD ARMOR (Wind-Weight Branches)\",\n        \"WATER SHEDDING SLOPE (Rain Drain)\",\n        \"DEAD AIR CORE & PLUG SEAL (Thermal Chamber)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD ARCHITECTURE\",\n        \"title\": \"Steep Slope Water Shedding & Multi-Layered Natural Shingling\",\n        \"text\": \"When dry debris is piled **60cm thick** on a **steep 45° slope**, leaf surface waxes and interlocking multi-layer structures act like roof shingles, forcing rainwater to run down the outside without penetrating the sleeping core.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Fatal Error: Building an Oversized Cabin & Mixing Wet Debris\",\n    \"description\": \"Raising the ceiling for sitting comfort creates a large air pocket that human basal metabolism (80–100W) cannot heat. Furthermore, packing damp leaves into the floor or walls turns the shelter into a conductive evaporative cooler.\",\n    \"consequence\": \"Consequence: Combined conductive and convective heat loss drops core body temperature below 30°C during sleep, causing fatal hypothermia.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr03-outcome.svg\",\n    \"title\": \"Completed A-Frame Debris Hut Thermal Shelter\",\n    \"description\": \"A 2.5m heavy ridgepole and 45° rib frame blanketed by 1 meter of compressed dry leaves and thatch branches, trapping body heat down to sub-zero temperatures without fire.\"\n  },\n  \"createdAt\": \"2026-10-09T16:08:00.000Z\",\n  \"updatedAt\": \"2026-10-15T16:00:00+09:00\",\n  \"contentHash\": \"5c83ac034006645f\"\n}","content/protocols/locales/03-프로토콜-03-데브리-헛-debris-hut-a프레임-단열-은신처-구축법.es.json":"{\n  \"protocolId\": \"PR-03\",\n  \"category\": \"SHELTER\",\n  \"title\": \"Cómo construir un refugio de hojarasca para retener calor sin fuego (Debris Hut)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[NIVEL DE AMENAZA: CRÍTICO]\",\n  \"summary\": \"Pasar la noche a la intemperie con viento y lluvia reduce la temperatura corporal en menos de 3 horas provocando hipotermia. Cuando no es posible encender fuego, apilar ramas y una gruesa capa de hojas secas retiene el calor corporal como un saco de dormir grueso para pasar la noche a salvo.\",\n  \"timeRequired\": \"90–120 MINUTOS\",\n  \"successRate\": \"92% (Espesor de hojas ≥ 60cm)\",\n  \"difficulty\": \"Nivel 1 (Sin herramientas)\",\n  \"outputPerHour\": \"1 Refugio para 1 persona / 2 Horas\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Viga cumbrera principal (Tronco largo)\",\n      \"desc\": \"Un tronco recto y resistente de 3.0~3.5m de largo y 10~15cm de grosor capaz de soportar peso.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"2 postes en Y y ramas laterales\",\n      \"desc\": \"Dos ramas en horquilla a la altura del pecho (1.5m) y 40~50 ramas de 1~1.5m para formar las costillas laterales.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Hojas secas y hierba seca en abundancia\",\n      \"desc\": \"Hojas secas, acículas de pino y hierba sin nada de humedad en gran cantidad (decenas de sacos).\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Paso 1: Levantar el bípode en Y y asentar la viga cumbrera\",\n      \"description\": \"1. **Cruzar postes en Y**: Enfrente dos ramas en horquilla para formar un bípode a una **altura de 0.8~1.0m**.\\n2. **Apoyar viga cumbrera**: Apoye un extremo del tronco de **3.0~3.5m** en la horquilla y ancle el otro extremo firmemente al suelo contra el viento.\\n3. **Ajustar tamaño al cuerpo**: Deje solo **un puño de espacio libre (unos 10cm)** a los lados de los hombros para que el refugio sea estrecho.\",\n      \"actionNote\": \"> Regla de espacio mínimo: Si el interior es amplio, el calor corporal no alcanza para calentar el aire. Mantenerlo ajustado como un ataúd retiene el calor.\",\n      \"svgFileName\": \"pr03-step-01.svg\",\n      \"svgLabels\": [\n        \"CRITICAL VOLUME RULE [VOLUMEN INTERIOR]:\",\n        \"Espacio tipo ataúd: máx. +10cm (1 puño) de holgura\",\n        \"WINDWARD (Anclaje Barlovento)\",\n        \"MAIN RIDGEPOLE: 3.0~3.5m (Viga Cumbrera)\",\n        \"Y-BIPOD & VINE LASHING (Unión en Y)\",\n        \"COFFIN CLEARANCE: +10cm (Holgura 1 Puño)\",\n        \"HEIGHT: 0.8~1.0m\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"Minimización del volumen interior y autorretención de calor radiante\",\n        \"text\": \"La única fuente de calor en este refugio de emergencia es la radiación metabólica humana (**unos 100W**). Un espacio excesivo disipa el calor por convección. Reducir el habitáculo al tamaño exacto del cuerpo evita corrientes y crea una bolsa de aire caliente.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Paso 2: Apoyar costillas a 45° y colocar colchón de hojas de 40cm\",\n      \"description\": \"1. **Disponer costillas a 45 grados**: Apoye 40~50 ramas a ambos lados de la viga en un **ángulo de 45°~60°** bien juntas.\\n2. **Colocar colchón aislante de 40cm**: Llene el suelo interior con hojas secas hasta la altura de la rodilla (**espesor mínimo de 40cm**).\\n3. **Comprobar espesor comprimido**: Acuéstese encima; verifique que al comprimirse con el peso queden al menos **20cm de colchón aislante** sobre la tierra.\",\n      \"actionNote\": \"> Escudo contra la conducción: La tierra fría roba calor 20 veces más rápido que el aire. El colchón del suelo es más importante que el propio techo.\",\n      \"svgFileName\": \"pr03-step-02.svg\",\n      \"svgLabels\": [\n        \"THERMAL CONDUCTION SHIELD [AISLAMIENTO BASAL]:\",\n        \"Bloquear conducción: mantener ≥15~20cm comprimido\",\n        \"RIDGEPOLE SPINE (Sección Cumbrera)\",\n        \"RIB LATTICE: 45°~60° (Costillas)\",\n        \"MATTRESS: 40cm → 20cm (Cama de Hojas)\",\n        \"GROUND COLD CONDUCTION BLOCKED\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PHYSICS\",\n        \"title\": \"Pérdida por conducción terrestre y colchón de aire estático\",\n        \"text\": \"El contacto directo con el suelo helado extrae calor **20 veces más rápido** que el aire quieto. La hojarasca seca encierra miles de microbolsas de aire con una conductividad de apenas **0.025 W/m·K**, bloqueando por completo la helada del suelo.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Paso 3: Apilar 60~90cm de hojas en el techo y sellar la entrada\",\n      \"description\": \"1. **Tejer base de ramitas**: Coloque ramas finas sobre las costillas para evitar que las hojas caigan al interior.\\n2. **Montículo de 60~90cm de hojas**: Apile hojas secas de abajo hacia arriba hasta alcanzar **60~90cm de grosor (la longitud del brazo)**.\\n3. **Fijar con ramas pesadas**: Disponga ramas pesadas enrejadas por encima para evitar que el viento vuele las hojas.\\n4. **Taponar la entrada con hojas**: Métase dentro y cierre la entrada con un fardo espeso de hojas secas para bloquear todo viento frío exterior.\",\n      \"actionNote\": \"> Solo hojas bien secas: Usar hojas húmedas roba calor por evaporación y enfría el cuerpo. Asegúrese de que las hojas estén completamente secas.\",\n      \"svgFileName\": \"pr03-step-03.svg\",\n      \"svgLabels\": [\n        \"INSULATION & SEALING [ESPEC. DE MURO]:\",\n        \"Muro de hojas de 60~90cm + tapón de entrada sellado\",\n        \"DEBRIS WALL: 60~90cm (Capa Aislante)\",\n        \"DEADWOOD ARMOR (Ramas de Peso)\",\n        \"WATER SHEDDING SLOPE (Drenaje)\",\n        \"DEAD AIR CORE & PLUG SEAL (Cámara Sellada)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD ARCHITECTURE\",\n        \"title\": \"Evacuación pluvial por pendiente pronunciada e impermeabilización natural\",\n        \"text\": \"Al apilar hojas con más de **60cm de grosor** sobre una pendiente de **45 grados**, la cutícula cerosa de las hojas y su estructura en capas actúan como tejas, evacuando el agua hacia el exterior sin gotear dentro.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Error fatal: Construir un refugio espacioso para estar sentado o usar hojas húmedas\",\n    \"description\": \"Hacer un techo alto para estar cómodo crea una masa de aire frío que el calor corporal (unos 100W) no puede calentar. Además, usar hojas húmedas convierte el refugio en una cámara frigorífica.\",\n    \"consequence\": \"Consecuencia: La pérdida combinada de calor por conducción y convección hace caer la temperatura corporal por debajo de 30°C durante el sueño, provocando hipotermia fatal.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr03-outcome.svg\",\n    \"title\": \"Refugio Térmico Debris Hut en A Completado\",\n    \"description\": \"Una viga pesada de 2.5m y un armazón de costillas a 45° cubiertos por 1 metro de hojas secas comprimidas y ramas, reteniendo el calor corporal a temperaturas bajo cero sin necesidad de fuego.\"\n  },\n  \"createdAt\": \"2026-10-09T16:08:00.000Z\",\n  \"updatedAt\": \"2026-10-15T16:00:00+09:00\",\n  \"contentHash\": \"5c83ac034006645f\"\n}","content/protocols/locales/03-프로토콜-03-데브리-헛-debris-hut-a프레임-단열-은신처-구축법.ja.json":"{\n  \"protocolId\": \"PR-03\",\n  \"category\": \"SHELTER\",\n  \"title\": \"火を使わずに体温を守る落ち葉シェルターの作り方（デブリハット）\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[危険等級: 致命的(CRITICAL)]\",\n  \"summary\": \"冷たい風と雨にさらされる荒野で裸身で夜を過ごすと、3時間以内に体温が低下し生命の危機に陥ります。火を起こせない状況下で、周囲の木の枝と乾燥した落ち葉を厚く積み上げ、厚手の寝袋のように自らの体温を閉じ込めて暖かく眠るための必須技術です。\",\n  \"timeRequired\": \"90~120分\",\n  \"successRate\": \"92% (落葉厚60cm以上確保時)\",\n  \"difficulty\": \"第1等級 (道具不要)\",\n  \"outputPerHour\": \"1人用の保温シェルター1基完成\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"主棟木 (長い丸太1本)\",\n      \"desc\": \"大人の身長の約2倍の長さ(3.0~3.5m)、前腕の太さ(10~15cm)の頑丈でまっすぐな枯れ木1本。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Y字支柱2本と両側に立てかける枝\",\n      \"desc\": \"先端がY字に分かれた胸の高さ(1.5m)の木2本と、側壁を形成する腕の長さ(1~1.5m)の枝40~50本。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"完全に乾いた落ち葉と枯草 (大量)\",\n      \"desc\": \"湿気の全くない乾燥落ち葉、松葉、枯草を大きな袋数十袋分集めます。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"ステップ1：Y字支柱2本を立てて中心の棟木を架設する\",\n      \"description\": \"1. **Y字支柱の交差結束**: 先端がY字に分かれた頑丈な木2本を向かい合わせて上部を噛み合わせ、**高さ0.8~1.0m**の三脚支持部を作ります。\\n2. **棟木スパインの架設**: 長さ**3.0~3.5m**の太い棟木の一端を三脚に乗せ、反対側の端を風上側の地面にしっかり固定します。\\n3. **体型に合わせた容積制限**: 横たわった際に両肩の脇に拳1個分(**隙間約10cm**)だけが残るよう、内部幅を狭く保ちます。\",\n      \"actionNote\": \"> 容積最小化の法則: シェルター内部が広すぎると体温だけで空気を温められません。棺のように身体にぴったり沿う狭さにすることで温気を閉じ込めます。\",\n      \"svgFileName\": \"pr03-step-01.svg\",\n      \"svgLabels\": [\n        \"CRITICAL VOLUME RULE [内部容積規格]:\",\n        \"棺(Coffin)規格厳守: 身体周囲に拳1個(10cm)の余裕のみ\",\n        \"WINDWARD (風上側地面密着)\",\n        \"MAIN RIDGEPOLE: 3.0~3.5m (主棟木)\",\n        \"Y-BIPOD & VINE LASHING (Y字支柱結束)\",\n        \"COFFIN CLEARANCE: +10cm (拳1個分の隙間制限)\",\n        \"HEIGHT: 0.8~1.0m\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"内部容積最小化と人体放射熱による自己蓄熱の法則\",\n        \"text\": \"無暖房の野戦避難所における唯一の熱源は人間の体温(**約100Wの放射熱**)です。空間が広いと体温が対流で奪われ低体温症に至ります。体型に合わせて容積を最小化することで空気の対流を防ぎ、厚手の寝袋のように温気を保ちます。\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"ステップ2：両脇に枝を密に立てかけ、床に落ち葉を厚く敷く\",\n      \"description\": \"1. **肋木枝の45度配置**: 中心棟木の両脇に40~50本の枝を**45~60度の角度**で隙間なく密に立てかけます。\\n2. **床面冷気遮断材の投入**: 地面からの底冷えを防ぐため、床一面に乾燥落ち葉を膝の高さ(**厚さ40cm以上**)まで敷き詰めます。\\n3. **体重圧縮後の厚み確認**: 人が横たわり体重で押し潰されても、最低一握り分(**圧縮後厚さ20cm以上**)の空気断熱層が残ることを確認します。\",\n      \"actionNote\": \"> 伝導冷気の防御: 冷たい地面は空気の20倍の速さで体温を奪います。屋根よりも床の落ち葉ベッドを厚く敷くことが生存の要です。\",\n      \"svgFileName\": \"pr03-step-02.svg\",\n      \"svgLabels\": [\n        \"THERMAL CONDUCTION SHIELD [床断熱原則]:\",\n        \"地面熱伝導遮断: 圧縮後も最低15~20cm厚を維持\",\n        \"RIDGEPOLE SPINE (中心棟木断面)\",\n        \"RIB LATTICE: 45°~60° (肋木格子壁)\",\n        \"MATTRESS: 40cm → 20cm (落葉寝床)\",\n        \"GROUND COLD CONDUCTION BLOCKED (地面冷気遮断)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PHYSICS\",\n        \"title\": \"地表面伝導熱損失と乾燥落ち葉の静止空気断熱層\",\n        \"text\": \"冷たい地面との直接接触による熱伝導損失は、空気中の対流損失の**20倍以上**に達します。乾燥落ち葉内部の無数の微細空気ポケットは熱伝導率が**0.025W/m・K**と極めて低く、地面からの氷点下の冷気を完全に遮断します。\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"ステップ3：屋根に落ち葉を腕の長さ分積み上げ、重い枝で押さえる\",\n      \"description\": \"1. **小枝の格子下地を配置**: 肋木の上に細い小枝を編み、落ち葉が室内へこぼれ落ちない受け網を作ります。\\n2. **外壁落葉を60~90cm積層**: 地面から屋根の天辺まで、乾燥落ち葉を腕全体の長さ(**厚さ60~90cm**)で山のように厚く積み上げます。\\n3. **防風用上掛け枝の固定**: 強風で落ち葉が飛ばされないよう、重い木の枝を格子状に乗せてしっかり押さえます。\\n4. **落葉プラグで入口密閉**: 内部へ潜り込んだ後、入口を乾燥落ち葉の束で完全に塞ぎ、冷気の流入を遮断します。\",\n      \"actionNote\": \"> 完全乾燥の徹底: 湿った落ち葉を混ぜると気化熱により逆に体温が急速に奪われます。必ずカラカラに乾いた落ち葉のみを使用してください。\",\n      \"svgFileName\": \"pr03-step-03.svg\",\n      \"svgLabels\": [\n        \"INSULATION & SEALING [断熱積層規格]:\",\n        \"外壁60~90cm乾燥落葉積層 + 入口プラグ完全密閉\",\n        \"DEBRIS WALL: 60~90cm (落葉断熱層)\",\n        \"DEADWOOD ARMOR (防風荷重枝)\",\n        \"WATER SHEDDING SLOPE (排水傾斜)\",\n        \"DEAD AIR CORE & PLUG SEAL (静止空気層・入口栓)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD ARCHITECTURE\",\n        \"title\": \"急傾斜による雨水排水と多層落ち葉の自然防水構造\",\n        \"text\": \"落ち葉を**45度以上**の急傾斜で**60cm以上**積み上げると、葉表面のワックス層と多層重合構造が屋根瓦のように機能し、雨水が内部へ染み込まず外側を伝って自然に流れ落ちます。\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命的誤認: 快適性のための大型空間確保および湿った落ち葉の使用\",\n    \"description\": \"座って休めるように天井を高くすると、人間の基礎代謝(約80〜100W)では内部空気を温めきれず体温が急速に奪われる。また湿った落ち葉を混ぜると高い熱容量と気化熱により氷の洞窟のような冷却装置へと変質する。\",\n    \"consequence\": \"誤判断時の結末: 睡眠中の伝導・対流複合熱損失により深部体温が30°C以下に急降下し、致命的な低体温症(Hypothermia)で死亡。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr03-outcome.svg\",\n    \"title\": \"Aフレーム デブリハット (落葉断熱シェルター) 完成外観\",\n    \"description\": \"2.5mの頑丈な棟木と45度肋木フレームの上に1m厚の乾燥落葉層を圧縮積層し、防風格子枝を被せて強風と風雨を防ぐ無暖房体温保持シェルターの完成形態です。\"\n  },\n  \"createdAt\": \"2026-10-09T16:08:00.000Z\",\n  \"updatedAt\": \"2026-10-15T16:00:00+09:00\",\n  \"contentHash\": \"5c83ac034006645f\"\n}","content/protocols/locales/03-프로토콜-03-데브리-헛-debris-hut-a프레임-단열-은신처-구축법.pt.json":"{\n  \"protocolId\": \"PR-03\",\n  \"category\": \"SHELTER\",\n  \"title\": \"Como Construir um Abrigo de Folhas Secas para Reter Calor sem Fogo (Debris Hut)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[NÍVEL DE AMEAÇA: CRÍTICO]\",\n  \"summary\": \"Passar a noite ao relento sob chuva e vento frio reduz a temperatura corporal em menos de 3 horas, gerando hipotermia grave. Quando não for possível acender fogo, empilhar galhos e uma grossa camada de folhas secas retém o calor corporal como um saco de dormir espesso para sobreviver à noite.\",\n  \"timeRequired\": \"90–120 MINUTOS\",\n  \"successRate\": \"92% (Espessura de folhas ≥ 60cm)\",\n  \"difficulty\": \"Nível 1 (Sem ferramentas)\",\n  \"outputPerHour\": \"1 Abrigo para 1 pessoa / 2 Horas\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Viga mestra principal (Tronco longo)\",\n      \"desc\": \"Um tronco reto e resistente de 3.0~3.5m de comprimento e 10~15cm de diâmetro capaz de suportar peso.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"2 postes em Y e galhos laterais\",\n      \"desc\": \"Duas forquilhas na altura do peito (1.5m) e 40~50 galhos de 1~1.5m para formar as costelas laterais.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Folhas secas e capim seco em abundância\",\n      \"desc\": \"Folhas secas, acículas de pinheiro e capim sem qualquer umidade em grande volume (dezenas de sacos).\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Passo 1: Erguer o bipé em Y e assentar a viga mestra\",\n      \"description\": \"1. **Cruzar forquilhas em Y**: Apoie dois galhos em forquilha para formar um bipé com **altura de 0.8~1.0m**.\\n2. **Assentar viga mestra**: Coloque uma ponta do tronco de **3.0~3.5m** na forquilha e ancore a outra extremidade firmemente no solo contra o vento.\\n3. **Ajustar espaço ao corpo**: Mantenha a largura interna estreita, deixando apenas **um punho de folga (cerca de 10cm)** ao lado dos ombros.\",\n      \"actionNote\": \"> Regra do volume mínimo: Se o interior for espaçoso, o calor corporal não consegue aquecer o ar. Mantenha o abrigo justo como um caixão para reter o calor.\",\n      \"svgFileName\": \"pr03-step-01.svg\",\n      \"svgLabels\": [\n        \"CRITICAL VOLUME RULE [VOLUME INTERNO]:\",\n        \"Padrão caixão: máx. +10cm (1 punho) de folga corporal\",\n        \"WINDWARD (Fixação Barlavento)\",\n        \"MAIN RIDGEPOLE: 3.0~3.5m (Viga Mestra)\",\n        \"Y-BIPOD & VINE LASHING (Amarração em Y)\",\n        \"COFFIN CLEARANCE: +10cm (Folga Máx. 1 Punho)\",\n        \"HEIGHT: 0.8~1.0m\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"Minimização de volume interno e autorretenção de calor radiante\",\n        \"text\": \"A única fonte térmica neste abrigo de emergência é a radiação metabólica humana (**cerca de 100W**). Um espaço grande dissipa o calor por convecção. Reduzir a câmara ao contorno exato do corpo elimina correntes de ar e cria uma bolsa de ar quente.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Passo 2: Apoiar costelas a 45° e colocar colchão de folhas de 40cm\",\n      \"description\": \"1. **Dispor costelas a 45 graus**: Apoie 40~50 galhos em ambos os lados da viga em **ângulo de 45°~60°** bem próximos.\\n2. **Adicionar colchão de folhas de 40cm**: Forre o solo interior com folhas secas até a altura do joelho (**espessura mínima de 40cm**).\\n3. **Verificar espessura comprimida**: Deite-se sobre o leito; confirme que, sob o peso do corpo, restam pelo menos **20cm de colchão isolante** sobre a terra.\",\n      \"actionNote\": \"> Escudo contra condução: A terra fria rouba calor 20 vezes mais rápido que o ar. O colchão de folhas no chão é mais importante que o teto.\",\n      \"svgFileName\": \"pr03-step-02.svg\",\n      \"svgLabels\": [\n        \"THERMAL CONDUCTION SHIELD [ISOLAMENTO DO PISO]:\",\n        \"Bloquear condução do solo: manter ≥15~20cm comprimido\",\n        \"RIDGEPOLE SPINE (Seção da Viga)\",\n        \"RIB LATTICE: 45°~60° (Grade de Galhos)\",\n        \"MATTRESS: 40cm → 20cm (Colchão de Folhas)\",\n        \"GROUND COLD CONDUCTION BLOCKED\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PHYSICS\",\n        \"title\": \"Perda por condução do solo e colchão de ar estático\",\n        \"text\": \"O contato direto com o solo gelado drena calor **20 vezes mais rápido** que o ar parado. A folhagem seca aprisiona milhares de microbolsas de ar com condutividade de apenas **0.025 W/m·K**, bloqueando totalmente o congelamento vindo do chão.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Passo 3: Empilhar 60~90cm de folhas no teto e vedar a entrada\",\n      \"description\": \"1. **Entrelaçar base de gravetos**: Coloque gravetos finos sobre as costelas para evitar que as folhas caiam no interior.\\n2. **Empilhar 60~90cm de folhas secas**: Acumule folhas secas de baixo até a cumeeira na **espessura de um braço inteiro (60~90cm)**.\\n3. **Prender com galhos de contrapeso**: Disponha galhos pesados em grade por cima para evitar que o vento espalhe as folhas.\\n4. **Vedar entrada com folhas**: Entre no abrigo e feche a entrada com um fardo denso de folhas secas para bloquear todo vento frio externo.\",\n      \"actionNote\": \"> Apenas folhas bem secas: Usar folhas úmidas rouba calor por evaporação e gela o corpo. Use exclusivamente folhagem completamente seca.\",\n      \"svgFileName\": \"pr03-step-03.svg\",\n      \"svgLabels\": [\n        \"INSULATION & SEALING [PAREDE TÉRMICA]:\",\n        \"60~90cm de folhas secas + tampão de entrada vedado\",\n        \"DEBRIS WALL: 60~90cm (Camada Isolante)\",\n        \"DEADWOOD ARMOR (Galhos de Contrapeso)\",\n        \"WATER SHEDDING SLOPE (Escoamento)\",\n        \"DEAD AIR CORE & PLUG SEAL (Cámara Vedada)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD ARCHITECTURE\",\n        \"title\": \"Escoamento pluvial em declive acentuado e impermeabilização natural\",\n        \"text\": \"Ao empilhar folhas com mais de **60cm de espessura** em uma inclinação íngreme de **45 graus**, a camada cerosa das folhas e a sobreposição agem como telhas, escoando a chuva para fora sem molhar o interior.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Erro fatal: Construir abrigo espaçoso para sentar ou usar folhas úmidas\",\n    \"description\": \"Fazer teto alto para ficar sentado cria um bolsão de ar frio que o calor do corpo (cerca de 100W) não consegue aquecer. Além disso, usar folhas úmidas transforma o abrigo em uma câmara fria.\",\n    \"consequence\": \"Consequência: A perda combinada por condução e convecção derruba a temperatura corporal abaixo de 30°C durante o sono, causando hipotermia fatal.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr03-outcome.svg\",\n    \"title\": \"Abrigo Térmico Debris Hut em A Concluído\",\n    \"description\": \"Uma viga pesada de 2.5m e armação de costelas a 45° cobertas por 1 metro de folhas secas compactadas e galhos, retendo o calor corporal em temperaturas negativas sem necessidade de fogo.\"\n  },\n  \"createdAt\": \"2026-10-09T16:08:00.000Z\",\n  \"updatedAt\": \"2026-10-15T16:00:00+09:00\",\n  \"contentHash\": \"5c83ac034006645f\"\n}","content/protocols/locales/03-프로토콜-03-데브리-헛-debris-hut-a프레임-단열-은신처-구축법.zh-TW.json":"{\n  \"protocolId\": \"PR-03\",\n  \"category\": \"SHELTER\",\n  \"title\": \"無火守護體溫的落葉小屋搭建法（Debris Hut）\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[重要度：必備生存]\",\n  \"summary\": \"在寒風暴雨的荒野中赤身過夜，3小時內核心體溫就會驟降至危險水準。無法生火時，利用身邊樹枝與乾燥落葉厚厚堆疊，如同厚睡袋般鎖住人體散發的熱量，實現溫暖過夜。\",\n  \"timeRequired\": \"90~120分鐘\",\n  \"successRate\": \"92% (落葉厚度達60cm以上時)\",\n  \"difficulty\": \"普通 (無需工具)\",\n  \"outputPerHour\": \"完成單人保溫落葉屋1座\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"主樑柱木（長原木1根）\",\n      \"desc\": \"長度約成人身高兩倍（3.0~3.5m）、粗細如前臂（10~15cm）的堅固筆直乾木1根。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Y型支撐木2根與兩側斜靠側枝\",\n      \"desc\": \"頂端呈Y型分叉的胸高（1.5m）樹枝2根，以及搭建兩側牆壁的手臂長（1~1.5m）枝條40~50根。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"完全乾燥的落葉與乾草（盡可能多）\",\n      \"desc\": \"毫無濕氣的乾落葉、松針、乾草，收集相當於數十個大麻袋的充足份量。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"第1步：立起2根Y型支撐柱並架設中央主樑\",\n      \"description\": \"1. **Y型支架交叉咬合**：將兩根頂端分叉的結實樹枝相對立起咬合，搭成**高度80cm~1m**的三角支撐架。\\n2. **中央脊樑穩固架設**：將長度**3.0~3.5m**的粗原木一端搭在三腳架頂端，另一端牢牢固定在迎風面地面。\\n3. **身型契合規格檢查**：躺下時肩膀兩側僅保留一拳寬度，將**多餘空間控制在約10cm**以內保持狹窄。\",\n      \"actionNote\": \"> 容積最小化法則：內部過於寬敞則人體散發的熱量無法溫熱空氣。必須緊貼身型保持狹窄，才能如睡袋般鎖住溫暖。\",\n      \"svgFileName\": \"pr03-step-01.svg\",\n      \"svgLabels\": [\n        \"CRITICAL VOLUME RULE [內部體積規格]:\",\n        \"嚴守棺木規格：身體周圍僅留1個拳頭(10cm)裕度\",\n        \"WINDWARD (迎風面地面錨定)\",\n        \"MAIN RIDGEPOLE: 3.0~3.5m (主脊柱木)\",\n        \"Y-BIPOD & VINE LASHING (Y型支撐綁紮)\",\n        \"COFFIN CLEARANCE: +10cm (僅限1拳間隙)\",\n        \"HEIGHT: 0.8~1.0m\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"內部體積最小化與人體輻射熱自體蓄熱法則\",\n        \"text\": \"無暖氣野外避難所唯一的熱源是人體散發的體溫（**約100W輻射熱**）。內部空間過大時無法加熱空氣，極易陷入失溫。緊密貼合身型極小化空間體積，才能阻斷空氣對流，僅憑體溫如睡袋般鎖住暖意。\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"第2步：兩側緊密斜靠枝條並在地面鋪設厚落葉層\",\n      \"description\": \"1. **肋骨枝條45度排列**：在主樑兩側以**45~60度角**緊密斜靠40~50根樹枝，不留明顯縫隙。\\n2. **地面阻寒材料鋪設**：在地面堆鋪完全乾燥的落葉達膝蓋高，即**厚度40cm以上**。\\n3. **體重受壓後厚度確認**：確認人躺下壓實後，仍能維持至少一掌寬的**壓實厚度20cm以上**。\",\n      \"actionNote\": \"> 傳導冷卻防禦：冰冷地面奪走體溫的速度比冷空氣快20倍。比起屋頂，地面的落葉被褥必須更加厚實才不至凍傷。\",\n      \"svgFileName\": \"pr03-step-02.svg\",\n      \"svgLabels\": [\n        \"THERMAL CONDUCTION SHIELD [地面斷熱原則]:\",\n        \"阻斷地面熱傳導：受壓後仍需維持15~20cm厚度\",\n        \"RIDGEPOLE SPINE (主脊柱木斷面)\",\n        \"RIB LATTICE: 45°~60° (肋骨格柵牆)\",\n        \"MATTRESS: 40cm → 20cm (落葉床墊)\",\n        \"GROUND COLD CONDUCTION BLOCKED (阻絕地面寒氣)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PHYSICS\",\n        \"title\": \"地面傳導熱損失與乾燥落葉的靜止空氣絕熱層\",\n        \"text\": \"與冰冷地面直接接觸造成的傳導熱損失比空氣對流**快20倍以上**。乾燥落葉內部的大量微細空氣層導熱係數僅為**0.025W/m·K**，能徹底阻絕自冰冷地面上升的寒氣。\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"第3步：屋頂堆疊手臂厚的落葉並覆蓋重枝防風\",\n      \"description\": \"1. **細枝阻擋網鋪設**：在枝條牆上編織乾燥細枝，防止外層落葉掉入內部。\\n2. **外壁落葉堆疊60~90cm**：將乾落葉從地面往上堆至屋脊，達到整條手臂長的**厚度60~90cm**。\\n3. **防風外壓枝條覆蓋**：以網格狀覆蓋沉重枯枝並向下壓實，防止強風吹散落葉。\\n4. **落葉門塞完全封閉**：鑽入小屋後用乾落葉球完全堵住門口，徹底阻隔外部冷風灌入。\",\n      \"actionNote\": \"> 嚴守乾燥落葉：若混入潮濕落葉，水分蒸發反而會急遽奪走體溫。務必僅挑選完全乾燥的落葉。\",\n      \"svgFileName\": \"pr03-step-03.svg\",\n      \"svgLabels\": [\n        \"INSULATION & SEALING [斷熱堆疊規格]:\",\n        \"外牆60~90cm乾落葉堆疊 + 入口落葉塞完全密封\",\n        \"DEBRIS WALL: 60~90cm (落葉斷熱層)\",\n        \"DEADWOOD ARMOR (防風壓重外枝)\",\n        \"WATER SHEDDING SLOPE (排水斜面)\",\n        \"DEAD AIR CORE & PLUG SEAL (靜止空氣層與入口塞)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD ARCHITECTURE\",\n        \"title\": \"陡坡雨水導流與多層落葉的天然防水機制\",\n        \"text\": \"落葉以**45度以上**陡坡堆疊達**60cm以上**時，葉片表面的天然蠟質成分與層疊結構如瓦片般發揮功效，雨水將自然順坡滑落而不滲入小屋內部。\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"絕不可犯的錯誤：為求舒適坐立而擴大空間或混用濕落葉\",\n    \"description\": \"若如帳篷般特意加高天花板並擴大空間，僅憑人體散發的熱量完全無法溫熱大空間內的冷空氣。此外，若鋪設潮濕落葉，夜間寒濕蒸發將導致體溫急速驟降。\",\n    \"consequence\": \"後果：必須搭建至僅容身體鑽入的狹小空間，並堆疊極厚的完全乾燥落葉，才能在無火之夜守住核心體溫。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr03-outcome.svg\",\n    \"title\": \"A字型落葉小屋（Debris Hut）完成外觀\",\n    \"description\": \"在2.5米粗主樑與45度肋骨支架上，緊密堆疊厚達1米的乾燥落葉層並覆蓋防風枝條網，完成阻隔強風暴雨、無需火源即可守護體溫的野外避難所外觀。\"\n  },\n  \"createdAt\": \"2026-10-09T16:08:00.000Z\",\n  \"updatedAt\": \"2026-10-15T16:00:00+09:00\",\n  \"contentHash\": \"5c83ac034006645f\"\n}","content/protocols/locales/04-stone-axe-making.de.json":"{\n  \"protocolId\": \"PR-04\",\n  \"category\": \"TOOLS\",\n  \"title\": \"Steinaxt aus Flusssteinen und Ranken bauen\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[WICHTIGKEIT: KERNWERKZEUG]\",\n  \"summary\": \"Mit bloßen Händen lassen sich keine dicken Äste für Unterschlupf oder Feuerholz fällen. So schlagen Sie zwei harte Flusssteine im 45-Grad-Winkel gegeneinander, um eine scharfe Steinklinge abzuspalten, und befestigen sie mit Kiefernharz und nasser Rankenrinde fest an einem Holzstiel.\",\n  \"timeRequired\": \"60 Min.\",\n  \"successRate\": \"90% (bei 45°-Schlag auf die Kante)\",\n  \"difficulty\": \"Mittel (Anfängerfreundlich)\",\n  \"outputPerHour\": \"1 fertige Steinaxt\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"1 harter Flussstein & 1 runder Schlagstein\",\n      \"desc\": \"Ein dichter Flussstein (etwa zwei Fäuste groß), der mit glasartigen, scharfen Kanten bricht, sowie ein schwerer runder Stein zum Zuschlagen.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Unterarmlanger Stiel aus Hartholz (Eiche oder Esche)\",\n      \"desc\": \"Ein zäher, frischer Ast (40–50cm lang, 3,5–4cm dick), der harte Schläge aushält, ohne zu brechen.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"In Wasser eingeweichte Ranken-Innenrinde & Kiefernharz\",\n      \"desc\": \"Mindestens 3 Meter nasse Innenrinde von Ranken (zieht sich beim Trocknen stark zusammen) und eine Handvoll festes Kiefernharz.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Steine im 45-Grad-Winkel schlagen, um eine scharfe Klinge abzuspalten\",\n      \"description\": \"1. **Amboss-Stein stabilisieren**: Platzieren Sie einen Flussstein von **Breite 15–20cm** wackelfrei flach auf dem Boden.\\n2. **Schlagpunkt anvisieren**: Zielen Sie exakt auf **1–2cm einwärts** vom äußeren Rand der Kante.\\n3. **45-Grad-Winkelschlag**: Schlagen Sie mit dem runden Schlagstein kraftvoll in einem präzisen **45-Grad-Winkel** auf die Kante.\\n4. **Klingenabschlag auslösen**: Spalten Sie eine handflächengroße Steinklinge mit rasiermesserscharfer Schneide und **1–2cm Dicke** ab.\",\n      \"actionNote\": \"> Schlagwinkel-Regel: Ein frontaler 90-Grad-Schlag in die Mitte zertrümmert den Stein zu nutzlosem Kies. Schlagen Sie stets die Kante im 45-Grad-Winkel für eine messerscharfe Schneide an.\",\n      \"svgFileName\": \"pr04-step-01.svg\",\n      \"svgLabels\": [\n        \"1. Runder Schlagstein\",\n        \"2. Kante mit 45° treffen\",\n        \"Scharfe Klinge (1-2cm)\",\n        \"4. Abgespaltene Axtklinge\",\n        \"3. Unterer Flussstein (15-20cm)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD GEOLOGY\",\n        \"title\": \"Muscheliger Bruch (Conchoidal Fracture) und Schockwellenlenkung\",\n        \"text\": \"Quarzit und Kieselgesteine besitzen keine Spaltebenen und brechen entlang konzentrischer Schockwellen im **muscheligen Bruch**. Ein Schlagwinkel von **45 Grad** lenkt die Bruchspannung entlang der Oberfläche ab und löst eine extrem scharfe Schneide von **1–2cm** Dicke ab.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Holzstiel oben spalten, Klinge einsetzen und mit Harz füllen\",\n      \"description\": \"1. **Riss-Stopp-Manschette binden**: Binden Sie **10cm unter** dem Stielende zuerst eine feste Schnur, um unkontrolliertes Aufspalten zu stoppen.\\n2. **Längsspalt einschneiden**: Spalten Sie die Spitze des Hartholzstiels mit einem scharfen Stein auf eine **Tiefe von 5–7cm** senkrecht ein.\\n3. **Klingenrücken tief einpassen**: Schieben Sie den dicken Rücken der Steinklinge vollständig und fest in den vorbereiteten Spalt.\\n4. **Harz-Kohle-Matrix einfüllen**: Mischen Sie geschmolzenes Kiefernharz mit feinem **Holzkohlepulver im Verhältnis 1:1** und verpressen Sie die Masse in alle Hohlräume.\",\n      \"actionNote\": \"> Komposit-Mischungsregel: Reines Kiefernharz wird nach dem Abkühlen glashart und spröde. Der Zusatz von Kohlepulver wirkt elastifizierend und erzeugt ein unzerbrechliches Natur-Epoxid. ([Kiefernharz-Kleber (PR-10)](/protocol-10.html) / [Holzkohlenmeiler (PR-09)](/protocol-09.html))\",\n      \"svgFileName\": \"pr04-step-02.svg\",\n      \"svgLabels\": [\n        \"1. Klinge von oben einsetzen\",\n        \"Scharfe Schneide\",\n        \"2. Holzspalt (5-7cm)\",\n        \"3. Harz + Holzkohlepulver\",\n        \"4. Unten abbinden gegen Risse\",\n        \"Stieldicke: 3,5-4cm\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD CHEMISTRY\",\n        \"title\": \"Terpenharz und Kohlenstoff-Partikelverbundwerkstoff\",\n        \"text\": \"Kiefernharz enthält Diterpensäuren, die beim Abkühlen polymerisieren, aber extrem spröde sind. Mikroskopische Kohlenstoffpartikel blockieren das Fortschreiten von Mikrorissen physikalisch und erzeugen einen **kohlefaserähnlichen Verbundwerkstoff** mit hoher Schlagabsorption.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Mit nasser Rankenrinde X-förmig umwickeln und im Schatten trocknen\",\n      \"description\": \"1. **Bastfaser-Wässerung**: Weichen Sie elastische Ranken-Innenrinde gründlich in Wasser ein, um maximale Faserdehnung zu erzielen.\\n2. **Diagonale X-Kreuzwicklung**: Wickeln Sie die nasse Rinde diagonal im X-Muster über Klinge und Stiel für **mindestens 10 straffe Touren**.\\n3. **Halsmanschetten-Arretierung**: Wickeln Sie das Faserende horizontal um den Halsansatz und sichern Sie es mit einem Zugknoten.\\n4. **Belüftete Schattentrocknung**: Lassen Sie die Axt an einem schattigen, windigen Ort vollständig aushärten, um maximale Schrumpfspannung zu erzielen.\",\n      \"actionNote\": \"> Schattentrocknungs-Prinzip: Niemals direkt am Lagerfeuer erhitzen, da Flammenhitze die Fasern versprödet. Bei langsamer Schattentrocknung schrumpft die Ranke um 30% und klemmt die Klinge wie Stahldraht ein. ([Wildseil (PR-05)](/protocol-05.html))\",\n      \"svgFileName\": \"pr04-step-03.svg\",\n      \"svgLabels\": [\n        \"1. Nasse Ranke X-Wicklung\",\n        \"2. Freie Schneidkante\",\n        \"3. Untere Querwicklung\",\n        \"4. Schrumpft 30% beim Trocknen\",\n        \"Fertig: Feste einteilige Steinaxt\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BOTANY\",\n        \"title\": \"Bastfaserschrumpfung durch Desikkation und radiale Klemmspannung\",\n        \"text\": \"Pflanzliche Bastfasern quellen bei Feuchtigkeitsaufnahme auf und erleiden beim Verdunsten des Wassers eine **Volumenkontraktion von bis zu 30%**. Die daraus resultierende radiale Ringspannung fixiert die Steinklinge formschlüssig wie eine Stahlverschraubung.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Häufiger Fehler: Flach in die Steinmitte schlagen oder trockene Ranken nutzen\",\n    \"description\": \"Wer im 90-Grad-Winkel flach auf die Steinmitte schlägt, erhält keine scharfe Klinge, sondern zertrümmert den Stein zu nutzlosem Kies. Wer trockene, spröde Ranken oder raue Außenrinde verwendet, riskiert, dass die Bindung beim ersten Schlag reißt und die schwere Steinklinge ins Gesicht fliegt.\",\n    \"consequence\": \"Ergebnis: Immer die Kante im 45-Grad-Winkel schlagen und eingeweichte Innenrinde im Schatten trocknen lassen.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr04-outcome.svg\",\n    \"title\": \"Vollendete primitive Steinaxt mit Ast- und Harzbindung\",\n    \"description\": \"Eine beidseitig geschlagene Feuersteinklinge, tief im gespaltenen Eichenstiel verankert, mit X-Kreuz-Lianenbindung verschnürt und mit Kiefernharz versiegelt.\"\n  },\n  \"createdAt\": \"2026-10-09T16:10:00.000Z\",\n  \"updatedAt\": \"2026-10-15T16:31:51+09:00\",\n  \"contentHash\": \"1c29ec86b6976738\"\n}","content/protocols/locales/04-stone-axe-making.en.json":"{\n  \"protocolId\": \"PR-04\",\n  \"category\": \"TOOLS\",\n  \"title\": \"How to Make a Stone Axe with River Stones and Vines\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[PRIORITY: CORE TOOL]\",\n  \"summary\": \"You cannot chop thick branches for shelter posts or firewood with your bare hands. Here is how to strike two hard river stones together at a 45-degree angle to split off a sharp stone blade, then lock it into a split wooden handle using pine resin and wet vine bark.\",\n  \"timeRequired\": \"60 mins\",\n  \"successRate\": \"90% (when striking the edge at 45°)\",\n  \"difficulty\": \"Medium (Beginner friendly)\",\n  \"outputPerHour\": \"1 Stone Axe Completed\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"1 Hard River Stone & 1 Round Hammerstone\",\n      \"desc\": \"One dense river stone (about the size of two fists) that breaks with sharp glass-like edges, plus one heavy round stone to hold and strike with.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Forearm-Length Hard Wooden Handle (Oak or Ash)\",\n      \"desc\": \"One tough green branch (40–50cm long, 3.5–4cm thick) that absorbs heavy impact without snapping.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Water-Soaked Vine Inner Bark & Pine Resin\",\n      \"desc\": \"At least 3 meters of wet inner vine bark (which shrinks and tightens as it dries) and a handful of hardened pine sap from tree bark.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Strike Stones Together at 45 Degrees to Split Off a Sharp Blade\",\n      \"description\": \"1. **Base Anvil Stabilization**: Brace a large river stone of **width 15–20cm** firmly flat on the ground so it cannot wobble.\\n2. **Target Impact Calibration**: Aim your strike point precisely at **1–2cm inside** the outer rim edge.\\n3. **45-Degree Bevel Strike**: Swing your round hammerstone forcefully down at an exact **45-degree angle** against the outer margin.\\n4. **Sharp Flake Selection**: Detach a palm-sized stone blade with a razor-sharp cutting edge and a thickness of **1–2cm**.\",\n      \"actionNote\": \"> Striking Angle Rule: Hitting flat in the center at 90 degrees shatters the entire stone into useless pebbles. You must strike the edge at 45 degrees to flake off a razor-sharp blade.\",\n      \"svgFileName\": \"pr04-step-01.svg\",\n      \"svgLabels\": [\n        \"1. Round Hammerstone\",\n        \"2. Strike Edge at 45°\",\n        \"Sharp Blade (1-2cm)\",\n        \"4. Split Stone Axe Blade\",\n        \"3. Base River Stone (15-20cm)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD GEOLOGY\",\n        \"title\": \"Conchoidal Fracture Mechanics and Shockwave Deflection\",\n        \"text\": \"Quartzite and cryptocrystalline silica lack cleavage planes and fracture in smooth, wave-like **conchoidal patterns**. Striking at a **45-degree angle** directs kinetic energy along the outer perimeter, spalling off an ultra-sharp cutting edge of **1–2cm** thickness.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Split the Top of the Wooden Handle, Wedge the Blade, and Fill with Resin\",\n      \"description\": \"1. **Anti-Split Collar Binding**: Tie cord tightly **10cm below** the handle top first to prevent uncontrolled splitting down the shaft.\\n2. **Longitudinal Notch Carving**: Split the top of the dense hardwood handle vertically to create a notch of **depth 5–7cm**.\\n3. **Deep Blade Seating**: Push the thick butt of the stone blade firmly and fully into the carved central slot.\\n4. **Charcoal-Resin Matrix Packing**: Melt pine sap and mix with powdered **charcoal in a 1:1 ratio**, packing the molten adhesive into every gap.\",\n      \"actionNote\": \"> Composite Mixing Rule: Pure pine resin cools brittle as glass and shatters on impact. Blending fine charcoal powder creates an impact-absorbing natural epoxy that never cracks. ([Pine Pitch Glue (PR-10)](/protocol-10.html) / [Oak Charcoal Kiln (PR-09)](/protocol-09.html))\",\n      \"svgFileName\": \"pr04-step-02.svg\",\n      \"svgLabels\": [\n        \"1. Push Blade Down In\",\n        \"Sharp Cutting Edge\",\n        \"2. Split Wood Slot (5-7cm)\",\n        \"3. Melted Resin + Charcoal\",\n        \"4. Tie Below Split First\",\n        \"Handle Width: 3.5-4cm\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD CHEMISTRY\",\n        \"title\": \"Terpene Resin and Carbon Particulate Composite Matrix\",\n        \"text\": \"Pine sap contains diterpenic acids that polymerize upon cooling but remain highly brittle. Adding microscopic carbon (charcoal) particles arrests crack propagation through micro-bridging, mirroring modern **carbon-epoxy composites** for field durability.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Wrap Tightly in an X-Pattern with Wet Vine Bark and Dry in the Shade\",\n      \"description\": \"1. **Bast Fiber Hydration**: Soak flexible inner vine bark in water to maximize cellular elasticity.\\n2. **Diagonal X-Lashing**: Criss-cross the wet bark diagonally around both stone blade and wooden haft for **at least 10 firm wraps**.\\n3. **Lower Shaft Collar Lock**: Wrap the remaining fiber horizontally around the lower neck and cinch tight with a secure knot.\\n4. **Ventilated Shade Cure**: Dry thoroughly in a breezy, shaded location away from direct sun to achieve maximum clamping force.\",\n      \"actionNote\": \"> Shade Drying Principle: Never force-dry over campfire flames as heat burns and snaps the delicate plant fibers. Natural air-drying in the shade causes the vine to shrink by 30%, locking the blade like steel wire. ([Wild Cordage (PR-05)](/protocol-05.html))\",\n      \"svgFileName\": \"pr04-step-03.svg\",\n      \"svgLabels\": [\n        \"1. Wet Vine X-Lashing\",\n        \"2. Exposed Sharp Edge\",\n        \"3. Lower Collar Wrap\",\n        \"4. Shrinks 30% When Dry\",\n        \"Finished: Solid One-Piece Stone Axe\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BOTANY\",\n        \"title\": \"Bast Fiber Desiccation Shrinkage and Radial Clamping Tension\",\n        \"text\": \"Bast fibers like kudzu and elm inner bark expand when hydrated and undergo **up to 30% radial contraction** as moisture evaporates. This mechanical shrinkage generates tremendous hoop stress, locking the lithic blade to the haft like an iron bolt.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Critical Mistake: Striking the Flat Center of the Rock or Binding with Dry Vines\",\n    \"description\": \"Smashing the flat center of a stone at 90 degrees shatters the rock into useless gravel instead of forming a sharp edge. Also, tying the blade with dry, brittle vines or rough outer bark will cause the lashing to snap on the first swing, sending a heavy stone blade flying toward your face or eyes.\",\n    \"consequence\": \"Result: Always strike the stone edge at 45 degrees for a clean blade, and lash with water-soaked inner bark dried slowly in the shade.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr04-outcome.svg\",\n    \"title\": \"Completed Primitive Chipped Stone Axe\",\n    \"description\": \"A bifacially flaked flint blade seated deeply into a split oak haft, bound firmly with criss-cross vine lashing and sealed with pine pitch resin composite.\"\n  },\n  \"createdAt\": \"2026-10-09T16:10:00.000Z\",\n  \"updatedAt\": \"2026-10-15T16:31:51+09:00\",\n  \"contentHash\": \"1c29ec86b6976738\"\n}","content/protocols/locales/04-stone-axe-making.es.json":"{\n  \"protocolId\": \"PR-04\",\n  \"category\": \"TOOLS\",\n  \"title\": \"Cómo hacer un hacha de piedra con rocas de río y lianas\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[IMPORTANCIA: HERRAMIENTA CLAVE]\",\n  \"summary\": \"Con las manos vacías no puedes cortar ramas gruesas para tu refugio o para leña. Aprende a golpear dos piedras duras de río en un ángulo de 45 grados para sacar una hoja afilada y fijarla en un mango de madera con resina de pino y corteza de liana húmeda.\",\n  \"timeRequired\": \"60 min\",\n  \"successRate\": \"90% (golpeando el borde a 45°)\",\n  \"difficulty\": \"Media (Apto para principiantes)\",\n  \"outputPerHour\": \"1 hacha de piedra lista\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"1 piedra dura de río y 1 piedra martillo redonda\",\n      \"desc\": \"Una piedra compacta de río (del tamaño de dos puños) que al romperse deje bordes afilados como vidrio, y una piedra redonda y pesada para golpear.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Mango de madera dura del largo del antebrazo (roble o fresno)\",\n      \"desc\": \"Una rama verde y resistente (40–50cm de largo y 3.5–4cm de grosor) que soporte golpes fuertes sin partirse.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Corteza interna de liana remojada y resina de pino\",\n      \"desc\": \"Más de 3 metros de corteza interna de liana húmeda (que se encoge y aprieta al secarse) y un puñado de resina de pino seca.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Golpear dos piedras a 45 grados para sacar una hoja afilada\",\n      \"description\": \"1. **Fijación de piedra yunque**: Apoya en el suelo una piedra de río de **ancho 15–20cm** de forma plana para que no se mueva.\\n2. **Calibración del punto de impacto**: Apunta con precisión a **1–2cm hacia adentro** del borde exterior de la roca.\\n3. **Impacto en bisel a 45 grados**: Descarga la piedra martillo redonda con fuerza en un ángulo exacto de **45 grados** contra el borde.\\n4. **Selección de lasca afilada**: Separa una hoja de piedra del tamaño de la palma con filo de navaja y un **grosor de 1–2cm**.\",\n      \"actionNote\": \"> Regla de ángulo de impacto: Golpear el centro plano a 90 grados destroza la roca en grava inútil. Golpea obligatoriamente el borde a 45 grados para desprender una hoja ultra afilada.\",\n      \"svgFileName\": \"pr04-step-01.svg\",\n      \"svgLabels\": [\n        \"1. Piedra martillo redonda\",\n        \"2. Golpear borde a 45°\",\n        \"Filo agudo (1-2cm)\",\n        \"4. Hoja de piedra separada\",\n        \"3. Piedra base (15-20cm)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD GEOLOGY\",\n        \"title\": \"Fractura concoidea y mecánica de dispersión de ondas de choque\",\n        \"text\": \"La cuarcita y el sílex carecen de planos de exfoliación y se fracturan en ondas suaves según el patrón de **fractura concoidea**. Aplicar el golpe a **45 grados** canaliza la energía hacia el perímetro externo, desprendiendo un filo cortante de **1–2cm** de grosor extremadamente afilado.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Rajar la punta del mango de madera, encajar la hoja y rellenar con resina\",\n      \"description\": \"1. **Ligadura de contención inferior**: Ata firmemente con cuerda a **10cm por debajo** de la punta del mango para evitar grietas incontroladas.\\n2. **Corte de hendidura longitudinal**: Con una piedra afilada, abre una ranura vertical de **profundidad 5–7cm** en el extremo del mango.\\n3. **Inserción profunda de la hoja**: Introduce la base gruesa de la lasca hasta el fondo de la ranura central.\\n4. **Relleno con compuesto de resina**: Funde resina de pino mezclada con **polvo de carbón en proporción 1:1**, rellenando cada hueco interno.\",\n      \"actionNote\": \"> Regla de mezcla compuesta: La resina pura se vuelve quebradiza como el vidrio al enfriarse. Mezclar polvo fino de carbón vegetal absorbe impactos y crea un epoxi natural irrompible. ([Pegamento de Resina (PR-10)](/protocol-10.html) / [Horno de Carbón (PR-09)](/protocol-09.html))\",\n      \"svgFileName\": \"pr04-step-02.svg\",\n      \"svgLabels\": [\n        \"1. Encajar hoja hacia abajo\",\n        \"Filo delantero\",\n        \"2. Ranura en madera (5-7cm)\",\n        \"3. Resina + polvo de carbón\",\n        \"4. Atar abajo para no rajar\",\n        \"Grosor del mango: 3.5-4cm\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD CHEMISTRY\",\n        \"title\": \"Resina terpénica y matriz compuesta de partículas de carbono\",\n        \"text\": \"Los ácidos diterpénicos de la resina de pino polimerizan al enfriarse pero son muy frágiles. Al añadir micropartículas de carbón vegetal, estas detienen la propagación de grietas, emulando la resistencia de los modernos **compuestos de fibra de carbono y epoxi**.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Atar fuerte en forma de X con liana húmeda y secar a la sombra\",\n      \"description\": \"1. **Hidratación de fibra floemática**: Remoja en agua la corteza interna de liana para maximizar su flexibilidad y elasticidad.\\n2. **Ligadura diagonal en X**: Cruza la fibra húmeda en diagonal sobre la piedra y el mango durante **al menos 10 vueltas tensas**.\\n3. **Bloqueo horizontal del cuello**: Enrolla la fibra sobrante en horizontal bajo la base y remata con un nudo de máxima tracción.\\n4. **Curado en sombra ventilada**: Deja secar por completo en un lugar sombreado y aireado lejos del sol directo para maximizar la presión.\",\n      \"actionNote\": \"> Principio de secado en sombra: Jamás seques junto a las llamas del fuego, ya que el calor quema y revienta las fibras. El secado natural a la sombra contrae la liana un 30%, aprisionando la hoja como alambre de acero. ([Cuerda Salvaje (PR-05)](/protocol-05.html))\",\n      \"svgFileName\": \"pr04-step-03.svg\",\n      \"svgLabels\": [\n        \"1. Amarre en X con liana\",\n        \"2. Filo cortante expuesto\",\n        \"3. Vueltas inferiores\",\n        \"4. Encoge 30% al secar\",\n        \"Listo: Hacha firme de una sola pieza\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BOTANY\",\n        \"title\": \"Contracción por desecación del floema y tensión radial de apriete\",\n        \"text\": \"Las fibras del líber (floema) se expanden al absorber agua y experimentan **hasta un 30% de contracción volumétrica** al evaporarse la humedad. Esta fuerza radial genera una tensión mecánica extrema que unifica la piedra y la madera como un perno de acero.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Error grave: Golpear el centro plano de la roca o atar con lianas secas\",\n    \"description\": \"Si golpeas el centro plano de la piedra a 90 grados, no saldrá ningún filo y toda la roca se romperá en grava inútil. Además, si atas con lianas secas o corteza exterior áspera, la cuerda se partirá al primer golpe y la piedra pesada puede salir disparada hacia tu cara o tus ojos.\",\n    \"consequence\": \"Resultado: Golpea siempre el borde a 45 grados y ata con fibra interna remojada en agua, secándola a la sombra.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr04-outcome.svg\",\n    \"title\": \"Hacha Primitiva de Piedra y Liana Completada\",\n    \"description\": \"Una hoja de pedernal tallada bifacialmente incrustada en un mango de roble hendido, atada firmemente en X con lianas y sellada con resina de pino.\"\n  },\n  \"createdAt\": \"2026-10-09T16:10:00.000Z\",\n  \"updatedAt\": \"2026-10-15T16:31:51+09:00\",\n  \"contentHash\": \"1c29ec86b6976738\"\n}","content/protocols/locales/04-stone-axe-making.ja.json":"{\n  \"protocolId\": \"PR-04\",\n  \"category\": \"TOOLS\",\n  \"title\": \"割った石とツルで作る木切り用の石斧\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[重要度: 基本道具]\",\n  \"summary\": \"素手では小屋の柱や薪にする太い枝を切ることはできません。河原の硬い石を45度の角度でぶつけて鋭い石の刃を割り出し、木の柄の割れ目に松ヤニと濡らしたツルの皮でしっかり固定して丈夫な石斧を作る方法です。\",\n  \"timeRequired\": \"60分\",\n  \"successRate\": \"90% (角を45度で叩いた場合)\",\n  \"difficulty\": \"普通 (初心者でも可能)\",\n  \"outputPerHour\": \"石斧 1本完成\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"硬い川石 1個と丸いハンマー石 1個\",\n      \"desc\": \"割れるとガラスのように鋭い縁ができる硬い川石（こぶし2個分）1個と、手に持って叩きつける丸くて重い石1個です。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"腕の長さの硬い木の枝（ナラやトネリコの生木）\",\n      \"desc\": \"強く振り下ろしても折れにくい丈夫な生木の枝（長さ40〜50cm、太さ3.5〜4cmほど）1本です。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"水に浸したツルの内皮と松ヤニ\",\n      \"desc\": \"乾くと縮んで強く締まるツルの内皮（長さ3m以上）と、松の木の傷口で固まった松ヤニひと握りです。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"石と石を45度の角度でぶつけて鋭い石の刃を割り出す\",\n      \"description\": \"1. **土台石の水平固定**: 地面に**幅15〜20cm**の大きな川石をガタつかないようしっかり安定させます。\\n2. **打撃位置の照準**: 石の縁から指関節1つ分である**1〜2cm内側**を正確な打撃ポイントに定めます。\\n3. **45度斜め打撃**: 手に持った丸いハンマー石で縁の角を**45度の角度**で斜めに力強く振り下ろします。\\n4. **鋭利な石刃の選別**: 手のひらサイズで刃の厚さが**1〜2cm**のカミソリのように鋭い石刃の破片を剥離させます。\",\n      \"actionNote\": \"> 打撃角度厳守: 平らな真ん中を90度垂直に叩くと衝撃が分散して石全体が粉々になります。必ず縁を45度で叩いて薄く鋭い刃を剥離させてください。\",\n      \"svgFileName\": \"pr04-step-01.svg\",\n      \"svgLabels\": [\n        \"① 丸いハンマー石（叩く石）\",\n        \"② 角を45°で斜めに叩く\",\n        \"鋭い石の刃（厚さ1〜2cm）\",\n        \"④ 剥がれた石斧の刃\",\n        \"③ 土台の川石（幅15〜20cm）\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD GEOLOGY\",\n        \"title\": \"貝殻状断口（Conchoidal Fracture）と衝撃波分散力学\",\n        \"text\": \"石英や珪岩は結晶面を持たず、強い打撃を受けると貝殻のような同心円状の波紋を描いて割れる**貝殻状断口**の性質を持ちます。打撃角度を**45度**に設定すると衝撃が表面に沿って誘導され、厚さ**1〜2cm**の極めて鋭利な切削刃が剥離します。\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"木の柄の上部を割って石の刃を挟み、松ヤニを詰める\",\n      \"description\": \"1. **柄の裂け防止仮縛り**: 枝が縦に割れ広がるのを防ぐため、先端から**10cm下**を丈夫な紐で先に固く縛ります。\\n2. **先端の縦割り加工**: 硬い生木の柄の上部を鋭い石で**深さ5〜7cm**の縦割れスリットを作ります。\\n3. **石刃の中心圧入**: 割れ目の奥深くまで石刃の厚みのある後端部をしっかり押し込みます。\\n4. **松ヤニ複合接着剤の充填**: 火で溶かした松ヤニに細かく砕いた**炭の粉を1:1の割合**で混ぜ、柄の隙間に隙間なく詰め込みます。\",\n      \"actionNote\": \"> 複合材の混合法則: 純粋な松ヤニだけを塗ると冷却後にガラスのように砕けます。炭の粉を混ぜることで衝撃吸収性が生まれ、割れない天然エポキシ接着剤になります。 ([松脂防水接着剤(PR-10)](/protocol-10.html) / [地下炭窯(PR-09)](/protocol-09.html))\",\n      \"svgFileName\": \"pr04-step-02.svg\",\n      \"svgLabels\": [\n        \"① 上から下へ石刃を差し込む\",\n        \"木を切る前の刃\",\n        \"② 割った木の隙間（5〜7cm）\",\n        \"③ 溶けた松ヤニ＋炭粉充填\",\n        \"④ 割れ止め用の下部縛り\",\n        \"生木の柄の太さ: 直径3.5〜4cm\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD CHEMISTRY\",\n        \"title\": \"テルペン樹脂と炭素微粒子の複合マトリックス（Composite Epoxy）物性\",\n        \"text\": \"松ヤニに含まれるテルペン酸は冷却固化時に脆化します。微小な炭素（木炭）粒子を複合添加すると微小亀裂の伝播を物理的に阻止し、現代の**カーボンエポキシ複合材**と同様の衝撃吸収耐性を獲得します。\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"濡れたツルの皮でX字に強く巻きつけて日陰で乾かす\",\n      \"description\": \"1. **靭皮繊維の水分浸漬**: 水に浸した柔軟なツルの内皮を十分に湿らせて弾力性を引き出します。\\n2. **対角X字クロス結束**: 石刃と木の柄を斜めのX字に交差させながら**最低10周以上**強く引き絞って巻き付けます。\\n3. **下部シャフト水平固定**: 残ったツルで柄の首元を水平に隙間なく巻き締めて固く結び止めます。\\n4. **通風日陰乾燥**: 直射日光を避け、風通しの良い日陰で完全乾燥させて圧着力を最大化します。\",\n      \"actionNote\": \"> 日陰乾燥の原則: 早く乾かそうと焚き火にかざすと熱で繊維が脆化して切れます。必ず風通しの良い日陰で自然乾燥させることで、繊維が30%縮んで鋼鉄のように刃を締め付けます。 ([野生ロープ製作(PR-05)](/protocol-05.html))\",\n      \"svgFileName\": \"pr04-step-03.svg\",\n      \"svgLabels\": [\n        \"① 濡れたツルをX字に巻く\",\n        \"② 鋭い石斧の先端\",\n        \"③ 柄の下側を横に強く巻く\",\n        \"④ 乾燥で30%縮んで圧着\",\n        \"完成状態: 強く叩いても抜けない一体型石斧\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BOTANY\",\n        \"title\": \"靭皮繊維の脱水収縮と放射方向クランプ張力固定\",\n        \"text\": \"クズやニレの内皮などの靭皮（Bast）植物繊維は、含水時に細胞壁が膨張し、乾燥脱水に伴って**最大30%の体積収縮**を起こします。この際に発生する強力なフープ応力が石刃と柄をボルトのように強固に一体化します。\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"絶対にしてはいけないミス: 平らな石の真ん中を叩く・乾いたツルで縛る\",\n    \"description\": \"石の平らな中央を90度で叩くと、鋭い刃ができずに石全体がただの砂利に砕けてしまいます。また、水に濡らしていない乾いたツルや硬い外皮で縛ると、木を叩いた瞬間に紐が切れ、重い石の刃が顔や目に飛んで大ケガをします。\",\n    \"consequence\": \"結果: 必ず石の角を45度で叩いて刃を作り、水に浸した丈夫な内皮でX字に巻いて日陰で乾かしてから安全に使ってください。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr04-outcome.svg\",\n    \"title\": \"割り石と葛蔓結束の原始石斧の完成形態\",\n    \"description\": \"硬い樫の木のY字柄の溝に両面打製された鋭利なフリント刃を深く噛み合わせ、強靭な葛蔓と松脂接着剤でX字十字結束した実戦石斧の完成形態です。\"\n  },\n  \"createdAt\": \"2026-10-09T16:10:00.000Z\",\n  \"updatedAt\": \"2026-10-15T16:31:51+09:00\",\n  \"contentHash\": \"1c29ec86b6976738\"\n}","content/protocols/locales/04-stone-axe-making.pt.json":"{\n  \"protocolId\": \"PR-04\",\n  \"category\": \"TOOLS\",\n  \"title\": \"Como fazer um machado de pedra com pedras de rio e cipó\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[IMPORTÂNCIA: FERRAMENTA ESSENCIAL]\",\n  \"summary\": \"Com as mãos vazias não é possível cortar galhos grossos para abrigo ou lenha. Veja como bater duas pedras duras de rio em um ângulo de 45 graus para tirar uma lâmina afiada e prendê-la em um cabo de madeira com resina de pinheiro e cipó úmido.\",\n  \"timeRequired\": \"60 min\",\n  \"successRate\": \"90% (batendo na borda a 45°)\",\n  \"difficulty\": \"Média (Iniciantes conseguem)\",\n  \"outputPerHour\": \"1 machado de pedra pronto\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"1 pedra dura de rio e 1 pedra redonda de bater\",\n      \"desc\": \"Uma pedra firme de rio (do tamanho de dois punhos) que quebre formando bordas afiadas como vidro, e uma pedra redonda e pesada para usar como martelo.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Cabo de madeira dura do tamanho do antebraço (carvalho ou freixo)\",\n      \"desc\": \"Um galho verde e resistente (40–50cm de comprimento, 3,5–4cm de espessura) que aguente pancadas fortes sem quebrar.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Fibra interna de cipó molhada e resina de pinheiro\",\n      \"desc\": \"Mais de 3 metros de casca interna de cipó deixada de molho na água (encolhe e aperta ao secar) e um punhado de resina seca de pinheiro.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Bater as pedras a 45 graus para soltar uma lâmina afiada\",\n      \"description\": \"1. **Estabilização da bigorna de pedra**: Apoie firmemente no chão uma pedra de rio de **largura 15–20cm** de forma plana e sem folgas.\\n2. **Calibração do ponto de impacto**: Mire com precisão a **1–2cm para dentro** da borda da margem externa.\\n3. **Impacto chanfrado a 45 graus**: Desça a pedra redonda com vigor em um ângulo exato de **45 graus** contra a quina.\\n4. **Seleção da lasca afiada**: Destaque uma lâmina de pedra do tamanho da palma com fio de navalha e **espessura de 1–2cm**.\",\n      \"actionNote\": \"> Regra do ângulo de impacto: Bater a 90 graus no centro plano esmigalha a rocha em cascalho inútil. Bata obrigatoriamente na borda a 45 graus para obter uma lâmina afiadíssima.\",\n      \"svgFileName\": \"pr04-step-01.svg\",\n      \"svgLabels\": [\n        \"1. Pedra redonda (martelo)\",\n        \"2. Bater na borda a 45°\",\n        \"Lâmina afiada (1-2cm)\",\n        \"4. Lasca de machado solta\",\n        \"3. Pedra base (15-20cm)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD GEOLOGY\",\n        \"title\": \"Fratura concoidal e dispersão mecânica de ondas de choque\",\n        \"text\": \"O quartzo e o sílex não têm planos de clivagem e partem em padrões ondulados concêntricos na chamada **fratura concoidal**. O golpe a **45 graus** guia a energia de choque ao longo da superfície, desprendendo uma lâmina de corte com **1–2cm** de espessura extremamente afiada.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Rachar a ponta do cabo de madeira, encaixar a lâmina e preencher com resina\",\n      \"description\": \"1. **Amarração de contenção antirrachadura**: Amarre firmemente um cordão **10cm abaixo** da ponta do cabo para bloquear rachaduras descontroladas.\\n2. **Corte da fenda longitudinal**: Com uma pedra afiada, abra uma ranhura vertical de **profundidade 5–7cm** no topo do galho.\\n3. **Assentamento profundo da lâmina**: Empurre a parte traseira grossa da pedra até o fundo da fenda central.\\n4. **Preenchimento com epóxi de resina**: Misture resina de pinheiro derretida com **carvão moído na proporção 1:1** e compacte a mistura em todas as folgas.\",\n      \"actionNote\": \"> Regra da mistura composta: A resina pura fica quebradiça como vidro ao esfriar. O pó de carvão vegetal absorve impactos e forma um epóxi natural inquebrável. ([Cola de Resina (PR-10)](/protocol-10.html) / [Forno de Carvão (PR-09)](/protocol-09.html))\",\n      \"svgFileName\": \"pr04-step-02.svg\",\n      \"svgLabels\": [\n        \"1. Encaixar lâmina por cima\",\n        \"Fio de corte frontal\",\n        \"2. Fenda no cabo (5-7cm)\",\n        \"3. Resina + pó de carvão\",\n        \"4. Amarrar embaixo antes\",\n        \"Espessura do cabo: 3,5-4cm\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD CHEMISTRY\",\n        \"title\": \"Resina terpênica e matriz composta de partículas de carbono\",\n        \"text\": \"A resina de pinho contém ácidos diterpênicos que polimerizam no resfriamento, mas são frágeis. A adição de micropartículas de carbono (carvão) bloqueia a propagação de microfissuras, simulando a resistência de **compósitos de carbono e epóxi** modernos.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Amarrar firme em X com cipó úmido e secar na sombra\",\n      \"description\": \"1. **Hidratação da fibra do líber**: Mergulhe em água a casca interna flexível de cipó para maximizar a elasticidade das fibras.\\n2. **Amarração diagonal em X**: Cruze a fibra molhada em X sobre a lâmina e o cabo por **pelo menos 10 voltas bem tensas**.\\n3. **Bloqueio do colar inferior**: Enrole o restante da fibra horizontalmente abaixo da junção e aperte com um nó de tração firme.\\n4. **Secagem e cura à sombra**: Deixe secar totalmente em local ventilado e à sombra, longe do sol direto, para obter aperto máximo.\",\n      \"actionNote\": \"> Princípio de secagem na sombra: Nunca seque perto das chamas da fogueira, pois o calor queima e rompe as fibras. A secagem natural na sombra encolhe o cipó em 30%, travando a lâmina como aço. ([Corda Selvagem (PR-05)](/protocol-05.html))\",\n      \"svgFileName\": \"pr04-step-03.svg\",\n      \"svgLabels\": [\n        \"1. Amarração em X com cipó\",\n        \"2. Fio afiado exposto\",\n        \"3. Voltas horizontais na base\",\n        \"4. Encolhe 30% ao secar\",\n        \"Pronto: Machado firme em peça única\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BOTANY\",\n        \"title\": \"Contração por desidratação do líber e tensão radial de aperto\",\n        \"text\": \"Fibras vegetais de líber incham quando hidratadas e sofrem uma **contração volumétrica de até 30%** conforme a umidade evapora. A tensão de tração circunferencial gerada integra a pedra e a madeira como um parafuso mecânico.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Erro grave: Bater no meio plano da pedra ou amarrar com cipó seco\",\n    \"description\": \"Bater em ângulo reto (90 graus) no centro plano da pedra não cria lâmina e só quebra a pedra em pedregulhos inúteis. Além disso, amarrar com cipó seco ou casca grossa faz a amarração arrebentar na primeira batida, podendo lançar a pedra pesada contra o seu rosto.\",\n    \"consequence\": \"Resultado: Bata sempre na borda a 45 graus e amarre com fibra interna molhada, secando na sombra.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr04-outcome.svg\",\n    \"title\": \"Machado Primitivo de Pedra e Cipó Concluído\",\n    \"description\": \"Uma lâmina de sílex lascada bifacialmente encaixada em cabo de carvalho fendido, amarrada firmemente em X com cipós e selada com resina de pinho.\"\n  },\n  \"createdAt\": \"2026-10-09T16:10:00.000Z\",\n  \"updatedAt\": \"2026-10-15T16:31:51+09:00\",\n  \"contentHash\": \"1c29ec86b6976738\"\n}","content/protocols/locales/04-stone-axe-making.zh-TW.json":"{\n  \"protocolId\": \"PR-04\",\n  \"category\": \"TOOLS\",\n  \"title\": \"用碎石與藤蔓製作砍樹石斧的方法\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[重要度：核心工具]\",\n  \"summary\": \"徒手無法砍斷用來蓋避難所或當柴燒的粗樹枝。只要將兩塊堅硬的河石以45度角互相敲擊，就能剝離出鋒利的石刃，接著嵌入木柄縫隙中，並用松脂與泡過水的濕藤皮牢牢綁緊，做出一把堅固耐用的石斧。\",\n  \"timeRequired\": \"60分鐘\",\n  \"successRate\": \"90% (以45度角敲擊邊緣時)\",\n  \"difficulty\": \"普通 (新手可完成)\",\n  \"outputPerHour\": \"完成 1 把石斧\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"堅硬河石 1 塊與圓形錘石 1 塊\",\n      \"desc\": \"敲碎後會產生如玻璃般鋒利邊緣的堅硬河石（約兩個拳頭大）1 塊，以及握在手中用來敲擊的沉重圓石 1 塊。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"前臂長度的堅硬木柄（橡木或白蠟木）\",\n      \"desc\": \"用力揮砍也不易折斷的強韌生木枝條（長 40～50cm，直徑約 3.5～4cm）1 根。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"泡水軟化的葛藤內皮與松樹樹脂\",\n      \"desc\": \"乾燥後會自動收縮勒緊的濕葛藤內皮（長 3m 以上），以及從松樹樹皮上採集的凝固松脂一把。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"以45度角敲擊石頭，剝離出鋒利的石刃\",\n      \"description\": \"1. **基底砧石水平定位**：將**寬度15~20cm**的大塊河石穩固放置在地面上，確保毫無晃動。\\n2. **敲擊瞄準點校準**：精確鎖定距離外緣邊角**內側1~2cm**處作為敲擊點。\\n3. **45度斜角邊緣重擊**：手持圓形錘石，對準邊角以精確的**45度角**斜向果斷重擊。\\n4. **剝離石刃挑選**：分離出一片巴掌大小、邊緣如剃刀般鋒利且**厚度1~2cm**的石斧刃片。\",\n      \"actionNote\": \"> 敲擊角度鐵則：以90度垂直敲擊平坦正中央會震碎整塊石頭成為碎石。務必以45度斜角敲擊邊緣，才能剝離出極薄而銳利的刃片。\",\n      \"svgFileName\": \"pr04-step-01.svg\",\n      \"svgLabels\": [\n        \"① 圓形錘石（敲擊石）\",\n        \"② 對準邊緣 45° 斜敲\",\n        \"鋒利石刃（厚 1～2cm）\",\n        \"④ 劈下的石斧刀片\",\n        \"③ 底部墊石（寬 15～20cm）\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD GEOLOGY\",\n        \"title\": \"貝殼狀斷口（Conchoidal Fracture）與衝擊波傳導力學\",\n        \"text\": \"石英與隱晶質矽質岩缺乏解理面，受強烈敲擊時會沿同心圓震波形成**貝殼狀斷口**。設定**45度敲擊角**可將動能引導至表面邊緣，剝離出厚度僅**1~2cm**的超鋒利刀刃。\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"劈開木柄頂端，嵌入石刃並填滿松脂\",\n      \"description\": \"1. **防開裂限位預先捆紮**：為防止木柄縱向劈裂失控，先在頂端**下方10cm處**用繩索緊緊綁縛。\\n2. **縱向開槽劈開木柄**：用鋒利石片在硬木柄頂端垂直劈開**深度5~7cm**的安裝夾縫。\\n3. **石刃後端中心壓入**：將石刃較厚的尾部平整而深入地壓入中央開槽最底部。\\n4. **松脂碳粉複合物灌注**：將加熱融化的松脂與磨細的**木炭粉以1:1比例**混合，填滿夾縫中所有空隙。\",\n      \"actionNote\": \"> 複合配方法則：單純塗抹純松脂冷卻後會像玻璃一樣脆弱碎裂。混入木炭粉能吸收衝擊應力，形成永不破裂的天然環氧樹脂。 ([松脂防水膠 (PR-10)](/protocol-10.html) / [地下炭窯 (PR-09)](/protocol-09.html))\",\n      \"svgFileName\": \"pr04-step-02.svg\",\n      \"svgLabels\": [\n        \"① 由上往下嵌入石刃\",\n        \"砍樹的前方刀刃\",\n        \"② 劈開的木柄縫隙（5～7cm）\",\n        \"③ 填入融化松脂＋木炭粉\",\n        \"④ 下方先綁緊防裂開\",\n        \"生木柄粗度：直徑 3.5～4cm\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD CHEMISTRY\",\n        \"title\": \"萜烯樹脂與碳微粒複合基質（Composite Epoxy）材料特性\",\n        \"text\": \"松脂中的二萜酸在冷卻固化時具備高硬度但極易脆裂。複合添加微細碳（木炭）顆粒能物理性阻斷微裂紋蔓延，達到與現代**碳纖維環氧樹脂複合材料**同等的抗衝擊韌性。\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"用濕藤皮以X字形緊緊纏繞並在陰涼處晾乾\",\n      \"description\": \"1. **韌皮纖維充分浸潤**：將柔軟的葛藤內皮浸入水中，使植物纖維徹底吸水恢復彈性。\\n2. **對角X字交叉結紮**：將濕藤皮在石刃與木柄之間以對角X字交叉纏繞**至少10圈以上**並用力拉緊。\\n3. **下端頸部橫向收緊**：用剩餘藤皮在下方頸部橫向密實纏繞，並以止滑結死死鎖定。\\n4. **通風陰涼處完全陰乾**：避開陽光直射，置於陰涼通風處徹底風乾，以激發最大收縮鎖緊力。\",\n      \"actionNote\": \"> 陰乾原則：切勿拿到營火旁烘烤，高溫會使纖維脆化斷裂。在陰涼處自然陰乾可讓藤皮收縮30%，如鋼絲般死死咬合石刃。 ([野生繩索 (PR-05)](/protocol-05.html))\",\n      \"svgFileName\": \"pr04-step-03.svg\",\n      \"svgLabels\": [\n        \"① 濕藤皮 X 字形交叉纏繞\",\n        \"② 外露的鋒利斧刃\",\n        \"③ 木柄下方橫向繞緊固定\",\n        \"④ 乾燥收縮 30% 強力鎖緊\",\n        \"完成狀態：重擊也不脫落的一體成型石斧\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BOTANY\",\n        \"title\": \"韌皮纖維脫水收縮與徑向夾緊張力鎖定\",\n        \"text\": \"葛藤內皮等韌皮（Bast）纖維吸水時細胞壁膨脹，隨水分蒸發乾燥會產生**高達30%的體積收縮**。由此產生的巨大徑向箍緊應力將石刃與木柄如金屬螺栓般剛性一體化。\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"絕對不能犯的錯誤：垂直敲打石頭中央或用乾藤蔓綁縛\",\n    \"description\": \"以 90 度垂直敲擊平坦的石頭中央，只會把整塊石頭震碎成沒用的碎石。此外，若用沒泡水的乾枯藤蔓或粗糙外皮捆綁，揮斧砍樹的瞬間繩子就會斷裂，沉重的石刃會直接飛向臉部或眼睛造成嚴重傷害。\",\n    \"consequence\": \"結果：務必以 45 度角敲擊河石邊緣取刃，並用泡水軟化的強韌內皮以 X 字形纏繞後陰乾。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr04-outcome.svg\",\n    \"title\": \"敲石碎屑與葛藤結紮原始石斧完成形態\",\n    \"description\": \"堅韌橡木柄凹槽中深嵌雙面打製鋒利燧石刃，以強韌葛藤與松脂黏合劑進行X型十字結紮，具備砍伐原木威力的實戰石斧完成形態。\"\n  },\n  \"createdAt\": \"2026-10-09T16:10:00.000Z\",\n  \"updatedAt\": \"2026-10-15T16:31:51+09:00\",\n  \"contentHash\": \"1c29ec86b6976738\"\n}","content/protocols/locales/05-natural-cordage.de.json":"{\n  \"protocolId\": \"PR-05\",\n  \"category\": \"TOOLS\",\n  \"title\": \"Reißfestes Wildnisseil aus Baumrinde und Ranken drehen\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[ÜBERLEBENSWICHTIG]\",\n  \"summary\": \"Eine stabile Schnur ist unverzichtbar für Unterstände, Steinäxte und Feuerbohrer. Ganze grüne Ranken schrumpfen und brechen beim Trocknen; wenn man jedoch die weiße Innenrinde (Bastfaser) abzieht und zwei Stränge gegenläufig zusammendreht, entsteht ein selbstsicherndes Seil, das das Gewicht eines Erwachsenen trägt.\",\n  \"timeRequired\": \"40 Min.\",\n  \"successRate\": \"95% (Mit Gegendrehung)\",\n  \"difficulty\": \"Mittel (Mit bloßen Händen)\",\n  \"outputPerHour\": \"5m / 40 Min.\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Lebende Kudzu-Ranken, Linden-, Weiden- oder Brennnesselstängel (10~15 armlange Triebe)\",\n      \"desc\": \"Wählen Sie biegsame Triebe, die beim Knicken nicht brechen und unter dem Fingernagel grüne Feuchtigkeit zeigen.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 scharfkantiger Steinabschlag zum Abschaben\",\n      \"desc\": \"Zum vorsichtigen Abschaben der spröden braunen Außenrinde, ohne die zähen weißen Innenfasern zu beschädigen.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Flacher Unterlegstein und faustgroßer runder Klopfstein\",\n      \"desc\": \"Um die eingeweichte Innenrinde sanft weichzuklopfen, bis sie sich in feine, haarähnliche Fasern teilt.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Bach- oder Tümpelwasser zum Einweichen\",\n      \"desc\": \"Frisch abgezogene Innenrinde 20~30 Minuten wässern, um steifen Pflanzensaft zu lösen und die Fasern geschmeidig zu halten.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Schritt 1: Biegsame Stängel wählen, Außenrinde abschaben und weiße Innenfaser abziehen\",\n      \"description\": \"1. **Trieb-Elastizitätsprüfung**: Biegen Sie den Stängel langsam um **über 90 Grad**, um sicherzustellen, dass er ohne Knick nachgibt.\\n2. **Außenrinden-Schabung**: Setzen Sie eine scharfe Steinkante schräg an und schaben Sie nur die spröde **braune Außenrinde** vorsichtig ab.\\n3. **Bastschicht-Sichtprüfung**: Vergewissern Sie sich, dass die feucht schimmernden **weißen, zähen Bastfasern** freigelegt sind.\\n4. **Holzkern-Trennung**: Heben Sie den Rindenrand mit dem Fingernagel an und ziehen Sie die langen Bastbänder **vom starren Holzkern ab**.\",\n      \"actionNote\": \"> Ernte-Grundregel: Abgestorbene, trockene Stängel am Boden haben morsche Fasern, die sofort reißen. Verwenden Sie stets lebende, saftige Triebe.\",\n      \"svgFileName\": \"pr05-step-01.svg\",\n      \"svgLabels\": [\n        \"① Raue Außenrinde mit Steinkante abschaben\",\n        \"② Spröde braune Außenrinde (abschaben & wegwerfen)\",\n        \"③ Zähe weiße Innenfaser (Hauptmaterial fürs Seil)\",\n        \"④ Harter Holzkern in der Mitte (entfernen)\",\n        \"⑤ Biegsamer lebender Stängel bricht nicht\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BOTANY\",\n        \"title\": \"Phloembast-Zugfestigkeit und Pektintrennung\",\n        \"text\": \"Das zwischen Außenrinde und Holzkörper liegende **Phloembastgewebe** besteht aus parallel ausgerichteten Cellulose-Mikrofibrillen und erreicht bis zu **50% der Zugfestigkeit von Baustahl**. Das saubere mechanische Abschaben isoliert diese tragenden Fasern ohne Scherbrüche.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Schritt 2: 20 Minuten im Bach wässern und mit rundem Stein weichklopfen\",\n      \"description\": \"1. **Wässerung und Pektinausschwemmung**: Tauchen Sie die Rindenbänder für **20 bis 30 Minuten** vollständig in Wasser, um steife Pflanzensäfte zu lösen.\\n2. **Flussstein-Amboss-Auflage**: Breiten Sie die geschmeidigen Fasern flach auf einem **wackelfreien, ebenen Flussstein** aus.\\n3. **Sanftes Weichklopfen**: Klopfen und rollen Sie einen runden Stein sanft entlang des Strangs, um starre Holzfasern in **feine Faserbündel** aufzuschließen.\\n4. **Symmetrische Zweiteilung**: Teilen Sie das Faserbündel in **2 gleich dicke Stränge** mit identischem Durchmesser.\",\n      \"actionNote\": \"> Klopfdruck-Kontrolle: Zu harte Schläge zerhacken die Fasern. Rollen und drücken Sie sanft mit einem runden Stein, um lange Stränge zu erhalten.\",\n      \"svgFileName\": \"pr05-step-02.svg\",\n      \"svgLabels\": [\n        \"① Innenrinde 20+ Min. im Bachwasser eingeweicht\",\n        \"② Sanft mit rundem Stein klopfen zum Auffasern\",\n        \"③ Weiches, haarfein gelöstes Faserbündel\",\n        \"④ Zwei gleichmäßige, fingerdicke Faserstränge\",\n        \"⑤ Stabiler flacher Flussstein als Unterlage\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Schritt 3: Nach außen zwirbeln und zum Körper kreuzen (Gegendrehung)\",\n      \"description\": \"1. **Mittenschlaufen-Klemmung**: Knicken Sie das Faserbündel in der Mitte und klemmen Sie die Schlaufe zwischen linkem Daumen und Zeigefinger zu **oberem und unterem Strang**.\\n2. **Einzelstrang-Zwirbelung**: Drehen Sie den oberen Strang mit der rechten Hand im **Uhrzeigersinn fest vom Körper weg (↑)** ein.\\n3. **Gegenläufiges Überkreuzen**: Führen Sie den verdrillten oberen Strang über den unteren Strang hinweg **gegen den Uhrzeigersinn zum Körper hin (↓)**.\\n4. **Fortlaufende Klemmverriegelung**: Setzen Sie den linken Daumen auf den neuen Kreuzungspunkt nach und wiederholen Sie den Zyklus **nach außen zwirbeln und zum Körper kreuzen**.\",\n      \"actionNote\": \"> Gegendreh-Gesetz: Dreht man beide Stränge in dieselbe Richtung, rollt sich das Seil sofort auf. Die Gegendrehung der Einzelstränge neutralisiert das Drehmoment dauerhaft.\",\n      \"svgFileName\": \"pr05-step-03.svg\",\n      \"svgLabels\": [\n        \"① Oberer Strang: fest vom Körper wegdrehen (↑)\",\n        \"② Verzahntes Fischgrät-Seilmuster\",\n        \"③ Kreuzungspunkt mit linkem Daumen & Zeigefinger halten\",\n        \"④ Gedrehten Strang über unteren zum Körper legen (↓)\",\n        \"⑤ Selbstsichernde Gegendreh-Verriegelung\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD MECHANICS\",\n        \"title\": \"Drehmomentausgleich und mechanische Selbsthemmung beim Reverse-Wrap\",\n        \"text\": \"Durch das Verdrillen der Einzelstränge im Uhrzeigersinn (Z-Schlag) bei gleichzeitigem Umschlagen gegen den Uhrzeigersinn (S-Schlag) heben sich die rückstellenden Torsionsmomente im **Drehmomentgleichgewicht** auf. Dieser Reibungsschluss verhindert das Aufdröseln selbst ohne Endknoten.\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Schritt 4: Neue Fasern 10cm überlappen für endlose Seillänge\",\n      \"description\": \"1. **Spleißfenster-Erkennung**: Erkennen Sie rechtzeitig, wann ein Strang auf eine Restlänge von **rund 10cm** ausdünnt.\\n2. **Faserbündel-Überlappung**: Legen Sie ein frisches Faserbündel parallel an das alte Ende mit **10cm Überlappungslänge** an.\\n3. **Gemeinsames Weiterzwirbeln**: Fassen Sie beide Faserenden wie einen einzigen Strang zusammen und führen Sie **3 bis 4 Verdrillungszyklen** durch.\\n4. **Versetzte Spleißabstände**: Versetzen Sie die Verbindungen von oberem und unterem Strang um **mindestens 15cm Abstand** zueinander.\",\n      \"actionNote\": \"> Spleißversatz-Regel: Liegen beide Spleißstellen am selben Punkt, entsteht eine Schwachstelle, die unter Zug reißt. Versetzen Sie die Spleißpunkte stets um mindestens 15cm.\",\n      \"svgFileName\": \"pr05-step-04.svg\",\n      \"svgLabels\": [\n        \"① Alter Strang wird bei 10cm Restlänge dünner\",\n        \"② Neues Faserbündel 10cm daneben überlappen\",\n        \"③ Beide Enden gemeinsam als einen Strang drehen\",\n        \"④ Glatte Verbindung ohne dicke Schwachstelle\",\n        \"⑤ Obere & untere Spleißstelle 15cm versetzen\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD TENSION\",\n        \"title\": \"Versetzte Spleißarchitektur und Grenzflächen-Schubspannung\",\n        \"text\": \"Das Zusammenlegen beider Spleißstellen an einem axialen Punkt erzeugt Querschnittssprünge und Spannungsspitzen unter Last. Ein Versatz um **mindestens 15cm** überträgt die Zugkraft über **Grenzflächen-Schubreibung** auf den parallelen durchgehenden Strang, wodurch die volle Nennfestigkeit erhalten bleibt.\"\n      }\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Schritt 5: Endknoten setzen und am Baumstamm mit Körpergewicht testen\",\n      \"description\": \"1. **Endknoten-Abschluss**: Bilden Sie bei Erreichen der Ziellänge (5m+) am Ende bei **3cm Abstand** eine Schlinge und ziehen Sie einen festen Überhandknoten an.\\n2. **Klingen-Glättung**: Schaben Sie mit einer scharfen Steinkante abstehende Fasern glatt, um einen **gleichmäßigen Durchmesser von 5mm** zu erzielen.\\n3. **Stamm-Verankerung**: Schlingen Sie das fertige Seil mindestens zweimal um einen armdicken, gesunden Baumstamm.\\n4. **Zuglasttest mit 50kg**: Greifen Sie das Seil mit beiden Händen und belasten Sie es mit **vollem Körpergewicht von 50kg+**, um den sicheren Halt der Spleiße zu bestätigen.\",\n      \"actionNote\": \"> Belastungsprüf-Kriterium: Knacken Fasern oder rutscht eine Verbindung, umwickeln Sie diese Zone sofort mit einer zusätzlichen dünnen Faserlage.\",\n      \"svgFileName\": \"pr05-step-05.svg\",\n      \"svgLabels\": [\n        \"① Sicherungsknoten 3cm vor dem Seilende\",\n        \"② Abstehende Fasern mit Steinklinge säubern\",\n        \"③ Um Baumstamm legen & mit Körpergewicht (50kg+) ziehen\",\n        \"④ Fertiges 5mm Wildnisseil (5m Länge)\",\n        \"⑤ Bereit für Unterstand, Steinaxt & Feuerbohrer\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Tödlicher Fehler: Ungeschälte grüne Ranken direkt zum Binden verwenden\",\n    \"description\": \"Wickelt man ganze grüne Ranken oder Zweige direkt um Unterstand oder Steinaxt, wirkt das nur anfangs fest. Sobald der Pflanzensaft trocknet, schrumpft die Ranke, lockert sich und der holzige Kern bricht bei Belastung sofort durch. Immer nur die abgezogene Innenfaser gegenläufig verdrillen.\",\n    \"consequence\": \"Folge: Das Dach des Unterstands bricht nachts ein oder der Steinaxtkopf löst sich beim Schlagen\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Wie man im Wald ohne Hilfsmittel mit bloßen Händen ein reißfestes Seil dreht.\",\n    \"body\": \"Braune Außenrinde von lebenden Ranken abschaben und weiße Innenfaser abziehen. 20 Minuten wässern und mit rundem Stein weichklopfen. Halbieren, oberen Strang vom Körper wegdrehen und zum Körper hin überkreuzen. Neue Fasern 10cm überlappen für endlose Länge.\",\n    \"outro\": \"Hält über 50kg Körpergewicht am Baumstamm. Perfekt für Unterstände, Steinäxte und Feuerbohrer.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr05-outcome.svg\",\n    \"title\": \"Vollendeter 2-Strang-Naturseilbund mit Gegenverdrallung\",\n    \"description\": \"Ein gleichmäßiger 8-mm-Seilbund aus im Uhrzeigersinn gedrehten und gegenläufig verzwirnten Bastfasern, der über 90 kgf Zuglast ohne Aufdröseln standhält.\"\n  },\n  \"createdAt\": \"2026-10-13T13:20:00.000Z\",\n  \"updatedAt\": \"2026-10-16T13:34:53+09:00\",\n  \"contentHash\": \"474efda727971489\"\n}","content/protocols/locales/05-natural-cordage.en.json":"{\n  \"protocolId\": \"PR-05\",\n  \"category\": \"TOOLS\",\n  \"title\": \"How to Twist Unbreakable Wild Cordage from Bark and Vines\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[CRITICAL SURVIVAL]\",\n  \"summary\": \"Strong cordage is essential for lashing shelter frames, hafting stone axes, and spinning a bow drill. Whole raw vines shrink and snap brittlely once dry, but extracting inner bast fibers and reverse-wrapping two strands creates a self-locking rope strong enough to hold adult body weight.\",\n  \"timeRequired\": \"40 min\",\n  \"successRate\": \"95% (With Reverse Wrap)\",\n  \"difficulty\": \"Medium (Bare Hands)\",\n  \"outputPerHour\": \"5m / 40 min\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Live Kudzu Vines, Basswood, Willow, or Nettle Stems (10~15 arm-length stalks)\",\n      \"desc\": \"Choose live stalks that bend smoothly without snapping and show green moisture when scratched with a fingernail.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 Sharp-Edged Stone Flake for Scraping\",\n      \"desc\": \"Used to gently scrape off the brittle brown outer bark without cutting into the tough white inner fibers beneath.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Flat Anvil Stone and Fist-Sized Round Hammer Stone\",\n      \"desc\": \"Used to gently pound soaked inner bark strips until they separate into soft, hair-like fiber strands.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Stream or Standing Water for Soaking\",\n      \"desc\": \"Soak freshly peeled inner bark for 20~30 minutes to soften stiff sap and keep fibers flexible while twisting.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Step 1: Select Flexible Stalks, Scrape Outer Bark, and Peel White Inner Bark\",\n      \"description\": \"1. **Live Stalk Elasticity Verification**: Slowly flex the stalk in half to ensure it bends smoothly past **90 degrees** without breaking.\\n2. **Outer Bark Stripping**: Angle a sharp stone edge against the stem to carefully scrape away only the brittle **brown outer bark**.\\n3. **Bast Layer Inspection**: Visually verify the moist, gleaming **white inner bast fibers** emerging beneath the scraped surface.\\n4. **Woody Core Separation**: Lift the bottom edge with your fingernail and pull upward firmly to **strip the tough ribbon fibers** clean off the rigid woody core.\",\n      \"actionNote\": \"> Harvesting Principle: Dead, dry stalks on the ground have rotted fibers that crumble under tension. Always harvest inner bark from live or freshly cut green stalks.\",\n      \"svgFileName\": \"pr05-step-01.svg\",\n      \"svgLabels\": [\n        \"① Scrape off rough outer bark with stone edge\",\n        \"② Brittle brown outer bark (scrape & discard)\",\n        \"③ Tough white inner bast fiber (core rope material)\",\n        \"④ Stiff woody center core (peel off & discard)\",\n        \"⑤ Flexible live stalk that bends without snapping\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BOTANY\",\n        \"title\": \"Phloem Bast Fiber Tensile Strength and Pectin Separation\",\n        \"text\": \"The **phloem bast tissue** located between the outer epidermis and the inner xylem core consists of parallel crystalline cellulose microfibrils, delivering a tensile strength nearly **50% of mild structural steel**. Clean mechanical scraping isolates these continuous load-bearing fibers without shear damage.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Step 2: Soak in Water for 20 Minutes and Pound into Soft Hair-Like Fibers\",\n      \"description\": \"1. **Hydration and Pectin Leaching**: Submerge peeled bast ribbons completely in water for **20–30 minutes** to dissolve stiffening tree sap.\\n2. **Flat Anvil Placement**: Spread the softened ribbons flat across a wide, stable **river anvil stone**.\\n3. **Gentle Hammerstone Milling**: Tap and roll a round stone gently along the length to break down stiff grain into **pliable hair-like filaments**.\\n4. **Equal Dual Splitting**: Divide the resulting continuous fiber bundle into **2 equal strands** of identical thickness.\",\n      \"actionNote\": \"> Pounding Control: Striking too hard severs the continuous filaments. Roll and press gently with a smooth stone to preserve maximum tensile length.\",\n      \"svgFileName\": \"pr05-step-02.svg\",\n      \"svgLabels\": [\n        \"① Inner bark soaked 20+ min in stream water\",\n        \"② Gently tap with round stone to split fibers\",\n        \"③ Softened hair-like fiber bundle\",\n        \"④ Two equal finger-thick fiber strands\",\n        \"⑤ Stable flat river stone anvil beneath\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Step 3: Twist Away and Cross Toward You (Reverse-Wrap Locking Method)\",\n      \"description\": \"1. **Bight Pinch Initiation**: Fold the continuous fiber bundle in half, pinching the center loop tightly between your left thumb and forefinger to form **upper and lower plies**.\\n2. **Individual Clockwise Twist**: Grip the upper ply with your right hand and twist tightly away from your body (↑) in a **clockwise rotation**.\\n3. **Collective Counter-Cross**: Bring the twisted upper ply down over the lower ply toward your body (↓) in a **counter-clockwise crossing movement**.\\n4. **Progressive Pinch Advance**: Walk your left thumb forward to pinch the new junction, repeating the **twist-away and wrap-inward cycle** continuously.\",\n      \"actionNote\": \"> Reverse-Wrap Locking Law: Twisting both strands in the same direction causes the rope to unravel instantly. Counter-twisting individual plies against the collective braid balances torque and creates a permanent mechanical lock.\",\n      \"svgFileName\": \"pr05-step-03.svg\",\n      \"svgLabels\": [\n        \"① Top strand: twist tightly away from body (↑)\",\n        \"② Interlocked chevron rope pattern\",\n        \"③ Pinch junction firmly with left thumb & index\",\n        \"④ Cross twisted top strand over toward body (↓)\",\n        \"⑤ Self-locking reverse-wrap structure\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD MECHANICS\",\n        \"title\": \"Torque Equilibrium and Mechanical Self-Locking in Reverse-Wrap Braiding\",\n        \"text\": \"By twisting individual plies clockwise (Z-twist) while braiding them counter-clockwise (S-twist), the opposing elastic recovery moments cancel each other out in complete **torque equilibrium**. This friction interlock prevents unraveling even when tension is fully released.\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Step 4: Overlap New Fibers by 10cm to Splice Endless Length\",\n      \"description\": \"1. **Splice Window Detection**: Identify when either working strand thins down to its final **10cm tail**.\\n2. **Overlap Layering**: Lay the tapered end of a fresh fiber bundle parallel alongside the depleting tail across a **10cm overlap zone**.\\n3. **Integrated Dual Ply Wrap**: Pinch both bundles together as a single strand and twist tightly across **3–4 consecutive braid cycles**.\\n4. **Staggered Splice Offset**: Offset the splices between upper and lower plies by a **minimum distance of 15cm**.\",\n      \"actionNote\": \"> Staggered Splice Rule: Splicing both strands at the same spot creates a swollen lump that shears under heavy tension. Always stagger splices by at least 15cm to preserve continuous tensile strength.\",\n      \"svgFileName\": \"pr05-step-04.svg\",\n      \"svgLabels\": [\n        \"① Existing strand thinning with 10cm left\",\n        \"② Lay new fiber bundle alongside (10cm overlap)\",\n        \"③ Twist overlapped tails together as one strand\",\n        \"④ Smooth splice without bulky weak lumps\",\n        \"⑤ Stagger top & bottom splices by 15cm\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD TENSION\",\n        \"title\": \"Staggered Splice Architecture and Interfacial Shear Friction\",\n        \"text\": \"Aligning splices in both plies at the same axial point causes sudden cross-sectional discontinuities, creating catastrophic stress concentrations. Offsetting joints by **at least 15cm** transfers tensile load via **interfacial shear friction** to the unbroken parallel ply, preserving 100% of the cord's breaking strength.\"\n      }\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Step 5: Tie an End Stopper Knot and Test with Full Body Weight on a Tree\",\n      \"description\": \"1. **Terminal Stopper Knot**: Upon reaching the target length (5m+), cinch the final **3cm end segment** into a tight overhand stopper knot.\\n2. **Lithic Shear Trimming**: Lightly scrape a sharp stone flake along the rope body to trim stray fuzz and maintain a **uniform 5mm diameter**.\\n3. **Arboreal Anchor Lashing**: Wrap the finished cordage at least twice around a solid tree trunk thicker than your forearm.\\n4. **50kg Tensile Proof-Load**: Grasp the rope firmly with both hands and suspend your **full body weight of 50kg+** to prove splice integrity.\",\n      \"actionNote\": \"> Tensile Proof Standard: If you hear fiber snapping sounds or observe splice slippage under load, wrap a thin reinforcing fiber sheath directly over the affected zone.\",\n      \"svgFileName\": \"pr05-step-05.svg\",\n      \"svgLabels\": [\n        \"① Overhand stopper knot 3cm from the end\",\n        \"② Trim loose fuzz cleanly with stone flake\",\n        \"③ Wrap around tree & pull with body weight (50kg+)\",\n        \"④ Finished 5mm wild rope (5m length)\",\n        \"⑤ Ready for shelter lashing, stone axe & bow drill\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Fatal Mistake: Tying Whole Unpeeled Green Vines Directly\",\n    \"description\": \"Wrapping whole raw vines or green twigs directly around a shelter frame or stone axe feels tight at first, but within hours the sap dries, the vine shrinks and loosens, and the woody core snaps like a dry cracker under impact. Always strip the outer bark and woody core, and reverse-wrap the inner bast fibers.\",\n    \"consequence\": \"Consequence: Shelter roof collapses overnight or stone axe head flies off mid-swing causing severe injury\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"When you have zero rope in the wild, here is how to twist unbreakable cordage with bare hands.\",\n    \"body\": \"Scrape the brown outer bark off live kudzu vines and peel out the white inner fibers. Soak for 20 minutes and tap with a round stone until soft. Fold in half, twist the top strand away from you, and cross it over toward you. Overlap new fibers by 10cm to splice endless length.\",\n    \"outro\": \"Tested against 50kg of body weight on a tree trunk. Ready for shelters, stone axes, and bow drills.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr05-outcome.svg\",\n    \"title\": \"Completed 2-Ply Reverse-Wrapped Natural Cordage Coil\",\n    \"description\": \"A uniform 8mm braided rope coil made by twisting bast fibers clockwise and counter-wrapping plies, sustaining over 90 kgf tensile load without slipping.\"\n  },\n  \"createdAt\": \"2026-10-13T13:20:00.000Z\",\n  \"updatedAt\": \"2026-10-16T13:34:53+09:00\",\n  \"contentHash\": \"474efda727971489\"\n}","content/protocols/locales/05-natural-cordage.es.json":"{\n  \"protocolId\": \"PR-05\",\n  \"category\": \"TOOLS\",\n  \"title\": \"Cómo trenzar cuerda salvaje irrompible con corteza y lianas\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[SUPERVIVENCIA CRÍTICA]\",\n  \"summary\": \"Una cuerda resistente es indispensable para atar refugios, fijar hachas de piedra y encender fuego con arco. Atar lianas verdes enteras falla porque encogen y se quiebran al secarse; en cambio, extraer la fibra blanca interna y trenzar dos cabos en sentido inverso crea una soga autobloqueante capaz de soportar el peso de un adulto.\",\n  \"timeRequired\": \"40 min\",\n  \"successRate\": \"95% (Con trenzado inverso)\",\n  \"difficulty\": \"Media (Con las manos)\",\n  \"outputPerHour\": \"5m / 40 min\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Lianas vivas de kudzu, tilo, sauce o tallos de ortiga (10~15 tallos del largo del brazo)\",\n      \"desc\": \"Elija tallos vivos que se doblen sin romperse y muestren humedad verde al rasparlos con la uña.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 lasca de piedra con borde afilado para raspar\",\n      \"desc\": \"Se usa para raspar suavemente la corteza exterior marrón sin cortar las fibras blancas internas.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Piedra plana de base y canto rodado del tamaño del puño\",\n      \"desc\": \"Para golpear suavemente la corteza interna remojada hasta separarla en hebras suaves como cabellos.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Agua de arroyo o charca para remojar\",\n      \"desc\": \"Remoje la corteza interna durante 20~30 minutos para ablandar la savia y mantener las fibras flexibles.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Paso 1: Elegir tallos flexibles, raspar la corteza exterior y pelar la fibra blanca interna\",\n      \"description\": \"1. **Comprobación de elasticidad**: Doble el tallo despacio en ángulo de **más de 90 grados** para verificar que no quiebre.\\n2. **Raspado de corteza exterior**: Apoye el borde biselado de una piedra para retirar solo la **corteza marrón quebradiza**.\\n3. **Inspección de la capa floemática**: Compruebe visualmente la aparición de las **fibras blancas internas y húmedas** bajo la superficie raspada.\\n4. **Desprendimiento del núcleo leñoso**: Levante el extremo con la uña y tire longitudinalmente para **separar el núcleo leñoso rígido** de las cintas de fibra.\",\n      \"actionNote\": \"> Principio de recolección: Los tallos caídos y secos poseen fibras podridas que se deshacen bajo carga. Extraiga la corteza interna siempre de ramas vivas o recién cortadas.\",\n      \"svgFileName\": \"pr05-step-01.svg\",\n      \"svgLabels\": [\n        \"① Raspar corteza exterior con borde de piedra\",\n        \"② Corteza marrón quebradiza (raspar y tirar)\",\n        \"③ Fibra interna blanca y firme (material clave)\",\n        \"④ Núcleo central de madera dura (desechar)\",\n        \"⑤ Tallo vivo flexible que se dobla sin partirse\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BOTANY\",\n        \"title\": \"Resistencia a la tracción del floema y separación de pectina\",\n        \"text\": \"El **tejido floemático (fibras del líber)** situado entre la corteza exterior y el xilema interno está compuesto por microfibrillas de celulosa paralelas que alcanzan el **50% de la resistencia a la tracción del acero dulce**. El raspado mecánico meticuloso aísla estas fibras portantes sin fracturarlas.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Paso 2: Remojar 20 minutos en el arroyo y machacar con piedra hasta suavizar\",\n      \"description\": \"1. **Hidratación y lixiviación de pectina**: Sumerja las cintas de corteza en agua de **20 a 30 minutos** para ablandar savias y gomas vegetales.\\n2. **Disposición en yunque de piedra**: Extienda las fibras hidratadas sobre una **piedra plana de río** perfectamente estable.\\n3. **Desfibrado por percusión suave**: Golpee y ruede suavemente un canto rodado a lo largo para separar el grano leñoso en **finos filamentos textiles**.\\n4. **División simétrica en dos cabos**: Divida el manojo resultante en **2 cabos iguales** con el mismo diámetro y densidad.\",\n      \"actionNote\": \"> Control de impacto: Descargar golpes bruscos secciona las hebras longitudinales. Presione y ruede con suavidad para mantener las fibras íntegras.\",\n      \"svgFileName\": \"pr05-step-02.svg\",\n      \"svgLabels\": [\n        \"① Corteza interna remojada 20+ min en agua\",\n        \"② Golpear suave con piedra redonda para abrir fibras\",\n        \"③ Manojo de fibras suaves como cabellos\",\n        \"④ Dos cabos iguales del grosor de un dedo\",\n        \"⑤ Piedra plana firme apoyada en el suelo\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Paso 3: Retorcer hacia afuera y cruzar hacia el cuerpo (Trenzado Inverso)\",\n      \"description\": \"1. **Sujeción en lazo central**: Doble el manojo por la mitad aprisionando el pliegue central entre pulgar e índice izquierdos para definir **cabo superior e inferior**.\\n2. **Torsión horaria individual**: Con la mano derecha, retuerza el cabo superior hacia afuera (↑) en **sentido horario** hasta que quede tenso.\\n3. **Cruce antihorario colectivo**: Pasa el cabo superior ya torsionado sobre el cabo inferior hacia tu cuerpo (↓) en un **movimiento de cruce antihorario**.\\n4. **Bloqueo progresivo continuo**: Avanza el pulgar izquierdo sujetando el nuevo nudo de cruce y repite la secuencia de **retorcer afuera y cruzar adentro**.\",\n      \"actionNote\": \"> Ley de bloqueo inverso: Girar ambos cabos en la misma dirección desarma la cuerda al instante. Contrarrotar los cabos individuales frente al trenzado equilibra el par torsor y crea un bloqueo permanente.\",\n      \"svgFileName\": \"pr05-step-03.svg\",\n      \"svgLabels\": [\n        \"① Cabo superior: retorcer firme hacia afuera (↑)\",\n        \"② Trenzado en espiga autobloqueado\",\n        \"③ Sujetar cruce con pulgar e índice izquierdos\",\n        \"④ Cruzar cabo superior hacia el cuerpo (↓)\",\n        \"⑤ Cierre inverso que no se deshace al soltar\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD MECHANICS\",\n        \"title\": \"Equilibrio de par torsor y bloqueo mecánico del trenzado inverso\",\n        \"text\": \"Al retorcer cada cabo en sentido horario (torsión Z) mientras se trenzan juntos en sentido antihorario (torsión S), las fuerzas de recuperación elástica opuestas se neutralizan en un **equilibrio de par torsor**. Este entrelazado por fricción evita que la soga se desenrolle sin necesidad de nudos.\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Paso 4: Superponer 10cm de fibra nueva para empalmar longitud infinita\",\n      \"description\": \"1. **Detección de zona de empalme**: Identifique cuándo cualquiera de los cabos se agote hasta un remanente de **unos 10cm**.\\n2. **Solapamiento longitudinal**: Coloque la punta de un nuevo manojo de fibra paralelo al cabo saliente a lo largo de **10cm de contacto**.\\n3. **Torsión de cabo unificado**: Sujete ambos extremos juntos como un solo hilo y retuerza hacia afuera durante **3 a 4 ciclos de trenzado**.\\n4. **Desfase axial de empalmes**: Asegúrese de que los empalmes del cabo superior e inferior mantengan una **separación mínima de 15cm**.\",\n      \"actionNote\": \"> Regla de empalmes desfasados: Coincidir ambas uniones en el mismo punto genera un engrosamiento que cede al someterlo a tracción. Alterne las uniones con 15cm de margen.\",\n      \"svgFileName\": \"pr05-step-04.svg\",\n      \"svgLabels\": [\n        \"① Cabo viejo adelgazado con 10cm restantes\",\n        \"② Colocar fibra nueva al lado (10cm superpuestos)\",\n        \"③ Retorcer ambos extremos juntos como uno solo\",\n        \"④ Empalme liso sin bultos ni puntos débiles\",\n        \"⑤ Desfasar empalmes superior e inferior por 15cm\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD TENSION\",\n        \"title\": \"Dispersión de empalmes desfasados y transferencia por fricción de cizallamiento\",\n        \"text\": \"Concentrar los empalmes de ambos cabos en el mismo punto genera discontinuidades axiales y fracturas por concentración de tensiones. Al desfasar las uniones **al menos 15cm**, la carga se transmite mediante **fricción interfacial de cizallamiento** al cabo continuo paralelo, conservando el 100% de la resistencia.\"\n      }\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Paso 5: Hacer nudo de tope final y probar con el peso del cuerpo en un árbol\",\n      \"description\": \"1. **Nudo terminal de contención**: Al alcanzar la longitud requerida (5m+), forme un lazo a **3cm del extremo** y ciña un nudo simple de tope.\\n2. **Afeitado de pelusas**: Pase suavemente una lasca afilada de piedra para eliminar rebabas hasta obtener una **sección uniforme de 5mm**.\\n3. **Fijación en tronco de anclaje**: Dé dos vueltas completas con la soga alrededor de un tronco verde más grueso que el antebrazo.\\n4. **Prueba de carga con 50kg**: Aférrese con las manos a la soga y descargue **más de 50kg de peso corporal** para verificar la ausencia de deslizamiento.\",\n      \"actionNote\": \"> Criterio de prueba de tracción: Si escucha fibras quebrarse o un empalme cede unos milímetros, envuelva una vaina delgada de fibra adicional sobre el sector afectado.\",\n      \"svgFileName\": \"pr05-step-05.svg\",\n      \"svgLabels\": [\n        \"① Nudo final de tope a 3cm del extremo\",\n        \"② Recortar fibras sueltas con lasca de piedra\",\n        \"③ Rodear árbol y tirar con peso corporal (50kg+)\",\n        \"④ Cuerda salvaje terminada de 5mm (5m largo)\",\n        \"⑤ Lista para refugios, hacha de piedra y arco\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Error Fatal: Atar lianas verdes enteras sin pelar la corteza\",\n    \"description\": \"Atar ramas o lianas enteras directamente al refugio o al hacha parece firme al principio, pero al secarse la savia en pocas horas se encogen, quedan flojas y el centro leñoso se parte como una galleta seca. Siempre pele la corteza y trence solo la fibra interna.\",\n    \"consequence\": \"Consecuencia: El techo del refugio se desploma mientras duerme o la hoja del hacha sale despedida causando heridas graves\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Cómo hacer una cuerda salvaje irrompible con las manos cuando no tienes nada en el bosque.\",\n    \"body\": \"Raspa la corteza marrón de una liana viva y saca la fibra blanca interna. Remójala 20 minutos y machácala con una piedra redonda hasta suavizarla. Dóblala, retuerce el cabo superior hacia afuera y crúzalo hacia ti. Superpón 10cm de fibra nueva para alargarla sin límite.\",\n    \"outro\": \"Soporta más de 50kg colgada de un árbol. Lista para atar tu refugio o fijar un hacha de piedra.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr05-outcome.svg\",\n    \"title\": \"Rollo de Cuerda Natural de 2 Cabos con Torsión Inversa Completado\",\n    \"description\": \"Una bobina de cuerda uniforme de 8 mm trenzada en sentido inverso con fibras de corteza, capaz de resistir más de 90 kgf de carga de tracción.\"\n  },\n  \"createdAt\": \"2026-10-13T13:20:00.000Z\",\n  \"updatedAt\": \"2026-10-16T13:34:53+09:00\",\n  \"contentHash\": \"474efda727971489\"\n}","content/protocols/locales/05-natural-cordage.ja.json":"{\n  \"protocolId\": \"PR-05\",\n  \"category\": \"TOOLS\",\n  \"title\": \"木の皮とクズのつるを撚って切れない野生ロープを作る方法\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[必須サバイバル]\",\n  \"summary\": \"シェルターの柱を結んだり、石斧を固定したり、火起こしをするには丈夫な紐が不可欠です。生のつるをそのまま結ぶと乾いた時に縮んで折れますが、内側の白い繊維を取り出して2本を逆方向にねじり合わせれば、大人の体重にも耐える強靭な野生ロープが作れます。\",\n  \"timeRequired\": \"40分\",\n  \"successRate\": \"95% (逆撚り法を守った場合)\",\n  \"difficulty\": \"普通 (素手で作業可能)\",\n  \"outputPerHour\": \"5m / 40分\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"生きているクズのつる、シナノキ・ヤナギ・イラクサの茎 (腕の長さ10〜15本)\",\n      \"desc\": \"曲げた時にポキッと折れずにしなやかに曲がり、爪で表面を削ると緑色の水分が見える新鮮な茎を選びます。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"外皮を削り落とす鋭い石の欠片 1個\",\n      \"desc\": \"茎の外側にある茶色い外皮だけを軽く削り落とすために使います。内側の繊維を切らないよう適度な角がある石を選びます。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"繊維を叩く平らな台石と拳大の丸石\",\n      \"desc\": \"水に浸した内皮を平らな石の上に置き、丸石で優しく叩いて髪の毛のように細く柔らかい繊維にほぐします。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"内皮を浸す川の水または溜まり水\",\n      \"desc\": \"剥ぎ取った内皮を20〜30分間浸して硬い樹液を抜き、撚っている間に繊維が折れないよう湿り気を保ちます。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"ステップ1: しなやかな茎を選び、茶色い外皮を削って白い内皮を剥ぎ取る\",\n      \"description\": \"1. **生木の弾力性確認**: 茎をゆっくり二つ折りに曲げ、折れずに**90度以上**しなる生きた茎を選別します。\\n2. **外側粗皮の削り落とし**: 石の角を斜めに当て、外側の脆い**茶色い外皮**だけを慎重に削り落とします。\\n3. **靭皮繊維層の露出点検**: 削った表面から水分を含んだ**白く強靭な内皮繊維**が現れたことを目で確認します。\\n4. **中心木質部の剥離分離**: 根元を爪でめくり、上に向かって長く引っ張って中心の**硬い木芯を分離**しリボン状の内皮のみを剥ぎ取ります。\",\n      \"actionNote\": \"> 採取の鉄則: 地面に落ちて乾いた枯れ枝は繊維が腐っており、引っ張るとすぐ粉砕します。必ず生きた枝や切りたての新鮮な茎から内皮を採取してください。\",\n      \"svgFileName\": \"pr05-step-01.svg\",\n      \"svgLabels\": [\n        \"① 石の角で粗い外皮だけを優しく削り落とす\",\n        \"② 折れやすい茶色い外皮 (削って捨てる)\",\n        \"③ 強靭で白い内皮繊維層 (ロープの主材料)\",\n        \"④ 中央の硬い木の芯 (剥がして捨てる)\",\n        \"⑤ 曲げても折れずにしなる生きた茎\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BOTANY\",\n        \"title\": \"師部組織（靭皮繊維）の引張強度とペクチン分解\",\n        \"text\": \"外皮と木質部の間に位置する**師部組織（靭皮繊維）**は、平行配向した結晶性セルロース構造により軟鋼（Mild Steel）の**約50%**に達する引張強度を発揮します。機械的削り取りにより純粋な靭皮のみを傷つけずに分離できます。\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"ステップ2: 川の水に20分浸し、丸石で叩いて糸のように柔らかくほぐす\",\n      \"description\": \"1. **水浸漬とペクチン溶出**: 剥離した内皮リボンを川の水に**20〜30分間**浸し、硬い樹液を溶かし出します。\\n2. **台石への水平展延**: 柔らかくなった内皮をガタつきのない**平らな川石の台**の上に広く伸ばします。\\n3. **丸石による解繊処理**: 丸石で上から下へ優しく滑らせるように叩き、硬い木目を砕いて**微細な繊維束**にほぐします。\\n4. **均等2分割配分**: 手で引っ張っても切れないしなやかな繊維束を、**太さが全く同じ2本の束**に均等に分けます。\",\n      \"actionNote\": \"> 叩き加減の調整: 強く叩きつけると繊維組織が切断されます。丸石で優しく押し潰しながら伸ばすことで長い繊維を保てます。\",\n      \"svgFileName\": \"pr05-step-02.svg\",\n      \"svgLabels\": [\n        \"① 川の水に20分以上浸して柔らかくした内皮\",\n        \"② 丸石で優しく叩いて繊維の筋をほぐす\",\n        \"③ 髪の毛のように柔らかくほぐれた繊維束\",\n        \"④ 指の太さに均等に分けた2本の束\",\n        \"⑤ 下に敷いた安定した平らな川石\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"ステップ3: 外側にねじって手前に交差させる「逆撚り」を繰り返す\",\n      \"description\": \"1. **中央二つ折り保持**: 繊維束の中央を左手の親指と人差し指でしっかり挟んで半分に折り、**上の束**と**下の束**を作ります。\\n2. **個別外側ツイスト**: 右手で上の束をつまみ、体の外側（↑）に向かって張りが出るまで**時計回りにねじり**ます。\\n3. **全体内側クロス交差**: ねじった上の束を下の束越しに自分の手前（↓）へ越えさせ、**反時計回りに交差**させます。\\n4. **進行ロック前進**: 左手親指を前進させて交差点を強く固定し、新たに上に来た束を**外側ねじり➔手前交差**の順で反復します。\",\n      \"actionNote\": \"> 逆撚りロックの法則: 2本を同方向に巻くと手を離した瞬間にほどけます。個別ストランドを外側にねじり全体を手前に交差させることで、相反するトルクが釣り合い永久固定されます。\",\n      \"svgFileName\": \"pr05-step-03.svg\",\n      \"svgLabels\": [\n        \"① 上の束：体の外側(↑)へ強くねじる\",\n        \"② 互いに噛み合ったV字のロープ模様\",\n        \"③ 左手の親指と人差し指で交差点を押さえる\",\n        \"④ ねじった上の束を下の束越しに手前(↓)へ渡す\",\n        \"⑤ 手を離してもほどけない二重ロック構造\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD MECHANICS\",\n        \"title\": \"逆撚り法（Reverse-Wrap）の回転トルク相殺と自律固定力学\",\n        \"text\": \"個々のストランドを時計回り（Z撚り）にねじりながら全体を反時計回り（S撚り）に交差させることで、反対向きのねじれ弾性エネルギーが相殺され**トルク平衡（Torque Equilibrium）**に達します。この摩擦噛み合いにより、結び目なしでも手を離した時にほどけません。\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"ステップ4: 短くなった繊維に新しい束を10cm重ねて無限に継ぎ足す\",\n      \"description\": \"1. **継ぎ足しタイミング検知**: 片方のストランドが短くなり残りが**約10cm**に達した時点で継ぎ足しを行います。\\n2. **新規繊維の平行重合**: 新しい繊維束の端を短くなった束の脇に**10cmの長さ**で平行に密着させます。\\n3. **一体型同時撚り合わせ**: 重ねた2本を1本の束として扱い、同じように外側へねじって手前へ**3〜4回連続で交差**させます。\\n4. **継ぎ目オフセット配置**: 上の束と下の束の接続部が同じ位置に重ならないよう、**最低15cm以上の間隔**を離して配置します。\",\n      \"actionNote\": \"> 継ぎ目分散の原則: 2本の接続部が同じ位置に重なると局所的に膨らみ、引張荷重時に破断します。必ず15cm以上の距離を空けて交互に継ぎ足してください。\",\n      \"svgFileName\": \"pr05-step-04.svg\",\n      \"svgLabels\": [\n        \"① 残り10cmほどになり細くなった元の束\",\n        \"② 新しい繊維束を10cm並べて重ねる\",\n        \"③ 重ねた2本を1本として一緒にねじり込む\",\n        \"④ 膨らまず滑らかに繋がった継ぎ目\",\n        \"⑤ 上下の継ぎ目を15cm以上ずらして配置\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD TENSION\",\n        \"title\": \"継ぎ目オフセット分散（Staggered Splice）と界面せん断摩擦伝達\",\n        \"text\": \"2本のストランドの継ぎ目を同一点に集中させると断面積が急変し、引張荷重時に応力集中で破断します。継ぎ目を**最低15cm以上**ずらして分散配置することで、隣接する連続繊維が**界面せん断摩擦力**によって荷重を受け止め、本来の強度を100%保持します。\"\n      }\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"ステップ5: 端から3cmに止め結びを作り、木の幹に掛けて体重で引っ張りテスト\",\n      \"description\": \"1. **末端止め結び結束**: 目標の長さ（5m以上）に達したら、端から**3cmの位置**で輪を作って引き締め止め結びを作ります。\\n2. **石刃による毛羽立ち剪定**: 鋭利な石片でロープ表面を軽く削り、はみ出た毛羽立ちを整えて**直径5mm**の滑らかな断面に仕上げます。\\n3. **太木へのアンカー結束**: 腕よりも太い強固な生木の幹に完成したロープを2周以上巻き付けて固定します。\\n4. **体重50kg引張検証**: 両手でロープを握り**体重50kg以上**の全荷重をかけて力強く引き、継ぎ目の滑りがないことを確認します。\",\n      \"actionNote\": \"> 強度確認基準: 体重をかけた際に繊維が千切れる音がしたり継ぎ目が滑る場合は、その箇所の上から薄い繊維を巻き足して補強してください。\",\n      \"svgFileName\": \"pr05-step-05.svg\",\n      \"svgLabels\": [\n        \"① 端から3cmを折って結んだほどけ防止結び\",\n        \"② はみ出た毛羽立ちを石の刃できれいに整える\",\n        \"③ 木の幹に掛けて体重(50kg+)で引っ張りテスト\",\n        \"④ 完成した太さ5mmの野生ロープ (長さ5m)\",\n        \"⑤ シェルター結束・石斧固定・火起こし紐に活用\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"絶対にやってはいけないミス：皮を剥いていない緑の生づるをそのまま結んで使う\",\n    \"description\": \"急いでいるからといってクズのつるや枝を丸ごと巻いてシェルターの柱や石斧を結ぶと、最初は固く見えても半日ほどで水分が抜けて縮み、緩んでしまいます。さらに乾燥した木の芯は少しの衝撃で煎餅のように折れます。必ず外皮と芯を除き、白い内皮繊維だけを逆撚りして使ってください。\",\n    \"consequence\": \"結果：就寝中にシェルターの屋根が崩落するか、木を伐採中に石斧の刃が外れて大怪我をする\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"山の中で紐が1本もない時、素手で切れない野生ロープを撚る方法です。\",\n    \"body\": \"生きたクズのつるの茶色い外皮を石で削り、白い内皮だけを長く剥ぎ取ります。水に20分浸して丸石で叩くと糸のように柔らかくなります。半分に折り、上の束を外側にねじって手前に交差させましょう。短くなったら新しい繊維を10cm重ねれば無限に伸ばせます。\",\n    \"outro\": \"木に掛けて体重で引っ張っても切れません。シェルター作りや石斧の固定にすぐ使えます。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr05-outcome.svg\",\n    \"title\": \"2本撚り逆回転編み天然ロープ完成コイル束\",\n    \"description\": \"樹皮の内皮と葛の繊維を時計回りに撚り、反時計回りに交差編みして引張強度90kg以上に耐える、均一で滑らかな2本撚り天然サバイバルロープ束です。\"\n  },\n  \"createdAt\": \"2026-10-13T13:20:00.000Z\",\n  \"updatedAt\": \"2026-10-16T13:34:53+09:00\",\n  \"contentHash\": \"474efda727971489\"\n}","content/protocols/locales/05-natural-cordage.pt.json":"{\n  \"protocolId\": \"PR-05\",\n  \"category\": \"TOOLS\",\n  \"title\": \"Como trançar corda selvagem inquebrável com casca de árvore e cipó\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[SOBREVIVÊNCIA CRÍTICA]\",\n  \"summary\": \"Uma corda forte é indispensável para amarrar abrigos, fixar machados de pedra e fazer fogo com arco. Cipós verdes inteiros encolhem e quebram ao secar; porém, extrair a fibra branca interna e torcer dois cabos em sentidos opostos cria uma corda autotravante capaz de suportar o peso de um adulto.\",\n  \"timeRequired\": \"40 min\",\n  \"successRate\": \"95% (Com torção reversa)\",\n  \"difficulty\": \"Média (Apenas com as mãos)\",\n  \"outputPerHour\": \"5m / 40 min\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Cipós vivos, tília, salgueiro ou caules de urtiga (10~15 hastes do comprimento do braço)\",\n      \"desc\": \"Escolha hastes vivas que dobrem sem quebrar e mostrem umidade verde ao raspar com a unha.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 lasca de pedra com borda afiada para raspar\",\n      \"desc\": \"Usada para raspar suavemente a casca externa marrom sem cortar as fibras brancas internas.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Pedra plana de base e pedra redonda do tamanho do punho\",\n      \"desc\": \"Para bater suavemente na casca interna demolhada até soltar fios macios como cabelo.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Água de riacho ou poça para demolhar\",\n      \"desc\": \"Deixe a casca interna de molho por 20~30 minutos para amolecer a seiva e manter as fibras flexíveis.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Passo 1: Escolher hastes flexíveis, raspar a casca externa e puxar a fibra branca interna\",\n      \"description\": \"1. **Teste de flexibilidade da haste**: Curve a haste lentamente em **mais de 90 graus** para garantir elasticidade sem fraturas.\\n2. **Raspagem da casca externa**: Apoie a quina de uma pedra em ângulo para raspar somente a **casca marrom quebradiça**.\\n3. **Exposição do líber interno**: Inspecione visualmente o surgimento das **fibras brancas resistentes e úmidas** sob a superfície raspada.\\n4. **Separação do miolo lenhoso**: Destaque a ponta com a unha e puxe no sentido do caule para **desprender o miolo duro** e extrair as fitas de fibra.\",\n      \"actionNote\": \"> Princípio de colheita: Galhos secos e mortos no chão contêm fibras podres que se rompem sob tração. Colete a casca interna sempre de ramos vivos ou recém-cortados.\",\n      \"svgFileName\": \"pr05-step-01.svg\",\n      \"svgLabels\": [\n        \"① Raspar casca externa com quina de pedra\",\n        \"② Casca marrom quebradiça (raspar e descartar)\",\n        \"③ Fibra interna branca e forte (material da corda)\",\n        \"④ Miolo central de madeira dura (descartar)\",\n        \"⑤ Haste viva flexível que dobra sem quebrar\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BOTANY\",\n        \"title\": \"Resistência à tração do floema e separação de pectina\",\n        \"text\": \"O **tecido floemático (fibras do líber)** entre a casca externa e o xilema é composto por microfibrilas paralelas de celulose que atingem **50% da resistência à tração do aço macio**. A raspagem mecânica cuidadosa isola essas fibras contínuas sem fissuras por cisalhamento.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Passo 2: Deixar 20 minutos na água e bater com pedra redonda até amaciar\",\n      \"description\": \"1. **Demolha e lixiviação de pectina**: Mergulhe as fitas de casca em água por **20 a 30 minutos** para dissolver resinas e seiva endurecida.\\n2. **Assentamento na bigorna de pedra**: Estenda as tiras amolecidas sobre uma **pedra de rio plana e firme**.\\n3. **Amaciamento por percussão**: Bata e role suavemente uma pedra redonda ao longo do comprimento para desfibrar em **filamentos finos e macios**.\\n4. **Separação em dois feixes simétricos**: Divida o feixe em **2 pernas iguais** com espessura e densidade idênticas.\",\n      \"actionNote\": \"> Força de batida: Golpear com violência corta as fibras longitudinais. Pressione e role suavemente para preservar fios longos e íntegros.\",\n      \"svgFileName\": \"pr05-step-02.svg\",\n      \"svgLabels\": [\n        \"① Casca interna de molho 20+ min no riacho\",\n        \"② Bater suave com pedra redonda para abrir fibras\",\n        \"③ Feixe de fibras macias como fios de cabelo\",\n        \"④ Dois cabos iguais da grossura de um dedo\",\n        \"⑤ Pedra plana firme apoiada no chão\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Passo 3: Torcer para fora e cruzar para o corpo (Torção Reversa)\",\n      \"description\": \"1. **Pinça na dobra central**: Dobre o feixe ao meio prendendo o laço entre polegar e indicador esquerdos para criar **perna superior e inferior**.\\n2. **Torção horária individual**: Com a mão direita, torça a perna de cima para fora (↑) em **rotação horária** até tensionar.\\n3. **Cruzamento anti-horário de conjunto**: Passe a perna superior torcida por cima da inferior em direção a você (↓) em **movimento anti-horário**.\\n4. **Travamento progressivo contínuo**: Desloque o polegar esquerdo segurando o cruzamento e repita a sequência de **torcer para fora e cruzar para dentro**.\",\n      \"actionNote\": \"> Lei do autotravamento: Girar as duas pernas na mesma direção desenrola a corda na hora. Torcer cada perna para fora e trançar para dentro equilibra o torque e trava a corda de forma permanente.\",\n      \"svgFileName\": \"pr05-step-03.svg\",\n      \"svgLabels\": [\n        \"① Cabo superior: torcer firme para fora (↑)\",\n        \"② Padrão de corda travado em escama\",\n        \"③ Prender cruzamento com polegar e indicador\",\n        \"④ Cruzar cabo superior sobre o inferior para si (↓)\",\n        \"⑤ Trava reversa que não desmancha ao soltar\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD MECHANICS\",\n        \"title\": \"Equilíbrio de torque e autotravamento mecânico na torção reversa\",\n        \"text\": \"Ao torcer cada perna no sentido horário (torção Z) enquanto se trançam no sentido anti-horário (torção S), as energias elásticas de torção opostas anulam-se em **equilíbrio de torque**. Este travamento por atrito dispensa nós e impede o desenrolamento mesmo ao soltar a corda.\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Passo 4: Sobrepor 10cm de fibra nova para emendar comprimento infinito\",\n      \"description\": \"1. **Identificação da zona de emenda**: Localize quando qualquer das pernas afinar até restar uma **ponta de cerca de 10cm**.\\n2. **Sobreposição longitudinal**: Posicione a ponta de um feixe novo ao lado do cabo curto em **10cm de contato paralelo**.\\n3. **Trançado unificado**: Segure as duas pontas juntas como se fossem uma só e torça por **3 a 4 ciclos consecutivos**.\\n4. **Espaçamento defasado de emendas**: Mantenha as emendas da perna superior e inferior separadas por uma **distância mínima de 15cm**.\",\n      \"actionNote\": \"> Regra do espaçamento: Fazer as duas emendas no mesmo ponto gera um caroço que se rompe sob tensão. Alterne as emendas com pelo menos 15cm de distância.\",\n      \"svgFileName\": \"pr05-step-04.svg\",\n      \"svgLabels\": [\n        \"① Cabo antigo afinando com 10cm restantes\",\n        \"② Encostar fibra nova ao lado (10cm sobrepostos)\",\n        \"③ Torcer as duas pontas juntas como um cabo só\",\n        \"④ Emenda lisa sem caroços ou pontos fracos\",\n        \"⑤ Desencontrar emendas de cima e de baixo em 15cm\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD TENSION\",\n        \"title\": \"Arquitetura de emenda defasada e atrito interfacial de cisalhamento\",\n        \"text\": \"Sobrepor emendas em ambas as pernas no mesmo ponto axial gera variações bruscas de seção e rompimento por concentração de tensões. O espaçamento de **pelo menos 15cm** transfere a carga de tração por **atrito interfacial de cisalhamento** para a perna contínua paralela, mantendo 100% da carga de ruptura.\"\n      }\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Passo 5: Dar nó de trava na ponta e testar com o peso do corpo em uma árvore\",\n      \"description\": \"1. **Nó terminal de retenção**: Ao alcançar o comprimento final (5m+), forme um laço a **3cm da ponta** e aperte um nó simples de retenção.\\n2. **Aparagem com lasca de pedra**: Raspe suavemente uma lasca de pedra na corda para aparar fiapos até obter **seção uniforme de 5mm**.\\n3. **Ancoragem em tronco firme**: Passe a corda duas vezes ao redor de um tronco verde e grosso mais espesso que o antebraço.\\n4. **Verificação com carga de 50kg**: Segure a corda com as duas mãos e projete **mais de 50kg de peso corporal** para checar a solidez das emendas.\",\n      \"actionNote\": \"> Critério de carga: Se escutar estalos ou notar deslizamento na emenda, enrole uma camada fina de fibra adicional sobre a região afetada.\",\n      \"svgFileName\": \"pr05-step-05.svg\",\n      \"svgLabels\": [\n        \"① Nó de trava a 3cm da ponta final\",\n        \"② Aparar fiapos soltos com lasca de pedra\",\n        \"③ Passar na árvore e puxar com peso do corpo (50kg+)\",\n        \"④ Corda selvagem pronta de 5mm (5m compr.)\",\n        \"⑤ Pronta para abrigo, machado de pedra e arco\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Erro Fatal: Amarrar cipós verdes inteiros sem descascar\",\n    \"description\": \"Enrolar cipós ou galhos verdes inteiros diretamente no abrigo ou no machado parece firme na hora, mas em poucas horas a seiva seca, o cipó encolhe e afrouxa, e o miolo de madeira quebra como biscoito seco no primeiro impacto. Sempre descasque e trance apenas a fibra interna.\",\n    \"consequence\": \"Consequência: O teto do abrigo desaba durante o sono ou a lâmina do machado escapa causando ferimentos graves\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Como fazer uma corda selvagem inquebrável com as mãos quando você não tem nada na mata.\",\n    \"body\": \"Raspe a casca marrom de um cipó vivo e puxe a fibra branca interna. Deixe 20 minutos na água e bata com uma pedra redonda até amaciar. Dobre ao meio, torça o cabo de cima para fora e cruze para o seu lado. Sobreponha 10cm de fibra nova para emendar sem limite.\",\n    \"outro\": \"Aguenta mais de 50kg presa em uma árvore. Pronta para amarrar abrigos e fixar machados de pedra.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr05-outcome.svg\",\n    \"title\": \"Rolo de Corda Natural de 2 Pernas com Torção Reversa Concluído\",\n    \"description\": \"Uma bobina de corda uniforme de 8 mm trançada com fibras de casca interna em torção reversa, suportando mais de 90 kgf de tração sem deslizar.\"\n  },\n  \"createdAt\": \"2026-10-13T13:20:00.000Z\",\n  \"updatedAt\": \"2026-10-16T13:34:53+09:00\",\n  \"contentHash\": \"474efda727971489\"\n}","content/protocols/locales/05-natural-cordage.zh-TW.json":"{\n  \"protocolId\": \"PR-05\",\n  \"category\": \"TOOLS\",\n  \"title\": \"用樹皮與葛藤搓出不斷裂野生繩索的方法\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[必備求生]\",\n  \"summary\": \"搭建避難所綁木柱、固定石斧或使用弓鑽生火時，堅固的繩索不可或缺。若直接拿整根青藤捆綁，乾掉後會收縮並脆裂；只有刮除粗外皮、取出白色內皮纖維，並將兩股纖維反向扭轉交疊，才能做出放手也不會散開、能承受成人體重的強韌野生繩索。\",\n  \"timeRequired\": \"40分鐘\",\n  \"successRate\": \"95% (遵守反向搓繩法時)\",\n  \"difficulty\": \"中等 (徒手即可完成)\",\n  \"outputPerHour\": \"5公尺 / 40分鐘\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"活的葛藤，或椴樹、柳樹、蕁麻莖幹 (手臂長約10~15根)\",\n      \"desc\": \"選擇對折時不會「啪」一聲斷裂、能柔韌彎曲，且用指甲刮表皮會露出翠綠水氣的新鮮藤蔓或樹枝。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"刮除外皮用的帶稜角石片 1塊\",\n      \"desc\": \"用來輕輕刮掉莖幹最外層粗糙易碎的褐色外皮。挑選邊緣適中、不會割斷內部白色纖維的石片。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"敲打纖維用的平坦墊石與拳頭大的圓石\",\n      \"desc\": \"將泡軟的內皮攤在平坦大石上，用圓石輕輕敲打，使纖維鬆開成如頭髮般細軟的絲束。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"浸泡內皮的溪水或積水\",\n      \"desc\": \"將剛剝下的內皮浸泡20~30分鐘以軟化僵硬樹液，並在搓繩過程中保持纖維濕潤不斷裂。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"第1步：挑選柔韌藤莖，刮除褐色粗外皮並撕下白色內皮\",\n      \"description\": \"1. **生鮮莖幹彈性檢驗**：緩慢將藤莖對折彎曲超過**90度角**，確認不會折斷、具備良好回彈彈性。\\n2. **外層粗糙外皮刮除**：將石片邊緣斜貼莖幹，細心刮除外層易脆斷的**褐色外皮**。\\n3. **韌皮纖維層露出確認**：用肉眼檢視確認刮削面底下露出帶水分的**雪白強韌內皮纖維**。\\n4. **木質中心剝離分離**：用指甲挑起末端邊緣並順向拉扯，將**堅硬的木芯分離**並剝下長帶狀內皮。\",\n      \"actionNote\": \"> 採集原則：掉在地上的枯枝纖維已腐爛，受力即碎。務必從活枝或剛折下的鮮嫩莖幹中採集內皮。\",\n      \"svgFileName\": \"pr05-step-01.svg\",\n      \"svgLabels\": [\n        \"① 用石頭稜角輕輕刮除粗糙外皮\",\n        \"② 易碎的褐色外皮 (刮除丟棄)\",\n        \"③ 強韌雪白的內皮纖維層 (做繩核心材料)\",\n        \"④ 中央堅硬的木質內芯 (剝離丟棄)\",\n        \"⑤ 彎曲時不會折斷的鮮活柔韌藤莖\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BOTANY\",\n        \"title\": \"韌皮部組織（Phloem）韌皮纖維抗拉強度與果膠分離\",\n        \"text\": \"位於外樹皮與木質部之間的**韌皮部組織（韌皮纖維）**由平行排列的結晶纖維素微纖維構成，抗拉強度可達低碳結構鋼（Mild Steel）的**約50%**。透過精細機械刮削能完整分離承重纖維而不產生剪切損傷。\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"第2步：泡溪水20分鐘後，用圓石敲打成細軟絲束\",\n      \"description\": \"1. **泡水溶出僵硬果膠**：將剝下的內皮帶浸入溪水中**20~30分鐘**，徹底溶解僵硬樹液膠質。\\n2. **平坦砧石展開定位**：將吸水變軟的內皮平攤在平穩不搖晃的**平坦河石**上方。\\n3. **圓石推壓碎紋開纖**：手持光滑圓石由上往下輕壓推揉，將粗硬木紋敲開成**蓬鬆的微細纖維束**。\\n4. **均稱二股等量劃分**：將拉扯不斷的長纖維束均勻分成**粗細完全相同的兩股**。\",\n      \"actionNote\": \"> 敲打力道調控：像砍刀一樣猛力重擊會砸斷纖維。以圓石溫和推揉擠壓，方能保留長纖維的完整抗拉長度。\",\n      \"svgFileName\": \"pr05-step-02.svg\",\n      \"svgLabels\": [\n        \"① 泡溪水20分鐘以上軟化的內皮\",\n        \"② 用圓石輕輕敲打使纖維紋理鬆開\",\n        \"③ 如頭髮般細軟蓬鬆的纖維絲束\",\n        \"④ 均勻分成手指粗細的兩股纖維\",\n        \"⑤ 底部墊著穩固不搖晃的平坦河石\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"第3步：向外扭轉、向內交疊，重複「反向搓繩法」\",\n      \"description\": \"1. **中央打折起點捏合**：用左手拇指與食指緊捏長纖維束中心並對折，劃分出**上股**與**下股**。\\n2. **單股向外順時針扭轉**：右手抓住上股向遠離身體的外側（↑）用力作**順時針扭轉**直到緊繃。\\n3. **整股向內逆時針交疊**：將扭緊的上股越過下股朝身體側（↓）翻過來，完成**逆時針方向交疊**。\\n4. **持續鎖定推進交替**：左手拇指前移死死捏住新結點，對新移到上方的股線重複**向外扭緊後向內翻越**的循環動作。\",\n      \"actionNote\": \"> 反向自鎖法則：兩股朝同方向捲一鬆手即刻散開。個別股向外扭、整體向內翻，反向回彈力相互抵消形成永久機械自鎖。\",\n      \"svgFileName\": \"pr05-step-03.svg\",\n      \"svgLabels\": [\n        \"① 上股纖維：朝身體外側(↑)用力扭緊\",\n        \"② 互相回彈咬合成鋸齒狀的緊密繩紋\",\n        \"③ 左手拇指與食指捏緊剛交疊的結點\",\n        \"④ 將扭緊的上股越過下股朝身體側(↓)翻過來\",\n        \"⑤ 放手也絕對不會鬆開的反向互鎖結構\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD MECHANICS\",\n        \"title\": \"反向搓繩（Reverse-Wrap）扭矩平衡與自鎖力學機制\",\n        \"text\": \"將單一股線順時針扭轉（Z撚），同時將兩股線逆時針交疊（S撚），相反方向的彈性扭矩能量相互抵消達成**扭矩平衡（Torque Equilibrium）**。此種摩擦咬合機制無需打結即可在鬆手時防止解開。\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"第4步：將新纖維重疊10公分捻入，無限延長繩索長度\",\n      \"description\": \"1. **續接時機精準判定**：當任一股線變細、剩下**約10公分末端**時即判定為續接時機。\\n2. **新舊纖維平行重疊**：取新纖維束端部貼合在即將耗盡的舊股旁，形成**10公分重疊接觸區**。\\n3. **合股同向連續扭轉**：將重疊的兩根纖維視為單一股線，同樣向外扭緊並向內翻越**連續交疊3~4圈**。\\n4. **接縫錯開間距保持**：嚴格確保上股與下股的接續點相互錯開**至少15公分以上**的軸向距離。\",\n      \"actionNote\": \"> 錯位接續原則：若兩股接縫重疊在同一處，會腫脹並在受重拉時撕裂斷開。務必保持15公分以上的交錯間距。\",\n      \"svgFileName\": \"pr05-step-04.svg\",\n      \"svgLabels\": [\n        \"① 剩下約10公分並逐漸變細的舊股\",\n        \"② 取新纖維束並排重疊10公分\",\n        \"③ 將重疊的兩條當作同一股一起扭緊\",\n        \"④ 不鼓包且平滑銜接的接縫部位\",\n        \"⑤ 上下兩股接縫位置錯開一拃(15公分)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD TENSION\",\n        \"title\": \"錯位接續結構（Staggered Splice）與介面剪切摩擦傳導\",\n        \"text\": \"若將兩股接縫置於同一軸向點，會造成截面突變與應力集中斷裂。將接縫錯開**至少15公分以上**，拉伸荷載即可透過**介面剪切摩擦力**傳遞至相鄰連續股線，完整保有100%抗拉強度。\"\n      }\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"第5步：末端打防鬆結，掛在樹幹上用全身體重拉扯測試\",\n      \"description\": \"1. **末端單結收尾鎖死**：達到預定長度（5公尺以上）後，在末端**3公分處**打一個結實的單結防止纖維散開。\\n2. **石片修整雜毛毛刺**：拿鋒利石片沿繩索輕刮掃除竄出的雜毛，修整為**直徑5mm**的勻稱圓截面。\\n3. **牢固樹幹雙圈纏繞**：將完成的繩索在比前臂粗的強壯生木樹幹上環繞兩圈固定。\\n4. **體重50公斤極限拉伸**：雙手緊握繩端，掛上**50公斤以上**的全身體重全力後拉，確認接縫毫無滑脫現象。\",\n      \"actionNote\": \"> 拉力檢驗標準：若聽聞纖維斷裂微響或接縫位移，請立即在該區段外側再包覆纏繞一層薄纖維加固。\",\n      \"svgFileName\": \"pr05-step-05.svg\",\n      \"svgLabels\": [\n        \"① 距離末端3公分處打緊防鬆收尾結\",\n        \"② 用石片將竄出的毛邊刮除修整乾淨\",\n        \"③ 繞在樹幹上掛上體重(50kg+)用力拉扯測試\",\n        \"④ 完成粗度5mm的強韌野生繩索 (長5m)\",\n        \"⑤ 立即用於綁避難所木柱、固定石斧與弓鑽弦\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"絕對不能犯的錯誤：直接拿未剝皮的綠色生藤捆綁重物\",\n    \"description\": \"若為了省事直接拿整根青藤或綠樹枝去綁避難所木柱或石斧，當下看似緊固，但只要過半天水分蒸發，藤條就會萎縮鬆脫，中間的木芯更會在受力時像乾餅乾一樣脆裂。務必去除外皮與木芯，只取白色內皮纖維反向搓成繩索。\",\n    \"consequence\": \"後果：睡覺時避難所屋頂坍塌砸傷自己，或砍樹時石斧刀刃飛出造成嚴重外傷\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"在深山裡連一條繩子都沒有時，如何徒手搓出拉不斷的野生繩索？\",\n    \"body\": \"用石頭刮掉鮮活葛藤的褐色外皮，撕下白色內皮纖維。泡水20分鐘後用圓石敲軟成絲束。對折後將上股向外扭緊，再越過下股朝自己翻過來。變短時重疊10公分新纖維就能無限接長。\",\n    \"outro\": \"掛在樹幹上用50公斤體重拉扯也不斷裂，綁避難所、固定石斧都能馬上派上用場。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr05-outcome.svg\",\n    \"title\": \"雙股反向搓捻天然繩索完成捲束\",\n    \"description\": \"將樹皮內韌皮與葛藤纖維順時針搓捻、逆時針交叉纏繞，具備90公斤以上抗拉強度的勻稱平滑雙股天然生存繩索捲束完成形態。\"\n  },\n  \"createdAt\": \"2026-10-13T13:20:00.000Z\",\n  \"updatedAt\": \"2026-10-16T13:34:53+09:00\",\n  \"contentHash\": \"474efda727971489\"\n}","content/protocols/locales/06-clay-hearth.de.json":"{\n  \"protocolId\": \"PR-06\",\n  \"category\": \"SHELTER\",\n  \"title\": \"Wie man eine primitive Lehmofenfeuerstelle baut, um Wind abzuhalten und Hitze zu speichern\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[LEBENSWICHTIGE WÄRME & UNTERKUNFT]\",\n  \"summary\": \"Ein offenes Bodenfeuer verliert über 80% seiner Wärme an den Wind und verbraucht dreimal mehr Brennholz, während umherfliegende Funken eine schwere Brandgefahr darstellen. Durch den Bau eines Kuppelofens aus Lehm, Sand, trockenem Gras und trockenen Steinen entsteht eine wetterfeste Koch- und Wärmestelle, die Hitze speichert und die ganze Nacht über warm hält.\",\n  \"timeRequired\": \"3 Stunden\",\n  \"successRate\": \"90% (Mit langsamer Vortrocknung)\",\n  \"difficulty\": \"Mittel (Lehmkneten & Steinmauern)\",\n  \"outputPerHour\": \"1 Dauerhafter Ofen\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"2 Schalen klebriger roter Lehm (an Uferböschungen ausgegraben)\",\n      \"desc\": \"Wählen Sie dichten, bindigen Lehm, der sich wie Teig formen lässt, ohne zu zerbröckeln. Dient als thermisches Hauptbindemittel.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 Schale grober Flusssand (trockener Sand mit Mineralkörnern)\",\n      \"desc\": \"Reiner Lehm schrumpft und reißt beim Trocknen. Grober Sand bildet das tragende Gerüst, das Rissbildung verhindert.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"1 Schale fingerlang geschnittenes trockenes Gras oder Stroh\",\n      \"desc\": \"Wirkt als Faserarmierung in der Lehmmischung und verhindert, dass die Wände unter großer Hitze zerspringen.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"15~20 staubtrockene Bruchsteine (faust- bis kopf傚groß)\",\n      \"desc\": \"Wassergesättigte Flusssteine explodieren bei Hitzeeinwirkung. Verwenden Sie nur trockene Steine von sonnigen Hängen mindestens 10 m vom Wasser entfernt.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Schritt 1: 2 Teile Lehm, 1 Teil Sand und 1 Teil trockenes Gras mit Wasser zu zähem Cob-Mörtel stampfen\",\n      \"description\": \"1. **Mischungsverhältnis abmessen**: Breiten Sie **2 Schalen roten Lehm**, **1 Schale groben Sand** und **1 Schale fingerlanges Trockengras** flach auf dem Boden aus.\\n2. **Schrittweise Wasserzugabe**: Fügen Sie Wasser portionsweise hinzu und stampfen Sie die Masse mit den Fersen für **mindestens 10 Minuten** intensiv durch.\\n3. **Falten und Kompaktieren**: Falten Sie den Lehmkuchen mehrfach um und verdichten Sie ihn wiederholt, bis eine homogene Masse entsteht.\\n4. **Plastizitätsprüfung**: Rollen Sie eine faustgroße Kugel und stellen Sie sicher, dass unter leichtem Druck **keine Oberflächenrisse** auftreten.\",\n      \"actionNote\": \"> Feuchtigkeitskontrolle: Zuviel Wasser erzeugt schlammigen Brei, der absackt; zuwenig lässt den Mörtel bröckeln. Streben Sie eine zähe Konsistenz wie festen Brotteig an.\",\n      \"svgFileName\": \"pr06-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // CLAY TEMPERING & FIBER MATRIX BLUEPRINT\",\n        \"① 2 Teile klebriger roter Lehm\",\n        \"Bindiges mineralisches Grundmaterial\",\n        \"+\",\n        \"② 1 Teil grober Flusssand\",\n        \"Verhindert Schrumpfung und Rissbildung\",\n        \"+\",\n        \"③ Fingerlange trockene Grasfasern\",\n        \"Strukturelle Armierungsmatrix\",\n        \"④ Wasser schrittweise zugeben und mit Fersen stampfen\",\n        \"Niemals überschwemmen; falten & durchtreten\",\n        \"⑤ Fertige zähe Lehmkugel\",\n        \"Zu fester faustgroßer Kugel formbar\",\n        \"Keine Risse an der Außenfläche\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD CERAMICS\",\n        \"title\": \"Feuerfest-Magerung und schwindungsresistente Verbundmatrix\",\n        \"text\": \"Reiner Ton erleidet beim Trocknen einen linearen Schwund von **10–15%** und reißt beim Brennen auf. Die Magerung mit Quarzsand und organischen Strohfasern im **Volumenverhältnis 2:1:1** erzeugt ein elastisches Gerüst, in dem pyrolysierte Fasern Mikroporen hinterlassen, die thermische Ausdehnungsspannungen elastisch abfangen.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Schritt 2: Faustgroße trockene Steine hufeisenförmig auf trockenem Boden als Fundament anordnen\",\n      \"description\": \"1. **Öffnungswinkel ausrichten**: Lassen Sie eine Beschickungsöffnung von **Breite ca. 20cm** auf der windabgewandten Seite frei.\\n2. **Hufeisen-Steinkranz**: Ordnen Sie faustgroße, trockene Bruchsteine in stabiler **U-Form als Basis** an.\\n3. **Boden-Wärmedämmung**: Bringen Sie im Innenbereich trockenen Sand und Kies in **Dicke von 2–3cm** ein, um Kältebrücken zum Boden abzuriegeln.\\n4. **Fugenmörtel-Verdichtung**: Drücken Sie zähen Lehmmörtel mit den Fäusten kraftvoll in jede Steinfuge, um alle Hohlräume luftdicht zu verschließen.\",\n      \"actionNote\": \"> Windausrichtung: Liegt die Öffnung im Luv, drückt Gegenwind Funken und Rauch ins Gesicht. Richten Sie die Feueröffnung immer windabgewandt oder schräg aus.\",\n      \"svgFileName\": \"pr06-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // FOUNDATION LAYOUT & AIR ENTRY SCHEMATIC\",\n        \"① Vordere Holzbeschickungsöffnung (20 cm breit)\",\n        \"Optimale Breite für Holz & Luftzufuhr\",\n        \"② Hufeisenförmige trockene Fundamentsteine\",\n        \"Tragendes Primärfundament\",\n        \"③ Dicker Lehmmörtel in Steinfugen\",\n        \"Dichtet Fugen gegen Nebenluft ab\",\n        \"④ Trockene Sand- & Kiesschicht am Boden\",\n        \"Wärmesperre gegen kalten Untergrund\",\n        \"⑤ Windabgewandte Ausrichtung der Öffnung\",\n        \"Schützt die Glut vor Windböen\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Schritt 3: Steine und Lehm schichtweise versetzt zu einer kniehohen Kuppel aufmauern\",\n      \"description\": \"1. **Mörtelbett vorbereiten**: Tragen Sie auf das Steinfundament eine handbreite Lehmschicht von **Dicke ca. 5cm** auf.\\n2. **Verzahnte Steinlagen**: Setzen Sie die nächste Steinreihe versetzt über die Stoßfugen und betten Sie alle Steine vollflächig in Mörtel ein.\\n3. **Einwärts geneigte Kuppel**: Neigen Sie die Wandlagen nach innen, bis eine kuppelförmige Brennkammer von **Höhe ca. 45cm** entsteht.\\n4. **Innenwand-Glättung**: Streichen Sie die Brennkammerinnenwand mit nassen Händen zu einer glatten Reflexionsfläche ohne Kanten aus.\",\n      \"actionNote\": \"> Struktur-Regel: Reine Lehmwände sacken unter dem Eigengewicht ein. Verwenden Sie stets ein tragendes Steingerüst, vollflächig umhüllt von dickem Lehmmörtel.\",\n      \"svgFileName\": \"pr06-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DOME CHAMBER CROSS-SECTION & THERMAL CURVATURE\",\n        \"45cm\",\n        \"① Querschnitt aus Stein & Lehmmörtel\",\n        \"Verzahnte Steine verhindern Einsturz\",\n        \"② Handtellerdicke (5 cm) wärmedämmende Lehmwand\",\n        \"Hohe Speichermasse hält Wärme über Nacht\",\n        \"③ Glatte wärmereflektierende Innenfläche\",\n        \"Mit nasser Hand für guten Zug geglättet\",\n        \"④ Kreisförmige innere Brennkammer\",\n        \"⑤ Kniehohe Gesamthöhe (45 cm)\",\n        \"Optimales Verhältnis aus Volumen & Kochhöhe\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"Strahlungskonzentration in der Halbkugelkuppel und 650°C Wärmespeichermasse\",\n        \"text\": \"Die parabolische Innenwölbung bündelt Infrarotstrahlung als Schwarzkörperstrahler punktgenau auf die obere Kochzone. Die **5cm dicke** hochdichte Lehmhülle besitzt eine enorme Wärmekapazität und konserviert **300–650°C** Brennraumtemperatur stundenlang nach Erlöschen der offenen Flammen.\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Schritt 4: Oberen Topfausschnitt anlegen und hinteren Kaminabzug ausstechen\",\n      \"description\": \"1. **Obere Kochöffnung freihalten**: Formen Sie am Scheitelpunkt eine kreisrunde Öffnung von **Durchmesser 15–20cm** für Töpfe oder Steinplatten.\\n2. **Dreipunkt-Distanzsteine**: Drücken Sie 3 kleine Kieselsteine symmetrisch in den Rand, um einen **1cm hohen Lüftungsabstand** zu sichern.\\n3. **Schräger Kaminabzug**: Stechen Sie mit einem handgelenkdicken Ast einen schräg aufsteigenden **Rauchabzugskanal** durch die obere Rückwand.\\n4. **Zugkanal prüfen**: Stellen Sie sicher, dass von der unteren Lufteinlassöffnung zum Kaminrohr eine ungehinderte Strömungsachse besteht.\",\n      \"actionNote\": \"> Kaminzug-Prinzip: Ohne oberen Abzug drückt Rauch durch die Beschickungsöffnung nach vorn. Ein höher liegender Abzug erzeugt sauberen thermischen Zug.\",\n      \"svgFileName\": \"pr06-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // AIR DRAFT PERSPECTIVE & EXHAUST BLUEPRINT\",\n        \"① Unterer vorderer Lufteinlass (Sauerstoff)\",\n        \"Frischluft strömt ins Glutbett\",\n        \"② Obere flache Kochöffnung\",\n        \"Sitz für Topf oder Bratstein\",\n        \"③ Oberer hinterer schräger Kaminabzug\",\n        \"Zieht beißenden Rauch sauber nach hinten ab\",\n        \"④ Aufsteigender thermischer Wirbelzug\",\n        \"Zirkuliert im Raum und erhitzt Topfboden\",\n        \"⑤ Topfabstandsnoppen für Dauerzug\",\n        \"Feuer erstickt nicht bei aufgesetztem Topf\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD AERODYNAMICS\",\n        \"title\": \"Kaminzug-Effekt und thermodynamische Venturi-Ansaugung\",\n        \"text\": \"Das Höhen- und Temperaturgefälle zwischen der vorderen Lufteinlassöffnung und dem hinteren Abzugskanal initiiert einen intensiven **Kamineffekt (Stack Effect)**. Die aufsteigenden Heißgase erzeugen im Brennraum einen dynamischen Unterdruck, der kontinuierlich sauerstoffreiche Frischluft durch das Glutbett nachzieht.\"\n      }\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Schritt 5: Mit kleinem Zweigfeuer 3 Stunden vortrocknen und steinhart ausbrennen\",\n      \"description\": \"1. **Zweigglut zünden**: Entzünden Sie ein faustgroßes Glutnest aus trockenem Reisig nahe der vorderen Beschickungsöffnung.\\n2. **Langsame Entfeuchtung**: Halten Sie über **3 bis 4 Stunden** gleichmäßige milde Hitze, ohne offene Flammen hochschlagen zu lassen.\\n3. **Farbwechsel-Prüfung**: Kontrollieren Sie den Farbumschlag von feuchtem Dunkelbraun zu **trockenem Hellocker** und das Ende des Dampfaustritts.\\n4. **Haarriss-Verschmierung**: Streichen Sie verbliebenen flüssigen Lehmschlicker mit dem Finger über feine Schwindrisse zur vollständigen Abdichtung.\",\n      \"actionNote\": \"> Vorsicht vor Schnellfeuerung: Schürung mit Großholz bringt Porenwasser zum Kochen und sprengt die Ofenwand. Trocknen Sie den Lehm stets langsam über 3+ Stunden zu solider Keramik aus.\",\n      \"svgFileName\": \"pr06-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // CONTROLLED DEHYDRATION & CERAMIC HARDENING\",\n        \"① Sanftes Zweigglutfeuer an der Öffnung\",\n        \"Gleichmäßige Wärme lässt Feuchte entweichen\",\n        \"② Abdampfende Wasserdampfschwaden\",\n        \"Porenwasser verdampft zerstörungsfrei\",\n        \"③ Farbwechsel-Prüfpunkt\",\n        \"Feuchtes Dunkelbraun → trockenes Hellocker\",\n        \"④ Trocken- & Wärmeprüfung von Hand\",\n        \"Wand fühlt sich trocken und warm an\",\n        \"⑤ Ausbesserungsschlicker für Haarrisse\",\n        \"Risse mit frischem Lehm zuschmieren\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Tödlicher Fehler: Flusssteine aus feuchten Zonen in feuerberührten Brennkammerwänden verbauen\",\n    \"description\": \"Steine aus Flussbetten schließen mikroskopisches Porenwasser im Inneren ein, selbst wenn die Außenseite trocken scheint. Bei direktem Kontakt mit über 300°C heißen Flammen verdampft dieses Wasser schlagartig unter extremem Druck und sprengt den Stein wie eine Handgranate. Rasiermesserscharfe Splitter fliegen in Gesicht und Augen. Verwenden Sie nur Steine von trockenen Hängen mindestens 10m vom Wasser entfernt und ummanteln Sie alle Steinflächen mit mindestens 5cm feuerfestem Lehm.\",\n    \"consequence\": \"Folge: Plötzliche Dampfexplosion im Steininneren schleudert Splitter umher und verursacht Erblindung sowie schwere Verbrennungen\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Offenes Bodenfeuer verliert 80% der Wärme an den Wind. So baut man einen unzerstörbaren Lehmofen im Wald.\",\n    \"body\": \"2 Teile Lehm, 1 Teil Sand und 1 Teil Stroh mit den Fersen durchstampfen. Trockene Steine in U-Form legen, zur kniehohen Kuppel aufmauern, Topfloch und Kamin anlegen. 3 Stunden mit Zweigen sanft ausbrennen. Niemals nasse Flusssteine an Flammen setzen; sie explodieren wie Schrapnelle.\",\n    \"outro\": \"Kocht Essen bei Sturm und speichert Strahlungswärme die ganze Nacht.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr06-outcome.svg\",\n    \"title\": \"Vollendeter lehmverputzter Steinkuppelofen\",\n    \"description\": \"Ein robuster Steinkern-Cob-Kuppelofen mit glattem Lehmverputz, oberer Kochplatte und hinterem Rauchabzug, ausgelegt auf die Speicherung von 650°C Betriebshitze.\"\n  },\n  \"createdAt\": \"2026-10-14T10:15:00.000Z\",\n  \"updatedAt\": \"2026-10-16T13:10:22+09:00\",\n  \"contentHash\": \"3786963cf3f53637\"\n}","content/protocols/locales/06-clay-hearth.en.json":"{\n  \"protocolId\": \"PR-06\",\n  \"category\": \"SHELTER\",\n  \"title\": \"How to Build a Primitive Clay & Stone Hearth to Block Wind and Trap Heat\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[ESSENTIAL SHELTER & WARMTH]\",\n  \"summary\": \"Building an open campfire on the ground loses over 80% of heat to the wind and burns firewood three times faster, while windborne sparks pose a severe fire hazard. By building a cob dome hearth with clay, sand, dry grass, and dry stones, you create a weatherproof cooking and heating shelter that traps heat and stays warm all night long.\",\n  \"timeRequired\": \"3 Hours\",\n  \"successRate\": \"90% (With Slow Pre-Cure)\",\n  \"difficulty\": \"Medium (Mud Mixing & Stone Stacking)\",\n  \"outputPerHour\": \"1 Permanent Hearth\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"2 Bowls of Sticky Red Clay (dug from riverbank or exposed soil banks)\",\n      \"desc\": \"Choose dense, cohesive clay that squishes like dough without crumbling. Acts as the primary thermal binder.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 Bowl of Coarse Sand or Gritty Soil (dry river sand)\",\n      \"desc\": \"Pure clay shrinks and cracks apart when drying. Coarse sand acts as a structural aggregate to prevent cracking.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"1 Bowl of Dry Grass or Straw Cut to Finger Length\",\n      \"desc\": \"Acts as organic reinforcement fiber within the mud mixture, preventing the walls from shattering under intense fire heat.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"15~20 Bone-Dry Fractured Stones (fist to head size)\",\n      \"desc\": \"Waterlogged river stones explode violently under heat. Use only bone-dry stones gathered from sunny ridges at least 10m away from water.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Step 1: Stomp 2 Parts Clay, 1 Part Sand, and 1 Part Dry Grass with Water into Tough Cob\",\n      \"description\": \"1. **Golden Proportional Blending**: Dump **2 bowls of sticky red clay**, **1 bowl of coarse sand**, and **1 bowl of finger-length dry grass** onto flat terrain.\\n2. **Incremental Water Stomping**: Splash water in small controlled doses, crushing the mixture with bare heels for **at least 10 minutes**.\\n3. **Mound Folding and Compression**: Repeatedly fold the clay mound in half and stomp thoroughly to establish an even cohesive matrix.\\n4. **Plasticity Verification**: Roll a fist-sized ball of cob in your hand and verify **zero surface hairline cracks** appear under pressure.\",\n      \"actionNote\": \"> Moisture Control Principle: Excess water turns cob into a sagging slurry; insufficient water leaves it dry and crumbly. Strive for a stiff, dough-like consistency that holds crisp contours.\",\n      \"svgFileName\": \"pr06-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // CLAY TEMPERING & FIBER MATRIX BLUEPRINT\",\n        \"① 2 parts sticky red clay\",\n        \"Cohesive binder base material\",\n        \"+\",\n        \"② 1 part coarse river sand\",\n        \"Prevents shrinkage and cracking\",\n        \"+\",\n        \"③ Finger-length dry grass fiber\",\n        \"Reinforcing structural tensile web\",\n        \"④ Add water gradually and stomp with heels\",\n        \"Never flood all at once; fold & stomp\",\n        \"⑤ Finished stiff cob ball\",\n        \"Roll into a solid fist-sized ball\",\n        \"Zero cracks on outer surface\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD CERAMICS\",\n        \"title\": \"Refractory Tempering and Shrinkage-Resistant Matrix Architecture\",\n        \"text\": \"Pure clay shrinks by **10–15%** upon dehydration, causing severe cracking during firing. Blending uncalcined silica sand and organic straw fibers in a **2:1:1 volumetric ratio** creates a thermal aggregate matrix where carbonized fibers leave micro-voids that absorb thermal shock without fracture.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Step 2: Lay Fist-Sized Dry Stones in a Horseshoe U-Shape to Anchor the Foundation\",\n      \"description\": \"1. **Intake Orientation**: Leave a front feeding mouth opening of **width 20cm** (one hand-span) pointing away from prevailing winds.\\n2. **Horseshoe Perimeter Layout**: Arrange fist-sized bone-dry stones in a stable **horseshoe U-shape** around the perimeter.\\n3. **Thermal Subfloor Bedding**: Spread dry sand and fine river gravel across the interior floor to a **depth of 2–3cm** to isolate ground frost.\\n4. **Crevice Mortar Packing**: Punch stiff cob mud firmly into every gap between anchor stones to eliminate parasitic air drafts.\",\n      \"actionNote\": \"> Wind Angle Rule: Facing the fire mouth directly into wind currents forces embers back into your eyes. Always point the mouth downwind or at a shielded cross-angle.\",\n      \"svgFileName\": \"pr06-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // FOUNDATION LAYOUT & AIR ENTRY SCHEMATIC\",\n        \"① Front firewood intake mouth (20 cm wide)\",\n        \"Optimal width for wood feeding & airflow\",\n        \"② Horseshoe U-shaped dry anchor stones\",\n        \"Primary foundation perimeter\",\n        \"③ Thick cob mortar in stone joints\",\n        \"Prevents drafts and air leaks\",\n        \"④ Dry sand & gravel base insulator\",\n        \"Thermal barrier against cold ground\",\n        \"⑤ Fire mouth facing away from wind\",\n        \"Protects ember bed from wind gusts\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Step 3: Stagger Stones and Cob Layer by Layer into a Knee-High Dome\",\n      \"description\": \"1. **Cob Mortar Bedding**: Spread a palm-thick cob bed of **depth approx. 5cm** over the base foundation stones.\\n2. **Staggered Corbel Stacking**: Bed the next tier of stones over the joints in a zig-zag pattern, packing clay between all gaps.\\n3. **Inward Corbel Dome Raising**: Slant stones inward as layers rise, completing a hemispherical igloo dome of **height approx. 45cm**.\\n4. **Burnished Smooth Rendering**: Dip hands in water and burnish the interior chamber into a slick, continuous curved heat reflector.\",\n      \"actionNote\": \"> Anti-Collapse Core Law: Pure mud walls slump under their own weight. Always use stone masonry as an interlocking skeleton, encased within a thick envelope of refractory cob.\",\n      \"svgFileName\": \"pr06-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DOME CHAMBER CROSS-SECTION & THERMAL CURVATURE\",\n        \"45cm\",\n        \"① Staggered stone & cob cross-section\",\n        \"Interlocking stones prevent structural failure\",\n        \"② Palm-thick (5 cm) thermal cob wall\",\n        \"Heavy thermal mass traps heat overnight\",\n        \"③ Smooth water-burnished heat reflector\",\n        \"Smoothed by wet hand for smooth draft\",\n        \"④ Spherical internal combustion chamber\",\n        \"⑤ Knee-high (45 cm) total profile\",\n        \"Optimal balance of volume and cooking height\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"Hemispherical Dome Radiant Concentration and 650°C Thermal Massing\",\n        \"text\": \"The parabolic inner curve acts as an infrared reflector, focusing blackbody radiation onto the central cooking port. The **5cm-thick** high-density cob shell stores sensible heat, sustaining internal combustion temperatures of **300–650°C** for hours after active flames die down.\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Step 4: Cut a Top Cooking Pot Ring and Punch a Rear Exhaust Flue\",\n      \"description\": \"1. **Circular Cooking Port Porting**: Carve a circular opening of **diameter 15–20cm** into the top crown for pots and flat stone griddles.\\n2. **Tri-Stone Ventilation Spacers**: Embed 3 small stones symmetrically around the rim to maintain a **1cm ventilation standoff gap**.\\n3. **Angled Chimney Flue Piercing**: Push a wrist-thick green bough through the upper rear dome to pierce a clean **smoke exhaust flue**.\\n4. **Draft Convection Verification**: Inspect the rising airflow channel from the lower wood intake up through the rear flue.\",\n      \"actionNote\": \"> Stack Effect Principle: Without an elevated exhaust flue, smoke rolls forward into the cook's face. Placing the flue higher than the intake mouth establishes clean upward draft.\",\n      \"svgFileName\": \"pr06-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // AIR DRAFT PERSPECTIVE & EXHAUST BLUEPRINT\",\n        \"① Lower front air intake (oxygen supply)\",\n        \"Cold fresh air drawn into burning ember bed\",\n        \"② Flat top circular cooking port\",\n        \"Seat for stone pan or clay pot\",\n        \"③ Upper rear angled chimney flue\",\n        \"Draws acrid smoke cleanly out the back\",\n        \"④ Updraft thermal vortex airflow\",\n        \"Vigorous draft heats cooking vessel base\",\n        \"⑤ Pot spacer nubs for continuous draft\",\n        \"Air passes freely even with pot seated\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD AERODYNAMICS\",\n        \"title\": \"Chimney Stack Effect and Venturi Air Induction Dynamics\",\n        \"text\": \"The vertical displacement and thermal gradient between the intake mouth and elevated rear flue drives a vigorous **chimney stack effect**. Low-density exhaust gases evacuate rapidly, generating negative pressure that continuously draws fresh oxygen into the firebed.\"\n      }\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Step 5: Cure with a Low Twig Fire for 3 Hours to Bake the Clay into Brick Hardness\",\n      \"description\": \"1. **Low-Intensity Ignition**: Kindle a small fist-sized ember of dry leaves and twigs near the fire mouth.\\n2. **Slow Thermal Dehydration**: Maintain gentle low-temperature drying over **3–4 hours** without roaring flames.\\n3. **Chromatic Cure Milestone**: Verify the outer surface shifts from damp dark brown to **warm pale ochre** with steam venting stopping.\\n4. **Hairline Fissure Sealing**: Smear remaining thin clay slurry over any developing drying cracks to seal the wall completely.\",\n      \"actionNote\": \"> Flash-Firing Warning: Raging fires in wet cob boil internal water instantly, exploding outer walls. Always pre-cure slowly over 3+ hours to bake into solid ceramic stone.\",\n      \"svgFileName\": \"pr06-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // CONTROLLED DEHYDRATION & CERAMIC HARDENING\",\n        \"① Gentle twig ember fire at mouth\",\n        \"Gentle heat allows gradual moisture exit\",\n        \"② Steam vapor plumes venting outward\",\n        \"Internal water evaporates safely\",\n        \"③ Color transition milestone\",\n        \"Dark damp brown → dry pale ochre\",\n        \"④ Warm & dry touch test\",\n        \"Wall feels warm without sticky dampness\",\n        \"⑤ Touch-up paste for hairline cracks\",\n        \"Seal minor fissures with wet clay paste\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Fatal Mistake: Building Hearth Fire-Contact Walls with Waterlogged River Rocks\",\n    \"description\": \"Stones gathered from riverbeds retain trapped microscopic water inside their pores even when their surface feels dry. Exposing these rocks to direct 300°C+ flames converts trapped water into high-pressure steam, causing the stone to detonate like a hand grenade. Shrapnel can cause blindness and severe facial trauma. Gather stones only from dry sunny ridges 10m away from water, and encase all rock faces in a 5cm layer of refractory cob.\",\n    \"consequence\": \"Consequence: Internal steam explosion hurls razor-sharp stone shrapnel causing permanent blindness and deep lacerations\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Open campfires lose 80% of heat to the wind. Here is how to build an unbreakable wild clay hearth.\",\n    \"body\": \"Stomp 2 parts clay, 1 part sand, and 1 part dry grass into stiff dough. Lay dry stones in a U-shape, build up a knee-high dome, cut a top pot ring, and punch a rear chimney. Cure gently with twigs for 3 hours. Never touch fire directly to wet river stones; trapped moisture detonates rocks like shrapnel.\",\n    \"outro\": \"Cooks meals in gale-force winds and traps radiant heat all night long.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr06-outcome.svg\",\n    \"title\": \"Completed Clay-Plastered Stone Hearth\",\n    \"description\": \"A stone-core cob dome hearth with smooth clay plaster, top cooking ring, and rear exhaust chimney designed to trap 650°C heat efficiently.\"\n  },\n  \"createdAt\": \"2026-10-14T10:15:00.000Z\",\n  \"updatedAt\": \"2026-10-16T13:10:22+09:00\",\n  \"contentHash\": \"3786963cf3f53637\"\n}","content/protocols/locales/06-clay-hearth.es.json":"{\n  \"protocolId\": \"PR-06\",\n  \"category\": \"SHELTER\",\n  \"title\": \"Cómo Construir un Fogón Primitivo de Barro y Piedras para Protegerse del Viento y Retener Calor\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[CALOR Y REFUGIO ESENCIAL]\",\n  \"summary\": \"Hacer una fogata abierta directamente en el suelo pierde más del 80% del calor con el viento y consume tres veces más leña, mientras que las chispas voladoras representan un grave riesgo de incendio. Al levantar un fogón en cúpula con barro, arena, hierba seca y piedras secas, se crea un refugio térmico resistente al mal tiempo que permite cocinar y conservar calor durante toda la noche.\",\n  \"timeRequired\": \"3 Horas\",\n  \"successRate\": \"90% (Con Curado Lento)\",\n  \"difficulty\": \"Media (Amasado de Barro y Apilado)\",\n  \"outputPerHour\": \"1 Fogón Permanente\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"2 Cuencos de Arcilla Roja Pegajosa (excavada en riberas o taludes)\",\n      \"desc\": \"Elija tierra densa que se amase como masa de pan sin desmoronarse. Actúa como el aglutinante térmico principal.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 Cuenco de Arena Gruesa de Río (arena seca con granos minerales)\",\n      \"desc\": \"La arcilla pura se encoge y se agrieta al secar. La arena gruesa proporciona el esqueleto estructural que evita grietas.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"1 Cuenco de Hierba Seca o Paja Cortada a la Medida de un Dedo\",\n      \"desc\": \"Funciona como fibra de refuerzo dentro de la mezcla, impidiendo que las paredes colapsen bajo el calor del fuego.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"15~20 Piedras Quebradas Completamente Secas (tamaño puño a cabeza)\",\n      \"desc\": \"Las piedras de río anegadas explotan con el calor. Utilice únicamente piedras secas recolectadas de lomas soleadas a más de 10 m del agua.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Paso 1: Pisar 2 partes de arcilla, 1 de arena y 1 de hierba seca con agua hasta formar barro maleable\",\n      \"description\": \"1. **Dosificación proporcional óptima**: Vierta sobre suelo nivelado **2 cuencos de arcilla roja**, **1 cuenco de arena gruesa** y **1 cuenco de hierba seca** troceada.\\n2. **Amasado progresivo con agua**: Agregue agua en pequeñas salpicaduras mientras pisotea con los talones durante **al menos 10 minutos**.\\n3. **Plegado y compresión de masa**: Doble el montículo de arcilla por la mitad y vuelva a pisar repetidamente para homogeneizar la mezcla.\\n4. **Prueba de plasticidad esférica**: Modele una bola del tamaño de un puño y confirme que **no muestra microfisuras superficiales** al presionarla.\",\n      \"actionNote\": \"> Control de humedad: El exceso de agua vuelve el barro un lodo blando que se desliza; la falta de agua lo deja quebradizo. Busque una textura densa y maleable similar a la masa de pan.\",\n      \"svgFileName\": \"pr06-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // CLAY TEMPERING & FIBER MATRIX BLUEPRINT\",\n        \"① 2 partes de arcilla roja pegajosa\",\n        \"Materia prima aglutinante base\",\n        \"+\",\n        \"② 1 parte de arena gruesa de río\",\n        \"Evita contracción y agrietamiento\",\n        \"+\",\n        \"③ Fibra de hierba seca cortada\",\n        \"Malla estructural de refuerzo interno\",\n        \"④ Agregar agua poco a poco y pisar con talones\",\n        \"Nunca inundar de golpe; doblar y pisar\",\n        \"⑤ Bola de barro firme terminada\",\n        \"Moldear en bola sólida tamaño puño\",\n        \"Superficie exterior sin fisuras\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD CERAMICS\",\n        \"title\": \"Templado refractario y matriz estructural antagrietamiento\",\n        \"text\": \"La arcilla pura experimenta una contracción por secado de **10 a 15%**, agrietándose durante la cocción. Mezclar arena silícea no calcinada y fibras de paja seca en **proporción volumétrica 2:1:1** crea un esqueleto donde las fibras carbonizadas generan microporos que absorben el choque térmico sin fractura.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Paso 2: Disponer piedras secas en herradura (forma de U) sobre suelo seco para la base\",\n      \"description\": \"1. **Orientación de la entrada**: Deje libre una boca de alimentación de **20cm de ancho** orientada en dirección contraria al viento predominante.\\n2. **Disposición en herradura**: Asiente piedras secas quebradas en **forma de U continua** sobre el terreno.\\n3. **Capa aislante de suelo**: Cubra el suelo interior con arena seca y gravilla fina con un **espesor de 2 a 3cm** para bloquear la humedad terrestre.\\n4. **Sellado de juntas con barro**: Introduzca barro denso a presión en cada hendidura entre piedras para sellar por completo el paso de aire.\",\n      \"actionNote\": \"> Dirección del viento: Abrir la boca hacia el viento provocará que las ráfagas expulsen chispas y humo contra usted. Oriente siempre la boca a sotavento o en ángulo protegido.\",\n      \"svgFileName\": \"pr06-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // FOUNDATION LAYOUT & AIR ENTRY SCHEMATIC\",\n        \"① Boca frontal para leña (20 cm de ancho)\",\n        \"Ancho óptimo para leña y entrada de aire\",\n        \"② Piedras secas de anclaje en forma de U\",\n        \"Perímetro estructural de la base\",\n        \"③ Mortero de barro grueso en juntas\",\n        \"Sella fugas de aire entre piedras\",\n        \"④ Aislante de arena y grava en el fondo\",\n        \"Barrera térmica contra el suelo frío\",\n        \"⑤ Boca orientada en contra del viento\",\n        \"Protege las brasas de ráfagas violentas\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Paso 3: Apilar piedras y barro de forma alternada hasta formar una cúpula a la altura de la rodilla\",\n      \"description\": \"1. **Base de mortero de barro**: Extienda sobre las piedras base una capa de barro de **unos 5cm de espesor** (grosor de una palma).\\n2. **Trabazón escalonada de piedras**: Coloque la hilera superior sobre las juntas inferiores en zigzag, embutiendo barro en todo el contorno.\\n3. **Aproximación en cúpula cerrada**: Incline las piedras hacia el interior a medida que sube hasta alcanzar **unos 45cm de altura**.\\n4. **Alisado y bruñido interior**: Moje sus manos en agua y alise la pared interna de la cámara para crear una curva reflectora sin rebabas.\",\n      \"actionNote\": \"> Principio estructural: Levantar paredes altas únicamente con barro provoca el colapso por peso propio. Use las piedras como núcleo rígido envuelto en barro refractario.\",\n      \"svgFileName\": \"pr06-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DOME CHAMBER CROSS-SECTION & THERMAL CURVATURE\",\n        \"45cm\",\n        \"① Corte transversal de piedras y barro\",\n        \"Piedras trabadas evitan fallas estructurales\",\n        \"② Pared gruesa de barro (5 cm) aislante\",\n        \"Masa térmica retiene calor toda la noche\",\n        \"③ Superficie lisa reflectora de calor\",\n        \"Alisada con mano húmeda para buen tiro\",\n        \"④ Cámara de combustión esférica interior\",\n        \"⑤ Perfil total a la rodilla (45 cm)\",\n        \"Equilibrio ideal de volumen y cocción\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"Concentración radiante en cúpula semiesférica y masa térmica a 650°C\",\n        \"text\": \"La curvatura parabólica interior actúa como reflector de radiación infrarroja de cuerpo negro hacia el orificio superior de cocción. La pared densa de **5cm de espesor** posee alta inercia térmica, manteniendo **300 a 650°C** durante horas tras extinguirse las llamas.\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Paso 4: Abrir un orificio superior para ollas y perforar una chimenea trasera\",\n      \"description\": \"1. **Orificio de cocción superior**: Modele en la cúspide una abertura circular de **diámetro 15–20cm** para asentar ollas o planchas de piedra.\\n2. **Piedras espaciadoras de tiro**: Incruste 3 piedras pequeñas en triángulo en el borde para garantizar una **holgura de ventilación de 1cm**.\\n3. **Perforación de chimenea trasera**: Inserte una rama del grosor de una muñeca en la parte superior posterior para abrir un **conducto de escape de humos**.\\n4. **Comprobación de tiro ascendente**: Verifique que exista un canal de evacuación limpio desde la entrada frontal hasta la salida superior trasera.\",\n      \"actionNote\": \"> Efecto chimenea: Sin un escape trasero elevado, el humo sale por la boca frontal cegando al usuario. Ubicar la chimenea más alta que la entrada garantiza un tiro limpio.\",\n      \"svgFileName\": \"pr06-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // AIR DRAFT PERSPECTIVE & EXHAUST BLUEPRINT\",\n        \"① Entrada inferior de aire (oxígeno fresco)\",\n        \"Aire fresco succionado hacia las brasas\",\n        \"② Orificio superior plano para cocinar\",\n        \"Asiento para olla o plancha de piedra\",\n        \"③ Salida trasera inclinada de chimenea\",\n        \"Expulsa el humo denso hacia atrás\",\n        \"④ Vórtice térmico ascendente de calor\",\n        \"Gira en la cámara calentando la base\",\n        \"⑤ Salientes espaciadoras para el tiro\",\n        \"El fuego no se ahoga al colocar la olla\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD AERODYNAMICS\",\n        \"title\": \"Efecto chimenea y dinámica de inducción Venturi\",\n        \"text\": \"El gradiente térmico y la altura entre la boca inferior y la chimenea trasera generan un vigoroso **efecto chimenea (Stack Effect)**. Los gases de combustión evacúan con rapidez creando una depresión interna que succiona oxígeno fresco de forma continua.\"\n      }\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Paso 5: Curar con fuego suave de ramitas durante 3 horas para endurecer el barro como ladrillo\",\n      \"description\": \"1. **Encendido a baja potencia**: Encienda un fuego suave con ramitas secas y hojas cerca de la entrada de leña.\\n2. **Deshidratación térmica gradual**: Mantenga una temperatura moderada durante **3 a 4 horas** continuas sin levantar llamas vivas.\\n3. **Inspección de secado**: Observe la transición de color del marrón oscuro húmedo a un **tono ocre cálido** y el cese de vapor blanco.\\n4. **Sellado de microfisuras**: Aplique una capa delgada de pasta de barro residual sobre cualquier pequeña grieta para consolidar el sellado.\",\n      \"actionNote\": \"> Peligro de fuego súbito: Quemar leña gruesa al inicio hace hervir el agua interna, reventando las paredes. El curado lento de más de 3 horas transforma el barro en cerámica resistente.\",\n      \"svgFileName\": \"pr06-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // CONTROLLED DEHYDRATION & CERAMIC HARDENING\",\n        \"① Fuego suave de ramitas en la entrada\",\n        \"Calor moderado permite salida de vapor\",\n        \"② Penachos de vapor de agua evaporándose\",\n        \"El agua interna se evapora sin reventar\",\n        \"③ Transición visual de color\",\n        \"Marrón oscuro húmedo → ocre pálido seco\",\n        \"④ Prueba de tacto seco y caliente\",\n        \"Pared tibia sin humedad pegajosa\",\n        \"⑤ Pasta de retoque para fisuras finas\",\n        \"Sellar grietas con pasta de barro fresca\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Error Fatal: Construir la cámara de combustión con piedras de río húmedas\",\n    \"description\": \"Las rocas recogidas de orillas de ríos encierran moléculas de agua en sus poros microscópicos, incluso si su superficie exterior parece seca. Si el fuego directo a más de 300°C calienta estas piedras, el agua atrapada se vaporiza al instante generando presiones extremas que provocan su explosión como una granada. Los fragmentos afilados causan ceguera y heridas graves. Use solo rocas de lomas secas a más de 10m del agua y cubra toda la piedra con 5cm de barro refractario.\",\n    \"consequence\": \"Consecuencia: La explosión interna por vapor proyecta esquirlas de roca afiladas causando ceguera y quemaduras graves\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Hacer fuego abierto en el suelo pierde el 80% del calor. Aprende a construir un fogón salvaje de barro indestructible.\",\n    \"body\": \"Pisa 2 partes de arcilla, 1 de arena y 1 de paja hasta lograr una masa firme. Coloca piedras en U, levanta una cúpula a la rodilla, abre el orificio superior y una chimenea trasera. Cura 3 horas con ramitas. Jamás uses piedras de río húmedas; estallan en esquirlas con el calor.\",\n    \"outro\": \"Cocina con vientos fuertes y retiene calor radiante toda la noche.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr06-outcome.svg\",\n    \"title\": \"Fogón de Piedra Revestido con Barro Terminado\",\n    \"description\": \"Un fogón en cúpula de barro con núcleo de piedra, acabado suave, orificio superior de cocción y chimenea trasera diseñado para retener 650°C de calor.\"\n  },\n  \"createdAt\": \"2026-10-14T10:15:00.000Z\",\n  \"updatedAt\": \"2026-10-16T13:10:22+09:00\",\n  \"contentHash\": \"3786963cf3f53637\"\n}","content/protocols/locales/06-clay-hearth.ja.json":"{\n  \"protocolId\": \"PR-06\",\n  \"category\": \"SHELTER\",\n  \"title\": \"粘土と石を積み上げて風雨を防ぎ熱を閉じ込める原始かまどの作り方\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[体温・食料必須]\",\n  \"summary\": \"野外で地面に直接火を起こすと、熱の80%が風で散り薪が3倍以上消費される上、火の粉が舞い上がり危険です。赤粘土、砂、枯草を練り合わせた泥ペーストで石を包み込みドーム状のかまどを築くことで、風雨の中でも消えず、煮炊きを行い朝まで熱を蓄え続ける堅牢な生存熱源になります。\",\n  \"timeRequired\": \"3時間\",\n  \"successRate\": \"90% (弱火乾燥を厳守した場合)\",\n  \"difficulty\": \"普通 (泥こねと石積み作業)\",\n  \"outputPerHour\": \"1基完成 (永久使用可能)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"粘性のある赤粘土 2杯 (川岸や露出した土手から採取した粘り土)\",\n      \"desc\": \"手で握ったときに餅のようにまとまり指に吸い付く土を選びます。かまどの壁を強固に固める主原料です。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"粗い川砂 1杯 (粒状の砂利が混ざった乾いた砂)\",\n      \"desc\": \"粘土だけでは乾燥時に収縮して割れてしまいます。粗い砂を混ぜることで骨材となりひび割れを防ぎます。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"指の長さに切った枯草またはワラ 1杯\",\n      \"desc\": \"泥の中で繊維質の鉄筋の役割を果たし、炎の高熱を受けても壁体が割れたり崩れたりするのを防ぎます。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"水気のない硬い割り石 15〜20個 (拳〜頭大の乾いた石)\",\n      \"desc\": \"水に浸かっていた川石は加熱時に水蒸気爆発を起こすため、水辺から10m以上離れた日当たりの良い尾根の完全に乾いた石のみを選びます。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"ステップ 1: 粘土2、砂1、枯草1に水を少しずつ加え足で踏み込んで粘り強い泥生地を作る\",\n      \"description\": \"1. **黄金配合の計量投入**: 平らな地面に**赤粘土2杯**、**粗砂1杯**、指の長さに刻んだ**枯草1杯**を均一に広げます。\\n2. **段階的加水混練**: 水を一度に注がず少量ずつ加えながら、かかとで体重を乗せて**10分以上**力強く踏み込みます。\\n3. **反転折りたたみ圧縮**: 泥を二つ折りに返して踏む工程を繰り返し、均質で粘り強い母材組織を形成します。\\n4. **保形弾性の検品**: 拳大の団子に丸めて手のひらに置いた際、表面に**微細なひび割れが一切生じない状態**を確認します。\",\n      \"actionNote\": \"> 水加減の極意: 水が多すぎると泥が崩れて壁にならず、少なすぎるとパサついて割れます。餃子の皮のように少し硬めで粘りのある状態が最適です。\",\n      \"svgFileName\": \"pr06-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // CLAY TEMPERING & FIBER MATRIX BLUEPRINT\",\n        \"① 粘性のある赤粘土 2杯\",\n        \"粘着力を持つ基本母材\",\n        \"+\",\n        \"② 粗い川砂 1杯\",\n        \"乾燥時の収縮・ひび割れ防止\",\n        \"+\",\n        \"③ 細かく切った枯草の繊維\",\n        \"骨組みとなる補強繊維層\",\n        \"④ 水を少しずつ加え足で踏み込む\",\n        \"一気に水を注がず折り返しながら踏む\",\n        \"⑤ 粘りのある泥団子の完成\",\n        \"拳大に丸めても崩れない\",\n        \"表面に細かな亀裂がない状態\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD CERAMICS\",\n        \"title\": \"耐火テンパリング（Refractory Tempering）と収縮亀裂防止マトリックス\",\n        \"text\": \"純粋な粘土は脱水乾燥時に**10〜15%**収縮し、焼成時に深刻な亀裂を生じます。未焼成の珪砂と有機質繊維（枯草）を**2:1:1の体積比**で複合配合することで、砂粒が骨材となり炭化した繊維が微小空隙を形成して熱応力を吸収する**耐火複合体**が完成します。\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"ステップ 2: 乾いた地面に拳大の石をU字型に並べて基礎を築く\",\n      \"description\": \"1. **給気開口部の位置決め**: 風下に向けて手のひら幅である**間口約20cm**の薪投入口を確保します。\\n2. **U字型アンカー石敷設**: 拳より大きな乾いた割り石を地面に**U字馬蹄形状**に並べて強固な輪郭を組みます。\\n3. **底面断熱層の敷設**: 内側の底面に乾いた砂と砂利を**厚さ2〜3cm**で敷き詰め、地表からの湿気と冷気を遮断します。\\n4. **目地モルタルの充填**: 石と石の隙間ごとにステップ1の泥ペーストを拳で押し込み、不要な空気漏れを密閉します。\",\n      \"actionNote\": \"> 風向きの注意: 投入口が風上を向いていると突風で火の粉が逆流し危険です。必ず風下または風を斜めに受ける向きに口を設けてください。\",\n      \"svgFileName\": \"pr06-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // FOUNDATION LAYOUT & AIR ENTRY SCHEMATIC\",\n        \"① 前方の薪投入口 (幅約20cm)\",\n        \"薪の補給と給気に最適な間口\",\n        \"② U字型に並べた拳大の乾いた石\",\n        \"基礎を支える一次骨組み\",\n        \"③ 隙間を埋めた厚手の泥ペースト\",\n        \"石の隙間からの空気漏れを完全遮断\",\n        \"④ 底面の乾いた砂・砂利断熱層\",\n        \"冷たい地表の湿気と冷気を遮断\",\n        \"⑤ 風下を向けた開口部の配置\",\n        \"突風による火の粉逆流と失火を防止\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"ステップ 3: 石と泥を交互に積み上げ膝丈のドーム壁を立ち上げる\",\n      \"description\": \"1. **泥モルタル敷設**: 基礎石の上に手のひら厚である**厚さ約5cm**の泥ペーストを厚く塗り広げます。\\n2. **互い違いのせり出し積み**: 次の段の石を目地の上にジグザグに載せ、内外の隙間を泥で完全に埋め込みます。\\n3. **内傾ドームの成形**: 上へ行くほど内側へすぼめながら膝丈である**高さ約45cm**のドームを築きます。\\n4. **内壁水磨き仕上げ**: 手に水をつけて内壁を滑らかに撫で上げ、熱気をスムーズに対流させる反射曲面に仕上げます。\",\n      \"actionNote\": \"> 崩落防止: 泥だけで高く築くと自重で潰れます。必ず石を芯材にし、その外側と内側を厚い泥でしっかり包み込むように施工してください。\",\n      \"svgFileName\": \"pr06-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DOME CHAMBER CROSS-SECTION & THERMAL CURVATURE\",\n        \"45cm\",\n        \"① 互い違いに積んだ壁体断面\",\n        \"石の間に泥を詰め崩壊を防止\",\n        \"② 手のひら厚(約5cm)の泥断熱壁\",\n        \"外側への熱逃げを完全に防ぐ\",\n        \"③ 滑らかな熱反射曲面\",\n        \"水の手で平滑に撫で上げた内壁\",\n        \"④ 熱が対流する円形燃焼室内部\",\n        \"⑤ 膝丈(約45cm)の外形ライン\",\n        \"調理安定性と蓄熱容積の最適化\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"半球ドーム内の放射熱集中と650℃蓄熱力学\",\n        \"text\": \"放物線状の内壁は黒体放射に従い放射赤外線を頂部の調理火口へ集中反射します。**厚さ5cm**の高密度泥壁は比熱が高く、火が消えた後も内部を**300〜650℃**の高温で数時間にわたり蓄熱保温します。\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"ステップ 4: 天面に鍋置き用の穴を残し後方に煙突穴を開ける\",\n      \"description\": \"1. **天面調理火口の開口**: ドーム頂部中央に鍋や平石を載せるための**直径15〜20cm**の円形開口部を残します。\\n2. **三点支持スペーサー設置**: 鍋底で炎が塞がれないよう開口部の周囲に小石3個を埋め込み、**1cmの通気隙間**を設けます。\\n3. **後方排気煙突の穿孔**: かまどの背面上部に手首太さの枝を斜めに貫通させ、煙が綺麗に抜ける**排気煙突**を開けます。\\n4. **対流気流路の点検**: 下部吸気口から頂部煙突へ向かう上昇気流ルートに障害物がないか確認します。\",\n      \"actionNote\": \"> 通気の原理: 煙突がないと煙が前の投入口から噴き出して目が痛くなります。後方の煙突を前口より高い位置に設けることで煙がきれいに抜けます。\",\n      \"svgFileName\": \"pr06-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // AIR DRAFT PERSPECTIVE & EXHAUST BLUEPRINT\",\n        \"① 前方下部の吸気口 (酸素供給)\",\n        \"冷たく新鮮な空気が引き込まれる通路\",\n        \"② 上部の平坦な調理用開口部\",\n        \"鍋や平石を安定して据える火口\",\n        \"③ 後方上部の煙突排気穴\",\n        \"煙を背後へ効率よく吸い出す排気口\",\n        \"④ 立ち昇る熱対流ライン\",\n        \"燃焼室内を旋回し鍋底を加熱\",\n        \"⑤ 鍋受け通気スペーサー突起\",\n        \"鍋を置いても炎が塞がれず消えない構造\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD AERODYNAMICS\",\n        \"title\": \"煙突効果（Stack Effect）とベンチュリ吸気流体力学\",\n        \"text\": \"下部吸気口と上部煙突の高低差および温度差により強力な**煙突効果（Chimney Effect）**が発生します。高温排気が急速に外部へ抜けることで燃焼室内に負圧が生じ、下部から新鮮な酸素を自動的かつ連続的に吸入します。\"\n      }\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"ステップ 5: 小枝の弱火で3時間じっくり乾かしレンガのように焼き固める\",\n      \"description\": \"1. **微小熱源での着火**: 枯れ葉と小枝で拳大の小さな火種を作り、投入口の近くで静かに火を点けます。\\n2. **低温緩慢乾燥の維持**: 大火を避け、**3〜4時間**かけて穏やかな低温熱を供給し土中の余剰水分を気化させます。\\n3. **色調転換の確認**: 外壁の濡れた暗褐色が明るい**黄土色へと変化**し、白い水蒸気が出なくなるのを見届けます。\\n4. **微細ヘアクラックの補修**: 乾燥時に生じた髪の毛ほどの微細亀裂に余った泥ペーストを薄く塗り込み密閉します。\",\n      \"actionNote\": \"> 急熱禁止の原則: 最初から大木を燃やすと内部の水分が爆沸して壁体が破裂します。必ず弱火で3時間以上じっくり焼成しセラミック状に硬化させてください。\",\n      \"svgFileName\": \"pr06-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // CONTROLLED DEHYDRATION & CERAMIC HARDENING\",\n        \"① 投入口の小枝の弱火 (穏やかな熱)\",\n        \"急熱を避け熱をゆっくり加える\",\n        \"② 外壁からの水蒸気蒸発線\",\n        \"内部水分が静かに気化して脱出\",\n        \"③ 色調変化の観察\",\n        \"濡れた濃褐色 → 乾いた明るい黄土色\",\n        \"④ 触手による乾燥完了確認\",\n        \"湿り気なく外壁全体に温かみが伝わる\",\n        \"⑤ 微細亀裂の泥ペースト補修\",\n        \"残った泥で表面の微小隙間を密閉\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"絶対にやってはいけない失敗: 水に濡れた川石を火が直接触れる燃焼室に積む\",\n    \"description\": \"水辺で拾った川石は、表面が乾いて見えても石の微細な隙間に水分が閉じ込められています。300度以上の炎が直接当たると水蒸気が爆発的に膨張し、手榴弾のように轟音を立てて粉々に破裂します。破片が顔や目に直撃して失明などの重傷を負う危険があります。必ず水辺から10m以上離れた乾いた丘の石を使い、石の表面を泥で5cm以上厚く覆って炎が直撃しないように施工してください。\",\n    \"consequence\": \"結果: 石の内部水蒸気爆発により鋭利な破片が飛散し、失明や重度の火傷を引き起こす\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"野外で地面に火を起こすと熱の80%が風で逃げます。風雨でも消えない原始かまどの作り方です。\",\n    \"body\": \"粘土2、砂1、枯草1を足で10分踏み込んで泥を作ります。乾いた石をU字に並べ、膝丈のドームに積み上げ、天面に鍋穴、後ろに煙突を開けましょう。小枝の弱火で3時間じっくり乾かせばレンガのように固まります。濡れた川石は水蒸気爆発するので絶対に使わないでください。\",\n    \"outro\": \"嵐の中でも料理ができ、朝まで温もりを保ちます。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr06-outcome.svg\",\n    \"title\": \"粘土仕上げ石積みかまど（原始かまど及び調理炉）完成形態\",\n    \"description\": \"U字型基礎の上に藁と黄土を5cm厚で滑らかに仕上げ、上部調理用耐熱天板と後部排気煙突を備えて650℃の熱を閉じ込める原始かまどの完成形態です。\"\n  },\n  \"createdAt\": \"2026-10-14T10:15:00.000Z\",\n  \"updatedAt\": \"2026-10-16T13:10:22+09:00\",\n  \"contentHash\": \"3786963cf3f53637\"\n}","content/protocols/locales/06-clay-hearth.pt.json":"{\n  \"protocolId\": \"PR-06\",\n  \"category\": \"SHELTER\",\n  \"title\": \"Como Construir um Fogão Primitivo de Barro e Pedras para Bloquear o Vento e Reter Calor\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[CALOR E ABRIGO ESSENCIAIS]\",\n  \"summary\": \"Fazer uma fogueira aberta no chão perde mais de 80% do calor com o vento e consome três vezes mais lenha, enquanto fagulhas representam risco crítico de incêndio. Construindo um fogão em cúpula com barro, areia, capim seco e pedras secas, você cria um ponto de cozimento à prova de tempestades que retém calor a noite toda.\",\n  \"timeRequired\": \"3 Horas\",\n  \"successRate\": \"90% (Com Cura Lenta)\",\n  \"difficulty\": \"Média (Amassar Barro e Assentar Pedras)\",\n  \"outputPerHour\": \"1 Fogão Permanente\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"2 Tigelas de Argila Vermelha Pegajosa (escavada em margens ou barrancos)\",\n      \"desc\": \"Escolha terra densa que amasse como massa de pão sem esfarelar. Atua como o ligante térmico principal.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 Tigela de Areia Grossa de Rio (areia seca com grãos minerais)\",\n      \"desc\": \"A argila pura encolhe e racha ao secar. A areia grossa fornece a estrutura que impede rachaduras.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"1 Tigela de Capim Seco ou Palha Cortada no Tamanho de um Dedo\",\n      \"desc\": \"Funciona como fibra de reforço dentro da mistura, impedindo que as paredes rachem sob o calor intenso.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"15~20 Pedras Quebradas Totalmente Secas (tamanho punho a cabeça)\",\n      \"desc\": \"Pedras de rio encharcadas explodem violentamente com o calor. Use apenas pedras secas coletadas em encostas ensolaradas a mais de 10 m da água.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Passo 1: Pisotear 2 partes de argila, 1 de areia e 1 de capim seco com água até formar massa firme\",\n      \"description\": \"1. **Dosagem proporcional exata**: Despeje sobre solo plano **2 tigelas de argila vermelha**, **1 tigela de areia grossa** e **1 tigela de capim seco** picado.\\n2. **Adição gradativa de água**: Adicione água em pequenas borrifadas enquanto pisoteia com os calcanhares por **pelo menos 10 minutos**.\\n3. **Dobra e compactação da massa**: Dobre o monte de barro ao meio e volte a pisar repetidamente até formar uma matriz coesa e homogênea.\\n4. **Verificação de plasticidade**: Modele uma bola do tamanho de um punho e certifique-se de que **não surgem trincas superficiais** ao apertar.\",\n      \"actionNote\": \"> Ponto de umidade ideal: Água em excesso vira lama frouxa que escorre; pouca água gera blocos quebradiços. O ponto correto é firme e maleável como massa de pão.\",\n      \"svgFileName\": \"pr06-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // CLAY TEMPERING & FIBER MATRIX BLUEPRINT\",\n        \"① 2 partes de argila vermelha pegajosa\",\n        \"Matéria-prima aglomerante de base\",\n        \"+\",\n        \"② 1 parte de areia grossa de rio\",\n        \"Evita retração e rachaduras\",\n        \"+\",\n        \"③ Fibra de capim seco picado\",\n        \"Malha estrutural de reforço interno\",\n        \"④ Adicionar água aos poucos e pisar\",\n        \"Nunca inundar de vez; dobrar e pisar\",\n        \"⑤ Bola de barro firme finalizada\",\n        \"Moldar bola sólida tamanho punho\",\n        \"Superfície externa sem trincas\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD CERAMICS\",\n        \"title\": \"Temperagem refratária e matriz antitrincamento por retração\",\n        \"text\": \"A argila pura sofre retração linear de **10 a 15%** na secagem, rachando na queima. A adição de areia quartzosa e fibras de capim seco na **proporção volumétrica de 2:1:1** forma um esqueleto onde as fibras carbonizadas criam microporos que dissipam as tensões de dilatação térmica sem fratura.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Passo 2: Dispor pedras secas em ferradura (formato de U) sobre chão seco como base\",\n      \"description\": \"1. **Orientação da entrada de ar**: Deixe uma boca de alimentação de lenha com **largura de 20cm** voltada contra a direção do vento dominante.\\n2. **Alinhamento em ferradura**: Assente pedras secas quebradas em **formato de U contínuo** para estruturar a base.\\n3. **Isolamento de fundo**: Espalhe areia seca e cascalho no piso interno com **espessura de 2 a 3cm** para barrar a friagem da terra.\\n4. **Preenchimento de juntas**: Introduza argamassa de barro sob pressão em todas as frestas entre pedras para selar fugas de ar.\",\n      \"actionNote\": \"> Orientação do vento: A boca voltada para o vento faz as rajadas soprarem fagulhas e fumaça no seu rosto. Aponte sempre a favor do vento ou em ângulo protegido.\",\n      \"svgFileName\": \"pr06-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // FOUNDATION LAYOUT & AIR ENTRY SCHEMATIC\",\n        \"① Boca frontal para lenha (20 cm de largura)\",\n        \"Largura ideal para lenha e entrada de ar\",\n        \"② Pedras secas de fundação em formato U\",\n        \"Perímetro estrutural da base\",\n        \"③ Argamassa grossa de barro nas juntas\",\n        \"Veda vazamentos de ar entre pedras\",\n        \"④ Camada de areia e cascalho no fundo\",\n        \"Barreira térmica contra chão frio\",\n        \"⑤ Abertura virada contra o vento\",\n        \"Protege as brasas contra rajadas fortes\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Passo 3: Empilhar pedras e barro alternadamente formando uma cúpula até a altura do joelho\",\n      \"description\": \"1. **Leito de argamassa de barro**: Espalhe sobre as pedras da base uma camada de barro com **cerca de 5cm de espessura** (palmo de mão).\\n2. **Assentamento travado em zigue-zague**: Assente a fileira seguinte sobre as juntas inferiores, preenchendo todo o contorno com barro.\\n3. **Inclinação em cúpula fechada**: Incline as pedras para dentro gradativamente até atingir **cerca de 45cm de altura**.\\n4. **Acabamento e polimento com água**: Umedeça as mãos e alise a parede interna da câmara formando uma curva refletora contínua sem arestas.\",\n      \"actionNote\": \"> Regra estrutural: Erguer paredes altas apenas de barro causa desabamento pelo próprio peso. Use as pedras como esqueleto revestido por barro refratário.\",\n      \"svgFileName\": \"pr06-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DOME CHAMBER CROSS-SECTION & THERMAL CURVATURE\",\n        \"45cm\",\n        \"① Corte transversal de pedras e barro\",\n        \"Pedras travadas evitam colapso estrutural\",\n        \"② Parede grossa de barro (5 cm) isolante\",\n        \"Massa térmica retém calor a noite toda\",\n        \"③ Superfície lisa refletora de calor\",\n        \"Alisada com mão úmida para bom fluxo\",\n        \"④ Câmara esférica interna de combustão\",\n        \"⑤ Perfil total até o joelho (45 cm)\",\n        \"Equilíbrio ideal de volume e altura de cocção\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"Concentração radiante em cúpula hemisférica e inércia térmica a 650°C\",\n        \"text\": \"A curvatura parabólica interna funciona como refletor infravermelho de corpo negro em direção à boca superior de cocção. A parede espessa de **5cm de espessura** armazena calor sensível em alta densidade, retendo **300 a 650°C** por horas após o término das chamas.\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Passo 4: Abrir bocal superior para panela e perfurar chaminé traseira\",\n      \"description\": \"1. **Abertura superior de cocção**: Modele no topo da cúpula um bocal circular de **diâmetro 15–20cm** para panelas ou pedras de assar.\\n2. **Ressaltos de espaçamento**: Crave 3 pedrinhas triangulares na borda para garantir uma **folga de 1cm para tiragem**.\\n3. **Furação da chaminé traseira**: Fure a parede posterior superior na diagonal com um galho grosso para criar um **duto de exaustão de fumaça**.\\n4. **Inspeção do fluxo térmico**: Confirme que há um canal contínuo de sucção de ar da entrada frontal inferior até a chaminé traseira.\",\n      \"actionNote\": \"> Efeito chaminé: Sem exaustão traseira alta, a fumaça sai pela boca frontal cegando o operador. Posicionar a chaminé mais alta garante tiragem limpa.\",\n      \"svgFileName\": \"pr06-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // AIR DRAFT PERSPECTIVE & EXHAUST BLUEPRINT\",\n        \"① Entrada inferior de ar (oxigênio)\",\n        \"Ar fresco puxado para a brasa\",\n        \"② Bocal plano superior de cozimento\",\n        \"Apoio para panela ou chapa de pedra\",\n        \"③ Chaminé traseira inclinada\",\n        \"Expele fumaça densa para trás\",\n        \"④ Vórtice térmico ascendente de calor\",\n        \"Circula na câmara aquecendo a panela\",\n        \"⑤ Ressaltos espaçadores para tiragem\",\n        \"O fogo não apaga com a panela apoiada\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD AERODYNAMICS\",\n        \"title\": \"Efeito chaminé e dinâmica de indução Venturi\",\n        \"text\": \"A diferença de cota e o gradiente térmico entre a boca frontal inferior e a chaminé traseira elevada acionam um forte **efeito chaminé (Stack Effect)**. A rápida ascensão dos gases quentes gera pressão negativa interna, induzindo ar fresco continuamente ao leito de brasas.\"\n      }\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Passo 5: Curar com fogo brando de gravetos por 3 horas para endurecer o barro como tijolo\",\n      \"description\": \"1. **Acendimento em baixa potência**: Crie um braseiro pequeno de folhas secas e gravetos próximo à boca de alimentação.\\n2. **Secagem lenta contínua**: Mantenha calor brando por **3 a 4 horas** consecutivas sem alimentar chamas altas.\\n3. **Verificação de cura visual**: Acompanhe a mudança de cor do marrom escuro úmido para um **tom ocre claro e seco**, cessando a saída de vapor.\\n4. **Calafetagem de microfissuras**: Aplique uma camada fina de pasta de barro sobre qualquer trinca de secagem para consolidar a vedação.\",\n      \"actionNote\": \"> Perigo de queima rápida: Queimar toras grossas logo no início ferve a água interna e explode as paredes. A secagem lenta por mais de 3 horas transforma o barro em cerâmica sólida.\",\n      \"svgFileName\": \"pr06-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // CONTROLLED DEHYDRATION & CERAMIC HARDENING\",\n        \"① Fogo brando de gravetos na entrada\",\n        \"Calor suave permite saída gradual de vapor\",\n        \"② Plumas de vapor d'água evaporando\",\n        \"Água interna evapora sem estourar\",\n        \"③ Mudança visual de coloração\",\n        \"Marrom escuro úmido → ocre claro seco\",\n        \"④ Teste de toque seco e quente\",\n        \"Parede morna sem umidade pegajosa\",\n        \"⑤ Pasta de barro para vedar trincas\",\n        \"Selar frestas com pasta fresca de barro\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Erro Fatal: Construir paredes de combustão com pedras de rio úmidas\",\n    \"description\": \"Pedras coletadas em leitos de rios guardam moléculas de água em seus microporos, mesmo quando secas por fora. Em contato direto com chamas a mais de 300°C, a água ferve instantaneamente sob altíssima pressão, fazendo a pedra explodir como uma granada. Estilhaços cortantes podem atingir olhos e rosto. Colete pedras apenas em encostas secas a mais de 10m da água e revista todas as faces com 5cm de barro refratário.\",\n    \"consequence\": \"Consequência: A explosão por vapor de água projeta estilhaços de rocha afiados causando cegueira e queimaduras profundas\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Fogueiras no chão perdem 80% do calor para o vento. Aprenda a fazer um fogão primitivo de barro indestrutível.\",\n    \"body\": \"Pise 2 partes de argila, 1 de areia e 1 de palha até formar massa firme. Disponha pedras em U, suba uma cúpula até o joelho, abra o bocal superior e a chaminé traseira. Cure por 3 horas com gravetos. Nunca use pedras de rio úmidas; elas explodem feito estilhaços no fogo.\",\n    \"outro\": \"Cozinha em tempestades e retém calor radiante a noite inteira.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr06-outcome.svg\",\n    \"title\": \"Fogão de Pedra com Reboco de Barro Finalizado\",\n    \"description\": \"Um fogão em cúpula de barro com núcleo de pedras, reboco liso, bocal superior de cocção e chaminé traseira projetado para reter 650°C de calor.\"\n  },\n  \"createdAt\": \"2026-10-14T10:15:00.000Z\",\n  \"updatedAt\": \"2026-10-16T13:10:22+09:00\",\n  \"contentHash\": \"3786963cf3f53637\"\n}","content/protocols/locales/06-clay-hearth.zh-TW.json":"{\n  \"protocolId\": \"PR-06\",\n  \"category\": \"SHELTER\",\n  \"title\": \"如何用泥土與石塊堆砌防風避雨且鎖住溫度的原始爐灶\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[保溫與食糧必備]\",\n  \"summary\": \"在野外直接於地面生火，八成以上的熱量會隨風散失，木柴消耗量暴增三倍，且飛散的火星極易引發火災。利用紅黏土、河砂、乾草揉合的泥漿包覆乾燥石塊築成圓頂泥灶，即使狂風暴雨也不會熄滅，能烹煮食物並整夜保持溫熱，是極佳的野外生存熱源。\",\n  \"timeRequired\": \"3小時\",\n  \"successRate\": \"90% (嚴格遵循微火烘烤時)\",\n  \"difficulty\": \"普通 (踩泥揉漿與疊石作業)\",\n  \"outputPerHour\": \"完成1座 (可永久重複使用)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"具黏性的紅黏土 2碗 (河岸邊或裸露土壁挖取的黏土)\",\n      \"desc\": \"挑選捏在手中如麵糰般緊密且具黏性的泥土。這是將整個灶體緊密黏合固化的核心原料。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"粗河砂 1碗 (混有細小石粒的乾燥砂土)\",\n      \"desc\": \"純黏土乾燥時會嚴重收縮碎裂。混入粗砂能提供堅固骨架，有效防止泥壁開裂。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"剪成手指長度的乾草或稻草 1碗\",\n      \"desc\": \"在泥漿中扮演如鋼筋般的拉力纖維，使爐壁即便承受高溫大火也不會裂開坍塌。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"完全乾燥的堅硬碎石 15~20顆 (拳頭至頭顱大小)\",\n      \"desc\": \"泡過水的河石受熱極易引發高壓水蒸氣爆炸。務必使用離水邊10公尺以上陽光曬乾的山丘乾石。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"步驟 1: 將黏土2份、粗砂1份、乾草1份加水踩踏揉成韌性泥糰\",\n      \"description\": \"1. **黃金比例倒料混勻**：在平坦地面上倒出**紅黏土2碗**、**粗砂1碗**、剪成手指長度的**乾草1碗**。\\n2. **少量分次加水踩踏**：切勿一次倒入過多水，分次少量潑灑，用腳後跟集中體重用力踩踏**10分鐘以上**。\\n3. **對折翻動均勻壓縮**：將泥堆對折反覆踩踏，使黏土、砂粒與纖維徹底揉合為均質基質。\\n4. **保形彈性無痕檢驗**：揉成拳頭大小泥球放在掌心，確認受壓時**表面毫無細微裂痕**。\",\n      \"actionNote\": \"> 水量拿捏秘訣: 水分過多會變成稀泥流淌無法築壁；水分過少則乾澀易碎。應揉至如同包子皮麵糰般略硬且黏實的狀態最佳。\",\n      \"svgFileName\": \"pr06-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // CLAY TEMPERING & FIBER MATRIX BLUEPRINT\",\n        \"① 具黏性的紅黏土 2份\",\n        \"提供黏結力的基礎基底材\",\n        \"+\",\n        \"② 粗河砂 1份\",\n        \"防止乾燥收縮與開裂\",\n        \"+\",\n        \"③ 剪碎的乾草纖維\",\n        \"強化結構拉力的內部骨幹\",\n        \"④ 少量加水並用腳後跟踩踏\",\n        \"切勿一次倒滿水；對折反覆踩\",\n        \"⑤ 完成扎實有韌性的泥糰\",\n        \"揉成拳頭大實心糰不散落\",\n        \"外表無細微龜裂痕跡\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD CERAMICS\",\n        \"title\": \"耐火回火（Refractory Tempering）與抗收縮龜裂基質\",\n        \"text\": \"純黏土脫水乾燥時線收縮率高達**10~15%**，燒結時極易開裂。將未燒結矽砂與有機乾草纖維依**2:1:1體積比**複合摻配，砂粒成為耐火骨材，炭化纖維留下微細空隙吸收熱應力，形成抗熱震複合基質。\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"步驟 2: 在乾燥地面以U字型排布拳頭大石塊奠定基座\",\n      \"description\": \"1. **進料開口朝向配置**：朝向背風方向預留一手掌寬、即**開口寬度約20公分**的柴火添料口。\\n2. **馬蹄U型基底排石**：將拳頭大的乾燥碎石以**U字型馬蹄狀**緊密排布於地面。\\n3. **底部隔熱鋪砂防潮**：內部地面鋪設乾砂與細石子達**厚度2~3公分**，徹底阻斷地表濕氣與冷氣。\\n4. **泥漿密實填塞接縫**：用拳頭將步驟1的泥糰用力壓入石塊間的所有夾縫，完全封閉漏風孔隙。\",\n      \"actionNote\": \"> 風向安全要領: 爐口若正面迎風，強風會將火星猛烈倒灌吹向臉部。務必將爐口設在背風面或斜向避風側。\",\n      \"svgFileName\": \"pr06-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // FOUNDATION LAYOUT & AIR ENTRY SCHEMATIC\",\n        \"① 前方柴火進料口 (寬約20公分)\",\n        \"兼顧添柴與進氣的最佳口徑\",\n        \"② U字型排布的拳頭大乾石塊\",\n        \"支撐基礎的主要骨幹\",\n        \"③ 填滿縫隙的厚實泥漿\",\n        \"完全阻斷石塊間漏氣縫隙\",\n        \"④ 底部乾砂與細石隔熱層\",\n        \"隔絕冰冷地面的濕氣與低溫\",\n        \"⑤ 背風方向配置爐口\",\n        \"防止強風倒灌吹散炭火\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"步驟 3: 交錯堆疊石塊與泥漿，砌出及膝高的圓頂爐壁\",\n      \"description\": \"1. **泥漿緩衝層塗抹**：在基底石塊上方鋪上厚達一掌、即**厚度約5公分**的泥漿層。\\n2. **交錯咬合疊加石塊**：將下一層石塊壓在下層石縫上呈Z字交錯疊放，並用泥漿填滿縫隙。\\n3. **向內收口圓頂砌築**：越往上堆疊石塊越朝內側傾角收縮，直至及膝高即**高度約45公分**形成圓頂。\\n4. **內壁手沾水抹光**：雙手沾水將燃燒室內壁撫平抹光，修飾成光滑連續的熱對流反射曲面。\",\n      \"actionNote\": \"> 防止坍塌: 切勿不加石頭單純疊泥壁，重力會使下方坍塌。必須以石塊為核心骨架，內外包覆厚實泥漿。\",\n      \"svgFileName\": \"pr06-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DOME CHAMBER CROSS-SECTION & THERMAL CURVATURE\",\n        \"45cm\",\n        \"① 石塊與泥漿交錯剖面\",\n        \"交錯互鎖防止結構坍塌\",\n        \"② 一掌厚(約5公分)泥保溫壁\",\n        \"巨大蓄熱層整夜鎖住溫度\",\n        \"③ 平整光滑的熱反射曲面\",\n        \"沾水手抹平確保良好通風\",\n        \"④ 熱氣盤旋的內部球形燃燒室\",\n        \"⑤ 及膝高(約45公分)整體高度\",\n        \"兼顧烹飪穩定度與蓄熱體積\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"半球圓頂輻射熱聚焦與650°C高溫蓄熱力學\",\n        \"text\": \"拋物線狀的圓頂內壁扮演黑體輻射反射面，將紅外線熱能精準聚焦於頂部烹飪火口。**厚度達5公分**的高密度泥壁具備極高熱容量，能在明火熄滅後長達數小時內持續維持**300~650°C**內部蓄熱。\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"步驟 4: 在爐頂保留鍋座開孔並於後方上方開鑿排煙煙囪\",\n      \"description\": \"1. **頂部烹飪火口開孔**：在圓頂正中央預留直徑**15~20公分**的圓孔以穩固承放鍋具或石板。\\n2. **三角透氣墊石預埋**：在孔緣三角形嵌入3顆小石子，維持**1公分透氣間隙**防止坐鍋熄火。\\n3. **後方排煙通道穿刺**：以手腕粗的樹枝斜刺穿透後壁上方，開闢排出刺鼻濃煙的**排氣煙囪孔**。\\n4. **熱對流抽風通道檢視**：確認從前方下側進料口至後方上方煙囪形成順暢無阻的熱空氣上升通道。\",\n      \"actionNote\": \"> 氣流對流原理: 若無後方煙囪，濃煙會全部由前方爐口湧出刺眼嗆人。後方煙囪位置高於前爐口，才能產生強大的抽風效應。\",\n      \"svgFileName\": \"pr06-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // AIR DRAFT PERSPECTIVE & EXHAUST BLUEPRINT\",\n        \"① 前下方進氣口 (供應氧氣)\",\n        \"新鮮冷空氣被吸入炭火堆\",\n        \"② 頂部平整烹飪開口\",\n        \"承放鍋具或石板的火口\",\n        \"③ 後上方傾斜排煙煙囪孔\",\n        \"將刺鼻濃煙乾淨導向後方排出\",\n        \"④ 向上迴旋的強烈熱流線\",\n        \"在爐室盤旋加熱鍋底\",\n        \"⑤ 鍋底透氣墊石凸起\",\n        \"放上鍋具也不會阻絕火勢\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD AERODYNAMICS\",\n        \"title\": \"煙囪效應（Stack Effect）與文丘里抽氣流體力學\",\n        \"text\": \"下部進氣口與後上方煙囪之間的高低差及強烈溫差會引發劇烈的**煙囪效應（Chimney Effect）**。高溫煙氣快速向外拔升在燃燒室內形成負壓，源源不絕自動吸入新鮮氧氣維持燃燒。\"\n      }\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"步驟 5: 以細枝微火烘烤3小時使泥壁如磚石般堅硬\",\n      \"description\": \"1. **微弱熱源引火**：以乾燥落葉與小細枝在進料口附近點燃拳頭大小的溫和微火。\\n2. **低溫緩慢脫水烘乾**：嚴禁使用大柴猛火，連續維持溫和烘烤**3至4小時**使內部水分蒸發。\\n3. **外觀色澤轉換確認**：外壁深褐色濕泥漸轉為**乾燥淺黃褐色**，且不再冒出白色水蒸氣。\\n4. **細微裂紋塗泥抹平**：若烘烤中出現細微髮絲裂痕，取少量泥漿薄薄抹平密封即可融合。\",\n      \"actionNote\": \"> 嚴禁急熱大火：若一開始就燃燒大木柴，內部水分瞬間暴沸會直接炸穿爐壁。必須以弱火微熱慢烘3小時以上，方能固化如耐火陶瓷磚石。\",\n      \"svgFileName\": \"pr06-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // CONTROLLED DEHYDRATION & CERAMIC HARDENING\",\n        \"① 爐口細枝微弱餘燼火 (溫和熱源)\",\n        \"均勻熱力讓內部水分緩緩排出\",\n        \"② 外壁水蒸氣蒸散線\",\n        \"孔隙水分安全氣化排出\",\n        \"③ 顏色轉變判斷指標\",\n        \"濕潤深褐色 → 乾燥淺黃褐色\",\n        \"④ 溫熱乾燥觸摸檢驗\",\n        \"外壁觸感溫熱無濕黏感\",\n        \"⑤ 髮絲裂縫泥漿修補\",\n        \"以新鮮泥漿密封微小縫隙\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"絕對不能犯的錯誤：在直接受火處堆砌未經完全乾燥的濕河石\",\n    \"description\": \"自河邊撿拾的河石內部微孔中封存著水分分子，即使表面乾燥，一旦遭遇超過300°C的直火加熱，內部水分會瞬間化為超高壓水蒸氣，如同手榴彈般引發劇烈爆炸。飛濺的碎石鋒利無比，極易致人失明或造成嚴重外傷。務必使用遠離水邊10公尺以上山丘曬乾的石頭，並以5公分厚泥漿徹底包裹防護。\",\n    \"consequence\": \"後果：高壓水蒸氣引發石塊爆炸飛濺碎屑，造成失明與重度燒燙傷\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"野外直接在地面生火，80%熱量隨風散失。教你如何搭建暴風雨中永不熄滅的原始泥石火灶。\",\n    \"body\": \"黏土2份、砂1份、乾草1份用腳踩踏成泥糰。排布U型乾石基座，砌至及膝高圓頂，頂部開鍋孔、後方穿煙囪。以細枝微火烘乾3小時脫水固化。絕不可拿潮濕河石直火加熱，水蒸氣會引發碎石爆炸。\",\n    \"outro\": \"狂風暴雨中亦能安穩烹飪，整夜鎖住宜人溫度。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr06-outcome.svg\",\n    \"title\": \"泥漿抹面石砌爐灶（原始烹飪爐灶）完成外觀\",\n    \"description\": \"U字形基座上覆蓋5公分厚平滑稻草黃土抹面，具備頂部烹飪耐熱爐口與後方排煙煙囪，可牢牢鎖住650°C高溫的原始爐灶完成形態。\"\n  },\n  \"createdAt\": \"2026-10-14T10:15:00.000Z\",\n  \"updatedAt\": \"2026-10-16T13:10:22+09:00\",\n  \"contentHash\": \"3786963cf3f53637\"\n}","content/protocols/locales/08-figure-four-deadfall.de.json":"{\n  \"protocolId\": \"PR-08\",\n  \"category\": \"FOOD\",\n  \"title\": \"Tiere fangen mit 3 Stöcken und einem Felsbrocken (Vierer-Schlagfalle)\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[PROTEIN & NAHRUNG KRITISCH]\",\n  \"summary\": \"Tiere mit bloßen Händen zu jagen führt schnell zu lebensgefährlicher Erschöpfung. Wenn man drei fingerdicke Äste mit Kerben versieht und zu einer 'Ziffer 4' zusammensteckt, tragen sie ohne jedes Seil einen 15kg schweren Stein. Berührt ein Beutetier den Köder, löst sich das Gestell in 0,1 Sekunden auf und der Fels fällt herab.\",\n  \"timeRequired\": \"30 Minuten (20 Min Schnitzen + 10 Min Ausrichtung)\",\n  \"successRate\": \"95% (bei Einhaltung der Auslöser-Kerbung)\",\n  \"difficulty\": \"Mittel (präzises Schnitzen & Gleichgewicht)\",\n  \"outputPerHour\": \"2 Fallen pro Stunde (dauerhaft wiederverwendbar)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"3 fingerdicke, gerade Hartholzstäbe (25-30 cm lang)\",\n      \"desc\": \"Trockenes Eichenholz, das sich unter schwerer Steinlast nicht durchbiegt, zugeschnitten als Pfosten, Stütze und Köderstab.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 flacher, schwerer Felsbrocken (10-15 kg)\",\n      \"desc\": \"Muss das 3- bis 5-fache des Beutetiergewichts wiegen und eine ebene Unterseite besitzen, die Fluchtlücken ausschließt.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"1 scharfer Feuerstein-Abschlag oder Steinklinge\",\n      \"desc\": \"Primitives Schneidwerkzeug zum Schnitzen exakter 45-Grad-Keile und rechtwinkliger Haltenuten.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Natürlicher Köder (Waldbeeren, Larven, Insekten, Samen)\",\n      \"desc\": \"Fest auf die innere Spitze des Köderstabs gespießt, um das Tier zum horizontalen Ziehen zu zwingen.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Schritt 1: Carve 3 sticks (Post, Strut, and Bait Stick notches)\",\n      \"description\": \"1. **Vertikalpfosten schnitzen**: Die Spitze des **20cm-Vertikalpfostens** flach wie einen Schlitzschraubendreher zuspitzen und eine rechtwinklige Nut in die Mitte schneiden.\\n2. **Diagonalstrebe schnitzen**: Eine 45-Grad-V-Nut in das obere Ende der **25cm-Diagonalstrebe** kerben und das untere Ende zu einer flachen Kante abschrägen.\\n3. **Köderstab schnitzen**: Eine Rastenstufe am **30cm-Köderstab** für den Pfosten schneiden, eine hintere Kerbe für die Strebe einkerben und die innere Spitze nadelspitz schnitzen.\\n4. **Rechtwinklige Kerbenkontrolle**: Sicherstellen, dass alle Verriegelungsstufen scharfe **90-Grad-Winkelkanten** statt abgerundeter Kurven aufweisen.\",\n      \"actionNote\": \"> Carving Tip: If you make the notches rounded, they will slip out. Cut them crisp and square with a sharp knife edge so the sticks bite firmly into each other.\",\n      \"svgFileName\": \"pr08-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // SCHRITT 01\",\n        \"POST (Stick 1 - Chisel Tip & Square Notch)\",\n        \"STRUT (Stick 2 - Top V-Notch & Bottom Bevel)\",\n        \"BAIT STICK (Stick 3 - Catch Ledge & Pin Tip)\",\n        \"[KEY] Carve crisp square notches that bite firmly\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD MECHANICS\",\n        \"title\": \"Statisches Reibungsgleichgewicht und Haarabzug-Empfindlichkeit\",\n        \"text\": \"Die drei Komponenten der 4er-Falle halten das Felsgewicht durch den **statischen Reibungskoeffizienten** der rechtwinkligen Kerben. Eine flache Kerbentiefe von nur **2–3mm** senkt die erforderliche Auslösekraft auf **unter 50g**, was maximale Empfindlichkeit garantiert.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Schritt 2: Rest the Diagonal Strut on top of the Vertical Post\",\n      \"description\": \"1. **Vertikale Basisausrichtung**: Den Vertikalpfosten auf festem, ebenem Boden absolut wackelfrei aufstellen.\\n2. **Obere V-Nut-Kopplung**: Die V-Nut der Diagonalstrebe in einem exakten **45-Grad-Neigungswinkel** auf die flache Spitze des Pfostens setzen.\\n3. **Achsausrichtung prüfen**: Mit dem Finger leichten Druck von oben ausüben, um sicherzustellen, dass die Strebe nicht abrutscht und exakt an der **Pfostenachse** anliegt.\",\n      \"actionNote\": \"> Angle Check: Keep the strut at roughly a 45-degree angle to hold the heavy boulder weight most reliably.\",\n      \"svgFileName\": \"pr08-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // SCHRITT 02\",\n        \"Post 1 Flat Chisel Tip\",\n        \"Strut 2 V-Notch Joint\",\n        \"Locks firmly at 45°\",\n        \"[KEY] Top hinge locks firmly without sliding\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD VECTOR PHYSICS\",\n        \"title\": \"45-Grad-Winkelstützung und Druck-Schub-Kraftzerlegung\",\n        \"text\": \"Durch die Neigung der Strebe um **45 Grad** wird die vertikale Schwerkraft des Felsens optimal in vertikale Druckspannung am Pfosten und horizontale Zugspannung am Köderstab aufgeteilt. Diese Geometrie bildet die ideale Schwelle zwischen Stabilität und Sofortauslösung.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Schritt 3: Insert the Bait Stick to make the 'Number 4' stand alone\",\n      \"description\": \"1. **Köderstab horizontal einhängen**: Den Köderstab waagerecht halten und die vordere Raststufe in die **mittlere Pfostennut** einhängen.\\n2. **Strebefuß aufsetzen**: Das untere Ende der Diagonalstrebe vorsichtig in die **hintere Kerbe des Köderstabs** einpassen.\\n3. **Selbsttragendes Gleichgewicht prüfen**: Die Hände langsam zurückziehen und kontrollieren, ob die drei Hölzer durch reine Reibung in einer steifen **Zahl-4-Silhouette** ohne Schnüre frei stehen.\",\n      \"actionNote\": \"> Balance Check: When you let go, it must balance solidly without wobbling. If it tilts, flatten the bottom of the vertical post.\",\n      \"svgFileName\": \"pr08-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // SCHRITT 03\",\n        \"Post-Bait Stick Middle Joint\",\n        \"Strut-Bait Stick Rear Joint\",\n        \"Stands alone in Number 4 shape\",\n        \"[KEY] Sticks push against each other to stand\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Schritt 4: Lean the heavy rock on top & test 0.1-second hair trigger\",\n      \"description\": \"1. **Köder fixieren**: Insekten oder Beeren fest auf die spitze Innenseite des Köderstabs spießen.\\n2. **10–15kg-Felsen anlehnen**: Einen flachen Stein von **10 bis 15kg** anheben und vorsichtig in einem **40–45-Grad-Winkel** an die obere Spitze der Strebe anlehnen.\\n3. **Sicherheitsabstand wahren**: Die Hände ausschließlich an den Seiten des Steins halten und niemals Finger unter die **Schlagfallzone** bringen.\\n4. **0,1-Sekunden-Auslösetest**: Den Köderstab leicht mit einem Zweig antippen, um zu prüfen, ob die Falle in **unter 0,1 Sekunden** blitzartig zusammenbricht.\",\n      \"actionNote\": \"> Safety First: Never put your hands or fingers underneath the rock while setting it. Always hold the sides so you are safe if it accidentally falls.\",\n      \"svgFileName\": \"pr08-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // SCHRITT 04\",\n        \"15kg Flat Rock Loaded\",\n        \"Bait set on inner tip\",\n        \"Drops rock in 0.1s when touched\",\n        \"[KEY] Hair trigger collapses instantly on touch\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD KINEMATICS\",\n        \"title\": \"0,1-Sekunden-Freifallbeschleunigung und Endaufprallimpuls\",\n        \"text\": \"Sobald der Abzug gelöst wird, fällt der Fels durch Erdbeschleunigung in **unter 0,1 Sekunden** zu Boden. Die **15kg** schwere Steinplatte erzeugt einen sofortigen Aufprallimpuls, der die Fluchtreaktion des Beutetiers (Reaktionszeit ca. 0,15–0,2s) vollständig unterbindet.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Tödlicher Fehler: Kerben zu tief schneiden oder zu leichten Stein wählen\",\n    \"description\": \"Zu tiefe Kerben klemmen fest und lösen bei Berührung nicht aus. Ein zu leichter Stein verletzt das Beutetier nur, sodass es flieht und Artgenossen im Revier dauerhaft warnt.\",\n    \"consequence\": \"Folge: Jagdmisserfolg, Hungertod und gewarntes Wild im gesamten Gebiet\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Wild hinterherzurennen lässt dich verhungern! Baue diese 0,1s-Steinfalle aus 3 Stöcken!\",\n    \"body\": \"Drei Stöcke mit Kerben zur Zahl 4 verbinden: Hält ganz ohne Seile durch reine Reibung einen 15kg-Felsen! Der Clou: Kerben flach halten. Sobald ein Nagetier den Köder berührt, bricht die Spannung und der Fels zermalmt die Beute in 0,1 Sekunden!\",\n    \"outro\": \"Offline-Überlebenspläne ohne Internetzugang über den Link im Profil abrufen.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr08-outcome.svg\",\n    \"title\": \"Completed Figure-4 Deadfall Trap Full Setup\",\n    \"description\": \"Three finger-thick sticks interlock to support a heavy 15kg rock at an angle, dropping the stone in 0.1 seconds the moment prey touches the bait beneath it.\",\n    \"imageFileName\": \"pr08-outcome.png\"\n  },\n  \"createdAt\": \"2026-10-14T15:35:00.000Z\",\n  \"updatedAt\": \"2026-10-15T16:00:00+09:00\",\n  \"contentHash\": \"51e4bec4273ad957\"\n}","content/protocols/locales/08-figure-four-deadfall.en.json":"{\n  \"protocolId\": \"PR-08\",\n  \"category\": \"FOOD\",\n  \"title\": \"How to Catch Animals with 3 Sticks and a Boulder (Figure-4 Trap)\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[PROTEIN & FOOD CRITICAL]\",\n  \"summary\": \"Chasing wild animals with bare hands will quickly exhaust you to death. By carving notches into three finger-thick sticks and interlocking them into a 'number 4' shape, they can support a heavy 15kg boulder without any rope. When a rodent or small animal touches the bait, the sticks instantly slip apart in 0.1 seconds, dropping the boulder for an instant, reliable kill.\",\n  \"timeRequired\": \"30 minutes (20 min carving + 10 min trigger setup)\",\n  \"successRate\": \"95% (with proper hair-trigger notch calibration)\",\n  \"difficulty\": \"Moderate (precise notch carving & balance)\",\n  \"outputPerHour\": \"2 traps per hour (reusable indefinitely)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"3 straight dry hardwood sticks (finger-thick, 25-30cm long)\",\n      \"desc\": \"Seasoned oak or hickory sticks that will not bend or flex under the heavy deadfall load, carved into the vertical post, diagonal strut, and bait stick.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 flat heavy boulder (10-15kg)\",\n      \"desc\": \"Must weigh 3 to 5 times the target prey's body mass, with a broad flat underside that crushes down without leaving escape gaps.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"1 sharp flint flake or stone knife\",\n      \"desc\": \"A primitive cutting edge used to carve clean 90-degree catch ledges and 45-degree chisel wedges on the sticks.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Natural bait (wild berries, grubs, insects, or seeds)\",\n      \"desc\": \"Firmly impaled onto the pointed inner tip of the bait stick to compel the animal to tug horizontally.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Step 1: Carve 3 sticks (Post, Strut, and Bait Stick notches)\",\n      \"description\": \"1. **Vertical Post Carving**: Whittle the top of the **20cm vertical post** into a flat screwdriver wedge and cut a crisp square notch across the midsection.\\n2. **Diagonal Strut Carving**: Notch a clean 45-degree V-socket into the top of the **25cm diagonal strut** and bevel the bottom foot into a flat chisel edge.\\n3. **Horizontal Bait Stick Carving**: Carve a square catch ledge on the **30cm bait stick** to mate with the post, cut a rear notch for the strut foot, and taper the inner tip into a sharp needle point.\\n4. **Right-Angle Joint Inspection**: Verify all interlocking ledges form crisp **90-degree square shoulders** rather than rounded bevels.\",\n      \"actionNote\": \"> Carving Tip: If you make the notches rounded, they will slip out. Cut them crisp and square with a sharp knife edge so the sticks bite firmly into each other.\",\n      \"svgFileName\": \"pr08-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // 3 STICKS ANATOMY & NOTCHES\",\n        \"POST (Stick 1 - Chisel Tip & Square Notch)\",\n        \"STRUT (Stick 2 - Top V-Notch & Bottom Bevel)\",\n        \"BAIT STICK (Stick 3 - Catch Ledge & Pin Tip)\",\n        \"[KEY] Carve crisp square notches that bite firmly\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD MECHANICS\",\n        \"title\": \"Static Friction Equilibrium and Hair-Trigger Critical Sensitivity\",\n        \"text\": \"The three components of the Figure-4 trap maintain mechanical equilibrium via the **coefficient of static friction** of the perpendicular notches. Whittling catch ledges down to an ultra-shallow depth of **2–3mm** drastically reduces the required trigger dislodging force to **under 50g**, delivering extreme sensitivity.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Step 2: Rest the Diagonal Strut on top of the Vertical Post\",\n      \"description\": \"1. **Vertical Base Alignment**: Plant the vertical post upright on firm, flat ground with zero wobble.\\n2. **Hinge Joint Engagement**: Mate the top V-socket of the diagonal strut onto the chisel crest of the post at an exact **45-degree incline**.\\n3. **Axial Alignment Verification**: Apply light finger pressure from above to ensure the strut remains locked securely along the **vertical post axis**.\",\n      \"actionNote\": \"> Angle Check: Keep the strut at roughly a 45-degree angle to hold the heavy boulder weight most reliably.\",\n      \"svgFileName\": \"pr08-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // TOP NOTCH INTERLOCK\",\n        \"Post 1 Flat Chisel Tip\",\n        \"Strut 2 V-Notch Joint\",\n        \"Locks firmly at 45°\",\n        \"[KEY] Top hinge locks firmly without sliding\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD VECTOR PHYSICS\",\n        \"title\": \"45-Degree Angular Support and Compressive-Shear Force Resolution\",\n        \"text\": \"Setting the diagonal strut at an exact **45-degree angle** resolves the downward gravitational force of the boulder into balanced vertical compressive load on the post and horizontal tension on the bait stick. This geometry represents the optimal threshold between rock support and instantaneous trigger release.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Step 3: Insert the Bait Stick to make the 'Number 4' stand alone\",\n      \"description\": \"1. **Horizontal Arm Orientation**: Hold the bait stick horizontally parallel to the ground, hooking its front catch ledge into the **central notch of the post**.\\n2. **Strut Foot Seat**: Rest the lower beveled foot of the diagonal strut lightly into the **rear notch of the bait stick**.\\n3. **Self-Balancing Release**: Slowly withdraw both hands and verify the assembly self-balances under mutual friction in a rigid **numeral 4 silhouette** without cords.\",\n      \"actionNote\": \"> Balance Check: When you let go, it must balance solidly without wobbling. If it tilts, flatten the bottom of the vertical post.\",\n      \"svgFileName\": \"pr08-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // NUMBER 4 LOCK ASSEMBLY\",\n        \"Post-Bait Stick Middle Joint\",\n        \"Strut-Bait Stick Rear Joint\",\n        \"Stands alone in Number 4 shape\",\n        \"[KEY] Sticks push against each other to stand\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Step 4: Lean the heavy rock on top & test 0.1-second hair trigger\",\n      \"description\": \"1. **Bait Fixation**: Firmly impale bait insects or wild berries onto the sharp interior tip of the horizontal trigger stick.\\n2. **Deadfall Slab Seating**: Lift a flat boulder of **weight 10–15kg** and lean its leading edge onto the strut crest at a **40–45 degree tilt**.\\n3. **Safety Clearance**: Keep your hands strictly to the side of the stone, never placing fingers beneath the **crush drop zone**.\\n4. **0.1-Second Release Verification**: Tap the bait stick gently with a twig to prove the trigger slips and drops the rock in **under 0.1 seconds**.\",\n      \"actionNote\": \"> Safety First: Never put your hands or fingers underneath the rock while setting it. Always hold the sides so you are safe if it accidentally falls.\",\n      \"svgFileName\": \"pr08-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // ROCK LOAD & 0.1S COLLAPSE\",\n        \"15kg Flat Rock Loaded\",\n        \"Bait set on inner tip\",\n        \"Drops rock in 0.1s when touched\",\n        \"[KEY] Hair trigger collapses instantly on touch\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD KINEMATICS\",\n        \"title\": \"0.1-Second Gravitational Free-Fall and Terminal Impact Force\",\n        \"text\": \"Upon trigger release, the boulder free-falls under gravitational acceleration, impacting the ground in **under 0.1 seconds**. A **15kg** deadfall slab delivers instantaneous terminal momentum that crushes target small game before its neuro-muscular auditory response (approx. 0.15–0.2s) can initiate an escape jump.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Fatal Mistake: Carving notches too deep or using an undersized rock\",\n    \"description\": \"Deep notches lock too tightly and fail to release when an animal nibbles the bait, stealing your food. An undersized rock merely injures the prey, allowing it to flee and spook other animals in the area.\",\n    \"consequence\": \"Consequence: Complete trapping failure, starvation, and alert prey fleeing the zone\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Running after wild animals in the forest will starve you to death. Build this 0.1s rock trap instead!\",\n    \"body\": \"Carve three dry sticks with interlocking notches into the shape of a numeral 4. Under friction alone, it effortlessly supports a 15kg flat boulder without a single knot! The secret? Keep the notches shallow. The moment a rodent or bird nudges the bait, the tension shatters and the rock crushes down in 0.1 seconds!\",\n    \"outro\": \"Access 100% offline survival blueprints without data via the link in bio.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr08-outcome.svg\",\n    \"title\": \"Completed Figure-4 Deadfall Trap Full Setup\",\n    \"description\": \"Three finger-thick sticks interlock to support a heavy 15kg rock at an angle, dropping the stone in 0.1 seconds the moment prey touches the bait beneath it.\",\n    \"imageFileName\": \"pr08-outcome.png\"\n  },\n  \"createdAt\": \"2026-10-14T15:35:00.000Z\",\n  \"updatedAt\": \"2026-10-15T16:00:00+09:00\",\n  \"contentHash\": \"51e4bec4273ad957\"\n}","content/protocols/locales/08-figure-four-deadfall.es.json":"{\n  \"protocolId\": \"PR-08\",\n  \"category\": \"FOOD\",\n  \"title\": \"Cómo atrapar animales con 3 ramas y una roca (Trampa en Figura de 4)\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[CRÍTICO: PROTEÍNA Y ALIMENTO]\",\n  \"summary\": \"Perseguir presas con las manos vacías en la naturaleza causará un agotamiento fatal. Al tallar ranuras en tres ramas del grosor de un dedo y encajarlas en forma de 'número 4', pueden sostener una roca pesada de 15kg sin usar ninguna cuerda. Cuando un animal toca el cebo, la estructura se desarma en 0.1 segundos dejando caer la roca.\",\n  \"timeRequired\": \"30 minutos (20 min tallado + 10 min calibración)\",\n  \"successRate\": \"95% (siguiendo el ajuste fino de muescas)\",\n  \"difficulty\": \"Media (tallado preciso y equilibrio de peso)\",\n  \"outputPerHour\": \"2 trampas por hora (reutilizable indefinidamente)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"3 ramas rectas de madera dura y seca (grosor de un dedo, 25-30 cm)\",\n      \"desc\": \"Madera curada de roble que no flexione bajo la carga pesada, talladas en poste vertical, puntal diagonal y varilla del cebo.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 roca plana y pesada (10-15 kg)\",\n      \"desc\": \"Debe pesar de 3 a 5 veces la masa corporal del animal objetivo, con base plana para aplastar sin dejar vías de escape.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"1 lasca afilada de pedernal o cuchillo de piedra\",\n      \"desc\": \"Filo primitivo para tallar cuñas biseladas a 45 grados y muescas rectas de agarre seguro.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Cebo natural (bayas silvestres, larvas, insectos o semillas)\",\n      \"desc\": \"Firmemente ensartado en el extremo afilado interior de la varilla para forzar a la presa a tirar horizontalmente.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Paso 1: Carve 3 sticks (Post, Strut, and Bait Stick notches)\",\n      \"description\": \"1. **Tallado del poste vertical**: Desbaste el extremo superior del **poste vertical de 20cm** en forma de cuña plana y talle una muesca cuadrada recta en la sección media.\\n2. **Tallado del puntal diagonal**: Talle una muesca en V a 45 grados en el extremo superior del **puntal diagonal de 25cm** y bisele el pie inferior en forma de cuña plana.\\n3. **Tallado de la vara del cebo**: Talle un escalón de retención en la **vara del cebo de 30cm** para encajar con el poste, corte una muesca trasera para el pie del puntal y afile la punta interior como aguja.\\n4. **Inspección de ángulos rectos**: Verifique que todas las muescas formen **hombros rectos a 90 grados** en lugar de bordes redondeados.\",\n      \"actionNote\": \"> Carving Tip: If you make the notches rounded, they will slip out. Cut them crisp and square with a sharp knife edge so the sticks bite firmly into each other.\",\n      \"svgFileName\": \"pr08-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PASO 01\",\n        \"POST (Stick 1 - Chisel Tip & Square Notch)\",\n        \"STRUT (Stick 2 - Top V-Notch & Bottom Bevel)\",\n        \"BAIT STICK (Stick 3 - Catch Ledge & Pin Tip)\",\n        \"[KEY] Carve crisp square notches that bite firmly\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD MECHANICS\",\n        \"title\": \"Equilibrio de fricción estática y sensibilidad crítica\",\n        \"text\": \"Los tres componentes de la trampa en 4 sostienen la carga de la roca mediante el **coeficiente de fricción estática** de las muescas perpendiculares. Tallar los rebordes a una profundidad mínima de **2 a 3mm** reduce la fuerza de disparo a **menos de 50g**, logrando una sensibilidad extrema.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Paso 2: Rest the Diagonal Strut on top of the Vertical Post\",\n      \"description\": \"1. **Alineación vertical de la base**: Plante el poste vertical firme y recto sobre suelo plano sin tambaleos.\\n2. **Enganche de la bisagra superior**: Encaje la muesca en V del puntal diagonal sobre la cuña superior del poste a una **inclinación exacta de 45 grados**.\\n3. **Verificación de alineación axial**: Aplique una ligera presión descendente con el dedo para confirmar que el puntal no se tuerza y mantenga la **alineación con el eje del poste**.\",\n      \"actionNote\": \"> Angle Check: Keep the strut at roughly a 45-degree angle to hold the heavy boulder weight most reliably.\",\n      \"svgFileName\": \"pr08-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // PASO 02\",\n        \"Post 1 Flat Chisel Tip\",\n        \"Strut 2 V-Notch Joint\",\n        \"Locks firmly at 45°\",\n        \"[KEY] Top hinge locks firmly without sliding\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD VECTOR PHYSICS\",\n        \"title\": \"Soporte angular a 45 grados y resolución de fuerzas\",\n        \"text\": \"Al colocar el puntal diagonal a un **ángulo de 45 grados**, la fuerza de gravedad vertical de la roca se resuelve equilibradamente en compresión vertical sobre el poste y tensión horizontal sobre la vara del cebo. Esta geometría marca el umbral óptimo entre soporte estable y disparo instantáneo.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Paso 3: Insert the Bait Stick to make the 'Number 4' stand alone\",\n      \"description\": \"1. **Colocación horizontal del cebo**: Sostenga la vara del cebo horizontalmente, enganchando su escalón frontal en la **muesca central del poste**.\\n2. **Asiento del pie del puntal**: Apoye suavemente el pie biselado del puntal diagonal en la **muesca trasera de la vara del cebo**.\\n3. **Comprobación de autoequilibrio**: Retire ambas manos lentamente y verifique que el conjunto se sostenga por pura fricción en una rígida **silueta del número 4** sin cuerdas.\",\n      \"actionNote\": \"> Balance Check: When you let go, it must balance solidly without wobbling. If it tilts, flatten the bottom of the vertical post.\",\n      \"svgFileName\": \"pr08-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // PASO 03\",\n        \"Post-Bait Stick Middle Joint\",\n        \"Strut-Bait Stick Rear Joint\",\n        \"Stands alone in Number 4 shape\",\n        \"[KEY] Sticks push against each other to stand\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Paso 4: Lean the heavy rock on top & test 0.1-second hair trigger\",\n      \"description\": \"1. **Fijación del cebo**: Ensarte firmemente insectos o frutos silvestres en la punta interior afilada de la vara del cebo.\\n2. **Colocación de la losa de 10-15kg**: Levante una roca plana de **10 a 15kg** y apoye su borde frontal sobre la punta superior del puntal a un **ángulo de 40 a 45 grados**.\\n3. **Espacio de seguridad**: Mantenga las manos estrictamente a los lados de la roca, sin colocar jamás los dedos bajo la **zona de caída de aplastamiento**.\\n4. **Prueba de disparo en 0.1 segundos**: Toque levemente el cebo con una ramita para comprobar que el gatillo se suelta y deja caer la roca en **menos de 0.1 segundos**.\",\n      \"actionNote\": \"> Safety First: Never put your hands or fingers underneath the rock while setting it. Always hold the sides so you are safe if it accidentally falls.\",\n      \"svgFileName\": \"pr08-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // PASO 04\",\n        \"15kg Flat Rock Loaded\",\n        \"Bait set on inner tip\",\n        \"Drops rock in 0.1s when touched\",\n        \"[KEY] Hair trigger collapses instantly on touch\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD KINEMATICS\",\n        \"title\": \"Caída libre gravitacional de 0.1 segundos e impacto terminal\",\n        \"text\": \"Al liberarse el gatillo, la roca cae en aceleración gravitacional impactando el suelo en **menos de 0.1 segundos**. Una losa de **15kg** transmite un impulso terminal instantáneo que aplasta a la presa antes de que su tiempo de respuesta neuro-muscular (aprox. 0.15 a 0.2s) le permita iniciar un salto de escape.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Error fatal: Tallar muescas demasiado profundas o usar una roca ligera\",\n    \"description\": \"Las muescas excesivamente profundas se traban y no disparan cuando el animal mordisquea el cebo. Una roca liviana solo lastima a la presa, permitiéndole escapar y alertar a todos los animales del entorno.\",\n    \"consequence\": \"Consecuencia: Fracaso total, inanición y animales fugitivos en alerta\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"¡Correr tras animales en la selva te matará de hambre! ¡Haz esta trampa de roca de 0,1 segundos!\",\n    \"body\": \"Talla tres ramas con muescas precisas para formar un número 4. ¡Sostiene por pura fricción una roca de 15 kg sin una sola cuerda! El secreto: muescas poco profundas. En cuanto una presa toca el cebo, la tensión se quiebra y la roca aplasta en 0,1 segundos.\",\n    \"outro\": \"Planos de supervivencia sin conexión a internet en el enlace de la bio.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr08-outcome.svg\",\n    \"title\": \"Completed Figure-4 Deadfall Trap Full Setup\",\n    \"description\": \"Three finger-thick sticks interlock to support a heavy 15kg rock at an angle, dropping the stone in 0.1 seconds the moment prey touches the bait beneath it.\",\n    \"imageFileName\": \"pr08-outcome.png\"\n  },\n  \"createdAt\": \"2026-10-14T15:35:00.000Z\",\n  \"updatedAt\": \"2026-10-15T16:00:00+09:00\",\n  \"contentHash\": \"51e4bec4273ad957\"\n}","content/protocols/locales/08-figure-four-deadfall.ja.json":"{\n  \"protocolId\": \"PR-08\",\n  \"category\": \"FOOD\",\n  \"title\": \"木の枝3本と岩で獲物を捕る方法（数字の4型 圧殺罠）\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[食糧・タンパク質確保]\",\n  \"summary\": \"野生で獲物を素手で追いかけると体力を使い果たして倒れてしまいます。指の太さの木の枝3本に溝を彫り「数字の4」の形に噛み合わせることで、紐を一切使わずに15kgの重い岩を自立して支えられます。内側の棒にエサを刺しておけば、小動物がエサをつついた瞬間に0.1秒で崩れて岩が落下する、確実なサバイバル罠です。\",\n  \"timeRequired\": \"30分（枝の加工20分 + 設置・感度調整10分）\",\n  \"successRate\": \"95%（刻み溝の感度調整厳守時）\",\n  \"difficulty\": \"普通（正確な溝削りと重量バランス）\",\n  \"outputPerHour\": \"1時間あたり2基設置可能（半永久再利用）\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"指の太さの硬い枯れ枝3本（長さ25〜30cm）\",\n      \"desc\": \"重い岩の荷重にもしならない乾燥した広葉樹（ナラ・カシ等）を選び、垂直柱・斜め支柱・水平餌棒に切り分けます。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"底が平らで重い平石1個（10〜15kg）\",\n      \"desc\": \"捕獲対象の体重の3〜5倍以上の重さがあり、小動物が隙間から逃げられないよう底面が平坦な石を使用します。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"鋭利な剥片石器または打製石刃1個\",\n      \"desc\": \"木の枝に正確な45度のクサビと直角の引っ掛け溝を削り出すための原始切削具です。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"誘引用の餌（木の実、幼虫、昆虫、種子など）\",\n      \"desc\": \"水平餌棒の先端にしっかり突き刺し、小動物が引っぱって罠を作動させるようにします。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"ステップ1: 枝3本を削る（支柱・突っ張り棒・エサ棒の溝彫り）\",\n      \"description\": \"1. **支柱の加工**: 地面に垂直に立てる**20cmの支柱**の先端をマイナスドライバー状のクサビに削り、中央に四角い溝を彫ります。\\n2. **突っ張り棒の加工**: 岩を斜めに支える**25cmの突っ張り棒**の上端に支柱を受けるV字溝を彫り、下端を平らなクサビ状に削ります。\\n3. **エサ棒の加工**: エサをつける**30cmのエサ棒**に支柱にかける段差と突っ張り棒の下端を受ける後部溝を彫り、先端を針のように尖らせます。\\n4. **直角噛み合いの点検**: 3本の部材の接合部が丸まらず、鋭い**90度の直角段差**を保っているか確認します。\",\n      \"actionNote\": \"> 削るコツ: 溝を丸く削ると滑って崩れてしまいます。刃物で角を直角に削り出すことで、3本の枝が互いにしっかり噛み合います。\",\n      \"svgFileName\": \"pr08-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // 3 STICKS ANATOMY & NOTCHES\",\n        \"支柱（上部クサビ型＆中央四角溝）\",\n        \"突っ張り棒（上部V字溝＆下部斜め削り）\",\n        \"エサ棒（引っ掛け段差＆溝＆尖った先端）\",\n        \"[重要] 互いにしっかり噛み合う直角溝の加工\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD MECHANICS\",\n        \"title\": \"静的摩擦平衡とヘアトリガー臨界感度\",\n        \"text\": \"数字の4型罠（Figure-4 Trap）の3本の部材は、直角溝の**静止摩擦係数**によって岩の重みを支えます。引っ掛け段差の噛み合い深さを**2〜3mm**の極浅に削ることで、トリガー解除に必要な離脱力を**50g未満**に抑え、極限の敏感度を確保します。\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"ステップ2: 支柱の先端に突っ張り棒を引っ掛ける\",\n      \"description\": \"1. **支柱の垂直設置**: 硬く平らな地面に1番の支柱をぐらつきなく垂直に立てます。\\n2. **上部V字溝の結合**: 2番の突っ張り棒の上部V字溝を支柱先端のクサビに**45度の傾斜角**で噛み合わせます。\\n3. **中心軸のアライメント点検**: 上から手で軽く押した際、突っ張り棒が左右にねじれず**支柱の中心軸**と一直線に保たれているか確認します。\",\n      \"actionNote\": \"> 角度確認: 突っ張り棒が約45度に傾いているとき、重い岩の重量を最も安定して支えられます。\",\n      \"svgFileName\": \"pr08-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // TOP NOTCH INTERLOCK\",\n        \"支柱の平たい先端\",\n        \"突っ張り棒のV字溝の結合\",\n        \"45度の角度でしっかり噛み合う\",\n        \"[重要] 滑らずにロックされる上部結合部\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD VECTOR PHYSICS\",\n        \"title\": \"45度斜角支持と圧縮・せん断分力配分\",\n        \"text\": \"突っ張り棒の傾斜角を**45度**に設定することで、岩の垂直重力荷重が支柱の圧縮応力とエサ棒の引張摩擦力へ理想的に等分されます。この幾何学的角度が自立支持と瞬時解除の最適臨界点です。\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"ステップ3: エサ棒を差し込み「数字の4」の形に自立させる\",\n      \"description\": \"1. **エサ棒の水平結合**: 3番のエサ棒を地面と水平に構え、先端の段差を1番支柱の**中央直角溝**に引っかけます。\\n2. **突っ張り棒下端の設置**: 2番突っ張り棒の下端クサビをエサ棒の**後部溝に軽く接触**させて乗せます。\\n3. **自立3角バランスの確認**: 両手をゆっくり離し、部材同士の押し合う摩擦力だけで紐なしで**数字の4の形**に自立するか確認します。\",\n      \"actionNote\": \"> バランス確認: 手を離したときにぐらつかず自立している必要があります。傾く場合は支柱の底面を平らに削り直してください。\",\n      \"svgFileName\": \"pr08-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // NUMBER 4 LOCK ASSEMBLY\",\n        \"支柱とエサ棒の中央結合段差\",\n        \"突っ張り棒とエサ棒の後部溝\",\n        \"紐なしで自立する数字の4型\",\n        \"[重要] 枝同士が押し合って自立する仕組み\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"ステップ4: 岩をもたれかけさせ、0.1秒で作動するか感度を点検する\",\n      \"description\": \"1. **エサの固定**: エサ棒の尖った内側先端に昆虫や野イチゴをしっかり刺して固定します。\\n2. **10〜15kgの岩の設置**: 片手で岩の側面を持ち、突っ張り棒の上端に**40〜45度の角度**でそっともたれかけさせます。\\n3. **安全クリアランスの確保**: 岩を設置する間、絶対に手や身体を**落石の下**に入れないよう注意します。\\n4. **0.1秒トリガー作動点検**: 細い小枝でエサを軽く触れた際、部材が**0.1秒で即座に外れて**岩が落下するか確認します。\",\n      \"actionNote\": \"> 安全第一: 岩をもたれさせるとき、絶対に岩の下に指を入れないでください。側面を支えて安全に作業します。\",\n      \"svgFileName\": \"pr08-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // ROCK LOAD & 0.1S COLLAPSE\",\n        \"15kgの平らな岩を設置\",\n        \"エサ棒の先端にエサを装着\",\n        \"触れると0.1秒で岩が落下\",\n        \"[重要] かすかな接触で即座に崩れる高感度設定\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD KINEMATICS\",\n        \"title\": \"0.1秒重力加速度自由落下と終端衝撃量\",\n        \"text\": \"トリガーが外れた瞬間、岩は重力加速度によって**0.1秒以内**に地表へ到達します。**15kg**の岩が落下して伝達する瞬間衝撃量は、小動物が察知して逃走する反応時間（聴覚・運動反射時間約0.15〜0.2秒）を完全に封殺します。\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命的な失敗：溝を深く彫りすぎて固くしたり、軽すぎる石を使うこと\",\n    \"description\": \"溝が深すぎると獲物が餌を揺らしても罠が崩れず餌だけ奪われます。また石が軽すぎると獲物が負傷したまま逃走し、周囲の動物を警戒させて二度と獲れなくなります。\",\n    \"consequence\": \"結果：食糧確保失敗、体力消耗、周辺の野生動物の警戒激化\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"森で獲物を走って追うと飢え死にします！枝3本で作る0.1秒落石罠！\",\n    \"body\": \"小枝3本に角ばった溝を彫り「数字の4」に組むだけで、紐なしで15kgの岩を支えます。奥に餌を刺しておけば、ネズミや鳥が触れた瞬間にバランスが崩れ0.1秒で岩が圧殺！最大の秘訣は溝を浅く彫ること。かすっただけで即座に落ちるように調整しましょう！\",\n    \"outro\": \"オフラインでも閲覧できる原始生存図面はプロフィールのリンクから。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr08-outcome.svg\",\n    \"title\": \"完成した数字の4型圧殺罠の全景\",\n    \"description\": \"3本の枝が絶妙に噛み合って15kgの重い岩を支え、獲物がエサに触れた瞬間に0.1秒で崩れて岩が圧殺する完成形態。\",\n    \"imageFileName\": \"pr08-outcome.png\"\n  },\n  \"createdAt\": \"2026-10-14T15:35:00.000Z\",\n  \"updatedAt\": \"2026-10-15T16:00:00+09:00\",\n  \"contentHash\": \"51e4bec4273ad957\"\n}","content/protocols/locales/08-figure-four-deadfall.pt.json":"{\n  \"protocolId\": \"PR-08\",\n  \"category\": \"FOOD\",\n  \"title\": \"Como capturar animais com 3 gravetos e uma pedra (Armadilha em 4)\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[CRÍTICO: PROTEÍNA E ALIMENTO]\",\n  \"summary\": \"Perseguir animais selvagens com as mãos vazias esgota rapidamente a sua energia. Entalhando encaixes em três gravetos da grossura de um dedo e montando-os em formato de 'número 4', eles sustentam uma pedra de 15kg sem nenhuma corda. Quando a presa toca a isca, a estrutura desmonta em 0,1 segundo, esmagando a presa.\",\n  \"timeRequired\": \"30 minutos (20 min entalhe + 10 min calibração)\",\n  \"successRate\": \"95% (seguindo o ajuste fino dos encaixes)\",\n  \"difficulty\": \"Média (entalhe de precisão e equilíbrio)\",\n  \"outputPerHour\": \"2 armadilhas por hora (reutilizável)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"3 gravetos retos de madeira dura seca (espessura de um dedo, 25-30 cm)\",\n      \"desc\": \"Madeira curada que não curve sob o peso da pedra, entalhada em haste vertical, escora diagonal e vareta de isca.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 pedra plana e pesada (10-15 kg)\",\n      \"desc\": \"Deve pesar de 3 a 5 vezes a massa do animal alvo, com base reta para esmagar sem deixar vãos de fuga.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"1 lasca de sílex afiada ou lâmina de pedra\",\n      \"desc\": \"Instrumento de corte primitivo para entalhar cunhas a 45 graus e travas retangulares precisas.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Isca natural (frutas silvestres, larvas, insetos ou sementes)\",\n      \"desc\": \"Firmemente espetada na ponta interna da vareta para obrigar a caça a puxar horizontalmente.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Passo 1: Carve 3 sticks (Post, Strut, and Bait Stick notches)\",\n      \"description\": \"1. **Entalhe do poste vertical**: Desbaste a ponta superior do **poste vertical de 20cm** em forma de cunha plana e corte um entalhe quadrado reto no meio.\\n2. **Entalhe da escora diagonal**: Abra um entalhe em V a 45 graus no topo da **escora diagonal de 25cm** e bisele a extremidade inferior em cunha plana.\\n3. **Entalhe da vareta da isca**: Talle um ressalto na **vareta da isca de 30cm** para encaixar no poste, corte um entalhe traseiro para a escora e aponte a extremidade interna como agulha.\\n4. **Inspeção de ângulos retos**: Certifique-se de que todos os encaixes mantenham **ombros retos a 90 graus** em vez de bordas arredondadas.\",\n      \"actionNote\": \"> Carving Tip: If you make the notches rounded, they will slip out. Cut them crisp and square with a sharp knife edge so the sticks bite firmly into each other.\",\n      \"svgFileName\": \"pr08-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PASSO 01\",\n        \"POST (Stick 1 - Chisel Tip & Square Notch)\",\n        \"STRUT (Stick 2 - Top V-Notch & Bottom Bevel)\",\n        \"BAIT STICK (Stick 3 - Catch Ledge & Pin Tip)\",\n        \"[KEY] Carve crisp square notches that bite firmly\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD MECHANICS\",\n        \"title\": \"Equilíbrio de atrito estático e sensibilidade de gatilho leve\",\n        \"text\": \"Os três componentes da armadilha em 4 sustentam a pedra pelo **coeficiente de atrito estático** dos encaixes perpendiculares. Entalhar os ressaltos com profundidade rasa de **2 a 3mm** reduz a força de desarmamento para **menos de 50g**, garantindo sensibilidade extrema.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Passo 2: Rest the Diagonal Strut on top of the Vertical Post\",\n      \"description\": \"1. **Alinhamento vertical da base**: Firme o poste vertical em solo plano e duro, sem qualquer oscilação.\\n2. **Engate da junta superior**: Encaixe o topo em V da escora diagonal na cunha superior do poste a um **ângulo exato de 45 graus**.\\n3. **Verificação de alinhamento axial**: Pressione levemente com o dedo de cima para baixo para garantir que a escora não deslize e mantenha o **alinhamento com o eixo do poste**.\",\n      \"actionNote\": \"> Angle Check: Keep the strut at roughly a 45-degree angle to hold the heavy boulder weight most reliably.\",\n      \"svgFileName\": \"pr08-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // PASSO 02\",\n        \"Post 1 Flat Chisel Tip\",\n        \"Strut 2 V-Notch Joint\",\n        \"Locks firmly at 45°\",\n        \"[KEY] Top hinge locks firmly without sliding\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD VECTOR PHYSICS\",\n        \"title\": \"Suporte angular a 45 graus e decomposição de forças\",\n        \"text\": \"Ao posicionar a escora diagonal a **45 graus**, a gravidade vertical da pedra é decomposta idealmente em compressão no poste e tração na vareta da isca. Essa geometria forma o limiar perfeito entre sustentação de carga e desarme instantâneo.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Passo 3: Insert the Bait Stick to make the 'Number 4' stand alone\",\n      \"description\": \"1. **Encaixe horizontal da isca**: Mantenha a vareta da isca horizontalmente, engatando o ressalto frontal no **entalhe central do poste**.\\n2. **Assentamento da base da escora**: Apoie a ponta chanfrada da escora diagonal no **entalhe traseiro da vareta da isca**.\\n3. **Verificação de autoequilíbrio**: Retire as mãos lentamente e confirme que as 3 peças se sustentam por atrito mútuo numa rígida **silhueta do número 4** sem cordas.\",\n      \"actionNote\": \"> Balance Check: When you let go, it must balance solidly without wobbling. If it tilts, flatten the bottom of the vertical post.\",\n      \"svgFileName\": \"pr08-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // PASSO 03\",\n        \"Post-Bait Stick Middle Joint\",\n        \"Strut-Bait Stick Rear Joint\",\n        \"Stands alone in Number 4 shape\",\n        \"[KEY] Sticks push against each other to stand\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Passo 4: Lean the heavy rock on top & test 0.1-second hair trigger\",\n      \"description\": \"1. **Fixação da isca**: Espete firmemente insetos ou frutas silvestres na ponta interna afiada da vareta da isca.\\n2. **Posicionamento da pedra de 10-15kg**: Levante uma pedra achatada de **10 a 15kg** e apoie sua borda na ponta superior da escora a uma **inclinação de 40 a 45 graus**.\\n3. **Margem de segurança**: Mantenha as mãos sempre pelas laterais da pedra, nunca colocando os dedos na **zona de queda de esmagamento**.\\n4. **Teste de disparo em 0.1 segundo**: Toque suavemente na isca com um graveto para confirmar que o gatilho se solta e derruba a pedra em **menos de 0.1 segundo**.\",\n      \"actionNote\": \"> Safety First: Never put your hands or fingers underneath the rock while setting it. Always hold the sides so you are safe if it accidentally falls.\",\n      \"svgFileName\": \"pr08-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // PASSO 04\",\n        \"15kg Flat Rock Loaded\",\n        \"Bait set on inner tip\",\n        \"Drops rock in 0.1s when touched\",\n        \"[KEY] Hair trigger collapses instantly on touch\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD KINEMATICS\",\n        \"title\": \"Queda livre gravitacional de 0.1 segundo e impacto terminal\",\n        \"text\": \"Assim que o gatilho se solta, a pedra cai sob aceleração gravitacional atingindo o solo em **menos de 0.1 segundo**. Uma laje de **15kg** gera um impulso terminal imediato que neutraliza a presa antes que seu tempo de reação motora (cerca de 0.15 a 0.2s) permita a fuga.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Erro fatal: Entalhar encaixes muito fundos ou usar pedra muito leve\",\n    \"description\": \"Encaixes fundos demais travam a armadilha e não disparam quando a caça morde a isca. Uma pedra leve apenas fere o animal, que foge e alerta todas as outras presas da região.\",\n    \"consequence\": \"Consequência: Falha total na caça, fome e presas ariscas espantadas\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Correr atrás de caça na mata vai te matar de fome! Monte essa armadilha de pedra de 0,1s!\",\n    \"body\": \"Entalhe 3 gravetos em formato de número 4: sustenta por pura fricção uma pedra de 15 kg sem nenhuma corda! O segredo é manter os encaixes rasos. Assim que o animal toca a isca, a pedra desaba em 0,1 segundo!\",\n    \"outro\": \"Acesse guias de sobrevivência offline sem usar dados no link do perfil.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr08-outcome.svg\",\n    \"title\": \"Completed Figure-4 Deadfall Trap Full Setup\",\n    \"description\": \"Three finger-thick sticks interlock to support a heavy 15kg rock at an angle, dropping the stone in 0.1 seconds the moment prey touches the bait beneath it.\",\n    \"imageFileName\": \"pr08-outcome.png\"\n  },\n  \"createdAt\": \"2026-10-14T15:35:00.000Z\",\n  \"updatedAt\": \"2026-10-15T16:00:00+09:00\",\n  \"contentHash\": \"51e4bec4273ad957\"\n}","content/protocols/locales/08-figure-four-deadfall.zh-TW.json":"{\n  \"protocolId\": \"PR-08\",\n  \"category\": \"FOOD\",\n  \"title\": \"用3根樹枝與大石頭捕捉野獸的方法（數字4字形落石陷阱）\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[生存必備：蛋白質與食糧]\",\n  \"summary\": \"在野外徒手追逐獵物只會加速體力耗盡。只要在手指粗的3根樹枝上削出凹槽，拼嵌成「數字4」形狀，不需任何繩索就能穩穩支撐15公斤的重石。當小動物碰觸內側餌料的瞬間，骨架會在0.1秒內鬆脫墜落，是最實用的原始求生陷阱。\",\n  \"timeRequired\": \"30分鐘（樹枝雕刻20分鐘 + 陷阱架設與調校10分鐘）\",\n  \"successRate\": \"95%（嚴格遵守卡槽觸發靈敏度時）\",\n  \"difficulty\": \"普通（精準卡槽雕刻與重量平衡）\",\n  \"outputPerHour\": \"每小時可製作並架設2具（可永久重複使用）\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"手指粗細的筆直乾燥硬木枝3根（長25-30公分）\",\n      \"desc\": \"挑選在高重壓下不會彎曲的堅硬橡木或雜木，分別裁切為垂直立柱、對角支撐桿與水平誘餌桿。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"底部平整的沉重巨石1塊（10-15公斤）\",\n      \"desc\": \"重量必須達獵物體重的3至5倍以上，且底面寬平，確保砸落時不留任何逃生空隙。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"鋒利的燧石石片或打製石刀1把\",\n      \"desc\": \"用以在樹枝上雕刻出精準的45度斜楔與直角卡榫凹槽的原始切削工具。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"天然誘餌（野果、昆蟲幼蟲、種子等）\",\n      \"desc\": \"牢固刺穿於水平誘餌桿內側尖端，誘使動物觸動並水平拉扯觸發陷阱。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"步驟 1: 削製三根樹枝（立柱、斜撐柱與誘餌棒刻槽）\",\n      \"description\": \"1. **加工垂直立柱**: 將垂直立於地面的**20cm立柱**頂端削成一字平頭楔形，並於中段刻出方形直角卡槽。\\n2. **加工對角斜撐柱**: 於支撐巨石的**25cm斜撐柱**上端切出嵌合立柱的V形凹槽，並將下端削成平整楔形。\\n3. **加工水平誘餌棒**: 於掛載誘餌的**30cm誘餌棒**上刻出扣合立柱的凸台與承接斜撐柱的後卡槽，並將內端削尖如針。\\n4. **直角咬合面檢查**: 確認三根構件的咬合切口皆保持**90度直角棱角**，嚴禁削成圓弧倒角。\",\n      \"actionNote\": \"> 削るコツ: 溝を丸く削ると滑って崩れてしまいます。刃物で角を直角に削り出すことで、3本の枝が互いにしっかり噛み合います。\",\n      \"svgFileName\": \"pr08-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // 步驟 01\",\n        \"支柱（上部クサビ型＆中央四角溝）\",\n        \"突っ張り棒（上部V字溝＆下部斜め削り）\",\n        \"エサ棒（引っ掛け段差＆溝＆尖った先端）\",\n        \"[重要] 互いにしっかり噛み合う直角溝の加工\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD MECHANICS\",\n        \"title\": \"靜摩擦平衡與微敏扳機臨界靈敏度\",\n        \"text\": \"4字形陷阱（Figure-4 Trap）的三大構件純靠直角槽口的**靜摩擦係數**支撐巨石重力。將卡槽咬合深度精確削至**2～3mm**極淺邊緣，可使誘餌觸發脫扣力驟降至**50g以下**，達到極致靈敏度。\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"步驟 2: 將斜撐柱頂端搭扣在垂直立柱頂部\",\n      \"description\": \"1. **立柱垂直立起**: 在堅硬平整的地面上將1號立柱端正垂直立起，確保毫無晃動。\\n2. **上端V槽咬合**: 將2號斜撐柱頂部的V形槽以**45度傾角**精確卡入立柱頂端的平頭楔口。\\n3. **中軸對齊檢查**: 用手從上方輕施垂直壓力，確認斜撐柱不會向兩側打滑扭轉，保持**與立柱軸線一致**。\",\n      \"actionNote\": \"> 角度確認: 突っ張り棒が約45度に傾いているとき、重い岩の重量を最も安定して支えられます。\",\n      \"svgFileName\": \"pr08-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // 步驟 02\",\n        \"支柱の平たい先端\",\n        \"突っ張り棒のV字溝の結合\",\n        \"45度の角度でしっかり噛み合う\",\n        \"[重要] 滑らずにロックされる上部結合部\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD VECTOR PHYSICS\",\n        \"title\": \"45度斜角支撐與受壓剪切分力平衡\",\n        \"text\": \"將斜撐柱設定為**45度傾斜角**，可將巨石的垂直重力荷載完美分解為立柱的軸向壓縮應力與誘餌棒的水平拉伸摩擦力。此幾何角度是穩定自立與瞬時解體脫扣的最佳臨界平衡點。\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"步驟 3: 嵌入誘餌棒使結構呈'數字4'狀自立\",\n      \"description\": \"1. **誘餌棒水平卡入**: 將3號誘餌棒水平橫置，將前端卡台扣入1號立柱的**中央直角凹槽**。\\n2. **承托斜撐柱底端**: 將2號斜撐柱底端楔部輕輕搭入誘餌棒**後端的定位槽**。\\n3. **驗證三點自平衡**: 雙手緩慢鬆開，確認三根構件僅憑相互推擠的摩擦力即可自立為穩固的**數字4形骨架**，完全無需繩索。\",\n      \"actionNote\": \"> バランス確認: 手を離したときにぐらつかず自立している必要があります。傾く場合は支柱の底面を平らに削り直してください。\",\n      \"svgFileName\": \"pr08-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // 步驟 03\",\n        \"支柱とエサ棒の中央結合段差\",\n        \"突っ張り棒とエサ棒の後部溝\",\n        \"紐なしで自立する数字の4型\",\n        \"[重要] 枝同士が押し合って自立する仕組み\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"步驟 4: 輕架巨石並測試0.1秒極速觸發靈敏度\",\n      \"description\": \"1. **固定誘餌**: 將昆蟲或野果牢固插在誘餌棒內側銳利的尖端上。\\n2. **架設10～15kg巨石**: 單手握住平整巨石兩側，小心抬起並以**40～45度角**輕靠在斜撐柱上端頂部。\\n3. **保持安全距離**: 安裝巨石時雙手嚴禁伸入**巨石砸落的正下方**，僅能扶持兩側。\\n4. **0.1秒脫扣測試**: 以細樹枝極輕觸動誘餌，檢驗骨架是否能在**0.1秒內瞬間解體**使巨石驟然砸落。\",\n      \"actionNote\": \"> 安全第一: 岩をもたれさせるとき、絶対に岩の下に指を入れないでください。側面を支えて安全に作業します。\",\n      \"svgFileName\": \"pr08-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // 步驟 04\",\n        \"15kgの平らな岩を設置\",\n        \"エサ棒の先端にエサを装着\",\n        \"触れると0.1秒で岩が落下\",\n        \"[重要] かすかな接触で即座に崩れる高感度設定\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD KINEMATICS\",\n        \"title\": \"0.1秒重力加速度自由落體與終端衝擊量\",\n        \"text\": \"扳機脫扣瞬間，巨石在重力加速度作用下將於**0.1秒以內**砸擊地面。**15kg**石板墜落釋放的瞬間終端衝擊量，將徹底封殺小型獵物的逃脫神經反應時間（聽覺-運動反射時間約0.15～0.2秒）。\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命錯誤：卡槽雕刻過深導致卡死，或使用過輕的石頭\",\n    \"description\": \"凹槽太深或過於緊繃，即使獵物大力拉扯誘餌骨架也無法崩解，白白損失食物。石頭太輕則無法一擊致命，獵物負傷逃脫並將警報擴散至整個區域。\",\n    \"consequence\": \"後果：捕獵徹底失敗、體力透支枯竭、區域獵物全部驚逃\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"在荒野狂追動物會把你活活餓死！快學這款3根樹枝做的0.1秒落石陷阱！\",\n    \"body\": \"將三根樹枝刻槽組合成數字4形狀：不用一根繩子，純靠摩擦力就能撐起15公斤巨石！關鍵秘訣在於卡槽要淺，小動物一碰誘餌，張力瞬間瓦解，巨石0.1秒直接砸落！\",\n    \"outro\": \"無須網路即可離線瀏覽的原始生存圖面，請點擊個人簡介連結。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr08-outcome.svg\",\n    \"title\": \"完成した数字の4型圧殺罠の全景\",\n    \"description\": \"3本の枝が絶妙に噛み合って15kgの重い岩を支え、獲物がエサに触れた瞬間に0.1秒で崩れて岩が圧殺する完成形態。\",\n    \"imageFileName\": \"pr08-outcome.png\"\n  },\n  \"createdAt\": \"2026-10-14T15:35:00.000Z\",\n  \"updatedAt\": \"2026-10-15T16:00:00+09:00\",\n  \"contentHash\": \"51e4bec4273ad957\"\n}","content/protocols/locales/09-pit-charcoal-kiln.de.json":"{\n  \"protocolId\": \"PR-09\",\n  \"category\": \"FIRE\",\n  \"title\": \"Herstellung von Hartholzkohle im anaeroben Erdgrubenmeiler\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[RAUCHFREIER BRENNSTOFF & KOHLEFILTER]\",\n  \"summary\": \"Wer Holz im offenen Lagerfeuer verbrennt, verschwendet wertvollen Brennstoff, da es mit Sauerstoff vollständig zu weißer Asche zerfällt. Durch das Ausheben einer 50cm tiefen konischen Erdgrube, dichtes vertikales Schichten von Eichenknüppeln und luftdichtes Versiegeln mit Lehm und Rasensoden wird die Sauerstoffzufuhr um 95% gedrosselt. Das Holz wird pyrolysiert statt verbrannt. Es entsteht dichte, metallisch klingende stückige Holzkohle, die rauchfrei bei 500°C brennt und Trinkwasser filtert.\",\n  \"timeRequired\": \"5 Stunden (1h Grube & Bestückung + 3h Pyrolyse + 1h geschlossene Abkühlung)\",\n  \"successRate\": \"90% (bei striktem Luftabschluss und vollständiger Abkühlung)\",\n  \"difficulty\": \"Mittel (Erkennung der Rauchphasen erforderlich)\",\n  \"outputPerHour\": \"3-5kg hochwertige Hartholzkohle pro Brand\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"15-20 armdicke trockene Eichen- oder Hartholzscheite (Länge 30-40cm)\",\n      \"desc\": \"Dichtes Hartholz, das unter Sauerstoffmangel pyrolysiert, ohne zu verflammen, und langanhaltende Glut liefert.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Konische Erdgrube (50cm Tiefe, 60cm oberer Durchmesser)\",\n      \"desc\": \"Nach unten verjüngt ausgehoben, um Strahlungswärme zu bündeln und die anaerobe Zirkulation zu steuern.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Stabiles Astgitter & breite Laubblätter\",\n      \"desc\": \"Quer über den Holzstapel gelegt, um die schwere Lehmschicht zu stützen und Erdrutsch in die Glut zu verhindern.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Feuchter Tonlehm & Rasensoden (10cm Schichtdicke)\",\n      \"desc\": \"Wärmedämmende Abdeckung, die 95% des Sauerstoffs abriegelt und das Holz bei über 400°C backt.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"Trockenes Reisig & Gluttbett zur Vortrocknung\",\n      \"desc\": \"Treibt Bodenfeuchtigkeit vollständig aus und zündet die Basis der gestapelten Holzscheite an.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Schritt 1: 50cm Konusgrube ausheben & Vorwärmglut anlegen\",\n      \"description\": \"1. **Konische Grube ausheben**: Wählen Sie festen, trockenen Boden und heben Sie eine Grube mit **60cm oberem Durchmesser und 50cm Tiefe** aus.\\n2. **Konischen Boden formen**: Verjüngen Sie die Wände nach unten auf **30cm Durchmesser**, um die thermische Konvektion zentriert zu bündeln.\\n3. **Restfeuchtigkeit austreiben**: Brennen Sie trockenes Reisig am Boden **über 15 Minuten** ab, um die Lehmwände staubtrocken zu brennen.\\n4. **Glutbett anlegen**: Warten Sie, bis die Flammen erlöschen und ein gleichmäßiges, **rot glühendes Glutbett** den gesamten Boden bedeckt.\",\n      \"actionNote\": \"> Aushub-Praxistipp: Restfeuchte in den Erdwänden führt zu Holzfäulnis und erstickt das Glutbett. Heizen Sie den Grubenboden trocken.\",\n      \"svgFileName\": \"pr09-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PIT EXCAVATION & PRE-DRYING\",\n        \"Obere Grubenöffnung 60cm Konusform\",\n        \"Tiefe 50cm (Bodendurchmesser 30cm)\",\n        \"Bodenglut & Reisig zur Vortrocknung\",\n        \"[KERN] Erdfeuchte austreiben & Glutbett bilden\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"Unterirdische Wärmemasse und konvektive Hitzespeicherung\",\n        \"text\": \"Unterirdische Grubenmeiler minimieren den Wärmeverlust durch natürliche Erddämmung. Die nach unten verjüngte V-Geometrie bündelt die aufsteigende Wärmekonvektion im Meilerkern und hält die anaerobe Backtemperatur **über 3 Stunden** stabil **über 400°C**.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Schritt 2: Armdicke Eichenscheite vertikal lückenlos stapeln\",\n      \"description\": \"1. **Eichenscheite vertikal aufstellen**: Stellen Sie trockene Hartholzscheite von **30–40cm Länge und 5–8cm Dicke** senkrecht auf die Bodenglut.\\n2. **Radiale Packungsdichte maximieren**: Schichten Sie die Scheite von innen nach außen **nahezu lückenlos** aneinander.\\n3. **Astkeile eintreiben**: Schlagen Sie **fingerdicke Zweige** als Keile in verbliebene Zwischenräume, um Sauerstoffnester zu beseitigen.\\n4. **Oberkante bündig prüfen**: Kontrollieren Sie, ob die Oberseite des Holzstapels **plan mit dem Grubenrand** abschließt.\",\n      \"actionNote\": \"> Stapel-Geheimnis: Der Meilerraum muss so dicht gefüllt sein, dass kaum Hohlräume verbleiben. Je dichter gepackt, desto härter die Holzkohle.\",\n      \"svgFileName\": \"pr09-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // DENSE VERTICAL TIMBER STACK\",\n        \"Eichenscheite (5-8cm) senkrecht gestapelt\",\n        \"Dünne Keilzweige füllen Zwischenräume\",\n        \"Aufsteigende Hitze vom Bodenglutbett\",\n        \"[KERN] Hohlräume minimieren für maximale Dichte\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PYROLYSIS\",\n        \"title\": \"Dichte Schichtung und anaerobe Pyrolyse-Mechanik\",\n        \"text\": \"Das Beseitigen von Luftlücken verbraucht den Restsauerstoff rasch und stoppt die offene Verbrennung. Die intensive Hitze treibt Feuchtigkeit und flüchtige Teere aus, sodass ein widerstandsfähiges Gitter aus **amorphem Kohlenstoff** entsteht, das dichte Stückkohle liefert.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Schritt 3: Astgitter auflegen & 95% Luft mit Lehm und Soden drosseln\",\n      \"description\": \"1. **Astgitter-Trägerstruktur errichten**: Legen Sie dicke grüne Äste im **Kreuzgitter** über die Scheite, um die Last der Lehmdecke zu tragen.\\n2. **Blätter-Sperrschicht auflegen**: Breiten Sie dichte Blätter und Gras über dem Gitter aus, damit keine feuchte Erde in den Meiler rieselt.\\n3. **10cm Lehm- und Rasensodenschicht**: Tragen Sie feuchten Lehm und Grassoden in **10cm Stärke** auf und riegeln Sie **95% des Luftstroms** ab.\\n4. **Zuluft- und Kaminlöcher stechen**: Bohren Sie windseitig am Boden **zwei fingerdicke Zuluftlöcher** und mittig **einen faustgroßen Kamin**.\",\n      \"actionNote\": \"> Dichtheitsprüfung: Tritt Rauch aus Rissen im Lehm aus, verschmieren Sie diese sofort mit feuchtem Lehm, um offenes Aufflammen zu verhindern.\",\n      \"svgFileName\": \"pr09-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // MULTI-LAYER ANAEROBIC SEAL\",\n        \"Astgitter & Blätter-Stützschicht\",\n        \"10cm Lehm- & Rasensoden-Dämmschicht\",\n        \"2 Zuluftöffnungen (fingerdick)\",\n        \"Zentraler Rauchkamin (faustgroß)\",\n        \"[KERN] Unvollständige Verbrennung bei 95% Luftmangel\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Schritt 4: Rauchfarbe bestimmen, hermetisch verschließen & kühlen\",\n      \"description\": \"1. **Dichten weißen Dampf beobachten**: In den ersten **1–2 Stunden** entweicht dichter weißer Dampf aus dem Kamin, während die innere Feuchtigkeit kocht.\\n2. **Feinen Blaurauch erkennen**: Sobald der Rauch nach **2–3 Stunden** in einen **zarten, bläulichen Dunst** übergeht, ist die Pyrolyse abgeschlossen.\\n3. **100% Lehmversiegelung**: Verschließen Sie Kamin und Zuluftlöcher sofort mit zähen Lehmkugeln, um **jeden Sauerstoffzutritt zu stoppen**.\\n4. **6 Stunden abkühlen und ernten**: Lassen Sie den Meiler **mindestens 6 Stunden** abkühlen, bis die Erde völlig handkalt ist, bevor Sie die klingende Kohle bergen.\",\n      \"actionNote\": \"> Verpuffungsgefahr (Backdraft): Öffnet man einen heißen Meiler vorzeitig, strömt Sauerstoff ein und erzeugt eine explosive Stichflamme, die die Kohle in Sekunden zu Asche verbrennt. Vollständig abkühlen lassen.\",\n      \"svgFileName\": \"pr09-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // SMOKE PHASE & CHARCOAL HARVEST\",\n        \"Phase 1: Dichter weißer Dampf (Wasser)\",\n        \"Phase 2: Zarter Blaurauch (Pyrolyse fertig)\",\n        \"Alle Öffnungen mit Lehm dicht verschlossen\",\n        \"Metallisch klingende Hartholzkohle ernten\",\n        \"[KERN] Bei Blaurauch sofort abdichten & abkühlen\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"Verpuffungsschutz und langsame thermische Stabilisierung\",\n        \"text\": \"Nach Abschluss der Verkohlung ist die Meilerkammer sauerstofffrei und extrem heiß. Ein plötzlicher Lufteintritt entzündet heiße Holzgase explosionsartig (Backdraft). Durch vollständiges Abdichten und langsames Abkühlen über **mehr als 6 Stunden** stabilisiert sich der Kohlenstoffkörper verlustfrei.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Fataler Fehler: Meiler im heißen Zustand öffnen oder Kaminversiegelung versäumen\",\n    \"description\": \"Das Freilegen der Grube bei über 400°C führt durch plötzlichen Sauerstoffeinstrom zu einer massiven Verpuffung. Bleiben die Schlitze bei Blaurauch offen, brennt die gesamte Kohle zu Asche ab.\",\n    \"consequence\": \"Konsequenz: Totalverlust der gesamten Ausbeute und schwere Brandverletzungen\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Lagerfeuer hinterlassen nur nutzlose Asche! So brennt man hochwertige Hartholzkohle unter der Erde!\",\n    \"body\": \"Schichten Sie Eichenholz senkrecht in eine 50cm Grube und dichten Sie sie mit Lehm ab, um 95% Sauerstoff zu blockieren! Nach 3 Stunden weißem Dampf kündigt feiner Blaurauch fertige Kohle an. Verschließen Sie alle Löcher mit Lehm und lassen Sie ihn erkalten. Sie erhalten dichte Kohle mit Metallklang für 500 Grad Hitze!\",\n    \"outro\": \"Offline-Überlebenspläne finden Sie über den Link im Profil.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr09-outcome.svg\",\n    \"title\": \"Querschnitt des Erdgrubenmeilers & Holzkohle-Kenndaten\",\n    \"description\": \"Technische Schnittdarstellung des anaeroben 50cm Erdmeilers mit 95% Luftdrosselung zur Gewinnung poröser Eichenholzkohle für rauchfreie Hitze und Trinkwasserfilterung.\"\n  },\n  \"createdAt\": \"2026-10-15T05:30:00.000Z\",\n  \"contentHash\": \"916099d408d4f948\",\n  \"updatedAt\": \"2026-10-15T14:41:20+09:00\"\n}","content/protocols/locales/09-pit-charcoal-kiln.en.json":"{\n  \"protocolId\": \"PR-09\",\n  \"category\": \"FIRE\",\n  \"title\": \"How to Make Hardwood Charcoal in an Underground Pit Kiln\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[SMOKELESS FUEL & CARBON FILTER]\",\n  \"summary\": \"Burning wood in an open campfire wastes fuel by turning it completely into useless white ash. By digging a 50cm cone-shaped pit, packing hardwood tightly, and sealing it with earth and turf sod to block 95% of incoming oxygen, the timber is pyrolyzed rather than combusted. This produces dense, metallic-ringing lump charcoal that burns smokeless at 500°C, purifies contaminated water, and preserves embers for days.\",\n  \"timeRequired\": \"5 hours (1h pit digging & wood packing + 3h pyrolysis + 1h sealed cooling)\",\n  \"successRate\": \"90% (strict compliance with anaerobic seal & cooling)\",\n  \"difficulty\": \"Moderate (identifying smoke transition phases)\",\n  \"outputPerHour\": \"3-5kg premium lump charcoal per batch\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"15-20 wrist-thick dry oak or hardwood billets (30-40cm length)\",\n      \"desc\": \"Dense hardwoods such as oak, maple, or hickory that pyrolyze without combusting, yielding long-burning, high-temperature charcoal.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Cone-shaped earthen pit (50cm depth, 60cm top diameter)\",\n      \"desc\": \"Tapered downward to concentrate internal radiant heat and control anaerobic airflow circulation.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Stout branch lattice frame & broad leaves\",\n      \"desc\": \"Placed horizontally across the timber stack to support the heavy mud mound and prevent loose soil from caving in.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Moist clay mud & grass turf sod (10cm thickness)\",\n      \"desc\": \"Forms an airtight thermal blanket over the kiln, restricting oxygen by 95% and baking the wood above 400°C.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"Dry kindling & starter ember bed\",\n      \"desc\": \"Completely bakes out pit wall dampness and ignites the bottom of the packed timber bundle.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Step 1: Dig a 50cm Cone Pit & Establish a Starter Ember Bed\",\n      \"description\": \"1. **Excavate Cone-Shaped Pit**: Dig a pit **60cm wide at the top** and **50cm deep** in dry, solid ground away from pooling rainwater.\\n2. **Shape Tapered Base**: Taper the pit walls downward to a **30cm base diameter** to concentrate internal thermal convection toward the center.\\n3. **Bake Out Residual Moisture**: Build an active fire with dry twigs and dead leaves at the bottom for **over 15 minutes** to dry the clay walls bone-dry.\\n4. **Establish Glowing Ember Bed**: Ensure the open flames subside into a thick, **glowing red coal bed** across the entire floor.\",\n      \"actionNote\": \"> Digging Insight: If residual soil moisture remains in the pit, the wood will steam, rot, and extinguish. Heat the base thoroughly until bone dry.\",\n      \"svgFileName\": \"pr09-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PIT EXCAVATION & PRE-DRYING\",\n        \"Top Opening 60cm Diameter Cone Pit\",\n        \"Depth 50cm (Base Diameter 30cm)\",\n        \"Base Pre-Drying Kindling & Ember Bed\",\n        \"[KEY] Fully bake out soil moisture for high heat\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"Subterranean Thermal Mass and Convective Heat Retention\",\n        \"text\": \"Subterranean pit kilns reduce ambient heat loss through earth insulation. The tapered V-shaped geometry focuses rising convection currents into the kiln core, maintaining steady anaerobic baking temperatures **above 400°C** for **over 3 hours**.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Step 2: Pack Wrist-Thick Oak Billets Vertically with Zero Gaps\",\n      \"description\": \"1. **Vertical Timber Placement**: Stand dry hardwood billets of **length 30–40cm and thickness 5–8cm** upright directly onto the base embers.\\n2. **Radial Packing Density**: Pack additional oak billets tightly from the center outward, leaving **virtually zero air voids**.\\n3. **Crevice Wedge Locking**: Drive **finger-thick branches** into remaining gaps as wooden wedges to eliminate trapped oxygen pockets.\\n4. **Level Top Edge Verification**: Inspect the top surface of the timber stack to ensure it sits **flush with the ground rim**.\",\n      \"actionNote\": \"> Stacking Secret: The kiln chamber must be packed solid with almost no breathing room. Maximum density yields dense, metallic-sounding charcoal.\",\n      \"svgFileName\": \"pr09-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // DENSE VERTICAL TIMBER STACK\",\n        \"Wrist-Thick (5-8cm) Oak Vertical Stack\",\n        \"Slender Wedges Filling Every Crevice\",\n        \"Heat Spreading from Bottom Embers\",\n        \"[KEY] Minimize air voids for pure anaerobic density\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PYROLYSIS\",\n        \"title\": \"Dense Stacking and Anaerobic Pyrolysis Mechanics\",\n        \"text\": \"Minimizing air gaps causes initial oxygen to deplete rapidly, arresting open-flame combustion. Intense ambient heat drives off bound moisture and volatile wood tars, leaving behind a resilient, crystallized **amorphous carbon** matrix that yields dense lump charcoal.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Step 3: Lay Branch Lattice & Seal 95% Oxygen with Mud and Turf Sod\",\n      \"description\": \"1. **Erect Branch Lattice Frame**: Lay thick green poles across the top of the vertical billets in a **criss-cross grid** to bear the ceiling load.\\n2. **Layer Leaf Barrier**: Shingle broad leaves and dense grass across the lattice to prevent wet dirt from tumbling into the kiln.\\n3. **Apply 10cm Clay and Turf Cap**: Pack moist mud and inverted sod to a **thickness of 10cm**, sealing **95% of incoming airflow**.\\n4. **Puncture Intake and Exhaust Vents**: Pierce **two finger-thick intake vents** at ground level on the windward side and **one fist-sized center chimney**.\",\n      \"actionNote\": \"> Seal Check: If smoke leaks through hairline cracks in the mud mound, immediately slap fresh wet clay over them to stop open flame combustion.\",\n      \"svgFileName\": \"pr09-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // MULTI-LAYER ANAEROBIC SEAL\",\n        \"Branch Lattice & Leaf Support Layer\",\n        \"10cm Moist Mud & Turf Sod Blanket\",\n        \"2 Base Intake Vents (Finger-Thick)\",\n        \"Center Exhaust Chimney (Fist-Sized)\",\n        \"[KEY] 95% oxygen starved incomplete combustion\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Step 4: Monitor Smoke Transition & Hermetically Seal for Cooling\",\n      \"description\": \"1. **Monitor Dense White Steam**: Observe thick white steam billowing from the chimney during the initial **1–2 hours** as interior moisture boils off.\\n2. **Detect Translucent Blue Smoke**: Watch for the smoke transitioning to a **faint translucent blue haze** after **2–3 hours**, signalling complete carbonization.\\n3. **100% Hermetic Clay Seal**: Immediately plug the chimney and both intake vents with stiff clay balls to **halt all oxygen transfer**.\\n4. **6-Hour Slow Cooling and Harvest**: Allow the kiln to slow-cool for **at least 6 hours** until cold to the touch before gently uncovering metallic-ringing lump charcoal.\",\n      \"actionNote\": \"> Kiln Flare-up (Backdraft) Warning: Opening a hot kiln rushes fresh oxygen inside, creating an explosive backdraft fireball that burns your charcoal to ash in seconds. Let the soil turn completely cold to the touch before unearthing.\",\n      \"svgFileName\": \"pr09-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // SMOKE PHASE & CHARCOAL HARVEST\",\n        \"Phase 1: Dense White Steam (Water Evaporation)\",\n        \"Phase 2: Faint Blue Haze (Pyrolysis Done)\",\n        \"Hermetically Seal All Vents & Cool Completely\",\n        \"Harvest Metallic-Ringing Dense Hardwood Charcoal\",\n        \"[KEY] Seal on blue smoke & cool fully to touch\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"Backdraft Prevention and Slow-Cooling Carbon Stabilization\",\n        \"text\": \"Upon carbonization completion, the kiln chamber is an oxygen-depleted thermal reservoir. An abrupt breach draws in fresh air, triggering rapid combustion of superheated wood gases (backdraft). Hermetically capping vents and slow-cooling for **over 6 hours** stabilizes the high-density carbon structure without ash loss.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Fatal Mistake: Opening the mound while hot or forgetting to seal the vents\",\n    \"description\": \"Cracking open a kiln above 400°C draws in massive volumes of fresh oxygen, creating an explosive backdraft fireball. Leaving vents unsealed when blue smoke appears allows the charcoal to catch fire and burn away into useless ash.\",\n    \"consequence\": \"Consequence: Complete loss of your fuel yield and severe burn hazards\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Burning wood in an open fire leaves only white ash! Here is how to bake metallic charcoal underground!\",\n    \"body\": \"Pack oak branches vertically into a 50cm pit and seal it under clay and sod to choke out 95% of oxygen! When thick white steam turns into faint blue smoke after 3 hours, plug every vent with mud. Once cool, you will harvest dense, metallic-sounding charcoal that burns smokeless at 500 degrees!\",\n    \"outro\": \"Tap the link in our profile for full offline survival blueprints.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr09-outcome.svg\",\n    \"title\": \"Completed Underground Pit Charcoal Kiln & Lump Charcoal Specs\",\n    \"description\": \"Cross-sectional engineering view of the 50cm underground cone kiln operating at 95% oxygen restriction, yielding dense porous hardwood charcoal ideal for smokeless high heat and emergency water filtration.\"\n  },\n  \"createdAt\": \"2026-10-15T05:30:00.000Z\",\n  \"contentHash\": \"916099d408d4f948\",\n  \"updatedAt\": \"2026-10-15T14:41:20+09:00\"\n}","content/protocols/locales/09-pit-charcoal-kiln.es.json":"{\n  \"protocolId\": \"PR-09\",\n  \"category\": \"FIRE\",\n  \"title\": \"Cómo hacer carbón vegetal en un horno de pozo subterráneo sin oxígeno\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[COMBUSTIBLE SIN HUMO Y FILTRO DE CARBONO]\",\n  \"summary\": \"Quemar leña en una fogata abierta la convierte por completo en ceniza blanca inútil debido al exceso de oxígeno. Al cavar un pozo cónico de 50 cm, apilar troncos de roble apretados verticalmente y sellarlo con barro y tepes de hierba para bloquear el 95% del aire, la madera se piroliza en lugar de arder. Esto genera carbón duro y denso que suena a metal, arde a 500 °C sin humo, purifica agua y conserva ascuas durante días.\",\n  \"timeRequired\": \"5 horas (1h excavación y carga + 3h pirólisis + 1h enfriamiento hermético)\",\n  \"successRate\": \"90% (cumpliendo el sellado anaeróbico y enfriamiento)\",\n  \"difficulty\": \"Media (requiere reconocer el cambio de color del humo)\",\n  \"outputPerHour\": \"3 a 5 kg de carbón vegetal duro por hornada\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"15-20 leños secos de roble del grosor de la muñeca (longitud 30-40 cm)\",\n      \"desc\": \"Maderas duras de alta densidad que se carbonizan sin consumirse en llamas, produciendo carbón duradero de alto poder calorífico.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Pozo cónico de tierra (50 cm de profundidad, 60 cm de diámetro superior)\",\n      \"desc\": \"Excavado con conicidad hacia abajo para concentrar el calor radiante y controlar el flujo de aire anaeróbico.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Enrejado de ramas gruesas y hojas anchas\",\n      \"desc\": \"Estructura colocada sobre los troncos para soportar la cubierta de lodo e impedir que la tierra caiga dentro del horno.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Barro arcilloso húmedo y tepes de césped (10 cm de espesor)\",\n      \"desc\": \"Capa aislante que sella el pozo, bloquea el 95% del oxígeno y hornea la madera a más de 400 °C.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"Ramas secas y cama de brasas inicial\",\n      \"desc\": \"Seca por completo la humedad del suelo y enciende la base del lote de troncos apilados.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Paso 1: Excavar el pozo cónico de 50 cm y crear la cama de brasas\",\n      \"description\": \"1. **Excavación del pozo cónico**: Elija suelo firme y seco y excave un pozo de **60cm de boca superior y 50cm de profundidad**.\\n2. **Perfilado cónico inferior**: Reduzca las paredes hacia una base de **30cm de diámetro** para concentrar la convección térmica central.\\n3. **Secado de humedad residual**: Encienda un fuego vivo con ramas secas durante **más de 15 minutos** para secar las paredes de arcilla por completo.\\n4. **Formación de cama de brasas**: Asegúrese de que las llamas abiertas decanten en una gruesa **capa de brasas al rojo vivo** sobre el fondo.\",\n      \"actionNote\": \"> Consejo de excavación: Si queda humedad en la tierra, la madera se pudrirá y el fuego se apagará. Caliente el fondo hasta secarlo por completo.\",\n      \"svgFileName\": \"pr09-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PIT EXCAVATION & PRE-DRYING\",\n        \"Pozo cónico de 60cm de boca superior\",\n        \"Profundidad 50cm (base de 30cm)\",\n        \"Brasas base para secar la tierra\",\n        \"[CLAVE] Secar humedad del suelo y crear brasas\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"Masa térmica subterránea y retención de calor convectivo\",\n        \"text\": \"Los hornos de pozo subterráneos reducen la pérdida de calor al exterior gracias al aislamiento natural de la tierra. Su geometría cónica en V enfoca las corrientes térmicas en el núcleo, manteniendo temperaturas de horneado anaeróbico **superiores a 400°C** durante **más de 3 horas**.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Paso 2: Apilar los leños de roble verticalmente sin dejar huecos\",\n      \"description\": \"1. **Colocación vertical de leños**: Plante leños secos de roble de **longitud 30–40cm y grosor 5–8cm** verticalmente sobre las brasas base.\\n2. **Densidad de carga radial**: Apile los leños apretadamente desde el centro hacia los bordes, dejando **prácticamente cero huecos de aire**.\\n3. **Acuñado de hendiduras**: Inserte **ramas del grosor de un dedo** a modo de cuñas en las ranuras restantes para eliminar bolsas de oxígeno.\\n4. **Inspección de nivel superior**: Verifique que la parte superior de la madera quede **a ras del borde del suelo**.\",\n      \"actionNote\": \"> Secreto de carga: El interior debe quedar tan denso que casi no haya espacio libre. Cuanta más densidad, más duro y sonoro será el carbón.\",\n      \"svgFileName\": \"pr09-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // DENSE VERTICAL TIMBER STACK\",\n        \"Leños de roble (5-8cm) en pila vertical\",\n        \"Ramas finas acuñadas en los huecos\",\n        \"Calor ascendente desde las brasas base\",\n        \"[CLAVE] Minimizar huecos para máxima densidad\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PYROLYSIS\",\n        \"title\": \"Apilado denso y mecánica de pirólisis anaeróbica\",\n        \"text\": \"Minimizar los huecos de aire agota rápidamente el oxígeno interno y frena la combustión abierta. El intenso calor ambiental evapora la humedad y los alquitranes volátiles, cristalizando una resistente matriz de **carbono amorfo** que produce carbón vegetal de alta densidad.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Paso 3: Colocar el enrejado de ramas y sellar el 95% del aire con barro\",\n      \"description\": \"1. **Estructura en rejilla de ramas**: Tienda ramas gruesas en **patrón cruzado de cuadrícula** sobre los leños para soportar el peso de la cubierta.\\n2. **Barrera vegetal de hojas**: Disponga hojas anchas y hierba tupida sobre el enrejado para impedir que la tierra húmeda caiga al interior.\\n3. **Capa de 10cm de arcilla y tepes**: Aplique barro húmedo y tepes invertidos con un **grosor de 10cm**, bloqueando el **95% de la entrada de aire**.\\n4. **Apertura de tomas y chimenea**: Perfore **dos respiraderos del grosor de un dedo** a nivel del suelo a favor del viento y **una chimenea central del tamaño de un puño**.\",\n      \"actionNote\": \"> Control de sellado: Si sale humo por grietas en la cúpula de barro, tápelas de inmediato con barro fresco para evitar que prenda fuego abierto.\",\n      \"svgFileName\": \"pr09-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // MULTI-LAYER ANAEROBIC SEAL\",\n        \"Enrejado de ramas y lecho de hojas\",\n        \"Cubierta de 10cm de barro y tepes\",\n        \"2 tomas de aire base (grosor de dedo)\",\n        \"Chimenea central de tiro (puño)\",\n        \"[CLAVE] Combustión incompleta sin 95% de oxígeno\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Paso 4: Distinguir el color del humo, sellar y enfriar antes de cosechar\",\n      \"description\": \"1. **Monitoreo de vapor blanco denso**: Observe el vapor blanco denso que brota de la chimenea durante las primeras **1–2 horas** al evaporarse la humedad interna.\\n2. **Detección de humo azul tenue**: Identifique la transición hacia un **humo azul pálido y translúcido** tras **2–3 horas**, indicio de carbonización completa.\\n3. **Sellado hermético total con barro**: Tape de inmediato la chimenea y las dos tomas de aire con bolas de barro fresco para **cortar todo flujo de aire**.\\n4. **Enfriamiento lento de 6 horas y cosecha**: Deje enfriar el pozo durante **al menos 6 horas** hasta que el suelo esté completamente frío al tacto antes de desenterrar el carbón sonoro.\",\n      \"actionNote\": \"> Alerta de explosión por retroceso (Backdraft): Abrir un horno aún caliente provoca una violenta entrada de oxígeno que desencadena una explosión de fuego, reduciendo el carbón a cenizas en segundos. Deje enfriar por completo.\",\n      \"svgFileName\": \"pr09-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // SMOKE PHASE & CHARCOAL HARVEST\",\n        \"Fase 1: Humo blanco denso (vapor de agua)\",\n        \"Fase 2: Humo azul tenue (pirólisis lista)\",\n        \"Sellado hermético total y enfriamiento\",\n        \"Cosecha de carbón duro con sonido metálico\",\n        \"[CLAVE] Sellar con humo azul y enfriar del todo\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"Prevención de llamarada explosiva y estabilización lenta\",\n        \"text\": \"Al completarse la carbonización, la cámara del horno es un reservorio térmico sin oxígeno. Una apertura abrupta aspira aire fresco e inflama los gases calientes (retroceso de llama). Sellar herméticamente y enfriar lentamente durante **más de 6 horas** estabiliza la estructura de carbono sin pérdidas.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Error fatal: Abrir el pozo mientras sigue caliente o no sellar las salidas a tiempo\",\n    \"description\": \"Abrir el horno a más de 400 °C provoca una entrada violenta de oxígeno que desata una explosión de fuego instantánea. Dejar los respiraderos abiertos tras la aparición del humo azul quemará todo el carbón hasta volverlo ceniza.\",\n    \"consequence\": \"Consecuencia: Pérdida total de la cosecha y riesgo grave de quemaduras\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"¡Quemar leña al aire libre solo deja ceniza blanca! ¡Aprende a fabricar carbón metálico bajo tierra!\",\n    \"body\": \"¡Coloca troncos de roble apretados en un pozo de 50 cm y tápalos con barro para bloquear el 95% del aire! Al principio saldrá humo blanco espeso, pero cuando se vuelva azul tenue a las 3 horas, tapa todos los agujeros con lodo. ¡Una vez frío, obtendrás carbón duro con timbre metálico que arde sin humo a 500 grados!\",\n    \"outro\": \"Planos completos de supervivencia sin conexión en el enlace de nuestro perfil.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr09-outcome.svg\",\n    \"title\": \"Corte transversal del horno de pozo y especificaciones del carbón\",\n    \"description\": \"Vista técnica del horno subterráneo cónico operando con restricción de oxígeno al 95%, produciendo carbón vegetal poroso de roble ideal para calor sin humo y purificación de agua.\"\n  },\n  \"createdAt\": \"2026-10-15T05:30:00.000Z\",\n  \"contentHash\": \"916099d408d4f948\",\n  \"updatedAt\": \"2026-10-15T14:41:20+09:00\"\n}","content/protocols/locales/09-pit-charcoal-kiln.ja.json":"{\n  \"protocolId\": \"PR-09\",\n  \"category\": \"FIRE\",\n  \"title\": \"土穴で空気を遮断して木材を高硬度な炭に焼き上げる方法（原始木炭窯）\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[無煙高熱燃料 & 浄水フィルター木炭確保]\",\n  \"summary\": \"焚き火で木をそのまま燃やすと酸素と完全反応して白い灰しか残りません。地面に深さ50cmの円錐形の穴を掘り、ナラなどの広葉樹を隙間なく垂直に立て並べ、泥と芝生で覆って空気の流入を95%遮断すると、木材は燃え上がらずに高温で蒸し焼きにされ、硬質な炭になります。煙を出さずに暖を取り、泥水の浄水ろ過材や火種保存に使える野外生存の黒い宝石です。\",\n  \"timeRequired\": \"5時間（穴掘り・薪配置1時間 ＋ 炭化3時間 ＋ 密閉冷却1時間）\",\n  \"successRate\": \"90%（空気遮断と冷却時間を厳守した場合）\",\n  \"difficulty\": \"普通（煙の色の変化を見極める技術が必要）\",\n  \"outputPerHour\": \"1回の稼働で高品質な硬質木炭3〜5kg収穫\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"手首ほどの太さの乾燥したナラ・カシの丸太15〜20本（長さ30〜40cm）\",\n      \"desc\": \"密度が高く硬い広葉樹を用意します。無酸素状態で燃え尽きずに炭化し、長持ちする高火力炭になります。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"深さ50cm・上部直径60cmの円錐形の土穴\",\n      \"desc\": \"下に向かって細くなる形状で熱を中心部に集中させ、空気の循環を制御する地下窯です。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"窯を覆う太い枝の格子枠と大きな広葉樹の葉\",\n      \"desc\": \"立てた丸太の上に渡し、泥が崩れ落ちないよう支える骨組みと土砂混入防止用の葉です。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"湿った粘土質の泥と芝生のターフ（厚さ10cm）\",\n      \"desc\": \"窯の上部を完全に覆って空気（酸素）の流入を95%遮断し、内部を400℃以上の高熱で蒸し焼きにする断熱蓋です。\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"下地乾燥用の小枝と熾火の種火\",\n      \"desc\": \"土穴の壁や底の湿気をしっかり飛ばし、丸太の下部に火を回すための点火材です。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"第1段階: 深さ50cmの円錐穴の掘削と底部の熾火作り\",\n      \"description\": \"1. **円錐形の土穴掘削**: 水がたまらない硬く乾いた地面を選び、**上部直径60cm、深さ50cm**の穴を掘ります。\\n2. **下部テーパー傾斜加工**: 下に向かうにつれて直径が**30cm**ほどに狭まる円錐形に整え、熱気を中央へ集中させます。\\n3. **底部の湿気乾燥**: 底に乾いた小枝や落ち葉を敷いて火を起こし、穴の湿気を**15分以上**しっかり焼き飛ばします。\\n4. **真っ赤な熾火層の形成**: 炎が落ち着き、底一面に**赤く輝く熾火の層**が均一に形成されたか確認します。\",\n      \"actionNote\": \"> 掘削のコツ: 底に湿気が残っていると蒸し焼きにならず腐敗臭がして火が消えてしまいます。土が乾燥するまでしっかり熾火で熱してください。\",\n      \"svgFileName\": \"pr09-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PIT EXCAVATION & PRE-DRYING\",\n        \"上部直径60cm 円錐形土穴掘削\",\n        \"深さ50cm（底部直径30cm）\",\n        \"底部乾燥用小枝 ＆ 熾火の種火\",\n        \"[核心] 土の湿気を完全乾燥させ高温火種を形成\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"円錐形土穴の蓄熱と地中断熱保温\",\n        \"text\": \"地下の土穴は外気への熱損失が極めて少なく、優れた地中断熱効果を発揮します。下部が狭まる円錐（V字）構造が熱対流を中央へ集約し、**400℃以上**の高温蓄熱状態を**3時間以上**安定して維持します。\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"第2段階: 手首太さのナラ材を隙間なく垂直に敷き詰める\",\n      \"description\": \"1. **ナラ丸太の垂直配置**: 底の熾火の上に、**長さ30〜40cm、太さ5〜8cm**の乾燥ナラ材を柱のようにまっすぐ立てます。\\n2. **放射状の高密度積載**: 中央から外側に向かって、ナラ材を**隙間なくぎっしり**敷き詰めます。\\n3. **小枝くさびの充填**: 丸太同士の残った隙間に**指ほどの小枝**をくさび状に打ち込み、空気溜まりを徹底的に排除します。\\n4. **上部水平面の点検**: 立てた木材の上端が地面の縁と**水平に揃っているか**確認します。\",\n      \"actionNote\": \"> 積み方の秘訣: 窯の中は木でぎっしり詰まり、空気の抜ける隙間がほとんどない状態にしてください。密度が高いほど金属音が鳴る最高級の炭になります。\",\n      \"svgFileName\": \"pr09-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // DENSE VERTICAL TIMBER STACK\",\n        \"手首太さ（5〜8cm）ナラ材の垂直積載\",\n        \"隙間をくさび状に埋めた小枝\",\n        \"底部熾火から立ち上る熱気\",\n        \"[核心] 隙間を最小化し無酸素炭化の密度を極大化\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PYROLYSIS\",\n        \"title\": \"垂直高密度積載と酸素遮断熱分解の原理\",\n        \"text\": \"薪の間の隙間を極限まで減らすことで内部酸素が早期に枯渇し、有炎燃焼が停止します。その後、外部の高熱により水分と木酢液・タール成分のみが気化排出され、純粋な**炭素（Carbon）**骨格だけが結晶化して硬質な木炭となります。\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"第3段階: 枝の枠組みを載せ泥と芝生で酸素を95%遮断する\",\n      \"description\": \"1. **枝の格子支持枠の設置**: 垂直な丸太の上に太い枝を**井桁（格子状）**に渡し、上部土蓋の荷重を受け止めます。\\n2. **広葉樹葉の遮断層**: 骨組みの上に幅広の葉や草を隙間なく敷き、泥が内部へ落ち込むのを防ぎます。\\n3. **泥と芝生を10cm塗布**: 湿った粘土泥と芝生ターフを**厚さ10cm**で塗り固め、空気の流入を**95%遮断**します。\\n4. **吸気孔と排気煙突の穿孔**: 風上側の地面際に**指太さの吸気穴2箇所**を開け、中央天頂部に**拳大の煙突1箇所**を残します。\",\n      \"actionNote\": \"> 密閉の確認: 煙突以外から煙が漏れている隙間があれば、すぐに泥を追加して塞ぎ、木が勢いよく燃え上がるのを防ぎます。\",\n      \"svgFileName\": \"pr09-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // MULTI-LAYER ANAEROBIC SEAL\",\n        \"枝格子枠 ＋ 広葉樹葉の支持層\",\n        \"10cm 湿潤泥 ＆ 芝生ターフ蓋\",\n        \"下部吸気穴2箇所（指の太さ）\",\n        \"中央排気煙突（拳大）\",\n        \"[核心] 酸素95%遮断の不完全燃焼窯が完成\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"第4段階: 煙の色の変化を識別し完全密閉冷却後に木炭を収穫\",\n      \"description\": \"1. **濃い白煙の排出確認**: 着火初期の**1〜2時間**は煙突から水分が蒸発して立ち上る濃い白煙を観察します。\\n2. **青煙への転移感知**: 点火から**2〜3時間**後、煙が**澄んだ淡い青色**へ変化したのを確認して炭化完了を判断します。\\n3. **通気孔の100%泥密閉**: 青煙を確認したら即座に泥団子で煙突と吸気穴を**100%隙間なく密閉**して空気を遮断します。\\n4. **6時間徐冷後に木炭収穫**: 窯の外壁が完全に冷えるまで**最低6時間**待った後、土を取り除いて銀色に輝く硬質木炭を取り出します。\",\n      \"actionNote\": \"> バックドラフト（逆火）警戒: 窯の中がまだ熱い時に掘り起こすと、新鮮な空気が一気に流入して爆発的に炎上し、炭が灰に変わってしまいます。必ず土が完全に冷え切ってから開けてください。\",\n      \"svgFileName\": \"pr09-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // SMOKE PHASE & CHARCOAL HARVEST\",\n        \"第1段階: 濃い白煙（水分蒸発）\",\n        \"第2段階: 淡い青煙（炭化完了）\",\n        \"全通気孔を泥で完全密閉し冷却\",\n        \"澄んだ金属音のする高密度ナラ炭を収穫\",\n        \"[核心] 青煙で即座に密閉し余熱を完全冷却\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"バックドラフト防止と徐冷（Slow Cooling）安定化\",\n        \"text\": \"炭化完了直後の窯内は酸素が枯渇した超高温状態です。この状態で急激に外気が入ると残留可燃ガスが爆発的に炎上（バックドラフト）し、木炭が一瞬で灰に酸化します。通気孔を完全密閉して**6時間以上**ゆっくり冷ますことで高密度炭素体が安定化します。\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命的な失敗: 熱が残っている状態で焦って蓋を開けること、または密閉忘れ\",\n    \"description\": \"窯の内部が400℃以上に達している状態で土を取り除くと、外気の酸素が一気に吸い込まれてバックドラフト（爆発的燃焼）が起こり炎上します。また青煙が出た時に穴を塞がずに放置すると木材全体が灰に酸化してしまいます。\",\n    \"consequence\": \"結果: 何時間もかけて焼いた木が一瞬で灰に消え、重度の火傷を負う危険\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"焚き火で木を燃やすと白い灰しか残りません！土に埋めて金属音の鳴る極上炭を焼く裏技！\",\n    \"body\": \"土穴にナラの木をぎっしり立て、泥と芝生で覆って酸素を95%遮断してください！最初は濃い白煙が出ますが、3時間後に透き通った青い煙に変わったら炭化完了のサイン。すべての穴を泥で塞いで完全に冷ませば、煙を出さずに500℃の熱を出す最高のサバイバル炭が完成します！\",\n    \"outro\": \"通信が途絶えたオフライン環境でも閲覧できるサバイバル図面はプロフィールのリンクから！\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr09-outcome.svg\",\n    \"title\": \"完成した原始地下木炭窯の断面及び多孔質木炭の諸元\",\n    \"description\": \"深さ50cmの円錐形土穴で酸素を95%遮断して高温蒸し焼きにし、無煙高熱燃料や飲料水ろ過フィルターとして使用可能な硬質多孔質ナラ炭の完成断面図です。\"\n  },\n  \"createdAt\": \"2026-10-15T05:30:00.000Z\",\n  \"contentHash\": \"916099d408d4f948\",\n  \"updatedAt\": \"2026-10-15T14:41:20+09:00\"\n}","content/protocols/locales/09-pit-charcoal-kiln.pt.json":"{\n  \"protocolId\": \"PR-09\",\n  \"category\": \"FIRE\",\n  \"title\": \"Como fazer carvão vegetal denso em trincheira de terra sem oxigênio\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[COMBUSTÍVEL SEM FUMAÇA E FILTRO DE CARBONO]\",\n  \"summary\": \"Queimar lenha em fogueira aberta consome a madeira por completo, deixando apenas cinzas brancas inúteis. Ao cavar uma vala cônica de 50 cm, empilhar toras de carvalho verticalmente e vedar tudo com barro e placas de grama para cortar 95% do oxigênio, a madeira passa por pirólise em vez de combustão. Isso produz carvão vegetal maciço de som metálico, que queima a 500 °C sem fumaça e filtra água barrenta.\",\n  \"timeRequired\": \"5 horas (1h escavação e carga + 3h pirólise + 1h resfriamento vedado)\",\n  \"successRate\": \"90% (cumprindo a vedação anaeróbica e tempo de resfriamento)\",\n  \"difficulty\": \"Médio (requer identificar a mudança na cor da fumaça)\",\n  \"outputPerHour\": \"3 a 5 kg de carvão vegetal de alta dureza por fornada\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"15-20 toretes secos de carvalho na grossura do punho (30-40 cm de comprimento)\",\n      \"desc\": \"Madeiras nobres de alta densidade que se carbonizam sem queimar em chamas abertas, gerando brasas duradouras.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Buraco cônico de terra (50 cm de profundidade, 60 cm de boca superior)\",\n      \"desc\": \"Escavado com afunilamento para o fundo para concentrar o calor e controlar a circulação de ar.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Grade de galhos grossos e folhas largas\",\n      \"desc\": \"Estrutura colocada sobre a lenha para sustentar a tampa de argila e evitar deslizamento de terra.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Barro argiloso úmido e placas de grama (10 cm de espessura)\",\n      \"desc\": \"Camada isolante que veda a vala, bloqueia 95% do oxigênio e assa a madeira a mais de 400 °C.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"Gravetos secos e leito de brasas inicial\",\n      \"desc\": \"Seca completamente a umidade das paredes de terra e acende a base da carga de madeira.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Passo 1: Cavar buraco cônico de 50 cm e fazer leito de brasas\",\n      \"description\": \"1. **Escavação da cova cônica**: Escolha solo seco e firme e escave uma cova de **60cm de largura no topo e 50cm de profundidade**.\\n2. **Perfilamento afunilado inferior**: Modele as paredes para uma base cônica de **30cm de diâmetro** para concentrar o calor no núcleo.\\n3. **Secagem de umidade residual**: Queime gravetos secos no fundo por **mais de 15 minutos** para secar as paredes de argila por completo.\\n4. **Formação de leito de brasas**: Garanta que as chamas abertas assentem numa espessa **camada de brasas incandescentes** no fundo.\",\n      \"actionNote\": \"> Dica de escavação: Se restar umidade no fundo, a madeira apodrecerá e o fogo se apagará. Aqueça a base até secar completamente.\",\n      \"svgFileName\": \"pr09-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PIT EXCAVATION & PRE-DRYING\",\n        \"Abertura superior de 60cm poço cônico\",\n        \"Profundidade 50cm (base de 30cm)\",\n        \"Brasas de fundo para secagem do solo\",\n        \"[CHAVE] Secar umidade da terra e formar brasas\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"Massa térmica subterrânea e retenção convectiva de calor\",\n        \"text\": \"Fornos subterrâneos reduzem a perda de calor para o ambiente através do isolamento térmico da terra. A geometria cônica em V concentra as correntes de convecção no centro, mantendo o cozimento anaeróbico **acima de 400°C** por **mais de 3 horas**.\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Passo 2: Empilhar toras de carvalho verticalmente sem frestas\",\n      \"description\": \"1. **Posicionamento vertical de toras**: Apoie toras secas de carvalho de **30–40cm de comprimento e 5–8cm de espessura** verticalmente sobre as brasas.\\n2. **Densidade de carga radial**: Preencha as toras firmemente do centro para fora, deixando **praticamente zero frestas de ar**.\\n3. **Cunhagem de vãos com gravetos**: Crave **galhos da grossura de um dedo** como cunhas nas frestas restantes para eliminar bolsas de oxigênio.\\n4. **Verificação de nível do topo**: Confira se o topo da carga de madeira está **nivelado com a borda do solo**.\",\n      \"actionNote\": \"> Segredo de empilhamento: O forno deve ficar tão compacto que quase não haja vazios. Quanto mais denso, mais resistente o carvão.\",\n      \"svgFileName\": \"pr09-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // DENSE VERTICAL TIMBER STACK\",\n        \"Toras de carvalho (5-8cm) em pé\",\n        \"Galhos finos cunhados nos vãos\",\n        \"Calor subindo das brasas da base\",\n        \"[CHAVE] Minimizar vazios para densidade anaeróbica\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PYROLYSIS\",\n        \"title\": \"Empilhamento denso e mecânica de pirólise anaeróbica\",\n        \"text\": \"Minimizar os vazios de ar consome o oxigênio interno rapidamente e interrompe a queima com chama aberta. O calor intenso evapora a umidade e alcatrões voláteis, consolidando uma matriz cristalina de **carbono amorfo** que forma o carvão vegetal denso.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Passo 3: Assentar grade de galhos e vedar 95% do ar com barro\",\n      \"description\": \"1. **Estrutura em grade de galhos**: Disponha galhos grossos em **padrão quadriculado cruzado** sobre as toras para suportar o peso da cobertura.\\n2. **Camada de barreira de folhas**: Espalhe folhas largas e capim denso sobre a grade para impedir que a terra caia no interior do forno.\\n3. **Aplicação de 10cm de argila e leivas**: Aplique barro úmido e placas de grama com **10cm de espessura**, bloqueando **95% do fluxo de ar**.\\n4. **Abertura de entradas e chaminé**: Abra **duas entradas de ar da grossura de um dedo** no solo a barlavento e **uma chaminé central do tamanho de um punho**.\",\n      \"actionNote\": \"> Checagem de vedação: Se sair fumaça por rachaduras no barro, tampe-as imediatamente com argila fresca para evitar chamas abertas.\",\n      \"svgFileName\": \"pr09-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // MULTI-LAYER ANAEROBIC SEAL\",\n        \"Grade de galhos e camada de folhas\",\n        \"Tampa de 10cm de argila e leivas\",\n        \"2 entradas de ar base (grossura de dedo)\",\n        \"Chaminé central de exaustão (punho)\",\n        \"[CHAVE] Combustão incompleta sem 95% de oxigênio\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Passo 4: Monitorar a cor da fumaça, lacrar e resfriar para colher\",\n      \"description\": \"1. **Monitoramento de vapor branco denso**: Observe o vapor branco denso expelido pela chaminé durante as primeiras **1–2 horas** conforme a umidade evapora.\\n2. **Identificação de fumaça azul tênue**: Note a transição para uma **fumaça azul clara e translúcida** após **2–3 horas**, indicando carbonização completa.\\n3. **Vedação hermética total com barro**: Vede imediatamente a chaminé e as entradas com bolas de argila úmida para **bloquear todo oxigênio**.\\n4. **Resfriamento lento de 6 horas e colheita**: Aguarde **ao menos 6 horas** até a terra esfriar totalmente ao toque antes de desenterrar o carvão metálico.\",\n      \"actionNote\": \"> Alerta de explosão por refluxo (Backdraft): Abrir o forno ainda quente provoca entrada brusca de oxigênio e detona uma labareda explosiva que queima o carvão em cinzas. Deixe esfriar completamente.\",\n      \"svgFileName\": \"pr09-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // SMOKE PHASE & CHARCOAL HARVEST\",\n        \"Fase 1: Fumaça branca densa (vapor)\",\n        \"Fase 2: Fumaça azul tênue (pirólise pronta)\",\n        \"Todas as aberturas lacradas e resfriadas\",\n        \"Carvão vegetal duro com ressonância metálica\",\n        \"[CHAVE] Lacrar na fumaça azul e resfriar total\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"Prevenção de labareda explosiva e estabilização térmica\",\n        \"text\": \"Ao terminar a carbonização, a câmara está superaquecida e sem oxigênio. Aberturas repentinas puxam ar fresco e inflamam os gases aquecidos (refluxo explosivo). Lacrar hermeticamente e resfriar lentamente por **mais de 6 horas** estabiliza o carbono de alta densidade sem perdas.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Erro fatal: Abrir a cova ainda quente ou esquecer de vedar as aberturas\",\n    \"description\": \"Destampar o forno acima de 400 °C puxa ar fresco de forma violenta, provocando uma labareda explosiva instantânea. Deixar as saídas abertas com a fumaça azul queimará todo o carvão até virar cinzas.\",\n    \"consequence\": \"Consequência: Perda total da produção de carvão e risco severo de queimaduras\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Fogueira ao ar livre só deixa cinza inútil! Veja como assar carvão de toque metálico debaixo da terra!\",\n    \"body\": \"Aperte toras de carvalho em pé num buraco de 50 cm e vede com barro para bloquear 95% do oxigênio! Após 3 horas, a fumaça branca vira azul claro, indicando carvão pronto. Tampe todos os furos com argila e deixe esfriar. Você colherá carvão denso que queima a 500 graus sem fumaça!\",\n    \"outro\": \"Acesse os manuais completos de sobrevivência offline no link do perfil.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr09-outcome.svg\",\n    \"title\": \"Corte transversal da trincheira de carvão e especificações\",\n    \"description\": \"Vista técnica do forno subterrâneo cônico com 95% de restrição de oxigênio, produzindo carvão vegetal poroso de carvalho para calor sem fumaça e filtragem de emergência.\"\n  },\n  \"createdAt\": \"2026-10-15T05:30:00.000Z\",\n  \"contentHash\": \"916099d408d4f948\",\n  \"updatedAt\": \"2026-10-15T14:41:20+09:00\"\n}","content/protocols/locales/09-pit-charcoal-kiln.zh-TW.json":"{\n  \"protocolId\": \"PR-09\",\n  \"category\": \"FIRE\",\n  \"title\": \"在土坑中隔絕空氣將木材燒製成堅硬木炭的方法（原始炭窯製作法）\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[無煙高熱燃料 & 淨水濾炭必備]\",\n  \"summary\": \"將木材直接在營火中燃燒，會與氧氣充分反應而僅留下無用的白灰。若在地面挖掘50公分深的圓錐形土坑，將橡木緊密垂直豎立排列，再以泥土和草皮封蓋阻隔95%的空氣進入，木材便不會起火燃燒，而是在高溫下被燜烤成質地堅硬的木炭。這是在野外維持體溫、淨化泥水及保存火種不可或缺的黑寶石。\",\n  \"timeRequired\": \"5小時（挖坑與木材配置1小時 ＋ 炭化3小時 ＋ 密封冷卻1小時）\",\n  \"successRate\": \"90%（嚴格遵守空氣隔絕與冷卻時間）\",\n  \"difficulty\": \"普通（需具備辨識煙霧顏色變化的要領）\",\n  \"outputPerHour\": \"單次運作可採收3至5公斤優質硬質木炭\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"手腕粗細的乾燥橡木或闊葉木段15至20根（長度30至40公分）\",\n      \"desc\": \"選用質地緻密的高硬度闊葉木，在無氧狀態下不燃燒而進行炭化，製成耐燒且持久的高溫木炭。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"深50公分、頂部直徑60公分的圓錐形土坑\",\n      \"desc\": \"向下漸漸縮小的圓錐形結構，能將熱量匯聚於中央並有效控制空氣循環。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"覆蓋炭窯的粗樹枝骨架與寬大樹葉\",\n      \"desc\": \"橫架於豎立木段之上，支撐泥土不致崩塌並防止泥沙落入炭堆的骨架與隔離層。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"濕潤黏土與草皮（厚度10公分）\",\n      \"desc\": \"完全封閉炭窯頂部，阻隔95%的空氣流入，使內部維持在400度以上高溫燜烤。\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"底部乾燥用細碎樹枝與引火炭火\",\n      \"desc\": \"徹底烤乾土坑底部與坑壁的濕氣，並引燃整批木段底部的點火材。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"第1步：挖掘50公分圓錐形土坑並培育底部基底炭火\",\n      \"description\": \"1. **圓錐形土坑挖掘**: 選擇無積水且乾燥堅實的地面，開挖**頂部直徑60cm、深度50cm**的土坑。\\n2. **下部漸縮錐面加工**: 沿深度向下錐形修整至底部直徑約**30cm**，使熱對流能匯聚於中央。\\n3. **徹底烤乾底壁濕氣**: 於坑底鋪滿乾細枝與落葉點火燃燒**15分鐘以上**，徹底烤乾坑壁黏土濕氣。\\n4. **培育熾熱炭火基底**: 待明火平息，確認坑底整體形成一層**均勻紅熱發光的炭火層**。\",\n      \"actionNote\": \"> 挖掘技巧：若坑底殘留濕氣，木段會產生酸腐臭味並熄滅。請務必用大火將坑壁土壤徹底烤乾。\",\n      \"svgFileName\": \"pr09-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PIT EXCAVATION & PRE-DRYING\",\n        \"頂部直徑60公分圓錐形土坑\",\n        \"深度50公分（底部直徑30公分）\",\n        \"底部乾燥用細枝 ＆ 炭火基底\",\n        \"[核心] 徹底烤乾土壤濕氣並形成高溫火種\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"圓錐土坑蓄熱與地中隔熱保溫\",\n        \"text\": \"地下土坑相較於地表具有極佳的地中隔熱保溫性能，散熱損失極低。上寬下窄的圓錐（V形）結構能將熱對流緊密匯聚於中央核心，維持**400℃以上**的高溫燜烤狀態達**3小時以上**。\"\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"第2步：將手腕粗的橡木段緊密垂直豎立排列無空隙\",\n      \"description\": \"1. **垂直豎立橡木木段**: 於坑底紅熱炭火之上，將**長30～40cm、粗5～8cm**的乾燥橡木如石柱般垂直立起。\\n2. **徑向緊密排列堆疊**: 由中央向外圍推進，將橡木段**嚴絲合縫、緊密無隙**地填滿坑室。\\n3. **敲入細枝木楔填隙**: 於木段間的殘存縫隙中，如木楔般用力打入**手指粗細的細枝**，徹底消除內部氣室。\\n4. **頂面水平度確認**: 檢查所有垂直木段的頂端是否與土坑地面外緣**保持平整齊平**。\",\n      \"actionNote\": \"> 堆疊秘訣：炭窯內部必須塞得嚴絲合縫、幾乎毫無喘息空間。密度越高，產出的木炭越堅硬且具金屬鏗鏘聲。\",\n      \"svgFileName\": \"pr09-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // DENSE VERTICAL TIMBER STACK\",\n        \"手腕粗（5至8公分）橡木垂直積載\",\n        \"以細枝如楔子般填補空隙\",\n        \"從底部炭火向上蔓延的熱氣\",\n        \"[核心] 空隙最小化達成無氧炭化密度極大化\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PYROLYSIS\",\n        \"title\": \"垂直密積與隔氧熱解碳化原理\",\n        \"text\": \"將木料空隙壓縮至極致，可使內部殘氧迅速耗盡，徹底終止明火燃燒。隨後外部高熱僅蒸發水分與揮發性焦油，使純淨的**無定形碳（Carbon）**骨架結晶固化，形成質地堅硬的高密度硬炭。\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"第3步：搭設樹枝骨架並以濕泥及草皮隔絕95%空氣\",\n      \"description\": \"1. **架設井字樹枝支撐架**: 於垂直木段上方橫向架設粗樹枝呈**井字形網格**，承載上部泥層重量。\\n2. **鋪設闊葉隔阻層**: 於木架上方密鋪寬大樹葉與雜草，阻擋上方濕泥坍落滲入炭窯內部。\\n3. **抹覆10cm厚黏土與草皮**: 覆蓋濕黏土與反轉草皮達**10cm厚度**，阻絕外部空氣達**95%以上**。\\n4. **開設進氣孔與煙囪**: 於迎風面地表開出**兩處手指粗的進氣孔**，並於頂部正中央留出**一處拳頭大的排煙煙囪**。\",\n      \"actionNote\": \"> 密封檢查：除煙囪外，若泥層裂縫有煙霧漏出，請立即補上濕泥封死，以防木材劇烈起火燃燒。\",\n      \"svgFileName\": \"pr09-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // MULTI-LAYER ANAEROBIC SEAL\",\n        \"井字樹枝架 ＋ 闊葉隔離支撐層\",\n        \"10公分濕黏土 ＆ 草皮封蓋\",\n        \"底部進氣孔2處（手指粗細）\",\n        \"中央排煙煙囪（拳頭大小）\",\n        \"[核心] 隔絕95%氧氣的不完全燃燒炭窯完成\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"第4步：辨識煙霧顏色變化、完全密封冷卻後採收木炭\",\n      \"description\": \"1. **觀察排出濃白水氣煙霧**: 點火初期**1～2小時**內，觀察煙囪持續排出水分蒸發所形成的濃白煙霧。\\n2. **捕捉淡藍煙霧轉變訊號**: 點火**2～3小時**後，煙霧轉為**澄澈清淡的青藍色**，代表碳化已完全達成。\\n3. **濕泥100%徹底封孔**: 確認藍煙瞬間，立即以濕泥團將煙囪與進氣孔**100%嚴密抹死**徹底斷絕空氣。\\n4. **徐冷6小時後採收木炭**: 靜置**至少6小時**待炭窯土表觸感完全冰涼後，挖開土蓋採收散發銀光鏗鏘有聲的硬木炭。\",\n      \"actionNote\": \"> 回燃爆燃（Backdraft）警示：若窯體內部尚處於高溫時急躁開挖，湧入的新鮮空氣會誘發猛烈回燃大火，瞬間將木炭燒化為灰燼。務必待土層完全冰涼後方可開啟。\",\n      \"svgFileName\": \"pr09-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // SMOKE PHASE & CHARCOAL HARVEST\",\n        \"第1階段：濃白煙霧（水分蒸發）\",\n        \"第2階段：淡藍煙霧（炭化完成）\",\n        \"以濕泥封閉所有孔隙後徹底冷卻\",\n        \"採收具金屬聲響的高密度優質木炭\",\n        \"[核心] 見藍煙立即封孔 ＆ 完全冷卻放涼\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"回燃爆發防範與徐冷（Slow Cooling）降溫\",\n        \"text\": \"碳化完成時炭窯內部處於極度缺氧的超高溫狀態。此時若突遭外氣湧入，高熱可燃氣體將瞬間爆發性起火（回燃現象），使整窯木炭化為白灰。將氣孔完全密封並緩慢冷卻（徐冷）**6小時以上**，能使高密度碳結構完全穩定。\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命錯誤：窯體尚熱時急於挖開土蓋，或未及時封閉排煙孔\",\n    \"description\": \"當內部達400度以上時掀開土蓋，外圍新鮮空氣會猛烈倒灌引發回燃大火。此外，若見藍煙時不及時封孔，整批木材將完全氧化燃燒成毫無價值的白灰。\",\n    \"consequence\": \"後果：數小時心血瞬間化為灰燼，並面臨嚴重灼傷危險\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"在營火裡燒木頭只會留下白灰！教你埋在地底燒出金屬敲擊聲的頂級硬炭！\",\n    \"body\": \"在50公分土坑內緊密豎立橡木段，覆蓋泥土草皮隔絕95%空氣！最初會冒出濃濃白煙，3小時後一旦轉為淡藍色煙霧，代表炭化大功告成。立刻用濕泥封死所有孔隙放涼。冷卻後便能採收無煙、散發500度高溫的野外頂級木炭！\",\n    \"outro\": \"無網路斷網環境也能離線使用的生存圖鑑，請點擊個人簡介連結查閱！\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr09-outcome.svg\",\n    \"title\": \"原始地下炭窯剖面及多孔木炭規格\",\n    \"description\": \"深50公分圓錐形土坑在限制95%空氣下高溫燜烤運作的技術剖面圖，產出可用於無煙高熱與飲用水過濾的緻密多孔橡木炭。\"\n  },\n  \"createdAt\": \"2026-10-15T05:30:00.000Z\",\n  \"contentHash\": \"916099d408d4f948\",\n  \"updatedAt\": \"2026-10-15T14:41:20+09:00\"\n}","content/protocols/locales/10-pine-resin-pitch-glue.de.json":"{\n  \"protocolId\": \"PR-10\",\n  \"category\": \"MEDICINE\",\n  \"title\": \"Kiefernharz zu antiseptischer Salbe und wasserfestem Pechkleber veredeln\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[INFEKTIONSABWEHR & WASSERFESTE WERKZEUGBINDUNG]\",\n  \"summary\": \"In der Wildnis kann sich eine unbehandelte Schnittwunde durch Steinsplitter oder Äste rasch infizieren und zu lebensbedrohlicher Sepsis führen. Zudem erfordern Steinbeile und rissige Gefäße ein felsenhartes, wasserfestes Bindemittel für härteste Feldbedingungen. Durch schonendes Schmelzen von Kiefernharz über indirekter Glutwärme und das Abschöpfen von Rindenteilen gewinnt man eine reine antimikrobielle Wundsalbe. Das Einrühren von feinem Holzkohlepulver im Verhältnis **1:1** ergibt einen obsidianharten, wasserdichten Pechklebestift (Pitch Glue).\",\n  \"timeRequired\": \"40 Minuten (15 Min. Harzernte + 15 Min. indirektes Schmelzen + 10 Min. Kohlemischung)\",\n  \"successRate\": \"95% (strikte indirekte Glutwärme und 1:1 Kohleverhältnis)\",\n  \"difficulty\": \"Einfach (Brand- und Verbrennungsgefahr beachten)\",\n  \"outputPerHour\": \"30ml reine Antiseptik-Salbe + 2 Pechklebestifte pro Charge\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"100g getrocknete Rohkiefernharz-Brocken von Baumstämmen\",\n      \"desc\": \"Spröde, kristalline Bernsteinklumpen. Vollständig ausgehärtete, transparente Knollen enthalten weniger Verunreinigungen und schmelzen zu einer reineren Salbe.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Konkave Schiefer-Steinschale oder große Muschelschale\",\n      \"desc\": \"Natürlicher hitzebeständiger Tiegel, der offene Flammen abwehrt und sanfte Infrarot-Strahlungswärme der Glut aufnimmt.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Zweigkamm-Sieb und saubere Muschelschale\",\n      \"desc\": \"Eng stehende Zweigzinken zum schnellen Auskämmen schwimmender Rindenteile sowie eine Muschel zur Aufbewahrung der Salbe.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"50g fein pulverisiertes Eichenholzkohlepulver\",\n      \"desc\": \"Beseitigt die glasartige Sprödigkeit des erkalteten Harzes und wirkt als mikroskopisches Kohlenstoff-Verstärkungsgerüst.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"Glühendes Hartholzkohlebett und Rührstab\",\n      \"desc\": \"Bietet flammenfreie Infrarotwärme zur Verflüssigung des Harzes, ohne flüchtige Terpendämpfe zu entzünden.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Schritt 1: Ausgehärtete bernsteinfarbene Harzknollen vom Stamm ernten\",\n      \"description\": \"1. **Kristalline Harzknollen aufspüren**: Kiefernstämme oder Astabbrüche nach tropfenförmigen, **ausgehärteten Bernsteinklumpen** absuchen.\\n2. **Mit Steinabschlag abschaben**: Mit einer Feuersteinklinge die **oberflächlichen Brocken behutsam abschaben**, ohne die Bastschicht zu verletzen.\\n3. **Faustgroße Menge sammeln**: Rund **eine Faust voll (ca. 100g)** sauberes Bernsteinharz auf einem breiten Blatt zusammentragen.\\n4. **Grobe Fremdkörper aussortieren**: Lose Erde, Nadeln und grobe Rindenreste vor dem Schmelzen von Hand entfernen.\",\n      \"actionNote\": \"> Baum-ID & Sammeltipp: Unterscheiden Sie die **Kiefer** (rötliche Schildkrötenpanzer-Rinde & **paarweise** wachsende Nadeln, für Harz) von der **Eiche** (tiefe vertikale Rindenfurchen, gezackte Blätter & Eicheln, für Holzkohle) anhand der Fototafel unten. ([Steinaxt (PR-04)](/protocol-04.html) / [Holzkohlenmeiler (PR-09)](/protocol-09.html))\",\n      \"svgFileName\": \"pr10-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // RAW PINE RESIN HARVESTING\",\n        \"Erstarrtes Bernsteinharz am Kiefernstamm\",\n        \"Tangentiales Abschaben mit Steinklinge\",\n        \"Faustgroße Menge (~100g) selektiert\",\n        \"[KERN] Ausgehärtete transparente Knollen wählen\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BOTANY\",\n        \"title\": \"Visuelle Feldbestimmung (Kiefer vs. Eiche) & Terpen-Abwehr\",\n        \"text\": \"Kiefern sondern bei Rindenverletzungen terpenreiches Harz ab, um Wunden luftdicht zu verschließen. Eichen liefern extrem dichtes Hartholz für langanhaltende Glut und das Kohlenstoffpulver zur Harzhärtung.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"Rotkiefer\",\n            \"scientificName\": \"Pinus densiflora\",\n            \"categoryTag\": \"Nadelholz(Softwood) / Harz & Kienspan\",\n            \"imageFileName\": \"id-pine-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-01A // MACRO OPTIC\",\n            \"hudStatus\": \"RESIN GLAND: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"RINDE\",\n                \"value\": \"Oben rötlich-braun; unten in **dicke, schildkrötenpanzerartige Platten** zerfurcht.\"\n              },\n              {\n                \"label\": \"BLATT\",\n                \"value\": \"Spitze, immergrüne **Nadeln, die stets paarweise zu zweit** (**8–14cm** lang) wachsen.\"\n              },\n              {\n                \"label\": \"MERKMAL\",\n                \"value\": \"Erstarrte **gold-bernsteinfarbene Harztropfen** an Stammwunden sowie holzige **Kiefernzapfen**.\"\n              }\n            ],\n            \"fieldUse\": \"Wundsalbe, wasserfester Pechkleber (Pitch), Kienspan-Zunder\"\n          },\n          {\n            \"name\": \"Eiche\",\n            \"scientificName\": \"Quercus\",\n            \"categoryTag\": \"Hartholz(Hardwood) / Dichte Holzkohle\",\n            \"imageFileName\": \"id-oak-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-01B // MACRO OPTIC\",\n            \"hudStatus\": \"FISSURE DEPTH: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"RINDE\",\n                \"value\": \"Dunkelbraune bis grauschwarze Rinde mit **tiefen, rauen vertikalen Längsfurchen**.\"\n              },\n              {\n                \"label\": \"BLATT\",\n                \"value\": \"Breite Laubblätter mit **deutlich gewellten Lappen oder scharfen Sägezähnen** am Rand.\"\n              },\n              {\n                \"label\": \"MERKMAL\",\n                \"value\": \"Herabgefallene **Eicheln mit schuppigen Hütchen (Fruchtbechern)** am Boden (**100%** sicher).\"\n              }\n            ],\n            \"fieldUse\": \"Feines Kohlepulver als Epoxid-Härter, rauchfreie Hochglut, Axtstiele\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Schritt 2: Harz in einer Steinschale über Glutrestwärme schmelzen (Kein offenes Feuer)\",\n      \"description\": \"1. **Harz in Steinschale häufen**: Die **100g Rohharzbrocken** in die Mitte einer flachen Schieferschale oder Muschel legen.\\n2. **10cm neben Glut betten**: Die Schale auf Stützsteinen ca. **10cm neben glühende Kohlen** platzieren, abseits offener Flammen.\\n3. **Mit sanfter Strahlungswärme schmelzen**: Das Harz **5 bis 8 Minuten** langsam verflüssigen lassen, ohne dass Flammen emporschlagen.\\n4. **Klares Goldsirup-Stadium prüfen**: Sicherstellen, dass sich alle festen Knollen vollständig zu einer **transparenten, blasenwerfenden Flüssigkeit** lösen.\",\n      \"actionNote\": \"> Brandgefahr: Harzdämpfe enthalten hochentzündliche Terpene. Die Schale niemals über offenes Lagerfeuer stellen, da Dämpfe explosionsartig verpuffen.\",\n      \"svgFileName\": \"pr10-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // GENTLE EMBER MELTING PROCESS\",\n        \"Geschmolzenes Goldharz in der Steinschale\",\n        \"10cm neben glühenden Kohlen platziert\",\n        \"Flammensperre & sanfte Infrarotwärme\",\n        \"[KERN] 100% Glutwärme verhindert Stichflammen\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PHARMACOLOGY\",\n        \"title\": \"Bakterizide Wirkung von Alpha-Pinen und Terpen-Derivaten\",\n        \"text\": \"Alpha-Pinen und Monoterpene durchdringen bakterielle Lipid-Zellmembranen und blockieren lebenswichtige Stoffwechselenzyme. Schonendes Erwärmen unterhalb des Siedepunkts bewahrt diese wirksamen Inhaltsstoffe vor thermischer Zersetzung.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Schritt 3: Rindenteile mit Zweigkamm abschöpfen & reine Wundsalbe abtrennen\",\n      \"description\": \"1. **Zweigkamm-Sieb anfertigen**: Zarte Zweigspitzen fächerförmig binden, um einen **feinzahnigen Schöpfkamm** herzustellen.\\n2. **Schwimmende Rinde abkämmen**: Den Kamm rasch durch das flüssige Harz ziehen, um **aufschwimmende Rindensplitter und Ruß abzufischen**.\\n3. **30ml reine Salbe abtrennen**: **Ein Drittel der geklärten Flüssigkeit (ca. 30ml)** in eine saubere Muschelschale abgießen.\\n4. **Im Schatten erkalten lassen**: Die Muschel **10 Minuten** ruhen lassen, bis das Harz zu einem geschmeidigen, klebrigen Antiseptik-Gelee erstarrt.\",\n      \"actionNote\": \"> Salbenanwendung: Erstarrt zu festem Balsam. Eine Portion mit der Fingerkuppe erwärmen und auf Schnitte streichen – bildet ein wasser- und keimdichtes Pflaster.\",\n      \"svgFileName\": \"pr10-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DEBRIS REMOVAL & OINTMENT EXTRACTION\",\n        \"Zweigkamm fischt Rindenpartikel ab\",\n        \"Abtrennung von 30ml reiner Wundsalbe\",\n        \"10 Minuten Auskühlen in der Muschel\",\n        \"[KERN] Reine goldene Wundsalbe separat sichern\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Schritt 4: Kohlepulver 1:1 einrühren & zum gehärteten Pechklebestift abschrecken\",\n      \"description\": \"1. **Kohlepulver einstreuen**: Langsam **50g feines Holzkohlepulver** in das restliche heiße Harz in der Steinschale rieseln lassen.\\n2. **Rasch zähkneten**: Mit einem Holzstab **1 bis 2 Minuten** kräftig rühren, bis eine glänzend schwarze, teerartige Masse entsteht.\\n3. **Um Astspitze wickeln**: Das Ende eines daumendicken Hartholzastes durch die Masse drehen und **eine dicke, runde Knolle formen**.\\n4. **In kaltem Wasser abschrecken**: Die Knolle in kaltes Flusswasser tauchen oder **5 Minuten** an der Luft härten lassen, bis sie obsidianhart wird.\",\n      \"actionNote\": \"> Mischungsverhältnis: Reines Harz zerspringt wie Glas. Ein exaktes 1:1-Volumenverhältnis mit Kohlepulver verhindert spröde Brüche bei maximaler Klebkraft. ([Steinaxt (PR-04)](/protocol-04.html) / [Wildseil (PR-05)](/protocol-05.html))\",\n      \"svgFileName\": \"pr10-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // CHARCOAL ADMIXTURE & PITCH STICK\",\n        \"1:1 Eichenholzkohlepulver-Einmischung\",\n        \"Schnelles Rühren zum zähen Teerbinder\",\n        \"Ummantelung des Astes & 5 Min. Härtung\",\n        \"[KERN] Rissfreier wasserdichter Natur-Epoxidstift\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD MATERIALS\",\n        \"title\": \"Beseitigung der Sprödigkeit durch Kohlenstoff-Mikropartikel\",\n        \"text\": \"Reines Kolophonium bricht bei Schlagbeanspruchung schlagartig. Die feine Verteilung poröser Kohlenstoffpartikel blockiert das Fortschreiten von Mikrorissen und wandelt sprödes Baumharz in ein extrem schlagzähes, 100% wasserfestes Natur-Epoxid (Pitch Glue) um.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Fataler Fehler: Erhitzen des Harzes über lodernden Flammen des Lagerfeuers\",\n    \"description\": \"Kiefernharz ist reich an leicht entzündlichen Terpen-Kohlenwasserstoffen. Steht die Schale direkt in offenen Flammen, steigen dichte brennbare Dämpfe auf, die schlagartig verpuffen, das gesamte Harz vernichten und schwerste Verbrennungen an Gesicht und Händen verursachen.\",\n    \"consequence\": \"Folge: Totalverlust des Harzes und akute Gefahr schwerer Verbrennungen 2. Grades\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Eine unbehandelte Wunde in der Wildnis führt binnen Stunden zur Blutvergiftung! So machst du aus Kiefernharz Wundsalbe und Felsenkleber!\",\n    \"body\": \"Schabe getrocknete Bernsteinklumpen von Kiefernstämmen ab und lege sie in eine Steinschale! Niemals über offenes Feuer stellen – nutze indirekte Glutwärme gegen Verpuffungen! Fische Rindensplitter mit einem Zweigkamm ab und gieße einen Teil in eine Muschel: fertig ist deine keimdichte Wundsalbe. Rühre in den Rest feines Kohlepulver 1:1 ein und härte es an einem Ast – so entsteht felsenharter Pechkleber, der Steinbeile bombenfest hält und Wasser abweist!\",\n    \"outro\": \"Entdecke Offline-Überlebensbaupläne für den Ernstfall über den Link im Profil.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr10-outcome.svg\",\n    \"title\": \"Spezifikationen der Kiefernharz-Wundsalbe und des Pechklebers\",\n    \"description\": \"Vollständige Spezifikationen der geklärten Wundsalbe in der Muschelschale, des obsidianharten Pechklebestifts am Hartholzast und des wasserdichten Beilbindungs-Schnitts.\"\n  },\n  \"createdAt\": \"2026-10-16T11:40:00.000Z\",\n  \"contentHash\": \"db453b0037c7d451\"\n}","content/protocols/locales/10-pine-resin-pitch-glue.en.json":"{\n  \"protocolId\": \"PR-10\",\n  \"category\": \"MEDICINE\",\n  \"title\": \"Purifying Pine Resin into Antiseptic Ointment & Waterproof Pitch Glue\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[INFECTION DEFENSE & WATERPROOF TOOL LASHING]\",\n  \"summary\": \"In the wilderness, an untreated cut from a stone edge or jagged branch can quickly turn septic, risking systemic poisoning. Furthermore, stone axe heads, bone needles, and split containers require a rock-hard waterproof binder to withstand heavy outdoor use. By gently melting natural pine resin over indirect ember heat and skimming out tree bark debris, you isolate a pure antimicrobial salve that prevents infection. Blending the remaining hot resin with pulverized charcoal in a **1:1** ratio yields a rock-hard, shock-absorbing waterproof pitch glue stick.\",\n  \"timeRequired\": \"40 minutes (15m resin harvest + 15m gentle indirect melting + 10m charcoal compounding)\",\n  \"successRate\": \"95% (strict indirect heating & 1:1 carbon ratio)\",\n  \"difficulty\": \"Easy (fire & burn safety caution)\",\n  \"outputPerHour\": \"30ml pure antiseptic salve + 2 solid pitch glue sticks per batch\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"100g dried raw pine resin chunks harvested from pine trunks\",\n      \"desc\": \"Brittle, crystalline amber lumps. Fully hardened, translucent nodules contain fewer impurities and melt into superior clarified ointment.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Concave river stone dish or large seashell container\",\n      \"desc\": \"A natural heat-resistant crucible that buffers direct flame and absorbs indirect radiant heat from glowing coals.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Twig comb skimmer & clean seashell collection cup\",\n      \"desc\": \"Tightly spaced twig tines to quickly rake out floating bark flakes, plus a dedicated clean shell to store the clarified salve.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"50g finely pulverized oak charcoal powder\",\n      \"desc\": \"Eliminates brittle glass-like fracturing in cooled resin, serving as an interlocking microscopic carbon reinforcement matrix.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"Glowing hardwood ember bed & hardwood stirring stick\",\n      \"desc\": \"Provides flame-free radiant infrared warmth to safely liquefy resin without igniting volatile terpene vapors.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Step 1: Harvest Hardened Amber Resin Nodules from Pine Tree Trunks\",\n      \"description\": \"1. **Identify Crystalline Amber Nodules**: Scan mature pine trunks or broken limbs for tear-shaped, **solid amber resin deposits**.\\n2. **Scrape with Stone Flake**: Use a flint flake or flat wood wedge to **gently scrape surface lumps** without cutting into live inner bark.\\n3. **Gather 100g Volume**: Collect roughly **one fist-sized volume (approx. 100g)** of relatively clean amber resin onto a broad leaf.\\n4. **Discard Loose Debris**: Manually pick out large pieces of loose dirt, dead needles, or dry bark fragments before processing.\",\n      \"actionNote\": \"> Tree ID & Harvesting Tip: Distinguish **Pine Trees** (reddish tortoise-shell bark & paired **2-needle** bundles, used for resin) from **Oak Trees** (deep vertical dark fissures, serrated leaves & acorns, used for charcoal powder) using the field photo guide below. Hardened glassy amber lumps yield the purest ointment. ([Stone Axe (PR-04)](/protocol-04.html) / [Oak Charcoal Kiln (PR-09)](/protocol-09.html))\",\n      \"svgFileName\": \"pr10-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // RAW PINE RESIN HARVESTING\",\n        \"Hardened Amber Resin on Pine Trunk\",\n        \"Stone Flake Scraping at Tangent Angle\",\n        \"Fist-Sized Volume (~100g) Collected\",\n        \"[KEY] Prioritize hardened translucent nodules\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BOTANY\",\n        \"title\": \"Visual Field Identification (Pine vs. Oak) & Terpene Defense\",\n        \"text\": \"Pine trees secrete terpene-rich resin when their outer bark is ruptured to seal wounds and block pathogens. Oak trees provide dense hardwood that burns into high-heat embers and carbon charcoal powder needed to reinforce brittle resin.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"Pine Tree\",\n            \"scientificName\": \"Pinus densiflora\",\n            \"categoryTag\": \"Softwood / Resin & Tinder\",\n            \"imageFileName\": \"id-pine-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-01A // MACRO OPTIC\",\n            \"hudStatus\": \"RESIN GLAND: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"BARK\",\n                \"value\": \"Reddish-brown upper trunk; lower trunk splits into **thick tortoise-shell diamond plates**.\"\n              },\n              {\n                \"label\": \"LEAF\",\n                \"value\": \"Sharp evergreen **needles growing in bundles of 2** (**8–14cm** long) from each sheath.\"\n              },\n              {\n                \"label\": \"SIGN\",\n                \"value\": \"Hardened **golden-amber resin teardrops** on trunk wounds and woody **pine cones**.\"\n              }\n            ],\n            \"fieldUse\": \"Antiseptic wound salve, waterproof pitch glue, fatwood tinder\"\n          },\n          {\n            \"name\": \"Oak Tree\",\n            \"scientificName\": \"Quercus\",\n            \"categoryTag\": \"Hardwood / Dense Charcoal & Hafts\",\n            \"imageFileName\": \"id-oak-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-01B // MACRO OPTIC\",\n            \"hudStatus\": \"FISSURE DEPTH: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"BARK\",\n                \"value\": \"Dark grey-brown surface carved with **deep, rugged vertical grooves and ridges**.\"\n              },\n              {\n                \"label\": \"LEAF\",\n                \"value\": \"Broad deciduous leaves featuring **distinct wavy lobes or sharp sawtooth edges**.\"\n              },\n              {\n                \"label\": \"SIGN\",\n                \"value\": \"Fallen **acorns and scaly cup-shaped caps (cupules)** scattered around the base (**100%** ID).\"\n              }\n            ],\n            \"fieldUse\": \"Pulverized carbon hardener for pitch, smokeless high-heat charcoal, axe handles\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Step 2: Liquefy Resin in a Stone Dish Using Indirect Ember Heat (No Open Flames)\",\n      \"description\": \"1. **Place Resin in Stone Dish**: Pile the **100g of raw resin chunks** into the center of a shallow concave slate dish or large sea shell.\\n2. **Position 10cm from Coals**: Set the dish on support stones roughly **10cm beside red-hot coals**, completely avoiding open flames.\\n3. **Melt Over Gentle Radiance**: Allow gentle conductive and infrared heat to liquefy the resin slowly over **5 to 8 minutes**.\\n4. **Observe Golden Syrup Phase**: Verify that the solid nodules dissolve entirely into a **translucent, bubbling golden liquid**.\",\n      \"actionNote\": \"> Fire Hazard: Pine resin vapors contain highly flammable volatile terpenes. Never place the dish directly over campfire flames, as vapors will flash-ignite violently.\",\n      \"svgFileName\": \"pr10-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // GENTLE EMBER MELTING PROCESS\",\n        \"Molten Golden Resin in Concave Dish\",\n        \"Positioned 10cm Beside Glowing Coals\",\n        \"Flame Barrier & Indirect Radiance\",\n        \"[KEY] 100% ember heat to prevent flash ignition\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PHARMACOLOGY\",\n        \"title\": \"Bactericidal Action of Alpha-Pinene and Terpene Derivates\",\n        \"text\": \"Alpha-pinene and mono-terpenes penetrate bacterial lipid cell membranes, inhibiting essential metabolic enzymes. Gentle thermal processing below the boiling point preserves these active antimicrobial compounds without thermal degradation.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Step 3: Rake Out Surface Bark Debris & Isolate Antiseptic Salve\",\n      \"description\": \"1. **Craft Twig Comb Skimmer**: Bind a fan of slender hardwood twigs side-by-side to form a **fine-toothed comb skimmer**.\\n2. **Skim Floating Impurities**: Rapidly draw the comb across the molten resin surface to **rake out buoyant bark flakes and soot**.\\n3. **Separate 30ml Pure Salve**: Scoop **one-third of the clarified golden liquid (approx. 30ml)** into a separate clean shell or flat stone.\\n4. **Allow Ambient Cooling**: Let the shell rest in the shade for **10 minutes** until it thickens into a firm, tacky antiseptic amber jelly.\",\n      \"actionNote\": \"> Salve Application: The salve cools into a firm gel. Warm a dab with your fingertip to melt it over cuts, creating a waterproof, bacteria-proof natural barrier.\",\n      \"svgFileName\": \"pr10-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DEBRIS REMOVAL & OINTMENT EXTRACTION\",\n        \"Twig Comb Raking Out Bark Debris\",\n        \"Isolating 30ml Antiseptic Salve Portion\",\n        \"Ambient Cooling in Shell for 10 Minutes\",\n        \"[KEY] Extract pure golden antiseptic salve\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Step 4: Blend 1:1 Charcoal Powder & Quench into a Hardened Pitch Stick\",\n      \"description\": \"1. **Add Pulverized Charcoal**: Slowly sprinkle **50g of fine hardwood charcoal powder** into the hot resin remaining in the dish.\\n2. **Rapid Viscous Churning**: Vigorously stir with a wooden stick for **1 to 2 minutes** until the mixture turns into glossy black pitch.\\n3. **Wrap Around Stick Tip**: Rotate the tip of a thumb-thick hardwood branch through the molten tar, **building a thick, round candy-like bulb**.\\n4. **Quench in Cold Water**: Dip the coated bulb into cold river water or cool in air for **5 minutes** to freeze into an obsidian-hard binder stick.\",\n      \"actionNote\": \"> Mixing Ratio: Pure resin shatters like glass when struck. A strict 1:1 volumetric blend with charcoal powder prevents brittle failure while preserving maximum bond strength. ([Stone Axe (PR-04)](/protocol-04.html) / [Wild Cordage (PR-05)](/protocol-05.html))\",\n      \"svgFileName\": \"pr10-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // CHARCOAL ADMIXTURE & PITCH STICK\",\n        \"1:1 Pulverized Oak Charcoal Admixture\",\n        \"High-Speed Churning into Viscous Tar\",\n        \"Bulb Wrapped onto Stick & 5-Min Quench\",\n        \"[KEY] Crack-free waterproof natural epoxy stick\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD MATERIALS\",\n        \"title\": \"Overcoming Brittleness via Carbon Micro-Particle Reinforcement\",\n        \"text\": \"Pure rosin undergoes catastrophic brittle fracture under impact. Dispersing porous microscopic carbon (charcoal) throughout the resin matrix creates crack-deflecting barriers, converting fragile pine rosin into a tough, 100% waterproof natural epoxy (Pitch Glue).\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Fatal Mistake: Heating resin directly over active campfire flames\",\n    \"description\": \"Pine resin is saturated with highly volatile terpene hydrocarbons. Exposing the melting dish directly to leaping flames releases dense flammable vapors that ignite in an explosive flash fire, consuming your resin and inflicting severe facial and hand burns.\",\n    \"consequence\": \"Consequence: Complete loss of resin and high risk of severe second-degree burns\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"An untreated wound in the wild can turn septic within hours! Here is how to turn pine resin into antiseptic salve and rock-hard epoxy!\",\n    \"body\": \"Scrape dried amber resin lumps from pine trunks and place them in a concave stone dish. Never heat over open fire—use indirect ember heat so volatile vapors don't explode! Skim floating bark debris with a twig comb and pour a portion into a clean shell to cool into a 100% bacteria-blocking antiseptic salve. Mix fine charcoal powder 1:1 into the rest to create an obsidian-hard pitch glue stick that permanently secures stone axes and repels water!\",\n    \"outro\": \"Discover offline primitive survival blueprints for post-collapse resilience at the link in profile.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr10-outcome.svg\",\n    \"title\": \"Finished Pine Resin Antiseptic Ointment & Waterproof Pitch Glue Specifications\",\n    \"description\": \"Full specifications of clarified golden antimicrobial salve in an oyster shell, rock-hard obsidian pitch glue stick wrapped on hardwood, and axe joint waterproof barrier cross-section.\"\n  },\n  \"createdAt\": \"2026-10-16T11:40:00.000Z\",\n  \"contentHash\": \"db453b0037c7d451\"\n}","content/protocols/locales/10-pine-resin-pitch-glue.es.json":"{\n  \"protocolId\": \"PR-10\",\n  \"category\": \"MEDICINE\",\n  \"title\": \"Purificación de resina de pino en ungüento antiséptico y pegamento impermeable\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[DEFENSA CONTRA INFECCIONES Y FIJACIÓN IMPERMEABLE]\",\n  \"summary\": \"En la naturaleza, un corte sin tratar con una piedra afilada o rama puede infectarse rápidamente, provocando septicemia y poniendo en riesgo la vida. Asimismo, las cabezas de hachas de piedra y recipientes agrietados requieren un aglutinante impermeable resistente para el uso rudo. Al derretir suavemente la resina de pino con el calor indirecto de las brasas y retirar los restos de corteza, se obtiene un ungüento antimicrobiano puro. Mezclando la resina restante con polvo fino de carbón en proporción **1:1**, se produce una barra de pegamento de brea (Pitch Glue) tan dura como la piedra.\",\n  \"timeRequired\": \"40 minutos (15m recolección + 15m fusión indirecta + 10m mezcla de carbón)\",\n  \"successRate\": \"95% (fusión indirecta estricta y proporción de carbón 1:1)\",\n  \"difficulty\": \"Fácil (precaución con fuego y quemaduras)\",\n  \"outputPerHour\": \"30ml de ungüento antiséptico + 2 barras de pegamento impermeable por lote\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"100g de trozos secos de resina de pino recolectados de troncos\",\n      \"desc\": \"Nódulos cristalinos de color ámbar. Los trozos bien endurecidos contienen menos impurezas y se derriten en un ungüento clarificado superior.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Plato de piedra cóncava o concha marina grande\",\n      \"desc\": \"Crisol natural resistente al calor que aísla de las llamas directas y absorbe la radiación térmica de las brasas.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Peine espumadera de ramitas y concha marina limpia\",\n      \"desc\": \"Dientes de ramitas muy juntos para extraer rápidamente la corteza flotante y una concha limpia para almacenar el ungüento.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"50g de polvo fino de carbón de roble\",\n      \"desc\": \"Elimina la fragilidad quebradiza de la resina fría, actuando como una matriz microscópica de refuerzo de carbono.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"Lecho de brasas de madera dura y palo para remover\",\n      \"desc\": \"Aporta calor radiante infrarrojo seguro para licuar la resina sin inflamar los vapores volátiles de terpenos.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Paso 1: Recolectar nódulos endurecidos de resina de pino en el tronco\",\n      \"description\": \"1. **Identificar nódulos cristalinos**: Busque en troncos de pino maduros depósitos de **resina endurecida en forma de gota**.\\n2. **Raspar con lasca de piedra**: Use una lasca de pedernal para **raspar suavemente los nódulos superficiales** sin dañar la corteza interior viva.\\n3. **Reunir 100g de volumen**: Junte aproximadamente **el volumen de un puño (unos 100g)** de resina limpia sobre una hoja ancha.\\n4. **Descartar residuos gruesos**: Retire manualmente hojas secas, tierra o astillas sueltas antes de fundir.\",\n      \"actionNote\": \"> Identificación y recolección: Distinga el **Pino** (corteza rojiza tipo caparazón de tortuga y agujas en **pares de 2**, para resina) del **Roble/Encino** (corteza oscura con surcos verticales profundos, hojas dentadas y bellotas, para carbón) con la guía fotográfica inferior. ([Hacha de Piedra (PR-04)](/protocol-04.html) / [Horno de Carbón (PR-09)](/protocol-09.html))\",\n      \"svgFileName\": \"pr10-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // RAW PINE RESIN HARVESTING\",\n        \"Resina de pino ámbar en el tronco\",\n        \"Raspado tangencial con lasca de piedra\",\n        \"Volumen de un puño (~100g) recolectado\",\n        \"[CLAVE] Priorizar nódulos duros y transparentes\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BOTANY\",\n        \"title\": \"Identificación Visual de Especies (Pino vs. Roble) y Defensa de Terpenos\",\n        \"text\": \"Los pinos secretan resina rica en terpenos al dañarse su corteza para sellar heridas y frenar bacterias. El roble es una madera dura y densa que produce brasas duraderas y el polvo de carbón necesario para endurecer la resina.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"Pino Rojo\",\n            \"scientificName\": \"Pinus densiflora\",\n            \"categoryTag\": \"Conífera(Softwood) / Resina y Yesca\",\n            \"imageFileName\": \"id-pine-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-01A // MACRO OPTIC\",\n            \"hudStatus\": \"RESIN GLAND: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"CORTEZA\",\n                \"value\": \"Parte superior rojiza; la base se agrieta en **placas gruesas con forma de caparazón de tortuga**.\"\n              },\n              {\n                \"label\": \"HOJA\",\n                \"value\": \"Agujas verdes punzantes que **crecen siempre en pares de 2** (**8–14cm** de largo).\"\n              },\n              {\n                \"label\": \"SEÑAL\",\n                \"value\": \"Gotas endurecidas de **resina color ámbar dorado** en heridas del tronco y **piñas** leñosas.\"\n              }\n            ],\n            \"fieldUse\": \"Ungüento antiséptico, pegamento impermeable (Pitch), tea de pino\"\n          },\n          {\n            \"name\": \"Roble / Encino\",\n            \"scientificName\": \"Quercus\",\n            \"categoryTag\": \"Madera Dura(Hardwood) / Carbón Denso\",\n            \"imageFileName\": \"id-oak-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-01B // MACRO OPTIC\",\n            \"hudStatus\": \"FISSURE DEPTH: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"CORTEZA\",\n                \"value\": \"Superficie marrón oscuro a grisáceo con **surcos verticales profundos y rugosos**.\"\n              },\n              {\n                \"label\": \"HOJA\",\n                \"value\": \"Hojas anchas con **bordes ondulados o dientes de sierra bien marcados**.\"\n              },\n              {\n                \"label\": \"SEÑAL\",\n                \"value\": \"Presencia de **bellotas y cúpulas escamosas** en las ramas o el suelo (**100%** seguro).\"\n              }\n            ],\n            \"fieldUse\": \"Polvo de carbón endurecedor, brasas sin humo de alto calor, mangos de hacha\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Paso 2: Licuar la resina en piedra usando calor indirecto (sin llamas abiertas)\",\n      \"description\": \"1. **Colocar resina en plato de piedra**: Apile los **100g de resina cruda** en el centro de un plato de pizarra cóncavo o concha grande.\\n2. **Ubicar a 10cm de las brasas**: Apoye el plato sobre piedras soporte a unos **10cm junto a las brasas al rojo vivo**, evitando llamas abiertas.\\n3. **Fundir con radiación suave**: Deje que el calor suave y la radiación infrarroja licúen la resina lentamente durante **5 a 8 minutos**.\\n4. **Verificar fase de jarabe dorado**: Compruebe que los nódulos sólidos se disuelvan por completo en un **líquido ámbar burbujeante y transparente**.\",\n      \"actionNote\": \"> Peligro de incendio: Los vapores de resina contienen terpenos altamente inflamables. Nunca coloque el plato directamente sobre llamas abiertas.\",\n      \"svgFileName\": \"pr10-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // GENTLE EMBER MELTING PROCESS\",\n        \"Resina líquida dorada en plato de piedra\",\n        \"Ubicada a 10cm junto a las brasas\",\n        \"Barrera contra llamas y radiación suave\",\n        \"[CLAVE] 100% calor de brasas para evitar ignición\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PHARMACOLOGY\",\n        \"title\": \"Acción bactericida del alfa-pineno y derivados de terpenos\",\n        \"text\": \"El alfa-pineno y los monoterpenos penetran las membranas lipídicas bacterianas, inhibiendo enzimas metabólicas esenciales. El calentamiento suave por debajo del punto de ebullición preserva estos compuestos activos sin degradación térmica.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Paso 3: Retirar impurezas flotantes con peine de ramitas y aislar el ungüento\",\n      \"description\": \"1. **Elaborar peine de ramitas**: Una varias ramitas delgadas en abanico para formar un **peine espumadera de dientes finos**.\\n2. **Retirar restos de corteza**: Pase rápidamente el peine por la resina líquida para **atrapar fragmentos de corteza y hollín**.\\n3. **Separar 30ml de ungüento puro**: Vierta **un tercio del líquido dorado clarificado (unos 30ml)** en una concha limpia separada o piedra plana.\\n4. **Dejar enfriar al ambiente**: Deje reposar la concha a la sombra durante **10 minutos** hasta que espese en una jalea antiséptica firme y gomosa.\",\n      \"actionNote\": \"> Aplicación del ungüento: Se endurece como un gel. Entibie una pequeña porción con la yema del dedo para aplicarla sobre cortes, creando una barrera impermeable y antibacteriana.\",\n      \"svgFileName\": \"pr10-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DEBRIS REMOVAL & OINTMENT EXTRACTION\",\n        \"Peine de ramitas extrayendo corteza\",\n        \"Aislamiento de 30ml de ungüento puro\",\n        \"Enfriamiento en concha durante 10 minutos\",\n        \"[CLAVE] Extraer ungüento dorado antiséptico puro\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Paso 4: Mezclar carbón 1:1 y enfriar en barra sólida de pegamento de brea\",\n      \"description\": \"1. **Incorporar carbón fino**: Espolvoree lentamente **50g de carbón de roble pulverizado** en la resina caliente restante en el plato.\\n2. **Agitación rápida y viscosa**: Remueva enérgicamente con un palo de madera durante **1 a 2 minutos** hasta formar un alquitrán negro brillante.\\n3. **Enrollar en punta de palo**: Gire el extremo de una rama gruesa en la brea caliente, **formando una bola redonda y gruesa tipo caramelo**.\\n4. **Templar en agua fría**: Sumerja la bola en agua fría de río o enfríe al aire durante **5 minutos** para obtener una barra adhesiva dura como la obsidiana.\",\n      \"actionNote\": \"> Proporción de mezcla: La resina pura se rompe como vidrio. Una mezcla volumétrica estricta 1:1 con carbón previene roturas frágiles manteniendo máxima fuerza de adhesión. ([Hacha de Piedra (PR-04)](/protocol-04.html) / [Cuerda Salvaje (PR-05)](/protocol-05.html))\",\n      \"svgFileName\": \"pr10-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // CHARCOAL ADMIXTURE & PITCH STICK\",\n        \"Mezcla 1:1 con carbón de roble fino\",\n        \"Agitación rápida formando pasta viscosa\",\n        \"Recubrimiento en palo y templado de 5 min\",\n        \"[CLAVE] Barra epóxica impermeable sin grietas\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD MATERIALS\",\n        \"title\": \"Superación de la fragilidad mediante micropartículas de carbono\",\n        \"text\": \"La colofonia de pino pura sufre fracturas frágiles catastróficas por impacto. Dispersar micropartículas porosas de carbono (carbón) crea barreras que desvían las grietas, transformando la resina frágil en un epoxi natural resistente y 100% impermeable (Pitch Glue).\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Error fatal: Calentar la resina directamente sobre llamas abiertas de fogata\",\n    \"description\": \"La resina de pino está saturada de hidrocarburos terpénicos volátiles. Exponer el plato directamente al fuego libera densos vapores inflamables que detonan en una llamarada instantánea, quemando toda la resina y causando graves quemaduras en rostro y manos.\",\n    \"consequence\": \"Consecuencia: Pérdida total de la resina y riesgo severo de quemaduras de segundo grado\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"¡Una herida sin tratar en la selva puede infectarse en pocas horas! ¡Aprende a transformar resina de pino en ungüento antibacteriano y pegamento de piedra!\",\n    \"body\": \"¡Raspe la resina ámbar seca de los pinos y colóquela en un plato de piedra! No la ponga al fuego directo: ¡use el calor indirecto de las brasas para evitar explosiones! Retire la corteza flotante con un peine de ramitas y vierta una parte en una concha limpia para obtener un ungüento 100% antiséptico. ¡Mezcle carbón fino 1:1 con el resto para crear una barra de pegamento de brea dura como obsidiana que asegura hachas y repele el agua!\",\n    \"outro\": \"Descubra planos de supervivencia primitiva sin conexión en el enlace del perfil.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr10-outcome.svg\",\n    \"title\": \"Especificaciones del ungüento antiséptico y pegamento impermeable de resina de pino\",\n    \"description\": \"Especificaciones del ungüento antimicrobiano en concha marina, barra de pegamento de brea sobre madera dura y sección transversal del sellado impermeable en unión de hacha.\"\n  },\n  \"createdAt\": \"2026-10-16T11:40:00.000Z\",\n  \"contentHash\": \"db453b0037c7d451\"\n}","content/protocols/locales/10-pine-resin-pitch-glue.ja.json":"{\n  \"protocolId\": \"PR-10\",\n  \"category\": \"MEDICINE\",\n  \"title\": \"松脂を溶かして固める傷口消毒軟膏と万能防水接着剤（原始松脂精製法）\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[細菌感染遮断 ＆ 道具防水結束]\",\n  \"summary\": \"野外において石刃や小枝による切り傷を放置すると、細菌感染により化膿し敗血症を引き起こす致命的な危険が生じます。また、石斧の柄や土器の隙間を頑丈かつ防水に固定する天然接着剤が不可欠です。松の木が自らを保護するために分泌する松脂を熾火の間接熱で優しく溶かし、不純物を濾過すれば傷口を守る天然抗菌軟膏となり、これに微細な木炭粉を**1:1**で混ぜて練り合わせると、冷えて石のように硬化する万能防水樹脂接着剤（ピッチグルー）が完成します。\",\n  \"timeRequired\": \"40分（松脂採取15分＋間接加熱溶解15分＋木炭粉配合成型10分）\",\n  \"successRate\": \"95%（直火厳禁および木炭粉1:1比率厳守時）\",\n  \"difficulty\": \"易（火災および火傷に厳重注意）\",\n  \"outputPerHour\": \"1回あたり抗菌軟膏30ml＋防水結束スティック2本完成\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"老松の幹から採取した乾燥生松脂の塊100g\",\n      \"desc\": \"拳1個大の琥珀色の結晶塊。完全に硬化した透明度の高い塊は不純物が少なく、溶かした際に極めて純度の高い上質軟膏になります。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"松脂を溶かす窪みのある平石皿または大型貝殻\",\n      \"desc\": \"直火の炎を遮断し、熾火の輻射熱を吸収して安全に松脂を溶かす天然耐熱容器です。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"小枝を櫛状に組んだ濾し器と軟膏用貝殻\",\n      \"desc\": \"溶けた松脂の表面に浮かぶ樹皮くずを素早く掬い取り、純粋軟膏を分離するための道具です。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"微細に粉砕したナラ木炭粉50g\",\n      \"desc\": \"冷却された松脂のガラスのような脆さを排除し、石のように強靭に固める微細炭素補強骨格です。\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"赤く熱した熾火の余熱と撹拌用の硬い小枝\",\n      \"desc\": \"炎を一切立てず、赤外線輻射熱のみで松脂を穏やかに液化させる安全な熱源です。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"ステップ1：松の幹から乾燥した琥珀色の生松脂塊を採取する\",\n      \"description\": \"1. **琥珀色松脂の選別**：松の幹や折れた枝の周囲に滴状に凝固した**乾いた琥珀色の松脂塊**を探します。\\n2. **石刃で削り取り**：鋭利な剥片石刃を用いて、生きた内樹皮を傷つけないよう**表面の塊のみを優しく**削り落とします。\\n3. **拳1個分を確保**：樹皮の混入が少ない綺麗な松脂を**拳1個分（約100g）**集めて広葉樹の葉に載せます。\\n4. **粗い異物の除去**：目立つ土埃や枯れ葉の破片は指先であらかじめ取り除いておきます。\",\n      \"actionNote\": \"> 樹種識別と採取のコツ：赤褐色の亀甲模様の樹皮と**2本束の針葉**を持つ**マツ（松）**（松脂採取用）と、縦に深い溝がある黒褐色の樹皮・ギザギザの葉・ドングリが特徴の**ナラ・クヌギ（楢・椚）**（炭粉硬化剤用）を下の実写図鑑で正確に区別してください。固まった琥珀色の塊が最も純粋な軟膏になります。 ([石斧・石刃製作(PR-04)](/protocol-04.html) / [地下炭窯(PR-09)](/protocol-09.html))\",\n      \"svgFileName\": \"pr10-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // RAW PINE RESIN HARVESTING\",\n        \"松の幹に凝固した琥珀色の生松脂\",\n        \"石刃で樹皮を傷めず表面のみ採取\",\n        \"拳1個分（約100g）を選別確保\",\n        \"[核心] 完全に硬化した透明な塊を優先\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BOTANY\",\n        \"title\": \"野生重要樹種（マツ・ナラ）の肉眼識別とテルペン防御機構\",\n        \"text\": \"マツは樹皮が傷つくと傷口を塞ぎ細菌を防ぐためにテルペンを含む樹脂（松脂）を分泌します。一方、ナラやクヌギは組織が緻密で硬い広葉樹であり、松脂の脆さを克服する最高級の炭素炭粉と高温の炭火を提供します。\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"マツ（アカマツ）\",\n            \"scientificName\": \"Pinus densiflora\",\n            \"categoryTag\": \"針葉樹(Softwood) / 松脂・着火材\",\n            \"imageFileName\": \"id-pine-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-01A // MACRO OPTIC\",\n            \"hudStatus\": \"RESIN GLAND: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"樹皮/BARK\",\n                \"value\": \"幹の上部は赤褐色、下部は**亀の甲羅のような菱形の割れ目**で厚く剥がれます。\"\n              },\n              {\n                \"label\": \"葉/LEAF\",\n                \"value\": \"付け根の鞘から**常に2本ずつ束になって生える尖った常緑の針葉**（長さ**8〜14cm**）が特徴です。\"\n              },\n              {\n                \"label\": \"徴候/SIGN\",\n                \"value\": \"幹の傷口に涙状に固まった**琥珀色の松脂の塊**と枝先の木質の**松ぼっくり**で即座に判別できます。\"\n              }\n            ],\n            \"fieldUse\": \"傷口消毒軟膏、万能防水接着剤（ピッチ）、高火力ファットウッド\"\n          },\n          {\n            \"name\": \"ナラ・クヌギ（オーク）\",\n            \"scientificName\": \"Quercus\",\n            \"categoryTag\": \"広葉樹(Hardwood) / 高密度炭・構造材\",\n            \"imageFileName\": \"id-oak-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-01B // MACRO OPTIC\",\n            \"hudStatus\": \"FISSURE DEPTH: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"樹皮/BARK\",\n                \"value\": \"暗い黒褐色〜暗灰色の表面に、**縦方向の深く粗い垂直の溝**が長く刻まれています。\"\n              },\n              {\n                \"label\": \"葉/LEAF\",\n                \"value\": \"葉の縁に**波状または鋭いノコギリ状のギザギザ（鋸歯）**がはっきりある手のひら大の広い葉です。\"\n              },\n              {\n                \"label\": \"徴候/SIGN\",\n                \"value\": \"枝や根元の地面に落ちている**ドングリの実とウロコ状の帽子（殻斗）**があれば**100%**ナラ・クヌギ類です。\"\n              }\n            ],\n            \"fieldUse\": \"ピッチ硬化用微細炭粉、無煙高熱炭、石斧の柄\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"ステップ2：窪み石に載せて熾火の間接余熱で静かに溶かす（直火厳禁）\",\n      \"description\": \"1. **石皿中央に配置**：窪みのある石皿または貝殻の中央に集めた**松脂塊100g**を載せます。\\n2. **熾火から10cm離隔**：燃え盛る炎を絶対に避け、赤熱した熾火の縁から**10cm離れた位置**に石皿を設置します。\\n3. **間接輻射熱で加熱**：吹き上がる火の粉に厳重注意しつつ、**5〜8分間**穏やかな余熱のみで松脂を溶解します。\\n4. **透明シロップ化確認**：固まりが完全に崩れ、**黄金色の澄んだ液体シロップ**に変化したことを確認します。\",\n      \"actionNote\": \"> 引火注意：松脂の蒸気には揮発性オイルが多く含まれ、炎がかすめただけで爆発的に引火します。必ず直火を避け、熾火の余熱のみで溶かしてください。\",\n      \"svgFileName\": \"pr10-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // GENTLE EMBER MELTING PROCESS\",\n        \"窪み石皿の中で溶けた黄金色の松脂\",\n        \"熾火の縁から10cm間接配置\",\n        \"直火の炎を遮断し穏やかな輻射熱加熱\",\n        \"[核心] 引火防止のための100%余熱溶解\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PHARMACOLOGY\",\n        \"title\": \"アルファピネンおよびテルペン分子の強力な抗菌作用\",\n        \"text\": \"松脂の主成分であるα-ピネンとテルペン誘導体は、細菌の脂質細胞膜を破壊し代謝酵素を無力化します。高温の直火で焦がさず低温で溶解させることで、有効成分の熱分解を防ぎます。\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"ステップ3：小枝の櫛で不純物を濾し、純粋な抗菌軟膏を取り分ける\",\n      \"description\": \"1. **小枝櫛の製作**：細い小枝の先端を束ねて並べ、**細かい櫛状の濾し器**を作ります。\\n2. **表面の樹皮かすを掬う**：液状松脂の表面に浮かび上がった樹皮かすや煤を、小枝櫛で**素早く掬い取ります**。\\n3. **抗菌軟膏30mlを分離**：澄み切った黄金色の松脂液の**3分の1（約30ml）**を、別の清潔な貝殻や平石に注ぎ分けます。\\n4. **自然冷却して保存**：日陰の涼しい場所で**10分間**冷ませば、指先で塗布できる弾力のある天然消毒軟膏が完成します。\",\n      \"actionNote\": \"> 軟膏の保管：冷えるとゼリーのように固まります。傷を負った際に体温で少し温めて塗れば、細菌の侵入を100%防ぐ天然防水バンデージになります。\",\n      \"svgFileName\": \"pr10-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DEBRIS REMOVAL & OINTMENT EXTRACTION\",\n        \"小枝の櫛で浮いた樹皮ゴミを濾過\",\n        \"傷口消毒用の純粋松脂液30mlを分離\",\n        \"貝殻に取り分けて10分間自然冷却\",\n        \"[核心] 澄んだ黄金色消毒軟膏の分離確保\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"ステップ4：微細木炭粉を1:1で練り合わせ、石のように硬い防水スティックを作る\",\n      \"description\": \"1. **木炭粉の投入**：石皿に残った熱い松脂液に、粉末状にすり潰した**ナラ木炭粉50g**を少量ずつ投入します。\\n2. **高速撹拌で練成**：小枝でダマが残らないよう**1〜2分間**素早くかき混ぜ、黒く粘り気のある水飴状に練り上げます。\\n3. **棒の先端に巻き付け**：親指大の硬い小枝の先端に、熱い黒樹脂を**球状に厚く**巻き付けます。\\n4. **冷水急冷で硬化**：冷水に浸すか常温で**5分間**冷ませば、爪も立たない黒曜石のような硬度の防水接着棒（ピッチスティック）が完成します。\",\n      \"actionNote\": \"> 配合比率：木炭粉が少なすぎるとガラスのように割れやすく、多すぎると接着力が落ちます。容積比1:1の黄金比を守ることが最も強靭に仕上がります。 ([石斧・石刃製作(PR-04)](/protocol-04.html) / [野生ロープ製作(PR-05)](/protocol-05.html))\",\n      \"svgFileName\": \"pr10-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // CHARCOAL ADMIXTURE & PITCH STICK\",\n        \"微細なナラ木炭粉を1:1比率で投入\",\n        \"小枝で高速撹拌し粘性ペースト化\",\n        \"小枝先端に塗布後5分間で急冷硬化\",\n        \"[核心] 割れのない天然防水エポキシ棒完成\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD MATERIALS\",\n        \"title\": \"炭素微粉末添加による脆性克服と天然エポキシ化\",\n        \"text\": \"純粋な松脂は冷却するとガラスのように脆くなります。多孔質炭素である木炭微粒子を均一に分散させることで、亀裂の進展を防ぐ骨格となり、強い衝撃にも砕けず水を100%弾く原始天然エポキシ（ピッチグルー）に生まれ変わります。\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命的な失敗：松脂を早く溶かそうと焚き火の炎の上に直接置くこと\",\n    \"description\": \"松脂は揮発性の高いテルペン炭化水素を大量に含んでいます。焚き火の炎に直接触れさせると、気化した可燃性ガスに瞬間的に引火して大爆発を起こし、松脂が全焼するとともに顔や手に深刻な重度熱傷を負います。\",\n    \"consequence\": \"結果：松脂の完全消失および顔面・両手の重症火傷の危険\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"野外の切り傷を放置すると敗血症で命を落とします！松脂で天然抗生物質と石接着剤を作る秘伝！\",\n    \"body\": \"松の幹に固まった琥珀色の松脂を削り落とし、窪み石皿に載せてください！炎に触れると爆発するので、必ず熾火の余熱のみで溶かします。澄んで溶けた松脂を貝殻に取り分けて冷ませば、細菌を100%防ぐ消毒軟膏になります。残りに細かい木炭粉を1:1で練り込み小枝に固めれば、石斧を固定し水を弾く最強の防水接着剤が完成します！\",\n    \"outro\": \"文明崩壊時にも役立つ原始サバイバル図面はプロフィールリンクで無料公開中。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr10-outcome.svg\",\n    \"title\": \"完成した松脂抗菌消毒軟膏および防水樹脂結束棒（ピッチスティック）の諸元\",\n    \"description\": \"窪み石皿と貝殻に収められた黄金色の天然抗菌保護軟膏と、木炭粉を1:1配合して小枝先端に固めた黒曜石光沢の防水結束棒、および石斧の柄結束部の防水防壁断面図です。\"\n  },\n  \"createdAt\": \"2026-10-16T11:40:00.000Z\",\n  \"contentHash\": \"db453b0037c7d451\"\n}","content/protocols/locales/10-pine-resin-pitch-glue.pt.json":"{\n  \"protocolId\": \"PR-10\",\n  \"category\": \"MEDICINE\",\n  \"title\": \"Purificação de resina de pinheiro em pomada antisséptica e cola impermeável\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[DEFESA CONTRA INFECÇÕES E FIXAÇÃO IMPERMEÁVEL]\",\n  \"summary\": \"Na selva, um corte não tratado causado por lascas de pedra ou galhos pode infeccionar rapidamente, provocando septicemia e risco de morte. Além disso, machados de pedra e recipientes rachados necessitam de um aglutinante impermeável resistente para o uso rústico. Ao derreter suavemente a resina de pinheiro sobre o calor indireto das brasas e remover os resíduos de casca, obtém-se uma pomada antimicrobiana pura. Misturando a resina restante com pó fino de carvão na proporção de **1:1**, produz-se um bastão de cola de piche (Pitch Glue) duro como pedra.\",\n  \"timeRequired\": \"40 minutos (15m coleta + 15m fusão indireta + 10m mistura de carvão)\",\n  \"successRate\": \"95% (aquecimento indireto estrito e proporção de carvão 1:1)\",\n  \"difficulty\": \"Fácil (cuidado com fogo e queimaduras)\",\n  \"outputPerHour\": \"30ml de pomada pura + 2 bastões de cola impermeável por lote\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"100g de pedaços secos de resina bruta colhidos de troncos de pinheiro\",\n      \"desc\": \"Nódulos cristalinos cor de âmbar. Pedaços bem endurecidos contêm menos impurezas e derretem em uma pomada clarificada de qualidade superior.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Prato de pedra côncava ou concha marinha grande\",\n      \"desc\": \"Cadinho natural resistente ao calor que protege contra chamas diretas e absorve a radiação térmica das brasas.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Pente escumadeira de gravetos e concha limpa\",\n      \"desc\": \"Dentes de gravetos bem juntos para retirar rapidamente cascas flutuantes e uma concha limpa para armazenar a pomada.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"50g de pó fino de carvão vegetal de carvalho\",\n      \"desc\": \"Elimina a fragilidade quebradiça da resina fria, servindo como matriz microscópica de reforço de carbono.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"Leito de brasas incandescentes e graveto para mexer\",\n      \"desc\": \"Fornece calor infravermelho seguro para liquefazer a resina sem inflamar vapores voláteis de terpenos.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Passo 1: Colher nódulos endurecidos de resina de âmbar no tronco do pinheiro\",\n      \"description\": \"1. **Identificar nódulos cristalinos**: Procure em troncos de pinheiros depósitos de **resina endurecida em formato de gota**.\\n2. **Raspar com lasca de pedra**: Use uma lasca de sílex para **raspar suavemente os nódulos superficiais** sem ferir a casca viva interna.\\n3. **Reunir 100g de volume**: Junte aproximadamente **o volume de um punho (cerca de 100g)** de resina limpa sobre uma folha larga.\\n4. **Descartar resíduos grossos**: Remova manualmente terra, agulhas secas ou lascas de casca antes de iniciar a fusão.\",\n      \"actionNote\": \"> Identificação e Coleta: Distinga o **Pinheiro** (casca avermelhada em placas de casco de tartaruga e agulhas em **pares de 2**, para resina) do **Carvalho** (casca escura com sulcos verticais profundos, folhas serrilhadas e bolotas, para carvão) usando o guia fotográfico abaixo. ([Machado de Pedra (PR-04)](/protocol-04.html) / [Forno de Carvão (PR-09)](/protocol-09.html))\",\n      \"svgFileName\": \"pr10-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // RAW PINE RESIN HARVESTING\",\n        \"Resina de pinheiro âmbar no tronco\",\n        \"Raspagem tangencial com lasca de pedra\",\n        \"Volume de um punho (~100g) coletado\",\n        \"[CHAVE] Priorizar nódulos duros e transparentes\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BOTANY\",\n        \"title\": \"Identificação Visual em Campo (Pinheiro vs. Carvalho) e Defesa Terpênica\",\n        \"text\": \"Pinheiros secretam resina rica em terpenos quando a casca se rompe para vedar feridas contra bactérias. O carvalho fornece madeira dura e densa que gera brasas intensas e o pó de carvão necessário para endurecer a resina.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"Pinheiro\",\n            \"scientificName\": \"Pinus densiflora\",\n            \"categoryTag\": \"Conífera(Softwood) / Resina e Isca\",\n            \"imageFileName\": \"id-pine-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-01A // MACRO OPTIC\",\n            \"hudStatus\": \"RESIN GLAND: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"CASCA\",\n                \"value\": \"Topo avermelhado; base rachada em **placas grossas em formato de casco de tartaruga**.\"\n              },\n              {\n                \"label\": \"FOLHA\",\n                \"value\": \"Agulhas verdes pontiagudas que **crescem sempre em pares de 2** (**8–14cm**).\"\n              },\n              {\n                \"label\": \"SINAL\",\n                \"value\": \"Gotas endurecidas de **resina âmbar dourada** em fendas do tronco e **pinhas** lenhosas.\"\n              }\n            ],\n            \"fieldUse\": \"Pomada antisséptica, cola impermeável (Pitch), lenha resinosa\"\n          },\n          {\n            \"name\": \"Carvalho\",\n            \"scientificName\": \"Quercus\",\n            \"categoryTag\": \"Madeira Dura(Hardwood) / Carvão Denso\",\n            \"imageFileName\": \"id-oak-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-01B // MACRO OPTIC\",\n            \"hudStatus\": \"FISSURE DEPTH: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"CASCA\",\n                \"value\": \"Superfície marrom-escura a acinzentada com **sulcos verticais profundos e ásperos**.\"\n              },\n              {\n                \"label\": \"FOLHA\",\n                \"value\": \"Folhas largas com **bordas onduladas ou dentes de serra bem definidos**.\"\n              },\n              {\n                \"label\": \"SINAL\",\n                \"value\": \"Presença de **bolotas e chapéus escamosos (cúpulas)** nos galhos ou no chão (**100%** seguro).\"\n              }\n            ],\n            \"fieldUse\": \"Pó de carvão endurecedor, carvão sem fumaça de alto calor, cabos de machado\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Passo 2: Derreter a resina em pedra usando calor indireto (sem chamas abertas)\",\n      \"description\": \"1. **Colocar resina no prato de pedra**: Empilhe os **100g de resina bruta** no centro de uma pedra ardósia côncava ou concha grande.\\n2. **Posicionar a 10cm das brasas**: Apoie o prato sobre pedras a cerca de **10cm ao lado das brasas incandescentes**, evitando fogo aberto.\\n3. **Fundir sob radiação suave**: Deixe o calor brando e o infravermelho liquefazerem a resina lentamente durante **5 a 8 minutos**.\\n4. **Verificar xarope dourado**: Confirme se os pedaços sólidos se dissolvem totalmente em um **líquido âmbar borbulhante e transparente**.\",\n      \"actionNote\": \"> Perigo de incêndio: Os vapores da resina contêm terpenos altamente inflamáveis. Nunca coloque o recipiente sobre chamas abertas de fogueira.\",\n      \"svgFileName\": \"pr10-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // GENTLE EMBER MELTING PROCESS\",\n        \"Resina líquida dourada em pedra côncava\",\n        \"Posicionada a 10cm ao lado das brasas\",\n        \"Barreira contra chamas e radiação suave\",\n        \"[CHAVE] 100% calor de brasas evita ignição\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PHARMACOLOGY\",\n        \"title\": \"Ação bactericida do alfa-pineno e derivados de terpenos\",\n        \"text\": \"O alfa-pineno e monoterpenos rompem as membranas celulares bacterianas, inibindo enzimas vitais. O aquecimento suave abaixo do ponto de fervura mantém esses compostos antimicrobianos intactos sem degradação térmica.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Passo 3: Peneirar resíduos de casca com pente de gravetos e separar a pomada\",\n      \"description\": \"1. **Confeccionar pente de gravetos**: Amarre gravetos finos lado a lado formando um **pente escumadeira de dentes finos**.\\n2. **Remover impurezas flutuantes**: Passe o pente na resina líquida para **capturar fragmentos de casca e fuligem**.\\n3. **Separar 30ml de pomada pura**: Despeje **um terço do líquido dourado purificado (cerca de 30ml)** em uma concha limpa ou pedra lisa.\\n4. **Esfriar em temperatura ambiente**: Deixe a concha descansar à sombra por **10 minutos** até engrossar em uma gelatina firme e antisséptica.\",\n      \"actionNote\": \"> Aplicação da pomada: Esfria como um gel firme. Aqueça uma porção com a ponta do dedo para aplicar sobre cortes, criando um curativo impermeável e bactericida.\",\n      \"svgFileName\": \"pr10-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DEBRIS REMOVAL & OINTMENT EXTRACTION\",\n        \"Pente de gravetos retirando cascas\",\n        \"Separação de 30ml de pomada antisséptica\",\n        \"Resfriamento na concha por 10 minutos\",\n        \"[CHAVE] Extrair pomada dourada antisséptica pura\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Passo 4: Misturar carvão 1:1 e temperar em bastão sólido de cola de piche\",\n      \"description\": \"1. **Adicionar carvão triturado**: Polvilhe aos poucos **50g de carvão de carvalho triturado** na resina quente restante no prato.\\n2. **Mexer rápido até engrossar**: Misture vigorosamente com um graveto por **1 a 2 minutos** até formar uma pasta preta brilhante.\\n3. **Enrolar na ponta do galho**: Gire a ponta de um galho grosso no piche quente, **moldando uma bola grossa e arredondada**.\\n4. **Resfriar em água fria**: Mergulhe a ponta em água fria ou resfrie ao ar por **5 minutos** para endurecer em uma cola dura como obsidiana.\",\n      \"actionNote\": \"> Proporção da mistura: Resina pura quebra como vidro. Uma mistura volumétrica estrita de 1:1 com carvão evita quebras mantendo a máxima fixação. ([Machado de Pedra (PR-04)](/protocol-04.html) / [Corda Selvagem (PR-05)](/protocol-05.html))\",\n      \"svgFileName\": \"pr10-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // CHARCOAL ADMIXTURE & PITCH STICK\",\n        \"Mistura 1:1 com carvão vegetal fino\",\n        \"Agitação rápida formando pasta viscosa\",\n        \"Aplicação no galho e têmpera de 5 min\",\n        \"[CHAVE] Bastão epóxi impermeável sem trincas\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD MATERIALS\",\n        \"title\": \"Superando a fragilidade por meio de micropartículas de carbono\",\n        \"text\": \"O breu de pinheiro puro sofre fratura frágil sob impacto. Dispersar micropartículas porosas de carbono (carvão) cria barreiras que barram trincas, transformando resina frágil em um epóxi natural robusto e 100% impermeável (Pitch Glue).\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Erro fatal: Aquecer a resina diretamente sobre as chamas abertas da fogueira\",\n    \"description\": \"A resina de pinheiro é rica em hidrocarbonetos terpênicos voláteis. Aquecer o prato diretamente no fogo libera densos vapores inflamáveis que explodem em labaredas intensas, destruindo toda a resina e causando queimaduras severas nas mãos e no rosto.\",\n    \"consequence\": \"Consequência: Perda total da resina e risco severo de queimaduras de segundo grau\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Um ferimento sem tratamento na mata pode causar infecção fatal em poucas horas! Aprenda a transformar resina de pinheiro em pomada e cola de pedra!\",\n    \"body\": \"Raspe a resina âmbar seca dos pinheiros e coloque em um prato de pedra! Nunca aqueça no fogo direto: use o calor indireto das brasas para não explodir! Peneire cascas flutuantes com um pente de gravetos e despeje uma porção em uma concha para virar uma pomada 100% antibacteriana. Misture carvão fino 1:1 no restante para criar um bastão de cola duro como obsidiana que fixa machados e repele água!\",\n    \"outro\": \"Descubra plantas e manuais de sobrevivência primitiva offline no link do perfil.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr10-outcome.svg\",\n    \"title\": \"Especificações da pomada antisséptica e cola impermeável de resina de pinheiro\",\n    \"description\": \"Especificações completas da pomada antimicrobiana em concha marinha, bastão de cola de piche em madeira dura e corte transversal da vedação impermeável no machado.\"\n  },\n  \"createdAt\": \"2026-10-16T11:40:00.000Z\",\n  \"contentHash\": \"db453b0037c7d451\"\n}","content/protocols/locales/10-pine-resin-pitch-glue.zh-TW.json":"{\n  \"protocolId\": \"PR-10\",\n  \"category\": \"MEDICINE\",\n  \"title\": \"熬製松脂傷口消毒軟膏與萬能防水硬膠（原始松脂提煉法）\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[阻斷野外細菌感染 ＆ 器具防水牢固結合]\",\n  \"summary\": \"在野外求生中，遭石片或枯枝劃傷若不及時消毒，極易引發細菌感染化膿甚至敗血症危及生命。此外，石斧握柄與陶器裂縫也迫切需要一種堅固防水的天然接著劑以承受重擊。將松樹分泌的天然松脂利用炭火餘熱溫和融化並濾除樹皮雜質，即可提煉出保護傷口的天然抗菌軟膏；若將剩餘松脂以**1:1**比例加入細炭粉均勻攪拌，冷卻後便能化為堅如磐石的萬能防水松脂膠棒（Pitch Glue）。\",\n  \"timeRequired\": \"40分鐘（松脂採集15分＋間接加熱融化15分＋炭粉調配塑形10分）\",\n  \"successRate\": \"95%（嚴禁直火加熱並嚴格遵守1:1炭粉比例）\",\n  \"difficulty\": \"簡易（需嚴防起火與高溫燙傷）\",\n  \"outputPerHour\": \"單次製作可得抗菌軟膏30ml＋防水膠棒2支\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"從老松樹幹採集的乾燥天然生松脂塊100g\",\n      \"desc\": \"如拳頭大小的琥珀色結晶塊。充分硬化且透明的凝塊雜質極少，融化後能提煉出純度極高的優質軟膏。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"凹陷石板盤或大型貝殼\",\n      \"desc\": \"天然耐熱容器，能隔絕明火直接接觸，並均勻吸收熱炭的紅外線輻射熱。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"細枝梳狀濾網與軟膏分裝貝殼\",\n      \"desc\": \"利用細密樹枝做成的梳子迅速撈除浮在表面的樹皮碎屑，並用乾淨貝殼分裝純淨軟膏。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"研磨成微細粉末的櫟木炭粉50g\",\n      \"desc\": \"消除冷卻松脂如玻璃般的脆弱易碎性，充當微觀交織的碳素強化骨架。\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"燒紅的硬木熱炭餘溫與攪拌硬木枝\",\n      \"desc\": \"不帶任何跳躍火苗，僅以純淨輻射熱安全液化松脂，防止高揮發性萜烯蒸氣閃燃。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"步驟1：從松樹幹採集乾燥硬化的琥珀色生松脂凝塊\",\n      \"description\": \"1. **尋找結晶松脂**：在老松樹幹或斷枝處尋找凝結成水滴狀的**乾燥琥珀色松脂塊**。\\n2. **石片輕輕刮取**：利用鋒利石片，在不切傷內部活性韌皮部的前提下，**僅輕刮表面凝塊**。\\n3. **備妥拳頭份量**：採集樹皮雜質較少的乾淨松脂，湊足**一拳頭份量（約100g）**放置於寬大葉片上。\\n4. **剔除粗糙異物**：在加熱前以手指預先揀除肉眼可見的泥土、乾松針與粗樹皮碎屑。\",\n      \"actionNote\": \"> 樹種識別與採集要領：請透過下方實拍圖鑑準確區分具有紅褐色龜甲樹皮與**2針一束松針**的**松樹**（採集松脂用），以及具有深縱裂黑褐樹皮、鋸齒葉與橡實的**橡樹/櫟樹**（製作炭粉硬化劑用）。乾硬透明的琥珀色松脂塊能煉出最純淨的軟膏。 ([石斧與石刃 (PR-04)](/protocol-04.html) / [地下炭窯 (PR-09)](/protocol-09.html))\",\n      \"svgFileName\": \"pr10-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // RAW PINE RESIN HARVESTING\",\n        \"松樹幹上凝固的琥珀色生松脂\",\n        \"利用石片切線刮取不傷樹皮\",\n        \"採集一拳頭份量（約100g）\",\n        \"[核心] 優先挑選硬化透明的松脂塊\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BOTANY\",\n        \"title\": \"野外核心樹種（松樹・橡樹）肉眼識別與萜烯防禦機制\",\n        \"text\": \"松樹外皮受損時會分泌富含萜烯的樹脂（Resin）以封閉傷口並阻絕細菌；而橡樹屬於組織緻密堅硬的闊葉硬木，悶燒後能提供克服松脂脆性的頂級碳粉與持久高溫炭火。\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"松樹（赤松）\",\n            \"scientificName\": \"Pinus densiflora\",\n            \"categoryTag\": \"針葉樹(Softwood) / 松脂・引火材\",\n            \"imageFileName\": \"id-pine-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-01A // MACRO OPTIC\",\n            \"hudStatus\": \"RESIN GLAND: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"樹皮/BARK\",\n                \"value\": \"樹幹上部呈紅褐色，下部則裂開成**龜甲狀的菱形厚鱗片**。\"\n              },\n              {\n                \"label\": \"葉片/LEAF\",\n                \"value\": \"從葉鞘基部**總是2根成束長出的尖銳常綠針葉**（長**8～14cm**）。\"\n              },\n              {\n                \"label\": \"特徵/SIGN\",\n                \"value\": \"樹幹傷口處凝結成淚滴狀的**金黃琥珀色松脂塊**，以及枝頭木質**松果**。\"\n              }\n            ],\n            \"fieldUse\": \"傷口消毒軟膏、萬能防水樹膠（Pitch）、高熱松明引火材\"\n          },\n          {\n            \"name\": \"橡樹 / 櫟樹\",\n            \"scientificName\": \"Quercus\",\n            \"categoryTag\": \"闊葉硬木(Hardwood) / 高密度炭・結構材\",\n            \"imageFileName\": \"id-oak-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-01B // MACRO OPTIC\",\n            \"hudStatus\": \"FISSURE DEPTH: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"樹皮/BARK\",\n                \"value\": \"深黑褐色至暗灰色表面，佈滿**縱向深邃且粗糙的垂直溝槽**。\"\n              },\n              {\n                \"label\": \"葉片/LEAF\",\n                \"value\": \"葉緣具有**明顯波浪狀或尖銳鋸齒**的手掌大小寬闊葉片。\"\n              },\n              {\n                \"label\": \"特徵/SIGN\",\n                \"value\": \"樹枝或樹根地面散落著**橡實（橡子）與鱗片狀帽殼（殼斗）**即可**100%**確認。\"\n              }\n            ],\n            \"fieldUse\": \"防水膠硬化用細炭粉、無煙高溫木炭、石斧木柄\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"步驟2：置於凹石盤利用熱炭餘熱溫和融化（嚴禁直火）\",\n      \"description\": \"1. **石盤中央堆放**：將採集的**100g生松脂塊**堆放在淺凹石板或大型貝殼中央。\\n2. **距炭火10cm處架設**：將石盤架在支撐石上，距離通紅炭火邊緣**約10cm處**，徹底避開跳躍明火。\\n3. **溫和輻射熱融化**：持續維持間接加熱**5至8分鐘**，讓松脂塊在溫和餘溫中漸漸融解。\\n4. **觀察金黃糖漿狀態**：確認固體塊狀完全溶解，轉變為**微冒氣泡的澄澈金黃液態糖漿**。\",\n      \"actionNote\": \"> 火災警告：松脂蒸氣富含高度易燃的揮發性油分。嚴禁直接放置於營火火苗上方，否則蒸氣將引發劇烈閃燃炸裂。\",\n      \"svgFileName\": \"pr10-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // GENTLE EMBER MELTING PROCESS\",\n        \"凹石盤中融化的金黃液態松脂\",\n        \"置於熱炭邊緣10cm間接加熱\",\n        \"阻絕明火並以溫和輻射熱融化\",\n        \"[核心] 100%餘溫融化嚴防閃燃起火\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PHARMACOLOGY\",\n        \"title\": \"α-蒎烯與萜烯分子的強效抑菌殺菌機理\",\n        \"text\": \"松脂的核心成分α-蒎烯與單萜能穿透細菌的脂質細胞膜，破壞其關鍵代謝酶活性。透過低於沸點的低溫間接加熱，可完全保留活性抗菌成分而不受熱解破壞。\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"步驟3：以細枝梳撈除浮渣樹皮並分裝純淨抗菌軟膏\",\n      \"description\": \"1. **製作細枝梳網**：將數根細木枝整齊排列綁定，製成一柄**細齒過濾梳**。\\n2. **撈除浮面雜質**：將細枝梳快速掃過融化松脂表面，**俐落撈出浮起之樹皮碎屑與炭灰**。\\n3. **分裝30ml純軟膏**：將澄澈金黃松脂液的**三分之一（約30ml）**單獨倒入乾淨貝殼或扁平石片中。\\n4. **常溫靜置冷卻**：移至陰涼通風處靜置**10分鐘**，待其冷卻凝固為可用手指塗抹的天然消毒軟膏。\",\n      \"actionNote\": \"> 軟膏塗抹法：冷卻後會形成富有彈性的膏體。受傷時取適量以體溫化開塗抹於傷口上，即成一層100%防水防菌的天然保護膜。\",\n      \"svgFileName\": \"pr10-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DEBRIS REMOVAL & OINTMENT EXTRACTION\",\n        \"細枝梳網濾除浮起樹皮雜質\",\n        \"分裝30ml傷口消毒專用純松脂液\",\n        \"倒入貝殼常溫靜置冷卻10分鐘\",\n        \"[核心] 萃取純淨金黃消毒軟膏單獨保存\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"步驟4：以1:1比例調入細炭粉並冷卻成堅固防水膠棒\",\n      \"description\": \"1. **撒入微細炭粉**：向石盤中剩餘的熱松脂緩緩倒入**50g研磨極細的櫟木炭粉**。\\n2. **高速攪拌均勻**：以木枝快速攪拌**1至2分鐘**，直到兩者完全融合成黏稠發亮的黑麥芽糖狀。\\n3. **纏裹於粗枝前端**：將拇指粗細之硬木枝尖端伸入膠液中反覆旋轉，**裹成一顆厚實圓球狀**。\\n4. **冷水驟冷硬化**：浸入冷溪水或置於冷空氣中淬火**5分鐘**，即凝固成如黑曜石般堅硬的萬能膠棒（Pitch Stick）。\",\n      \"actionNote\": \"> 配比關鍵：純松脂冷卻後如玻璃般易碎。嚴格維持1:1體積比加入炭粉，方能徹底消除脆性並發揮極致黏結強度。 ([石斧與石刃 (PR-04)](/protocol-04.html) / [野生繩索 (PR-05)](/protocol-05.html))\",\n      \"svgFileName\": \"pr10-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // CHARCOAL ADMIXTURE & PITCH STICK\",\n        \"依1:1比例加入細櫟木炭粉\",\n        \"木枝高速攪拌成黏稠黑膠\",\n        \"纏裹於木枝端部淬冷硬化5分鐘\",\n        \"[核心] 鍛造無裂紋之天然防水環氧膠棒\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD MATERIALS\",\n        \"title\": \"添加碳微粒消除脆性與天然環氧樹脂化\",\n        \"text\": \"純松香受外力衝擊極易發生災難性脆性斷裂。將微孔碳素（炭粉）均勻分散於樹脂中可形成阻偏裂紋的微觀骨架，使脆弱松脂轉化為抗衝擊且100%防水的原始天然環氧樹脂（Pitch Glue）。\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命錯誤：為求速融而將松脂石盤直接架在營火明火上\",\n    \"description\": \"松脂飽含高度易燃之萜烯烴化合物。若將石盤直接置於熊熊烈火上，高溫將促使氣化油氣瞬間爆發性閃燃，不僅將所有寶貴松脂燒成灰燼，更會造成臉部與雙手的嚴重深層燙傷。\",\n    \"consequence\": \"後果：松脂全毀且面部與雙手面臨二級嚴重燒燙傷極高風險\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"野外割傷如果不消毒，幾小時內就會引發敗血症！用松樹松脂自製抗生素與石膠的絕技！\",\n    \"body\": \"從松樹刮下乾燥琥珀松脂放在凹石上！千萬別直接用火燒：利用炭火餘熱溫和融化才不會爆炸！用樹枝梳撈除樹皮雜質，分裝到貝殼放涼就是100%阻絕細菌的消毒軟膏。剩下的松脂以1:1拌入細炭粉裹在木棒上放涼，就能做出如黑曜石般堅硬、牢牢固定石斧且完全防水的萬能膠棒！\",\n    \"outro\": \"文明崩潰時亦能離線運行的原始生存藍圖，請至個人檔案連結免費查閱。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr10-outcome.svg\",\n    \"title\": \"熬製完成之松脂抗菌消毒軟膏與萬能防水膠棒技術諸元\",\n    \"description\": \"貝殼內金黃澄澈的天然抗菌保護軟膏、混合櫟木炭粉裹於硬木端部之黑曜石光澤膠棒，以及石斧握柄接合處完全防水之斷面構造技術圖解。\"\n  },\n  \"createdAt\": \"2026-10-16T11:40:00.000Z\",\n  \"contentHash\": \"db453b0037c7d451\"\n}","content/protocols/locales/11-willow-funnel-fish-trap.de.json":"{\n  \"protocolId\": \"PR-11\",\n  \"category\": \"FOOD\",\n  \"title\": \"Flechten einer Einweg-Weidenreuse (Fischreuse) für passiven Fischfang im Fluss\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[PASSIVE PROTEINQUELLE & KRAFTERHALT]\",\n  \"summary\": \"Schnelle Fische mit bloßen Händen oder einem Holzspeer zu jagen, verbrennt wertvolle Kalorien und scheitert in über 90% der Fälle. Wenn Sie biegsame Weidenruten am Flussufer zu einem konischen Korb mit einem nach innen verengten Rückschlag-Trichter flechten, schwimmen Fische der Duftspur nach hinein und werden beim Umkehrversuch von den elastischen Rutenspitzen blockiert. In einer Flussstromschnelle verankert, fängt die Reuse im Schlaf zuverlässig Fische.\",\n  \"timeRequired\": \"50 Min. (10m Weidenruten schneiden + 25m Ringe & Korb flechten + 15m Trichter & Verankerung)\",\n  \"successRate\": \"92% (bei 3-Finger-Trichteröffnung & Ausrichtung gegen die Strömung)\",\n  \"difficulty\": \"Mittel (Vorsicht vor zurückschnellenden Rutenspitzen & glatten Steinen)\",\n  \"outputPerHour\": \"3–8 Süßwasserfische passiv über Nacht pro Einsatz\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"40–50 biegsame grüne Weiden- oder Haselruten (Armlänge, 70–80cm)\",\n      \"desc\": \"Frisch am Ufer mit einer [Steinaxt oder scharfen Steinklinge](/protocol-04.html) geschnittene Triebe von halber Kleinfingerdicke (~5mm), die sich biegen lassen, ohne zu brechen.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"4 dickere Weidenäste oder Ranken für die Stützringe (Reifen)\",\n      \"desc\": \"Bleistiftdicke (~8–10mm) grüne Zweige, die zu kreisrunden Ringen gebogen werden, um den Kegelkorb gegen den Wasserdruck offenzuhalten.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Wasserfeste Wildkudzu- oder Bastfaserschnur (15m Gesamtlänge)\",\n      \"desc\": \"Gedrehte Pflanzenschnur nach [Herstellung von Wildseilen](/protocol-05.html). Das Versiegeln der Hauptknoten mit [Wasserfestem Kiefernharz-Kleber](/protocol-10.html) verhindert ein Lösen unter Wasser.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"2 faustgroße Flusssteine als Ballast & 4 unterarmlange Holzpflöcke\",\n      \"desc\": \"Schwere Flusskiesel, um die schwimmfähige Reuse am Grund zu halten, sowie Holzpflöcke gegen das Wegrollen in der Strömung.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"1 Handvoll zerdrückte Flussschnecken oder Ufer-Regenwürmer\",\n      \"desc\": \"Natürlicher Duftköder in einem durchstochenen Laubblatt, der Aminosäuren stromabwärts verströmt und Fische ins Innere lockt.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Schritt 1: Dicke Zweige zu 4 abgestuften Kreisringen (Reifen) biegen\",\n      \"description\": \"1. **Biegsamkeit prüfen**: Biegen Sie 4 bleistiftdicke Weidenzweige langsam mit der Hand, um sicherzustellen, dass sie sich geschmeidig runden lassen.\\n2. **4 abgestufte Ringgrößen formen**: Biegen Sie die Zweige zu vier Ringen mit **anderthalb Handspannen (25cm Durchmesser)**, **einer Handspanne (20cm)**, **zwei Faustbreiten (15cm)** und **einer Faustbreite (10cm)**.\\n3. **Überlappende Enden abbinden**: Legen Sie die Ringenden um **zwei Fingerbreiten (~4cm)** übereinander und umwickeln Sie sie fest mit mindestens 10 Windungen [Wilder Bastschnur](/protocol-05.html).\\n4. **Im Abstand von 1 Handspanne ausrichten**: Stellen Sie die vier Ringe der Größe nach im Abstand von **einer Handspanne (~15cm)** hintereinander auf.\",\n      \"actionNote\": \"> Materialkennung & Augenschutz: Trockenes Totholz bricht splitternd und kann Augen oder Hände verletzen. Nutzen Sie die Fotokarte unten zur sicheren Unterscheidung von **lebenden Weidenruten** und **Flussschnecken-Ködern** ([Steinaxt (PR-04)](/protocol-04.html) / [Wildseil (PR-05)](/protocol-05.html)).\",\n      \"svgFileName\": \"pr11-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // GRADUATED HOOP RINGS (4 SIZES)\",\n        \"1. Großer Frontring (1.5 Spannen / 25cm)\",\n        \"2. Zwei Mittelringe (20cm & 15cm Dia)\",\n        \"3. Kleiner Endring (1 Faust / 10cm Dia)\",\n        \"4. Bastschnur-Wicklung (15cm Abstand)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BOTANY\",\n        \"title\": \"Biegeelastizität der Uferweide & Duftfahnen aquatischer Köder\",\n        \"text\": \"Uferweiden (Salix) besitzen lange Zellulosefasern und hohen Saftgehalt, was enges Biegen ohne Bruch sowie hohe Fäulnisresistenz im Wasser ermöglicht. Zerdrückte Flussschnecken setzen wasserlösliche Aminosäuren frei, die mit der Strömung als Lockspur driften.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"Lebende Uferweidenrute\",\n            \"scientificName\": \"Salix koreensis / Salix alba\",\n            \"categoryTag\": \"Ufer-Laubholz / Hochelastischer Rahmen\",\n            \"imageFileName\": \"id-willow-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-11A // MACRO OPTIC\",\n            \"hudStatus\": \"FLEX ELASTICITY: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"ZWEIG/TWIG\",\n                \"value\": \"Schlanke gelbgrüne bis glatte braune Ruten, die sich **ohne zu brechen in eine enge U-Schlaufe biegen lassen**.\"\n              },\n              {\n                \"label\": \"BLATT/LEAF\",\n                \"value\": \"Schmale **lanzettförmige grüne Blätter (5–12cm lang)** mit fein gesägtem Rand.\"\n              },\n              {\n                \"label\": \"MERKMAL/SIGN\",\n                \"value\": \"Wächst auf feuchten Kiesbänken am Fluss; beim Ankratzen der Rinde strömt ein **frischer, herber Salicyl-Duft** aus.\"\n              }\n            ],\n            \"fieldUse\": \"Fischreusen-Geflecht, elastische Bogenstäbe, schmerzstillender Weidenrindentee\"\n          },\n          {\n            \"name\": \"Flussschnecken- & Wurmköder\",\n            \"scientificName\": \"Semisulcospira / Lumbricina\",\n            \"categoryTag\": \"Aquatischer Köder / Duftlockstoff\",\n            \"imageFileName\": \"id-river-snail-bait.jpg\",\n            \"hudCode\": \"FIG. BIO-11B // MACRO OPTIC\",\n            \"hudStatus\": \"SCENT PLUME: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"GEHÄUSE/SHELL\",\n                \"value\": \"Dunkle **kegelförmige Spiralschnecken (1.5–3cm)** an der Unterseite bemooster Flusssteine.\"\n              },\n              {\n                \"label\": \"AUFBRECHEN/CRUSH\",\n                \"value\": \"Die Schale mit einem Kiesel **nur leicht anknacken**, damit der Gewebesaft über 3+ Stunden langsam austritt.\"\n              },\n              {\n                \"label\": \"ERSATZ/ALT\",\n                \"value\": \"Alternativ im feuchten Uferschlamm oder unter Laub nach **roten Regenwürmern oder Grashüpfern** graben.\"\n              }\n            ],\n            \"fieldUse\": \"Lockköder für Fischreusen, Angelköder, abgekochte Notnahrung\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Schritt 2: 30–40 gerade Weidenruten längs zum konischen Korpus verflechten\",\n      \"description\": \"1. **Längsstreben gleichmäßig anlegen**: Legen Sie 30–40 gerade, armlange (70–80cm) Weidenruten außen um die vier Ringe im Abstand von **einer Fingerbreite (~1–1.5cm)** an.\\n2. **Kreuzungspunkte festbinden**: Wickeln Sie eine lange Bastschnur fest um jede Kreuzung, an der eine Längsrute auf einen Kreisring trifft.\\n3. **Kegelform spannen**: Ziehen Sie die Längsruten vom weiten 25cm-Frontring zum engen 10cm-Endring gleichmäßig zusammen.\\n4. **Hecköffnung mit Schleifenknoten schließen**: Bündeln Sie die überstehenden Rutenspitzen hinter dem kleinsten Ring mit einem **lösbaren Zugknoten** zur späteren Fischentnahme.\",\n      \"actionNote\": \"> Strebenabstand: Wenn die Lücken breiter als ein Finger (1.5cm) sind, schlüpfen Fische seitlich heraus. Flechten Sie das Gitter so eng, dass nur Ihre Fingerspitze hindurchpasst.\",\n      \"svgFileName\": \"pr11-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // CONICAL WICKER BODY WEAVING\",\n        \"30-40 Weiden-Längsstreben (1-1.5cm Spalt)\",\n        \"Kreuzwicklung an allen 4 Stützringen\",\n        \"Stromlinien-Kegel (-70% Strömungsdruck)\",\n        \"[KERN] Lösbarer Zugknoten am Heck zur Entnahme\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD MECHANICS\",\n        \"title\": \"Reduzierung des Strömungswiderstands durch konische Gitter\",\n        \"text\": \"Ein Längsgitter mit 1–1.5cm Spaltweite lässt die Flussströmung nahezu ungehindert passieren, reduziert den Strömungsdruck (Drag) um **über 70%** und hält dennoch jeden Fisch ab **2cm** Körperbreite sicher zurück.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Schritt 3: Nach innen verengten Einweg-Trichter (Rückschlagventil) einnähen\",\n      \"description\": \"1. **Trichterruten bündeln**: Fassen Sie **16–20 dünne, federnde Weidenzweiglein** (Unterarmlänge, ~30–35cm) zu einem kleineren Kegel zusammen.\\n2. **Ein- und Ausgangsdurchmesser einstellen**: Weiten Sie den vorderen Rand auf **anderthalb Handspannen (25cm)** passend zum Korbmaul und verengen Sie den inneren Hals auf **drei Fingerbreiten (5–6cm)**.\\n3. **Innere Rutenspitzen frei lassen**: Lassen Sie die letzten **zwei Fingerbreiten (5cm)** der inneren Spitzen ungebunden, damit sie sich beim Hineinschwimmen spreizen und beim Rückwärtsversuch wie Dornen sperren.\\n4. **In die Korböffnung einsetzen & vernähen**: Schieben Sie den Trichter in die vordere Korböffnung und nähen Sie beide Außenringe mit [Wildseil](/protocol-05.html) lückenlos zusammen.\",\n      \"actionNote\": \"> Trichterhals-Maß: Ist die innere Öffnung größer als eine Faust, schwimmen die Fische wieder hinaus. Halten Sie den Durchlass auf drei Fingerbreiten (5–6cm), damit die federnden Spitzen als Einwegventil wirken.\",\n      \"svgFileName\": \"pr11-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // ONE-WAY INVERTED FUNNEL VALVE\",\n        \"Trichter-Außenring an 25cm-Maul vernäht\",\n        \"Federnde innere Rutenspitzen (5-6cm Hals)\",\n        \"Spreizt beim Eintritt & sperrt Rückweg\",\n        \"[KERN] Einweg-Eintritt & Null Rückwärtsflucht\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PHYSICS\",\n        \"title\": \"Elastische Kragarm-Rückschlagventil-Geometrie\",\n        \"text\": \"Schwimmt ein Fisch vorwärts in den Trichter, drückt sein stromlinienförmiger Kopf die federnden Weidenspitzen leicht auseinander. Im Fangraum angekommen, verfängt sich jeder Rückwärtsversuch an den spitz zusammenlaufenden Rutenenden.\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Schritt 4: Ballaststeine & Köder einlegen und mit Pflöcken in der Strömung verankern\",\n      \"description\": \"1. **Ballast & Köderbeutel laden**: Öffnen Sie den Heckknoten, legen Sie **2 faustgroße Flusssteine** und ein perforiertes Blatt mit **zerdrückten Schnecken & Würmern** hinein und binden Sie das Heck wieder fest zu.\\n2. **Strömungsrinne wählen**: Suchen Sie eine knietiefe (**30–50cm**) Engstelle zwischen Flussfelsen oder am Uferbewuchs.\\n3. **Trichteröffnung stromaufwärts richten**: Versenken Sie die Reuse so am Grund, dass die **Trichteröffnung stromaufwärts (oder schräg gegen die Strömung)** zeigt, damit der Köderduft stromabwärts zu den Fischen treibt.\\n4. **Mit 4 Pflöcken & Steinen sichern**: Schlagen Sie **4 unterarmlange Holzpflöcke** beidseitig tief in das Flussbett und verkeilen Sie schwere Steine an den Flanken gegen das Wegrollen.\",\n      \"actionNote\": \"> Entnahme & Garvorschrift: Am Morgen einfach den Heckknoten aufziehen. Süßwasserfische zum Schutz vor Parasiten immer über einem [Rauchfreien Dakota-Erdofen](/protocol-06.html) oder [Eichenholzkohle-Glut](/protocol-09.html) vollständig durchgaren.\",\n      \"svgFileName\": \"pr11-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // STREAM CHANNEL ANCHORING & BAIT PLUME\",\n        \"2 Ballaststeine & Schneckenköder im Inneren\",\n        \"Strömungsrichtung & Duftspur stromabwärts\",\n        \"4 Holzpflöcke & seitliche Stützfelsen\",\n        \"[KERN] Fische folgen Duft stromaufwärts in Reuse\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD ECOLOGY\",\n        \"title\": \"Positive Rheotaxis und Duftspur-Verfolgung bei Flussfischen\",\n        \"text\": \"Süßwasserfische zeigen **positive Rheotaxis**: Sie stellen sich instinktiv mit dem Kopf gegen die Strömung, um die Kiemenatmung zu optimieren und abtreibende Nahrung aufzunehmen. Treibt der Schneckenduft aus der Reuse stromabwärts, folgen die Fische der Spur direkt in den Trichter.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Tödlicher Fehler: Die schwimmfähige Reuse ohne Ballaststeine auslegen oder rohen Süßwasserfisch essen\",\n    \"description\": \"Weidenholz schwimmt; ohne schwere Steine im Inneren und 4 verankerte Holzpflöcke reißt die Strömung Ihre Reuse in wenigen Minuten fort. Zudem führt der Verzehr von rohem Süßwasserfisch zu schweren Infektionen durch Leberegel und Bakterien.\",\n    \"consequence\": \"Folge: Totalverlust der Fischreuse in der Strömung oder schwere Parasiten-/Bakterieninfektion\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Verschwenden Sie keine Kraft bei der Fischjagd mit der Hand! Flechten Sie diese Weidenreuse, die im Schlaf Fische fängt!\",\n    \"body\": \"Biegen Sie grüne Weidenzweige zu vier abgestuften Ringen von anderthalb Handspannen bis Faustgröße. Binden Sie 40 gerade Weidenruten im Fingerabstand längs darüber. Der Trick ist der nach innen gerichtete Trichter mit drei Finger breitem Durchlass! Zwei Steine und zerdrückte Flussschnecken hineinlegen und im knietiefen Wasser mit Pflöcken sichern!\",\n    \"outro\": \"Fische folgen dem Duft durch die federnden Spitzen und kommen nie wieder heraus. Kompletter Bauplan im Profil-Link!\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr11-outcome.svg\",\n    \"title\": \"Fertige Einweg-Weidenreuse & Unterwasser-Querschnitt in der Strömungsrinne\",\n    \"description\": \"Längsschnitt durch die 4 abgestuften Ringe, das 1cm-Weidengitter, den 5cm-Rückschlagtrichter, 2 Ballaststeine, Schneckenköderbeutel und 4 Bodenpflöcke mit gefangenem Fisch.\"\n  },\n  \"createdAt\": \"2026-10-16T13:38:00.000Z\",\n  \"contentHash\": \"037d4ce0763a3aa2\"\n}","content/protocols/locales/11-willow-funnel-fish-trap.en.json":"{\n  \"protocolId\": \"PR-11\",\n  \"category\": \"FOOD\",\n  \"title\": \"Weaving a One-Way Willow Funnel Fish Trap for Passive Stream Fishing\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[PASSIVE PROTEIN HARVEST & CALORIE CONSERVATION]\",\n  \"summary\": \"Chasing swift fish by hand or with a wooden spear drains vital calories and fails over 90% of the time. By weaving flexible riverside willow shoots into a conical basket fitted with an inward-narrowing check-valve funnel, fish follow the scent trail inside and are blocked from backing out by converging twig tips. Anchored in a stream riffle, it passively harvests fish while you sleep or build shelter.\",\n  \"timeRequired\": \"50 mins (10m willow cutting + 25m frame & rib weaving + 15m funnel lock & stream anchoring)\",\n  \"successRate\": \"92% (with 3-finger inner funnel throat & upstream channel alignment)\",\n  \"difficulty\": \"Medium (watch for springing twig ends & slippery river stones)\",\n  \"outputPerHour\": \"3–8 freshwater fish captured passively overnight per deployment\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"40–50 flexible green willow or hazel shoots (forearm-to-arm length, 70–80cm)\",\n      \"desc\": \"Freshly cut shoots about half the thickness of a pinky finger (~5mm) harvested along the riverbank using a [Stone Axe or Sharp Stone Flake](/protocol-04.html). Select live green shoots that bend without snapping.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"4 thicker willow branches or vines for structural hoop rings\",\n      \"desc\": \"Pencil-thick (~8–10mm) green branches coiled into circular hoops to hold the conical body open against water pressure.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Water-resistant wild kudzu or inner bark cordage (15m total length)\",\n      \"desc\": \"Twisted plant fiber cordage made via [Wild Bast Fiber Cordage](/protocol-05.html). Sealing main hoop knots with [Waterproof Pine Pitch Glue](/protocol-10.html) prevents loosening underwater.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"2 fist-sized river ballast stones & 4 forearm-length wooden anchor stakes\",\n      \"desc\": \"Heavy river cobbles to sink the buoyant wicker trap flat on the riverbed, plus wooden stakes to pin it against rolling in strong current.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"1 handful of crushed freshwater snails or riverbank earthworms\",\n      \"desc\": \"Natural olfactory bait wrapped in a pierced green leaf to release amino-acid scent trails downstream and lure fish inside.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Step 1: Coil Thick Branches into 4 Graduated Circular Hoop Rings\",\n      \"description\": \"1. **Test Green Shoot Flexibility**: Slowly bend 4 pencil-thick willow branches by hand to verify they curve smoothly into a circle without cracking.\\n2. **Form 4 Graduated Hoop Sizes**: Coil the branches into four circular rings measuring **1.5 hand-spans (25cm diameter)**, **1 hand-span (20cm)**, **two-fist width (15cm)**, and **one-fist width (10cm)**.\\n3. **Lash Overlapping Ends**: Overlap the ends of each ring by **two finger-widths (~4cm)** and bind tightly with 10+ wraps of [Wild Bast Cordage](/protocol-05.html).\\n4. **Align at 1-Span Intervals**: Lay the four rings in descending order spaced **one hand-span (~15cm) apart** to establish the conical taper.\",\n      \"actionNote\": \"> Material ID & Eye Safety: Brittle dead twigs snap sharply and can injure your hands or eyes. Use the macro field guide below to identify flexible live **Stream Willow** shoots and **Freshwater Snail Bait** ([Stone Axe (PR-04)](/protocol-04.html) / [Wild Cordage (PR-05)](/protocol-05.html)).\",\n      \"svgFileName\": \"pr11-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // GRADUATED HOOP RINGS (4 SIZES)\",\n        \"1. Front Mouth Hoop (1.5 Spans / 25cm Dia)\",\n        \"2. Two Middle Hoops (20cm & 15cm Dia)\",\n        \"3. Tail Ring Hoop (1 Fist / 10cm Dia)\",\n        \"4. Cordage Lashing (15cm Spacing Interval)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BOTANY\",\n        \"title\": \"Willow Shoot Flexural Elasticity & Aquatic Bait Scent Plumes\",\n        \"text\": \"Riparian willow (Salix) possesses long cellulose fibers and high sap moisture, allowing tight circular bending without fracture and high rot resistance underwater. Crushed freshwater snails release water-soluble amino acids that disperse downstream as a powerful chemotactic lure.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"Stream Willow Shoot\",\n            \"scientificName\": \"Salix koreensis / Salix alba\",\n            \"categoryTag\": \"Riparian Hardwood / High-Flex Trap Frame\",\n            \"imageFileName\": \"id-willow-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-11A // MACRO OPTIC\",\n            \"hudStatus\": \"FLEX ELASTICITY: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"TWIG\",\n                \"value\": \"Slender yellowish-green to smooth brown shoots that **bend into a full U-loop without snapping or splintering**.\"\n              },\n              {\n                \"label\": \"LEAF\",\n                \"value\": \"Narrow **lance-shaped green leaves (5–12cm long)** with finely serrated edges and pale undersides.\"\n              },\n              {\n                \"label\": \"SIGN\",\n                \"value\": \"Grows along wet gravel bars and stream edges; scraping the green inner bark releases a **crisp herbal salicylate scent**.\"\n              }\n            ],\n            \"fieldUse\": \"Conical fish traps, flexible bow-drill bows, willow bark pain-relief infusion\"\n          },\n          {\n            \"name\": \"Freshwater Snail & Worm Bait\",\n            \"scientificName\": \"Semisulcospira / Lumbricina\",\n            \"categoryTag\": \"Aquatic Bait / Chemo-Attractant\",\n            \"imageFileName\": \"id-river-snail-bait.jpg\",\n            \"hudCode\": \"FIG. BIO-11B // MACRO OPTIC\",\n            \"hudStatus\": \"SCENT PLUME: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"SHELL\",\n                \"value\": \"Dark **conical spiral shells (1.5–3cm)** clinging to the underside of wet, mossy stream rocks.\"\n              },\n              {\n                \"label\": \"CRUSH\",\n                \"value\": \"Lightly **crack the shell with a pebble** so tissue fluids seep out slowly over 3+ hours in moving water.\"\n              },\n              {\n                \"label\": \"ALT\",\n                \"value\": \"If snails are scarce, dig under damp riverbank leaf litter for **red earthworms or grasshoppers** wrapped in a pierced leaf.\"\n              }\n            ],\n            \"fieldUse\": \"Fish trap scent bait, gorge hook bait, boiled emergency survival protein\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Step 2: Weave 30–40 Straight Willow Shoots Longitudinally into a Conical Body\",\n      \"description\": \"1. **Space Longitudinal Ribs**: Arrange 30–40 straight arm-length (70–80cm) willow shoots around the outside of the four hoops at **one finger-width (~1–1.5cm) intervals**.\\n2. **Cross-Lash Every Intersection**: Weave a long strand of bark cordage tightly around each junction where a longitudinal shoot crosses a circular hoop.\\n3. **Taper the Cone Smoothly**: Draw the straight ribs inward gradually from the wide 25cm mouth ring down to the narrow 10cm tail ring.\\n4. **Tie Quick-Release Tail Knot**: Gather the protruding shoot tips behind the smallest tail ring and bind them with a **slip-loop knot** that unties easily for fish retrieval.\",\n      \"actionNote\": \"> Rib Spacing Rule: If gaps between ribs exceed one finger-width (1.5cm), trapped fish will wriggle out sideways. Keep the lattice tight enough that only your fingertip fits through.\",\n      \"svgFileName\": \"pr11-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // CONICAL WICKER BODY WEAVING\",\n        \"30-40 Willow Ribs (1-1.5cm Finger Gap)\",\n        \"Cross-Lashing at All 4 Hoop Junctions\",\n        \"Streamlined Cone Cuts Water Drag by 70%\",\n        \"[KEY] Slip-Loop Tail Knot for Easy Emptying\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD MECHANICS\",\n        \"title\": \"Hydrodynamic Drag Reduction Across a Conical Lattice\",\n        \"text\": \"A 1–1.5cm longitudinal rib grid allows stream current to pass freely with minimal turbulence, reducing hydrodynamic drag by **over 70%** while physically retaining any freshwater fish wider than **2cm**.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Step 3: Build the Inward-Narrowing Funnel Valve and Sew into the Mouth\",\n      \"description\": \"1. **Assemble Funnel Tines**: Gather **16–20 slender, springy willow twigs** (forearm length, ~30–35cm) into a smaller cone.\\n2. **Set Outer & Inner Diameters**: Flare the front opening to **1.5 hand-spans (25cm)** to match the main basket mouth, tapering the inner throat down to **three fingers wide (5–6cm)**.\\n3. **Leave Inner Tine Tips Unbound**: Leave the final **two finger-widths (5cm)** of the inner twig tips untied so they flex apart when a fish pushes inward and spring shut behind it.\\n4. **Insert & Lash to Basket Mouth**: Push the funnel cone inside the wide front opening of the main body and stitch both outer rims tightly together with [Wild Cordage](/protocol-05.html).\",\n      \"actionNote\": \"> Throat Gauge: If the inner funnel opening is wider than your fist, fish will swim back out. Keep the throat at a three-finger bundle width (5–6cm) so the springy tips act as a one-way valve.\",\n      \"svgFileName\": \"pr11-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // ONE-WAY INVERTED FUNNEL VALVE\",\n        \"Funnel Outer Rim Lashed to 25cm Mouth\",\n        \"Flexible Unbound Inner Tips (5-6cm Throat)\",\n        \"Flexes Open on Entry & Blocks Reversal\",\n        \"[KEY] One-Way Entry & Zero Reverse Escape\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PHYSICS\",\n        \"title\": \"Elastic Cantilever Check-Valve Geometry\",\n        \"text\": \"As a fish swims forward into the narrowing cone, its streamlined head easily deflects the cantilevered willow tips outward. Once inside the holding chamber, any attempt to swim backward catches against the converging sharp twig ends.\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Step 4: Load Ballast Stones & Bait, Then Anchor in a Stream Riffle\",\n      \"description\": \"1. **Load Ballast & Bait Pouch**: Untie the tail knot, place **2 fist-sized river stones** and a pierced leaf pouch of **crushed snails & worms** inside, then retie the tail securely.\\n2. **Select Riffle Channel**: Locate a knee-deep (**30–50cm**) stream constriction between boulders or along undercut bank vegetation where fish funnel naturally.\\n3. **Aim Funnel Into Current**: Submerge the trap on the riverbed with the **funnel mouth facing upstream (or diagonally across the current)** so bait scent washes downstream into approaching fish.\\n4. **Pin with 4 Stakes & Side Rocks**: Drive **4 forearm-length wooden stakes** firmly into the riverbed on both sides of the basket and wedge heavy stones against the flanks so strong current cannot roll the trap.\",\n      \"actionNote\": \"> Harvest & Cooking Safety: In the morning, pull the tail slip-knot to empty your catch. Always cook freshwater fish thoroughly over a [Dakota Smokeless Fire](/protocol-06.html) or [Oak Charcoal Embers](/protocol-09.html) to eliminate waterborne parasites.\",\n      \"svgFileName\": \"pr11-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // STREAM CHANNEL ANCHORING & BAIT PLUME\",\n        \"2 Internal Ballast Stones & Crushed Snail Bait\",\n        \"Downstream Scent Plume & Current Direction\",\n        \"4 Wooden Riverbed Stakes & Side Boulders\",\n        \"[KEY] Fish Swim Upstream Into Funnel & Lock Inside\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD ECOLOGY\",\n        \"title\": \"Positive Rheotaxis and Olfactory Plume Tracking in Stream Fish\",\n        \"text\": \"Freshwater stream fish exhibit **positive rheotaxis**—instinctively orienting head-first into oncoming current to maximize gill oxygenation and intercept drifting food. When crushed snail amino acids drift downstream from an upstream-facing funnel, fish track the scent plume straight into the valve.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Fatal Mistake: Deploying the buoyant wicker trap without internal ballast stones or eating raw freshwater fish\",\n    \"description\": \"Willow wood is naturally buoyant; without heavy internal ballast stones and 4 riverbed stakes, stream currents will sweep your trap away within minutes. Furthermore, eating raw freshwater fish exposes you to liver flukes and severe bacterial dysentery.\",\n    \"consequence\": \"Consequence: Complete loss of the fish trap in the current or debilitating parasitic/bacterial infection\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Stop wasting calories chasing fish by hand! Weave this one-way willow funnel trap that catches fish while you sleep!\",\n    \"body\": \"Coil green willow branches into four graduated hoops from one-and-a-half hand-spans down to fist size. Lash 40 straight willow shoots across the hoops spaced one finger-width apart. Now build a small inverted cone with a three-finger throat and lash it inside the front mouth! Drop two fist-sized rocks and crushed river snails inside, then stake it in a knee-deep stream channel!\",\n    \"outro\": \"Fish follow the scent in through the flexible twig tips and can never swim back out. Check the full blueprint in the profile link!\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr11-outcome.svg\",\n    \"title\": \"Completed One-Way Willow Funnel Fish Trap & Submerged Stream Cutaway Spec\",\n    \"description\": \"Longitudinal cutaway showing the 4 graduated hoops, 1cm-spaced willow rib cone, inward-converging 5cm check-valve funnel tips, 2 internal ballast cobbles, crushed snail bait pouch, and 4 riverbed anchor stakes holding captured fish.\"\n  },\n  \"createdAt\": \"2026-10-16T13:38:00.000Z\",\n  \"contentHash\": \"037d4ce0763a3aa2\"\n}","content/protocols/locales/11-willow-funnel-fish-trap.es.json":"{\n  \"protocolId\": \"PR-11\",\n  \"category\": \"FOOD\",\n  \"title\": \"Cómo Tejer una Nasa de Sauce con Embudo Unidireccional para Capturar Peces\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[PROTEÍNA PASIVA Y AHORRO DE ENERGÍA]\",\n  \"summary\": \"Perseguir peces veloces a mano o con lanza agota tus calorías vitales y falla más del 90% de las veces. Al tejer ramas flexibles de sauce ribereño en una cesta cónica con un embudo invertido unidireccional, los peces siguen el rastro de olor hacia adentro y quedan bloqueados por las puntas elásticas al intentar retroceder. Anclada en la corriente del río, captura peces sola mientras duermes o construyes tu refugio.\",\n  \"timeRequired\": \"50 min (10m corte de sauce + 25m tejido de aros y cuerpo + 15m embudo y anclaje en río)\",\n  \"successRate\": \"92% (manteniendo boca interior de 3 dedos y orientación aguas arriba)\",\n  \"difficulty\": \"Media (precaución con puntas de ramas en los ojos y piedras resbaladizas)\",\n  \"outputPerHour\": \"3–8 peces de agua dulce capturados pasivamente por noche\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"40–50 varas verdes flexibles de sauce o avellano (largo de brazo, 70–80cm)\",\n      \"desc\": \"Ramas verdes recién cortadas en la orilla con un [Hacha de Piedra o Lasca Afilada](/protocol-04.html), de la mitad del grosor de un meñique (~5mm), que se doblen sin romperse.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"4 ramas gruesas de sauce o lianas para los aros estructurales\",\n      \"desc\": \"Cuatro ramas verdes del grosor de un lápiz (~8–10mm) enrolladas en círculos para sostener la forma cónica de la nasa.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Cuerda resistente al agua de corteza interna de kudzu (15m en total)\",\n      \"desc\": \"Cordel vegetal trenzado mediante [Cuerda Salvaje de Fibras](/protocol-05.html). Sellar los nudos principales con [Pegamento Impermeable de Resina de Pino](/protocol-10.html) evita que se aflojen bajo el agua.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"2 piedras de río del tamaño de un puño y 4 estacas de madera del largo del antebrazo\",\n      \"desc\": \"Cantos rodados pesados para hundir la nasa en el lecho del río y estacas para fijarla contra la corriente.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"1 puñado de caracoles de río machacados o lombrices de tierra\",\n      \"desc\": \"Cebo natural envuelto en una hoja ancha perforada para liberar olor aguas abajo y atraer peces al interior.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Paso 1: Enrollar Ramas Gruesas en 4 Aros Circulares de Tamaño Gradual\",\n      \"description\": \"1. **Probar Elasticidad de las Varas**: Dobla lentamente a mano 4 ramas de sauce del grosor de un lápiz para comprobar que se curvan sin quebrarse.\\n2. **Formar 4 Aros Graduales**: Enrolla las ramas en cuatro anillos circulares de **un palmo y medio (25cm de diámetro)**, **un palmo (20cm)**, **dos puños (15cm)** y **un puño (10cm)**.\\n3. **Atar Extremos Superpuestos**: Superpón los extremos de cada aro por **dos dedos de ancho (~4cm)** y átalos firmemente con más de 10 vueltas de [Cuerda Salvaje](/protocol-05.html).\\n4. **Alinear a Intervalos de 1 Palmo**: Coloca los cuatro aros de mayor a menor separados por **un palmo (~15cm)** para definir el cono.\",\n      \"actionNote\": \"> Identificación y Seguridad Ocular: Las ramas secas se parten bruscamente y pueden herir tus manos u ojos. Usa la guía fotográfica inferior para distinguir las **varas vivas de sauce** y el **cebo de caracol de río** ([Hacha de Piedra (PR-04)](/protocol-04.html) / [Cuerda Salvaje (PR-05)](/protocol-05.html)).\",\n      \"svgFileName\": \"pr11-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // GRADUATED HOOP RINGS (4 SIZES)\",\n        \"1. Aro Frontal Grande (1.5 Palmos / 25cm)\",\n        \"2. Dos Aros Intermedios (20cm y 15cm)\",\n        \"3. Aro Trasero Pequeño (1 Puño / 10cm)\",\n        \"4. Amarre con Cuerda (Separación de 15cm)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BOTANY\",\n        \"title\": \"Elasticidad del Sauce Ribereño y Pluma Olfativa de Cebos Acuáticos\",\n        \"text\": \"El sauce de ribera (Salix) posee fibras largas y alta humedad interna, lo que permite doblarlo en círculos cerrados sin fractura y resiste la putrefacción bajo el agua. Los caracoles acuáticos machacados liberan aminoácidos solubles que viajan con la corriente atrayendo a los peces.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"Vara Viva de Sauce\",\n            \"scientificName\": \"Salix koreensis / Salix alba\",\n            \"categoryTag\": \"Árbol Ribereño / Armazón Elástico\",\n            \"imageFileName\": \"id-willow-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-11A // MACRO OPTIC\",\n            \"hudStatus\": \"FLEX ELASTICITY: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"RAMA/TWIG\",\n                \"value\": \"Varas largas verde-amarillentas que **se doblan en forma de U completa sin romperse ni astillarse**.\"\n              },\n              {\n                \"label\": \"HOJA/LEAF\",\n                \"value\": \"Hojas verdes **estrechas en forma de lanza (5–12cm)** con bordes finamente aserrados.\"\n              },\n              {\n                \"label\": \"SEÑAL/SIGN\",\n                \"value\": \"Crece junto a bancos de grava húmeda en ríos; al raspar la corteza desprende un **aroma herbal fresco a salicilato**.\"\n              }\n            ],\n            \"fieldUse\": \"Tejido de nasas pesqueras, arcos flexibles, infusión analgésica de corteza\"\n          },\n          {\n            \"name\": \"Cebo de Caracol de Río y Lombriz\",\n            \"scientificName\": \"Semisulcospira / Lumbricina\",\n            \"categoryTag\": \"Cebo Acuático / Atrayente Olfativo\",\n            \"imageFileName\": \"id-river-snail-bait.jpg\",\n            \"hudCode\": \"FIG. BIO-11B // MACRO OPTIC\",\n            \"hudStatus\": \"SCENT PLUME: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"CONCHA/SHELL\",\n                \"value\": \"Conchas **cónicas en espiral de color oscuro (1.5–3cm)** adheridas bajo piedras musgosas del río.\"\n              },\n              {\n                \"label\": \"MACHACADO/CRUSH\",\n                \"value\": \"Golpea **suavemente la concha con un guijarro** para que los jugos se filtren lentamente durante más de 3 horas.\"\n              },\n              {\n                \"label\": \"ALTERNATIVA/ALT\",\n                \"value\": \"Si no hay caracoles, excava en el barro húmedo de la orilla para obtener **lombrices rojas o saltamontes**.\"\n              }\n            ],\n            \"fieldUse\": \"Cebo olfativo para nasas, carnada de anzuelo, proteína hervida de emergencia\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Paso 2: Tejer 30–40 Varas Rectas de Sauce a lo Largo para Formar el Cuerpo Cónico\",\n      \"description\": \"1. **Distribuir Varillas Longitudinales**: Coloca 30–40 varas rectas de sauce (70–80cm) alrededor de los cuatro aros con una separación de **un dedo de ancho (~1–1.5cm)**.\\n2. **Amarrar Cada Cruce**: Usa una cuerda larga de corteza para envolver firmemente cada punto donde una varilla longitudinal cruza un aro circular.\\n3. **Mantener la Tensión del Cono**: Junta gradualmente las varillas desde la boca ancha de 25cm hasta el aro trasero de 10cm.\\n4. **Cerrar la Cola con Nudo Corredizo**: Reúne las puntas traseras detrás del aro más pequeño y átalas con un **nudo de lazo corredizo** fácil de abrir para sacar los peces.\",\n      \"actionNote\": \"> Regla de Separación: Si el espacio entre varillas supera el ancho de un dedo (1.5cm), los peces escaparán por los lados. Teje la rejilla tan tupida que solo entre la punta de tu dedo.\",\n      \"svgFileName\": \"pr11-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // CONICAL WICKER BODY WEAVING\",\n        \"30-40 Varillas de Sauce (Espacio 1-1.5cm)\",\n        \"Amarre Cruzado en los 4 Aros Circulares\",\n        \"Cesta Cónica Hidrodinámica (-70% Arrastre)\",\n        \"[CLAVE] Nudo Corredizo Trasero de Extracción\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD MECHANICS\",\n        \"title\": \"Reducción del Arrastre Hidrodinámico en Rejillas Cónicas\",\n        \"text\": \"Una rejilla longitudinal con separación de 1–1.5cm permite que la corriente fluya libremente, reduciendo la fuerza de arrastre del agua en **más del 70%** mientras retiene cualquier pez de más de **2cm** de ancho.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Paso 3: Construir el Embudo Invertido (Válvula Unidireccional) y Unirlo a la Boca\",\n      \"description\": \"1. **Formar el Cono del Embudo**: Reúne **16–20 ramitas delgadas y elásticas de sauce** (largo del antebrazo, ~30–35cm) formando un cono pequeño.\\n2. **Ajustar Diámetros de Entrada y Salida**: Abre la boca exterior a **un palmo y medio (25cm)** para encajar en el cuerpo, y estrecha el cuello interior al grosor de **tres dedos juntos (5–6cm)**.\\n3. **Dejar Libres las Puntas Interiores**: Deja los últimos **dos dedos (5cm)** de las puntas interiores sin atar para que se abran cuando el pez empuje al entrar y se cierren como espinas si intenta salir.\\n4. **Insertar y Coser a la Boca**: Introduce el embudo dentro de la boca ancha del cuerpo principal y cose ambos bordes exteriores con [Cuerda Salvaje](/protocol-05.html).\",\n      \"actionNote\": \"> Calibre del Cuello: Si el agujero interior es más grande que tu puño, los peces nadarán hacia afuera. Mantenlo al ancho de tres dedos (5–6cm) para que funcione como válvula antirretorno.\",\n      \"svgFileName\": \"pr11-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // ONE-WAY INVERTED FUNNEL VALVE\",\n        \"Borde Exterior Unido a la Boca de 25cm\",\n        \"Puntas Elásticas Interiores (Cuello 5-6cm)\",\n        \"Se Abre al Entrar y Bloquea el Retroceso\",\n        \"[CLAVE] Entrada Unidireccional Sin Escape\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PHYSICS\",\n        \"title\": \"Mecanismo de Válvula Antirretorno por Puntas en Voladizo\",\n        \"text\": \"Cuando el pez avanza hacia el interior del cono, su cabeza hidrodinámica separa suavemente las ramitas flexibles. Una vez dentro de la cámara, cualquier intento de retroceder choca contra el anillo de puntas convergentes.\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Paso 4: Cargar Piedras de Lastre y Cebo, y Anclar con Estacas en la Corriente\",\n      \"description\": \"1. **Introducir Lastre y Bolsa de Cebo**: Abre el nudo trasero, mete **2 piedras del tamaño de un puño** y una hoja perforada con **caracoles machacados y lombrices**, y vuelve a atar la cola.\\n2. **Elegir Canal Entre Rocas**: Busca un paso estrecho de agua entre rocas de **profundidad hasta la rodilla (30–50cm)** o junto a plantas acuáticas.\\n3. **Orientar la Boca Aguas Arriba**: Hunde la nasa en el fondo con la **boca del embudo mirando aguas arriba (o en diagonal a la corriente)** para que el olor del cebo baje con el agua.\\n4. **Fijar con 4 Estacas y Rocas Laterales**: Clava **4 estacas de madera del largo del antebrazo** a ambos lados de la nasa y calza piedras pesadas en los costados para que la corriente nocturna no la arrastre.\",\n      \"actionNote\": \"> Recolección y Cocción Segura: Por la mañana, suelta el nudo trasero para vaciar los peces. Cocina siempre el pescado de río completamente sobre un [Fogón Dakota Sin Humo](/protocol-06.html) o [Brasas de Carbón de Roble](/protocol-09.html) para eliminar parásitos.\",\n      \"svgFileName\": \"pr11-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // STREAM CHANNEL ANCHORING & BAIT PLUME\",\n        \"2 Piedras de Lastre y Cebo de Caracol Machacado\",\n        \"Corriente del Río y Difusión de Olor Aguas Abajo\",\n        \"4 Estacas de Madera y Rocas de Soporte Lateral\",\n        \"[CLAVE] Peces Atraídos Aguas Arriba y Atrapados\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD ECOLOGY\",\n        \"title\": \"Reotaxis Positiva y Rastreo Olfativo en Peces de Río\",\n        \"text\": \"Los peces de agua dulce muestran **reotaxis positiva**: nadan instintivamente contra la corriente para oxigenar sus branquias y detectar alimento. Al difundirse los aminoácidos del cebo aguas abajo, los peces remontan el rastro directo hacia el embudo.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Error Fatal: Lanzar la nasa ligera al agua sin piedras de lastre o comer pescado de río crudo\",\n    \"description\": \"La madera de sauce flota; sin piedras pesadas dentro y 4 estacas clavadas en el fondo, la corriente arrastrará y perderá tu nasa en pocos minutos. Además, comer pescado de agua dulce crudo provoca infecciones graves por parásitos hepáticos y bacterias.\",\n    \"consequence\": \"Consecuencia: Pérdida total de la trampa en la corriente o infección parasitaria/bacteriana incapacitante\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"¡Deja de gastar energías persiguiendo peces a mano! ¡Haz esta trampa de sauce que atrapa peces mientras duermes!\",\n    \"body\": \"Enrolla ramas flexibles de sauce en cuatro aros desde un palmo y medio hasta el tamaño de un puño. Teje 40 varas rectas separadas por el ancho de un dedo para formar un cesto cónico. ¡El secreto es el embudo invertido en la entrada con un cuello de tres dedos! Mete dos piedras y caracoles machacados, y fíjala con estacas en el río.\",\n    \"outro\": \"Los peces entran siguiendo el olor y las puntas les impiden salir. ¡Mira el plano completo en el enlace del perfil!\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr11-outcome.svg\",\n    \"title\": \"Nasa de Sauce con Embudo Unidireccional Completada y Corte Subacuático\",\n    \"description\": \"Sección longitudinal mostrando los 4 aros graduales, cuerpo cónico de varas de sauce a 1cm, embudo antirretorno de 5cm, 2 piedras de lastre, bolsa de cebo de caracol y 4 estacas de fijación en el lecho del río.\"\n  },\n  \"createdAt\": \"2026-10-16T13:38:00.000Z\",\n  \"contentHash\": \"037d4ce0763a3aa2\"\n}","content/protocols/locales/11-willow-funnel-fish-trap.ja.json":"{\n  \"protocolId\": \"PR-11\",\n  \"category\": \"FOOD\",\n  \"title\": \"柳の枝を編んで入った魚が抜け出せない原始漏斗（ろうと）魚罠（ウケ・筌漁法）\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[自動タンパク質確保・体力温存]\",\n  \"summary\": \"素手や木の銛で素早い川魚を追い回すと、貴重な体力を消耗するばかりで9割以上は失敗します。川辺に生えるしなやかな柳の若枝で、入口は広く奥ほど狭まる逆漏斗（ぎゃくろうと）構造の魚罠（ウケ）を編んで瀬に沈めておけば、餌の匂いにつられて入った魚が内向きに集まる枝先に阻まれて二度と出られなくなります。睡眠中やシェルター作業中にも自動で魚を捕獲し続ける高効率な原始漁具です。\",\n  \"timeRequired\": \"50分（柳の枝採取10分＋骨組み・胴体編み25分＋逆漏斗結合・川底固定15分）\",\n  \"successRate\": \"92%（逆漏斗の奥口を指3本幅に保ち、上流向きに固定した場合）\",\n  \"difficulty\": \"普通（跳ねる枝先による目の保護・滑りやすい川底に注意）\",\n  \"outputPerHour\": \"一晩の設置で川魚3〜8匹を自動捕獲\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"しなやかな柳（ヤナギ）またはハシバミの生枝 40〜50本（腕の長さ70〜80cm）\",\n      \"desc\": \"[石斧や鋭い石刃](/protocol-04.html)で川辺から切り出した小指の半分ほどの太さ（約5mm）の弾力ある生枝です。曲げても折れない瑞々しい枝を選びます。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"円形フレーム（リム）用の太めのツルまたは柳の枝 4本\",\n      \"desc\": \"丸く曲げて魚罠の円錐形を支える鉛筆ほどの太さ（約8〜10mm）の丈夫な生枝4本です。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"水に強い野生クズ（葛）の内皮ロープ（全長15m）\",\n      \"desc\": \"[野生植物ロープの編み方](/protocol-05.html)で縒り合わせた強靭な植物紐です。水中で結び目が緩まないよう[松脂（マツヤニ）防水接着剤](/protocol-10.html)を塗っておくとさらに頑丈になります。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"魚罠を川底に沈める拳大の川石2個と固定杭4本\",\n      \"desc\": \"木の魚罠が浮き上がったり水流で転がったりしないよう重しにする大人の拳サイズの石と、前腕の長さの木の杭です。\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"石で潰したカワニナ・タニシまたは川底のミミズ一掴み\",\n      \"desc\": \"水流に乗って下流へ強い匂いを拡散させ、魚を罠の奥へと誘い込む天然の撒き餌です。広い葉に包んで穴を開けて入れます。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"ステップ1：太い枝を丸めてサイズ順の円形リング（骨組み）を4個作る\",\n      \"description\": \"1. **生枝のしなり確認**: 川辺で採取した鉛筆太さの柳の枝4本を手でゆっくり曲げ、折れずに滑らかな輪になるか確認します。\\n2. **4段階サイズのリング成形**: 枝を丸めて**一咫半（直径25cm）**、**一咫（直径20cm）**、**拳2個分（直径15cm）**、**拳1個分（直径10cm）**の円形リング4個を作ります。\\n3. **重なり部分の紐結束**: 各リングの両端を**指2本分（約4cm）**以上重ね合わせ、[野生クズの紐](/protocol-05.html)で10回以上しっかり巻き縛ります。\\n4. **等間隔の整列配置**: 大きいリングから小さいリングへ順番に**一咫（約15cm）間隔**で並べ、円錐形の比率を整えます。\",\n      \"actionNote\": \"> 素材識別と目の保護：枯れた枝は曲げた瞬間に鋭く折れて手や目を突く危険があります。下の実写図鑑で川辺のしなやかな**柳の生枝**と**カワニナ天然餌**を正確に識別してください（[石斧・石刃製作(PR-04)](/protocol-04.html) / [野生ロープ製作(PR-05)](/protocol-05.html)）。\",\n      \"svgFileName\": \"pr11-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // GRADUATED HOOP RINGS (4 SIZES)\",\n        \"① 入口大リング（一咫半 / 直径25cm）\",\n        \"② 中間リング2個（直径20cm・15cm）\",\n        \"③ 尾部小リング（拳幅 / 直径10cm）\",\n        \"④ 重ね端の葛紐結束（15cm間隔配列）\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BOTANY\",\n        \"title\": \"柳の生枝の曲げ弾性・水中耐久性と天然ベイトの選別\",\n        \"text\": \"水辺に自生するヤナギ（Salix）は木質繊維が長く水分量が多いため、強い円形に曲げても折れにくく、水中に沈めても腐りにくい特性があります。また川底の石裏に張り付くカワニナやタニシは殻を割ることでアミノ酸体液が水流に乗って広範囲に拡散し、川魚を強力に誘引します。\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"柳（ヤナギ）の生枝\",\n            \"scientificName\": \"Salix koreensis\",\n            \"categoryTag\": \"水辺広葉樹 / 高弾性フレーム・縦骨材\",\n            \"imageFileName\": \"id-willow-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-11A // MACRO OPTIC\",\n            \"hudStatus\": \"FLEX ELASTICITY: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"枝/TWIG\",\n                \"value\": \"黄緑〜薄茶色の細長くしなやかな枝で、**U字型に深く曲げても折れない強い弾力**があります。\"\n              },\n              {\n                \"label\": \"葉/LEAF\",\n                \"value\": \"槍の先のように**細長い披針形の緑葉（長さ5〜12cm）**で、縁に細かいギザギザ（鋸歯）があります。\"\n              },\n              {\n                \"label\": \"特徴/SIGN\",\n                \"value\": \"川岸の湿った砂利場に群生し、樹皮を削ると**ヤナギ特有の爽やかな青臭い香り**がします。\"\n              }\n            ],\n            \"fieldUse\": \"魚罠（ウケ）の編み込み、高弾性弓、鎮痛・解熱用の柳樹皮茶\"\n          },\n          {\n            \"name\": \"カワニナ・ミミズ天然餌\",\n            \"scientificName\": \"Semisulcospira / Lumbricina\",\n            \"categoryTag\": \"水生生物ベイト / 嗅覚誘引剤\",\n            \"imageFileName\": \"id-river-snail-bait.jpg\",\n            \"hudCode\": \"FIG. BIO-11B // MACRO OPTIC\",\n            \"hudStatus\": \"SCENT PLUME: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"外観/SHELL\",\n                \"value\": \"水中の苔むした石の裏に張り付く**黒褐色の細長い円錐巻貝（長さ1.5〜3cm）**です。\"\n              },\n              {\n                \"label\": \"加工/CRUSH\",\n                \"value\": \"小石で殻を**軽く潰して体液がじわじわ染み出すように**すると、水中で3時間以上匂いが持続します。\"\n              },\n              {\n                \"label\": \"代替/ALT\",\n                \"value\": \"巻貝がなければ川岸の湿った土や落ち葉の下を掘って捕まえた**赤ミミズやバッタ**を包んでも効果抜群です。\"\n              }\n            ],\n            \"fieldUse\": \"魚罠内部の嗅覚誘引餌、釣り針の餌、非常時の煮沸タンパク源\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"ステップ2：柳の細枝30〜40本を縦に細かく編み込んで円錐の胴体を完成させる\",\n      \"description\": \"1. **縦骨の均等配置**: 腕の長さ（70〜80cm）のまっすぐな柳の細枝30〜40本を、一番大きいリングから一番小さいリングまで**指1本分（約1〜1.5cm）間隔**でぐるりと当てがいます。\\n2. **交差部の巻き結び**: 長いクズの紐を使い、円形リングと縦枝が交差する箇所を**1本ずつ交互に巻き付けて**しっかり固定します。\\n3. **円錐格子の張力維持**: 広い入口から狭い尾部へ向かって自然にすぼまるよう手で形を整えながら4つのリングすべてを編み上げます。\\n4. **尾部取り出し口の引き解き結び**: 最小リングの後ろに集まった枝先を束ね、捕れた魚をすぐ取り出せるよう**引けば解ける輪結び**で縛り閉じます。\",\n      \"actionNote\": \"> 隙間基準：縦枝同士の隙間が指1本幅（1.5cm）より広いと、入った魚が横からすり抜けて逃げます。指先がやっと通る程度に密に編んでください。\",\n      \"svgFileName\": \"pr11-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // CONICAL WICKER BODY WEAVING\",\n        \"柳の縦骨30〜40本（指1本 / 1〜1.5cm間隔）\",\n        \"4つの円形リングと縦骨の交差巻き結び\",\n        \"水流抵抗を70%減らす流線型円錐バスケット\",\n        \"[核心] 尾部の魚回収用・開閉スリップノット\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD MECHANICS\",\n        \"title\": \"流線型円錐格子による水流抵抗（抗力）の分散力学\",\n        \"text\": \"1〜1.5cm間隔の縦骨格子は川の流れを遮らずにスムーズに通過させるため、急流で罠が流される水流抵抗（ドラッグ）を**70%以上軽減**しつつ、体幅**2cm以上**の川魚の脱出を完全に封じ込めます。\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"ステップ3：奥に向かって狭まる逆漏斗（逆止弁）を作り胴体の入口に縫い合わせる\",\n      \"description\": \"1. **逆漏斗の細枝編成**: 前腕の長さ（約30〜35cm）の細く弾力のある柳の枝**16〜20本**を丸く束ねて小さな円錐漏斗を作ります。\\n2. **入口・出口の口径設定**: 外側の広い入口は胴体に合わせて**一咫半（直径25cm）**に広げ、奥の先端は**指3本を束ねた太さ（直径5〜6cm）**に狭めます。\\n3. **奥側の弾性枝先の解放**: 狭まった奥の先端**指2関節分（5cm）**は紐で縛らず、枝先が内側に集まるままにして、魚が押し入る時だけ開き逆戻りする時は刺さって塞がる一方向弁にします。\\n4. **胴体入口への挿入・縫合**: 完成した逆漏斗をステップ2の胴体入口の内側へ差し込み、重なる外縁を[野生クズ紐](/protocol-05.html)で隙間なく縫い合わせて一体化します。\",\n      \"actionNote\": \"> 逆漏斗の口径基準：奥の狭い穴が拳より大きいと魚がそのまま泳いで出てしまいます。指3本分の太さ（直径5〜6cm）に絞ることで、入る時だけ枝が広がり後ろ向きにはロックされます。\",\n      \"svgFileName\": \"pr11-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // ONE-WAY INVERTED FUNNEL VALVE\",\n        \"逆漏斗の外縁（直径25cm胴体入口と縫合）\",\n        \"内側にすぼまる弾性枝先（直径5〜6cm通過口）\",\n        \"魚の進入時に開き逆走時に引っかかる構造\",\n        \"[核心] 一方向進入許容＆逆方向脱出を完全遮断\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PHYSICS\",\n        \"title\": \"弾性小枝の楔（くさび）による一方向逆止弁（チェックバルブ）機構\",\n        \"text\": \"魚が前進して漏斗を通過する際は、流線型の頭部が弾性のある枝先を外側へ優しく押し広げて通路が開きます。しかし一度内部に入った後に引き返そうとすると、内向きに鋭く集まった枝先がエラ蓋やヒレに引っかかり、逆方向の脱出を幾何学的に遮断します。\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"ステップ4：内部に重し石と餌を入れ、瀬の岩間に杭でしっかり固定する\",\n      \"description\": \"1. **沈降石と餌袋の投入**: 尾部の結び目を解き、浮き上がりを防ぐ**拳大の川石2個**と穴を開けた葉で包んだ**潰しカワニナ・ミミズ餌**を入れて再び尾部を固く縛ります。\\n2. **岩間の瀬の選定**: 川の水が岩の間で絞られて流れる**膝下水深（30〜50cm）**の通り道や水草の陰を設置場所に選びます。\\n3. **漏斗入口の上流向き配置**: 餌の匂いが下流へ流れて魚を呼び寄せるよう、魚罠の**漏斗入口が水の流れてくる上流（または流れに対して斜め上流）**を向くように川底へ沈めます。\\n4. **杭4本と両脇の石による3点固定**: 魚罠の両脇の川底に**前腕長の木の杭4本**を深く打ち込み、上を紐で結ぶか重い石で両脇を挟んで、夜間の強い水流でも転がらないよう固定します。\",\n      \"actionNote\": \"> 回収と加熱調理：翌朝、尾部の引き解き結びを引くだけで捕れた魚を簡単に取り出せます。淡水魚は寄生虫感染を防ぐため、必ず[ダコタ無煙かまど](/protocol-06.html)や[クヌギ炭火](/protocol-09.html)で中心まで完全に火を通して食べてください。\",\n      \"svgFileName\": \"pr11-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // STREAM CHANNEL ANCHORING & BAIT PLUME\",\n        \"内部の沈降用川石2個＆潰したカワニナ餌袋\",\n        \"上流から下流への水流＆匂い拡散ルート\",\n        \"木の固定杭4本および両脇の岩による固定\",\n        \"[核心] 匂いを辿り遡上して罠に閉じ込められた魚\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD ECOLOGY\",\n        \"title\": \"淡水魚の正の走流性（Positive Rheotaxis）と嗅覚誘引\",\n        \"text\": \"多くの川魚はエラ呼吸の効率を高め流下する餌を捕食するため、水流に向かって上流へ頭を向ける**正の走流性**本能を持っています。上流に向けて設置した罠から餌の匂いが下流へ流れると、下流の魚が匂いの筋を辿って遡上し、自ら漏斗の奥へと入り込みます。\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命的なミス：重しの石を入れずに軽い魚罠だけを川に投げ込むこと、または捕れた川魚を生で食べること\",\n    \"description\": \"柳で編んだ魚罠は浮力が大きいため、内部に重い川石を入れず杭で固定しないと数分で水流に流されて失われます。また、捕獲した淡水魚を焼かずに生食すると肝吸虫などの致命的な寄生虫や水系細菌に感染し、激しい腹痛と高熱で生存が危うくなります。\",\n    \"consequence\": \"結果：魚罠の流失による食料確保失敗、および寄生虫・細菌感染による重症化\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"川で魚を素手で追い回すと体力が尽きます！寝ている間に魚が勝手に入る柳の魚罠の作り方！\",\n    \"body\": \"川辺のしなやかな柳の枝を丸めて、一咫半から拳サイズまで4つの円形リングを作ります。ここに長い細枝40本を指1本間隔で細かく編み込み円錐カゴを作ります。最大の秘訣は入口にはめ込む逆漏斗です！奥の穴を指3本サイズに絞って縫い付ければ、潰したカワニナの匂いにつられて入った魚が枝先に引っかかり二度と出られません！\",\n    \"outro\": \"拳大の石2個を入れて瀬の岩間に固定すれば、毎朝新鮮な川魚が手に入ります。詳しい図面はプロフィールリンクから確認してください。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr11-outcome.svg\",\n    \"title\": \"完成した柳の二重逆漏斗魚罠（ウケ）および瀬の水中捕獲断面仕様\",\n    \"description\": \"4段の円形リングと1cm間隔の柳の縦骨で編んだ流線型円錐ボディ、一方向弾性枝先を持つ逆漏斗入口（逆止弁）、沈降用の川石2個とカワニナ餌袋、そして川底の岩間に杭で固定され魚を自動捕獲する水中断面構造です。\"\n  },\n  \"createdAt\": \"2026-10-16T13:38:00.000Z\",\n  \"contentHash\": \"037d4ce0763a3aa2\"\n}","content/protocols/locales/11-willow-funnel-fish-trap.pt.json":"{\n  \"protocolId\": \"PR-11\",\n  \"category\": \"FOOD\",\n  \"title\": \"Como Trançar um Covo de Salgueiro com Funil Unidirecional para Pesca Passiva\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[PROTEÍNA PASSIVA E ECONOMIA DE ENERGIA]\",\n  \"summary\": \"Perseguir peixes rápidos com as mãos ou lança de madeira esgota suas calorias vitais e falha em mais de 90% das tentativas. Ao trançar ramos flexíveis de salgueiro ribeirinho em um cesto cônico com funil invertido unidirecional, os peixes entram seguindo o cheiro da isca e ficam bloqueados pelas pontas elásticas ao tentar voltar. Ancorado na correnteza do rio, captura peixes sozinho enquanto você dorme ou constrói seu abrigo.\",\n  \"timeRequired\": \"50 min (10m corte de salgueiro + 25m aros e corpo + 15m funil e fixação no rio)\",\n  \"successRate\": \"92% (mantendo abertura interna de 3 dedos e boca voltada rio acima)\",\n  \"difficulty\": \"Média (cuidado com pontas de galhos nos olhos e pedras escorregadias)\",\n  \"outputPerHour\": \"3–8 peixes de água doce capturados passivamente por noite\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"40–50 varas verdes flexíveis de salgueiro ou aveleira (comprimento de um braço, 70–80cm)\",\n      \"desc\": \"Ramos verdes recém-cortados na margem com um [Machado de Pedra ou Lasca Afiada](/protocol-04.html), com metade da grossura de um dedo mínimo (~5mm), que dobrem sem quebrar.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"4 galhos mais grossos de salgueiro ou cipós para os aros estruturais\",\n      \"desc\": \"Quatro ramos verdes da grossura de um lápis (~8–10mm) curvados em círculos para sustentar o formato cônico do covo.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Corda resistente à água de entrecasca de kudzu (15m no total)\",\n      \"desc\": \"Corda vegetal torcida conforme [Corda Selvagem de Fibras](/protocol-05.html). Selar os nós principais com [Cola Impermeável de Resina de Pinheiro](/protocol-10.html) evita que afrouxem debaixo d'água.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"2 pedras de rio do tamanho de um punho e 4 estacas de madeira do tamanho do antebraço\",\n      \"desc\": \"Pedras pesadas para afundar o covo no leito do rio e estacas para travá-lo contra a correnteza.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"1 punhado de caramujos de rio esmagados ou minhocas da margem\",\n      \"desc\": \"Isca natural envolvida em uma folha larga perfurada para liberar cheiro rio abaixo e atrair peixes para dentro.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Passo 1: Curvar Galhos Grossos em 4 Aros Circulares de Tamanhos Graduais\",\n      \"description\": \"1. **Testar Flexibilidade dos Galhos**: Dobre lentamente com as mãos 4 galhos de salgueiro da grossura de um lápis para garantir que curvem sem rachar.\\n2. **Formar 4 Aros Graduais**: Enrole os galhos em quatro anéis circulares de **um palmo e meio (25cm de diâmetro)**, **um palmo (20cm)**, **dois punhos (15cm)** e **um punho (10cm)**.\\n3. **Amarrar Pontas Sobrepostas**: Sobreponha as pontas de cada aro por **dois dedos de largura (~4cm)** e amarre firmemente com mais de 10 voltas de [Corda Selvagem](/protocol-05.html).\\n4. **Alinhar a Intervalos de 1 Palmo**: Posicione os quatro aros do maior para o menor separados por **um palmo (~15cm)** para definir o cone.\",\n      \"actionNote\": \"> Identificação e Proteção Ocular: Galhos secos quebram de repente e podem ferir suas mãos ou olhos. Use o guia fotográfico abaixo para identificar **varas vivas de salgueiro** e **isca de caramujo de rio** ([Machado de Pedra (PR-04)](/protocol-04.html) / [Corda Selvagem (PR-05)](/protocol-05.html)).\",\n      \"svgFileName\": \"pr11-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // GRADUATED HOOP RINGS (4 SIZES)\",\n        \"1. Aro Frontal Grande (1.5 Palmos / 25cm)\",\n        \"2. Dois Aros Médios (20cm e 15cm Dia)\",\n        \"3. Aro Traseiro Pequeno (1 Punho / 10cm)\",\n        \"4. Amarração de Corda (Intervalo de 15cm)\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BOTANY\",\n        \"title\": \"Elasticidade do Salgueiro Ribeirinho e Pluma Olfativa de Iscas Aquáticas\",\n        \"text\": \"O salgueiro de margem (Salix) possui fibras longas e alta umidade, permitindo curvá-lo em anéis fechados sem fratura e resistindo ao apodrecimento submerso. Caramujos esmagados liberam aminoácidos solúveis que viajam pela correnteza atraindo peixes.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"Vara Viva de Salgueiro\",\n            \"scientificName\": \"Salix koreensis / Salix alba\",\n            \"categoryTag\": \"Árvore Ribeirinha / Armação Flexível\",\n            \"imageFileName\": \"id-willow-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-11A // MACRO OPTIC\",\n            \"hudStatus\": \"FLEX ELASTICITY: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"RAMO/TWIG\",\n                \"value\": \"Varas longas verde-amareladas que **dobram em formato de U completo sem quebrar ou lascar**.\"\n              },\n              {\n                \"label\": \"FOLHA/LEAF\",\n                \"value\": \"Folhas verdes **estreitas em forma de lança (5–12cm)** com bordas finamente serrilhadas.\"\n              },\n              {\n                \"label\": \"SINAL/SIGN\",\n                \"value\": \"Cresce em bancos de cascalho úmido na beira de rios; ao raspar a casca exala um **aroma herbal fresco de salicilato**.\"\n              }\n            ],\n            \"fieldUse\": \"Trançado de covos de pesca, arcos flexíveis, chá analgésico de casca\"\n          },\n          {\n            \"name\": \"Isca de Caramujo de Rio e Minhoca\",\n            \"scientificName\": \"Semisulcospira / Lumbricina\",\n            \"categoryTag\": \"Isca Aquática / Atrativo Olfativo\",\n            \"imageFileName\": \"id-river-snail-bait.jpg\",\n            \"hudCode\": \"FIG. BIO-11B // MACRO OPTIC\",\n            \"hudStatus\": \"SCENT PLUME: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"CONCHA/SHELL\",\n                \"value\": \"Conchas **cônicas em espiral escura (1.5–3cm)** presas embaixo de pedras com musgo no rio.\"\n              },\n              {\n                \"label\": \"PREPARO/CRUSH\",\n                \"value\": \"Quebre **levemente a concha com um seixo** para que o líquido interno se espalhe lentamente por mais de 3 horas.\"\n              },\n              {\n                \"label\": \"ALTERNATIVA/ALT\",\n                \"value\": \"Se não houver caramujos, cave na lama úmida da margem em busca de **minhocas vermelhas ou gafanhotos**.\"\n              }\n            ],\n            \"fieldUse\": \"Isca olfativa para covo, isca de anzol, proteína cozida de emergência\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Passo 2: Trançar 30–40 Varas Retas de Salgueiro no Comprimento para Formar o Corpo\",\n      \"description\": \"1. **Distribuir Varetas Longitudinais**: Posicione 30–40 varas retas de salgueiro (70–80cm) ao redor dos quatro aros com espaçamento de **um dedo de largura (~1–1.5cm)**.\\n2. **Amarrar Cada Cruzamento**: Use uma corda longa de entrecasca para dar voltas firmes em cada ponto onde uma vareta cruza um aro circular.\\n3. **Manter a Tensão do Cone**: Afine gradualmente as varetas desde a boca larga de 25cm até o aro traseiro de 10cm.\\n4. **Fechar a Cauda com Nó Corrediço**: Junte as pontas traseiras atrás do aro menor e amarre com um **nó de laço corrediço** fácil de soltar para retirar os peixes.\",\n      \"actionNote\": \"> Regra de Espaçamento: Se a fresta entre as varetas passar da largura de um dedo (1.5cm), os peixes escaparão pelos lados. Trance a grade bem fechada para passar apenas a ponta do dedo.\",\n      \"svgFileName\": \"pr11-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // CONICAL WICKER BODY WEAVING\",\n        \"30-40 Varetas de Salgueiro (Fresta 1-1.5cm)\",\n        \"Amarração Cruzada nos 4 Aros Circulares\",\n        \"Cesto Cônico Hidrodinâmico (-70% Arrasto)\",\n        \"[CHAVE] Nó Corrediço Traseiro de Retirada\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD MECHANICS\",\n        \"title\": \"Redução do Arrasto Hidrodinâmico em Grades Cônicas\",\n        \"text\": \"Uma grade longitudinal com frestas de 1–1.5cm deixa a água passar livremente, reduzindo a força de arrasto da correnteza em **mais de 70%** enquanto retém qualquer peixe com mais de **2cm** de largura.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Passo 3: Construir o Funil Invertido (Válvula Unidirecional) e Costurar na Boca\",\n      \"description\": \"1. **Montar o Cone do Funil**: Junte **16–20 raminhos finos e elásticos de salgueiro** (comprimento do antebraço, ~30–35cm) formando um cone menor.\\n2. **Definir Diâmetros de Entrada e Saída**: Abra a boca externa em **um palmo e meio (25cm)** para encaixar no corpo, e estreite o pescoço interno para a largura de **três dedos juntos (5–6cm)**.\\n3. **Deixar as Pontas Internas Livres**: Deixe os últimos **dois dedos (5cm)** das pontas internas sem amarrar para que abram quando o peixe empurrar para entrar e travem como espinhos se tentar voltar.\\n4. **Encaixar e Costurar na Boca**: Empurre o funil para dentro da boca larga do corpo principal e costure as duas bordas externas com [Corda Selvagem](/protocol-05.html).\",\n      \"actionNote\": \"> Medida do Pescoço: Se o furo interno for maior que seu punho, os peixes nadarão para fora. Mantenha na largura de três dedos (5–6cm) para funcionar como válvula de retenção.\",\n      \"svgFileName\": \"pr11-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // ONE-WAY INVERTED FUNNEL VALVE\",\n        \"Borda Externa Costurada na Boca de 25cm\",\n        \"Pontas Elásticas Internas (Pescoço 5-6cm)\",\n        \"Abre na Entrada e Bloqueia o Retorno\",\n        \"[CHAVE] Entrada Unidirecional Sem Fuga\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PHYSICS\",\n        \"title\": \"Mecanismo de Válvula de Retenção por Pontas Flexíveis\",\n        \"text\": \"Quando o peixe avança para dentro do funil, sua cabeça hidrodinâmica afasta suavemente as pontas flexíveis de salgueiro. Uma vez dentro da câmara, qualquer tentativa de recuar esbarra no anel de pontas convergentes.\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Passo 4: Colocar Pedras de Lastro e Isca, e Fixar com Estacas na Correnteza\",\n      \"description\": \"1. **Colocar Lastro e Trouxa de Isca**: Abra o nó traseiro, coloque **2 pedras do tamanho de um punho** e uma folha furada com **caramujos esmagados e minhocas**, e amarre a cauda novamente.\\n2. **Escolher Canal Entre Pedras**: Procure um canal estreito de água entre pedras com **profundidade até o joelho (30–50cm)** ou junto à vegetação da margem.\\n3. **Apontar a Boca Rio Acima**: Afunde o covo no leito com a **boca do funil voltada rio acima (ou na diagonal da correnteza)** para que o cheiro da isca desça com a água.\\n4. **Travar com 4 Estacas e Pedras Laterais**: Crave **4 estacas de madeira do tamanho do antebraço** nos dois lados do covo e escore pedras pesadas nas laterais para que a correnteza noturna não o role.\",\n      \"actionNote\": \"> Coleta e Cozimento Seguro: Pela manhã, basta puxar o nó traseiro para recolher os peixes. Cozinhe sempre muito bem os peixes de água doce sobre um [Fogão Dakota Sem Fumaça](/protocol-06.html) ou [Brasas de Carvão de Carvalho](/protocol-09.html) para eliminar parasitas.\",\n      \"svgFileName\": \"pr11-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // STREAM CHANNEL ANCHORING & BAIT PLUME\",\n        \"2 Pedras de Lastro e Isca de Caramujo Esmagado\",\n        \"Correnteza do Rio e Rastro de Cheiro Rio Abaixo\",\n        \"4 Estacas de Madeira e Pedras de Apoio Lateral\",\n        \"[CHAVE] Peixes Subindo pelo Cheiro e Capturados\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD ECOLOGY\",\n        \"title\": \"Reotaxia Positiva e Rastreamento Olfativo em Peixes de Rio\",\n        \"text\": \"Peixes de água doce apresentam **reotaxia positiva**: nadam instintivamente contra a correnteza para oxigenar as brânquias e interceptar alimento. Quando os aminoácidos da isca descem com a água, os peixes sobem o rastro direto para dentro do funil.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Erro Fatal: Lançar o covo leve na água sem pedras de lastro ou comer peixe de água doce cru\",\n    \"description\": \"A madeira de salgueiro flutua; sem pedras pesadas dentro e 4 estacas cravadas no fundo, a correnteza levará seu covo embora em minutos. Além disso, comer peixe de rio cru causa infecções graves por vermes hepáticos e bactérias.\",\n    \"consequence\": \"Consequência: Perda total da armadilha na correnteza ou infecção parasitária/bacteriana grave\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Pare de gastar energia correndo atrás de peixe com a mão! Faça este covo de salgueiro que pega peixe enquanto você dorme!\",\n    \"body\": \"Enrole galhos flexíveis de salgueiro em quatro aros de um palmo e meio até o tamanho de um punho. Amarre 40 varas retas com espaço de um dedo para formar um cesto cônico. O segredo é o funil invertido na entrada com passagem de três dedos! Coloque duas pedras e caramujos esmagados dentro e trave com estacas no rio!\",\n    \"outro\": \"Os peixes entram seguindo o cheiro e as pontas impedem a saída. Veja o projeto completo no link do perfil!\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr11-outcome.svg\",\n    \"title\": \"Covo de Salgueiro com Funil Unidirecional Completo e Corte Submerso\",\n    \"description\": \"Corte longitudinal mostrando os 4 aros graduais, corpo cônico de varas de salgueiro a 1cm, funil antirretorno de 5cm, 2 pedras de lastro, trouxa de isca de caramujo e 4 estacas de fixação no leito do rio.\"\n  },\n  \"createdAt\": \"2026-10-16T13:38:00.000Z\",\n  \"contentHash\": \"037d4ce0763a3aa2\"\n}","content/protocols/locales/11-willow-funnel-fish-trap.zh-TW.json":"{\n  \"protocolId\": \"PR-11\",\n  \"category\": \"FOOD\",\n  \"title\": \"編織柳枝單向倒鬚魚筌（原始漏斗捕魚籠製作法）\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[被動獲取蛋白質 & 體力保存]\",\n  \"summary\": \"徒手或用木叉追捕敏捷的河魚會消耗大量體力，且失敗率超過90%。利用河邊隨處可見的柔韌柳樹枝條，編織出入口寬大、內部收窄的單向倒鬚漏斗魚筌（魚籠），固定在淺灘水道中，魚群順著餌料氣味鑽入後，就會被向內聚攏的彈性枝尖擋住而無法倒退逃脫。在睡眠或搭建避難所時也能自動捕魚。\",\n  \"timeRequired\": \"50分鐘（採集柳枝10分＋編織圓框與籠身25分＋倒鬚漏斗結合與河床固定15分）\",\n  \"successRate\": \"92%（維持漏斗內口3指寬度並朝上游固定時）\",\n  \"difficulty\": \"中等（注意彈起的枝尖保護眼睛及濕滑河石）\",\n  \"outputPerHour\": \"每次放置過夜可自動捕獲3～8條淡水魚\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"柔韌的柳樹或榛樹鮮枝 40～50根（手臂長70～80cm）\",\n      \"desc\": \"使用[石斧或鋒利石片](/protocol-04.html)在河岸剛砍下、約小指一半粗（約5mm）的鮮綠枝條。挑選彎曲時不會折斷的柔韌活枝。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"圓形骨架（圈環）用的較粗藤蔓或柳枝 4根\",\n      \"desc\": \"彎成圓環以支撐魚筌圓錐形狀、約鉛筆粗細（8～10mm）的堅固鮮枝4根。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"耐水浸泡的野生葛藤內皮繩（總長15m）\",\n      \"desc\": \"依照[野生植物繩索編織法](/protocol-05.html)搓成的強韌植物繩。若在主要繩結塗上[松脂防水膠](/protocol-10.html)，在水底更不易鬆脫。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"使魚筌沉入河床的拳頭大河石2顆與固定木樁4根\",\n      \"desc\": \"防止木製魚筌浮起或被水流沖走的成人拳頭大鵝卵石，以及前臂長的木樁。\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"用石頭砸碎的淡水川蜷、田螺或河岸蚯蚓一把\",\n      \"desc\": \"順著水流向下游散發腥味、將魚群引誘進籠內的天然餌料。用刺破的寬樹葉包裹後放入。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"步驟1：將粗枝彎成4個由大到小的圓形骨架圈環\",\n      \"description\": \"1. **測試鮮枝彈性**：用手慢慢彎曲4根鉛筆粗的柳枝，確認能順暢彎成圓弧而不會斷裂。\\n2. **製作4種尺寸圓環**：將枝條彎成**一拃半（直徑25cm）**、**一拃（直徑20cm）**、**兩拳寬（直徑15cm）**與**一拳寬（直徑10cm）**的4個圓形圈環。\\n3. **重疊處綁繩固定**：讓每個圓環兩端重疊**兩指寬（約4cm）**以上，用[野生葛藤繩](/protocol-05.html)緊密纏繞10圈以上綁牢。\\n4. **依序等距排列**：在地面由大到小每隔**一拃（約15cm）**排列四個圓環，抓出圓錐體比例。\",\n      \"actionNote\": \"> 材料辨識與護眼安全：乾枯死枝彎曲時會瞬間斷裂並刺傷手或眼睛。請參考下方實拍圖鑑準確分辨水邊柔韌的**柳樹鮮枝**與**淡水螺天然餌料**（[石斧與石刃 (PR-04)](/protocol-04.html) / [野生繩索 (PR-05)](/protocol-05.html)）。\",\n      \"svgFileName\": \"pr11-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // GRADUATED HOOP RINGS (4 SIZES)\",\n        \"① 入口大圈環（一拃半 / 直徑25cm）\",\n        \"② 中間圈環2個（直徑20cm・15cm）\",\n        \"③ 尾部小圈環（一拳寬 / 直徑10cm）\",\n        \"④ 重疊端葛繩捆紮（15cm間距排列）\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BOTANY\",\n        \"title\": \"河岸柳枝的抗彎彈性、水下耐腐性與天然誘餌篩選\",\n        \"text\": \"生長於水邊的柳樹（Salix）木質纖維長且含水量高，大幅彎折也不易斷裂，浸泡水中亦不易腐爛。吸附在河底石塊背面的川蜷與田螺敲碎後，水溶性胺基酸體液會順流擴散，強烈吸引淡水魚群。\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"柳樹鮮枝\",\n            \"scientificName\": \"Salix koreensis\",\n            \"categoryTag\": \"河岸闊葉樹 / 高彈性魚筌骨架\",\n            \"imageFileName\": \"id-willow-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-11A // MACRO OPTIC\",\n            \"hudStatus\": \"FLEX ELASTICITY: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"枝條/TWIG\",\n                \"value\": \"黃綠至淺褐色的細長柔韌枝條，**完全彎成U字形也不會折斷或劈裂**。\"\n              },\n              {\n                \"label\": \"葉片/LEAF\",\n                \"value\": \"如長矛般**狹長的披針形綠葉（長5～12cm）**，葉緣有細微鋸齒。\"\n              },\n              {\n                \"label\": \"特徵/SIGN\",\n                \"value\": \"成群生長於河岸潮濕礫石灘，刮開樹皮會散發**柳樹特有的清新草木氣味**。\"\n              }\n            ],\n            \"fieldUse\": \"編織捕魚籠、高彈性弓身、止痛退燒柳樹皮茶\"\n          },\n          {\n            \"name\": \"淡水川蜷與蚯蚓餌料\",\n            \"scientificName\": \"Semisulcospira / Lumbricina\",\n            \"categoryTag\": \"水生生物餌料 / 嗅覺引誘劑\",\n            \"imageFileName\": \"id-river-snail-bait.jpg\",\n            \"hudCode\": \"FIG. BIO-11B // MACRO OPTIC\",\n            \"hudStatus\": \"SCENT PLUME: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"外殼/SHELL\",\n                \"value\": \"吸附在水中長苔石頭背面的**黑褐色細長圓錐螺旋殼（長1.5～3cm）**。\"\n              },\n              {\n                \"label\": \"處理/CRUSH\",\n                \"value\": \"用鵝卵石**輕輕敲裂外殼讓汁液緩慢滲出**，即可在流水中持續散發氣味達3小時以上。\"\n              },\n              {\n                \"label\": \"替代/ALT\",\n                \"value\": \"若無螺類，翻開河岸潮濕泥土或落葉層抓一把**紅蚯蚓或蚱蜢**包裹放入同樣有效。\"\n              }\n            ],\n            \"fieldUse\": \"魚筌內部嗅覺誘餌、魚鉤餌料、緊急煮沸蛋白質來源\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"步驟2：將30～40根柳樹細枝縱向緊密編織成圓錐籠身\",\n      \"description\": \"1. **均勻排列縱向枝條**：將30～40根手臂長（70～80cm）的筆直柳枝，從最大圈環到最小圈環每隔**一指寬（約1～1.5cm）**環繞鋪設。\\n2. **交叉點纏繞綁緊**：使用長葛繩，在圓形圈環與縱向柳枝相交的每個節點**交替纏繞綁牢**。\\n3. **維持圓錐網格張力**：從25cm寬口向10cm窄尾自然收攏，依序將四個圈環全部編織固定。\\n4. **尾部取魚口活結收尾**：將最小圈環後方聚攏的枝條末端束起，打上**一拉即開的活結**，方便日後倒出漁獲。\",\n      \"actionNote\": \"> 間距標準：若縱向枝條間隙超過一指寬（1.5cm），進入的魚會從側面縫隙鑽出逃脫。請編得夠密，僅容手指尖勉強穿過。\",\n      \"svgFileName\": \"pr11-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // CONICAL WICKER BODY WEAVING\",\n        \"柳樹縱向枝條30～40根（間隔1～1.5cm）\",\n        \"4個圓形圈環與縱枝交叉纏繞綁緊\",\n        \"降低70%水流阻力的流線型圓錐籠身\",\n        \"[核心] 尾部取魚用快速開闔活結\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD MECHANICS\",\n        \"title\": \"流線型圓錐網格的水流阻力（Drag）分散力學\",\n        \"text\": \"1～1.5cm間距的縱向枝條網格能讓河水順暢通過，將急流沖走魚筌的水流阻力（拖曳力）**降低70%以上**，同時完全阻擋體寬**2cm以上**的淡水魚逃脫。\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"步驟3：製作向內收窄的倒鬚漏斗（單向閥）並縫合於籠口\",\n      \"description\": \"1. **編排倒鬚漏斗細枝**：取**16～20根**前臂長（約30～35cm）的細軟彈性柳枝，圍成一個小圓錐漏斗。\\n2. **設定內外口徑**：外侧寬口展開至**一拃半（直徑25cm）**以貼合籠身入口，內側窄口收縮至**三指併攏粗細（直徑5～6cm）**。\\n3. **保留內側彈性倒鬚尖端**：內側收窄末端**兩指節（5cm）**處不綁繩，讓枝尖自然向內聚攏，形成魚往內頂時張開、往後退時刺住卡死的單向門。\\n4. **嵌入籠口並縫合**：將完成的倒鬚漏斗塞入步驟2籠身的大口內側，用[野生葛繩](/protocol-05.html)將重疊的外圈緊密縫合成一體。\",\n      \"actionNote\": \"> 漏斗內口尺寸：若內側窄口比拳頭還大，魚會直接游出來。必須收窄至三指併攏寬度（直徑5～6cm），才能發揮單向止回閥的作用。\",\n      \"svgFileName\": \"pr11-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // ONE-WAY INVERTED FUNNEL VALVE\",\n        \"倒鬚漏斗外圈（與直徑25cm籠口縫合）\",\n        \"向內聚攏的彈性枝尖（直徑5～6cm窄口）\",\n        \"魚進入時張開、倒退時卡住的結構\",\n        \"[核心] 單向准許進入 & 徹底阻斷逆向逃脫\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD PHYSICS\",\n        \"title\": \"彈性細枝楔形的單向止回閥（Check-Valve）機制\",\n        \"text\": \"當魚向前游過漏斗時，流線型的魚頭能輕易將具彈性的細枝尖端向外推開；但一旦進入籠內想要掉頭游出，向內尖銳聚攏的枝尖就會卡住魚鰓蓋與魚鰭，從幾何結構上徹底封死退路。\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"步驟4：裝入壓艙石與誘餌，於淺灘水道打樁固定\",\n      \"description\": \"1. **放入壓艙石與餌袋**：解開尾部活結，放入防止上浮的**拳頭大河石2顆**與刺破樹葉包裹的**砸碎螺肉・蚯蚓餌包**，再次綁緊尾部。\\n2. **挑選岩縫淺灘水道**：尋找河水在岩石間收窄流動、**及膝水深（30～50cm）**的水道或水草陰影處作為放置點。\\n3. **漏斗口朝上游對準水流**：為了讓餌料氣味順流而下吸引魚群，將魚筌的**漏斗入口朝向水流來的上游（或斜對水流方向）**沉入河底。\\n4. **4根木樁與兩側石塊三點固定**：在魚筌兩側河床深深打入**4根前臂長木樁**並用繩綁住，或用重石夾緊兩側，確保夜間急流也不會滾動。\",\n      \"actionNote\": \"> 收穫與加熱烹調：隔天早上只需拉開尾部活結即可倒出漁獲。捕獲的淡水魚為預防寄生蟲感染，務必在[達科他無煙火坑](/protocol-06.html)或[橡木炭火](/protocol-09.html)上徹底烤熟後再食用。\",\n      \"svgFileName\": \"pr11-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // STREAM CHANNEL ANCHORING & BAIT PLUME\",\n        \"籠內壓艙河石2顆 & 砸碎川蜷誘餌袋\",\n        \"由上游往下游的水流 & 氣味擴散路徑\",\n        \"4根木樁及兩側岩石固定支撐\",\n        \"[核心] 順著氣味逆流而上並困在籠內的魚\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD ECOLOGY\",\n        \"title\": \"淡水魚的正趨流性（Positive Rheotaxis）與嗅覺誘引\",\n        \"text\": \"多數淡水魚為了提高魚鰓呼吸效率並攔截順流而下的食物，具有將頭部朝向上游逆水而游的**正趨流性**本能。當朝上游放置的魚筌將螺肉氣味散播至下游時，下游魚群便會順著氣味軌跡逆流而上，自動鑽入漏斗中。\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命失誤：未放壓艙石就直接將輕飄的魚筌丟入水中，或生吃捕獲的淡水魚\",\n    \"description\": \"柳枝編織的魚筌浮力很大，若內部不放重石且未打樁固定，幾分鐘內就會被水流沖走遺失。此外，生吃未煮熟的淡水魚會感染中華肝吸蟲等致命寄生蟲與水生細菌，引發劇烈腹痛與高燒。\",\n    \"consequence\": \"後果：魚筌被沖走導致斷糧，以及感染嚴重寄生蟲與細菌疾病\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"別再徒手追魚白費體力了！教你編織睡覺時也會自動抓魚的柳枝倒鬚魚籠！\",\n    \"body\": \"把河邊柔韌的柳枝彎成一拃半到拳頭大小的4個圓環，再每隔一指寬綁上40根長柳枝編成圓錐籠。最大的關鍵是塞在入口的倒鬚漏斗！把內口收窄到三指寬縫合，魚聞到砸碎的田螺香鑽進去後，就會被倒刺卡住再也出不來！\",\n    \"outro\": \"裡面放兩顆拳頭大的石頭並用木樁固定在淺灘，每天早上都有新鮮的魚！完整圖紙請見個人檔案連結。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr11-outcome.svg\",\n    \"title\": \"完成的柳枝單向倒鬚漏斗魚筌及淺灘水下捕獲剖面規格\",\n    \"description\": \"展示4段圓形圈環、1cm間距柳枝圓錐籠身、5cm單向彈性倒鬚漏斗口、內部2顆壓艙石與螺肉餌袋，以及河床木樁固定自動捕魚的水下剖面結構。\"\n  },\n  \"createdAt\": \"2026-10-16T13:38:00.000Z\",\n  \"contentHash\": \"037d4ce0763a3aa2\"\n}","content/protocols/locales/12-twin-can-wood-gas-stove.de.json":"{\n  \"protocolId\": \"PR-12\",\n  \"category\": \"FIRE\",\n  \"title\": \"Doppelwandiger Holzvergaser-Kocher aus 2 leeren Konservendosen, Schrottdraht und Zweigen\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[RAUCHFREIES HOCHTEMPERATUR-KOCHEN & 80% HOLZERSPARNIS]\",\n  \"summary\": \"In einer verlassenen Stadt oder im Ödland ist dickes Brennholz knapp, und ein offenes Feuer verrät durch schwarzen Rauch sofort den Standort, während der Wind die Hitze verweht. Steckt man zwei unterschiedlich große Stahlblechdosen ineinander und fixiert sie mit dem blanken Kupfer- oder Stahlkern eines alten Elektrokabels, entsteht ein rauchfreier Holzvergaser-Kocher, der den aufsteigenden Rauch selbst verbrennt. Zwei Handvoll trockener Zweige bringen 1 Liter Wasser in 8 Minuten völlig rauchfrei zum Kochen.\",\n  \"timeRequired\": \"35 Min (10m Ausbrennen + 15m Lochen + 10m Zusammenbau & Zünden)\",\n  \"successRate\": \"95% (bei Verwendung geriffelter Stahldosen & Zündung von oben)\",\n  \"difficulty\": \"Mittel (Vorsicht vor scharfen Blechkanten & giftigem Beschichtungsrauch beim Vorbrand)\",\n  \"outputPerHour\": \"20 Min rauchfreie 850°C-Flamme mit 2 Handvoll (200g) Zweigen (kocht 1,5L Wasser ab)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"1 große äußere Stahldose (12–15cm) & 1 kleinere innere Stahldose (8–10cm)\",\n      \"desc\": \"Zwei stabile, geriffelte Stahlblechdosen (große Suppen- oder Milchpulverdose außen, normale Konservendose innen), zwischen denen ein fingerbreiter (1,5–2cm) Luftspalt bleibt.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"50cm geborgenes Elektrokabel (ohne Isolierung)\",\n      \"desc\": \"Schneiden Sie die äußere Isolierung mit einer [scharfen Steinklinge oder Steinaxt](/protocol-04.html) ab und nutzen Sie den blanken Kupfer- oder Stahldrahtkern (1,5–3mm dick) zur feuerfesten Befestigung und als Topfkreuz.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Spitzer Schrottnagel (oder Steinahle) und Schlagstein\",\n      \"desc\": \"Spitzer Metallstift oder Steinpfriem samt faustgroßem Flussstein zum Einschlagen der Primär- und Sekundärluftdüsen.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Zwei Handvoll daumenlanger trockener Zweige & Kiefernharz-Zunder\",\n      \"desc\": \"Knochentrockene Laubholzzweige auf Daumenlänge gebrochen zur vertikalen Schichtung sowie [Kiefernharzbrocken](/protocol-10.html) und trockene Rinde für die Zündung von oben.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Schritt 1: Stabile Stahldosen wählen, Kabel abisolieren & innere Epoxidschicht ausbrennen\",\n      \"description\": \"1. **Geriffelte Stahldosen auswählen**: Wählen Sie zwei feste Konservendosen mit querverlaufenden Verstärkungsrillen, die sich mit der Hand nicht eindrücken lassen. Zwischen Innen- und Außendose muss ringsum **eine Fingerbreite (1,5–2cm)** Luftspalt bleiben.\\n2. **Elektrokabel abisolieren**: Ritzen Sie den Mantel eines alten Kabels mit einer [scharfen Steinklinge](/protocol-04.html) längs auf und ziehen Sie **50cm blanken Kupfer- oder Stahldraht** heraus.\\n3. **5 Minuten Ausbrennen der Beschichtung**: Füllen Sie vor dem Lochen trockenes Laub und Reisig in beide leeren Dosen und **brennen Sie diese im Freien 5 Minuten lang aus**, um Innenbeschichtung und Farbe restlos zu verkohlen.\\n4. **Mattgraue Stahloberfläche prüfen**: Sobald kein beißender Geruch mehr aufsteigt und das Innere **matt dunkelgrau** ist, lassen Sie die Dosen im Schatten abkühlen.\",\n      \"actionNote\": \"> Giftgas- & Metall-Check: Ohne vorheriges Ausbrennen gelangen giftige Dämpfe ins Kochwasser. Dünne Getränkedosen schmelzen wie Papier – prüfen Sie anhand der Fotos unten die geriffelten Stahldosen und den blanken Drahtkern.\",\n      \"svgFileName\": \"pr12-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // STEEL CAN SELECTION & LINER BURN-OFF\",\n        \"ÄUSSERE STAHLDOSE (12-15CM) & INNENDOSE\",\n        \"FINGERBREITER (1.5-2CM) DOPPELWAND-LUFTSPALT\",\n        \"5 MIN AUSBRENNEN ENTFERNT EPOXIDSCHICHT\",\n        \"[KERN] STABILE STAHLDOSE & BLANKER DRAHTKERN\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"URBAN SALVAGE\",\n        \"title\": \"Weißblech-Stahl (Schmelzpunkt 1.500°C) und thermische Entfernung von BPA-Harz\",\n        \"text\": \"Verzinnte Kohlenstoffstahldosen haben einen Schmelzpunkt von rund **1.500°C** und halten der 800–900°C heißen Holzgasflamme dauerhaft stand. Getränkedosen schmelzen bereits bei **660°C**. Das vorherige Ausbrennen im Freien zersetzt die innere BPA-Epoxidschicht vollständig.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"Hitzefeste geriffelte Stahl-Konservendose\",\n            \"scientificName\": \"Tin-Coated Corrugated Carbon Steel\",\n            \"categoryTag\": \"Urbaner Metallschrott / Brennkammerkörper\",\n            \"imageFileName\": \"id-steel-tin-can.jpg\",\n            \"hudCode\": \"FIG. SALV-12A // MACRO OPTIC\",\n            \"hudStatus\": \"MELT POINT 1500C: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"RILLEN\",\n                \"value\": \"Umlaufende **quergeprägte Verstärkungsrippen** an der Zylinderwand verhindern ein Verbiegen bei Hitze.\"\n              },\n              {\n                \"label\": \"RAND\",\n                \"value\": \"Dick gefalzte Ober- und Unterkanten erzeugen beim Anschlagen mit einem Stein einen **satten, klaren Metallklang**.\"\n              },\n              {\n                \"label\": \"VORBRAND\",\n                \"value\": \"Nach 5 Minuten Laubfeuer verschwindet der Innenglanz und hinterlässt **sicheren, matt dunkelgrauen Stahl**.\"\n              }\n            ],\n            \"fieldUse\": \"Doppelwand-Holzvergaser, Notfall-Abkochgefäß, Holzkohlebehälter\"\n          },\n          {\n            \"name\": \"Blanker Schrottdraht & trockene Zweige\",\n            \"scientificName\": \"Stripped Copper/Steel Core & Dry Hardwood\",\n            \"categoryTag\": \"Stadt-Natur-Hybrid / Bindedraht & Brennstoff\",\n            \"imageFileName\": \"id-salvage-wire-twigs.jpg\",\n            \"hudCode\": \"FIG. SALV-12B // MACRO OPTIC\",\n            \"hudStatus\": \"INSULATION STRIPPED: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"ADER\",\n                \"value\": \"Mit der Steinklinge komplett abisolierter **massiver Kupfer- oder Stahldraht** (**1,5–3mm** stark).\"\n              },\n              {\n                \"label\": \"HOLZ\",\n                \"value\": \"Fingerdicke, daumenlange **knochentrockene Laubholzzweige**, die beim Biegen mit hellem Knacken brechen.\"\n              },\n              {\n                \"label\": \"ZUNDER\",\n                \"value\": \"Goldene **Kiefernharzstücke und trockene Rinde** ganz oben auf dem Holzstapel für die Top-Down-Zündung.\"\n              }\n            ],\n            \"fieldUse\": \"Feuerfeste Doppelwand-Bindung, Kreuz-Topfauflage, rauchfreier Holzgas-Brennstoff\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Schritt 2: Primärrost-Löcher und sekundäre Holzgas-Düsen in die Innendose schlagen\",\n      \"description\": \"1. **Innendose abstützen**: Stecken Sie ein passendes Holzstück oder feste Erde in die kleine Dose, damit das Blech beim Einschlagen nicht eindellt.\\n2. **Untere Primärlöcher einschlagen**: Schlagen Sie mit dem spitzen Nagel oder Steinpfriem und dem Schlagstein **12–15 kleinfingerdicke (8mm) Löcher** gleichmäßig in den Boden der kleinen Dose.\\n3. **Obere Sekundär-Gasdüsen einschlagen**: Schlagen Sie **eine Fingerbreite (1,5cm) unterhalb des oberen Randes** ringsum **8–10 daumendicke (10–12mm) Löcher** in die Seitenwand der kleinen Dose.\\n4. **Scharfe Blechgrate glätten**: Klopfen Sie nach innen stehende scharfe Metallkanten mit dem Stein flach an die Wand, um Schnittwunden zu vermeiden.\",\n      \"actionNote\": \"> Funktion der oberen Düsen: Die 8–10 großen Löcher unter dem oberen Rand wirken wie Gasherd-Düsen, die vorgewärmten Sauerstoff in den Rauch blasen. Machen Sie diese daumendick für starke Flammenstrahlen.\",\n      \"svgFileName\": \"pr12-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // INNER BURN CHAMBER PERFORATION\",\n        \"INNENBODEN: 12-15 PRIMÄRLUFTLÖCHER (8MM)\",\n        \"OBEN: 8-10 SEKUNDÄR-GASDÜSEN (10-12MM)\",\n        \"MIT DORN & STEIN LOCHEN, GRATE GLÄTTEN\",\n        \"[KERN] ASCHEROST UNTEN & GASDÜSEN OBEN FERTIG\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"Querschnittsverhältnis zwischen Primär-Pyrolyserost und Sekundär-Gasdüsen\",\n        \"text\": \"Die kleineren Bodenlöcher liefern begrenzte Primärluft zur Holzvergasung und lassen Asche durchfallen. Die großen 10–12mm-Düsen oben pressen hocherhitzte Sekundärluft direkt in das aufsteigende Kohlenmonoxid und Methan und verbrennen den Rauch vollständig.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Schritt 3: Außendose öffnen, Innendose einsetzen & mit blankem Draht fixieren\",\n      \"description\": \"1. **Untere Lufteinlässe in die Außendose schlagen**: Schlagen Sie rings um die große Außendose **1,5cm über dem Boden 8–10 daumendicke (12mm) Kaltluftlöcher** ein.\\n2. **Obere Öffnung ausschneiden**: Meißeln Sie eine runde Öffnung in den Deckel der großen Dose, sodass die kleine Innendose stramm bis zum oberen Rand hineinpasst.\\n3. **Beide Dosen mit Draht verbinden**: Ziehen Sie den **blanken Kupfer- oder Stahldraht** durch gegenüberliegende Randlöcher und verdrillen Sie ihn fest, sodass die Innendose **2cm über dem Außenboden** frei schwebt.\\n4. **Kreuz-Topfauflage biegen**: Biegen Sie den restlichen dicken Draht über der Öffnung zu einem **2–3cm hohen Topfkreuz**, damit der Topf die Flamme nicht erstickt.\",\n      \"actionNote\": \"> Wichtiger Abgasspalt: Stellen Sie niemals einen Topf direkt flach auf den Dosenrand! Ohne den 2–3cm hohen Drahtabstand erstickt die Sekundärflamme sofort und qualmt schwarz.\",\n      \"svgFileName\": \"pr12-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DOUBLE-WALL NESTING & WIRE BINDING\",\n        \"AUSSENDOSE UNTEN: KALTLUFTEINLÄSSE (12MM)\",\n        \"INNENDOSE MIT 1.5-2CM LUFTSPALT EINGESETZT\",\n        \"DRAHT-RANDVERBINDUNG & 2-3CM TOPFKREUZ\",\n        \"[KERN] DOPPELWAND-VORWÄRMKANAL FERTIGGESTELLT\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"STRUCTURAL MECHANICS\",\n        \"title\": \"Warum blanker Metalldraht bei 850°C jeder Pflanzenschnur überlegen ist\",\n        \"text\": \"Pflanzenschnüre verkohlen und reißen ab 300°C. Blanker Kupferdraht (Schmelzpunkt **1.085°C**) oder Stahldraht (**1.500°C**) aus alten Elektrokabeln hält die Doppelwand und einen vollen Wassertopf mitten in der 850°C-Flammenzone sicher zusammen.\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Schritt 4: Zweige senkrecht schlichten, von oben entzünden & rauchfrei Wasser kochen\",\n      \"description\": \"1. **Zweige senkrecht einstellen**: Brechen Sie trockene Laubholzzweige auf Daumenlänge und stellen Sie diese **senkrecht und dicht an dicht** in die Innendose bis **knapp unter die oberen Düsenlöcher**.\\n2. **Zündung von oben nach unten (Top-Down)**: Legen Sie trockene Rinde und [Kiefernharz-Zunder](/protocol-10.html) **oben auf die senkrechten Zweige** und entzünden Sie diese von oben mit Glut vom [Feuerbogen](/protocol-02.html).\\n3. **Sekundäre Holzgas-Flammen prüfen**: Nach 2–3 Minuten erhitzt sich die Doppelwand; aus den oberen Düsen schießen **hellgelb-bläuliche Flammenstrahlen** nach innen und der Rauch verschwindet komplett.\\n4. **Wasser abkochen & Pflanzenkohle sichern**: Setzen Sie Ihr Gefäß mit [gefiltertem Wasser](/protocol-01.html) auf das Drahtkreuz (kocht in 7–8 Minuten) und löschen Sie danach die rote Restglut mit Erde ab, um [reine Holzkohle](/protocol-09.html) zu gewinnen.\",\n      \"actionNote\": \"> Warum von oben anzünden?: Von unten angezündet qualmt das gesamte Holz auf einmal. Von oben brennt die Glut langsam wie eine Kerze nach unten, sodass aller aufsteigende Rauch durch den oberen Flammenring gezogen und restlos verbrannt wird.\",\n      \"svgFileName\": \"pr12-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // TOP-DOWN PYROLYSIS & SECONDARY JETS\",\n        \"TROCKENE ZWEIGE SENKRECHT UNTER DEN DÜSEN\",\n        \"ZÜNDUNG VON OBEN MIT KIEFERNHARZ & RINDE\",\n        \"HEISSE LUFTSTRAHLEN VERBRENNEN HOLZGAS RAUCHFREI\",\n        \"[KERN] KOCHT 1L WASSER IN 8 MIN MIT ZWEI HANDVOLL\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"COMBUSTION SCIENCE\",\n        \"title\": \"Aufstrom-Holzvergasung mit Kopfzündung (TLUD) und Pflanzenkohle-Gewinnung\",\n        \"text\": \"Beim TLUD-Holzvergaser wandert die Pyrolysezone langsam von oben nach unten. Die darunter entstehenden Holzgase müssen zwingend durch den 850°C heißen Sekundärluftring strömen, wodurch über 95% der Rauchpartikel verbrennen und am Boden reine Kohle zurückbleibt.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Tödlicher Fehler: Kochen in unausgebrannten Epoxid-Dosen oder Verwendung dünner Getränkedosen\",\n    \"description\": \"Konservendosen sind innen mit Epoxidharz beschichtet, das ohne vorheriges Ausbrennen giftige Dämpfe ins Wasser abgibt. Zudem schmelzen dünne Getränkedosen bei 660°C und brechen unter dem kochenden Wassertopf zusammen.\",\n    \"consequence\": \"Folge: Giftgasinhalation sowie schwere Verbrühungen durch Einsturz des Kochers\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Mit nur 2 leeren Konservendosen und einer Handvoll Zweige baust du einen rauchfreien Jet-Kocher, der Wasser in 8 Minuten kocht!\",\n    \"body\": \"Wähle zwei unterschiedlich große Stahldosen und brenne trockenes Laub darin 5 Minuten lang aus, um die giftige Innenbeschichtung zu entfernen. Schlage Löcher in den Boden der kleinen Dose und 8 daumendicke Düsen unter den oberen Rand. Loche die große Dose unten, stecke die kleine Dose hinein und fixiere sie mit blankem Draht. Fülle trockene Zweige senkrecht ein und zünde sie von oben an – die heiße Luft zwischen den Wänden verbrennt den Rauch selbst wie ein Gasherd!\",\n    \"outro\": \"Kein Rauch verrät deinen Standort, und nach 8 Minuten kocht das Wasser. Den Bauplan findest du über den Link im Profil.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr12-outcome.svg\",\n    \"title\": \"Fertiger Doppelwand-Holzvergaser-Kocher (Rauchfreier 850°C-Jetbrenner)\",\n    \"description\": \"Gebaut aus zwei geborgenen Stahldosen und blankem Draht mit 1,5–2cm Doppelwand-Luftspalt, unteren Kaltlufteinlässen, oberen Sekundärluftdüsen, Draht-Topfkreuz und rauchfreier 850°C-Holzgasverbrennung.\"\n  },\n  \"createdAt\": \"2026-10-17T10:12:00.000Z\",\n  \"contentHash\": \"00b85f08738b5163\"\n}","content/protocols/locales/12-twin-can-wood-gas-stove.en.json":"{\n  \"protocolId\": \"PR-12\",\n  \"category\": \"FIRE\",\n  \"title\": \"Twin-Can Double-Wall Wood Gas Stove Using Salvaged Cans, Scrap Wire & Dry Twigs\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[SMOKELESS HIGH-HEAT BOILING & 80% FUEL SAVING]\",\n  \"summary\": \"In a post-collapse city or barren wasteland, thick firewood is scarce, and an open campfire sends up black smoke that gives away your position while losing heat to the wind. By nesting two salvaged steel cans of different sizes to form a double-wall chamber and locking them with bare copper or steel core wire stripped from scrap electrical cable, you create a smokeless gasifier stove that burns the rising wood smoke itself. Just two handfuls of finger-thick dry twigs boil 1 liter of water in 8 minutes with zero visible smoke.\",\n  \"timeRequired\": \"35 mins (10m coating burn-off + 15m hole punching + 10m nesting & ignition)\",\n  \"successRate\": \"95% (when using rigid steel cans & top-down ignition)\",\n  \"difficulty\": \"Medium (watch for sharp metal burrs & toxic liner smoke during pre-burn)\",\n  \"outputPerHour\": \"20 mins of smokeless 850°C flame from 2 handfuls (200g) of twigs (boils 1.5L water)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"1 Large Outer Steel Can (12–15cm diameter) & 1 Smaller Inner Steel Can (8–10cm diameter)\",\n      \"desc\": \"Salvaged corrugated steel cans (large soup or milk-powder tin for the outer body; standard food tin for the inner chamber) leaving a finger-width (1.5–2cm) air gap between walls.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"50cm Salvaged Electrical Wire (Insulation Stripped)\",\n      \"desc\": \"Use a [sharp stone flake blade](/protocol-04.html) to strip the outer jacket from scrap cable, extracting the bare copper or steel core wire (1.5–3mm thick) for heat-proof binding and a pot stand.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Pointed Scrap Nail (or Stone Awl) & Hammer Stone\",\n      \"desc\": \"Hard pointed salvage spike or stone awl struck with a fist-sized river cobble to punch primary and secondary air-jet holes around the steel cans.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Two Handfuls of Thumb-Length Dry Twigs & Pine Resin Tinder\",\n      \"desc\": \"Bone-dry hardwood twigs snapped to thumb length for vertical packing, plus [pine resin chunks](/protocol-10.html) and dry bark for top-down ignition.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Step 1: Select Rigid Steel Cans, Strip Scrap Wire & Pre-Burn Inner Epoxy Coatings\",\n      \"description\": \"1. **Select Corrugated Steel Cans**: Choose two rigid steel food cans with horizontal reinforcement ribs that do not flex when squeezed. When the small can is held inside the large can, a **finger-width (1.5–2cm)** gap must remain all around.\\n2. **Strip Scrap Electrical Wire**: Slice along the outer insulation of salvaged electrical wire using a [sharp stone flake blade](/protocol-04.html) and pull out **50cm of bare copper or steel core wire**.\\n3. **Pre-Burn Inner Epoxy Liner**: Before punching holes, stuff dry leaves and twigs inside both empty cans and **burn them outdoors for 5 minutes** to incinerate the interior BPA epoxy coating and outer paint.\\n4. **Verify Matte Grey Surface**: Once acrid smoke stops and the inner steel turns **matte dark grey**, let both cans cool completely in the shade.\",\n      \"actionNote\": \"> Coating & Metal Check: Skipping the 5-minute pre-burn contaminates your boiling water with toxic fumes. Thin soda cans melt like paper in high heat—use the field identification photos below to select ribbed steel cans and stripped metal wire.\",\n      \"svgFileName\": \"pr12-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // STEEL CAN SELECTION & LINER BURN-OFF\",\n        \"OUTER STEEL CAN (12-15CM) & INNER CAN\",\n        \"FINGER-WIDTH (1.5-2CM) DOUBLE-WALL AIR GAP\",\n        \"5-MIN PRE-BURN REMOVES INNER EPOXY LINER\",\n        \"[KEY] SELECT HEAVY STEEL CAN & STRIPPED WIRE CORE\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"URBAN SALVAGE\",\n        \"title\": \"Tinplate Steel (1,500°C Melting Point) vs Thin Cans & Epoxy Burn-Off Safety\",\n        \"text\": \"Tin-coated carbon steel food cans have a melting point near **1,500°C**, easily enduring repeated 800–900°C wood-gas combustion. Thin beverage cans melt at **660°C** and collapse rapidly. Pre-burning the cans in open air carbonizes the internal anti-corrosion BPA epoxy liner so cooking remains clean and non-toxic.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"Corrugated Steel Food / Milk Can\",\n            \"scientificName\": \"Tin-Coated Corrugated Carbon Steel\",\n            \"categoryTag\": \"Urban Metal Salvage / Stove Body\",\n            \"imageFileName\": \"id-steel-tin-can.jpg\",\n            \"hudCode\": \"FIG. SALV-12A // MACRO OPTIC\",\n            \"hudStatus\": \"MELT POINT 1500C: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"RIBS\",\n                \"value\": \"Horizontal **raised corrugation beads** around the cylinder wall prevent warping or crushing under hand pressure.\"\n              },\n              {\n                \"label\": \"RIM\",\n                \"value\": \"Thick double-seamed top and bottom rims produce a **solid metallic ring** when tapped with a stone.\"\n              },\n              {\n                \"label\": \"PREP\",\n                \"value\": \"After a 5-minute leaf burn, the glossy inner coating disappears, leaving a **safe matte dark-grey steel wall**.\"\n              }\n            ],\n            \"fieldUse\": \"Double-wall wood gas stove body, emergency water boiling pot, charcoal tin\"\n          },\n          {\n            \"name\": \"Stripped Scrap Wire & Dry Twigs\",\n            \"scientificName\": \"Stripped Copper/Steel Core & Dry Hardwood\",\n            \"categoryTag\": \"Urban-Nature Hybrid / Fastener & Fuel\",\n            \"imageFileName\": \"id-salvage-wire-twigs.jpg\",\n            \"hudCode\": \"FIG. SALV-12B // MACRO OPTIC\",\n            \"hudStatus\": \"INSULATION STRIPPED: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"CORE\",\n                \"value\": \"Bare **solid copper or galvanized steel wire core** (**1.5–3mm** thick) with all outer insulation stripped off.\"\n              },\n              {\n                \"label\": \"FUEL\",\n                \"value\": \"Finger-thick **bone-dry hardwood twigs** snapped to thumb length that break with a crisp snap.\"\n              },\n              {\n                \"label\": \"TINDER\",\n                \"value\": \"Golden **pine resin chunks and dry bark curls** placed at the top of the fuel stack for top-down ignition.\"\n              }\n            ],\n            \"fieldUse\": \"High-heat double-wall binding, cross-wire pot trivet, smokeless biomass fuel\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Step 2: Punch Primary Grate & Secondary Wood-Gas Nozzle Holes in the Inner Can\",\n      \"description\": \"1. **Brace the Inner Can**: Pack a tight wooden block or damp earth inside the smaller can so the steel wall does not dent while punching.\\n2. **Punch Bottom Primary Holes**: Using a pointed nail or stone awl and hammer stone, punch **12–15 pinky-thick (8mm) holes** evenly across the bottom of the small can.\\n3. **Punch Upper Secondary Gas Nozzles**: Measure **one finger-joint (1.5cm) below the top rim** of the small can and punch **8–10 thumb-thick (10–12mm) holes** evenly around the circumference.\\n4. **Flatten Sharp Metal Burrs**: Tap any jagged inner metal burrs flat against the wall with a stone edge to prevent hand cuts.\",\n      \"actionNote\": \"> Role of Upper Nozzles: The 8–10 large holes near the top rim act as gas-burner jets that mix preheated oxygen with rising wood smoke. Make them thumb-thick (10–12mm) for strong secondary flame jets.\",\n      \"svgFileName\": \"pr12-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // INNER BURN CHAMBER PERFORATION\",\n        \"INNER BOTTOM PRIMARY HOLES (8MM X 12-15)\",\n        \"UPPER SECONDARY GAS NOZZLES (10-12MM X 8-10)\",\n        \"PUNCH WITH SPIKE & STONE, FLATTEN BURRS\",\n        \"[KEY] BOTTOM ASH DRAIN & UPPER JET NOZZLES\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"Primary Pyrolysis Grate vs Secondary Gas-Jet Nozzle Sizing\",\n        \"text\": \"Small holes in the floor of the inner can supply limited primary air for wood pyrolysis and let fine ash drop out. The larger 10–12mm upper holes inject superheated secondary oxygen directly into rising carbon monoxide and methane vapors, converting thick smoke into clean thermal energy.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Step 3: Cut the Outer Can Rim, Nest the Inner Chamber & Bind with Stripped Scrap Wire\",\n      \"description\": \"1. **Punch Outer Bottom Intake Holes**: Around the side wall of the large outer can, **1.5cm above its floor**, punch **8–10 thumb-thick (12mm) cold-air intake holes**.\\n2. **Cut Center Opening in Outer Top**: Chisel out a circular opening in the top lid of the large can so the small inner can slides in tightly up to its top rim.\\n3. **Lock Both Cans with Scrap Wire**: Thread the **stripped copper or steel wire** through two pairs of opposing rim holes and twist tightly with a stick so the inner can hangs suspended **2cm above the outer floor**.\\n4. **Weave Cross-Wire Pot Trivet**: Bend the remaining thick scrap wire into a **2–3cm raised cross-bar stand (trivet)** across the top rim so a cooking pot does not choke the flame.\",\n      \"actionNote\": \"> Exhaust Gap Check: Never rest a flat pot directly flush on the can rim! Without a 2–3cm wire trivet gap for exhaust draft, the secondary flame suffocates immediately and pours out black smoke.\",\n      \"svgFileName\": \"pr12-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DOUBLE-WALL NESTING & WIRE BINDING\",\n        \"OUTER LOWER COLD AIR INTAKES (12MM X 8-10)\",\n        \"INNER CAN SUSPENDED WITH 1.5-2CM WALL GAP\",\n        \"STRIPPED WIRE RIM LOCK & CROSS POT TRIVET\",\n        \"[KEY] PREHEATED UPDRAFT CHANNEL COMPLETED\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"STRUCTURAL MECHANICS\",\n        \"title\": \"Why Stripped Metal Wire Outperforms Natural Cordage on High-Heat Stoves\",\n        \"text\": \"Natural plant cordage chars and snaps above 300°C. Bare copper (melting point **1,085°C**) and carbon steel wire (**1,500°C**) salvaged from urban cables hold the concentric double wall and pot weight securely right inside the 850°C flame zone.\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Step 4: Pack Dry Twigs Vertically, Ignite from the Top Down & Boil Water Smokelessly\",\n      \"description\": \"1. **Pack Dry Twigs Vertically**: Snap finger-thick dry hardwood twigs to thumb length and pack them **standing vertically** inside the inner can up to just **below the upper nozzle holes**.\\n2. **Top-Down Ignition**: Place dry bark curls and [pine resin tinder](/protocol-10.html) on **top of the vertical twigs** and light from above using an ember from a [Bow Drill Fire](/protocol-02.html).\\n3. **Verify Secondary Wood-Gas Jets**: After 2–3 minutes, as the inner wall heats up, watch **bright golden-blue flame jets** shoot inward from the upper 10–12mm holes while visible smoke disappears.\\n4. **Boil Water & Harvest Biochar**: Set your pot of [filtered water](/protocol-01.html) on the wire trivet to reach a rolling boil in 7–8 minutes, then smother the remaining red coals with dirt to save [clean charcoal](/protocol-09.html).\",\n      \"actionNote\": \"> Why Light from the Top? Lighting from the bottom sends all twigs into smoke at once. Lighting from the top makes the ember zone burn slowly downward like a candle, forcing rising wood smoke right through the upper flame jets.\",\n      \"svgFileName\": \"pr12-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // TOP-DOWN PYROLYSIS & SECONDARY JETS\",\n        \"DRY TWIGS PACKED BELOW UPPER NOZZLE HOLES\",\n        \"TOP-DOWN IGNITION WITH PINE RESIN & BARK\",\n        \"PREHEATED AIR JETS IGNITE WOOD GAS (SMOKELESS)\",\n        \"[KEY] 1L WATER BOILED IN 8 MIN WITH TWO HANDFULS\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"COMBUSTION SCIENCE\",\n        \"title\": \"Top-Down Lit Updraft (TLUD) Gasification & Biochar Co-Production\",\n        \"text\": \"In a TLUD wood-gas stove, the pyrolysis front moves downward through the vertical twigs. Volatile gases released below must pass through the 850°C secondary air-jet ring at the top, burning off 95%+ of smoke particulates and leaving pure carbon char at the bottom.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Fatal Mistake: Cooking in Unburned Epoxy-Lined Cans or Using Thin Beverage Cans\",\n    \"description\": \"Food cans are coated inside with anti-rust BPA epoxy resin; cooking without a prior 5-minute open-air burn-off releases toxic fumes into your water and lungs. Furthermore, thin beverage cans melt at 660°C and collapse suddenly under a boiling pot, causing severe scalding burns.\",\n    \"consequence\": \"Consequence: Toxic fume inhalation and stove collapse spilling boiling water\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"With just two salvaged tin cans and a handful of twigs, you can build a smokeless jet stove that boils water in 8 minutes!\",\n    \"body\": \"First, pick two different-sized steel food cans and burn dry leaves inside for 5 minutes to burn off the toxic inner liner. Punch 8mm air holes in the bottom of the small can and 8 thumb-thick gas nozzles around its top rim. Punch air intakes near the bottom of the large can, nest the small can inside, and lock them with bare wire stripped from scrap cable. Pack dry twigs vertically and light from the top! Hot air rises between the double walls and ignites the smoke itself into a roaring gas-burner flame!\",\n    \"outro\": \"Zero smoke means zero detection, and water boils in 8 minutes. Check the full blueprint at the link in bio.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr12-outcome.svg\",\n    \"title\": \"Completed Twin-Can Double-Wall Wood Gas Stove (850°C Smokeless Jet Burner)\",\n    \"description\": \"Built from two salvaged steel cans and stripped scrap wire, featuring a 1.5–2cm double-wall air preheat channel, lower cold-air intakes, upper secondary oxygen nozzles, a cross-wire pot trivet, and smokeless 850°C wood-gas combustion.\"\n  },\n  \"createdAt\": \"2026-10-17T10:12:00.000Z\",\n  \"contentHash\": \"00b85f08738b5163\"\n}","content/protocols/locales/12-twin-can-wood-gas-stove.es.json":"{\n  \"protocolId\": \"PR-12\",\n  \"category\": \"FIRE\",\n  \"title\": \"Estufa de Gas de Leña de Doble Combustión con 2 Latas Vacías, Cable Pelado y Ramitas\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[COCCIÓN SIN HUMO A ALTA TEMPERATURA Y 80% AHORRO DE LEÑA]\",\n  \"summary\": \"En una ciudad colapsada o en terreno baldío es difícil hallar leña gruesa, y encender una fogata común levanta humo negro que delata tu posición además de perder calor con el viento. Al encajar dos latas de acero vacías de distinto tamaño para formar una cámara de doble pared y sujetarlas con el núcleo de cobre o hierro de un cable eléctrico pelado, obtienes un hornillo sin humo que quema el propio gas de la madera. Con solo dos puñados de ramitas secas hierves 1 litro de agua en 8 minutos sin emitir humo.\",\n  \"timeRequired\": \"35 min (10m quema de revestimiento + 15m perforación + 10m ensamblaje y encendido)\",\n  \"successRate\": \"95% (usando latas de acero estriado y encendido desde arriba)\",\n  \"difficulty\": \"Media (cuidado con los bordes cortantes de chapa y el humo del barniz durante la purga)\",\n  \"outputPerHour\": \"20 min de llama limpia a 850°C con dos puñados (200g) de ramitas (esteriliza 1.5L de agua)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"1 Lata Grande de Acero Exterior (12–15cm) y 1 Lata Pequeña de Acero Interior (8–10cm)\",\n      \"desc\": \"Dos latas rígidas de acero con nervaduras horizontales que, al encajarse una dentro de otra, dejen un espacio de un nudillo (1.5–2cm) entre sus paredes.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"50cm de Cable Eléctrico Recuperado (Sin Funda Aislante)\",\n      \"desc\": \"Use una [laja de piedra afilada o hacha de piedra](/protocol-04.html) para pelar la funda exterior del cable y extraer el alambre desnudo de cobre o acero (1.5–3mm) para fijar las latas y armar el soporte de olla.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Clavo de Chatarra Puntiagudo (o Punzón de Piedra) y Piedra Martillo\",\n      \"desc\": \"Clavo grueso recuperado o punzón de piedra golpeado con un canto rodado del tamaño del puño para perforar las toberas de aire.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Dos Puñados de Ramitas Secas del Largo del Pulgar y Yesca de Resina\",\n      \"desc\": \"Ramitas secas de madera dura partidas al tamaño del pulgar para carga vertical, junto con [trozos de resina de pino](/protocol-10.html) y corteza seca para el encendido superior.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Paso 1: Seleccionar Latas de Acero, Pelar el Cable y Quemar el Revestimiento Epoxi Interior\",\n      \"description\": \"1. **Seleccionar Latas de Acero Estriado**: Elija dos latas rígidas de conserva con estrías horizontales de refuerzo que no se doblen al apretarlas. Al colocar la pequeña dentro de la grande debe quedar un canal de aire del **ancho de un nudillo (1.5–2cm)** alrededor.\\n2. **Pelar el Cable Eléctrico**: Corte longitudinalmente el aislamiento del cable con una [laja de piedra afilada](/protocol-04.html) y extraiga **50cm de alambre metálico desnudo** de cobre o acero.\\n3. **Quema Previa de 5 Minutos**: Antes de hacer agujeros, llene ambas latas vacías con hojas y ramitas secas y **quémelas al aire libre durante 5 minutos** para carbonizar el barniz epoxi interior y la pintura.\\n4. **Verificar el Acero Gris Mate**: Cuando desaparezca el olor químico y el interior luzca **gris oscuro mate**, deje enfriar las latas a la sombra.\",\n      \"actionNote\": \"> Control de Toxicidad y Metal: Omitir la quema previa contamina el agua con vapores tóxicos. Las latas blandas de bebida se derriten rápido; guíese por las fotos reales de abajo para elegir latas de acero estriado y alambre pelado.\",\n      \"svgFileName\": \"pr12-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // STEEL CAN SELECTION & LINER BURN-OFF\",\n        \"LATA EXTERIOR (12-15CM) Y LATA INTERIOR\",\n        \"CANAL DE AIRE DE 1.5-2CM ENTRE PAREDES\",\n        \"QUEMA DE 5 MIN ELIMINA EL BARNIZ EPOXI\",\n        \"[CLAVE] ELEGIR LATA DE ACERO Y ALAMBRE PELADO\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"URBAN SALVAGE\",\n        \"title\": \"Acero Estañado (Punto de Fusión 1,500°C) y Eliminación Térmica de Resina BPA\",\n        \"text\": \"Las latas de conserva de acero al carbono tienen un punto de fusión cercano a **1,500°C**, soportando sin deformarse los 800–900°C del gas de leña. Las latas de refresco se funden a **660°C**. La quema previa en vacío elimina la película interna de bisfenol (BPA) para cocinar de forma segura.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"Lata de Acero Estriado de Alta Resistencia\",\n            \"scientificName\": \"Tin-Coated Corrugated Carbon Steel\",\n            \"categoryTag\": \"Chatarra Metálica Urbana / Cuerpo del Hornillo\",\n            \"imageFileName\": \"id-steel-tin-can.jpg\",\n            \"hudCode\": \"FIG. SALV-12A // MACRO OPTIC\",\n            \"hudStatus\": \"MELT POINT 1500C: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"ESTRÍAS\",\n                \"value\": \"Anillos horizontales **en relieve (nervaduras)** en la pared cilíndrica que impiden que la lata se aplaste con la mano.\"\n              },\n              {\n                \"label\": \"BORDE\",\n                \"value\": \"Bordes superior e inferior doblemente engarzados que emiten un **sonido metálico grave y firme** al golpearlos.\"\n              },\n              {\n                \"label\": \"PURGA\",\n                \"value\": \"Tras 5 minutos de fuego con hojas, desaparece el brillo interior y queda una **pared segura de acero gris mate**.\"\n              }\n            ],\n            \"fieldUse\": \"Cámara doble de estufa de gas de leña, recipiente para hervir agua, bote de carbón\"\n          },\n          {\n            \"name\": \"Alambre Pelado y Ramitas Secas\",\n            \"scientificName\": \"Stripped Copper/Steel Core & Dry Hardwood\",\n            \"categoryTag\": \"Híbrido Urbano-Natural / Fijación y Combustible\",\n            \"imageFileName\": \"id-salvage-wire-twigs.jpg\",\n            \"hudCode\": \"FIG. SALV-12B // MACRO OPTIC\",\n            \"hudStatus\": \"INSULATION STRIPPED: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"NÚCLEO\",\n                \"value\": \"Alambre sólido **de cobre rojizo o acero gris** (**1.5–3mm** de grosor) totalmente libre de funda aislante.\"\n              },\n              {\n                \"label\": \"LEÑA\",\n                \"value\": \"Ramitas secas de madera dura del **grosor de un dedo y largo del pulgar** que se parten con un chasquido seco.\"\n              },\n              {\n                \"label\": \"YESCA\",\n                \"value\": \"Trozos dorados de **resina de pino y virutas de corteza seca** colocados arriba para iniciar el fuego hacia abajo.\"\n              }\n            ],\n            \"fieldUse\": \"Amarre ignífugo de doble pared, parrilla cruzada para olla, biomasa sin humo\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Paso 2: Perforar los Orificios Primarios y las Toberas Secundarias en la Lata Interior\",\n      \"description\": \"1. **Calzar la Lata Pequeña**: Rellene el interior de la lata pequeña con un taco de madera o tierra firme para no abollarla al golpear.\\n2. **Perforar el Fondo Primario**: Con el clavo puntiagudo o punzón y la piedra martillo, abra **12–15 agujeros del grosor del meñique (8mm)** repartidos por el fondo de la lata pequeña.\\n3. **Perforar las Toberas Superiores de Gas**: A **un nudillo (1.5cm) por debajo del borde superior** de la lata pequeña, perfore **8–10 agujeros del grosor del pulgar (10–12mm)** alrededor de toda la circunferencia.\\n4. **Aplanar las Rebabas Cortantes**: Golpee con el canto de la piedra las rebabas metálicas internas para aplanarlas y evitar cortes.\",\n      \"actionNote\": \"> Función de las Toberas Superiores: Los 8–10 agujeros grandes bajo el borde superior actúan como los quemadores de una cocina de gas, inyectando oxígeno caliente al humo. Hágalos del grosor del pulgar para lograr chorros potentes.\",\n      \"svgFileName\": \"pr12-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // INNER BURN CHAMBER PERFORATION\",\n        \"FONDO INTERIOR: 12-15 AGUJEROS PRIMARIOS (8MM)\",\n        \"BORDE SUPERIOR: 8-10 TOBERAS DE GAS (10-12MM)\",\n        \"PERFORAR CON PUNZÓN Y APLANAR REBABAS\",\n        \"[CLAVE] DRENAJE DE CENIZA Y TOBERAS DE OXÍGENO\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"Diseño de Rejilla de Pirólisis Primaria y Toberas de Combustión Secundaria\",\n        \"text\": \"Los orificios pequeños del fondo aportan el aire primario justo para gasificar la madera y dejan caer la ceniza. Las toberas superiores de 10–12mm inyectan aire secundario sobrecalentado directamente sobre el monóxido de carbono y metano ascendentes, transformando el humo en fuego limpio.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Paso 3: Abrir la Tapa Exterior, Encajar la Cámara Interna y Atar con Alambre Pelado\",\n      \"description\": \"1. **Perforar Tomas Inferiores en la Lata Grande**: Alrededor de la base de la lata exterior, **1.5cm por encima del suelo**, perfore **8–10 agujeros del grosor del pulgar (12mm)** para la entrada de aire frío.\\n2. **Recortar la Boca Superior Exterior**: Cincele una abertura circular en la tapa superior de la lata grande para que la lata pequeña entre ajustada hasta su reborde.\\n3. **Fijar Ambas Latas con Alambre**: Pase el **alambre desnudo de cobre o acero** por los agujeros enfrentados del borde superior y retuérzalo con un palo para que la lata interna quede suspendida **2cm por encima del fondo exterior**.\\n4. **Armar el Soporte Cruzado (Trébede)**: Doble el resto del alambre grueso sobre la boca formando una **parrilla cruzada de 2–3cm de altura** para apoyar la olla sin ahogar el fuego.\",\n      \"actionNote\": \"> Espacio de Escape Vital: ¡Nunca apoye una olla directamente pegada al borde de la lata! Sin esos 2–3cm de separación del soporte de alambre, la llama se ahoga al instante y sale humo negro.\",\n      \"svgFileName\": \"pr12-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DOUBLE-WALL NESTING & WIRE BINDING\",\n        \"LATA EXTERIOR: TOMAS INFERIORES (12MM X 8-10)\",\n        \"LATA INTERNA SUSPENDIDA CON CANAL DE 1.5-2CM\",\n        \"AMARRE DE ALAMBRE PELADO Y PARRILLA DE 2-3CM\",\n        \"[CLAVE] CONDUCTO DE PRECALENTAMIENTO COMPLETADO\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"STRUCTURAL MECHANICS\",\n        \"title\": \"Por Qué el Alambre Metálico Recuperado Supera a las Cuerdas Vegetales a 850°C\",\n        \"text\": \"Las fibras vegetales se carbonizan y rompen por encima de 300°C. El núcleo desnudo de cobre (fusión a **1,085°C**) o acero (**1,500°C**) extraído de cables urbanos sostiene firmemente la doble pared y el peso del agua hirviendo en plena zona de llamas.\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Paso 4: Cargar Ramitas en Vertical, Encender desde Arriba y Hervir Agua Sin Humo\",\n      \"description\": \"1. **Carga Vertical de Ramitas**: Parta ramitas secas del grosor de un dedo al largo del pulgar y colóquelas **de pie en vertical** dentro de la lata interna hasta **justo debajo de las toberas superiores**.\\n2. **Encendido Invertido (Arriba hacia Abajo)**: Coloque corteza seca y [yesca de resina de pino](/protocol-10.html) **encima de las ramitas verticales** y préndalas desde arriba con una brasa de [arco de fricción](/protocol-02.html).\\n3. **Verificar los Chorros de Gas de Leña**: En 2–3 minutos, al calentarse la doble pared, verá salir **chorros de llama amarillo-azulada** por las toberas superiores mientras el humo desaparece por completo.\\n4. **Hervir Agua y Recoger Biocarbón**: Coloque su recipiente con [agua filtrada](/protocol-01.html) sobre el soporte de alambre para hervir en 7–8 minutos; al terminar, cubra las brasas rojas con tierra para obtener [carbón vegetal limpio](/protocol-09.html).\",\n      \"actionNote\": \"> ¿Por qué encender desde arriba?: Si enciende por debajo, toda la madera humea a la vez. Al encender por arriba como una vela, el humo que sube desde abajo tiene que atravesar el anillo de fuego superior y se quema sin dejar rastro.\",\n      \"svgFileName\": \"pr12-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // TOP-DOWN PYROLYSIS & SECONDARY JETS\",\n        \"RAMITAS SECAS EN VERTICAL BAJO LAS TOBERAS\",\n        \"ENCENDIDO SUPERIOR CON RESINA Y CORTEZA\",\n        \"CHORROS DE AIRE QUEMAN EL GAS DE LEÑA SIN HUMO\",\n        \"[CLAVE] HIERVE 1L EN 8 MIN CON DOS PUÑADOS\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"COMBUSTION SCIENCE\",\n        \"title\": \"Gasificación de Tiro Ascendente Encendida por Arriba (TLUD) y Biocarbón\",\n        \"text\": \"En un gasificador TLUD, el frente de pirólisis desciende lentamente por las ramitas verticales. Los gases volátiles liberados abajo atraviesan el anillo superior de chorros de oxígeno a 850°C, quemando más del 95% del humo y dejando carbón puro en la base.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Error Fatal: Cocinar en latas sin quemar previamente el revestimiento epoxi o usar latas delgadas de bebida\",\n    \"description\": \"Las latas de conserva tienen un recubrimiento interior epoxi antioxidante que desprende gases tóxicos si no se quema en vacío antes de usar. Además, las latas delgadas de refresco se funden a 660°C y colapsan derramando el agua hirviendo.\",\n    \"consequence\": \"Consecuencia: Intoxicación por vapores químicos y quemaduras graves por colapso del hornillo\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"¡Con solo 2 latas vacías y un puñado de ramitas puedes fabricar un hornillo sin humo que hierve agua en 8 minutos!\",\n    \"body\": \"Primero elige dos latas de acero de distinto tamaño y quema hojas secas dentro durante 5 minutos para eliminar el barniz tóxico. Perfora agujeros en el fondo de la lata pequeña y 8 toberas del grosor del pulgar bajo el borde superior. Abre entradas de aire en la base de la lata grande, encaja la pequeña dentro y átalas con alambre de cable pelado. ¡Llena con ramitas en vertical y enciende desde arriba para que el aire caliente queme el propio humo como un soplete!\",\n    \"outro\": \"Sin humo nadie descubre tu posición y el agua hierve en 8 minutos. Mira los planos en el enlace del perfil.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr12-outcome.svg\",\n    \"title\": \"Estufa de Gas de Leña de Doble Lata Completada (Quemador Sin Humo de 850°C)\",\n    \"description\": \"Construida con dos latas de acero recuperadas y alambre pelado, con canal de precalentamiento de 1.5–2cm, tomas inferiores de aire frío, toberas superiores de oxígeno secundario y soporte cruzado de alambre para combustión limpia a 850°C.\"\n  },\n  \"createdAt\": \"2026-10-17T10:12:00.000Z\",\n  \"contentHash\": \"00b85f08738b5163\"\n}","content/protocols/locales/12-twin-can-wood-gas-stove.ja.json":"{\n  \"protocolId\": \"PR-12\",\n  \"category\": \"FIRE\",\n  \"title\": \"空き缶2個と廃電線・小枝で煙を出さずに水を沸かす二重燃焼ウッドガスストーブ\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[無煙高熱調理・殺菌 ＆ 燃料80%節約]\",\n  \"summary\": \"文明が停止した都市や荒野では太い薪が手に入りにくく、普通の焚き火をすると黒い煙が上がって居場所が露見するうえ、風で熱が逃げてしまいます。廃墟で拾えるサイズの違うスチール空き缶2個を重ねて二重壁のかまどを作り、廃電線の銅・鉄芯線で固定すれば、枝から出る煙（木ガス）まで再び燃やし尽くす無煙ガスコンロになります。指の太さの乾いた小枝二つかみだけで、煙を出さずに8分で水1リットルを沸騰させられます。\",\n  \"timeRequired\": \"35分（空き缶の空焼き10分 ＋ 通気穴あけ15分 ＋ 二重結合と着火10分）\",\n  \"successRate\": \"95%（スチール缶の使用および上部着火原則の遵守時）\",\n  \"difficulty\": \"普通（缶の鋭い切り口による怪我および塗装の有毒煙に注意）\",\n  \"outputPerHour\": \"小枝二つかみ（200g）で20分間無煙高熱火炎を維持（飲料水1.5L殺菌）\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"外側用の大型スチール缶1個（直径12〜15cm）＆ 内側用の小型スチール缶1個（直径8〜10cm）\",\n      \"desc\": \"重ねた時に壁の間に指の第一関節（1.5〜2cm）の隙間ができる、横溝入りの頑丈な鉄製空き缶2個です。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"被覆を剥いた廃電線の金属芯線 50cm\",\n      \"desc\": \"廃電線の外側被覆を[鋭い石刃や石斧](/protocol-04.html)で裂いて剥ぎ取り、熱で溶けない銅線または鉄芯線（太さ1.5〜3mm）を取り出して固定と五徳に使います。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"尖った古釘（または石錐）とハンマー石\",\n      \"desc\": \"スチール缶の底と側面に一次・二次空気穴を貫通させるための尖った鉄片（または石の錐）と拳大の川石です。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"親指の長さに折った乾いた小枝二つかみと松脂の火口\",\n      \"desc\": \"内缶に縦向きに詰める乾いた広葉樹の小枝と、上から着火するための[松脂の塊](/protocol-10.html)および乾燥樹皮です。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"ステップ1：耐熱スチール缶2個と廃電線を選び、内部コーティングを空焼きして除去する\",\n      \"description\": \"1. **頑丈なスチール缶の選別**: 手で強く握っても潰れない横溝（補強リブ）入りのスチール缶を大小2個選びます。大缶の中に小缶を入れた際、周囲に**指の第一関節（約1.5〜2cm）**の空気通路が残るサイズを揃えます。\\n2. **廃電線の被覆剥離**: 拾った電線のゴム被覆を[鋭い石刃](/protocol-04.html)で縦に裂き、火に強い**裸の銅線または鉄芯線50cm**を取り出します。\\n3. **5分間の空焼き（コーティング除去）**: 穴を開ける前に両方の空き缶に枯れ葉と小枝を入れて**屋外で5分間燃やし**、内側のエポキシ樹脂膜と外側の塗料を完全に焼き切ります。\\n4. **ツヤ消し黒灰色の確認**: 焦げ臭い煙が消え、缶の内側が**ツヤ消しの黒灰色**に変わったら火を消し、日陰で完全に冷まします。\",\n      \"actionNote\": \"> 有毒ガス・薄缶への注意: 空焼きを省くと有害な煙を吸い込みます。また薄い飲料缶は高温で紙のように溶け落ちるため、下の実写図鑑で**横溝入りスチール缶**と**裸の金属芯線**を正確に見分けてください。\",\n      \"svgFileName\": \"pr12-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // STEEL CAN SELECTION & LINER BURN-OFF\",\n        \"外側大型スチール缶（12〜15cm）＆内側小型缶\",\n        \"内外壁の間に指一関節（1.5〜2cm）の空気層\",\n        \"使用前5分間の空焼きで内部エポキシ膜を除去\",\n        \"[核心] 耐熱スチール缶の選別＆裸電線芯線の確保\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"URBAN SALVAGE\",\n        \"title\": \"スズメッキ鋼板（融点1,500℃）の選別とエポキシ被膜熱分解の安全性\",\n        \"text\": \"缶詰や粉ミルク缶に使われるスズメッキ鋼板（スチール）は融点が約**1,500℃**あり、ウッドガスストーブの高温（800〜900℃）に繰り返し耐えます。一方、薄い飲料缶は**660℃**で溶け落ちます。使用前の空焼きによって内面のビスフェノール系エポキシ樹脂を炭化させることで、安全に湯沸かしや調理が可能になります。\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"高耐熱リブ付きスチール空き缶\",\n            \"scientificName\": \"Tin-Coated Corrugated Carbon Steel\",\n            \"categoryTag\": \"都市金属廃材 / 二重燃焼室本体\",\n            \"imageFileName\": \"id-steel-tin-can.jpg\",\n            \"hudCode\": \"FIG. SALV-12A // MACRO OPTIC\",\n            \"hudStatus\": \"MELT POINT 1500C: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"外観/RIB\",\n                \"value\": \"円筒の側面に**横向きの凹凸溝（補強ビード）**が刻まれており、手で握っても歪みません。\"\n              },\n              {\n                \"label\": \"縁/RIM\",\n                \"value\": \"上下の縁が厚く巻き締められており、石で叩くと**重く澄んだ金属音**が響きます。\"\n              },\n              {\n                \"label\": \"前処理/PREP\",\n                \"value\": \"枯れ葉の火で5分間空焼きすると内側の光沢膜が消え、**安全なツヤ消し暗灰色の鋼鉄面**が現れます。\"\n              }\n            ],\n            \"fieldUse\": \"二重燃焼ウッドガスストーブ本体、緊急煮沸ポット、炭保存缶\"\n          },\n          {\n            \"name\": \"被覆を剥いた廃電線＆乾燥小枝\",\n            \"scientificName\": \"Stripped Copper/Steel Core & Dry Hardwood\",\n            \"categoryTag\": \"都市・自然ハイブリッド / 耐熱結束材・燃料\",\n            \"imageFileName\": \"id-salvage-wire-twigs.jpg\",\n            \"hudCode\": \"FIG. SALV-12B // MACRO OPTIC\",\n            \"hudStatus\": \"INSULATION STRIPPED: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"芯線/CORE\",\n                \"value\": \"石刃で外側の被覆を完全に剥ぎ取った**赤銅色の銅単線または銀灰色の鉄芯線**（太さ**1.5〜3mm**）です。\"\n              },\n              {\n                \"label\": \"燃料/FUEL\",\n                \"value\": \"曲げるとパキッと乾いた音を立てて折れる**指の太さ・親指の長さの乾燥広葉樹枝**です。\"\n              },\n              {\n                \"label\": \"着火/TINDER\",\n                \"value\": \"小枝の最上部から素早く火を下ろすための**琥珀色の松脂と乾いた樹皮**を併用します。\"\n              }\n            ],\n            \"fieldUse\": \"二重壁の耐熱結束、十字五徳（ゴトク）、無煙高火力バイオマス燃料\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"ステップ2：小さい内缶の底面と上部側面に一次・二次空気穴を開ける\",\n      \"description\": \"1. **内缶の変形防止固定**: 穴を開ける際に缶が凹まないよう、小さい缶の内側に硬い木片や土を詰めて支えます。\\n2. **底面の一次吸気穴あけ**: 小缶の底面に尖った古釘や石錐を当て、ハンマー石で叩いて**小指の太さ（直径8mm）の穴を12〜15個**均等に開けます。\\n3. **上部側面の二次ガスノズル穴あけ**: 小缶の上縁から**指の第一関節（約1.5cm）下**の側面に沿って、**親指の太さ（直径10〜12mm）の穴を8〜10個**ぐるりと一周開けます。\\n4. **鋭いバリの平坦化**: 穴の内側にめくれた鋭い鉄のバリを石の角で叩いて平らに潰し、怪我を防ぎます。\",\n      \"actionNote\": \"> 上部穴の役割: 小缶の上部側面に開けた8〜10個の大きな穴が、煙を炎に変える「ガスコンロの噴射口（二次燃焼ノズル）」になります。親指の太さで大きく開けるほど火力が強まります。\",\n      \"svgFileName\": \"pr12-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // INNER BURN CHAMBER PERFORATION\",\n        \"内缶底面の一次吸気穴（8mm × 12〜15個）\",\n        \"上縁1.5cm下の二次ガスノズル（10〜12mm × 8〜10個）\",\n        \"古釘とハンマー石で穿孔し鋭いバリを平坦化\",\n        \"[核心] 下部の灰排出＆上部の高温酸素噴射口を完成\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"一次熱分解ロストルと二次ガス燃焼ノズルの開口設計\",\n        \"text\": \"内缶底面の小さな穴は小枝の熱分解に必要な最小限の一次空気を送り込み、灰を下に落とします。一方、上部周囲の大きな穴は二重壁を昇ってきた高温空気を燃焼室上部へ強く噴射し、立ち昇る可燃性木ガス（一酸化炭素・メタン）と混合して完全燃焼を引き起こします。\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"ステップ3：外缶の上面をくり抜いて内缶を重ね、廃電線で固定して五徳を作る\",\n      \"description\": \"1. **外缶下部の吸気穴あけ**: 大きい外缶の底から**1.5cm上の側面周囲**に、**親指の太さ（直径12mm）の冷気取り入れ穴を8〜10個**開けます。\\n2. **外缶上蓋の中央くり抜き**: 大缶の上面に石刃や釘で丸い穴をくり抜き、小さい内缶が上縁までぴったり差し込めるようにします。\\n3. **廃電線による二重壁の固定**: 内缶を差し込み（外缶の底から**約2cm浮いた状態**）、両缶の上縁の穴に**裸の銅線・鉄芯線**を十字に通して木の棒で強くねじり固定します。\\n4. **十字五徳（ゴトク）の形成**: 残った太い廃電線を折り曲げ、上縁の上に**高さ2〜3cmの十字の鍋受け（五徳）**を作って炎の抜け道を確保します。\",\n      \"actionNote\": \"> 排気隙間の確保: 五徳なしで鍋を缶の縁にベタ置きすると、炎と煙の逃げ道が塞がれて一瞬で消火してしまいます。必ず廃電線で2〜3cmの隙間を作ってください。\",\n      \"svgFileName\": \"pr12-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DOUBLE-WALL NESTING & WIRE BINDING\",\n        \"外缶下部の冷気吸気穴（12mm × 8〜10個）\",\n        \"外缶上部に内缶を挿入（壁間1.5〜2cmの空気通路）\",\n        \"裸電線で上下の縁を結束＆2〜3cmの十字五徳\",\n        \"[核心] 下部吸気→壁面予熱→上部噴射の二重壁完成\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"STRUCTURAL MECHANICS\",\n        \"title\": \"850℃の火口で植物ロープではなく金属芯線を使う理由\",\n        \"text\": \"天然の植物ロープは300℃を超えると炭化して切れてしまいます。都市廃材の電線から取り出した銅線（融点**1,085℃**）や鉄線（融点**1,500℃**）なら、850℃の二次燃焼炎の中でも緩まずに二重構造と満水のクッカーを支え続けます。\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"ステップ4：乾いた小枝を縦に詰め、上から着火して無煙ジェット炎で水を沸かす\",\n      \"description\": \"1. **小枝の垂直充填**: 指の太さの乾いた小枝を親指の長さに揃え、内缶の**上部ノズル穴のすぐ下まで縦向きにぎっしり**立てて詰めます。\\n2. **トップダウン（上部）着火**: 縦に詰めた小枝の**一番上**に乾燥樹皮と[松脂の火口](/protocol-10.html)を載せ、[弓ぎり式火起こし](/protocol-02.html)で得た火種で上から火をつけます。\\n3. **二次燃焼ジェット炎の確認**: 着火後2〜3分で二重壁が温まると、上部ノズル穴から**黄金色〜青白い二次火炎**が内側へ噴き出し、煙がピタリと消えます。\\n4. **湯沸かしと炭の回収**: 電線の五徳の上に[ろ過した水](/protocol-01.html)を入れた缶を載せて7〜8分で沸騰させ、調理後に底に残った赤い熾火に土を被せて[良質な木炭（バイオ炭）](/protocol-09.html)として回収します。\",\n      \"actionNote\": \"> なぜ上から火をつけるのか？: 下から火をつけると小枝全体が一気に燻って大量の煙が出ます。ロウソクのように一番上から燃え下がらせることで、下から昇る煙がすべて上部の高温炎を通過し、煙ゼロで燃え尽きます。\",\n      \"svgFileName\": \"pr12-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // TOP-DOWN PYROLYSIS & SECONDARY JETS\",\n        \"上部ノズル穴の下まで乾いた小枝を垂直充填\",\n        \"松脂と樹皮を最上部に載せてトップダウン着火\",\n        \"予熱酸素がノズルから噴出し木ガスを無煙二次燃焼\",\n        \"[核心] 小枝二つかみで煙を出さず8分以内に1L沸騰\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"COMBUSTION SCIENCE\",\n        \"title\": \"トップダウン上昇気流ガス化（TLUD）とバイオ炭の同時生成\",\n        \"text\": \"上部着火方式（TLUD）では熱分解層が上から下へとゆっくり移動します。下層の小枝から発生した可燃性ガスは必ず上部の850℃二次空気リングを通過するため、煤や煙の95%以上がクリーンな熱エネルギーに変換され、底には純粋な木炭が残ります。\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命的なミス：内部コーティングを空焼きしていない空き缶や薄い飲料缶をそのまま調理に使う行為\",\n    \"description\": \"缶詰の内側には防錆用のエポキシ樹脂膜が塗られており、事前に空焼きせずに調理すると有毒な煙や環境ホルモンが水に溶け込みます。また薄い飲料缶は高温で一瞬で溶け落ち、熱湯がこぼれて大やけどを負います。\",\n    \"consequence\": \"結果：有毒ガス吸引による中毒およびコンロ崩壊による熱湯やけどの危険\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"捨てられた空き缶2個さえあれば、小枝ひとつかみで煙を一切出さずに水を沸かす最強コンロが作れます！\",\n    \"body\": \"まずサイズの違うスチール缶2個を選び、枯れ葉の火で内側の有毒コーティングを焼き切ります。小さい缶の底に穴をたくさん開け、上部側面に親指太さの穴を8個開けます。大きい缶の下部にも吸気穴を開け、上から小さい缶を差し込んで廃電線で固定し二重壁を作ります！乾いた小枝を縦に詰めて一番上から火をつければ、二重壁を昇った熱い空気が煙まで燃やし尽くし、ガスコンロのような炎が噴き出します！\",\n    \"outro\": \"煙が出ないので居場所がバレず、8分で水が沸騰します。詳しい図面はプロフィールリンクから確認してください。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr12-outcome.svg\",\n    \"title\": \"完成した空き缶二重燃焼ウッドガスストーブ（850℃無煙ジェットコンロ）断面諸元\",\n    \"description\": \"外側大型スチール缶と内側小型燃焼缶の間の1.5〜2cm二重空気通路、下部冷気吸気口と上部二次予熱酸素噴射ノズル、廃電線五徳、そして木ガスが無煙高熱火炎として完全燃焼する熱力学断面構造です。\"\n  },\n  \"createdAt\": \"2026-10-17T10:12:00.000Z\",\n  \"contentHash\": \"00b85f08738b5163\"\n}","content/protocols/locales/12-twin-can-wood-gas-stove.pt.json":"{\n  \"protocolId\": \"PR-12\",\n  \"category\": \"FIRE\",\n  \"title\": \"Fogareiro a Gás de Lenha de Dupla Combustão com 2 Latas Vazias, Fio Desencapado e Gravetos\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[COZIMENTO SEM FUMAÇA DE ALTA TEMPERATURA E 80% ECONOMIA DE LENHA]\",\n  \"summary\": \"Em uma cidade colapsada ou terreno ermo é difícil achar lenha grossa, e uma fogueira comum levanta fumaça preta que entrega sua posição enquanto o vento espalha o calor. Ao encaixar duas latas de aço vazias de tamanhos diferentes para formar uma parede dupla e prendê-las com o arame de cobre ou ferro de um fio elétrico desencapado, você cria um fogareiro sem fumaça que queima o próprio gás da madeira. Com apenas dois punhados de gravetos secos você ferve 1 litro de água em 8 minutos sem emitir fumaça.\",\n  \"timeRequired\": \"35 min (10m queima de revestimento + 15m furação + 10m montagem e acendimento)\",\n  \"successRate\": \"95% (usando latas de aço frisado e acendimento pelo topo)\",\n  \"difficulty\": \"Média (cuidado com rebarbas cortantes de metal e fumaça tóxica na queima prévia)\",\n  \"outputPerHour\": \"20 min de chama limpa a 850°C com 2 punhados (200g) de gravetos (esteriliza 1,5L de água)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"1 Lata Grande de Aço Externa (12–15cm) e 1 Lata Pequena de Aço Interna (8–10cm)\",\n      \"desc\": \"Duas latas rígidas de aço com frisos horizontais que, encaixadas uma dentro da outra, deixem um espaço de um dedo (1,5–2cm) entre as paredes.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"50cm de Fio Elétrico Descartado (Sem Capa Isolante)\",\n      \"desc\": \"Use uma [lasca de pedra afiada ou machado de pedra](/protocol-04.html) para rasgar a capa isolante externa e extrair o arame nu de cobre ou aço (1,5–3mm) para amarrar as latas e fazer a trempe da panela.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Prego de Sucata Pontiagudo (ou Furador de Pedra) e Pedra Martelo\",\n      \"desc\": \"Pino metálico pontiagudo ou furador de pedra batido com um seixo do tamanho do punho para perfurar os bicos de ar.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Dois Punhados de Gravetos Secos do Tamanho do Polegar e Isca de Resina\",\n      \"desc\": \"Gravetos secos de madeira dura quebrados no comprimento do polegar para carga vertical, mais [pedacinhos de resina de pinheiro](/protocol-10.html) e casca seca para acendimento pelo topo.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Passo 1: Selecionar Latas de Aço, Desencapar o Fio e Queimar o Revestimento Epóxi Interno\",\n      \"description\": \"1. **Selecionar Latas de Aço Frisado**: Escolha duas latas rígidas de conserva com anéis horizontais de reforço que não amassem ao apertar. Ao colocar a menor dentro da maior, deve restar uma folga da **largura de um dedo (1,5–2cm)** ao redor.\\n2. **Desencapar o Fio Elétrico**: Corte a capa isolante do cabo com uma [lasca de pedra afiada](/protocol-04.html) e retire **50cm de fio metálico nu** de cobre ou aço.\\n3. **Queima Prévia de 5 Minutos**: Antes de furar, coloque folhas e gravetos secos dentro das duas latas vazias e **queime ao ar livre por 5 minutos** para carbonizar o verniz epóxi interno e a tinta.\\n4. **Confirmar o Aço Cinza Fosco**: Quando o cheiro químico sumir e o interior ficar **cinza-escuro fosco**, deixe esfriar totalmente na sombra.\",\n      \"actionNote\": \"> Verificação de Toxicidade e Metal: Pular a queima prévia contamina a água com vapores tóxicos. Latas finas de bebida derretem rápido; veja as fotos reais abaixo para identificar latas de aço frisado e arame desencapado.\",\n      \"svgFileName\": \"pr12-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // STEEL CAN SELECTION & LINER BURN-OFF\",\n        \"LATA EXTERNA (12-15CM) E LATA INTERNA\",\n        \"FOLGA DE AR DE 1.5-2CM ENTRE AS PAREDES\",\n        \"QUEIMA DE 5 MIN REMOVE O VERNIZ EPÓXI\",\n        \"[CHAVE] ESCOLHER LATA DE AÇO E ARAME NU\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"URBAN SALVAGE\",\n        \"title\": \"Aço Folha-de-Flandres (Fusão a 1.500°C) e Remoção Térmica de Resina BPA\",\n        \"text\": \"As latas de conserva de aço carbono têm ponto de fusão próximo a **1.500°C**, suportando repetidamente os 800–900°C do gás de madeira. Latas de bebida derretem a **660°C**. A queima prévia ao ar livre elimina a película interna de bisfenol (BPA) para um cozimento seguro.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"Lata de Aço Frisado de Alta Resistência\",\n            \"scientificName\": \"Tin-Coated Corrugated Carbon Steel\",\n            \"categoryTag\": \"Sucata Metálica Urbana / Corpo do Fogareiro\",\n            \"imageFileName\": \"id-steel-tin-can.jpg\",\n            \"hudCode\": \"FIG. SALV-12A // MACRO OPTIC\",\n            \"hudStatus\": \"MELT POINT 1500C: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"FRISOS\",\n                \"value\": \"Anéis horizontais **em relevo (nervuras)** na parede cilíndrica que impedem que a lata dobre no calor.\"\n              },\n              {\n                \"label\": \"BORDA\",\n                \"value\": \"Bordas superior e inferior com costura dupla grossa que produzem um **som metálico firme** ao bater.\"\n              },\n              {\n                \"label\": \"QUEIMA\",\n                \"value\": \"Após 5 minutos de fogo com folhas, o brilho interno some e resta uma **parede segura de aço cinza fosco**.\"\n              }\n            ],\n            \"fieldUse\": \"Corpo duplo de fogareiro a gás de lenha, caneca de fervura, pote de carvão\"\n          },\n          {\n            \"name\": \"Arame Desencapado e Gravetos Secos\",\n            \"scientificName\": \"Stripped Copper/Steel Core & Dry Hardwood\",\n            \"categoryTag\": \"Híbrido Urbano-Natural / Amarração e Combustível\",\n            \"imageFileName\": \"id-salvage-wire-twigs.jpg\",\n            \"hudCode\": \"FIG. SALV-12B // MACRO OPTIC\",\n            \"hudStatus\": \"INSULATION STRIPPED: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"NÚCLEO\",\n                \"value\": \"Fio sólido **de cobre avermelhado ou aço cinza** (**1,5–3mm** de espessura) totalmente sem capa isolante.\"\n              },\n              {\n                \"label\": \"LENHA\",\n                \"value\": \"Gravetos secos de madeira dura da **grossura de um dedo e comprimento do polegar** que quebram com estalo seco.\"\n              },\n              {\n                \"label\": \"ISCA\",\n                \"value\": \"Pedaços dourados de **resina de pinheiro e casca seca** colocados no topo para acender de cima para baixo.\"\n              }\n            ],\n            \"fieldUse\": \"Amarração resistente ao fogo, suporte cruzado de panela, biomassa sem fumaça\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Passo 2: Perfurar os Furos Primários e os Bicos Secundários de Gás na Lata Interna\",\n      \"description\": \"1. **Apoiar a Lata Pequena**: Preencha o interior da lata pequena com um toco de madeira ou terra firme para não amassar a parede ao bater.\\n2. **Perfurar o Fundo Primário**: Com o prego pontiagudo ou furador e a pedra martelo, abra **12–15 furos da grossura do mindinho (8mm)** espalhados pelo fundo da lata pequena.\\n3. **Perfurar os Bicos Superiores de Gás**: A **uma falange (1,5cm) abaixo da borda superior** da lata pequena, fure **8–10 buracos da grossura do polegar (10–12mm)** em toda a volta.\\n4. **Rebater as Rebarbas Cortantes**: Bata com a quina da pedra nas pontas de metal internas para achatá-las e evitar cortes nas mãos.\",\n      \"actionNote\": \"> Função dos Bicos Superiores: Os 8–10 furos grandes perto da borda superior funcionam como bocas de fogão a gás, injetando oxigênio quente na fumaça. Faça-os na grossura do polegar para jatos fortes.\",\n      \"svgFileName\": \"pr12-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // INNER BURN CHAMBER PERFORATION\",\n        \"FUNDO INTERNO: 12-15 FUROS PRIMÁRIOS (8MM)\",\n        \"TOPO: 8-10 BICOS DE GÁS SECUNDÁRIOS (10-12MM)\",\n        \"FURAR COM PINO E ACHATAR REBARBAS INTERNAS\",\n        \"[CHAVE] DRENO DE CINZAS E BICOS DE OXIGÊNIO\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"Proporção entre a Grelha de Pirólise Primária e os Bicos de Combustão Secundária\",\n        \"text\": \"Os furos menores do fundo fornecem o ar primário exato para gassificar os gravetos e deixam a cinza cair. Os bicos superiores de 10–12mm injetam ar secundário superaquecido diretamente no monóxido de carbono e metano ascendentes, convertendo fumaça em fogo limpo.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Passo 3: Abrir a Tampa Externa, Encaixar a Câmara Interna e Amarrar com Fio Desencapado\",\n      \"description\": \"1. **Furar Entradas Inferiores na Lata Grande**: Ao redor da base da lata externa, **1,5cm acima do fundo**, faça **8–10 furos da grossura do polegar (12mm)** para entrada de ar frio.\\n2. **Recortar a Boca Superior Externa**: Corte uma abertura circular na tampa superior da lata grande para que a lata pequena entre justa até a borda.\\n3. **Travar Ambas as Latas com Arame**: Passe o **fio nu de cobre ou aço** pelos furos opostos da borda superior e torça firme com um graveto para que a lata interna fique suspensa **2cm acima do fundo externo**.\\n4. **Moldar o Suporte Cruzado (Trempe)**: Dobre o restante do arame grosso sobre a boca formando uma **grelha cruzada de 2–3cm de altura** para apoiar a panela sem abafar a chama.\",\n      \"actionNote\": \"> Folga de Exaustão Vital: Nunca apoie uma panela direto colada na borda da lata! Sem os 2–3cm de espaço do suporte de arame, a chama apaga na hora e solta fumaça preta.\",\n      \"svgFileName\": \"pr12-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DOUBLE-WALL NESTING & WIRE BINDING\",\n        \"LATA EXTERNA: ENTRADAS DE AR FRIO (12MM X 8-10)\",\n        \"LATA INTERNA SUSPENSA COM CANAL DE 1.5-2CM\",\n        \"TRAVA DE ARAME NU E SUPORTE CRUZADO DE 2-3CM\",\n        \"[CHAVE] DUTO DE PRÉ-AQUECIMENTO CONCLUÍDO\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"STRUCTURAL MECHANICS\",\n        \"title\": \"Por Que o Fio Metálico Desencapado Supera Cordas Naturais a 850°C\",\n        \"text\": \"Fibras vegetais carbonizam e arrebentam acima de 300°C. O núcleo nu de cobre (fusão a **1.085°C**) ou aço (**1.500°C**) retirado de cabos urbanos sustenta com segurança a parede dupla e o peso da água fervendo bem no centro das chamas.\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Passo 4: Empilhar Gravetos na Vertical, Acender pelo Topo e Ferver Água Sem Fumaça\",\n      \"description\": \"1. **Carga Vertical de Gravetos**: Quebre gravetos secos na grossura de um dedo e comprimento do polegar e arrume-os **em pé na vertical** dentro da lata interna até **logo abaixo dos bicos superiores**.\\n2. **Acendimento Invertido (Topo para Baixo)**: Coloque casca seca e [isca de resina de pinheiro](/protocol-10.html) **no topo dos gravetos verticais** e acenda por cima usando uma brasa do [arco de pua](/protocol-02.html).\\n3. **Confirmar os Jatos de Gás de Lenha**: Em 2–3 minutos, quando a parede dupla aquecer, **jatos de chama amarelo-azulada** sairão pelos bicos superiores e a fumaça desaparecerá por completo.\\n4. **Ferver Água e Colher Biocarvão**: Coloque sua vasilha com [água filtrada](/protocol-01.html) sobre o suporte de arame para ferver em 7–8 minutos; depois, abafe as brasas vermelhas com terra para guardar [carvão vegetal puro](/protocol-09.html).\",\n      \"actionNote\": \"> Por que acender por cima?: Se acender por baixo, toda a lenha fumega de uma vez. Acendendo pelo topo como uma vela, a fumaça que sobe de baixo é forçada a atravessar o anel de fogo superior e queima sem deixar rastro.\",\n      \"svgFileName\": \"pr12-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // TOP-DOWN PYROLYSIS & SECONDARY JETS\",\n        \"GRAVETOS SECOS EM PÉ ABAIXO DOS BICOS\",\n        \"IGNIÇÃO PELO TOPO COM RESINA E CASCA SECA\",\n        \"JATOS DE AR QUEIMAM O GÁS DE LENHA SEM FUMAÇA\",\n        \"[CHAVE] FERVE 1L EM 8 MIN COM DOIS PUNHADOS\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"COMBUSTION SCIENCE\",\n        \"title\": \"Gassificação de Fluxo Ascendente Acesa pelo Topo (TLUD) e Biocarvão\",\n        \"text\": \"Num gassificador TLUD, a frente de pirólise desce lentamente pelos gravetos verticais. Os gases voláteis liberados embaixo atravessam o anel superior de oxigênio a 850°C, queimando mais de 95% da fumaça e deixando carvão puro no fundo.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Erro Fatal: Cozinhar em latas sem queimar antes o revestimento epóxi ou usar latas finas de bebida\",\n    \"description\": \"Latas de conserva têm verniz epóxi interno que solta gases tóxicos se não for queimado vazio antes do uso. Além disso, latas finas de refrigerante derretem a 660°C e cedem sob a panela fervendo.\",\n    \"consequence\": \"Consequência: Inalação de vapores químicos e queimaduras graves por colapso do fogareiro\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Com apenas 2 latas vazias e um punhado de gravetos você faz um fogareiro sem fumaça que ferve água em 8 minutos!\",\n    \"body\": \"Escolha duas latas de aço de tamanhos diferentes e queime folhas secas dentro por 5 minutos para eliminar o verniz tóxico. Fure o fundo da lata pequena e abra 8 bicos da grossura do polegar perto da borda superior. Faça entradas de ar na base da lata grande, encaixe a pequena dentro e amarre com arame de fio desencapado. Encha com gravetos em pé e acenda por cima para o ar quente queimar a própria fumaça como um fogão a gás!\",\n    \"outro\": \"Sem fumaça ninguém descobre sua posição e a água ferve em 8 minutos. Veja o projeto completo no link do perfil.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr12-outcome.svg\",\n    \"title\": \"Fogareiro a Gás de Lenha de Dupla Lata Concluído (Queimador Sem Fumaça de 850°C)\",\n    \"description\": \"Construído com duas latas de aço descartadas e arame desencapado, com canal de pré-aquecimento de 1,5–2cm, entradas inferiores de ar frio, bicos superiores de oxigênio secundário e suporte cruzado de arame para combustão limpa a 850°C.\"\n  },\n  \"createdAt\": \"2026-10-17T10:12:00.000Z\",\n  \"contentHash\": \"00b85f08738b5163\"\n}","content/protocols/locales/12-twin-can-wood-gas-stove.zh-TW.json":"{\n  \"protocolId\": \"PR-12\",\n  \"category\": \"FIRE\",\n  \"title\": \"用2個廢棄空鐵罐與廢電線、枯枝打造無煙煮水的雙重燃燒木煤氣爐\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[無煙高熱炊事殺菌 ＆ 節省80%木柴燃料]\",\n  \"summary\": \"在文明停擺的城市或荒野中很難找到粗木柴，若直接生營火不僅黑煙沖天會暴露位置，熱量也會被風吹散。只要撿兩個大小不同的廢棄鋼鐵空罐套在一起形成雙層爐壁，再用廢電線剝出的裸銅線或鐵芯線綁緊固定，就能做出把樹枝濃煙（木煤氣）二次點燃的無煙瓦斯爐。僅需兩把手指粗的乾枯枝，就能在毫無黑煙的情況下於8分鐘內將1公升水徹底煮沸。\",\n  \"timeRequired\": \"35分鐘（空罐塗層預燒10分鐘 ＋ 鑿穿氣孔15分鐘 ＋ 雙罐結合與點火10分鐘）\",\n  \"successRate\": \"95%（使用橫紋鋼鐵罐並遵守由上往下點火原則時）\",\n  \"difficulty\": \"中等（注意鐵罐鋒利切口割傷與預燒時的塗層毒煙）\",\n  \"outputPerHour\": \"兩把細枝（200g）可維持20分鐘無煙850℃高溫火燄（消毒1.5公升飲水）\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"外層大號鋼鐵空罐 1個（直徑12〜15cm）＆ 內層小號鋼鐵空罐 1個（直徑8〜10cm）\",\n      \"desc\": \"套在一起時內外罐壁之間剛好留有一指節寬（1.5〜2cm）空氣間隙的兩個堅固橫紋食品鐵罐或奶粉罐。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"剝去外皮的廢電線金屬芯線 50cm\",\n      \"desc\": \"用[鋒利石片刀或石斧](/protocol-04.html)剖開廢棄電線的外層絕緣皮，取出耐高溫的裸銅線或鐵芯線（粗1.5〜3mm），用於捆綁雙罐與製作十字鍋架。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"尖頭廢鐵釘（或石錐）與石錘\",\n      \"desc\": \"堅硬的尖鐵釘或尖銳石錐搭配拳頭大小的鵝卵石，用來在鐵罐底部與側壁鑿出一次與二次進氣孔。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"折成拇指長的乾燥細枝兩把與松脂引火物\",\n      \"desc\": \"垂直塞入內罐的乾燥硬木細枝，以及放在頂層用於由上往下點火的[松脂塊](/protocol-10.html)與乾樹皮。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"步驟1：挑選耐高溫鋼鐵罐與廢電線，並預先空燒去除內壁有毒塗層\",\n      \"description\": \"1. **挑選橫紋鋼鐵空罐**：選出兩個用手用力捏也不會凹陷、側面有橫向凹凸加強筋的鋼鐵罐。把小罐放進大罐中央時，四周必須留出**一指節寬（約1.5〜2cm）**的空氣通道。\\n2. **剝除廢電線絕緣外皮**：用[鋒利石片刀](/protocol-04.html)劃開廢電線外皮，抽出**50公分長的不燃裸銅線或鐵絲芯線**。\\n3. **5分鐘空燒去除環氧塗層**：打孔前先在兩個空罐內塞滿乾葉與細枝，**在戶外空燒5分鐘**，將罐內的環氧樹脂薄膜與外層油漆徹底燒光。\\n4. **確認霧面黑灰色鋼壁**：待刺鼻氣味散去、罐內壁變成**霧面深黑灰色**後，移至陰涼處完全冷卻。\",\n      \"actionNote\": \"> 毒氣與薄罐警告：省略空燒步驟會讓有毒煙霧溶入飲水中。此外薄飲料罐遇高溫會像紙一樣熔化，請對照下方實拍圖鑑認明**橫紋鋼鐵罐**與**裸金屬電線芯**。\",\n      \"svgFileName\": \"pr12-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // STEEL CAN SELECTION & LINER BURN-OFF\",\n        \"外層大號鋼鐵罐（12〜15cm）＆內層小號鐵罐\",\n        \"內外罐壁之間保留一指節（1.5〜2cm）空氣間隙\",\n        \"使用前空燒5分鐘徹底燒除內壁環氧樹脂膜\",\n        \"[核心] 嚴選耐高溫鋼鐵罐＆取得去皮裸電線芯\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"URBAN SALVAGE\",\n        \"title\": \"鍍錫碳鋼罐（熔點1,500℃）選別與雙酚A環氧塗層熱分解安全守則\",\n        \"text\": \"食品罐頭與奶粉罐使用的鍍錫碳鋼（馬口鐵）熔點高達約**1,500℃**，能反覆承受木煤氣爐800〜900℃的高溫；而薄飲料罐熔點僅**660℃**，在二次燃燒高溫下會立刻熔毀。預先在戶外空燒可將內壁防腐環氧樹脂完全碳化，確保煮水安全無毒。\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"耐高溫橫紋鋼鐵食品／奶粉罐\",\n            \"scientificName\": \"Tin-Coated Corrugated Carbon Steel\",\n            \"categoryTag\": \"城市金屬廢料 / 雙層燃燒室本體\",\n            \"imageFileName\": \"id-steel-tin-can.jpg\",\n            \"hudCode\": \"FIG. SALV-12A // MACRO OPTIC\",\n            \"hudStatus\": \"MELT POINT 1500C: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"外觀/RIB\",\n                \"value\": \"圓筒側壁壓有**多圈橫向凸起的加強筋（波紋槽）**，受高熱與手捏都不易變形。\"\n              },\n              {\n                \"label\": \"捲邊/RIM\",\n                \"value\": \"上下罐口皆有厚實的雙重捲邊接縫，用石頭敲擊會發出**厚重清脆的鋼鐵聲**。\"\n              },\n              {\n                \"label\": \"空燒/PREP\",\n                \"value\": \"用乾葉火預燒5分鐘後，內壁反光塗層消失，露出**安全的霧面深灰色鋼鐵表面**。\"\n              }\n            ],\n            \"fieldUse\": \"雙重燃燒木煤氣爐主體、野外煮沸消毒容器、木炭保存罐\"\n          },\n          {\n            \"name\": \"去皮廢電線芯＆乾燥硬木細枝\",\n            \"scientificName\": \"Stripped Copper/Steel Core & Dry Hardwood\",\n            \"categoryTag\": \"城市與自然混合 / 耐熱捆綁材與燃料\",\n            \"imageFileName\": \"id-salvage-wire-twigs.jpg\",\n            \"hudCode\": \"FIG. SALV-12B // MACRO OPTIC\",\n            \"hudStatus\": \"INSULATION STRIPPED: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"芯線/CORE\",\n                \"value\": \"用石刃完全剝去外皮的**紫紅粗銅線或銀灰鐵芯線**（線徑**1.5〜3mm**）。\"\n              },\n              {\n                \"label\": \"燃料/FUEL\",\n                \"value\": \"彎折時會發出清脆斷裂聲的**手指粗、拇指長乾燥硬木細枝**。\"\n              },\n              {\n                \"label\": \"引火/TINDER\",\n                \"value\": \"擺在細枝最頂端、能迅速向下引燃的**琥珀色松脂塊與乾燥樹皮**。\"\n              }\n            ],\n            \"fieldUse\": \"雙層爐壁耐高溫固定、十字架鍋架、無煙高熱木煤氣燃料\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"步驟2：在內層小罐底部與頂部側壁鑿出一次進氣孔與二次煤氣噴嘴\",\n      \"description\": \"1. **內罐防凹支撐**：打孔前先在小罐內部塞入硬木塊或壓實的泥土，防止敲擊時罐壁凹陷。\\n2. **鑿出底部一次進氣孔**：將尖鐵釘或石錐抵住小罐底部，用石錘均勻敲出**12〜15個小指粗（直徑8mm）的底孔**。\\n3. **鑿出頂部側壁二次噴嘴**：沿著小罐頂部邊緣往下**一指節（約1.5cm）處**的側壁周圍，均勻鑿出**8〜10個拇指粗（直徑10〜12mm）的二次煤氣噴孔**。\\n4. **敲平鋒利鐵刺**：用石頭邊緣將孔洞內側翻起的鋒利鐵皮毛邊敲平，避免割傷手指。\",\n      \"actionNote\": \"> 頂部大孔的作用：小罐上緣這一圈8〜10個大孔就是將濃煙變成火燄的「瓦斯爐噴嘴（二次燃燒噴孔）」。孔徑維持拇指粗（10〜12mm），噴出的火柱才會強勁。\",\n      \"svgFileName\": \"pr12-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // INNER BURN CHAMBER PERFORATION\",\n        \"內罐底部一次進氣與排灰孔（8mm × 12〜15孔）\",\n        \"上緣1.5cm下二次煤氣噴嘴（10〜12mm × 8〜10孔）\",\n        \"用尖鐵釘與石錘打孔並敲平內部鋒利毛邊\",\n        \"[核心] 完成底部排灰網＆頂部高溫氧氣噴嘴\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD THERMODYNAMICS\",\n        \"title\": \"一次熱裂解爐篦與二次木煤氣噴嘴的截面積設計\",\n        \"text\": \"內罐底部的小孔提供樹枝熱裂解所需的少量一次空氣，並讓灰燼自然落下；而頂部周圍的大孔則將沿雙層壁上升的高溫預熱空氣強勁噴入燃燒室頂端，與上升的可燃木煤氣（一氧化碳、甲烷）混合並徹底燃燒。\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"步驟3：鑿開外罐頂蓋套入內罐，並用去皮廢電線捆綁固定與折出十字鍋架\",\n      \"description\": \"1. **鑿出外罐底部進氣孔**：在大號外罐距離底部**1.5公分高的側壁四周**，均勻鑿出**8〜10個拇指粗（直徑12mm）的冷空氣吸入孔**。\\n2. **鑿開外罐頂蓋中央圓口**：用石刃或鐵釘在大罐頂蓋中央鑿出圓形開口，讓小號內罐能緊密插到頂部邊緣。\\n3. **用廢電線鎖緊雙層罐口**：將小罐插入大罐（小罐底部懸空距離大罐底部**約2cm**），把**裸銅線或鐵絲**穿過兩罐上緣的對稱孔洞，用木棒絞緊固定。\\n4. **彎折十字鍋架**：將剩餘的粗電線芯在爐口上方折成**高2〜3公分的十字形鍋架**，確保放上水壺後火燄依然順暢排出。\",\n      \"actionNote\": \"> 排氣間隙關鍵：絕對不能把平底鍋直接貼著罐口平放！若沒有2〜3公分高的電線鍋架留出排氣通道，二次火燄會瞬間窒息並冒出大量黑煙。\",\n      \"svgFileName\": \"pr12-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DOUBLE-WALL NESTING & WIRE BINDING\",\n        \"外罐底部冷空氣吸入孔（12mm × 8〜10孔）\",\n        \"內罐懸空套入外罐（保留1.5〜2cm雙層預熱通道）\",\n        \"去皮裸電線鎖死上下罐口＆架設2〜3cm十字鍋架\",\n        \"[核心] 底部進氣→雙壁預熱→頂部噴射通道完成\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"STRUCTURAL MECHANICS\",\n        \"title\": \"為何在850℃爐口必須使用去皮電線金屬芯而非天然植物繩索\",\n        \"text\": \"天然植物纖維繩索在300℃以上就會迅速碳化斷裂。從城市廢電線剝出的裸銅線（熔點**1,085℃**）或鐵絲（熔點**1,500℃**）能在850℃的猛烈火燄中牢牢固定雙層結構，並穩固支撐裝滿水的煮鍋。\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"步驟4：垂直塞滿乾燥細枝，由上往下點火並以無煙噴射火燄煮沸飲水\",\n      \"description\": \"1. **垂直塞緊乾燥細枝**：將手指粗的乾硬木細枝折成拇指長，**垂直站立緊密塞入**內罐中，高度剛好停在**頂部二次噴嘴孔的正下方**。\\n2. **頂部向下點火（Top-Down）**：在垂直細枝的**最頂端**鋪上乾樹皮與[松脂引火物](/protocol-10.html)，用[弓鑽取火](/protocol-02.html)取得的火種從最上方點燃。\\n3. **確認二次木煤氣噴射火燄**：點火後2〜3分鐘雙層壁受熱，頂部噴孔會向內噴出**明亮的金黃與淡藍色二次火柱**，濃煙隨即完全消失。\\n4. **煮沸飲水與收集生物炭**：將裝有[過濾水](/protocol-01.html)的容器放上電線鍋架，7〜8分鐘即可滾沸；煮完水後用泥土蓋熄底部通紅的炭火，即可收穫[純淨木炭（生物炭）](/protocol-09.html)。\",\n      \"actionNote\": \"> 為什麼要從最上面點火？：若從底部點火，整罐樹枝會同時悶燒冒出濃煙。像蠟燭一樣從頂端往下燒，下方熱裂解產生的濃煙就必須穿過頂層的高溫火環，變成100%無煙的強勁火力。\",\n      \"svgFileName\": \"pr12-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // TOP-DOWN PYROLYSIS & SECONDARY JETS\",\n        \"在頂部噴嘴孔下方垂直緊密塞滿乾燥細枝\",\n        \"將松脂與乾樹皮放在最頂層由上往下點火\",\n        \"預熱氧氣從噴孔噴出點燃木煤氣實現無煙燃燒\",\n        \"[核心] 僅用兩把細枝在8分鐘內無煙煮沸1L水\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"COMBUSTION SCIENCE\",\n        \"title\": \"頂部點火上吸式氣化（TLUD）與生物炭（Biochar）同步生成原理\",\n        \"text\": \"在頂部點火氣化爐（TLUD）中，熱裂解層會由上往下緩慢推進。下層木枝釋放的揮發性木煤氣向上竄升時，會被頂部850℃的預熱氧氣噴流徹底燃燒，消除95%以上的煙塵，並在爐底留下高純度木炭。\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命失誤：直接使用未空燒去除內壁塗層的罐頭，或拿薄飲料罐當爐體\",\n    \"description\": \"食品罐頭內壁塗有防鏽環氧樹脂膜，若未事先空燒燒除就直接煮水，劇毒煙霧與環境荷爾蒙會滲入飲水中；此外薄飲料罐在660℃就會瞬間熔穿，導致滾水翻倒造成嚴重燙傷。\",\n    \"consequence\": \"後果：吸入劇毒廢氣中毒，以及爐體坍塌導致滾水全身燙傷\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"只要撿2個廢棄空鐵罐和一把枯枝，就能做出一點黑煙都沒有、8分鐘煮開水的怪獸級火箭爐！\",\n    \"body\": \"先挑兩個大小不同的鋼鐵罐頭，用乾葉火把內壁的有毒塗層徹底燒掉。在小罐底部打滿進氣孔，上緣側面鑿出8個拇指粗的噴氣孔。在大罐底部也打進氣孔，把小罐從上方套進去，用剝皮廢電線綁緊做成雙層壁！塞滿直立的乾樹枝並從最上面點火，雙層壁加熱後的熱空氣就會把濃煙再次點燃，噴出像瓦斯爐一樣的猛烈火燄！\",\n    \"outro\": \"完全不冒煙不會暴露位置，8分鐘水就滾沸。詳細設計圖請見個人檔案連結。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr12-outcome.svg\",\n    \"title\": \"完成的雙鐵罐雙重燃燒木煤氣爐（850℃無煙噴射爐）熱流體斷面規格\",\n    \"description\": \"外層大號鋼鐵罐與內層小號燃燒罐之間的1.5〜2cm雙層預熱空氣通道、底部冷氣吸入孔與頂部二次預熱氧氣噴嘴、廢電線十字鍋架，以及將木煤氣完全燃燒為850℃無煙火燄的熱力學斷面結構。\"\n  },\n  \"createdAt\": \"2026-10-17T10:12:00.000Z\",\n  \"contentHash\": \"00b85f08738b5163\"\n}","content/protocols/locales/13-wood-ash-lye-soap.de.json":"{\n  \"protocolId\": \"PR-13\",\n  \"category\": \"MEDICINE\",\n  \"title\": \"Herstellung von natürlicher Eichenaschelauge- & Fettseife zur Infektionsabwehr (Feldhygiene-Desinfektionsseife)\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[FELDHYGIENE & WUNDDESINFEKTION & SEPSIS-PRÄVENTION]\",\n  \"summary\": \"Im autarken Wildnisüberleben oder bei einem Zusammenbruch der Infrastruktur ohne fließendes Wasser und Medikamente können schon kleine Schürfwunden oder verunreinigte Hände beim Essen tödliche Ruhr, Wundstarrkrampf (Tetanus) oder systemische Blutvergiftung (Sepsis) auslösen. Sammelt man schneeweiße Eichenasche aus einer Feuerstelle oder dem [Doppeldosen-Holzvergaserofen](/protocol-12.html), verdichtet sie in einem Dosenfilter mit Schilfgras- und Kiesschicht und übergießt sie mit heißem Wasser, entsteht alkalische Kaliumkarbonatlauge. Kocht man diese Lauge im Verhältnis 1:1 mit ausgelassenem Tiertalg oder gefiltertem Altspeiseöl unter ständigem Rühren mit einem Holzspatel ein, setzt die Verseifung ein und erzeugt eine hochwirksame Desinfektionsseife, die bakterielle Zellmembranen auflöst.\",\n  \"timeRequired\": \"70 Minuten (20 Min. Ascheauslaugung + 45 Min. Verseifungssieden + 5 Min. Gießen)\",\n  \"successRate\": \"95% (bei Einhaltung der Kartoffel-Auftriebsdichte und kontinuierlichem Rühren in eine Richtung)\",\n  \"difficulty\": \"Mittel (äußerste Vorsicht vor Verätzungen von Haut und Augen durch stark basische Lauge)\",\n  \"outputPerHour\": \"1 Eimer Eichenasche & 2 Tassen Fett ergeben 3–4 feste Seifenstücke (1 Monatsvorrat)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Ein Eimer vollständig verbrannte, schneeweiße Hartholz-Asche (Eiche)\",\n      \"desc\": \"Mehlfeine weiße Asche aus einem [Eichenholzkohlemeiler](/protocol-09.html) oder einer Feuerstelle, gesiebt und frei von schwarzen Holzkohlestücken. Harthölzer wie Eiche besitzen den höchsten Kaliumgehalt für konzentrierte Lauge.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Gelochter Dosenfilter mit Trockengras- und Kies-Pufferschicht\",\n      \"desc\": \"Basiert auf dem Filtrationsprinzip des [natürlichen Wasserfilters](/protocol-01.html). Eine große Weißblechdose mit Nagelperforationen im Boden, ausgelegt mit Kieselsteinen und trockenem Schilfgras, um Aschepartikel zurückzuhalten, während klare goldene Lauge abtropft. Schutzlacke zuvor ausbrennen.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Rohes Kartoffelstück (oder frisches Ei) für die Auftriebs-Dichteprüfung\",\n      \"desc\": \"Visueller Dichteanzeiger ohne moderne Hydrometer. Schwimmt das Stück in der Lauge so auf, dass eine Daumennagelbreite über der Oberfläche liegt, entspricht die Dichte exakt den erforderlichen 1,08 g/cm³.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"2 Tassen ausgelassener Tiertalg (Rinder-/Schweinefett) oder geklärtes Altspeiseöl\",\n      \"desc\": \"Über schwacher Hitze geschmolzene Fettabschnitte von Beutetieren, befreit von Grieben und Wasser, oder gefiltertes Pflanzenöl aus städtischen Restbeständen. Hohe Reinheit verhindert Verderb und sichert Formstabilität.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"1 Esslöffel feines Kiefernharzpulver und 1 Teelöffel Kochsalz\",\n      \"desc\": \"Helle Kiefernharzkristalle ähnlich der [Kiefernharz-Wundsalbe](/protocol-10.html), zu feinem Pulver zerstoßen. Natürliche Phytonzide maximieren die antimikrobielle Wirkung; das Salz unterstützt die Härtung der Seifenstücke.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Schritt 1: Weiße Eichenasche im Dosenfilter verdichten und mit heißem Wasser goldene Lauge auslaugen\",\n      \"description\": \"1. **Ascheauslese & Vorbereitung**: Sortieren Sie unverbrannte schwarze Kohlestücke aus und sammeln Sie einen Eimer **mehlfeine, weiße Eichenasche**, befreit von Rinde und Steinen.\\n2. **Kies- & Grasfilterschicht anlegen**: Stanzen Sie kleine Nagellöcher in den Boden einer großen Blechdose, legen Sie saubere daumendicke Kiesel hinein und verdichten Sie trockenes Schilfgras **zwei Fingerbreit (ca. 3 cm)** fest darüber.\\n3. **Asche einfüllen & Heißwasseraufguss**: Drücken Sie die weiße Asche bis zu **einer Handbreite unter den Rand (80% Füllung)** fest an und gießen Sie langsam [kochendes, heißes Wasser](/protocol-01.html) auf, bis das Aschebett vollständig getränkt ist.\\n4. **Goldene Lauge auffangen**: Stellen Sie ein sauberes Auffanggefäß unter die Dose und fangen Sie die tropfende, bernsteingoldene, seifig-glatte Holzaschelauge (Kaliumkarbonatlösung) auf.\",\n      \"actionNote\": \"> Verätzungsgefahr: Konzentrierte Eichenaschelauge zersetzt Proteine und verursacht schwere Verätzungen auf ungeschützter Haut. Benutzen Sie ausschließlich Holzspatel und spülen Sie Spritzer sofort 5 Minuten mit klarem, kaltem Wasser aus. Botanische Felddetails siehe Spezifikation unten.\",\n      \"svgFileName\": \"pr13-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // EICHENASCHELAUGE-AUSLAUGUNGSFILTER\",\n        \"EICHEN-WEISSASCHEBETT (OBERE 80% VERDICHTET)\",\n        \"SCHILFGRAS-FASERSCHICHT & KIES-PUFFERFILTER\",\n        \"AUSGELAUGTE BERNSTEINGOLDENE ALKALISCHE LAUGE\",\n        \"[SCHRITT 1 FOKUS] ASCHESIEBUNG & HEISSWASSER-LIXIVIATION\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD CHEMISTRY\",\n        \"title\": \"Kaliumkarbonat-Auslaugung (K2CO3) und hochalkalische Ausbeutefaktoren\",\n        \"text\": \"Beim Verbrennen dichter Harthölzer wie Eiche reagiert das im Holzgewebe gespeicherte Kalium zu Kaliumkarbonat (K2CO3). Durch die Verwendung von 70–80°C heißem Wasser verdoppelt sich die Löslichkeit im Vergleich zu kaltem Wasser, was eine schnelle Auslaugung hochkonzentrierter Lauge bewirkt. Schwarze Holzkohleanteile müssen zwingend entfernt werden, da lösliche Gerbstoffe (Tannine) die Seife brüchig machen und verfärben.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"Vollständig ausgebrannte weiße Eichenholzasche\",\n            \"scientificName\": \"Quercus Acutissima White Wood Ash\",\n            \"categoryTag\": \"Feldchemisches Reagenz / Alkalische Kaliumquelle\",\n            \"imageFileName\": \"id-oak-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-13A // MACRO OPTIC\",\n            \"hudStatus\": \"POTASSIUM CONTENT HIGH: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"FARBE\",\n                \"value\": \"Kreidig **reinweiß oder helles Silbergrau**, frei von schwarzen Kohleresten.\"\n              },\n              {\n                \"label\": \"TEXTUR\",\n                \"value\": \"Zerfällt zwischen den Fingern zu einem **seidig-feinen, mehlartigen Pulver**.\"\n              },\n              {\n                \"label\": \"LAUGE\",\n                \"value\": \"Ergibt nach Heißwasserdurchlauf eine **klare, bernsteingoldene Flüssigkeit** mit rutschigem Griff.\"\n              }\n            ],\n            \"fieldUse\": \"Laugenextraktion für Seife, Neutralisation saurer Böden, Entspelzung von Getreide\"\n          },\n          {\n            \"name\": \"Natürliche Kiefernharzkristalle\",\n            \"scientificName\": \"Pinus Densiflora Natural Oleoresin\",\n            \"categoryTag\": \"Feld-Konservierungsmittel / Natürliches antibakterielles Phytonzid\",\n            \"imageFileName\": \"id-pine-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-13B // MACRO OPTIC\",\n            \"hudStatus\": \"TERPENE PURITY: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"FORM\",\n                \"value\": \"Erstarrte **bernsteinfarbene oder weißgelbliche, halbtransparente Harztränen**.\"\n              },\n              {\n                \"label\": \"DUFT\",\n                \"value\": \"Beim Zerdrücken verströmt es einen **intensiv-frischen Terpengeruch nach Nadelwald**.\"\n              },\n              {\n                \"label\": \"WIRKUNG\",\n                \"value\": \"Stabilisiert den Schaum und **hemmt Staphylokokken sowie infektiöse Keime**.\"\n              }\n            ],\n            \"fieldUse\": \"Antiseptischer Seifenzusatz, desinfizierende Wundsalbe, wasserfester Baumharzkleber\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Schritt 2: Laugendichte mittels Kartoffel-Auftrieb prüfen und Talg oder Altspeiseöl klären\",\n      \"description\": \"1. **Kartoffel-Dichteprüfung**: Legen Sie ein **daumennagelgroßes Stück rohe Kartoffel (ca. 2 cm)** oder ein frisches rohes Ei vorsichtig in die aufgefangene Lauge.\\n2. **Auftriebshöhe beurteilen**: Sinkt das Stück auf den Boden, ist die Lauge zu schwach; kochen Sie sie auf kleiner Flamme ein, **bis sich das Volumen halbiert hat**. Schwimmt die Kartoffel so, dass **eine Daumennagelfläche über den Wasserspiegel ragt**, ist die optimale Konzentration erreicht.\\n3. **Tiertalg ausschmelzen**: Schneiden Sie Fettabschnitte von Beutetieren klein, geben Sie sie in einen Topf über der schwachen Flamme des [Holzvergaserofens](/protocol-12.html) und schmelzen Sie klares flüssiges Öl aus.\\n4. **Filtrieren & Abmessen**: Seihen Sie das geschmolzene Fett durch ein sauberes Tuch oder Schilf ab, um Fleischreste und Wasser vollständig zu entfernen, und stellen Sie **exakt 2 Tassen klares Öl** bereit.\",\n      \"actionNote\": \"> Auftriebsregel: Ragt die Kartoffel zu mehr als der Hälfte aus der Lauge heraus, ist die Lauge überkonzentriert und führt zu Hautreizungen. Geben Sie schrittweise eine halbe Tasse sauberes Wasser hinzu, bis nur noch eine kleine Kuppe herausschaut.\",\n      \"svgFileName\": \"pr13-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // KARTOFFEL-AUFTRIEBS-DICHTETEST\",\n        \"AUFSCHWIMMENDES KARTOFFELSTÜCK (DAUMENNAGELBREITE)\",\n        \"EINKOCHEN BEI UNTERSCHREITUNG & VERDÜNNEN BEI ÜBERSCHUSS\",\n        \"AUSGELASSENER TIERTALG & 2 TASSEN REINES ÖL\",\n        \"[SCHRITT 2 FOKUS] DICHTEKONTROLLE & FETTKLÄRUNG\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"SPECIFIC GRAVITY\",\n        \"title\": \"Hydrodynamik der feldmäßigen Dichtemessung (Spezifisches Gewicht 1,05~1,10)\",\n        \"text\": \"Eine gebrauchsfähige Seifenlauge besitzt eine Dichte von ca. 1,08 g/cm³. Frische rohe Kartoffeln weisen eine mittlere Dichte von 1,06 bis 1,09 g/cm³ auf und schwimmen gemäß dem archimedischen Prinzip erst dann auf, wenn die Kaliumkarbonatkonzentration ausreichend hoch ist. Bei einer Dichte unter 1,05 g/cm³ misslingt die Verseifungsreaktion und die Phasen trennen sich wieder.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Schritt 3: Lauge und Fett im Verhältnis 1:1 mischen und unter stetigem Rühren bis zur Zeichnung sieden\",\n      \"description\": \"1. **Mischungsverhältnis einhalten**: Geben Sie 2 Tassen geklärtes warmes Fett und 2 Tassen eingestellte Lauge im **exakten 1:1 Volumenverhältnis** in einen Metalltopf.\\n2. **Sanfte Glutwärme**: Meiden Sie offenes Brandfeuer und halten Sie den Topf auf sanfter Glutwärme, sodass **lediglich feine Bläschen am Topfrand aufsteigen**.\\n3. **Kontinuierliches Rühren in eine Richtung**: Rühren Sie die Mischung mit einem flachen Holzspatel **40 bis 50 Minuten lang ununterbrochen in kreisenden Bewegungen in dieselbe Richtung**. Ein plötzlicher Richtungswechsel kann die Emulsion zerreißen.\\n4. **Prüfung der Zeichnung (Trace) & Harzzugabe**: Sobald die Masse die Konsistenz von dickflüssigem Brei oder Erdnussbutter annimmt und vom Spatel abtropfende Spuren **mindestens 3 Sekunden lang sichtbar auf der Oberfläche verweilen**, rühren Sie **1 Esslöffel Kiefernharzpulver** und 1 Teelöffel Salz ein und nehmen den Topf von der Glut.\",\n      \"actionNote\": \"> 3-Sekunden-Zeichnung: Die Seifenmasse muss beim Anheben des Spatels deutliche, erhabene Fäden bilden, die nicht sofort verlaufen. Dies signalisiert den erfolgreichen Abschluss der chemischen Verseifung. Das Kiefernharz verleiht einen frischen Duft und stärkt den Schaum.\",\n      \"svgFileName\": \"pr13-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // VERSEIFUNGSREAKTION & RÜHRPROZESS\",\n        \"LAUGE & GEKLÄRTES FETT IM 1:1 VOLUMENVERHÄLTNIS\",\n        \"KONTINUIERLICHES RÜHREN IN EINE RICHTUNG (45 MIN)\",\n        \"ZEICHNUNG: SPATELSPUR BLEIBT 3 SEKUNDEN BESTEHEN\",\n        \"[SCHRITT 3 FOKUS] MÄSSIGE HITZE & HARZZUGABE\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"SAPONIFICATION\",\n        \"title\": \"Triglycerid-Hydrolyse und Glycerinbildung im Verseifungsprozess\",\n        \"text\": \"Esterbindungen der Triglyceride im Fett werden durch basische Kaliumionen hydrolysiert. Dabei verbinden sich Fettsäuren mit Kalium zu Kaliumfettsäuresalzen (echte Naturseife), während Glycerin als natürlicher Feuchtigkeitsspender freigesetzt wird. Das gleichmäßige Rühren in eine Richtung vergrößert die Grenzfläche der nicht mischbaren Phasen und beschleunigt die molekulare Bindung.\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Schritt 4: In Rindenformen gießen, im Schatten aushärten lassen und Verträglichkeit per Schaumtest prüfen\",\n      \"description\": \"1. **Rindenform falten**: Falten Sie aus glatter Birken- oder Kiefernrinde eine **handtellergroße rechteckige Kastenform** oder modellieren Sie einen Lehmdamm auf einer flachen Steinplatte.\\n2. **Eingießen & Entlüften**: Gießen Sie den zähflüssigen Seifenbrei in die Form und klopfen Sie den Boden sanft auf, um Luftbläschen entweichen zu lassen.\\n3. **48 Stunden Schattentrocknung**: Lagern Sie die Form an einem gut belüfteten, regengeschützten und schattigen Felsspalt und lassen Sie sie **zwei volle Tage (48 Stunden)** fest werden.\\n4. **Schaumtest auf dem Handrücken**: Schneiden Sie die feste Seife in faustgroße Stücke. Befeuchten Sie ein Stück und reiben Sie es auf dem Handrücken: Entsteht ein **feiner, dichter weißer Schaum ohne Brennen oder Rötung**, ist die Seife einsatzbereit.\",\n      \"actionNote\": \"> Verträglichkeitskontrolle: Brennt oder juckt die Haut beim Einreiben, ist noch unneutralisierte Restlauge vorhanden. Spülen Sie die Haut mit Wasser ab und lassen Sie die Seife weitere 3 bis 4 Tage im Schatten nachreifen; sie nimmt Kohlendioxid aus der Luft auf und wird mild.\",\n      \"svgFileName\": \"pr13-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // RINDENFORMGUSS & SCHAUM-SICHERHEITSTEST\",\n        \"RECHTECKIGE BIRKENRINDEN-GUSSFORM & BEFÜLLUNG\",\n        \"48 STUNDEN SCHATTENAUSHÄRTUNG AN FRISCHER LUFT\",\n        \"FEINER DICHTER SCHAUM OHNE HAUTBRENNEN\",\n        \"[SCHRITT 4 FOKUS] VOLLSTÄNDIGE REIFUNG & HAUTTEST\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"ANTIMICROBIAL SCIENCE\",\n        \"title\": \"Auflösung von Lipid-Doppelschichten und Zerstörung von Bakterienmembranen\",\n        \"text\": \"Seifenmoleküle bestehen aus einem fettliebenden (lipophilen) Kohlenwasserstoffschwanz und einem wasserliebenden (hydrophilen) Kopf. Treffen sie auf Bakterien oder Viren in Schmutz und Wundsekreten, dringen die lipophilen Enden keilartig in die Lipid-Doppelschicht der mikrobiellen Membran ein, reißen sie auf und zerstören den Erreger, bevor die Bruchstücke im Schaum mit Wasser weggespült werden.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Fataler Fehler: Hantieren mit konzentrierter Lauge ohne Schutz oder Auftragen unreifer Seife auf frische Fleischwunden\",\n    \"description\": \"Aus Eichenasche ausgelaugte Lauge ist stark alkalisch und zersetzt körpereigenes Eiweiß; Berührung mit bloßen Händen führt zu schweren chemischen Verbrennungen, Spritzer in die Augen können zur Erblindung führen. Frische, unvollständig verseifte Seife auf tiefen Wunden ruft Gewebenekrosen hervor. Bei Hautkontakt sofort mindestens 5 Minuten mit reichlich kaltem Wasser spülen. Nutzen Sie ausschließlich Seife, die 48 Stunden gereift ist und den Schaumtest bestanden hat.\",\n    \"consequence\": \"Folge: Schwere chemische Hautverätzungen, irreversible Erblindung durch Hornhautschäden und Gewebenekrosen\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Ohne Ärzte und Penicillin führt ein kleiner Kratzer in der Wildnis binnen 3 Tagen zur tödlichen Sepsis! So kochst du echte Desinfektionsseife aus Eichenasche!\",\n    \"body\": \"Sammle reine weiße Eichenasche in einer gelochten Dose und gieße heißes Wasser darüber, um goldene Lauge zu filtern. Schwimmt ein Stück rohe Kartoffel mit daumennagelbreitem Kopf auf, stimmt die Dichte perfekt! Mische die Lauge 1:1 mit ausgelassenem Tierfett und rühre sie auf kleiner Glut 40 Minuten in eine Richtung. Zieht der Spatel eine 3 Sekunden stehende Spur, rühre Kiefernharzpulver ein und gieße alles in Rindenformen. Nach zwei Tagen Schattenreife wäscht der weiße Schaum sämtliche Keime eiskalt weg!\",\n    \"outro\": \"Lade dir die taktischen Vektor-Schaltpläne für die Offline-Nutzung über den Profil-Link herunter.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr13-outcome.svg\",\n    \"title\": \"Technische Fertigungsspezifikationen & Verseifungs-Querschnitt der Eichenaschelauge-Naturseife\",\n    \"description\": \"Umfassender Querschnitt der chemischen Feldfertigung: Eichenasche-Laugensäule, Kartoffel-Auftriebsprüfung, 1:1-Verseifungsreaktion im Kochtopf und die fertigen quaderförmigen Desinfektionsseifenstücke aus der Rindengussform.\",\n    \"svgLabels\": [\n      \"FIG. 13-M // EICHENASCHELAUGE-SEIFENHERSTELLUNG GESAMTÜBERSICHT\",\n      \"LINKS: EICHENASCHE-AUSLAUGUNG & KARTOFFEL-AUFTRIEBSDICHTE\",\n      \"MITTE: 1:1 VERSEIFUNG BEI MÄSSIGER HITZE & HARZZUGABE\",\n      \"RECHTS: AUSGEHÄRTETE QUADERSICHERHEITSSEIFE AUS RINDENFORM\",\n      \"[PR-13 ABSCHLUSS] KEIMTÖTENDE FELDHYGIENE-DESINFEKTIONSSEIFE\"\n    ]\n  },\n  \"createdAt\": \"2026-10-21T05:30:00.000Z\",\n  \"contentHash\": \"84750b222b4c5546\",\n  \"updatedAt\": \"2026-10-21T05:32:17.564Z\"\n}","content/protocols/locales/13-wood-ash-lye-soap.en.json":"{\n  \"protocolId\": \"PR-13\",\n  \"category\": \"MEDICINE\",\n  \"title\": \"Natural Wood Ash Lye & Oil Soap Making to Prevent Wound Infection (Field Hygiene)\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[FIELD SANITATION & WOUND DISINFECTION & SEPSIS PREVENTION]\",\n  \"summary\": \"In off-grid wilderness survival or post-collapse scenarios without plumbing or medicine, a minor scrape or eating with dirty hands can rapidly cause lethal dysentery, tetanus, or systemic sepsis. By collecting pure white oak ashes from a campfire or [twin-can gasifier stove](/protocol-12.html), packing them in a leacher can with a gravel and grass filter, and pouring hot water through, you extract potassium carbonate lye. Simmering this lye 1:1 with rendered animal tallow or salvaged cooking oil while stirring with a wooden paddle initiates saponification, creating a potent antibacterial soap that ruptures pathogen cell membranes.\",\n  \"timeRequired\": \"70 mins (20m ash leaching + 45m saponification simmer + 5m pour)\",\n  \"successRate\": \"95% (when potato buoyancy indicates correct lye density & continuous 1-way stirring is maintained)\",\n  \"difficulty\": \"Medium (requires skin & eye protection against strong alkaline caustic burn)\",\n  \"outputPerHour\": \"1 bucket of oak ash & 2 cups oil yields 3–4 solid soap bars (1 month field supply)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"One Bucket of Pure White Hardwood (Oak) Ash\",\n      \"desc\": \"Flour-like powdery white ash sifted from an [oak charcoal kiln](/protocol-09.html) or hearth, with all black charcoal chunks removed. Hardwoods like oak provide the highest potassium carbonate concentration for potent lye.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Perforated Metal Can Leacher with Wild Grass & Gravel Filter\",\n      \"desc\": \"Based on the filtration mechanics of the [natural water filter](/protocol-01.html). A salvaged steel can with nail holes in the base, lined with thumb-sized pebbles and dry reed grass to retain ash while dripping clean golden lye. Liners pre-burned to eliminate toxic fumes.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Raw Potato Cube (or Fresh Egg) for Buoyancy Testing\",\n      \"desc\": \"A visual density test gauge. When placed in extracted lye, floating with a thumbnail-sized crown exposed above the surface indicates the precise specific gravity (1.08 g/cm³) needed for soapmaking without modern hydrometers.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"2 Cups Rendered Animal Tallow (Beef/Pork Fat) or Salvaged Cooking Oil\",\n      \"desc\": \"Animal trimmings melted down over gentle heat and strained of cracklings and water, or filtered cooking oil scavenged from abandoned kitchens.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"1 Tablespoon Crushed Pine Resin Powder & 1 Teaspoon Salt\",\n      \"desc\": \"Natural golden pine resin crystals from [pine pitch ointment](/protocol-10.html) pulverized into powder to boost antimicrobial strength, combined with a pinch of salt to firm the soap bars.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Step 1: Pack Sifted White Oak Ash in a Can Leacher & Leach Golden Alkaline Lye\",\n      \"description\": \"1. **Sift Pure White Ash**: Discard black charcoal lumps and gather one bucket of powdery **pure white oak ash** free from soil or bark debris.\\n2. **Layer Gravel & Grass Filter**: In a large steel can with small nail holes punched in the base, place thumb-thick clean pebbles and pack dry reed grass **two finger widths deep (about 3cm)** to prevent ash from dumping through.\\n3. **Pack Ash & Pour Hot Water**: Tamp the white ash firmly into the can to **one handspan high (80% full)**, then slowly pour [boiled, warm water](/protocol-01.html) over the top until saturated.\\n4. **Collect Amber Lye**: Place a clean receiving vessel underneath to catch the rich, slippery golden-amber lye (potassium carbonate solution) as it percolates down drop by drop.\",\n      \"actionNote\": \"> Caustic Hazard: Concentrated wood ash lye dissolves organic tissue and causes painful chemical burns on bare skin. Always use a wooden paddle and flush immediately with cool, clean water for 5 minutes if splashed. Ground identification with the botanical traits below.\",\n      \"svgFileName\": \"pr13-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // WOOD ASH LYE EXTRACTION LEACHER\",\n        \"OAK WHITE ASH BED (PACKED TOP 80%)\",\n        \"BASE GRASS FIBER & PEBBLE BUFFER FILTER\",\n        \"LEACHED DEEP AMBER ALKALINE LYE SOLUTION\",\n        \"[KEY STEP 1] SIFT WHITE ASH & WARM WATER LEACHING\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD CHEMISTRY\",\n        \"title\": \"Potassium Carbonate (K2CO3) Leaching & High-Alkaline Extraction Yields\",\n        \"text\": \"Burning dense hardwoods like oak oxidizes potassium stored in wood fibers into potassium carbonate (K2CO3). Pouring warm water (70–80°C) more than doubles solubility compared to cold water, rapidly extracting concentrated lye. Black charcoal chunks must be discarded because unburned tannins darken the solution and soften finished soap bars.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"White Oak Completely Burned Wood Ash\",\n            \"scientificName\": \"Quercus Acutissima White Wood Ash\",\n            \"categoryTag\": \"Field Chemistry Reagent / Potassium Carbonate Source\",\n            \"imageFileName\": \"id-oak-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-13A // MACRO OPTIC\",\n            \"hudStatus\": \"POTASSIUM CONTENT HIGH: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"COLOR\",\n                \"value\": \"Chalky **pure white or pale silvery-grey** powder without black charcoal fragments.\"\n              },\n              {\n                \"label\": \"TEXTURE\",\n                \"value\": \"Crumbles into an **ultra-fine, talc-like dust** between fingers without gritty grit.\"\n              },\n              {\n                \"label\": \"EXTRACT\",\n                \"value\": \"Leaches into a **clear, rich amber-gold fluid** with a distinctly slippery alkaline feel.\"\n              }\n            ],\n            \"fieldUse\": \"Raw material for lye soap, soil pH balancing, hominy corn nixtamalization\"\n          },\n          {\n            \"name\": \"Natural Pine Resin Crystals\",\n            \"scientificName\": \"Pinus Densiflora Natural Oleoresin\",\n            \"categoryTag\": \"Wilderness Preservative / Phytoncide Antibacterial\",\n            \"imageFileName\": \"id-pine-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-13B // MACRO OPTIC\",\n            \"hudStatus\": \"TERPENE PURITY: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"RESIN\",\n                \"value\": \"Translucent **golden amber crystals** oozed from natural pine bark crevices.\"\n              },\n              {\n                \"label\": \"AROMA\",\n                \"value\": \"Emits a sharp, invigorating **terpene pine aroma** when pulverized between stones.\"\n              },\n              {\n                \"label\": \"ACTION\",\n                \"value\": \"Firms soap lather and **inhibits bacterial growth (Staphylococcus)** on cleansed skin.\"\n              }\n            ],\n            \"fieldUse\": \"Antimicrobial soap additive, waterproof wound salve, pitch adhesive binder\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Step 2: Balance Lye Strength via Potato Buoyancy & Clarify Tallow / Cooking Oil\",\n      \"description\": \"1. **Float Test Potato Cube**: Drop a **thumbnail-sized raw potato cube (or fresh egg)** into the extracted lye bowl.\\n2. **Check Buoyancy Elevation**: If the potato sinks to the bottom, the lye is too weak—simmer in a pot to **reduce volume by half**. When the potato floats with a **thumbnail-width crown (1–2cm)** protruding above the surface, lye strength is optimal.\\n3. **Render Fat over Gentle Heat**: Dice wild game fat or fat scraps into small chunks and melt slowly in a pot over [gentle stove heat](/protocol-12.html) until liquid oil separates from cracklings.\\n4. **Strain Clarified Oil**: Pour warm melted oil through clean cloth or reed grass to filter out burnt solids and water, yielding **2 cups of pure golden oil**.\",\n      \"actionNote\": \"> Density Rule: If the potato bobs high with over half its body exposed, lye is dangerously caustic. Add half a cup of boiled water to dilute until just the potato top breaks the surface, avoiding harsh skin irritation in the finished soap.\",\n      \"svgFileName\": \"pr13-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // POTATO BUOYANCY SPECIFIC GRAVITY TEST\",\n        \"POTATO FLOATING THUMBNAIL-WIDTH ABOVE LIQUID\",\n        \"WEAK LYE: SIMMER REDUCE // STRONG LYE: DILUTE\",\n        \"RENDERED CLEAN ANIMAL TALLOW / PURIFIED OIL\",\n        \"[KEY STEP 2] VERIFY LYE BUOYANCY & CLARIFY OIL\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"SPECIFIC GRAVITY\",\n        \"title\": \"Tool-Free Hydrometry (Specific Gravity 1.05–1.10) via Archimedes Principle\",\n        \"text\": \"Properly balanced lye reaches a specific gravity around 1.08 g/cm³. Fresh potato density averages 1.06–1.09 g/cm³, meaning buoyant equilibrium occurs only when alkali concentration is sufficient. Below 1.05 g/cm³, saponification fails to initiate, resulting in oily separation.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Step 3: Combine Lye and Oil 1:1, Simmer over Low Heat & Stir to Peanut Butter Trace\",\n      \"description\": \"1. **Measure 1:1 Ratio**: Pour 2 cups of warm clarified oil and 2 cups of balanced lye into a clean metal pot in an **equal 1:1 volume ratio**.\\n2. **Maintain Gentle Heat**: Set the pot over glowing coals or low heat, keeping the liquid at a **gentle simmer with tiny bubbles along the rim**.\\n3. **Continuous Clockwise Stirring**: Stir slowly in **one direction only with a flat wooden paddle for 40–50 minutes**. Reversing direction breaks the emulsion and causes oil separation.\\n4. **Verify 3-Second Trace & Add Resin**: Lift the paddle; when dripping batter leaves a **raised ribbon mark that holds for 3 seconds** (peanut butter consistency), stir in **1 tablespoon crushed pine resin powder** and a pinch of salt, then remove from heat.\",\n      \"actionNote\": \"> 3-Second Trace Signal: Saponification is complete only when the batter holds its shape like thick porridge instead of blending back like liquid. Pine resin adds a clean pine scent, hardens the bar, and enhances antibacterial properties.\",\n      \"svgFileName\": \"pr13-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // SAPONIFICATION REACTION & STIRRING\",\n        \"1:1 VOLUME RATIO BALANCED LYE & PURIFIED OIL\",\n        \"UNIDIRECTIONAL STIRRING FOR 45 MINS WITH PADDLE\",\n        \"THICK TRACE LEAVES RAISED TRAIL FOR 3 SECONDS\",\n        \"[KEY STEP 3] GENTLE SIMMER & CRUSHED PINE RESIN MIX\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"SAPONIFICATION\",\n        \"title\": \"Triglyceride Hydrolysis & Glycerol Release Mechanics\",\n        \"text\": \"Fatty acid triglycerides react with potassium hydroxide/carbonate to split ester bonds, forming potassium carboxylate salts (natural soap) while freeing glycerol as a natural moisturizer. Unidirectional mechanical stirring maximizes interfacial contact area between immiscible liquid phases.\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Step 4: Pour into Bark Molds, Cure in the Shade & Verify with Back-of-Hand Foam Test\",\n      \"description\": \"1. **Form Bark Mold**: Fold smooth birch or pine bark into a **palm-sized rectangular box** pinned with small wooden twigs, or form a flat stone slab with clay borders.\\n2. **Pour & Tap Out Air**: Pour the thick soap batter into the mold and tap the base on the ground to release trapped air pockets.\\n3. **48-Hour Shaded Cure**: Set the filled mold in a cool, well-ventilated shaded rock crevice away from direct sun and **let harden for 48 hours**.\\n4. **Back-of-Hand Foam Test**: Slice cured soap into fist-half bars with a knife. Rub with water onto the back of your hand; if it lathers into **creamy white foam without stinging or burning**, it is safe for washing wounds and camp utensils.\",\n      \"actionNote\": \"> Skin Safety Test: If rubbing causes redness or a stinging sensation, excess unreacted lye remains. Rinse immediately and let bars cure in the shade for an additional 3–5 days. Atmospheric carbon dioxide naturally neutralizes residual alkalinity into mild, gentle soap.\",\n      \"svgFileName\": \"pr13-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // MOLD CASTING & FOAM SAFETY TEST\",\n        \"BIRCH BARK RECTANGULAR FORM CASTING\",\n        \"48-HOUR SHADED WELL-VENTILATED HARDENING CURE\",\n        \"RICH CREAMY FOAM ON SKIN WITHOUT STINGING\",\n        \"[KEY STEP 4] COMPLETE CURING & FOAM SAFETY PASS\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"ANTIMICROBIAL SCIENCE\",\n        \"title\": \"Lipid Bilayer Dissolution & Pathogen Membrane Destruction\",\n        \"text\": \"Soap molecules possess a hydrophobic hydrocarbon tail and a hydrophilic polar head. When applied to bacterial pathogens, the hydrophobic tails wedge into the lipid bilayer of cell membranes, prying them apart and lysing the microbe. Rinsing lifts enveloped debris away inside micro-emulsion micelle foam.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Fatal Mistake: Handling raw concentrated lye bare-handed or applying uncured fresh soap directly to open wounds\",\n    \"description\": \"Wood ash lye is a strong alkaline caustic that dissolves skin proteins, causing severe chemical burns, tissue necrosis, and permanent blindness if splashed into the eyes. Applying uncured fresh soap before complete saponification burns flesh and destroys healing tissue. Flush splashes immediately with cold running water for 5+ minutes, and only use bars that have cured 48+ hours and passed the back-of-hand foam safety check.\",\n    \"consequence\": \"Outcome: Severe caustic chemical skin burns, ocular blindness & wound tissue necrosis\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Wild muddy water on an open wound will cause lethal sepsis in 3 days! Here is how to make antiseptic soap from campfire ash!\",\n    \"body\": \"Sift white oak ash, pack it over gravel in a can, and pour hot water to extract golden lye. Float a raw potato cube; when it bobs thumbnail-width high, lye strength is perfect! Mix 1:1 with animal fat in a pot over gentle heat and stir clockwise for 40 minutes. When the batter holds a 3-second trace like peanut butter, pour into a bark mold and cure 48 hours in the shade! When it lathers into rich white foam without stinging, your field-grade antiseptic soap is ready to kill deadly bacteria!\",\n    \"outro\": \"Access full offline survival blueprints with zero cell data via the profile link.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr13-outcome.svg\",\n    \"title\": \"Completed Wood Ash Lye Soap Production & Saponification Chemical Overview\",\n    \"description\": \"A comprehensive chemical and mechanical overview illustrating hardwood ash percolation, potato buoyancy hydrometry, 1:1 pot simmer saponification, and rectangular solid cured antiseptic soap bars cast in birch bark molds.\",\n    \"svgLabels\": [\n      \"FIG. 13-M // NATURAL WOOD ASH LYE SOAP PRODUCTION OVERVIEW\",\n      \"LEFT: OAK ASH LEACHING & POTATO BUOYANCY DENSITY TEST\",\n      \"CENTER: LOW-HEAT 1:1 SAPONIFICATION & RESIN STIRRING\",\n      \"RIGHT: TREE BARK MOLD CURED SOLID ANTISEPTIC SOAP BARS\",\n      \"[PR-13 FINAL BLUEPRINT] PATHOGEN MEMBRANE DESTROYING SOAP\"\n    ]\n  },\n  \"createdAt\": \"2026-10-21T05:30:00.000Z\",\n  \"contentHash\": \"84750b222b4c5546\",\n  \"updatedAt\": \"2026-10-21T05:32:17.564Z\"\n}","content/protocols/locales/13-wood-ash-lye-soap.es.json":"{\n  \"protocolId\": \"PR-13\",\n  \"category\": \"MEDICINE\",\n  \"title\": \"Fabricación de Jabón Desinfectante Natural con Lejía de Ceniza de Roble y Grasa para Prevenir Infecciones\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[HIGIENE DE CAMPO & DESINFECCIÓN DE HERIDAS & PREVENCIÓN DE SEPSIS]\",\n  \"summary\": \"En escenarios de supervivencia agreste o colapso de infraestructuras sin agua corriente ni medicinas, un simple raspón o comer con manos contaminadas puede provocar disentería mortal, tétanos o sepsis sistémica fulminante. Al recolectar ceniza blanca pura de roble de una hoguera o de la [estufa de gasificación de leña de doble lata](/protocol-12.html), compactarla en una lata filtrante con lecho de grava y hierba seca, y verter agua caliente, se extrae lejía alcalina de carbonato de potasio. Al hervir suavemente esta lejía en proporción 1:1 con sebo animal clarificado o aceite vegetal rescatado mientras se bate continuamente con una espátula de madera, se desencadena la saponificación, produciendo un potente jabón antiséptico que destruye las membranas de los patógenos.\",\n  \"timeRequired\": \"70 minutos (20 min lixiviación de ceniza + 45 min ebullición de saponificación + 5 min vertido)\",\n  \"successRate\": \"95% (al verificar densidad con flotación de patata y mantener batido unidireccional)\",\n  \"difficulty\": \"Media (precaución extrema contra quemaduras cáusticas por lejía alcalina en piel y ojos)\",\n  \"outputPerHour\": \"1 cubo de ceniza de roble y 2 tazas de grasa rinden 3–4 pastillas de jabón (suministro mensual de campo)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Un cubo de ceniza blanca pura de madera dura (roble) completamente calcinada\",\n      \"desc\": \"Ceniza pulverulenta y sedosa como harina, recolectada de un [horno de carbón de roble](/protocol-09.html) o fogón, tras cribar y retirar todos los trozos negros de carbón. El roble ofrece la máxima concentración de sales de potasio para una lejía concentrada.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Lata metálica perforada con lecho filtrante de grava y hierba seca\",\n      \"desc\": \"Basada en los principios mecánicos del [filtro de agua natural](/protocol-01.html). Una lata de conserva grande con agujeros de clavo en la base, almohadillada con guijarros y hierba seca compacta para retener la ceniza mientras drena lejía dorada limpia. Quemar previamente los recubrimientos sintéticos.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Trozo de patata cruda (o huevo fresco) para prueba de flotabilidad\",\n      \"desc\": \"Indicador hidrométrico visual sin instrumentos modernos. Al colocarla en la lejía, debe flotar asomando una corona del tamaño de una uña sobre la superficie, confirmando la densidad ideal (1,08 g/cm³) para la saponificación.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"2 tazas de grasa animal clarificada (sebo de res/cerdo) o aceite vegetal residual\",\n      \"desc\": \"Recortes de grasa animal derretidos a fuego lento y filtrados de chicharrones y agua, o aceite vegetal recogido de restos urbanos. La ausencia de impurezas garantiza un jabón sólido y duradero que no se enrancia.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"1 cucharada de resina de pino molida y 1 cucharadita de sal común\",\n      \"desc\": \"Cristales transparentes de resina de pino obtenidos como en el [ungüento de brea de pino](/protocol-10.html), triturados en polvo para aportar fitoncidas antibacterianos, junto a una pizca de sal para endurecer las pastillas y facilitar el desmoldeo.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Paso 1: Compactar ceniza blanca de roble en la lata filtrante y lixiviar lejía alcalina dorada con agua caliente\",\n      \"description\": \"1. **Cribado de ceniza blanca pura**: Retire cualquier trozo de carbón negro y recolecte un cubo de **ceniza de roble blanca y fina**, sacudiendo restos gruesos de corteza o tierra.\\n2. **Estratificación del filtro de grava y hierba**: En una lata grande de hojalata con orificios perforados en el fondo, coloque guijarros limpios del grosor de un pulgar y comprima encima hierba seca hasta un espesor de **dos nudillos (aprox. 3 cm)** para evitar fugas de ceniza.\\n3. **Carga de ceniza e infusión caliente**: Rellene con la ceniza blanca comprimiendo firmemente hasta **un palmo de altura (80% del volumen)**, y vierta lentamente [agua hervida muy caliente](/protocol-01.html) hasta saturar todo el lecho.\\n4. **Recolección de lejía ambarina**: Coloque un cuenco limpio debajo para recoger gota a gota la lejía densa, resbaladiza y de color ámbar dorado (solución de carbonato de potasio).\",\n      \"actionNote\": \"> Peligro de quemadura cáustica: La lejía concentrada es altamente alcalina y disuelve la queratina y las proteínas de la piel viva. Utilice siempre espátulas de madera y enjuague de inmediato con agua fría corriente durante 5 minutos si salpica la piel o los ojos. Confirme los rasgos botánicos en la guía inferior.\",\n      \"svgFileName\": \"pr13-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // LEJÍA DE CENIZA DE ROBLE - COLUMNA DE FILTRACIÓN\",\n        \"LECHO DE CENIZA BLANCA DE ROBLE (80% SUPERIOR)\",\n        \"CAPA DE FIBRA DE HIERBA SECA & TAMPÓN DE GRAVA\",\n        \"LIXIVIACIÓN DE LEJÍA ALCALINA ÁMBAR DORADA\",\n        \"[PASO CLAVE 1] CRIBADO DE CENIZA & LIXIVIACIÓN EN CALIENTE\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD CHEMISTRY\",\n        \"title\": \"Lixiviación de Carbonato de Potasio (K2CO3) y Rendimiento Alcalino de Alta Pureza\",\n        \"text\": \"Al quemar maderas duras como el roble, el potasio acumulado en los tejidos vegetales reacciona con el dióxido de carbono formando carbonato de potasio (K2CO3). Verter agua caliente a 70–80°C duplica con creces la solubilidad frente al agua fría, acelerando la extracción de lejía concentrada. El carbón vegetal negro no quemado debe eliminarse minuciosamente, ya que los taninos solubles manchan la solución y reblandecen el jabón final.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"Ceniza de Madera de Roble Completamente Calcinada\",\n            \"scientificName\": \"Quercus Acutissima White Wood Ash\",\n            \"categoryTag\": \"Reactivo Químico de Campo / Fuente de Base Alcalina\",\n            \"imageFileName\": \"id-oak-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-13A // MACRO OPTIC\",\n            \"hudStatus\": \"POTASSIUM CONTENT HIGH: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"COLOR\",\n                \"value\": \"Polvo calcáreo **completamente blanco o gris plateado brillante**, sin residuos de carbón negro.\"\n              },\n              {\n                \"label\": \"TEXTURA\",\n                \"value\": \"Al frotarla entre los dedos, se deshace en un **polvo impalpable y suave** sin granos ásperos.\"\n              },\n              {\n                \"label\": \"LEJÍA\",\n                \"value\": \"Al pasar agua caliente, genera un **líquido ámbar dorado transparente** de tacto muy jabonoso.\"\n              }\n            ],\n            \"fieldUse\": \"Extracción de lejía cáustica para jabón, neutralización de suelos ácidos, pelado de granos\"\n          },\n          {\n            \"name\": \"Cristales de Resina Natural de Pino\",\n            \"scientificName\": \"Pinus Densiflora Natural Oleoresin\",\n            \"categoryTag\": \"Conservante de Campo / Fitoncida Antibacteriano Natural\",\n            \"imageFileName\": \"id-pine-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-13B // MACRO OPTIC\",\n            \"hudStatus\": \"TERPENE PURITY: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"ASPECTO\",\n                \"value\": \"Gotas y lágrimas endurecidas de resina **translúcida de tono ámbar o blanco amarillento**.\"\n              },\n              {\n                \"label\": \"AROMA\",\n                \"value\": \"Al triturarla emana una **fuerte y penetrante fragancia a pinar silvestre (terpenos)**.\"\n              },\n              {\n                \"label\": \"EFECTO\",\n                \"value\": \"Mejora la espuma, endurece la barra e **inhibe estafilococos y bacterias patógenas**.\"\n              }\n            ],\n            \"fieldUse\": \"Aditivo antiséptico para jabón, pomada desinfectante estéril, adhesivo impermeable\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Paso 2: Calibrar la concentración de lejía mediante flotación de patata y clarificar la grasa o aceite residual\",\n      \"description\": \"1. **Prueba hidrométrica con patata cruda**: En el recipiente con la lejía extraída, deposite con delicadeza un **trozo de patata cruda del tamaño de una uña (2 cm de diámetro)** o un huevo fresco.\\n2. **Evaluación de la altura de flotación**: Si la patata se hunde hasta el fondo, la lejía está demasiado diluida; llévela al fuego y **hiérvala a fuego moderado hasta reducir su volumen a la mitad**. Si la patata flota asomando **el tamaño de una uña sobre la superficie**, la concentración es perfecta para fabricar jabón.\\n3. **Clarificación térmica de la grasa animal**: Pique en dados pequeños los restos de grasa de caza o sebo, colóquelos en una olla sobre la llama suave del [estufa de leña de gasificación](/protocol-12.html) y fúndalos lentamente para liberar el aceite líquido claro.\\n4. **Filtrado de impurezas**: Filtre la grasa fundida a través de un paño limpio o fibra vegetal para retirar todos los restos de carne y agua, reuniendo **2 tazas exactas de grasa clarificada y limpia**.\",\n      \"actionNote\": \"> Calibración de flotabilidad: Si la patata flota sobresaliendo más de la mitad, la lejía es excesivamente cáustica y el jabón quemará la piel. Añada media taza de agua limpia para diluir hasta que solo asome una pequeña corona en la superficie.\",\n      \"svgFileName\": \"pr13-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // PRUEBA DE GRAVEDAD ESPECÍFICA CON PATATA\",\n        \"PATATA FLOTANDO ASOMANDO UNA CORONA DEL TAMAÑO DE UNA UÑA\",\n        \"CONCENTRAR SI SE HUNDE & DILUIR SI FLOTA EN EXCESO\",\n        \"SEBO ANIMAL FUNDIDO & 2 TAZAS DE ACEITE CLARIFICADO\",\n        \"[PASO CLAVE 2] CONTROL DE FLOTABILIDAD & FILTRADO DE GRASA\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"SPECIFIC GRAVITY\",\n        \"title\": \"Hidrodinámica del Control de Densidad de Campo (Gravedad Específica 1,05~1,10)\",\n        \"text\": \"La lejía en concentración óptima alcanza una gravedad específica cercana a 1,08 g/cm³. La patata cruda fresca posee una densidad media de 1,06 a 1,09 g/cm³, por lo que solo flotará según el principio de Arquímedes cuando la concentración alcalina sea suficiente. Una densidad inferior a 1,05 impide la reacción de saponificación y provoca la separación de fases entre el aceite y el agua.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Paso 3: Mezclar lejía y grasa en proporción 1:1 y hervir batiendo en una sola dirección hasta alcanzar traza\",\n      \"description\": \"1. **Proporción de vertido**: En una olla metálica, combine 2 tazas de grasa animal clarificada tibia y 2 tazas de lejía calibrada en **proporción de volumen exacta 1:1**.\\n2. **Cocción a fuego bajo y constante**: Evite llamas intensas; mantenga la mezcla sobre brasas calientes asegurando **un hervor suave con diminutas burbujas en los bordes**.\\n3. **Batido unidireccional ininterrumpido**: Con una espátula de madera limpia, remueva el líquido en **círculos hacia una sola dirección durante 40 a 50 minutos** sin detenerse. Si invierte la dirección bruscamente, la emulsión puede romperse separando el aceite de la lejía.\\n4. **Verificación del punto de traza y adición de resina**: Cuando la masa adquiera la textura espesa de crema o puré, y al levantar la espátula el chorro forme **un relieve visible que persista durante 3 segundos**, añada **1 cucharada de resina de pino molida** y 1 cucharadita de sal, mezcle a fondo y retire del fuego.\",\n      \"actionNote\": \"> Señal de traza de 3 segundos: La masa debe mantener surcos nítidos al escurrir de la espátula. Este estado confirma que la saponificación química se ha completado. La resina de pino pulverizada aporta propiedades antisépticas duraderas y compacta la espuma.\",\n      \"svgFileName\": \"pr13-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // REACCIÓN DE SAPONIFICACIÓN & AGITACIÓN\",\n        \"MEZCLA DE LEJÍA Y GRASA CLARIFICADA EN PROPORCIÓN 1:1\",\n        \"BATIDO UNIDIRECCIONAL CONTINUO DURANTE 45 MINUTOS\",\n        \"TRAZA ESPESA CON RELIEVE QUE PERSISTE 3 SEGUNDOS\",\n        \"[PASO CLAVE 3] FUEGO LENTO & INCORPORACIÓN DE RESINA\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"SAPONIFICATION\",\n        \"title\": \"Mecanismo Químico de Hidrólisis de Triglicéridos y Formación de Glicerina\",\n        \"text\": \"Los ésteres de los triglicéridos de la grasa reaccionan con la base de carbonato de potasio, rompiendo los enlaces lipídicos para formar sales potásicas de ácidos grasos (jabón natural) y liberando glicerina como subproducto emoliente. La agitación unidireccional maximiza el área interfacial entre los líquidos inmiscibles, acelerando el choque molecular necesario para la reacción completa.\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Paso 4: Verter en moldes de corteza, curar a la sombra y verificar seguridad con prueba de espuma\",\n      \"description\": \"1. **Construcción del molde de corteza**: Pliegue una lámina limpia y lisa de corteza de abedul o pino formando una **caja rectangular del tamaño de una palma**, o cree un cerco de arcilla sobre una laja de piedra plana.\\n2. **Vertido de masa y desaireado**: Vierta la masa caliente de jabón en el molde y golpee suavemente la base contra el suelo para expulsar las burbujas de aire atrapadas.\\n3. **Curado en sombra ventilada durante 48 horas**: Sitúe el molde en una hendidura rocosa ventilada, protegida de la lluvia y del sol directo, dejándolo endurecer durante **dos días enteros (48 horas)**.\\n4. **Prueba de espuma en el dorso de la mano**: Desmolde y corte la barra en pastillas del tamaño de medio puño. Humedézcala y frótela en el dorso de la mano: si genera una **espuma blanca y cremosa sin provocar picor ni ardor**, el jabón es seguro para su uso.\",\n      \"actionNote\": \"> Control de reactividad dérmica: Si nota escozor, picor o enrojecimiento, la lejía aún no se ha neutralizado del todo. Enjuáguese con abundante agua y deje curar las pastillas de jabón a la sombra durante 3 o 4 días adicionales; la absorción paulatina de dióxido de carbono atmosférico completará la neutralización alcalina.\",\n      \"svgFileName\": \"pr13-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // MOLDEADO EN CORTEZA & PRUEBA DE ESPUMA\",\n        \"MOLDE RECTANGULAR DE CORTEZA DE ABEDUL & VERTIDO\",\n        \"CURADO NATURAL DE 48 HORAS EN SOMBRA VENTILADA\",\n        \"ESPUMA CREMOSA ABUNDANTE SIN IRRITACIÓN DÉRMICA\",\n        \"[PASO CLAVE 4] CURADO COMPLETO & PRUEBA DE BIOSEGURIDAD\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"ANTIMICROBIAL SCIENCE\",\n        \"title\": \"Disolución de Bicapas Lipídicas y Ruptura de Membranas Bacterianas\",\n        \"text\": \"Las moléculas de jabón poseen una cola hidrocarbonada lipofílica (afín a las grasas) y una cabeza hidrofílica (afín al agua). Al entrar en contacto con bacterias o virus patógenos presentes en las heridas o manos, las colas lipofílicas se insertan en la bicapa lipídica que forma la membrana externa del microorganismo, rompiéndola como cuñas y disolviendo su envoltura, para luego arrastrar los restos en microgotas suspendidas durante el enjuague.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Error Fatal: Manipular lejía cáustica con las manos desnudas o aplicar jabón inmaduro sobre heridas abiertas profundas\",\n    \"description\": \"La lejía lixiviada de ceniza de roble es un álcali fuerte que digiere las proteínas dérmicas; tocarla sin protección produce quemaduras químicas graves y puede causar ceguera permanente si salpica los ojos. Asimismo, frotar jabón crudo sin curar en heridas profundas provoca necrosis tisular por exceso cáustico. En caso de contacto accidental, lave la piel con abundante agua fría durante al menos 5 minutos, y use únicamente jabón que haya completado 48 horas de curado y superado la prueba de espuma para desinfectar vajilla y el contorno de laceraciones.\",\n    \"consequence\": \"Consecuencia: Quemaduras químicas graves, pérdida irreversible de visión por daño corneal y necrosis celular por contacto cáustico\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"¡En plena catástrofe sin médicos ni antibióticos, una simple herida infectada te causará sepsis mortal en 3 días! ¡Aprende a fabricar jabón antiséptico con ceniza de roble!\",\n    \"body\": \"Recoge ceniza blanca pura de roble en una lata perforada y vierte agua caliente para extraer lejía dorada. Comprueba la concentración con una patata cruda: si flota asomando una corona, ¡es la densidad exacta! Mézclala 1 a 1 con grasa animal clarificada y bátela al fuego en una sola dirección durante 40 minutos. Cuando la espátula deje un rastro espeso que dure 3 segundos, añade resina de pino molida y viértela en un molde de corteza durante dos días. ¡Al frotar brotará una espuma blanca que fulmina cualquier bacteria patógena!\",\n    \"outro\": \"Descarga los diagramas tácticos vectoriales para consultarlos sin internet en el enlace del perfil.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr13-outcome.svg\",\n    \"title\": \"Especificaciones Técnicas del Proceso de Fabricación y Reacción de Saponificación de Jabón de Lejía de Roble\",\n    \"description\": \"Sección química y táctica que ilustra la columna de lixiviación de ceniza de roble, la medición hidrométrica por flotación de patata, el proceso de cocción y saponificación 1:1 en caldero, y las pastillas cuadradas de jabón desinfectante curadas en moldes de corteza natural.\",\n    \"svgLabels\": [\n      \"FIG. 13-M // RESUMEN DE PRODUCCIÓN DE JABÓN DE LEJÍA Y ROBLE\",\n      \"IZQ: LIXIVIACIÓN DE CENIZA & PRUEBA DE FLOTABILIDAD DE PATATA\",\n      \"CENTRO: REACCIÓN DE SAPONIFICACIÓN 1:1 & AGITACIÓN CON RESINA\",\n      \"DER: BLOQUES DE JABÓN DESINFECTANTE CURADOS EN CORTEZA\",\n      \"[PR-13 FINAL] JABÓN ANTISÉPTICO DESTRUCTIVO DE MEMBRANAS BACTERIANAS\"\n    ]\n  },\n  \"createdAt\": \"2026-10-21T05:30:00.000Z\",\n  \"contentHash\": \"84750b222b4c5546\",\n  \"updatedAt\": \"2026-10-21T05:32:17.564Z\"\n}","content/protocols/locales/13-wood-ash-lye-soap.ja.json":"{\n  \"protocolId\": \"PR-13\",\n  \"category\": \"MEDICINE\",\n  \"title\": \"木灰の灰汁と動物油脂を煮詰めて傷口感染を防ぐ天然殺菌石鹸の作り方 (野外衛生・防疫)\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[野外衛生・傷口消毒 & 細菌性敗血症遮断]\",\n  \"summary\": \"上下水道や医療機関が途絶した被災地や野外環境では、小さなすり傷や汚れた手で食事をするだけで破傷風や赤痢、敗血症を発症し命を落とします。焚き火や[空き缶ウッドガスストーブ](/protocol-12.html)から出る白いナラ灰を缶ろ過器に集めて熱湯を注ぐと、炭酸カリウムが溶け出したぬめりのある灰汁(アルカリ液)が抽出されます。これに動物の脂身オイルや廃食用油を1:1で混ぜ、弱火でとろみがつくまで木べらで混ぜながら煮詰めることで、病原菌の細胞膜を破壊する強力な天然殺菌石鹸が完成します。\",\n  \"timeRequired\": \"70分 (灰ろ過 20分 + 鹸化煮沸 45分 + 冷却 5分)\",\n  \"successRate\": \"95% (生ジャガイモ浮力テストによる濃度判定と一方向攪拌の順守時)\",\n  \"difficulty\": \"普通 (強アルカリ灰汁による皮膚化学熱傷および目への飛散に厳重注意)\",\n  \"outputPerHour\": \"灰1バケツと油2カップで石鹸3〜4個(約1か月分の野外殺菌石鹸)を製造\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"完全に白く燃え尽きたナラの木灰 1バケツ\",\n      \"desc\": \"[木炭窯](/protocol-09.html)やカマドから黒い炭のかけらを取り除き、ふるいにかけて集めた小麦粉のように細かく白い灰です。カリウム分が最も豊富な広葉樹の白灰を使うことで濃い灰汁が得られます。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"底に穴を開けたスチール缶ろ過器とススキ・小石フィルター\",\n      \"desc\": \"[自然ろ過器](/protocol-01.html)の原理を応用したろ過缶です。有害コーティングをあらかじめ焼き払った大型缶の底に水抜き穴を開け、小石と乾燥したススキを敷いて灰の流出を防ぎます。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"灰汁の濃度測定用 生ジャガイモの小片 (または生卵)\",\n      \"desc\": \"アルカリ濃度を目視で確認する浮力試験体です。抽出した灰汁に浮かべた際、沈まずに水面から親指の爪ほどの頭を出せば石鹸作りに最適な比重(1.08 g/cm³)です。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"精製した動物の脂身油(牛脂・豚脂)または廃食用油 2カップ\",\n      \"desc\": \"獲物の脂身を弱火で煮溶かして肉かすを濾した油脂、または廃墟で回収した植物性食用油です。不純物を完全に取り除くことで腐敗を防ぎ固形化させます。\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"抗菌力強化用の松脂粉末 大さじ1と塩 小さじ1\",\n      \"desc\": \"[松脂軟膏](/protocol-10.html)に用いる透明な松脂の塊をすりつぶした粉末です。フィトンチッド成分で殺菌消毒効果を高め、塩分が石鹸の離型と硬化を助けます。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"手順 1: 白いナラ灰を缶ろ過器に詰め、熱湯を注いで黄金色の灰汁を抽出する\",\n      \"description\": \"1. **白灰の選別と異物除去**: 黒い炭のかけらを取り除き、小麦粉のように白く細かい**ナラの完全燃焼灰1バケツ**を集めます。\\n2. **下部ススキ・小石フィルターの設置**: 有害コーティングを焼き払った大型缶の底に釘で小さな穴を開け、底に親指大の小石と乾燥したススキを**指2本分の厚み(約3cm)**で敷き詰めます。\\n3. **木灰の充填と温水浸出**: フィルターの上に白灰を缶の**手のひら1つ分の高さ(80%)**までしっかり押し固め、[一度沸騰させて冷ましたお湯](/protocol-01.html)をゆっくり注ぎます。\\n4. **黄金色の灰汁の回収**: 底の穴から一滴ずつ落ちてくる琥珀色の滑らかな灰汁(炭酸カリウム水溶液)を受け皿に集めます。\",\n      \"actionNote\": \"> 強アルカリ熱傷注意: 抽出された灰汁はタンパク質を溶かす強アルカリ性のため、素手で触れると皮膚が剥離します。必ず木のヘラを使用し、付着した際は直ちに冷水で5分以上洗い流してください。下記の図鑑で白灰と松脂の特徴を確認してください。\",\n      \"svgFileName\": \"pr13-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // WOOD ASH LYE EXTRACTION LEACHER\",\n        \"ナラ白灰ベッド (上部80%充填)\",\n        \"底部ススキ繊維層 &amp; 小石フィルター\",\n        \"浸出抽出される琥珀色のアルカリ灰汁\",\n        \"[手順1の核心] 炭片の除去と温水浸出ろ過\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD CHEMISTRY\",\n        \"title\": \"炭酸カリウム(K2CO3)水溶液の浸出と高純度アルカリ抽出条件\",\n        \"text\": \"硬質広葉樹であるナラを完全燃焼させると、木質中のカリウムが炭酸カリウム(K2CO3)へと変化します。70〜80℃の温水を通すことで冷水の2倍以上の溶解度で濃い灰汁が抽出されます。黒い未燃焼炭が混ざるとタンニンが溶け出し石鹸が軟化するため、純白の灰のみを選別することが不可欠です。\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"ナラの完全燃焼白灰\",\n            \"scientificName\": \"Quercus Acutissima White Wood Ash\",\n            \"categoryTag\": \"野外化学原料 / 炭酸カリウム供給源\",\n            \"imageFileName\": \"id-oak-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-13A // MACRO OPTIC\",\n            \"hudStatus\": \"POTASSIUM CONTENT HIGH: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"色彩/COLOR\",\n                \"value\": \"黒い炭片がなく、小麦粉のように**真っ白または明るい銀灰色**をしています。\"\n              },\n              {\n                \"label\": \"触感/TEXTURE\",\n                \"value\": \"指ですりつぶすとザラつきがなく、**滑らかな微細粉末**として崩れます。\"\n              },\n              {\n                \"label\": \"抽出液/LYE\",\n                \"value\": \"水を通すと赤みを帯びた**透明感のある黄金の琥珀色液体**として滴ります。\"\n              }\n            ],\n            \"fieldUse\": \"殺菌石鹸の原料灰汁、酸性土壌の中和、穀物の脱殻処理\"\n          },\n          {\n            \"name\": \"天然の松脂結晶\",\n            \"scientificName\": \"Pinus Densiflora Natural Oleoresin\",\n            \"categoryTag\": \"野外防腐剤 / 天然フィトンチッド抗菌材\",\n            \"imageFileName\": \"id-pine-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-13B // MACRO OPTIC\",\n            \"hudStatus\": \"TERPENE PURITY: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"外観/RESIN\",\n                \"value\": \"マツの樹皮の傷から浸出して固まった**半透明の琥珀色または淡黄色の結晶**です。\"\n              },\n              {\n                \"label\": \"芳香/AROMA\",\n                \"value\": \"指先で砕くと鼻を突く**爽快な松の香り(テルペン)**が強く漂います。\"\n              },\n              {\n                \"label\": \"抗菌/EFFECT\",\n                \"value\": \"石鹸に混ぜると泡持ちが向上し、**皮膚上の細菌増殖を強力に抑制**します。\"\n              }\n            ],\n            \"fieldUse\": \"殺菌石鹸の添加剤、傷口用防水軟膏、接着剤の強化剤\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"手順 2: 生ジャガイモの浮力で灰汁の濃度を調整し、動物油脂または廃油を精製する\",\n      \"description\": \"1. **生ジャガイモによる浮力判定**: 抽出した灰汁の器に**親指の爪大(直径2cm)の生ジャガイモ片(または新鮮な生卵)**を静かに浮かべます。\\n2. **浮上高さの点検**: ジャガイモが底に沈む場合は濃度が薄いため、鍋に移して**液量が半分になるまで弱火で煮詰めて濃縮**します。ジャガイモの頭が水面から**親指の爪ほど浮き上がれば**最適な黄金濃度です。\\n3. **脂身の加熱精製**: 獲物の脂身を細かく刻んで鍋に入れ、[ウッドガスストーブ](/protocol-12.html)の弱火でじっくり熱して透明な液状油脂を抽出します。\\n4. **不純物のろ過**: 溶け出た油を布や繊維フィルターで濾し、焦げた肉片や水分を取り除いて**透明な精製油2カップ**を確保します。\",\n      \"actionNote\": \"> 浮力基準の順守: ジャガイモが半分以上突き出るほど浮き上がる場合はアルカリが強すぎるため、完成後の石鹸で肌が荒れます。冷まし湯を半カップ加えて希釈し、水面にわずかに頭を出す状態に調整してください。\",\n      \"svgFileName\": \"pr13-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // POTATO BUOYANCY SPECIFIC GRAVITY TEST\",\n        \"水面に親指の爪大ほど浮遊する生ジャガイモ\",\n        \"比重不足時は煮詰め濃縮 &amp; 過剰時は希釈\",\n        \"動物脂身の加熱抽出および精製油2カップ確保\",\n        \"[手順2の核心] 浮力による濃度確認と油脂精製\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"SPECIFIC GRAVITY\",\n        \"title\": \"比重計のない野外比重測定(1.05〜1.10)とアルキメデスの原理\",\n        \"text\": \"適切な濃度の灰汁は約1.08 g/cm³の比重に達します。生ジャガイモの平均密度は1.06〜1.09 g/cm³であるため、十分なアルカリ濃度がある場合のみ浮上します。比重が1.05未満では鹸化反応が始まらず、油と水が分離して失敗します。\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"手順 3: 灰汁と油を1:1で混ぜ、とろみがつくまで木べらで一方向に混ぜながら煮る\",\n      \"description\": \"1. **1:1比率の投入**: スチール鍋に精製した油2カップと濃度調整した灰汁2カップを**等量(1:1)の比率**で注ぎます。\\n2. **穏やかな弱火加熱**: 強火を避け、炭火の穏やかな余熱の上で液体の縁に**小さな気泡が立つ程度の弱火**を保ちます。\\n3. **一方向への連続攪拌**: 平らな木べらを使い、**一方向にのみ40〜50分間**休まずゆっくり円を描くように混ぜ続けます。途中で回転方向を変えると油と水が分離します。\\n4. **トレース判定と松脂投入**: ヘラを持ち上げた際、落ちた液体の筋が**水面に3秒間そのまま残るピーナッツバター状(トレース)**になったら、砕いた[松脂粉末大さじ1](/protocol-10.html)と塩小さじ1を加えてよく混ぜ、火から下ろします。\",\n      \"actionNote\": \"> 3秒トレースのサイン: ヘラから落ちた生地が液面に溶け込まず立体的なリボンの筋を残す状態が鹸化完了の合図です。松脂を加えることで天然の清涼な香りがつき、泡立ちが長持ちします。\",\n      \"svgFileName\": \"pr13-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // SAPONIFICATION REACTION &amp; STIRRING\",\n        \"灰汁と精製油の1:1等量混合液\",\n        \"平らな木べらによる一方向45分間連続攪拌\",\n        \"筋が3秒間残る濃厚なトレースの完成\",\n        \"[手順3の核心] 弱火加熱と松脂粉末の混和\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"SAPONIFICATION\",\n        \"title\": \"トリグリセリドの加水分解とグリセリン生成の化学\",\n        \"text\": \"油脂のエステル結合が強アルカリの炭酸カリウムと接触すると、脂肪酸分子がカリウムイオンと結合して『脂肪酸カリウム塩(天然石鹸)』を形成し、保湿成分であるグリセリンが遊離します。一方向の連続攪拌は混ざり合わない液体同士の接触界面を最大化する必須工程です。\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"手順 4: 樹皮の型に流し込んで日陰で固め、手の甲の泡立てテストで安全性を確認する\",\n      \"description\": \"1. **樹皮の木枠の準備**: 内側が滑らかなシラカバやマツの樹皮を折りたたみ、小枝で留めて**手のひら大の長方形の箱型枠**を作ります。\\n2. **石鹸液の充填と気泡抜き**: とろみのある石鹸液を枠に流し込み、底を地面に軽くトントンと叩いて内部の気泡を抜きます。\\n3. **48時間の日陰乾燥**: 直射日光を避け、風通しの良い日陰の岩陰に置いて**丸2日間(48時間)**しっかり硬化させます。\\n4. **手の甲での安全性テスト**: 固まった石鹸をナイフで手のひら半分大に切り分け、水をつけて手の甲で泡立てます。ヒリヒリした刺激がなく、**きめ細かく白い泡**が豊かに立てば完成です。\",\n      \"actionNote\": \"> 皮膚刺激の点検: 手の甲に塗った際に赤みや刺すような痛みが生じる場合は、未反応の灰汁が残っています。直ちに洗い流し、さらに3〜5日間日陰で乾燥熟成させてください。空気中の炭酸ガスを自然吸収して肌に優しいマイルドな石鹸へと変化します。\",\n      \"svgFileName\": \"pr13-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // MOLD CASTING &amp; FOAM SAFETY TEST\",\n        \"シラカバ樹皮の四角い型枠への成形充填\",\n        \"48時間の風通しの良い日陰での自然硬化\",\n        \"手の甲での刺激のない豊かな微細泡テスト\",\n        \"[手順4の核心] 完全乾燥熟成と皮膚安全性の合格\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"ANTIMICROBIAL SCIENCE\",\n        \"title\": \"脂質二重層の溶解と病原菌細胞膜の破壊原理\",\n        \"text\": \"石鹸分子は親油性の炭化水素の尾部と親水性の頭部で構成されています。傷口周辺の細菌に接触すると親油性の尾部が病原菌の細胞膜(脂質二重層)に楔のように突き刺さって外皮を破壊し、水で洗い流す際に泡の中に閉じ込めて完全に除去します。\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命的過失: 強アルカリの生灰汁を素手で扱う行為や未熟成の石鹸を傷口に直接塗り込む行為\",\n    \"description\": \"木灰から抽出したばかりの灰汁はタンパク質を激しく腐食させる強アルカリ性です。素手で触れると皮膚がただれ、目に入ると失明します。また鹸化反応と熟成が不十分な生石鹸を直接傷口に塗ると組織が壊死します。付着した際は直ちに清潔な流水で5分以上洗い流し、48時間以上乾燥熟成させて泡立てテストに合格したマイルドな石鹸のみを使用してください。\",\n    \"consequence\": \"結果: 皮膚の重度化学熱傷、失明および未熟成灰汁による組織壊死の危険\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"病院も薬もない被災地では、傷口に泥水がつくだけで3日で敗血症になり命を落とします！木灰から作る天然殺菌石鹸の作り方！\",\n    \"body\": \"白く燃え尽きたナラ灰を缶に詰め、熱湯を注いで灰汁を抽出します。生のジャガイモを浮かべ、親指の爪大ほど浮き上がれば完璧な濃度です！ここに精製した動物の油を1:1で混ぜ、ウッドガスストーブの弱火で40分間木べらで混ぜ続けます。ヘラの跡が3秒間残るピーナッツバター状になったら樹皮の型に流し込んで日陰で2日間固めるだけ！白いきめ細やかな泡が立つ瞬間、細菌を撃退する特級の殺菌石鹸が完成します！\",\n    \"outro\": \"通信が途絶しても閲覧できるオフライン設計図はプロフィールのリンクからご確認ください。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr13-outcome.svg\",\n    \"title\": \"完成した木灰天然殺菌石鹸の製造工程および鹸化化学断面図\",\n    \"description\": \"ナラ白灰のろ過カラムから抽出される黄金の灰汁、生ジャガイモによる浮力比重測定、鍋での1:1鹸化加熱攪拌工程、および樹皮型枠で固化成形された固形殺菌石鹸ブロックの総合化学構造です。\",\n    \"svgLabels\": [\n      \"FIG. 13-M // NATURAL WOOD ASH LYE SOAP PRODUCTION OVERVIEW\",\n      \"左側: ナラ白灰のろ過および生ジャガイモ浮力比重測定\",\n      \"中央: 弱火加熱1:1鹸化反応 &amp; 松脂添加攪拌\",\n      \"右側: 樹皮型枠での固化成形角型殺菌石鹸ブロック\",\n      \"[PR-13 最終完成] 病原菌の細胞膜を破壊する野外消毒石鹸\"\n    ]\n  },\n  \"createdAt\": \"2026-10-21T05:30:00.000Z\",\n  \"contentHash\": \"84750b222b4c5546\",\n  \"updatedAt\": \"2026-10-21T05:32:17.564Z\"\n}","content/protocols/locales/13-wood-ash-lye-soap.pt.json":"{\n  \"protocolId\": \"PR-13\",\n  \"category\": \"MEDICINE\",\n  \"title\": \"Fabricação de Sabão Desinfetante Natural com Lixívia de Cinza de Carvalho e Gordura para Prevenir Infecções\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[HIGIENE DE CAMPO & DESINFECÇÃO DE FERIDAS & PREVENÇÃO DE SEPSE]\",\n  \"summary\": \"Em cenários de sobrevivência no mato ou colapso civilizatório sem saneamento nem antibióticos, uma simples escoriação ou comer com as mãos sujas pode desencadear disenteria bacteriana, tétano ou sepse fatal em poucos dias. Coletando cinzas brancas puras de carvalho de uma fogueira ou do [fogareiro a lenha de gaseificação em lata dupla](/protocol-12.html), compactando-as em uma lata perfurada com leito de cascalho e capim-seco e vertendo água quente, extrai-se uma lixívia alcalina rica em carbonato de potássio. Fervendo suavemente essa lixívia na proporção de 1:1 com sebo animal purificado ou óleo vegetal reaproveitado sob agitação constante com espátula de madeira, inicia-se a saponificação, gerando um sabão bactericida de alta potência que rompe as membranas dos patógenos.\",\n  \"timeRequired\": \"70 minutos (20 min lixiviação de cinzas + 45 min fervura de saponificação + 5 min moldagem)\",\n  \"successRate\": \"95% (ao verificar a densidade com flutuação de batata e manter a mistura unidirecional)\",\n  \"difficulty\": \"Média (extremo cuidado contra queimaduras químicas cáusticas por contato de lixívia com pele e olhos)\",\n  \"outputPerHour\": \"1 balde de cinzas de carvalho e 2 xícaras de gordura rendem 3 a 4 barras de sabão sólido (suprimento mensal)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Um balde de cinzas brancas puras de carvalho completamente calcinadas\",\n      \"desc\": \"Cinza fina e aveludada como farinha, recolhida de um [forno de carvão de carvalho](/protocol-09.html) ou fogueira, peneirada e livre de pedaços de carvão preto. O carvalho e as madeiras de lei concentram a maior carga de potássio para produzir lixívia forte.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Lata metálica perfurada com leito filtrante de cascalho e capim-seco\",\n      \"desc\": \"Inspirada no princípio do [filtro de água natural](/protocol-01.html). Uma lata de conserva grande com perfurações no fundo, forrada com seixos rolados e capim-seco compactado para impedir a passagem das cinzas enquanto drena a lixívia límpida. Queimar tintas e vernizes antes do uso.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Pedaço de batata crua (ou ovo fresco) para teste de flutuabilidade\",\n      \"desc\": \"Medidor hidrométrico visual de campo sem aparelhos eletrônicos. Ao ser colocado na lixívia, deve boiar com uma coroa do tamanho de uma unha acima da superfície, atestando a densidade ideal (1,08 g/cm³) para reagir com o óleo.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"2 xícaras de gordura animal clarificada (sebo bovino/suíno) ou óleo vegetal recuperado\",\n      \"desc\": \"Aparas de gordura de caça derretidas em fogo brando e coadas para remoção de torresmos e umidade, ou óleo comestível resgatado em áreas urbanas abandonadas. A ausência de impurezas evita que o sabão fique rançoso ou amolecido.\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"1 colher de sopa de resina de pinheiro em pó e 1 colher de chá de sal de cozinha\",\n      \"desc\": \"Cristais de resina de pinheiro semelhantes aos da [pomada desinfetante de pinho](/protocol-10.html), pulverizados finamente para agregar fitoncidas antibacterianos, e uma pitada de sal para acelerar o endurecimento das barras no desmolde.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Passo 1: Compactar cinzas brancas de carvalho na lata filtrante e extrair a lixívia alcalina dourada com água quente\",\n      \"description\": \"1. **Triagem de cinzas brancas puras**: Remova pedaços de carvão preto e recolha um balde de **cinzas de carvalho esbranquiçadas e finas**, descartando lascas grossas de casca ou terra.\\n2. **Estratificação do filtro de seixos e capim**: Em uma lata metálica grande perfurada no fundo com prego, coloque seixos limpos da grossura de um polegar e prense por cima capim-seco na espessura de **dois nós de dedo (cerca de 3 cm)**.\\n3. **Carga de cinza e infusão com água fervente**: Pressione a cinza branca com força até **um palmo abaixo da borda (80% da capacidade)** e despeje vagarosamente [água previamente fervida e quente](/protocol-01.html) até embeber todo o leito.\\n4. **Coleta da lixívia âmbar**: Posicione um recipiente limpo por baixo para aparar gota a gota a lixívia untuosa, espessa e de tom âmbar dourado (solução de carbonato de potássio).\",\n      \"actionNote\": \"> Perigo cáustico: A lixívia de cinza de carvalho é uma base alcalina forte capaz de digerir tecidos orgânicos e queimar a pele. Mexa apenas com espátulas de madeira e lave com água corrente fria por 5 minutos caso espirrem gotas. Confira as espécies botânicas no guia abaixo.\",\n      \"svgFileName\": \"pr13-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // COLUNA DE EXTRAÇÃO DE LIXÍVIA DE CINZAS\",\n        \"LEITO DE CINZA BRANCA DE CARVALHO (80% SUPERIOR)\",\n        \"CAMADA DE FIBRA DE CAPIM & TAMPÃO DE CASCALHO\",\n        \"LIXÍVIA ALCALINA ÂMBAR DOURADA EXTRAÍDA\",\n        \"[PASSO CHAVE 1] PENEIRAMENTO DE CINZA & LIXIVIAÇÃO TÉRMICA\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD CHEMISTRY\",\n        \"title\": \"Lixiviação de Carbonato de Potássio (K2CO3) e Rendimento Alcalino\",\n        \"text\": \"A combustão completa de madeiras densas como o carvalho converte o potássio vegetal em carbonato de potássio (K2CO3). O uso de água aquecida a 70–80°C duplica a velocidade e solubilidade da extração em relação à água fria. Pedaços de carvão preto devem ser descartados com rigor, pois os taninos solúveis enfraquecem a estrutura do sabão e provocam escurecimento excessivo.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"Cinza de Madeira de Carvalho Totalmente Calcinada\",\n            \"scientificName\": \"Quercus Acutissima White Wood Ash\",\n            \"categoryTag\": \"Reagente Químico de Campo / Fonte de Base Alcalina\",\n            \"imageFileName\": \"id-oak-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-13A // MACRO OPTIC\",\n            \"hudStatus\": \"POTASSIUM CONTENT HIGH: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"COR\",\n                \"value\": \"Aspecto calcário, **branco puro ou cinza prateado claro**, sem partículas pretas.\"\n              },\n              {\n                \"label\": \"TEXTURA\",\n                \"value\": \"Desmancha-se entre os dedos como um **pó aveludado e macio** sem grãos ásperos.\"\n              },\n              {\n                \"label\": \"LIXÍVIA\",\n                \"value\": \"Gera ao contato com água quente um **líquido translúcido âmbar dourado** escorregadio.\"\n              }\n            ],\n            \"fieldUse\": \"Extração de lixívia para sabão, correção de solos ácidos, maceração alcalina de sementes\"\n          },\n          {\n            \"name\": \"Cristais Naturais de Resina de Pinheiro\",\n            \"scientificName\": \"Pinus Densiflora Natural Oleoresin\",\n            \"categoryTag\": \"Conservante de Campo / Fitoncida Antibacteriano Natural\",\n            \"imageFileName\": \"id-pine-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-13B // MACRO OPTIC\",\n            \"hudStatus\": \"TERPENE PURITY: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"APARÊNCIA\",\n                \"value\": \"Grumos secos e lágrimas de resina **translúcida cor de âmbar ou amarelo claro**.\"\n              },\n              {\n                \"label\": \"AROMA\",\n                \"value\": \"Ao moer libera uma **fragrância penetrante e refrescante de pinheiro (terpenos)**.\"\n              },\n              {\n                \"label\": \"AÇÃO\",\n                \"value\": \"Estabiliza a espuma, encorpa a barra e **bloqueia bactérias como estafilococos**.\"\n              }\n            ],\n            \"fieldUse\": \"Aditivo bactericida para sabão, pomada estéril contra infecções, adesivo selante\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Passo 2: Calibrar a densidade da lixívia com batata crua e clarificar o sebo ou óleo usado\",\n      \"description\": \"1. **Teste hidrométrico com batata crua**: Deposite suavemente um **cubo de batata crua do tamanho de uma unha (2 cm)** ou um ovo cru fresco na lixívia coletada.\\n2. **Avaliação da flutuabilidade**: Se a batata afundar, a lixívia está fraca; leve-a ao fogo para **ferver e reduzir pela metade**. Quando a batata boiar expondo **uma coroa da largura de uma unha para fora do líquido**, a concentração é perfeita para saponificar.\\n3. **Fusão e clarificação de gordura animal**: Pique a gordura e o sebo de caça em pedaços miúdos, coloque numa panela sobre a chama suave do [fogareiro a lenha](/protocol-12.html) e derreta lentamente até extrair o óleo límpido.\\n4. **Filtragem e dosagem**: Coe a gordura derretida com pano limpo ou capim para reter resíduos de carne e água, obtendo **exatamente 2 xícaras de óleo clarificado e puro**.\",\n      \"actionNote\": \"> Parâmetro de flutuação: Se a batata boiar mostrando mais de metade do corpo fora do líquido, a lixívia está forte demais e causará irritação na pele. Adicione meia xícara de água pura para diluir, deixando apenas uma pequena ponta na flor da água.\",\n      \"svgFileName\": \"pr13-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // TESTE DE GRAVIDADE ESPECÍFICA COM BATATA\",\n        \"BATATA FLUTUANDO COM COROA DA LARGURA DE UMA UNHA\",\n        \"REDUZIR AO FOGO SE AFUNDAR & DILUIR SE BOIAR EM EXCESSO\",\n        \"SEBO ANIMAL FUNDIDO & 2 XÍCARAS DE ÓLEO CLARIFICADO\",\n        \"[PASSO CHAVE 2] TESTE DE FLUTUAÇÃO & PURIFICAÇÃO DE GORDURA\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"SPECIFIC GRAVITY\",\n        \"title\": \"Hidrodinâmica da Medição de Gravidade Específica de Campo (1,05~1,10)\",\n        \"text\": \"A lixívia ideal atinge uma gravidade específica de cerca de 1,08 g/cm³. Como a densidade de uma batata crua varia entre 1,06 e 1,09 g/cm³, ela só atinge empuxo positivo e flutua pelo princípio de Arquimedes quando há sais de potássio suficientes dissolvidos. Uma densidade menor que 1,05 inviabiliza a reação química, ocasionando a separação do óleo.\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Passo 3: Misturar lixívia e gordura na proporção 1:1 e cozinhar sob agitação contínua até o ponto de traço\",\n      \"description\": \"1. **Proporção na panela**: Numa panela de metal, verta 2 xícaras de óleo animal morno clarificado e 2 xícaras de lixívia ajustada na **proporção volumétrica exata de 1:1**.\\n2. **Fervura mansa sobre brasas**: Evite labaredas fortes; mantenha o recipiente sobre calor moderado de brasas assegurando **um borbulhar sutil apenas nas bordas do caldeirão**.\\n3. **Agitação contínua em sentido único**: Mexa a calda com uma espátula de madeira plana fazendo **círculos sempre para a mesma direção durante 40 a 50 minutos**, sem interrupção. Inverter o sentido de forma brusca pode quebrar a emulsão.\\n4. **Verificação do ponto de traço (Trace) e resina**: Quando a mistura engrossar como mingau ou manteiga de amendoim, e ao levantar a colher o fio formar **um rastro espesso que permaneça visível por 3 segundos**, incorpore **1 colher de resina de pinheiro em pó** e 1 colher de chá de sal, mexa bem e retire do fogo.\",\n      \"actionNote\": \"> Ponto de traço de 3 segundos: O sabão líquido deve deixar fitas em relevo ao escorrer do mexedor. Esse rastro indica a estabilidade da saponificação. O pó de resina de pinho introduz terpenos bactericidas naturais e melhora a firmeza da espuma.\",\n      \"svgFileName\": \"pr13-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // REAÇÃO DE SAPONIFICAÇÃO & BATIMENTO\",\n        \"MISTURA DE LIXÍVIA E GORDURA NA PROPORÇÃO DE 1:1\",\n        \"AGITAÇÃO UNIDIRECIONAL CONTÍNUA POR 45 MINUTOS\",\n        \"TRAÇO ESPESSO: RASTRO VISÍVEL POR 3 SEGUNDOS\",\n        \"[PASSO CHAVE 3] FOGO BRANDO & ADIÇÃO DE RESINA DE PINHO\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"SAPONIFICATION\",\n        \"title\": \"Mecanismo Químico de Hidrólise de Triglicerídeos e Glicerina\",\n        \"text\": \"A base alcalina hidrolisa as ligações éster dos triglicerídeos presentes na gordura, unindo os ácidos graxos ao potássio para sintetizar sais de potássio (sabão natural), liberando glicerina líquida com efeito umectante. A rotação contínua na mesma direção aumenta a área interfacial entre os líquidos imiscíveis, garantindo a colisão de moléculas necessária para a reação completa.\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Passo 4: Verter em fôrmas de casca de árvore, curar à sombra e verificar segurança pelo teste de espuma\",\n      \"description\": \"1. **Montagem da fôrma de casca**: Dobre uma placa flexível e lisa de casca de bétula ou pinheiro formando uma **caixa retangular do tamanho de uma palma da mão**, ou molde uma mureta de argila sobre uma laje de pedra limpa.\\n2. **Despejo e remoção de bolsas de ar**: Verta a massa de sabão morna na fôrma e dê batidinhas leves com a base no chão para assentar e desalojar bolhas internas de ar.\\n3. **Cura natural em sombra arejada por 48 horas**: Deixe a fôrma num abrigo rochoso protegido da chuva e de raios solares diretos por **dois dias inteiros (48 horas)** até endurecer completamente.\\n4. **Teste de espuma nas costas da mão**: Desenforme e corte a barra em blocos do tamanho de meio punho. Molhe e esfregue nas costas da mão: se formar uma **espuma densa, branca e cremosa sem causar coceira ou ardor**, o sabão está pronto e seguro.\",\n      \"actionNote\": \"> Teste de biocompatibilidade: Caso sinta ardência, picadas ou vermelhidão na pele, a lixívia ainda não foi neutralizada por completo. Lave com água abundante e deixe as barras curarem por mais 3 a 4 dias à sombra; a absorção do gás carbônico do ar rebaixará o pH cáustico.\",\n      \"svgFileName\": \"pr13-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // MOLDAGEM EM CASCA & TESTE DE ESPUMA\",\n        \"FÔRMA RETANGULAR DE CASCA DE BÉTULA & DESPEJO\",\n        \"48 HORAS DE CURA NATURAL EM SOMBRA VENTILADA\",\n        \"ESPUMA CREMOSA ABUNDANTE SEM IRRITAÇÃO NA PELE\",\n        \"[PASSO CHAVE 4] CURA COMPLETA & TESTE DE SEGURANÇA\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"ANTIMICROBIAL SCIENCE\",\n        \"title\": \"Dissolução da Bicamada Lipídica e Lise Celular de Bactérias\",\n        \"text\": \"As moléculas de sabão consistem em uma cauda hidrofóbica lipofílica (atraída por gorduras) e uma cabeça polar hidrofílica (solúvel em água). Ao tocar patógenos e micróbios infecciosos em ferimentos ou nas mãos, as caudas penetram na membrana lipídica externa do micro-organismo como cunhas, desmantelando sua integridade celular e permitindo que os fragmentos bacterianos sejam arrastados pela água.\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Erro Fatal: Manusear lixívia cáustica com as mãos desprotegidas ou esfregar sabão verde e não curado em feridas abertas profundas\",\n    \"description\": \"A lixívia concentrada de cinzas de carvalho é uma base alcalina agressiva que dissolve proteínas orgânicas; o contato direto queima as camadas da pele e espirros nos olhos causam cegueira permanente. Além disso, aplicar sabão verde ainda alcalino em cortes profundos gera necrose química celular. Caso haja contato acidental, enxágue com água fria corrente por 5 minutos, e utilize apenas sabão com 48 horas de cura que tenha passado com sucesso no teste de espuma.\",\n    \"consequence\": \"Consequência: Queimaduras químicas graves, cegueira por lesão na córnea e necrose tecidual provocada por excesso alcalino\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Num colapso sem médicos ou remédios, uma ferida suja de terra causa sepse letal em 3 dias! Veja como fazer sabão desinfetante potente com cinzas de carvalho!\",\n    \"body\": \"Peneire cinzas brancas de carvalho numa lata furada e despeje água quente para recolher a lixívia dourada. Coloque uma batata crua: boiou com a pontinha de fora? A densidade está perfeita! Misture 1 por 1 com gordura animal clarificada e mexa sem parar no mesmo sentido por 40 minutos em fogo brando. Quando a colher deixar um rastro que dure 3 segundos, misture resina de pinho e cure em formas de casca por 2 dias. A espuma densa que brota destrói qualquer bactéria perigosa!\",\n    \"outro\": \"Acesse os diagramas táticos vetoriais completos para salvar offline no link da bio.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr13-outcome.svg\",\n    \"title\": \"Especificações Técnicas do Processo Produtivo e Corte Transversal de Saponificação do Sabão de Cinzas de Carvalho\",\n    \"description\": \"Diagrama técnico integrado detalhando a coluna de lixiviação de cinzas de carvalho, a checagem hidrométrica por flutuação de batata, o caldeirão de saponificação 1:1 e as barras sólidas de sabão antisséptico finalizadas e curadas em molde de casca vegetal.\",\n    \"svgLabels\": [\n      \"FIG. 13-M // VISÃO GERAL DA PRODUÇÃO DE SABÃO DE LIXÍVIA E CARVALHO\",\n      \"ESQ: LIXIVIAÇÃO DE CINZAS & TESTE DE FLUTUAÇÃO DE BATATA\",\n      \"CENTRO: REAÇÃO DE SAPONIFICAÇÃO 1:1 & AGITAÇÃO COM RESINA\",\n      \"DIR: BLOCOS DE SABÃO ANTISSÉPTICO CURADOS EM CASCA NATURAL\",\n      \"[PR-13 FINAL] SABÃO DESINFETANTE QUE ROMPE MEMBRANAS BACTERIANAS\"\n    ]\n  },\n  \"createdAt\": \"2026-10-21T05:30:00.000Z\",\n  \"contentHash\": \"84750b222b4c5546\",\n  \"updatedAt\": \"2026-10-21T05:32:17.564Z\"\n}","content/protocols/locales/13-wood-ash-lye-soap.zh-TW.json":"{\n  \"protocolId\": \"PR-13\",\n  \"category\": \"MEDICINE\",\n  \"title\": \"熬煮橡木灰鹼水與油脂製作天然殺菌肥皂以防傷口感染（野戰消毒肥皂）\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[野戰衛生·傷口消毒 & 阻斷細菌性敗血症]\",\n  \"summary\": \"在自來水與醫療體系崩潰的荒野求生或災後環境中，即便僅是微小的擦傷或用污染的手進食，都可能引發致命的痢疾、破傷風與敗血症而喪命。將營火或[雙層罐木氣爐](/protocol-12.html)中完全燃燒後的純白橡木白炭灰裝入鋪有礫石與乾草的鐵罐過濾器，注入沸水沖淋過濾，即可萃取出溶有碳酸鉀的滑溜強鹼水（Lye）。將此鹼水與提煉後的動物油脂或廢食用油以1:1比例混合，在微火上用木鏟朝單一方向持續攪拌熬煮至黏稠成糊，便能產生破壞病原菌細胞膜的強力天然殺菌肥皂。\",\n  \"timeRequired\": \"70分鐘（草木灰淋濾20分鐘 + 皂化熬煮45分鐘 + 入模定型5分鐘）\",\n  \"successRate\": \"95%（遵循生馬鈴薯浮力測試濃度並維持單向連續攪拌）\",\n  \"difficulty\": \"中等（須嚴防強鹼水噴濺皮膚灼傷與傷害眼睛）\",\n  \"outputPerHour\": \"1桶橡木灰與2杯油脂可產出3至4塊硬肥皂（單月野戰消毒配額）\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"一桶完全燒透呈雪白色的闊葉橡木炭灰\",\n      \"desc\": \"從[橡木炭窯](/protocol-09.html)或火塘底部挑出黑色木炭並過篩收集的細緻白灰粉。必須使用富含鉀離子的硬木白灰，才能萃取出高濃度的鹼液。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"底部打孔的鐵罐過濾筒與芒草·礫石過濾層\",\n      \"desc\": \"應用[天然簡易淨水器](/protocol-01.html)的過濾原理製成。在大鐵罐底部用釘子打出濾孔，底層鋪設卵石與乾燥芒草，防止灰粉漏出同時濾出澄清金黃色鹼液。使用前須火燒去除內部塗層。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"用於測定鹼水浮力濃度的生馬鈴薯塊（或新鮮生雞蛋）\",\n      \"desc\": \"無需電子比重計的野外密度檢驗物。放入鹼液中時，若能浮起並使大拇指指甲大小的表皮露出液面，即代表達到最完美的皂化比重（1.08 g/cm³）。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"2杯熬煉澄清的動物板油（牛脂·豬油）或回收植物食用油\",\n      \"desc\": \"將獵物脂肪切碎置於鍋中慢火融化並濾除油渣與水分的澄清油脂，或廢墟中搜集的食用油。雜質去除越徹底，肥皂越堅固且不易酸敗。\"\n    },\n    {\n      \"id\": \"mat-05\",\n      \"name\": \"增強抗菌力的研磨松脂粉1大匙與食鹽1茶匙\",\n      \"desc\": \"採用製作[松脂膏](/protocol-10.html)所得之透明松脂塊研磨成細粉。天然芬多精能大幅提升殺菌力，微量食鹽則有助於肥皂凝固脫模。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"第1步：將雪白橡木灰裝入鐵罐過濾筒，注入熱水沖淋過濾出金黃色強鹼水\",\n      \"description\": \"1. **揀選白灰與除雜**：剔除黑色未燃盡木炭塊，收集一桶質地如麵粉般純白的**橡木完全燃燒灰**，除去粗糙樹皮與碎石。\\n2. **鋪設礫石乾草緩衝濾層**：在底部打孔的大鐵罐底層鋪入大拇指粗細的卵石，其上緊密壓入厚度約**兩指節（約3公分）**的乾燥芒草纖維。\\n3. **裝填草木灰與熱水浸提**：將白灰緊實填壓至鐵罐**一掌高（約八成滿）**，緩慢注入[煮沸的熱水](/protocol-01.html)直至灰層完全濕透。\\n4. **收集金黃色琥珀鹼液**：在底部下方放置清潔容器，逐滴接取流出的滑膩且呈琥珀金黃色的碳酸鉀強鹼溶液。\",\n      \"actionNote\": \"> 強鹼灼傷警告：橡木灰濾出的高濃度鹼水具備溶解蛋白質的強鹼性，徒手接觸將造成化學性灼傷與脫皮。務必使用木鏟操作，若不慎噴濺須立即以冷水沖洗5分鐘。請對照下方生物特徵圖鑑確認樹種。\",\n      \"svgFileName\": \"pr13-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // 橡木草木灰鹼水萃取過濾筒\",\n        \"雪白橡木炭灰層（上方充填80%）\",\n        \"底部乾草纖維層與卵石緩衝濾層\",\n        \"淋濾流出的深琥珀金黃色鹼液\",\n        \"[第1步核心] 篩選純白灰粉 & 熱水浸出過濾\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD CHEMISTRY\",\n        \"title\": \"碳酸鉀（K2CO3）水溶液浸出與高純度鹼度收率條件\",\n        \"text\": \"燃燒質地堅硬的闊葉橡木時，木質纖維中累積的鉀離子轉化為碳酸鉀（K2CO3）鹽類。使用70~80℃熱水沖淋相較於冷水可使溶解度倍增，能迅速提取出高濃度的鹼液。若混入黑色木炭塊，溶解出的單寧成分會導致肥皂質地軟爛且發黑，故必須揀選純白色灰燼。\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"橡木完全燃燒純白木灰\",\n            \"scientificName\": \"Quercus Acutissima White Wood Ash\",\n            \"categoryTag\": \"野戰化學原料 / 碳酸鉀鹼性來源\",\n            \"imageFileName\": \"id-oak-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-13A // MACRO OPTIC\",\n            \"hudStatus\": \"POTASSIUM CONTENT HIGH: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"成色/COLOR\",\n                \"value\": \"毫無黑碳雜質，呈現如麵粉般**純白或明亮銀灰色**粉末。\"\n              },\n              {\n                \"label\": \"觸感/TEXTURE\",\n                \"value\": \"手指搓揉時無粗糙顆粒感，如**細膩粉末**般散開。\"\n              },\n              {\n                \"label\": \"鹼水/LYE\",\n                \"value\": \"熱水沖淋後滲出帶有些微紅光的**透明琥珀金黃色滑膩液體**。\"\n              }\n            ],\n            \"fieldUse\": \"萃取殺菌肥皂用鹼水、中和酸性土壤、穀物鹼水去殼\"\n          },\n          {\n            \"name\": \"天然松樹松脂結晶\",\n            \"scientificName\": \"Pinus Densiflora Natural Oleoresin\",\n            \"categoryTag\": \"野戰防腐劑 / 天然芬多精抗菌劑\",\n            \"imageFileName\": \"id-pine-tree.jpg\",\n            \"hudCode\": \"FIG. BIO-13B // MACRO OPTIC\",\n            \"hudStatus\": \"TERPENE PURITY: VERIFIED\",\n            \"traits\": [\n              {\n                \"label\": \"外觀/RESIN\",\n                \"value\": \"松樹傷口凝結之**半透明琥珀色或黃白色天然硬塊**。\"\n              },\n              {\n                \"label\": \"氣味/AROMA\",\n                \"value\": \"研碎時散發出極為強烈清新的**松林芳香氣味（萜烯成分）**。\"\n              },\n              {\n                \"label\": \"效能/EFFECT\",\n                \"value\": \"加入肥皂能穩固泡沫，並**有效抑制葡萄球菌等病原菌繁殖**。\"\n              }\n            ],\n            \"fieldUse\": \"殺菌肥皂添加劑、傷口防水消毒膏、火塘黏著密封劑\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"第2步：利用生馬鈴薯浮力校準鹼水濃度，並加熱澄清動物油脂或廢油\",\n      \"description\": \"1. **生馬鈴薯浮力判定**：將一塊約**大拇指指甲大小（直徑2公分）的生馬鈴薯塊**或新鮮生雞蛋小心放入濾出的鹼水中。\\n2. **浮出水面高度檢測**：若馬鈴薯沉底，表示濃度過稀，須置於鍋中**以文火加熱濃縮至體積減半**。若馬鈴薯漂浮且頂端露出**約大拇指指甲面積於水面上**，即為皂化最佳濃度。\\n3. **動物脂肪熔融提煉**：將獵物油脂板油切成細丁放入鐵鍋，在[木氣爐](/protocol-12.html)的微火上慢慢熬煮融化，析出清澈液態油脂。\\n4. **濾除雜質渣滓**：以乾淨棉布或草纖維過濾熱油，徹底除去油渣焦屑與水分，備妥**2杯清澈純淨的油脂**。\",\n      \"actionNote\": \"> 浮力基準原則：若馬鈴薯漂浮露出超過一半，表示鹼度過強，製成的肥皂會刺激灼傷皮膚。此時須加入半杯冷開水稀釋，直至僅有微小頂部浮於水面。\",\n      \"svgFileName\": \"pr13-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // 生馬鈴薯比重浮力測試\",\n        \"浮出水面約指甲大小的生馬鈴薯塊\",\n        \"比重過低慢火濃縮 & 浮力過大加水稀釋\",\n        \"動物油脂慢火融化並濾得2杯澄清油\",\n        \"[第2步核心] 馬鈴薯浮力校準 & 油脂純化去渣\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"SPECIFIC GRAVITY\",\n        \"title\": \"無比重計條件下野外密度測量（比重1.05~1.10）之流體力學\",\n        \"text\": \"標準肥皂用鹼水之比重約達1.08 g/cm³。新鮮生馬鈴薯之平均密度落在1.06~1.09 g/cm³之間，僅在鹼液碳酸鉀濃度充足時，才能依據阿基米德浮力原理浮上水面。比重若低於1.05，與油混合時將無法進行完全皂化反應而導致油水分離。\"\n      }\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"第3步：將鹼水與油脂以1:1比例混合，以木鏟朝單一方向持續攪拌熬煮至糊化\",\n      \"description\": \"1. **鐵鍋投料比例**：於金屬鍋中倒入2杯微溫的澄清動物油與2杯校準好的鹼水，維持**1:1的精確體積比**。\\n2. **炭火餘熱溫和加熱**：避開猛烈大火，置於炭火餘熱上加熱，使鍋底與邊緣保持**僅有微小氣泡輕微冒出的微溫狀態**。\\n3. **朝單一方向連續攪拌**：使用扁平木鏟以**順時針或單一方向連續畫圓攪拌40至50分鐘**。切忌隨意變換攪拌方向，否則乳化體系將被破壞而導致分層。\\n4. **黏稠糊化（Trace跡線）判定與松脂添加**：當肥皂液濃稠如花生醬或米糊，用木鏟撈起滴落時**產生的紋路能於表面維持停留3秒鐘**，即刻倒入**1大匙磨碎的松脂粉末**與1茶匙食鹽，徹底攪勻後離火。\",\n      \"actionNote\": \"> 3秒殘留跡線信號：木鏟滴落的液體不再迅速擴散平復，而是留下清晰凸起的條紋痕跡，即代表化學皂化完全成立。松脂粉能賦予長效天然抗菌芬芳並使泡沫更加緊密。\",\n      \"svgFileName\": \"pr13-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // 皂化化學反應與單向攪拌\",\n        \"鹼水與澄清油脂1:1體積混合液\",\n        \"以扁平木鏟朝單一方向攪拌45分鐘\",\n        \"鏟痕清晰停留3秒的黏稠糊化狀態\",\n        \"[第3步核心] 餘火恆溫微沸 & 混入天然松脂粉\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"SAPONIFICATION\",\n        \"title\": \"三酸甘油酯水解與甘油生成化學機制\",\n        \"text\": \"油脂中的酯類化合物在遇到強鹼性碳酸鉀時發生水解，脂肪酸與鉀離子結合形成「脂肪酸鉀鹽（天然皂化成分）」，並釋放出甘油作為副產物。朝單一方向持續攪拌能最大化不互溶液體間的接觸表面積，大幅增加分子碰撞機率以促成完全皂化反應。\"\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"第4步：注入樹皮模具置於陰涼處固化，並以手背起泡測試驗證安全性\",\n      \"description\": \"1. **製作樹皮模具**：將平整的白樺樹皮或松樹皮內層摺疊成**手掌大小的長方形盒狀模具**，或在平坦石板邊緣圍上黏土護堤。\\n2. **澆鑄皂液與排氣泡**：將溫熱濃稠的皂液倒入模具中，輕敲底部以震出內部殘留的氣泡。\\n3. **通風陰涼處靜置48小時**：將模具安置於無陽光直射且通風良好的乾燥岩縫中，**靜置兩天（48小時）**使其冷卻凝固硬化。\\n4. **手背起泡安全測試**：將凝固的肥皂脫模並以刀切成拳頭一半大小的皂塊。沾水在手背輕輕搓揉：若肌膚毫無刺痛感且產生**細緻綿密的純白泡沫**，即代表合格安全。\",\n      \"actionNote\": \"> 皮膚刺激檢驗：若搓揉時手背產生發紅、刺痛感，表示仍有未被中和的游離強鹼。應立即用冷水洗淨，並將肥皂塊繼續置於陰涼通風處陳化熟成3至4天；肥皂吸收空氣中的二氧化碳後鹼性將自然溫和化。\",\n      \"svgFileName\": \"pr13-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // 樹皮模具澆鑄與起泡安全測試\",\n        \"樺樹皮長方盒模具成形與皂液澆注\",\n        \"陰涼通風處自然冷卻硬化48小時\",\n        \"手背摩擦不起紅疹且泡沫細密豐富\",\n        \"[第4步核心] 徹底通風熟成 & 通過人體安全檢測\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"ANTIMICROBIAL SCIENCE\",\n        \"title\": \"脂質雙分子層溶解與病原菌細胞膜破裂機制\",\n        \"text\": \"肥皂分子由親油性烴鏈尾部與親水性極性頭部組成。當接觸傷口周圍或污染雙手的細菌與病毒時，親油性尾端如楔子般強力刺入病原體的脂質雙分子外膜，使微生物細胞壁瓦解破裂而死亡，並在清水沖洗時包裹於微細泡沫中徹底帶走。\"\n      }\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命錯誤：徒手接觸濃縮強鹼水，或將未完全熟成的生肥皂直接塗抹於深層傷口\",\n    \"description\": \"橡木灰濾出的高濃度強鹼水能腐蝕溶解動物蛋白質；徒手接觸會造成皮膚嚴重化學灼傷，噴入眼內則會造成失明。此外，皂化反應尚未完全且未經熟成的生肥皂若塗於開放性深層傷口，游離強鹼會造成肌肉細胞化學壞死。若不慎接觸，務必立即以冷水持續沖洗5分鐘以上，且僅能使用陰乾熟成48小時以上並通過手背起泡測試的肥皂清洗餐具與創口周圍皮膚。\",\n    \"consequence\": \"後果：化學性皮膚灼傷、角膜損傷失明及生肥皂強鹼導致之細胞組織壞死\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"在缺乏醫院與抗生素的末日荒野中，傷口沾上泥水三天內就會因敗血症喪命！教你用木炭灰熬出頂級殺菌肥皂！\",\n    \"body\": \"把燒透的純白橡木灰裝入打孔鐵罐，沖入沸水淋出琥珀色強鹼水。丟入生馬鈴薯檢驗浮力，露出一指甲高度就是最完美的濃度！接著將鹼水與提煉後的油脂1比1混合，在木氣爐微火上用木鏟朝同個方向攪拌40分鐘。當鏟子劃過留下能維持3秒的紋路時，拌入松脂粉倒入樹皮盒中陰乾兩天。搓揉出的綿密白泡能瞬間瓦解所有致命病菌！\",\n    \"outro\": \"離線也能查閱的高清戰術向量圖解，請點擊個人簡介連結免費獲取。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr13-outcome.svg\",\n    \"title\": \"橡木灰天然殺菌肥皂完整製作工藝與皂化化學反應結構圖解\",\n    \"description\": \"全面展示橡木炭灰淋濾筒、生馬鈴薯比重浮力校準、鐵鍋1:1微火皂化攪拌工藝，以及在天然樹皮模具中硬化成型的長方形野戰殺菌肥皂塊之化學剖面。\",\n    \"svgLabels\": [\n      \"FIG. 13-M // 橡木草木灰天然肥皂生產工藝總覽\",\n      \"左側：橡木白灰淋濾筒 & 生馬鈴薯比重測試\",\n      \"中央：1:1微火皂化反應 & 添入松脂單向攪拌\",\n      \"右側：天然樹皮模具硬化方形消毒肥皂塊\",\n      \"[PR-13 最終成品] 破壞病原菌細胞膜野戰消毒肥皂\"\n    ]\n  },\n  \"createdAt\": \"2026-10-21T05:30:00.000Z\",\n  \"contentHash\": \"84750b222b4c5546\",\n  \"updatedAt\": \"2026-10-21T05:32:17.564Z\"\n}","content/protocols/locales/14-bone-needle-sinew-sewing.de.json":"{\n  \"protocolId\": \"PR-14\",\n  \"category\": \"TOOLS\",\n  \"title\": \"Primitive Knochennadel & Sehnenfaden zur Reparatur von Leder und Stiefeln\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[WINTERLICHE WÄRMEVERLUSTABWEHR & ERFRIERUNGS- / HYPOTHERMIESCHUTZ]\",\n  \"summary\": \"In subpolarer Wildnis oder bei zusammengebrochener zivilisatorischer Versorgung führt ein Riss im Winterleder oder an den Stiefelsohlen binnen 2 Stunden zu tödlicher Unterkühlung oder schweren Erfrierungen. Wenn moderne Stahl Nadeln und Kunstfaserfäden fehlen, muss aus [erbeuteten Jagdtieren](/protocol-08.html) wie Hirsch oder Wildschwein ein Nähbesteck improvisiert werden: Das dichte Schienbeinkompakta wird mit einer [Steinaxt](/protocol-04.html) gespalten, auf nassem Quarzit geschliffen und mit einer Feuersteinahle beidseitig durchbohrt. Kombiniert mit faserig geklopften Tiersehnen entsteht hochfester Nähfaden, der beim Trocknen um 3–5% schrumpft, die Nahtlöcher hermetisch verpresst und nach Versiegelung mit [flüssigem Kiefernharz](/protocol-10.html) vollkommen wind- und wasserdicht schützt.\",\n  \"timeRequired\": \"60 Min (30m Knochenschliff + 15m Sehnenspaltung + 15m Ledernaht)\",\n  \"successRate\": \"95% (bei Vorlochen mit Feuersteinahle und Speichelbefeuchtung der Sehnenfäden)\",\n  \"difficulty\": \"Mittel (erfordert sorgfältiges Spalten der Kompakta und beidseitiges Bohren des Nadelöhrs)\",\n  \"outputPerHour\": \"2 polierte Knochennadeln und 10 Sehnenstränge; repariert 1 Paar Winterstiefel oder 1 Lederjacke\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"1–2 Schienbein-Knochensplitter großer Säugetiere (Hirsch, Reh, Wildschwein)\",\n      \"desc\": \"Gewonnen aus [Fallenjagd](/protocol-08.html) oder Resten der Talgverarbeitung für [Holzaschen-Seife](/protocol-13.html). Die zylindrische Röhrenknochen-Kompakta (Cortical Bone) besitzt eine Biegezugfestigkeit ähnlich wie Stahlnägel und bricht beim Durchstechen von Leder nicht ab.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Grobe Quarzit-Schleifplatte & scharfe Feuerstein-Bohrahle (Flint Awl)\",\n      \"desc\": \"Ein rauer Quarzit-Schleifstein aus der [Steinwerkzeug-Herstellung](/protocol-04.html) und eine spitz zulaufende Feuersteinahle, um ein 1,8 mm weites Nadelöhr beidseitig auszudrehen.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Luftgetrockneter Tiersehnenstrang (Achillessehne)\",\n      \"desc\": \"Aus Beingelenken gewonnene, im schattigen Wind hornartig getrocknete Sehne von bernsteingelber Farbe. Durch leichtes Hämmern mit Holz spaltet sie sich in hunderte haarfeine, extrem zugfeste Kollagenfasern.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Hartholz-Klopfer & abdichtendes Kiefernpech\",\n      \"desc\": \"Ein handlicher Eichenholzknüppel zum Auffasern der Sehne und Eintreiben der Ahle, sowie [Kiefernharzsalbe](/protocol-10.html) zur dauerhaften Imprägnierung der Nahtfalten.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Schritt 1: Schienbeinkompakta spalten und fingerlangen Nadelrohling auf nassem Quarzit schleifen\",\n      \"description\": \"1. **Kompakta auswählen und spalten**: Das Schienbein eines Hirsches mit einer [Steinaxt oder einem schweren Flusskiesel](/protocol-04.html) längs spalten, um einen Splitter von **Fingerlänge (ca. 7–8 cm) und 3–4 mm Stärke** zu gewinnen.\\n2. **Grobschliff auf nassem Quarzit**: Den Knochensplitter im 45-Grad-Winkel auf der befeuchteten Quarzitplatte reiben, um raue Markreste abzutragen und einen gleichmäßigen zylindrischen Stab zu formen.\\n3. **Nadeldorn zuschleifen**: Ein Ende im 30-Grad-Winkel unter ständiger Drehung schleifen, bis eine **dornenscharfe, penetrierende Spitze** entsteht.\",\n      \"actionNote\": \"> Splittergefahr: Beim Zertrümmern können feine Knochensplitter weggeschleudert werden; wenden Sie das Gesicht beim Schlagen um 45 Grad ab. Den Schleifstein stets feucht halten, um Reibungshitze und Versprödung des Knochens zu verhindern.\",\n      \"svgFileName\": \"pr14-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // BONE SPLINTER BLANK PREPARATION\",\n        \"LÄNGSSPALTE DES HIRSCH-SCHIENBEINKNOCHENS\",\n        \"OBERFLÄCHENSCHLIFF AUF FEUCHTEM QUARZIT\",\n        \"FINGERLANGER (7–8CM) ZYLINDER-ROHLING\",\n        \"[SCHRITT 1 FOKUS] 30° ROTATIONSSCHLIFF ZUR NADELSPITZE\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BIOMECHANICS\",\n        \"title\": \"Hydroxyapatit-Kristallgitter und Scherfestigkeit der Säuger-Kompakta\",\n        \"text\": \"Die dichte Knochenwand tragender Extremitätenknochen besteht aus hochdicht lamelliertem Kompaktknochen ohne Schwammstrukturen. Die Verbindung aus mineralischem Hydroxyapatit und elastischen Kollagenfasern erzeugt eine enorme Torsions- und Bruchfestigkeit, die Knochennadeln geschmeidig und bruchsicher durch zähes Leder gleiten lässt.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"Säugetier-Schienbein Kompakta-Splitter\",\n            \"scientificName\": \"Mammalian Tibia Cortical Bone\",\n            \"categoryTag\": \"Prähistorisches Knochenmaterial / Hochfeste Nadelspäne\",\n            \"imageFileName\": \"id-deer-metatarsal-bone.jpg\",\n            \"hudCode\": \"FIG. BIO-14A // MACRO OPTIC\",\n            \"hudStatus\": \"DENSITY & FLEXURAL STRENGTH: HIGH\",\n            \"traits\": [\n              {\n                \"label\": \"FARBE\",\n                \"value\": \"Elfenbeinweiß bis cremefarben mit dichter, gelblicher Knocheninnenwand.\"\n              },\n              {\n                \"label\": \"DICHTE\",\n                \"value\": \"Porenfreier, glasig-fester Querschnitt völlig ohne schwammige Hohlräume.\"\n              },\n              {\n                \"label\": \"AKUSTIK\",\n                \"value\": \"Erzeugt beim leichten Antippen mit Stein einen hellen, metallischen Klingelton.\"\n              }\n            ],\n            \"fieldUse\": \"3–4 mm dicke Späne zur Formung von Knochennadeln auf Quarzitsteinen\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Schritt 2: Nadelöhr mit der Feuersteinahle beidseitig ausbohren und mit feinem Flusssand polieren\",\n      \"description\": \"1. **Beidseitiges Rotationsbohren**: Die Spitze der Feuersteinahle **einen halben Fingernagel breit (ca. 5 mm) unterhalb des Nadelkopfes** ansetzen und zwischen den Fingern drehen, bis eine konische Vertiefung zur Knochenmitte reicht; dann wenden und von hinten gegenbohren.\\n2. **Kanalräumung und Entgraten**: Sobald das Öhr durchbrochen ist, einen Dorn oder dünnen Zweig durchstecken und rotieren, um schneidende Innenkanten abzuschaben.\\n3. **Feinpolitur**: Die gesamte Nadel mit feinem, feuchtem Flusssand abreiben, bis die Oberfläche **glatt wie Glas poliert** ist und reibungsfrei durch Tierhäute gleitet.\",\n      \"actionNote\": \"> Kopfbruch vermeiden: Einseitiges Bohren sprengt den Knochenkopf durch Spreizdruck. Bohren Sie stets von vorne bis zur Hälfte und schließen Sie das Öhr sanduhrförmig von der Rückseite ab.\",\n      \"svgFileName\": \"pr14-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // DUAL-CONE EYE DRILLING & FINISHING\",\n        \"BEIDSEITIGES DREHBOHREN MIT FEUERSTEINAHLE\",\n        \"5MM VOM NADELKOPF EINGESETZTES NADELÖHR\",\n        \"ENTGRATEN DES ÖHRS MIT DREHENDEM PFLANZENSTRUNK\",\n        \"[SCHRITT 2 FOKUS] FLUSSSAND-POLITUR ZU GLASARTIGEM GLANZ\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Schritt 3: Getrocknete Sehne mit dem Holzknüppel klopfen und hochfeste Kollagenfasern auffasern\",\n      \"description\": \"1. **Getrocknete Sehne auflegen**: Den luftgetrockneten, bernsteinfarbenen Sehnenstrang flach auf einen glatten Flussstein-Amboss betten.\\n2. **Sanftes Einklopfen**: Mit dem runden Ende eines Eichenknüppels leicht und federnd auf die Sehne klopfen, um die Bindung der Faserbündel aufzulösen (harte Schläge zerschneiden die Fasern).\\n3. **Ausfaserung und Speichelpflege**: Die weich geklopften Faserbüschel mit den Fingerspitzen in **Stränge von 3–4 Haaren Stärke** auseinanderzupfen. Die Spitze mit Speichel befeuchten und drehen, damit sie formstabil und geschmeidig durch das Öhr gleitet.\",\n      \"actionNote\": \"> Schlagdosierung: Niemals scharfe Steinkanten oder Klingen zum Klopfen verwenden. Benutzen Sie glattes Hartholz und klopfen Sie behutsam, um die Seide der Sehne sanft aufzuwollst.\",\n      \"svgFileName\": \"pr14-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DRIED ANIMAL SINEW FIBER SEPARATION\",\n        \"PLATZIERUNG DER SEHNE AUF FLUSSSTEIN-AMBOSS\",\n        \"EICHENKNÜPPEL-KLOPFUNG (KOLLAGENSPALTUNG)\",\n        \"AUSFASERN IN 3–4 HAARE STARKE ZUGFÄDEN\",\n        \"[SCHRITT 3 FOKUS] SPEICHELGLÄTTUNG ZUM EINFÄDELN INS ÖHR\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIBER SCIENCE\",\n        \"title\": \"Typ-I-Kollagen-Quervernetzung und selbstblockierende Trockenschrumpfung\",\n        \"text\": \"Die Typ-I-Kollagen-Mikrofibrillen von Tiersehnen erreichen Zugfestigkeiten von 50 bis 100 MPa – viermal mehr als vergleichbare Baumwollfäden. Mit Speichel angefeuchtet bleiben sie weich und führig. Beim Trocknen im verarbeiteten Zustand verringern sie ihr Volumen um 3–5%, klemmen das Einstichloch im Leder radial fest zusammen und fixieren die Naht ohne voluminöse Knoten.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"Luftgetrocknete Säugersehne (Sehnenfaden)\",\n            \"scientificName\": \"Dried Mammalian Tendon (Sinew)\",\n            \"categoryTag\": \"Prähistorische Naturfaser / Hochfester Nähfaden\",\n            \"imageFileName\": \"id-dried-animal-sinew.jpg\",\n            \"hudCode\": \"FIG. BIO-14B // MACRO OPTIC\",\n            \"hudStatus\": \"TENSILE STRENGTH RATING: MAXIMUM\",\n            \"traits\": [\n              {\n                \"label\": \"TEXTUR\",\n                \"value\": \"Hornartig zäher, bernsteingelber Stab mit längslaufender Faserung.\"\n              },\n              {\n                \"label\": \"SPALTUNG\",\n                \"value\": \"Entfaltet sich beim Klopfen zu seidig-weißen, feinsten Einzelfasern.\"\n              },\n              {\n                \"label\": \"SCHRUMPFUNG\",\n                \"value\": \"Feucht geschmeidig; zieht sich beim Trocknen wie Stahldraht zusammen.\"\n              }\n            ],\n            \"fieldUse\": \"In feine Fäden zerfasert zur Besteckung von Knochennadeln und Steinaxt-Bindungen\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Schritt 4: Löcher im 5mm-Abstand vorstechen, im Sattlerstich vernähen und mit Kiefernharz abdichten\",\n      \"description\": \"1. **Lederkanten vorlochen**: Die zerrissenen Lederstücke **um Fingergliedbreite überlappen** und mit Feuersteinahle und Holzknüppel eine gerade Reihe von **Löchern im Abstand von 5 mm** vorlochen.\\n2. **Sattlerstich (Zweiseitiges Kreuznähen)**: Beide Enden des Sehnenfadens mit Knochennadeln bestücken oder eine Nadel abwechselnd von vorn und hinten durch dieselben Löcher kreuzen und jede Schlinge stramm anziehen.\\n3. **Schrumpfung und Pechversiegelung**: Sobald der Sehnenfaden getrocknet und gespannt ist, erwärmte [Kiefernharzsalbe](/protocol-10.html) auf die Nahtlinie streichen, um das Leder **vollkommen sturm- und schneewasserdicht** zu versiegeln.\",\n      \"actionNote\": \"> Vorlochen strikt einhalten: Knochennadeln sind extrem druckfest, brechen jedoch bei seitlicher Scherbelastung in dickem Leder. Stechen Sie Löcher stets mit der Feuersteinahle vor und nutzen Sie die Knochennadel nur als Fadenführer.\",\n      \"svgFileName\": \"pr14-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // SADDLE STITCHING & PITCH SEALING\",\n        \"FEUERSTEINAHLE VORLOCHUNG IM 5MM ABSTAND\",\n        \"DOPPELTER SATTLERSTICH-SEHNENNAHTVERLAUF\",\n        \"KIEFERNHARZ-IMPRÄGNIERUNG DER NAHTFALTE\",\n        \"[SCHRITT 4 FOKUS] SEHNENSCHRUMPFUNG DICHTET NADELÖCHER AB\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Fataler Fehler: Gewaltsames Hineindrücken der Knochennadel in dickes, ungebohrtes Leder durch Druck auf den Nadelkopf\",\n    \"description\": \"Das gewaltsame Durchdrücken einer Knochennadel durch zähes Rohleder ohne Vorlochung erzeugt extreme Biegespannungen, die den Nadelkopf oder Nadelschaft abbrechen. Die messerscharfen Knochenbruchkanten dringen tief in den Handballen oder die Finger ein und verursachen schwere Stichverletzungen sowie tödlichen Wundstarrkrampf (Tetanus). Löcher stets im 5-mm-Abstand mit einer gehärteten Feuersteinahle und Holzknüppel vorstechen; die Knochennadel nur als reibungsfreie Führungsnadel durch existierende Öffnungen leiten.\",\n    \"consequence\": \"Folge: Nadelbruch, tiefe Knochensplinter-Stichverletzungen der Hand & lebensbedrohlicher Wundstarrkrampf\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Minus 20 Grad und der Stiefel reißt auf? In 2 Stunden erfrierst du im Schnee. Baue dir SOFORT eine Knochennadel!\",\n    \"body\": \"Spalte Hirschknochen mit einem Stein, schleife ihn auf feuchtem Quarzit zu einer Nadel und bohre das Öhr mit Feuerstein. Klopfe getrocknete Sehnen mit Holz: Du erhältst Fäden, die 4-mal reißfester als Baumwolle sind! Befeuchte den Faden mit Speichel, loche das Leder mit Feuerstein vor und vernähe es im Sattlerstich. Beim Trocknen zieht sich die Sehne zusammen wie Stahldraht, und Kiefernharz dichtet alles 100% wasserdicht ab!\",\n    \"outro\": \"Erlernen Sie echte Überlebenstechniken für den Ernstfall. Laden Sie alle Baupläne offline herunter!\"\n  },\n  \"outcome\": {\n    \"title\": \"Feldmäßig reparierte Winterstiefel & Knochennadel-Nähbesteck\",\n    \"badge\": \"ABNAHMESTANDARD // FIELD REPAIRED GEAR\",\n    \"standard\": \"Knochennadel glasartig glatt poliert, Öhr nimmt Doppelstrang ohne Reibung auf, und die Sattlernaht hält starkem manuellem Zug ohne 1 mm Spaltbildung stand\",\n    \"svgFileName\": \"pr14-outcome.svg\",\n    \"svgLabels\": [\n      \"PR-14 OUTCOME // BONE NEEDLE & SINEW SEWING KIT\",\n      \"FERTIGE ELFENBEIN-KNOCHENNADEL (LÄNGE 7.5CM)\",\n      \"FEUERSTEIN-BOHRUNG PRÄZISIONS-ÖHR (DURCHMESSER 1.8MM)\",\n      \"MIT HOLZKNÜPPEL AUFGEFASERTE HOCHFESTE SEHNENSTRÄNGE\",\n      \"SATTLERSTICH-DOPPELVERBINDUNG & KIEFERNHARZNAHT\",\n      \"RESTAURIERTER WINTERSTIEFEL (100% WÄRMEERHALT)\",\n      \"FIELD VERIFIED // TENSILE STRENGTH RATED & WATERPROOF\"\n    ]\n  },\n  \"createdAt\": \"2026-10-22T08:09:29.733Z\",\n  \"updatedAt\": \"2026-10-22T08:14:43.819Z\",\n  \"contentHash\": \"614132e570544622\"\n}","content/protocols/locales/14-bone-needle-sinew-sewing.en.json":"{\n  \"protocolId\": \"PR-14\",\n  \"category\": \"TOOLS\",\n  \"title\": \"Primitive Bone Needle & Dried Sinew Sewing Kit for Leather & Footwear Repair\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[WINTER HEAT-LOSS DEFENSE & FROSTBITE / HYPOTHERMIA PREVENTION]\",\n  \"summary\": \"In sub-zero wilderness conditions or post-collapse disaster environments, torn winter leather garments or boot soles lead to catastrophic body heat loss, inducing fatal hypothermia or crippling frostbite within 2 hours. When modern needles and nylon thread are unavailable, you must craft an emergency sewing kit using high-density cortical shin bones from deer or boar split with a [stone axe](/protocol-04.html) and ground on wet quartzite into a sharp bone needle with a dual-drilled eye, paired with natural high-tensile sinew cord harvested from dried leg tendons. As saliva-coated sinew thread dries inside stitched leather, it shrinks 3–5%, mechanically locking needle holes airtight before sealing with [melted pine pitch ointment](/protocol-10.html) to create a stormproof, waterproof barrier.\",\n  \"timeRequired\": \"60 mins (30m bone needle honing + 15m sinew fiber splitting + 15m leather stitching)\",\n  \"successRate\": \"95% (when pre-punching holes with a flint awl and saliva-coating sinew threads)\",\n  \"difficulty\": \"Medium (requires careful flint awl drilling and cortical bone selection)\",\n  \"outputPerHour\": \"2 polished bone needles and 10 sinew threads; fully restores 1 pair of torn leather boots or winter coat\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"1–2 Mammalian Leg Bone Splinters (Deer, Elk, or Boar Metatarsal)\",\n      \"desc\": \"Salvaged from [primitive hunting traps](/protocol-08.html) or tallow rendering for [wood ash lye soap](/protocol-13.html). The dense cortical wall of mammalian leg bones possesses flexural tensile strength rivaling steel nails and resists bending fractures under leather penetration.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Coarse Quartzite Honing Slab & Sharp Flint Drill Awl\",\n      \"desc\": \"A flat coarse quartzite sharpening slab used in [stone tool making](/protocol-04.html), paired with a razor-sharp conical chert or flint awl micro-drill to bore a clean 1.8mm needle eye.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Dried Animal Tendon / Sinew Bundle (Achilles Tendon)\",\n      \"desc\": \"Natural tendon harvested from deer leg joints, wind-dried in the shade into a hard amber cord. Light tapping with a wooden baton frees hundreds of hair-thin, ultra-high-tensile collagen fibers.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Palm-Sized Hardwood Tapping Baton & Waterproof Pine Resin\",\n      \"desc\": \"A blunt oak branch used to crush tendon bundles and drive flint awls, paired with sticky [pine pitch ointment](/protocol-10.html) to waterproof the finished leather seam.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Step 1: Split Shin Bone Splinters & Grind a Finger-Length Needle Blank on Wet Quartzite\",\n      \"description\": \"1. **Select & Split Cortical Bone**: Split a deer leg bone lengthwise using a [stone axe or heavy river hammerstone](/protocol-04.html) to extract a dense splinter **finger-length (7–8cm) and 3–4mm thick**.\\n2. **Grind on Wet Quartzite**: Wet a coarse quartzite slab and rub the bone splinter flat at a 45-degree angle, removing porous marrow residues and shaping it into a uniform cylinder.\\n3. **Form Piercing Awl Tip**: Tilt one end at 30 degrees while rotating continuously against the wet rock until you obtain a **needle-sharp penetrating point**.\",\n      \"actionNote\": \"> Splinter Hazard: Bone fragments can shatter under blunt impact; turn your face 45 degrees away when striking. Always lubricate the quartzite slab with water to prevent frictional heat from scorching and weakening the bone matrix.\",\n      \"svgFileName\": \"pr14-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // BONE SPLINTER BLANK PREPARATION\",\n        \"SPLITTING DEER TIBIA CORTICAL BONE CYLINDER\",\n        \"WET COARSE QUARTZITE SLAB SURFACE HONING\",\n        \"FINGER-LENGTH (7–8CM) & ROUND ROD SHAPING\",\n        \"[KEY STEP 1] 30° ROTATIONAL HONING FOR SHARP TIP\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BIOMECHANICS\",\n        \"title\": \"Mammalian Cortical Bone Hydroxyapatite Matrix & Shear Resilience\",\n        \"text\": \"The weight-bearing cortical wall of ungulate leg bones consists of dense concentric lamellae reinforced with crystalline hydroxyapatite and interwoven collagen fibers. This biological composite structure yields extraordinary compressive strength and flexural resilience, producing needles capable of penetrating thick animal hides without catastrophic snapping.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"Mammalian Cortical Bone Splinter\",\n            \"scientificName\": \"Mammalian Tibia Cortical Bone\",\n            \"categoryTag\": \"Field Osteological Material / High-Strength Needle Blank\",\n            \"imageFileName\": \"id-deer-metatarsal-bone.jpg\",\n            \"hudCode\": \"FIG. BIO-14A // MACRO OPTIC\",\n            \"hudStatus\": \"DENSITY & FLEXURAL STRENGTH: HIGH\",\n            \"traits\": [\n              {\n                \"label\": \"COLOR\",\n                \"value\": \"Ivory-white to pale cream exterior with yellowish dense inner bone core.\"\n              },\n              {\n                \"label\": \"DENSITY\",\n                \"value\": \"Pore-less, glassy smooth cross-section free of spongy cancellous cavities.\"\n              },\n              {\n                \"label\": \"ACOUSTIC\",\n                \"value\": \"Produces a clear, metallic ringing chime when tapped lightly against stone.\"\n              }\n            ],\n            \"fieldUse\": \"Selected 3–4mm splinters shaped into needle blanks on wet quartzite slabs\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Step 2: Bore a Bi-Conical Needle Eye with a Flint Awl & Polish with Fine Sand\",\n      \"description\": \"1. **Dual-Cone Rotational Drilling**: Place the tip of a sharp flint awl **half a fingernail width (about 5mm) from the blunt head**. Twist back and forth between your fingers to drill a conical depression halfway through, then flip and drill from the opposite side.\\n2. **Passage Clearing & Burr Removal**: Once pierced through, thread a slender twig or dried thorn through the eye, spinning it to scrape away internal bone burrs that could fray thread.\\n3. **Fine Polishing**: Buff the entire needle surface with damp clay-stone or fine river sand until it gleams with **glass-like smoothness** to ensure frictionless hide penetration.\",\n      \"actionNote\": \"> Head Fracture Prevention: Drilling entirely from one side exerts excessive outward pressure, splitting the needle head. Always drill halfway from the front, then flip over and meet from the rear in a bi-conical hourglass channel.\",\n      \"svgFileName\": \"pr14-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // DUAL-CONE EYE DRILLING & FINISHING\",\n        \"FLINT AWL DUAL-CONE ROTATIONAL DRILLING\",\n        \"5MM INSET EYE PASSAGE FROM NEEDLE HEAD\",\n        \"THORN ROTATION INTERNAL BURR REMOVAL\",\n        \"[KEY STEP 2] FINE RIVER SAND BUFFING TO GLASS GLOSS\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Step 3: Pound Dried Sinew with a Wooden Baton to Separate High-Tensile Collagen Threads\",\n      \"description\": \"1. **Prepare Dried Tendon**: Lay an amber, sun-dried tendon cord flat across a smooth river stone anvil.\\n2. **Light Baton Tapping**: Lightly tap the tendon with a rounded hardwood baton to fracture the inter-fiber collagen matrix (hard strikes will sever fibers prematurely).\\n3. **Fiber Combing & Saliva Coating**: Pull apart the frayed bundle with your fingertips into **threads 3–4 hairs thick**. Roll the thread tip between saliva-moistened fingertips to condense the fibers into a stiff, sleek point that glides effortlessly through the needle eye.\",\n      \"actionNote\": \"> Strike Modulation: Never use sharp stones or axe edges to pound sinew. Use a smooth wooden baton and tap gently to fluff the fibers apart like silk floss rather than cutting them.\",\n      \"svgFileName\": \"pr14-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DRIED ANIMAL SINEW FIBER SEPARATION\",\n        \"DRIED SINEW PLACEMENT ON FLAT ANVIL STONE\",\n        \"OAK BATON GENTLE TAPPING (COLLAGEN SPLIT)\",\n        \"COMBING 3–4 HAIR THICK HIGH-TENSILE FIBERS\",\n        \"[KEY STEP 3] SALIVA COATING FOR SMOOTH EYE THREADING\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIBER SCIENCE\",\n        \"title\": \"Type I Collagen Molecular Crosslinking & Self-Locking Shrinkage\",\n        \"text\": \"Mammalian tendon fibers consist of parallel arrays of Type I collagen fibrils with tensile strengths between 50 and 100 MPa—exceeding cotton cordage fourfold. When moistened with saliva or water, the fibers soften for friction-free stitching. Upon ambient drying, they shrink 3–5% in volume, exerting radial clamping pressure that self-locks the needle puncture without complex knots.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"Sun-Dried Mammalian Sinew Cord\",\n            \"scientificName\": \"Dried Mammalian Tendon (Sinew)\",\n            \"categoryTag\": \"Primitive Natural Fiber / High-Tensile Sewing Thread\",\n            \"imageFileName\": \"id-dried-animal-sinew.jpg\",\n            \"hudCode\": \"FIG. BIO-14B // MACRO OPTIC\",\n            \"hudStatus\": \"TENSILE STRENGTH RATING: MAXIMUM\",\n            \"traits\": [\n              {\n                \"label\": \"TEXTURE\",\n                \"value\": \"Translucent amber-yellow, horn-like rigid cord with longitudinal grain.\"\n              },\n              {\n                \"label\": \"SEPARATION\",\n                \"value\": \"Fluffs into glistening silver-white, silk-fine filaments when lightly pounded.\"\n              },\n              {\n                \"label\": \"SHRINKAGE\",\n                \"value\": \"Supple when wet; contracts into rock-hard tensile wire upon drying.\"\n              }\n            ],\n            \"fieldUse\": \"Frayed into fine filaments to thread bone needles for garment repair and axe hafting\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Step 4: Pre-Punch 5mm Holes with a Flint Awl, Saddle Stitch & Seal Seams with Pine Pitch\",\n      \"description\": \"1. **Pre-Punch Leather Holes**: Overlap torn leather edges by **one knuckle width**, and use a sharp flint awl and wooden baton to pre-punch a row of **holes spaced 5mm apart**.\\n2. **Execute Saddle Stitching**: Thread bone needles on both ends of a sinew cord, or pass a single needle alternating front-to-back in an interlocking figure-8 saddle stitch, pulling each stitch firmly.\\n3. **Shrinkage & Pine Pitch Seal**: Allow the sinew to dry and contract, then smear warm [pine pitch ointment](/protocol-10.html) over the seam line to form a **100% stormproof, wind-tight leather seal**.\",\n      \"actionNote\": \"> Mandatory Pre-Punching: Bone needles have high compressive strength but will shear if forced through tough rawhide. Always pre-punch holes with a flint awl, using the bone needle solely as a smooth thread guide.\",\n      \"svgFileName\": \"pr14-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // SADDLE STITCHING & PITCH SEALING\",\n        \"FLINT AWL 5MM INTERVAL PRE-PUNCHED HOLES\",\n        \"DUAL-DIRECTION SADDLE STITCH SEWING\",\n        \"PINE PITCH OINTMENT WATERPROOF SEAM SEAL\",\n        \"[KEY STEP 4] SINEW DRY SHRINKAGE AIRTIGHT CLOSURE\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Fatal Mistake: Forcing a bone needle through thick, un-punched leather by pressing hard on the needle head\",\n    \"description\": \"Forcing a bone needle through tough, thick rawhide without pre-punched holes applies severe bending torque that snaps the needle head or shaft. The jagged, razor-sharp bone splinter can penetrate deep into the palm or fingers, causing disabling puncture wounds and life-threatening field tetanus. Always pre-punch 5mm interval holes with a hardened flint awl and wooden baton, using the bone needle solely as a guide to carry sinew threads smoothly through existing apertures.\",\n    \"consequence\": \"Outcome: Needle fracture, deep palmar bone puncture trauma & lethal field tetanus infection\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Sub-zero blizzard and your boot sole splits wide open? You have 2 hours before fatal hypothermia sets in. Craft a primitive bone needle NOW!\",\n    \"body\": \"Split a deer leg bone with a stone axe, grind it on wet quartzite into a finger-length needle, and dual-drill an eye with a flint awl. Next, tap dried animal sinew with a wooden stick—it fluffs into collagen threads 4 times stronger than cotton! Lick the thread, pass it through, pre-punch leather holes with flint, and cross-stitch tightly. As the sinew dries, it contracts like steel wire, and pine resin seals it 100% waterproof!\",\n    \"outro\": \"Master post-collapse primitive technology before disaster strikes. Access all survival blueprints offline!\"\n  },\n  \"outcome\": {\n    \"title\": \"Field-Repaired Winter Leather Boot & Primitive Bone Needle Sewing Kit\",\n    \"badge\": \"INSPECTION CRITERIA // FIELD REPAIRED GEAR\",\n    \"standard\": \"Bone needle surface polished to glass-smooth finish, eye accommodates dual sinew strands cleanly, and saddle-stitched leather seam shows zero gap under heavy manual tension\",\n    \"svgFileName\": \"pr14-outcome.svg\",\n    \"svgLabels\": [\n      \"PR-14 OUTCOME // BONE NEEDLE & SINEW SEWING KIT\",\n      \"COMPLETED CORTICAL BONE NEEDLE (LENGTH 7.5CM)\",\n      \"FLINT AWL DUAL-BORED EYE PASSAGE (DIA 1.8MM)\",\n      \"OAK BATON SEPARATED HIGH-TENSILE SINEW FIBERS\",\n      \"SADDLE STITCH & PINE PITCH WATERPROOF SEAM\",\n      \"RESTORED WINTER BOOT (100% HEAT LOSS BLOCKED)\",\n      \"FIELD VERIFIED // TENSILE STRENGTH RATED & WATERPROOF\"\n    ]\n  },\n  \"createdAt\": \"2026-10-22T08:09:29.733Z\",\n  \"updatedAt\": \"2026-10-22T08:14:43.819Z\",\n  \"contentHash\": \"614132e570544622\"\n}","content/protocols/locales/14-bone-needle-sinew-sewing.es.json":"{\n  \"protocolId\": \"PR-14\",\n  \"category\": \"TOOLS\",\n  \"title\": \"Aguja de Hueso Primitiva y Costura con Tendón Seco para Cuero y Calzado\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[DEFENSA CONTRA PÉRDIDA TÉRMICA Y PREVENCIÓN DE HIPOTERMIA / CONGELACIÓN]\",\n  \"summary\": \"En climas gélidos extremos o tras el colapso de la infraestructura moderna, si las prendas térmicas de cuero o las suelas de las botas se desgarran, el calor corporal escapa rápidamente, provocando hipotermia mortal o congelación de extremidades en menos de 2 horas. Ante la ausencia de agujas de acero e hilo sintético, es indispensable fabricar un juego de costura de emergencia utilizando fragmentos de hueso cortical de ciervo o jabalí hendidos con un [hacha de piedra](/protocol-04.html), afilados sobre cuarcita húmeda y perforados con una lezna de sílex, combinados con cordones de tendón animal secado al aire. Al humedecerse con saliva y coserse, el hilo de tendón se encoge de un 3 a un 5% al secarse, sellando los agujeros por compresión radial antes de impermeabilizarse con [brea caliente de pino](/protocol-10.html).\",\n  \"timeRequired\": \"60 min (30 min pulido de aguja + 15 min desfibrado de tendón + 15 min costura)\",\n  \"successRate\": \"95% (perforando previamente con lezna de sílex e hidratando el tendón con saliva)\",\n  \"difficulty\": \"Media (selección de hueso cortical denso y perforación bicónica cuidadosa)\",\n  \"outputPerHour\": \"2 agujas de hueso y 10 hebras de tendón; restaura 1 par de botas o 1 abrigo de piel\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"1–2 Fragmentos de Hueso Cortical de Pata (Tibia o Metatarso de Ciervo o Jabalí)\",\n      \"desc\": \"Recuperados de [trampas de caza](/protocol-08.html) o del procesamiento de grasa para [jabón de lejía](/protocol-13.html). La densa pared cilíndrica del hueso cortical posee una tenacidad a la flexión similar a la de un clavo de acero y no se quiebra al penetrar cuero.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Laja de Cuarcita Abrasiva y Lezna Perforadora de Sílex\",\n      \"desc\": \"Una laja de cuarcita de grano grueso para [fabricación de herramientas líticas](/protocol-04.html) y una lezna cónica afilada de sílex para perforar el ojo de 1,8 mm en la aguja.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Manojo de Tendón Animal Secado al Viento (Tendón de Aquiles)\",\n      \"desc\": \"Tendón recolectado de articulaciones de ciervo o vacuno, secado a la sombra hasta formar una tira rígida de color ámbar. Al golpearlo suavemente con un mazo de madera, se desfibra en cientos de hebras de colágeno ultrafinas.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Maza Corta de Madera Dura y Resina de Pino Impermeabilizante\",\n      \"desc\": \"Una rama cilíndrica de roble para machacar el tendón y percutir la lezna, junto con [ungüento de resina de pino](/protocol-10.html) para sellar herméticamente las costuras del cuero.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Paso 1: Hender el Hueso Cortical y Desbastar una Espiga de Aguja sobre Cuarcita Húmeda\",\n      \"description\": \"1. **Selección y Hendido Longitudinal**: Henda la tibia de un ciervo longitudinalmente con un [hacha de piedra o canto rodado pesado](/protocol-04.html) para obtener una astilla densa del **largo de un dedo (7–8 cm) y 3–4 mm de grosor**.\\n2. **Desbaste sobre Cuarcita Húmeda**: Moje la laja de cuarcita y frote la astilla ósea con una inclinación de 45 grados, eliminando restos porosos de médula y redondeando la pieza hasta lograr un cilindro parejo.\\n3. **Afilar la Punta de Perforación**: Incline un extremo a 30 grados girándolo continuamente contra la piedra mojada hasta obtener una **punta aguzada capaz de penetrar cuero**.\",\n      \"actionNote\": \"> Peligro de Esquirlas: El impacto puede proyectar astillas afiladas; gire el rostro 45 grados al golpear el hueso. Lubrique siempre la cuarcita con agua para evitar que el calor de fricción queme y debilite la estructura ósea.\",\n      \"svgFileName\": \"pr14-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // BONE SPLINTER BLANK PREPARATION\",\n        \"HENDIDO LONGITUDINAL DE TIBIA CORTICAL\",\n        \"DESBASTE SOBRE LAJA DE CUARCITA HÚMEDA\",\n        \"ESPIGA CILÍNDRICA DEL LARGO DE UN DEDO (7–8CM)\",\n        \"[PASO CLAVE 1] AFILADO ROTACIONAL A 30° DE PUNTA\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BIOMECHANICS\",\n        \"title\": \"Matriz de Hidroxiapatita y Resistencia al Cizallamiento del Hueso Cortical\",\n        \"text\": \"La pared cortical de las patas de grandes ungulados está diseñada para soportar cargas dinámicas masivas, careciendo de poros esponjosos. Su estructura laminar de cristales de hidroxiapatita entrelazados con fibras elásticas de colágeno ofrece una formidable tenacidad a la flexión, permitiendo a la aguja penetrar cuero grueso sin quebrarse.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"Astilla de Hueso Cortical de Ungulado\",\n            \"scientificName\": \"Mammalian Tibia Cortical Bone\",\n            \"categoryTag\": \"Material Osteológico Primitivo / Espiga para Agujas\",\n            \"imageFileName\": \"id-deer-metatarsal-bone.jpg\",\n            \"hudCode\": \"FIG. BIO-14A // MACRO OPTIC\",\n            \"hudStatus\": \"DENSITY & FLEXURAL STRENGTH: HIGH\",\n            \"traits\": [\n              {\n                \"label\": \"COLOR\",\n                \"value\": \"Exterior blanco marfil o crema pálido con núcleo óseo denso y amarillento.\"\n              },\n              {\n                \"label\": \"DENSIDAD\",\n                \"value\": \"Corte transversal liso y vidrioso, totalmente libre de cavidades esponjosas.\"\n              },\n              {\n                \"label\": \"ACÚSTICA\",\n                \"value\": \"Emite un sonido metálico claro y resonante al golpearse suavemente con piedra.\"\n              }\n            ],\n            \"fieldUse\": \"Astillas seleccionadas de 3–4 mm afiladas como agujas sobre lajas de cuarcita\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Paso 2: Perforar el Ojo Bicónico con Lezna de Sílex y Pulir con Arena Fina\",\n      \"description\": \"1. **Perforación Rotatoria Opuesta**: Apoye la punta de la lezna de sílex a **medio ancho de uña (unos 5 mm) del extremo grueso**. Gírela entre los dedos para excavar una cavidad cónica hasta la mitad del grosor, luego invierta la aguja y perfore desde el lado opuesto.\\n2. **Limpieza del Canal y Desbarbado**: Al perforar el ojo, pase una espina vegetal seca o ramita delgada girándola enérgicamente para raspar asperezas internas que pudieran cortar el hilo.\\n3. **Pulido de Alto Brillo**: Frote la aguja con arcilla fina humedecida o arena de río hasta que adquiera una **superficie lisa como el cristal**, asegurando un deslizamiento sin fricción a través del cuero.\",\n      \"actionNote\": \"> Prevención de Fracturas: Perforar desde una sola cara ejerce presión expansiva y quiebra la cabeza del hueso. Aplique siempre el método bicónico perforando hasta la mitad por delante y rematando por detrás.\",\n      \"svgFileName\": \"pr14-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // DUAL-CONE EYE DRILLING & FINISHING\",\n        \"PERFORACIÓN ROTATORIA OPUESTA CON LEZNA DE SÍLEX\",\n        \"OJO PERFORADO A 5MM DEL EXTREMO DE LA AGUJA\",\n        \"DESBARBADO INTERNO DEL OJO CON ESPINA VEGETAL\",\n        \"[PASO CLAVE 2] PULIDO CON ARENA FINA A BRILLO VIDRIO\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Paso 3: Machacar el Tendón Seco con Maza de Madera y Extraer Hebras de Colágeno\",\n      \"description\": \"1. **Colocar el Tendón Seco**: Coloque la tira de tendón ámbar secada al viento sobre una piedra de río lisa a modo de yunque.\\n2. **Percusión Ligera con Madera**: Golpee suavemente con una maza cilíndrica de roble para desintegrar los enlaces entre fibras de colágeno (un impacto violento cortará las hebras).\\n3. **Separación y Humectación con Saliva**: Separe con las yemas de los dedos las hebras esponjadas hasta obtener **filamentos del grosor de 3–4 cabellos**. Humedezca la punta del hilo con saliva y tuérzala para afilarla y facilitar el enhebrado.\",\n      \"actionNote\": \"> Control del Impacto: Jamás utilice piedras filosas ni hachas para machacar el tendón. Emplee una maza roma de madera dura y golpee rítmicamente para desfibrar el material como seda natural sin cortarlo.\",\n      \"svgFileName\": \"pr14-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DRIED ANIMAL SINEW FIBER SEPARATION\",\n        \"TENDÓN SECO SOBRE YUNQUE DE PIEDRA PLANA\",\n        \"GOLPETEO SUAVE CON MAZA DE ROBLE (FIBRA DE COLÁGENO)\",\n        \"SEPARACIÓN DE HEBRAS DEL GROSOR DE 3–4 CABELLOS\",\n        \"[PASO CLAVE 3] HUMECTACIÓN CON SALIVA PARA ENHEBRADO\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIBER SCIENCE\",\n        \"title\": \"Entrecruzamiento Molecular de Colágeno Tipo I y Retracción Autoblocante\",\n        \"text\": \"Las fibrillas de colágeno Tipo I que componen los tendones poseen una resistencia a la tracción de 50 a 100 MPa, superando cuatro veces la tenacidad del hilo de algodón. Al humedecerse con saliva, las hebras se vuelven dóciles para la costura; al evaporarse la humedad, se contraen entre un 3 y un 5% en volumen, bloqueando firmemente los orificios del cuero sin requerir nudos voluminosos.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"Tira de Tendón Animal Secado al Viento\",\n            \"scientificName\": \"Dried Mammalian Tendon (Sinew)\",\n            \"categoryTag\": \"Fibra Natural Primitiva / Hilo de Tracción Extrema\",\n            \"imageFileName\": \"id-dried-animal-sinew.jpg\",\n            \"hudCode\": \"FIG. BIO-14B // MACRO OPTIC\",\n            \"hudStatus\": \"TENSILE STRENGTH RATING: MAXIMUM\",\n            \"traits\": [\n              {\n                \"label\": \"TEXTURA\",\n                \"value\": \"Tira rígida y traslúcida de color ámbar con estrías fibrosas visibles.\"\n              },\n              {\n                \"label\": \"DESFIBRADO\",\n                \"value\": \"Se esponja en hebras blanco-plateadas tan suaves como la seda al percutirse.\"\n              },\n              {\n                \"label\": \"CONTRACCIÓN\",\n                \"value\": \"Flexible al contacto con saliva; se tensa como alambre acerado al secarse.\"\n              }\n            ],\n            \"fieldUse\": \"Separado en filamentos finos para enhebrar agujas de hueso y reparar equipo de cuero\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Paso 4: Pre-Perforar Orificios a 5mm con Lezna, Coser con Puntada de Guarnicionero y Sellar con Brea\",\n      \"description\": \"1. **Pre-Perforación del Cuero**: Traslape los bordes del cuero roto **el ancho de una falange** y perfore previamente una hilera de **agujeros separados 5 mm** con la lezna de sílex y la maza de madera.\\n2. **Costura de Guarnicionero (Saddle Stitch)**: Enhebre una aguja en cada extremo del tendón o cruce una sola aguja alternando de adelante hacia atrás, tensando firmemente cada puntada.\\n3. **Contracción y Sellado con Resina**: Una vez tensada la costura y seco el tendón, extienda [ungüento templado de resina de pino](/protocol-10.html) sobre la costura para sellar los orificios contra **la entrada de nieve, viento y agua helada**.\",\n      \"actionNote\": \"> Pre-Perforación Obligatoria: Aunque la aguja de hueso es sumamente resistente, se quebrará si intenta perforar cuero duro directamente. Abra siempre los orificios con la lezna de sílex y use la aguja solo como guía de arrastre del hilo.\",\n      \"svgFileName\": \"pr14-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // SADDLE STITCHING & PITCH SEALING\",\n        \"PRE-PERFORACIÓN CON LEZNA A INTERVALOS DE 5MM\",\n        \"COSTURA DE GUARNICIONERO CON TENDÓN CRUZADO\",\n        \"SELLADO IMPERMEABLE DE COSTURA CON BREA DE PINO\",\n        \"[PASO CLAVE 4] RETRACCIÓN DEL TENDÓN PARA CIERRE ESTANCO\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Error Fatal: Empujar con fuerza la cabeza de la aguja de hueso para forzarla a atravesar cuero grueso sin perforación previa\",\n    \"description\": \"Forzar una aguja de hueso a través de cuero crudo y grueso sin perforaciones previas somete la estructura a un par de torsión excesivo que quiebra la cabeza o el cuerpo. La astilla ósea afilada puede clavarse profundamente en la palma o dedos, provocando traumatismos penetrantes graves y tétanos letal de campo. Perfore siempre orificios espaciados a 5 mm con una lezna de sílex y maza de madera, utilizando la aguja de hueso exclusivamente como guía suave para deslizar el hilo de tendón.\",\n    \"consequence\": \"Consecuencia: Fractura de la aguja, herida penetrante profunda en la mano y riesgo de tétanos / sepsis\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"¿Viento helado a 20 bajo cero y la bota rota? En 2 horas morirás congelado. ¡Fabrica una aguja de hueso ahora mismo!\",\n    \"body\": \"Parte la tibia de un ciervo con una piedra, afílala sobre cuarcita mojada y taladra el ojo con sílex. Machaca tendón seco con un palo: ¡obtendrás hebras 4 veces más fuertes que el algodón! Humedece el hilo con saliva, perfora agujeros en el cuero con sílex y cose cruzado. Al secarse, el tendón se encoge y aprieta los orificios, ¡y untar resina de pino hace que la bota sea 100% impermeable!\",\n    \"outro\": \"Sobrevive sin tecnología moderna aprendiendo habilidades primitivas. Consulta todos los manuales sin conexión.\"\n  },\n  \"outcome\": {\n    \"title\": \"Bota de Cuero Reparada en Campo y Juego de Aguja de Hueso y Tendón\",\n    \"badge\": \"CRITERIO DE INSPECCIÓN // FIELD REPAIRED GEAR\",\n    \"standard\": \"La aguja de hueso debe lucir un pulido sedoso sin aristas, el ojo debe admitir hebra doble con holgura y la costura de cuero no debe abrirse ni 1 mm bajo tracción manual vigorosa\",\n    \"svgFileName\": \"pr14-outcome.svg\",\n    \"svgLabels\": [\n      \"PR-14 OUTCOME // BONE NEEDLE & SINEW SEWING KIT\",\n      \"AGUJA DE HUESO CORTICAL TERMINADA (LARGO 7.5CM)\",\n      \"OJO PRECISO PERFORADO CON LEZNA DE SÍLEX (DIÁMETRO 1.8MM)\",\n      \"MANOJO DE HEBRAS DE TENDÓN DE ALTA TENACIDAD DESFIBRADO\",\n      \"COSTURA CRUZADA DE GUARNICIONERO Y SELLO DE BREA\",\n      \"BOTA DE INVIERNO RESTAURADA (100% RETENCIÓN TÉRMICA)\",\n      \"FIELD VERIFIED // TENSILE STRENGTH RATED & WATERPROOF\"\n    ]\n  },\n  \"createdAt\": \"2026-10-22T08:09:29.733Z\",\n  \"updatedAt\": \"2026-10-22T08:14:43.819Z\",\n  \"contentHash\": \"614132e570544622\"\n}","content/protocols/locales/14-bone-needle-sinew-sewing.ja.json":"{\n  \"protocolId\": \"PR-14\",\n  \"category\": \"TOOLS\",\n  \"title\": \"動物の骨と乾燥腱で作る革服・靴修繕キット（野戦骨針と腱糸縫製術）\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[極寒期の体温流失遮断＆足の凍傷・低体温症防止]\",\n  \"summary\": \"極寒の冬期野外や文明崩壊後の被災地において、防寒用の革服や靴底が裂けると体温が急激に奪われ、2時間以内に致命的な低体温症や凍傷を招きます。金属針やナイロン糸がない野戦環境では、[罠猟で捕獲した獲物](/protocol-08.html)の鹿や猪の脛骨（緻密骨）を[石斧](/protocol-04.html)で割り、湿らせた珪岩砥石で研ぎ出して火打石の錐で針孔を開けた「骨針」と、脚の腱を叩いてほぐした超高強度繊維「腱糸」を自作して修繕します。腱糸は唾液で湿らせて縫製した後、自然乾燥に伴い3〜5%自己収縮して縫い目を締め付けるため、[松脂軟膏](/protocol-10.html)を塗布すれば冷気と水分を100%遮断する防寒装備が蘇ります。\",\n  \"timeRequired\": \"60分（骨針研磨30分＋腱糸加工15分＋革縫製15分）\",\n  \"successRate\": \"95%（火打石の錐による予備穿孔および腱糸の唾液湿潤を厳守した場合）\",\n  \"difficulty\": \"普通（指の長さの緻密骨選別と火打石による両面穿孔に注意）\",\n  \"outputPerHour\": \"骨針2本と腱糸10本で革長靴1足または防寒上着1着を完全修繕\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"大型哺乳類（鹿・猪）の脛骨（すね骨）破片1〜2個\",\n      \"desc\": \"[罠猟](/protocol-08.html)や[灰汁石鹸](/protocol-13.html)用の油脂抽出後に残った骨です。骨の円筒部緻密骨（Cortical Bone）は鉄釘に匹敵する引張強度と曲げ弾性を持ち、革を貫通させても容易に折れません。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"粗い珪岩の砥石板と穴あけ用火打石の錐（Flint Awl）\",\n      \"desc\": \"[打製石器加工](/protocol-04.html)に使用する粒子が粗い珪岩の岩盤と、骨に1.8mmの針孔を開けるための鋭利な錐状チャート石です。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"関節部から採取し乾燥させた動物の腱（Sinew）の束\",\n      \"desc\": \"鹿のアキレス腱などを日陰の風通しの良い場所で琥珀色に乾燥させた硬い腱です。木槌で軽く叩くと、髪の毛ほどの太さの高強度天然繊維数十本に分離します。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"叩き加工用の硬木バトンと防水密閉用の松脂\",\n      \"desc\": \"腱の破砕や錐の打撃に用いる手頃なナラ材の棒と、[松脂軟膏](/protocol-10.html)として用いる防水用松脂の塊です。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"ステップ1：動物の脛骨を割り、湿った珪岩砥石で研いで指の長さの骨針ブランクを成形する\",\n      \"description\": \"1. **緻密骨の選別と縦割り**：鹿の脛骨を[石斧や丸石](/protocol-04.html)で縦方向に打ち割り、**指の長さ（約7〜8cm）、厚さ3〜4mm**の細長い骨片を取り出します。\\n2. **珪岩砥石による粗研磨**：水をかけた粗い珪岩の表面に骨片を45度の角度で当てて擦り、凹凸のある骨髄痕を削り落として円筒状の棒状に整えます。\\n3. **針先の鋭角研磨**：片端を砥石に30度の角度で当て、回転させながら研ぎ上げて**革を突き刺せる鋭利な先端**を完成させます。\",\n      \"actionNote\": \"> 破片飛散注意：骨を叩き割る際に骨粉や細片が飛び散るため、顔を45度逸らして打撃してください。砥石に水をたっぷり含ませることで、摩擦熱による骨の劣化を防ぎます。\",\n      \"svgFileName\": \"pr14-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // BONE SPLINTER BLANK PREPARATION\",\n        \"鹿脛骨緻密骨の縦割り分離工程\",\n        \"水研ぎ粗目珪岩砥石による表面研磨\",\n        \"指の長さ（7〜8CM）棒状ブランク成形\",\n        \"[第1段階要点] 30°回転研磨による鋭利針先完成\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BIOMECHANICS\",\n        \"title\": \"哺乳類脛骨ハイドロキシアパタイト結晶構造とせん断強度\",\n        \"text\": \"鹿などの大型有蹄類の脛骨（Tibia）は体重を支えるため、微細気孔が極めて少ない高密度緻密骨（Cortical Bone）で構成されています。リン酸カルシウム複合体と膠原線維（コラーゲン）が同心円状の層板構造を形成しており、研磨加工によって鋼鉄釘に匹敵する耐曲げ弾性と滑らかな刺突性を獲得します。\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"哺乳類脛骨緻密骨の骨片\",\n            \"scientificName\": \"Mammalian Tibia Cortical Bone\",\n            \"categoryTag\": \"野戦骨角器素材 / 高強度骨針ブランク\",\n            \"imageFileName\": \"id-deer-metatarsal-bone.jpg\",\n            \"hudCode\": \"FIG. BIO-14A // MACRO OPTIC\",\n            \"hudStatus\": \"DENSITY & FLEXURAL STRENGTH: HIGH\",\n            \"traits\": [\n              {\n                \"label\": \"色彩/COLOR\",\n                \"value\": \"骨の内層はやや黄ばみ、外表面は**乳白色から淡いクリーム色**を呈します。\"\n              },\n              {\n                \"label\": \"組織/DENSITY\",\n                \"value\": \"海綿状の気孔がなく、**ガラスの断面のように硬質で緻密**な層です。\"\n              },\n              {\n                \"label\": \"音響/ACOUSTIC\",\n                \"value\": \"石で軽く叩いた際、鈍い音ではなく**金属のように甲高い共鳴音**が響きます。\"\n              }\n            ],\n            \"fieldUse\": \"厚さ3〜4mmの縦割り骨片を選別し、珪岩砥石研磨用ブランクとして投入\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"ステップ2：火打石の錐で骨針の頭部に両面回転穿孔し、針孔（Eye）を開けて砂で研磨する\",\n      \"description\": \"1. **両面回転穿孔**：鋭利な火打石の錐（Flint Awl）の先端を骨針の頭部から**小指の爪半分（約5mm）内側の位置**に当て、指先で往復回転させて表裏両面から円錐状の窪みを彫り進めます。\\n2. **貫通と内部バリ取り**：穴が貫通したら、細い小枝や乾いた植物の棘を差し込んで回転させ、内部の粗いバリを削り落として糸切れを防ぎます。\\n3. **微細研磨**：きめの細かい粘土石や川砂で骨針の全身を磨き込み、革を通過する際に引っかかりがないよう**ガラス玉のような滑らかな光沢**を出します。\",\n      \"actionNote\": \"> 頭部破損防止：片面から一度に深く掘り進めると頭部が割れてしまいます。必ず表面から深さ半分まで彫り、裏返して反対側から貫通させる「両面対称穿孔」を徹底してください。\",\n      \"svgFileName\": \"pr14-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // DUAL-CONE EYE DRILLING & FINISHING\",\n        \"火打石錐（FLINT AWL）両面回転穿孔\",\n        \"頭部から5MM内側の針孔（EYE）貫通口\",\n        \"植物棘の回転による内部バリ除去研磨\",\n        \"[第2段階要点] 細川砂研磨によるガラス光沢仕上げ\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"ステップ3：乾燥腱を木製バトンで叩き、髪の毛ほどの極細高強度コラーゲン繊維をほぐす\",\n      \"description\": \"1. **乾燥腱の配置**：風通しの良い日陰で硬く乾燥させた琥珀色の腱を、平らな川石の台の上に置きます。\\n2. **木槌による軽打撃**：丸みのあるナラ材のバトンで腱を軽くトントンと叩き、コラーゲン線維束の結合をほぐします（強打すると繊維が破断するため注意）。\\n3. **繊維の分離と唾液コーティング**：綿のように白くほぐれた腱の束から、指先で**髪の毛3〜4本分の細い繊維**を引き抜きます。糸の先端に唾液を少量塗って撚り合わせると繊維がまとまり、針孔へ滑らかに通せます。\",\n      \"actionNote\": \"> 打撃の加減：鋭利な石や刃物で叩くと繊維が粉断されて使えなくなります。丸みを帯びた硬木バトンの角を使い、「叩いて繊維をほぐし広げる」感覚で繊細に打撃してください。\",\n      \"svgFileName\": \"pr14-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DRIED ANIMAL SINEW FIBER SEPARATION\",\n        \"平坦川石アンビル上の乾燥腱（SINEW）配置\",\n        \"ナラ材バトン軽打撃（コラーゲン束分離）\",\n        \"髪の毛3〜4本太さの高張力繊維コーミング\",\n        \"[第3段階要点] 唾液塗布による針孔通過性向上\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIBER SCIENCE\",\n        \"title\": \"動物腱のType Iコラーゲン架橋構造と乾燥収縮による自己締結力\",\n        \"text\": \"哺乳類の腱（Tendon）を構成するType Iコラーゲン原線維は、引張強度が約50〜100 MPaに達し、同等の太さの綿糸の4倍以上の強度を誇ります。水分や唾液を含んだ状態では柔軟で縫製しやすく、縫製後に自然乾燥すると体積が3〜5%収縮して革の針穴を全周から締め上げ、結び目を解けなくする強力な自己締結（Self-Locking）作用を発揮します。\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"日陰乾燥した動物の腱（腱糸）\",\n            \"scientificName\": \"Dried Mammalian Tendon (Sinew)\",\n            \"categoryTag\": \"野戦天然繊維 / 超高張力縫製糸\",\n            \"imageFileName\": \"id-dried-animal-sinew.jpg\",\n            \"hudCode\": \"FIG. BIO-14B // MACRO OPTIC\",\n            \"hudStatus\": \"TENSILE STRENGTH RATING: MAXIMUM\",\n            \"traits\": [\n              {\n                \"label\": \"外観/TEXTURE\",\n                \"value\": \"光にかざすと**琥珀色の角質のように半透明で硬い**棒状を呈します。\"\n              },\n              {\n                \"label\": \"分離/SEPARATION\",\n                \"value\": \"木槌で叩くと**絹糸のように柔らかく銀白色の極小繊維**にほぐれます。\"\n              },\n              {\n                \"label\": \"収縮/SHRINKAGE\",\n                \"value\": \"唾液でしなやかになり、乾燥すると**鋼鉄線のように強固に収縮**します。\"\n              }\n            ],\n            \"fieldUse\": \"細く引き裂いて骨針に通し、革装備の補修や石斧の柄の結束に投入\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"ステップ4：火打石の錐で革に予備穴を開け、サドルステッチ（両引き縫い）で縫合して松脂で密閉する\",\n      \"description\": \"1. **革の縁の予備穿孔**：破れた革の両端を**指の関節1つ分重ね合わせ**、骨針の破損を防ぐため鋭い火打石の錐で**5mm間隔の針穴**を一列に開けます。\\n2. **サドルステッチ（交互交差縫い）**：腱糸の両端に骨針を付けるか、1本の針で穴を表裏交互に交差させて通し、一針ごとに強く引き締めながら縫い進めます。\\n3. **乾燥収縮と松脂防水コーティング**：縫製後、[温めた松脂軟膏](/protocol-10.html)を縫い目（シーム）の上に薄く塗り込むことで、収縮した腱糸と共に雪や冷水の浸入を遮断する**完全防寒・防水装備**が完成します。\",\n      \"actionNote\": \"> 予備穿孔の徹底：骨針は硬いものの、厚い生革を無理に貫通させようとすると頭部が折損します。穴は必ず火打石の錐で先行して開け、骨針は糸を通すためのガイドとしてのみ使用してください。\",\n      \"svgFileName\": \"pr14-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // SADDLE STITCHING & PITCH SEALING\",\n        \"火打石錐による5MM間隔革予備穿孔\",\n        \"腱糸両方向交差サドルステッチ縫製\",\n        \"松脂軟膏塗布による縫合部防水コーティング\",\n        \"[第4段階要点] 腱糸の乾燥自己収縮で針穴を完全密閉\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命的失敗：火打石の錐による予備穿孔を行わず、厚い濡れた革に骨針の頭部を持って力任せに押し込む行為\",\n    \"description\": \"予備穿孔なしに厚手の生革へ骨針を無理に押し込むと、曲げ応力により針頭や針体が破断します。破損した鋭利な骨片が手のひらや指の深部に突き刺さり、重篤な刺創と野戦破傷風による敗血症を引き起こします。厚い革は必ず火打石の錐と木製バトンで5mm間隔の貫通孔を先行して開け、骨針は糸を通すガイドとしてのみ使用してください。\",\n    \"consequence\": \"結果：骨針の破損、手のひらへの深部刺創および野戦破傷風・敗血症の感染リスク\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"氷点下20度の猛吹雪で靴底や革服が裂けたら？2時間で凍死します。今すぐ骨針を作ってください！\",\n    \"body\": \"鹿のすね骨を石で割り、珪岩砥石で研いで指の長さの骨針を作ります。火打石の錐で両面から穴を開けて針孔を貫通させましょう。次に乾いた腱を木の棒で叩けば、絹糸より強靭なコラーゲン糸の完成！唾液を塗って針に通し、火打石で革に穴を開けて交互に縫い合わせれば完了です。腱糸が乾きながら穴を強く締め付け、松脂を塗れば完全防水の防寒靴が蘇ります。\",\n    \"outro\": \"文明が崩壊しても野生の素材が命を救います。教範を保存して野戦技術を習得してください！\"\n  },\n  \"outcome\": {\n    \"title\": \"野戦修繕が完了した防寒革靴と骨針・腱糸ソーイングキット\",\n    \"badge\": \"完成検収基準 // FIELD REPAIRED GEAR\",\n    \"standard\": \"骨針表面がガラスのように滑らかで、針孔が腱糸2本を確実に保持し、サドルステッチで縫合された革の継ぎ目が手で強く引いても1mmの隙間なく密着していること\",\n    \"svgFileName\": \"pr14-outcome.svg\",\n    \"svgLabels\": [\n      \"PR-14 OUTCOME // BONE NEEDLE & SINEW SEWING KIT\",\n      \"完成した乳白色高密度緻密骨針（全長7.5CM）\",\n      \"火打石錐両面穿孔の精密針孔（直径1.8MM）\",\n      \"木製バトン打撃で分離した銀白色高張力腱糸束\",\n      \"サドルステッチ二重結合＆松脂防水密閉シーム断面\",\n      \"完全復元された防寒革長靴（体温流失100%遮断）\",\n      \"FIELD VERIFIED // TENSILE STRENGTH RATED & WATERPROOF\"\n    ]\n  },\n  \"createdAt\": \"2026-10-22T08:09:29.733Z\",\n  \"updatedAt\": \"2026-10-22T08:14:43.819Z\",\n  \"contentHash\": \"614132e570544622\"\n}","content/protocols/locales/14-bone-needle-sinew-sewing.pt.json":"{\n  \"protocolId\": \"PR-14\",\n  \"category\": \"TOOLS\",\n  \"title\": \"Agulha de Osso Primitiva e Costura com Tendão Seco para Couro e Calçados\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[DEFESA CONTRA PERDA TÉRMICA & PREVENÇÃO DE HIPOTERMIA E CONGELAMENTO]\",\n  \"summary\": \"Em climas de frio extremo ou em cenários pós-colapso sem acesso a suprimentos manufaturados, o rompimento de trajes de couro ou solas de botas provoca uma perda térmica drástica, levando à hipotermia letal ou congelamento de membros em menos de 2 horas. Sem agulhas de aço ou linha sintética, é vital confeccionar um kit de costura rústico: quebre ossos longos de perna de cervos ou javalis com um [machado de pedra](/protocol-04.html), lixe sobre quartzito molhado e fure o olho com uma sovela de sílex. Combinadas com tendões secos desfiados em fibras de colágeno de altíssima tensão, as linhas amolecidas com saliva encolhem de 3 a 5% ao secar, comprimindo os orifícios antes de serem impermeabilizadas com [breu de pinho aquecido](/protocol-10.html).\",\n  \"timeRequired\": \"60 min (30m polimento de osso + 15m desfiamento de tendão + 15m costura)\",\n  \"successRate\": \"95% (quando pré-perfurado com sovela de sílex e lubrificado com saliva)\",\n  \"difficulty\": \"Média (seleção criteriosa de osso cortical denso e perfuração bicônica)\",\n  \"outputPerHour\": \"2 agulhas de osso e 10 fios de tendão; restaura 1 par de botas ou 1 casaco de couro\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"1–2 Fragmentos de Osso Cortical da Perna (Tíbia ou Metatarso de Cervo ou Javali)\",\n      \"desc\": \"Obtidos em [armadilhas de caça](/protocol-08.html) ou restos de gordura para [sabão de lixívia de cinzas](/protocol-13.html). A densa parede tubular do osso cortical resiste a esforços de flexão comparáveis aos de pregos de aço, não se quebrando ao perfurar couros duros.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Placa Abrasiva de Quartzito & Sovela Perfuradora de Sílex\",\n      \"desc\": \"Uma laje de quartzito áspero usada na [manufatura lítica](/protocol-04.html) e uma sovela pontiaguda de sílex para escavar o orifício de 1,8 mm da agulha em ambos os lados.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Tira de Tendão Animal Seco ao Vento (Tendão de Aquiles)\",\n      \"desc\": \"Tendão extraído das articulações de cervos, desidratado à sombra até adquirir aspecto córneo e translúcido. Ao ser percutido suavemente com madeira, solta centenas de filamentos de colágeno finíssimos e resistentes.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Bastão Curto de Madeira Dura & Resina de Pinho Impermeabilizante\",\n      \"desc\": \"Um pedaço roliço de carvalho para desfiar tendões e percutir a sovela, junto com [unguento de resina de pinho](/protocol-10.html) para selar hermeticamente as costuras do couro.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Passo 1: Fender o Osso Cortical e Esboçar uma Haste de Agulha sobre Quartzito Úmido\",\n      \"description\": \"1. **Seleção e Fendimento Longitudinal**: Fenda a tíbia de um cervo no sentido longitudinal com um [machado de pedra ou seixo pesado](/protocol-04.html) para extrair uma lasca densa do **comprimento de um dedo (7–8 cm) e 3–4 mm de espessura**.\\n2. **Desbaste em Quartzito Úmido**: Molhe a laje de quartzito e friccione a lasca óssea a 45 graus, removendo resíduos esponjosos de medula e moldando-a em formato cilíndrico regular.\\n3. **Usinagem da Ponta Perfurante**: Incline uma das pontas a 30 graus girando-a continuamente contra a pedra molhada até obter uma **ponta afiada capaz de perfurar couro**.\",\n      \"actionNote\": \"> Risco de Estilhaços: O impacto pode projetar lascas de osso; vire o rosto em 45 graus ao percutir. Mantenha o quartzito sempre úmido para que o atrito térmico não queime nem fragilize o osso.\",\n      \"svgFileName\": \"pr14-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // BONE SPLINTER BLANK PREPARATION\",\n        \"FENDIMENTO LONGITUDINAL DE TÍBIA DE CERVO\",\n        \"DESBASTE DE SUPERFÍCIE EM QUARTZITO ÚMIDO\",\n        \"HASTE CILÍNDRICA DO TAMANHO DE UM DEDO (7–8CM)\",\n        \"[PASSO CHAVE 1] AFIAÇÃO ROTACIONAL A 30° DA PONTA\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BIOMECHANICS\",\n        \"title\": \"Matriz de Hidroxiapatita e Resistência ao Cisalhamento do Osso Cortical\",\n        \"text\": \"A cortical dos ossos de sustentação de grandes mamíferos é constituída por camadas concêntricas de osteônios sem porosidade esponjosa. A sinergia entre cristais de hidroxiapatita e fibras de colágeno confere tenacidade e elasticidade mecânica, permitindo que as agulhas suportem pressões de torção sem se romperem dentro de peles duras.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"Lasca de Osso Cortical de Mamífero\",\n            \"scientificName\": \"Mammalian Tibia Cortical Bone\",\n            \"categoryTag\": \"Material Osteológico Rústico / Haste de Agulha\",\n            \"imageFileName\": \"id-deer-metatarsal-bone.jpg\",\n            \"hudCode\": \"FIG. BIO-14A // MACRO OPTIC\",\n            \"hudStatus\": \"DENSITY & FLEXURAL STRENGTH: HIGH\",\n            \"traits\": [\n              {\n                \"label\": \"COLORAÇÃO\",\n                \"value\": \"Superfície marfim ou creme claro com interior denso e amarelado.\"\n              },\n              {\n                \"label\": \"DENSIDADE\",\n                \"value\": \"Corte transversal polido e vítreo, sem cavidades porosas esponjosas.\"\n              },\n              {\n                \"label\": \"ACÚSTICA\",\n                \"value\": \"Produz um tinido metálico cristalino e ressonante ao ser batido de leve em pedra.\"\n              }\n            ],\n            \"fieldUse\": \"Lascas selecionadas de 3–4 mm polidas em agulhas afiadas sobre quartzito\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Passo 2: Escavar o Olho Bicônico com Sovela de Sílex e Polir com Areia Fina\",\n      \"description\": \"1. **Perfuração Rotativa Oposta**: Apoie a ponta da sovela de sílex a **meia unha de distância (cerca de 5 mm) da cabeça cega**. Gire entre os dedos para abrir uma cavidade cônica até a metade da espessura; vire a agulha e termine a perfuração pelo lado oposto.\\n2. **Desbaste Interno e Remoção de Rebarbas**: Com o canal aberto, passe um espinho seco ou graveto fino girando-o com vigor para remover rebarbas internas que possam desfiar a linha.\\n3. **Polimento Sedoso**: Esfregue toda a extensão da agulha com argila úmida ou areia fina de rio até que fique **lisa e brilhante como vidro**, garantindo deslizamento suave no couro.\",\n      \"actionNote\": \"> Evitar Ruptura da Cabeça: Furar por um único lado cria pressão expansiva e racha o osso. Adote sempre a perfuração simétrica em formato de ampulheta (frente e verso).\",\n      \"svgFileName\": \"pr14-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // DUAL-CONE EYE DRILLING & FINISHING\",\n        \"PERFURAÇÃO ROTATIVA OPOSTA COM SOVELA DE SÍLEX\",\n        \"OLHO DA AGULHA ESCAVADO A 5MM DA CABEÇA\",\n        \"REMOÇÃO DE REBARBAS INTERNAS COM ESPINHO VEGETAL\",\n        \"[PASSO CHAVE 2] POLIMENTO COM AREIA FINA ATÉ O BRILHO\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Passo 3: Bater o Tendão Seco com Bastão de Madeira e Extrair Fibras de Colágeno\",\n      \"description\": \"1. **Posicionamento do Tendão**: Disponha a tira rígida de tendão seco em uma pedra chata de rio que sirva de bigorna.\\n2. **Batidas Leves de Madeira**: Golpeie suavemente com a ponta roliça de um bastão de carvalho para desarticular a união entre os feixes de colágeno (pancadas fortes cortam as fibras prematuramente).\\n3. **Separação e Lubrificação com Saliva**: Puxe com as pontas dos dedos os feixes esfiapados até destacar **linhas da espessura de 3 a 4 fios de cabelo**. Molhe a ponta com saliva e torça entre os dedos para compactá-la, facilitando a passagem pelo olho da agulha.\",\n      \"actionNote\": \"> Força das Batidas: Nunca use pedras cortantes ou machados para bater no tendão. Use madeira arredondada e bata delicadamente para desfiar o material como pluma de seda sem quebrar sua extensão.\",\n      \"svgFileName\": \"pr14-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DRIED ANIMAL SINEW FIBER SEPARATION\",\n        \"TENDÃO SECO SOBRE BIGORNA DE PEDRA LISA\",\n        \"BATIDAS LEVES COM BASTÃO (DESPRENDIMENTO DE COLÁGENO)\",\n        \"DESFIAMENTO DE LINHAS DA LARGURA DE 3–4 CABELOS\",\n        \"[PASSO CHAVE 3] LUBRIFICAÇÃO COM SALIVA PARA ENFIAMENTO\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIBER SCIENCE\",\n        \"title\": \"Entrecruzamento Molecular de Colágeno Tipo I e Contração Autoblocante\",\n        \"text\": \"As fibrilas de colágeno Tipo I dos tendões atingem resistências à tração de 50 a 100 MPa — quadruplicando a resistência do algodão de mesmo calibre. Umedecidas em saliva, tornam-se maleáveis para a costura. Ao secarem no couro, sofrem retração volumétrica de 3 a 5%, apertando as margens do orifício e garantindo um travamento mecânico firme sem a necessidade de nós complexos.\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"Tira de Tendão Animal Seco ao Vento\",\n            \"scientificName\": \"Dried Mammalian Tendon (Sinew)\",\n            \"categoryTag\": \"Fibra Natural Rústica / Linha de Alta Resistência\",\n            \"imageFileName\": \"id-dried-animal-sinew.jpg\",\n            \"hudCode\": \"FIG. BIO-14B // MACRO OPTIC\",\n            \"hudStatus\": \"TENSILE STRENGTH RATING: MAXIMUM\",\n            \"traits\": [\n              {\n                \"label\": \"TEXTURA\",\n                \"value\": \"Bastão rígido e translúcido cor de âmbar com estrias longitudinais visíveis.\"\n              },\n              {\n                \"label\": \"DESFIAMENTO\",\n                \"value\": \"Desprende-se em filamentos brancos prateados e macios como seda quando percutido.\"\n              },\n              {\n                \"label\": \"CONTRAÇÃO\",\n                \"value\": \"Maleável com saliva; contrai-se com a rigidez de um arame de aço ao secar.\"\n              }\n            ],\n            \"fieldUse\": \"Fibras delgadas enfiadas em agulhas de osso para reparar trajes e amarrar ferramentas\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Passo 4: Pré-Perfurar Furos a 5mm com Sovela, Costurar em Ponto de Sela e Selar com Breu\",\n      \"description\": \"1. **Pré-Perfuração do Couro**: Sobreponha as bordas rasgadas em **uma largura de falange** e faça previamente uma fileira de **furos espaçados em 5 mm** usando a sovela de sílex e o bastão.\\n2. **Ponto de Sela (Costura Cruzada)**: Passe agulhas em ambas as extremidades da linha de tendão ou cruze uma única agulha alternando frente e verso em oito, puxando com firmeza a cada ponto.\\n3. **Contração e Selagem com Resina**: Deixe a linha secar e esticar, aplicando em seguida [unguento de resina de pinho aquecido](/protocol-10.html) sobre a costura para bloquear **a infiltração de água, neve e vento gelado**.\",\n      \"actionNote\": \"> Pré-Perfuração Obrigatória: A agulha de osso resiste bem à compressão, mas partirá com esforço de alavanca em couro duro. Fure sempre com a sovela de sílex e use a agulha de osso apenas como guia da linha.\",\n      \"svgFileName\": \"pr14-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // SADDLE STITCHING & PITCH SEALING\",\n        \"PRÉ-PERFURAÇÃO COM SOVELA A INTERVALOS DE 5MM\",\n        \"COSTURA EM PONTO DE SELA COM TENDÃO CRUZADO\",\n        \"SELAGEM IMPERMEÁVEL DA COSTURA COM BREU DE PINHO\",\n        \"[PASSO CHAVE 4] CONTRAÇÃO DO TENDÃO BLOQUEIA FUROS\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Erro Fatal: Empurrar com força a cabeça da agulha de osso para furar couro espesso sem fazer furos prévios\",\n    \"description\": \"Forçar uma agulha de osso através de couro cru e espesso sem furos prévios submete a estrutura a uma força de torção excessiva que quebra a cabeça ou a haste. Lascas pontiagudas de osso podem penetrar profundamente na palma da mão ou nos dedos, provocando ferimentos penetrantes graves e infecção por tétano em campo. Faça sempre furos prévios a cada 5 mm com uma sovela de sílex e bastão de madeira, usando a agulha de osso exclusivamente como guia suave para conduzir a linha de tendão.\",\n    \"consequence\": \"Consequência: Quebra da agulha, ferimento penetrante profundo na mão e risco de infecção por tétano\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Nevasca a 20 graus abaixo de zero e a bota rasgada? Em 2 horas você morre de hipotermia. Fabrique uma agulha de osso AGORA!\",\n    \"body\": \"Quebre o osso da perna de um cervo, afie em pedra de quartzito molhada e fure o olho com sílex. Bata no tendão seco com um pedaço de pau: você terá fios 4 vezes mais resistentes que algodão! Molhe com saliva, fure o couro com sílex e faça a costura cruzada. Ao secar, o tendão encolhe como arame de aço, e a resina de pinho torna a bota 100% à prova d'água!\",\n    \"outro\": \"Aprenda habilidades primitivas reais para sobreviver ao colapso. Baixe todos os guias sem precisar de internet!\"\n  },\n  \"outcome\": {\n    \"title\": \"Bota de Couro Reparada em Campo e Kit de Agulha de Osso e Tendão\",\n    \"badge\": \"PADRÃO DE INSPEÇÃO // FIELD REPAIRED GEAR\",\n    \"standard\": \"Agulha de osso com polimento vítreo, olho acomodando duas pontas de tendão confortavelmente e costura em ponto de sela sem afrouxar nem 1 mm sob forte tração manual\",\n    \"svgFileName\": \"pr14-outcome.svg\",\n    \"svgLabels\": [\n      \"PR-14 OUTCOME // BONE NEEDLE & SINEW SEWING KIT\",\n      \"AGULHA DE OSSO CORTICAL CONCLUÍDA (COMPRIMENTO 7.5CM)\",\n      \"OLHO PRECISO PERFURADO COM SOVELA DE SÍLEX (DIÂMETRO 1.8MM)\",\n      \"FEIXE DE FIOS DE TENDÃO DE ALTA TENSÃO DESFIADOS\",\n      \"PONTO DE SELA DUPLO E COSTURA SELADA COM BREU DE PINHO\",\n      \"BOTA DE INVERNO RECUPERADA (100% RETENÇÃO TÉRMICA)\",\n      \"FIELD VERIFIED // TENSILE STRENGTH RATED & WATERPROOF\"\n    ]\n  },\n  \"createdAt\": \"2026-10-22T08:09:29.733Z\",\n  \"updatedAt\": \"2026-10-22T08:14:43.819Z\",\n  \"contentHash\": \"614132e570544622\"\n}","content/protocols/locales/14-bone-needle-sinew-sewing.zh-TW.json":"{\n  \"protocolId\": \"PR-14\",\n  \"category\": \"TOOLS\",\n  \"title\": \"野外動物腿骨與乾鹿筋縫合破損皮衣皮靴術（骨針與筋線縫紉套裝）\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[嚴寒野外體溫流失阻斷＆凍傷與失溫症緊急預防]\",\n  \"summary\": \"在零下數十度的極寒野外或文明崩潰的荒野環境中，防寒皮衣或雪地皮靴底若破裂撕開，體溫將在2小時內急劇流失，導致致命的失溫症或雙腳凍傷壞死。在缺乏鋼針與尼龍線的原始條件下，必須利用[陷阱捕獵獲取](/protocol-08.html)的鹿或野豬腿部脛骨（緻密骨），以[石斧](/protocol-04.html)縱向劈開並在沾水的石英岩磨石上研磨出針身，用燧石錐鑽出雙錐形針孔製成「骨針」；同時將風乾的腿筋敲打拆解出超高強度的「筋線（Sinew）」。筋線沾唾液縫合後，在自然風乾過程中會自行收縮3~5%死死鎖住針孔，塗抹[松香軟膏](/protocol-10.html)後即可完全隔絕風雪與冰水滲透。\",\n  \"timeRequired\": \"60分鐘（骨針打磨30分＋筋線敲打拆解15分＋皮革雙向縫製15分）\",\n  \"successRate\": \"95%（嚴格遵守燧石錐預先穿孔與筋線唾液塗抹潤滑時）\",\n  \"difficulty\": \"中等（注意選取手指長度緻密骨與燧石錐兩面對稱鑽孔）\",\n  \"outputPerHour\": \"製作2根骨針與10條高強度筋線；可完整修補1雙皮靴或1件防寒皮大衣\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"大型哺乳動物（鹿或野豬）小腿脛骨緻密骨破片1~2塊\",\n      \"desc\": \"來自[陷阱捕獲物](/protocol-08.html)或提煉[草木灰鹼皂](/protocol-13.html)油脂後剩餘的腿骨。骨壁中段的圓筒狀緻密骨（Cortical Bone）具有抗衡鋼釘的抗彎與抗拉強度，穿透厚皮不易折斷。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"粗顆粒石英岩磨石平板與鑽孔用尖銳燧石錐（Flint Awl）\",\n      \"desc\": \"[打製石器製造](/protocol-04.html)所用的粗磨石，以及能在骨頭上旋轉鑽出1.8mm直徑針孔的堅硬錐狀燧石/角岩。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"由腿部關節處剝取並完全風乾的動物筋腱（Sinew）束\",\n      \"desc\": \"鹿後腿跟腱（阿基里斯腱）在陰涼通風處晾乾而成的硬質琥珀色條狀物。用木棒輕敲即可散開成數百根如髮絲般的超強天然膠原纖維。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"敲擊用硬木棒與接縫防水密封用松樹松香\",\n      \"desc\": \"用於敲散筋腱纖維與敲擊燧石錐的結實橡木短棒，以及[松香藥膏](/protocol-10.html)所用的天然防水密封松香。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"步驟 1：劈開動物腿骨緻密骨並在沾水石英岩上磨出手指長度的骨針粗坯\",\n      \"description\": \"1. **緻密骨挑選與縱向敲劈**：選取鹿的脛骨，用[石斧或沉重卵石](/protocol-04.html)縱向擊裂，取得**手指長度（約7~8公分）、厚度3~4毫米**的細長緻密骨骨片。\\n2. **沾水石英岩粗磨**：在澆了水的粗石英岩板上以45度角反覆摩擦骨片，磨去粗糙的骨髓殘留物，修整成均勻的圓棒狀。\\n3. **研磨穿刺針尖**：將骨坯一端以30度角邊旋轉邊在石面上打磨，磨出**足以刺穿皮革的鋒利錐狀針尖**。\",\n      \"actionNote\": \"> 碎屑防護：敲擊骨頭時碎屑可能飛濺，擊打時面部請偏向一側45度。磨石必須隨時澆水保持濕潤，防止摩擦生熱使骨質碳化發脆。\",\n      \"svgFileName\": \"pr14-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // BONE SPLINTER BLANK PREPARATION\",\n        \"鹿腿脛骨緻密骨縱向劈開分離\",\n        \"澆水粗石英岩磨石表面修形研磨\",\n        \"手指長度（7~8CM）圓柱粗坯成形\",\n        \"[第1步重點] 30°旋轉研磨成鋒利穿刺針尖\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIELD BIOMECHANICS\",\n        \"title\": \"哺乳動物脛骨羥基磷灰石晶體結構與抗剪切韌性\",\n        \"text\": \"大型有蹄類動物的脛骨（Tibia）承載全身劇烈運動重量，骨壁由無海綿氣孔的高密度緻密骨（Cortical Bone）構成。鈣磷複合體羥基磷灰石晶體與彈性膠原纖維形成緻密的同心圓骨單位層板結構，經研磨後具備極高抗彎折韌性，能輕鬆穿透堅韌生皮而不致脆裂。\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"哺乳動物脛骨緻密骨骨片\",\n            \"scientificName\": \"Mammalian Tibia Cortical Bone\",\n            \"categoryTag\": \"野戰骨角器材料 / 高強度骨針粗坯\",\n            \"imageFileName\": \"id-deer-metatarsal-bone.jpg\",\n            \"hudCode\": \"FIG. BIO-14A // MACRO OPTIC\",\n            \"hudStatus\": \"DENSITY & FLEXURAL STRENGTH: HIGH\",\n            \"traits\": [\n              {\n                \"label\": \"色澤/COLOR\",\n                \"value\": \"骨髓內層微黃，外表面呈現**象牙白至淡奶油色**光澤。\"\n              },\n              {\n                \"label\": \"質地/DENSITY\",\n                \"value\": \"斷面平滑如玻璃，**完全沒有蜂窩狀海綿孔洞**的堅硬層。\"\n              },\n              {\n                \"label\": \"聲響/ACOUSTIC\",\n                \"value\": \"用石頭輕敲時不會發悶，能發出**如金屬般的清脆金石共鳴聲**。\"\n              }\n            ],\n            \"fieldUse\": \"挑選厚3~4mm縱向骨片，在石英岩磨石上打磨成骨針粗坯\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"步驟 2：用燧石錐在骨針頂部雙面對稱旋轉鑽出針孔（Eye）並以細砂拋光\",\n      \"description\": \"1. **雙面對稱旋轉鑽孔**：將尖銳的燧石錐（Flint Awl）尖端對準距骨針頂端**半個小指甲蓋寬（約5毫米）處**，在指間往復旋轉鑽入約一半深度；隨後翻轉骨身，從背面準確對齊對穿貫通。\\n2. **通道貫通與毛刺清除**：針孔貫通後，穿入細硬樹枝或乾硬植物尖刺高速旋轉刮拭，除去孔內鋒利的骨質毛刺以防割斷縫線。\\n3. **細微拋光**：用沾水的細黏土石或河砂全面搓磨針身，直到表面呈現**如玻璃珠般平滑的光澤**，確保穿透厚皮時毫無阻滯。\",\n      \"actionNote\": \"> 防針頭斷裂：單面強行鑽透會產生擴張應力導致針頭崩裂。務必遵照雙面各鑽一半的對稱沙漏型鑽孔法。\",\n      \"svgFileName\": \"pr14-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // DUAL-CONE EYE DRILLING & FINISHING\",\n        \"燧石錐（FLINT AWL）雙面對稱旋轉鑽孔\",\n        \"距針頭5MM處精確雙錐針孔（EYE）貫通\",\n        \"植物硬刺旋轉清除內部骨質毛刺\",\n        \"[第2步重點] 沾水細河砂拋光至玻璃鏡面光澤\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"步驟 3：用木棒輕敲風乾動物筋腱，梳理出如髮絲般的超強拉力膠原纖維線\",\n      \"description\": \"1. **放置乾燥筋腱**：將在陰涼通風處風乾成硬質琥珀色的筋腱條平放在光滑的扁平河石砧板上。\\n2. **木棒輕柔擊打**：用圓頭橡木短棒輕輕敲打筋條，震碎膠原纖維束之間的黏合基質（嚴禁重擊，否則纖維會被砸斷）。\\n3. **梳理纖維與唾液塑形**：用指尖將敲散發白的筋束撕拉分離成**3~4根頭髮絲粗細的長纖維**。在線頭塗抹少量唾液並搓捻，膠原蛋白遇濕軟化並聚攏，能極其滑順地穿過細小針孔。\",\n      \"actionNote\": \"> 擊打力度控制：嚴禁使用鋒利石刃砸擊筋腱。必須使用圓滑硬木短棒，以「震散纖維」的手感溫和叩擊。\",\n      \"svgFileName\": \"pr14-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DRIED ANIMAL SINEW FIBER SEPARATION\",\n        \"平坦河石砧板上放置乾燥筋腱（SINEW）\",\n        \"橡木棒輕柔擊打（震碎膠原蛋白束）\",\n        \"梳理抽離3~4根髮絲粗細的高抗拉纖維\",\n        \"[第3步重點] 唾液塗抹軟化線頭便於穿針引線\"\n      ],\n      \"deepDive\": {\n        \"badge\": \"FIBER SCIENCE\",\n        \"title\": \"動物筋腱Type I膠原蛋白交聯結構與風乾自鎖收縮力\",\n        \"text\": \"構成筋腱的Type I型膠原微原纖維具備50~100 MPa的超高抗拉強度，同等直徑下拉力為棉線的4倍以上。遇唾液或水潤濕時質地柔軟易於穿行；縫合完畢後在空氣中乾燥，體積會自行收縮3~5%，對皮革針孔產生強大的徑向夾緊力，即使不打繁複線結也絕不鬆脫。\",\n        \"fieldSpecs\": [\n          {\n            \"name\": \"風乾動物腿筋（乾燥筋線）\",\n            \"scientificName\": \"Dried Mammalian Tendon (Sinew)\",\n            \"categoryTag\": \"野外天然纖維 / 超高強度縫紉線\",\n            \"imageFileName\": \"id-dried-animal-sinew.jpg\",\n            \"hudCode\": \"FIG. BIO-14B // MACRO OPTIC\",\n            \"hudStatus\": \"TENSILE STRENGTH RATING: MAXIMUM\",\n            \"traits\": [\n              {\n                \"label\": \"外觀/TEXTURE\",\n                \"value\": \"透光看呈現**琥珀色角質般半透明堅硬**條狀。\"\n              },\n              {\n                \"label\": \"分解/SEPARATION\",\n                \"value\": \"敲打後散開為**如蠶絲般柔順銀白的微細纖維**。\"\n              },\n              {\n                \"label\": \"收縮/SHRINKAGE\",\n                \"value\": \"沾唾液變軟，風乾後如**鋼絲般緊繃收縮緊箍**。\"\n              }\n            ],\n            \"fieldUse\": \"撕解成細絲穿入骨針，用於皮具修補與石斧手柄緊密捆紮\"\n          }\n        ]\n      }\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"步驟 4：燧石錐預先穿透皮孔，雙向馬鞍針法（Saddle Stitch）縫合並以松香密封接縫\",\n      \"description\": \"1. **皮革邊緣預穿孔**：將撕裂的皮革邊緣**重疊一指節寬度**，用堅硬的燧石錐與木棒預先垂直打出一排**間距5毫米的針孔**。\\n2. **馬鞍針法（雙向交叉縫合）**：在筋線兩端各穿一根骨針，或用單針在孔洞中前後交叉穿行，每穿一針兩端用力拉緊。\\n3. **乾燥收縮與松香密封**：縫合完成後，待筋線乾燥收縮勒緊，將溫熱的[松香藥膏](/protocol-10.html)薄薄塗抹在整條縫合線上，形成**完全隔絕雨雪冰水與冷風的防寒防水屏障**。\",\n      \"actionNote\": \"> 嚴格遵守預穿孔：骨針縱向耐壓，但若強行用針頭頂刺厚重生皮極易折斷。必須先用燧石錐穿出孔洞，骨針僅作為牽引筋線穿過的導引工具。\",\n      \"svgFileName\": \"pr14-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // SADDLE STITCHING & PITCH SEALING\",\n        \"燧石錐5MM間距皮革預先穿孔引導\",\n        \"筋線雙向交叉馬鞍針法（SADDLE STITCH）\",\n        \"松樹松香藥膏縫合線接縫防水塗層\",\n        \"[第4步重點] 筋線乾燥自縮死死鎖閉針孔\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命錯誤：未經燧石錐預先打孔，用手掌死死頂住骨針頭部強行往厚硬濕皮革裡硬推\",\n    \"description\": \"未經預先穿孔而強行將骨針推入厚硬生皮中，橫向剪切力會使骨針頭部或針身瞬間折斷。斷裂的尖銳骨刺會深深刺入手掌或手指肉內，造成深層刺傷與致命的野戰破傷風感染。厚皮革務必先以硬質燧石錐與木棒垂直鑿出間距5mm的導引貫穿孔；骨針僅作為輕巧牽引筋線穿行通過的導引滑動工具。\",\n    \"consequence\": \"後果：骨針崩斷，手部深層骨刺刺傷及野戰破傷風感染風險\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"零下20度的暴風雪中靴子破了？2小時內雙腳凍爛甚至喪命。現在立即學會磨骨針！\",\n    \"body\": \"用石頭劈開鹿腿骨，在沾水的石英岩上磨出手指長度的骨針，拿燧石錐雙面旋轉鑽出針孔。接著拿木棍輕敲曬乾的動物筋腱，瞬間爆開比蠶絲還強韌4倍的膠原纖維線！沾點口水穿過針孔，用燧石在皮靴上打孔交叉縫合。筋線乾了之後像鋼絲一樣死死收縮，再抹上熱松香，防風防水的生皮革靴滿血復活！\",\n    \"outro\": \"文明崩潰野外求生，原始科技救你一命。點擊主頁離線獲取全套生存手冊！\"\n  },\n  \"outcome\": {\n    \"title\": \"野外修復完成的防寒皮靴與骨針·筋線縫紉套裝\",\n    \"badge\": \"驗收檢驗標準 // FIELD REPAIRED GEAR\",\n    \"standard\": \"骨針表面呈現鏡面光滑，針孔能容納兩股筋線順暢穿過，雙向馬鞍縫合的皮革接縫在雙手用力拉扯下無1毫米鬆脫裂隙\",\n    \"svgFileName\": \"pr14-outcome.svg\",\n    \"svgLabels\": [\n      \"PR-14 OUTCOME // BONE NEEDLE & SINEW SEWING KIT\",\n      \"製作完成的高密度象牙白緻密骨骨針（長7.5CM）\",\n      \"燧石錐雙向旋轉穿透精密針孔（直徑1.8MM）\",\n      \"經木棒輕敲分離之銀白色高抗拉筋線纖維束\",\n      \"馬鞍針法雙向縫合與松樹松香防水密封接縫\",\n      \"完全修復之防寒皮革靴（體溫流失100%隔絕）\",\n      \"FIELD VERIFIED // TENSILE STRENGTH RATED & WATERPROOF\"\n    ]\n  },\n  \"createdAt\": \"2026-10-22T08:09:29.733Z\",\n  \"updatedAt\": \"2026-10-22T08:14:43.819Z\",\n  \"contentHash\": \"614132e570544622\"\n}","content/svgs/02-step-01.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full max-w-2xl h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <pattern id=\"diag-hatch\" width=\"8\" height=\"8\" patternTransform=\"rotate(45 0 0)\" patternUnits=\"userSpaceOnUse\">\n      <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"8\" stroke=\"#333333\" stroke-width=\"1\" />\n    </pattern>\n    <marker id=\"arrow-white\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#F5F5F5\" />\n    </marker>\n    <marker id=\"arrow-red\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#E02424\" />\n    </marker>\n  </defs>\n\n  <!-- Outer Frame Guideline -->\n  <rect x=\"10\" y=\"10\" width=\"660\" height=\"320\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"4,4\" />\n\n  <!-- Ember Catcher Leaf positioned under the board & notch opening -->\n  <path d=\"M 180 260 C 240 250, 440 250, 500 260 C 515 285, 430 308, 340 308 C 250 308, 165 285, 180 260 Z\" \n        fill=\"#171717\" stroke=\"#666666\" stroke-width=\"1.2\" stroke-dasharray=\"3,3\" />\n  <text x=\"655\" y=\"298\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" text-anchor=\"end\">불씨 받침 나뭇잎</text>\n\n  <!-- Hearth Board 3D block (isometric projection) -->\n  <!-- Top Face -->\n  <polygon points=\"120,180 520,180 480,230 80,230\" fill=\"#1f1e1e\" stroke=\"#888888\" stroke-width=\"1.5\" />\n  <!-- Front Face (Thickness profile) -->\n  <polygon points=\"80,230 480,230 480,265 80,265\" fill=\"#141414\" stroke=\"#888888\" stroke-width=\"1.5\" />\n  <!-- Right Side Face -->\n  <polygon points=\"480,230 520,180 520,215 480,265\" fill=\"#181818\" stroke=\"#666666\" stroke-width=\"1.2\" />\n\n  <!-- Spindle Socket Hole on Top Surface -->\n  <ellipse cx=\"300\" cy=\"205\" rx=\"26\" ry=\"12\" fill=\"#0d0d0d\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" stroke-dasharray=\"2,2\" />\n  <circle cx=\"300\" cy=\"205\" r=\"4\" fill=\"#E02424\" />\n\n  <!-- 45-degree V-Notch carved from outer edge inward to socket center -->\n  <!-- Wedge cut into top surface and vertical front face -->\n  <polygon points=\"300,205 260,230 340,230\" fill=\"#0d0d0d\" stroke=\"#E02424\" stroke-width=\"2\" />\n  <!-- Vertical notch slot cut down through front edge -->\n  <polygon points=\"260,230 340,230 340,265 260,265\" fill=\"#080808\" stroke=\"#E02424\" stroke-width=\"1.5\" />\n\n  <!-- 45° Angle Indicator Arc inside Notch -->\n  <path d=\"M 285,215 A 20 20 0 0 0 315,215\" fill=\"none\" stroke=\"#E02424\" stroke-width=\"1.2\" />\n  <line x1=\"325\" y1=\"222\" x2=\"350\" y2=\"245\" stroke=\"#E02424\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n  <text x=\"355\" y=\"248\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"start\">45° V자 홈 (막대 중심까지 파기)</text>\n\n  <!-- Spindle Axis (Ghosted Shaft entering Socket) -->\n  <path d=\"M 286,45 L 314,45 L 314,175 L 300,205 L 286,175 Z\" fill=\"#242424\" fill-opacity=\"0.85\" stroke=\"#F5F5F5\" stroke-width=\"1.5\" />\n  <line x1=\"293\" y1=\"55\" x2=\"293\" y2=\"170\" stroke=\"#444444\" stroke-width=\"1\" />\n  <line x1=\"307\" y1=\"55\" x2=\"307\" y2=\"170\" stroke=\"#444444\" stroke-width=\"1\" />\n\n  <!-- Spindle Dimension lines (Ø 20mm) -->\n  <line x1=\"270\" y1=\"75\" x2=\"286\" y2=\"75\" stroke=\"#888888\" stroke-width=\"1\" marker-end=\"url(#arrow-white)\" />\n  <line x1=\"330\" y1=\"75\" x2=\"314\" y2=\"75\" stroke=\"#888888\" stroke-width=\"1\" marker-end=\"url(#arrow-white)\" />\n  <text x=\"340\" y=\"79\" fill=\"#E5E5E5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\">두께 2cm 가운데 회전 막대</text>\n\n  <!-- Hearth Board Thickness Dimension: 15~20mm -->\n  <line x1=\"65\" y1=\"230\" x2=\"65\" y2=\"265\" stroke=\"#888888\" stroke-width=\"1\" />\n  <line x1=\"60\" y1=\"230\" x2=\"70\" y2=\"230\" stroke=\"#888888\" stroke-width=\"1\" />\n  <line x1=\"60\" y1=\"265\" x2=\"70\" y2=\"265\" stroke=\"#888888\" stroke-width=\"1\" />\n  <text x=\"20\" y=\"282\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" text-anchor=\"start\">판 두께: 1.5~2cm</text>\n\n  <!-- Hearth Board label -->\n  <text x=\"130\" y=\"215\" fill=\"#AAAAAA\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\">바닥 받침 나무</text>\n\n  <!-- Notch Apex / Center Seating Pointer -->\n  <line x1=\"160\" y1=\"155\" x2=\"295\" y2=\"203\" stroke=\"#AAAAAA\" stroke-width=\"1\" stroke-dasharray=\"2,2\" marker-end=\"url(#arrow-white)\" />\n  <text x=\"110\" y=\"150\" fill=\"#CCCCCC\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">V자 홈 끝점 (구멍 한가운데와 일치)</text>\n\n  <!-- Rule Callout Box -->\n  <rect x=\"25\" y=\"25\" width=\"255\" height=\"44\" fill=\"#141414\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"35\" y=\"42\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">핵심 준비 포인트:</text>\n  <text x=\"35\" y=\"58\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\">V자 홈 끝이 막대 중심에 딱 닿아야 함</text>\n\n  <!-- Carbon Dust Accumulation Zone (Under Notch Opening) -->\n  <ellipse cx=\"300\" cy=\"278\" rx=\"35\" ry=\"8\" fill=\"#E02424\" fill-opacity=\"0.2\" stroke=\"#E02424\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n  <line x1=\"300\" y1=\"286\" x2=\"300\" y2=\"310\" stroke=\"#E02424\" stroke-width=\"1\" />\n  <text x=\"300\" y=\"322\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" text-anchor=\"middle\">까만 불씨 가루가 모이는 자리</text>\n</svg>\n","content/svgs/02-step-02.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full max-w-2xl h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arrow-white\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#F5F5F5\" />\n    </marker>\n    <marker id=\"arrow-red\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#E02424\" />\n    </marker>\n  </defs>\n\n  <!-- Grid borders -->\n  <rect x=\"10\" y=\"10\" width=\"660\" height=\"320\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"4,4\"/>\n\n  <!-- Hand Socket Block (Top Pressure Block) -->\n  <path d=\"M 285 25 L 375 25 L 390 55 L 270 55 Z\" fill=\"#222222\" stroke=\"#CCCCCC\" stroke-width=\"1.5\"/>\n  <text x=\"330\" y=\"42\" fill=\"#E5E5E5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" text-anchor=\"middle\">손잡이 누름판</text>\n\n  <!-- Vertical Force Vector F_down -->\n  <line x1=\"330\" y1=\"12\" x2=\"330\" y2=\"25\" stroke=\"#E02424\" stroke-width=\"2.5\" marker-end=\"url(#arrow-red)\"/>\n  <text x=\"345\" y=\"18\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" font-weight=\"bold\">위에서 체중 실어 누르기 (12~15kg)</text>\n\n  <!-- Spindle Axis (Rotating cylinder) -->\n  <rect x=\"318\" y=\"55\" width=\"24\" height=\"175\" fill=\"#1e1e1e\" stroke=\"#F5F5F5\" stroke-width=\"1.5\"/>\n  \n  <!-- Bow Cord Looped Around Spindle (1 Turn Loop) -->\n  <!-- Bow Stick -->\n  <path d=\"M 60 135 C 180 110, 480 110, 600 135\" fill=\"none\" stroke=\"#888888\" stroke-width=\"6\" stroke-linecap=\"square\"/>\n  <text x=\"110\" y=\"102\" fill=\"#AAAAAA\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\">활대 (길이 65cm 휘어진 나뭇가지)</text>\n\n  <!-- String with Tension & Single Wrap Loop around Spindle -->\n  <path d=\"M 60 135 L 318 140\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <ellipse cx=\"330\" cy=\"142\" rx=\"16\" ry=\"6\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"2.5\"/>\n  <path d=\"M 342 144 L 600 135\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n\n  <!-- Horizontal Bow Stroke Sawing Arrows -->\n  <line x1=\"180\" y1=\"160\" x2=\"480\" y2=\"160\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" stroke-dasharray=\"4,4\"/>\n  <line x1=\"230\" y1=\"160\" x2=\"190\" y2=\"160\" stroke=\"#E5E5E5\" stroke-width=\"2\" marker-end=\"url(#arrow-white)\"/>\n  <line x1=\"430\" y1=\"160\" x2=\"470\" y2=\"160\" stroke=\"#E5E5E5\" stroke-width=\"2\" marker-end=\"url(#arrow-white)\"/>\n  <text x=\"330\" y=\"175\" fill=\"#E5E5E5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" text-anchor=\"middle\">활대 끝에서 끝까지 길게 당기고 밀기</text>\n\n  <!-- Rotation RPM Velocity Vector -->\n  <path d=\"M 360 85 A 25 15 0 1 1 360 105\" fill=\"none\" stroke=\"#E02424\" stroke-width=\"2\" marker-end=\"url(#arrow-red)\"/>\n  <text x=\"385\" y=\"98\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" font-weight=\"bold\">빠르게 양방향 회전</text>\n\n  <!-- Hearth Board Base -->\n  <rect x=\"200\" y=\"230\" width=\"260\" height=\"40\" fill=\"#141414\" stroke=\"#888888\" stroke-width=\"1.5\"/>\n  <text x=\"210\" y=\"254\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">바닥 받침 나무</text>\n\n  <!-- Friction Contact Heat & Smoke Generation Point -->\n  <circle cx=\"330\" cy=\"230\" r=\"5\" fill=\"#E02424\"/>\n  \n  <!-- Thermal Wave / Heat Glow Ring -->\n  <circle cx=\"330\" cy=\"230\" r=\"14\" fill=\"none\" stroke=\"#E02424\" stroke-width=\"1\" stroke-dasharray=\"2,2\"/>\n  <circle cx=\"330\" cy=\"230\" r=\"24\" fill=\"none\" stroke=\"#E02424\" stroke-width=\"0.8\" stroke-dasharray=\"1,3\"/>\n  \n  <!-- Smoke Stream SVG Paths -->\n  <path d=\"M 326 225 Q 315 210 322 195 T 310 180\" fill=\"none\" stroke=\"#A3A3A3\" stroke-width=\"1.5\" stroke-dasharray=\"2,2\"/>\n  <path d=\"M 334 225 Q 345 208 338 190 T 350 175\" fill=\"none\" stroke=\"#A3A3A3\" stroke-width=\"1.5\" stroke-dasharray=\"2,2\"/>\n  <path d=\"M 330 220 Q 330 200 325 185\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"1\"/>\n\n  <text x=\"295\" y=\"210\" fill=\"#CCCCCC\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" text-anchor=\"end\">하얀 연기가 피어오름</text>\n\n  <!-- Technical Specification Box on the right -->\n  <rect x=\"490\" y=\"215\" width=\"170\" height=\"70\" fill=\"#141414\" stroke=\"#333333\" stroke-width=\"1\"/>\n  <text x=\"500\" y=\"232\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">불씨 만드는 핵심:</text>\n  <text x=\"500\" y=\"248\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">마찰 열기: 400°C 이상</text>\n  <text x=\"500\" y=\"262\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">누르는 힘: 약하게 → 세게</text>\n  <text x=\"500\" y=\"276\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">활대 전체 길이를 끝까지 사용</text>\n</svg>\n","content/svgs/02-step-03.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full max-w-2xl h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arrow-white\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#F5F5F5\" />\n    </marker>\n  </defs>\n\n  <rect x=\"10\" y=\"10\" width=\"660\" height=\"320\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"4,4\"/>\n\n  <!-- LEFT SIDE: TINDER NEST & AIRFLOW DYNAMICS -->\n  <!-- Tinder Nest Cup Profile (Bird's nest shape) -->\n  <path d=\"M 60 250 C 90 280, 230 280, 260 250 C 270 210, 240 180, 160 170 C 80 180, 50 210, 60 250 Z\" \n        fill=\"#181818\" stroke=\"#777777\" stroke-width=\"1.5\"/>\n  <!-- Fibers pattern inside nest -->\n  <path d=\"M 70 230 Q 160 255 250 230\" fill=\"none\" stroke=\"#444444\" stroke-width=\"1\"/>\n  <path d=\"M 80 210 Q 160 240 240 210\" fill=\"none\" stroke=\"#444444\" stroke-width=\"1\"/>\n  <path d=\"M 95 195 Q 160 225 225 195\" fill=\"none\" stroke=\"#444444\" stroke-width=\"1\"/>\n\n  <!-- Central Ember Core (Glowing Hot Carbon Coal) -->\n  <ellipse cx=\"160\" cy=\"220\" rx=\"14\" ry=\"10\" fill=\"#E02424\" stroke=\"#FFAA00\" stroke-width=\"1.5\"/>\n  <circle cx=\"160\" cy=\"220\" r=\"4\" fill=\"#FFEE55\"/>\n  <text x=\"160\" y=\"292\" fill=\"#FFAA00\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">달궈진 불씨 덩어리 (450°C)</text>\n\n  <!-- Gentle Air Stream Vectors (Breathing 45-degree angle vectors) -->\n  <path d=\"M 70 120 C 100 130, 120 160, 150 195\" fill=\"none\" stroke=\"#00D4FF\" stroke-width=\"1.5\" stroke-dasharray=\"4,3\" marker-end=\"url(#arrow-white)\"/>\n  <path d=\"M 90 105 C 120 120, 135 155, 158 190\" fill=\"none\" stroke=\"#00D4FF\" stroke-width=\"1.5\" stroke-dasharray=\"4,3\" marker-end=\"url(#arrow-white)\"/>\n  <text x=\"75\" y=\"95\" fill=\"#00D4FF\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\">길고 부드럽게 입김 불기</text>\n\n  <!-- Smoke and Flame Transition Emitters -->\n  <path d=\"M 160 195 Q 150 150 170 110 T 165 70\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n  <path d=\"M 170 195 Q 185 145 175 105 T 190 65\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n  \n  <!-- Ignition Flame Burst Outline (Transient stage) -->\n  <path d=\"M 160 160 Q 140 120 160 90 Q 180 120 160 160 Z\" fill=\"#E02424\" fill-opacity=\"0.3\" stroke=\"#E02424\" stroke-width=\"1.5\"/>\n  <text x=\"160\" y=\"55\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">불꽃이 확 피어오름</text>\n\n  <!-- Cupping Angle 45° Spec -->\n  <line x1=\"260\" y1=\"250\" x2=\"310\" y2=\"200\" stroke=\"#888888\" stroke-width=\"1\" stroke-dasharray=\"2,2\"/>\n  <text x=\"275\" y=\"268\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\">45도 기울여 들기</text>\n\n  <!-- RIGHT SIDE: TEMPERATURE IGNITION THRESHOLD GRAPH -->\n  <rect x=\"360\" y=\"45\" width=\"295\" height=\"255\" fill=\"#141414\" stroke=\"#333333\" stroke-width=\"1\"/>\n  <text x=\"375\" y=\"68\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">입김 불어 불붙이는 온도 변화</text>\n\n  <!-- Graph Axes -->\n  <line x1=\"410\" y1=\"260\" x2=\"630\" y2=\"260\" stroke=\"#666666\" stroke-width=\"1\"/>\n  <line x1=\"410\" y1=\"260\" x2=\"410\" y2=\"90\" stroke=\"#666666\" stroke-width=\"1\"/>\n\n  <text x=\"630\" y=\"276\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" text-anchor=\"end\">시간 (초)</text>\n  <text x=\"375\" y=\"95\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">온도 (°C)</text>\n\n  <!-- Threshold Line 600°C Flame Point -->\n  <line x1=\"410\" y1=\"125\" x2=\"630\" y2=\"125\" stroke=\"#E02424\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/>\n  <text x=\"415\" y=\"120\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">600°C 불꽃이 타오르는 온도</text>\n\n  <!-- Threshold Line 400°C Ember Point -->\n  <line x1=\"410\" y1=\"185\" x2=\"630\" y2=\"185\" stroke=\"#FFAA00\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/>\n  <text x=\"415\" y=\"180\" fill=\"#FFAA00\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">400°C 불씨가 유지되는 온도</text>\n\n  <!-- Temperature Curve Line -->\n  <path d=\"M 410 255 Q 460 240 500 185 T 570 125 T 620 100\" fill=\"none\" stroke=\"#F5F5F5\" stroke-width=\"2.5\"/>\n  \n  <!-- Key Milestone Dots -->\n  <circle cx=\"500\" cy=\"185\" r=\"4\" fill=\"#FFAA00\"/>\n  <circle cx=\"570\" cy=\"125\" r=\"4\" fill=\"#E02424\"/>\n  \n  <text x=\"505\" y=\"202\" fill=\"#FFAA00\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\">30초 기다린 뒤 옮기기 (0초)</text>\n  <text x=\"650\" y=\"145\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\" font-weight=\"bold\" text-anchor=\"end\">불꽃 점화 (15~20초)</text>\n</svg>\n","content/svgs/03-step-01.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-03 [DEBRIS-HUT-SHELTER]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 01</text>\n\n  <!-- 지면 기준선 -->\n  <line x1=\"40\" y1=\"280\" x2=\"360\" y2=\"280\" stroke=\"#404040\" stroke-width=\"2\"/>\n  <line x1=\"40\" y1=\"285\" x2=\"360\" y2=\"285\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"2 4\"/>\n\n  <!-- 지지 바위 / 밑동 그루터기 (Fork / Boulder) -->\n  <polygon points=\"60,280 80,180 120,180 140,280\" fill=\"#141414\" stroke=\"#737373\" stroke-width=\"1.5\"/>\n  <text x=\"100\" y=\"240\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\">STUMP FORK</text>\n\n  <!-- 3m 주 기둥 (Ridge Pole: 지지대 1m 높이에서 지면으로 경사) -->\n  <line x1=\"100\" y1=\"180\" x2=\"340\" y2=\"280\" stroke=\"#FFFFFF\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n  <line x1=\"100\" y1=\"180\" x2=\"340\" y2=\"280\" stroke=\"#000000\" stroke-width=\"2\" stroke-linecap=\"round\"/>\n\n  <!-- 치수선: 지지 높이 1m -->\n  <line x1=\"50\" y1=\"180\" x2=\"50\" y2=\"280\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <path d=\"M47 185 L50 180 L53 185 M47 275 L50 280 L53 275\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <text x=\"42\" y=\"235\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"end\" font-weight=\"bold\">1.0m</text>\n\n  <!-- 치수선: 주 기둥 길이 3m -->\n  <line x1=\"110\" y1=\"165\" x2=\"345\" y2=\"265\" stroke=\"#A3A3A3\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"235\" y=\"205\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">RIDGE POLE (3.0m)</text>\n\n  <!-- 1인 누운 신체 치수 프로파일 (점선) -->\n  <ellipse cx=\"220\" cy=\"270\" rx=\"45\" ry=\"8\" fill=\"none\" stroke=\"#525252\" stroke-width=\"1.5\" stroke-dasharray=\"3 3\"/>\n  <circle cx=\"165\" cy=\"265\" r=\"7\" fill=\"none\" stroke=\"#525252\" stroke-width=\"1.5\" stroke-dasharray=\"2 2\"/>\n  <text x=\"210\" y=\"255\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">BODY FIT SPACE</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 01: RIDGE POLE &amp; STRUCTURAL ANCHOR</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">SECURE 3m HARDWOOD AT 1m CREST TO MINIMIZE INTERNAL AIR VOLUME</text>\n</svg>\n","content/svgs/03-step-02.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-03 [DEBRIS-HUT-SHELTER]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 02</text>\n\n  <!-- 지면 기준선 -->\n  <line x1=\"40\" y1=\"280\" x2=\"360\" y2=\"280\" stroke=\"#404040\" stroke-width=\"2\"/>\n\n  <!-- 주 기둥 (중앙) -->\n  <line x1=\"80\" y1=\"160\" x2=\"320\" y2=\"280\" stroke=\"#E5E5E5\" stroke-width=\"5\"/>\n\n  <!-- 좌우 45도 빗살 갈비뼈 잔가지 (Rib Poles) -->\n  <!-- 좌측 날개 -->\n  <line x1=\"110\" y1=\"175\" x2=\"70\" y2=\"280\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <line x1=\"140\" y1=\"190\" x2=\"105\" y2=\"280\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <line x1=\"170\" y1=\"205\" x2=\"140\" y2=\"280\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <line x1=\"200\" y1=\"220\" x2=\"175\" y2=\"280\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <line x1=\"230\" y1=\"235\" x2=\"210\" y2=\"280\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <line x1=\"260\" y1=\"250\" x2=\"245\" y2=\"280\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <line x1=\"290\" y1=\"265\" x2=\"280\" y2=\"280\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n\n  <!-- 우측 날개 (원근 입체 표현) -->\n  <line x1=\"110\" y1=\"175\" x2=\"160\" y2=\"280\" stroke=\"#737373\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n  <line x1=\"140\" y1=\"190\" x2=\"195\" y2=\"280\" stroke=\"#737373\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n  <line x1=\"170\" y1=\"205\" x2=\"230\" y2=\"280\" stroke=\"#737373\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n  <line x1=\"200\" y1=\"220\" x2=\"265\" y2=\"280\" stroke=\"#737373\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n  <line x1=\"230\" y1=\"235\" x2=\"300\" y2=\"280\" stroke=\"#737373\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n\n  <!-- 가로 엮음 격자망 (Lattice Framework) -->\n  <path d=\"M 65 250 Q 150 200 235 250\" fill=\"none\" stroke=\"#A3A3A3\" stroke-width=\"1.5\"/>\n  <path d=\"M 75 220 Q 130 185 195 220\" fill=\"none\" stroke=\"#A3A3A3\" stroke-width=\"1.5\"/>\n\n  <!-- 45도 각도 호선 인디케이터 -->\n  <path d=\"M 120 280 A 25 25 0 0 1 135 258\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <text x=\"145\" y=\"270\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">45° SLOPE</text>\n\n  <!-- 간격 표시 (10cm Spacing) -->\n  <line x1=\"70\" y1=\"290\" x2=\"105\" y2=\"290\" stroke=\"#737373\" stroke-width=\"1\"/>\n  <text x=\"87\" y=\"303\" fill=\"#737373\" font-family=\"monospace\" font-size=\"8\" text-anchor=\"middle\">&lt; 10cm &gt;</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 02: 45° RIB SKELETON &amp; LATTICE</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">DENSELY PACK RIBS EVERY 10cm TO PREVENT DEBRIS COLLAPSE</text>\n</svg>\n","content/svgs/03-step-03.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-03 [DEBRIS-HUT-SHELTER]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 03</text>\n\n  <!-- 지면 기준선 -->\n  <line x1=\"40\" y1=\"280\" x2=\"360\" y2=\"280\" stroke=\"#404040\" stroke-width=\"2\"/>\n\n  <!-- 1m 외부 낙엽 돔 윤곽선 (Debris Mound) -->\n  <path d=\"M 50 280 Q 90 90 200 90 Q 310 90 350 280 Z\" fill=\"#141414\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <!-- 내부 골조 단면 (점선) -->\n  <path d=\"M 100 280 Q 130 180 200 180 Q 270 180 300 280\" fill=\"#050505\" stroke=\"#737373\" stroke-width=\"1.5\" stroke-dasharray=\"3 3\"/>\n\n  <!-- 바닥 40cm 마른 낙엽 단열 매트리스 (Ground Insulation) -->\n  <rect x=\"105\" y=\"245\" width=\"190\" height=\"35\" fill=\"#262626\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <line x1=\"105\" y1=\"262\" x2=\"295\" y2=\"262\" stroke=\"#525252\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n  <text x=\"200\" y=\"267\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"bold\">40cm GROUND BED [LEAVES]</text>\n\n  <!-- 외벽 1m 두께 치수선 -->\n  <line x1=\"75\" y1=\"180\" x2=\"140\" y2=\"210\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <path d=\"M 78 186 L 75 180 L 82 178 M 133 212 L 140 210 L 137 204\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <text x=\"100\" y=\"188\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"11\" font-weight=\"black\">1.0m THICK</text>\n\n  <!-- 외벽 솔잎 비늘 빗물 유도 층 (Thatch / Pine Shingles) -->\n  <path d=\"M 120 120 L 110 135 M 140 105 L 130 120 M 260 105 L 270 120 M 280 120 L 290 135\" stroke=\"#A3A3A3\" stroke-width=\"1.5\"/>\n  <text x=\"200\" y=\"115\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\">WATER-SHEDDING PINE THATCH</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 03: 1m DEBRIS MOUND &amp; 40cm BED</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">NEVER SLEEP ON BARE GROUND; PILE LEAVES ARM-DEEP TO SEAL BODY HEAT</text>\n</svg>\n","content/svgs/04-step-01.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-04 [PRIMITIVE-STONE-AXE]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 01</text>\n\n  <!-- 작업대 받침돌 (Anvil Stone) -->\n  <polygon points=\"100,280 140,220 260,220 300,280\" fill=\"#141414\" stroke=\"#737373\" stroke-width=\"2\"/>\n  <text x=\"200\" y=\"260\" fill=\"#525252\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\">ANVIL STONE</text>\n\n  <!-- 가공할 규암 원석 도끼날 (Quartzite Core) -->\n  <polygon points=\"150,220 180,130 230,130 250,220\" fill=\"#262626\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n\n  <!-- 둥근 망치돌 (Hammerstone) -->\n  <circle cx=\"270\" cy=\"100\" r=\"28\" fill=\"#1A1A1A\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <text x=\"270\" y=\"104\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"8\" text-anchor=\"middle\">HAMMER</text>\n\n  <!-- 70도 타격 궤적 벡터 화살표 -->\n  <path d=\"M 255 125 L 215 155\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n  <polygon points=\"215,155 228,148 221,140\" fill=\"#FFFFFF\"/>\n  <text x=\"260\" y=\"145\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">70° STRIKE</text>\n\n  <!-- 박편 파편 비산 궤적 (Flakes Splitting) -->\n  <polygon points=\"175,145 160,160 170,170\" fill=\"#737373\" stroke=\"#A3A3A3\" stroke-width=\"1\"/>\n  <polygon points=\"140,180 120,195 135,205\" fill=\"#737373\" stroke=\"#A3A3A3\" stroke-width=\"1\"/>\n  <line x1=\"180\" y1=\"150\" x2=\"130\" y2=\"190\" stroke=\"#737373\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n  <text x=\"110\" y=\"175\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"9\">CHIPPED FLAKES</text>\n\n  <!-- 양날 각도 표시 -->\n  <path d=\"M 180 130 L 165 110 M 230 130 L 245 110\" stroke=\"#E5E5E5\" stroke-width=\"1\"/>\n  <text x=\"205\" y=\"115\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"bold\">BIFACIAL BEVEL</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 01: 70° HAMMERSTONE PERCUSSION FLAKING</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">STRIKE QUARTZITE RIM AT 70° TO DETACH RAZOR SHARP BIFACIAL FLAKES</text>\n</svg>\n","content/svgs/04-step-02.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-04 [PRIMITIVE-STONE-AXE]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 02</text>\n\n  <!-- 참나무 Y자 손잡이 (Hardwood Y-Haft) -->\n  <!-- 메인 손잡이 몸체 -->\n  <rect x=\"185\" y=\"160\" width=\"30\" height=\"130\" fill=\"#141414\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <!-- Y자 갈래 좌측/우측 포크 -->\n  <path d=\"M 185 160 Q 170 120 145 90 L 165 80 Q 195 115 200 140 Q 205 115 235 80 L 255 90 Q 230 120 215 160 Z\" fill=\"#1A1A1A\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n\n  <!-- 가공된 석기 도끼날 (결합 위치) -->\n  <polygon points=\"120,110 200,60 280,110 230,170 170,170\" fill=\"#262626\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <!-- 날 부분 강조선 -->\n  <path d=\"M 120 110 L 200 60 L 280 110\" stroke=\"#FFFFFF\" stroke-width=\"3\"/>\n  <text x=\"200\" y=\"85\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"bold\">AXE BLADE</text>\n\n  <!-- 요철 결합 음각 가공 표시 (Notch Fit) -->\n  <line x1=\"170\" y1=\"170\" x2=\"160\" y2=\"190\" stroke=\"#A3A3A3\" stroke-width=\"1\"/>\n  <line x1=\"230\" y1=\"170\" x2=\"240\" y2=\"190\" stroke=\"#A3A3A3\" stroke-width=\"1\"/>\n  <text x=\"200\" y=\"200\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\">FIRE-CARVED MORTISE SEAT</text>\n\n  <!-- 손잡이 규격 치수 -->\n  <line x1=\"225\" y1=\"225\" x2=\"265\" y2=\"225\" stroke=\"#737373\" stroke-width=\"1\"/>\n  <text x=\"270\" y=\"228\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">Ø 3.5cm OAK</text>\n\n  <!-- 압입 방향 화살표 (Downward Force) -->\n  <line x1=\"200\" y1=\"35\" x2=\"200\" y2=\"55\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <polygon points=\"200,55 195,45 205,45\" fill=\"#FFFFFF\"/>\n  <text x=\"200\" y=\"30\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\">PRESSURE FIT</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 02: Y-FORK NOTCH FIT &amp; CHARRED SEAT</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">SLIGHTLY CHAR WOOD INTERIOR TO MOLD NEGATIVE CAVITY EXACTLY TO BLADE</text>\n</svg>\n","content/svgs/04-step-03.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-04 [PRIMITIVE-STONE-AXE]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 03</text>\n\n  <!-- 조립된 도끼 손잡이 및 석기 날 -->\n  <rect x=\"185\" y=\"160\" width=\"30\" height=\"130\" fill=\"#141414\" stroke=\"#737373\" stroke-width=\"1.5\"/>\n  <polygon points=\"130,110 200,60 270,110 225,170 175,170\" fill=\"#262626\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n\n  <!-- 8자형 교차 칡 섬유 바인딩 (Figure-8 Lashings) -->\n  <line x1=\"140\" y1=\"120\" x2=\"230\" y2=\"190\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n  <line x1=\"145\" y1=\"130\" x2=\"225\" y2=\"200\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n  <line x1=\"150\" y1=\"140\" x2=\"220\" y2=\"210\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n\n  <line x1=\"260\" y1=\"120\" x2=\"170\" y2=\"190\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n  <line x1=\"255\" y1=\"130\" x2=\"175\" y2=\"200\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n  <line x1=\"250\" y1=\"140\" x2=\"180\" y2=\"210\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n\n  <!-- 수평 감기 밴드 (Frapping Turns) -->\n  <rect x=\"175\" y=\"155\" width=\"50\" height=\"25\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"2\" stroke-dasharray=\"3 2\"/>\n\n  <!-- 송진 + 숯가루 혼합 코팅층 (Black Pine Pitch Cement) -->\n  <path d=\"M 160 145 Q 200 135 240 145 Q 235 215 200 215 Q 165 215 160 145 Z\" fill=\"#0A0A0A\" fill-opacity=\"0.7\" stroke=\"#FFFFFF\" stroke-width=\"1.5\" stroke-dasharray=\"2 3\"/>\n  <text x=\"200\" y=\"235\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"black\">PINE PITCH + CHARCOAL CEMENT</text>\n\n  <!-- 수축 장력 화살표 (Shrinkage Tension) -->\n  <path d=\"M 140 185 L 160 175 M 260 185 L 240 175\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <text x=\"80\" y=\"190\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"9\">WET KUDZU SHRINKAGE</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 03: FIGURE-8 LASHINGS &amp; RESIN SEAL</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">WET FIBERS SHRINK TIGHT LIKE IRON; SEAL WITH CHARCOAL PITCH TO LOCK</text>\n</svg>\n","content/svgs/05-step-01.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-05 [EDIBLE-PLANT-TEST]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 01</text>\n\n  <!-- 절단된 식물 줄기 단면 (Cut Stem) -->\n  <rect x=\"180\" y=\"110\" width=\"40\" height=\"110\" fill=\"#141414\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <ellipse cx=\"200\" cy=\"110\" rx=\"20\" ry=\"8\" fill=\"#262626\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n\n  <!-- 유백색 독성 유즙 방출 (Milky White Sap Drop) -->\n  <path d=\"M 195 118 Q 190 145 200 155 Q 210 145 205 118 Z\" fill=\"#FFFFFF\" stroke=\"#E5E5E5\" stroke-width=\"1\"/>\n  <ellipse cx=\"200\" cy=\"170\" rx=\"12\" ry=\"16\" fill=\"#FFFFFF\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  \n  <!-- 치명적 독성 금지 표식 (Disallowed Cross) -->\n  <circle cx=\"200\" cy=\"170\" r=\"32\" fill=\"none\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <line x1=\"177\" y1=\"147\" x2=\"223\" y2=\"193\" stroke=\"#FFFFFF\" stroke-width=\"3\"/>\n  <line x1=\"223\" y1=\"147\" x2=\"177\" y2=\"193\" stroke=\"#FFFFFF\" stroke-width=\"3\"/>\n\n  <!-- 배제 판별 텍스트 박스 -->\n  <rect x=\"50\" y=\"235\" width=\"300\" height=\"60\" fill=\"#0A0A0A\" stroke=\"#404040\" stroke-width=\"1\"/>\n  <text x=\"65\" y=\"255\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">1. MILKY SAP (LATEX ALKALOIDS) ➔ DISCARD</text>\n  <text x=\"65\" y=\"272\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\">2. BITTER ALMOND ODOR (CYANIDE) ➔ DISCARD</text>\n  <text x=\"65\" y=\"287\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"10\">3. FINE STINGING HAIRS ➔ DISCARD</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 01: IMMEDIATE VISUAL &amp; OLFACTORY EXCLUSION</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">IMMEDIATELY REJECT ANY SPECIMEN WITH MILKY SAP OR ALMOND SCENT</text>\n</svg>\n","content/svgs/05-step-02.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-05 [EDIBLE-PLANT-TEST]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 02</text>\n\n  <!-- 사람 팔 전완부 윤곽선 (Inner Forearm) -->\n  <path d=\"M 60 160 C 120 155 240 150 340 140 L 340 220 C 240 215 120 220 60 210 Z\" fill=\"#141414\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <text x=\"90\" y=\"190\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\">INNER FOREARM</text>\n\n  <!-- 식물 즙 도포 테스트 스팟 (Test Patch) -->\n  <circle cx=\"210\" cy=\"180\" r=\"18\" fill=\"none\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <circle cx=\"210\" cy=\"180\" r=\"26\" fill=\"none\" stroke=\"#737373\" stroke-width=\"1\" stroke-dasharray=\"3 3\"/>\n  <!-- 즙 도포 화살표 -->\n  <path d=\"M 210 110 L 210 155\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <polygon points=\"210,155 205,145 215,145\" fill=\"#FFFFFF\"/>\n  <text x=\"210\" y=\"100\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"bold\">RUB CRUSHED SAP</text>\n\n  <!-- 15분 경과 스톱워치 다이얼 (15 MIN Stopwatch) -->\n  <circle cx=\"290\" cy=\"180\" r=\"30\" fill=\"#0A0A0A\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <line x1=\"290\" y1=\"180\" x2=\"290\" y2=\"155\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <line x1=\"290\" y1=\"180\" x2=\"315\" y2=\"180\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <path d=\"M 290 155 A 25 25 0 0 1 315 180\" fill=\"none\" stroke=\"#FFFFFF\" stroke-width=\"3\"/>\n  <text x=\"290\" y=\"225\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"bold\">15 MIN WAIT</text>\n\n  <!-- 이상 반응 감시 체크리스트 -->\n  <rect x=\"50\" y=\"240\" width=\"300\" height=\"55\" fill=\"#0A0A0A\" stroke=\"#404040\" stroke-width=\"1\"/>\n  <text x=\"65\" y=\"260\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\">OBSERVE: ERYTHEMA / ITCHING / HIVES</text>\n  <text x=\"65\" y=\"278\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">&gt; IF BURNING SENSATION OCCURS ➔ RINSE IMMEDIATELY</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 02: DERMAL CONTACT &amp; 15-MINUTE MONITORING</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">RUB JUICE ON SENSITIVE INNER ARM; WAIT 15 MIN FOR HISTAMINE REACTION</text>\n</svg>\n","content/svgs/05-step-03.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-05 [EDIBLE-PLANT-TEST]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 03</text>\n\n  <!-- 입술 및 혀 측면 프로파일 도해 (Oral Profile) -->\n  <path d=\"M 120 120 Q 170 120 190 140 Q 210 160 180 180 Q 210 190 190 220 Q 150 230 110 230\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <!-- 혀 (Tongue Extended) -->\n  <path d=\"M 175 175 C 220 170 250 185 240 200 C 220 210 185 200 175 195\" fill=\"#1F1F1F\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <text x=\"210\" y=\"195\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"9\" font-weight=\"bold\">TONGUE TIP</text>\n\n  <!-- 식물 잎 미세 조각 안치 (Specimen Fragment) -->\n  <polygon points=\"245,185 260,180 255,195 240,195\" fill=\"#FFFFFF\" stroke=\"#E5E5E5\" stroke-width=\"1\"/>\n  <line x1=\"260\" y1=\"160\" x2=\"252\" y2=\"182\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n  <text x=\"265\" y=\"155\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"9\" font-weight=\"bold\">LEAF PIECE (15 MIN)</text>\n\n  <!-- 침 삼킴 금지 경고 배지 (DO NOT SWALLOW) -->\n  <rect x=\"220\" y=\"80\" width=\"130\" height=\"40\" fill=\"#121212\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n  <text x=\"285\" y=\"98\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"black\">DO NOT SWALLOW</text>\n  <text x=\"285\" y=\"112\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"8\" text-anchor=\"middle\">HOLD SALIVA IN MOUTH</text>\n\n  <!-- 단계별 시간 프로토콜 -->\n  <rect x=\"50\" y=\"240\" width=\"300\" height=\"55\" fill=\"#0A0A0A\" stroke=\"#404040\" stroke-width=\"1\"/>\n  <text x=\"65\" y=\"258\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\">STEP A: OUTER LIP CONTACT ➔ 3 MINUTES</text>\n  <text x=\"65\" y=\"275\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\">STEP B: TONGUE TIP CONTACT ➔ 15 MINUTES</text>\n  <text x=\"65\" y=\"290\" fill=\"#737373\" font-family=\"monospace\" font-size=\"8\">&gt; IF NUMBNESS OR BITTERNESS ➔ SPIT &amp; RINSE x3</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 03: LIP &amp; TONGUE TIP PROGRESSIVE CHECK</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">NEVER CHEW OR SWALLOW; DETECT NUMBNESS BEFORE ANY INGESTION</text>\n</svg>\n","content/svgs/06-step-01.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-06 [SOLAR-STILL-WATER]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 01</text>\n\n  <!-- 지표면 선 -->\n  <line x1=\"40\" y1=\"180\" x2=\"360\" y2=\"180\" stroke=\"#404040\" stroke-width=\"2\"/>\n  <text x=\"50\" y=\"170\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">GROUND LEVEL</text>\n\n  <!-- 깔때기형 원형 웅덩이 단면 (Pit Excavation) -->\n  <path d=\"M 80 180 Q 140 280 200 280 Q 260 280 320 180\" fill=\"#121212\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n\n  <!-- 직경 1.0m 치수선 -->\n  <line x1=\"80\" y1=\"160\" x2=\"320\" y2=\"160\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <path d=\"M 85 155 L 80 160 L 85 165 M 315 155 L 320 160 L 315 165\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <text x=\"200\" y=\"152\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"bold\">DIAMETER 1.0m</text>\n\n  <!-- 깊이 50cm 치수선 -->\n  <line x1=\"340\" y1=\"180\" x2=\"340\" y2=\"280\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <path d=\"M 335 185 L 340 180 L 345 185 M 335 275 L 340 280 L 345 275\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"235\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">0.5m</text>\n\n  <!-- 바닥 중앙 토기 안착 홈 (Pot Hollow) -->\n  <rect x=\"180\" y=\"275\" width=\"40\" height=\"15\" fill=\"#262626\" stroke=\"#737373\" stroke-width=\"1\"/>\n  <text x=\"200\" y=\"298\" fill=\"#737373\" font-family=\"monospace\" font-size=\"8\" text-anchor=\"middle\">POT HOLLOW</text>\n\n  <!-- 경사벽 생 잎사귀 충진 (Transpiration Foliage) -->\n  <circle cx=\"120\" cy=\"210\" r=\"12\" fill=\"#1C1C1C\" stroke=\"#A3A3A3\" stroke-width=\"1\"/>\n  <circle cx=\"150\" cy=\"245\" r=\"10\" fill=\"#1C1C1C\" stroke=\"#A3A3A3\" stroke-width=\"1\"/>\n  <circle cx=\"280\" cy=\"210\" r=\"12\" fill=\"#1C1C1C\" stroke=\"#A3A3A3\" stroke-width=\"1\"/>\n  <circle cx=\"250\" cy=\"245\" r=\"10\" fill=\"#1C1C1C\" stroke=\"#A3A3A3\" stroke-width=\"1\"/>\n  <text x=\"135\" y=\"230\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"8\">NON-TOXIC LEAVES (2x YIELD)</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 01: 1m CONICAL PIT &amp; FOLIAGE PACK</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">DIG 1m x 0.5m PIT IN SUNNY GROUND; PACK WITH EDIBLE LEAVES FOR TRANSPIRATION</text>\n</svg>\n","content/svgs/06-step-02.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-06 [SOLAR-STILL-WATER]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 02</text>\n\n  <!-- 지표면 및 웅덩이 -->\n  <line x1=\"40\" y1=\"180\" x2=\"80\" y2=\"180\" stroke=\"#404040\" stroke-width=\"2\"/>\n  <line x1=\"320\" y1=\"180\" x2=\"360\" y2=\"180\" stroke=\"#404040\" stroke-width=\"2\"/>\n  <path d=\"M 80 180 Q 140 280 200 280 Q 260 280 320 180\" fill=\"#121212\" stroke=\"#737373\" stroke-width=\"1.5\"/>\n\n  <!-- 중앙 수거 토기 (Clay Collection Pot) -->\n  <rect x=\"180\" y=\"225\" width=\"40\" height=\"45\" fill=\"#262626\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <ellipse cx=\"200\" cy=\"225\" rx=\"20\" ry=\"6\" fill=\"#141414\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n  <text x=\"200\" y=\"252\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"bold\">COLLECTION POT</text>\n\n  <!-- 상단 수평 밀폐 시트 (Tarp / Large Leaf Membrane) -->\n  <line x1=\"60\" y1=\"180\" x2=\"340\" y2=\"180\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n\n  <!-- 양 끝단 흙/모래 밀폐 둑 (Dirt/Sand Seal Bank) -->\n  <polygon points=\"50,180 85,150 110,180\" fill=\"#262626\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <polygon points=\"290,180 315,150 350,180\" fill=\"#262626\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <text x=\"80\" y=\"145\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\">SOIL SEAL</text>\n  <text x=\"320\" y=\"145\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\">AIR-TIGHT</text>\n\n  <!-- 밀폐 압력 및 온도 상승 인디케이터 (55°C Greenhouse) -->\n  <rect x=\"140\" y=\"90\" width=\"120\" height=\"35\" fill=\"#0A0A0A\" stroke=\"#E5E5E5\" stroke-width=\"1\"/>\n  <text x=\"200\" y=\"105\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"bold\">INTERNAL TEMP &gt; 55°C</text>\n  <text x=\"200\" y=\"118\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"8\" text-anchor=\"middle\">SATURATED VAPOR PRESSURE</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 02: POT CENTERED &amp; PERIMETER AIRTIGHT SEAL</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">ANCHOR EDGES WITH WET SOIL; COMPLETE SEAL REQUIRED FOR 55°C VAPORIZATION</text>\n</svg>\n","content/svgs/06-step-03.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-06 [SOLAR-STILL-WATER]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 03</text>\n\n  <!-- 웅덩이 단면 -->\n  <path d=\"M 80 160 Q 140 280 200 280 Q 260 280 320 160\" fill=\"#121212\" stroke=\"#404040\" stroke-width=\"1.5\"/>\n\n  <!-- 중앙 수거 토기 (Clay Pot) -->\n  <rect x=\"180\" y=\"230\" width=\"40\" height=\"40\" fill=\"#262626\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <!-- 모인 순수 증류수 수면 -->\n  <rect x=\"182\" y=\"250\" width=\"36\" height=\"18\" fill=\"#FFFFFF\" fill-opacity=\"0.8\"/>\n  <text x=\"200\" y=\"263\" fill=\"#000000\" font-family=\"monospace\" font-size=\"8\" text-anchor=\"middle\" font-weight=\"bold\">PURE H2O</text>\n\n  <!-- 역원뿔 형태로 처진 덮개 시트 (Inverted Cone Sheet) -->\n  <path d=\"M 70 160 L 200 210 L 330 160\" fill=\"none\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n\n  <!-- 중앙 중심 추 (Weight Stone) -->\n  <ellipse cx=\"200\" cy=\"207\" rx=\"14\" ry=\"7\" fill=\"#1A1A1A\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <text x=\"200\" y=\"195\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"bold\">STONE WEIGHT</text>\n\n  <!-- 간격 확인 (5cm Clearance) -->\n  <line x1=\"225\" y1=\"210\" x2=\"225\" y2=\"230\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <text x=\"240\" y=\"222\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"8\">&gt; 5cm GAP</text>\n\n  <!-- 시트 하단 수증기 응결 및 낙하 물방울 (Condensation Droplets) -->\n  <circle cx=\"150\" cy=\"180\" r=\"3\" fill=\"#FFFFFF\"/>\n  <circle cx=\"175\" cy=\"195\" r=\"3.5\" fill=\"#FFFFFF\"/>\n  <circle cx=\"250\" cy=\"180\" r=\"3\" fill=\"#FFFFFF\"/>\n  <circle cx=\"225\" cy=\"195\" r=\"3.5\" fill=\"#FFFFFF\"/>\n  \n  <!-- 중앙 낙하 궤적 (Dripping Line) -->\n  <line x1=\"200\" y1=\"215\" x2=\"200\" y2=\"245\" stroke=\"#FFFFFF\" stroke-width=\"2\" stroke-dasharray=\"2 3\"/>\n  <polygon points=\"200,248 197,242 203,242\" fill=\"#FFFFFF\"/>\n  <text x=\"145\" y=\"228\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"9\">STERILE CONDENSATE</text>\n\n  <!-- 태양열 복사 화살표 (Solar Radiation Vectors) -->\n  <line x1=\"120\" y1=\"80\" x2=\"140\" y2=\"120\" stroke=\"#737373\" stroke-width=\"1.5\"/>\n  <line x1=\"200\" y1=\"70\" x2=\"200\" y2=\"115\" stroke=\"#737373\" stroke-width=\"1.5\"/>\n  <line x1=\"280\" y1=\"80\" x2=\"260\" y2=\"120\" stroke=\"#737373\" stroke-width=\"1.5\"/>\n  <text x=\"200\" y=\"65\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\">SOLAR THERMAL FLUX</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 03: INVERTED CONE CONDENSATION DRIP</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">STONE DRIVES CONDENSED DROPLETS TO INCLINE PEAK; DRIPS 100% STERILE WATER</text>\n</svg>\n","content/svgs/07-step-01.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-07 [PINE-RESIN-OINTMENT]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 01</text>\n\n  <!-- 소나무 수피 단면 (Pine Bark Trunk) -->\n  <rect x=\"60\" y=\"90\" width=\"70\" height=\"190\" fill=\"#141414\" stroke=\"#737373\" stroke-width=\"1.5\"/>\n  <!-- 소나무 상처 및 송진 덩어리 (Resin Globules) -->\n  <polygon points=\"130,130 110,145 130,160\" fill=\"#262626\" stroke=\"#FFFFFF\" stroke-width=\"1\"/>\n  <ellipse cx=\"132\" cy=\"175\" rx=\"8\" ry=\"14\" fill=\"#FFFFFF\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <text x=\"75\" y=\"145\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"9\">PINE TRUNK</text>\n\n  <!-- 긁어모으는 석기 스크레이퍼 -->\n  <polygon points=\"165,150 145,170 155,180\" fill=\"#E5E5E5\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n  <path d=\"M 160 160 L 140 175\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <polygon points=\"140,175 145,168 148,175\" fill=\"#FFFFFF\"/>\n  <text x=\"175\" y=\"165\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"9\">SCRAPE RAW RESIN</text>\n\n  <!-- 오목한 조리 편평석 (Concave Hearth Stone) -->\n  <path d=\"M 210 210 Q 280 250 350 210 L 330 260 Q 280 270 230 260 Z\" fill=\"#1A1A1A\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <!-- 녹은 액상 송진 웅덩이 -->\n  <ellipse cx=\"280\" cy=\"225\" rx=\"45\" ry=\"12\" fill=\"#FFFFFF\" fill-opacity=\"0.9\"/>\n  <text x=\"280\" y=\"228\" fill=\"#000000\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"bold\">LIQUID RESIN (MELTED)</text>\n\n  <!-- 하부 숯불 간접열 (Charcoal Indirect Heat) -->\n  <circle cx=\"250\" cy=\"280\" r=\"8\" fill=\"#404040\" stroke=\"#737373\" stroke-width=\"1\"/>\n  <circle cx=\"280\" cy=\"285\" r=\"9\" fill=\"#404040\" stroke=\"#737373\" stroke-width=\"1\"/>\n  <circle cx=\"310\" cy=\"280\" r=\"8\" fill=\"#404040\" stroke=\"#737373\" stroke-width=\"1\"/>\n  <path d=\"M 280 275 L 280 250\" stroke=\"#FFFFFF\" stroke-width=\"1.5\" stroke-dasharray=\"2 2\"/>\n  <text x=\"280\" y=\"302\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\">INDIRECT COAL HEAT (NO DIRECT FLAME)</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 01: RESIN HARVEST &amp; GENTLE INDIRECT MELTING</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">SCRAPE HARD AMBER RESIN; MELT GENTLY OVER COALS AWAY FROM OPEN FIRE</text>\n</svg>\n","content/svgs/07-step-02.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-07 [PINE-RESIN-OINTMENT]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 02</text>\n\n  <!-- 조약돌 조제 보울 (Stone Mortar Bowl) -->\n  <ellipse cx=\"200\" cy=\"180\" rx=\"90\" ry=\"35\" fill=\"#1A1A1A\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <ellipse cx=\"200\" cy=\"180\" rx=\"75\" ry=\"25\" fill=\"#0F0F0F\" stroke=\"#737373\" stroke-width=\"1\"/>\n\n  <!-- 3:1 혼합 비율 인디케이터 (3:1 Ratio) -->\n  <rect x=\"140\" y=\"80\" width=\"120\" height=\"40\" fill=\"#0A0A0A\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n  <text x=\"200\" y=\"98\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"black\">RATIO 3 : 1</text>\n  <text x=\"200\" y=\"112\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"8\" text-anchor=\"middle\">RESIN (3) + STERILE CHARCOAL (1)</text>\n\n  <!-- 숯가루 살포 투입 궤적 (Charcoal Powder Dusting) -->\n  <circle cx=\"160\" cy=\"140\" r=\"2.5\" fill=\"#FFFFFF\"/>\n  <circle cx=\"170\" cy=\"148\" r=\"2\" fill=\"#FFFFFF\"/>\n  <circle cx=\"190\" cy=\"142\" r=\"3\" fill=\"#FFFFFF\"/>\n  <circle cx=\"210\" cy=\"145\" r=\"2\" fill=\"#FFFFFF\"/>\n  <circle cx=\"230\" cy=\"140\" r=\"2.5\" fill=\"#FFFFFF\"/>\n  <line x1=\"200\" y1=\"125\" x2=\"200\" y2=\"155\" stroke=\"#FFFFFF\" stroke-width=\"1.5\" stroke-dasharray=\"2 2\"/>\n\n  <!-- 혼합 교반 스틱 (Wooden Stirring Paddle) -->\n  <line x1=\"260\" y1=\"110\" x2=\"210\" y2=\"185\" stroke=\"#E5E5E5\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n  <!-- 회전 교반 화살표 (Vigorous Stirring) -->\n  <path d=\"M 175 185 A 25 10 0 1 0 225 185\" fill=\"none\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <polygon points=\"225,181 231,188 223,191\" fill=\"#FFFFFF\"/>\n\n  <!-- 연고 경화 텍스처 박스 -->\n  <rect x=\"50\" y=\"240\" width=\"300\" height=\"55\" fill=\"#0A0A0A\" stroke=\"#404040\" stroke-width=\"1\"/>\n  <text x=\"65\" y=\"260\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\">ANTISEPTIC: TERPENES + ACTIVATED CARBON</text>\n  <text x=\"65\" y=\"278\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">&gt; BINDS BACTERIA &amp; COATS AGAINST ANAEROBIC TETANUS</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 02: 3:1 STERILE CHARCOAL BLEND &amp; SALVE COMPOUNDING</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">STIR CRUSHED CHARCOAL INTO WARM RESIN UNTIL IT FORMS A PLIABLE BLACK SALVE</text>\n</svg>\n","content/svgs/07-step-03.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-07 [PINE-RESIN-OINTMENT]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 03</text>\n\n  <!-- 팔뚝 환부 단면 (Wounded Arm Section) -->\n  <rect x=\"60\" y=\"160\" width=\"280\" height=\"60\" fill=\"#141414\" stroke=\"#737373\" stroke-width=\"1.5\"/>\n\n  <!-- 상처 열상 부위 (Laceration Wound) -->\n  <line x1=\"160\" y1=\"160\" x2=\"240\" y2=\"160\" stroke=\"#FFFFFF\" stroke-width=\"3\"/>\n  <line x1=\"180\" y1=\"155\" x2=\"220\" y2=\"165\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n\n  <!-- 두꺼운 송진 연고 도포층 (Thick Ointment Seal, 40°C Warm) -->\n  <path d=\"M 140 160 Q 200 140 260 160\" fill=\"#262626\" stroke=\"#FFFFFF\" stroke-width=\"4\"/>\n  <text x=\"200\" y=\"132\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"bold\">WARM SALVE SEAL (40°C)</text>\n\n  <!-- 멸균 자작나무 껍질 붕대 감기 (Birch Bark Wrap Bandage) -->\n  <path d=\"M 120 150 L 150 230 M 160 150 L 190 230 M 210 150 L 240 230 M 250 150 L 280 230\" stroke=\"#E5E5E5\" stroke-width=\"3\"/>\n  <text x=\"200\" y=\"250\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"bold\">BIRCH BARK BANDAGE COMPRESSION</text>\n\n  <!-- 100% 방수 및 혐기성 차단 배지 -->\n  <rect x=\"50\" y=\"80\" width=\"300\" height=\"35\" fill=\"#0A0A0A\" stroke=\"#FFFFFF\" stroke-width=\"1\"/>\n  <text x=\"200\" y=\"95\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"bold\">WATERPROOF + ANTIMICROBIAL BARRIER</text>\n  <text x=\"200\" y=\"107\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"8\" text-anchor=\"middle\">CLEAN WITH BOILED WATER BEFORE APPLICATION</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 03: WARM APPLICATION &amp; BIRCH BARK DRESSING</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">COOL TO BODY TEMP (~40°C); APPLY THICK LAYER AND BIND TO HALT SEPSIS</text>\n</svg>\n","content/svgs/pr01-outcome.svg":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\" class=\"w-full h-auto\">\n  <defs>\n    <!-- Background & Frame Gradients -->\n    <linearGradient id=\"bgGrad1\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#0d0d0d\"/>\n      <stop offset=\"100%\" stop-color=\"#141414\"/>\n    </linearGradient>\n    <linearGradient id=\"woodTripod\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#4a3728\"/>\n      <stop offset=\"50%\" stop-color=\"#73543d\"/>\n      <stop offset=\"100%\" stop-color=\"#3b2b1f\"/>\n    </linearGradient>\n    <linearGradient id=\"cylinderGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#2a2a2a\" stop-opacity=\"0.8\"/>\n      <stop offset=\"30%\" stop-color=\"#404040\" stop-opacity=\"0.2\"/>\n      <stop offset=\"70%\" stop-color=\"#404040\" stop-opacity=\"0.2\"/>\n      <stop offset=\"100%\" stop-color=\"#222222\" stop-opacity=\"0.8\"/>\n    </linearGradient>\n\n    <!-- Filter Layers Gradients -->\n    <linearGradient id=\"muddyWater\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#5c4028\"/>\n      <stop offset=\"100%\" stop-color=\"#422e1c\"/>\n    </linearGradient>\n    <linearGradient id=\"pebbleGrad\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#6e6e6e\"/>\n      <stop offset=\"50%\" stop-color=\"#4f4f4f\"/>\n      <stop offset=\"100%\" stop-color=\"#383838\"/>\n    </linearGradient>\n    <linearGradient id=\"coarseSand\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#998059\"/>\n      <stop offset=\"100%\" stop-color=\"#7a6341\"/>\n    </linearGradient>\n    <linearGradient id=\"fineSand\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#c9ad7d\"/>\n      <stop offset=\"100%\" stop-color=\"#ad9162\"/>\n    </linearGradient>\n    <linearGradient id=\"charcoalGrad\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#222222\"/>\n      <stop offset=\"50%\" stop-color=\"#141414\"/>\n      <stop offset=\"100%\" stop-color=\"#0a0a0a\"/>\n    </linearGradient>\n    <linearGradient id=\"fiberGrad\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#8a7e6b\"/>\n      <stop offset=\"100%\" stop-color=\"#635847\"/>\n    </linearGradient>\n\n    <!-- Purified Water Gradient & Glow -->\n    <linearGradient id=\"pureWater\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#38bdf8\"/>\n      <stop offset=\"50%\" stop-color=\"#0284c7\"/>\n      <stop offset=\"100%\" stop-color=\"#0369a1\"/>\n    </linearGradient>\n    <radialGradient id=\"dropletGlow\" cx=\"50%\" cy=\"50%\" r=\"50%\">\n      <stop offset=\"0%\" stop-color=\"#bae6fd\" stop-opacity=\"0.9\"/>\n      <stop offset=\"60%\" stop-color=\"#38bdf8\" stop-opacity=\"0.6\"/>\n      <stop offset=\"100%\" stop-color=\"#0284c7\" stop-opacity=\"0\"/>\n    </radialGradient>\n    <radialGradient id=\"waterSurface\" cx=\"50%\" cy=\"30%\" r=\"70%\">\n      <stop offset=\"0%\" stop-color=\"#7dd3fc\" stop-opacity=\"0.8\"/>\n      <stop offset=\"100%\" stop-color=\"#0369a1\" stop-opacity=\"0.9\"/>\n    </radialGradient>\n\n    <!-- Technical Drop Shadow -->\n    <filter id=\"subtleShadow\" x=\"-10%\" y=\"-10%\" width=\"120%\" height=\"120%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"6\" flood-color=\"#000000\" flood-opacity=\"0.7\"/>\n    </filter>\n  </defs>\n\n  <!-- Technical Canvas Backdrop -->\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"450\" fill=\"url(#bgGrad1)\"/>\n  <rect x=\"15\" y=\"15\" width=\"770\" height=\"420\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Crosshair Registration Markers -->\n  <path d=\"M 25 35 L 45 35 M 35 25 L 35 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 35 L 755 35 M 765 25 L 765 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 25 415 L 45 415 M 35 405 L 35 425\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 415 L 755 415 M 765 405 L 765 425\" stroke=\"#444\" stroke-width=\"1\"/>\n\n  <!-- Technical Watermark / Metadata -->\n  <text x=\"35\" y=\"60\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" letter-spacing=\"1\">ARCHIVE // OUTCOME SPECIFICATION</text>\n  <text x=\"35\" y=\"74\" fill=\"#E02424\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">TARGET: 5-TIER STRATIFIED PURIFIER [100% SPEC]</text>\n  <text x=\"765\" y=\"60\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"end\">FLOW RATE: 1.5L / HR</text>\n\n  <!-- Tripod Legs (Behind Cylinder) -->\n  <g id=\"tripod\">\n    <!-- Back Leg -->\n    <polygon points=\"398,50 402,50 435,390 425,390\" fill=\"#3b2b1f\" stroke=\"#261b13\" stroke-width=\"1\"/>\n    <!-- Left Leg -->\n    <polygon points=\"396,50 400,50 280,395 270,395\" fill=\"url(#woodTripod)\" stroke=\"#261b13\" stroke-width=\"1\"/>\n    <!-- Right Leg -->\n    <polygon points=\"400,50 404,50 530,395 520,395\" fill=\"url(#woodTripod)\" stroke=\"#261b13\" stroke-width=\"1\"/>\n    <!-- Lashing at Apex -->\n    <ellipse cx=\"400\" cy=\"56\" rx=\"14\" ry=\"7\" fill=\"#695138\" stroke=\"#3b2b1f\" stroke-width=\"1.5\"/>\n    <ellipse cx=\"400\" cy=\"62\" rx=\"13\" ry=\"6\" fill=\"#54402c\" stroke=\"#3b2b1f\" stroke-width=\"1.5\"/>\n  </g>\n\n  <!-- Filter Funnel Housing (Glass/PET/Clay Cutaway) -->\n  <g id=\"filterHousing\" filter=\"url(#subtleShadow)\">\n    <!-- Outer Cylinder Wall -->\n    <path d=\"M 340 90 L 460 90 L 440 270 L 415 310 L 415 330 L 385 330 L 385 310 L 360 270 Z\" fill=\"url(#cylinderGrad)\" stroke=\"#4a4a4a\" stroke-width=\"2\"/>\n\n    <!-- Layer 0: Raw Muddy Water (Top Level) -->\n    <polygon points=\"342,92 458,92 454,120 346,120\" fill=\"url(#muddyWater)\"/>\n    <ellipse cx=\"400\" cy=\"92\" rx=\"58\" ry=\"6\" fill=\"#6e4f33\" stroke=\"#8c6643\" stroke-width=\"1\"/>\n    <!-- Floating particulates in muddy water -->\n    <circle cx=\"370\" cy=\"105\" r=\"1.5\" fill=\"#382617\"/>\n    <circle cx=\"420\" cy=\"102\" r=\"2\" fill=\"#2b1d11\"/>\n    <circle cx=\"395\" cy=\"112\" r=\"1.8\" fill=\"#3d2817\"/>\n\n    <!-- Layer 1: Pebbles & Coarse Gravel -->\n    <polygon points=\"346,120 454,120 450,155 350,155\" fill=\"url(#pebbleGrad)\"/>\n    <!-- Illustrated round pebbles -->\n    <ellipse cx=\"365\" cy=\"130\" rx=\"9\" ry=\"6\" fill=\"#888\" stroke=\"#444\"/>\n    <ellipse cx=\"385\" cy=\"128\" rx=\"8\" ry=\"5\" fill=\"#666\" stroke=\"#333\"/>\n    <ellipse cx=\"405\" cy=\"132\" rx=\"10\" ry=\"7\" fill=\"#777\" stroke=\"#444\"/>\n    <ellipse cx=\"428\" cy=\"129\" rx=\"9\" ry=\"6\" fill=\"#555\" stroke=\"#333\"/>\n    <ellipse cx=\"442\" cy=\"133\" rx=\"7\" ry=\"5\" fill=\"#777\" stroke=\"#444\"/>\n    <ellipse cx=\"355\" cy=\"144\" rx=\"8\" ry=\"6\" fill=\"#666\" stroke=\"#333\"/>\n    <ellipse cx=\"378\" cy=\"145\" rx=\"10\" ry=\"7\" fill=\"#777\" stroke=\"#444\"/>\n    <ellipse cx=\"400\" cy=\"144\" rx=\"9\" ry=\"6\" fill=\"#555\" stroke=\"#333\"/>\n    <ellipse cx=\"422\" cy=\"146\" rx=\"8\" ry=\"5\" fill=\"#888\" stroke=\"#444\"/>\n    <ellipse cx=\"440\" cy=\"145\" rx=\"7\" ry=\"5\" fill=\"#666\" stroke=\"#333\"/>\n\n    <!-- Layer 2: Coarse River Sand -->\n    <polygon points=\"350,155 450,155 446,190 354,190\" fill=\"url(#coarseSand)\"/>\n    <!-- Sand speckles -->\n    <line x1=\"358\" y1=\"172\" x2=\"442\" y2=\"172\" stroke=\"#665235\" stroke-dasharray=\"2 3\" stroke-width=\"1\"/>\n    <line x1=\"360\" y1=\"180\" x2=\"440\" y2=\"180\" stroke=\"#665235\" stroke-dasharray=\"3 4\" stroke-width=\"1\"/>\n\n    <!-- Layer 3: Fine Silica Sand -->\n    <polygon points=\"354,190 446,190 442,225 358,225\" fill=\"url(#fineSand)\"/>\n    <line x1=\"362\" y1=\"205\" x2=\"438\" y2=\"205\" stroke=\"#8f764d\" stroke-dasharray=\"1 2\" stroke-width=\"0.8\"/>\n    <line x1=\"364\" y1=\"215\" x2=\"436\" y2=\"215\" stroke=\"#8f764d\" stroke-dasharray=\"2 2\" stroke-width=\"0.8\"/>\n\n    <!-- Layer 4: Activated Crushed Charcoal -->\n    <polygon points=\"358,225 442,225 438,265 362,265\" fill=\"url(#charcoalGrad)\"/>\n    <!-- Charcoal granular facets -->\n    <polygon points=\"370,235 382,232 380,245 368,242\" fill=\"#333\" stroke=\"#111\" stroke-width=\"0.8\"/>\n    <polygon points=\"392,238 406,234 404,248 390,246\" fill=\"#2a2a2a\" stroke=\"#111\" stroke-width=\"0.8\"/>\n    <polygon points=\"418,235 430,233 428,245 415,244\" fill=\"#333\" stroke=\"#111\" stroke-width=\"0.8\"/>\n    <polygon points=\"375,250 388,248 386,260 373,258\" fill=\"#2a2a2a\" stroke=\"#111\" stroke-width=\"0.8\"/>\n    <polygon points=\"398,252 412,249 410,262 396,260\" fill=\"#383838\" stroke=\"#111\" stroke-width=\"0.8\"/>\n    <polygon points=\"420,250 432,248 430,260 418,258\" fill=\"#222\" stroke=\"#111\" stroke-width=\"0.8\"/>\n\n    <!-- Layer 5: Cloth / Fiber Filter Plug -->\n    <polygon points=\"362,265 438,265 415,310 385,310\" fill=\"url(#fiberGrad)\"/>\n    <path d=\"M 370 275 Q 400 285 430 275 M 378 290 Q 400 300 422 290\" stroke=\"#473f32\" stroke-width=\"1.2\" fill=\"none\"/>\n\n    <!-- Spout Opening & Perforations -->\n    <rect x=\"385\" y=\"310\" width=\"30\" height=\"20\" fill=\"#1f1f1f\" stroke=\"#444\" stroke-width=\"1\"/>\n  </g>\n\n  <!-- Flowing Purified Water & Droplet Dynamics -->\n  <g id=\"purifiedDrop\">\n    <!-- Stream Line -->\n    <line x1=\"400\" y1=\"330\" x2=\"400\" y2=\"348\" stroke=\"#38bdf8\" stroke-width=\"2.5\" stroke-linecap=\"round\" opacity=\"0.8\"/>\n    <!-- Clear Droplet with Radial Glow -->\n    <ellipse cx=\"400\" cy=\"358\" rx=\"6\" ry=\"10\" fill=\"url(#dropletGlow)\"/>\n    <path d=\"M 400 350 C 397 355 395 358 395 362 C 395 365 397 367 400 367 C 403 367 405 365 405 362 C 405 358 403 355 400 350 Z\" fill=\"url(#pureWater)\"/>\n    <circle cx=\"398\" cy=\"360\" r=\"1.5\" fill=\"#ffffff\" opacity=\"0.9\"/>\n  </g>\n\n  <!-- Collection Pot / Water Receptacle -->\n  <g id=\"collectionPot\" filter=\"url(#subtleShadow)\">\n    <!-- Pot Body -->\n    <path d=\"M 330 375 C 330 370 345 365 400 365 C 455 365 470 370 470 375 L 458 420 C 458 428 435 432 400 432 C 365 432 342 428 342 420 Z\" fill=\"#24211d\" stroke=\"#3d3730\" stroke-width=\"2\"/>\n    <!-- Water Level Inside Pot -->\n    <ellipse cx=\"400\" cy=\"385\" rx=\"60\" ry=\"10\" fill=\"url(#waterSurface)\"/>\n    <!-- Water Ripple Circles from Droplet Impact -->\n    <ellipse cx=\"400\" cy=\"385\" rx=\"14\" ry=\"3.5\" fill=\"none\" stroke=\"#bae6fd\" stroke-width=\"1.2\" opacity=\"0.8\"/>\n    <ellipse cx=\"400\" cy=\"385\" rx=\"28\" ry=\"6\" fill=\"none\" stroke=\"#7dd3fc\" stroke-width=\"1\" opacity=\"0.6\"/>\n    <ellipse cx=\"400\" cy=\"385\" rx=\"42\" ry=\"8\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"0.8\" opacity=\"0.4\"/>\n  </g>\n\n  <!-- Technical Callout Leader Lines & Labels (Right Side) -->\n  <g id=\"calloutsRight\" font-family=\"monospace\" font-size=\"10\" fill=\"#cccccc\">\n    <!-- Callout 1: Pebbles -->\n    <line x1=\"435\" y1=\"135\" x2=\"550\" y2=\"135\" stroke=\"#E02424\" stroke-width=\"1\"/>\n    <circle cx=\"435\" cy=\"135\" r=\"2\" fill=\"#E02424\"/>\n    <text x=\"560\" y=\"132\" fill=\"#ffffff\" font-weight=\"bold\">STAGE 1: RIVER PEBBLES</text>\n    <text x=\"560\" y=\"145\" fill=\"#888888\">낙엽·벌레 등 대형 부유물 1차 차단</text>\n\n    <!-- Callout 2: Coarse Sand -->\n    <line x1=\"430\" y1=\"172\" x2=\"550\" y2=\"172\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"430\" cy=\"172\" r=\"2\" fill=\"#666\"/>\n    <text x=\"560\" y=\"169\" fill=\"#ffffff\" font-weight=\"bold\">STAGE 2: COARSE SAND</text>\n    <text x=\"560\" y=\"182\" fill=\"#888888\">굵은 흙 입자 및 모래 부유물 침전</text>\n\n    <!-- Callout 3: Fine Silica Sand -->\n    <line x1=\"425\" y1=\"208\" x2=\"550\" y2=\"208\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"425\" cy=\"208\" r=\"2\" fill=\"#666\"/>\n    <text x=\"560\" y=\"205\" fill=\"#ffffff\" font-weight=\"bold\">STAGE 3: FINE SILICA SAND</text>\n    <text x=\"560\" y=\"218\" fill=\"#888888\">미세 진흙 입자 및 미세 탁도 여과</text>\n\n    <!-- Callout 4: Charcoal -->\n    <line x1=\"420\" y1=\"245\" x2=\"550\" y2=\"245\" stroke=\"#E02424\" stroke-width=\"1\"/>\n    <circle cx=\"420\" cy=\"245\" r=\"2\" fill=\"#E02424\"/>\n    <text x=\"560\" y=\"242\" fill=\"#E02424\" font-weight=\"bold\">STAGE 4: ACTIVATED CHARCOAL</text>\n    <text x=\"560\" y=\"255\" fill=\"#888888\">미세 구멍으로 독소·냄새·유기물 흡착</text>\n\n    <!-- Callout 5: Fiber Plug -->\n    <line x1=\"410\" y1=\"288\" x2=\"550\" y2=\"288\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"410\" cy=\"288\" r=\"2\" fill=\"#666\"/>\n    <text x=\"560\" y=\"285\" fill=\"#ffffff\" font-weight=\"bold\">STAGE 5: FIBER FILTER PLUG</text>\n    <text x=\"560\" y=\"298\" fill=\"#888888\">숯가루 유출 방지 및 최종 유속 조절</text>\n\n    <!-- Callout 6: Potable Water -->\n    <line x1=\"440\" y1=\"390\" x2=\"550\" y2=\"390\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n    <circle cx=\"440\" cy=\"390\" r=\"2\" fill=\"#38bdf8\"/>\n    <text x=\"560\" y=\"387\" fill=\"#38bdf8\" font-weight=\"bold\">OUTPUT: CLEAR POTABLE WATER</text>\n    <text x=\"560\" y=\"400\" fill=\"#888888\">무색투명 식수 (음용 전 3분 끓임 필수)</text>\n  </g>\n\n  <!-- Technical Callout Leader Lines & Specs (Left Side) -->\n  <g id=\"calloutsLeft\" font-family=\"monospace\" font-size=\"10\" fill=\"#cccccc\">\n    <!-- Spec Box -->\n    <rect x=\"45\" y=\"110\" width=\"180\" height=\"150\" fill=\"#141414\" stroke=\"#333\" stroke-width=\"1\"/>\n    <rect x=\"45\" y=\"110\" width=\"180\" height=\"22\" fill=\"#1f1f1f\"/>\n    <text x=\"55\" y=\"125\" fill=\"#E02424\" font-weight=\"bold\">CRITICAL METRICS</text>\n\n    <text x=\"55\" y=\"150\" fill=\"#aaa\">· TOTAL HEIGHT: 60-80 CM</text>\n    <text x=\"55\" y=\"170\" fill=\"#aaa\">· COMPACTION: 100% TIGHT</text>\n    <text x=\"55\" y=\"190\" fill=\"#aaa\">· CHARCOAL THICKNESS: 10 CM+</text>\n    <text x=\"55\" y=\"210\" fill=\"#aaa\">· INITIAL FLUSH: DISCARD 1L</text>\n    <text x=\"55\" y=\"230\" fill=\"#aaa\">· WATER PURITY: 99.2% CLARITY</text>\n    <text x=\"55\" y=\"250\" fill=\"#38bdf8\">· BOILING REQ: 3 MIN AT 100°C</text>\n\n    <!-- Raw Water Inflow Indicator -->\n    <path d=\"M 330 75 Q 360 82 375 92\" stroke=\"#8c6643\" stroke-width=\"2\" fill=\"none\"/>\n    <text x=\"320\" y=\"65\" fill=\"#c9ad7d\" font-weight=\"bold\">RAW MUDDY INFLOW (탁수 유입)</text>\n  </g>\n</svg>\n","content/svgs/pr01-step-01.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgGradP01\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#08090b\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1217\"/>\n      <stop offset=\"100%\" stop-color=\"#080a0d\"/>\n    </linearGradient>\n\n    <!-- Timber Tripod Cylinder Shading -->\n    <linearGradient id=\"woodLeg\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#3d2817\"/>\n      <stop offset=\"45%\" stop-color=\"#694627\"/>\n      <stop offset=\"70%\" stop-color=\"#8c5d35\"/>\n      <stop offset=\"100%\" stop-color=\"#2a1b0e\"/>\n    </linearGradient>\n\n    <!-- Birch Bark Cone Funnel -->\n    <linearGradient id=\"birchCone\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#403830\"/>\n      <stop offset=\"35%\" stop-color=\"#736658\"/>\n      <stop offset=\"65%\" stop-color=\"#9e8d7c\"/>\n      <stop offset=\"100%\" stop-color=\"#332c25\"/>\n    </linearGradient>\n\n    <!-- Moss Plug Green Gradient -->\n    <linearGradient id=\"mossGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#14532d\"/>\n      <stop offset=\"50%\" stop-color=\"#22c55e\"/>\n      <stop offset=\"100%\" stop-color=\"#052e16\"/>\n    </linearGradient>\n\n    <!-- Drop Shadow Filter -->\n    <filter id=\"shadowP01\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"4\" flood-color=\"#000000\" flood-opacity=\"0.9\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Backdrop -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgGradP01)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#22262c\" stroke-width=\"1\"/>\n\n  <!-- Technical Corner Crosshairs -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n\n  <!-- Blueprint Header (Label 1) -->\n  <text x=\"24\" y=\"28\" fill=\"#9ca3af\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" letter-spacing=\"0.5\">FIG. 01 // PURIFICATION STEP 1: 프레임 거치 및 하단 마개</text>\n  <line x1=\"24\" y1=\"36\" x2=\"376\" y2=\"36\" stroke=\"#262d35\" stroke-width=\"1\"/>\n\n  <!-- Tripod Legs (Back Leg first) -->\n  <line x1=\"200\" y1=\"65\" x2=\"200\" y2=\"320\" stroke=\"#000000\" stroke-width=\"14\" stroke-linecap=\"round\"/>\n  <line x1=\"200\" y1=\"65\" x2=\"200\" y2=\"320\" stroke=\"url(#woodLeg)\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n\n  <!-- Cone Funnel Body (Birch Bark) with Drop Shadow -->\n  <polygon points=\"140,110 260,110 215,260 185,260\" fill=\"url(#birchCone)\" stroke=\"#221c17\" stroke-width=\"1.5\" filter=\"url(#shadowP01)\"/>\n  <ellipse cx=\"200\" cy=\"110\" rx=\"60\" ry=\"12\" fill=\"#52473c\" stroke=\"#221c17\" stroke-width=\"1.5\"/>\n\n  <!-- Front Tripod Left Leg -->\n  <line x1=\"200\" y1=\"65\" x2=\"120\" y2=\"320\" stroke=\"#000000\" stroke-width=\"16\" stroke-linecap=\"round\"/>\n  <line x1=\"200\" y1=\"65\" x2=\"120\" y2=\"320\" stroke=\"url(#woodLeg)\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n\n  <!-- Front Tripod Right Leg -->\n  <line x1=\"200\" y1=\"65\" x2=\"280\" y2=\"320\" stroke=\"#000000\" stroke-width=\"16\" stroke-linecap=\"round\"/>\n  <line x1=\"200\" y1=\"65\" x2=\"280\" y2=\"320\" stroke=\"url(#woodLeg)\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n\n  <!-- Top Lash Knot Binding Tripod -->\n  <rect x=\"188\" y=\"58\" width=\"24\" height=\"16\" rx=\"4\" fill=\"#854d0e\" stroke=\"#451a03\" stroke-width=\"1.5\"/>\n\n  <!-- Bottom Spout Opening and Moss Plug -->\n  <polygon points=\"185,260 215,260 210,282 190,282\" fill=\"#2d241c\" stroke=\"#1c1611\" stroke-width=\"1\"/>\n  <!-- Moss / Fabric Plug Core -->\n  <ellipse cx=\"200\" cy=\"275\" rx=\"11\" ry=\"7\" fill=\"url(#mossGrad)\" stroke=\"#14532d\" stroke-width=\"1\"/>\n  <!-- Texture dots for moss -->\n  <circle cx=\"197\" cy=\"274\" r=\"1.5\" fill=\"#86efac\"/>\n  <circle cx=\"203\" cy=\"276\" r=\"1.2\" fill=\"#4ade80\"/>\n\n  <!-- Support Cord wrapped around Funnel -->\n  <ellipse cx=\"200\" cy=\"140\" rx=\"48\" ry=\"9\" fill=\"none\" stroke=\"#ca8a04\" stroke-width=\"2.5\" stroke-dasharray=\"6 3\"/>\n\n  <!-- Technical Callout Lines -->\n  <!-- Callout 1: Tripod Frame (Label 2) -->\n  <line x1=\"140\" y1=\"160\" x2=\"105\" y2=\"75\" stroke=\"#9ca3af\" stroke-width=\"1\"/>\n  <circle cx=\"140\" cy=\"160\" r=\"2.5\" fill=\"#f59e0b\"/>\n  <text x=\"24\" y=\"70\" fill=\"#fde68a\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\" font-weight=\"bold\">TRIPOD FRAME (삼각대)</text>\n\n  <!-- Callout 2: Cone Funnel (Label 3) -->\n  <line x1=\"240\" y1=\"170\" x2=\"105\" y2=\"165\" stroke=\"#9ca3af\" stroke-width=\"1\"/>\n  <circle cx=\"240\" cy=\"170\" r=\"2.5\" fill=\"#38bdf8\"/>\n  <text x=\"24\" y=\"160\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\" font-weight=\"bold\">CONE FUNNEL (여과관)</text>\n\n  <!-- Callout 3: Moss Plug (Label 4) -->\n  <line x1=\"200\" y1=\"275\" x2=\"105\" y2=\"255\" stroke=\"#9ca3af\" stroke-width=\"1\"/>\n  <circle cx=\"200\" cy=\"275\" r=\"2.5\" fill=\"#22c55e\"/>\n  <text x=\"24\" y=\"250\" fill=\"#86efac\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\" font-weight=\"bold\">MOSS PLUG (이끼 마개)</text>\n\n  <!-- Bottom Tactical Note Strip -->\n  <rect x=\"18\" y=\"340\" width=\"364\" height=\"34\" fill=\"#111419\" stroke=\"#262d35\" stroke-width=\"1\"/>\n  <rect x=\"18\" y=\"340\" width=\"4\" height=\"34\" fill=\"#38bdf8\"/>\n  <!-- Label 5: Step Core Instruction -->\n  <text x=\"32\" y=\"361\" fill=\"#ffffff\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9.5\" font-weight=\"bold\">[1단계 핵심] 흔들리지 않는 3점 지지대 결속</text>\n</svg>\n","content/svgs/pr01-step-02.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgGradP02\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#08090b\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1217\"/>\n      <stop offset=\"100%\" stop-color=\"#080a0d\"/>\n    </linearGradient>\n\n    <!-- Funnel Cutaway Shell Gradient -->\n    <linearGradient id=\"funnelCutaway\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#332c25\"/>\n      <stop offset=\"15%\" stop-color=\"#665747\"/>\n      <stop offset=\"50%\" stop-color=\"#181e26\"/>\n      <stop offset=\"85%\" stop-color=\"#665747\"/>\n      <stop offset=\"100%\" stop-color=\"#332c25\"/>\n    </linearGradient>\n\n    <!-- Charcoal Grain Texture Pattern -->\n    <pattern id=\"charcoalTexture\" width=\"12\" height=\"12\" patternUnits=\"userSpaceOnUse\">\n      <rect width=\"12\" height=\"12\" fill=\"#111317\"/>\n      <circle cx=\"3\" cy=\"3\" r=\"2.2\" fill=\"#22272e\"/>\n      <circle cx=\"8\" cy=\"8\" r=\"2.8\" fill=\"#1b2026\"/>\n      <circle cx=\"9\" cy=\"2\" r=\"1.5\" fill=\"#2d333b\"/>\n      <circle cx=\"2\" cy=\"9\" r=\"1.8\" fill=\"#262c33\"/>\n    </pattern>\n\n    <!-- Drop Shadow Filter -->\n    <filter id=\"shadowP02\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"4\" flood-color=\"#000000\" flood-opacity=\"0.9\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Backdrop -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgGradP02)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#22262c\" stroke-width=\"1\"/>\n\n  <!-- Technical Corner Crosshairs -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n\n  <!-- Blueprint Header (Label 1) -->\n  <text x=\"24\" y=\"28\" fill=\"#9ca3af\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" letter-spacing=\"0.5\">FIG. 02 // PURIFICATION STEP 2: 숯 흡착층 형성</text>\n  <line x1=\"24\" y1=\"36\" x2=\"376\" y2=\"36\" stroke=\"#262d35\" stroke-width=\"1\"/>\n\n  <!-- Cutaway Cross Section Funnel Wall -->\n  <polygon points=\"120,85 240,85 195,295 165,295\" fill=\"none\" stroke=\"#4b5563\" stroke-width=\"1.5\" stroke-dasharray=\"4 2\"/>\n  <path d=\"M 120 85 L 165 295 L 195 295 L 240 85\" fill=\"none\" stroke=\"#374151\" stroke-width=\"3\"/>\n\n  <!-- Bottom Moss Plug in Cross Section -->\n  <polygon points=\"166,275 194,275 190,295 170,295\" fill=\"#14532d\" stroke=\"#22c55e\" stroke-width=\"1\"/>\n\n  <!-- Charcoal Bed (8cm layer) with Texture and Shading -->\n  <polygon points=\"152,195 208,195 194,275 166,275\" fill=\"url(#charcoalTexture)\" stroke=\"#111827\" stroke-width=\"1.5\" filter=\"url(#shadowP02)\"/>\n  \n  <!-- Individual Charcoal Chunks (5~8mm grains) -->\n  <rect x=\"172\" y=\"202\" width=\"7\" height=\"6\" rx=\"1.5\" fill=\"#374151\" stroke=\"#1f2937\" stroke-width=\"0.8\"/>\n  <rect x=\"183\" y=\"205\" width=\"8\" height=\"7\" rx=\"1.5\" fill=\"#4b5563\" stroke=\"#1f2937\" stroke-width=\"0.8\"/>\n  <rect x=\"175\" y=\"218\" width=\"9\" height=\"7\" rx=\"2\" fill=\"#374151\" stroke=\"#111827\" stroke-width=\"0.8\"/>\n  <rect x=\"188\" y=\"222\" width=\"7\" height=\"6\" rx=\"1.5\" fill=\"#4b5563\" stroke=\"#1f2937\" stroke-width=\"0.8\"/>\n  <rect x=\"170\" y=\"235\" width=\"8\" height=\"8\" rx=\"2\" fill=\"#1f2937\" stroke=\"#0f172a\" stroke-width=\"0.8\"/>\n  <rect x=\"182\" y=\"240\" width=\"9\" height=\"7\" rx=\"2\" fill=\"#374151\" stroke=\"#1f2937\" stroke-width=\"0.8\"/>\n  <rect x=\"174\" y=\"255\" width=\"8\" height=\"6\" rx=\"1.5\" fill=\"#4b5563\" stroke=\"#111827\" stroke-width=\"0.8\"/>\n\n  <!-- 8cm Height Dimension Bracket -->\n  <path d=\"M 215 195 L 225 195 L 225 275 L 215 275\" fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"1.5\"/>\n  <line x1=\"225\" y1=\"235\" x2=\"235\" y2=\"235\" stroke=\"#f59e0b\" stroke-width=\"1.5\"/>\n\n  <!-- Zoom Loupe: Micro-Pore Adsorption Mechanism (Right Top) -->\n  <circle cx=\"310\" cy=\"115\" r=\"32\" fill=\"#0d1117\" stroke=\"#38bdf8\" stroke-width=\"1.5\"/>\n  <!-- Charcoal Porous Matrix -->\n  <circle cx=\"310\" cy=\"115\" r=\"22\" fill=\"#1f2937\"/>\n  <circle cx=\"304\" cy=\"110\" r=\"3\" fill=\"#0b0f14\"/>\n  <circle cx=\"316\" cy=\"112\" r=\"2.5\" fill=\"#0b0f14\"/>\n  <circle cx=\"310\" cy=\"122\" r=\"3.2\" fill=\"#0b0f14\"/>\n  <!-- Toxin Trap Arrow Vectors into pores -->\n  <path d=\"M 292 105 L 302 109\" stroke=\"#ef4444\" stroke-width=\"1.5\" marker-end=\"url(#arrow)\"/>\n  <polygon points=\"302,109 296,106 298,112\" fill=\"#ef4444\"/>\n  <path d=\"M 326 126 L 314 123\" stroke=\"#ef4444\" stroke-width=\"1.5\"/>\n  <polygon points=\"314,123 320,121 319,127\" fill=\"#ef4444\"/>\n\n  <!-- Technical Callouts -->\n  <!-- Callout 1: Charcoal Core (Label 2) -->\n  <line x1=\"160\" y1=\"235\" x2=\"115\" y2=\"75\" stroke=\"#9ca3af\" stroke-width=\"1\"/>\n  <circle cx=\"160\" cy=\"235\" r=\"2.5\" fill=\"#f59e0b\"/>\n  <text x=\"24\" y=\"70\" fill=\"#fde68a\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\" font-weight=\"bold\">CHARCOAL CORE (활성 숯)</text>\n\n  <!-- Callout 2: Pore Absorption (Label 3) -->\n  <text x=\"376\" y=\"70\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"end\">PORE ABSORPTION (미세 흡착)</text>\n\n  <!-- Callout 3: Thickness 8cm (Label 4) -->\n  <line x1=\"235\" y1=\"235\" x2=\"285\" y2=\"165\" stroke=\"#f59e0b\" stroke-width=\"1\"/>\n  <circle cx=\"235\" cy=\"235\" r=\"2.5\" fill=\"#f59e0b\"/>\n  <text x=\"376\" y=\"165\" fill=\"#fde68a\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"end\">THICKNESS: 8CM (두께)</text>\n\n  <!-- Bottom Tactical Note Strip -->\n  <rect x=\"18\" y=\"340\" width=\"364\" height=\"34\" fill=\"#111419\" stroke=\"#262d35\" stroke-width=\"1\"/>\n  <rect x=\"18\" y=\"340\" width=\"4\" height=\"34\" fill=\"#f59e0b\"/>\n  <!-- Label 5: Step Core Instruction -->\n  <text x=\"32\" y=\"361\" fill=\"#ffffff\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9.5\" font-weight=\"bold\">[2단계 핵심] 콩알 크기(5~8mm)로 부숴 8cm 충진</text>\n</svg>\n","content/svgs/pr01-step-03.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgGradP03\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#08090b\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1217\"/>\n      <stop offset=\"100%\" stop-color=\"#080a0d\"/>\n    </linearGradient>\n\n    <!-- River Sand Granular Pattern -->\n    <pattern id=\"sandTexture\" width=\"10\" height=\"10\" patternUnits=\"userSpaceOnUse\">\n      <rect width=\"10\" height=\"10\" fill=\"#785934\"/>\n      <circle cx=\"2\" cy=\"2\" r=\"1.2\" fill=\"#d97706\"/>\n      <circle cx=\"7\" cy=\"7\" r=\"1.4\" fill=\"#fbbf24\"/>\n      <circle cx=\"8\" cy=\"2\" r=\"1\" fill=\"#b45309\"/>\n      <circle cx=\"3\" cy=\"8\" r=\"1.1\" fill=\"#fde68a\"/>\n    </pattern>\n\n    <!-- Drop Shadow Filter -->\n    <filter id=\"shadowP03\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"4\" flood-color=\"#000000\" flood-opacity=\"0.9\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Backdrop -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgGradP03)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#22262c\" stroke-width=\"1\"/>\n\n  <!-- Technical Corner Crosshairs -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n\n  <!-- Blueprint Header (Label 1) -->\n  <text x=\"24\" y=\"28\" fill=\"#9ca3af\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" letter-spacing=\"0.5\">FIG. 03 // PURIFICATION STEP 3: 미세 모래층 적층</text>\n  <line x1=\"24\" y1=\"36\" x2=\"376\" y2=\"36\" stroke=\"#262d35\" stroke-width=\"1\"/>\n\n  <!-- Cutaway Cross Section Funnel Wall -->\n  <polygon points=\"120,85 240,85 195,295 165,295\" fill=\"none\" stroke=\"#4b5563\" stroke-width=\"1.5\" stroke-dasharray=\"4 2\"/>\n  <path d=\"M 120 85 L 165 295 L 195 295 L 240 85\" fill=\"none\" stroke=\"#374151\" stroke-width=\"3\"/>\n\n  <!-- Bottom Moss Plug -->\n  <polygon points=\"166,275 194,275 190,295 170,295\" fill=\"#14532d\" stroke=\"#22c55e\" stroke-width=\"1\"/>\n\n  <!-- 1. Lower Layer: Charcoal Bed (Already Placed) -->\n  <polygon points=\"152,215 208,215 194,275 166,275\" fill=\"#181c22\" stroke=\"#111827\" stroke-width=\"1\"/>\n\n  <!-- 2. Mid Layer: River Sand (6cm layer) with Texture and Shading -->\n  <polygon points=\"138,155 222,155 208,215 152,215\" fill=\"url(#sandTexture)\" stroke=\"#92400e\" stroke-width=\"1.5\" filter=\"url(#shadowP03)\"/>\n\n  <!-- Leveling Guide Arrows (수평 다듬기) -->\n  <line x1=\"145\" y1=\"150\" x2=\"215\" y2=\"150\" stroke=\"#fde68a\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n  <polygon points=\"215,150 209,147 209,153\" fill=\"#fde68a\"/>\n  <polygon points=\"145,150 151,147 151,153\" fill=\"#fde68a\"/>\n\n  <!-- 6cm Height Dimension Bracket -->\n  <path d=\"M 230 155 L 240 155 L 240 215 L 230 215\" fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"1.5\"/>\n  <line x1=\"240\" y1=\"185\" x2=\"250\" y2=\"185\" stroke=\"#f59e0b\" stroke-width=\"1.5\"/>\n\n  <!-- Particle Trap Inset Zoom (Right Top) -->\n  <circle cx=\"310\" cy=\"115\" r=\"32\" fill=\"#0d1117\" stroke=\"#fbbf24\" stroke-width=\"1.5\"/>\n  <circle cx=\"310\" cy=\"115\" r=\"24\" fill=\"#451a03\"/>\n  <!-- Sand Grains interlocking -->\n  <circle cx=\"304\" cy=\"110\" r=\"5\" fill=\"#d97706\"/>\n  <circle cx=\"316\" cy=\"112\" r=\"4.5\" fill=\"#f59e0b\"/>\n  <circle cx=\"309\" cy=\"121\" r=\"5\" fill=\"#b45309\"/>\n  <!-- Trapped Silt Dust -->\n  <circle cx=\"310\" cy=\"114\" r=\"1.8\" fill=\"#78350f\"/>\n  <circle cx=\"306\" cy=\"118\" r=\"1.5\" fill=\"#78350f\"/>\n\n  <!-- Technical Callouts -->\n  <!-- Callout 1: River Sand (Label 2) -->\n  <line x1=\"165\" y1=\"185\" x2=\"115\" y2=\"75\" stroke=\"#9ca3af\" stroke-width=\"1\"/>\n  <circle cx=\"165\" cy=\"185\" r=\"2.5\" fill=\"#f59e0b\"/>\n  <text x=\"24\" y=\"70\" fill=\"#fde68a\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\" font-weight=\"bold\">RIVER SAND (고운 모래)</text>\n\n  <!-- Callout 2: Particle Filter (Label 3) -->\n  <text x=\"376\" y=\"70\" fill=\"#fbbf24\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"end\">PARTICLE FILTER (흙먼지 차단)</text>\n\n  <!-- Callout 3: Thickness 6cm (Label 4) -->\n  <line x1=\"250\" y1=\"185\" x2=\"295\" y2=\"165\" stroke=\"#f59e0b\" stroke-width=\"1\"/>\n  <circle cx=\"250\" cy=\"185\" r=\"2.5\" fill=\"#f59e0b\"/>\n  <text x=\"376\" y=\"165\" fill=\"#fde68a\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"end\">THICKNESS: 6CM (두께)</text>\n\n  <!-- Bottom Tactical Note Strip -->\n  <rect x=\"18\" y=\"340\" width=\"364\" height=\"34\" fill=\"#111419\" stroke=\"#262d35\" stroke-width=\"1\"/>\n  <rect x=\"18\" y=\"340\" width=\"4\" height=\"34\" fill=\"#f59e0b\"/>\n  <!-- Label 5: Step Core Instruction -->\n  <text x=\"32\" y=\"361\" fill=\"#ffffff\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9.5\" font-weight=\"bold\">[3단계 핵심] 숯을 고정하고 미세 흙먼지 차단</text>\n</svg>\n","content/svgs/pr01-step-04.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgGradP04\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#08090b\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1217\"/>\n      <stop offset=\"100%\" stop-color=\"#080a0d\"/>\n    </linearGradient>\n\n    <!-- Water Drop Gradient -->\n    <linearGradient id=\"clearWater\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#e0f2fe\"/>\n      <stop offset=\"50%\" stop-color=\"#38bdf8\"/>\n      <stop offset=\"100%\" stop-color=\"#0284c7\"/>\n    </linearGradient>\n\n    <!-- Turbid Inflow Water -->\n    <linearGradient id=\"muddyWater\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#78350f\"/>\n      <stop offset=\"100%\" stop-color=\"#92400e\"/>\n    </linearGradient>\n\n    <!-- Pebble 3D Gradient -->\n    <linearGradient id=\"pebbleGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#9ca3af\"/>\n      <stop offset=\"50%\" stop-color=\"#4b5563\"/>\n      <stop offset=\"100%\" stop-color=\"#1f2937\"/>\n    </linearGradient>\n\n    <!-- Drop Shadow Filter -->\n    <filter id=\"shadowP04\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"4\" flood-color=\"#000000\" flood-opacity=\"0.9\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Backdrop -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgGradP04)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#22262c\" stroke-width=\"1\"/>\n\n  <!-- Technical Corner Crosshairs -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n\n  <!-- Blueprint Header (Label 1) -->\n  <text x=\"24\" y=\"28\" fill=\"#9ca3af\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" letter-spacing=\"0.5\">FIG. 04 // PURIFICATION STEP 4: 자갈층 및 초기 세척</text>\n  <line x1=\"24\" y1=\"36\" x2=\"376\" y2=\"36\" stroke=\"#262d35\" stroke-width=\"1\"/>\n\n  <!-- Funnel Outline -->\n  <polygon points=\"120,85 240,85 195,275 165,275\" fill=\"none\" stroke=\"#4b5563\" stroke-width=\"1.5\" stroke-dasharray=\"4 2\"/>\n  <path d=\"M 120 85 L 165 275 L 195 275 L 240 85\" fill=\"none\" stroke=\"#374151\" stroke-width=\"3\"/>\n\n  <!-- Inflow Muddy Water Stream -->\n  <path d=\"M 180 55 C 180 75 170 85 170 95\" stroke=\"url(#muddyWater)\" stroke-width=\"6\" stroke-linecap=\"round\" fill=\"none\"/>\n  <polygon points=\"180,50 176,58 184,58\" fill=\"#78350f\"/>\n\n  <!-- Top Pebble Bed (4cm) -->\n  <polygon points=\"125,95 235,95 222,140 138,140\" fill=\"#2d333b\" stroke=\"#1f242c\" stroke-width=\"1\" filter=\"url(#shadowP04)\"/>\n  <!-- 3D Pebbles -->\n  <ellipse cx=\"145\" cy=\"115\" rx=\"9\" ry=\"6\" fill=\"url(#pebbleGrad)\" stroke=\"#111827\" stroke-width=\"0.8\"/>\n  <ellipse cx=\"165\" cy=\"110\" rx=\"10\" ry=\"7\" fill=\"url(#pebbleGrad)\" stroke=\"#111827\" stroke-width=\"0.8\"/>\n  <ellipse cx=\"185\" cy=\"116\" rx=\"8\" ry=\"6\" fill=\"url(#pebbleGrad)\" stroke=\"#111827\" stroke-width=\"0.8\"/>\n  <ellipse cx=\"205\" cy=\"112\" rx=\"11\" ry=\"7\" fill=\"url(#pebbleGrad)\" stroke=\"#111827\" stroke-width=\"0.8\"/>\n  <ellipse cx=\"155\" cy=\"128\" rx=\"8\" ry=\"5\" fill=\"url(#pebbleGrad)\" stroke=\"#111827\" stroke-width=\"0.8\"/>\n  <ellipse cx=\"178\" cy=\"130\" rx=\"9\" ry=\"6\" fill=\"url(#pebbleGrad)\" stroke=\"#111827\" stroke-width=\"0.8\"/>\n  <ellipse cx=\"198\" cy=\"126\" rx=\"8\" ry=\"5\" fill=\"url(#pebbleGrad)\" stroke=\"#111827\" stroke-width=\"0.8\"/>\n\n  <!-- Mid Sand Layer -->\n  <polygon points=\"138,140 222,140 208,195 152,195\" fill=\"#785934\" stroke=\"#92400e\" stroke-width=\"1\"/>\n  <!-- Charcoal Bed -->\n  <polygon points=\"152,195 208,195 194,255 166,255\" fill=\"#181c22\" stroke=\"#111827\" stroke-width=\"1\"/>\n  <!-- Moss Plug -->\n  <polygon points=\"166,255 194,255 190,275 170,275\" fill=\"#14532d\" stroke=\"#22c55e\" stroke-width=\"1\"/>\n\n  <!-- Water Dripping Mechanism at Bottom Spout -->\n  <circle cx=\"180\" cy=\"285\" r=\"3.5\" fill=\"url(#clearWater)\"/>\n  <path d=\"M 180 292 C 182 297 182 301 180 304 C 178 301 178 297 180 292\" fill=\"url(#clearWater)\"/>\n\n  <!-- Dual Cup Flushing Scheme (Right Inset) -->\n  <g id=\"flushingCups\">\n    <!-- Cup 1: Dirty Black Flush Cup (DISCARD) -->\n    <rect x=\"290\" y=\"210\" width=\"30\" height=\"35\" rx=\"3\" fill=\"#181c22\" stroke=\"#ef4444\" stroke-width=\"1.5\"/>\n    <rect x=\"294\" y=\"218\" width=\"22\" height=\"23\" fill=\"#0f1216\"/>\n    <!-- Red X mark -->\n    <path d=\"M 299 224 L 311 236 M 311 224 L 299 236\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n\n    <!-- Arrow from discard to clean -->\n    <path d=\"M 325 228 L 338 228\" stroke=\"#9ca3af\" stroke-width=\"1.5\"/>\n    <polygon points=\"340,228 334,225 334,231\" fill=\"#9ca3af\"/>\n\n    <!-- Cup 2: Crystal Clean Water Cup (COLLECT) -->\n    <rect x=\"345\" y=\"210\" width=\"30\" height=\"35\" rx=\"3\" fill=\"#111827\" stroke=\"#38bdf8\" stroke-width=\"1.5\"/>\n    <rect x=\"349\" y=\"222\" width=\"22\" height=\"19\" fill=\"#0284c7\" opacity=\"0.6\"/>\n    <!-- Green Check mark -->\n    <path d=\"M 353 230 L 358 235 L 367 225\" stroke=\"#22c55e\" stroke-width=\"2\" fill=\"none\"/>\n  </g>\n\n  <!-- Technical Callouts -->\n  <!-- Callout 1: Pebble Layer (Label 2) -->\n  <line x1=\"165\" y1=\"120\" x2=\"115\" y2=\"75\" stroke=\"#9ca3af\" stroke-width=\"1\"/>\n  <circle cx=\"165\" cy=\"120\" r=\"2.5\" fill=\"#f59e0b\"/>\n  <text x=\"24\" y=\"70\" fill=\"#fde68a\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\" font-weight=\"bold\">PEBBLE LAYER (자갈층)</text>\n\n  <!-- Callout 2: Flush First Cups (Label 3) -->\n  <text x=\"376\" y=\"70\" fill=\"#f87171\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"end\">FLUSH FIRST CUPS (첫물 버리기)</text>\n\n  <!-- Callout 3: Clear Drip (Label 4) -->\n  <line x1=\"185\" y1=\"298\" x2=\"285\" y2=\"165\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <circle cx=\"185\" cy=\"298\" r=\"2.5\" fill=\"#38bdf8\"/>\n  <text x=\"376\" y=\"165\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"end\">CLEAR DRIP (맑은 물 방울)</text>\n\n  <!-- Bottom Tactical Note Strip -->\n  <rect x=\"18\" y=\"340\" width=\"364\" height=\"34\" fill=\"#111419\" stroke=\"#262d35\" stroke-width=\"1\"/>\n  <rect x=\"18\" y=\"340\" width=\"4\" height=\"34\" fill=\"#38bdf8\"/>\n  <!-- Label 5: Step Core Instruction -->\n  <text x=\"32\" y=\"361\" fill=\"#ffffff\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9.5\" font-weight=\"bold\">[4단계 핵심] 자갈로 수압 분산 후 첫 1~2컵 버리기</text>\n</svg>\n","content/svgs/pr01-step-05.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgGradP05\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#08090b\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1217\"/>\n      <stop offset=\"100%\" stop-color=\"#080a0d\"/>\n    </linearGradient>\n\n    <!-- Clay Pot Shading -->\n    <linearGradient id=\"clayPotGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#451a03\"/>\n      <stop offset=\"30%\" stop-color=\"#78350f\"/>\n      <stop offset=\"70%\" stop-color=\"#9a3412\"/>\n      <stop offset=\"100%\" stop-color=\"#2a0d01\"/>\n    </linearGradient>\n\n    <!-- Campfire Flame Gradient -->\n    <linearGradient id=\"flameGrad\" x1=\"0%\" y1=\"100%\" x2=\"0%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#dc2626\"/>\n      <stop offset=\"50%\" stop-color=\"#f97316\"/>\n      <stop offset=\"85%\" stop-color=\"#facc15\"/>\n      <stop offset=\"100%\" stop-color=\"#fef08a\"/>\n    </linearGradient>\n\n    <!-- Boiling Water Steam/Surface -->\n    <linearGradient id=\"boilingWater\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#e0f2fe\"/>\n      <stop offset=\"60%\" stop-color=\"#38bdf8\"/>\n      <stop offset=\"100%\" stop-color=\"#0284c7\"/>\n    </linearGradient>\n\n    <!-- Drop Shadow Filter -->\n    <filter id=\"shadowP05\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"4\" flood-color=\"#000000\" flood-opacity=\"0.9\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Backdrop -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgGradP05)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#22262c\" stroke-width=\"1\"/>\n\n  <!-- Technical Corner Crosshairs -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n\n  <!-- Blueprint Header (Label 1) -->\n  <text x=\"24\" y=\"28\" fill=\"#9ca3af\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" letter-spacing=\"0.5\">FIG. 05 // PURIFICATION STEP 5: 100℃ 비등 멸균</text>\n  <line x1=\"24\" y1=\"36\" x2=\"376\" y2=\"36\" stroke=\"#262d35\" stroke-width=\"1\"/>\n\n  <!-- Campfire Flames at Base -->\n  <g id=\"fireBase\">\n    <!-- Firewood logs -->\n    <line x1=\"130\" y1=\"305\" x2=\"230\" y2=\"285\" stroke=\"#3d2817\" stroke-width=\"14\" stroke-linecap=\"round\"/>\n    <line x1=\"150\" y1=\"285\" x2=\"250\" y2=\"305\" stroke=\"#2a1b0e\" stroke-width=\"14\" stroke-linecap=\"round\"/>\n    <!-- Dynamic Flame Tongues -->\n    <path d=\"M 160 300 C 150 260 170 230 180 215 C 190 235 185 265 175 300\" fill=\"url(#flameGrad)\" opacity=\"0.9\"/>\n    <path d=\"M 180 300 C 175 250 195 220 200 205 C 210 230 205 265 195 300\" fill=\"url(#flameGrad)\" opacity=\"0.95\"/>\n    <path d=\"M 200 300 C 205 260 225 240 220 225 C 215 245 210 270 215 300\" fill=\"url(#flameGrad)\" opacity=\"0.85\"/>\n  </g>\n\n  <!-- Clay Pot Cooking Vessel -->\n  <path d=\"M 135 150 C 120 185 125 250 155 265 C 175 272 225 272 245 265 C 275 250 280 185 265 150 Z\" \n        fill=\"url(#clayPotGrad)\" stroke=\"#1c0c04\" stroke-width=\"2\" filter=\"url(#shadowP05)\"/>\n  <!-- Pot Rim Ellipse -->\n  <ellipse cx=\"200\" cy=\"150\" rx=\"65\" ry=\"14\" fill=\"#5c2406\" stroke=\"#1c0c04\" stroke-width=\"1.8\"/>\n\n  <!-- Boiling Water Inside Pot -->\n  <ellipse cx=\"200\" cy=\"154\" rx=\"55\" ry=\"11\" fill=\"url(#boilingWater)\"/>\n\n  <!-- Rolling Boil Bubbles (큰 거품) -->\n  <circle cx=\"180\" cy=\"152\" r=\"6\" fill=\"#ffffff\" opacity=\"0.8\" stroke=\"#0284c7\" stroke-width=\"0.8\"/>\n  <circle cx=\"215\" cy=\"154\" r=\"7.5\" fill=\"#ffffff\" opacity=\"0.85\" stroke=\"#0284c7\" stroke-width=\"0.8\"/>\n  <circle cx=\"198\" cy=\"156\" r=\"5\" fill=\"#ffffff\" opacity=\"0.75\" stroke=\"#0284c7\" stroke-width=\"0.8\"/>\n  <circle cx=\"165\" cy=\"155\" r=\"4.5\" fill=\"#ffffff\" opacity=\"0.8\"/>\n  <circle cx=\"230\" cy=\"153\" r=\"4\" fill=\"#ffffff\" opacity=\"0.8\"/>\n\n  <!-- Steam Vapor Waves -->\n  <path d=\"M 175 140 C 170 120 180 105 175 85\" stroke=\"#93c5fd\" stroke-width=\"2\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.6\"/>\n  <path d=\"M 200 138 C 205 118 195 102 200 82\" stroke=\"#93c5fd\" stroke-width=\"2.5\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.7\"/>\n  <path d=\"M 225 140 C 230 122 220 108 225 88\" stroke=\"#93c5fd\" stroke-width=\"2\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.6\"/>\n\n  <!-- 3-Minute Timer Stopwatch Dial (Right Top Inset) -->\n  <circle cx=\"310\" cy=\"115\" r=\"32\" fill=\"#0d1117\" stroke=\"#ef4444\" stroke-width=\"1.5\"/>\n  <circle cx=\"310\" cy=\"115\" r=\"26\" fill=\"#181111\"/>\n  <!-- Stopwatch Hand pointing to 3 min -->\n  <line x1=\"310\" y1=\"115\" x2=\"310\" y2=\"95\" stroke=\"#ef4444\" stroke-width=\"2\" stroke-linecap=\"round\"/>\n  <line x1=\"310\" y1=\"115\" x2=\"328\" y2=\"122\" stroke=\"#f59e0b\" stroke-width=\"1.8\" stroke-linecap=\"round\"/>\n  <circle cx=\"310\" cy=\"115\" r=\"3\" fill=\"#ffffff\"/>\n  <!-- 3-Min Arc Badge -->\n  <path d=\"M 310 93 A 22 22 0 0 1 332 115\" stroke=\"#22c55e\" stroke-width=\"3\" fill=\"none\"/>\n\n  <!-- Technical Callouts -->\n  <!-- Callout 1: Boiling 100°C (Label 2) -->\n  <line x1=\"165\" y1=\"154\" x2=\"115\" y2=\"75\" stroke=\"#9ca3af\" stroke-width=\"1\"/>\n  <circle cx=\"165\" cy=\"154\" r=\"2.5\" fill=\"#ef4444\"/>\n  <text x=\"24\" y=\"70\" fill=\"#f87171\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\" font-weight=\"bold\">BOILING 100°C (펄펄 끓이기)</text>\n\n  <!-- Callout 2: Time 3+ Min (Label 3) -->\n  <text x=\"376\" y=\"70\" fill=\"#f59e0b\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"end\">TIME: 3+ MIN (3분 이상)</text>\n\n  <!-- Callout 3: Pathogen Free (Label 4) -->\n  <line x1=\"240\" y1=\"160\" x2=\"285\" y2=\"165\" stroke=\"#22c55e\" stroke-width=\"1\"/>\n  <circle cx=\"240\" cy=\"160\" r=\"2.5\" fill=\"#22c55e\"/>\n  <text x=\"376\" y=\"165\" fill=\"#4ade80\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"end\">PATHOGEN FREE (세균 99.9% 사멸)</text>\n\n  <!-- Bottom Tactical Note Strip -->\n  <rect x=\"18\" y=\"340\" width=\"364\" height=\"34\" fill=\"#111419\" stroke=\"#262d35\" stroke-width=\"1\"/>\n  <rect x=\"18\" y=\"340\" width=\"4\" height=\"34\" fill=\"#ef4444\"/>\n  <!-- Label 5: Step Core Instruction -->\n  <text x=\"32\" y=\"361\" fill=\"#ffffff\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9.5\" font-weight=\"bold\">[5단계 핵심] 큰 거품이 솟구치도록 3분 이상 가열</text>\n</svg>\n","content/svgs/pr02-outcome.svg":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\" class=\"w-full h-auto\">\n  <defs>\n    <!-- Dark Tactical Backdrop -->\n    <linearGradient id=\"bgGrad2\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#0c0c0c\"/>\n      <stop offset=\"100%\" stop-color=\"#151313\"/>\n    </linearGradient>\n\n    <!-- Wood Shading -->\n    <linearGradient id=\"hearthWood\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#3d2d1e\"/>\n      <stop offset=\"40%\" stop-color=\"#694d34\"/>\n      <stop offset=\"70%\" stop-color=\"#4d3725\"/>\n      <stop offset=\"100%\" stop-color=\"#2b1f14\"/>\n    </linearGradient>\n    <linearGradient id=\"spindleWood\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#594432\"/>\n      <stop offset=\"50%\" stop-color=\"#806248\"/>\n      <stop offset=\"100%\" stop-color=\"#403022\"/>\n    </linearGradient>\n    <linearGradient id=\"bearingBlock\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#735c45\"/>\n      <stop offset=\"100%\" stop-color=\"#3b2d1e\"/>\n    </linearGradient>\n\n    <!-- Hot Glowing Ember & Fire Gradients -->\n    <radialGradient id=\"emberGlow\" cx=\"50%\" cy=\"50%\" r=\"50%\">\n      <stop offset=\"0%\" stop-color=\"#fffbeb\" stop-opacity=\"1\"/>\n      <stop offset=\"25%\" stop-color=\"#fef08a\" stop-opacity=\"0.9\"/>\n      <stop offset=\"55%\" stop-color=\"#f97316\" stop-opacity=\"0.8\"/>\n      <stop offset=\"85%\" stop-color=\"#dc2626\" stop-opacity=\"0.6\"/>\n      <stop offset=\"100%\" stop-color=\"#7f1d1d\" stop-opacity=\"0\"/>\n    </radialGradient>\n    <linearGradient id=\"flameGrad\" x1=\"0%\" y1=\"100%\" x2=\"0%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#ef4444\"/>\n      <stop offset=\"40%\" stop-color=\"#f97316\"/>\n      <stop offset=\"75%\" stop-color=\"#fde047\"/>\n      <stop offset=\"100%\" stop-color=\"#ffffff\"/>\n    </linearGradient>\n\n    <!-- Smoke Effect Filter -->\n    <filter id=\"smokeBlur\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feGaussianBlur stdDeviation=\"3\"/>\n    </filter>\n  </defs>\n\n  <!-- Technical Canvas Backdrop -->\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"450\" fill=\"url(#bgGrad2)\"/>\n  <rect x=\"15\" y=\"15\" width=\"770\" height=\"420\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Crosshairs -->\n  <path d=\"M 25 35 L 45 35 M 35 25 L 35 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 35 L 755 35 M 765 25 L 765 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 25 415 L 45 415 M 35 405 L 35 425\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 415 L 755 415 M 765 405 L 765 425\" stroke=\"#444\" stroke-width=\"1\"/>\n\n  <!-- Title & Top Metrics -->\n  <text x=\"35\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" letter-spacing=\"1\">ARCHIVE // OUTCOME SPECIFICATION</text>\n  <text x=\"35\" y=\"70\" fill=\"#E02424\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">TARGET: BOW DRILL FRICTION FIRE [EMBER IGNITION]</text>\n  <text x=\"765\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"end\">CORE TEMP: 400°C+</text>\n\n  <!-- Left Spec Box -->\n  <g id=\"specBoxLeft\" font-family=\"monospace\" font-size=\"10\">\n    <rect x=\"45\" y=\"100\" width=\"185\" height=\"155\" fill=\"#141414\" stroke=\"#333\" stroke-width=\"1\"/>\n    <rect x=\"45\" y=\"100\" width=\"185\" height=\"22\" fill=\"#1f1f1f\"/>\n    <text x=\"55\" y=\"115\" fill=\"#E02424\" font-weight=\"bold\">FRICTION MECHANICS</text>\n    <text x=\"55\" y=\"140\" fill=\"#aaa\">· NOTCH ANGLE: 45° V-CUT</text>\n    <text x=\"55\" y=\"160\" fill=\"#aaa\">· SPINDLE RPM: 400-600</text>\n    <text x=\"55\" y=\"180\" fill=\"#aaa\">· EMBER COLOR: DENSE CHERRY</text>\n    <text x=\"55\" y=\"200\" fill=\"#aaa\">· TINDER PREP: DRIED BAST</text>\n    <text x=\"55\" y=\"220\" fill=\"#aaa\">· COAL DUST: BLACK GRAPHITE</text>\n    <text x=\"55\" y=\"240\" fill=\"#f97316\">· BLOWING: GENTLE LONG BREATH</text>\n  </g>\n\n  <!-- Ground Plane Shadow -->\n  <ellipse cx=\"430\" cy=\"390\" rx=\"260\" ry=\"22\" fill=\"#050505\" opacity=\"0.9\"/>\n\n  <!-- Hearth Board (받침 판재) -->\n  <g id=\"hearthBoard\">\n    <!-- Main Plank Slab (Isometric 3D) -->\n    <polygon points=\"260,335 480,335 460,375 240,375\" fill=\"url(#hearthWood)\" stroke=\"#1a140d\" stroke-width=\"2\"/>\n    <polygon points=\"240,375 460,375 460,395 240,395\" fill=\"#241a10\" stroke=\"#1a140d\" stroke-width=\"2\"/>\n    <polygon points=\"460,375 480,335 480,355 460,395\" fill=\"#1f160e\" stroke=\"#1a140d\" stroke-width=\"2\"/>\n\n    <!-- Burn Socket & 45-degree V-Notch -->\n    <ellipse cx=\"360\" cy=\"350\" rx=\"14\" ry=\"7\" fill=\"#080808\" stroke=\"#111\" stroke-width=\"1.5\"/>\n    <polygon points=\"360,350 348,375 372,375\" fill=\"#050505\"/>\n\n    <!-- Catch Bark Tray Underneath Notch -->\n    <polygon points=\"335,372 385,372 395,388 325,388\" fill=\"#523d2b\" stroke=\"#332417\" stroke-width=\"1.5\"/>\n  </g>\n\n  <!-- Glowing Ember Coal (Hot 400°C) on Catch Tray -->\n  <g id=\"emberHot\">\n    <!-- Concentrated Red/Orange Glow Halo -->\n    <circle cx=\"360\" cy=\"378\" r=\"22\" fill=\"url(#emberGlow)\"/>\n    <!-- Black Carbon Powder Mound with Red Hot Core -->\n    <ellipse cx=\"360\" cy=\"380\" rx=\"12\" ry=\"6\" fill=\"#141414\"/>\n    <circle cx=\"359\" cy=\"379\" r=\"4.5\" fill=\"#ffedd5\"/>\n    <circle cx=\"362\" cy=\"378\" r=\"2\" fill=\"#ffffff\"/>\n    <circle cx=\"357\" cy=\"380\" r=\"1.5\" fill=\"#fde047\"/>\n\n    <!-- Rising Woodsmoke Wisps -->\n    <path d=\"M 360 372 Q 352 340 365 315 Q 375 290 358 260 Q 345 230 360 200\" stroke=\"#e2e8f0\" stroke-width=\"4\" fill=\"none\" opacity=\"0.35\" filter=\"url(#smokeBlur)\"/>\n    <path d=\"M 362 370 Q 370 335 358 310 Q 348 285 362 255\" stroke=\"#f1f5f9\" stroke-width=\"2.5\" fill=\"none\" opacity=\"0.45\" filter=\"url(#smokeBlur)\"/>\n  </g>\n\n  <!-- Spindle (회전봉) & Handhold Bearing Block -->\n  <g id=\"spindleAssembly\">\n    <!-- Vertical Spindle -->\n    <polygon points=\"354,150 366,150 364,348 356,348\" fill=\"url(#spindleWood)\" stroke=\"#261b13\" stroke-width=\"1.5\"/>\n    <!-- Bottom Carved Friction Tip (Charred) -->\n    <polygon points=\"356,345 364,345 362,352 358,352\" fill=\"#171717\"/>\n\n    <!-- Top Handhold Bearing Block -->\n    <path d=\"M 340 148 C 340 135 350 130 360 130 C 370 130 380 135 380 148 L 375 156 L 345 156 Z\" fill=\"url(#bearingBlock)\" stroke=\"#261b13\" stroke-width=\"1.8\"/>\n    <!-- Lubricant / Leaf Cushion Layer in Handhold Socket -->\n    <line x1=\"346\" y1=\"154\" x2=\"374\" y2=\"154\" stroke=\"#4ade80\" stroke-width=\"2\"/>\n  </g>\n\n  <!-- Bow & Taut Cord Wrapped Around Spindle -->\n  <g id=\"bowAndCord\">\n    <!-- Curved Wooden Bow Branch -->\n    <path d=\"M 230 290 Q 290 190 470 230\" fill=\"none\" stroke=\"#785336\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n    <path d=\"M 230 290 Q 290 190 470 230\" fill=\"none\" stroke=\"#47301e\" stroke-width=\"3\" stroke-linecap=\"round\"/>\n\n    <!-- Taut Rawhide / Fiber Bowstring Wrapped Once Around Spindle -->\n    <line x1=\"230\" y1=\"288\" x2=\"355\" y2=\"250\" stroke=\"#d4b483\" stroke-width=\"2.5\"/>\n    <!-- Wrap Turn around spindle shaft -->\n    <ellipse cx=\"360\" cy=\"250\" rx=\"7\" ry=\"3.5\" fill=\"#8c6c45\" stroke=\"#d4b483\" stroke-width=\"2\"/>\n    <line x1=\"365\" y1=\"250\" x2=\"470\" y2=\"228\" stroke=\"#d4b483\" stroke-width=\"2.5\"/>\n  </g>\n\n  <!-- Tinder Nest with Sprouting Flame (부싯깃 둥지 & 피어난 불꽃) -->\n  <g id=\"tinderNestAndFlame\">\n    <!-- Bird's Nest Bundle of Fibers -->\n    <ellipse cx=\"560\" cy=\"365\" rx=\"55\" ry=\"24\" fill=\"#36291a\" stroke=\"#241b12\" stroke-width=\"2\"/>\n    <path d=\"M 515 360 Q 560 380 605 360 M 520 370 Q 560 385 600 370 M 530 355 Q 560 370 590 355\" stroke=\"#78593a\" stroke-width=\"1.5\" fill=\"none\"/>\n\n    <!-- Blazing Fire Flame Center -->\n    <path d=\"M 560 355 C 540 340 535 305 555 270 C 560 288 568 295 565 275 C 575 285 585 310 580 340 C 585 330 588 318 584 305 C 595 320 592 345 575 355 Z\" fill=\"url(#flameGrad)\" filter=\"url(#smokeBlur)\"/>\n    <path d=\"M 560 355 C 545 342 542 312 555 280 C 559 295 566 300 564 285 C 572 295 580 315 576 342 C 580 334 582 324 579 315 C 588 326 585 346 572 355 Z\" fill=\"url(#flameGrad)\"/>\n    <!-- White Hot Core -->\n    <ellipse cx=\"563\" cy=\"345\" rx=\"8\" ry=\"14\" fill=\"#ffffff\" opacity=\"0.95\"/>\n    <ellipse cx=\"563\" cy=\"345\" rx=\"14\" ry=\"20\" fill=\"#fef08a\" opacity=\"0.7\"/>\n\n    <!-- Rising Flame Sparks & Smoke -->\n    <circle cx=\"550\" cy=\"245\" r=\"1.5\" fill=\"#f97316\"/>\n    <circle cx=\"568\" cy=\"230\" r=\"1.2\" fill=\"#fde047\"/>\n    <circle cx=\"562\" cy=\"210\" r=\"1\" fill=\"#f97316\"/>\n    <path d=\"M 560 260 Q 550 220 565 180 Q 575 150 560 120\" stroke=\"#cbd5e1\" stroke-width=\"3\" fill=\"none\" opacity=\"0.25\" filter=\"url(#smokeBlur)\"/>\n  </g>\n\n  <!-- Technical Callouts (Right Side) -->\n  <g id=\"calloutsRight\" font-family=\"monospace\" font-size=\"10\" fill=\"#cccccc\">\n    <!-- Callout 1: Handhold -->\n    <line x1=\"380\" y1=\"140\" x2=\"565\" y2=\"140\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"380\" cy=\"140\" r=\"2\" fill=\"#666\"/>\n    <text x=\"570\" y=\"137\" fill=\"#ffffff\" font-weight=\"bold\">TOP BEARING BLOCK</text>\n    <text x=\"570\" y=\"150\" fill=\"#888888\">윤활유/풀잎 삽입으로 상단 마찰 최소화</text>\n\n    <!-- Callout 2: Bow & String -->\n    <line x1=\"435\" y1=\"230\" x2=\"565\" y2=\"230\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"435\" cy=\"230\" r=\"2\" fill=\"#666\"/>\n    <text x=\"570\" y=\"227\" fill=\"#ffffff\" font-weight=\"bold\">BOW RIGGING (활비비 구동)</text>\n    <text x=\"570\" y=\"240\" fill=\"#888888\">1회 감김 텐션으로 고속 회전력 전달</text>\n\n    <!-- Callout 3: Ember Coal -->\n    <line x1=\"375\" y1=\"380\" x2=\"565\" y2=\"380\" stroke=\"#E02424\" stroke-width=\"1\"/>\n    <circle cx=\"375\" cy=\"380\" r=\"2\" fill=\"#E02424\"/>\n    <text x=\"570\" y=\"377\" fill=\"#E02424\" font-weight=\"bold\">STAGE 1: 400°C GLOWING EMBER</text>\n    <text x=\"570\" y=\"390\" fill=\"#888888\">V홈 숯가루가 잉걸불로 자가 연소</text>\n\n    <!-- Callout 4: Flame Nest -->\n    <line x1=\"560\" y1=\"310\" x2=\"565\" y2=\"310\" stroke=\"#f97316\" stroke-width=\"1\"/>\n    <circle cx=\"560\" cy=\"310\" r=\"2\" fill=\"#f97316\"/>\n    <text x=\"570\" y=\"307\" fill=\"#f97316\" font-weight=\"bold\">STAGE 2: SUSTAINED OPEN FLAME</text>\n    <text x=\"570\" y=\"320\" fill=\"#888888\">부싯깃 둥지 감싸 쥐고 완만한 호흡 착화</text>\n  </g>\n</svg>\n","content/svgs/pr03-outcome.svg":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\" class=\"w-full h-auto\">\n  <defs>\n    <linearGradient id=\"bgGrad3\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#0a0f0d\"/>\n      <stop offset=\"100%\" stop-color=\"#141916\"/>\n    </linearGradient>\n\n    <!-- Wood Trunk Gradients -->\n    <linearGradient id=\"ridgepoleWood\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#3f2e1d\"/>\n      <stop offset=\"50%\" stop-color=\"#694f34\"/>\n      <stop offset=\"100%\" stop-color=\"#2a1e12\"/>\n    </linearGradient>\n\n    <!-- Dense Leaf Blanket Texture Gradients -->\n    <linearGradient id=\"leafLayer\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#713f12\"/>\n      <stop offset=\"35%\" stop-color=\"#854d0e\"/>\n      <stop offset=\"70%\" stop-color=\"#a16207\"/>\n      <stop offset=\"100%\" stop-color=\"#4d3800\"/>\n    </linearGradient>\n    <radialGradient id=\"shelterInterior\" cx=\"50%\" cy=\"50%\" r=\"50%\">\n      <stop offset=\"0%\" stop-color=\"#050505\"/>\n      <stop offset=\"80%\" stop-color=\"#111111\"/>\n      <stop offset=\"100%\" stop-color=\"#1a1a1a\"/>\n    </radialGradient>\n  </defs>\n\n  <!-- Technical Canvas Backdrop -->\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"450\" fill=\"url(#bgGrad3)\"/>\n  <rect x=\"15\" y=\"15\" width=\"770\" height=\"420\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Crosshairs -->\n  <path d=\"M 25 35 L 45 35 M 35 25 L 35 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 35 L 755 35 M 765 25 L 765 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 25 415 L 45 415 M 35 405 L 35 425\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 415 L 755 415 M 765 405 L 765 425\" stroke=\"#444\" stroke-width=\"1\"/>\n\n  <!-- Metadata -->\n  <text x=\"35\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" letter-spacing=\"1\">ARCHIVE // OUTCOME SPECIFICATION</text>\n  <text x=\"35\" y=\"70\" fill=\"#E02424\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">TARGET: A-FRAME DEBRIS HUT [THERMAL SHELTER]</text>\n  <text x=\"765\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"end\">DEAD-AIR INSULATION: 1.0M</text>\n\n  <!-- Left Spec Box -->\n  <g id=\"specBoxLeft\" font-family=\"monospace\" font-size=\"10\">\n    <rect x=\"45\" y=\"100\" width=\"180\" height=\"155\" fill=\"#141414\" stroke=\"#333\" stroke-width=\"1\"/>\n    <rect x=\"45\" y=\"100\" width=\"180\" height=\"22\" fill=\"#1f1f1f\"/>\n    <text x=\"55\" y=\"115\" fill=\"#E02424\" font-weight=\"bold\">SHELTER METRICS</text>\n    <text x=\"55\" y=\"140\" fill=\"#aaa\">· RIDGEPOLE: 2.5-3.0 M</text>\n    <text x=\"55\" y=\"160\" fill=\"#aaa\">· ROOF PITCH: 45° SLANT</text>\n    <text x=\"55\" y=\"180\" fill=\"#aaa\">· LEAF THICKNESS: 100 CM</text>\n    <text x=\"55\" y=\"200\" fill=\"#aaa\">· GROUND BEDDING: 50 CM</text>\n    <text x=\"55\" y=\"220\" fill=\"#aaa\">· ENTRANCE: LOW BRAWL FIT</text>\n    <text x=\"55\" y=\"240\" fill=\"#4ade80\">· TEMP RETENTION: +15°C</text>\n  </g>\n\n  <!-- Forest Ground Base -->\n  <polygon points=\"120,410 680,410 740,360 200,360\" fill=\"#141a13\" opacity=\"0.8\"/>\n  <ellipse cx=\"450\" cy=\"390\" rx=\"240\" ry=\"22\" fill=\"#080c09\"/>\n\n  <!-- Debris Hut Main Volume (3D Sloping Dome) -->\n  <g id=\"debrisHutStructure\">\n    <!-- Back End Ground Anchor (Tail) -->\n    <ellipse cx=\"640\" cy=\"350\" rx=\"40\" ry=\"18\" fill=\"#1a140d\"/>\n\n    <!-- Thick 1-Meter Debris Leaf Mound Volume (Roof Shading) -->\n    <path d=\"M 330 155 C 390 145 520 220 650 345 L 610 380 C 490 385 360 385 240 375 C 230 330 260 200 330 155 Z\" fill=\"url(#leafLayer)\" stroke=\"#3f2305\" stroke-width=\"2\"/>\n\n    <!-- Highlighting Leaf Scales / Foliage Tufts -->\n    <g stroke=\"#a16207\" stroke-width=\"1.2\" fill=\"#854d0e\" opacity=\"0.85\">\n      <ellipse cx=\"370\" cy=\"210\" rx=\"18\" ry=\"10\"/>\n      <ellipse cx=\"410\" cy=\"230\" rx=\"22\" ry=\"12\"/>\n      <ellipse cx=\"460\" cy=\"250\" rx=\"20\" ry=\"11\"/>\n      <ellipse cx=\"510\" cy=\"280\" rx=\"24\" ry=\"13\"/>\n      <ellipse cx=\"560\" cy=\"310\" rx=\"22\" ry=\"12\"/>\n      <ellipse cx=\"350\" cy=\"260\" rx=\"20\" ry=\"11\"/>\n      <ellipse cx=\"390\" cy=\"280\" rx=\"22\" ry=\"12\"/>\n      <ellipse cx=\"440\" cy=\"300\" rx=\"24\" ry=\"14\"/>\n      <ellipse cx=\"490\" cy=\"330\" rx=\"25\" ry=\"13\"/>\n      <ellipse cx=\"310\" cy=\"300\" rx=\"18\" ry=\"10\"/>\n      <ellipse cx=\"350\" cy=\"325\" rx=\"22\" ry=\"12\"/>\n      <ellipse cx=\"400\" cy=\"340\" rx=\"24\" ry=\"13\"/>\n    </g>\n\n    <!-- Exterior Weighting Thatch Branches (바람막이 겉가지 격자) -->\n    <g stroke=\"#452e18\" stroke-width=\"3\" stroke-linecap=\"round\">\n      <line x1=\"335\" y1=\"170\" x2=\"270\" y2=\"365\"/>\n      <line x1=\"380\" y1=\"180\" x2=\"330\" y2=\"370\"/>\n      <line x1=\"435\" y1=\"210\" x2=\"395\" y2=\"375\"/>\n      <line x1=\"490\" y1=\"240\" x2=\"465\" y2=\"380\"/>\n      <line x1=\"550\" y1=\"280\" x2=\"530\" y2=\"380\"/>\n      <!-- Cross horizontal sticks -->\n      <line x1=\"290\" y1=\"280\" x2=\"540\" y2=\"305\"/>\n      <line x1=\"260\" y1=\"330\" x2=\"570\" y2=\"350\"/>\n    </g>\n\n    <!-- Front A-Frame Crutch Entrance Structure -->\n    <!-- Left A-Frame Post -->\n    <polygon points=\"230,370 240,370 338,150 330,150\" fill=\"url(#ridgepoleWood)\" stroke=\"#1a120b\" stroke-width=\"1.5\"/>\n    <!-- Right A-Frame Post -->\n    <polygon points=\"350,370 340,370 330,150 338,150\" fill=\"url(#ridgepoleWood)\" stroke=\"#1a120b\" stroke-width=\"1.5\"/>\n    <!-- Apex Notch Crotch -->\n    <ellipse cx=\"334\" cy=\"150\" rx=\"10\" ry=\"6\" fill=\"#523922\" stroke=\"#261b11\" stroke-width=\"1.5\"/>\n\n    <!-- Ridgepole Extending Through Apex to Back Tail -->\n    <polygon points=\"328,145 342,145 650,345 640,348\" fill=\"url(#ridgepoleWood)\" stroke=\"#261b11\" stroke-width=\"1.5\"/>\n\n    <!-- Small Snug Entrance Opening -->\n    <path d=\"M 260 370 C 260 280 320 280 320 370 Z\" fill=\"url(#shelterInterior)\" stroke=\"#291b10\" stroke-width=\"2\"/>\n\n    <!-- Entrance Door Plug (낙엽 차단 마개) Placed Beside Entry -->\n    <g id=\"doorPlug\">\n      <ellipse cx=\"230\" cy=\"380\" rx=\"26\" ry=\"16\" fill=\"#5c3a14\" stroke=\"#33200b\" stroke-width=\"1.5\"/>\n      <path d=\"M 215 375 Q 230 385 245 375\" stroke=\"#854d0e\" stroke-width=\"1.2\" fill=\"none\"/>\n    </g>\n  </g>\n\n  <!-- Technical Callouts (Right Side) -->\n  <g id=\"calloutsRight\" font-family=\"monospace\" font-size=\"10\" fill=\"#cccccc\">\n    <!-- Callout 1: Ridgepole -->\n    <line x1=\"335\" y1=\"150\" x2=\"565\" y2=\"150\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"335\" cy=\"150\" r=\"2\" fill=\"#666\"/>\n    <text x=\"570\" y=\"147\" fill=\"#ffffff\" font-weight=\"bold\">HEAVY RIDGEPOLE (용마루)</text>\n    <text x=\"570\" y=\"160\" fill=\"#888888\">성인 체중을 견디는 굵은 주 기둥 안착</text>\n\n    <!-- Callout 2: Debris Layer -->\n    <line x1=\"440\" y1=\"240\" x2=\"565\" y2=\"240\" stroke=\"#E02424\" stroke-width=\"1\"/>\n    <circle cx=\"440\" cy=\"240\" r=\"2\" fill=\"#E02424\"/>\n    <text x=\"570\" y=\"237\" fill=\"#E02424\" font-weight=\"bold\">1-METER DEBRIS INSULATION</text>\n    <text x=\"570\" y=\"250\" fill=\"#888888\">마른 낙엽 1미터로 영하권 체온 손실 방지</text>\n\n    <!-- Callout 3: Thatch Lattice -->\n    <line x1=\"510\" y1=\"310\" x2=\"565\" y2=\"310\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"510\" cy=\"310\" r=\"2\" fill=\"#666\"/>\n    <text x=\"570\" y=\"307\" fill=\"#ffffff\" font-weight=\"bold\">THATCH TRELLIS (겉가지 격자)</text>\n    <text x=\"570\" y=\"320\" fill=\"#888888\">돌풍에 낙엽이 날리지 않게 상단 누름 고정</text>\n\n    <!-- Callout 4: Snug Entrance & Plug -->\n    <line x1=\"285\" y1=\"350\" x2=\"565\" y2=\"350\" stroke=\"#4ade80\" stroke-width=\"1\"/>\n    <circle cx=\"285\" cy=\"350\" r=\"2\" fill=\"#4ade80\"/>\n    <text x=\"570\" y=\"347\" fill=\"#4ade80\" font-weight=\"bold\">LOW ENTRANCE &amp; DOOR PLUG</text>\n    <text x=\"570\" y=\"360\" fill=\"#888888\">기어 들어갈 크기 + 취침 시 마개 차단</text>\n  </g>\n</svg>\n","content/svgs/pr03-step-01.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full max-w-2xl h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arrow-white\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#F5F5F5\" />\n    </marker>\n    <marker id=\"arrow-red\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#E02424\" />\n    </marker>\n  </defs>\n\n  <!-- Outer Frame Guideline -->\n  <rect x=\"10\" y=\"10\" width=\"660\" height=\"320\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"4,4\" />\n\n  <!-- Rule Callout Box -->\n  <rect x=\"25\" y=\"24\" width=\"330\" height=\"44\" fill=\"#141414\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"35\" y=\"41\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">움막 크기 핵심 규칙:</text>\n  <text x=\"35\" y=\"58\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\">몸이 겨우 들어갈 크기 (어깨 옆 주먹 1개 여유)</text>\n\n  <!-- Ground Baseline -->\n  <line x1=\"40\" y1=\"265\" x2=\"640\" y2=\"265\" stroke=\"#666666\" stroke-width=\"2\" />\n  <line x1=\"60\" y1=\"273\" x2=\"620\" y2=\"273\" stroke=\"#333333\" stroke-width=\"1\" stroke-dasharray=\"6,4\" />\n\n  <!-- Windward Force Vector (Left Side) -->\n  <line x1=\"45\" y1=\"195\" x2=\"115\" y2=\"195\" stroke=\"#E02424\" stroke-width=\"1.8\" marker-end=\"url(#arrow-red)\" />\n  <line x1=\"45\" y1=\"215\" x2=\"105\" y2=\"215\" stroke=\"#E02424\" stroke-width=\"1.2\" stroke-dasharray=\"3,2\" marker-end=\"url(#arrow-red)\" />\n  <text x=\"45\" y=\"182\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">바람 불어오는 쪽 (바닥에 고정)</text>\n\n  <!-- Main Ridgepole (3.0~3.5m Hardwood Spine) from (110, 265) to (490, 115) -->\n  <polygon points=\"105,265 492,110 498,124 125,265\" fill=\"#262626\" stroke=\"#F5F5F5\" stroke-width=\"2\" />\n  <!-- Ground Stake / Anchor at Windward Tail -->\n  <polygon points=\"102,248 112,248 112,282 102,282\" fill=\"#E02424\" stroke=\"#F5F5F5\" stroke-width=\"1.2\" />\n\n  <!-- Ridgepole Label & Leader Line -->\n  <line x1=\"280\" y1=\"190\" x2=\"250\" y2=\"132\" stroke=\"#AAAAAA\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n  <text x=\"165\" y=\"124\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">중심 기둥 나무: 길이 3.0~3.5m</text>\n\n  <!-- Y-Frame Bipod Support Sticks at Entrance (Apex at 490, 118) -->\n  <line x1=\"445\" y1=\"265\" x2=\"508\" y2=\"92\" stroke=\"#CCCCCC\" stroke-width=\"5\" />\n  <line x1=\"535\" y1=\"265\" x2=\"472\" y2=\"92\" stroke=\"#999999\" stroke-width=\"5\" />\n  <!-- Vine Lashing Node at Apex -->\n  <circle cx=\"490\" cy=\"116\" r=\"11\" fill=\"#141414\" stroke=\"#E02424\" stroke-width=\"2\" />\n  <line x1=\"481\" y1=\"112\" x2=\"499\" y2=\"120\" stroke=\"#F5F5F5\" stroke-width=\"1.5\" />\n  <line x1=\"481\" y1=\"120\" x2=\"499\" y2=\"112\" stroke=\"#F5F5F5\" stroke-width=\"1.5\" />\n\n  <!-- Lashing Node Label -->\n  <line x1=\"490\" y1=\"102\" x2=\"490\" y2=\"68\" stroke=\"#E02424\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n  <text x=\"490\" y=\"60\" fill=\"#E5E5E5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" text-anchor=\"middle\">Y자 기둥 2개 맞물려 묶기</text>\n\n  <!-- Interior Prone Body Clearance Envelope (Coffin Spec) -->\n  <path d=\"M 165,258 L 455,258 L 455,212 L 385,205 L 165,242 Z\" fill=\"#1c1b1b\" stroke=\"#888888\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\" />\n  <!-- Clearance Gap Arrows (+10cm Fist Tolerance) -->\n  <line x1=\"365\" y1=\"172\" x2=\"365\" y2=\"205\" stroke=\"#E02424\" stroke-width=\"1.5\" marker-end=\"url(#arrow-red)\" />\n  <text x=\"340\" y=\"298\" fill=\"#CCCCCC\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" text-anchor=\"middle\">내부 공간: 몸 둘레 + 10cm (주먹 1개 여유)</text>\n\n  <!-- Vertical Elevation Dimension (0.8 ~ 1.0m) on Right -->\n  <line x1=\"575\" y1=\"116\" x2=\"575\" y2=\"265\" stroke=\"#F5F5F5\" stroke-width=\"1.2\" />\n  <line x1=\"565\" y1=\"116\" x2=\"585\" y2=\"116\" stroke=\"#F5F5F5\" stroke-width=\"1.5\" />\n  <line x1=\"565\" y1=\"265\" x2=\"585\" y2=\"265\" stroke=\"#F5F5F5\" stroke-width=\"1.5\" />\n  <text x=\"655\" y=\"194\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">입구 높이: 0.8~1.0m</text>\n</svg>\n","content/svgs/pr03-step-02.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full max-w-2xl h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arrow-white\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#F5F5F5\" />\n    </marker>\n    <marker id=\"arrow-red\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#E02424\" />\n    </marker>\n  </defs>\n\n  <!-- Outer Frame Guideline -->\n  <rect x=\"10\" y=\"10\" width=\"660\" height=\"320\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"4,4\" />\n\n  <!-- Rule Callout Box -->\n  <rect x=\"25\" y=\"24\" width=\"335\" height=\"44\" fill=\"#141414\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"35\" y=\"41\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">바닥 냉기 차단 핵심:</text>\n  <text x=\"35\" y=\"58\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\">마른 낙엽을 두껍게 깔아 눌린 뒤에도 20cm 유지</text>\n\n  <!-- Ground Baseline -->\n  <line x1=\"60\" y1=\"265\" x2=\"620\" y2=\"265\" stroke=\"#666666\" stroke-width=\"2\" />\n\n  <!-- Cross-Section A-Frame Rib Lattice (Center X = 340, Apex Y = 88) -->\n  <!-- Left & Right Rib Poles at 52° Pitch -->\n  <line x1=\"340\" y1=\"88\" x2=\"185\" y2=\"265\" stroke=\"#F5F5F5\" stroke-width=\"4\" />\n  <line x1=\"340\" y1=\"88\" x2=\"495\" y2=\"265\" stroke=\"#F5F5F5\" stroke-width=\"4\" />\n  <!-- Secondary Lattice Branches -->\n  <line x1=\"295\" y1=\"138\" x2=\"412\" y2=\"170\" stroke=\"#777777\" stroke-width=\"1.5\" stroke-dasharray=\"5,3\" />\n  <line x1=\"255\" y1=\"184\" x2=\"445\" y2=\"208\" stroke=\"#777777\" stroke-width=\"1.5\" stroke-dasharray=\"5,3\" />\n\n  <!-- Ridgepole Cross-Section Circle at Apex -->\n  <circle cx=\"340\" cy=\"88\" r=\"14\" fill=\"#262626\" stroke=\"#E02424\" stroke-width=\"2.5\" />\n  <circle cx=\"340\" cy=\"88\" r=\"4\" fill=\"#F5F5F5\" />\n  <line x1=\"354\" y1=\"84\" x2=\"430\" y2=\"56\" stroke=\"#AAAAAA\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n  <text x=\"436\" y=\"59\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">중심 기둥 나무 (단면)</text>\n\n  <!-- Rib Pitch Angle Indicator (45° ~ 60°) -->\n  <path d=\"M 222,265 A 36 36 0 0 0 209,238\" fill=\"none\" stroke=\"#E02424\" stroke-width=\"1.8\" />\n  <line x1=\"252\" y1=\"188\" x2=\"175\" y2=\"145\" stroke=\"#AAAAAA\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n  <text x=\"35\" y=\"140\" fill=\"#E5E5E5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\">양옆 나뭇가지: 45°~60° 각도로 촘촘히 세우기</text>\n\n  <!-- Interior Floor Mattress: Initial 40cm Mound (Dashed) & Compressed 15~20cm Core (Solid) -->\n  <path d=\"M 215,265 Q 340,175 465,265 Z\" fill=\"#1c1b1b\" stroke=\"#888888\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\" />\n  <rect x=\"215\" y=\"222\" width=\"250\" height=\"43\" fill=\"#252323\" stroke=\"#E02424\" stroke-width=\"2\" />\n  <!-- Texture lines inside mattress -->\n  <line x1=\"230\" y1=\"236\" x2=\"450\" y2=\"236\" stroke=\"#666666\" stroke-width=\"1\" stroke-dasharray=\"8,4\" />\n  <line x1=\"225\" y1=\"250\" x2=\"455\" y2=\"250\" stroke=\"#666666\" stroke-width=\"1\" stroke-dasharray=\"6,5\" />\n\n  <!-- Mattress Dimension Callout on Right -->\n  <line x1=\"470\" y1=\"235\" x2=\"520\" y2=\"205\" stroke=\"#E02424\" stroke-width=\"1.2\" marker-end=\"url(#arrow-red)\" />\n  <text x=\"655\" y=\"200\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">낙엽 이불: 40cm → 눌린 뒤 20cm</text>\n\n  <!-- Ground Cold Conduction Blocked Vectors (Bottom) -->\n  <line x1=\"270\" y1=\"292\" x2=\"270\" y2=\"270\" stroke=\"#E02424\" stroke-width=\"1.5\" marker-end=\"url(#arrow-red)\" />\n  <line x1=\"340\" y1=\"292\" x2=\"340\" y2=\"270\" stroke=\"#E02424\" stroke-width=\"1.5\" marker-end=\"url(#arrow-red)\" />\n  <line x1=\"410\" y1=\"292\" x2=\"410\" y2=\"270\" stroke=\"#E02424\" stroke-width=\"1.5\" marker-end=\"url(#arrow-red)\" />\n  <text x=\"340\" y=\"314\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">땅에서 올라오는 찬 기운 완벽 차단</text>\n</svg>","content/svgs/pr03-step-03.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full max-w-2xl h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arrow-white\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#F5F5F5\" />\n    </marker>\n    <marker id=\"arrow-red\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#E02424\" />\n    </marker>\n  </defs>\n\n  <!-- Outer Frame Guideline -->\n  <rect x=\"10\" y=\"10\" width=\"660\" height=\"320\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"4,4\" />\n\n  <!-- Rule Callout Box -->\n  <rect x=\"25\" y=\"24\" width=\"335\" height=\"44\" fill=\"#141414\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"35\" y=\"41\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">지붕 낙엽 쌓기 &amp; 입구 막기:</text>\n  <text x=\"35\" y=\"58\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\">지붕에 낙엽을 팔 길이(60~90cm)로 쌓고 입구 막기</text>\n\n  <!-- Ground Baseline -->\n  <line x1=\"45\" y1=\"268\" x2=\"635\" y2=\"268\" stroke=\"#666666\" stroke-width=\"2\" />\n\n  <!-- Outer Heavy Deadwood Wind-Armor Layer (Outer Mound) -->\n  <path d=\"M 95,268 Q 340,22 585,268 Z\" fill=\"#191818\" stroke=\"#F5F5F5\" stroke-width=\"2.2\" />\n  <!-- Shingled Debris Layer (60~90cm Thickness Zone) -->\n  <path d=\"M 135,268 Q 340,68 545,268 Z\" fill=\"#222020\" stroke=\"#888888\" stroke-width=\"1.5\" stroke-dasharray=\"6,3\" />\n\n  <!-- Inner Rib Core & Dead-Air Thermal Chamber -->\n  <polygon points=\"340,142 230,268 450,268\" fill=\"#121212\" stroke=\"#E02424\" stroke-width=\"2\" />\n  <!-- Entrance Debris Plug / Seal Indicator inside Chamber -->\n  <circle cx=\"340\" cy=\"222\" r=\"24\" fill=\"#291414\" stroke=\"#E02424\" stroke-width=\"1.8\" stroke-dasharray=\"3,2\" />\n  <path d=\"M 326,222 L 354,222 M 340,208 L 340,236\" stroke=\"#E02424\" stroke-width=\"1.5\" />\n\n  <!-- 60~90cm Thickness Dimension Callout (Left Slope) -->\n  <line x1=\"185\" y1=\"162\" x2=\"255\" y2=\"212\" stroke=\"#E02424\" stroke-width=\"2\" marker-end=\"url(#arrow-red)\" />\n  <line x1=\"185\" y1=\"162\" x2=\"135\" y2=\"128\" stroke=\"#AAAAAA\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n  <text x=\"30\" y=\"120\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">마른 낙엽 벽: 60~90cm 두께</text>\n\n  <!-- Heavy Deadwood Armor Callout (Right Slope) -->\n  <line x1=\"455\" y1=\"118\" x2=\"505\" y2=\"75\" stroke=\"#AAAAAA\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n  <text x=\"655\" y=\"70\" fill=\"#E5E5E5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" text-anchor=\"end\">바람에 안 날리게 무거운 가지 덮기</text>\n\n  <!-- Rain / Wind Shedding Vector on Right Slope -->\n  <line x1=\"505\" y1=\"145\" x2=\"575\" y2=\"215\" stroke=\"#F5F5F5\" stroke-width=\"1.5\" marker-end=\"url(#arrow-white)\" />\n  <text x=\"655\" y=\"142\" fill=\"#AAAAAA\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\" text-anchor=\"end\">빗물이 타고 흐르는 경사면</text>\n\n  <!-- Dead Air Space & Entrance Plug Label (Bottom Center) -->\n  <line x1=\"340\" y1=\"246\" x2=\"340\" y2=\"292\" stroke=\"#E02424\" stroke-width=\"1.2\" />\n  <text x=\"340\" y=\"312\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">따뜻한 공기가 갇힌 내부 &amp; 낙엽 마개</text>\n</svg>","content/svgs/pr04-outcome.svg":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\" class=\"w-full h-auto\">\n  <defs>\n    <linearGradient id=\"bgGrad4\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#0c0d0e\"/>\n      <stop offset=\"100%\" stop-color=\"#14171a\"/>\n    </linearGradient>\n\n    <!-- Haft Wood Texture -->\n    <linearGradient id=\"haftWood\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#3d2c1d\"/>\n      <stop offset=\"35%\" stop-color=\"#694e36\"/>\n      <stop offset=\"70%\" stop-color=\"#523c28\"/>\n      <stop offset=\"100%\" stop-color=\"#2b1e12\"/>\n    </linearGradient>\n\n    <!-- Stone Axe Head (Chert / Basalt Flint) -->\n    <linearGradient id=\"flintStone\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#474747\"/>\n      <stop offset=\"40%\" stop-color=\"#2e2e2e\"/>\n      <stop offset=\"80%\" stop-color=\"#1a1a1a\"/>\n      <stop offset=\"100%\" stop-color=\"#0f0f0f\"/>\n    </linearGradient>\n\n    <!-- Pine Pitch Resin Glue -->\n    <linearGradient id=\"pitchResin\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#1c1106\"/>\n      <stop offset=\"50%\" stop-color=\"#42290d\"/>\n      <stop offset=\"100%\" stop-color=\"#0f0802\"/>\n    </linearGradient>\n\n    <!-- Raw Vine Lashing -->\n    <linearGradient id=\"vineLashing\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#a8895b\"/>\n      <stop offset=\"50%\" stop-color=\"#7a623e\"/>\n      <stop offset=\"100%\" stop-color=\"#4f3e26\"/>\n    </linearGradient>\n  </defs>\n\n  <!-- Canvas Backdrop -->\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"450\" fill=\"url(#bgGrad4)\"/>\n  <rect x=\"15\" y=\"15\" width=\"770\" height=\"420\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Crosshairs -->\n  <path d=\"M 25 35 L 45 35 M 35 25 L 35 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 35 L 755 35 M 765 25 L 765 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 25 415 L 45 415 M 35 405 L 35 425\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 415 L 755 415 M 765 405 L 765 425\" stroke=\"#444\" stroke-width=\"1\"/>\n\n  <!-- Title & Top Metrics -->\n  <text x=\"35\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" letter-spacing=\"1\">ARCHIVE // OUTCOME SPECIFICATION</text>\n  <text x=\"35\" y=\"70\" fill=\"#E02424\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">TARGET: PRIMITIVE STONE AXE [BIFACIAL CHERT]</text>\n  <text x=\"765\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"end\">TENSILE RATING: 80 KGF</text>\n\n  <!-- Left Spec Box -->\n  <g id=\"specBoxLeft\" font-family=\"monospace\" font-size=\"10\">\n    <rect x=\"45\" y=\"100\" width=\"180\" height=\"155\" fill=\"#141414\" stroke=\"#333\" stroke-width=\"1\"/>\n    <rect x=\"45\" y=\"100\" width=\"180\" height=\"22\" fill=\"#1f1f1f\"/>\n    <text x=\"55\" y=\"115\" fill=\"#E02424\" font-weight=\"bold\">AXE SPECIFICATIONS</text>\n    <text x=\"55\" y=\"140\" fill=\"#aaa\">· STONE: RIVER BASALT/FLINT</text>\n    <text x=\"55\" y=\"160\" fill=\"#aaa\">· BEVEL: 35° BIFACE EDGE</text>\n    <text x=\"55\" y=\"180\" fill=\"#aaa\">· HAFT: DRIED OAK / HICKORY</text>\n    <text x=\"55\" y=\"200\" fill=\"#aaa\">· BINDING: X-CROSS VINE</text>\n    <text x=\"55\" y=\"220\" fill=\"#aaa\">· RESIN: PINE PITCH + ASH</text>\n    <text x=\"55\" y=\"240\" fill=\"#38bdf8\">· CHOPPING EFF: 10 CM / 5 MIN</text>\n  </g>\n\n  <!-- Shadow Under Stone Axe -->\n  <ellipse cx=\"440\" cy=\"380\" rx=\"200\" ry=\"16\" fill=\"#050505\" opacity=\"0.9\"/>\n\n  <!-- Complete Stone Axe Assembly -->\n  <g id=\"axeAssembly\" transform=\"rotate(-15 420 250)\">\n    <!-- Wooden Haft Handle (Diagonal Solid Club) -->\n    <path d=\"M 280 230 C 310 232 440 242 560 250 C 585 252 600 256 600 268 C 600 280 580 282 560 280 C 440 270 310 255 280 250 Z\" fill=\"url(#haftWood)\" stroke=\"#1a120b\" stroke-width=\"2\"/>\n\n    <!-- Forked Cleft / Socket at Head End -->\n    <path d=\"M 285 220 C 265 215 250 200 250 185 L 295 190 C 295 210 285 220 285 220 Z\" fill=\"#241a10\" stroke=\"#120c07\" stroke-width=\"1.5\"/>\n\n    <!-- Chipped Basalt/Flint Stone Axe Blade Head -->\n    <polygon points=\"210,135 295,155 315,225 240,240 185,190\" fill=\"url(#flintStone)\" stroke=\"#111111\" stroke-width=\"2\"/>\n    <!-- Chipping Facets & Flaking Edges (Realistic Bifacial Flakes) -->\n    <polygon points=\"210,135 250,155 235,175 195,160\" fill=\"#3d3d3d\" stroke=\"#222\" stroke-width=\"1\"/>\n    <polygon points=\"250,155 295,155 280,185 235,175\" fill=\"#4d4d4d\" stroke=\"#222\" stroke-width=\"1\"/>\n    <polygon points=\"195,160 235,175 225,210 185,190\" fill=\"#262626\" stroke=\"#111\" stroke-width=\"1\"/>\n    <polygon points=\"235,175 280,185 270,220 225,210\" fill=\"#363636\" stroke=\"#222\" stroke-width=\"1\"/>\n    <polygon points=\"280,185 315,225 270,220\" fill=\"#1f1f1f\" stroke=\"#111\" stroke-width=\"1\"/>\n    <!-- Razor-Sharp Front Cutting Edge Highlight -->\n    <path d=\"M 210 135 L 185 190 L 240 240\" fill=\"none\" stroke=\"#e0e0e0\" stroke-width=\"1.8\" stroke-linecap=\"round\"/>\n\n    <!-- Black Pine Pitch Resin Adhesive Layer Sealing Socket -->\n    <ellipse cx=\"285\" cy=\"225\" rx=\"30\" ry=\"20\" fill=\"url(#pitchResin)\" opacity=\"0.95\"/>\n\n    <!-- Tight Criss-Cross Vine / Rawhide Lashings (X-Lashing Pattern) -->\n    <g stroke=\"url(#vineLashing)\" stroke-width=\"3.5\" stroke-linecap=\"round\">\n      <!-- Diagonal Forward Turns -->\n      <line x1=\"260\" y1=\"210\" x2=\"310\" y2=\"255\"/>\n      <line x1=\"265\" y1=\"205\" x2=\"315\" y2=\"250\"/>\n      <line x1=\"270\" y1=\"200\" x2=\"320\" y2=\"245\"/>\n      <!-- Diagonal Backward Turns (Crossing to form X) -->\n      <line x1=\"310\" y1=\"210\" x2=\"260\" y2=\"255\"/>\n      <line x1=\"315\" y1=\"205\" x2=\"265\" y2=\"250\"/>\n      <line x1=\"320\" y1=\"200\" x2=\"270\" y2=\"245\"/>\n      <!-- Tight Frapping Turns Around Socket Base -->\n      <line x1=\"280\" y1=\"250\" x2=\"280\" y2=\"265\" stroke-width=\"4\"/>\n      <line x1=\"288\" y1=\"248\" x2=\"288\" y2=\"263\" stroke-width=\"4\"/>\n    </g>\n\n    <!-- Handle Grip Carvings / Notches -->\n    <line x1=\"520\" y1=\"248\" x2=\"520\" y2=\"276\" stroke=\"#241a10\" stroke-width=\"1.5\"/>\n    <line x1=\"535\" y1=\"250\" x2=\"535\" y2=\"278\" stroke=\"#241a10\" stroke-width=\"1.5\"/>\n    <line x1=\"550\" y1=\"252\" x2=\"550\" y2=\"280\" stroke=\"#241a10\" stroke-width=\"1.5\"/>\n  </g>\n\n  <!-- Technical Callouts (Right Side) -->\n  <g id=\"calloutsRight\" font-family=\"monospace\" font-size=\"10\" fill=\"#cccccc\">\n    <!-- Callout 1: Stone Blade -->\n    <line x1=\"260\" y1=\"140\" x2=\"565\" y2=\"140\" stroke=\"#E02424\" stroke-width=\"1\"/>\n    <circle cx=\"260\" cy=\"140\" r=\"2\" fill=\"#E02424\"/>\n    <text x=\"570\" y=\"137\" fill=\"#E02424\" font-weight=\"bold\">CHIPPED BIFACE STONE BLADE</text>\n    <text x=\"570\" y=\"150\" fill=\"#888888\">양면 박편 타제로 세운 35도 예리한 절삭날</text>\n\n    <!-- Callout 2: Resin Seal -->\n    <line x1=\"350\" y1=\"210\" x2=\"565\" y2=\"210\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"350\" cy=\"210\" r=\"2\" fill=\"#666\"/>\n    <text x=\"570\" y=\"207\" fill=\"#ffffff\" font-weight=\"bold\">PINE PITCH COMPOSITE SEAL</text>\n    <text x=\"570\" y=\"220\" fill=\"#888888\">송진과 숯가루 혼합재로 유격 100% 밀봉</text>\n\n    <!-- Callout 3: Cross Lashing -->\n    <line x1=\"330\" y1=\"280\" x2=\"565\" y2=\"280\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"330\" cy=\"280\" r=\"2\" fill=\"#666\"/>\n    <text x=\"570\" y=\"277\" fill=\"#ffffff\" font-weight=\"bold\">X-CROSS VINE LASHING</text>\n    <text x=\"570\" y=\"290\" fill=\"#888888\">충격을 흡수 분산하는 십자 결속 및 프래핑</text>\n\n    <!-- Callout 4: Oak Haft -->\n    <line x1=\"490\" y1=\"340\" x2=\"565\" y2=\"340\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n    <circle cx=\"490\" cy=\"340\" r=\"2\" fill=\"#38bdf8\"/>\n    <text x=\"570\" y=\"337\" fill=\"#38bdf8\" font-weight=\"bold\">HARDENED OAK HAFT</text>\n    <text x=\"570\" y=\"350\" fill=\"#888888\">불에 그슬려 경화한 묵직한 참나무 손잡이</text>\n  </g>\n</svg>\n","content/svgs/pr04-step-01.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full max-w-2xl h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arrow\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#E02424\" />\n    </marker>\n    <marker id=\"arrow-white\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#F5F5F5\" />\n    </marker>\n  </defs>\n\n  <!-- Background technical coordinate lines -->\n  <rect x=\"0\" y=\"0\" width=\"680\" height=\"340\" fill=\"#131313\" />\n  <rect x=\"10\" y=\"10\" width=\"660\" height=\"320\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"4 4\" />\n  <line x1=\"340\" y1=\"20\" x2=\"340\" y2=\"320\" stroke=\"#222222\" stroke-width=\"1\" />\n\n  <!-- Core River Stone (Base Cobble) -->\n  <path d=\"M 220 275 C 180 265 145 225 155 180 C 165 140 210 130 260 135 C 310 140 345 165 350 210 C 355 250 310 280 220 275 Z\" \n        fill=\"#1c1b1b\" stroke=\"#F5F5F5\" stroke-width=\"1.8\" />\n  \n  <!-- Flake detachment line & fracture cone -->\n  <path d=\"M 310 150 Q 325 180 340 215\" stroke=\"#E02424\" stroke-width=\"2.2\" stroke-dasharray=\"3 3\" />\n  <path d=\"M 340 215 C 360 210 395 185 400 160 C 390 145 350 140 310 150 Z\" \n        fill=\"#262626\" stroke=\"#E02424\" stroke-width=\"2\" />\n\n  <!-- Detached Sharp Axe Blade (Separating Flake) -->\n  <path d=\"M 430 190 Q 480 145 520 180 Q 490 225 430 190 Z\" \n        fill=\"#1a1a1a\" stroke=\"#F5F5F5\" stroke-width=\"2\" />\n  <path d=\"M 430 190 Q 475 160 520 180\" stroke=\"#E02424\" stroke-width=\"2\" />\n\n  <!-- Hammerstone (Striking Stone) -->\n  <ellipse cx=\"280\" cy=\"70\" rx=\"42\" ry=\"30\" fill=\"#222222\" stroke=\"#F5F5F5\" stroke-width=\"1.8\" transform=\"rotate(-25 280 70)\" />\n  \n  <!-- 45 Degree Kinetic Strike Vector -->\n  <line x1=\"260\" y1=\"85\" x2=\"310\" y2=\"148\" stroke=\"#E02424\" stroke-width=\"3\" marker-end=\"url(#arrow)\" />\n  \n  <!-- 45 Degree Angle Arc & Guide Lines -->\n  <line x1=\"310\" y1=\"150\" x2=\"380\" y2=\"150\" stroke=\"#737373\" stroke-width=\"1\" stroke-dasharray=\"3 3\" />\n  <line x1=\"310\" y1=\"150\" x2=\"260\" y2=\"90\" stroke=\"#737373\" stroke-width=\"1\" stroke-dasharray=\"3 3\" />\n  <path d=\"M 350 150 A 40 40 0 0 0 338 122\" fill=\"none\" stroke=\"#E02424\" stroke-width=\"1.8\" />\n\n  <!-- Technical dimension line -->\n  <line x1=\"155\" y1=\"295\" x2=\"350\" y2=\"295\" stroke=\"#525252\" stroke-width=\"1\" />\n  <line x1=\"155\" y1=\"290\" x2=\"155\" y2=\"300\" stroke=\"#525252\" stroke-width=\"1\" />\n  <line x1=\"350\" y1=\"290\" x2=\"350\" y2=\"300\" stroke=\"#525252\" stroke-width=\"1\" />\n\n  <!-- 5 Clear Korean labels placed in non-overlapping safe zones -->\n  <rect x=\"25\" y=\"28\" width=\"205\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"35\" y=\"44\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#F5F5F5\">① 둥근 망치돌 (내리치는 돌)</text>\n\n  <rect x=\"25\" y=\"84\" width=\"215\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"35\" y=\"100\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#E02424\">② 모서리 45° 비스듬히 치기</text>\n\n  <rect x=\"420\" y=\"112\" width=\"225\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"430\" y=\"128\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#E02424\" font-weight=\"bold\">날카로운 돌날 (두께 1~2cm)</text>\n\n  <rect x=\"420\" y=\"245\" width=\"230\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"430\" y=\"261\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#F5F5F5\">④ 쪼개져 나온 도끼날 돌조각</text>\n\n  <text x=\"250\" y=\"316\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#9E9E9E\" text-anchor=\"middle\">③ 바닥에 받친 큰 강돌 (너비 15~20cm)</text>\n</svg>\n","content/svgs/pr04-step-02.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full max-w-2xl h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arrow\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#E02424\" />\n    </marker>\n  </defs>\n\n  <rect x=\"0\" y=\"0\" width=\"680\" height=\"340\" fill=\"#131313\" />\n  <rect x=\"10\" y=\"10\" width=\"660\" height=\"320\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"4 4\" />\n\n  <!-- Wooden Handle (Shaft) -->\n  <path d=\"M 315 170 L 315 275 L 355 275 L 355 170 Z\" fill=\"#201f1f\" stroke=\"#F5F5F5\" stroke-width=\"1.8\" />\n  \n  <!-- Split Cleft Head (Two tines separated) -->\n  <path d=\"M 315 170 C 315 140 280 110 270 70 L 305 70 C 315 105 330 135 335 170 Z\" fill=\"#292828\" stroke=\"#F5F5F5\" stroke-width=\"1.8\" />\n  <path d=\"M 355 170 C 355 140 390 110 400 70 L 365 70 C 355 105 340 135 335 170 Z\" fill=\"#292828\" stroke=\"#F5F5F5\" stroke-width=\"1.8\" />\n\n  <!-- Split stop safety collar notch -->\n  <line x1=\"300\" y1=\"172\" x2=\"370\" y2=\"172\" stroke=\"#E02424\" stroke-width=\"2.2\" stroke-dasharray=\"3 2\" />\n\n  <!-- Melted Pine Resin + Charcoal Glue Bedding (Inside cleft) -->\n  <path d=\"M 305 130 C 315 150 335 168 335 168 C 335 168 355 150 365 130 C 355 110 315 110 305 130 Z\" \n        fill=\"#78350f\" stroke=\"#d97706\" stroke-width=\"1.5\" />\n  <circle cx=\"325\" cy=\"140\" r=\"2.5\" fill=\"#171717\" />\n  <circle cx=\"335\" cy=\"132\" r=\"2\" fill=\"#171717\" />\n  <circle cx=\"345\" cy=\"142\" r=\"2.5\" fill=\"#171717\" />\n  <circle cx=\"335\" cy=\"150\" r=\"1.8\" fill=\"#171717\" />\n\n  <!-- Wedged Stone Blade in Slot -->\n  <path d=\"M 230 100 L 440 100 L 415 135 L 255 135 Z\" fill=\"#333333\" stroke=\"#F5F5F5\" stroke-width=\"2\" />\n  <path d=\"M 230 100 Q 210 115 255 135\" stroke=\"#E02424\" stroke-width=\"2.5\" />\n\n  <!-- Insertion down vector -->\n  <line x1=\"335\" y1=\"30\" x2=\"335\" y2=\"85\" stroke=\"#E02424\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\" />\n\n  <!-- Dimension callout for handle diameter -->\n  <line x1=\"280\" y1=\"288\" x2=\"390\" y2=\"288\" stroke=\"#525252\" stroke-width=\"1\" />\n  <line x1=\"280\" y1=\"283\" x2=\"280\" y2=\"293\" stroke=\"#525252\" stroke-width=\"1\" />\n  <line x1=\"390\" y1=\"283\" x2=\"390\" y2=\"293\" stroke=\"#525252\" stroke-width=\"1\" />\n\n  <!-- 5 Clear Korean labels in safe zones -->\n  <rect x=\"420\" y=\"30\" width=\"225\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"430\" y=\"46\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#F5F5F5\">① 위에서 아래로 돌날 끼우기</text>\n\n  <rect x=\"25\" y=\"102\" width=\"175\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"35\" y=\"118\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#E02424\" font-weight=\"bold\">나무 자르는 앞날</text>\n\n  <rect x=\"445\" y=\"96\" width=\"215\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"455\" y=\"112\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#E02424\">② 쪼갠 나무 자루 틈 (5~7cm)</text>\n\n  <rect x=\"430\" y=\"152\" width=\"230\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"440\" y=\"168\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#F5F5F5\">③ 녹인 송진 + 숯가루 채우기</text>\n\n  <rect x=\"25\" y=\"220\" width=\"255\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"35\" y=\"236\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#F5F5F5\">④ 더 안 갈라지게 아래쪽 먼저 묶기</text>\n\n  <text x=\"335\" y=\"314\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#9E9E9E\" text-anchor=\"middle\">생나무 자루 굵기: 지름 3.5~4cm</text>\n</svg>\n","content/svgs/pr04-step-03.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full max-w-2xl h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arrow\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#E02424\" />\n    </marker>\n  </defs>\n\n  <rect x=\"0\" y=\"0\" width=\"680\" height=\"340\" fill=\"#131313\" />\n  <rect x=\"10\" y=\"10\" width=\"660\" height=\"320\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"4 4\" />\n\n  <!-- Wooden Shaft Handle -->\n  <rect x=\"315\" y=\"45\" width=\"45\" height=\"225\" fill=\"#201f1f\" stroke=\"#F5F5F5\" stroke-width=\"1.8\" />\n  \n  <!-- Stone Blade Head Fixed Horizontally -->\n  <path d=\"M 200 90 L 470 90 L 440 145 L 230 145 Z\" fill=\"#2e2d2d\" stroke=\"#F5F5F5\" stroke-width=\"2\" />\n  <path d=\"M 200 90 Q 180 115 230 145\" stroke=\"#E02424\" stroke-width=\"3\" />\n\n  <!-- Cross-Lashing Vine Bands (X-Pattern) -->\n  <line x1=\"280\" y1=\"80\" x2=\"390\" y2=\"160\" stroke=\"#84cc16\" stroke-width=\"4.5\" stroke-linecap=\"round\" />\n  <line x1=\"285\" y1=\"75\" x2=\"395\" y2=\"155\" stroke=\"#4d7c0f\" stroke-width=\"3\" stroke-linecap=\"round\" />\n  <line x1=\"390\" y1=\"80\" x2=\"280\" y2=\"160\" stroke=\"#84cc16\" stroke-width=\"4.5\" stroke-linecap=\"round\" />\n  <line x1=\"395\" y1=\"75\" x2=\"285\" y2=\"155\" stroke=\"#4d7c0f\" stroke-width=\"3\" stroke-linecap=\"round\" />\n\n  <!-- Horizontal securing turns around shaft collar -->\n  <rect x=\"305\" y=\"165\" width=\"65\" height=\"40\" fill=\"#3f6212\" stroke=\"#84cc16\" stroke-width=\"1.5\" />\n  <line x1=\"305\" y1=\"175\" x2=\"370\" y2=\"175\" stroke=\"#ecfccb\" stroke-width=\"1\" />\n  <line x1=\"305\" y1=\"185\" x2=\"370\" y2=\"185\" stroke=\"#ecfccb\" stroke-width=\"1\" />\n  <line x1=\"305\" y1=\"195\" x2=\"370\" y2=\"195\" stroke=\"#ecfccb\" stroke-width=\"1\" />\n\n  <!-- Inward tension arrows (Shrinkage vectors) -->\n  <line x1=\"250\" y1=\"120\" x2=\"290\" y2=\"120\" stroke=\"#E02424\" stroke-width=\"2\" marker-end=\"url(#arrow)\" />\n  <line x1=\"420\" y1=\"120\" x2=\"380\" y2=\"120\" stroke=\"#E02424\" stroke-width=\"2\" marker-end=\"url(#arrow)\" />\n  <line x1=\"337\" y1=\"225\" x2=\"337\" y2=\"208\" stroke=\"#E02424\" stroke-width=\"2\" marker-end=\"url(#arrow)\" />\n\n  <!-- 5 Clear Korean labels in safe zones -->\n  <rect x=\"415\" y=\"30\" width=\"235\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"425\" y=\"46\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#84cc16\">① 젖은 칡 속껍질 X자로 감기</text>\n\n  <rect x=\"25\" y=\"95\" width=\"160\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"35\" y=\"111\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#E02424\">② 날카로운 도끼 앞날</text>\n\n  <rect x=\"415\" y=\"172\" width=\"235\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"425\" y=\"188\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#F5F5F5\">③ 자루 아래쪽 가로로 칭칭 감기</text>\n\n  <rect x=\"415\" y=\"232\" width=\"235\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"425\" y=\"248\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#E02424\">④ 마르면서 30% 줄어들며 꽉 조임</text>\n\n  <text x=\"340\" y=\"308\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#F5F5F5\" text-anchor=\"middle\" font-weight=\"bold\">완성 상태: 세게 내리쳐도 돌날이 빠지지 않는 일체형 돌도끼</text>\n</svg>\n","content/svgs/pr05-outcome.svg":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\" class=\"w-full h-auto\">\n  <defs>\n    <linearGradient id=\"bgGrad5\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#0c0d0c\"/>\n      <stop offset=\"100%\" stop-color=\"#141814\"/>\n    </linearGradient>\n\n    <!-- Natural Cordage Fiber Gradients -->\n    <linearGradient id=\"cordLight\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#80623f\"/>\n      <stop offset=\"50%\" stop-color=\"#bda078\"/>\n      <stop offset=\"100%\" stop-color=\"#694d2f\"/>\n    </linearGradient>\n    <linearGradient id=\"cordDark\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#543e26\"/>\n      <stop offset=\"50%\" stop-color=\"#8a6c47\"/>\n      <stop offset=\"100%\" stop-color=\"#402d1a\"/>\n    </linearGradient>\n  </defs>\n\n  <!-- Technical Canvas Backdrop -->\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"450\" fill=\"url(#bgGrad5)\"/>\n  <rect x=\"15\" y=\"15\" width=\"770\" height=\"420\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Crosshairs -->\n  <path d=\"M 25 35 L 45 35 M 35 25 L 35 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 35 L 755 35 M 765 25 L 765 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 25 415 L 45 415 M 35 405 L 35 425\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 415 L 755 415 M 765 405 L 765 425\" stroke=\"#444\" stroke-width=\"1\"/>\n\n  <!-- Title & Top Metrics -->\n  <text x=\"35\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" letter-spacing=\"1\">ARCHIVE // OUTCOME SPECIFICATION</text>\n  <text x=\"35\" y=\"70\" fill=\"#E02424\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">TARGET: 2-PLY REVERSE-WRAPPED NATURAL CORDAGE</text>\n  <text x=\"765\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"end\">TENSILE LOAD: 90+ KGF</text>\n\n  <!-- Left Spec Box -->\n  <g id=\"specBoxLeft\" font-family=\"monospace\" font-size=\"10\">\n    <rect x=\"45\" y=\"100\" width=\"180\" height=\"155\" fill=\"#141414\" stroke=\"#333\" stroke-width=\"1\"/>\n    <rect x=\"45\" y=\"100\" width=\"180\" height=\"22\" fill=\"#1f1f1f\"/>\n    <text x=\"55\" y=\"115\" fill=\"#E02424\" font-weight=\"bold\">CORDAGE METRICS</text>\n    <text x=\"55\" y=\"140\" fill=\"#aaa\">· STRUCTURE: 2-PLY REVERSE</text>\n    <text x=\"55\" y=\"160\" fill=\"#aaa\">· STRAND TWIST: CLOCKWISE</text>\n    <text x=\"55\" y=\"180\" fill=\"#aaa\">· PLY INTERLOCK: COUNTER-CW</text>\n    <text x=\"55\" y=\"200\" fill=\"#aaa\">· SPLICING: 1/3 STAGGERED</text>\n    <text x=\"55\" y=\"220\" fill=\"#aaa\">· DIAMETER: 8.0 MM UNIFORM</text>\n    <text x=\"55\" y=\"240\" fill=\"#4ade80\">· TENSILE BREAK: 92.4 KGF</text>\n  </g>\n\n  <!-- Ground Plane Shadow -->\n  <ellipse cx=\"430\" cy=\"385\" rx=\"180\" ry=\"18\" fill=\"#060606\" opacity=\"0.9\"/>\n\n  <!-- Coiled Rope Bundle (원형 코일 다발) -->\n  <g id=\"ropeCoil\">\n    <!-- Back Loop Turns -->\n    <ellipse cx=\"400\" cy=\"270\" rx=\"90\" ry=\"60\" fill=\"none\" stroke=\"url(#cordDark)\" stroke-width=\"10\"/>\n    <ellipse cx=\"402\" cy=\"265\" rx=\"85\" ry=\"55\" fill=\"none\" stroke=\"url(#cordLight)\" stroke-width=\"9\"/>\n    <ellipse cx=\"398\" cy=\"260\" rx=\"80\" ry=\"50\" fill=\"none\" stroke=\"url(#cordDark)\" stroke-width=\"9\"/>\n\n    <!-- Front Loop Turns -->\n    <ellipse cx=\"400\" cy=\"275\" rx=\"95\" ry=\"65\" fill=\"none\" stroke=\"url(#cordLight)\" stroke-width=\"10\"/>\n    <ellipse cx=\"405\" cy=\"280\" rx=\"90\" ry=\"60\" fill=\"none\" stroke=\"url(#cordDark)\" stroke-width=\"9\"/>\n    <ellipse cx=\"395\" cy=\"285\" rx=\"85\" ry=\"55\" fill=\"none\" stroke=\"url(#cordLight)\" stroke-width=\"10\"/>\n\n    <!-- Center Binding Collar (다발 고정 묶음) -->\n    <rect x=\"382\" y=\"210\" width=\"36\" height=\"135\" rx=\"6\" fill=\"#4d3722\" stroke=\"#2b1d10\" stroke-width=\"2\"/>\n    <!-- Individual Wrap Wrappings Around Center -->\n    <g stroke=\"url(#cordLight)\" stroke-width=\"5\" stroke-linecap=\"round\">\n      <line x1=\"384\" y1=\"225\" x2=\"416\" y2=\"225\"/>\n      <line x1=\"384\" y1=\"240\" x2=\"416\" y2=\"240\"/>\n      <line x1=\"384\" y1=\"255\" x2=\"416\" y2=\"255\"/>\n      <line x1=\"384\" y1=\"270\" x2=\"416\" y2=\"270\"/>\n      <line x1=\"384\" y1=\"285\" x2=\"416\" y2=\"285\"/>\n      <line x1=\"384\" y1=\"300\" x2=\"416\" y2=\"300\"/>\n      <line x1=\"384\" y1=\"315\" x2=\"416\" y2=\"315\"/>\n      <line x1=\"384\" y1=\"330\" x2=\"416\" y2=\"330\"/>\n    </g>\n\n    <!-- Trailing Working End with Figure-8 Stopper Knot -->\n    <path d=\"M 400 340 Q 370 380 320 375 Q 290 370 270 380\" fill=\"none\" stroke=\"url(#cordLight)\" stroke-width=\"9\" stroke-linecap=\"round\"/>\n    <!-- Figure-8 Knot Ball -->\n    <circle cx=\"270\" cy=\"380\" r=\"10\" fill=\"#735435\" stroke=\"#3b2b1a\" stroke-width=\"2\"/>\n    <path d=\"M 264 374 Q 270 386 276 374\" stroke=\"#d4b483\" stroke-width=\"2.5\" fill=\"none\"/>\n  </g>\n\n  <!-- Zoom Loupe Window for Micro Reverse-Wrap Detail -->\n  <g id=\"microDetailWindow\" transform=\"translate(180, 110)\">\n    <!-- Lens Circle -->\n    <circle cx=\"150\" cy=\"50\" r=\"48\" fill=\"#141414\" stroke=\"#444\" stroke-width=\"2\"/>\n    <!-- Interior 2-Ply Braid Micro Strands -->\n    <g stroke-width=\"4.5\" stroke-linecap=\"round\">\n      <!-- Strand A (Dark Bast) -->\n      <path d=\"M 115 35 Q 130 30 145 45 Q 160 60 175 45 Q 190 30 195 40\" fill=\"none\" stroke=\"#694d2f\"/>\n      <!-- Strand B (Light Kudzu) -->\n      <path d=\"M 115 55 Q 130 65 145 45 Q 160 25 175 45 Q 190 65 195 55\" fill=\"none\" stroke=\"#c4a57b\"/>\n      <!-- Surface Twisting Hatch Lines -->\n      <line x1=\"124\" y1=\"38\" x2=\"128\" y2=\"44\" stroke=\"#3d2b18\" stroke-width=\"1.2\"/>\n      <line x1=\"154\" y1=\"48\" x2=\"158\" y2=\"54\" stroke=\"#3d2b18\" stroke-width=\"1.2\"/>\n      <line x1=\"138\" y1=\"48\" x2=\"142\" y2=\"54\" stroke=\"#edd6b6\" stroke-width=\"1.2\"/>\n      <line x1=\"168\" y1=\"38\" x2=\"172\" y2=\"44\" stroke=\"#edd6b6\" stroke-width=\"1.2\"/>\n    </g>\n    <!-- Loupe Label -->\n    <text x=\"150\" y=\"88\" fill=\"#888\" font-family=\"monospace\" font-size=\"8\" text-anchor=\"middle\">5X MAGNIFICATION</text>\n  </g>\n\n  <!-- Technical Callouts (Right Side) -->\n  <g id=\"calloutsRight\" font-family=\"monospace\" font-size=\"10\" fill=\"#cccccc\">\n    <!-- Callout 1: Reverse Wrap Mechanics -->\n    <line x1=\"375\" y1=\"150\" x2=\"565\" y2=\"150\" stroke=\"#E02424\" stroke-width=\"1\"/>\n    <circle cx=\"375\" cy=\"150\" r=\"2\" fill=\"#E02424\"/>\n    <text x=\"570\" y=\"147\" fill=\"#E02424\" font-weight=\"bold\">2-PLY REVERSE INTERLOCK</text>\n    <text x=\"570\" y=\"160\" fill=\"#888888\">자체 마찰력으로 당길수록 더 단단히 조임</text>\n\n    <!-- Callout 2: Center Collar -->\n    <line x1=\"418\" y1=\"250\" x2=\"565\" y2=\"250\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"418\" cy=\"250\" r=\"2\" fill=\"#666\"/>\n    <text x=\"570\" y=\"247\" fill=\"#ffffff\" font-weight=\"bold\">EXPEDITION COIL PACK</text>\n    <text x=\"570\" y=\"260\" fill=\"#888888\">엉킴 없이 즉각 풀리는 야전 휴대 권취</text>\n\n    <!-- Callout 3: Tensile Strength -->\n    <line x1=\"480\" y1=\"310\" x2=\"565\" y2=\"310\" stroke=\"#4ade80\" stroke-width=\"1\"/>\n    <circle cx=\"480\" cy=\"310\" r=\"2\" fill=\"#4ade80\"/>\n    <text x=\"570\" y=\"307\" fill=\"#4ade80\" font-weight=\"bold\">TENSILE BREAK: 90+ KGF</text>\n    <text x=\"570\" y=\"320\" fill=\"#888888\">성인 체중 및 쉘터 가이라인 완벽 지지</text>\n\n    <!-- Callout 4: Figure-8 Stopper -->\n    <line x1=\"280\" y1=\"380\" x2=\"565\" y2=\"380\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n    <circle cx=\"280\" cy=\"380\" r=\"2\" fill=\"#38bdf8\"/>\n    <text x=\"570\" y=\"377\" fill=\"#38bdf8\" font-weight=\"bold\">FIGURE-8 STOPPER KNOT</text>\n    <text x=\"570\" y=\"390\" fill=\"#888888\">말단 올 풀림을 영구 방지하는 8자 마감</text>\n  </g>\n</svg>\n","content/svgs/pr05-step-01.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto max-w-[680px]\" xmlns=\"http://www.w3.org/2000/svg\">\n  <!-- Grid & Guide lines -->\n  <rect x=\"0\" y=\"0\" width=\"680\" height=\"340\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Outer circle (Stem cross section) -->\n  <circle cx=\"190\" cy=\"175\" r=\"95\" fill=\"#1C1814\" stroke=\"#8B5A2B\" stroke-width=\"5\" />\n  <circle cx=\"190\" cy=\"175\" r=\"82\" fill=\"#242820\" stroke=\"#E5E5E5\" stroke-dasharray=\"3 3\" stroke-width=\"2.5\" />\n  <circle cx=\"190\" cy=\"175\" r=\"45\" fill=\"#151515\" stroke=\"#444444\" stroke-width=\"2\" />\n  <circle cx=\"190\" cy=\"175\" r=\"6\" fill=\"#666666\" />\n\n  <!-- Stone scraper tool peeling bark -->\n  <path d=\"M175,78 L240,48 L228,92 Z\" fill=\"#3A3A3A\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <path d=\"M195,85 Q235,90 265,70\" fill=\"none\" stroke=\"#E02424\" stroke-width=\"2\" stroke-dasharray=\"4 2\"/>\n\n  <!-- Bent living vine diagram -->\n  <path d=\"M350,245 Q430,135 545,195\" fill=\"none\" stroke=\"#10B981\" stroke-width=\"6\"/>\n  <circle cx=\"350\" cy=\"245\" r=\"4\" fill=\"#10B981\"/>\n  <circle cx=\"545\" cy=\"195\" r=\"4\" fill=\"#10B981\"/>\n\n  <!-- Peel strand visualization -->\n  <path d=\"M265,125 C305,105 350,135 395,115\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"5\"/>\n  <path d=\"M275,145 C315,125 360,155 405,135\" fill=\"none\" stroke=\"#8B5A2B\" stroke-width=\"4\"/>\n\n  <!-- Callout lines -->\n  <line x1=\"240\" y1=\"58\" x2=\"295\" y2=\"48\" stroke=\"#E5E5E5\" stroke-width=\"1.2\"/>\n  <line x1=\"265\" y1=\"120\" x2=\"295\" y2=\"95\" stroke=\"#8B5A2B\" stroke-width=\"1.2\"/>\n  <line x1=\"270\" y1=\"165\" x2=\"295\" y2=\"145\" stroke=\"#E5E5E5\" stroke-width=\"1.2\"/>\n  <line x1=\"190\" y1=\"175\" x2=\"295\" y2=\"205\" stroke=\"#888888\" stroke-width=\"1.2\"/>\n\n  <!-- 5 Clean, Non-Overlapping Labels -->\n  <text x=\"300\" y=\"52\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">① 돌 모서리로 거친 겉껍질만 살살 긁어내기</text>\n  <text x=\"300\" y=\"98\" fill=\"#C49A6C\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">② 잘 부러지는 갈색 겉껍질 (긁어내어 버림)</text>\n  <text x=\"300\" y=\"148\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">③ 질기고 하얀 속껍질 섬유층 (밧줄 핵심 재료)</text>\n  <text x=\"300\" y=\"208\" fill=\"#9E9E9E\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\">④ 가운데 딱딱한 나무 속심 (빼내고 버림)</text>\n  <text x=\"260\" y=\"295\" fill=\"#10B981\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">⑤ 구부렸을 때 부러지지 않고 휘어지는 살아있는 줄기</text>\n</svg>","content/svgs/pr05-step-02.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto max-w-[680px]\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"680\" height=\"340\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Water stream / pool zone on left -->\n  <rect x=\"70\" y=\"80\" width=\"130\" height=\"90\" fill=\"#102528\" stroke=\"#007788\" stroke-width=\"1.5\"/>\n  <path d=\"M75,115 Q135,95 195,115\" fill=\"none\" stroke=\"#00B4D8\" stroke-width=\"2\"/>\n  <path d=\"M75,135 Q135,155 195,135\" fill=\"none\" stroke=\"#00B4D8\" stroke-width=\"2\"/>\n  <path d=\"M90,100 Q120,150 170,110\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"3\"/>\n\n  <!-- Flat anvil stone in center -->\n  <polygon points=\"240,225 450,225 470,265 220,265\" fill=\"#282828\" stroke=\"#666666\" stroke-width=\"2\"/>\n\n  <!-- Round hand hammer stone -->\n  <ellipse cx=\"335\" cy=\"145\" rx=\"36\" ry=\"26\" fill=\"#3D3D3D\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <line x1=\"335\" y1=\"175\" x2=\"335\" y2=\"210\" stroke=\"#E02424\" stroke-width=\"2.5\" stroke-dasharray=\"3 3\"/>\n  <polygon points=\"330,205 335,218 340,205\" fill=\"#E02424\"/>\n\n  <!-- Crushed soft fiber on the stone -->\n  <path d=\"M270,220 C310,210 350,230 400,220\" stroke=\"#E5E5E5\" stroke-width=\"6\"/>\n  <path d=\"M280,217 C320,223 360,215 395,221\" stroke=\"#9E9E9E\" stroke-width=\"2\"/>\n\n  <!-- Two split bundles on right -->\n  <path d=\"M490,145 Q525,180 575,170\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"4\"/>\n  <path d=\"M490,215 Q525,195 575,225\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"4\"/>\n  <circle cx=\"490\" cy=\"180\" r=\"14\" fill=\"none\" stroke=\"#D97706\" stroke-width=\"2\" stroke-dasharray=\"2 2\"/>\n\n  <!-- 5 Clean, Non-Overlapping Labels -->\n  <text x=\"70\" y=\"55\" fill=\"#00B4D8\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">① 냇물에 20분 이상 담가 부드럽게 불린 속껍질</text>\n  <text x=\"250\" y=\"98\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">② 둥근 돌로 살살 두드려 섬유 결 쪼개기</text>\n  <text x=\"380\" y=\"135\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\">③ 머리카락처럼 부드럽게 풀어진 섬유 다발</text>\n  <text x=\"380\" y=\"255\" fill=\"#D97706\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">④ 손가락 굵기로 똑같이 나눈 두 가닥</text>\n  <text x=\"190\" y=\"298\" fill=\"#9E9E9E\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">⑤ 바닥에 흔들리지 않게 받친 평평한 강돌</text>\n</svg>","content/svgs/pr05-step-03.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto max-w-[680px]\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"680\" height=\"340\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Left finished twisted rope -->\n  <g transform=\"translate(95, 165)\">\n    <path d=\"M0,0 C20,-15 40,15 60,0 C80,-15 100,15 120,0 C140,-15 160,15 180,0\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"10\"/>\n    <path d=\"M0,0 C20,15 40,-15 60,0 C80,15 100,-15 120,0 C140,15 160,-15 180,0\" fill=\"none\" stroke=\"#888888\" stroke-width=\"7\"/>\n  </g>\n\n  <!-- Left hand pinch point -->\n  <circle cx=\"275\" cy=\"165\" r=\"18\" fill=\"#1E1E1E\" stroke=\"#E02424\" stroke-width=\"2.5\"/>\n  <circle cx=\"275\" cy=\"165\" r=\"4\" fill=\"#E02424\"/>\n\n  <!-- Top strand twisting outward (away from body) -->\n  <path d=\"M290,157 Q365,115 445,110\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"7\"/>\n  <path d=\"M365,120 C370,95 390,90 400,105\" fill=\"none\" stroke=\"#10B981\" stroke-width=\"3\"/>\n  <polygon points=\"400,97 407,107 395,110\" fill=\"#10B981\"/>\n\n  <!-- Bottom strand crossing over towards body -->\n  <path d=\"M290,173 Q355,215 445,220\" fill=\"none\" stroke=\"#888888\" stroke-width=\"7\"/>\n  <path d=\"M375,135 C405,155 395,185 385,200\" fill=\"none\" stroke=\"#D97706\" stroke-width=\"3\" stroke-dasharray=\"4 2\"/>\n  <polygon points=\"380,193 383,207 393,198\" fill=\"#D97706\"/>\n\n  <!-- Double lock icon/diagram on right -->\n  <rect x=\"490\" y=\"115\" width=\"110\" height=\"95\" fill=\"#151515\" stroke=\"#333333\" stroke-width=\"1.5\"/>\n  <path d=\"M520,162 L570,162 M545,137 L545,187\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <circle cx=\"545\" cy=\"162\" r=\"18\" fill=\"none\" stroke=\"#10B981\" stroke-width=\"2\"/>\n\n  <!-- 5 Clean, Non-Overlapping Labels -->\n  <text x=\"250\" y=\"62\" fill=\"#10B981\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">① 위쪽 가닥: 몸 바깥쪽(↑)으로 단단히 비틀기</text>\n  <text x=\"70\" y=\"115\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\">② 서로 되감기며 톱니처럼 맞물린 밧줄 무늬</text>\n  <text x=\"70\" y=\"218\" fill=\"#E02424\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">③ 왼손 엄지·검지로 꼬인 자리 꽉 눌러 잡기</text>\n  <text x=\"250\" y=\"258\" fill=\"#D97706\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">④ 비튼 위 가닥을 아래 가닥 너머 몸 쪽(↓)으로 넘기기</text>\n  <text x=\"280\" y=\"298\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">⑤ 손을 놓아도 절대 풀리지 않는 역방향 잠금 구조</text>\n</svg>","content/svgs/pr05-step-04.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto max-w-[680px]\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"680\" height=\"340\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Top strand: Thinned old strand + New thick strand overlap -->\n  <g transform=\"translate(80, 120)\">\n    <path d=\"M0,20 L160,20\" stroke=\"#888888\" stroke-width=\"5\"/>\n    <path d=\"M160,20 L260,20\" stroke=\"#888888\" stroke-width=\"2.5\" stroke-dasharray=\"2 2\"/>\n    <path d=\"M160,10 L260,10\" stroke=\"#10B981\" stroke-width=\"3\"/>\n    <path d=\"M260,10 L430,10\" stroke=\"#10B981\" stroke-width=\"6\"/>\n    <line x1=\"160\" y1=\"-5\" x2=\"260\" y2=\"-5\" stroke=\"#E02424\" stroke-width=\"1.5\"/>\n    <line x1=\"160\" y1=\"-10\" x2=\"160\" y2=\"0\" stroke=\"#E02424\" stroke-width=\"1.5\"/>\n    <line x1=\"260\" y1=\"-10\" x2=\"260\" y2=\"0\" stroke=\"#E02424\" stroke-width=\"1.5\"/>\n  </g>\n\n  <!-- Bottom strand: Staggered junction 15cm further right -->\n  <g transform=\"translate(80, 200)\">\n    <path d=\"M0,20 L300,20\" stroke=\"#888888\" stroke-width=\"5\"/>\n    <path d=\"M300,20 L400,20\" stroke=\"#888888\" stroke-width=\"2.5\" stroke-dasharray=\"2 2\"/>\n    <path d=\"M300,10 L400,10\" stroke=\"#D97706\" stroke-width=\"3\"/>\n    <path d=\"M400,10 L470,10\" stroke=\"#D97706\" stroke-width=\"6\"/>\n    <line x1=\"210\" y1=\"45\" x2=\"350\" y2=\"45\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" stroke-dasharray=\"3 3\"/>\n    <polygon points=\"210,41 202,45 210,49\" fill=\"#E5E5E5\"/>\n    <polygon points=\"350,41 358,45 350,49\" fill=\"#E5E5E5\"/>\n  </g>\n\n  <!-- Smooth twisted rope preview on far right -->\n  <path d=\"M520,165 C545,150 570,180 595,165\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"8\"/>\n\n  <!-- 5 Clean, Non-Overlapping Top-Level Labels -->\n  <text x=\"75\" y=\"58\" fill=\"#9E9E9E\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\">① 끝이 10cm쯤 남아 가늘어진 기존 가닥</text>\n  <text x=\"235\" y=\"96\" fill=\"#10B981\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">② 새 섬유 다발을 10cm 나란히 겹쳐 대기</text>\n  <text x=\"75\" y=\"178\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">③ 겹친 두 줄을 한 가닥처럼 함께 비틀어 감기</text>\n  <text x=\"360\" y=\"232\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\">④ 불룩해지지 않고 매끄럽게 이어진 연결부</text>\n  <text x=\"150\" y=\"295\" fill=\"#D97706\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">⑤ 위·아래 이음매 위치를 한 뼘(15cm) 어긋나게 배치</text>\n</svg>","content/svgs/pr05-step-05.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto max-w-[680px]\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"680\" height=\"340\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Tree trunk on left -->\n  <rect x=\"95\" y=\"75\" width=\"55\" height=\"205\" fill=\"#221C18\" stroke=\"#665544\" stroke-width=\"3\"/>\n  <path d=\"M95,115 L150,115 M95,175 L150,175 M95,235 L150,235\" stroke=\"#443322\" stroke-width=\"1\"/>\n\n  <!-- Rope wrapped around tree trunk -->\n  <ellipse cx=\"122\" cy=\"155\" rx=\"33\" ry=\"12\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"6\"/>\n  <line x1=\"155\" y1=\"155\" x2=\"425\" y2=\"155\" stroke=\"#E5E5E5\" stroke-width=\"6\"/>\n\n  <!-- End eye knot -->\n  <g transform=\"translate(425, 155)\">\n    <circle cx=\"20\" cy=\"0\" r=\"16\" fill=\"none\" stroke=\"#10B981\" stroke-width=\"5\"/>\n    <rect x=\"0\" y=\"-8\" width=\"12\" height=\"16\" fill=\"#E02424\" stroke=\"#E5E5E5\" stroke-width=\"1\"/>\n  </g>\n\n  <!-- Stone scraper trimming loose fuzz -->\n  <polygon points=\"310,115 350,100 340,130\" fill=\"#444444\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <path d=\"M290,152 L295,140 M305,152 L310,143 M320,152 L325,141\" stroke=\"#9E9E9E\" stroke-width=\"1.5\"/>\n\n  <!-- Body weight tension indicator arrow -->\n  <g transform=\"translate(310, 168)\">\n    <line x1=\"0\" y1=\"10\" x2=\"65\" y2=\"10\" stroke=\"#E02424\" stroke-width=\"3\"/>\n    <polygon points=\"65,5 77,10 65,15\" fill=\"#E02424\"/>\n  </g>\n\n  <!-- Practical usage box on right -->\n  <rect x=\"495\" y=\"105\" width=\"110\" height=\"110\" fill=\"#141414\" stroke=\"#333333\" stroke-width=\"1\"/>\n  <line x1=\"510\" y1=\"135\" x2=\"590\" y2=\"135\" stroke=\"#10B981\" stroke-width=\"2\"/>\n  <line x1=\"510\" y1=\"160\" x2=\"590\" y2=\"160\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <line x1=\"510\" y1=\"185\" x2=\"590\" y2=\"185\" stroke=\"#D97706\" stroke-width=\"2\"/>\n\n  <!-- 5 Clean, Non-Overlapping Top-Level Labels -->\n  <text x=\"270\" y=\"62\" fill=\"#10B981\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">① 끝부분 3cm를 접어 묶은 풀림 방지 마감 매듭</text>\n  <text x=\"175\" y=\"102\" fill=\"#9E9E9E\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\">② 삐져나온 잔털을 돌날로 깔끔하게 정리</text>\n  <text x=\"175\" y=\"212\" fill=\"#E02424\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">③ 나무 기둥에 걸고 몸무게(50kg+)를 실어 당겨보기</text>\n  <text x=\"175\" y=\"255\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">④ 완성된 5mm 굵기 야생 밧줄 (5m 길이)</text>\n  <text x=\"210\" y=\"298\" fill=\"#10B981\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">⑤ 움막 기둥 묶기·돌도끼 고정·활비비 줄로 즉시 활용</text>\n</svg>","content/svgs/pr06-outcome.svg":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\" class=\"w-full h-auto\">\n  <defs>\n    <linearGradient id=\"bgGrad6\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#0e0c0b\"/>\n      <stop offset=\"100%\" stop-color=\"#17120f\"/>\n    </linearGradient>\n\n    <!-- Clay & Terracotta Plaster Gradients -->\n    <linearGradient id=\"clayPlaster\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#a8653b\"/>\n      <stop offset=\"40%\" stop-color=\"#8c4e26\"/>\n      <stop offset=\"80%\" stop-color=\"#693717\"/>\n      <stop offset=\"100%\" stop-color=\"#45230c\"/>\n    </linearGradient>\n    <linearGradient id=\"stoneBlock\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#4a4a4a\"/>\n      <stop offset=\"50%\" stop-color=\"#737373\"/>\n      <stop offset=\"100%\" stop-color=\"#3d3d3d\"/>\n    </linearGradient>\n\n    <!-- Glowing Firebox Interior -->\n    <radialGradient id=\"hearthFireGlow\" cx=\"50%\" cy=\"60%\" r=\"55%\">\n      <stop offset=\"0%\" stop-color=\"#ffffff\"/>\n      <stop offset=\"20%\" stop-color=\"#fef08a\"/>\n      <stop offset=\"50%\" stop-color=\"#f97316\"/>\n      <stop offset=\"80%\" stop-color=\"#dc2626\"/>\n      <stop offset=\"100%\" stop-color=\"#140804\"/>\n    </radialGradient>\n\n    <filter id=\"heatBlur\" x=\"-10%\" y=\"-10%\" width=\"120%\" height=\"120%\">\n      <feGaussianBlur stdDeviation=\"2\"/>\n    </filter>\n  </defs>\n\n  <!-- Technical Canvas Backdrop -->\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"450\" fill=\"url(#bgGrad6)\"/>\n  <rect x=\"15\" y=\"15\" width=\"770\" height=\"420\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Crosshairs -->\n  <path d=\"M 25 35 L 45 35 M 35 25 L 35 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 35 L 755 35 M 765 25 L 765 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 25 415 L 45 415 M 35 405 L 35 425\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 415 L 755 415 M 765 405 L 765 425\" stroke=\"#444\" stroke-width=\"1\"/>\n\n  <!-- Metadata -->\n  <text x=\"35\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" letter-spacing=\"1\">ARCHIVE // OUTCOME SPECIFICATION</text>\n  <text x=\"35\" y=\"70\" fill=\"#E02424\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">TARGET: STONE &amp; TEMPERED CLAY HEARTH [650°C SPEC]</text>\n  <text x=\"765\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"end\">MAX TEMP: 650°C</text>\n\n  <!-- Left Spec Box -->\n  <g id=\"specBoxLeft\" font-family=\"monospace\" font-size=\"10\">\n    <rect x=\"45\" y=\"100\" width=\"180\" height=\"155\" fill=\"#141414\" stroke=\"#333\" stroke-width=\"1\"/>\n    <rect x=\"45\" y=\"100\" width=\"180\" height=\"22\" fill=\"#1f1f1f\"/>\n    <text x=\"55\" y=\"115\" fill=\"#E02424\" font-weight=\"bold\">HEARTH METRICS</text>\n    <text x=\"55\" y=\"140\" fill=\"#aaa\">· BASE: U-SHAPE RIVER STONE</text>\n    <text x=\"55\" y=\"160\" fill=\"#aaa\">· CLAY WALL: 50 MM THICK</text>\n    <text x=\"55\" y=\"180\" fill=\"#aaa\">· DRAFT: REAR EXHAUST FLUE</text>\n    <text x=\"55\" y=\"200\" fill=\"#aaa\">· COOKTOP: LEVEL STONE RIM</text>\n    <text x=\"55\" y=\"220\" fill=\"#aaa\">· FUEL EFF: 3X WOOD SAVING</text>\n    <text x=\"55\" y=\"240\" fill=\"#f97316\">· CORE TEMP: 650°C INTENSE</text>\n  </g>\n\n  <!-- Ground Plane Shadow -->\n  <ellipse cx=\"430\" cy=\"390\" rx=\"220\" ry=\"20\" fill=\"#050302\" opacity=\"0.9\"/>\n\n  <!-- Clay & Stone Hearth Structure (3D Perspective) -->\n  <g id=\"hearth3D\">\n    <!-- Foundation River Stones Layer (Base Tier) -->\n    <g id=\"baseStones\">\n      <ellipse cx=\"290\" cy=\"365\" rx=\"32\" ry=\"18\" fill=\"url(#stoneBlock)\" stroke=\"#222\" stroke-width=\"1.5\"/>\n      <ellipse cx=\"340\" cy=\"375\" rx=\"35\" ry=\"19\" fill=\"url(#stoneBlock)\" stroke=\"#222\" stroke-width=\"1.5\"/>\n      <ellipse cx=\"400\" cy=\"380\" rx=\"38\" ry=\"20\" fill=\"url(#stoneBlock)\" stroke=\"#222\" stroke-width=\"1.5\"/>\n      <ellipse cx=\"460\" cy=\"375\" rx=\"35\" ry=\"19\" fill=\"url(#stoneBlock)\" stroke=\"#222\" stroke-width=\"1.5\"/>\n      <ellipse cx=\"510\" cy=\"365\" rx=\"32\" ry=\"18\" fill=\"url(#stoneBlock)\" stroke=\"#222\" stroke-width=\"1.5\"/>\n    </g>\n\n    <!-- Main Terracotta Clay Domed Wall Body -->\n    <path d=\"M 270 360 C 270 230 330 180 400 180 C 470 180 530 230 530 360 Z\" fill=\"url(#clayPlaster)\" stroke=\"#381907\" stroke-width=\"2\"/>\n\n    <!-- Clay Drying Cracks & Straw Binder Texture -->\n    <g stroke=\"#52240b\" stroke-width=\"1.2\" fill=\"none\" opacity=\"0.7\">\n      <path d=\"M 320 250 Q 335 265 330 285\"/>\n      <path d=\"M 470 240 Q 460 260 475 275\"/>\n      <path d=\"M 360 210 Q 380 220 375 235\"/>\n      <path d=\"M 430 215 Q 420 230 435 245\"/>\n    </g>\n\n    <!-- Top Level Cooking Platform Rim (돌판/냄비 얹는 조리구) -->\n    <ellipse cx=\"400\" cy=\"180\" rx=\"55\" ry=\"18\" fill=\"#4d4d4d\" stroke=\"#262626\" stroke-width=\"2\"/>\n    <ellipse cx=\"400\" cy=\"180\" rx=\"42\" ry=\"13\" fill=\"#171717\" stroke=\"#333\" stroke-width=\"1.5\"/>\n\n    <!-- Rear Vertical Chimney Flue (후면 배기 굴뚝) -->\n    <g id=\"chimneyFlue\">\n      <path d=\"M 465 190 L 485 130 L 515 130 L 505 210 Z\" fill=\"url(#clayPlaster)\" stroke=\"#381907\" stroke-width=\"1.5\"/>\n      <ellipse cx=\"500\" cy=\"130\" rx=\"15\" ry=\"6\" fill=\"#140804\" stroke=\"#381907\" stroke-width=\"1.2\"/>\n      <!-- Hot Chimney Exhaust Heat Shimmer -->\n      <path d=\"M 500 125 Q 492 95 505 75 Q 515 55 500 35\" stroke=\"#f97316\" stroke-width=\"2\" fill=\"none\" opacity=\"0.4\" filter=\"url(#heatBlur)\"/>\n      <path d=\"M 504 125 Q 512 90 498 70\" stroke=\"#fef08a\" stroke-width=\"1.5\" fill=\"none\" opacity=\"0.5\" filter=\"url(#heatBlur)\"/>\n    </g>\n\n    <!-- Front Firebox Mouth (연소실 아치 개구부) -->\n    <path d=\"M 335 365 C 335 250 465 250 465 365 Z\" fill=\"#0d0401\" stroke=\"#260f04\" stroke-width=\"2\"/>\n    <!-- Intense Glowing Radiant Embers in Firebox -->\n    <ellipse cx=\"400\" cy=\"340\" rx=\"60\" ry=\"24\" fill=\"url(#hearthFireGlow)\"/>\n\n    <!-- Firewood Logs & Core Flames Inside -->\n    <!-- Charred Log 1 -->\n    <polygon points=\"350,355 425,325 435,335 360,365\" fill=\"#1c1109\" stroke=\"#080402\" stroke-width=\"1\"/>\n    <!-- Charred Log 2 -->\n    <polygon points=\"445,355 375,325 365,335 435,365\" fill=\"#1c1109\" stroke=\"#080402\" stroke-width=\"1\"/>\n    <!-- Active Flame Tongues -->\n    <path d=\"M 400 345 C 385 330 380 300 400 270 C 405 285 412 290 410 275 C 418 285 425 305 420 330 C 425 320 428 310 424 298 C 432 312 430 335 415 345 Z\" fill=\"#f97316\" filter=\"url(#heatBlur)\"/>\n    <ellipse cx=\"402\" cy=\"335\" rx=\"14\" ry=\"18\" fill=\"#fef08a\"/>\n    <ellipse cx=\"402\" cy=\"335\" rx=\"8\" ry=\"10\" fill=\"#ffffff\"/>\n\n    <!-- Inflow Air Draft Direction Arrows (하단 산소 흡입) -->\n    <g stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"none\">\n      <path d=\"M 300 375 Q 330 365 350 355\"/>\n      <path d=\"M 500 375 Q 470 365 450 355\"/>\n    </g>\n  </g>\n\n  <!-- Technical Callouts (Right Side) -->\n  <g id=\"calloutsRight\" font-family=\"monospace\" font-size=\"10\" fill=\"#cccccc\">\n    <!-- Callout 1: Chimney Flue -->\n    <line x1=\"505\" y1=\"130\" x2=\"565\" y2=\"130\" stroke=\"#f97316\" stroke-width=\"1\"/>\n    <circle cx=\"505\" cy=\"130\" r=\"2\" fill=\"#f97316\"/>\n    <text x=\"570\" y=\"127\" fill=\"#f97316\" font-weight=\"bold\">REAR EXHAUST CHIMNEY</text>\n    <text x=\"570\" y=\"140\" fill=\"#888888\">후면 굴뚝 상승 기류로 불완전연소 방지</text>\n\n    <!-- Callout 2: Top Cooktop Rim -->\n    <line x1=\"455\" y1=\"180\" x2=\"565\" y2=\"180\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"455\" cy=\"180\" r=\"2\" fill=\"#666\"/>\n    <text x=\"570\" y=\"177\" fill=\"#ffffff\" font-weight=\"bold\">LEVEL COOKING RIM</text>\n    <text x=\"570\" y=\"190\" fill=\"#888888\">냄비·판석을 안정되게 얹는 직화 가열구</text>\n\n    <!-- Callout 3: 5cm Clay Wall -->\n    <line x1=\"510\" y1=\"260\" x2=\"565\" y2=\"260\" stroke=\"#E02424\" stroke-width=\"1\"/>\n    <circle cx=\"510\" cy=\"260\" r=\"2\" fill=\"#E02424\"/>\n    <text x=\"570\" y=\"257\" fill=\"#E02424\" font-weight=\"bold\">5CM CLAY INSULATION</text>\n    <text x=\"570\" y=\"270\" fill=\"#888888\">볏짚 황토 미장으로 열기를 가두어 650°C 유지</text>\n\n    <!-- Callout 4: Arch Inflow Draft -->\n    <line x1=\"465\" y1=\"340\" x2=\"565\" y2=\"340\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n    <circle cx=\"465\" cy=\"340\" r=\"2\" fill=\"#38bdf8\"/>\n    <text x=\"570\" y=\"337\" fill=\"#38bdf8\" font-weight=\"bold\">INFLOW DRAFT ARCH</text>\n    <text x=\"570\" y=\"350\" fill=\"#888888\">바람을 막고 하단 산소를 흡입하는 아치 입구</text>\n  </g>\n</svg>\n","content/svgs/pr06-step-01.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto block\" xmlns=\"http://www.w3.org/2000/svg\">\n          <defs>\n            <marker id=\"arrow-step1\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n              <path d=\"M 0 1 L 8 5 L 0 9 z\" fill=\"#06B6D4\" />\n            </marker>\n          </defs>\n\n          <!-- Blueprint Header -->\n          <text x=\"75\" y=\"40\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">\n            FIG. 01 // CLAY TEMPERING &amp; FIBER MATRIX BLUEPRINT\n          </text>\n          <line x1=\"75\" y1=\"48\" x2=\"605\" y2=\"48\" stroke=\"#222222\" stroke-width=\"1\" />\n\n          <!-- Material 1: 붉은 찰흙 2바가지 -->\n          <g transform=\"translate(100, 70)\">\n            <ellipse cx=\"45\" cy=\"45\" rx=\"38\" ry=\"24\" fill=\"#1C1815\" stroke=\"#D97706\" stroke-width=\"1.5\" />\n            <path d=\"M 20 45 Q 45 15 70 45\" stroke=\"#D97706\" stroke-width=\"1\" fill=\"none\" stroke-dasharray=\"2,2\" />\n            <circle cx=\"45\" cy=\"35\" r=\"4\" fill=\"#D97706\" />\n          </g>\n          <text x=\"80\" y=\"155\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ① 붉은 찰흙 2바가지\n          </text>\n          <text x=\"80\" y=\"175\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            끈끈한 점력의 기본 바탕재\n          </text>\n\n          <!-- Plus Sign 1 -->\n          <text x=\"210\" y=\"115\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"18\" font-weight=\"bold\">+</text>\n\n          <!-- Material 2: 굵은 모래 1바가지 -->\n          <g transform=\"translate(235, 75)\">\n            <ellipse cx=\"40\" cy=\"40\" rx=\"34\" ry=\"20\" fill=\"#151717\" stroke=\"#06B6D4\" stroke-width=\"1.5\" />\n            <!-- Sand speckles -->\n            <circle cx=\"28\" cy=\"38\" r=\"1.5\" fill=\"#06B6D4\" />\n            <circle cx=\"42\" cy=\"32\" r=\"1.5\" fill=\"#06B6D4\" />\n            <circle cx=\"50\" cy=\"42\" r=\"1.5\" fill=\"#06B6D4\" />\n            <circle cx=\"35\" cy=\"45\" r=\"1.5\" fill=\"#06B6D4\" />\n          </g>\n          <text x=\"235\" y=\"155\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ② 굵은 모래 1바가지\n          </text>\n          <text x=\"235\" y=\"175\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            마를 때 오그라듦 방지\n          </text>\n\n          <!-- Plus Sign 2 -->\n          <text x=\"350\" y=\"115\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"18\" font-weight=\"bold\">+</text>\n\n          <!-- Material 3: 잘게 자른 마른 풀잎 -->\n          <g transform=\"translate(375, 75)\">\n            <ellipse cx=\"40\" cy=\"40\" rx=\"34\" ry=\"20\" fill=\"#141914\" stroke=\"#10B981\" stroke-width=\"1.5\" />\n            <!-- Grass fiber lines -->\n            <line x1=\"25\" y1=\"36\" x2=\"40\" y2=\"44\" stroke=\"#10B981\" stroke-width=\"1.5\" />\n            <line x1=\"38\" y1=\"32\" x2=\"52\" y2=\"40\" stroke=\"#10B981\" stroke-width=\"1.5\" />\n            <line x1=\"30\" y1=\"46\" x2=\"48\" y2=\"42\" stroke=\"#10B981\" stroke-width=\"1.5\" />\n          </g>\n          <text x=\"375\" y=\"155\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ③ 잘게 자른 마른 풀잎\n          </text>\n          <text x=\"375\" y=\"175\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            뼈대 역할을 하는 보강 섬유\n          </text>\n\n          <!-- Arrow downward to kneading and ball -->\n          <path d=\"M 290 190 L 290 220\" stroke=\"#06B6D4\" stroke-width=\"1.5\" marker-end=\"url(#arrow-step1)\" />\n\n          <!-- Process 4: 물을 조금씩 부어가며 발로 치대기 -->\n          <rect x=\"80\" y=\"235\" width=\"220\" height=\"65\" fill=\"#141414\" stroke=\"#333333\" stroke-width=\"1\" />\n          <text x=\"95\" y=\"260\" fill=\"#F59E0B\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ④ 물을 조금씩 부어가며 발로 치대기\n          </text>\n          <text x=\"95\" y=\"282\" fill=\"#AAAAAA\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            한 번에 많이 붓지 말고 뒤집으며 밟기\n          </text>\n\n          <!-- Process 5: 차진 반죽 덩어리 판정 -->\n          <g transform=\"translate(350, 225)\">\n            <!-- Clay ball -->\n            <circle cx=\"65\" cy=\"40\" r=\"32\" fill=\"#1C1815\" stroke=\"#E5E5E5\" stroke-width=\"2\" />\n            <!-- Inner smooth contour -->\n            <path d=\"M 45 40 Q 65 20 85 40\" stroke=\"#888888\" stroke-width=\"1\" fill=\"none\" />\n            <circle cx=\"65\" cy=\"40\" r=\"4\" fill=\"#10B981\" />\n          </g>\n          <text x=\"470\" y=\"255\" fill=\"#10B981\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ⑤ 차진 반죽 덩어리 완성\n          </text>\n          <text x=\"470\" y=\"278\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            주먹 크기로 둥글게 뭉쳐도\n          </text>\n          <text x=\"470\" y=\"295\" fill=\"#AAAAAA\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            겉면에 실금이 가지 않는 상태\n          </text>\n        </svg>","content/svgs/pr06-step-02.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto block\" xmlns=\"http://www.w3.org/2000/svg\">\n          <defs>\n            <marker id=\"arrow-wind\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n              <path d=\"M 0 1 L 8 5 L 0 9 z\" fill=\"#06B6D4\" />\n            </marker>\n          </defs>\n\n          <!-- Blueprint Header -->\n          <text x=\"75\" y=\"40\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">\n            FIG. 02 // FOUNDATION LAYOUT &amp; AIR ENTRY SCHEMATIC\n          </text>\n          <line x1=\"75\" y1=\"48\" x2=\"605\" y2=\"48\" stroke=\"#222222\" stroke-width=\"1\" />\n\n          <!-- Center U-Shape Stone Structure (Top-Down View) -->\n          <g transform=\"translate(180, 75)\">\n            <!-- Base Ground Insulation Bed (모래/자갈층) -->\n            <rect x=\"0\" y=\"0\" width=\"220\" height=\"190\" fill=\"#121212\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"3,3\" />\n\n            <!-- U-shaped Mud Bed -->\n            <path d=\"M 40 170 L 40 50 Q 110 10 180 50 L 180 170\" fill=\"none\" stroke=\"#654321\" stroke-width=\"36\" stroke-linecap=\"round\" stroke-linejoin=\"round\" />\n\n            <!-- Stones in U-Shape -->\n            <!-- Left arm stones -->\n            <circle cx=\"40\" cy=\"160\" r=\"14\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <circle cx=\"40\" cy=\"120\" r=\"15\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <circle cx=\"45\" cy=\"80\" r=\"14\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <!-- Curve stones -->\n            <circle cx=\"70\" cy=\"45\" r=\"15\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <circle cx=\"110\" cy=\"30\" r=\"16\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <circle cx=\"150\" cy=\"45\" r=\"15\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <!-- Right arm stones -->\n            <circle cx=\"175\" cy=\"80\" r=\"14\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <circle cx=\"180\" cy=\"120\" r=\"15\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <circle cx=\"180\" cy=\"160\" r=\"14\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n\n            <!-- Front Opening (장작 입구 폭 20cm) -->\n            <line x1=\"56\" y1=\"165\" x2=\"164\" y2=\"165\" stroke=\"#F59E0B\" stroke-width=\"1.5\" stroke-dasharray=\"4,4\" />\n            <line x1=\"56\" y1=\"160\" x2=\"56\" y2=\"170\" stroke=\"#F59E0B\" stroke-width=\"1.5\" />\n            <line x1=\"164\" y1=\"160\" x2=\"164\" y2=\"170\" stroke=\"#F59E0B\" stroke-width=\"1.5\" />\n          </g>\n\n          <!-- Label 1: 앞쪽 장작 넣는 입구 (한 뼘 너비 20cm) -->\n          <text x=\"80\" y=\"290\" fill=\"#F59E0B\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ① 앞쪽 장작 넣는 입구 (한 뼘 너비 20cm)\n          </text>\n          <text x=\"80\" y=\"308\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            불길 조절과 공기 공급에 알맞은 입구 폭\n          </text>\n\n          <!-- Label 2: U자형으로 둘러앉힌 마른 돌 -->\n          <line x1=\"180\" y1=\"130\" x2=\"120\" y2=\"100\" stroke=\"#E5E5E5\" stroke-width=\"1\" />\n          <text x=\"75\" y=\"85\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ② U자형 주먹만 한 마른 돌\n          </text>\n          <text x=\"75\" y=\"103\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            기초를 지탱하는 1차 뼈대\n          </text>\n\n          <!-- Label 3: 돌 틈새를 메운 진흙 반죽 -->\n          <line x1=\"395\" y1=\"145\" x2=\"450\" y2=\"120\" stroke=\"#D97706\" stroke-width=\"1\" />\n          <text x=\"455\" y=\"115\" fill=\"#D97706\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ③ 틈새를 메운 진흙 반죽\n          </text>\n          <text x=\"455\" y=\"133\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            돌 사이 공기 누출 완전 차단\n          </text>\n\n          <!-- Label 4: 바닥 모래·자갈 단열층 -->\n          <line x1=\"290\" y1=\"180\" x2=\"450\" y2=\"190\" stroke=\"#06B6D4\" stroke-width=\"1\" />\n          <text x=\"455\" y=\"185\" fill=\"#06B6D4\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ④ 바닥 마른 모래·자갈 단열층\n          </text>\n          <text x=\"455\" y=\"203\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            차가운 땅바닥 습기와 냉기 차단\n          </text>\n\n          <!-- Label 5: 바람 불어오는 반대 방향 -->\n          <g transform=\"translate(420, 245)\">\n            <path d=\"M 0 15 L 45 15\" stroke=\"#06B6D4\" stroke-width=\"1.5\" marker-end=\"url(#arrow-wind)\" />\n            <path d=\"M 5 28 L 50 28\" stroke=\"#06B6D4\" stroke-width=\"1.5\" marker-end=\"url(#arrow-wind)\" />\n          </g>\n          <text x=\"390\" y=\"290\" fill=\"#10B981\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ⑤ 바람 불어오는 반대쪽으로 입구 배치\n          </text>\n          <text x=\"390\" y=\"308\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            강풍에 불티가 역류하거나 꺼지지 않도록 보호\n          </text>\n        </svg>","content/svgs/pr06-step-03.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto block\" xmlns=\"http://www.w3.org/2000/svg\">\n          <defs>\n            <marker id=\"arrow-swirl\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n              <path d=\"M 0 1 L 8 5 L 0 9 z\" fill=\"#E02424\" />\n            </marker>\n          </defs>\n\n          <!-- Blueprint Header -->\n          <text x=\"75\" y=\"40\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">\n            FIG. 03 // DOME CHAMBER CROSS-SECTION &amp; THERMAL CURVATURE\n          </text>\n          <line x1=\"75\" y1=\"48\" x2=\"605\" y2=\"48\" stroke=\"#222222\" stroke-width=\"1\" />\n\n          <!-- Cutaway Dome Silhouette -->\n          <g transform=\"translate(190, 70)\">\n            <!-- Outer Mud Layer -->\n            <path d=\"M 30 190 C 30 70 80 20 150 20 C 220 20 270 70 270 190\" fill=\"none\" stroke=\"#8B5A2B\" stroke-width=\"40\" stroke-linecap=\"round\" />\n\n            <!-- Embedded Staggered Stones (Cross section) -->\n            <!-- Left wall stones -->\n            <ellipse cx=\"40\" cy=\"170\" rx=\"14\" ry=\"10\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <ellipse cx=\"44\" cy=\"130\" rx=\"13\" ry=\"9\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <ellipse cx=\"58\" cy=\"90\" rx=\"12\" ry=\"9\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <ellipse cx=\"85\" cy=\"55\" rx=\"12\" ry=\"8\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <!-- Top apex stones -->\n            <ellipse cx=\"125\" cy=\"32\" rx=\"12\" ry=\"8\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <ellipse cx=\"175\" cy=\"32\" rx=\"12\" ry=\"8\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <!-- Right wall stones -->\n            <ellipse cx=\"215\" cy=\"55\" rx=\"12\" ry=\"8\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <ellipse cx=\"242\" cy=\"90\" rx=\"12\" ry=\"9\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <ellipse cx=\"256\" cy=\"130\" rx=\"13\" ry=\"9\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <ellipse cx=\"260\" cy=\"170\" rx=\"14\" ry=\"10\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n\n            <!-- Smooth Interior Heat Reflector Surface -->\n            <path d=\"M 50 190 C 50 90 90 40 150 40 C 210 40 250 90 250 190\" fill=\"#141414\" stroke=\"#F59E0B\" stroke-width=\"2\" />\n\n            <!-- Rotating Heat Swirl Inside Chamber -->\n            <path d=\"M 120 160 Q 150 100 180 140 Q 150 170 135 120\" fill=\"none\" stroke=\"#E02424\" stroke-width=\"2\" stroke-dasharray=\"3,3\" marker-end=\"url(#arrow-swirl)\" />\n\n            <!-- Dimension: Height 45cm (무릎 높이) -->\n            <line x1=\"295\" y1=\"20\" x2=\"295\" y2=\"190\" stroke=\"#06B6D4\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n            <line x1=\"290\" y1=\"20\" x2=\"300\" y2=\"20\" stroke=\"#06B6D4\" stroke-width=\"1\" />\n            <line x1=\"290\" y1=\"190\" x2=\"300\" y2=\"190\" stroke=\"#06B6D4\" stroke-width=\"1\" />\n            <text x=\"305\" y=\"110\" fill=\"#06B6D4\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\">45cm</text>\n          </g>\n\n          <!-- Label 1: 돌과 진흙을 엇갈려 쌓은 벽체 단면 -->\n          <line x1=\"210\" y1=\"180\" x2=\"130\" y2=\"150\" stroke=\"#E5E5E5\" stroke-width=\"1\" />\n          <text x=\"75\" y=\"125\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ① 엇갈려 쌓은 벽체 단면\n          </text>\n          <text x=\"75\" y=\"143\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            돌 틈에 진흙을 채워 무너짐 방지\n          </text>\n\n          <!-- Label 2: 손바닥 두께(약 5cm) 단열벽 -->\n          <line x1=\"430\" y1=\"180\" x2=\"480\" y2=\"150\" stroke=\"#D97706\" stroke-width=\"1\" />\n          <text x=\"470\" y=\"130\" fill=\"#D97706\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ② 손바닥 두께(약 5cm) 진흙벽\n          </text>\n          <text x=\"470\" y=\"148\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            바깥으로 새는 열 손실 완벽 차단\n          </text>\n\n          <!-- Label 3: 안쪽 벽면 매끄러운 열 반사 곡면 -->\n          <line x1=\"270\" y1=\"130\" x2=\"150\" y2=\"225\" stroke=\"#F59E0B\" stroke-width=\"1\" />\n          <text x=\"75\" y=\"235\" fill=\"#F59E0B\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ③ 매끄러운 열 반사 곡면\n          </text>\n          <text x=\"75\" y=\"253\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            손에 물을 묻혀 반질반질하게 다듬기\n          </text>\n\n          <!-- Label 4: 열기가 모여 회전하는 연소실 내부 -->\n          <text x=\"210\" y=\"295\" fill=\"#E02424\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ④ 열기가 모여 회전하는 둥근 연소실 내부\n          </text>\n\n          <!-- Label 5: 무릎 높이(약 45cm) 전체 외형선 -->\n          <text x=\"460\" y=\"235\" fill=\"#06B6D4\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ⑤ 무릎 높이(약 45cm) 외형선\n          </text>\n          <text x=\"460\" y=\"253\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            취사 안정성과 축열 용적 최적화\n          </text>\n        </svg>","content/svgs/pr06-step-04.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto block\" xmlns=\"http://www.w3.org/2000/svg\">\n          <defs>\n            <marker id=\"arrow-draft-blue\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n              <path d=\"M 0 1 L 8 5 L 0 9 z\" fill=\"#06B6D4\" />\n            </marker>\n            <marker id=\"arrow-draft-red\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n              <path d=\"M 0 1 L 8 5 L 0 9 z\" fill=\"#E02424\" />\n            </marker>\n            <marker id=\"arrow-smoke\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n              <path d=\"M 0 1 L 8 5 L 0 9 z\" fill=\"#888888\" />\n            </marker>\n          </defs>\n\n          <!-- Blueprint Header -->\n          <text x=\"75\" y=\"40\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">\n            FIG. 04 // AIR DRAFT PERSPECTIVE &amp; EXHAUST BLUEPRINT\n          </text>\n          <line x1=\"75\" y1=\"48\" x2=\"605\" y2=\"48\" stroke=\"#222222\" stroke-width=\"1\" />\n\n          <!-- Perspective Cutaway Chamber -->\n          <g transform=\"translate(160, 65)\">\n            <!-- Outer structure wireframe / body -->\n            <path d=\"M 30 180 L 30 120 Q 50 40 160 30 L 260 50 Q 320 80 330 180 Z\" fill=\"#151515\" stroke=\"#333333\" stroke-width=\"1\" />\n\n            <!-- Flat Top Cooking Rim (냄비 얹는 자리) -->\n            <ellipse cx=\"160\" cy=\"40\" rx=\"36\" ry=\"12\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"2\" />\n            <path d=\"M 124 40 Q 160 52 196 40\" stroke=\"#888888\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n\n            <!-- Clay Spacer Knobs (틈새 돌기) -->\n            <circle cx=\"128\" cy=\"38\" r=\"3\" fill=\"#F59E0B\" />\n            <circle cx=\"160\" cy=\"51\" r=\"3\" fill=\"#F59E0B\" />\n            <circle cx=\"192\" cy=\"38\" r=\"3\" fill=\"#F59E0B\" />\n\n            <!-- Rear Chimney Flue (뒤편 굴뚝 구멍) -->\n            <ellipse cx=\"275\" cy=\"55\" rx=\"18\" ry=\"8\" fill=\"#111111\" stroke=\"#888888\" stroke-width=\"1.5\" />\n            <path d=\"M 275 55 Q 290 20 285 5\" stroke=\"#888888\" stroke-width=\"2\" stroke-dasharray=\"3,3\" marker-end=\"url(#arrow-smoke)\" />\n\n            <!-- Front Air/Wood Opening (앞쪽 하부 흡입구) -->\n            <path d=\"M 30 180 Q 70 120 110 180\" fill=\"#0C0C0C\" stroke=\"#06B6D4\" stroke-width=\"2\" />\n\n            <!-- Internal Fire Draft Flow -->\n            <!-- Blue Oxygen entry -->\n            <path d=\"M 10 165 L 60 160\" stroke=\"#06B6D4\" stroke-width=\"2.5\" marker-end=\"url(#arrow-draft-blue)\" />\n            <!-- Red Flame Rising to pot -->\n            <path d=\"M 80 155 Q 120 110 155 60\" stroke=\"#E02424\" stroke-width=\"2.5\" marker-end=\"url(#arrow-draft-red)\" />\n            <!-- Red Heat to rear chimney -->\n            <path d=\"M 140 100 Q 210 90 265 65\" stroke=\"#E02424\" stroke-width=\"2\" stroke-dasharray=\"3,3\" marker-end=\"url(#arrow-draft-red)\" />\n          </g>\n\n          <!-- Label 1: 앞쪽 하부 공기 흡입구 -->\n          <text x=\"75\" y=\"260\" fill=\"#06B6D4\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ① 앞쪽 하부 공기 흡입구 (산소 유입)\n          </text>\n          <text x=\"75\" y=\"278\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            차가운 신선한 공기가 빨려 들어가는 길목\n          </text>\n\n          <!-- Label 2: 윗부분 평평한 조리용 구멍 -->\n          <line x1=\"320\" y1=\"100\" x2=\"220\" y2=\"70\" stroke=\"#E5E5E5\" stroke-width=\"1\" />\n          <text x=\"75\" y=\"90\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ② 윗부분 평평한 조리용 구멍\n          </text>\n          <text x=\"75\" y=\"108\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            냄비나 평평한 돌판을 얹는 화구\n          </text>\n\n          <!-- Label 3: 뒤편 상단 굴뚝 구멍 -->\n          <text x=\"445\" y=\"85\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ③ 뒤편 상단 굴뚝 구멍\n          </text>\n          <text x=\"445\" y=\"103\" fill=\"#666666\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            매운 연기를 뒤로 뽑아내는 배출구\n          </text>\n\n          <!-- Label 4: 붉은 화살표 열기 순환 -->\n          <text x=\"400\" y=\"185\" fill=\"#E02424\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ④ 솟구치는 열기 순환선\n          </text>\n          <text x=\"400\" y=\"203\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            연소실 안을 회전하며 냄비 바닥을 달굼\n          </text>\n\n          <!-- Label 5: 냄비를 얹어도 공기가 통하는 틈새 -->\n          <text x=\"390\" y=\"260\" fill=\"#F59E0B\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ⑤ 냄비 받침 통기 틈새 돌기\n          </text>\n          <text x=\"390\" y=\"278\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            냄비를 얹어도 불길이 막혀 꺼지지 않는 여유 공간\n          </text>\n        </svg>","content/svgs/pr06-step-05.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto block\" xmlns=\"http://www.w3.org/2000/svg\">\n          <!-- Blueprint Header -->\n          <text x=\"75\" y=\"40\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">\n            FIG. 05 // CONTROLLED DEHYDRATION &amp; CERAMIC HARDENING\n          </text>\n          <line x1=\"75\" y1=\"48\" x2=\"605\" y2=\"48\" stroke=\"#222222\" stroke-width=\"1\" />\n\n          <!-- Main Curing Stove Illustration -->\n          <g transform=\"translate(180, 70)\">\n            <!-- Left Side (Dark Wet Clay) transitioning to Right Side (Bright Baked Ocher) -->\n            <path d=\"M 40 180 C 40 80 80 40 140 40 L 180 40 C 240 40 280 80 280 180 Z\" fill=\"#2A1E14\" stroke=\"#D97706\" stroke-width=\"1.5\" />\n            \n            <!-- Baked Ocher Highlight on right half -->\n            <path d=\"M 160 40 C 220 40 260 80 260 180 L 160 180 Z\" fill=\"#422812\" opacity=\"0.6\" />\n\n            <!-- Rising Steam Lines (외벽 수증기) -->\n            <path d=\"M 80 50 Q 70 30 85 10\" stroke=\"#888888\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\" fill=\"none\" />\n            <path d=\"M 120 45 Q 110 25 125 5\" stroke=\"#888888\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\" fill=\"none\" />\n            <path d=\"M 200 45 Q 190 25 205 5\" stroke=\"#888888\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\" fill=\"none\" />\n            <path d=\"M 240 50 Q 230 30 245 10\" stroke=\"#888888\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\" fill=\"none\" />\n\n            <!-- Weak Ember Fire at Entry (작은 불씨) -->\n            <ellipse cx=\"60\" cy=\"175\" rx=\"20\" ry=\"8\" fill=\"#111111\" stroke=\"#333333\" stroke-width=\"1\" />\n            <circle cx=\"55\" cy=\"173\" r=\"3\" fill=\"#E02424\" />\n            <circle cx=\"65\" cy=\"175\" r=\"4\" fill=\"#F59E0B\" />\n            <circle cx=\"60\" cy=\"170\" r=\"2.5\" fill=\"#E5E5E5\" />\n\n            <!-- Small Surface Hairline Cracks being patched -->\n            <line x1=\"190\" y1=\"90\" x2=\"210\" y2=\"105\" stroke=\"#E5E5E5\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n            <!-- Patch indicator circle -->\n            <circle cx=\"200\" cy=\"98\" r=\"8\" fill=\"none\" stroke=\"#10B981\" stroke-width=\"1.5\" />\n          </g>\n\n          <!-- Label 1: 입구에 지핀 작은 잔가지 불씨 -->\n          <text x=\"75\" y=\"270\" fill=\"#F59E0B\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ① 입구 작은 잔가지 불씨 (약한 열기)\n          </text>\n          <text x=\"75\" y=\"288\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            강한 불 대신 은은한 열기로 시작\n          </text>\n\n          <!-- Label 2: 외벽에서 김(수증기)이 빠져나가는 모습 -->\n          <text x=\"75\" y=\"90\" fill=\"#AAAAAA\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ② 외벽 수증기 증발선\n          </text>\n          <text x=\"75\" y=\"108\" fill=\"#666666\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            내부 수분이 천천히 기화\n          </text>\n\n          <!-- Label 3: 진흙 색상 변화 -->\n          <text x=\"440\" y=\"90\" fill=\"#D97706\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ③ 색상 변화 관찰\n          </text>\n          <text x=\"440\" y=\"108\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            짙은 고동색 → 밝은 황토색\n          </text>\n\n          <!-- Label 4: 손을 댔을 때 따뜻한 열감 -->\n          <text x=\"440\" y=\"170\" fill=\"#10B981\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ④ 따뜻한 건조 완료 판정\n          </text>\n          <text x=\"440\" y=\"188\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            축축함 없이 외벽 전체가 훈훈\n          </text>\n\n          <!-- Label 5: 갈라진 미세 틈을 덧바를 진흙 반죽 여분 -->\n          <text x=\"390\" y=\"270\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ⑤ 미세 실금 덧바름 보수\n          </text>\n          <text x=\"390\" y=\"288\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            남은 진흙 반죽으로 틈새 메우기\n          </text>\n        </svg>","content/svgs/pr07-outcome.svg":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\" class=\"w-full h-auto\">\n  <defs>\n    <!-- Background Technical Gradient -->\n    <linearGradient id=\"bgGradOutcome\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#080a0e\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1218\"/>\n      <stop offset=\"100%\" stop-color=\"#090b0f\"/>\n    </linearGradient>\n\n    <!-- Timber Anchor Post Gradients -->\n    <linearGradient id=\"anchorPostCylinder\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#2d1e12\"/>\n      <stop offset=\"25%\" stop-color=\"#4a3320\"/>\n      <stop offset=\"50%\" stop-color=\"#735235\"/>\n      <stop offset=\"75%\" stop-color=\"#553a24\"/>\n      <stop offset=\"100%\" stop-color=\"#1e140c\"/>\n    </linearGradient>\n    <linearGradient id=\"anchorTopCap\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#5a4029\"/>\n      <stop offset=\"50%\" stop-color=\"#7a583a\"/>\n      <stop offset=\"100%\" stop-color=\"#3b291a\"/>\n    </linearGradient>\n\n    <!-- Wood Bark Texture Pattern -->\n    <pattern id=\"barkLines\" width=\"20\" height=\"40\" patternUnits=\"userSpaceOnUse\">\n      <line x1=\"5\" y1=\"0\" x2=\"4\" y2=\"40\" stroke=\"#1f140b\" stroke-width=\"1.2\" opacity=\"0.6\"/>\n      <line x1=\"12\" y1=\"0\" x2=\"13\" y2=\"40\" stroke=\"#1f140b\" stroke-width=\"1.5\" opacity=\"0.5\"/>\n      <line x1=\"18\" y1=\"0\" x2=\"17\" y2=\"40\" stroke=\"#8c6442\" stroke-width=\"0.8\" opacity=\"0.3\"/>\n    </pattern>\n\n    <!-- Manila Standing Rope 3D Tubular Gradient -->\n    <linearGradient id=\"ropeManilaOutcome\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#652b05\"/>\n      <stop offset=\"20%\" stop-color=\"#a14908\"/>\n      <stop offset=\"48%\" stop-color=\"#fef3c7\"/>\n      <stop offset=\"75%\" stop-color=\"#b45309\"/>\n      <stop offset=\"100%\" stop-color=\"#3d1502\"/>\n    </linearGradient>\n\n    <!-- Tactical Green Working Rope 3D Gradient -->\n    <linearGradient id=\"ropeGreenOutcome\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#0f3d20\"/>\n      <stop offset=\"22%\" stop-color=\"#15803d\"/>\n      <stop offset=\"48%\" stop-color=\"#bbf7d0\"/>\n      <stop offset=\"75%\" stop-color=\"#16a34a\"/>\n      <stop offset=\"100%\" stop-color=\"#052e16\"/>\n    </linearGradient>\n\n    <!-- Deep Drop Shadow for Over/Under Crossing -->\n    <filter id=\"shadowDeepOutcome\" x=\"-30%\" y=\"-30%\" width=\"160%\" height=\"160%\">\n      <feDropShadow dx=\"0\" dy=\"6\" stdDeviation=\"6\" flood-color=\"#000000\" flood-opacity=\"0.95\"/>\n    </filter>\n\n    <!-- Manila Braid Texture Pattern -->\n    <pattern id=\"braidManilaOutcome\" width=\"14\" height=\"14\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(45)\">\n      <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"14\" stroke=\"#451a03\" stroke-width=\"2.5\" opacity=\"0.65\"/>\n      <line x1=\"7\" y1=\"0\" x2=\"7\" y2=\"14\" stroke=\"#fef3c7\" stroke-width=\"1.8\" opacity=\"0.45\"/>\n    </pattern>\n\n    <!-- Paracord Texture Pattern for Working Tail -->\n    <pattern id=\"braidGreenOutcome\" width=\"8\" height=\"8\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(-45)\">\n      <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"8\" stroke=\"#052e16\" stroke-width=\"2\" opacity=\"0.7\"/>\n      <line x1=\"4\" y1=\"0\" x2=\"4\" y2=\"8\" stroke=\"#bbf7d0\" stroke-width=\"1.2\" opacity=\"0.5\"/>\n    </pattern>\n  </defs>\n\n  <!-- Technical Canvas Backdrop -->\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"450\" fill=\"url(#bgGradOutcome)\"/>\n  <rect x=\"14\" y=\"14\" width=\"772\" height=\"422\" fill=\"none\" stroke=\"#22262e\" stroke-width=\"1\"/>\n\n  <!-- Technical Corner Crosshairs -->\n  <path d=\"M 22 32 L 34 32 M 28 26 L 28 38\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 778 32 L 766 32 M 772 26 L 772 38\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 22 418 L 34 418 M 28 412 L 28 424\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 778 418 L 766 418 M 772 412 L 772 424\" stroke=\"#374151\" stroke-width=\"1\"/>\n\n  <!-- Blueprint Header Strip -->\n  <text x=\"32\" y=\"38\" fill=\"#9ca3af\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">ARCHIVE // MASTER SPECIFICATION</text>\n  <text x=\"32\" y=\"56\" fill=\"#ef4444\" font-family=\"'JetBrains Mono', monospace\" font-size=\"12\" font-weight=\"bold\">BOWLINE MASTER BLUEPRINT // 매듭의 왕 완전 제원도</text>\n  <text x=\"768\" y=\"38\" fill=\"#22c55e\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">RELEASE: 1.0 SEC // JAM-PROOF</text>\n  <line x1=\"32\" y1=\"66\" x2=\"768\" y2=\"66\" stroke=\"#262d35\" stroke-width=\"1\"/>\n\n  <!-- Left Technical Spec Card -->\n  <g id=\"specCardLeft\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\">\n    <rect x=\"32\" y=\"80\" width=\"190\" height=\"175\" fill=\"#111419\" stroke=\"#262d35\" stroke-width=\"1\"/>\n    <rect x=\"32\" y=\"80\" width=\"190\" height=\"24\" fill=\"#181d24\"/>\n    <text x=\"44\" y=\"96\" fill=\"#ef4444\" font-weight=\"bold\">BOWLINE SPECIFICATIONS</text>\n    <text x=\"44\" y=\"122\" fill=\"#d1d5db\">· KNOT TYPE: FIXED LOOP</text>\n    <text x=\"44\" y=\"142\" fill=\"#d1d5db\">· SLIPPAGE: ZERO (0%)</text>\n    <text x=\"44\" y=\"162\" fill=\"#d1d5db\">· EFFICIENCY: 75% RATING</text>\n    <text x=\"44\" y=\"182\" fill=\"#d1d5db\">· JAMMING: 100% JAM-PROOF</text>\n    <text x=\"44\" y=\"202\" fill=\"#d1d5db\">· RELEASE: BREAK THE BACK</text>\n    <text x=\"44\" y=\"222\" fill=\"#4ade80\">· LOAD CAPACITY: 500+ KG</text>\n    <text x=\"44\" y=\"242\" fill=\"#38bdf8\">· TAIL POSITION: INSIDE LOOP</text>\n  </g>\n\n  <!-- Left Material Guide Strip -->\n  <g id=\"matGuideLeft\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\">\n    <rect x=\"32\" y=\"265\" width=\"190\" height=\"135\" fill=\"#0d1014\" stroke=\"#1e242c\" stroke-width=\"1\"/>\n    <rect x=\"32\" y=\"265\" width=\"4\" height=\"135\" fill=\"#f59e0b\"/>\n    <text x=\"44\" y=\"284\" fill=\"#f59e0b\" font-weight=\"bold\">[TWO-COLOR CONTRAST]</text>\n    <rect x=\"44\" y=\"295\" width=\"12\" height=\"12\" fill=\"url(#ropeManilaOutcome)\"/>\n    <text x=\"62\" y=\"305\" fill=\"#fde68a\">원줄: 마닐라 탄 로프</text>\n    <text x=\"62\" y=\"318\" fill=\"#9ca3af\">(하중 지탱 주 라인)</text>\n    <rect x=\"44\" y=\"335\" width=\"12\" height=\"12\" fill=\"url(#ropeGreenOutcome)\"/>\n    <text x=\"62\" y=\"345\" fill=\"#86efac\">작동 끝단: 전술 그린 줄</text>\n    <text x=\"62\" y=\"358\" fill=\"#9ca3af\">(토끼 궤적 전용 식별)</text>\n    <text x=\"44\" y=\"385\" fill=\"#38bdf8\">안전: 꼬리는 고리 안쪽 위치</text>\n  </g>\n\n  <!-- Ground Plane Cast Shadow -->\n  <ellipse cx=\"440\" cy=\"410\" rx=\"220\" ry=\"16\" fill=\"#030405\" opacity=\"0.95\"/>\n\n  <!-- ============================================================== -->\n  <!-- 3D RIGGING SCENE: TIMBER POST + 3D BRAIDED BOWLINE KNOT -->\n  <!-- ============================================================== -->\n  <!-- 1. Anchor Post: Rope passing BEHIND Post (Drawn First) -->\n  <path d=\"M 410 325 C 455 350 515 350 550 325\" stroke=\"#000000\" stroke-width=\"22\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 410 325 C 455 350 515 350 550 325\" stroke=\"url(#ropeManilaOutcome)\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 410 325 C 455 350 515 350 550 325\" stroke=\"url(#braidManilaOutcome)\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.8\"/>\n\n  <!-- 2. Timber Anchor Post Solid Cylinder -->\n  <g id=\"timberPostGroup\">\n    <!-- Cast Shadow on Timber Post from incoming top line -->\n    <polygon points=\"480,210 525,210 520,415 475,415\" fill=\"url(#anchorPostCylinder)\" stroke=\"#1a120b\" stroke-width=\"1.5\"/>\n    <polygon points=\"480,210 525,210 520,415 475,415\" fill=\"url(#barkLines)\" opacity=\"0.65\"/>\n    <!-- Top Cap Ellipse with Tree Growth Rings -->\n    <ellipse cx=\"502\" cy=\"210\" rx=\"22.5\" ry=\"9\" fill=\"url(#anchorTopCap)\" stroke=\"#261b11\" stroke-width=\"1.5\"/>\n    <ellipse cx=\"502\" cy=\"210\" rx=\"15\" ry=\"6\" fill=\"none\" stroke=\"#3b291a\" stroke-width=\"1\"/>\n    <ellipse cx=\"502\" cy=\"210\" rx=\"7\" ry=\"3\" fill=\"none\" stroke=\"#261b11\" stroke-width=\"0.8\"/>\n    <!-- Timber Post Label -->\n    <text x=\"502\" y=\"195\" fill=\"#d1d5db\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"middle\">TIMBER POST</text>\n  </g>\n\n  <!-- 3. Anchor Post: Rope passing IN FRONT OF Post (Drawn After Post) -->\n  <path d=\"M 550 325 C 525 285 460 280 415 295\" stroke=\"#000000\" stroke-width=\"22\" stroke-linecap=\"round\" fill=\"none\" filter=\"url(#shadowDeepOutcome)\"/>\n  <path d=\"M 550 325 C 525 285 460 280 415 295\" stroke=\"url(#ropeManilaOutcome)\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 550 325 C 525 285 460 280 415 295\" stroke=\"url(#braidManilaOutcome)\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.8\"/>\n\n  <!-- 4. Main Standing Line (하중 받는 수직 원줄) -->\n  <path d=\"M 315 75 L 315 190\" stroke=\"#000000\" stroke-width=\"24\" stroke-linecap=\"round\"/>\n  <path d=\"M 315 75 L 315 190\" stroke=\"url(#ropeManilaOutcome)\" stroke-width=\"15\" stroke-linecap=\"round\"/>\n  <path d=\"M 315 75 L 315 190\" stroke=\"url(#braidManilaOutcome)\" stroke-width=\"15\" stroke-linecap=\"round\" opacity=\"0.8\"/>\n\n  <!-- 5. Nipper Loop Ring (토끼굴 3D 고리) -->\n  <path d=\"M 315 190 C 275 200 265 240 305 252 C 335 258 355 232 340 205 C 335 195 315 190 315 190\" \n        stroke=\"#000000\" stroke-width=\"24\" stroke-linecap=\"round\" fill=\"none\" filter=\"url(#shadowDeepOutcome)\"/>\n  <path d=\"M 315 190 C 275 200 265 240 305 252 C 335 258 355 232 340 205 C 335 195 315 190 315 190\" \n        stroke=\"url(#ropeManilaOutcome)\" stroke-width=\"15\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 315 190 C 275 200 265 240 305 252 C 335 258 355 232 340 205 C 335 195 315 190 315 190\" \n        stroke=\"url(#braidManilaOutcome)\" stroke-width=\"15\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.8\"/>\n\n  <!-- 6. Collar Loop (뒤통수 칼라 링) Wrapped around Standing Line -->\n  <path d=\"M 310 248 C 295 230 290 190 315 180 C 345 170 365 205 340 245\" \n        stroke=\"#000000\" stroke-width=\"24\" stroke-linecap=\"round\" fill=\"none\" filter=\"url(#shadowDeepOutcome)\"/>\n  <path d=\"M 310 248 C 295 230 290 190 315 180 C 345 170 365 205 340 245\" \n        stroke=\"url(#ropeGreenOutcome)\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 310 248 C 295 230 290 190 315 180 C 345 170 365 205 340 245\" \n        stroke=\"url(#braidGreenOutcome)\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.75\"/>\n\n  <!-- 7. Working End Tail (고리 안쪽에 안전하게 잠긴 토끼 꼬리) -->\n  <path d=\"M 335 240 L 365 295\" stroke=\"#000000\" stroke-width=\"22\" stroke-linecap=\"round\" filter=\"url(#shadowDeepOutcome)\"/>\n  <path d=\"M 335 240 L 365 295\" stroke=\"url(#ropeGreenOutcome)\" stroke-width=\"14\" stroke-linecap=\"round\"/>\n  <path d=\"M 335 240 L 365 295\" stroke=\"url(#braidGreenOutcome)\" stroke-width=\"14\" stroke-linecap=\"round\" opacity=\"0.75\"/>\n\n  <!-- 8. Eye Loop Leads connecting knot to anchor post -->\n  <path d=\"M 305 252 C 295 285 350 310 410 325\" stroke=\"#000000\" stroke-width=\"24\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 305 252 C 295 285 350 310 410 325\" stroke=\"url(#ropeManilaOutcome)\" stroke-width=\"15\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 305 252 C 295 285 350 310 410 325\" stroke=\"url(#braidManilaOutcome)\" stroke-width=\"15\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.8\"/>\n\n  <path d=\"M 415 295 C 380 285 350 270 335 240\" stroke=\"#000000\" stroke-width=\"24\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 415 295 C 380 285 350 270 335 240\" stroke=\"url(#ropeManilaOutcome)\" stroke-width=\"15\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 415 295 C 380 285 350 270 335 240\" stroke=\"url(#braidManilaOutcome)\" stroke-width=\"15\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.8\"/>\n\n  <!-- Dynamic Opposing Tension Force Arrows -->\n  <g stroke=\"#ef4444\" stroke-width=\"2.5\" fill=\"none\">\n    <!-- Tension upward on standing line -->\n    <line x1=\"315\" y1=\"135\" x2=\"315\" y2=\"95\"/>\n    <polygon points=\"315,86 308,100 322,100\" fill=\"#ef4444\"/>\n    <!-- Tension pulling toward timber anchor post -->\n    <line x1=\"410\" y1=\"300\" x2=\"445\" y2=\"310\"/>\n    <polygon points=\"453,312 439,305 443,319\" fill=\"#ef4444\"/>\n  </g>\n\n  <!-- ============================================================== -->\n  <!-- RIGHT TECHNICAL PANEL: 1-SECOND QUICK RELEASE MECHANISM -->\n  <!-- ============================================================== -->\n  <g id=\"quickReleasePanel\">\n    <rect x=\"560\" y=\"80\" width=\"205\" height=\"195\" fill=\"#111419\" stroke=\"#ef4444\" stroke-width=\"1\"/>\n    <rect x=\"560\" y=\"80\" width=\"205\" height=\"24\" fill=\"#241010\"/>\n    <text x=\"572\" y=\"96\" fill=\"#ef4444\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">1-SEC BREAK-THE-BACK</text>\n\n    <!-- Finger Action Principles -->\n    <text x=\"572\" y=\"122\" fill=\"#ffffff\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\" font-weight=\"bold\">칼라(뒤통수) 꺾기 원리</text>\n    <text x=\"572\" y=\"140\" fill=\"#9ca3af\" font-family=\"'Chivo', sans-serif\" font-size=\"8.5\">1. 매듭 뒤편 둥근 칼라 고리 확인</text>\n    <text x=\"572\" y=\"156\" fill=\"#9ca3af\" font-family=\"'Chivo', sans-serif\" font-size=\"8.5\">2. 엄지로 칼라를 바깥쪽으로 젖힘</text>\n    <text x=\"572\" y=\"172\" fill=\"#9ca3af\" font-family=\"'Chivo', sans-serif\" font-size=\"8.5\">3. 마찰 락 즉시 풀려 1초 만에 해체</text>\n\n    <!-- Mini Loupe Vector of the Release Action -->\n    <circle cx=\"660\" cy=\"225\" r=\"32\" fill=\"#080a0e\" stroke=\"#262d35\" stroke-width=\"1\"/>\n    <!-- Standing Rope in Loupe -->\n    <line x1=\"660\" y1=\"198\" x2=\"660\" y2=\"252\" stroke=\"#b45309\" stroke-width=\"7\" stroke-linecap=\"round\"/>\n    <!-- Collar Loop being bent backwards -->\n    <path d=\"M 645 225 C 645 208 675 208 675 225\" stroke=\"#22c55e\" stroke-width=\"6\" stroke-linecap=\"round\" fill=\"none\"/>\n    <!-- Thumb Push Arrow -->\n    <line x1=\"660\" y1=\"235\" x2=\"660\" y2=\"212\" stroke=\"#38bdf8\" stroke-width=\"2.2\"/>\n    <polygon points=\"660,205 654,216 666,216\" fill=\"#38bdf8\"/>\n    <text x=\"660\" y=\"248\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\" font-weight=\"bold\" text-anchor=\"middle\">PUSH UP</text>\n\n    <!-- Bottom Jam-Proof Stamp -->\n    <rect x=\"560\" y=\"250\" width=\"205\" height=\"25\" fill=\"#052e16\"/>\n    <text x=\"662\" y=\"266\" fill=\"#4ade80\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"middle\">JAM-PROOF // 칼날 불필요</text>\n  </g>\n\n  <!-- Right Safety Warning Box -->\n  <g id=\"safetyWarningBox\">\n    <rect x=\"560\" y=\"290\" width=\"205\" height=\"110\" fill=\"#140d0d\" stroke=\"#ef4444\" stroke-width=\"1\"/>\n    <rect x=\"560\" y=\"290\" width=\"205\" height=\"20\" fill=\"#2d1212\"/>\n    <text x=\"572\" y=\"304\" fill=\"#ef4444\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\">[FATAL MISTAKE 방지]</text>\n    <text x=\"572\" y=\"326\" fill=\"#fca5a5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"8.5\" font-weight=\"bold\">토끼 꼬리는 반드시 고리 안쪽!</text>\n    <text x=\"572\" y=\"344\" fill=\"#9ca3af\" font-family=\"'Chivo', sans-serif\" font-size=\"8\">바깥으로 노출되면 마찰에 쓸려</text>\n    <text x=\"572\" y=\"358\" fill=\"#9ca3af\" font-family=\"'Chivo', sans-serif\" font-size=\"8\">매듭이 저절로 풀릴 수 있습니다.</text>\n    <text x=\"572\" y=\"382\" fill=\"#22c55e\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\">INSIDE TAIL = 100% SECURE</text>\n  </g>\n\n  <!-- ============================================================== -->\n  <!-- TECHNICAL CALLOUTS & DIMENSIONS -->\n  <!-- ============================================================== -->\n  <g id=\"calloutsMaster\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\">\n    <!-- Callout 1: Standing Line -->\n    <line x1=\"315\" y1=\"130\" x2=\"365\" y2=\"130\" stroke=\"#9ca3af\" stroke-width=\"1\"/>\n    <circle cx=\"315\" cy=\"130\" r=\"2.5\" fill=\"#f59e0b\"/>\n    <text x=\"375\" y=\"126\" fill=\"#ffffff\" font-weight=\"bold\">STANDING PART</text>\n    <text x=\"375\" y=\"140\" fill=\"#9ca3af\">하중을 받는 주 원줄</text>\n\n    <!-- Callout 2: Fixed Eye Loop -->\n    <line x1=\"450\" y1=\"330\" x2=\"450\" y2=\"370\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n    <circle cx=\"450\" cy=\"330\" r=\"2.5\" fill=\"#38bdf8\"/>\n    <text x=\"450\" y=\"386\" fill=\"#38bdf8\" font-weight=\"bold\">FIXED EYE LOOP</text>\n    <text x=\"450\" y=\"400\" fill=\"#9ca3af\">하중에도 줄어들지 않는 고리</text>\n\n    <!-- Callout 3: Working End Tail -->\n    <line x1=\"365\" y1=\"290\" x2=\"320\" y2=\"335\" stroke=\"#22c55e\" stroke-width=\"1\"/>\n    <circle cx=\"365\" cy=\"290\" r=\"2.5\" fill=\"#22c55e\"/>\n    <text x=\"310\" y=\"340\" fill=\"#4ade80\" font-weight=\"bold\" text-anchor=\"end\">WORKING END TAIL</text>\n    <text x=\"310\" y=\"354\" fill=\"#9ca3af\" text-anchor=\"end\">고리 안쪽으로 단단히 잠김</text>\n  </g>\n</svg>\n","content/svgs/pr07-step-01.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgGrad01\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#08090b\"/>\n      <stop offset=\"50%\" stop-color=\"#0f1216\"/>\n      <stop offset=\"100%\" stop-color=\"#0a0c0e\"/>\n    </linearGradient>\n\n    <!-- Manila Standing Rope 3D Tubular Gradient -->\n    <linearGradient id=\"ropeManila\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#78350f\"/>\n      <stop offset=\"25%\" stop-color=\"#b45309\"/>\n      <stop offset=\"50%\" stop-color=\"#fef3c7\"/>\n      <stop offset=\"75%\" stop-color=\"#d97706\"/>\n      <stop offset=\"100%\" stop-color=\"#451a03\"/>\n    </linearGradient>\n\n    <!-- Tactical Green Working Rope 3D Gradient -->\n    <linearGradient id=\"ropeTacticalGreen\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#14532d\"/>\n      <stop offset=\"25%\" stop-color=\"#16a34a\"/>\n      <stop offset=\"50%\" stop-color=\"#bbf7d0\"/>\n      <stop offset=\"75%\" stop-color=\"#22c55e\"/>\n      <stop offset=\"100%\" stop-color=\"#052e16\"/>\n    </linearGradient>\n\n    <!-- Deep Drop Shadow Filter for Over/Under Crossing -->\n    <filter id=\"shadowDeep\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"4\" flood-color=\"#000000\" flood-opacity=\"0.95\"/>\n    </filter>\n\n    <!-- Twisted Rope Braid Pattern for Manila Rope -->\n    <pattern id=\"braidManila\" width=\"12\" height=\"12\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(45)\">\n      <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"12\" stroke=\"#451a03\" stroke-width=\"2.5\" opacity=\"0.6\"/>\n      <line x1=\"6\" y1=\"0\" x2=\"6\" y2=\"12\" stroke=\"#fef3c7\" stroke-width=\"1.5\" opacity=\"0.4\"/>\n    </pattern>\n\n    <!-- Paracord Texture Pattern for Working End -->\n    <pattern id=\"braidGreen\" width=\"8\" height=\"8\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(-45)\">\n      <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"8\" stroke=\"#052e16\" stroke-width=\"2\" opacity=\"0.7\"/>\n      <line x1=\"4\" y1=\"0\" x2=\"4\" y2=\"8\" stroke=\"#bbf7d0\" stroke-width=\"1.2\" opacity=\"0.5\"/>\n    </pattern>\n  </defs>\n\n  <!-- Technical Canvas Backdrop -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgGrad01)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#22262c\" stroke-width=\"1\"/>\n\n  <!-- Technical Corner Crosshairs -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n\n  <!-- Blueprint Header -->\n  <text x=\"24\" y=\"28\" fill=\"#9ca3af\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">FIG. 01 // BOWLINE STEP 1: 토끼굴 고리 형성</text>\n  <line x1=\"24\" y1=\"36\" x2=\"376\" y2=\"36\" stroke=\"#262d35\" stroke-width=\"1\"/>\n\n  <!-- Background Reference Grid for Scale -->\n  <g opacity=\"0.12\" stroke=\"#4b5563\" stroke-width=\"0.5\" stroke-dasharray=\"2 4\">\n    <line x1=\"60\" y1=\"40\" x2=\"60\" y2=\"340\"/>\n    <line x1=\"200\" y1=\"40\" x2=\"200\" y2=\"340\"/>\n    <line x1=\"340\" y1=\"40\" x2=\"340\" y2=\"340\"/>\n    <line x1=\"20\" y1=\"120\" x2=\"380\" y2=\"120\"/>\n    <line x1=\"20\" y1=\"200\" x2=\"380\" y2=\"200\"/>\n    <line x1=\"20\" y1=\"280\" x2=\"380\" y2=\"280\"/>\n  </g>\n\n  <!-- ============================================================== -->\n  <!-- 1. STANDING PART (원줄 / 서 있는 나무) - 수직 황갈색 삼끈 로프 -->\n  <!-- ============================================================== -->\n  <!-- Ground contact shadow -->\n  <ellipse cx=\"200\" cy=\"335\" rx=\"16\" ry=\"5\" fill=\"#000000\" opacity=\"0.6\"/>\n\n  <!-- Standing Rope Segment: Top to Loop Entrance -->\n  <path d=\"M 200 42 L 200 120\" stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\"/>\n  <path d=\"M 200 42 L 200 120\" stroke=\"url(#ropeManila)\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n  <path d=\"M 200 42 L 200 120\" stroke=\"url(#braidManila)\" stroke-width=\"12\" stroke-linecap=\"round\" opacity=\"0.7\"/>\n\n  <!-- Loop Body (토끼굴의 아래쪽 루프 곡선 - 숫자 6의 둥근 배) -->\n  <!-- Deep drop shadow behind loop -->\n  <path d=\"M 200 120 C 130 135 125 225 190 235 C 245 240 265 195 240 160 C 220 135 185 128 150 145\" \n        stroke=\"#000000\" stroke-width=\"20\" stroke-linecap=\"round\" fill=\"none\"/>\n  <!-- Base Manila 3D Tube -->\n  <path d=\"M 200 120 C 130 135 125 225 190 235 C 245 240 265 195 240 160 C 220 135 185 128 150 145\" \n        stroke=\"url(#ropeManila)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 200 120 C 130 135 125 225 190 235 C 245 240 265 195 240 160 C 220 135 185 128 150 145\" \n        stroke=\"url(#braidManila)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.75\"/>\n\n  <!-- Standing Part Continuation downwards (수직 원줄의 하단부) -->\n  <path d=\"M 190 235 L 195 330\" stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\"/>\n  <path d=\"M 190 235 L 195 330\" stroke=\"url(#ropeManila)\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n  <path d=\"M 190 235 L 195 330\" stroke=\"url(#braidManila)\" stroke-width=\"12\" stroke-linecap=\"round\" opacity=\"0.7\"/>\n\n  <!-- ============================================================== -->\n  <!-- 2. WORKING END (작동 줄 - 녹색 토끼 줄) - 원줄 \"위(OVER)\" 교차! -->\n  <!-- ============================================================== -->\n  <!-- The crossing segment with heavy physical drop shadow to prove OVER crossing -->\n  <g filter=\"url(#shadowDeep)\">\n    <!-- Black cast shadow mask -->\n    <path d=\"M 150 145 C 135 155 105 195 105 250 L 105 320\" \n          stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\" fill=\"none\"/>\n    <!-- 3D Tactical Green Tube -->\n    <path d=\"M 150 145 C 135 155 105 195 105 250 L 105 320\" \n          stroke=\"url(#ropeTacticalGreen)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n    <path d=\"M 150 145 C 135 155 105 195 105 250 L 105 320\" \n          stroke=\"url(#braidGreen)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.8\"/>\n  </g>\n\n  <!-- Heat-sealed Rope End Cap (작동 줄 끝단 마감 테이프 디테일) -->\n  <line x1=\"100\" y1=\"320\" x2=\"110\" y2=\"320\" stroke=\"#ef4444\" stroke-width=\"4\" stroke-linecap=\"square\"/>\n\n  <!-- ============================================================== -->\n  <!-- 3. INSET LOUPE: OVER 교차점 3D 확대경 (인간 인지성 극대화) -->\n  <!-- ============================================================== -->\n  <!-- Inset Loupe Circular Frame at Top Right -->\n  <g transform=\"translate(300, 110)\">\n    <circle cx=\"0\" cy=\"0\" r=\"32\" fill=\"#0c0e12\" stroke=\"#22c55e\" stroke-width=\"1.8\"/>\n    <circle cx=\"0\" cy=\"0\" r=\"30\" fill=\"none\" stroke=\"#222\" stroke-width=\"1\"/>\n    \n    <!-- Underneath Manila Rope inside Zoom -->\n    <path d=\"M -30 6 L 30 -6\" stroke=\"#000000\" stroke-width=\"16\" stroke-linecap=\"round\"/>\n    <path d=\"M -30 6 L 30 -6\" stroke=\"url(#ropeManila)\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n    \n    <!-- OVER Green Rope with Deep Cast Shadow -->\n    <path d=\"M -8 -30 L 8 30\" stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\"/>\n    <path d=\"M -8 -30 L 8 30\" stroke=\"url(#ropeTacticalGreen)\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n    \n    <!-- \"OVER\" Visual Indicator inside Loupe -->\n    <rect x=\"-16\" y=\"-12\" width=\"32\" height=\"6\" fill=\"#14532d\" stroke=\"#22c55e\" stroke-width=\"0.8\"/>\n    <polygon points=\"0,-15 -4,-12 4,-12\" fill=\"#22c55e\"/>\n    \n    <!-- Loupe Leader Line connecting to actual crossing -->\n    <path d=\"M -22 22 L -100 35\" stroke=\"#22c55e\" stroke-width=\"1\" stroke-dasharray=\"2 2\" fill=\"none\"/>\n    <circle cx=\"-100\" cy=\"35\" r=\"3\" fill=\"#22c55e\"/>\n  </g>\n\n  <!-- ============================================================== -->\n  <!-- 4. MOTION & TARGET INDICATORS -->\n  <!-- ============================================================== -->\n  <!-- Number 6 Loop Target Crosshair & Circle -->\n  <circle cx=\"185\" cy=\"185\" r=\"22\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"1.5\" stroke-dasharray=\"3 3\"/>\n  <circle cx=\"185\" cy=\"185\" r=\"3\" fill=\"#38bdf8\"/>\n  <path d=\"M 185 155 L 185 165 M 185 205 L 185 215 M 155 185 L 165 185 M 205 185 L 215 185\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n\n  <!-- Dynamic Loop Twist Arrow (시계 방향 꼬임 가이드) -->\n  <path d=\"M 230 165 C 245 190 230 220 195 220 C 170 220 155 200 165 175\" \n        fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-dasharray=\"4 2\"/>\n  <polygon points=\"163,168 174,175 166,183\" fill=\"#f59e0b\"/>\n\n  <!-- ============================================================== -->\n  <!-- 5. CALLOUT LABELS (9대 선언적 바인딩 라벨) -->\n  <!-- ============================================================== -->\n  <!-- Label 2 & 3: Standing Part (Top Left) -->\n  <line x1=\"192\" y1=\"75\" x2=\"90\" y2=\"75\" stroke=\"#9ca3af\" stroke-width=\"1\"/>\n  <circle cx=\"192\" cy=\"75\" r=\"2.5\" fill=\"#f59e0b\"/>\n  <text x=\"24\" y=\"70\" fill=\"#fef3c7\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">STANDING PART</text>\n  <text x=\"24\" y=\"83\" fill=\"#9ca3af\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">원줄 (서 있는 나무)</text>\n\n  <!-- Label 4 & 5: Rabbit Hole (Center Left) -->\n  <line x1=\"163\" y1=\"185\" x2=\"80\" y2=\"185\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <circle cx=\"163\" cy=\"185\" r=\"2.5\" fill=\"#38bdf8\"/>\n  <text x=\"24\" y=\"175\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">RABBIT HOLE (고리)</text>\n  <text x=\"24\" y=\"188\" fill=\"#bae6fd\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">숫자 6 모양의 토끼굴</text>\n\n  <!-- Label 6 & 7: Working End (Bottom Left) -->\n  <line x1=\"105\" y1=\"270\" x2=\"50\" y2=\"270\" stroke=\"#22c55e\" stroke-width=\"1\"/>\n  <circle cx=\"105\" cy=\"270\" r=\"2.5\" fill=\"#22c55e\"/>\n  <text x=\"24\" y=\"260\" fill=\"#86efac\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">WORKING END (토끼)</text>\n  <text x=\"24\" y=\"273\" fill=\"#4ade80\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">작동 끝단이 원줄 '위'로 교차</text>\n\n  <!-- Bottom Tactical Field Note Strip -->\n  <rect x=\"18\" y=\"342\" width=\"364\" height=\"40\" fill=\"#111419\" stroke=\"#262d35\" stroke-width=\"1\"/>\n  <rect x=\"18\" y=\"342\" width=\"4\" height=\"40\" fill=\"#22c55e\"/>\n  <!-- Label 8 & 9: Summary Instruction -->\n  <text x=\"32\" y=\"357\" fill=\"#ffffff\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\" font-weight=\"bold\">[1단계 핵심] 원줄 위에 작동 줄을 얹어 6자 루프 형성</text>\n  <text x=\"32\" y=\"371\" fill=\"#9ca3af\" font-family=\"'Chivo', sans-serif\" font-size=\"8.5\">작동 줄이 반드시 원줄의 위쪽에 위치해야 잠금 구조가 완성됩니다.</text>\n</svg>","content/svgs/pr07-step-02.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgGrad02\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#08090b\"/>\n      <stop offset=\"50%\" stop-color=\"#0f1216\"/>\n      <stop offset=\"100%\" stop-color=\"#0a0c0e\"/>\n    </linearGradient>\n\n    <!-- Manila Standing Rope 3D Tubular Gradient -->\n    <linearGradient id=\"ropeManila02\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#78350f\"/>\n      <stop offset=\"25%\" stop-color=\"#b45309\"/>\n      <stop offset=\"50%\" stop-color=\"#fef3c7\"/>\n      <stop offset=\"75%\" stop-color=\"#d97706\"/>\n      <stop offset=\"100%\" stop-color=\"#451a03\"/>\n    </linearGradient>\n\n    <!-- Tactical Green Working Rope 3D Gradient -->\n    <linearGradient id=\"ropeGreen02\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#14532d\"/>\n      <stop offset=\"25%\" stop-color=\"#16a34a\"/>\n      <stop offset=\"50%\" stop-color=\"#bbf7d0\"/>\n      <stop offset=\"75%\" stop-color=\"#22c55e\"/>\n      <stop offset=\"100%\" stop-color=\"#052e16\"/>\n    </linearGradient>\n\n    <!-- Deep Drop Shadow Filter for Over/Under Crossing -->\n    <filter id=\"shadowDeep02\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"5\" stdDeviation=\"4.5\" flood-color=\"#000000\" flood-opacity=\"0.95\"/>\n    </filter>\n\n    <!-- Twisted Rope Braid Pattern for Manila Rope -->\n    <pattern id=\"braidManila02\" width=\"12\" height=\"12\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(45)\">\n      <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"12\" stroke=\"#451a03\" stroke-width=\"2.5\" opacity=\"0.6\"/>\n      <line x1=\"6\" y1=\"0\" x2=\"6\" y2=\"12\" stroke=\"#fef3c7\" stroke-width=\"1.5\" opacity=\"0.4\"/>\n    </pattern>\n\n    <!-- Paracord Texture Pattern for Working End -->\n    <pattern id=\"braidGreen02\" width=\"8\" height=\"8\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(-45)\">\n      <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"8\" stroke=\"#052e16\" stroke-width=\"2\" opacity=\"0.7\"/>\n      <line x1=\"4\" y1=\"0\" x2=\"4\" y2=\"8\" stroke=\"#bbf7d0\" stroke-width=\"1.2\" opacity=\"0.5\"/>\n    </pattern>\n  </defs>\n\n  <!-- Canvas Backdrop -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgGrad02)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#22262c\" stroke-width=\"1\"/>\n\n  <!-- Technical Corner Crosshairs -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n\n  <!-- Blueprint Header -->\n  <text x=\"24\" y=\"28\" fill=\"#9ca3af\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">FIG. 02 // BOWLINE STEP 2: 토끼굴 상향 탈출</text>\n  <line x1=\"24\" y1=\"36\" x2=\"376\" y2=\"36\" stroke=\"#262d35\" stroke-width=\"1\"/>\n\n  <!-- Background Reference Grid -->\n  <g opacity=\"0.12\" stroke=\"#4b5563\" stroke-width=\"0.5\" stroke-dasharray=\"2 4\">\n    <line x1=\"60\" y1=\"40\" x2=\"60\" y2=\"340\"/>\n    <line x1=\"200\" y1=\"40\" x2=\"200\" y2=\"340\"/>\n    <line x1=\"340\" y1=\"40\" x2=\"340\" y2=\"340\"/>\n    <line x1=\"20\" y1=\"120\" x2=\"380\" y2=\"120\"/>\n    <line x1=\"20\" y1=\"200\" x2=\"380\" y2=\"200\"/>\n    <line x1=\"20\" y1=\"280\" x2=\"380\" y2=\"280\"/>\n  </g>\n\n  <!-- ============================================================== -->\n  <!-- 1. STANDING PART (원줄) & NUMBER 6 THROAT LOOP -->\n  <!-- ============================================================== -->\n  <!-- Top Vertical Standing Line -->\n  <path d=\"M 200 42 L 200 115\" stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\"/>\n  <path d=\"M 200 42 L 200 115\" stroke=\"url(#ropeManila02)\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n  <path d=\"M 200 42 L 200 115\" stroke=\"url(#braidManila02)\" stroke-width=\"12\" stroke-linecap=\"round\" opacity=\"0.75\"/>\n\n  <!-- Throat Loop Back Arc (The 6-loop back) -->\n  <path d=\"M 200 115 C 135 130 130 215 190 225 C 240 230 260 190 235 155 C 215 130 185 122 150 140\" \n        stroke=\"#000000\" stroke-width=\"20\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 200 115 C 135 130 130 215 190 225 C 240 230 260 190 235 155 C 215 130 185 122 150 140\" \n        stroke=\"url(#ropeManila02)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 200 115 C 135 130 130 215 190 225 C 240 230 260 190 235 155 C 215 130 185 122 150 140\" \n        stroke=\"url(#braidManila02)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.75\"/>\n\n  <!-- ============================================================== -->\n  <!-- 2. MAIN EYE LOOP (최종 큰 고리가 될 밧줄 하단 루프) -->\n  <!-- ============================================================== -->\n  <!-- Standing rope going down, making the giant eye loop, and coming back up -->\n  <path d=\"M 190 225 C 190 280 150 325 110 325 C 70 325 45 270 55 210 C 65 160 110 130 150 140\" \n        stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 190 225 C 190 280 150 325 110 325 C 70 325 45 270 55 210 C 65 160 110 130 150 140\" \n        stroke=\"url(#ropeManila02)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 190 225 C 190 280 150 325 110 325 C 70 325 45 270 55 210 C 65 160 110 130 150 140\" \n        stroke=\"url(#braidManila02)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.75\"/>\n\n  <!-- ============================================================== -->\n  <!-- 3. WORKING END (토끼 줄) - 굴 아래에서 위로 솟구쳐 나오는 상향 관통! -->\n  <!-- ============================================================== -->\n  <!-- First part: Entering underneath the throat hole -->\n  <path d=\"M 150 140 C 160 150 175 165 185 178\" \n        stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.6\"/>\n        \n  <!-- Emerging Upward through Rabbit Hole with Deep 3D Shadow -->\n  <g filter=\"url(#shadowDeep02)\">\n    <!-- Emerging green tail shooting upward -->\n    <path d=\"M 185 185 C 195 160 215 110 225 75\" \n          stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\" fill=\"none\"/>\n    <path d=\"M 185 185 C 195 160 215 110 225 75\" \n          stroke=\"url(#ropeGreen02)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n    <path d=\"M 185 185 C 195 160 215 110 225 75\" \n          stroke=\"url(#braidGreen02)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.85\"/>\n  </g>\n\n  <!-- Heat-sealed Red End Cap on Working Tip -->\n  <line x1=\"220\" y1=\"75\" x2=\"230\" y2=\"75\" stroke=\"#ef4444\" stroke-width=\"4\" stroke-linecap=\"square\"/>\n\n  <!-- ============================================================== -->\n  <!-- 4. 3D DIRECTIONAL & COGNITIVE CUES (땅속에서 위로 솟구침) -->\n  <!-- ============================================================== -->\n  <!-- The 3D Throat Hole Opening Indicator (Portal ellipse) -->\n  <ellipse cx=\"185\" cy=\"180\" rx=\"20\" ry=\"14\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"1.8\" stroke-dasharray=\"3 2\"/>\n  \n  <!-- Giant Upward 3D Vector Arrow (솟구치는 탈출 궤적) -->\n  <path d=\"M 185 200 C 190 175 200 140 210 100\" fill=\"none\" stroke=\"#ef4444\" stroke-width=\"2.5\" stroke-linecap=\"round\"/>\n  <polygon points=\"214,92 203,103 218,107\" fill=\"#ef4444\"/>\n\n\n\n  <!-- 15cm Dimension Bracket for Rabbit Head Slack -->\n  <path d=\"M 235 75 L 245 75 L 245 155 L 235 155\" fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"1\"/>\n  <line x1=\"245\" y1=\"115\" x2=\"255\" y2=\"115\" stroke=\"#f59e0b\" stroke-width=\"1\"/>\n\n  <!-- ============================================================== -->\n  <!-- 5. CALLOUT LABELS (9대 선언적 바인딩 라벨) -->\n  <!-- ============================================================== -->\n  <!-- Label 2 & 3: Emerge from hole (Top Center/Right) -->\n  <line x1=\"220\" y1=\"85\" x2=\"270\" y2=\"85\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <circle cx=\"220\" cy=\"85\" r=\"2.5\" fill=\"#38bdf8\"/>\n  <text x=\"280\" y=\"80\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">EMERGE FROM HOLE</text>\n  <text x=\"280\" y=\"93\" fill=\"#bae6fd\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">굴 아래에서 위로 탈출</text>\n\n  <!-- Label 4 & 5: Rabbit Head 15cm Slack (Right Center) -->\n  <text x=\"260\" y=\"152\" fill=\"#fef3c7\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">토끼 머리 15cm</text>\n  <text x=\"260\" y=\"165\" fill=\"#fde68a\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">충분한 길이 인출</text>\n\n  <!-- Label 6 & 7: Main Eye Loop (Bottom Left) -->\n  <line x1=\"60\" y1=\"280\" x2=\"30\" y2=\"280\" stroke=\"#f59e0b\" stroke-width=\"1\"/>\n  <circle cx=\"60\" cy=\"280\" r=\"2.5\" fill=\"#f59e0b\"/>\n  <text x=\"24\" y=\"268\" fill=\"#ffffff\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">MAIN EYE LOOP</text>\n  <text x=\"24\" y=\"281\" fill=\"#9ca3af\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">최종 하중을 받을 큰 고리</text>\n\n  <!-- Bottom Tactical Field Note Strip -->\n  <rect x=\"18\" y=\"342\" width=\"364\" height=\"40\" fill=\"#111419\" stroke=\"#262d35\" stroke-width=\"1\"/>\n  <rect x=\"18\" y=\"342\" width=\"4\" height=\"40\" fill=\"#38bdf8\"/>\n  <!-- Label 8 & 9: Summary Instruction -->\n  <text x=\"32\" y=\"357\" fill=\"#ffffff\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\" font-weight=\"bold\">[2단계 핵심] 굴 밑바닥에서 위쪽으로 토끼를 쑥 뽑아 올림</text>\n  <text x=\"32\" y=\"371\" fill=\"#9ca3af\" font-family=\"'Chivo', sans-serif\" font-size=\"8.5\">위에서 아래로 찌르면 매듭이 풀리는 올가미가 되므로 절대 주의하십시오.</text>\n</svg>","content/svgs/pr07-step-03.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgGrad03\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#08090b\"/>\n      <stop offset=\"50%\" stop-color=\"#0f1216\"/>\n      <stop offset=\"100%\" stop-color=\"#0a0c0e\"/>\n    </linearGradient>\n\n    <!-- Manila Standing Rope 3D Tubular Gradient -->\n    <linearGradient id=\"ropeManila03\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#78350f\"/>\n      <stop offset=\"25%\" stop-color=\"#b45309\"/>\n      <stop offset=\"50%\" stop-color=\"#fef3c7\"/>\n      <stop offset=\"75%\" stop-color=\"#d97706\"/>\n      <stop offset=\"100%\" stop-color=\"#451a03\"/>\n    </linearGradient>\n\n    <!-- Tactical Green Working Rope 3D Gradient -->\n    <linearGradient id=\"ropeGreen03\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#14532d\"/>\n      <stop offset=\"25%\" stop-color=\"#16a34a\"/>\n      <stop offset=\"50%\" stop-color=\"#bbf7d0\"/>\n      <stop offset=\"75%\" stop-color=\"#22c55e\"/>\n      <stop offset=\"100%\" stop-color=\"#052e16\"/>\n    </linearGradient>\n\n    <!-- Deep Drop Shadow Filter for Over/Under Crossing -->\n    <filter id=\"shadowDeep03\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"5\" stdDeviation=\"5\" flood-color=\"#000000\" flood-opacity=\"0.95\"/>\n    </filter>\n\n    <!-- Twisted Rope Braid Pattern for Manila Rope -->\n    <pattern id=\"braidManila03\" width=\"12\" height=\"12\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(45)\">\n      <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"12\" stroke=\"#451a03\" stroke-width=\"2.5\" opacity=\"0.6\"/>\n      <line x1=\"6\" y1=\"0\" x2=\"6\" y2=\"12\" stroke=\"#fef3c7\" stroke-width=\"1.5\" opacity=\"0.4\"/>\n    </pattern>\n\n    <!-- Paracord Texture Pattern for Working End -->\n    <pattern id=\"braidGreen03\" width=\"8\" height=\"8\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(-45)\">\n      <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"8\" stroke=\"#052e16\" stroke-width=\"2\" opacity=\"0.7\"/>\n      <line x1=\"4\" y1=\"0\" x2=\"4\" y2=\"8\" stroke=\"#bbf7d0\" stroke-width=\"1.2\" opacity=\"0.5\"/>\n    </pattern>\n  </defs>\n\n  <!-- Canvas Backdrop -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgGrad03)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#22262c\" stroke-width=\"1\"/>\n\n  <!-- Technical Corner Crosshairs -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n\n  <!-- Blueprint Header -->\n  <text x=\"24\" y=\"28\" fill=\"#9ca3af\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">FIG. 03 // BOWLINE STEP 3: 나무(원줄) 뒤편 선회</text>\n  <line x1=\"24\" y1=\"36\" x2=\"376\" y2=\"36\" stroke=\"#262d35\" stroke-width=\"1\"/>\n\n  <!-- Background Reference Grid -->\n  <g opacity=\"0.12\" stroke=\"#4b5563\" stroke-width=\"0.5\" stroke-dasharray=\"2 4\">\n    <line x1=\"60\" y1=\"40\" x2=\"60\" y2=\"340\"/>\n    <line x1=\"200\" y1=\"40\" x2=\"200\" y2=\"340\"/>\n    <line x1=\"340\" y1=\"40\" x2=\"340\" y2=\"340\"/>\n    <line x1=\"20\" y1=\"120\" x2=\"380\" y2=\"120\"/>\n    <line x1=\"20\" y1=\"200\" x2=\"380\" y2=\"200\"/>\n    <line x1=\"20\" y1=\"280\" x2=\"380\" y2=\"280\"/>\n  </g>\n\n  <!-- ============================================================== -->\n  <!-- 1. WORKING END (토끼 줄) BEHIND THE TREE (원줄 뒤편으로 감는 구간) -->\n  <!-- Drawn FIRST so the tree sits in FRONT of it! -->\n  <!-- ============================================================== -->\n  <!-- Loop emerging from throat hole and curving behind the tree to the left -->\n  <g opacity=\"0.95\">\n    <!-- Path behind the standing part -->\n    <path d=\"M 215 155 C 235 120 235 75 195 72 C 160 70 145 95 150 135\" \n          stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\" fill=\"none\"/>\n    <path d=\"M 215 155 C 235 120 235 75 195 72 C 160 70 145 95 150 135\" \n          stroke=\"url(#ropeGreen03)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n    <path d=\"M 215 155 C 235 120 235 75 195 72 C 160 70 145 95 150 135\" \n          stroke=\"url(#braidGreen03)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.8\"/>\n  </g>\n\n  <!-- ============================================================== -->\n  <!-- 2. STANDING PART (나무 / 원줄) SITTING IN FRONT WITH HEAVY SHADOW -->\n  <!-- ============================================================== -->\n  <g filter=\"url(#shadowDeep03)\">\n    <!-- Standing Rope Main Vertical Trunk -->\n    <path d=\"M 195 42 L 195 120\" stroke=\"#000000\" stroke-width=\"20\" stroke-linecap=\"round\"/>\n    <path d=\"M 195 42 L 195 120\" stroke=\"url(#ropeManila03)\" stroke-width=\"14\" stroke-linecap=\"round\"/>\n    <path d=\"M 195 42 L 195 120\" stroke=\"url(#braidManila03)\" stroke-width=\"14\" stroke-linecap=\"round\" opacity=\"0.75\"/>\n  </g>\n\n  <!-- Throat Loop (토끼굴 루프 - 6자 루프 구조) -->\n  <path d=\"M 195 120 C 130 135 125 215 185 225 C 235 230 255 190 230 155 C 210 130 180 122 145 140\" \n        stroke=\"#000000\" stroke-width=\"20\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 195 120 C 130 135 125 215 185 225 C 235 230 255 190 230 155 C 210 130 180 122 145 140\" \n        stroke=\"url(#ropeManila03)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 195 120 C 130 135 125 215 185 225 C 235 230 255 190 230 155 C 210 130 180 122 145 140\" \n        stroke=\"url(#braidManila03)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.75\"/>\n\n  <!-- Lower Main Eye Loop -->\n  <path d=\"M 185 225 C 185 280 145 325 105 325 C 65 325 40 270 50 210 C 60 160 105 130 145 140\" \n        stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 185 225 C 185 280 145 325 105 325 C 65 325 40 270 50 210 C 60 160 105 130 145 140\" \n        stroke=\"url(#ropeManila03)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 185 225 C 185 280 145 325 105 325 C 65 325 40 270 50 210 C 60 160 105 130 145 140\" \n        stroke=\"url(#braidManila03)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.75\"/>\n\n  <!-- ============================================================== -->\n  <!-- 3. WORKING END FRONT POINTER (굴로 다시 들어갈 준비) -->\n  <!-- ============================================================== -->\n  <!-- Green Tail emerging on the left, curving downward aiming into the hole -->\n  <g filter=\"url(#shadowDeep03)\">\n    <path d=\"M 150 135 C 152 148 165 160 175 168\" \n          stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\" fill=\"none\"/>\n    <path d=\"M 150 135 C 152 148 165 160 175 168\" \n          stroke=\"url(#ropeGreen03)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n    <path d=\"M 150 135 C 152 148 165 160 175 168\" \n          stroke=\"url(#braidGreen03)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.85\"/>\n  </g>\n\n  <!-- Heat-sealed Red End Cap on Working Tip -->\n  <line x1=\"172\" y1=\"165\" x2=\"178\" y2=\"171\" stroke=\"#ef4444\" stroke-width=\"4\" stroke-linecap=\"square\"/>\n\n  <!-- ============================================================== -->\n  <!-- 4. MOTION & COGNITIVE BEHIND-THE-TREE CUES -->\n  <!-- ============================================================== -->\n  <!-- Behind-the-Tree Orbit Motion Arrow (시계 반대 방향 회전 궤적) -->\n  <path d=\"M 235 100 C 235 60 165 55 145 95 C 135 115 140 145 160 160\" \n        fill=\"none\" stroke=\"#ef4444\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-dasharray=\"4 2\"/>\n  <polygon points=\"163,165 152,159 160,150\" fill=\"#ef4444\"/>\n\n\n\n  <!-- Re-entry Target Loupe Circle around throat hole -->\n  <circle cx=\"180\" cy=\"180\" r=\"18\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n\n  <!-- ============================================================== -->\n  <!-- 5. CALLOUT LABELS (9대 선언적 바인딩 라벨) -->\n  <!-- ============================================================== -->\n  <!-- Label 2 & 3: Around the tree (Top Right) -->\n  <line x1=\"225\" y1=\"95\" x2=\"265\" y2=\"95\" stroke=\"#f59e0b\" stroke-width=\"1\"/>\n  <circle cx=\"225\" cy=\"95\" r=\"2.5\" fill=\"#f59e0b\"/>\n  <text x=\"275\" y=\"92\" fill=\"#fde68a\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">AROUND THE TREE</text>\n  <text x=\"275\" y=\"105\" fill=\"#fef3c7\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">원줄 '뒤쪽'을 감아 돔</text>\n\n  <!-- Label 4 & 5: Tree Trunk Axis (Top Left) -->\n  <line x1=\"190\" y1=\"70\" x2=\"80\" y2=\"70\" stroke=\"#9ca3af\" stroke-width=\"1\"/>\n  <circle cx=\"190\" cy=\"70\" r=\"2.5\" fill=\"#f59e0b\"/>\n  <text x=\"24\" y=\"65\" fill=\"#ffffff\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">TREE (나무 기둥줄)</text>\n  <text x=\"24\" y=\"78\" fill=\"#9ca3af\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">토끼가 돌아 나갈 중심 축</text>\n\n  <!-- Label 6 & 7: Re-entry Ready (Center Left) -->\n  <line x1=\"165\" y1=\"165\" x2=\"80\" y2=\"165\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <circle cx=\"165\" cy=\"165\" r=\"2.5\" fill=\"#38bdf8\"/>\n  <text x=\"24\" y=\"158\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">RE-ENTRY READY</text>\n  <text x=\"24\" y=\"171\" fill=\"#bae6fd\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">다시 굴로 진입할 준비</text>\n\n  <!-- Bottom Tactical Field Note Strip -->\n  <rect x=\"18\" y=\"342\" width=\"364\" height=\"40\" fill=\"#111419\" stroke=\"#262d35\" stroke-width=\"1\"/>\n  <rect x=\"18\" y=\"342\" width=\"4\" height=\"40\" fill=\"#f59e0b\"/>\n  <!-- Label 8 & 9: Summary Instruction -->\n  <text x=\"32\" y=\"357\" fill=\"#ffffff\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\" font-weight=\"bold\">[3단계 핵심] 굴에서 나온 토끼가 원줄 뒤편을 감싸 돎</text>\n  <text x=\"32\" y=\"371\" fill=\"#9ca3af\" font-family=\"'Chivo', sans-serif\" font-size=\"8.5\">반드시 원줄의 '뒤'로 돌아야 단단히 조여지는 칼라(Collar) 루프가 만들어집니다.</text>\n</svg>","content/svgs/pr07-step-04.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgGrad04\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#08090b\"/>\n      <stop offset=\"50%\" stop-color=\"#0f1216\"/>\n      <stop offset=\"100%\" stop-color=\"#0a0c0e\"/>\n    </linearGradient>\n\n    <!-- Manila Standing Rope 3D Tubular Gradient -->\n    <linearGradient id=\"ropeManila04\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#78350f\"/>\n      <stop offset=\"25%\" stop-color=\"#b45309\"/>\n      <stop offset=\"50%\" stop-color=\"#fef3c7\"/>\n      <stop offset=\"75%\" stop-color=\"#d97706\"/>\n      <stop offset=\"100%\" stop-color=\"#451a03\"/>\n    </linearGradient>\n\n    <!-- Tactical Green Working Rope 3D Gradient -->\n    <linearGradient id=\"ropeGreen04\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#14532d\"/>\n      <stop offset=\"25%\" stop-color=\"#16a34a\"/>\n      <stop offset=\"50%\" stop-color=\"#bbf7d0\"/>\n      <stop offset=\"75%\" stop-color=\"#22c55e\"/>\n      <stop offset=\"100%\" stop-color=\"#052e16\"/>\n    </linearGradient>\n\n    <!-- Deep Drop Shadow Filter for Over/Under Crossing -->\n    <filter id=\"shadowDeep04\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"5\" stdDeviation=\"5\" flood-color=\"#000000\" flood-opacity=\"0.95\"/>\n    </filter>\n\n    <!-- Twisted Rope Braid Pattern for Manila Rope -->\n    <pattern id=\"braidManila04\" width=\"12\" height=\"12\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(45)\">\n      <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"12\" stroke=\"#451a03\" stroke-width=\"2.5\" opacity=\"0.6\"/>\n      <line x1=\"6\" y1=\"0\" x2=\"6\" y2=\"12\" stroke=\"#fef3c7\" stroke-width=\"1.5\" opacity=\"0.4\"/>\n    </pattern>\n\n    <!-- Paracord Texture Pattern for Working End -->\n    <pattern id=\"braidGreen04\" width=\"8\" height=\"8\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(-45)\">\n      <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"8\" stroke=\"#052e16\" stroke-width=\"2\" opacity=\"0.7\"/>\n      <line x1=\"4\" y1=\"0\" x2=\"4\" y2=\"8\" stroke=\"#bbf7d0\" stroke-width=\"1.2\" opacity=\"0.5\"/>\n    </pattern>\n  </defs>\n\n  <!-- Canvas Backdrop -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgGrad04)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#22262c\" stroke-width=\"1\"/>\n\n  <!-- Technical Corner Crosshairs -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n\n  <!-- Blueprint Header -->\n  <text x=\"24\" y=\"28\" fill=\"#9ca3af\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">FIG. 04 // BOWLINE STEP 4: 토끼굴 재진입</text>\n  <line x1=\"24\" y1=\"36\" x2=\"376\" y2=\"36\" stroke=\"#262d35\" stroke-width=\"1\"/>\n\n  <!-- Background Reference Grid -->\n  <g opacity=\"0.12\" stroke=\"#4b5563\" stroke-width=\"0.5\" stroke-dasharray=\"2 4\">\n    <line x1=\"60\" y1=\"40\" x2=\"60\" y2=\"340\"/>\n    <line x1=\"200\" y1=\"40\" x2=\"200\" y2=\"340\"/>\n    <line x1=\"340\" y1=\"40\" x2=\"340\" y2=\"340\"/>\n    <line x1=\"20\" y1=\"120\" x2=\"380\" y2=\"120\"/>\n    <line x1=\"20\" y1=\"200\" x2=\"380\" y2=\"200\"/>\n    <line x1=\"20\" y1=\"280\" x2=\"380\" y2=\"280\"/>\n  </g>\n\n  <!-- ============================================================== -->\n  <!-- 1. COLLAR LOOP BEHIND (원줄 뒤편을 통과해 나오는 U자 칼라) -->\n  <!-- ============================================================== -->\n  <path d=\"M 215 145 C 240 115 240 68 195 68 C 155 68 140 100 152 145\" \n        stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 215 145 C 240 115 240 68 195 68 C 155 68 140 100 152 145\" \n        stroke=\"url(#ropeGreen04)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 215 145 C 240 115 240 68 195 68 C 155 68 140 100 152 145\" \n        stroke=\"url(#braidGreen04)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.8\"/>\n\n  <!-- ============================================================== -->\n  <!-- 2. STANDING PART (원줄 / 나무) SITTING IN FRONT -->\n  <!-- ============================================================== -->\n  <g filter=\"url(#shadowDeep04)\">\n    <!-- Standing Rope Main Vertical Trunk -->\n    <path d=\"M 195 42 L 195 120\" stroke=\"#000000\" stroke-width=\"20\" stroke-linecap=\"round\"/>\n    <path d=\"M 195 42 L 195 120\" stroke=\"url(#ropeManila04)\" stroke-width=\"14\" stroke-linecap=\"round\"/>\n    <path d=\"M 195 42 L 195 120\" stroke=\"url(#braidManila04)\" stroke-width=\"14\" stroke-linecap=\"round\" opacity=\"0.75\"/>\n  </g>\n\n  <!-- Throat Loop (토끼굴 루프 - 6자 루프 구조) -->\n  <path d=\"M 195 120 C 130 135 125 215 185 225 C 235 230 255 190 230 155 C 210 130 180 122 145 140\" \n        stroke=\"#000000\" stroke-width=\"20\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 195 120 C 130 135 125 215 185 225 C 235 230 255 190 230 155 C 210 130 180 122 145 140\" \n        stroke=\"url(#ropeManila04)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 195 120 C 130 135 125 215 185 225 C 235 230 255 190 230 155 C 210 130 180 122 145 140\" \n        stroke=\"url(#braidManila04)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.75\"/>\n\n  <!-- Lower Main Eye Loop -->\n  <path d=\"M 185 225 C 185 280 145 325 105 325 C 65 325 40 270 50 210 C 60 160 105 130 145 140\" \n        stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 185 225 C 185 280 145 325 105 325 C 65 325 40 270 50 210 C 60 160 105 130 145 140\" \n        stroke=\"url(#ropeManila04)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 185 225 C 185 280 145 325 105 325 C 65 325 40 270 50 210 C 60 160 105 130 145 140\" \n        stroke=\"url(#braidManila04)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.75\"/>\n\n  <!-- ============================================================== -->\n  <!-- 3. PARALLEL GREEN STRANDS (굴 속으로 재진입하여 나란히 정렬) -->\n  <!-- ============================================================== -->\n  <g filter=\"url(#shadowDeep04)\">\n    <!-- Strand 1: Coming UP out of hole (From step 2) -->\n    <path d=\"M 172 205 L 172 150\" stroke=\"#000000\" stroke-width=\"16\" stroke-linecap=\"round\"/>\n    <path d=\"M 172 205 L 172 150\" stroke=\"url(#ropeGreen04)\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n    <path d=\"M 172 205 L 172 150\" stroke=\"url(#braidGreen04)\" stroke-width=\"10\" stroke-linecap=\"round\" opacity=\"0.8\"/>\n\n    <!-- Strand 2: Diving DOWN back into hole (From step 4) -->\n    <path d=\"M 186 145 L 186 215\" stroke=\"#000000\" stroke-width=\"16\" stroke-linecap=\"round\"/>\n    <path d=\"M 186 145 L 186 215\" stroke=\"url(#ropeGreen04)\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n    <path d=\"M 186 145 L 186 215\" stroke=\"url(#braidGreen04)\" stroke-width=\"10\" stroke-linecap=\"round\" opacity=\"0.8\"/>\n  </g>\n\n  <!-- Heat-sealed Red End Cap on Working Tip pointing down -->\n  <line x1=\"181\" y1=\"215\" x2=\"191\" y2=\"215\" stroke=\"#ef4444\" stroke-width=\"4\" stroke-linecap=\"square\"/>\n\n  <!-- Downward Re-entry Motion Arrow -->\n  <path d=\"M 186 130 L 186 165\" stroke=\"#ef4444\" stroke-width=\"2.5\" stroke-linecap=\"round\" fill=\"none\"/>\n  <polygon points=\"186,172 181,162 191,162\" fill=\"#ef4444\"/>\n\n  <!-- Parallel Alignment Bracket -->\n  <path d=\"M 164 165 L 160 165 L 160 195 L 164 195\" fill=\"none\" stroke=\"#22c55e\" stroke-width=\"1.2\"/>\n  <path d=\"M 194 165 L 198 165 L 198 195 L 194 195\" fill=\"none\" stroke=\"#22c55e\" stroke-width=\"1.2\"/>\n\n  <!-- ============================================================== -->\n  <!-- 4. CALLOUT LABELS (9대 선언적 바인딩 라벨) -->\n  <!-- ============================================================== -->\n  <!-- Label 2 & 3: Back Into Hole (Top Left) -->\n  <line x1=\"180\" y1=\"135\" x2=\"90\" y2=\"135\" stroke=\"#ef4444\" stroke-width=\"1\"/>\n  <circle cx=\"180\" cy=\"135\" r=\"2.5\" fill=\"#ef4444\"/>\n  <text x=\"24\" y=\"125\" fill=\"#f87171\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">BACK INTO HOLE</text>\n  <text x=\"24\" y=\"138\" fill=\"#fca5a5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">위에서 아래로 재진입</text>\n\n  <!-- Label 4 & 5: Parallel Strands (Center Right) -->\n  <line x1=\"198\" y1=\"180\" x2=\"265\" y2=\"180\" stroke=\"#22c55e\" stroke-width=\"1\"/>\n  <circle cx=\"198\" cy=\"180\" r=\"2.5\" fill=\"#22c55e\"/>\n  <text x=\"275\" y=\"175\" fill=\"#86efac\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">PARALLEL STRANDS</text>\n  <text x=\"275\" y=\"188\" fill=\"#4ade80\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">두 가닥이 나란히 정렬</text>\n\n  <!-- Label 6 & 7: Collar Loop (Top Right) -->\n  <line x1=\"225\" y1=\"80\" x2=\"265\" y2=\"80\" stroke=\"#f59e0b\" stroke-width=\"1\"/>\n  <circle cx=\"225\" cy=\"80\" r=\"2.5\" fill=\"#f59e0b\"/>\n  <text x=\"275\" y=\"75\" fill=\"#fde68a\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">COLLAR LOOP</text>\n  <text x=\"275\" y=\"88\" fill=\"#fef3c7\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">나무를 감싼 뒤통수 고리</text>\n\n  <!-- Bottom Tactical Field Note Strip -->\n  <rect x=\"18\" y=\"342\" width=\"364\" height=\"40\" fill=\"#111419\" stroke=\"#262d35\" stroke-width=\"1\"/>\n  <rect x=\"18\" y=\"342\" width=\"4\" height=\"40\" fill=\"#22c55e\"/>\n  <!-- Label 8 & 9: Summary Instruction -->\n  <text x=\"32\" y=\"357\" fill=\"#ffffff\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\" font-weight=\"bold\">[4단계 핵심] 토끼가 굴 속으로 다시 쏙 들어감</text>\n  <text x=\"32\" y=\"371\" fill=\"#9ca3af\" font-family=\"'Chivo', sans-serif\" font-size=\"8.5\">나무를 돌아 나온 끝단을 처음 나왔던 토끼굴에 위에서 아래로 찔러 넣습니다.</text>\n</svg>","content/svgs/pr07-step-05.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgGrad05\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#08090b\"/>\n      <stop offset=\"50%\" stop-color=\"#0f1216\"/>\n      <stop offset=\"100%\" stop-color=\"#0a0c0e\"/>\n    </linearGradient>\n\n    <!-- Manila Standing Rope 3D Tubular Gradient -->\n    <linearGradient id=\"ropeManila05\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#78350f\"/>\n      <stop offset=\"25%\" stop-color=\"#b45309\"/>\n      <stop offset=\"50%\" stop-color=\"#fef3c7\"/>\n      <stop offset=\"75%\" stop-color=\"#d97706\"/>\n      <stop offset=\"100%\" stop-color=\"#451a03\"/>\n    </linearGradient>\n\n    <!-- Tactical Green Working Rope 3D Gradient -->\n    <linearGradient id=\"ropeGreen05\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#14532d\"/>\n      <stop offset=\"25%\" stop-color=\"#16a34a\"/>\n      <stop offset=\"50%\" stop-color=\"#bbf7d0\"/>\n      <stop offset=\"75%\" stop-color=\"#22c55e\"/>\n      <stop offset=\"100%\" stop-color=\"#052e16\"/>\n    </linearGradient>\n\n    <!-- Deep Drop Shadow Filter for Over/Under Crossing -->\n    <filter id=\"shadowDeep05\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"5\" stdDeviation=\"5\" flood-color=\"#000000\" flood-opacity=\"0.95\"/>\n    </filter>\n\n    <!-- Twisted Rope Braid Pattern for Manila Rope -->\n    <pattern id=\"braidManila05\" width=\"12\" height=\"12\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(45)\">\n      <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"12\" stroke=\"#451a03\" stroke-width=\"2.5\" opacity=\"0.6\"/>\n      <line x1=\"6\" y1=\"0\" x2=\"6\" y2=\"12\" stroke=\"#fef3c7\" stroke-width=\"1.5\" opacity=\"0.4\"/>\n    </pattern>\n\n    <!-- Paracord Texture Pattern for Working End -->\n    <pattern id=\"braidGreen05\" width=\"8\" height=\"8\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(-45)\">\n      <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"8\" stroke=\"#052e16\" stroke-width=\"2\" opacity=\"0.7\"/>\n      <line x1=\"4\" y1=\"0\" x2=\"4\" y2=\"8\" stroke=\"#bbf7d0\" stroke-width=\"1.2\" opacity=\"0.5\"/>\n    </pattern>\n  </defs>\n\n  <!-- Canvas Backdrop -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgGrad05)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#22262c\" stroke-width=\"1\"/>\n\n  <!-- Technical Corner Crosshairs -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#374151\" stroke-width=\"1\"/>\n\n  <!-- Blueprint Header -->\n  <text x=\"24\" y=\"28\" fill=\"#9ca3af\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">FIG. 05 // BOWLINE STEP 5: 락킹 및 1초 해체</text>\n  <line x1=\"24\" y1=\"36\" x2=\"376\" y2=\"36\" stroke=\"#262d35\" stroke-width=\"1\"/>\n\n  <!-- Background Reference Grid -->\n  <g opacity=\"0.12\" stroke=\"#4b5563\" stroke-width=\"0.5\" stroke-dasharray=\"2 4\">\n    <line x1=\"60\" y1=\"40\" x2=\"60\" y2=\"340\"/>\n    <line x1=\"200\" y1=\"40\" x2=\"200\" y2=\"340\"/>\n    <line x1=\"340\" y1=\"40\" x2=\"340\" y2=\"340\"/>\n    <line x1=\"20\" y1=\"120\" x2=\"380\" y2=\"120\"/>\n    <line x1=\"20\" y1=\"200\" x2=\"380\" y2=\"200\"/>\n    <line x1=\"20\" y1=\"280\" x2=\"380\" y2=\"280\"/>\n  </g>\n\n  <!-- ============================================================== -->\n  <!-- 1. FULLY TIGHTENED LOCKED BOWLINE KNOT (완벽 결속된 3D 매듭) -->\n  <!-- ============================================================== -->\n  <!-- Standing Part pulled upward under extreme tension -->\n  <path d=\"M 200 42 L 200 135\" stroke=\"#000000\" stroke-width=\"20\" stroke-linecap=\"round\"/>\n  <path d=\"M 200 42 L 200 135\" stroke=\"url(#ropeManila05)\" stroke-width=\"14\" stroke-linecap=\"round\"/>\n  <path d=\"M 200 42 L 200 135\" stroke=\"url(#braidManila05)\" stroke-width=\"14\" stroke-linecap=\"round\" opacity=\"0.75\"/>\n\n  <!-- Rear Collar Loop (Behind Standing Line) -->\n  <path d=\"M 215 150 C 235 125 235 85 198 85 C 165 85 155 115 165 150\" \n        stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 215 150 C 235 125 235 85 198 85 C 165 85 155 115 165 150\" \n        stroke=\"url(#ropeGreen05)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 215 150 C 235 125 235 85 198 85 C 165 85 155 115 165 150\" \n        stroke=\"url(#braidGreen05)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.8\"/>\n\n  <!-- Tightened Throat Loop (Locked Nipper Loop) -->\n  <g filter=\"url(#shadowDeep05)\">\n    <path d=\"M 200 135 C 160 145 155 195 190 202 C 225 205 235 180 220 155 C 205 138 185 135 160 148\" \n          stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\" fill=\"none\"/>\n    <path d=\"M 200 135 C 160 145 155 195 190 202 C 225 205 235 180 220 155 C 205 138 185 135 160 148\" \n          stroke=\"url(#ropeManila05)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n    <path d=\"M 200 135 C 160 145 155 195 190 202 C 225 205 235 180 220 155 C 205 138 185 135 160 148\" \n          stroke=\"url(#braidManila05)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.75\"/>\n  </g>\n\n  <!-- Locked Parallel Green Strands through Throat -->\n  <g filter=\"url(#shadowDeep05)\">\n    <!-- Emerging strand & Re-entered strand tightly bound together -->\n    <path d=\"M 180 185 L 180 148\" stroke=\"#000000\" stroke-width=\"16\" stroke-linecap=\"round\"/>\n    <path d=\"M 180 185 L 180 148\" stroke=\"url(#ropeGreen05)\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n    <path d=\"M 193 145 L 193 192\" stroke=\"#000000\" stroke-width=\"16\" stroke-linecap=\"round\"/>\n    <path d=\"M 193 145 L 193 192\" stroke=\"url(#ropeGreen05)\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n  </g>\n\n  <!-- Working Tail coming out inside the loop (Inside Tail - Correct Bowline) -->\n  <path d=\"M 193 192 C 193 210 215 220 230 220\" stroke=\"#000000\" stroke-width=\"16\" stroke-linecap=\"round\"/>\n  <path d=\"M 193 192 C 193 210 215 220 230 220\" stroke=\"url(#ropeGreen05)\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n  <line x1=\"228\" y1=\"216\" x2=\"232\" y2=\"224\" stroke=\"#ef4444\" stroke-width=\"4\" stroke-linecap=\"square\"/>\n\n  <!-- Big Locked Main Loop (하중을 받아도 절대 줄어들지 않는 완벽 루프) -->\n  <path d=\"M 190 202 C 190 255 155 315 110 315 C 65 315 35 255 50 195 C 60 145 110 130 160 148\" \n        stroke=\"#000000\" stroke-width=\"18\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 190 202 C 190 255 155 315 110 315 C 65 315 35 255 50 195 C 60 145 110 130 160 148\" \n        stroke=\"url(#ropeManila05)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 190 202 C 190 255 155 315 110 315 C 65 315 35 255 50 195 C 60 145 110 130 160 148\" \n        stroke=\"url(#braidManila05)\" stroke-width=\"12\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.75\"/>\n\n  <!-- ============================================================== -->\n  <!-- 2. TENSION FORCES (사방 팽팽한 장력 화살표) -->\n  <!-- ============================================================== -->\n  <!-- Upward Force Arrow -->\n  <path d=\"M 200 70 L 200 45\" stroke=\"#ef4444\" stroke-width=\"2.5\" stroke-linecap=\"round\" fill=\"none\"/>\n  <polygon points=\"200,38 194,50 206,50\" fill=\"#ef4444\"/>\n\n  <!-- Rightward Grip Force Arrow -->\n  <path d=\"M 215 225 L 245 235\" stroke=\"#ef4444\" stroke-width=\"2.5\" stroke-linecap=\"round\" fill=\"none\"/>\n  <polygon points=\"252,237 240,230 243,242\" fill=\"#ef4444\"/>\n\n  <!-- ============================================================== -->\n  <!-- 3. INSET LOUPE: 1초 해체 (BREAK THE BACK 엄지손가락 꺾기 기법) -->\n  <!-- ============================================================== -->\n  <g transform=\"translate(85, 110)\">\n    <circle cx=\"0\" cy=\"0\" r=\"38\" fill=\"#0d1117\" stroke=\"#38bdf8\" stroke-width=\"1.8\"/>\n    <circle cx=\"0\" cy=\"0\" r=\"36\" fill=\"none\" stroke=\"#222\" stroke-width=\"1\"/>\n    \n    <!-- Standing Line inside Loupe -->\n    <line x1=\"0\" y1=\"-28\" x2=\"0\" y2=\"28\" stroke=\"#b45309\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n    \n    <!-- Collar Loop being tilted backwards -->\n    <path d=\"M 16 0 C 16 -18 -16 -18 -16 0\" stroke=\"#22c55e\" stroke-width=\"7\" stroke-linecap=\"round\" fill=\"none\"/>\n    \n    <!-- Thumb Push Force Vector (엄지 젖히기) -->\n    <path d=\"M 0 -8 C 0 -22 18 -22 22 -14\" fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n\n  </g>\n\n  <!-- ============================================================== -->\n  <!-- 4. CALLOUT LABELS (12대 선언적 바인딩 라벨) -->\n  <!-- ============================================================== -->\n  <!-- Label 2, 3, 4: Quick Release Inset (Top Left) -->\n  <text x=\"24\" y=\"52\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">1-SEC QUICK RELEASE</text>\n  <text x=\"24\" y=\"65\" fill=\"#bae6fd\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">뒤통수(칼라) 꺾기 비법</text>\n  <text x=\"24\" y=\"162\" fill=\"#93c5fd\" font-family=\"'Chivo', sans-serif\" font-size=\"8.5\">엄지로 칼라를 꺾으면 즉시 해체</text>\n\n  <!-- Label 5 & 6: Pull Standing (Top Right) -->\n  <line x1=\"210\" y1=\"55\" x2=\"265\" y2=\"55\" stroke=\"#ef4444\" stroke-width=\"1\"/>\n  <circle cx=\"210\" cy=\"55\" r=\"2.5\" fill=\"#ef4444\"/>\n  <text x=\"275\" y=\"50\" fill=\"#f87171\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">PULL STANDING</text>\n  <text x=\"275\" y=\"63\" fill=\"#fca5a5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">원줄을 위로 강하게 당김</text>\n\n  <!-- Label 7 & 8: Grip Together (Center Right) -->\n  <line x1=\"240\" y1=\"210\" x2=\"265\" y2=\"210\" stroke=\"#22c55e\" stroke-width=\"1\"/>\n  <circle cx=\"240\" cy=\"210\" r=\"2.5\" fill=\"#22c55e\"/>\n  <text x=\"275\" y=\"205\" fill=\"#86efac\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">GRIP TOGETHER</text>\n  <text x=\"275\" y=\"218\" fill=\"#4ade80\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">끝단과 고리를 한 손에 쥠</text>\n\n  <!-- Label 9 & 10: Locked Fixed Loop (Bottom Left) -->\n  <line x1=\"60\" y1=\"280\" x2=\"30\" y2=\"280\" stroke=\"#f59e0b\" stroke-width=\"1\"/>\n  <circle cx=\"60\" cy=\"280\" r=\"2.5\" fill=\"#f59e0b\"/>\n  <text x=\"24\" y=\"268\" fill=\"#fde68a\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">LOCKED FIXED LOOP</text>\n  <text x=\"24\" y=\"281\" fill=\"#fef3c7\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">하중을 받아도 크기 불변</text>\n\n  <!-- Bottom Tactical Field Note Strip -->\n  <rect x=\"18\" y=\"342\" width=\"364\" height=\"40\" fill=\"#111419\" stroke=\"#262d35\" stroke-width=\"1\"/>\n  <rect x=\"18\" y=\"342\" width=\"4\" height=\"40\" fill=\"#38bdf8\"/>\n  <!-- Label 11 & 12: Summary Instruction -->\n  <text x=\"32\" y=\"357\" fill=\"#ffffff\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\" font-weight=\"bold\">[5단계 핵심] 양손으로 잡고 반대로 당겨 락킹 체결</text>\n  <text x=\"32\" y=\"371\" fill=\"#9ca3af\" font-family=\"'Chivo', sans-serif\" font-size=\"8.5\">풀 때는 매듭 뒤편 칼라 링을 엄지로 젖히면 칼 없이 1초 만에 풀립니다.</text>\n</svg>","content/svgs/pr08-outcome.svg":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\" class=\"w-full h-auto\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgOut\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#07080a\"/>\n      <stop offset=\"50%\" stop-color=\"#0f131a\"/>\n      <stop offset=\"100%\" stop-color=\"#060709\"/>\n    </linearGradient>\n\n    <!-- Heavy Slate Rock Texture Gradient -->\n    <linearGradient id=\"rockOut\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#64748b\"/>\n      <stop offset=\"25%\" stop-color=\"#475569\"/>\n      <stop offset=\"65%\" stop-color=\"#334155\"/>\n      <stop offset=\"100%\" stop-color=\"#1e293b\"/>\n    </linearGradient>\n\n    <!-- Rock Side Thickness Gradient -->\n    <linearGradient id=\"rockRimOut\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#94a3b8\"/>\n      <stop offset=\"50%\" stop-color=\"#64748b\"/>\n      <stop offset=\"100%\" stop-color=\"#1e293b\"/>\n    </linearGradient>\n\n    <!-- Rock Underside Cavern Shadow Gradient -->\n    <linearGradient id=\"rockUnderOut\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#1e293b\"/>\n      <stop offset=\"50%\" stop-color=\"#0f172a\"/>\n      <stop offset=\"100%\" stop-color=\"#020617\"/>\n    </linearGradient>\n\n    <!-- Hardwood Cylinder 3D Gradient -->\n    <linearGradient id=\"stick3D\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#3d210f\"/>\n      <stop offset=\"35%\" stop-color=\"#78350f\"/>\n      <stop offset=\"70%\" stop-color=\"#a15112\"/>\n      <stop offset=\"100%\" stop-color=\"#3d210f\"/>\n    </linearGradient>\n\n    <!-- Diagonal Strut Gradient -->\n    <linearGradient id=\"strut3D\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#3d210f\"/>\n      <stop offset=\"40%\" stop-color=\"#854d0e\"/>\n      <stop offset=\"75%\" stop-color=\"#b45309\"/>\n      <stop offset=\"100%\" stop-color=\"#2d1607\"/>\n    </linearGradient>\n\n    <!-- Carved Notch Pale Wood -->\n    <linearGradient id=\"carvedOut\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#fffbeb\"/>\n      <stop offset=\"60%\" stop-color=\"#fde68a\"/>\n      <stop offset=\"100%\" stop-color=\"#d97706\"/>\n    </linearGradient>\n\n    <!-- Deep Ground Cast Shadow -->\n    <filter id=\"shadowOut\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"10\" stdDeviation=\"8\" flood-color=\"#000000\" flood-opacity=\"0.95\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Canvas -->\n  <rect width=\"800\" height=\"450\" fill=\"url(#bgOut)\"/>\n  <rect x=\"12\" y=\"12\" width=\"776\" height=\"426\" fill=\"none\" stroke=\"#222831\" stroke-width=\"1.5\"/>\n\n  <!-- Technical Corner Ticks -->\n  <path d=\"M 20 32 L 36 32 M 28 24 L 28 40\" stroke=\"#4b5563\" stroke-width=\"1.5\"/>\n  <path d=\"M 780 32 L 764 32 M 772 24 L 772 40\" stroke=\"#4b5563\" stroke-width=\"1.5\"/>\n  <path d=\"M 20 418 L 36 418 M 28 410 L 28 426\" stroke=\"#4b5563\" stroke-width=\"1.5\"/>\n  <path d=\"M 780 418 L 764 418 M 772 410 L 772 426\" stroke=\"#4b5563\" stroke-width=\"1.5\"/>\n\n  <!-- Top Technical Header Strip -->\n  <rect x=\"28\" y=\"24\" width=\"744\" height=\"34\" fill=\"#0f172a\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n  <rect x=\"28\" y=\"24\" width=\"4\" height=\"34\" fill=\"#ef4444\"/>\n  <text x=\"44\" y=\"45\" fill=\"#f8fafc\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\" letter-spacing=\"1\">TARGET OUTCOME // FIGURE-4 DEADFALL TRAP</text>\n  <text x=\"756\" y=\"45\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" text-anchor=\"end\">PR-08 // FULL ASSEMBLY OVERVIEW</text>\n\n  <!-- Ground Plane Baseline -->\n  <line x1=\"40\" y1=\"365\" x2=\"760\" y2=\"365\" stroke=\"#334155\" stroke-width=\"2\"/>\n  <path d=\"M 60 370 L 80 385 M 120 370 L 140 385 M 180 370 L 200 385 M 240 370 L 260 385 M 300 370 L 320 385 M 360 370 L 380 385 M 420 370 L 440 385 M 480 370 L 500 385 M 540 370 L 560 385 M 600 370 L 620 385 M 660 370 L 680 385\" stroke=\"#1e293b\" stroke-width=\"1.2\"/>\n\n  <!-- Ground Shadows Beneath Post and Rock Ground Base -->\n  <ellipse cx=\"243\" cy=\"368\" rx=\"40\" ry=\"8\" fill=\"#000000\" opacity=\"0.8\"/>\n  <ellipse cx=\"620\" cy=\"368\" rx=\"85\" ry=\"12\" fill=\"#000000\" opacity=\"0.85\"/>\n\n  <!-- ============================================== -->\n  <!-- 1. HEAVY 15KG SLATE ROCK (3D Propped Canopy Slab) -->\n  <!-- ============================================== -->\n  <g filter=\"url(#shadowOut)\">\n    <!-- Underside Cavern Ceiling (Dark shadowed interior beneath the rock) -->\n    <polygon points=\"223,125 650,195 750,365 240,365\" fill=\"url(#rockUnderOut)\" stroke=\"#0f172a\" stroke-width=\"1.2\"/>\n    <!-- Top Face of Heavy Slate Slab (Slanted backward towards ground) -->\n    <polygon points=\"223,110 250,90 680,150 770,345 750,365 650,180\" fill=\"url(#rockOut)\" stroke=\"#1e293b\" stroke-width=\"2.2\"/>\n    <!-- Front Lifted Lip Thickness (Resting cleanly on strut tip at (223,125)) -->\n    <polygon points=\"223,125 650,195 650,180 223,110\" fill=\"#94a3b8\" stroke=\"#475569\" stroke-width=\"1\"/>\n    <!-- Rock Surface Geological Cleavage & Fractures -->\n    <path d=\"M 310 115 L 450 200 L 600 280 M 380 135 L 540 230 M 480 170 L 630 270\" stroke=\"#1e293b\" stroke-width=\"1.5\" stroke-linecap=\"round\"/>\n  </g>\n\n  <!-- ============================================== -->\n  <!-- 2. FIGURE-4 INTERLOCKING FRAME (In Foreground) -->\n  <!-- ============================================== -->\n  <g filter=\"url(#shadowOut)\">\n    <!-- Stick 1: Vertical Post (세움대 - x=230 to 256, y=175 to 365) -->\n    <rect x=\"230\" y=\"175\" width=\"26\" height=\"190\" rx=\"3\" fill=\"url(#stick3D)\" stroke=\"#271408\" stroke-width=\"1.2\"/>\n    <!-- Post Chisel Top Head (납작 쐐기 - Peak at (243, 145)) -->\n    <polygon points=\"230,175 243,145 256,175\" fill=\"url(#carvedOut)\" stroke=\"#78350f\" stroke-width=\"1\"/>\n    <!-- Middle Notch in Post (네모 홈 - y=268 to 286) -->\n    <rect x=\"230\" y=\"268\" width=\"14\" height=\"18\" fill=\"url(#carvedOut)\" stroke=\"#78350f\" stroke-width=\"1\"/>\n    <!-- Wood Bark Lines -->\n    <line x1=\"237\" y1=\"210\" x2=\"237\" y2=\"250\" stroke=\"#271408\" stroke-width=\"1\"/>\n    <line x1=\"250\" y1=\"295\" x2=\"250\" y2=\"345\" stroke=\"#271408\" stroke-width=\"1\"/>\n\n    <!-- Stick 2: Diagonal Strut (Mathematically 45.0°, Top at (243, 145) down to (368, 270)) -->\n    <!-- Extends above post to (223, 125) propping up rock, and bottom lands inside Bait stick rear notch at (368, 270) -->\n    <polygon points=\"213,115 225,127 243,145 255,133 267,145 378,256 368,272 356,260 233,137 223,125 203,105\" fill=\"url(#strut3D)\" stroke=\"#271408\" stroke-width=\"1.5\"/>\n\n    <!-- Upper Strut Tip Support Notch (Props Rock at (223, 125)) -->\n    <polygon points=\"213,115 225,127 223,125\" fill=\"url(#carvedOut)\" stroke=\"#b45309\" stroke-width=\"1.2\"/>\n    <!-- Mating Notch over Post Chisel Head (243, 145) -->\n    <polygon points=\"233,137 243,145 251,137 243,141\" fill=\"url(#carvedOut)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n    <!-- Bottom Beveled Tip (Locks into Bait stick rear notch at y=270) -->\n    <polygon points=\"356,260 368,272 378,256 368,252\" fill=\"url(#carvedOut)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n\n    <!-- Mechanical Contact Pivot Markers -->\n    <circle cx=\"223\" cy=\"125\" r=\"5\" fill=\"#ef4444\" opacity=\"0.95\"/>\n    <circle cx=\"223\" cy=\"125\" r=\"9\" fill=\"none\" stroke=\"#ef4444\" stroke-width=\"1.2\" stroke-dasharray=\"2 2\"/>\n    <circle cx=\"243\" cy=\"145\" r=\"4.5\" fill=\"#38bdf8\" opacity=\"0.95\"/>\n    <circle cx=\"368\" cy=\"270\" r=\"4.5\" fill=\"#38bdf8\" opacity=\"0.95\"/>\n\n    <!-- Stick 3: Horizontal Bait Stick (먹이대 - x=195 horizontally through to x=460, y=270 to 286) -->\n    <!-- Extends deeply into the danger zone sheltered beneath the rock -->\n    <path d=\"M 195 270 L 435 270 L 460 278 L 435 286 L 195 286 Z\" fill=\"url(#stick3D)\" stroke=\"#271408\" stroke-width=\"1.5\"/>\n    <!-- Catch Ledge on Bait Stick (locked with post at x=230) -->\n    <polygon points=\"228,268 245,268 245,286 228,286\" fill=\"url(#carvedOut)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n    <!-- Rear Notch on Bait Stick (locked with strut bottom at x=360..376, y=270) -->\n    <polygon points=\"360,270 376,270 368,284\" fill=\"url(#carvedOut)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n\n    <!-- Sharp Bait Pin at Far Right (under the rock) -->\n    <polygon points=\"435,270 460,278 435,286\" fill=\"url(#carvedOut)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n    <!-- Juicy Red Wild Berries Bait -->\n    <circle cx=\"450\" cy=\"278\" r=\"7\" fill=\"#ef4444\"/>\n    <circle cx=\"457\" cy=\"273\" r=\"5.5\" fill=\"#dc2626\"/>\n    <circle cx=\"456\" cy=\"283\" r=\"5\" fill=\"#b91c1c\"/>\n    <circle cx=\"450\" cy=\"278\" r=\"11\" fill=\"none\" stroke=\"#ef4444\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n  </g>\n\n  <!-- ============================================== -->\n  <!-- TECHNICAL LABELS & POINTERS -->\n  <!-- ============================================== -->\n  <!-- 1. Rock Pointer -->\n  <line x1=\"395\" y1=\"175\" x2=\"350\" y2=\"82\" stroke=\"#38bdf8\" stroke-width=\"1.5\"/>\n  <circle cx=\"395\" cy=\"175\" r=\"3.5\" fill=\"#38bdf8\"/>\n  <rect x=\"235\" y=\"70\" width=\"230\" height=\"22\" fill=\"#0f172a\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <text x=\"350\" y=\"85\" fill=\"#38bdf8\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">15kg 넓적한 평평한 바위 (45도 기울임)</text>\n\n  <!-- 2. Post 1 Pointer -->\n  <line x1=\"243\" y1=\"310\" x2=\"160\" y2=\"310\" stroke=\"#f59e0b\" stroke-width=\"1.5\"/>\n  <circle cx=\"243\" cy=\"310\" r=\"3.5\" fill=\"#f59e0b\"/>\n  <rect x=\"35\" y=\"299\" width=\"125\" height=\"22\" fill=\"#18181b\" stroke=\"#f59e0b\" stroke-width=\"1\"/>\n  <text x=\"45\" y=\"314\" fill=\"#fbbf24\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9\" font-weight=\"bold\">1번 세움대 (땅에 똑바로 선 기둥)</text>\n\n  <!-- 3. Strut 2 Pointer -->\n  <line x1=\"285\" y1=\"185\" x2=\"200\" y2=\"150\" stroke=\"#f59e0b\" stroke-width=\"1.5\"/>\n  <circle cx=\"285\" cy=\"185\" r=\"3.5\" fill=\"#f59e0b\"/>\n  <rect x=\"35\" y=\"140\" width=\"165\" height=\"22\" fill=\"#18181b\" stroke=\"#f59e0b\" stroke-width=\"1\"/>\n  <text x=\"45\" y=\"155\" fill=\"#fbbf24\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9\" font-weight=\"bold\">2번 빗장대 (바위를 떠받치는 버팀목)</text>\n\n  <!-- 4. Bait Stick 3 Pointer -->\n  <line x1=\"450\" y1=\"278\" x2=\"520\" y2=\"245\" stroke=\"#ef4444\" stroke-width=\"1.5\"/>\n  <circle cx=\"450\" cy=\"278\" r=\"3.5\" fill=\"#ef4444\"/>\n  <rect x=\"520\" y=\"234\" width=\"175\" height=\"22\" fill=\"#18181b\" stroke=\"#ef4444\" stroke-width=\"1\"/>\n  <text x=\"530\" y=\"249\" fill=\"#f87171\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9\" font-weight=\"bold\">3번 먹이대 (먹이를 꽂아둔 가로 막대)</text>\n\n  <!-- Bottom Right Summary Callout Box -->\n  <rect x=\"430\" y=\"335\" width=\"335\" height=\"52\" fill=\"#0d1117\" stroke=\"#21262d\" stroke-width=\"1\"/>\n  <rect x=\"430\" y=\"335\" width=\"4\" height=\"52\" fill=\"#22c55e\"/>\n  <text x=\"445\" y=\"354\" fill=\"#f8fafc\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9.5\" font-weight=\"bold\">[완성 기준] 먹이를 톡 건드리면 0.1초 만에 붕괴</text>\n  <text x=\"445\" y=\"369\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\">・끈 하나 없이 세 막대의 맞물림만으로 15kg 바위를 지탱합니다.</text>\n  <text x=\"445\" y=\"381\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\">・안쪽 미끼를 건드리는 즉시 뼈대가 풀려 바위가 단번에 덮칩니다.</text>\n</svg>\n","content/svgs/pr08-step-01.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgS1\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#07080a\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1117\"/>\n      <stop offset=\"100%\" stop-color=\"#060709\"/>\n    </linearGradient>\n\n    <!-- Bark Wood Gradient (Outer Bark) -->\n    <linearGradient id=\"barkGrad\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#5c3a21\"/>\n      <stop offset=\"25%\" stop-color=\"#8a532a\"/>\n      <stop offset=\"60%\" stop-color=\"#6e3f1d\"/>\n      <stop offset=\"100%\" stop-color=\"#3d210f\"/>\n    </linearGradient>\n\n    <!-- Carved Inner Wood (Pale Flesh Tone) -->\n    <linearGradient id=\"carvedWood\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#fffbeb\"/>\n      <stop offset=\"40%\" stop-color=\"#fef3c7\"/>\n      <stop offset=\"85%\" stop-color=\"#fde68a\"/>\n      <stop offset=\"100%\" stop-color=\"#d97706\"/>\n    </linearGradient>\n\n    <!-- Deep Drop Shadow -->\n    <filter id=\"shadowS1\" x=\"-15%\" y=\"-20%\" width=\"130%\" height=\"150%\">\n      <feDropShadow dx=\"0\" dy=\"5\" stdDeviation=\"4\" flood-color=\"#000000\" flood-opacity=\"0.85\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Canvas -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgS1)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#232830\" stroke-width=\"1.2\"/>\n\n  <!-- Technical Corner Ticks -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n\n  <!-- Top Header Strip (Label 1) -->\n  <rect x=\"20\" y=\"16\" width=\"360\" height=\"20\" fill=\"#0f172a\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n  <rect x=\"20\" y=\"16\" width=\"3\" height=\"20\" fill=\"#ef4444\"/>\n  <text x=\"30\" y=\"30\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" letter-spacing=\"0.5\">FIG. 01 // 3 STICKS ANATOMY &amp; NOTCHES</text>\n\n  <!-- Grid Guide Lines -->\n  <line x1=\"45\" y1=\"45\" x2=\"45\" y2=\"340\" stroke=\"#171f2a\" stroke-width=\"1\" stroke-dasharray=\"3 3\"/>\n  <line x1=\"355\" y1=\"45\" x2=\"355\" y2=\"340\" stroke=\"#171f2a\" stroke-width=\"1\" stroke-dasharray=\"3 3\"/>\n\n  <!-- ========================================== -->\n  <!-- 1. STICK 1: VERTICAL POST (세움대 20cm) -->\n  <!-- ========================================== -->\n  <g filter=\"url(#shadowS1)\">\n    <!-- Round End (Bottom Base, right side) -->\n    <ellipse cx=\"280\" cy=\"78\" rx=\"5\" ry=\"11\" fill=\"#3d210f\"/>\n    <!-- Main Cylinder Body -->\n    <path d=\"M 80 67 L 280 67 A 5 11 0 0 1 280 89 L 80 89 Z\" fill=\"url(#barkGrad)\" stroke=\"#271408\" stroke-width=\"1\"/>\n    <!-- Bark Texture Lines -->\n    <line x1=\"110\" y1=\"72\" x2=\"140\" y2=\"72\" stroke=\"#3d210f\" stroke-width=\"1\" stroke-linecap=\"round\"/>\n    <line x1=\"210\" y1=\"84\" x2=\"250\" y2=\"84\" stroke=\"#3d210f\" stroke-width=\"1\" stroke-linecap=\"round\"/>\n\n    <!-- Left Chisel Tip (납작 쐐기 깎은 단면) -->\n    <polygon points=\"80,67 52,78 80,89\" fill=\"url(#carvedWood)\" stroke=\"#92400e\" stroke-width=\"1.2\"/>\n    <line x1=\"52\" y1=\"78\" x2=\"80\" y2=\"78\" stroke=\"#b45309\" stroke-width=\"0.8\" stroke-dasharray=\"2 1\"/>\n\n    <!-- Middle Square Notch (가운데 사각 홈) -->\n    <polygon points=\"155,67 175,67 175,80 155,80\" fill=\"url(#carvedWood)\" stroke=\"#78350f\" stroke-width=\"1\"/>\n    <polygon points=\"155,80 175,80 175,82 155,82\" fill=\"#451a03\"/>\n    <!-- Graphic Notch Pointer -->\n    <path d=\"M 165 95 L 165 84\" stroke=\"#ef4444\" stroke-width=\"1.2\"/>\n    <polygon points=\"163,84 165,80 167,84\" fill=\"#ef4444\"/>\n  </g>\n\n  <!-- Label 2: Stick 1 -->\n  <text x=\"50\" y=\"58\" fill=\"#f59e0b\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9.5\" font-weight=\"bold\">POST (1번 세움대 - 윗머리 납작 쐐기 &amp; 네모 홈)</text>\n\n  <!-- ========================================== -->\n  <!-- 2. STICK 2: DIAGONAL STRUT (빗장대 25cm) -->\n  <!-- ========================================== -->\n  <g filter=\"url(#shadowS1)\">\n    <!-- Base Cylinder -->\n    <ellipse cx=\"315\" cy=\"165\" rx=\"5\" ry=\"11\" fill=\"#3d210f\"/>\n    <path d=\"M 65 154 L 315 154 A 5 11 0 0 1 315 176 L 65 176 Z\" fill=\"url(#barkGrad)\" stroke=\"#271408\" stroke-width=\"1\"/>\n    <!-- Bark Texture -->\n    <line x1=\"120\" y1=\"160\" x2=\"160\" y2=\"160\" stroke=\"#3d210f\" stroke-width=\"1\" stroke-linecap=\"round\"/>\n\n    <!-- Left Top V-Notch (상단 45도 V자 홈) -->\n    <polygon points=\"78,154 98,154 78,174\" fill=\"url(#carvedWood)\" stroke=\"#92400e\" stroke-width=\"1.2\"/>\n    <polygon points=\"78,174 98,154 98,156 80,176\" fill=\"#451a03\"/>\n    <path d=\"M 65 154 L 78 154 L 78 174 L 65 176 Z\" fill=\"url(#carvedWood)\" stroke=\"#92400e\" stroke-width=\"0.8\"/>\n\n    <!-- Right Bottom Bevel (하단 45도 안쪽 깎기) -->\n    <polygon points=\"300,154 315,154 300,176\" fill=\"url(#carvedWood)\" stroke=\"#92400e\" stroke-width=\"1\"/>\n    <!-- Graphic V-Notch Pointer -->\n    <path d=\"M 88 188 L 88 177\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n    <polygon points=\"86,177 88,173 90,177\" fill=\"#38bdf8\"/>\n  </g>\n\n  <!-- Label 3: Stick 2 -->\n  <text x=\"50\" y=\"145\" fill=\"#f59e0b\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9.5\" font-weight=\"bold\">STRUT (2번 빗장대 - 윗머리 V홈 &amp; 아랫머리 쐐기)</text>\n\n  <!-- ========================================== -->\n  <!-- 3. STICK 3: BAIT STICK (먹이대 30cm) -->\n  <!-- ========================================== -->\n  <g filter=\"url(#shadowS1)\">\n    <!-- Base Cylinder -->\n    <path d=\"M 60 242 L 320 242 L 350 253 L 320 264 L 60 264 Z\" fill=\"url(#barkGrad)\" stroke=\"#271408\" stroke-width=\"1\"/>\n    <!-- Bark Texture -->\n    <line x1=\"130\" y1=\"248\" x2=\"180\" y2=\"248\" stroke=\"#3d210f\" stroke-width=\"1\" stroke-linecap=\"round\"/>\n\n    <!-- Front Catch Ledge -->\n    <polygon points=\"60,242 85,242 85,251 60,251\" fill=\"url(#carvedWood)\" stroke=\"#92400e\" stroke-width=\"1.2\"/>\n    <polygon points=\"60,251 85,251 85,253 60,253\" fill=\"#451a03\"/>\n\n    <!-- Rear Notch for Strut -->\n    <polygon points=\"170,242 188,242 170,256\" fill=\"url(#carvedWood)\" stroke=\"#92400e\" stroke-width=\"1.2\"/>\n\n    <!-- Sharp Pencil Tip on Far Right -->\n    <polygon points=\"320,242 350,253 320,264\" fill=\"url(#carvedWood)\" stroke=\"#92400e\" stroke-width=\"1.2\"/>\n    <circle cx=\"348\" cy=\"253\" r=\"3.5\" fill=\"#ef4444\"/>\n    <!-- Graphic Bait Pointer -->\n    <path d=\"M 348 275 L 348 264\" stroke=\"#ef4444\" stroke-width=\"1.2\"/>\n    <polygon points=\"346,264 348,260 350,264\" fill=\"#ef4444\"/>\n  </g>\n\n  <!-- Label 4: Stick 3 -->\n  <text x=\"50\" y=\"233\" fill=\"#f59e0b\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9.5\" font-weight=\"bold\">BAIT STICK (3번 먹이대 - 걸림턱 &amp; 홈 &amp; 뾰족한 끝)</text>\n\n  <!-- Bottom Visual Callout Box (Label 5) -->\n  <rect x=\"20\" y=\"315\" width=\"360\" height=\"58\" fill=\"#0d1117\" stroke=\"#21262d\" stroke-width=\"1\"/>\n  <rect x=\"20\" y=\"315\" width=\"3\" height=\"58\" fill=\"#f59e0b\"/>\n  <text x=\"32\" y=\"348\" fill=\"#f8fafc\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9.5\" font-weight=\"bold\">[핵심] 서로 딱 물리는 직각 홈과 걸림턱 깎기</text>\n</svg>\n","content/svgs/pr08-step-02.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgS2\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#07080a\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1117\"/>\n      <stop offset=\"100%\" stop-color=\"#060709\"/>\n    </linearGradient>\n\n    <!-- Bark Wood Gradient -->\n    <linearGradient id=\"barkGrad2\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#451a03\"/>\n      <stop offset=\"30%\" stop-color=\"#78350f\"/>\n      <stop offset=\"70%\" stop-color=\"#92400e\"/>\n      <stop offset=\"100%\" stop-color=\"#451a03\"/>\n    </linearGradient>\n\n    <!-- Diagonal Bark Wood Gradient -->\n    <linearGradient id=\"diagBark\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#3d210f\"/>\n      <stop offset=\"35%\" stop-color=\"#78350f\"/>\n      <stop offset=\"75%\" stop-color=\"#92400e\"/>\n      <stop offset=\"100%\" stop-color=\"#2d1607\"/>\n    </linearGradient>\n\n    <!-- Fresh Cut Inner Wood -->\n    <linearGradient id=\"cutWood2\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#fffbeb\"/>\n      <stop offset=\"50%\" stop-color=\"#fde68a\"/>\n      <stop offset=\"100%\" stop-color=\"#d97706\"/>\n    </linearGradient>\n\n    <filter id=\"shadowS2\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"6\" stdDeviation=\"5\" flood-color=\"#000000\" flood-opacity=\"0.9\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Canvas -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgS2)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#232830\" stroke-width=\"1.2\"/>\n\n  <!-- Technical Corner Ticks -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n\n  <!-- Top Header Strip (Label 1) -->\n  <rect x=\"20\" y=\"16\" width=\"360\" height=\"20\" fill=\"#0f172a\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n  <rect x=\"20\" y=\"16\" width=\"3\" height=\"20\" fill=\"#3b82f6\"/>\n  <text x=\"30\" y=\"30\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" letter-spacing=\"0.5\">FIG. 02 // TOP NOTCH INTERLOCK</text>\n\n  <!-- Ground Plane Baseline -->\n  <line x1=\"30\" y1=\"310\" x2=\"370\" y2=\"310\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n  <path d=\"M 50 312 L 65 322 M 100 312 L 115 322 M 150 312 L 165 322 M 200 312 L 215 322 M 250 312 L 265 322 M 300 312 L 315 322\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n\n  <!-- ============================================== -->\n  <!-- MAIN ASSEMBLY: POST 1 & STRUT 2 TOP INTERLOCK -->\n  <!-- ============================================== -->\n  <g filter=\"url(#shadowS2)\">\n    <!-- 1. Stick 1: Vertical Post (x=132 to 156, y=135 to 310) -->\n    <rect x=\"132\" y=\"135\" width=\"24\" height=\"175\" rx=\"3\" fill=\"url(#barkGrad2)\" stroke=\"#271408\" stroke-width=\"1.2\"/>\n    <!-- Bark Texture Lines -->\n    <line x1=\"138\" y1=\"180\" x2=\"138\" y2=\"230\" stroke=\"#3d210f\" stroke-width=\"1\"/>\n    <line x1=\"150\" y1=\"200\" x2=\"150\" y2=\"260\" stroke=\"#3d210f\" stroke-width=\"1\"/>\n\n    <!-- Post Top Chisel Tip (납작 쐐기 - y=105 to 135, Peak at (144, 105)) -->\n    <polygon points=\"132,135 144,105 156,135\" fill=\"url(#cutWood2)\" stroke=\"#78350f\" stroke-width=\"1.2\"/>\n    <line x1=\"144\" y1=\"105\" x2=\"144\" y2=\"135\" stroke=\"#b45309\" stroke-width=\"1\" stroke-dasharray=\"2 1\"/>\n\n    <!-- 2. Stick 2: Diagonal Strut (Leaning 45 degrees, coming from (305, 266) to (144, 105)) -->\n    <!-- Direct V-notch cavity physically nesting over Chisel peak (144, 105) -->\n    <polygon points=\"130,91 144,105 158,91 172,105 315,248 297,266 154,123 144,113 134,123 116,105\" fill=\"url(#diagBark)\" stroke=\"#271408\" stroke-width=\"1.5\"/>\n\n    <!-- Inner Carved V-Notch Face (#fde68a 고대비 하이라이트) -->\n    <polygon points=\"134,123 144,105 154,123 144,113\" fill=\"url(#cutWood2)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n\n    <!-- Contact Pivot Highlight (Mechanical Axis alignment point) -->\n    <circle cx=\"144\" cy=\"105\" r=\"4.5\" fill=\"#ef4444\" opacity=\"0.95\"/>\n    <circle cx=\"144\" cy=\"105\" r=\"8\" fill=\"none\" stroke=\"#ef4444\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n  </g>\n\n  <!-- Force & Angle Indicators (Graphic Only) -->\n  <path d=\"M 225 150 L 165 110\" stroke=\"#38bdf8\" stroke-width=\"2.5\" stroke-linecap=\"round\"/>\n  <polygon points=\"160,107 172,111 168,118\" fill=\"#38bdf8\"/>\n  <path d=\"M 175 138 A 35 35 0 0 1 190 162\" fill=\"none\" stroke=\"#fbbf24\" stroke-width=\"1.5\" stroke-dasharray=\"2 2\"/>\n\n  <!-- Technical Magnifier Inspection Ring (Inset Zoom) -->\n  <g transform=\"translate(45, 60)\">\n    <circle cx=\"45\" cy=\"45\" r=\"40\" fill=\"#090d16\" stroke=\"#38bdf8\" stroke-width=\"1.5\"/>\n    <circle cx=\"45\" cy=\"45\" r=\"44\" fill=\"none\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n    <!-- Zoom Joint Silhouette: Post Chisel nested in Strut V-Notch -->\n    <polygon points=\"35,65 45,35 55,65\" fill=\"#fde68a\" stroke=\"#78350f\" stroke-width=\"1.5\"/>\n    <polygon points=\"28,28 45,35 62,28 72,38 52,58 45,45 38,58 18,38\" fill=\"#854d0e\" stroke=\"#271408\" stroke-width=\"1.5\"/>\n    <polygon points=\"38,45 45,35 52,45 45,42\" fill=\"#fde68a\"/>\n    <!-- Lock Check Icon -->\n    <path d=\"M 38 78 L 43 83 L 53 73\" stroke=\"#22c55e\" stroke-width=\"1.8\" fill=\"none\"/>\n  </g>\n\n  <!-- Technical Label Pointers with Direct Lines to Joint -->\n  <!-- Label 2: Post Tip -->\n  <line x1=\"140\" y1=\"102\" x2=\"80\" y2=\"55\" stroke=\"#f59e0b\" stroke-width=\"1.2\"/>\n  <circle cx=\"140\" cy=\"102\" r=\"3\" fill=\"#f59e0b\"/>\n  <rect x=\"25\" y=\"45\" width=\"140\" height=\"20\" fill=\"#18181b\" stroke=\"#f59e0b\" stroke-width=\"1\"/>\n  <text x=\"95\" y=\"59\" fill=\"#fbbf24\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"middle\">1번 세움대 납작 윗머리</text>\n\n  <!-- Label 3: Strut V-notch (Points directly to red contact hinge circle) -->\n  <line x1=\"148\" y1=\"105\" x2=\"220\" y2=\"75\" stroke=\"#f59e0b\" stroke-width=\"1.2\"/>\n  <circle cx=\"148\" cy=\"105\" r=\"3\" fill=\"#f59e0b\"/>\n  <rect x=\"200\" y=\"65\" width=\"150\" height=\"20\" fill=\"#18181b\" stroke=\"#f59e0b\" stroke-width=\"1\"/>\n  <text x=\"275\" y=\"79\" fill=\"#fbbf24\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"middle\">2번 빗장대 V자 홈 결합</text>\n\n  <!-- Label 4: Angle Mating -->\n  <rect x=\"180\" y=\"165\" width=\"135\" height=\"20\" fill=\"#0f172a\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <text x=\"247\" y=\"179\" fill=\"#38bdf8\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"middle\">45도 각도로 딱 맞물림</text>\n\n  <!-- Bottom Visual Callout Box (Label 5) -->\n  <rect x=\"20\" y=\"325\" width=\"360\" height=\"52\" fill=\"#0d1117\" stroke=\"#21262d\" stroke-width=\"1\"/>\n  <rect x=\"20\" y=\"325\" width=\"3\" height=\"52\" fill=\"#3b82f6\"/>\n  <text x=\"32\" y=\"355\" fill=\"#f8fafc\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9.5\" font-weight=\"bold\">[핵심] 미끄러지지 않고 딱 물리는 상단 결합</text>\n</svg>\n","content/svgs/pr08-step-03.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgS3\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#07080a\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1117\"/>\n      <stop offset=\"100%\" stop-color=\"#060709\"/>\n    </linearGradient>\n\n    <!-- Post Wood Gradient (Vertical) -->\n    <linearGradient id=\"postWoodS3\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#3d210f\"/>\n      <stop offset=\"35%\" stop-color=\"#78350f\"/>\n      <stop offset=\"70%\" stop-color=\"#92400e\"/>\n      <stop offset=\"100%\" stop-color=\"#3d210f\"/>\n    </linearGradient>\n\n    <!-- Strut Wood Gradient (Diagonal) -->\n    <linearGradient id=\"strutWoodS3\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#3d210f\"/>\n      <stop offset=\"40%\" stop-color=\"#854d0e\"/>\n      <stop offset=\"75%\" stop-color=\"#b45309\"/>\n      <stop offset=\"100%\" stop-color=\"#2d1607\"/>\n    </linearGradient>\n\n    <!-- Bait Stick Wood Gradient (Horizontal) -->\n    <linearGradient id=\"baitWoodS3\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#854d0e\"/>\n      <stop offset=\"30%\" stop-color=\"#b45309\"/>\n      <stop offset=\"70%\" stop-color=\"#92400e\"/>\n      <stop offset=\"100%\" stop-color=\"#451a03\"/>\n    </linearGradient>\n\n    <!-- Inner Carved Notches Highlight -->\n    <linearGradient id=\"notchFlesh\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#fffbeb\"/>\n      <stop offset=\"60%\" stop-color=\"#fde68a\"/>\n      <stop offset=\"100%\" stop-color=\"#d97706\"/>\n    </linearGradient>\n\n    <filter id=\"shadowS3\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"8\" stdDeviation=\"6\" flood-color=\"#000000\" flood-opacity=\"0.9\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Canvas -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgS3)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#232830\" stroke-width=\"1.2\"/>\n\n  <!-- Technical Corner Ticks -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n\n  <!-- Top Header Strip (Label 1) -->\n  <rect x=\"20\" y=\"16\" width=\"360\" height=\"20\" fill=\"#0f172a\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n  <rect x=\"20\" y=\"16\" width=\"3\" height=\"20\" fill=\"#22c55e\"/>\n  <text x=\"30\" y=\"30\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" letter-spacing=\"0.5\">FIG. 03 // NUMBER 4 LOCK ASSEMBLY</text>\n\n  <!-- Ground Plane Baseline -->\n  <line x1=\"30\" y1=\"310\" x2=\"370\" y2=\"310\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n  <path d=\"M 50 312 L 65 322 M 100 312 L 115 322 M 150 312 L 165 322 M 200 312 L 215 322 M 250 312 L 265 322 M 300 312 L 315 322\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n\n  <!-- Ground Shadows Beneath Post -->\n  <ellipse cx=\"156\" cy=\"311\" rx=\"28\" ry=\"5\" fill=\"#000000\" opacity=\"0.8\"/>\n\n  <!-- ============================================== -->\n  <!-- FULL NUMERAL 4 ASSEMBLED STANDALONE FRAME -->\n  <!-- ============================================== -->\n  <g filter=\"url(#shadowS3)\">\n    <!-- 1. Stick 1: Vertical Post (Straight Upright: x=145 to 167, y=125 to 310) -->\n    <rect x=\"145\" y=\"125\" width=\"22\" height=\"185\" rx=\"2.5\" fill=\"url(#postWoodS3)\" stroke=\"#271408\" stroke-width=\"1.2\"/>\n    <!-- Top Chisel Tip (Peak at (156, 95)) -->\n    <polygon points=\"145,125 156,95 167,125\" fill=\"url(#notchFlesh)\" stroke=\"#78350f\" stroke-width=\"1\"/>\n\n    <!-- Middle Notch in Post (y=192 to 208) -->\n    <rect x=\"145\" y=\"192\" width=\"12\" height=\"16\" fill=\"url(#notchFlesh)\" stroke=\"#78350f\" stroke-width=\"1\"/>\n    <!-- Post Bark Lines -->\n    <line x1=\"150\" y1=\"140\" x2=\"150\" y2=\"185\" stroke=\"#271408\" stroke-width=\"0.8\"/>\n    <line x1=\"162\" y1=\"215\" x2=\"162\" y2=\"290\" stroke=\"#271408\" stroke-width=\"0.8\"/>\n\n    <!-- 2. Stick 2: Diagonal Strut (Mathematically 45.0°, Top at (156, 95) down to (258, 196)) -->\n    <!-- Strut branch body: Width 16px, Top notch nests over chisel (156, 95), Bottom beveled tip nests inside Bait stick rear notch (258, 196) -->\n    <polygon points=\"144,83 156,95 168,83 178,93 268,183 258,196 248,186 134,73\" fill=\"url(#strutWoodS3)\" stroke=\"#271408\" stroke-width=\"1.2\"/>\n\n    <!-- Top Mating V-Notch (Nests snugly over chisel peak (156, 95)) -->\n    <polygon points=\"148,87 156,95 164,87 156,92\" fill=\"url(#notchFlesh)\" stroke=\"#b45309\" stroke-width=\"0.8\"/>\n\n    <!-- Bottom Beveled Tip (Locks flush inside Bait stick rear notch at y=192 to 198) -->\n    <polygon points=\"248,186 258,196 268,183 258,180\" fill=\"url(#notchFlesh)\" stroke=\"#b45309\" stroke-width=\"0.8\"/>\n\n    <!-- 3. Stick 3: Horizontal Bait Stick (Runs from x=110 across to x=345, y=192 to 208) -->\n    <path d=\"M 110 192 L 315 192 L 345 200 L 315 208 L 110 208 Z\" fill=\"url(#baitWoodS3)\" stroke=\"#271408\" stroke-width=\"1.2\"/>\n\n    <!-- Catch Ledge on Bait Stick (Locked into Post middle notch at x=145..157) -->\n    <polygon points=\"145,192 157,192 157,208 145,208\" fill=\"url(#notchFlesh)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n\n    <!-- Rear Notch on Bait Stick (Receives Strut bottom tip at x=250..266, y=192..204) -->\n    <polygon points=\"250,192 266,192 258,204\" fill=\"url(#notchFlesh)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n\n    <!-- Sharp Bait Pin at Far Right -->\n    <polygon points=\"315,192 345,200 315,208\" fill=\"url(#notchFlesh)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n    <!-- Red Wild Berry Bait -->\n    <circle cx=\"343\" cy=\"200\" r=\"4.5\" fill=\"#ef4444\"/>\n    <circle cx=\"343\" cy=\"200\" r=\"8\" fill=\"none\" stroke=\"#ef4444\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n  </g>\n\n  <!-- Key Interlock Joint Markers & Badges -->\n  <!-- Joint A: Post & Bait Stick (Label 2) -->\n  <circle cx=\"151\" cy=\"200\" r=\"5\" fill=\"#ef4444\" opacity=\"0.9\"/>\n  <circle cx=\"151\" cy=\"200\" r=\"9\" fill=\"none\" stroke=\"#ef4444\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n  <line x1=\"151\" y1=\"190\" x2=\"115\" y2=\"155\" stroke=\"#ef4444\" stroke-width=\"1.2\"/>\n  <rect x=\"40\" y=\"138\" width=\"115\" height=\"18\" fill=\"#1c1917\" stroke=\"#ef4444\" stroke-width=\"1\"/>\n  <text x=\"97\" y=\"150\" fill=\"#fca5a5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"8.5\" text-anchor=\"middle\" font-weight=\"bold\">세움대-먹이대 맞물림 턱</text>\n\n  <!-- Joint B: Strut & Bait Stick (Label 3) -->\n  <circle cx=\"258\" cy=\"196\" r=\"5\" fill=\"#38bdf8\" opacity=\"0.9\"/>\n  <circle cx=\"258\" cy=\"196\" r=\"9\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n  <line x1=\"258\" y1=\"187\" x2=\"285\" y2=\"155\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n  <rect x=\"235\" y=\"138\" width=\"115\" height=\"18\" fill=\"#0f172a\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <text x=\"292\" y=\"150\" fill=\"#bae6fd\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"8.5\" text-anchor=\"middle\" font-weight=\"bold\">빗장대-먹이대 뒷홈 걸림</text>\n\n  <!-- Top Center Self-Standing Badge (Label 4) -->\n  <rect x=\"130\" y=\"55\" width=\"140\" height=\"22\" fill=\"#14532d\" stroke=\"#22c55e\" stroke-width=\"1.2\"/>\n  <text x=\"200\" y=\"70\" fill=\"#86efac\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"bold\">끈 없이 혼자 서는 숫자 4</text>\n\n  <!-- Bottom Visual Callout Box (Label 5) -->\n  <rect x=\"20\" y=\"325\" width=\"360\" height=\"52\" fill=\"#0d1117\" stroke=\"#21262d\" stroke-width=\"1\"/>\n  <rect x=\"20\" y=\"325\" width=\"3\" height=\"52\" fill=\"#22c55e\"/>\n  <text x=\"32\" y=\"355\" fill=\"#f8fafc\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9.5\" font-weight=\"bold\">[핵심] 세 막대가 서로 밀어내며 스스로 자립</text>\n</svg>\n","content/svgs/pr08-step-04.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgS4\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#07080a\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1117\"/>\n      <stop offset=\"100%\" stop-color=\"#060709\"/>\n    </linearGradient>\n\n    <!-- Heavy Slate Rock Texture Gradient -->\n    <linearGradient id=\"rockGradS4\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#64748b\"/>\n      <stop offset=\"35%\" stop-color=\"#475569\"/>\n      <stop offset=\"70%\" stop-color=\"#334155\"/>\n      <stop offset=\"100%\" stop-color=\"#1e293b\"/>\n    </linearGradient>\n\n    <!-- Rock Underside Cavern Shadow Gradient -->\n    <linearGradient id=\"rockUnderGrad\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#1e293b\"/>\n      <stop offset=\"50%\" stop-color=\"#0f172a\"/>\n      <stop offset=\"100%\" stop-color=\"#020617\"/>\n    </linearGradient>\n\n    <!-- Rock Rim 3D Gradient -->\n    <linearGradient id=\"rockRimS4\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#94a3b8\"/>\n      <stop offset=\"50%\" stop-color=\"#64748b\"/>\n      <stop offset=\"100%\" stop-color=\"#334155\"/>\n    </linearGradient>\n\n    <!-- Wood Bark Gradient -->\n    <linearGradient id=\"woodBarkS4\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#451a03\"/>\n      <stop offset=\"35%\" stop-color=\"#78350f\"/>\n      <stop offset=\"70%\" stop-color=\"#92400e\"/>\n      <stop offset=\"100%\" stop-color=\"#3d210f\"/>\n    </linearGradient>\n\n    <!-- Diagonal Strut Gradient -->\n    <linearGradient id=\"strutBarkS4\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#3d210f\"/>\n      <stop offset=\"40%\" stop-color=\"#854d0e\"/>\n      <stop offset=\"75%\" stop-color=\"#b45309\"/>\n      <stop offset=\"100%\" stop-color=\"#2d1607\"/>\n    </linearGradient>\n\n    <!-- Carved Inner Wood Notch -->\n    <linearGradient id=\"carvedWoodS4\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#fffbeb\"/>\n      <stop offset=\"50%\" stop-color=\"#fde68a\"/>\n      <stop offset=\"100%\" stop-color=\"#d97706\"/>\n    </linearGradient>\n\n    <!-- Motion Blur Ghost Fill for Falling Rock -->\n    <linearGradient id=\"rockGhostS4\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#38bdf8\" stop-opacity=\"0.35\"/>\n      <stop offset=\"100%\" stop-color=\"#0284c7\" stop-opacity=\"0.08\"/>\n    </linearGradient>\n\n    <filter id=\"shadowS4\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"8\" stdDeviation=\"6\" flood-color=\"#000000\" flood-opacity=\"0.9\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Canvas -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgS4)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#232830\" stroke-width=\"1.2\"/>\n\n  <!-- Technical Corner Ticks -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n\n  <!-- Top Header Strip (Label 1) -->\n  <rect x=\"20\" y=\"16\" width=\"360\" height=\"20\" fill=\"#0f172a\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n  <rect x=\"20\" y=\"16\" width=\"3\" height=\"20\" fill=\"#f59e0b\"/>\n  <text x=\"30\" y=\"30\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" letter-spacing=\"0.5\">FIG. 04 // ROCK LOAD &amp; 0.1S COLLAPSE</text>\n\n  <!-- Ground Plane Baseline -->\n  <line x1=\"25\" y1=\"310\" x2=\"375\" y2=\"310\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n  <path d=\"M 35 312 L 50 322 M 70 312 L 85 322 M 105 312 L 120 322 M 140 312 L 155 322 M 175 312 L 190 322 M 210 312 L 225 322 M 245 312 L 260 322 M 280 312 L 295 322 M 315 312 L 330 322 M 350 312 L 365 322\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n\n  <!-- Ground Shadows -->\n  <ellipse cx=\"156\" cy=\"311\" rx=\"28\" ry=\"5\" fill=\"#000000\" opacity=\"0.8\"/>\n  <ellipse cx=\"320\" cy=\"311\" rx=\"45\" ry=\"6\" fill=\"#000000\" opacity=\"0.9\"/>\n\n  <!-- ============================================== -->\n  <!-- 0.1s COLLAPSE MOTION GHOST (Falling Rock Trajectory) -->\n  <!-- ============================================== -->\n  <!-- Ghost Rock Dropped Flat on Ground Crushing Bait Area -->\n  <polygon points=\"135,308 355,308 350,282 140,282\" fill=\"url(#rockGhostS4)\" stroke=\"#38bdf8\" stroke-width=\"1\" stroke-dasharray=\"3 3\"/>\n  <!-- Downward Impact Motion Trajectory Arrows -->\n  <path d=\"M 180 120 L 180 270 M 235 135 L 235 270 M 285 145 L 285 270\" stroke=\"#38bdf8\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n  <polygon points=\"177,270 180,277 183,270\" fill=\"#38bdf8\"/>\n  <polygon points=\"232,270 235,277 238,270\" fill=\"#38bdf8\"/>\n  <polygon points=\"282,270 285,277 288,270\" fill=\"#38bdf8\"/>\n\n  <!-- ============================================== -->\n  <!-- 1. HEAVY 15KG SLATE ROCK (3D Propped Canopy Slab) -->\n  <!-- ============================================== -->\n  <!-- The massive stone slab is lifted at front lip (138,77) by the Strut tip, forming a wide open overhead roof. -->\n  <!-- The back edge rests on the ground (150..390, 308). The entire bait stick is sheltered inside the deep cavern. -->\n  <g filter=\"url(#shadowS4)\">\n    <!-- Underside Cavern Ceiling (Dark shadowed interior beneath the rock) -->\n    <polygon points=\"138,77 350,125 390,308 150,308\" fill=\"url(#rockUnderGrad)\" stroke=\"#0f172a\" stroke-width=\"1\"/>\n    <!-- Top Face of Heavy Slate Slab (Slanted backward towards ground) -->\n    <polygon points=\"138,65 156,50 370,95 400,290 390,308 350,113\" fill=\"url(#rockGradS4)\" stroke=\"#1e293b\" stroke-width=\"1.8\"/>\n    <!-- Front Lifted Lip Thickness (Resting cleanly on Strut top notch at (138,77)) -->\n    <polygon points=\"138,77 350,125 350,113 138,65\" fill=\"#94a3b8\" stroke=\"#475569\" stroke-width=\"0.8\"/>\n    <!-- Top Face Geological Cleavage Lines -->\n    <path d=\"M 180 62 L 270 140 L 370 220 M 230 75 L 320 160 M 300 95 L 380 190\" stroke=\"#1e293b\" stroke-width=\"1.2\" stroke-linecap=\"round\"/>\n  </g>\n\n  <!-- ============================================== -->\n  <!-- 2. FIGURE-4 STICK TRIGGER MECHANISM (In Foreground) -->\n  <!-- ============================================== -->\n  <g filter=\"url(#shadowS4)\">\n    <!-- Stick 1: Vertical Post (세움대 - Stands upright at x=145 to 167, y=125 to 310) -->\n    <rect x=\"145\" y=\"125\" width=\"22\" height=\"185\" rx=\"2.5\" fill=\"url(#woodBarkS4)\" stroke=\"#271408\" stroke-width=\"1.2\"/>\n    <!-- Post Top Chisel Head (납작 쐐기 - Peak at (156, 95)) -->\n    <polygon points=\"145,125 156,95 167,125\" fill=\"url(#carvedWoodS4)\" stroke=\"#78350f\" stroke-width=\"1\"/>\n    <!-- Post Middle Notch (네모 홈 - y=192 to 208) -->\n    <rect x=\"145\" y=\"192\" width=\"12\" height=\"16\" fill=\"url(#carvedWoodS4)\" stroke=\"#78350f\" stroke-width=\"0.8\"/>\n    <!-- Post Bark Lines -->\n    <line x1=\"150\" y1=\"140\" x2=\"150\" y2=\"185\" stroke=\"#271408\" stroke-width=\"0.8\"/>\n    <line x1=\"162\" y1=\"215\" x2=\"162\" y2=\"290\" stroke=\"#271408\" stroke-width=\"0.8\"/>\n\n    <!-- Stick 2: Diagonal Strut (Mathematically 45.0°, Top at (156, 95) down to (258, 196)) -->\n    <!-- Extends above post to (138, 77) where it directly props up the rock's front underside lip -->\n    <polygon points=\"128,67 140,79 156,95 168,83 178,93 268,183 258,196 248,186 148,87 138,77 118,57\" fill=\"url(#strutBarkS4)\" stroke=\"#271408\" stroke-width=\"1.2\"/>\n\n    <!-- Upper Support Tip Notch (Props Rock at (138, 77)) -->\n    <polygon points=\"128,67 140,79 138,77\" fill=\"url(#carvedWoodS4)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n    <!-- Mating Notch over Post Chisel (156, 95) -->\n    <polygon points=\"148,87 156,95 164,87 156,92\" fill=\"url(#carvedWoodS4)\" stroke=\"#b45309\" stroke-width=\"0.8\"/>\n    <!-- Bottom Beveled Tip (Locks into Bait stick rear notch at y=192 to 198) -->\n    <polygon points=\"248,186 258,196 268,183 258,180\" fill=\"url(#carvedWoodS4)\" stroke=\"#b45309\" stroke-width=\"0.8\"/>\n\n    <!-- Critical Mechanical Contact Pivots -->\n    <circle cx=\"138\" cy=\"77\" r=\"4.5\" fill=\"#ef4444\" opacity=\"0.95\"/>\n    <circle cx=\"138\" cy=\"77\" r=\"8\" fill=\"none\" stroke=\"#ef4444\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n    <circle cx=\"156\" cy=\"95\" r=\"3.5\" fill=\"#38bdf8\" opacity=\"0.9\"/>\n    <circle cx=\"258\" cy=\"196\" r=\"3.5\" fill=\"#38bdf8\" opacity=\"0.9\"/>\n\n    <!-- Stick 3: Horizontal Bait Stick (Runs from x=110 across to x=280, y=192 to 208) -->\n    <!-- Extends deeply into the sheltered cavern under the rock, bait clearly inside the fall zone -->\n    <path d=\"M 110 192 L 260 192 L 280 200 L 260 208 L 110 208 Z\" fill=\"url(#woodBarkS4)\" stroke=\"#271408\" stroke-width=\"1.2\"/>\n    <!-- Front Ledge on Bait Stick (Locked into Post middle notch) -->\n    <polygon points=\"145,192 157,192 157,208 145,208\" fill=\"url(#carvedWoodS4)\" stroke=\"#b45309\" stroke-width=\"0.8\"/>\n    <!-- Rear Catch Notch on Bait Stick (Locked with Strut bottom) -->\n    <polygon points=\"250,192 266,192 258,204\" fill=\"url(#carvedWoodS4)\" stroke=\"#b45309\" stroke-width=\"0.8\"/>\n    <!-- Pointed Inner Bait Pin under the Rock -->\n    <polygon points=\"260,192 280,200 260,208\" fill=\"url(#carvedWoodS4)\" stroke=\"#b45309\" stroke-width=\"0.8\"/>\n    <!-- Juicy Red Wild Berries Bait (Deep inside cavern, 80px away from rock edge) -->\n    <circle cx=\"275\" cy=\"200\" r=\"5\" fill=\"#ef4444\"/>\n    <circle cx=\"281\" cy=\"197\" r=\"4\" fill=\"#dc2626\"/>\n    <circle cx=\"275\" cy=\"200\" r=\"8\" fill=\"none\" stroke=\"#ef4444\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n  </g>\n\n  <!-- Prey Touch Action Trigger Pointer -->\n  <path d=\"M 320 175 C 305 175 297 190 287 198\" stroke=\"#ef4444\" stroke-width=\"1.8\" fill=\"none\" stroke-linecap=\"round\"/>\n  <polygon points=\"285,195 281,203 289,200\" fill=\"#ef4444\"/>\n\n  <!-- ============================================== -->\n  <!-- TECHNICAL LABELS & POINTERS -->\n  <!-- ============================================== -->\n  <!-- Label 2: Heavy Rock -->\n  <line x1=\"230\" y1=\"100\" x2=\"270\" y2=\"65\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n  <circle cx=\"230\" cy=\"100\" r=\"3\" fill=\"#38bdf8\"/>\n  <rect x=\"200\" y=\"55\" width=\"150\" height=\"20\" fill=\"#0f172a\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <text x=\"275\" y=\"69\" fill=\"#38bdf8\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"middle\">15kg 평평한 바위 안착</text>\n\n  <!-- Label 3: Bait Mount (Points directly to berries inside the drop zone) -->\n  <line x1=\"275\" y1=\"210\" x2=\"275\" y2=\"245\" stroke=\"#f59e0b\" stroke-width=\"1.2\"/>\n  <circle cx=\"275\" cy=\"210\" r=\"3\" fill=\"#f59e0b\"/>\n  <rect x=\"205\" y=\"245\" width=\"140\" height=\"20\" fill=\"#18181b\" stroke=\"#f59e0b\" stroke-width=\"1\"/>\n  <text x=\"275\" y=\"259\" fill=\"#fbbf24\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"middle\">먹이대 끝 미끼 장착</text>\n\n  <!-- Label 4: Instant Collapse -->\n  <line x1=\"180\" y1=\"210\" x2=\"135\" y2=\"225\" stroke=\"#ef4444\" stroke-width=\"1.2\"/>\n  <circle cx=\"180\" cy=\"210\" r=\"3\" fill=\"#ef4444\"/>\n  <rect x=\"25\" y=\"215\" width=\"155\" height=\"20\" fill=\"#1c1917\" stroke=\"#ef4444\" stroke-width=\"1\"/>\n  <text x=\"102\" y=\"229\" fill=\"#f87171\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">톡 건드리면 0.1초 만에 바위 낙하</text>\n\n  <!-- Bottom Visual Callout Box (Label 5) -->\n  <rect x=\"20\" y=\"325\" width=\"360\" height=\"52\" fill=\"#0d1117\" stroke=\"#21262d\" stroke-width=\"1\"/>\n  <rect x=\"20\" y=\"325\" width=\"3\" height=\"52\" fill=\"#f59e0b\"/>\n  <text x=\"32\" y=\"355\" fill=\"#f8fafc\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"9.5\" font-weight=\"bold\">[핵심] 스치기만 해도 와르르 무너지는 민감도</text>\n</svg>\n","content/svgs/pr09-outcome.svg":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\" class=\"w-full h-auto\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgOut9\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#07080a\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1218\"/>\n      <stop offset=\"100%\" stop-color=\"#050709\"/>\n    </linearGradient>\n\n    <!-- Soil Strata -->\n    <linearGradient id=\"soilCutOut\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#3b2314\"/>\n      <stop offset=\"50%\" stop-color=\"#241409\"/>\n      <stop offset=\"100%\" stop-color=\"#140a04\"/>\n    </linearGradient>\n\n    <!-- Mud Kiln Mound -->\n    <linearGradient id=\"moundGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#3e2314\"/>\n      <stop offset=\"35%\" stop-color=\"#593b26\"/>\n      <stop offset=\"70%\" stop-color=\"#412918\"/>\n      <stop offset=\"100%\" stop-color=\"#2d1607\"/>\n    </linearGradient>\n\n    <!-- Turf Grass Layer -->\n    <linearGradient id=\"turfGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#2d4a22\"/>\n      <stop offset=\"50%\" stop-color=\"#4d7c0f\"/>\n      <stop offset=\"100%\" stop-color=\"#365314\"/>\n    </linearGradient>\n\n    <!-- Pyrolysis Glow in Kiln Interior -->\n    <radialGradient id=\"pyrolysisGlow\" cx=\"50%\" cy=\"80%\" r=\"70%\">\n      <stop offset=\"0%\" stop-color=\"#ea580c\" stop-opacity=\"0.75\"/>\n      <stop offset=\"35%\" stop-color=\"#b45309\" stop-opacity=\"0.45\"/>\n      <stop offset=\"70%\" stop-color=\"#78350f\" stop-opacity=\"0.2\"/>\n      <stop offset=\"100%\" stop-color=\"#07080a\" stop-opacity=\"0\"/>\n    </radialGradient>\n\n    <!-- Blue Pyrolysis Smoke Stream -->\n    <radialGradient id=\"bluePlume\" cx=\"50%\" cy=\"50%\" r=\"50%\">\n      <stop offset=\"0%\" stop-color=\"#38bdf8\" stop-opacity=\"0.85\"/>\n      <stop offset=\"35%\" stop-color=\"#0284c7\" stop-opacity=\"0.5\"/>\n      <stop offset=\"75%\" stop-color=\"#0369a1\" stop-opacity=\"0.15\"/>\n      <stop offset=\"100%\" stop-color=\"#07080a\" stop-opacity=\"0\"/>\n    </radialGradient>\n\n    <!-- Carbon Charcoal Texture -->\n    <linearGradient id=\"charcoalGloss\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#334155\"/>\n      <stop offset=\"30%\" stop-color=\"#1e293b\"/>\n      <stop offset=\"70%\" stop-color=\"#0f172a\"/>\n      <stop offset=\"100%\" stop-color=\"#020617\"/>\n    </linearGradient>\n\n    <!-- Silver Sheen Highlight -->\n    <linearGradient id=\"silverGloss\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#475569\"/>\n      <stop offset=\"50%\" stop-color=\"#cbd5e1\"/>\n      <stop offset=\"100%\" stop-color=\"#334155\"/>\n    </linearGradient>\n\n    <filter id=\"shadowOut9\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"6\" stdDeviation=\"5\" flood-color=\"#000000\" flood-opacity=\"0.95\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Canvas -->\n  <rect width=\"800\" height=\"450\" fill=\"url(#bgOut9)\"/>\n  <rect x=\"12\" y=\"12\" width=\"776\" height=\"426\" fill=\"none\" stroke=\"#232830\" stroke-width=\"1.2\"/>\n\n  <!-- Technical Corner Ticks -->\n  <path d=\"M 20 28 L 36 28 M 28 20 L 28 36\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 780 28 L 764 28 M 772 20 L 772 36\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 20 422 L 36 422 M 28 414 L 28 430\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 780 422 L 764 422 M 772 414 L 772 430\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n\n  <!-- Top Technical Header Strip -->\n  <rect x=\"28\" y=\"22\" width=\"744\" height=\"24\" fill=\"#0f172a\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n  <rect x=\"28\" y=\"22\" width=\"4\" height=\"24\" fill=\"#f97316\"/>\n  <text x=\"42\" y=\"38\" fill=\"#e2e8f0\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" font-weight=\"bold\" letter-spacing=\"0.5\">PR-09 // PIT CHARCOAL KILN (원시 지하 숯가마 구조 &amp; 고순도 탄소 숯 완성 단면)</text>\n\n  <!-- Left: Underground Kiln Cross Section -->\n  <!-- Ground Level & Earth -->\n  <path d=\"M 35 190 L 80 190 L 140 375 L 35 375 Z\" fill=\"url(#soilCutOut)\" opacity=\"0.65\"/>\n  <path d=\"M 450 190 L 390 190 L 330 375 L 450 375 Z\" fill=\"url(#soilCutOut)\" opacity=\"0.65\"/>\n\n  <!-- Pit Interior Chamber (Cone Shape) -->\n  <path d=\"M 80 190 Q 235 200 390 190 L 330 375 Q 235 380 140 375 Z\" fill=\"#140a04\" stroke=\"#452715\" stroke-width=\"1.5\"/>\n\n  <!-- Heat/Pyrolysis Glow inside Kiln -->\n  <path d=\"M 140 375 Q 235 380 330 375 L 310 260 Q 235 270 160 260 Z\" fill=\"url(#pyrolysisGlow)\"/>\n\n  <!-- Stood Oak Logs inside (Pyrolyzing to Black Charcoal) -->\n  <g filter=\"url(#shadowOut9)\">\n    <!-- Log 1 -->\n    <rect x=\"155\" y=\"205\" width=\"22\" height=\"160\" rx=\"3\" fill=\"#1e130b\" stroke=\"#0a0502\" stroke-width=\"1\"/>\n    <!-- Log 2 -->\n    <rect x=\"185\" y=\"195\" width=\"25\" height=\"175\" rx=\"3\" fill=\"#24170d\" stroke=\"#0a0502\" stroke-width=\"1\"/>\n    <!-- Log 3 (Center) -->\n    <rect x=\"220\" y=\"190\" width=\"30\" height=\"182\" rx=\"3\" fill=\"#2a1b10\" stroke=\"#0a0502\" stroke-width=\"1\"/>\n    <!-- Log 4 -->\n    <rect x=\"260\" y=\"195\" width=\"26\" height=\"175\" rx=\"3\" fill=\"#24170d\" stroke=\"#0a0502\" stroke-width=\"1\"/>\n    <!-- Log 5 -->\n    <rect x=\"295\" y=\"205\" width=\"22\" height=\"160\" rx=\"3\" fill=\"#1e130b\" stroke=\"#0a0502\" stroke-width=\"1\"/>\n    <!-- Wedge branches -->\n    <line x1=\"180\" y1=\"210\" x2=\"182\" y2=\"350\" stroke=\"#78350f\" stroke-width=\"5\" stroke-linecap=\"round\"/>\n    <line x1=\"215\" y1=\"205\" x2=\"216\" y2=\"355\" stroke=\"#78350f\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n    <line x1=\"254\" y1=\"205\" x2=\"253\" y2=\"355\" stroke=\"#78350f\" stroke-width=\"5.5\" stroke-linecap=\"round\"/>\n    <line x1=\"290\" y1=\"210\" x2=\"288\" y2=\"350\" stroke=\"#78350f\" stroke-width=\"5\" stroke-linecap=\"round\"/>\n  </g>\n\n  <!-- Glowing Embers Bed at Bottom -->\n  <g>\n    <ellipse cx=\"235\" cy=\"372\" rx=\"75\" ry=\"8\" fill=\"#ea580c\"/>\n    <circle cx=\"185\" cy=\"370\" r=\"5\" fill=\"#fef08a\"/>\n    <circle cx=\"215\" cy=\"373\" r=\"6\" fill=\"#fde047\"/>\n    <circle cx=\"255\" cy=\"371\" r=\"5\" fill=\"#fef08a\"/>\n    <circle cx=\"285\" cy=\"372\" r=\"5\" fill=\"#fde047\"/>\n  </g>\n\n  <!-- Kiln Dome: Mud & Sod Seal (10cm) -->\n  <g filter=\"url(#shadowOut9)\">\n    <path d=\"M 65 190 Q 235 110 405 190 Q 235 160 65 190 Z\" fill=\"url(#moundGrad)\" stroke=\"#593b26\" stroke-width=\"1.5\"/>\n    <path d=\"M 72 189 Q 235 113 398 189 Q 235 130 72 189 Z\" fill=\"url(#turfGrad)\" opacity=\"0.85\"/>\n  </g>\n\n  <!-- Center Chimney -->\n  <g filter=\"url(#shadowOut9)\">\n    <path d=\"M 220 126 L 220 105 Q 235 102 250 105 L 250 126 Z\" fill=\"#3e2314\" stroke=\"#5c381e\" stroke-width=\"1.2\"/>\n    <ellipse cx=\"235\" cy=\"105\" rx=\"15\" ry=\"4\" fill=\"#0c0603\" stroke=\"#ea580c\" stroke-width=\"1\"/>\n  </g>\n\n  <!-- Billowing Faint Blue Pyrolysis Smoke Stream -->\n  <g>\n    <circle cx=\"235\" cy=\"85\" r=\"14\" fill=\"url(#bluePlume)\"/>\n    <circle cx=\"222\" cy=\"65\" r=\"18\" fill=\"url(#bluePlume)\"/>\n    <circle cx=\"245\" cy=\"55\" r=\"22\" fill=\"url(#bluePlume)\"/>\n    <circle cx=\"230\" cy=\"35\" r=\"26\" fill=\"url(#bluePlume)\"/>\n  </g>\n\n  <!-- Air Intake Arrows -->\n  <g>\n    <!-- Left Intake -->\n    <ellipse cx=\"78\" cy=\"195\" rx=\"4\" ry=\"7\" fill=\"#0a0502\" stroke=\"#ea580c\" stroke-width=\"1\"/>\n    <path d=\"M 45 195 L 68 195\" stroke=\"#38bdf8\" stroke-width=\"1.6\" stroke-dasharray=\"3 2\"/>\n    <polygon points=\"73,195 66,192 66,198\" fill=\"#38bdf8\"/>\n    <!-- Right Intake -->\n    <ellipse cx=\"392\" cy=\"195\" rx=\"4\" ry=\"7\" fill=\"#0a0502\" stroke=\"#ea580c\" stroke-width=\"1\"/>\n    <path d=\"M 425 195 L 402 195\" stroke=\"#38bdf8\" stroke-width=\"1.6\" stroke-dasharray=\"3 2\"/>\n    <polygon points=\"397,195 404,192 404,198\" fill=\"#38bdf8\"/>\n  </g>\n\n  <!-- Annotations on Kiln Diagram -->\n  <rect x=\"42\" y=\"75\" width=\"135\" height=\"18\" fill=\"#0b1320\" rx=\"3\" stroke=\"#1e3a5f\" stroke-width=\"1\"/>\n  <text x=\"109\" y=\"88\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">상단 굴뚝: 푸른 연기 배출</text>\n\n  <rect x=\"42\" y=\"145\" width=\"135\" height=\"18\" fill=\"#141f0d\" rx=\"3\" stroke=\"#4d7c0f\" stroke-width=\"1\"/>\n  <text x=\"109\" y=\"158\" fill=\"#bef264\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">10cm 점토 &amp; 잔디 뗏장 덮개</text>\n\n  <rect x=\"28\" y=\"275\" width=\"115\" height=\"18\" fill=\"#1c0f05\" rx=\"3\" stroke=\"#ea580c\" stroke-width=\"1\"/>\n  <text x=\"85\" y=\"288\" fill=\"#fb923c\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">50cm 원뿔 구덩이</text>\n\n  <!-- Right: Harvested Charcoal Specification & Performance Panel -->\n  <g filter=\"url(#shadowOut9)\">\n    <rect x=\"480\" y=\"62\" width=\"292\" height=\"325\" fill=\"#0b0f17\" rx=\"6\" stroke=\"#1e293b\" stroke-width=\"1.5\"/>\n    <rect x=\"480\" y=\"62\" width=\"292\" height=\"26\" fill=\"#111827\" rx=\"6\" stroke=\"#1f2937\" stroke-width=\"1\"/>\n    <text x=\"626\" y=\"79\" fill=\"#f8fafc\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10.5\" font-weight=\"bold\" text-anchor=\"middle\">수확된 고급 참나무 숯 제원 (SPECIFICATION)</text>\n\n    <!-- Harvested Charcoal Vector Art Illustration -->\n    <!-- Large Charcoal Log Chunk -->\n    <g>\n      <polygon points=\"560,165 620,120 710,130 735,175 660,215 570,205\" fill=\"url(#charcoalGloss)\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n      <!-- Silver Sheen Facet -->\n      <polygon points=\"620,120 710,130 675,170 595,155\" fill=\"url(#silverGloss)\" opacity=\"0.3\"/>\n      <!-- Cleavage Lines -->\n      <line x1=\"635\" y1=\"135\" x2=\"670\" y2=\"195\" stroke=\"#020617\" stroke-width=\"1.8\"/>\n      <line x1=\"590\" y1=\"170\" x2=\"640\" y2=\"205\" stroke=\"#020617\" stroke-width=\"1.4\"/>\n      <!-- Metallic Bell Sound Waves -->\n      <path d=\"M 725 140 A 12 12 0 0 1 740 155\" fill=\"none\" stroke=\"#e2e8f0\" stroke-width=\"1.5\"/>\n      <path d=\"M 732 132 A 20 20 0 0 1 752 158\" fill=\"none\" stroke=\"#94a3b8\" stroke-width=\"1.2\"/>\n    </g>\n\n    <!-- Micro Pores Callout Inset Circle -->\n    <circle cx=\"535\" cy=\"180\" r=\"28\" fill=\"#090d16\" stroke=\"#38bdf8\" stroke-width=\"1.5\"/>\n    <!-- Micro Pores Pattern -->\n    <circle cx=\"525\" cy=\"172\" r=\"2\" fill=\"#38bdf8\"/>\n    <circle cx=\"540\" cy=\"170\" r=\"2.5\" fill=\"#38bdf8\"/>\n    <circle cx=\"530\" cy=\"184\" r=\"1.8\" fill=\"#38bdf8\"/>\n    <circle cx=\"545\" cy=\"182\" r=\"2.2\" fill=\"#38bdf8\"/>\n    <circle cx=\"536\" cy=\"192\" r=\"1.5\" fill=\"#38bdf8\"/>\n    <line x1=\"563\" y1=\"180\" x2=\"585\" y2=\"180\" stroke=\"#38bdf8\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n    <text x=\"535\" y=\"220\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7.5\" font-weight=\"bold\" text-anchor=\"middle\">다공성 활성 구조</text>\n\n    <!-- Technical Specs Table Rows -->\n    <g>\n      <!-- Row 1: Carbon Purity -->\n      <rect x=\"495\" y=\"235\" width=\"262\" height=\"24\" fill=\"#0f172a\" rx=\"3\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <text x=\"505\" y=\"251\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\">탄소 순도 (Carbon Purity)</text>\n      <text x=\"745\" y=\"251\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"end\">85 ~ 90% (고밀도 탄화)</text>\n\n      <!-- Row 2: Calorific Value & Smokeless -->\n      <rect x=\"495\" y=\"265\" width=\"262\" height=\"24\" fill=\"#0f172a\" rx=\"3\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <text x=\"505\" y=\"281\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\">연소 온도 &amp; 연기 유무</text>\n      <text x=\"745\" y=\"281\" fill=\"#f59e0b\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"end\">400~500℃ / 연기 0%</text>\n\n      <!-- Row 3: Multipurpose Utility -->\n      <rect x=\"495\" y=\"295\" width=\"262\" height=\"24\" fill=\"#0f172a\" rx=\"3\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <text x=\"505\" y=\"311\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\">생존 다목적 활용</text>\n      <text x=\"745\" y=\"311\" fill=\"#34d399\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"end\">식수 여과 / 불씨 보관</text>\n\n      <!-- Row 4: Acoustic Ring Test -->\n      <rect x=\"495\" y=\"325\" width=\"262\" height=\"24\" fill=\"#0f172a\" rx=\"3\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <text x=\"505\" y=\"341\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\">완성 판정 (Acoustic Ring)</text>\n      <text x=\"745\" y=\"341\" fill=\"#e2e8f0\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"end\">맑은 쇳소리 &amp; 은빛 광택</text>\n\n      <!-- Row 5: Yield per Batch -->\n      <rect x=\"495\" y=\"355\" width=\"262\" height=\"24\" fill=\"#0f172a\" rx=\"3\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <text x=\"505\" y=\"371\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\">1회 가동 수확량</text>\n      <text x=\"745\" y=\"371\" fill=\"#a78bfa\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"end\">고급 숯 3~5kg (참나무)</text>\n    </g>\n  </g>\n\n  <!-- Bottom Core Summary Banner -->\n  <rect x=\"28\" y=\"398\" width=\"744\" height=\"28\" fill=\"#111827\" rx=\"4\" stroke=\"#1f2937\" stroke-width=\"1.2\"/>\n  <rect x=\"28\" y=\"398\" width=\"4\" height=\"28\" fill=\"#10b981\" rx=\"1\"/>\n  <text x=\"400\" y=\"416\" fill=\"#34d399\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10.5\" font-weight=\"bold\" text-anchor=\"middle\">[핵심 공학] 흙구덩이 속 95% 공기 차단 ➔ 수분·타르만 방출하여 연기 없는 500℃ 고열 숯 생산</text>\n</svg>\n","content/svgs/pr09-step-01.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgS1\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#07080a\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1117\"/>\n      <stop offset=\"100%\" stop-color=\"#060709\"/>\n    </linearGradient>\n\n    <!-- Soil Strata Gradient -->\n    <linearGradient id=\"soilCutGrad\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#3e2723\"/>\n      <stop offset=\"40%\" stop-color=\"#2d1d18\"/>\n      <stop offset=\"100%\" stop-color=\"#1b120c\"/>\n    </linearGradient>\n\n    <!-- Pit Interior Shadow Gradient -->\n    <linearGradient id=\"pitWallGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#140d07\"/>\n      <stop offset=\"50%\" stop-color=\"#26170d\"/>\n      <stop offset=\"100%\" stop-color=\"#140d07\"/>\n    </linearGradient>\n\n    <!-- Ember & Fire Glow Radial Gradient -->\n    <radialGradient id=\"emberGlow\" cx=\"50%\" cy=\"50%\" r=\"50%\">\n      <stop offset=\"0%\" stop-color=\"#ff7a00\" stop-opacity=\"0.9\"/>\n      <stop offset=\"30%\" stop-color=\"#e63900\" stop-opacity=\"0.6\"/>\n      <stop offset=\"70%\" stop-color=\"#b31e00\" stop-opacity=\"0.2\"/>\n      <stop offset=\"100%\" stop-color=\"#140d07\" stop-opacity=\"0\"/>\n    </radialGradient>\n\n    <!-- Hot Charcoal Glow -->\n    <radialGradient id=\"charcoalRed\" cx=\"40%\" cy=\"40%\" r=\"60%\">\n      <stop offset=\"0%\" stop-color=\"#fffbeb\"/>\n      <stop offset=\"25%\" stop-color=\"#f59e0b\"/>\n      <stop offset=\"65%\" stop-color=\"#dc2626\"/>\n      <stop offset=\"100%\" stop-color=\"#450a0a\"/>\n    </radialGradient>\n\n    <!-- Drop Shadow Filter -->\n    <filter id=\"shadowS1\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"3\" flood-color=\"#000000\" flood-opacity=\"0.9\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Canvas -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgS1)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#232830\" stroke-width=\"1.2\"/>\n\n  <!-- Technical Corner Ticks -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n\n  <!-- Top Header Strip (Label 1) -->\n  <rect x=\"20\" y=\"16\" width=\"360\" height=\"20\" fill=\"#0f172a\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n  <rect x=\"20\" y=\"16\" width=\"3\" height=\"20\" fill=\"#f97316\"/>\n  <text x=\"30\" y=\"30\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" letter-spacing=\"0.5\">FIG. 01 // PIT EXCAVATION &amp; PRE-DRYING</text>\n\n  <!-- Ground Level Line & Soil Cross Section -->\n  <!-- Left Ground Surface -->\n  <path d=\"M 20 120 L 70 120\" stroke=\"#78716c\" stroke-width=\"2\"/>\n  <!-- Right Ground Surface -->\n  <path d=\"M 330 120 L 380 120\" stroke=\"#78716c\" stroke-width=\"2\"/>\n  <!-- Grass Blades on Surface -->\n  <path d=\"M 28 120 L 32 112 M 45 120 L 48 114 M 345 120 L 348 113 M 365 120 L 369 111\" stroke=\"#4ade80\" stroke-width=\"1.5\" stroke-linecap=\"round\"/>\n\n  <!-- Surrounding Soil Mass -->\n  <path d=\"M 20 120 L 70 120 L 130 310 L 20 310 Z\" fill=\"url(#soilCutGrad)\" opacity=\"0.6\"/>\n  <path d=\"M 380 120 L 330 120 L 270 310 L 380 310 Z\" fill=\"url(#soilCutGrad)\" opacity=\"0.6\"/>\n\n  <!-- Pit Excavation Cavity (Cone Shape) -->\n  <path d=\"M 70 120 Q 200 135 330 120 L 270 310 Q 200 315 130 310 Z\" fill=\"url(#pitWallGrad)\" stroke=\"#573824\" stroke-width=\"1.5\"/>\n\n  <!-- Pit Top Opening Rim Ellipse Guide -->\n  <ellipse cx=\"200\" cy=\"120\" rx=\"130\" ry=\"20\" fill=\"none\" stroke=\"#ea580c\" stroke-width=\"1.5\" stroke-dasharray=\"4 3\"/>\n\n  <!-- Dimension Indicator: Top Diameter 60cm (Label 2) -->\n  <g>\n    <line x1=\"70\" y1=\"88\" x2=\"330\" y2=\"88\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n    <path d=\"M 70 85 L 63 88 L 70 91 Z\" fill=\"#38bdf8\"/>\n    <path d=\"M 330 85 L 337 88 L 330 91 Z\" fill=\"#38bdf8\"/>\n    <line x1=\"70\" y1=\"83\" x2=\"70\" y2=\"115\" stroke=\"#38bdf8\" stroke-width=\"0.8\" stroke-dasharray=\"2 2\"/>\n    <line x1=\"330\" y1=\"83\" x2=\"330\" y2=\"115\" stroke=\"#38bdf8\" stroke-width=\"0.8\" stroke-dasharray=\"2 2\"/>\n    <rect x=\"100\" y=\"76\" width=\"200\" height=\"15\" fill=\"#0b1320\" rx=\"3\" stroke=\"#1e3a5f\" stroke-width=\"1\"/>\n    <text x=\"200\" y=\"87\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"middle\">상부 지름 60cm 원뿔형 흙구덩이</text>\n  </g>\n\n  <!-- Dimension Indicator: Depth 50cm & Bottom Diameter 30cm (Label 3) -->\n  <g>\n    <!-- Vertical Depth Line on Left -->\n    <line x1=\"45\" y1=\"120\" x2=\"45\" y2=\"310\" stroke=\"#f59e0b\" stroke-width=\"1.2\"/>\n    <path d=\"M 42 120 L 45 113 L 48 120 Z\" fill=\"#f59e0b\"/>\n    <path d=\"M 42 310 L 45 317 L 48 310 Z\" fill=\"#f59e0b\"/>\n    <line x1=\"40\" y1=\"120\" x2=\"68\" y2=\"120\" stroke=\"#f59e0b\" stroke-width=\"0.8\" stroke-dasharray=\"2 2\"/>\n    <line x1=\"40\" y1=\"310\" x2=\"128\" y2=\"310\" stroke=\"#f59e0b\" stroke-width=\"0.8\" stroke-dasharray=\"2 2\"/>\n    <!-- Bottom Rim Guide -->\n    <ellipse cx=\"200\" cy=\"310\" rx=\"70\" ry=\"10\" fill=\"none\" stroke=\"#d97706\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n    <rect x=\"52\" y=\"205\" width=\"168\" height=\"15\" fill=\"#1c1308\" rx=\"3\" stroke=\"#b45309\" stroke-width=\"1\"/>\n    <text x=\"136\" y=\"216\" fill=\"#f59e0b\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" text-anchor=\"middle\">깊이 50cm (바닥 지름 30cm)</text>\n  </g>\n\n  <!-- Bottom Pre-Drying Fire & Embers Bed -->\n  <!-- Fire Glow Backdrop -->\n  <ellipse cx=\"200\" cy=\"295\" rx=\"80\" ry=\"35\" fill=\"url(#emberGlow)\"/>\n\n  <!-- Burning Twigs & Glowing Charcoal Chunks -->\n  <g filter=\"url(#shadowS1)\">\n    <!-- Twigs -->\n    <line x1=\"145\" y1=\"305\" x2=\"255\" y2=\"295\" stroke=\"#78350f\" stroke-width=\"5\" stroke-linecap=\"round\"/>\n    <line x1=\"155\" y1=\"290\" x2=\"245\" y2=\"308\" stroke=\"#451a03\" stroke-width=\"4.5\" stroke-linecap=\"round\"/>\n    <line x1=\"170\" y1=\"310\" x2=\"230\" y2=\"288\" stroke=\"#9a3412\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n\n    <!-- Glowing Embers -->\n    <circle cx=\"175\" cy=\"298\" r=\"7\" fill=\"url(#charcoalRed)\"/>\n    <circle cx=\"195\" cy=\"302\" r=\"9\" fill=\"url(#charcoalRed)\"/>\n    <circle cx=\"215\" cy=\"295\" r=\"8\" fill=\"url(#charcoalRed)\"/>\n    <circle cx=\"188\" cy=\"289\" r=\"6\" fill=\"#fde047\"/>\n    <circle cx=\"205\" cy=\"291\" r=\"5\" fill=\"#fef08a\"/>\n\n    <!-- Flame Tongues -->\n    <path d=\"M 180 290 Q 185 270 190 282 Q 195 260 200 285 Q 205 265 212 288 Z\" fill=\"#f97316\" opacity=\"0.85\"/>\n    <path d=\"M 188 288 Q 193 273 197 282 Q 202 271 206 287 Z\" fill=\"#fef08a\" opacity=\"0.95\"/>\n  </g>\n\n  <!-- Heat Waves Rising -->\n  <path d=\"M 185 265 Q 180 245 190 230 Q 200 215 195 195\" fill=\"none\" stroke=\"#fb923c\" stroke-width=\"1.2\" stroke-dasharray=\"3 3\" opacity=\"0.6\"/>\n  <path d=\"M 215 265 Q 220 245 210 230 Q 200 215 205 195\" fill=\"none\" stroke=\"#fb923c\" stroke-width=\"1.2\" stroke-dasharray=\"3 3\" opacity=\"0.6\"/>\n\n  <!-- Label 4: Embers & Pre-Drying Bed -->\n  <g>\n    <path d=\"M 245 300 L 290 270\" stroke=\"#f97316\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n    <circle cx=\"245\" cy=\"300\" r=\"2.5\" fill=\"#f97316\"/>\n    <rect x=\"180\" y=\"258\" width=\"200\" height=\"15\" fill=\"#1c0f05\" rx=\"3\" stroke=\"#ea580c\" stroke-width=\"1\"/>\n    <text x=\"280\" y=\"269\" fill=\"#fb923c\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">바닥 초벌 건조 잔가지 &amp; 숯불 밑천</text>\n  </g>\n\n  <!-- Bottom Core Insight Briefing Box (Label 5) -->\n  <rect x=\"20\" y=\"348\" width=\"360\" height=\"26\" fill=\"#111827\" rx=\"4\" stroke=\"#1f2937\" stroke-width=\"1.2\"/>\n  <rect x=\"20\" y=\"348\" width=\"4\" height=\"26\" fill=\"#10b981\" rx=\"1\"/>\n  <text x=\"200\" y=\"364\" fill=\"#34d399\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">[핵심] 흙 습기 완전 건조 및 고온 불씨 형성</text>\n</svg>\n","content/svgs/pr09-step-02.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgS2\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#07080a\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1117\"/>\n      <stop offset=\"100%\" stop-color=\"#060709\"/>\n    </linearGradient>\n\n    <!-- Bark Gradient for Logs -->\n    <linearGradient id=\"oakBark\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#2d1d13\"/>\n      <stop offset=\"25%\" stop-color=\"#593b26\"/>\n      <stop offset=\"65%\" stop-color=\"#412918\"/>\n      <stop offset=\"100%\" stop-color=\"#1f130a\"/>\n    </linearGradient>\n\n    <!-- Log Top End Grain -->\n    <radialGradient id=\"oakEndGrain\" cx=\"50%\" cy=\"50%\" r=\"50%\">\n      <stop offset=\"0%\" stop-color=\"#e5c596\"/>\n      <stop offset=\"50%\" stop-color=\"#c99f67\"/>\n      <stop offset=\"85%\" stop-color=\"#936232\"/>\n      <stop offset=\"100%\" stop-color=\"#412918\"/>\n    </radialGradient>\n\n    <!-- Pit Wall Cutout -->\n    <linearGradient id=\"pitWall2\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#140d07\"/>\n      <stop offset=\"50%\" stop-color=\"#22140a\"/>\n      <stop offset=\"100%\" stop-color=\"#140d07\"/>\n    </linearGradient>\n\n    <!-- Heat Radial from Bottom -->\n    <radialGradient id=\"heatBottom\" cx=\"50%\" cy=\"100%\" r=\"70%\">\n      <stop offset=\"0%\" stop-color=\"#ea580c\" stop-opacity=\"0.8\"/>\n      <stop offset=\"35%\" stop-color=\"#c2410c\" stop-opacity=\"0.4\"/>\n      <stop offset=\"70%\" stop-color=\"#7c2d12\" stop-opacity=\"0.15\"/>\n      <stop offset=\"100%\" stop-color=\"#07080a\" stop-opacity=\"0\"/>\n    </radialGradient>\n\n    <filter id=\"shadowS2\" x=\"-15%\" y=\"-15%\" width=\"130%\" height=\"130%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"3\" flood-color=\"#000000\" flood-opacity=\"0.9\"/>\n    </filter>\n  </defs>\n\n  <!-- Background -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgS2)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#232830\" stroke-width=\"1.2\"/>\n\n  <!-- Technical Corner Ticks -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n\n  <!-- Top Header Strip (Label 1) -->\n  <rect x=\"20\" y=\"16\" width=\"360\" height=\"20\" fill=\"#0f172a\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n  <rect x=\"20\" y=\"16\" width=\"3\" height=\"20\" fill=\"#f97316\"/>\n  <text x=\"30\" y=\"30\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" letter-spacing=\"0.5\">FIG. 02 // DENSE VERTICAL TIMBER STACK</text>\n\n  <!-- Soil Cross Section & Pit Boundary -->\n  <path d=\"M 20 100 L 65 100 L 125 315 L 20 315 Z\" fill=\"#24150c\" opacity=\"0.6\"/>\n  <path d=\"M 380 100 L 335 100 L 275 315 L 380 315 Z\" fill=\"#24150c\" opacity=\"0.6\"/>\n  <path d=\"M 65 100 Q 200 115 335 100 L 275 315 Q 200 320 125 315 Z\" fill=\"url(#pitWall2)\" stroke=\"#452715\" stroke-width=\"1.2\"/>\n\n  <!-- Heat Glow from Bottom Embers -->\n  <path d=\"M 125 315 Q 200 320 275 315 L 260 250 Q 200 255 140 250 Z\" fill=\"url(#heatBottom)\"/>\n\n  <!-- ============================================== -->\n  <!-- VERTICAL LOGS (수직 적재 참나무 장작들) -->\n  <!-- ============================================== -->\n  <g filter=\"url(#shadowS2)\">\n    <!-- Back Layer Logs -->\n    <!-- Log B1 -->\n    <g>\n      <rect x=\"110\" y=\"125\" width=\"22\" height=\"175\" rx=\"3\" fill=\"url(#oakBark)\" stroke=\"#1a0f07\" stroke-width=\"0.8\"/>\n      <ellipse cx=\"121\" cy=\"125\" rx=\"11\" ry=\"4\" fill=\"url(#oakEndGrain)\" stroke=\"#3e2413\" stroke-width=\"0.6\"/>\n    </g>\n    <!-- Log B2 -->\n    <g>\n      <rect x=\"155\" y=\"120\" width=\"26\" height=\"185\" rx=\"3\" fill=\"url(#oakBark)\" stroke=\"#1a0f07\" stroke-width=\"0.8\"/>\n      <ellipse cx=\"168\" cy=\"120\" rx=\"13\" ry=\"5\" fill=\"url(#oakEndGrain)\" stroke=\"#3e2413\" stroke-width=\"0.6\"/>\n    </g>\n    <!-- Log B3 -->\n    <g>\n      <rect x=\"215\" y=\"122\" width=\"25\" height=\"182\" rx=\"3\" fill=\"url(#oakBark)\" stroke=\"#1a0f07\" stroke-width=\"0.8\"/>\n      <ellipse cx=\"227\" cy=\"122\" rx=\"12.5\" ry=\"4.5\" fill=\"url(#oakEndGrain)\" stroke=\"#3e2413\" stroke-width=\"0.6\"/>\n    </g>\n    <!-- Log B4 -->\n    <g>\n      <rect x=\"268\" y=\"128\" width=\"22\" height=\"172\" rx=\"3\" fill=\"url(#oakBark)\" stroke=\"#1a0f07\" stroke-width=\"0.8\"/>\n      <ellipse cx=\"279\" cy=\"128\" rx=\"11\" ry=\"4\" fill=\"url(#oakEndGrain)\" stroke=\"#3e2413\" stroke-width=\"0.6\"/>\n    </g>\n\n    <!-- Front Layer Main Logs (Prominent Wrist-Thick Oak) -->\n    <!-- Front Log 1 -->\n    <g>\n      <rect x=\"80\" y=\"135\" width=\"28\" height=\"165\" rx=\"3\" fill=\"url(#oakBark)\" stroke=\"#1a0f07\" stroke-width=\"1\"/>\n      <ellipse cx=\"94\" cy=\"135\" rx=\"14\" ry=\"5\" fill=\"url(#oakEndGrain)\" stroke=\"#3e2413\" stroke-width=\"0.8\"/>\n      <!-- Bark Details -->\n      <line x1=\"88\" y1=\"160\" x2=\"88\" y2=\"240\" stroke=\"#1f1207\" stroke-width=\"1.2\"/>\n      <line x1=\"98\" y1=\"180\" x2=\"98\" y2=\"270\" stroke=\"#1f1207\" stroke-width=\"1\"/>\n    </g>\n\n    <!-- Front Log 2 -->\n    <g>\n      <rect x=\"128\" y=\"130\" width=\"30\" height=\"175\" rx=\"3\" fill=\"url(#oakBark)\" stroke=\"#1a0f07\" stroke-width=\"1\"/>\n      <ellipse cx=\"143\" cy=\"130\" rx=\"15\" ry=\"5.5\" fill=\"url(#oakEndGrain)\" stroke=\"#3e2413\" stroke-width=\"0.8\"/>\n      <line x1=\"136\" y1=\"150\" x2=\"136\" y2=\"230\" stroke=\"#1f1207\" stroke-width=\"1.2\"/>\n      <line x1=\"148\" y1=\"170\" x2=\"148\" y2=\"260\" stroke=\"#1f1207\" stroke-width=\"1\"/>\n    </g>\n\n    <!-- Front Log 3 (Center) -->\n    <g>\n      <rect x=\"182\" y=\"125\" width=\"32\" height=\"182\" rx=\"3\" fill=\"url(#oakBark)\" stroke=\"#1a0f07\" stroke-width=\"1\"/>\n      <ellipse cx=\"198\" cy=\"125\" rx=\"16\" ry=\"6\" fill=\"url(#oakEndGrain)\" stroke=\"#3e2413\" stroke-width=\"0.8\"/>\n      <ellipse cx=\"198\" cy=\"125\" rx=\"8\" ry=\"3\" fill=\"none\" stroke=\"#78350f\" stroke-width=\"0.6\"/>\n      <line x1=\"190\" y1=\"155\" x2=\"190\" y2=\"250\" stroke=\"#1f1207\" stroke-width=\"1.2\"/>\n      <line x1=\"202\" y1=\"175\" x2=\"202\" y2=\"265\" stroke=\"#1f1207\" stroke-width=\"1\"/>\n    </g>\n\n    <!-- Front Log 4 -->\n    <g>\n      <rect x=\"238\" y=\"132\" width=\"30\" height=\"173\" rx=\"3\" fill=\"url(#oakBark)\" stroke=\"#1a0f07\" stroke-width=\"1\"/>\n      <ellipse cx=\"253\" cy=\"132\" rx=\"15\" ry=\"5.5\" fill=\"url(#oakEndGrain)\" stroke=\"#3e2413\" stroke-width=\"0.8\"/>\n      <line x1=\"246\" y1=\"155\" x2=\"246\" y2=\"235\" stroke=\"#1f1207\" stroke-width=\"1.2\"/>\n      <line x1=\"258\" y1=\"175\" x2=\"258\" y2=\"265\" stroke=\"#1f1207\" stroke-width=\"1\"/>\n    </g>\n\n    <!-- Front Log 5 (Right edge) -->\n    <g>\n      <rect x=\"290\" y=\"138\" width=\"26\" height=\"162\" rx=\"3\" fill=\"url(#oakBark)\" stroke=\"#1a0f07\" stroke-width=\"1\"/>\n      <ellipse cx=\"303\" cy=\"138\" rx=\"13\" ry=\"5\" fill=\"url(#oakEndGrain)\" stroke=\"#3e2413\" stroke-width=\"0.8\"/>\n      <line x1=\"298\" y1=\"165\" x2=\"298\" y2=\"245\" stroke=\"#1f1207\" stroke-width=\"1.2\"/>\n    </g>\n\n    <!-- ============================================== -->\n    <!-- SLENDER PACKING WEDGES (틈새 메운 잔가지들) -->\n    <!-- ============================================== -->\n    <!-- Wedge 1 (between 1 and 2) -->\n    <line x1=\"119\" y1=\"140\" x2=\"121\" y2=\"280\" stroke=\"#a16207\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n    <ellipse cx=\"119\" cy=\"140\" rx=\"3\" ry=\"1.5\" fill=\"#fef08a\"/>\n\n    <!-- Wedge 2 (between 2 and 3) -->\n    <line x1=\"172\" y1=\"135\" x2=\"175\" y2=\"285\" stroke=\"#a16207\" stroke-width=\"7\" stroke-linecap=\"round\"/>\n    <ellipse cx=\"172\" cy=\"135\" rx=\"3.5\" ry=\"1.8\" fill=\"#fef08a\"/>\n\n    <!-- Wedge 3 (between 3 and 4) -->\n    <line x1=\"227\" y1=\"138\" x2=\"225\" y2=\"282\" stroke=\"#a16207\" stroke-width=\"6.5\" stroke-linecap=\"round\"/>\n    <ellipse cx=\"227\" cy=\"138\" rx=\"3.2\" ry=\"1.6\" fill=\"#fef08a\"/>\n\n    <!-- Wedge 4 (between 4 and 5) -->\n    <line x1=\"280\" y1=\"142\" x2=\"278\" y2=\"278\" stroke=\"#a16207\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n    <ellipse cx=\"280\" cy=\"142\" rx=\"3\" ry=\"1.5\" fill=\"#fef08a\"/>\n  </g>\n\n  <!-- Lower Embers (Igniting the Base of Logs) -->\n  <g>\n    <circle cx=\"150\" cy=\"308\" r=\"6\" fill=\"#dc2626\"/>\n    <circle cx=\"185\" cy=\"312\" r=\"7\" fill=\"#ea580c\"/>\n    <circle cx=\"215\" cy=\"310\" r=\"8\" fill=\"#f59e0b\"/>\n    <circle cx=\"245\" cy=\"309\" r=\"6\" fill=\"#dc2626\"/>\n    <path d=\"M 175 310 Q 185 295 195 308\" fill=\"#fef08a\" opacity=\"0.8\"/>\n    <path d=\"M 205 310 Q 215 292 225 308\" fill=\"#fef08a\" opacity=\"0.8\"/>\n  </g>\n\n  <!-- Callout Label 2: Wrist-Thick Oak Stacking -->\n  <g>\n    <line x1=\"94\" y1=\"135\" x2=\"60\" y2=\"75\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n    <circle cx=\"94\" cy=\"135\" r=\"2.5\" fill=\"#38bdf8\"/>\n    <rect x=\"20\" y=\"65\" width=\"220\" height=\"16\" fill=\"#0b1320\" rx=\"3\" stroke=\"#1e3a5f\" stroke-width=\"1\"/>\n    <text x=\"130\" y=\"77\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">손목 굵기(5~8cm) 참나무 수직 적재</text>\n  </g>\n\n  <!-- Callout Label 3: Packing Wedges in Gaps -->\n  <g>\n    <line x1=\"172\" y1=\"170\" x2=\"275\" y2=\"85\" stroke=\"#facc15\" stroke-width=\"1.2\"/>\n    <circle cx=\"172\" cy=\"170\" r=\"2.5\" fill=\"#facc15\"/>\n    <rect x=\"200\" y=\"75\" width=\"180\" height=\"16\" fill=\"#1c1608\" rx=\"3\" stroke=\"#854d0e\" stroke-width=\"1\"/>\n    <text x=\"290\" y=\"87\" fill=\"#fde047\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">빈틈을 쐐기처럼 메운 잔가지</text>\n  </g>\n\n  <!-- Callout Label 4: Bottom Ember Heat Spreading -->\n  <g>\n    <line x1=\"200\" y1=\"305\" x2=\"270\" y2=\"285\" stroke=\"#fb923c\" stroke-width=\"1.2\"/>\n    <circle cx=\"200\" cy=\"305\" r=\"2.5\" fill=\"#fb923c\"/>\n    <rect x=\"180\" y=\"275\" width=\"190\" height=\"16\" fill=\"#1c0f05\" rx=\"3\" stroke=\"#ea580c\" stroke-width=\"1\"/>\n    <text x=\"275\" y=\"287\" fill=\"#fb923c\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">하단 초벌 불씨에서 번지는 열기</text>\n  </g>\n\n  <!-- Bottom Core Insight Briefing Box (Label 5) -->\n  <rect x=\"20\" y=\"348\" width=\"360\" height=\"26\" fill=\"#111827\" rx=\"4\" stroke=\"#1f2937\" stroke-width=\"1.2\"/>\n  <rect x=\"20\" y=\"348\" width=\"4\" height=\"26\" fill=\"#10b981\" rx=\"1\"/>\n  <text x=\"200\" y=\"364\" fill=\"#34d399\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">[핵심] 빈틈 최소화로 무산소 탄화 밀도 극대화</text>\n</svg>\n","content/svgs/pr09-step-03.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgS3\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#07080a\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1117\"/>\n      <stop offset=\"100%\" stop-color=\"#060709\"/>\n    </linearGradient>\n\n    <!-- Clay & Mud Mound Gradient -->\n    <linearGradient id=\"mudSealGrad\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#543823\"/>\n      <stop offset=\"40%\" stop-color=\"#3b2314\"/>\n      <stop offset=\"100%\" stop-color=\"#241409\"/>\n    </linearGradient>\n\n    <!-- Sod / Turf Grass Texture -->\n    <linearGradient id=\"sodGrassGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#2d4a22\"/>\n      <stop offset=\"50%\" stop-color=\"#3f6212\"/>\n      <stop offset=\"100%\" stop-color=\"#2d4a22\"/>\n    </linearGradient>\n\n    <!-- Early White Steam Smoke Radial -->\n    <radialGradient id=\"whiteSmoke\" cx=\"50%\" cy=\"80%\" r=\"70%\">\n      <stop offset=\"0%\" stop-color=\"#f1f5f9\" stop-opacity=\"0.85\"/>\n      <stop offset=\"50%\" stop-color=\"#cbd5e1\" stop-opacity=\"0.5\"/>\n      <stop offset=\"80%\" stop-color=\"#94a3b8\" stop-opacity=\"0.2\"/>\n      <stop offset=\"100%\" stop-color=\"#07080a\" stop-opacity=\"0\"/>\n    </radialGradient>\n\n    <filter id=\"shadowS3\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"5\" stdDeviation=\"4\" flood-color=\"#000000\" flood-opacity=\"0.85\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Canvas -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgS3)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#232830\" stroke-width=\"1.2\"/>\n\n  <!-- Technical Corner Ticks -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n\n  <!-- Top Header Strip (Label 1) -->\n  <rect x=\"20\" y=\"16\" width=\"360\" height=\"20\" fill=\"#0f172a\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n  <rect x=\"20\" y=\"16\" width=\"3\" height=\"20\" fill=\"#f97316\"/>\n  <text x=\"30\" y=\"30\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" letter-spacing=\"0.5\">FIG. 03 // MULTI-LAYER ANAEROBIC SEAL</text>\n\n  <!-- Ground Line & Surrounding Earth -->\n  <path d=\"M 20 185 L 65 185 L 125 325 L 20 325 Z\" fill=\"#20130a\" opacity=\"0.6\"/>\n  <path d=\"M 380 185 L 335 185 L 275 325 L 380 325 Z\" fill=\"#20130a\" opacity=\"0.6\"/>\n\n  <!-- Pit Cavity & Smoldering Internal Wood Stack -->\n  <path d=\"M 65 185 L 125 325 Q 200 330 275 325 L 335 185 Z\" fill=\"#140a04\" stroke=\"#3d210f\" stroke-width=\"1.2\"/>\n  <!-- Internal Timber Silhouettes (Dim Smoldering) -->\n  <path d=\"M 135 320 L 130 190 L 160 190 L 165 320 Z\" fill=\"#2a1608\" opacity=\"0.7\"/>\n  <path d=\"M 175 322 L 175 190 L 205 190 L 205 322 Z\" fill=\"#381d0b\" opacity=\"0.8\"/>\n  <path d=\"M 220 322 L 225 190 L 255 190 L 250 322 Z\" fill=\"#2a1608\" opacity=\"0.7\"/>\n  <!-- Internal Ember Glow at bottom -->\n  <ellipse cx=\"200\" cy=\"320\" rx=\"60\" ry=\"8\" fill=\"#ea580c\" opacity=\"0.4\"/>\n\n  <!-- ============================================== -->\n  <!-- MULTI-LAYER SEAL SYSTEM (상부 덮개 구조) -->\n  <!-- ============================================== -->\n\n  <!-- Layer 1: Wood Lattice Frame (격자 나뭇가지틀) -->\n  <g stroke=\"#854d0e\" stroke-width=\"5\" stroke-linecap=\"round\">\n    <!-- Horizontal Crossbars -->\n    <line x1=\"75\" y1=\"188\" x2=\"325\" y2=\"188\"/>\n    <line x1=\"85\" y1=\"180\" x2=\"315\" y2=\"180\"/>\n    <!-- Angled Cross Beams -->\n    <line x1=\"110\" y1=\"193\" x2=\"160\" y2=\"175\"/>\n    <line x1=\"180\" y1=\"193\" x2=\"230\" y2=\"175\"/>\n    <line x1=\"250\" y1=\"193\" x2=\"300\" y2=\"175\"/>\n  </g>\n\n  <!-- Layer 2: Broad Leaves Layer (넓은 나뭇잎 차단층) -->\n  <g fill=\"#4d7c0f\" opacity=\"0.85\">\n    <ellipse cx=\"105\" cy=\"178\" rx=\"25\" ry=\"7\" transform=\"rotate(-5 105 178)\"/>\n    <ellipse cx=\"145\" cy=\"174\" rx=\"28\" ry=\"8\" transform=\"rotate(3 145 174)\"/>\n    <ellipse cx=\"195\" cy=\"172\" rx=\"30\" ry=\"8\"/>\n    <ellipse cx=\"245\" cy=\"174\" rx=\"28\" ry=\"8\" transform=\"rotate(-3 245 174)\"/>\n    <ellipse cx=\"285\" cy=\"178\" rx=\"25\" ry=\"7\" transform=\"rotate(5 285 178)\"/>\n  </g>\n\n  <!-- Layer 3: Thick Mud & Clay Mound with Turf Grass on Top -->\n  <g filter=\"url(#shadowS3)\">\n    <!-- Domed Mud Seal (10cm thick mound) -->\n    <path d=\"M 50 185 Q 200 120 350 185 Q 200 160 50 185 Z\" fill=\"url(#mudSealGrad)\" stroke=\"#452715\" stroke-width=\"1.5\"/>\n\n    <!-- Sod / Turf Grass Layer on the Dome Surface -->\n    <path d=\"M 55 184 Q 200 122 345 184 Q 200 135 55 184 Z\" fill=\"url(#sodGrassGrad)\" opacity=\"0.9\"/>\n    <!-- Grass Fringe along Dome -->\n    <path d=\"M 75 175 L 77 167 M 105 160 L 108 152 M 140 146 L 142 138 M 255 146 L 257 138 M 290 160 L 292 153 M 325 175 L 327 168\" stroke=\"#86efac\" stroke-width=\"1.5\" stroke-linecap=\"round\"/>\n  </g>\n\n  <!-- Center Chimney Vent (중앙 배기 굴뚝) -->\n  <g filter=\"url(#shadowS3)\">\n    <!-- Chimney Collar (진흙 굴뚝 테두리) -->\n    <path d=\"M 182 134 L 182 118 Q 200 115 218 118 L 218 134 Z\" fill=\"#3e2314\" stroke=\"#5c381e\" stroke-width=\"1.2\"/>\n    <ellipse cx=\"200\" cy=\"118\" rx=\"18\" ry=\"5\" fill=\"#140a04\" stroke=\"#ea580c\" stroke-width=\"1\"/>\n  </g>\n\n  <!-- Billowing White Smoke from Chimney -->\n  <g>\n    <!-- Smoke Puffs -->\n    <circle cx=\"200\" cy=\"98\" r=\"14\" fill=\"url(#whiteSmoke)\"/>\n    <circle cx=\"212\" cy=\"78\" r=\"20\" fill=\"url(#whiteSmoke)\"/>\n    <circle cx=\"192\" cy=\"60\" r=\"26\" fill=\"url(#whiteSmoke)\"/>\n    <circle cx=\"218\" cy=\"42\" r=\"32\" fill=\"url(#whiteSmoke)\"/>\n  </g>\n\n  <!-- Air Intake Vents (하단 흡기 구멍 2개) -->\n  <!-- Left Intake -->\n  <g>\n    <ellipse cx=\"68\" cy=\"190\" rx=\"5\" ry=\"8\" fill=\"#090502\" stroke=\"#ea580c\" stroke-width=\"1\"/>\n    <!-- Air Flow Arrow Inward -->\n    <path d=\"M 32 190 L 58 190\" stroke=\"#38bdf8\" stroke-width=\"1.8\" stroke-dasharray=\"3 2\"/>\n    <polygon points=\"63,190 56,187 56,193\" fill=\"#38bdf8\"/>\n  </g>\n  <!-- Right Intake -->\n  <g>\n    <ellipse cx=\"332\" cy=\"190\" rx=\"5\" ry=\"8\" fill=\"#090502\" stroke=\"#ea580c\" stroke-width=\"1\"/>\n    <!-- Air Flow Arrow Inward -->\n    <path d=\"M 368 190 L 342 190\" stroke=\"#38bdf8\" stroke-width=\"1.8\" stroke-dasharray=\"3 2\"/>\n    <polygon points=\"337,190 344,187 344,193\" fill=\"#38bdf8\"/>\n  </g>\n\n  <!-- ============================================== -->\n  <!-- CALLOUT LABELS (2, 3, 4, 5) -->\n  <!-- ============================================== -->\n\n  <!-- Label 2: Lattice & Leaf Support Layer -->\n  <g>\n    <line x1=\"110\" y1=\"180\" x2=\"60\" y2=\"235\" stroke=\"#a3e635\" stroke-width=\"1.2\"/>\n    <circle cx=\"110\" cy=\"180\" r=\"2.5\" fill=\"#a3e635\"/>\n    <rect x=\"20\" y=\"235\" width=\"180\" height=\"16\" fill=\"#141f0d\" rx=\"3\" stroke=\"#4d7c0f\" stroke-width=\"1\"/>\n    <text x=\"110\" y=\"247\" fill=\"#bef264\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">격자 가지틀 + 넓은 잎 지지층</text>\n  </g>\n\n  <!-- Label 3: 10cm Mud & Turf Sod Seal -->\n  <g>\n    <line x1=\"280\" y1=\"150\" x2=\"310\" y2=\"95\" stroke=\"#facc15\" stroke-width=\"1.2\"/>\n    <circle cx=\"280\" cy=\"150\" r=\"2.5\" fill=\"#facc15\"/>\n    <rect x=\"180\" y=\"85\" width=\"200\" height=\"16\" fill=\"#1c1608\" rx=\"3\" stroke=\"#854d0e\" stroke-width=\"1\"/>\n    <text x=\"280\" y=\"97\" fill=\"#fde047\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">10cm 젖은 진흙 &amp; 잔디 뗏장 덮개</text>\n  </g>\n\n  <!-- Label 4: Two Intake Vents (Finger-thick) -->\n  <g>\n    <line x1=\"68\" y1=\"198\" x2=\"100\" y2=\"280\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n    <circle cx=\"68\" cy=\"198\" r=\"2.5\" fill=\"#38bdf8\"/>\n    <rect x=\"20\" y=\"280\" width=\"195\" height=\"16\" fill=\"#081524\" rx=\"3\" stroke=\"#0284c7\" stroke-width=\"1\"/>\n    <text x=\"117\" y=\"292\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">하단 흡기 구멍 2개 (손가락 굵기)</text>\n  </g>\n\n  <!-- Label 5: Center Chimney Vent -->\n  <g>\n    <line x1=\"218\" y1=\"125\" x2=\"270\" y2=\"235\" stroke=\"#fb923c\" stroke-width=\"1.2\"/>\n    <circle cx=\"218\" cy=\"125\" r=\"2.5\" fill=\"#fb923c\"/>\n    <rect x=\"210\" y=\"235\" width=\"170\" height=\"16\" fill=\"#1c0f05\" rx=\"3\" stroke=\"#ea580c\" stroke-width=\"1\"/>\n    <text x=\"295\" y=\"247\" fill=\"#fb923c\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">중앙 배기 굴뚝 (주먹 크기)</text>\n  </g>\n\n  <!-- Bottom Core Insight Briefing Box (Label 6) -->\n  <rect x=\"20\" y=\"348\" width=\"360\" height=\"26\" fill=\"#111827\" rx=\"4\" stroke=\"#1f2937\" stroke-width=\"1.2\"/>\n  <rect x=\"20\" y=\"348\" width=\"4\" height=\"26\" fill=\"#10b981\" rx=\"1\"/>\n  <text x=\"200\" y=\"364\" fill=\"#34d399\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">[핵심] 산소 95% 차단 불완전 연소 가마 완성</text>\n</svg>\n","content/svgs/pr09-step-04.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgS4\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#07080a\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1117\"/>\n      <stop offset=\"100%\" stop-color=\"#060709\"/>\n    </linearGradient>\n\n    <!-- Thick White Steam Smoke -->\n    <radialGradient id=\"denseWhiteSmoke\" cx=\"50%\" cy=\"50%\" r=\"50%\">\n      <stop offset=\"0%\" stop-color=\"#ffffff\" stop-opacity=\"0.95\"/>\n      <stop offset=\"50%\" stop-color=\"#e2e8f0\" stop-opacity=\"0.7\"/>\n      <stop offset=\"85%\" stop-color=\"#94a3b8\" stop-opacity=\"0.3\"/>\n      <stop offset=\"100%\" stop-color=\"#07080a\" stop-opacity=\"0\"/>\n    </radialGradient>\n\n    <!-- Faint Pure Blue Pyrolysis Smoke -->\n    <radialGradient id=\"faintBlueSmoke\" cx=\"50%\" cy=\"50%\" r=\"50%\">\n      <stop offset=\"0%\" stop-color=\"#38bdf8\" stop-opacity=\"0.8\"/>\n      <stop offset=\"40%\" stop-color=\"#0284c7\" stop-opacity=\"0.45\"/>\n      <stop offset=\"80%\" stop-color=\"#0369a1\" stop-opacity=\"0.15\"/>\n      <stop offset=\"100%\" stop-color=\"#07080a\" stop-opacity=\"0\"/>\n    </radialGradient>\n\n    <!-- Metallic Carbon Charcoal Gradient -->\n    <linearGradient id=\"charcoalLump\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#334155\"/>\n      <stop offset=\"25%\" stop-color=\"#1e293b\"/>\n      <stop offset=\"60%\" stop-color=\"#0f172a\"/>\n      <stop offset=\"100%\" stop-color=\"#020617\"/>\n    </linearGradient>\n\n    <!-- Charcoal Silver Sheen -->\n    <linearGradient id=\"silverSheen\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#475569\"/>\n      <stop offset=\"50%\" stop-color=\"#94a3b8\"/>\n      <stop offset=\"100%\" stop-color=\"#334155\"/>\n    </linearGradient>\n\n    <filter id=\"shadowS4\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"4\" flood-color=\"#000000\" flood-opacity=\"0.9\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Canvas -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgS4)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#232830\" stroke-width=\"1.2\"/>\n\n  <!-- Technical Corner Ticks -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n\n  <!-- Top Header Strip (Label 1) -->\n  <rect x=\"20\" y=\"16\" width=\"360\" height=\"20\" fill=\"#0f172a\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n  <rect x=\"20\" y=\"16\" width=\"3\" height=\"20\" fill=\"#f97316\"/>\n  <text x=\"30\" y=\"30\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" letter-spacing=\"0.5\">FIG. 04 // SMOKE PHASE &amp; CHARCOAL HARVEST</text>\n\n  <!-- ============================================== -->\n  <!-- TOP HALF: SMOKE PHASE COMPARISON PANEL -->\n  <!-- ============================================== -->\n  <!-- Left Side: Phase 1 Dense White Steam Smoke -->\n  <g>\n    <!-- Background Box -->\n    <rect x=\"20\" y=\"44\" width=\"175\" height=\"110\" fill=\"#0b1017\" rx=\"4\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n    <!-- Chimney Mini Silhouette -->\n    <path d=\"M 85 140 L 85 125 L 115 125 L 115 140 Z\" fill=\"#2d1d13\" stroke=\"#452715\" stroke-width=\"1\"/>\n    <ellipse cx=\"100\" cy=\"125\" rx=\"15\" ry=\"4\" fill=\"#140a04\"/>\n\n    <!-- Billowing Dense White Steam Clouds -->\n    <circle cx=\"100\" cy=\"105\" r=\"14\" fill=\"url(#denseWhiteSmoke)\"/>\n    <circle cx=\"85\" cy=\"85\" r=\"18\" fill=\"url(#denseWhiteSmoke)\"/>\n    <circle cx=\"115\" cy=\"80\" r=\"16\" fill=\"url(#denseWhiteSmoke)\"/>\n    <circle cx=\"95\" cy=\"62\" r=\"20\" fill=\"url(#denseWhiteSmoke)\"/>\n\n    <!-- Label 2: Phase 1 White Smoke -->\n    <rect x=\"24\" y=\"48\" width=\"167\" height=\"15\" fill=\"#030712\" rx=\"3\" stroke=\"#475569\" stroke-width=\"1\"/>\n    <text x=\"107\" y=\"59\" fill=\"#f8fafc\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7.5\" font-weight=\"bold\" text-anchor=\"middle\">1단계: 짙은 백색 연기 (수분 증발)</text>\n  </g>\n\n  <!-- Transition Arrow -->\n  <g>\n    <path d=\"M 198 95 L 206 95\" stroke=\"#f97316\" stroke-width=\"2\"/>\n    <polygon points=\"208,95 204,91 204,99\" fill=\"#f97316\"/>\n  </g>\n\n  <!-- Right Side: Phase 2 Faint Blue Pyrolysis Smoke -->\n  <g>\n    <!-- Background Box -->\n    <rect x=\"210\" y=\"44\" width=\"170\" height=\"110\" fill=\"#081422\" rx=\"4\" stroke=\"#0369a1\" stroke-width=\"1\"/>\n    <!-- Chimney Mini Silhouette -->\n    <path d=\"M 280 140 L 280 125 L 310 125 L 310 140 Z\" fill=\"#2d1d13\" stroke=\"#452715\" stroke-width=\"1\"/>\n    <ellipse cx=\"295\" cy=\"125\" rx=\"15\" ry=\"4\" fill=\"#140a04\"/>\n\n    <!-- Delicate Wisps of Blue Pyrolysis Smoke -->\n    <circle cx=\"295\" cy=\"108\" r=\"12\" fill=\"url(#faintBlueSmoke)\"/>\n    <circle cx=\"282\" cy=\"88\" r=\"15\" fill=\"url(#faintBlueSmoke)\"/>\n    <circle cx=\"308\" cy=\"85\" r=\"14\" fill=\"url(#faintBlueSmoke)\"/>\n    <circle cx=\"292\" cy=\"65\" r=\"16\" fill=\"url(#faintBlueSmoke)\"/>\n\n    <!-- Label 3: Phase 2 Blue Smoke -->\n    <rect x=\"214\" y=\"48\" width=\"162\" height=\"15\" fill=\"#021d33\" rx=\"3\" stroke=\"#0284c7\" stroke-width=\"1\"/>\n    <text x=\"295\" y=\"59\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7.5\" font-weight=\"bold\" text-anchor=\"middle\">2단계: 옅은 청색 연기 (탄화 완료)</text>\n  </g>\n\n  <!-- ============================================== -->\n  <!-- MIDDLE: HERMETIC MUD PLUG SEAL -->\n  <!-- ============================================== -->\n  <g filter=\"url(#shadowS4)\">\n    <!-- Plugged Kiln Dome Mound -->\n    <path d=\"M 40 215 Q 200 170 360 215 L 330 255 Q 200 260 70 255 Z\" fill=\"#2d1a0e\" stroke=\"#452715\" stroke-width=\"1.2\"/>\n\n    <!-- Mud Plug Ball on Chimney (진흙 반죽으로 꽉 틀어막은 마개) -->\n    <circle cx=\"200\" cy=\"188\" r=\"16\" fill=\"#543823\" stroke=\"#854d0e\" stroke-width=\"1.5\"/>\n    <ellipse cx=\"200\" cy=\"185\" rx=\"14\" ry=\"10\" fill=\"#3e2314\"/>\n    <!-- Sealed Air Intake Plugs -->\n    <ellipse cx=\"65\" cy=\"225\" rx=\"7\" ry=\"10\" fill=\"#543823\" stroke=\"#854d0e\" stroke-width=\"1\"/>\n    <ellipse cx=\"335\" cy=\"225\" rx=\"7\" ry=\"10\" fill=\"#543823\" stroke=\"#854d0e\" stroke-width=\"1\"/>\n\n    <!-- Lock Clamps / Cooling Ice Thermometer Icon Vector -->\n    <rect x=\"188\" y=\"178\" width=\"24\" height=\"20\" rx=\"3\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"1\" opacity=\"0.9\"/>\n    <!-- Padlock Shackle / 100% Hermetic Symbol -->\n    <path d=\"M 194 178 L 194 172 A 6 6 0 0 1 206 172 L 206 178\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"1.5\"/>\n    <circle cx=\"200\" cy=\"187\" r=\"2\" fill=\"#38bdf8\"/>\n  </g>\n\n  <!-- Label 4: Hermetic Mud Seal & Cooling -->\n  <g>\n    <rect x=\"75\" y=\"215\" width=\"250\" height=\"16\" fill=\"#180e06\" rx=\"3\" stroke=\"#b45309\" stroke-width=\"1\"/>\n    <text x=\"200\" y=\"227\" fill=\"#fbbf24\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">모든 구멍 진흙 밀폐 후 완전 냉각</text>\n  </g>\n\n  <!-- ============================================== -->\n  <!-- BOTTOM: HARVESTED METALLIC HARDWOOD CHARCOAL -->\n  <!-- ============================================== -->\n  <g filter=\"url(#shadowS4)\">\n    <!-- Charcoal Log Chunk 1 (Large Center) -->\n    <g>\n      <polygon points=\"120,305 155,275 220,280 235,310 180,335 130,330\" fill=\"url(#charcoalLump)\" stroke=\"#475569\" stroke-width=\"1\"/>\n      <!-- Carbonized Facets & Silver Sheen Reflections -->\n      <polygon points=\"155,275 220,280 200,305 145,298\" fill=\"url(#silverSheen)\" opacity=\"0.25\"/>\n      <line x1=\"165\" y1=\"285\" x2=\"195\" y2=\"320\" stroke=\"#020617\" stroke-width=\"1.5\"/>\n      <line x1=\"140\" y1=\"305\" x2=\"175\" y2=\"325\" stroke=\"#020617\" stroke-width=\"1.2\"/>\n      <!-- Metallic Ring Sound Wave Icon -->\n      <path d=\"M 235,285 A 8 8 0 0 1 245,295\" fill=\"none\" stroke=\"#e2e8f0\" stroke-width=\"1.2\"/>\n      <path d=\"M 240,280 A 14 14 0 0 1 254,298\" fill=\"none\" stroke=\"#94a3b8\" stroke-width=\"1\"/>\n    </g>\n\n    <!-- Charcoal Chunk 2 (Left) -->\n    <g>\n      <polygon points=\"65,315 95,295 130,305 120,335 80,340\" fill=\"url(#charcoalLump)\" stroke=\"#475569\" stroke-width=\"1\"/>\n      <polygon points=\"95,295 130,305 115,320 85,312\" fill=\"url(#silverSheen)\" opacity=\"0.3\"/>\n      <line x1=\"85\" y1=\"310\" x2=\"105\" y2=\"335\" stroke=\"#020617\" stroke-width=\"1\"/>\n    </g>\n\n    <!-- Charcoal Chunk 3 (Right) -->\n    <g>\n      <polygon points=\"230,310 265,290 305,302 295,335 250,338\" fill=\"url(#charcoalLump)\" stroke=\"#475569\" stroke-width=\"1\"/>\n      <polygon points=\"265,290 305,302 285,320 250,310\" fill=\"url(#silverSheen)\" opacity=\"0.3\"/>\n      <line x1=\"260\" y1=\"305\" x2=\"280\" y2=\"330\" stroke=\"#020617\" stroke-width=\"1\"/>\n    </g>\n\n    <!-- Porous Micro-pores Detail (다공성 미세기공 점들) -->\n    <circle cx=\"170\" cy=\"310\" r=\"1\" fill=\"#475569\"/>\n    <circle cx=\"185\" cy=\"305\" r=\"1.2\" fill=\"#475569\"/>\n    <circle cx=\"195\" cy=\"315\" r=\"1\" fill=\"#475569\"/>\n    <circle cx=\"105\" cy=\"320\" r=\"1\" fill=\"#475569\"/>\n    <circle cx=\"270\" cy=\"318\" r=\"1\" fill=\"#475569\"/>\n  </g>\n\n  <!-- Label 5: Harvested Metallic Dense Oak Charcoal -->\n  <g>\n    <rect x=\"75\" y=\"270\" width=\"250\" height=\"16\" fill=\"#090d16\" rx=\"3\" stroke=\"#334155\" stroke-width=\"1\"/>\n    <text x=\"200\" y=\"282\" fill=\"#e2e8f0\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">쇳소리 나는 고밀도 참나무 숯 수확</text>\n  </g>\n\n  <!-- Bottom Core Insight Briefing Box (Label 6) -->\n  <rect x=\"20\" y=\"348\" width=\"360\" height=\"26\" fill=\"#111827\" rx=\"4\" stroke=\"#1f2937\" stroke-width=\"1.2\"/>\n  <rect x=\"20\" y=\"348\" width=\"4\" height=\"26\" fill=\"#10b981\" rx=\"1\"/>\n  <text x=\"200\" y=\"364\" fill=\"#34d399\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">[핵심] 푸른 연기 즉시 밀폐 &amp; 잔열 완전 냉각</text>\n</svg>\n","content/svgs/pr10-outcome.svg":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\" class=\"w-full h-auto\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgOut10\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#07080a\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1218\"/>\n      <stop offset=\"100%\" stop-color=\"#050709\"/>\n    </linearGradient>\n\n    <!-- Amber Resin Radial Gradient -->\n    <radialGradient id=\"amberGlowOut\" cx=\"45%\" cy=\"40%\" r=\"55%\">\n      <stop offset=\"0%\" stop-color=\"#fef08a\"/>\n      <stop offset=\"35%\" stop-color=\"#fde047\"/>\n      <stop offset=\"70%\" stop-color=\"#f59e0b\"/>\n      <stop offset=\"100%\" stop-color=\"#b45309\"/>\n    </radialGradient>\n\n    <!-- Obsidian Hardened Pitch Gradient -->\n    <radialGradient id=\"obsidianPitchOut\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#52525b\"/>\n      <stop offset=\"30%\" stop-color=\"#27272a\"/>\n      <stop offset=\"70%\" stop-color=\"#18181b\"/>\n      <stop offset=\"100%\" stop-color=\"#09090b\"/>\n    </radialGradient>\n\n    <!-- Seashell Gradient -->\n    <linearGradient id=\"shellGradOut\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#f8fafc\"/>\n      <stop offset=\"40%\" stop-color=\"#e2e8f0\"/>\n      <stop offset=\"70%\" stop-color=\"#cbd5e1\"/>\n      <stop offset=\"100%\" stop-color=\"#94a3b8\"/>\n    </linearGradient>\n\n    <!-- Wood Stick Gradient -->\n    <linearGradient id=\"woodGradOut\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#78350f\"/>\n      <stop offset=\"50%\" stop-color=\"#9a3412\"/>\n      <stop offset=\"100%\" stop-color=\"#451a03\"/>\n    </linearGradient>\n\n    <!-- Stone Axe Blade Gradient -->\n    <linearGradient id=\"axeStoneGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#cbd5e1\"/>\n      <stop offset=\"40%\" stop-color=\"#64748b\"/>\n      <stop offset=\"100%\" stop-color=\"#1e293b\"/>\n    </linearGradient>\n\n    <!-- Drop Shadow Filter -->\n    <filter id=\"shadowOut10\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"6\" stdDeviation=\"5\" flood-color=\"#000000\" flood-opacity=\"0.95\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Canvas -->\n  <rect width=\"800\" height=\"450\" fill=\"url(#bgOut10)\"/>\n  <rect x=\"12\" y=\"12\" width=\"776\" height=\"426\" fill=\"none\" stroke=\"#232830\" stroke-width=\"1.2\"/>\n\n  <!-- Technical Corner Ticks -->\n  <path d=\"M 20 28 L 36 28 M 28 20 L 28 36\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 780 28 L 764 28 M 772 20 L 772 36\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 20 422 L 36 422 M 28 414 L 28 430\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 780 422 L 764 422 M 772 414 L 772 430\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n\n  <!-- Top Technical Header Strip -->\n  <rect x=\"28\" y=\"22\" width=\"744\" height=\"24\" fill=\"#0f172a\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n  <rect x=\"28\" y=\"22\" width=\"4\" height=\"24\" fill=\"#f59e0b\"/>\n  <text x=\"42\" y=\"38\" fill=\"#e2e8f0\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" font-weight=\"bold\" letter-spacing=\"0.5\">PR-10 // PINE RESIN PURIFICATION &amp; PITCH GLUE (소나무 송진 항균 연고 및 만능 방수 결속 막대 제원)</text>\n\n  <!-- LEFT HALF: Physical Dual Assets & Axe Lashing Detail -->\n  <g>\n    <!-- Ground / Slate Work Table -->\n    <rect x=\"35\" y=\"335\" width=\"425\" height=\"48\" fill=\"#141a23\" stroke=\"#252f3e\" stroke-width=\"1\"/>\n    <line x1=\"35\" y1=\"335\" x2=\"460\" y2=\"335\" stroke=\"#38bdf8\" stroke-width=\"1.2\" opacity=\"0.6\"/>\n\n    <!-- 1. Antiseptic Amber Ointment in Clam Shell -->\n    <g filter=\"url(#shadowOut10)\">\n      <path d=\"M 55 310 C 60 250, 180 250, 190 310 C 160 330, 85 330, 55 310 Z\" fill=\"url(#shellGradOut)\" stroke=\"#475569\" stroke-width=\"1.5\"/>\n      <path d=\"M 122 322 L 75 265 M 122 322 L 100 258 M 122 322 L 122 255 M 122 322 L 145 258 M 122 322 L 170 265\" stroke=\"#94a3b8\" stroke-width=\"1\" fill=\"none\" opacity=\"0.6\"/>\n      <!-- Pure Amber Ointment Pool -->\n      <ellipse cx=\"122\" cy=\"298\" rx=\"48\" ry=\"19\" fill=\"url(#amberGlowOut)\" stroke=\"#b45309\" stroke-width=\"1.2\"/>\n      <circle cx=\"105\" cy=\"295\" r=\"3.5\" fill=\"#ffffff\" opacity=\"0.8\"/>\n      <path d=\"M 85 294 Q 120 304 155 294\" stroke=\"#ffffff\" stroke-width=\"1.5\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.6\"/>\n    </g>\n\n    <!-- Annotation: Antiseptic Ointment -->\n    <rect x=\"42\" y=\"70\" width=\"165\" height=\"18\" fill=\"#1c1308\" rx=\"3\" stroke=\"#b45309\" stroke-width=\"1\"/>\n    <text x=\"124\" y=\"83\" fill=\"#fbbf24\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">천연 상처 소독 연고 (30ml)</text>\n    <line x1=\"122\" y1=\"90\" x2=\"122\" y2=\"280\" stroke=\"#f59e0b\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n\n    <!-- 2. Solid Pitch Stick (Stick with Obsidian Black Pitch Bulb) -->\n    <g filter=\"url(#shadowOut10)\">\n      <path d=\"M 235 325 L 420 220\" stroke=\"url(#woodGradOut)\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n      <ellipse cx=\"230\" cy=\"325\" rx=\"32\" ry=\"24\" fill=\"url(#obsidianPitchOut)\" stroke=\"#3f3f46\" stroke-width=\"1.8\"/>\n      <circle cx=\"222\" cy=\"320\" r=\"20\" fill=\"#09090b\"/>\n      <!-- Specular Reflection on Obsidian Surface -->\n      <path d=\"M 210 310 Q 235 315 248 332\" stroke=\"#ffffff\" stroke-width=\"2.5\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.85\"/>\n      <circle cx=\"212\" cy=\"318\" r=\"4\" fill=\"#ffffff\" opacity=\"0.75\"/>\n    </g>\n\n    <!-- Annotation: Pitch Stick -->\n    <rect x=\"235\" y=\"115\" width=\"180\" height=\"18\" fill=\"#18181b\" rx=\"3\" stroke=\"#3f3f46\" stroke-width=\"1\"/>\n    <text x=\"325\" y=\"128\" fill=\"#e4e4e7\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">방수 결속 수지 막대 (Pitch Stick)</text>\n    <line x1=\"260\" y1=\"135\" x2=\"235\" y2=\"305\" stroke=\"#71717a\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n\n    <!-- 3. Axe Lashing Waterproof Seal Cross-Section Inset (Top Center/Left) -->\n    <g filter=\"url(#shadowOut10)\">\n      <rect x=\"230\" y=\"145\" width=\"225\" height=\"130\" fill=\"#0a0f18\" rx=\"5\" stroke=\"#1e293b\" stroke-width=\"1.2\"/>\n      <rect x=\"230\" y=\"145\" width=\"225\" height=\"20\" fill=\"#0f172a\" rx=\"5\" stroke=\"#1e293b\" stroke-width=\"0.8\"/>\n      <text x=\"342\" y=\"159\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"middle\">실전 결속 방수 단면 // TOOL JOINT SEAL</text>\n\n      <!-- Axe Handle Cross-Section -->\n      <rect x=\"260\" y=\"195\" width=\"165\" height=\"28\" rx=\"4\" fill=\"url(#woodGradOut)\" stroke=\"#451a03\" stroke-width=\"1\"/>\n      <!-- Stone Axe Blade Inserted into Split -->\n      <polygon points=\"310,175 350,175 365,210 295,210\" fill=\"url(#axeStoneGrad)\" stroke=\"#334155\" stroke-width=\"1\"/>\n      <!-- Black Pitch Glue Collar Sealing Joint 100% -->\n      <path d=\"M 290 205 Q 330 198 370 205 Q 370 220 330 222 Q 290 220 290 205 Z\" fill=\"#09090b\" stroke=\"#3f3f46\" stroke-width=\"1.5\"/>\n      <path d=\"M 295 208 Q 330 204 365 208\" stroke=\"#ffffff\" stroke-width=\"1\" fill=\"none\" opacity=\"0.6\"/>\n\n      <!-- Water Droplets Bouncing Off Waterproof Pitch Collar -->\n      <path d=\"M 315 188 Q 320 198 322 204\" stroke=\"#38bdf8\" stroke-width=\"1.5\" stroke-linecap=\"round\" fill=\"none\"/>\n      <circle cx=\"320\" cy=\"186\" r=\"2.5\" fill=\"#38bdf8\"/>\n      <path d=\"M 345 188 Q 340 198 338 204\" stroke=\"#38bdf8\" stroke-width=\"1.5\" stroke-linecap=\"round\" fill=\"none\"/>\n      <circle cx=\"346\" cy=\"186\" r=\"2.5\" fill=\"#38bdf8\"/>\n\n      <!-- Label inside Inset -->\n      <text x=\"342\" y=\"240\" fill=\"#34d399\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\" font-weight=\"bold\" text-anchor=\"middle\">100% 방수 에폭시: 빗물 침투 차단</text>\n      <text x=\"342\" y=\"258\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7.5\" text-anchor=\"middle\">진동 충격 흡수 &amp; 칡줄 결속 영구 고정</text>\n    </g>\n  </g>\n\n  <!-- RIGHT HALF: Specification & Engineering Performance Panel -->\n  <g filter=\"url(#shadowOut10)\">\n    <rect x=\"480\" y=\"62\" width=\"292\" height=\"325\" fill=\"#0b0f17\" rx=\"6\" stroke=\"#1e293b\" stroke-width=\"1.5\"/>\n    <rect x=\"480\" y=\"62\" width=\"292\" height=\"26\" fill=\"#111827\" rx=\"6\" stroke=\"#1f2937\" stroke-width=\"1\"/>\n    <text x=\"626\" y=\"79\" fill=\"#f8fafc\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10.5\" font-weight=\"bold\" text-anchor=\"middle\">송진 정제 및 천연 에폭시 제원 (SPECIFICATION)</text>\n\n    <!-- Microscopic Carbon Matrix Callout Circle -->\n    <g>\n      <circle cx=\"535\" cy=\"145\" r=\"32\" fill=\"#090d16\" stroke=\"#f59e0b\" stroke-width=\"1.5\"/>\n      <!-- Resin Matrix (Golden Honeycomb) -->\n      <circle cx=\"535\" cy=\"145\" r=\"28\" fill=\"#451a03\" opacity=\"0.6\"/>\n      <!-- Dispersed Carbon Micro-Particles -->\n      <circle cx=\"522\" cy=\"135\" r=\"3\" fill=\"#18181b\" stroke=\"#71717a\" stroke-width=\"0.5\"/>\n      <circle cx=\"538\" cy=\"132\" r=\"4\" fill=\"#18181b\" stroke=\"#71717a\" stroke-width=\"0.5\"/>\n      <circle cx=\"550\" cy=\"142\" r=\"3.5\" fill=\"#18181b\" stroke=\"#71717a\" stroke-width=\"0.5\"/>\n      <circle cx=\"525\" cy=\"152\" r=\"4\" fill=\"#18181b\" stroke=\"#71717a\" stroke-width=\"0.5\"/>\n      <circle cx=\"542\" cy=\"156\" r=\"3\" fill=\"#18181b\" stroke=\"#71717a\" stroke-width=\"0.5\"/>\n      <circle cx=\"534\" cy=\"145\" r=\"3.5\" fill=\"#18181b\" stroke=\"#71717a\" stroke-width=\"0.5\"/>\n      <!-- Interstitial Terpene Resin Binder -->\n      <path d=\"M 524 136 L 536 134 M 540 134 L 548 140 M 527 150 L 532 146\" stroke=\"#fbbf24\" stroke-width=\"1\" opacity=\"0.8\"/>\n      <!-- Microstructure Label -->\n      <text x=\"640\" y=\"138\" fill=\"#fbbf24\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\">탄소-수지 결합 미세구조</text>\n      <text x=\"640\" y=\"152\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7.5\">균열 전파 차단 복합재 골격</text>\n      <text x=\"640\" y=\"164\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7.5\">충격 인성 400% 향상 (취성 극복)</text>\n    </g>\n\n    <!-- Technical Specs Table Rows -->\n    <g>\n      <!-- Row 1: Antimicrobial Efficacy -->\n      <rect x=\"495\" y=\"195\" width=\"262\" height=\"24\" fill=\"#0f172a\" rx=\"3\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <text x=\"505\" y=\"211\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\">항균 유효 성분</text>\n      <text x=\"745\" y=\"211\" fill=\"#fbbf24\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"end\">알파-피넨 &amp; 테르펜 (세균 차단)</text>\n\n      <!-- Row 2: Hardness & Toughness -->\n      <rect x=\"495\" y=\"225\" width=\"262\" height=\"24\" fill=\"#0f172a\" rx=\"3\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <text x=\"505\" y=\"241\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\">경화 경도 (Hardness)</text>\n      <text x=\"745\" y=\"241\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"end\">모스 경도 3.0 (흑요석 광택)</text>\n\n      <!-- Row 3: Optimum Ratio -->\n      <rect x=\"495\" y=\"255\" width=\"262\" height=\"24\" fill=\"#0f172a\" rx=\"3\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <text x=\"505\" y=\"271\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\">최적 배합 비율</text>\n      <text x=\"745\" y=\"271\" fill=\"#f59e0b\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"end\">송진 1 : 참나무 숯가루 1</text>\n\n      <!-- Row 4: Waterproof Seal -->\n      <rect x=\"495\" y=\"285\" width=\"262\" height=\"24\" fill=\"#0f172a\" rx=\"3\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <text x=\"505\" y=\"301\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\">방수 및 내열 한계</text>\n      <text x=\"745\" y=\"301\" fill=\"#34d399\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"end\">완전 방수 100% / 60℃ 이하 안정</text>\n\n      <!-- Row 5: Batch Yield -->\n      <rect x=\"495\" y=\"315\" width=\"262\" height=\"24\" fill=\"#0f172a\" rx=\"3\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <text x=\"505\" y=\"331\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\">1회 정제 수확량</text>\n      <text x=\"745\" y=\"331\" fill=\"#a78bfa\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"end\">연고 30ml + 결속 막대 2개</text>\n\n      <!-- Row 6: Re-melting Utility -->\n      <rect x=\"495\" y=\"345\" width=\"262\" height=\"24\" fill=\"#0f172a\" rx=\"3\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n      <text x=\"505\" y=\"361\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\">재사용성 (Re-melting)</text>\n      <text x=\"745\" y=\"361\" fill=\"#e2e8f0\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\" font-weight=\"bold\" text-anchor=\"end\">가열 시 즉시 재용융 접착</text>\n    </g>\n  </g>\n\n  <!-- Bottom Core Summary Banner -->\n  <rect x=\"28\" y=\"398\" width=\"744\" height=\"28\" fill=\"#111827\" rx=\"4\" stroke=\"#1f2937\" stroke-width=\"1.2\"/>\n  <rect x=\"28\" y=\"398\" width=\"4\" height=\"28\" fill=\"#10b981\" rx=\"1\"/>\n  <text x=\"400\" y=\"416\" fill=\"#34d399\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10.5\" font-weight=\"bold\" text-anchor=\"middle\">[핵심 공학] 테르펜 항균 분자로 상처 감염을 차단하고 숯가루 탄소 결속으로 돌처럼 단단한 방수 에폭시 완성</text>\n</svg>\n","content/svgs/pr10-step-01.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgS1\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#07080a\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1117\"/>\n      <stop offset=\"100%\" stop-color=\"#060709\"/>\n    </linearGradient>\n\n    <!-- Pine Bark Texture Gradient -->\n    <linearGradient id=\"barkGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#2a1810\"/>\n      <stop offset=\"25%\" stop-color=\"#3d2317\"/>\n      <stop offset=\"50%\" stop-color=\"#1f120c\"/>\n      <stop offset=\"75%\" stop-color=\"#4a2b1c\"/>\n      <stop offset=\"100%\" stop-color=\"#2a1810\"/>\n    </linearGradient>\n\n    <!-- Golden Amber Resin Gradient -->\n    <radialGradient id=\"amberResin\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#fffbeb\"/>\n      <stop offset=\"25%\" stop-color=\"#fde047\"/>\n      <stop offset=\"60%\" stop-color=\"#f59e0b\"/>\n      <stop offset=\"85%\" stop-color=\"#b45309\"/>\n      <stop offset=\"100%\" stop-color=\"#78350f\"/>\n    </radialGradient>\n\n    <!-- Stone Flake Knife Gradient -->\n    <linearGradient id=\"stoneKnife\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#cbd5e1\"/>\n      <stop offset=\"40%\" stop-color=\"#94a3b8\"/>\n      <stop offset=\"80%\" stop-color=\"#475569\"/>\n      <stop offset=\"100%\" stop-color=\"#1e293b\"/>\n    </linearGradient>\n\n    <!-- Drop Shadow Filter -->\n    <filter id=\"shadowS1\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"3\" stdDeviation=\"3\" flood-color=\"#000000\" flood-opacity=\"0.85\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Canvas -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgS1)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#232830\" stroke-width=\"1.2\"/>\n\n  <!-- Technical Corner Ticks -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n\n  <!-- Top Header Strip (Label 1) -->\n  <rect x=\"20\" y=\"16\" width=\"360\" height=\"20\" fill=\"#0f172a\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n  <rect x=\"20\" y=\"16\" width=\"3\" height=\"20\" fill=\"#f59e0b\"/>\n  <text x=\"30\" y=\"30\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" letter-spacing=\"0.5\">FIG. 01 // RAW PINE RESIN HARVESTING</text>\n\n  <!-- Pine Tree Trunk (Cross-Section & Bark Surface) -->\n  <g>\n    <!-- Trunk Body on Left Side -->\n    <rect x=\"25\" y=\"55\" width=\"160\" height=\"275\" fill=\"url(#barkGrad)\" stroke=\"#1c120c\" stroke-width=\"1.5\"/>\n    \n    <!-- Vertical Bark Fissures & Ridges -->\n    <path d=\"M 45 55 Q 50 120 42 190 Q 48 260 44 330\" stroke=\"#140a05\" stroke-width=\"3\" fill=\"none\"/>\n    <path d=\"M 75 55 Q 70 130 80 200 Q 72 270 78 330\" stroke=\"#140a05\" stroke-width=\"4\" fill=\"none\"/>\n    <path d=\"M 110 55 Q 118 110 108 180 Q 116 250 112 330\" stroke=\"#140a05\" stroke-width=\"3.5\" fill=\"none\"/>\n    <path d=\"M 145 55 Q 140 125 150 195 Q 142 265 146 330\" stroke=\"#140a05\" stroke-width=\"3\" fill=\"none\"/>\n\n    <!-- Bark Plate Highlights -->\n    <path d=\"M 60 70 L 68 110 L 62 150\" stroke=\"#5a3522\" stroke-width=\"1.5\" fill=\"none\" opacity=\"0.6\"/>\n    <path d=\"M 95 90 L 102 140 L 96 180\" stroke=\"#5a3522\" stroke-width=\"1.5\" fill=\"none\" opacity=\"0.6\"/>\n    <path d=\"M 130 80 L 138 130 L 132 170\" stroke=\"#5a3522\" stroke-width=\"1.5\" fill=\"none\" opacity=\"0.6\"/>\n  </g>\n\n  <!-- Hardened Amber Pine Resin Nodules (Crystalline Clusters) -->\n  <g filter=\"url(#shadowS1)\">\n    <!-- Main Big Teardrop Resin Mass -->\n    <path d=\"M 115 130 Q 145 140 140 185 Q 135 215 110 225 Q 90 220 95 185 Q 100 145 115 130 Z\" fill=\"url(#amberResin)\" stroke=\"#78350f\" stroke-width=\"1.2\"/>\n    <!-- Specular Highlight Curve -->\n    <path d=\"M 118 140 Q 135 152 132 175\" stroke=\"#ffffff\" stroke-width=\"2\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.8\"/>\n    <circle cx=\"108\" cy=\"180\" r=\"3\" fill=\"#ffffff\" opacity=\"0.75\"/>\n\n    <!-- Smaller Secondary Droplets -->\n    <ellipse cx=\"145\" cy=\"160\" rx=\"14\" ry=\"20\" fill=\"url(#amberResin)\" stroke=\"#78350f\" stroke-width=\"1\"/>\n    <path d=\"M 148 150 Q 155 158 153 170\" stroke=\"#ffffff\" stroke-width=\"1.5\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.7\"/>\n\n    <ellipse cx=\"90\" cy=\"155\" rx=\"12\" ry=\"16\" fill=\"url(#amberResin)\" stroke=\"#78350f\" stroke-width=\"1\"/>\n    <ellipse cx=\"120\" cy=\"240\" rx=\"10\" ry=\"14\" fill=\"url(#amberResin)\" stroke=\"#78350f\" stroke-width=\"0.8\"/>\n    <ellipse cx=\"80\" cy=\"210\" rx=\"8\" ry=\"12\" fill=\"url(#amberResin)\" stroke=\"#78350f\" stroke-width=\"0.8\"/>\n  </g>\n\n  <!-- Label 2: Hardened Amber Resin Nodules on Bark -->\n  <g>\n    <line x1=\"140\" y1=\"175\" x2=\"230\" y2=\"120\" stroke=\"#f59e0b\" stroke-width=\"1.2\"/>\n    <circle cx=\"140\" cy=\"175\" r=\"2.5\" fill=\"#f59e0b\"/>\n    <rect x=\"220\" y=\"108\" width=\"160\" height=\"16\" fill=\"#1c1308\" rx=\"3\" stroke=\"#b45309\" stroke-width=\"1\"/>\n    <text x=\"300\" y=\"120\" fill=\"#fbbf24\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\" font-weight=\"bold\" text-anchor=\"middle\">소나무 줄기에 응고된 호박색 생송진</text>\n  </g>\n\n  <!-- Stone Flake Knife Scraping at Tangent Angle -->\n  <g filter=\"url(#shadowS1)\">\n    <!-- Knife Blade Polygon -->\n    <polygon points=\"175,190 240,150 255,170 190,210\" fill=\"url(#stoneKnife)\" stroke=\"#334155\" stroke-width=\"1.2\"/>\n    <!-- Sharp Beveled Cutting Edge -->\n    <line x1=\"175\" y1=\"190\" x2=\"190\" y2=\"210\" stroke=\"#f8fafc\" stroke-width=\"2\" stroke-linecap=\"round\"/>\n    <!-- Blade Chipping Ridges -->\n    <path d=\"M 195 180 L 210 195 M 215 165 L 230 185\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n    <!-- Tangent Motion Arrow -->\n    <path d=\"M 215 210 L 182 202\" stroke=\"#38bdf8\" stroke-width=\"1.5\" stroke-linecap=\"round\"/>\n    <path d=\"M 182 202 L 190 197 L 189 207 Z\" fill=\"#38bdf8\"/>\n  </g>\n\n  <!-- Label 3: Stone Scraper at Tangent Angle -->\n  <g>\n    <line x1=\"220\" y1=\"185\" x2=\"220\" y2=\"215\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n    <circle cx=\"220\" cy=\"185\" r=\"2.5\" fill=\"#38bdf8\"/>\n    <rect x=\"180\" y=\"215\" width=\"195\" height=\"16\" fill=\"#0c1726\" rx=\"3\" stroke=\"#0284c7\" stroke-width=\"1\"/>\n    <text x=\"277\" y=\"227\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\" font-weight=\"bold\" text-anchor=\"middle\">돌칼로 나무껍질 손상 없이 표면 채취</text>\n  </g>\n\n  <!-- Broad Collection Leaf at Bottom Catching Resin -->\n  <g filter=\"url(#shadowS1)\">\n    <!-- Wide Green Forest Leaf -->\n    <path d=\"M 80 295 Q 160 270 240 285 Q 270 315 220 330 Q 140 335 80 295 Z\" fill=\"#14532d\" stroke=\"#166534\" stroke-width=\"1.5\"/>\n    <path d=\"M 85 295 Q 165 295 240 285\" stroke=\"#22c55e\" stroke-width=\"1\" fill=\"none\" opacity=\"0.6\"/>\n    <!-- Falling Resin Chunks into Leaf -->\n    <circle cx=\"160\" cy=\"275\" r=\"4\" fill=\"url(#amberResin)\"/>\n    <circle cx=\"180\" cy=\"290\" r=\"5\" fill=\"url(#amberResin)\"/>\n    <circle cx=\"150\" cy=\"305\" r=\"6\" fill=\"url(#amberResin)\"/>\n    <circle cx=\"170\" cy=\"308\" r=\"8\" fill=\"url(#amberResin)\"/>\n    <circle cx=\"195\" cy=\"300\" r=\"7\" fill=\"url(#amberResin)\"/>\n    <circle cx=\"215\" cy=\"298\" r=\"5\" fill=\"url(#amberResin)\"/>\n  </g>\n\n  <!-- Label 4: Collection Volume Indicator (Fist-Sized ~100g) -->\n  <g>\n    <line x1=\"175\" y1=\"305\" x2=\"210\" y2=\"265\" stroke=\"#a3e635\" stroke-width=\"1\"/>\n    <circle cx=\"175\" cy=\"305\" r=\"2.5\" fill=\"#a3e635\"/>\n    <rect x=\"180\" y=\"255\" width=\"195\" height=\"16\" fill=\"#14210a\" rx=\"3\" stroke=\"#4d7c0f\" stroke-width=\"1\"/>\n    <text x=\"277\" y=\"267\" fill=\"#bef264\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\" font-weight=\"bold\" text-anchor=\"middle\">주먹 1개 분량 (약 100g) 선별 확보</text>\n  </g>\n\n  <!-- Bottom Core Insight Briefing Box (Label 5) -->\n  <rect x=\"20\" y=\"348\" width=\"360\" height=\"26\" fill=\"#111827\" rx=\"4\" stroke=\"#1f2937\" stroke-width=\"1.2\"/>\n  <rect x=\"20\" y=\"348\" width=\"4\" height=\"26\" fill=\"#f59e0b\" rx=\"1\"/>\n  <text x=\"200\" y=\"364\" fill=\"#fbbf24\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">[핵심] 바짝 굳은 투명한 덩어리 위주 채취</text>\n</svg>\n","content/svgs/pr10-step-02.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgS2\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#07080a\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1117\"/>\n      <stop offset=\"100%\" stop-color=\"#060709\"/>\n    </linearGradient>\n\n    <!-- Stone Dish Gradient -->\n    <linearGradient id=\"stoneDishGrad\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#475569\"/>\n      <stop offset=\"50%\" stop-color=\"#334155\"/>\n      <stop offset=\"100%\" stop-color=\"#1e293b\"/>\n    </linearGradient>\n\n    <!-- Liquid Amber Resin Pool -->\n    <radialGradient id=\"liquidResinGrad\" cx=\"45%\" cy=\"40%\" r=\"55%\">\n      <stop offset=\"0%\" stop-color=\"#fef08a\"/>\n      <stop offset=\"35%\" stop-color=\"#fde047\"/>\n      <stop offset=\"70%\" stop-color=\"#f59e0b\"/>\n      <stop offset=\"100%\" stop-color=\"#b45309\"/>\n    </radialGradient>\n\n    <!-- Glowing Embers Radial -->\n    <radialGradient id=\"emberGlowS2\" cx=\"50%\" cy=\"50%\" r=\"50%\">\n      <stop offset=\"0%\" stop-color=\"#ffedd5\"/>\n      <stop offset=\"25%\" stop-color=\"#fb923c\"/>\n      <stop offset=\"60%\" stop-color=\"#ea580c\"/>\n      <stop offset=\"85%\" stop-color=\"#991b1b\"/>\n      <stop offset=\"100%\" stop-color=\"#450a0a\"/>\n    </radialGradient>\n\n    <!-- Drop Shadow Filter -->\n    <filter id=\"shadowS2\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"3\" flood-color=\"#000000\" flood-opacity=\"0.9\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Canvas -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgS2)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#232830\" stroke-width=\"1.2\"/>\n\n  <!-- Technical Corner Ticks -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n\n  <!-- Top Header Strip (Label 1) -->\n  <rect x=\"20\" y=\"16\" width=\"360\" height=\"20\" fill=\"#0f172a\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n  <rect x=\"20\" y=\"16\" width=\"3\" height=\"20\" fill=\"#f59e0b\"/>\n  <text x=\"30\" y=\"30\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" letter-spacing=\"0.5\">FIG. 02 // GENTLE EMBER MELTING PROCESS</text>\n\n  <!-- Ground Bed Level -->\n  <line x1=\"20\" y1=\"320\" x2=\"380\" y2=\"320\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n\n  <!-- Glowing Charcoal Ember Bed on Right Side -->\n  <g filter=\"url(#shadowS2)\">\n    <!-- Charcoal Mound -->\n    <ellipse cx=\"310\" cy=\"305\" rx=\"65\" ry=\"25\" fill=\"#18181b\" stroke=\"#27272a\" stroke-width=\"1\"/>\n    <!-- Glowing Coals Clusters -->\n    <circle cx=\"280\" cy=\"300\" r=\"12\" fill=\"url(#emberGlowS2)\"/>\n    <circle cx=\"305\" cy=\"290\" r=\"16\" fill=\"url(#emberGlowS2)\"/>\n    <circle cx=\"335\" cy=\"302\" r=\"14\" fill=\"url(#emberGlowS2)\"/>\n    <circle cx=\"295\" cy=\"310\" r=\"11\" fill=\"url(#emberGlowS2)\"/>\n    <circle cx=\"325\" cy=\"312\" r=\"10\" fill=\"url(#emberGlowS2)\"/>\n\n    <!-- Ember Cores Specular Glow -->\n    <circle cx=\"305\" cy=\"290\" r=\"6\" fill=\"#fffbeb\"/>\n    <circle cx=\"280\" cy=\"300\" r=\"4\" fill=\"#fef08a\"/>\n\n    <!-- Radiant Heat Waves from Embers -->\n    <path d=\"M 270 275 Q 240 260 215 265\" stroke=\"#f97316\" stroke-width=\"1.5\" stroke-dasharray=\"3 3\" fill=\"none\" opacity=\"0.8\"/>\n    <path d=\"M 280 255 Q 245 240 210 248\" stroke=\"#f97316\" stroke-width=\"1.5\" stroke-dasharray=\"3 3\" fill=\"none\" opacity=\"0.8\"/>\n    <path d=\"M 295 240 Q 255 220 205 230\" stroke=\"#fbbf24\" stroke-width=\"1.2\" stroke-dasharray=\"3 3\" fill=\"none\" opacity=\"0.7\"/>\n  </g>\n\n  <!-- Concave Stone Dish Resting on Support Stones (Left/Center) -->\n  <g filter=\"url(#shadowS2)\">\n    <!-- Support Stones Beneath Dish -->\n    <ellipse cx=\"100\" cy=\"315\" rx=\"20\" ry=\"10\" fill=\"#334155\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n    <ellipse cx=\"160\" cy=\"315\" rx=\"22\" ry=\"11\" fill=\"#334155\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n\n    <!-- Outer Concave Stone Dish Body -->\n    <path d=\"M 45 245 C 50 310, 210 310, 215 245 C 190 265, 70 265, 45 245 Z\" fill=\"url(#stoneDishGrad)\" stroke=\"#1e293b\" stroke-width=\"1.5\"/>\n    <ellipse cx=\"130\" cy=\"245\" rx=\"85\" ry=\"24\" fill=\"#1e293b\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n\n    <!-- Molten Golden Pine Resin Pool inside Dish Cavity -->\n    <ellipse cx=\"130\" cy=\"247\" rx=\"72\" ry=\"18\" fill=\"url(#liquidResinGrad)\" stroke=\"#92400e\" stroke-width=\"1.2\"/>\n\n    <!-- Melting Resin Chunks & Bubbles -->\n    <ellipse cx=\"115\" cy=\"244\" rx=\"14\" ry=\"7\" fill=\"#b45309\" opacity=\"0.6\"/>\n    <circle cx=\"100\" cy=\"246\" r=\"3\" fill=\"#fde047\" opacity=\"0.85\"/>\n    <circle cx=\"145\" cy=\"248\" r=\"3.5\" fill=\"#fde047\" opacity=\"0.85\"/>\n    <circle cx=\"165\" cy=\"245\" r=\"2.5\" fill=\"#fffbeb\" opacity=\"0.9\"/>\n    <!-- Specular Highlight on Liquid Surface -->\n    <path d=\"M 85 243 Q 130 252 175 243\" stroke=\"#ffffff\" stroke-width=\"1.5\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.7\"/>\n  </g>\n\n  <!-- Label 2: Molten Golden Resin inside Concave Stone Dish -->\n  <g>\n    <line x1=\"130\" y1=\"247\" x2=\"130\" y2=\"120\" stroke=\"#fbbf24\" stroke-width=\"1.2\"/>\n    <circle cx=\"130\" cy=\"247\" r=\"2.5\" fill=\"#fbbf24\"/>\n    <rect x=\"40\" y=\"108\" width=\"180\" height=\"16\" fill=\"#1c1308\" rx=\"3\" stroke=\"#b45309\" stroke-width=\"1\"/>\n    <text x=\"130\" y=\"120\" fill=\"#fbbf24\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\" font-weight=\"bold\" text-anchor=\"middle\">오목한 돌판 속 황금빛 액상 송진</text>\n  </g>\n\n  <!-- Dimension Indicator: 10cm Gap from Direct Flame (Label 3) -->\n  <g>\n    <line x1=\"215\" y1=\"290\" x2=\"265\" y2=\"290\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n    <path d=\"M 215 287 L 208 290 L 215 293 Z\" fill=\"#38bdf8\"/>\n    <path d=\"M 265 287 L 272 290 L 265 293 Z\" fill=\"#38bdf8\"/>\n    <line x1=\"215\" y1=\"270\" x2=\"215\" y2=\"300\" stroke=\"#38bdf8\" stroke-width=\"0.8\" stroke-dasharray=\"2 2\"/>\n    <line x1=\"265\" y1=\"270\" x2=\"265\" y2=\"300\" stroke=\"#38bdf8\" stroke-width=\"0.8\" stroke-dasharray=\"2 2\"/>\n    <rect x=\"180\" y=\"150\" width=\"180\" height=\"16\" fill=\"#0b1726\" rx=\"3\" stroke=\"#0284c7\" stroke-width=\"1\"/>\n    <text x=\"270\" y=\"162\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\" font-weight=\"bold\" text-anchor=\"middle\">숯불 가장자리 10cm 간접 거치</text>\n    <line x1=\"240\" y1=\"290\" x2=\"270\" y2=\"166\" stroke=\"#38bdf8\" stroke-width=\"0.8\" stroke-dasharray=\"2 2\"/>\n  </g>\n\n  <!-- Flame Barrier / Radiant Heating Indicator (Label 4) -->\n  <g>\n    <path d=\"M 245 220 L 245 260\" stroke=\"#ef4444\" stroke-width=\"1.5\" stroke-dasharray=\"2 2\"/>\n    <circle cx=\"245\" cy=\"240\" r=\"3\" fill=\"#ef4444\"/>\n    <rect x=\"170\" y=\"180\" width=\"205\" height=\"16\" fill=\"#200a0a\" rx=\"3\" stroke=\"#b91c1c\" stroke-width=\"1\"/>\n    <text x=\"272\" y=\"192\" fill=\"#f87171\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\" font-weight=\"bold\" text-anchor=\"middle\">직화 불꽃 차단 및 은근한 복사열 가열</text>\n  </g>\n\n  <!-- Bottom Core Insight Briefing Box (Label 5) -->\n  <rect x=\"20\" y=\"348\" width=\"360\" height=\"26\" fill=\"#111827\" rx=\"4\" stroke=\"#1f2937\" stroke-width=\"1.2\"/>\n  <rect x=\"20\" y=\"348\" width=\"4\" height=\"26\" fill=\"#f59e0b\" rx=\"1\"/>\n  <text x=\"200\" y=\"364\" fill=\"#fbbf24\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">[핵심] 인화 방지를 위한 100% 잔열 용융</text>\n</svg>\n","content/svgs/pr10-step-03.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgS3\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#07080a\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1117\"/>\n      <stop offset=\"100%\" stop-color=\"#060709\"/>\n    </linearGradient>\n\n    <!-- Stone Dish Gradient -->\n    <linearGradient id=\"stoneDishS3\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#475569\"/>\n      <stop offset=\"100%\" stop-color=\"#1e293b\"/>\n    </linearGradient>\n\n    <!-- Clarified Amber Resin -->\n    <radialGradient id=\"clarifiedResin\" cx=\"45%\" cy=\"40%\" r=\"55%\">\n      <stop offset=\"0%\" stop-color=\"#fef08a\"/>\n      <stop offset=\"40%\" stop-color=\"#fde047\"/>\n      <stop offset=\"75%\" stop-color=\"#f59e0b\"/>\n      <stop offset=\"100%\" stop-color=\"#b45309\"/>\n    </radialGradient>\n\n    <!-- Seashell Gradient -->\n    <linearGradient id=\"seashellGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#f8fafc\"/>\n      <stop offset=\"40%\" stop-color=\"#e2e8f0\"/>\n      <stop offset=\"70%\" stop-color=\"#cbd5e1\"/>\n      <stop offset=\"100%\" stop-color=\"#94a3b8\"/>\n    </linearGradient>\n\n    <!-- Drop Shadow Filter -->\n    <filter id=\"shadowS3\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"3\" flood-color=\"#000000\" flood-opacity=\"0.9\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Canvas -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgS3)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#232830\" stroke-width=\"1.2\"/>\n\n  <!-- Technical Corner Ticks -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n\n  <!-- Top Header Strip (Label 1) -->\n  <rect x=\"20\" y=\"16\" width=\"360\" height=\"20\" fill=\"#0f172a\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n  <rect x=\"20\" y=\"16\" width=\"3\" height=\"20\" fill=\"#f59e0b\"/>\n  <text x=\"30\" y=\"30\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" letter-spacing=\"0.5\">FIG. 03 // DEBRIS REMOVAL &amp; OINTMENT EXTRACTION</text>\n\n  <!-- Ground / Stone Work Surface -->\n  <line x1=\"20\" y1=\"320\" x2=\"380\" y2=\"320\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n\n  <!-- Main Stone Melting Dish on Left -->\n  <g filter=\"url(#shadowS3)\">\n    <path d=\"M 35 240 C 40 310, 190 310, 195 240 C 170 260, 60 260, 35 240 Z\" fill=\"url(#stoneDishS3)\" stroke=\"#1e293b\" stroke-width=\"1.5\"/>\n    <ellipse cx=\"115\" cy=\"240\" rx=\"78\" ry=\"22\" fill=\"#1e293b\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n    <!-- Liquid Resin Pool -->\n    <ellipse cx=\"115\" cy=\"242\" rx=\"66\" ry=\"16\" fill=\"url(#clarifiedResin)\" stroke=\"#92400e\" stroke-width=\"1.2\"/>\n    <path d=\"M 65 238 Q 115 248 165 238\" stroke=\"#ffffff\" stroke-width=\"1.5\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.6\"/>\n  </g>\n\n  <!-- Twig Comb Filter Skimming Debris -->\n  <g filter=\"url(#shadowS3)\">\n    <!-- Main Handle Twig -->\n    <line x1=\"140\" y1=\"140\" x2=\"95\" y2=\"235\" stroke=\"#78350f\" stroke-width=\"5\" stroke-linecap=\"round\"/>\n    <line x1=\"140\" y1=\"140\" x2=\"95\" y2=\"235\" stroke=\"#9a3412\" stroke-width=\"3\" stroke-linecap=\"round\"/>\n    <!-- Comb Tines (Fine Twig Teeth) -->\n    <path d=\"M 80 238 L 92 235 M 84 242 L 96 238 M 90 245 L 102 240 M 96 247 L 108 242\" stroke=\"#451a03\" stroke-width=\"2.5\" stroke-linecap=\"round\"/>\n    <!-- Trapped Bark Debris Chunks on Comb -->\n    <ellipse cx=\"90\" cy=\"235\" rx=\"5\" ry=\"3\" fill=\"#18181b\"/>\n    <ellipse cx=\"98\" cy=\"237\" rx=\"4\" ry=\"2.5\" fill=\"#292524\"/>\n    <circle cx=\"85\" cy=\"238\" r=\"2\" fill=\"#18181b\"/>\n  </g>\n\n  <!-- Label 2: Twig Comb Skimming Bark Debris -->\n  <g>\n    <line x1=\"110\" y1=\"210\" x2=\"60\" y2=\"120\" stroke=\"#f59e0b\" stroke-width=\"1.2\"/>\n    <circle cx=\"110\" cy=\"210\" r=\"2.5\" fill=\"#f59e0b\"/>\n    <rect x=\"40\" y=\"108\" width=\"180\" height=\"16\" fill=\"#1c1308\" rx=\"3\" stroke=\"#b45309\" stroke-width=\"1\"/>\n    <text x=\"130\" y=\"120\" fill=\"#fbbf24\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\" font-weight=\"bold\" text-anchor=\"middle\">잔가지 빗으로 불순물 찌꺼기 여과</text>\n  </g>\n\n  <!-- Golden Resin Pouring Stream to Seashell -->\n  <g filter=\"url(#shadowS3)\">\n    <!-- Wooden Spoon / Split Bark Dipper -->\n    <path d=\"M 150 200 Q 185 185 220 205 L 210 215 Q 180 195 150 210 Z\" fill=\"#78350f\" stroke=\"#451a03\" stroke-width=\"1\"/>\n    <!-- Dipped Molten Ointment Droplet -->\n    <ellipse cx=\"215\" cy=\"210\" rx=\"12\" ry=\"7\" fill=\"url(#clarifiedResin)\"/>\n    <!-- Liquid Amber Pour Stream into Shell -->\n    <path d=\"M 215 212 C 220 230, 245 235, 255 250\" stroke=\"#f59e0b\" stroke-width=\"4.5\" stroke-linecap=\"round\" fill=\"none\"/>\n    <path d=\"M 215 212 C 220 230, 245 235, 255 250\" stroke=\"#fef08a\" stroke-width=\"2\" stroke-linecap=\"round\" fill=\"none\"/>\n  </g>\n\n  <!-- Label 3: Ointment Extraction (30ml) -->\n  <g>\n    <line x1=\"220\" y1=\"215\" x2=\"270\" y2=\"160\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n    <circle cx=\"220\" cy=\"215\" r=\"2.5\" fill=\"#38bdf8\"/>\n    <rect x=\"180\" y=\"150\" width=\"195\" height=\"16\" fill=\"#0c1726\" rx=\"3\" stroke=\"#0284c7\" stroke-width=\"1\"/>\n    <text x=\"277\" y=\"162\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\" font-weight=\"bold\" text-anchor=\"middle\">상처 소독용 순수 송진액 30ml 분리</text>\n  </g>\n\n  <!-- Clean Seashell Container with Clarified Ointment (Right Side) -->\n  <g filter=\"url(#shadowS3)\">\n    <!-- Scallop / Clam Shell Shape -->\n    <path d=\"M 230 295 C 235 240, 335 240, 345 295 C 320 315, 255 315, 230 295 Z\" fill=\"url(#seashellGrad)\" stroke=\"#475569\" stroke-width=\"1.5\"/>\n    <!-- Shell Ridges Radiating -->\n    <path d=\"M 290 305 L 250 255 M 290 305 L 270 250 M 290 305 L 290 248 M 290 305 L 310 250 M 290 305 L 330 255\" stroke=\"#94a3b8\" stroke-width=\"1\" fill=\"none\" opacity=\"0.6\"/>\n    <!-- Pure Amber Ointment Pool Cooling inside Shell -->\n    <ellipse cx=\"288\" cy=\"285\" rx=\"38\" ry=\"16\" fill=\"url(#clarifiedResin)\" stroke=\"#b45309\" stroke-width=\"1.2\"/>\n    <circle cx=\"275\" cy=\"283\" r=\"3\" fill=\"#ffffff\" opacity=\"0.8\"/>\n    <ellipse cx=\"305\" cy=\"286\" rx=\"5\" ry=\"2.5\" fill=\"#fef08a\" opacity=\"0.9\"/>\n  </g>\n\n  <!-- Label 4: Seashell Cooling Container (10 Minutes) -->\n  <g>\n    <line x1=\"290\" y1=\"285\" x2=\"270\" y2=\"225\" stroke=\"#a3e635\" stroke-width=\"1\"/>\n    <circle cx=\"290\" cy=\"285\" r=\"2.5\" fill=\"#a3e635\"/>\n    <rect x=\"165\" y=\"220\" width=\"215\" height=\"16\" fill=\"#14210a\" rx=\"3\" stroke=\"#4d7c0f\" stroke-width=\"1\"/>\n    <text x=\"272\" y=\"232\" fill=\"#bef264\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\" font-weight=\"bold\" text-anchor=\"middle\">조개껍데기에 덜어내어 10분간 자연 냉각</text>\n  </g>\n\n  <!-- Bottom Core Insight Briefing Box (Label 5) -->\n  <rect x=\"20\" y=\"348\" width=\"360\" height=\"26\" fill=\"#111827\" rx=\"4\" stroke=\"#1f2937\" stroke-width=\"1.2\"/>\n  <rect x=\"20\" y=\"348\" width=\"4\" height=\"26\" fill=\"#f59e0b\" rx=\"1\"/>\n  <text x=\"200\" y=\"364\" fill=\"#fbbf24\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">[핵심] 맑은 황금빛 소독 연고 분리 확보</text>\n</svg>\n","content/svgs/pr10-step-04.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Gradient -->\n    <linearGradient id=\"bgS4\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#07080a\"/>\n      <stop offset=\"50%\" stop-color=\"#0e1117\"/>\n      <stop offset=\"100%\" stop-color=\"#060709\"/>\n    </linearGradient>\n\n    <!-- Stone Dish Gradient -->\n    <linearGradient id=\"stoneDishS4\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#475569\"/>\n      <stop offset=\"100%\" stop-color=\"#1e293b\"/>\n    </linearGradient>\n\n    <!-- Black Pitch Mix Gradient -->\n    <radialGradient id=\"blackPitchGrad\" cx=\"45%\" cy=\"40%\" r=\"55%\">\n      <stop offset=\"0%\" stop-color=\"#27272a\"/>\n      <stop offset=\"40%\" stop-color=\"#18181b\"/>\n      <stop offset=\"85%\" stop-color=\"#09090b\"/>\n      <stop offset=\"100%\" stop-color=\"#000000\"/>\n    </radialGradient>\n\n    <!-- Obsidian Hardened Pitch Stick Gradient -->\n    <radialGradient id=\"pitchStickGrad\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#52525b\"/>\n      <stop offset=\"30%\" stop-color=\"#27272a\"/>\n      <stop offset=\"70%\" stop-color=\"#18181b\"/>\n      <stop offset=\"100%\" stop-color=\"#09090b\"/>\n    </radialGradient>\n\n    <!-- Wood Stick Gradient -->\n    <linearGradient id=\"woodStickGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#78350f\"/>\n      <stop offset=\"50%\" stop-color=\"#9a3412\"/>\n      <stop offset=\"100%\" stop-color=\"#451a03\"/>\n    </linearGradient>\n\n    <!-- Drop Shadow Filter -->\n    <filter id=\"shadowS4\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"3\" flood-color=\"#000000\" flood-opacity=\"0.9\"/>\n    </filter>\n  </defs>\n\n  <!-- Background Canvas -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bgS4)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#232830\" stroke-width=\"1.2\"/>\n\n  <!-- Technical Corner Ticks -->\n  <path d=\"M 14 22 L 26 22 M 20 16 L 20 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 22 L 374 22 M 380 16 L 380 28\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 14 378 L 26 378 M 20 372 L 20 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n  <path d=\"M 386 378 L 374 378 M 380 372 L 380 384\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n\n  <!-- Top Header Strip (Label 1) -->\n  <rect x=\"20\" y=\"16\" width=\"360\" height=\"20\" fill=\"#0f172a\" stroke=\"#1e293b\" stroke-width=\"1\"/>\n  <rect x=\"20\" y=\"16\" width=\"3\" height=\"20\" fill=\"#f59e0b\"/>\n  <text x=\"30\" y=\"30\" fill=\"#94a3b8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" font-weight=\"bold\" letter-spacing=\"0.5\">FIG. 04 // CHARCOAL ADMIXTURE &amp; PITCH STICK</text>\n\n  <!-- Ground Work Surface -->\n  <line x1=\"20\" y1=\"320\" x2=\"380\" y2=\"320\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n\n  <!-- Mixing Stone Dish on Left -->\n  <g filter=\"url(#shadowS4)\">\n    <path d=\"M 30 240 C 35 310, 185 310, 190 240 C 165 260, 55 260, 30 240 Z\" fill=\"url(#stoneDishS4)\" stroke=\"#1e293b\" stroke-width=\"1.5\"/>\n    <ellipse cx=\"110\" cy=\"240\" rx=\"78\" ry=\"22\" fill=\"#1e293b\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n    <!-- Pitch Black Viscous Resin Mixture -->\n    <ellipse cx=\"110\" cy=\"242\" rx=\"66\" ry=\"16\" fill=\"url(#blackPitchGrad)\" stroke=\"#27272a\" stroke-width=\"1.2\"/>\n    <!-- Swirling Agitation Lines in Pitch -->\n    <path d=\"M 80 240 Q 110 248 140 240\" stroke=\"#52525b\" stroke-width=\"1.5\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.6\"/>\n    <path d=\"M 95 245 Q 120 250 135 244\" stroke=\"#71717a\" stroke-width=\"1.2\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.7\"/>\n  </g>\n\n  <!-- Cascading Fine Charcoal Powder from Leaf above -->\n  <g filter=\"url(#shadowS4)\">\n    <!-- Charcoal Powder Leaf / Bark Scoop -->\n    <path d=\"M 70 145 Q 115 135 140 155 L 125 165 Q 100 150 70 155 Z\" fill=\"#3f2213\" stroke=\"#26140b\" stroke-width=\"1\"/>\n    <!-- Micro Charcoal Powder Particles Streaming Down -->\n    <g fill=\"#18181b\">\n      <circle cx=\"120\" cy=\"175\" r=\"3.5\"/>\n      <circle cx=\"128\" cy=\"180\" r=\"2.5\"/>\n      <circle cx=\"115\" cy=\"190\" r=\"3\"/>\n      <circle cx=\"125\" cy=\"198\" r=\"2\"/>\n      <circle cx=\"118\" cy=\"208\" r=\"3.5\"/>\n      <circle cx=\"126\" cy=\"215\" r=\"2.5\"/>\n      <circle cx=\"112\" cy=\"225\" r=\"3\"/>\n      <circle cx=\"122\" cy=\"230\" r=\"2\"/>\n    </g>\n  </g>\n\n  <!-- Label 2: Fine Charcoal Powder 1:1 Admixture -->\n  <g>\n    <line x1=\"120\" y1=\"185\" x2=\"60\" y2=\"120\" stroke=\"#f59e0b\" stroke-width=\"1.2\"/>\n    <circle cx=\"120\" cy=\"185\" r=\"2.5\" fill=\"#f59e0b\"/>\n    <rect x=\"40\" y=\"108\" width=\"180\" height=\"16\" fill=\"#1c1308\" rx=\"3\" stroke=\"#b45309\" stroke-width=\"1\"/>\n    <text x=\"130\" y=\"120\" fill=\"#fbbf24\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\" font-weight=\"bold\" text-anchor=\"middle\">미세 참나무 숯가루 1:1 비율 투입</text>\n  </g>\n\n  <!-- Active Churning Stick in Resin Dish -->\n  <g filter=\"url(#shadowS4)\">\n    <line x1=\"145\" y1=\"170\" x2=\"95\" y2=\"245\" stroke=\"url(#woodStickGrad)\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n    <!-- Sticky Tar Coating on Stirrer Tip -->\n    <ellipse cx=\"95\" cy=\"245\" rx=\"8\" ry=\"5\" fill=\"#09090b\"/>\n    <!-- Rotation Arrow around Stirrer -->\n    <path d=\"M 85 230 C 80 238, 105 242, 105 232\" stroke=\"#38bdf8\" stroke-width=\"1.5\" fill=\"none\" stroke-linecap=\"round\"/>\n    <path d=\"M 105 232 L 102 238 L 108 238 Z\" fill=\"#38bdf8\"/>\n  </g>\n\n  <!-- Label 3: High-Speed Churning & Viscous Dough -->\n  <g>\n    <line x1=\"100\" y1=\"240\" x2=\"260\" y2=\"155\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n    <circle cx=\"100\" cy=\"240\" r=\"2.5\" fill=\"#38bdf8\"/>\n    <rect x=\"175\" y=\"145\" width=\"200\" height=\"16\" fill=\"#0c1726\" rx=\"3\" stroke=\"#0284c7\" stroke-width=\"1\"/>\n    <text x=\"275\" y=\"157\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\" font-weight=\"bold\" text-anchor=\"middle\">나뭇가지로 고속 교반 및 점성 반죽</text>\n  </g>\n\n  <!-- Finished Obsidian Pitch Stick on Right -->\n  <g filter=\"url(#shadowS4)\">\n    <!-- Wooden Handle Stick -->\n    <path d=\"M 235 305 L 345 220\" stroke=\"url(#woodStickGrad)\" stroke-width=\"9\" stroke-linecap=\"round\"/>\n    <!-- Hardened Bulb of Glossy Black Pitch at the Tip -->\n    <ellipse cx=\"230\" cy=\"308\" rx=\"22\" ry=\"16\" fill=\"url(#pitchStickGrad)\" stroke=\"#27272a\" stroke-width=\"1.5\"/>\n    <circle cx=\"225\" cy=\"305\" r=\"14\" fill=\"#09090b\"/>\n    <!-- Specular Highlight reflecting hard obsidian surface -->\n    <path d=\"M 220 298 Q 235 302 242 312\" stroke=\"#ffffff\" stroke-width=\"2\" stroke-linecap=\"round\" fill=\"none\" opacity=\"0.8\"/>\n    <circle cx=\"218\" cy=\"304\" r=\"3\" fill=\"#ffffff\" opacity=\"0.7\"/>\n\n    <!-- Cold Water Quenching Basin / Surface -->\n    <ellipse cx=\"230\" cy=\"325\" rx=\"35\" ry=\"8\" fill=\"#0284c7\" opacity=\"0.3\"/>\n    <path d=\"M 215 325 Q 230 327 245 325\" stroke=\"#38bdf8\" stroke-width=\"1\" fill=\"none\" opacity=\"0.8\"/>\n  </g>\n\n  <!-- Label 4: Pitch Stick Wrapping & 5-Min Quench -->\n  <g>\n    <line x1=\"240\" y1=\"305\" x2=\"270\" y2=\"235\" stroke=\"#a3e635\" stroke-width=\"1\"/>\n    <circle cx=\"240\" cy=\"305\" r=\"2.5\" fill=\"#a3e635\"/>\n    <rect x=\"160\" y=\"225\" width=\"220\" height=\"16\" fill=\"#14210a\" rx=\"3\" stroke=\"#4d7c0f\" stroke-width=\"1\"/>\n    <text x=\"270\" y=\"237\" fill=\"#bef264\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\" font-weight=\"bold\" text-anchor=\"middle\">나뭇가지 끝에 둥글게 도포 후 5분 급랭</text>\n  </g>\n\n  <!-- Bottom Core Insight Briefing Box (Label 5) -->\n  <rect x=\"20\" y=\"348\" width=\"360\" height=\"26\" fill=\"#111827\" rx=\"4\" stroke=\"#1f2937\" stroke-width=\"1.2\"/>\n  <rect x=\"20\" y=\"348\" width=\"4\" height=\"26\" fill=\"#10b981\" rx=\"1\"/>\n  <text x=\"200\" y=\"364\" fill=\"#34d399\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">[핵심] 균열 없는 천연 방수 에폭시 막대 완성</text>\n</svg>\n","content/svgs/pr11-outcome.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 450\" width=\"100%\" height=\"100%\">\n  <defs>\n    <linearGradient id=\"bgOut11\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#070b10\"/>\n      <stop offset=\"50%\" stop-color=\"#0b1520\"/>\n      <stop offset=\"100%\" stop-color=\"#091017\"/>\n    </linearGradient>\n    <linearGradient id=\"willowCone\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#9cb36c\"/>\n      <stop offset=\"50%\" stop-color=\"#64783d\"/>\n      <stop offset=\"100%\" stop-color=\"#35411f\"/>\n    </linearGradient>\n    <linearGradient id=\"funnelGold\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n      <stop offset=\"0%\" stop-color=\"#fde68a\"/>\n      <stop offset=\"100%\" stop-color=\"#d97706\"/>\n    </linearGradient>\n    <linearGradient id=\"stoneGrad\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#94a3b8\"/>\n      <stop offset=\"60%\" stop-color=\"#475569\"/>\n      <stop offset=\"100%\" stop-color=\"#1e293b\"/>\n    </linearGradient>\n    <filter id=\"shadowOut11\" x=\"-10%\" y=\"-10%\" width=\"120%\" height=\"120%\">\n      <feDropShadow dx=\"0\" dy=\"6\" stdDeviation=\"6\" flood-color=\"#000000\" flood-opacity=\"0.8\"/>\n    </filter>\n    <pattern id=\"gridOut11\" width=\"25\" height=\"25\" patternUnits=\"userSpaceOnUse\">\n      <path d=\"M 25 0 L 0 0 0 25\" fill=\"none\" stroke=\"#152331\" stroke-width=\"0.6\"/>\n    </pattern>\n  </defs>\n\n  <rect width=\"800\" height=\"450\" fill=\"url(#bgOut11)\"/>\n  <rect width=\"800\" height=\"450\" fill=\"url(#gridOut11)\"/>\n  <rect x=\"10\" y=\"10\" width=\"780\" height=\"430\" fill=\"none\" stroke=\"#293d52\" stroke-width=\"1.2\"/>\n\n  <!-- Top Master Header Banner -->\n  <rect x=\"20\" y=\"18\" width=\"760\" height=\"34\" fill=\"#0f1822\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <text x=\"34\" y=\"40\" fill=\"#fde68a\" font-family=\"monospace\" font-size=\"13\" font-weight=\"bold\">PR-11 MASTER BLUEPRINT // WILLOW ONE-WAY FUNNEL FISH TRAP (HYDRO-MECHANICAL CUTAWAY)</text>\n\n  <!-- River Water Surface & Stream Current Lines -->\n  <path d=\"M 20 82 Q 200 74, 400 82 T 780 82\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"1.5\" stroke-dasharray=\"8,4\" opacity=\"0.6\"/>\n  <path d=\"M 20 382 L 780 382\" stroke=\"#334155\" stroke-width=\"3\"/>\n\n  <!-- Main Cutaway Diagram of Conical Willow Fish Trap (Center-Left) -->\n  <g filter=\"url(#shadowOut11)\">\n    <!-- Outer Conical Basket Cutaway -->\n    <polygon points=\"165,135 615,195 615,285 165,345\" fill=\"#182314\" opacity=\"0.65\"/>\n\n    <!-- 4 Graduated Willow Hoop Rings (25cm, 20cm, 15cm, 10cm) -->\n    <ellipse cx=\"165\" cy=\"240\" rx=\"34\" ry=\"105\" fill=\"none\" stroke=\"url(#willowCone)\" stroke-width=\"8\"/>\n    <ellipse cx=\"305\" cy=\"240\" rx=\"28\" ry=\"86\" fill=\"none\" stroke=\"url(#willowCone)\" stroke-width=\"7\"/>\n    <ellipse cx=\"445\" cy=\"240\" rx=\"22\" ry=\"66\" fill=\"none\" stroke=\"url(#willowCone)\" stroke-width=\"6.5\"/>\n    <ellipse cx=\"575\" cy=\"240\" rx=\"16\" ry=\"46\" fill=\"none\" stroke=\"url(#willowCone)\" stroke-width=\"6\"/>\n\n    <!-- Longitudinal Willow Ribs (1~1.5cm spacing) -->\n    <g stroke=\"url(#willowCone)\" stroke-width=\"2.4\" opacity=\"0.88\">\n      <line x1=\"165\" y1=\"135\" x2=\"645\" y2=\"230\"/>\n      <line x1=\"165\" y1=\"158\" x2=\"645\" y2=\"233\"/>\n      <line x1=\"165\" y1=\"181\" x2=\"645\" y2=\"236\"/>\n      <line x1=\"165\" y1=\"204\" x2=\"645\" y2=\"238\"/>\n      <line x1=\"165\" y1=\"276\" x2=\"645\" y2=\"242\"/>\n      <line x1=\"165\" y1=\"299\" x2=\"645\" y2=\"244\"/>\n      <line x1=\"165\" y1=\"322\" x2=\"645\" y2=\"247\"/>\n      <line x1=\"165\" y1=\"345\" x2=\"645\" y2=\"250\"/>\n    </g>\n\n    <!-- Inner One-Way Inverted Funnel Valve (Check-Valve) -->\n    <polygon points=\"165,142 332,216 332,264 165,338\" fill=\"#451a03\" opacity=\"0.45\"/>\n    <g stroke=\"url(#funnelGold)\" stroke-width=\"2.8\" stroke-linecap=\"round\">\n      <line x1=\"165\" y1=\"145\" x2=\"342\" y2=\"218\"/>\n      <line x1=\"165\" y1=\"175\" x2=\"345\" y2=\"225\"/>\n      <line x1=\"165\" y1=\"205\" x2=\"346\" y2=\"232\"/>\n      <line x1=\"165\" y1=\"275\" x2=\"346\" y2=\"248\"/>\n      <line x1=\"165\" y1=\"305\" x2=\"345\" y2=\"255\"/>\n      <line x1=\"165\" y1=\"335\" x2=\"342\" y2=\"262\"/>\n    </g>\n    <!-- 5~6cm Funnel Throat Ring Highlight -->\n    <ellipse cx=\"342\" cy=\"240\" rx=\"9\" ry=\"24\" fill=\"none\" stroke=\"#fde68a\" stroke-width=\"2.2\" stroke-dasharray=\"4,3\"/>\n\n    <!-- 2 Fist-Sized River Ballast Stones Inside Bottom -->\n    <ellipse cx=\"420\" cy=\"296\" rx=\"28\" ry=\"17\" fill=\"url(#stoneGrad)\" stroke=\"#cbd5e1\" stroke-width=\"1.2\"/>\n    <ellipse cx=\"485\" cy=\"286\" rx=\"25\" ry=\"15\" fill=\"url(#stoneGrad)\" stroke=\"#cbd5e1\" stroke-width=\"1.2\"/>\n\n    <!-- Crushed Snail & Earthworm Bait Leaf Pouch + Scent Plume -->\n    <circle cx=\"435\" cy=\"242\" r=\"18\" fill=\"#3f6212\" stroke=\"#fde68a\" stroke-width=\"1.8\"/>\n    <circle cx=\"430\" cy=\"238\" r=\"4\" fill=\"#fde68a\"/>\n    <circle cx=\"442\" cy=\"245\" r=\"3.5\" fill=\"#fde68a\"/>\n    <path d=\"M 415 242 C 300 240, 160 240, 35 240\" fill=\"none\" stroke=\"#fde68a\" stroke-width=\"2\" stroke-dasharray=\"4,5\"/>\n\n    <!-- Captured Freshwater Fish Inside Holding Chamber -->\n    <path d=\"M 480 212 C 502 195, 536 195, 558 212 C 570 202, 580 198, 583 198 L 577 212 L 583 226 C 580 226, 570 222, 558 212 C 536 229, 502 229, 480 212 Z\" fill=\"#38bdf8\" stroke=\"#f8fafc\" stroke-width=\"1.5\"/>\n    <circle cx=\"494\" cy=\"210\" r=\"2.5\" fill=\"#091017\"/>\n\n    <!-- Tail Retrieval Slip-Knot Binding -->\n    <rect x=\"635\" y=\"220\" width=\"22\" height=\"40\" rx=\"5\" fill=\"url(#funnelGold)\" stroke=\"#451a03\" stroke-width=\"1.5\"/>\n    <path d=\"M 657 232 C 688 212, 692 268, 657 248\" fill=\"none\" stroke=\"#fde68a\" stroke-width=\"3\"/>\n\n    <!-- Wooden Anchor Stakes Driven Into Riverbed -->\n    <rect x=\"225\" y=\"310\" width=\"10\" height=\"72\" rx=\"2\" fill=\"#a16207\" stroke=\"#fde68a\" stroke-width=\"1.2\"/>\n    <rect x=\"520\" y=\"280\" width=\"10\" height=\"102\" rx=\"2\" fill=\"#a16207\" stroke=\"#fde68a\" stroke-width=\"1.2\"/>\n  </g>\n\n  <!-- Callout Labels (Zero Overlap, High Contrast) -->\n  <rect x=\"28\" y=\"92\" width=\"270\" height=\"26\" rx=\"3\" fill=\"#0f172a\" stroke=\"#fde68a\" stroke-width=\"1\"/>\n  <text x=\"38\" y=\"109\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11.5\" font-weight=\"bold\">① 일방향 역깔때기 입구 (외경 25cm ➔ 내경 5cm)</text>\n\n  <rect x=\"320\" y=\"92\" width=\"265\" height=\"26\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <text x=\"330\" y=\"109\" fill=\"#38bdf8\" font-family=\"sans-serif\" font-size=\"11.5\" font-weight=\"bold\">② 4단 원형 림 &amp; 버드나무 세로 살 (1cm 간격)</text>\n\n  <rect x=\"598\" y=\"135\" width=\"178\" height=\"26\" rx=\"3\" fill=\"#0f172a\" stroke=\"#eab308\" stroke-width=\"1\"/>\n  <text x=\"608\" y=\"152\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11.5\" font-weight=\"bold\">③ 꼬리 수거용 풀림 매듭</text>\n\n  <rect x=\"34\" y=\"395\" width=\"340\" height=\"28\" rx=\"3\" fill=\"#0f172a\" stroke=\"#eab308\" stroke-width=\"1\"/>\n  <text x=\"46\" y=\"413\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11.5\" font-weight=\"bold\">④ 으깬 다슬기 미끼 주머니 &amp; 침강용 강돌 2개</text>\n\n  <rect x=\"410\" y=\"395\" width=\"360\" height=\"28\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <text x=\"422\" y=\"413\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11.5\" font-weight=\"bold\">⑤ 여울목 강바닥 나무 말뚝 고정 &amp; 자율 포획 챔버</text>\n</svg>\n","content/svgs/pr11-step-01.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <defs>\n    <linearGradient id=\"bg01\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#090c10\"/>\n      <stop offset=\"100%\" stop-color=\"#0d131a\"/>\n    </linearGradient>\n    <linearGradient id=\"willowBark\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#849b5c\"/>\n      <stop offset=\"50%\" stop-color=\"#5c6e3b\"/>\n      <stop offset=\"100%\" stop-color=\"#364222\"/>\n    </linearGradient>\n    <linearGradient id=\"cordageGold\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#fde68a\"/>\n      <stop offset=\"50%\" stop-color=\"#d97706\"/>\n      <stop offset=\"100%\" stop-color=\"#78350f\"/>\n    </linearGradient>\n    <filter id=\"shadow01\" x=\"-15%\" y=\"-15%\" width=\"130%\" height=\"130%\">\n      <feDropShadow dx=\"0\" dy=\"5\" stdDeviation=\"5\" flood-color=\"#000000\" flood-opacity=\"0.75\"/>\n    </filter>\n    <pattern id=\"grid01\" width=\"20\" height=\"20\" patternUnits=\"userSpaceOnUse\">\n      <path d=\"M 20 0 L 0 0 0 20\" fill=\"none\" stroke=\"#18222d\" stroke-width=\"0.6\"/>\n    </pattern>\n  </defs>\n\n  <rect width=\"400\" height=\"400\" fill=\"url(#bg01)\"/>\n  <rect width=\"400\" height=\"400\" fill=\"url(#grid01)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#263545\" stroke-width=\"1\"/>\n\n  <!-- Top HUD Header -->\n  <rect x=\"16\" y=\"14\" width=\"368\" height=\"28\" fill=\"#101720\" stroke=\"#2c3e50\" stroke-width=\"1\"/>\n  <text x=\"26\" y=\"32\" fill=\"#fde68a\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">FIG. 01 // GRADUATED HOOP RINGS (4 SIZES)</text>\n\n  <!-- Coaxial Alignment Axis Line -->\n  <line x1=\"35\" y1=\"215\" x2=\"365\" y2=\"215\" stroke=\"#38bdf8\" stroke-width=\"1\" stroke-dasharray=\"5,4\" opacity=\"0.65\"/>\n\n  <!-- Spacing Dimension Markers (15cm intervals) -->\n  <g stroke=\"#fde68a\" stroke-width=\"1\" opacity=\"0.8\">\n    <line x1=\"88\" y1=\"305\" x2=\"168\" y2=\"305\"/>\n    <line x1=\"88\" y1=\"298\" x2=\"88\" y2=\"312\"/>\n    <line x1=\"168\" y1=\"298\" x2=\"168\" y2=\"312\"/>\n    <line x1=\"168\" y1=\"305\" x2=\"245\" y2=\"305\"/>\n    <line x1=\"245\" y1=\"298\" x2=\"245\" y2=\"312\"/>\n    <line x1=\"245\" y1=\"305\" x2=\"315\" y2=\"305\"/>\n    <line x1=\"315\" y1=\"298\" x2=\"315\" y2=\"312\"/>\n  </g>\n\n  <!-- 4 Graduated 3D Elliptical Willow Hoops -->\n  <!-- Hoop 1: 25cm (Largest Front Ring) -->\n  <g filter=\"url(#shadow01)\">\n    <ellipse cx=\"88\" cy=\"210\" rx=\"34\" ry=\"78\" fill=\"none\" stroke=\"#283319\" stroke-width=\"11\"/>\n    <ellipse cx=\"88\" cy=\"210\" rx=\"34\" ry=\"78\" fill=\"none\" stroke=\"url(#willowBark)\" stroke-width=\"7.5\"/>\n    <ellipse cx=\"86\" cy=\"210\" rx=\"32\" ry=\"76\" fill=\"none\" stroke=\"#b5cc84\" stroke-width=\"1.2\" opacity=\"0.6\"/>\n    <!-- Top Overlap Cordage Lashing -->\n    <rect x=\"76\" y=\"126\" width=\"24\" height=\"12\" rx=\"3\" fill=\"url(#cordageGold)\" stroke=\"#451a03\" stroke-width=\"1\"/>\n    <line x1=\"81\" y1=\"126\" x2=\"81\" y2=\"138\" stroke=\"#451a03\" stroke-width=\"1\"/>\n    <line x1=\"87\" y1=\"126\" x2=\"87\" y2=\"138\" stroke=\"#451a03\" stroke-width=\"1\"/>\n    <line x1=\"93\" y1=\"126\" x2=\"93\" y2=\"138\" stroke=\"#451a03\" stroke-width=\"1\"/>\n  </g>\n\n  <!-- Hoop 2: 20cm -->\n  <g filter=\"url(#shadow01)\">\n    <ellipse cx=\"168\" cy=\"210\" rx=\"28\" ry=\"63\" fill=\"none\" stroke=\"#283319\" stroke-width=\"10\"/>\n    <ellipse cx=\"168\" cy=\"210\" rx=\"28\" ry=\"63\" fill=\"none\" stroke=\"url(#willowBark)\" stroke-width=\"7\"/>\n    <ellipse cx=\"166\" cy=\"210\" rx=\"26\" ry=\"61\" fill=\"none\" stroke=\"#b5cc84\" stroke-width=\"1\" opacity=\"0.55\"/>\n    <rect x=\"157\" y=\"141\" width=\"22\" height=\"11\" rx=\"3\" fill=\"url(#cordageGold)\" stroke=\"#451a03\" stroke-width=\"1\"/>\n    <line x1=\"163\" y1=\"141\" x2=\"163\" y2=\"152\" stroke=\"#451a03\" stroke-width=\"1\"/>\n    <line x1=\"169\" y1=\"141\" x2=\"169\" y2=\"152\" stroke=\"#451a03\" stroke-width=\"1\"/>\n  </g>\n\n  <!-- Hoop 3: 15cm -->\n  <g filter=\"url(#shadow01)\">\n    <ellipse cx=\"245\" cy=\"210\" rx=\"22\" ry=\"48\" fill=\"none\" stroke=\"#283319\" stroke-width=\"9\"/>\n    <ellipse cx=\"245\" cy=\"210\" rx=\"22\" ry=\"48\" fill=\"none\" stroke=\"url(#willowBark)\" stroke-width=\"6.5\"/>\n    <ellipse cx=\"243\" cy=\"210\" rx=\"20\" ry=\"46\" fill=\"none\" stroke=\"#b5cc84\" stroke-width=\"1\" opacity=\"0.5\"/>\n    <rect x=\"235\" y=\"157\" width=\"20\" height=\"10\" rx=\"2.5\" fill=\"url(#cordageGold)\" stroke=\"#451a03\" stroke-width=\"1\"/>\n  </g>\n\n  <!-- Hoop 4: 10cm (Smallest Tail Ring) -->\n  <g filter=\"url(#shadow01)\">\n    <ellipse cx=\"315\" cy=\"210\" rx=\"16\" ry=\"33\" fill=\"none\" stroke=\"#283319\" stroke-width=\"8.5\"/>\n    <ellipse cx=\"315\" cy=\"210\" rx=\"16\" ry=\"33\" fill=\"none\" stroke=\"url(#willowBark)\" stroke-width=\"6\"/>\n    <ellipse cx=\"313\" cy=\"210\" rx=\"14\" ry=\"31\" fill=\"none\" stroke=\"#b5cc84\" stroke-width=\"1\" opacity=\"0.5\"/>\n    <rect x=\"306\" y=\"172\" width=\"18\" height=\"9\" rx=\"2\" fill=\"url(#cordageGold)\" stroke=\"#451a03\" stroke-width=\"1\"/>\n  </g>\n\n  <!-- Taper Envelope Dashed Guide Lines -->\n  <line x1=\"88\" y1=\"132\" x2=\"315\" y2=\"177\" stroke=\"#94a3b8\" stroke-width=\"1\" stroke-dasharray=\"3,3\" opacity=\"0.5\"/>\n  <line x1=\"88\" y1=\"288\" x2=\"315\" y2=\"243\" stroke=\"#94a3b8\" stroke-width=\"1\" stroke-dasharray=\"3,3\" opacity=\"0.5\"/>\n\n  <!-- Callout Lines & Labels -->\n  <!-- Label 2: Hoop 1 (25cm) -->\n  <line x1=\"88\" y1=\"126\" x2=\"88\" y2=\"75\" stroke=\"#fde68a\" stroke-width=\"1.2\"/>\n  <circle cx=\"88\" cy=\"126\" r=\"3\" fill=\"#fde68a\"/>\n  <rect x=\"18\" y=\"52\" width=\"250\" height=\"24\" rx=\"3\" fill=\"#0f172a\" stroke=\"#fde68a\" stroke-width=\"1\"/>\n  <text x=\"26\" y=\"68\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\">① 입구 대형 림 (한 뼘 반 / 직경 25cm)</text>\n\n  <!-- Label 3: Middle Hoops (20cm, 15cm) -->\n  <line x1=\"206\" y1=\"150\" x2=\"225\" y2=\"108\" stroke=\"#e2e8f0\" stroke-width=\"1.2\"/>\n  <circle cx=\"168\" cy=\"147\" r=\"2.5\" fill=\"#e2e8f0\"/>\n  <circle cx=\"245\" cy=\"162\" r=\"2.5\" fill=\"#e2e8f0\"/>\n  <rect x=\"148\" y=\"86\" width=\"234\" height=\"24\" rx=\"3\" fill=\"#0f172a\" stroke=\"#64748b\" stroke-width=\"1\"/>\n  <text x=\"156\" y=\"102\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">② 중간 림 2개 (직경 20cm · 15cm)</text>\n\n  <!-- Label 4: Small Hoop (10cm) -->\n  <line x1=\"315\" y1=\"175\" x2=\"315\" y2=\"138\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n  <circle cx=\"315\" cy=\"175\" r=\"3\" fill=\"#38bdf8\"/>\n  <rect x=\"152\" y=\"116\" width=\"230\" height=\"24\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <text x=\"160\" y=\"132\" fill=\"#38bdf8\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\">③ 꼬리 소형 림 (주먹 폭 / 직경 10cm)</text>\n\n  <!-- Bottom Callout Banner -->\n  <rect x=\"18\" y=\"344\" width=\"364\" height=\"34\" rx=\"4\" fill=\"#141e28\" stroke=\"#d97706\" stroke-width=\"1.2\"/>\n  <text x=\"32\" y=\"365\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11.5\" font-weight=\"bold\">④ 겹친 끝단 칡 끈 결속 (15cm 간격 배열)</text>\n</svg>\n","content/svgs/pr11-step-02.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <defs>\n    <linearGradient id=\"bg02\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#090c10\"/>\n      <stop offset=\"100%\" stop-color=\"#0d131a\"/>\n    </linearGradient>\n    <linearGradient id=\"ribWood\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#9cb36c\"/>\n      <stop offset=\"50%\" stop-color=\"#6b7f43\"/>\n      <stop offset=\"100%\" stop-color=\"#3f4d25\"/>\n    </linearGradient>\n    <linearGradient id=\"lashAmber\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#fde68a\"/>\n      <stop offset=\"100%\" stop-color=\"#b45309\"/>\n    </linearGradient>\n    <filter id=\"shadow02\" x=\"-15%\" y=\"-15%\" width=\"130%\" height=\"130%\">\n      <feDropShadow dx=\"0\" dy=\"5\" stdDeviation=\"5\" flood-color=\"#000000\" flood-opacity=\"0.75\"/>\n    </filter>\n    <pattern id=\"grid02\" width=\"20\" height=\"20\" patternUnits=\"userSpaceOnUse\">\n      <path d=\"M 20 0 L 0 0 0 20\" fill=\"none\" stroke=\"#18222d\" stroke-width=\"0.6\"/>\n    </pattern>\n  </defs>\n\n  <rect width=\"400\" height=\"400\" fill=\"url(#bg02)\"/>\n  <rect width=\"400\" height=\"400\" fill=\"url(#grid02)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#263545\" stroke-width=\"1\"/>\n\n  <!-- Top HUD Header -->\n  <rect x=\"16\" y=\"14\" width=\"368\" height=\"28\" fill=\"#101720\" stroke=\"#2c3e50\" stroke-width=\"1\"/>\n  <text x=\"26\" y=\"32\" fill=\"#fde68a\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">FIG. 02 // CONICAL WICKER BODY WEAVING</text>\n\n  <!-- 3D Conical Basket Frame (Hoops + Longitudinal Willow Ribs) -->\n  <g filter=\"url(#shadow02)\">\n    <!-- Back half of hoops -->\n    <ellipse cx=\"75\" cy=\"215\" rx=\"26\" ry=\"74\" fill=\"none\" stroke=\"#425029\" stroke-width=\"6\"/>\n    <ellipse cx=\"145\" cy=\"215\" rx=\"22\" ry=\"60\" fill=\"none\" stroke=\"#425029\" stroke-width=\"5.5\"/>\n    <ellipse cx=\"215\" cy=\"215\" rx=\"17\" ry=\"46\" fill=\"none\" stroke=\"#425029\" stroke-width=\"5\"/>\n    <ellipse cx=\"280\" cy=\"215\" rx=\"13\" ry=\"32\" fill=\"none\" stroke=\"#425029\" stroke-width=\"4.5\"/>\n\n    <!-- Longitudinal Willow Ribs (1cm spacing grid converging to tail knot at x=340, y=215) -->\n    <g stroke=\"url(#ribWood)\" stroke-width=\"2.6\" stroke-linecap=\"round\">\n      <line x1=\"75\" y1=\"141\" x2=\"342\" y2=\"207\"/>\n      <line x1=\"70\" y1=\"152\" x2=\"342\" y2=\"209\"/>\n      <line x1=\"65\" y1=\"164\" x2=\"342\" y2=\"210\"/>\n      <line x1=\"60\" y1=\"176\" x2=\"342\" y2=\"212\"/>\n      <line x1=\"56\" y1=\"189\" x2=\"342\" y2=\"213\"/>\n      <line x1=\"53\" y1=\"202\" x2=\"342\" y2=\"214\"/>\n      <line x1=\"52\" y1=\"215\" x2=\"342\" y2=\"215\"/>\n      <line x1=\"53\" y1=\"228\" x2=\"342\" y2=\"216\"/>\n      <line x1=\"56\" y1=\"241\" x2=\"342\" y2=\"217\"/>\n      <line x1=\"60\" y1=\"254\" x2=\"342\" y2=\"218\"/>\n      <line x1=\"65\" y1=\"266\" x2=\"342\" y2=\"220\"/>\n      <line x1=\"70\" y1=\"278\" x2=\"342\" y2=\"221\"/>\n      <line x1=\"75\" y1=\"289\" x2=\"342\" y2=\"223\"/>\n    </g>\n\n    <!-- Front half of hoops & Cross-Lashing Nodes -->\n    <path d=\"M 75 141 A 26 74 0 0 0 75 289\" fill=\"none\" stroke=\"#849b5c\" stroke-width=\"6.5\"/>\n    <path d=\"M 145 155 A 22 60 0 0 0 145 275\" fill=\"none\" stroke=\"#849b5c\" stroke-width=\"6\"/>\n    <path d=\"M 215 169 A 17 46 0 0 0 215 261\" fill=\"none\" stroke=\"#849b5c\" stroke-width=\"5.5\"/>\n    <path d=\"M 280 183 A 13 32 0 0 0 280 247\" fill=\"none\" stroke=\"#849b5c\" stroke-width=\"5\"/>\n\n    <!-- Cordage Lashing Knots along hoops -->\n    <g fill=\"url(#lashAmber)\" stroke=\"#451a03\" stroke-width=\"0.8\">\n      <circle cx=\"145\" cy=\"156\" r=\"3.2\"/>\n      <circle cx=\"132\" cy=\"175\" r=\"3.2\"/>\n      <circle cx=\"125\" cy=\"195\" r=\"3.2\"/>\n      <circle cx=\"123\" cy=\"215\" r=\"3.2\"/>\n      <circle cx=\"125\" cy=\"235\" r=\"3.2\"/>\n      <circle cx=\"132\" cy=\"255\" r=\"3.2\"/>\n      <circle cx=\"145\" cy=\"274\" r=\"3.2\"/>\n\n      <circle cx=\"215\" cy=\"170\" r=\"3\"/>\n      <circle cx=\"203\" cy=\"190\" r=\"3\"/>\n      <circle cx=\"198\" cy=\"215\" r=\"3\"/>\n      <circle cx=\"203\" cy=\"240\" r=\"3\"/>\n      <circle cx=\"215\" cy=\"260\" r=\"3\"/>\n    </g>\n\n    <!-- Tail Retrieval Slip-Knot Binding -->\n    <rect x=\"330\" y=\"201\" width=\"16\" height=\"28\" rx=\"4\" fill=\"url(#lashAmber)\" stroke=\"#451a03\" stroke-width=\"1.2\"/>\n    <path d=\"M 346 210 C 368 195, 372 225, 346 220\" fill=\"none\" stroke=\"#fde68a\" stroke-width=\"2.5\"/>\n  </g>\n\n  <!-- Callouts & Labels -->\n  <!-- Label 2: 30-40 longitudinal willow ribs -->\n  <line x1=\"102\" y1=\"162\" x2=\"102\" y2=\"76\" stroke=\"#fde68a\" stroke-width=\"1.2\"/>\n  <circle cx=\"102\" cy=\"162\" r=\"3\" fill=\"#fde68a\"/>\n  <rect x=\"18\" y=\"52\" width=\"275\" height=\"24\" rx=\"3\" fill=\"#0f172a\" stroke=\"#fde68a\" stroke-width=\"1\"/>\n  <text x=\"26\" y=\"68\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\">버드나무 세로 살 30~40개 (간격 1~1.5cm)</text>\n\n  <!-- Label 3: Hoop-to-rib cross lashing -->\n  <line x1=\"145\" y1=\"156\" x2=\"185\" y2=\"108\" stroke=\"#e2e8f0\" stroke-width=\"1.2\"/>\n  <rect x=\"130\" y=\"86\" width=\"252\" height=\"24\" rx=\"3\" fill=\"#0f172a\" stroke=\"#64748b\" stroke-width=\"1\"/>\n  <text x=\"138\" y=\"102\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">4개 원형 림과 세로 살 교차 감쳐 묶기</text>\n\n  <!-- Label 4: Streamlined cone body -->\n  <line x1=\"215\" y1=\"260\" x2=\"215\" y2=\"310\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n  <circle cx=\"215\" cy=\"260\" r=\"3\" fill=\"#38bdf8\"/>\n  <rect x=\"24\" y=\"310\" width=\"255\" height=\"24\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <text x=\"32\" y=\"326\" fill=\"#38bdf8\" font-family=\"sans-serif\" font-size=\"11\">물살 저항을 줄이는 유선형 원뿔 바구니</text>\n\n  <!-- Label 5: Tail slip-knot -->\n  <line x1=\"348\" y1=\"224\" x2=\"348\" y2=\"344\" stroke=\"#d97706\" stroke-width=\"1.2\"/>\n  <circle cx=\"348\" cy=\"224\" r=\"3\" fill=\"#fde68a\"/>\n  <rect x=\"18\" y=\"344\" width=\"364\" height=\"34\" rx=\"4\" fill=\"#141e28\" stroke=\"#d97706\" stroke-width=\"1.2\"/>\n  <text x=\"32\" y=\"365\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11.5\" font-weight=\"bold\">[핵심] 꼬리 끝 물고기 수거용 개폐 매듭</text>\n</svg>\n","content/svgs/pr11-step-03.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <defs>\n    <linearGradient id=\"bg03\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#090c10\"/>\n      <stop offset=\"100%\" stop-color=\"#0d131a\"/>\n    </linearGradient>\n    <linearGradient id=\"funnelTwig\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n      <stop offset=\"0%\" stop-color=\"#fde68a\"/>\n      <stop offset=\"60%\" stop-color=\"#eab308\"/>\n      <stop offset=\"100%\" stop-color=\"#ca8a04\"/>\n    </linearGradient>\n    <filter id=\"shadow03\" x=\"-15%\" y=\"-15%\" width=\"130%\" height=\"130%\">\n      <feDropShadow dx=\"0\" dy=\"5\" stdDeviation=\"5\" flood-color=\"#000000\" flood-opacity=\"0.75\"/>\n    </filter>\n    <pattern id=\"grid03\" width=\"20\" height=\"20\" patternUnits=\"userSpaceOnUse\">\n      <path d=\"M 20 0 L 0 0 0 20\" fill=\"none\" stroke=\"#18222d\" stroke-width=\"0.6\"/>\n    </pattern>\n  </defs>\n\n  <rect width=\"400\" height=\"400\" fill=\"url(#bg03)\"/>\n  <rect width=\"400\" height=\"400\" fill=\"url(#grid03)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#263545\" stroke-width=\"1\"/>\n\n  <!-- Top HUD Header -->\n  <rect x=\"16\" y=\"14\" width=\"368\" height=\"28\" fill=\"#101720\" stroke=\"#2c3e50\" stroke-width=\"1\"/>\n  <text x=\"26\" y=\"32\" fill=\"#fde68a\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">FIG. 03 // ONE-WAY INVERTED FUNNEL VALVE</text>\n\n  <!-- Cutaway Cross-Section of Outer Basket & Inner Inverted Funnel -->\n  <g filter=\"url(#shadow03)\">\n    <!-- Outer Basket Cutaway Shell (Dimmed Olive) -->\n    <polygon points=\"65,135 345,195 345,235 65,295\" fill=\"#162013\" opacity=\"0.55\"/>\n    <line x1=\"65\" y1=\"135\" x2=\"345\" y2=\"195\" stroke=\"#6b7f43\" stroke-width=\"4\"/>\n    <line x1=\"65\" y1=\"295\" x2=\"345\" y2=\"235\" stroke=\"#6b7f43\" stroke-width=\"4\"/>\n    <ellipse cx=\"65\" cy=\"215\" rx=\"24\" ry=\"80\" fill=\"none\" stroke=\"#849b5c\" stroke-width=\"6\"/>\n\n    <!-- Inner Inverted Funnel Cone (Highlighted Amber/Gold Check-Valve) -->\n    <polygon points=\"65,140 198,196 198,234 65,290\" fill=\"#422006\" opacity=\"0.45\"/>\n    <g stroke=\"url(#funnelTwig)\" stroke-width=\"2.5\" stroke-linecap=\"round\">\n      <line x1=\"65\" y1=\"142\" x2=\"205\" y2=\"198\"/>\n      <line x1=\"65\" y1=\"160\" x2=\"208\" y2=\"203\"/>\n      <line x1=\"65\" y1=\"178\" x2=\"210\" y2=\"208\"/>\n      <line x1=\"65\" y1=\"196\" x2=\"210\" y2=\"212\"/>\n      <line x1=\"65\" y1=\"234\" x2=\"210\" y2=\"218\"/>\n      <line x1=\"65\" y1=\"252\" x2=\"210\" y2=\"222\"/>\n      <line x1=\"65\" y1=\"270\" x2=\"208\" y2=\"227\"/>\n      <line x1=\"65\" y1=\"288\" x2=\"205\" y2=\"232\"/>\n    </g>\n\n    <!-- 5~6cm Narrow Inner Throat Dimension Indicator -->\n    <ellipse cx=\"204\" cy=\"215\" rx=\"7\" ry=\"19\" fill=\"none\" stroke=\"#fde68a\" stroke-width=\"2\" stroke-dasharray=\"3,2\"/>\n\n    <!-- Fish Entry Path Arrow (Green/Cyan) -->\n    <path d=\"M 22 215 L 185 215\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"3\" stroke-dasharray=\"5,3\"/>\n    <polygon points=\"192,215 180,209 180,221\" fill=\"#38bdf8\"/>\n\n    <!-- Trapped Fish Inside Chamber & Blocked Reverse Escape Arrows (Red) -->\n    <path d=\"M 245 215 C 260 202, 288 202, 305 215 C 315 207, 322 204, 324 204 L 320 215 L 324 226 C 322 226, 315 223, 305 215 C 288 228, 260 228, 245 215 Z\" fill=\"#94a3b8\" stroke=\"#f8fafc\" stroke-width=\"1.2\"/>\n    <circle cx=\"256\" cy=\"213\" r=\"2\" fill=\"#0f172a\"/>\n    <!-- Blocked reverse path -->\n    <path d=\"M 245 198 C 228 190, 218 190, 210 196\" fill=\"none\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n    <line x1=\"205\" y1=\"191\" x2=\"215\" y2=\"201\" stroke=\"#ef4444\" stroke-width=\"2.5\"/>\n    <line x1=\"215\" y1=\"191\" x2=\"205\" y2=\"201\" stroke=\"#ef4444\" stroke-width=\"2.5\"/>\n  </g>\n\n  <!-- Callouts & Labels -->\n  <!-- Label 2: Outer rim joined to basket mouth (25cm) -->\n  <line x1=\"65\" y1=\"135\" x2=\"65\" y2=\"76\" stroke=\"#fde68a\" stroke-width=\"1.2\"/>\n  <circle cx=\"65\" cy=\"135\" r=\"3\" fill=\"#fde68a\"/>\n  <rect x=\"18\" y=\"52\" width=\"285\" height=\"24\" rx=\"3\" fill=\"#0f172a\" stroke=\"#fde68a\" stroke-width=\"1\"/>\n  <text x=\"26\" y=\"68\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\">역깔때기 외측 입구 (직경 25cm 몸통 결합)</text>\n\n  <!-- Label 3: Flexible inner twig tips (5-6cm) -->\n  <line x1=\"204\" y1=\"196\" x2=\"225\" y2=\"110\" stroke=\"#fde68a\" stroke-width=\"1.2\"/>\n  <circle cx=\"204\" cy=\"196\" r=\"3\" fill=\"#fde68a\"/>\n  <rect x=\"92\" y=\"86\" width=\"290\" height=\"24\" rx=\"3\" fill=\"#0f172a\" stroke=\"#eab308\" stroke-width=\"1\"/>\n  <text x=\"100\" y=\"102\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11\">안쪽으로 오므라든 탄성 가지 끝단 (직경 5~6cm)</text>\n\n  <!-- Label 4: Expands on entry, blocks reverse -->\n  <line x1=\"210\" y1=\"232\" x2=\"210\" y2=\"310\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n  <circle cx=\"210\" cy=\"232\" r=\"3\" fill=\"#38bdf8\"/>\n  <rect x=\"24\" y=\"310\" width=\"295\" height=\"24\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <text x=\"32\" y=\"326\" fill=\"#38bdf8\" font-family=\"sans-serif\" font-size=\"11\">물고기 진입 시 벌어지고 역진 시 걸리는 구조</text>\n\n  <!-- Label 5: Core Check-Valve Principle -->\n  <rect x=\"18\" y=\"344\" width=\"364\" height=\"34\" rx=\"4\" fill=\"#141e28\" stroke=\"#ef4444\" stroke-width=\"1.2\"/>\n  <text x=\"28\" y=\"365\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11.5\" font-weight=\"bold\">[핵심] 일방향 침입 허용 &amp; 역방향 탈출 원천 차단</text>\n</svg>\n","content/svgs/pr11-step-04.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <defs>\n    <linearGradient id=\"bg04\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#081018\"/>\n      <stop offset=\"100%\" stop-color=\"#0b1924\"/>\n    </linearGradient>\n    <linearGradient id=\"riverRock\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#64748b\"/>\n      <stop offset=\"60%\" stop-color=\"#475569\"/>\n      <stop offset=\"100%\" stop-color=\"#1e293b\"/>\n    </linearGradient>\n    <filter id=\"shadow04\" x=\"-15%\" y=\"-15%\" width=\"130%\" height=\"130%\">\n      <feDropShadow dx=\"0\" dy=\"5\" stdDeviation=\"5\" flood-color=\"#000000\" flood-opacity=\"0.75\"/>\n    </filter>\n    <pattern id=\"grid04\" width=\"20\" height=\"20\" patternUnits=\"userSpaceOnUse\">\n      <path d=\"M 20 0 L 0 0 0 20\" fill=\"none\" stroke=\"#142636\" stroke-width=\"0.6\"/>\n    </pattern>\n  </defs>\n\n  <rect width=\"400\" height=\"400\" fill=\"url(#bg04)\"/>\n  <rect width=\"400\" height=\"400\" fill=\"url(#grid04)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#263545\" stroke-width=\"1\"/>\n\n  <!-- Top HUD Header -->\n  <rect x=\"16\" y=\"14\" width=\"368\" height=\"28\" fill=\"#101720\" stroke=\"#2c3e50\" stroke-width=\"1\"/>\n  <text x=\"26\" y=\"32\" fill=\"#fde68a\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">FIG. 04 // STREAM CHANNEL ANCHORING &amp; BAIT PLUME</text>\n\n  <!-- Stream Water Current Flow Lines (Right to Left: Upstream -> Downstream) -->\n  <g stroke=\"#38bdf8\" stroke-width=\"1.5\" stroke-dasharray=\"6,4\" opacity=\"0.55\" fill=\"none\">\n    <path d=\"M 380 150 C 300 155, 180 155, 25 150\"/>\n    <path d=\"M 380 280 C 300 275, 180 275, 25 280\"/>\n  </g>\n\n  <!-- Scent Plume Diffusing Downstream (Amber Dotted Waves) -->\n  <g stroke=\"#fde68a\" stroke-width=\"1.4\" stroke-dasharray=\"3,4\" opacity=\"0.75\" fill=\"none\">\n    <path d=\"M 215 215 C 160 200, 95 190, 25 182\"/>\n    <path d=\"M 215 215 C 160 215, 95 215, 20 215\"/>\n    <path d=\"M 215 215 C 160 230, 95 240, 25 248\"/>\n  </g>\n\n  <!-- Submerged Conical Trap Anchored Between Rocks & 4 Stakes -->\n  <g filter=\"url(#shadow04)\">\n    <!-- Surrounding Stream Channel Boulders -->\n    <ellipse cx=\"210\" cy=\"132\" rx=\"48\" ry=\"18\" fill=\"url(#riverRock)\" stroke=\"#94a3b8\" stroke-width=\"1\"/>\n    <ellipse cx=\"210\" cy=\"298\" rx=\"52\" ry=\"18\" fill=\"url(#riverRock)\" stroke=\"#94a3b8\" stroke-width=\"1\"/>\n\n    <!-- Conical Fish Trap Body (Mouth facing Left/Downstream or Upstream channel) -->\n    <polygon points=\"115,155 315,192 315,238 115,275\" fill=\"#1e2918\" stroke=\"#849b5c\" stroke-width=\"3\"/>\n    <!-- Inner Funnel Valve -->\n    <polyline points=\"115,160 195,202 195,228 115,270\" fill=\"none\" stroke=\"#fde68a\" stroke-width=\"2.5\"/>\n\n    <!-- 2 Internal Ballast Stones & Crushed Snail Bait Leaf Pouch -->\n    <ellipse cx=\"235\" cy=\"232\" rx=\"16\" ry=\"11\" fill=\"url(#riverRock)\" stroke=\"#cbd5e1\" stroke-width=\"1.2\"/>\n    <ellipse cx=\"272\" cy=\"228\" rx=\"14\" ry=\"10\" fill=\"url(#riverRock)\" stroke=\"#cbd5e1\" stroke-width=\"1.2\"/>\n    <!-- Green Bait Pouch -->\n    <circle cx=\"235\" cy=\"202\" r=\"11\" fill=\"#4d7c0f\" stroke=\"#fde68a\" stroke-width=\"1.5\"/>\n\n    <!-- 4 Wooden Anchor Stakes Driven Around Trap -->\n    <g fill=\"#a16207\" stroke=\"#fde68a\" stroke-width=\"1.2\">\n      <rect x=\"142\" y=\"146\" width=\"7\" height=\"22\" rx=\"2\"/>\n      <rect x=\"265\" y=\"168\" width=\"7\" height=\"22\" rx=\"2\"/>\n      <rect x=\"142\" y=\"262\" width=\"7\" height=\"22\" rx=\"2\"/>\n      <rect x=\"265\" y=\"240\" width=\"7\" height=\"22\" rx=\"2\"/>\n    </g>\n\n    <!-- Fish Swimming Upstream Along Scent Plume Into Funnel -->\n    <path d=\"M 92 215 C 78 205, 55 205, 42 215 C 34 208, 28 206, 26 206 L 30 215 L 26 224 C 28 224, 34 222, 42 215 C 55 225, 78 225, 92 215 Z\" fill=\"#38bdf8\" stroke=\"#f8fafc\" stroke-width=\"1.2\"/>\n    <path d=\"M 96 215 L 138 215\" stroke=\"#fde68a\" stroke-width=\"2.2\"/>\n    <polygon points=\"145,215 135,210 135,220\" fill=\"#fde68a\"/>\n  </g>\n\n  <!-- Callouts & Labels -->\n  <!-- Label 2: 2 Ballast stones & snail bait inside -->\n  <line x1=\"235\" y1=\"202\" x2=\"235\" y2=\"76\" stroke=\"#fde68a\" stroke-width=\"1.2\"/>\n  <circle cx=\"235\" cy=\"202\" r=\"3\" fill=\"#fde68a\"/>\n  <rect x=\"18\" y=\"52\" width=\"295\" height=\"24\" rx=\"3\" fill=\"#0f172a\" stroke=\"#fde68a\" stroke-width=\"1\"/>\n  <text x=\"26\" y=\"68\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\">통발 내부 침강용 강돌 2개 &amp; 으깬 다슬기 미끼</text>\n\n  <!-- Label 3: Stream flow & scent diffusion -->\n  <line x1=\"85\" y1=\"188\" x2=\"125\" y2=\"110\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n  <circle cx=\"85\" cy=\"188\" r=\"3\" fill=\"#38bdf8\"/>\n  <rect x=\"82\" y=\"86\" width=\"300\" height=\"24\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <text x=\"90\" y=\"102\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">상류에서 하류로 흐르는 물살 &amp; 냄새 확산 경로</text>\n\n  <!-- Label 4: 4 Wooden stakes & side boulders -->\n  <line x1=\"146\" y1=\"274\" x2=\"146\" y2=\"310\" stroke=\"#eab308\" stroke-width=\"1.2\"/>\n  <circle cx=\"146\" cy=\"274\" r=\"3\" fill=\"#eab308\"/>\n  <rect x=\"24\" y=\"310\" width=\"275\" height=\"24\" rx=\"3\" fill=\"#0f172a\" stroke=\"#eab308\" stroke-width=\"1\"/>\n  <text x=\"32\" y=\"326\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11\">나무 말뚝 4개 및 양옆 바위 고정 지지대</text>\n\n  <!-- Label 5: Core Outcome -->\n  <rect x=\"18\" y=\"344\" width=\"364\" height=\"34\" rx=\"4\" fill=\"#141e28\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n  <text x=\"26\" y=\"365\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11.5\" font-weight=\"bold\">[핵심] 냄새를 따라 거슬러 올라와 통발에 갇힌 물고기</text>\n</svg>\n","content/svgs/pr12-outcome.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 450\" width=\"100%\" height=\"100%\">\n  <defs>\n    <linearGradient id=\"bgOut12\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#070a0e\"/>\n      <stop offset=\"50%\" stop-color=\"#0d131b\"/>\n      <stop offset=\"100%\" stop-color=\"#080b10\"/>\n    </linearGradient>\n    <linearGradient id=\"outerCanGrad\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n      <stop offset=\"0%\" stop-color=\"#1e293b\"/>\n      <stop offset=\"50%\" stop-color=\"#475569\"/>\n      <stop offset=\"100%\" stop-color=\"#1e293b\"/>\n    </linearGradient>\n    <linearGradient id=\"woodGasFlame\" x1=\"0\" y1=\"1\" x2=\"0\" y2=\"0\">\n      <stop offset=\"0%\" stop-color=\"#38bdf8\"/>\n      <stop offset=\"45%\" stop-color=\"#f97316\"/>\n      <stop offset=\"100%\" stop-color=\"#fde68a\"/>\n    </linearGradient>\n    <filter id=\"shadowOut12\" x=\"-10%\" y=\"-10%\" width=\"120%\" height=\"120%\">\n      <feDropShadow dx=\"0\" dy=\"6\" stdDeviation=\"6\" flood-color=\"#000000\" flood-opacity=\"0.82\"/>\n    </filter>\n    <pattern id=\"gridOut12\" width=\"25\" height=\"25\" patternUnits=\"userSpaceOnUse\">\n      <path d=\"M 25 0 L 0 0 0 25\" fill=\"none\" stroke=\"#152230\" stroke-width=\"0.6\"/>\n    </pattern>\n  </defs>\n\n  <rect width=\"800\" height=\"450\" fill=\"url(#bgOut12)\"/>\n  <rect width=\"800\" height=\"450\" fill=\"url(#gridOut12)\"/>\n  <rect x=\"10\" y=\"10\" width=\"780\" height=\"430\" fill=\"none\" stroke=\"#293d52\" stroke-width=\"1.2\"/>\n\n  <!-- Top Master Header Banner -->\n  <rect x=\"20\" y=\"18\" width=\"760\" height=\"34\" fill=\"#0f1822\" stroke=\"#f97316\" stroke-width=\"1\"/>\n  <text x=\"34\" y=\"40\" fill=\"#fde68a\" font-family=\"monospace\" font-size=\"13\" font-weight=\"bold\">PR-12 MASTER BLUEPRINT // TWIN-CAN DOUBLE-WALL WOOD GAS STOVE (THERMO-FLUID CUTAWAY)</text>\n\n  <!-- Central High-Precision Cutaway of Twin-Can Wood Gas Stove & Boiling Vessel -->\n  <g filter=\"url(#shadowOut12)\">\n    <!-- 3 Flat Insulating Base Stones -->\n    <rect x=\"255\" y=\"365\" width=\"90\" height=\"16\" rx=\"4\" fill=\"#475569\" stroke=\"#94a3b8\" stroke-width=\"1\"/>\n    <rect x=\"355\" y=\"365\" width=\"90\" height=\"16\" rx=\"4\" fill=\"#475569\" stroke=\"#94a3b8\" stroke-width=\"1\"/>\n    <rect x=\"455\" y=\"365\" width=\"90\" height=\"16\" rx=\"4\" fill=\"#475569\" stroke=\"#94a3b8\" stroke-width=\"1\"/>\n\n    <!-- Outer Large Steel Can (x=270 to 530, y=185 to 365) -->\n    <rect x=\"270\" y=\"185\" width=\"260\" height=\"180\" rx=\"5\" fill=\"url(#outerCanGrad)\" stroke=\"#cbd5e1\" stroke-width=\"2.2\"/>\n\n    <!-- Inner Small Pyrolysis Chamber Can (x=310 to 490, y=185 to 325) -->\n    <rect x=\"310\" y=\"185\" width=\"180\" height=\"140\" rx=\"4\" fill=\"#0b1118\" stroke=\"#fde68a\" stroke-width=\"2.2\"/>\n\n    <!-- Vertically Packed Dry Twigs & Glowing Biochar Bed Inside Inner Can -->\n    <g fill=\"#92400e\" stroke=\"#fde68a\" stroke-width=\"0.9\">\n      <rect x=\"324\" y=\"220\" width=\"14\" height=\"95\" rx=\"2\"/>\n      <rect x=\"344\" y=\"218\" width=\"14\" height=\"97\" rx=\"2\"/>\n      <rect x=\"364\" y=\"222\" width=\"14\" height=\"93\" rx=\"2\"/>\n      <rect x=\"384\" y=\"217\" width=\"14\" height=\"98\" rx=\"2\"/>\n      <rect x=\"404\" y=\"220\" width=\"14\" height=\"95\" rx=\"2\"/>\n      <rect x=\"424\" y=\"219\" width=\"14\" height=\"96\" rx=\"2\"/>\n      <rect x=\"444\" y=\"221\" width=\"14\" height=\"94\" rx=\"2\"/>\n      <rect x=\"464\" y=\"218\" width=\"14\" height=\"97\" rx=\"2\"/>\n    </g>\n\n    <!-- Bottom Grate Holes (8mm x 12~15) & Outer Lower Air Intakes (12mm x 8~10) -->\n    <line x1=\"310\" y1=\"325\" x2=\"490\" y2=\"325\" stroke=\"#38bdf8\" stroke-width=\"3\" stroke-dasharray=\"8,5\"/>\n    <g fill=\"#090d12\" stroke=\"#38bdf8\" stroke-width=\"1.8\">\n      <circle cx=\"288\" cy=\"346\" r=\"7\"/>\n      <circle cx=\"335\" cy=\"346\" r=\"7\"/>\n      <circle cx=\"400\" cy=\"346\" r=\"7\"/>\n      <circle cx=\"465\" cy=\"346\" r=\"7\"/>\n      <circle cx=\"512\" cy=\"346\" r=\"7\"/>\n    </g>\n\n    <!-- Secondary Gas Jet Nozzles Near Top of Inner Can (10~12mm x 8~10) -->\n    <g fill=\"#090d12\" stroke=\"#fde68a\" stroke-width=\"1.8\">\n      <circle cx=\"330\" cy=\"204\" r=\"6.5\"/>\n      <circle cx=\"365\" cy=\"204\" r=\"6.5\"/>\n      <circle cx=\"400\" cy=\"204\" r=\"6.5\"/>\n      <circle cx=\"435\" cy=\"204\" r=\"6.5\"/>\n      <circle cx=\"470\" cy=\"204\" r=\"6.5\"/>\n    </g>\n\n    <!-- Preheated Air Rising Through 1.5~2cm Double-Wall Gap (Orange Arrows) -->\n    <path d=\"M 290 338 L 290 204 L 315 204\" fill=\"none\" stroke=\"#f97316\" stroke-width=\"3\"/>\n    <path d=\"M 510 338 L 510 204 L 485 204\" fill=\"none\" stroke=\"#f97316\" stroke-width=\"3\"/>\n\n    <!-- Smokeless Secondary Wood Gas Combustion Vortex Flame -->\n    <path d=\"M 318 204 C 350 192, 375 170, 400 142 C 425 170, 450 192, 482 204 Z\" fill=\"url(#woodGasFlame)\" opacity=\"0.95\"/>\n\n    <!-- Salvaged Wire Trivet & Boiling Water Container on Top -->\n    <rect x=\"295\" y=\"166\" width=\"210\" height=\"18\" rx=\"3\" fill=\"none\" stroke=\"#fbbf24\" stroke-width=\"3\"/>\n    <rect x=\"315\" y=\"96\" width=\"170\" height=\"70\" rx=\"5\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n    <circle cx=\"365\" cy=\"142\" r=\"6\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"1.8\"/>\n    <circle cx=\"400\" cy=\"132\" r=\"7\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"1.8\"/>\n    <circle cx=\"435\" cy=\"140\" r=\"6\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"1.8\"/>\n  </g>\n\n  <!-- Callout Labels (Zero Overlap, High Contrast) -->\n  <rect x=\"24\" y=\"88\" width=\"265\" height=\"28\" rx=\"3\" fill=\"#0f172a\" stroke=\"#fde68a\" stroke-width=\"1\"/>\n  <text x=\"34\" y=\"106\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11.5\" font-weight=\"bold\">① 상단 2차 노즐 (예열 산소 + 목재 가스 완전 연소)</text>\n\n  <rect x=\"515\" y=\"88\" width=\"260\" height=\"28\" rx=\"3\" fill=\"#0f172a\" stroke=\"#fbbf24\" stroke-width=\"1\"/>\n  <text x=\"525\" y=\"106\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11.5\" font-weight=\"bold\">② 피복 벗긴 폐전선 결속 및 오덕 받침대</text>\n\n  <rect x=\"24\" y=\"235\" width=\"230\" height=\"28\" rx=\"3\" fill=\"#0f172a\" stroke=\"#f97316\" stroke-width=\"1\"/>\n  <text x=\"34\" y=\"253\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11.5\" font-weight=\"bold\">③ 내외측 깡통 1.5~2cm 이중 예열 통로</text>\n\n  <rect x=\"546\" y=\"235\" width=\"230\" height=\"28\" rx=\"3\" fill=\"#0f172a\" stroke=\"#eab308\" stroke-width=\"1\"/>\n  <text x=\"556\" y=\"253\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11.5\" font-weight=\"bold\">④ 수직 적재 마른 잔가지 (하향 열분해)</text>\n\n  <rect x=\"24\" y=\"395\" width=\"350\" height=\"28\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <text x=\"36\" y=\"413\" fill=\"#38bdf8\" font-family=\"sans-serif\" font-size=\"11.5\" font-weight=\"bold\">⑤ 하단 외부 찬 공기 흡입구 (12mm) &amp; 내부 바닥 재 배출공</text>\n\n  <rect x=\"412\" y=\"395\" width=\"364\" height=\"28\" rx=\"3\" fill=\"#0f172a\" stroke=\"#f97316\" stroke-width=\"1\"/>\n  <text x=\"420\" y=\"413\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"10.5\" font-weight=\"bold\">⑥ 무연 850℃ 제트 화염 (8분 내 식수 비등 &amp; 바이오차 숯 생성)</text>\n</svg>\n","content/svgs/pr12-step-01.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <defs>\n    <linearGradient id=\"bg1201\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#090b0e\"/>\n      <stop offset=\"100%\" stop-color=\"#0e1318\"/>\n    </linearGradient>\n    <linearGradient id=\"steelCyl\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n      <stop offset=\"0%\" stop-color=\"#475569\"/>\n      <stop offset=\"35%\" stop-color=\"#94a3b8\"/>\n      <stop offset=\"70%\" stop-color=\"#64748b\"/>\n      <stop offset=\"100%\" stop-color=\"#1e293b\"/>\n    </linearGradient>\n    <linearGradient id=\"burnInner\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#1e293b\"/>\n      <stop offset=\"100%\" stop-color=\"#090d12\"/>\n    </linearGradient>\n    <linearGradient id=\"copperWire\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#fbbf24\"/>\n      <stop offset=\"50%\" stop-color=\"#d97706\"/>\n      <stop offset=\"100%\" stop-color=\"#78350f\"/>\n    </linearGradient>\n    <filter id=\"shadow1201\" x=\"-15%\" y=\"-15%\" width=\"130%\" height=\"130%\">\n      <feDropShadow dx=\"0\" dy=\"5\" stdDeviation=\"5\" flood-color=\"#000000\" flood-opacity=\"0.78\"/>\n    </filter>\n    <pattern id=\"grid1201\" width=\"20\" height=\"20\" patternUnits=\"userSpaceOnUse\">\n      <path d=\"M 20 0 L 0 0 0 20\" fill=\"none\" stroke=\"#18222d\" stroke-width=\"0.6\"/>\n    </pattern>\n  </defs>\n\n  <rect width=\"400\" height=\"400\" fill=\"url(#bg1201)\"/>\n  <rect width=\"400\" height=\"400\" fill=\"url(#grid1201)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#263545\" stroke-width=\"1\"/>\n\n  <!-- Top HUD Header -->\n  <rect x=\"16\" y=\"14\" width=\"368\" height=\"28\" fill=\"#101720\" stroke=\"#2c3e50\" stroke-width=\"1\"/>\n  <text x=\"26\" y=\"32\" fill=\"#fde68a\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">FIG. 01 // STEEL CAN SELECTION &amp; LINER BURN-OFF</text>\n\n  <!-- Left: Large Outer Steel Can (12~15cm) with Inner Can (8~10cm) Gap Comparison -->\n  <g filter=\"url(#shadow1201)\">\n    <!-- Outer Can Cylinder Body -->\n    <path d=\"M 65 150 L 65 280 A 68 18 0 0 0 201 280 L 201 150 Z\" fill=\"url(#steelCyl)\" stroke=\"#cbd5e1\" stroke-width=\"1.2\"/>\n    <ellipse cx=\"133\" cy=\"150\" rx=\"68\" ry=\"18\" fill=\"url(#burnInner)\" stroke=\"#e2e8f0\" stroke-width=\"2\"/>\n    <!-- Corrugation Ribs on Outer Steel Can -->\n    <path d=\"M 65 185 A 68 16 0 0 0 201 185\" fill=\"none\" stroke=\"#334155\" stroke-width=\"2\"/>\n    <path d=\"M 65 215 A 68 16 0 0 0 201 215\" fill=\"none\" stroke=\"#334155\" stroke-width=\"2\"/>\n    <path d=\"M 65 245 A 68 16 0 0 0 201 245\" fill=\"none\" stroke=\"#334155\" stroke-width=\"2\"/>\n\n    <!-- Inner Small Can Cylinder Concentric Preview -->\n    <ellipse cx=\"133\" cy=\"150\" rx=\"45\" ry=\"12\" fill=\"#0f172a\" stroke=\"#fde68a\" stroke-width=\"1.8\" stroke-dasharray=\"4,2\"/>\n    <!-- 1.5~2cm Annular Air Gap Arrows -->\n    <line x1=\"66\" y1=\"150\" x2=\"88\" y2=\"150\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n    <line x1=\"178\" y1=\"150\" x2=\"200\" y2=\"150\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n  </g>\n\n  <!-- Right: Pre-Burn (Liner Burn-Off) & Stripped Copper/Steel Wire Coil -->\n  <g filter=\"url(#shadow1201)\">\n    <path d=\"M 248 175 L 248 275 A 45 13 0 0 0 338 275 L 338 175 Z\" fill=\"url(#steelCyl)\" stroke=\"#cbd5e1\" stroke-width=\"1.2\"/>\n    <ellipse cx=\"293\" cy=\"175\" rx=\"45\" ry=\"13\" fill=\"#1e293b\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/>\n    <!-- Pre-burn Flame Purging Epoxy Coating -->\n    <path d=\"M 272 175 C 272 142, 286 135, 293 118 C 300 135, 314 142, 314 175 Z\" fill=\"#f97316\" opacity=\"0.85\"/>\n    <path d=\"M 281 175 C 281 152, 289 145, 293 132 C 297 145, 305 152, 305 175 Z\" fill=\"#fde68a\"/>\n\n    <!-- Stripped Copper/Steel Salvage Wire Coil Below -->\n    <ellipse cx=\"295\" cy=\"296\" rx=\"36\" ry=\"10\" fill=\"none\" stroke=\"url(#copperWire)\" stroke-width=\"3.5\"/>\n    <ellipse cx=\"295\" cy=\"293\" rx=\"32\" ry=\"8\" fill=\"none\" stroke=\"url(#copperWire)\" stroke-width=\"2.5\"/>\n  </g>\n\n  <!-- Callouts & Labels -->\n  <!-- Label 2: Outer (12-15cm) & Inner Can -->\n  <line x1=\"133\" y1=\"132\" x2=\"133\" y2=\"76\" stroke=\"#fde68a\" stroke-width=\"1.2\"/>\n  <circle cx=\"133\" cy=\"132\" r=\"3\" fill=\"#fde68a\"/>\n  <rect x=\"18\" y=\"52\" width=\"335\" height=\"24\" rx=\"3\" fill=\"#0f172a\" stroke=\"#fde68a\" stroke-width=\"1\"/>\n  <text x=\"26\" y=\"68\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\">외부 대형 철제 깡통 (직경 12~15cm) &amp; 내부 소형 깡통</text>\n\n  <!-- Label 3: 1.5~2cm finger-width air gap -->\n  <line x1=\"189\" y1=\"150\" x2=\"215\" y2=\"110\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n  <circle cx=\"189\" cy=\"150\" r=\"3\" fill=\"#38bdf8\"/>\n  <rect x=\"75\" y=\"86\" width=\"307\" height=\"24\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <text x=\"83\" y=\"102\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">내외측 벽면 사이 손가락 한 마디 (1.5~2cm) 공기 틈</text>\n\n  <!-- Label 4: 5-min pre-burn to remove epoxy liner -->\n  <line x1=\"293\" y1=\"245\" x2=\"245\" y2=\"310\" stroke=\"#f97316\" stroke-width=\"1.2\"/>\n  <circle cx=\"293\" cy=\"245\" r=\"3\" fill=\"#f97316\"/>\n  <rect x=\"24\" y=\"310\" width=\"305\" height=\"24\" rx=\"3\" fill=\"#0f172a\" stroke=\"#f97316\" stroke-width=\"1\"/>\n  <text x=\"32\" y=\"326\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11\">사용 전 5분 공소로 내부 에폭시 코팅 완전 제거</text>\n\n  <!-- Label 5: Core Rule -->\n  <rect x=\"18\" y=\"344\" width=\"364\" height=\"34\" rx=\"4\" fill=\"#141e28\" stroke=\"#eab308\" stroke-width=\"1.2\"/>\n  <text x=\"28\" y=\"365\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11.5\" font-weight=\"bold\">[핵심] 고열 강철 깡통 선별 &amp; 피복 벗긴 폐전선 확보</text>\n</svg>\n","content/svgs/pr12-step-02.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <defs>\n    <linearGradient id=\"bg1202\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#090b0e\"/>\n      <stop offset=\"100%\" stop-color=\"#0e1318\"/>\n    </linearGradient>\n    <linearGradient id=\"innerSteel\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n      <stop offset=\"0%\" stop-color=\"#334155\"/>\n      <stop offset=\"40%\" stop-color=\"#94a3b8\"/>\n      <stop offset=\"80%\" stop-color=\"#475569\"/>\n      <stop offset=\"100%\" stop-color=\"#1e293b\"/>\n    </linearGradient>\n    <filter id=\"shadow1202\" x=\"-15%\" y=\"-15%\" width=\"130%\" height=\"130%\">\n      <feDropShadow dx=\"0\" dy=\"5\" stdDeviation=\"5\" flood-color=\"#000000\" flood-opacity=\"0.78\"/>\n    </filter>\n    <pattern id=\"grid1202\" width=\"20\" height=\"20\" patternUnits=\"userSpaceOnUse\">\n      <path d=\"M 20 0 L 0 0 0 20\" fill=\"none\" stroke=\"#18222d\" stroke-width=\"0.6\"/>\n    </pattern>\n  </defs>\n\n  <rect width=\"400\" height=\"400\" fill=\"url(#bg1202)\"/>\n  <rect width=\"400\" height=\"400\" fill=\"url(#grid1202)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#263545\" stroke-width=\"1\"/>\n\n  <!-- Top HUD Header -->\n  <rect x=\"16\" y=\"14\" width=\"368\" height=\"28\" fill=\"#101720\" stroke=\"#2c3e50\" stroke-width=\"1\"/>\n  <text x=\"26\" y=\"32\" fill=\"#fde68a\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">FIG. 02 // INNER BURN CHAMBER PERFORATION</text>\n\n  <!-- Inner Small Can 3D Cutaway Showing Top Secondary Nozzles & Bottom Grate Holes -->\n  <g filter=\"url(#shadow1202)\">\n    <!-- Can Cylinder Body -->\n    <path d=\"M 115 142 L 115 276 A 75 20 0 0 0 265 276 L 265 142 Z\" fill=\"url(#innerSteel)\" stroke=\"#e2e8f0\" stroke-width=\"1.4\"/>\n    <ellipse cx=\"190\" cy=\"142\" rx=\"75\" ry=\"20\" fill=\"#0f172a\" stroke=\"#e2e8f0\" stroke-width=\"2\"/>\n\n    <!-- Top Rim Secondary Gas Jet Nozzles (10~12mm x 8~10 holes, 1.5cm below top rim) -->\n    <g fill=\"#090d12\" stroke=\"#fde68a\" stroke-width=\"1.6\">\n      <circle cx=\"132\" cy=\"168\" r=\"6.5\"/>\n      <circle cx=\"158\" cy=\"173\" r=\"7\"/>\n      <circle cx=\"190\" cy=\"175\" r=\"7.2\"/>\n      <circle cx=\"222\" cy=\"173\" r=\"7\"/>\n      <circle cx=\"248\" cy=\"168\" r=\"6.5\"/>\n    </g>\n\n    <!-- Bottom Grate Cutaway View (12~15 Primary Air & Ash Holes, 8mm) -->\n    <ellipse cx=\"190\" cy=\"276\" rx=\"75\" ry=\"20\" fill=\"#1e293b\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/>\n    <g fill=\"#090d12\" stroke=\"#38bdf8\" stroke-width=\"1.3\">\n      <circle cx=\"155\" cy=\"272\" r=\"4.5\"/>\n      <circle cx=\"178\" cy=\"270\" r=\"4.5\"/>\n      <circle cx=\"202\" cy=\"270\" r=\"4.5\"/>\n      <circle cx=\"225\" cy=\"272\" r=\"4.5\"/>\n      <circle cx=\"166\" cy=\"280\" r=\"4.5\"/>\n      <circle cx=\"190\" cy=\"281\" r=\"4.5\"/>\n      <circle cx=\"214\" cy=\"280\" r=\"4.5\"/>\n      <circle cx=\"190\" cy=\"263\" r=\"4.5\"/>\n    </g>\n\n    <!-- Iron Spike / Nail & Hammerstone Punching Action on Right -->\n    <polygon points=\"255,168 305,152 308,159 255,171\" fill=\"#cbd5e1\" stroke=\"#0f172a\" stroke-width=\"1\"/>\n    <ellipse cx=\"328\" cy=\"148\" rx=\"22\" ry=\"15\" fill=\"#64748b\" stroke=\"#e2e8f0\" stroke-width=\"1.2\"/>\n  </g>\n\n  <!-- Callouts & Labels -->\n  <!-- Label 2: Bottom primary holes (8mm x 12-15) -->\n  <line x1=\"155\" y1=\"272\" x2=\"85\" y2=\"76\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n  <circle cx=\"155\" cy=\"272\" r=\"3\" fill=\"#38bdf8\"/>\n  <rect x=\"18\" y=\"52\" width=\"320\" height=\"24\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <text x=\"26\" y=\"68\" fill=\"#38bdf8\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\">내부 소형 깡통 바닥 1차 흡기공 (8mm × 12~15개)</text>\n\n  <!-- Label 3: Top secondary gas nozzles (10-12mm x 8-10) -->\n  <line x1=\"190\" y1=\"168\" x2=\"190\" y2=\"110\" stroke=\"#fde68a\" stroke-width=\"1.2\"/>\n  <circle cx=\"190\" cy=\"168\" r=\"3\" fill=\"#fde68a\"/>\n  <rect x=\"35\" y=\"86\" width=\"348\" height=\"24\" rx=\"3\" fill=\"#0f172a\" stroke=\"#fde68a\" stroke-width=\"1\"/>\n  <text x=\"43\" y=\"102\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11\">상단 테두리 1.5cm 아래 2차 가스 노즐 (10~12mm × 8~10개)</text>\n\n  <!-- Label 4: Spike & hammerstone punching -->\n  <line x1=\"305\" y1=\"158\" x2=\"285\" y2=\"310\" stroke=\"#e2e8f0\" stroke-width=\"1.2\"/>\n  <circle cx=\"305\" cy=\"158\" r=\"3\" fill=\"#e2e8f0\"/>\n  <rect x=\"24\" y=\"310\" width=\"310\" height=\"24\" rx=\"3\" fill=\"#0f172a\" stroke=\"#64748b\" stroke-width=\"1\"/>\n  <text x=\"32\" y=\"326\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">고철 못과 망치돌 타공 후 날카로운 단면 평탄화</text>\n\n  <!-- Label 5: Core Summary -->\n  <rect x=\"18\" y=\"344\" width=\"364\" height=\"34\" rx=\"4\" fill=\"#141e28\" stroke=\"#eab308\" stroke-width=\"1.2\"/>\n  <text x=\"26\" y=\"365\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11.5\" font-weight=\"bold\">[핵심] 하단 재 배출 &amp; 상단 고온 예열 산소 분사구 완성</text>\n</svg>\n","content/svgs/pr12-step-03.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <defs>\n    <linearGradient id=\"bg1203\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#090b0e\"/>\n      <stop offset=\"100%\" stop-color=\"#0e1318\"/>\n    </linearGradient>\n    <linearGradient id=\"outerWall\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n      <stop offset=\"0%\" stop-color=\"#1e293b\"/>\n      <stop offset=\"50%\" stop-color=\"#475569\"/>\n      <stop offset=\"100%\" stop-color=\"#1e293b\"/>\n    </linearGradient>\n    <filter id=\"shadow1203\" x=\"-15%\" y=\"-15%\" width=\"130%\" height=\"130%\">\n      <feDropShadow dx=\"0\" dy=\"5\" stdDeviation=\"5\" flood-color=\"#000000\" flood-opacity=\"0.78\"/>\n    </filter>\n    <pattern id=\"grid1203\" width=\"20\" height=\"20\" patternUnits=\"userSpaceOnUse\">\n      <path d=\"M 20 0 L 0 0 0 20\" fill=\"none\" stroke=\"#18222d\" stroke-width=\"0.6\"/>\n    </pattern>\n  </defs>\n\n  <rect width=\"400\" height=\"400\" fill=\"url(#bg1203)\"/>\n  <rect width=\"400\" height=\"400\" fill=\"url(#grid1203)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#263545\" stroke-width=\"1\"/>\n\n  <!-- Top HUD Header -->\n  <rect x=\"16\" y=\"14\" width=\"368\" height=\"28\" fill=\"#101720\" stroke=\"#2c3e50\" stroke-width=\"1\"/>\n  <text x=\"26\" y=\"32\" fill=\"#fde68a\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">FIG. 03 // DOUBLE-WALL COAXIAL ASSEMBLY</text>\n\n  <!-- Cross-Section of Outer Can + Suspended Inner Can + Salvage Wire Pot Stand -->\n  <g filter=\"url(#shadow1203)\">\n    <!-- Outer Large Steel Can Cutaway (x=105 to 295, y=148 to 295) -->\n    <rect x=\"105\" y=\"148\" width=\"190\" height=\"147\" rx=\"4\" fill=\"url(#outerWall)\" stroke=\"#cbd5e1\" stroke-width=\"2\"/>\n\n    <!-- Inner Small Steel Can Suspended Inside (x=133 to 267, y=148 to 260) -->\n    <rect x=\"133\" y=\"148\" width=\"134\" height=\"112\" rx=\"3\" fill=\"#0f172a\" stroke=\"#fde68a\" stroke-width=\"2\"/>\n\n    <!-- Bottom 3~4cm Clearance Zone (y=260 to 295) -->\n    <line x1=\"133\" y1=\"260\" x2=\"267\" y2=\"260\" stroke=\"#38bdf8\" stroke-width=\"2\" stroke-dasharray=\"5,3\"/>\n\n    <!-- Outer Can Bottom Side Air Intake Holes (12mm x 8~10 holes) -->\n    <g fill=\"#090d12\" stroke=\"#38bdf8\" stroke-width=\"1.6\">\n      <circle cx=\"118\" cy=\"280\" r=\"6\"/>\n      <circle cx=\"155\" cy=\"280\" r=\"6\"/>\n      <circle cx=\"200\" cy=\"280\" r=\"6\"/>\n      <circle cx=\"245\" cy=\"280\" r=\"6\"/>\n      <circle cx=\"282\" cy=\"280\" r=\"6\"/>\n    </g>\n\n    <!-- Inner Can Upper Secondary Gas Jet Holes -->\n    <g fill=\"#090d12\" stroke=\"#fde68a\" stroke-width=\"1.5\">\n      <circle cx=\"148\" cy=\"166\" r=\"5\"/>\n      <circle cx=\"174\" cy=\"166\" r=\"5\"/>\n      <circle cx=\"200\" cy=\"166\" r=\"5\"/>\n      <circle cx=\"226\" cy=\"166\" r=\"5\"/>\n      <circle cx=\"252\" cy=\"166\" r=\"5\"/>\n    </g>\n\n    <!-- Upward Preheated Air Draft Arrows Inside Annular Gap (Left & Right) -->\n    <path d=\"M 119 272 L 119 166 L 136 166\" fill=\"none\" stroke=\"#f97316\" stroke-width=\"2\"/>\n    <path d=\"M 281 272 L 281 166 L 264 166\" fill=\"none\" stroke=\"#f97316\" stroke-width=\"2\"/>\n\n    <!-- Stripped Salvaged Copper/Steel Wire Rim Binding & Cross Pot-Support Stand Above -->\n    <rect x=\"126\" y=\"132\" width=\"148\" height=\"14\" rx=\"2\" fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"3\"/>\n    <line x1=\"115\" y1=\"138\" x2=\"285\" y2=\"138\" stroke=\"#fbbf24\" stroke-width=\"2.5\"/>\n  </g>\n\n  <!-- Callouts & Labels -->\n  <!-- Label 2: Outer bottom air intakes -->\n  <line x1=\"118\" y1=\"280\" x2=\"72\" y2=\"76\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n  <circle cx=\"118\" cy=\"280\" r=\"3\" fill=\"#38bdf8\"/>\n  <rect x=\"18\" y=\"52\" width=\"335\" height=\"24\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <text x=\"26\" y=\"68\" fill=\"#38bdf8\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\">외부 대형 깡통 하단 찬 공기 흡입구 (12mm × 8~10개)</text>\n\n  <!-- Label 3: Coaxial insertion of inner chamber -->\n  <line x1=\"200\" y1=\"148\" x2=\"225\" y2=\"110\" stroke=\"#fde68a\" stroke-width=\"1.2\"/>\n  <circle cx=\"200\" cy=\"148\" r=\"3\" fill=\"#fde68a\"/>\n  <rect x=\"65\" y=\"86\" width=\"318\" height=\"24\" rx=\"3\" fill=\"#0f172a\" stroke=\"#fde68a\" stroke-width=\"1\"/>\n  <text x=\"73\" y=\"102\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">상단 원형 개방구에 내부 연소실 깡통 수직 삽입</text>\n\n  <!-- Label 4: 3~4cm bottom ash & air plenum clearance -->\n  <line x1=\"200\" y1=\"260\" x2=\"200\" y2=\"310\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n  <circle cx=\"200\" cy=\"260\" r=\"3\" fill=\"#38bdf8\"/>\n  <rect x=\"24\" y=\"310\" width=\"340\" height=\"24\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <text x=\"32\" y=\"326\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11\">바닥에서 3~4cm 띄워 재 받이 및 공기 분배 공간 확보</text>\n\n  <!-- Label 5: Core Wire Lashing & Pot Stand -->\n  <rect x=\"18\" y=\"344\" width=\"364\" height=\"34\" rx=\"4\" fill=\"#141e28\" stroke=\"#f59e0b\" stroke-width=\"1.2\"/>\n  <text x=\"28\" y=\"365\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11.5\" font-weight=\"bold\">[핵심] 폐전선 철사로 상단 고정 및 냄비 받침대 거치</text>\n</svg>\n","content/svgs/pr12-step-04.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <defs>\n    <linearGradient id=\"bg1204\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#090b0e\"/>\n      <stop offset=\"100%\" stop-color=\"#0e1318\"/>\n    </linearGradient>\n    <linearGradient id=\"jetFlame\" x1=\"0\" y1=\"1\" x2=\"0\" y2=\"0\">\n      <stop offset=\"0%\" stop-color=\"#38bdf8\"/>\n      <stop offset=\"40%\" stop-color=\"#f97316\"/>\n      <stop offset=\"100%\" stop-color=\"#fde68a\"/>\n    </linearGradient>\n    <filter id=\"shadow1204\" x=\"-15%\" y=\"-15%\" width=\"130%\" height=\"130%\">\n      <feDropShadow dx=\"0\" dy=\"5\" stdDeviation=\"5\" flood-color=\"#000000\" flood-opacity=\"0.78\"/>\n    </filter>\n    <pattern id=\"grid1204\" width=\"20\" height=\"20\" patternUnits=\"userSpaceOnUse\">\n      <path d=\"M 20 0 L 0 0 0 20\" fill=\"none\" stroke=\"#18222d\" stroke-width=\"0.6\"/>\n    </pattern>\n  </defs>\n\n  <rect width=\"400\" height=\"400\" fill=\"url(#bg1204)\"/>\n  <rect width=\"400\" height=\"400\" fill=\"url(#grid1204)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#263545\" stroke-width=\"1\"/>\n\n  <!-- Top HUD Header -->\n  <rect x=\"16\" y=\"14\" width=\"368\" height=\"28\" fill=\"#101720\" stroke=\"#2c3e50\" stroke-width=\"1\"/>\n  <text x=\"26\" y=\"32\" fill=\"#fde68a\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">FIG. 04 // TOP-DOWN IGNITION &amp; WOOD GAS JET</text>\n\n  <!-- Active Wood Gas Stove with Vertical Twigs, Secondary Flame Jets, and Boiling Water Pot -->\n  <g filter=\"url(#shadow1204)\">\n    <!-- Outer & Inner Can Cutaway -->\n    <rect x=\"110\" y=\"178\" width=\"180\" height=\"118\" rx=\"4\" fill=\"#334155\" stroke=\"#cbd5e1\" stroke-width=\"1.8\"/>\n    <rect x=\"136\" y=\"178\" width=\"128\" height=\"92\" rx=\"3\" fill=\"#0f172a\" stroke=\"#fde68a\" stroke-width=\"1.6\"/>\n\n    <!-- Vertically Stacked Dry Hardwood Twigs Inside Inner Chamber -->\n    <g fill=\"#a16207\" stroke=\"#fde68a\" stroke-width=\"0.8\">\n      <rect x=\"145\" y=\"202\" width=\"10\" height=\"62\" rx=\"2\"/>\n      <rect x=\"159\" y=\"200\" width=\"10\" height=\"64\" rx=\"2\"/>\n      <rect x=\"173\" y=\"203\" width=\"10\" height=\"61\" rx=\"2\"/>\n      <rect x=\"187\" y=\"200\" width=\"10\" height=\"64\" rx=\"2\"/>\n      <rect x=\"201\" y=\"202\" width=\"10\" height=\"62\" rx=\"2\"/>\n      <rect x=\"215\" y=\"201\" width=\"10\" height=\"63\" rx=\"2\"/>\n      <rect x=\"229\" y=\"203\" width=\"10\" height=\"61\" rx=\"2\"/>\n      <rect x=\"243\" y=\"202\" width=\"10\" height=\"62\" rx=\"2\"/>\n    </g>\n\n    <!-- Secondary Preheated Air Jet Flames Shooting Inward from Upper Nozzles -->\n    <path d=\"M 136 190 C 165 182, 185 165, 200 148 C 215 165, 235 182, 264 190 Z\" fill=\"url(#jetFlame)\" opacity=\"0.92\"/>\n\n    <!-- Preheated Air Draft Arrows in Annular Wall (Left & Right) -->\n    <path d=\"M 123 285 L 123 190 L 136 190\" fill=\"none\" stroke=\"#f97316\" stroke-width=\"2.2\"/>\n    <path d=\"M 277 285 L 277 190 L 264 190\" fill=\"none\" stroke=\"#f97316\" stroke-width=\"2.2\"/>\n\n    <!-- Boiling Water Container Resting on Wire Trivet Above Stove (y=115 to 162) -->\n    <rect x=\"142\" y=\"118\" width=\"116\" height=\"44\" rx=\"4\" fill=\"#1e293b\" stroke=\"#38bdf8\" stroke-width=\"1.8\"/>\n    <circle cx=\"175\" cy=\"145\" r=\"4\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"1.5\"/>\n    <circle cx=\"200\" cy=\"138\" r=\"5\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"1.5\"/>\n    <circle cx=\"225\" cy=\"144\" r=\"4\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"1.5\"/>\n  </g>\n\n  <!-- Callouts & Labels -->\n  <!-- Label 2: Vertical dry twigs stacked below upper nozzles -->\n  <line x1=\"145\" y1=\"225\" x2=\"75\" y2=\"76\" stroke=\"#fde68a\" stroke-width=\"1.2\"/>\n  <circle cx=\"145\" cy=\"225\" r=\"3\" fill=\"#fde68a\"/>\n  <rect x=\"18\" y=\"52\" width=\"290\" height=\"24\" rx=\"3\" fill=\"#0f172a\" stroke=\"#fde68a\" stroke-width=\"1\"/>\n  <text x=\"26\" y=\"68\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\">상단 노즐 아래까지 마른 잔가지 수직 적재</text>\n\n  <!-- Label 3: Top-down tinder ignition -->\n  <line x1=\"200\" y1=\"185\" x2=\"255\" y2=\"110\" stroke=\"#f97316\" stroke-width=\"1.2\"/>\n  <circle cx=\"200\" cy=\"185\" r=\"3\" fill=\"#f97316\"/>\n  <rect x=\"105\" y=\"86\" width=\"275\" height=\"24\" rx=\"3\" fill=\"#0f172a\" stroke=\"#f97316\" stroke-width=\"1\"/>\n  <text x=\"113\" y=\"102\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">맨 위 부싯깃 점화 (Top-Down 하향 연소)</text>\n\n  <!-- Label 4: Preheated air injection & smokeless wood gas flame -->\n  <line x1=\"277\" y1=\"235\" x2=\"277\" y2=\"310\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n  <circle cx=\"277\" cy=\"235\" r=\"3\" fill=\"#38bdf8\"/>\n  <rect x=\"24\" y=\"310\" width=\"335\" height=\"24\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <text x=\"32\" y=\"326\" fill=\"#38bdf8\" font-family=\"sans-serif\" font-size=\"11\">이중 벽체 예열 공기 분사 &amp; 무연 2차 가스 화염</text>\n\n  <!-- Label 5: Core Result -->\n  <rect x=\"18\" y=\"344\" width=\"364\" height=\"34\" rx=\"4\" fill=\"#141e28\" stroke=\"#f97316\" stroke-width=\"1.2\"/>\n  <text x=\"28\" y=\"365\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11.5\" font-weight=\"bold\">[핵심] 연기 제로 고열로 8분 만에 식수 비등 살균</text>\n</svg>\n","content/svgs/pr13-outcome.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 450\" width=\"100%\" height=\"100%\">\n  <defs>\n    <linearGradient id=\"bgOut13\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#070a0e\"/>\n      <stop offset=\"50%\" stop-color=\"#0c121a\"/>\n      <stop offset=\"100%\" stop-color=\"#080b10\"/>\n    </linearGradient>\n    <linearGradient id=\"steelMetal\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n      <stop offset=\"0%\" stop-color=\"#1e293b\"/>\n      <stop offset=\"35%\" stop-color=\"#475569\"/>\n      <stop offset=\"70%\" stop-color=\"#334155\"/>\n      <stop offset=\"100%\" stop-color=\"#0f172a\"/>\n    </linearGradient>\n    <linearGradient id=\"ashFill\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#f8fafc\"/>\n      <stop offset=\"50%\" stop-color=\"#cbd5e1\"/>\n      <stop offset=\"100%\" stop-color=\"#94a3b8\"/>\n    </linearGradient>\n    <linearGradient id=\"lyeAmber\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#f59e0b\"/>\n      <stop offset=\"50%\" stop-color=\"#d97706\"/>\n      <stop offset=\"100%\" stop-color=\"#92400e\"/>\n    </linearGradient>\n    <linearGradient id=\"soapPaste\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#fef08a\"/>\n      <stop offset=\"50%\" stop-color=\"#f59e0b\"/>\n      <stop offset=\"100%\" stop-color=\"#ca8a04\"/>\n    </linearGradient>\n    <linearGradient id=\"soapBlock\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#fef08a\"/>\n      <stop offset=\"40%\" stop-color=\"#facc15\"/>\n      <stop offset=\"80%\" stop-color=\"#d97706\"/>\n      <stop offset=\"100%\" stop-color=\"#92400e\"/>\n    </linearGradient>\n    <linearGradient id=\"birchBark\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#f8fafc\"/>\n      <stop offset=\"40%\" stop-color=\"#cbd5e1\"/>\n      <stop offset=\"100%\" stop-color=\"#64748b\"/>\n    </linearGradient>\n    <filter id=\"shadowOut13\" x=\"-10%\" y=\"-10%\" width=\"120%\" height=\"120%\">\n      <feDropShadow dx=\"0\" dy=\"6\" stdDeviation=\"6\" flood-color=\"#000000\" flood-opacity=\"0.85\"/>\n    </filter>\n    <pattern id=\"gridOut13\" width=\"25\" height=\"25\" patternUnits=\"userSpaceOnUse\">\n      <path d=\"M 25 0 L 0 0 0 25\" fill=\"none\" stroke=\"#152230\" stroke-width=\"0.6\"/>\n    </pattern>\n  </defs>\n\n  <!-- Background -->\n  <rect width=\"800\" height=\"450\" fill=\"url(#bgOut13)\"/>\n  <rect width=\"800\" height=\"450\" fill=\"url(#gridOut13)\"/>\n  <rect x=\"10\" y=\"10\" width=\"780\" height=\"430\" fill=\"none\" stroke=\"#293d52\" stroke-width=\"1.2\"/>\n\n  <!-- Top Master Header Banner (Label 1) -->\n  <rect x=\"20\" y=\"18\" width=\"760\" height=\"34\" rx=\"3\" fill=\"#0f1822\" stroke=\"#eab308\" stroke-width=\"1\"/>\n  <text x=\"34\" y=\"40\" fill=\"#fde68a\" font-family=\"monospace\" font-size=\"12\" font-weight=\"bold\">FIG. 13-M // NATURAL WOOD ASH LYE SOAP PRODUCTION OVERVIEW</text>\n\n  <!-- Composite Master Graphics -->\n  <g filter=\"url(#shadowOut13)\">\n    <!-- LEFT PANEL: Wood Ash Column & Potato Buoyancy Test (x=40 to 250) -->\n    <!-- Ash Leaching Column -->\n    <path d=\"M 60 145 L 60 275 A 45 12 0 0 0 150 275 L 150 145 Z\" fill=\"url(#steelMetal)\" stroke=\"#94a3b8\" stroke-width=\"1.2\"/>\n    <ellipse cx=\"105\" cy=\"145\" rx=\"45\" ry=\"12\" fill=\"#1e293b\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/>\n    <!-- Ash Bed Inside -->\n    <path d=\"M 61 147 L 61 250 A 44 11 0 0 0 149 250 L 149 147 Z\" fill=\"url(#ashFill)\"/>\n    <!-- Filter Grass & Pebble Base -->\n    <path d=\"M 61 250 L 61 273 A 44 11 0 0 0 149 273 L 149 250 Z\" fill=\"#4d7c0f\"/>\n\n    <!-- Dripping Amber Lye Droplets -->\n    <path d=\"M 105 290 Q 105 310 105 320\" stroke=\"#f59e0b\" stroke-width=\"2\" stroke-dasharray=\"3,3\"/>\n    <circle cx=\"105\" cy=\"300\" r=\"2.5\" fill=\"#f59e0b\"/>\n\n    <!-- Buoyancy Testing Vessel Beside Column -->\n    <path d=\"M 165 185 L 165 295 A 35 10 0 0 0 235 295 L 235 185 Z\" fill=\"#131c26\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n    <ellipse cx=\"200\" cy=\"185\" rx=\"35\" ry=\"10\" fill=\"#0f172a\" stroke=\"#64748b\" stroke-width=\"1\"/>\n    <!-- Lye in Glass -->\n    <path d=\"M 166 205 L 166 293 A 34 9 0 0 0 234 293 L 234 205 Z\" fill=\"url(#lyeAmber)\" opacity=\"0.9\"/>\n    <!-- Floating Potato Crown -->\n    <ellipse cx=\"200\" cy=\"203\" rx=\"14\" ry=\"9\" fill=\"#d97706\" stroke=\"#fde68a\" stroke-width=\"1\"/>\n    <path d=\"M 188 203 Q 200 193 212 203 Z\" fill=\"#fef08a\"/>\n\n    <!-- CENTER PANEL: Saponification Pot & Stirring (x=270 to 520) -->\n    <!-- Stove Embers Below -->\n    <ellipse cx=\"395\" cy=\"350\" rx=\"75\" ry=\"14\" fill=\"#450a0a\" opacity=\"0.7\"/>\n    <circle cx=\"365\" cy=\"349\" r=\"4\" fill=\"#ea580c\"/>\n    <circle cx=\"395\" cy=\"351\" r=\"4.5\" fill=\"#f97316\"/>\n    <circle cx=\"425\" cy=\"349\" r=\"4\" fill=\"#ea580c\"/>\n\n    <!-- Main Iron Pot -->\n    <path d=\"M 310 175 L 320 330 A 80 18 0 0 0 470 330 L 480 175 Z\" fill=\"url(#steelMetal)\" stroke=\"#cbd5e1\" stroke-width=\"1.8\"/>\n    <ellipse cx=\"395\" cy=\"175\" rx=\"85\" ry=\"20\" fill=\"#1e293b\" stroke=\"#cbd5e1\" stroke-width=\"1.8\"/>\n    <!-- Golden Soap Paste -->\n    <path d=\"M 312 200 L 320 328 A 78 17 0 0 0 470 328 L 478 200 Z\" fill=\"url(#soapPaste)\"/>\n    <ellipse cx=\"395\" cy=\"200\" rx=\"82\" ry=\"18\" fill=\"#facc15\" opacity=\"0.85\"/>\n    <!-- Stirring Flow Orbit -->\n    <ellipse cx=\"395\" cy=\"200\" rx=\"55\" ry=\"10\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2\" stroke-dasharray=\"6,3\"/>\n    <polygon points=\"452,200 448,193 458,196\" fill=\"#38bdf8\"/>\n    <!-- 3s Trace Ridge -->\n    <path d=\"M 355 205 Q 380 193 405 207 Q 430 217 445 203\" fill=\"none\" stroke=\"#fef08a\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n    <!-- Diagonal Spatula -->\n    <g transform=\"rotate(25 395 185)\">\n      <rect x=\"390\" y=\"90\" width=\"10\" height=\"110\" rx=\"2\" fill=\"#78350f\" stroke=\"#291204\" stroke-width=\"1\"/>\n      <path d=\"M 386 195 L 404 195 L 400 220 L 390 220 Z\" fill=\"#78350f\" stroke=\"#291204\" stroke-width=\"1\"/>\n      <path d=\"M 388 210 Q 395 225 402 210 Z\" fill=\"#fef08a\"/>\n    </g>\n\n    <!-- RIGHT PANEL: Cured Birch Mold & Finished Soap Bars (x=540 to 760) -->\n    <!-- Folded Birch Bark Mold Box -->\n    <polygon points=\"545,235 625,200 715,235 635,270\" fill=\"url(#birchBark)\" stroke=\"#1e293b\" stroke-width=\"1.2\"/>\n    <polygon points=\"545,235 635,270 635,315 545,280\" fill=\"#94a3b8\" stroke=\"#1e293b\" stroke-width=\"1.2\"/>\n    <polygon points=\"635,270 715,235 715,280 635,315\" fill=\"#64748b\" stroke=\"#1e293b\" stroke-width=\"1.2\"/>\n    <!-- Bark Texture Lines -->\n    <line x1=\"555\" y1=\"265\" x2=\"585\" y2=\"273\" stroke=\"#1e293b\" stroke-width=\"1.2\"/>\n    <line x1=\"655\" y1=\"293\" x2=\"685\" y2=\"281\" stroke=\"#1e293b\" stroke-width=\"1.2\"/>\n    <!-- Solid Cured Soap in Mold -->\n    <polygon points=\"555,235 625,205 705,235 635,265\" fill=\"url(#soapBlock)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n\n    <!-- Cut Ready-to-Use Soap Bar on Stand (x=680, y=140) -->\n    <polygon points=\"660,150 705,130 750,150 705,170\" fill=\"url(#soapBlock)\" stroke=\"#b45309\" stroke-width=\"1.2\"/>\n    <polygon points=\"660,150 705,170 705,205 660,185\" fill=\"#f59e0b\" stroke=\"#b45309\" stroke-width=\"1.2\"/>\n    <polygon points=\"705,170 750,150 750,185 705,205\" fill=\"#d97706\" stroke=\"#b45309\" stroke-width=\"1.2\"/>\n\n    <!-- Rich White Antimicrobial Froth Bubbles -->\n    <circle cx=\"700\" cy=\"120\" r=\"10\" fill=\"#ffffff\" opacity=\"0.95\"/>\n    <circle cx=\"715\" cy=\"115\" r=\"12\" fill=\"#f8fafc\" opacity=\"0.95\"/>\n    <circle cx=\"730\" cy=\"122\" r=\"11\" fill=\"#ffffff\" opacity=\"0.95\"/>\n    <circle cx=\"710\" cy=\"130\" r=\"9\" fill=\"#f1f5f9\" opacity=\"0.95\"/>\n    <circle cx=\"725\" cy=\"132\" r=\"8\" fill=\"#ffffff\" opacity=\"0.95\"/>\n    <ellipse cx=\"712\" cy=\"112\" rx=\"3\" ry=\"2\" fill=\"#38bdf8\"/>\n    <ellipse cx=\"726\" cy=\"119\" rx=\"3\" ry=\"2\" fill=\"#38bdf8\"/>\n  </g>\n\n  <!-- Process Callout Badges (Labels 2, 3, 4, 5) -->\n  <!-- Label 2: Left Process (x=24, y=70, text y=87) -->\n  <rect x=\"24\" y=\"68\" width=\"280\" height=\"26\" rx=\"3\" fill=\"#0f172a\" stroke=\"#fde68a\" stroke-width=\"1\"/>\n  <text x=\"32\" y=\"85\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"10.5\" font-weight=\"bold\">좌측: 참나무 백탄 재 여과 및 생감자 부력 비중 측정</text>\n\n  <!-- Label 3: Center Process (x=260, y=105, text y=122) -->\n  <rect x=\"260\" y=\"105\" width=\"275\" height=\"26\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <text x=\"268\" y=\"122\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"10.5\" font-weight=\"bold\">중앙: 약불 가열 1:1 비누화 반응 &amp; 송진 첨가 교반</text>\n\n  <!-- Label 4: Right Process (x=495, y=68, text y=85) -->\n  <rect x=\"495\" y=\"68\" width=\"280\" height=\"26\" rx=\"3\" fill=\"#0f172a\" stroke=\"#facc15\" stroke-width=\"1\"/>\n  <text x=\"503\" y=\"85\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"10.5\" font-weight=\"bold\">우측: 수목 수피 거푸집 응고 사각 살균 비누 블록</text>\n\n  <!-- Label 5: Core Summary Rule Banner (x=20, y=388, text y=412) -->\n  <rect x=\"20\" y=\"388\" width=\"760\" height=\"38\" rx=\"4\" fill=\"#141c26\" stroke=\"#eab308\" stroke-width=\"1.2\"/>\n  <text x=\"34\" y=\"412\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"12\" font-weight=\"bold\">[PR-13 최종 완성] 병원균 세포막 사멸 야전 소독 비누</text>\n</svg>","content/svgs/pr13-step-01.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <defs>\n    <linearGradient id=\"bg1301\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#080a0e\"/>\n      <stop offset=\"100%\" stop-color=\"#0e1319\"/>\n    </linearGradient>\n    <linearGradient id=\"canBody\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n      <stop offset=\"0%\" stop-color=\"#334155\"/>\n      <stop offset=\"25%\" stop-color=\"#64748b\"/>\n      <stop offset=\"60%\" stop-color=\"#475569\"/>\n      <stop offset=\"100%\" stop-color=\"#1e293b\"/>\n    </linearGradient>\n    <linearGradient id=\"ashGrad\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#f8fafc\"/>\n      <stop offset=\"50%\" stop-color=\"#cbd5e1\"/>\n      <stop offset=\"100%\" stop-color=\"#94a3b8\"/>\n    </linearGradient>\n    <linearGradient id=\"grassGrad\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n      <stop offset=\"0%\" stop-color=\"#65a30d\"/>\n      <stop offset=\"50%\" stop-color=\"#84cc16\"/>\n      <stop offset=\"100%\" stop-color=\"#4d7c0f\"/>\n    </linearGradient>\n    <linearGradient id=\"amberLye\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#f59e0b\"/>\n      <stop offset=\"50%\" stop-color=\"#d97706\"/>\n      <stop offset=\"100%\" stop-color=\"#b45309\"/>\n    </linearGradient>\n    <filter id=\"drop1301\" x=\"-15%\" y=\"-15%\" width=\"130%\" height=\"130%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"4\" flood-color=\"#000000\" flood-opacity=\"0.8\"/>\n    </filter>\n    <pattern id=\"grid1301\" width=\"20\" height=\"20\" patternUnits=\"userSpaceOnUse\">\n      <path d=\"M 20 0 L 0 0 0 20\" fill=\"none\" stroke=\"#16202c\" stroke-width=\"0.6\"/>\n    </pattern>\n  </defs>\n\n  <!-- Background -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bg1301)\"/>\n  <rect width=\"400\" height=\"400\" fill=\"url(#grid1301)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#253342\" stroke-width=\"1\"/>\n\n  <!-- Top Header (Label 1) -->\n  <rect x=\"16\" y=\"14\" width=\"368\" height=\"28\" rx=\"2\" fill=\"#0f1722\" stroke=\"#2c3e50\" stroke-width=\"1\"/>\n  <text x=\"26\" y=\"32\" fill=\"#fde68a\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">FIG. 01 // WOOD ASH LYE EXTRACTION LEACHER</text>\n\n  <!-- 3D Leaching Column & Collector -->\n  <g filter=\"url(#drop1301)\">\n    <!-- Collecting Basin Below -->\n    <path d=\"M 125 300 L 135 345 A 65 14 0 0 0 265 345 L 275 300 Z\" fill=\"#1e293b\" stroke=\"#64748b\" stroke-width=\"1.2\"/>\n    <ellipse cx=\"200\" cy=\"300\" rx=\"75\" ry=\"14\" fill=\"#0f172a\" stroke=\"#94a3b8\" stroke-width=\"1.5\"/>\n    <ellipse cx=\"200\" cy=\"316\" rx=\"55\" ry=\"10\" fill=\"url(#amberLye)\" opacity=\"0.9\"/>\n\n    <!-- Main Leaching Can Cylinder -->\n    <path d=\"M 115 130 L 115 255 A 85 18 0 0 0 285 255 L 285 130 Z\" fill=\"url(#canBody)\" stroke=\"#94a3b8\" stroke-width=\"1.2\"/>\n    <ellipse cx=\"200\" cy=\"130\" rx=\"85\" ry=\"18\" fill=\"#1e293b\" stroke=\"#cbd5e1\" stroke-width=\"1.8\"/>\n\n    <!-- Cutaway Cross-Section Front View -->\n    <!-- Layer 1: Pebble Bed (Bottom 3cm) -->\n    <path d=\"M 116 238 L 116 254 A 84 18 0 0 0 284 254 L 284 238 A 84 18 0 0 1 116 238 Z\" fill=\"#475569\"/>\n    <circle cx=\"140\" cy=\"245\" r=\"5\" fill=\"#64748b\"/>\n    <circle cx=\"160\" cy=\"248\" r=\"6\" fill=\"#94a3b8\"/>\n    <circle cx=\"185\" cy=\"246\" r=\"5\" fill=\"#64748b\"/>\n    <circle cx=\"215\" cy=\"249\" r=\"6\" fill=\"#94a3b8\"/>\n    <circle cx=\"240\" cy=\"246\" r=\"5.5\" fill=\"#64748b\"/>\n    <circle cx=\"265\" cy=\"244\" r=\"5\" fill=\"#94a3b8\"/>\n\n    <!-- Layer 2: Dry Grass / Fiber Filter (Middle 3cm) -->\n    <path d=\"M 116 220 L 116 238 A 84 18 0 0 0 284 238 L 284 220 A 84 18 0 0 1 116 220 Z\" fill=\"url(#grassGrad)\"/>\n    <!-- Grass fiber hatching -->\n    <path d=\"M 125 224 L 145 234 M 150 223 L 175 235 M 190 224 L 210 236 M 225 223 L 255 235\" stroke=\"#365314\" stroke-width=\"1.5\"/>\n\n    <!-- Layer 3: Packed Pure White Oak Ash Bed (Top 80%) -->\n    <path d=\"M 116 132 L 116 220 A 84 18 0 0 0 284 220 L 284 132 A 84 18 0 0 1 116 132 Z\" fill=\"url(#ashGrad)\"/>\n    <ellipse cx=\"200\" cy=\"132\" rx=\"83\" ry=\"17\" fill=\"#f1f5f9\"/>\n\n    <!-- Hot Water Dripping Pour from Top -->\n    <path d=\"M 200 80 Q 200 110 200 125\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"3\" stroke-dasharray=\"4,2\"/>\n    <ellipse cx=\"200\" cy=\"80\" rx=\"12\" ry=\"4\" fill=\"#38bdf8\"/>\n\n    <!-- Amber Lye Droplets Falling into Collector -->\n    <path d=\"M 198 268 Q 198 285 198 295\" stroke=\"#f59e0b\" stroke-width=\"2.5\" stroke-dasharray=\"3,3\"/>\n    <circle cx=\"198\" cy=\"275\" r=\"2.5\" fill=\"#f59e0b\"/>\n    <circle cx=\"198\" cy=\"288\" r=\"3\" fill=\"#d97706\"/>\n  </g>\n\n  <!-- Callouts & Labels -->\n  <!-- Label 2: Oak White Ash Bed -->\n  <line x1=\"260\" y1=\"165\" x2=\"310\" y2=\"120\" stroke=\"#fde68a\" stroke-width=\"1.2\"/>\n  <circle cx=\"260\" cy=\"165\" r=\"3\" fill=\"#fde68a\"/>\n  <rect x=\"75\" y=\"52\" width=\"250\" height=\"24\" rx=\"3\" fill=\"#0f1722\" stroke=\"#fde68a\" stroke-width=\"1\"/>\n  <text x=\"83\" y=\"68\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\">참나무 백탄 재 (상단 80% 적층)</text>\n\n  <!-- Label 3: Grass & Pebble Buffer Filter -->\n  <line x1=\"120\" y1=\"235\" x2=\"60\" y2=\"235\" stroke=\"#a3e635\" stroke-width=\"1.2\"/>\n  <circle cx=\"120\" cy=\"235\" r=\"3\" fill=\"#a3e635\"/>\n  <rect x=\"20\" y=\"200\" width=\"235\" height=\"24\" rx=\"3\" fill=\"#0f1722\" stroke=\"#a3e635\" stroke-width=\"1\"/>\n  <text x=\"28\" y=\"216\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">바닥 억새풀 섬유층 &amp; 자갈 완충 필터</text>\n\n  <!-- Label 4: Amber Alkali Lye Extraction -->\n  <line x1=\"205\" y1=\"318\" x2=\"275\" y2=\"318\" stroke=\"#f59e0b\" stroke-width=\"1.2\"/>\n  <circle cx=\"205\" cy=\"318\" r=\"3\" fill=\"#f59e0b\"/>\n  <rect x=\"120\" y=\"270\" width=\"265\" height=\"24\" rx=\"3\" fill=\"#0f1722\" stroke=\"#f59e0b\" stroke-width=\"1\"/>\n  <text x=\"128\" y=\"286\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11\">침출 추출되는 짙은 호박색 알칼리 양잿물</text>\n\n  <!-- Label 5: Core Rule -->\n  <rect x=\"16\" y=\"348\" width=\"368\" height=\"34\" rx=\"4\" fill=\"#141c26\" stroke=\"#eab308\" stroke-width=\"1.2\"/>\n  <text x=\"26\" y=\"369\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11.5\" font-weight=\"bold\">[1단계 핵심] 숯 조각 제거 &amp; 끓인 온수 침출 여과</text>\n</svg>","content/svgs/pr13-step-02.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <defs>\n    <linearGradient id=\"bg1302\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#080a0e\"/>\n      <stop offset=\"100%\" stop-color=\"#0e1319\"/>\n    </linearGradient>\n    <linearGradient id=\"lyeLiquid\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#f59e0b\"/>\n      <stop offset=\"70%\" stop-color=\"#d97706\"/>\n      <stop offset=\"100%\" stop-color=\"#92400e\"/>\n    </linearGradient>\n    <linearGradient id=\"potatoSkin\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#d97706\"/>\n      <stop offset=\"50%\" stop-color=\"#b45309\"/>\n      <stop offset=\"100%\" stop-color=\"#78350f\"/>\n    </linearGradient>\n    <linearGradient id=\"clearOil\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#fef08a\"/>\n      <stop offset=\"60%\" stop-color=\"#facc15\"/>\n      <stop offset=\"100%\" stop-color=\"#ca8a04\"/>\n    </linearGradient>\n    <linearGradient id=\"potBody\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n      <stop offset=\"0%\" stop-color=\"#334155\"/>\n      <stop offset=\"35%\" stop-color=\"#64748b\"/>\n      <stop offset=\"70%\" stop-color=\"#475569\"/>\n      <stop offset=\"100%\" stop-color=\"#1e293b\"/>\n    </linearGradient>\n    <filter id=\"drop1302\" x=\"-15%\" y=\"-15%\" width=\"130%\" height=\"130%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"4\" flood-color=\"#000000\" flood-opacity=\"0.8\"/>\n    </filter>\n    <pattern id=\"grid1302\" width=\"20\" height=\"20\" patternUnits=\"userSpaceOnUse\">\n      <path d=\"M 20 0 L 0 0 0 20\" fill=\"none\" stroke=\"#16202c\" stroke-width=\"0.6\"/>\n    </pattern>\n  </defs>\n\n  <!-- Background -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bg1302)\"/>\n  <rect width=\"400\" height=\"400\" fill=\"url(#grid1302)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#253342\" stroke-width=\"1\"/>\n\n  <!-- Top Header (Label 1) -->\n  <rect x=\"16\" y=\"14\" width=\"368\" height=\"28\" rx=\"2\" fill=\"#0f1722\" stroke=\"#2c3e50\" stroke-width=\"1\"/>\n  <text x=\"26\" y=\"32\" fill=\"#fde68a\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">FIG. 02 // POTATO BUOYANCY SPECIFIC GRAVITY TEST</text>\n\n  <!-- 3D Buoyancy Vessel (Left) & Oil Render Pot (Right) -->\n  <g filter=\"url(#drop1302)\">\n    <!-- LEFT: Transparent Lye Testing Vessel -->\n    <path d=\"M 45 130 L 45 270 A 55 14 0 0 0 155 270 L 155 130 Z\" fill=\"#131c26\" stroke=\"#475569\" stroke-width=\"1.2\" opacity=\"0.95\"/>\n    <ellipse cx=\"100\" cy=\"130\" rx=\"55\" ry=\"14\" fill=\"#0f172a\" stroke=\"#64748b\" stroke-width=\"1.2\"/>\n\n    <!-- Lye Liquid Fill -->\n    <path d=\"M 46 160 L 46 268 A 54 13 0 0 0 154 268 L 154 160 Z\" fill=\"url(#lyeLiquid)\" opacity=\"0.85\"/>\n    <ellipse cx=\"100\" cy=\"160\" rx=\"54\" ry=\"13\" fill=\"#f59e0b\" opacity=\"0.7\"/>\n\n    <!-- Floating Potato Piece (Thumb-sized, top 25% exposed above water line) -->\n    <ellipse cx=\"100\" cy=\"158\" rx=\"22\" ry=\"14\" fill=\"url(#potatoSkin)\" stroke=\"#fbbf24\" stroke-width=\"1\"/>\n    <!-- Exposed crown above water -->\n    <path d=\"M 80 158 Q 100 144 120 158 Z\" fill=\"#fef08a\" stroke=\"#ca8a04\" stroke-width=\"0.8\"/>\n    <!-- Meniscus Water Ring Around Potato -->\n    <ellipse cx=\"100\" cy=\"160\" rx=\"26\" ry=\"6\" fill=\"none\" stroke=\"#fde68a\" stroke-width=\"1.2\" stroke-dasharray=\"3,2\"/>\n    <!-- Buoyancy Vector Indicator -->\n    <line x1=\"100\" y1=\"180\" x2=\"100\" y2=\"162\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n    <polygon points=\"100,156 96,164 104,164\" fill=\"#38bdf8\"/>\n\n    <!-- RIGHT: Rendered Animal Fat / Salvaged Oil Pot -->\n    <path d=\"M 235 150 L 235 270 A 65 15 0 0 0 365 270 L 365 150 Z\" fill=\"url(#potBody)\" stroke=\"#94a3b8\" stroke-width=\"1.2\"/>\n    <ellipse cx=\"300\" cy=\"150\" rx=\"65\" ry=\"15\" fill=\"#1e293b\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/>\n\n    <!-- Golden Clear Rendered Oil Layer -->\n    <path d=\"M 236 175 L 236 268 A 64 14 0 0 0 364 268 L 364 175 Z\" fill=\"url(#clearOil)\"/>\n    <ellipse cx=\"300\" cy=\"175\" rx=\"64\" ry=\"14\" fill=\"#fef08a\" opacity=\"0.8\"/>\n\n    <!-- Floating Filtered Cracklings Skimmed on Rim -->\n    <circle cx=\"280\" cy=\"172\" r=\"4\" fill=\"#78350f\"/>\n    <circle cx=\"310\" cy=\"176\" r=\"3.5\" fill=\"#92400e\"/>\n    <circle cx=\"325\" cy=\"173\" r=\"4.5\" fill=\"#78350f\"/>\n\n    <!-- Gentle Embers Glowing Below Pot -->\n    <ellipse cx=\"300\" cy=\"285\" rx=\"50\" ry=\"8\" fill=\"#450a0a\" opacity=\"0.7\"/>\n    <circle cx=\"285\" cy=\"284\" r=\"3\" fill=\"#ea580c\"/>\n    <circle cx=\"315\" cy=\"285\" r=\"3\" fill=\"#f97316\"/>\n  </g>\n\n  <!-- Callouts & Labels -->\n  <!-- Label 2: Potato Buoyancy Crown -->\n  <line x1=\"100\" y1=\"150\" x2=\"65\" y2=\"88\" stroke=\"#fde68a\" stroke-width=\"1.2\"/>\n  <circle cx=\"100\" cy=\"150\" r=\"3\" fill=\"#fde68a\"/>\n  <rect x=\"20\" y=\"64\" width=\"280\" height=\"24\" rx=\"3\" fill=\"#0f1722\" stroke=\"#fde68a\" stroke-width=\"1\"/>\n  <text x=\"28\" y=\"80\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\">수면 위로 엄지손톱 크기만큼 부유하는 생감자</text>\n\n  <!-- Label 3: Specific Gravity Adjustment -->\n  <line x1=\"100\" y1=\"210\" x2=\"45\" y2=\"210\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n  <circle cx=\"100\" cy=\"210\" r=\"3\" fill=\"#38bdf8\"/>\n  <rect x=\"18\" y=\"222\" width=\"280\" height=\"24\" rx=\"3\" fill=\"#0f1722\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <text x=\"26\" y=\"238\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">비중 부족 시 약불 농축 &amp; 과도 시 온수 희석</text>\n\n  <!-- Label 4: Rendered Oil 2 Cups -->\n  <line x1=\"300\" y1=\"210\" x2=\"330\" y2=\"120\" stroke=\"#facc15\" stroke-width=\"1.2\"/>\n  <circle cx=\"300\" cy=\"210\" r=\"3\" fill=\"#facc15\"/>\n  <rect x=\"95\" y=\"105\" width=\"285\" height=\"24\" rx=\"3\" fill=\"#0f1722\" stroke=\"#facc15\" stroke-width=\"1\"/>\n  <text x=\"103\" y=\"121\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11\">동물 비계 열탕 용출 및 맑은 정제유 2컵 확보</text>\n\n  <!-- Label 5: Core Rule -->\n  <rect x=\"16\" y=\"348\" width=\"368\" height=\"34\" rx=\"4\" fill=\"#141c26\" stroke=\"#eab308\" stroke-width=\"1.2\"/>\n  <text x=\"26\" y=\"369\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11.5\" font-weight=\"bold\">[2단계 핵심] 감자 부력 검증 &amp; 유지 불순물 완전 분리</text>\n</svg>","content/svgs/pr13-step-03.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <defs>\n    <linearGradient id=\"bg1303\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#080a0e\"/>\n      <stop offset=\"100%\" stop-color=\"#0e1319\"/>\n    </linearGradient>\n    <linearGradient id=\"potMetal\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n      <stop offset=\"0%\" stop-color=\"#334155\"/>\n      <stop offset=\"20%\" stop-color=\"#64748b\"/>\n      <stop offset=\"60%\" stop-color=\"#475569\"/>\n      <stop offset=\"100%\" stop-color=\"#1e293b\"/>\n    </linearGradient>\n    <linearGradient id=\"pasteGrad\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#fef08a\"/>\n      <stop offset=\"50%\" stop-color=\"#f59e0b\"/>\n      <stop offset=\"100%\" stop-color=\"#b45309\"/>\n    </linearGradient>\n    <linearGradient id=\"spatulaWood\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n      <stop offset=\"0%\" stop-color=\"#78350f\"/>\n      <stop offset=\"50%\" stop-color=\"#b45309\"/>\n      <stop offset=\"100%\" stop-color=\"#451a03\"/>\n    </linearGradient>\n    <linearGradient id=\"resinAmber\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#fef08a\"/>\n      <stop offset=\"50%\" stop-color=\"#f59e0b\"/>\n      <stop offset=\"100%\" stop-color=\"#d97706\"/>\n    </linearGradient>\n    <filter id=\"drop1303\" x=\"-15%\" y=\"-15%\" width=\"130%\" height=\"130%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"4\" flood-color=\"#000000\" flood-opacity=\"0.8\"/>\n    </filter>\n    <pattern id=\"grid1303\" width=\"20\" height=\"20\" patternUnits=\"userSpaceOnUse\">\n      <path d=\"M 20 0 L 0 0 0 20\" fill=\"none\" stroke=\"#16202c\" stroke-width=\"0.6\"/>\n    </pattern>\n  </defs>\n\n  <!-- Background -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bg1303)\"/>\n  <rect width=\"400\" height=\"400\" fill=\"url(#grid1303)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#253342\" stroke-width=\"1\"/>\n\n  <!-- Top Header (Label 1) -->\n  <rect x=\"16\" y=\"14\" width=\"368\" height=\"28\" rx=\"2\" fill=\"#0f1722\" stroke=\"#2c3e50\" stroke-width=\"1\"/>\n  <text x=\"26\" y=\"32\" fill=\"#fde68a\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">FIG. 03 // SAPONIFICATION REACTION &amp; STIRRING</text>\n\n  <!-- Saponification Pot & Stirring Spatula -->\n  <g filter=\"url(#drop1303)\">\n    <!-- Stove / Embers Base Below Pot -->\n    <ellipse cx=\"200\" cy=\"305\" rx=\"90\" ry=\"15\" fill=\"#450a0a\" opacity=\"0.6\"/>\n    <circle cx=\"170\" cy=\"303\" r=\"4\" fill=\"#ea580c\"/>\n    <circle cx=\"200\" cy=\"306\" r=\"4.5\" fill=\"#f97316\"/>\n    <circle cx=\"230\" cy=\"304\" r=\"3.5\" fill=\"#ea580c\"/>\n\n    <!-- Main Steel Pot Body -->\n    <path d=\"M 100 145 L 110 290 A 90 20 0 0 0 290 290 L 300 145 Z\" fill=\"url(#potMetal)\" stroke=\"#94a3b8\" stroke-width=\"1.5\"/>\n    <ellipse cx=\"200\" cy=\"145\" rx=\"100\" ry=\"22\" fill=\"#1e293b\" stroke=\"#cbd5e1\" stroke-width=\"2\"/>\n\n    <!-- Saponified Viscous Soap Paste (Peanut Butter Texture) -->\n    <path d=\"M 102 175 L 110 288 A 88 19 0 0 0 290 288 L 298 175 Z\" fill=\"url(#pasteGrad)\"/>\n    <ellipse cx=\"200\" cy=\"175\" rx=\"96\" ry=\"20\" fill=\"#facc15\" opacity=\"0.8\"/>\n\n    <!-- Clockwise Circular Stirring Orbit Arrows -->\n    <ellipse cx=\"200\" cy=\"175\" rx=\"65\" ry=\"12\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2\" stroke-dasharray=\"8,4\"/>\n    <polygon points=\"268,175 264,167 274,171\" fill=\"#38bdf8\"/>\n\n    <!-- 3-Second Trace Raised Ribbon on Paste Surface -->\n    <path d=\"M 155 180 Q 185 165 210 182 Q 235 195 250 178\" fill=\"none\" stroke=\"#fef08a\" stroke-width=\"4.5\" stroke-linecap=\"round\"/>\n\n    <!-- Wooden Paddle Spatula Held Diagonally -->\n    <g transform=\"rotate(22 200 160)\">\n      <!-- Paddle Handle -->\n      <rect x=\"194\" y=\"60\" width=\"12\" height=\"120\" rx=\"3\" fill=\"url(#spatulaWood)\" stroke=\"#291204\" stroke-width=\"1\"/>\n      <!-- Paddle Flat Blade -->\n      <path d=\"M 190 175 L 210 175 L 206 205 L 194 205 Z\" fill=\"url(#spatulaWood)\" stroke=\"#291204\" stroke-width=\"1\"/>\n      <!-- Soap Paste Clinging to Blade Tip -->\n      <path d=\"M 192 195 Q 200 215 208 195 Z\" fill=\"#fef08a\" stroke=\"#d97706\" stroke-width=\"1\"/>\n    </g>\n\n    <!-- Pine Resin Amber Powder Falling into Mix -->\n    <circle cx=\"140\" cy=\"150\" r=\"3\" fill=\"url(#resinAmber)\"/>\n    <circle cx=\"146\" cy=\"156\" r=\"2.5\" fill=\"url(#resinAmber)\"/>\n    <circle cx=\"135\" cy=\"160\" r=\"3.5\" fill=\"url(#resinAmber)\"/>\n    <circle cx=\"152\" cy=\"163\" r=\"2\" fill=\"url(#resinAmber)\"/>\n  </g>\n\n  <!-- Callouts & Labels -->\n  <!-- Label 2: 1:1 Mixture Ratio -->\n  <line x1=\"110\" y1=\"210\" x2=\"60\" y2=\"125\" stroke=\"#fde68a\" stroke-width=\"1.2\"/>\n  <circle cx=\"110\" cy=\"210\" r=\"3\" fill=\"#fde68a\"/>\n  <rect x=\"18\" y=\"52\" width=\"265\" height=\"24\" rx=\"3\" fill=\"#0f1722\" stroke=\"#fde68a\" stroke-width=\"1\"/>\n  <text x=\"26\" y=\"68\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\">양잿물과 정제 기름 1:1 부피 비율 혼합액</text>\n\n  <!-- Label 3: Unidirectional 45-min Stirring -->\n  <line x1=\"265\" y1=\"172\" x2=\"310\" y2=\"105\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n  <circle cx=\"265\" cy=\"172\" r=\"3\" fill=\"#38bdf8\"/>\n  <rect x=\"95\" y=\"90\" width=\"285\" height=\"24\" rx=\"3\" fill=\"#0f1722\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <text x=\"103\" y=\"106\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">납작한 나무 주걱으로 한 방향 45분 연속 교반</text>\n\n  <!-- Label 4: 3-Second Trace Raised Trail -->\n  <line x1=\"210\" y1=\"182\" x2=\"250\" y2=\"235\" stroke=\"#facc15\" stroke-width=\"1.2\"/>\n  <circle cx=\"210\" cy=\"182\" r=\"3\" fill=\"#facc15\"/>\n  <rect x=\"85\" y=\"240\" width=\"295\" height=\"24\" rx=\"3\" fill=\"#0f1722\" stroke=\"#facc15\" stroke-width=\"1\"/>\n  <text x=\"93\" y=\"256\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11\">주걱 자국이 3초 유지되는 걸쭉한 트레이스 완성</text>\n\n  <!-- Label 5: Core Rule -->\n  <rect x=\"16\" y=\"348\" width=\"368\" height=\"34\" rx=\"4\" fill=\"#141c26\" stroke=\"#eab308\" stroke-width=\"1.2\"/>\n  <text x=\"26\" y=\"369\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11.5\" font-weight=\"bold\">[3단계 핵심] 약불 은근한 가열 &amp; 송진 가루 혼합</text>\n</svg>","content/svgs/pr13-step-04.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <defs>\n    <linearGradient id=\"bg1304\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#080a0e\"/>\n      <stop offset=\"100%\" stop-color=\"#0e1319\"/>\n    </linearGradient>\n    <linearGradient id=\"barkGrad\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#f1f5f9\"/>\n      <stop offset=\"30%\" stop-color=\"#cbd5e1\"/>\n      <stop offset=\"70%\" stop-color=\"#94a3b8\"/>\n      <stop offset=\"100%\" stop-color=\"#475569\"/>\n    </linearGradient>\n    <linearGradient id=\"soapBar\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#fef08a\"/>\n      <stop offset=\"50%\" stop-color=\"#f59e0b\"/>\n      <stop offset=\"100%\" stop-color=\"#d97706\"/>\n    </linearGradient>\n    <linearGradient id=\"handSkin\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n      <stop offset=\"0%\" stop-color=\"#d97706\"/>\n      <stop offset=\"40%\" stop-color=\"#b45309\"/>\n      <stop offset=\"100%\" stop-color=\"#78350f\"/>\n    </linearGradient>\n    <filter id=\"drop1304\" x=\"-15%\" y=\"-15%\" width=\"130%\" height=\"130%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"4\" flood-color=\"#000000\" flood-opacity=\"0.8\"/>\n    </filter>\n    <pattern id=\"grid1304\" width=\"20\" height=\"20\" patternUnits=\"userSpaceOnUse\">\n      <path d=\"M 20 0 L 0 0 0 20\" fill=\"none\" stroke=\"#16202c\" stroke-width=\"0.6\"/>\n    </pattern>\n  </defs>\n\n  <!-- Background -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bg1304)\"/>\n  <rect width=\"400\" height=\"400\" fill=\"url(#grid1304)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#253342\" stroke-width=\"1\"/>\n\n  <!-- Top Header (Label 1) -->\n  <rect x=\"16\" y=\"14\" width=\"368\" height=\"28\" rx=\"2\" fill=\"#0f1722\" stroke=\"#2c3e50\" stroke-width=\"1\"/>\n  <text x=\"26\" y=\"32\" fill=\"#fde68a\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">FIG. 04 // MOLD CASTING &amp; FOAM SAFETY TEST</text>\n\n  <!-- Birch Bark Mold (Left) & Hand Lather Foam Test (Right) -->\n  <g filter=\"url(#drop1304)\">\n    <!-- LEFT: Folded Birch Bark Rectangular Mold with Cured Soap -->\n    <!-- Mold Outer Box -->\n    <polygon points=\"40,215 110,185 185,215 115,245\" fill=\"url(#barkGrad)\" stroke=\"#1e293b\" stroke-width=\"1.2\"/>\n    <polygon points=\"40,215 115,245 115,285 40,255\" fill=\"#94a3b8\" stroke=\"#1e293b\" stroke-width=\"1.2\"/>\n    <polygon points=\"115,245 185,215 185,255 115,285\" fill=\"#64748b\" stroke=\"#1e293b\" stroke-width=\"1.2\"/>\n    <!-- Bark Texture Streaks -->\n    <line x1=\"45\" y1=\"240\" x2=\"65\" y2=\"248\" stroke=\"#1e293b\" stroke-width=\"1.2\"/>\n    <line x1=\"125\" y1=\"265\" x2=\"155\" y2=\"253\" stroke=\"#1e293b\" stroke-width=\"1.2\"/>\n\n    <!-- Hardened Solid Soap Block Inside Mold -->\n    <polygon points=\"50,215 110,190 175,215 115,240\" fill=\"url(#soapBar)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n    <!-- Cut Lines Dividing Bars -->\n    <line x1=\"80\" y1=\"202\" x2=\"82\" y2=\"227\" stroke=\"#92400e\" stroke-width=\"1.5\" stroke-dasharray=\"3,2\"/>\n    <line x1=\"140\" y1=\"202\" x2=\"142\" y2=\"227\" stroke=\"#92400e\" stroke-width=\"1.5\" stroke-dasharray=\"3,2\"/>\n\n    <!-- Cut Single Soap Bar Standing Beside Mold -->\n    <polygon points=\"65,160 95,145 125,160 95,175\" fill=\"url(#soapBar)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n    <polygon points=\"65,160 95,175 95,200 65,185\" fill=\"#f59e0b\" stroke=\"#b45309\" stroke-width=\"1\"/>\n    <polygon points=\"95,175 125,160 125,185 95,200\" fill=\"#d97706\" stroke=\"#b45309\" stroke-width=\"1\"/>\n\n    <!-- RIGHT: Survivalist Hand Lather Foam Test -->\n    <!-- Forearm & Back of Hand -->\n    <path d=\"M 370 290 Q 330 270 295 240 Q 275 220 260 215 Q 240 220 235 240 Q 260 265 300 295 Z\" fill=\"url(#handSkin)\" stroke=\"#451a03\" stroke-width=\"1.5\"/>\n    <!-- Thumb & Knuckles -->\n    <ellipse cx=\"255\" cy=\"215\" rx=\"12\" ry=\"8\" fill=\"#d97706\" stroke=\"#451a03\" stroke-width=\"1\"/>\n    <ellipse cx=\"275\" cy=\"212\" rx=\"10\" ry=\"7\" fill=\"#b45309\"/>\n    <ellipse cx=\"292\" cy=\"215\" rx=\"9\" ry=\"7\" fill=\"#b45309\"/>\n\n    <!-- Rich White Soapy Froth / Micro Foam Bubbles over Back of Hand -->\n    <circle cx=\"265\" cy=\"235\" r=\"9\" fill=\"#ffffff\" opacity=\"0.95\"/>\n    <circle cx=\"278\" cy=\"230\" r=\"11\" fill=\"#f8fafc\" opacity=\"0.95\"/>\n    <circle cx=\"290\" cy=\"240\" r=\"12\" fill=\"#ffffff\" opacity=\"0.95\"/>\n    <circle cx=\"272\" cy=\"248\" r=\"10\" fill=\"#f1f5f9\" opacity=\"0.95\"/>\n    <circle cx=\"285\" cy=\"252\" r=\"11\" fill=\"#ffffff\" opacity=\"0.95\"/>\n    <circle cx=\"258\" cy=\"245\" r=\"7\" fill=\"#e2e8f0\" opacity=\"0.95\"/>\n    <circle cx=\"302\" cy=\"246\" r=\"8\" fill=\"#ffffff\" opacity=\"0.95\"/>\n    <circle cx=\"296\" cy=\"232\" r=\"7\" fill=\"#f8fafc\" opacity=\"0.95\"/>\n    <!-- Bubble Gleams -->\n    <ellipse cx=\"276\" cy=\"227\" rx=\"3\" ry=\"2\" fill=\"#38bdf8\"/>\n    <ellipse cx=\"288\" cy=\"237\" rx=\"3\" ry=\"2\" fill=\"#38bdf8\"/>\n    <ellipse cx=\"263\" cy=\"233\" rx=\"2\" ry=\"1.5\" fill=\"#38bdf8\"/>\n  </g>\n\n  <!-- Callouts & Labels -->\n  <!-- Label 2: Birch Bark Mold -->\n  <line x1=\"80\" y1=\"145\" x2=\"50\" y2=\"90\" stroke=\"#fde68a\" stroke-width=\"1.2\"/>\n  <circle cx=\"80\" cy=\"145\" r=\"3\" fill=\"#fde68a\"/>\n  <rect x=\"20\" y=\"60\" width=\"260\" height=\"24\" rx=\"3\" fill=\"#0f1722\" stroke=\"#fde68a\" stroke-width=\"1\"/>\n  <text x=\"28\" y=\"76\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\">자작나무 껍질 사각 거푸집 성형 및 타설</text>\n\n  <!-- Label 3: 48h Natural Curing in Shade -->\n  <line x1=\"150\" y1=\"215\" x2=\"200\" y2=\"120\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n  <circle cx=\"150\" cy=\"215\" r=\"3\" fill=\"#38bdf8\"/>\n  <rect x=\"90\" y=\"95\" width=\"275\" height=\"24\" rx=\"3\" fill=\"#0f1722\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <text x=\"98\" y=\"111\" fill=\"#f8fafc\" font-family=\"sans-serif\" font-size=\"11\">48시간 서늘한 바람 그늘 자연 응고 경화</text>\n\n  <!-- Label 4: Hand Foam Safety Test -->\n  <line x1=\"280\" y1=\"235\" x2=\"310\" y2=\"155\" stroke=\"#facc15\" stroke-width=\"1.2\"/>\n  <circle cx=\"280\" cy=\"235\" r=\"3\" fill=\"#facc15\"/>\n  <rect x=\"75\" y=\"160\" width=\"310\" height=\"24\" rx=\"3\" fill=\"#0f1722\" stroke=\"#facc15\" stroke-width=\"1\"/>\n  <text x=\"83\" y=\"176\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11\">손등 문지름 시 따끔거림 없는 풍성한 미세 거품</text>\n\n  <!-- Label 5: Core Rule -->\n  <rect x=\"16\" y=\"348\" width=\"368\" height=\"34\" rx=\"4\" fill=\"#141c26\" stroke=\"#eab308\" stroke-width=\"1.2\"/>\n  <text x=\"26\" y=\"369\" fill=\"#fde68a\" font-family=\"sans-serif\" font-size=\"11.5\" font-weight=\"bold\">[4단계 핵심] 완전 건조 숙성 &amp; 피부 안전성 통과</text>\n</svg>","content/svgs/pr14-outcome.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 450\" width=\"100%\" height=\"100%\">\n  <defs>\n    <linearGradient id=\"bgOut14\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#070a0e\"/>\n      <stop offset=\"50%\" stop-color=\"#0c121a\"/>\n      <stop offset=\"100%\" stop-color=\"#080b10\"/>\n    </linearGradient>\n    <linearGradient id=\"boneOut\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#ffffff\"/>\n      <stop offset=\"30%\" stop-color=\"#f8fafc\"/>\n      <stop offset=\"70%\" stop-color=\"#e2e8f0\"/>\n      <stop offset=\"100%\" stop-color=\"#cbd5e1\"/>\n    </linearGradient>\n    <linearGradient id=\"sinewOutAmber\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n      <stop offset=\"0%\" stop-color=\"#d97706\"/>\n      <stop offset=\"50%\" stop-color=\"#f59e0b\"/>\n      <stop offset=\"100%\" stop-color=\"#b45309\"/>\n    </linearGradient>\n    <linearGradient id=\"bootLeather\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#451a03\"/>\n      <stop offset=\"40%\" stop-color=\"#78350f\"/>\n      <stop offset=\"80%\" stop-color=\"#292524\"/>\n      <stop offset=\"100%\" stop-color=\"#0c0a09\"/>\n    </linearGradient>\n    <linearGradient id=\"pitchOutSeam\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n      <stop offset=\"0%\" stop-color=\"#ea580c\"/>\n      <stop offset=\"50%\" stop-color=\"#f59e0b\"/>\n      <stop offset=\"100%\" stop-color=\"#ca8a04\"/>\n    </linearGradient>\n    <linearGradient id=\"furLining\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#f8fafc\"/>\n      <stop offset=\"100%\" stop-color=\"#cbd5e1\"/>\n    </linearGradient>\n    <filter id=\"shadowOut14\" x=\"-10%\" y=\"-10%\" width=\"120%\" height=\"120%\">\n      <feDropShadow dx=\"0\" dy=\"6\" stdDeviation=\"6\" flood-color=\"#000000\" flood-opacity=\"0.85\"/>\n    </filter>\n    <pattern id=\"gridOut14\" width=\"25\" height=\"25\" patternUnits=\"userSpaceOnUse\">\n      <path d=\"M 25 0 L 0 0 0 25\" fill=\"none\" stroke=\"#152230\" stroke-width=\"0.6\"/>\n    </pattern>\n  </defs>\n\n  <!-- Background -->\n  <rect width=\"800\" height=\"450\" fill=\"url(#bgOut14)\"/>\n  <rect width=\"800\" height=\"450\" fill=\"url(#gridOut14)\"/>\n  <rect x=\"12\" y=\"12\" width=\"776\" height=\"426\" fill=\"none\" stroke=\"#253548\" stroke-width=\"1.2\"/>\n\n  <!-- Top Tactical Header Banner (Label 1) -->\n  <rect x=\"24\" y=\"20\" width=\"752\" height=\"34\" rx=\"2\" fill=\"#0d141f\" stroke=\"#2563eb\" stroke-width=\"1.2\"/>\n  <text x=\"38\" y=\"42\" fill=\"#fde68a\" font-family=\"monospace\" font-size=\"12\" font-weight=\"bold\">PR-14 OUTCOME // BONE NEEDLE &amp; SINEW SEWING KIT</text>\n\n  <!-- SECTION 1 (LEFT): Bone Needle & Eye Crafting (x: 30 ~ 260) -->\n  <g filter=\"url(#shadowOut14)\">\n    <rect x=\"30\" y=\"66\" width=\"230\" height=\"305\" rx=\"3\" fill=\"#0b111a\" stroke=\"#2a3f55\" stroke-width=\"1\"/>\n    <rect x=\"30\" y=\"66\" width=\"230\" height=\"24\" fill=\"#131e2b\"/>\n\n    <!-- Sharpening Slate Base Slab -->\n    <path d=\"M 50 310 L 230 290 L 245 340 L 65 355 Z\" fill=\"#1e293b\" stroke=\"#475569\" stroke-width=\"1\"/>\n\n    <!-- Complete Bone Needle (7.5cm, high polish) -->\n    <g transform=\"rotate(-35 140 200)\">\n      <!-- Needle body tapering to point -->\n      <path d=\"M 80 195 C 80 188 88 184 100 184 L 230 190 C 235 190 240 194 240 198 L 230 206 L 100 212 C 88 212 80 208 80 201 Z\" fill=\"url(#boneOut)\" stroke=\"#94a3b8\" stroke-width=\"1.2\"/>\n      <!-- Sharp needle point -->\n      <polygon points=\"230,190 260,198 230,206\" fill=\"#ffffff\" stroke=\"#e02424\" stroke-width=\"1.2\"/>\n      <!-- Drilled eye (1.8mm) -->\n      <ellipse cx=\"102\" cy=\"198\" rx=\"5\" ry=\"9\" fill=\"#020617\" stroke=\"#38bdf8\" stroke-width=\"1.5\"/>\n      <ellipse cx=\"102\" cy=\"198\" rx=\"2\" ry=\"4\" fill=\"#000000\"/>\n    </g>\n\n    <!-- Flint Awl Tool (Resting nearby) -->\n    <path d=\"M 55 120 L 85 95 L 95 105 L 75 135 Z\" fill=\"#334155\" stroke=\"#64748b\" stroke-width=\"1\"/>\n    <polygon points=\"55,120 45,138 62,132\" fill=\"#0f172a\" stroke=\"#94a3b8\" stroke-width=\"1\"/>\n\n    <!-- Needle Eye Zoom Circle -->\n    <circle cx=\"195\" cy=\"125\" r=\"30\" fill=\"#0f172a\" stroke=\"#38bdf8\" stroke-width=\"1.5\"/>\n    <ellipse cx=\"195\" cy=\"125\" rx=\"7\" ry=\"14\" fill=\"#020617\" stroke=\"#fde68a\" stroke-width=\"1.5\"/>\n    <path d=\"M 175 145 Q 195 125 215 105\" stroke=\"#f8fafc\" stroke-width=\"2.5\" fill=\"none\"/>\n  </g>\n\n  <!-- Label 2: Bone Needle 7.5cm (Placed inside Section 1) -->\n  <rect x=\"36\" y=\"70\" width=\"218\" height=\"18\" fill=\"none\"/>\n  <text x=\"40\" y=\"83\" fill=\"#fde68a\" font-family=\"monospace\" font-size=\"9\" font-weight=\"bold\">완성된 유백색 고밀도 치밀골 뼈바늘 (길이 7.5cm)</text>\n\n  <!-- Label 3: Precision Eye 1.8mm (Placed inside Section 1) -->\n  <rect x=\"36\" y=\"155\" width=\"165\" height=\"20\" rx=\"2\" fill=\"#141a23\" stroke=\"#38bdf8\" stroke-width=\"0.8\"/>\n  <text x=\"40\" y=\"169\" fill=\"#38bdf8\" font-family=\"monospace\" font-size=\"8.5\" font-weight=\"bold\">부싯돌 송곳 양면 천공 정밀 바늘귀 (직경 1.8mm)</text>\n\n  <!-- SECTION 2 (CENTER): Sinew Fiber Processing (x: 275 ~ 515) -->\n  <g filter=\"url(#shadowOut14)\">\n    <rect x=\"275\" y=\"66\" width=\"240\" height=\"305\" rx=\"3\" fill=\"#0b111a\" stroke=\"#2a3f55\" stroke-width=\"1\"/>\n    <rect x=\"275\" y=\"66\" width=\"240\" height=\"24\" fill=\"#131e2b\"/>\n\n    <!-- River Stone Anvil -->\n    <path d=\"M 290 230 L 490 220 L 505 310 L 305 325 Z\" fill=\"#1e293b\" stroke=\"#475569\" stroke-width=\"1\"/>\n\n    <!-- Dried Tendon Bundle Transition to Filaments -->\n    <!-- Amber uncrushed root -->\n    <path d=\"M 300 245 C 320 240 345 242 365 240 L 365 260 C 345 262 320 260 300 255 Z\" fill=\"url(#sinewOutAmber)\" stroke=\"#92400e\" stroke-width=\"1\"/>\n\n    <!-- Pounded Fan of Silver-White Filaments -->\n    <path d=\"M 365 245 C 400 220 440 200 485 180\" stroke=\"#ffffff\" stroke-width=\"1.2\" fill=\"none\"/>\n    <path d=\"M 365 248 C 410 230 450 215 490 205\" stroke=\"#f8fafc\" stroke-width=\"1.2\" fill=\"none\"/>\n    <path d=\"M 365 250 C 420 248 460 245 495 240\" stroke=\"#f1f5f9\" stroke-width=\"1.5\" fill=\"none\"/>\n    <path d=\"M 365 253 C 410 265 450 275 490 280\" stroke=\"#e2e8f0\" stroke-width=\"1.2\" fill=\"none\"/>\n    <path d=\"M 365 256 C 400 280 440 300 485 310\" stroke=\"#cbd5e1\" stroke-width=\"1.2\" fill=\"none\"/>\n\n    <!-- Rolled Spool of Sinew Thread around Twig -->\n    <rect x=\"420\" y=\"115\" width=\"65\" height=\"16\" rx=\"2\" fill=\"#78350f\" stroke=\"#b45309\" stroke-width=\"1\"/>\n    <rect x=\"430\" y=\"110\" width=\"45\" height=\"26\" rx=\"4\" fill=\"#f8fafc\" stroke=\"#cbd5e1\" stroke-width=\"1\"/>\n    <!-- Thread coils -->\n    <line x1=\"435\" y1=\"110\" x2=\"435\" y2=\"136\" stroke=\"#94a3b8\" stroke-width=\"1\"/>\n    <line x1=\"442\" y1=\"110\" x2=\"442\" y2=\"136\" stroke=\"#94a3b8\" stroke-width=\"1\"/>\n    <line x1=\"450\" y1=\"110\" x2=\"450\" y2=\"136\" stroke=\"#94a3b8\" stroke-width=\"1\"/>\n    <line x1=\"458\" y1=\"110\" x2=\"458\" y2=\"136\" stroke=\"#94a3b8\" stroke-width=\"1\"/>\n    <line x1=\"466\" y1=\"110\" x2=\"466\" y2=\"136\" stroke=\"#94a3b8\" stroke-width=\"1\"/>\n  </g>\n\n  <!-- Label 4: Pounded Sinew Threads (Placed inside Section 2) -->\n  <rect x=\"281\" y=\"70\" width=\"228\" height=\"18\" fill=\"none\"/>\n  <text x=\"285\" y=\"83\" fill=\"#fde68a\" font-family=\"monospace\" font-size=\"8.8\" font-weight=\"bold\">나무 방망이로 두드려 분리한 은백색 고인장 힘줄 실 다발</text>\n\n  <!-- SECTION 3 (RIGHT): Repaired Winter Leather Boot & Seam (x: 530 ~ 770) -->\n  <g filter=\"url(#shadowOut14)\">\n    <rect x=\"530\" y=\"66\" width=\"240\" height=\"305\" rx=\"3\" fill=\"#0b111a\" stroke=\"#2a3f55\" stroke-width=\"1\"/>\n    <rect x=\"530\" y=\"66\" width=\"240\" height=\"24\" fill=\"#131e2b\"/>\n\n    <!-- Field Repaired Winter Boot Silhouette -->\n    <!-- Fur lining collar at top -->\n    <ellipse cx=\"650\" cy=\"120\" rx=\"35\" ry=\"12\" fill=\"url(#furLining)\" stroke=\"#94a3b8\" stroke-width=\"1\"/>\n    <!-- Boot shaft & ankle -->\n    <path d=\"M 618 122 L 620 220 L 560 250 L 550 280 L 730 280 L 730 260 L 685 220 L 682 122 Z\" fill=\"url(#bootLeather)\" stroke=\"#a16207\" stroke-width=\"1.5\"/>\n    <!-- Sole block -->\n    <path d=\"M 545 280 L 735 280 L 735 298 L 545 298 Z\" fill=\"#0c0a09\" stroke=\"#44403c\" stroke-width=\"1.5\"/>\n\n    <!-- Repaired Seam with Saddle Stitching & Pine Pitch Coating -->\n    <!-- Curved tear seam running down boot vamp -->\n    <path d=\"M 625 210 Q 640 235 660 265\" stroke=\"#ea580c\" stroke-width=\"7\" stroke-linecap=\"round\" fill=\"none\"/>\n    <path d=\"M 625 210 Q 640 235 660 265\" stroke=\"url(#pitchOutSeam)\" stroke-width=\"5\" stroke-linecap=\"round\" fill=\"none\"/>\n\n    <!-- Cross Saddle Stitches over the seam -->\n    <line x1=\"622\" y1=\"216\" x2=\"632\" y2=\"212\" stroke=\"#ffffff\" stroke-width=\"2\"/>\n    <line x1=\"626\" y1=\"228\" x2=\"636\" y2=\"224\" stroke=\"#ffffff\" stroke-width=\"2\"/>\n    <line x1=\"634\" y1=\"240\" x2=\"644\" y2=\"236\" stroke=\"#ffffff\" stroke-width=\"2\"/>\n    <line x1=\"642\" y1=\"252\" x2=\"652\" y2=\"248\" stroke=\"#ffffff\" stroke-width=\"2\"/>\n    <line x1=\"650\" y1=\"264\" x2=\"660\" y2=\"260\" stroke=\"#ffffff\" stroke-width=\"2\"/>\n\n    <!-- High-Tension Waterproof Seal Graphic Stamp -->\n    <circle cx=\"715\" cy=\"180\" r=\"22\" fill=\"#0f172a\" stroke=\"#22c55e\" stroke-width=\"1.5\"/>\n    <path d=\"M 705 180 L 712 187 L 725 174\" fill=\"none\" stroke=\"#22c55e\" stroke-width=\"2\"/>\n  </g>\n\n  <!-- Label 5: Saddle Stitch & Pine Pitch Seam (Inside Section 3) -->\n  <rect x=\"534\" y=\"70\" width=\"232\" height=\"18\" fill=\"none\"/>\n  <text x=\"536\" y=\"83\" fill=\"#fde68a\" font-family=\"monospace\" font-size=\"8\" font-weight=\"bold\">새들 스티치 이중 결속 &amp; 소나무 송진 방수 밀봉 솔기 단면</text>\n\n  <!-- Label 6: Fully Restored Boot (Inside Section 3) -->\n  <rect x=\"540\" y=\"325\" width=\"220\" height=\"22\" rx=\"2\" fill=\"#141a23\" stroke=\"#22c55e\" stroke-width=\"1\"/>\n  <text x=\"548\" y=\"340\" fill=\"#22c55e\" font-family=\"monospace\" font-size=\"9\" font-weight=\"bold\">완전 복원된 방한 가죽 장화 (체온 유실 100% 차단)</text>\n\n  <!-- Bottom Master Verification Banner (Label 7) -->\n  <rect x=\"24\" y=\"388\" width=\"752\" height=\"38\" rx=\"2\" fill=\"#1e293b\" stroke=\"#22c55e\" stroke-width=\"1.5\"/>\n  <text x=\"38\" y=\"412\" fill=\"#ffffff\" font-family=\"monospace\" font-size=\"12\" font-weight=\"bold\">FIELD VERIFIED // TENSILE STRENGTH RATED &amp; WATERPROOF</text>\n</svg>","content/svgs/pr14-step-01.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <defs>\n    <linearGradient id=\"bg1401\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#080a0e\"/>\n      <stop offset=\"100%\" stop-color=\"#0e1319\"/>\n    </linearGradient>\n    <linearGradient id=\"stoneSlab\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#475569\"/>\n      <stop offset=\"35%\" stop-color=\"#334155\"/>\n      <stop offset=\"70%\" stop-color=\"#1e293b\"/>\n      <stop offset=\"100%\" stop-color=\"#0f172a\"/>\n    </linearGradient>\n    <linearGradient id=\"boneShade\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#ffffff\"/>\n      <stop offset=\"30%\" stop-color=\"#f8fafc\"/>\n      <stop offset=\"70%\" stop-color=\"#e2e8f0\"/>\n      <stop offset=\"100%\" stop-color=\"#cbd5e1\"/>\n    </linearGradient>\n    <linearGradient id=\"boneHollow\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n      <stop offset=\"0%\" stop-color=\"#78350f\"/>\n      <stop offset=\"50%\" stop-color=\"#92400e\"/>\n      <stop offset=\"100%\" stop-color=\"#451a03\"/>\n    </linearGradient>\n    <linearGradient id=\"waterDroplet\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#38bdf8\" stop-opacity=\"0.8\"/>\n      <stop offset=\"100%\" stop-color=\"#0284c7\" stop-opacity=\"0.3\"/>\n    </linearGradient>\n    <filter id=\"drop1401\" x=\"-15%\" y=\"-15%\" width=\"130%\" height=\"130%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"4\" flood-color=\"#000000\" flood-opacity=\"0.8\"/>\n    </filter>\n    <pattern id=\"grid1401\" width=\"20\" height=\"20\" patternUnits=\"userSpaceOnUse\">\n      <path d=\"M 20 0 L 0 0 0 20\" fill=\"none\" stroke=\"#16202c\" stroke-width=\"0.6\"/>\n    </pattern>\n  </defs>\n\n  <!-- Background -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bg1401)\"/>\n  <rect width=\"400\" height=\"400\" fill=\"url(#grid1401)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#253342\" stroke-width=\"1\"/>\n\n  <!-- Top Header (Label 1) -->\n  <rect x=\"16\" y=\"14\" width=\"368\" height=\"28\" rx=\"2\" fill=\"#0f1722\" stroke=\"#2c3e50\" stroke-width=\"1\"/>\n  <text x=\"26\" y=\"32\" fill=\"#fde68a\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">FIG. 01 // BONE SPLINTER BLANK PREPARATION</text>\n\n  <!-- Split Bone Cylinder Illustration (Top-Left) -->\n  <g filter=\"url(#drop1401)\">\n    <!-- Split Femur/Tibia Cross Section -->\n    <path d=\"M 40 85 L 140 85 C 145 105 145 125 140 145 L 40 145 C 35 125 35 105 40 85 Z\" fill=\"url(#boneShade)\" stroke=\"#94a3b8\" stroke-width=\"1.2\"/>\n    <ellipse cx=\"40\" cy=\"115\" rx=\"8\" ry=\"30\" fill=\"url(#boneHollow)\" stroke=\"#475569\" stroke-width=\"1\"/>\n    <ellipse cx=\"140\" cy=\"115\" rx=\"8\" ry=\"30\" fill=\"#f1f5f9\" stroke=\"#94a3b8\" stroke-width=\"1\"/>\n    <!-- Fracture Crack Lines -->\n    <path d=\"M 40 100 L 140 100\" stroke=\"#b91c1c\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n    <path d=\"M 40 130 L 140 130\" stroke=\"#b91c1c\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n  </g>\n\n  <!-- Label 2: Split Bone -->\n  <rect x=\"30\" y=\"155\" width=\"165\" height=\"22\" rx=\"2\" fill=\"#141a23\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"38\" y=\"170\" fill=\"#94a3b8\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">사슴 정강이뼈 치밀골 세로 쪼개기</text>\n\n  <!-- 3D Wet Quartzite Sharpening Stone Slab (Center-Bottom) -->\n  <g filter=\"url(#drop1401)\">\n    <!-- Main Slate Block -->\n    <path d=\"M 80 230 L 320 200 L 370 290 L 120 330 Z\" fill=\"url(#stoneSlab)\" stroke=\"#64748b\" stroke-width=\"1.5\"/>\n    <path d=\"M 80 230 L 80 245 L 120 345 L 370 305 L 370 290 L 120 330 Z\" fill=\"#0f172a\" stroke=\"#475569\" stroke-width=\"1\"/>\n    <path d=\"M 120 330 L 120 345\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n\n    <!-- Water Film on Stone -->\n    <ellipse cx=\"230\" cy=\"265\" rx=\"90\" ry=\"35\" fill=\"url(#waterDroplet)\"/>\n    <ellipse cx=\"190\" cy=\"275\" rx=\"6\" ry=\"3\" fill=\"#bae6fd\" opacity=\"0.8\"/>\n    <ellipse cx=\"260\" cy=\"255\" rx=\"8\" ry=\"4\" fill=\"#bae6fd\" opacity=\"0.7\"/>\n\n    <!-- Grinding Wear Groove on Quartzite -->\n    <line x1=\"160\" y1=\"280\" x2=\"280\" y2=\"245\" stroke=\"#94a3b8\" stroke-width=\"3\" stroke-linecap=\"round\" opacity=\"0.6\"/>\n  </g>\n\n  <!-- Label 3: Wet Sharpening Stone -->\n  <rect x=\"210\" y=\"175\" width=\"165\" height=\"22\" rx=\"2\" fill=\"#141a23\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"218\" y=\"190\" fill=\"#94a3b8\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">물 묻힌 거친 규암 숫돌 표면 연마</text>\n\n  <!-- Bone Blank Needle in Grinding Motion (Diagonal 45/30 deg) -->\n  <g filter=\"url(#drop1401)\">\n    <!-- Bone Needle Blank Being Sharpened -->\n    <path d=\"M 150 310 L 290 220 C 293 218 296 220 295 224 L 290 227 L 155 315 Z\" fill=\"url(#boneShade)\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n    <!-- Needle Point (Zoom Detail Arrow) -->\n    <path d=\"M 285 222 L 310 205 L 292 229 Z\" fill=\"#ffffff\" stroke=\"#e02424\" stroke-width=\"1.5\"/>\n    <!-- Rotation/Motion Arc Indicator -->\n    <path d=\"M 215 260 A 25 25 0 0 1 235 240\" fill=\"none\" stroke=\"#fde68a\" stroke-width=\"1.5\" stroke-dasharray=\"2 2\"/>\n    <polygon points=\"238,240 231,237 234,245\" fill=\"#fde68a\"/>\n  </g>\n\n  <!-- Label 4: Finger Length Blank -->\n  <rect x=\"25\" y=\"340\" width=\"170\" height=\"22\" rx=\"2\" fill=\"#141a23\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"32\" y=\"355\" fill=\"#fde68a\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">손가락 길이 (7~8cm) &amp; 원형 막대 성형</text>\n\n  <!-- Label 5: Step 1 Callout -->\n  <rect x=\"16\" y=\"368\" width=\"368\" height=\"22\" rx=\"2\" fill=\"#1e293b\" stroke=\"#e02424\" stroke-width=\"1\"/>\n  <text x=\"24\" y=\"383\" fill=\"#ffffff\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">[1단계 핵심] 30° 회전 연마로 날카로운 촉 완성</text>\n</svg>\n","content/svgs/pr14-step-02.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <defs>\n    <linearGradient id=\"bg1402\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#080a0e\"/>\n      <stop offset=\"100%\" stop-color=\"#0e1319\"/>\n    </linearGradient>\n    <linearGradient id=\"flintAwl\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#1e293b\"/>\n      <stop offset=\"30%\" stop-color=\"#334155\"/>\n      <stop offset=\"60%\" stop-color=\"#475569\"/>\n      <stop offset=\"100%\" stop-color=\"#0f172a\"/>\n    </linearGradient>\n    <linearGradient id=\"boneBody\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#ffffff\"/>\n      <stop offset=\"40%\" stop-color=\"#f1f5f9\"/>\n      <stop offset=\"80%\" stop-color=\"#e2e8f0\"/>\n      <stop offset=\"100%\" stop-color=\"#cbd5e1\"/>\n    </linearGradient>\n    <linearGradient id=\"boneHole\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#0f172a\"/>\n      <stop offset=\"50%\" stop-color=\"#1e293b\"/>\n      <stop offset=\"100%\" stop-color=\"#020617\"/>\n    </linearGradient>\n    <filter id=\"drop1402\" x=\"-15%\" y=\"-15%\" width=\"130%\" height=\"130%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"4\" flood-color=\"#000000\" flood-opacity=\"0.8\"/>\n    </filter>\n    <pattern id=\"grid1402\" width=\"20\" height=\"20\" patternUnits=\"userSpaceOnUse\">\n      <path d=\"M 20 0 L 0 0 0 20\" fill=\"none\" stroke=\"#16202c\" stroke-width=\"0.6\"/>\n    </pattern>\n  </defs>\n\n  <!-- Background -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bg1402)\"/>\n  <rect width=\"400\" height=\"400\" fill=\"url(#grid1402)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#253342\" stroke-width=\"1\"/>\n\n  <!-- Top Header (Label 1) -->\n  <rect x=\"16\" y=\"14\" width=\"368\" height=\"28\" rx=\"2\" fill=\"#0f1722\" stroke=\"#2c3e50\" stroke-width=\"1\"/>\n  <text x=\"26\" y=\"32\" fill=\"#fde68a\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">FIG. 02 // DUAL-CONE EYE DRILLING &amp; FINISHING</text>\n\n  <!-- Main Drilling Action: Flint Awl & Bone Needle Head -->\n  <g filter=\"url(#drop1402)\">\n    <!-- Bone Needle Head (Enlarged Macro View) -->\n    <path d=\"M 40 180 C 40 160 55 145 80 145 L 340 152 C 345 152 350 156 350 162 L 350 198 C 350 204 345 208 340 208 L 80 215 C 55 215 40 200 40 180 Z\" fill=\"url(#boneBody)\" stroke=\"#94a3b8\" stroke-width=\"1.5\"/>\n\n    <!-- 5mm Measurement Graphic Gauge (Lines only, no extra text) -->\n    <line x1=\"42\" y1=\"135\" x2=\"42\" y2=\"125\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n    <line x1=\"88\" y1=\"135\" x2=\"88\" y2=\"125\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n    <line x1=\"42\" y1=\"128\" x2=\"88\" y2=\"128\" stroke=\"#38bdf8\" stroke-width=\"1.2\" stroke-dasharray=\"2 1\"/>\n    <!-- Small 5mm tick dots -->\n    <circle cx=\"42\" cy=\"128\" r=\"1.5\" fill=\"#38bdf8\"/>\n    <circle cx=\"88\" cy=\"128\" r=\"1.5\" fill=\"#38bdf8\"/>\n\n    <!-- Bi-conical Eye Hole -->\n    <ellipse cx=\"88\" cy=\"180\" rx=\"9\" ry=\"12\" fill=\"url(#boneHole)\" stroke=\"#e02424\" stroke-width=\"1.5\"/>\n    <ellipse cx=\"88\" cy=\"180\" rx=\"4\" ry=\"6\" fill=\"#000000\" stroke=\"#fde68a\" stroke-width=\"1\"/>\n\n    <!-- Sharp Chipped Flint Awl Drill Bit (Top Plunge) -->\n    <path d=\"M 88 174 L 76 90 L 85 70 L 98 72 L 100 90 Z\" fill=\"url(#flintAwl)\" stroke=\"#64748b\" stroke-width=\"1.2\"/>\n    <path d=\"M 88 174 L 85 70\" stroke=\"#94a3b8\" stroke-width=\"0.8\" opacity=\"0.6\"/>\n    <path d=\"M 88 174 L 100 90\" stroke=\"#1e293b\" stroke-width=\"0.8\"/>\n\n    <!-- Drilling Rotation Arcs -->\n    <path d=\"M 70 105 A 20 10 0 0 1 106 105\" fill=\"none\" stroke=\"#fde68a\" stroke-width=\"1.5\"/>\n    <polygon points=\"108,105 102,100 104,108\" fill=\"#fde68a\"/>\n    <path d=\"M 106 115 A 20 10 0 0 1 70 115\" fill=\"none\" stroke=\"#fde68a\" stroke-width=\"1.5\"/>\n    <polygon points=\"68,115 74,120 72,112\" fill=\"#fde68a\"/>\n\n    <!-- Reverse Drill Vector (Opposite Side Awl Indicator Graphic) -->\n    <path d=\"M 88 190 L 88 230\" stroke=\"#38bdf8\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n    <polygon points=\"88,186 84,194 92,194\" fill=\"#38bdf8\"/>\n    <!-- Opposite rotation arc -->\n    <path d=\"M 76 220 A 14 6 0 0 1 100 220\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n  </g>\n\n  <!-- Label 2: Flint Awl Drilling -->\n  <rect x=\"25\" y=\"48\" width=\"220\" height=\"22\" rx=\"2\" fill=\"#141a23\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"33\" y=\"63\" fill=\"#fde68a\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">부싯돌 송곳(Flint Awl) 양면 회전 천공</text>\n\n  <!-- Label 3: 5mm Eye Distance -->\n  <rect x=\"180\" y=\"80\" width=\"205\" height=\"22\" rx=\"2\" fill=\"#141a23\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"188\" y=\"95\" fill=\"#94a3b8\" font-family=\"monospace\" font-size=\"9.5\" font-weight=\"bold\">머리 끝 5mm 안쪽 바늘귀(Eye) 관통 구멍</text>\n\n  <!-- Thorn/Twig Deburring & Sand Polishing Section (Bottom) -->\n  <g filter=\"url(#drop1402)\">\n    <!-- Sand Polishing Leather Wrap on Needle Body -->\n    <rect x=\"200\" y=\"160\" width=\"60\" height=\"40\" rx=\"3\" fill=\"#78350f\" stroke=\"#b45309\" stroke-width=\"1.2\" opacity=\"0.9\"/>\n    <!-- Fine sand grain particles -->\n    <circle cx=\"210\" cy=\"170\" r=\"1.2\" fill=\"#fde68a\"/>\n    <circle cx=\"230\" cy=\"165\" r=\"1.2\" fill=\"#fde68a\"/>\n    <circle cx=\"225\" cy=\"185\" r=\"1.5\" fill=\"#fde68a\"/>\n    <circle cx=\"245\" cy=\"180\" r=\"1.2\" fill=\"#fde68a\"/>\n    <circle cx=\"215\" cy=\"190\" r=\"1\" fill=\"#fde68a\"/>\n\n    <!-- Slender Thorn / Twig Burr Reamer passing through hole -->\n    <path d=\"M 60 290 L 88 185 L 105 130\" stroke=\"#d97706\" stroke-width=\"2\" stroke-linecap=\"round\"/>\n    <circle cx=\"88\" cy=\"185\" r=\"3\" fill=\"#f59e0b\"/>\n    <!-- Internal Reaming Rotation -->\n    <ellipse cx=\"88\" cy=\"210\" rx=\"14\" ry=\"5\" fill=\"none\" stroke=\"#22c55e\" stroke-width=\"1.2\" stroke-dasharray=\"2 2\"/>\n  </g>\n\n  <!-- Label 4: Thorn Burr Removal -->\n  <rect x=\"25\" y=\"310\" width=\"180\" height=\"22\" rx=\"2\" fill=\"#141a23\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"33\" y=\"325\" fill=\"#94a3b8\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">잔가시 회전 내부 버(Burr) 제거</text>\n\n  <!-- Label 5: Step 2 Core Summary -->\n  <rect x=\"16\" y=\"368\" width=\"368\" height=\"22\" rx=\"2\" fill=\"#1e293b\" stroke=\"#e02424\" stroke-width=\"1\"/>\n  <text x=\"24\" y=\"383\" fill=\"#ffffff\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">[2단계 핵심] 고운 강 모래 연마로 유리알 광택 마감</text>\n</svg>","content/svgs/pr14-step-03.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <defs>\n    <linearGradient id=\"bg1403\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#080a0e\"/>\n      <stop offset=\"100%\" stop-color=\"#0e1319\"/>\n    </linearGradient>\n    <linearGradient id=\"anvilStone\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#334155\"/>\n      <stop offset=\"50%\" stop-color=\"#1e293b\"/>\n      <stop offset=\"100%\" stop-color=\"#0f172a\"/>\n    </linearGradient>\n    <linearGradient id=\"sinewAmber\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n      <stop offset=\"0%\" stop-color=\"#d97706\"/>\n      <stop offset=\"40%\" stop-color=\"#f59e0b\"/>\n      <stop offset=\"80%\" stop-color=\"#b45309\"/>\n      <stop offset=\"100%\" stop-color=\"#78350f\"/>\n    </linearGradient>\n    <linearGradient id=\"oakBaton\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#854d0e\"/>\n      <stop offset=\"50%\" stop-color=\"#a16207\"/>\n      <stop offset=\"100%\" stop-color=\"#713f12\"/>\n    </linearGradient>\n    <linearGradient id=\"bone3\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#ffffff\"/>\n      <stop offset=\"100%\" stop-color=\"#cbd5e1\"/>\n    </linearGradient>\n    <filter id=\"drop1403\" x=\"-15%\" y=\"-15%\" width=\"130%\" height=\"130%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"4\" flood-color=\"#000000\" flood-opacity=\"0.8\"/>\n    </filter>\n    <pattern id=\"grid1403\" width=\"20\" height=\"20\" patternUnits=\"userSpaceOnUse\">\n      <path d=\"M 20 0 L 0 0 0 20\" fill=\"none\" stroke=\"#16202c\" stroke-width=\"0.6\"/>\n    </pattern>\n  </defs>\n\n  <!-- Background -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bg1403)\"/>\n  <rect width=\"400\" height=\"400\" fill=\"url(#grid1403)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#253342\" stroke-width=\"1\"/>\n\n  <!-- Top Header (Label 1) -->\n  <rect x=\"16\" y=\"14\" width=\"368\" height=\"28\" rx=\"2\" fill=\"#0f1722\" stroke=\"#2c3e50\" stroke-width=\"1\"/>\n  <text x=\"26\" y=\"32\" fill=\"#fde68a\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">FIG. 03 // DRIED ANIMAL SINEW FIBER SEPARATION</text>\n\n  <!-- Flat Anvil Stone & Sinew Processing Area -->\n  <g filter=\"url(#drop1403)\">\n    <!-- Flat Anvil River Stone -->\n    <path d=\"M 50 210 L 310 190 L 350 270 L 80 290 Z\" fill=\"url(#anvilStone)\" stroke=\"#475569\" stroke-width=\"1.5\"/>\n    <path d=\"M 50 210 L 50 225 L 80 305 L 350 285 L 350 270 L 80 290 Z\" fill=\"#090d16\" stroke=\"#334155\" stroke-width=\"1\"/>\n\n    <!-- Rigid Amber Dried Sinew Tendon (Left portion uncrushed) -->\n    <path d=\"M 60 235 C 80 230 110 232 140 230 C 145 226 145 240 140 244 C 110 246 80 248 60 245 Z\" fill=\"url(#sinewAmber)\" stroke=\"#92400e\" stroke-width=\"1\"/>\n    <!-- Fibrous surface striations on tendon -->\n    <line x1=\"70\" y1=\"236\" x2=\"135\" y2=\"233\" stroke=\"#fde68a\" stroke-width=\"0.7\" opacity=\"0.7\"/>\n    <line x1=\"75\" y1=\"242\" x2=\"135\" y2=\"241\" stroke=\"#fde68a\" stroke-width=\"0.7\" opacity=\"0.7\"/>\n\n    <!-- Crushed/Pounded Transition Zone -->\n    <polygon points=\"140,230 160,222 165,248 140,244\" fill=\"#fbbf24\" opacity=\"0.8\"/>\n    <!-- Impact shockwaves -->\n    <circle cx=\"152\" cy=\"235\" r=\"16\" fill=\"none\" stroke=\"#fde68a\" stroke-width=\"1.2\" stroke-dasharray=\"3 2\" opacity=\"0.8\"/>\n    <circle cx=\"152\" cy=\"235\" r=\"24\" fill=\"none\" stroke=\"#fde68a\" stroke-width=\"0.8\" stroke-dasharray=\"2 3\" opacity=\"0.5\"/>\n\n    <!-- Oak Wood Baton (Tapping action from top-right) -->\n    <g transform=\"rotate(-25 152 235)\">\n      <rect x=\"135\" y=\"100\" width=\"32\" height=\"110\" rx=\"6\" fill=\"url(#oakBaton)\" stroke=\"#ca8a04\" stroke-width=\"1.2\"/>\n      <!-- Wood grain rings -->\n      <line x1=\"140\" y1=\"130\" x2=\"162\" y2=\"130\" stroke=\"#713f12\" stroke-width=\"1\"/>\n      <line x1=\"140\" y1=\"160\" x2=\"162\" y2=\"160\" stroke=\"#713f12\" stroke-width=\"1\"/>\n      <line x1=\"140\" y1=\"190\" x2=\"162\" y2=\"190\" stroke=\"#713f12\" stroke-width=\"1\"/>\n    </g>\n\n    <!-- Fanned Out Silky Silver-White Collagen Fibers (Right portion) -->\n    <!-- Fine individual filaments -->\n    <path d=\"M 160 225 C 200 215 240 210 290 205\" stroke=\"#f8fafc\" stroke-width=\"1.2\" fill=\"none\"/>\n    <path d=\"M 162 230 C 210 225 250 225 300 220\" stroke=\"#f1f5f9\" stroke-width=\"1\" fill=\"none\"/>\n    <path d=\"M 164 235 C 205 238 255 240 310 238\" stroke=\"#ffffff\" stroke-width=\"1.2\" fill=\"none\"/>\n    <path d=\"M 162 240 C 200 248 245 252 295 255\" stroke=\"#e2e8f0\" stroke-width=\"1\" fill=\"none\"/>\n    <path d=\"M 160 245 C 195 258 235 265 285 270\" stroke=\"#cbd5e1\" stroke-width=\"0.8\" fill=\"none\"/>\n  </g>\n\n  <!-- Label 2: Flat Anvil Stone & Sinew -->\n  <rect x=\"25\" y=\"55\" width=\"220\" height=\"22\" rx=\"2\" fill=\"#141a23\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"33\" y=\"70\" fill=\"#94a3b8\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">납작한 돌받침 위 건조 힘줄(Sinew) 배치</text>\n\n  <!-- Label 3: Oak Baton Tapping -->\n  <rect x=\"200\" y=\"85\" width=\"185\" height=\"22\" rx=\"2\" fill=\"#141a23\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"208\" y=\"100\" fill=\"#fde68a\" font-family=\"monospace\" font-size=\"9.5\" font-weight=\"bold\">참나무 방망이 경타격 (콜라겐 다발 분쇄)</text>\n\n  <!-- Micro Detail Inset: Needle Threading with Saliva-Coated Sinew (Bottom-Right) -->\n  <g filter=\"url(#drop1403)\">\n    <rect x=\"180\" y=\"275\" width=\"195\" height=\"85\" rx=\"3\" fill=\"#0f172a\" stroke=\"#2563eb\" stroke-width=\"1\"/>\n\n    <!-- Bone needle head outline in inset -->\n    <path d=\"M 190 315 C 190 305 200 295 215 295 L 360 298 L 360 332 L 215 335 C 200 335 190 325 190 315 Z\" fill=\"url(#bone3)\" stroke=\"#94a3b8\" stroke-width=\"1\"/>\n    <!-- Eye hole -->\n    <ellipse cx=\"220\" cy=\"315\" rx=\"6\" ry=\"10\" fill=\"#020617\" stroke=\"#e02424\" stroke-width=\"1\"/>\n\n    <!-- Sinew thread entering eye smoothly -->\n    <path d=\"M 270 345 C 245 340 230 330 220 315 C 210 300 195 290 170 288\" fill=\"none\" stroke=\"#f8fafc\" stroke-width=\"2\"/>\n    <!-- Saliva moisture gloss highlight -->\n    <ellipse cx=\"220\" cy=\"315\" rx=\"3\" ry=\"5\" fill=\"#38bdf8\" opacity=\"0.6\"/>\n  </g>\n\n  <!-- Label 4: Fiber Combing -->\n  <rect x=\"25\" y=\"295\" width=\"150\" height=\"22\" rx=\"2\" fill=\"#141a23\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"31\" y=\"310\" fill=\"#94a3b8\" font-family=\"monospace\" font-size=\"9\" font-weight=\"bold\">머리카락 3~4가닥 굵기 고인장 섬유 빗질</text>\n\n  <!-- Label 5: Step 3 Core Summary -->\n  <rect x=\"16\" y=\"368\" width=\"368\" height=\"22\" rx=\"2\" fill=\"#1e293b\" stroke=\"#e02424\" stroke-width=\"1\"/>\n  <text x=\"24\" y=\"383\" fill=\"#ffffff\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">[3단계 핵심] 침(Saliva) 코팅으로 바늘귀 부드러운 통과</text>\n</svg>","content/svgs/pr14-step-04.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <defs>\n    <linearGradient id=\"bg1404\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#080a0e\"/>\n      <stop offset=\"100%\" stop-color=\"#0e1319\"/>\n    </linearGradient>\n    <linearGradient id=\"leatherTop\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#854d0e\"/>\n      <stop offset=\"50%\" stop-color=\"#713f12\"/>\n      <stop offset=\"100%\" stop-color=\"#451a03\"/>\n    </linearGradient>\n    <linearGradient id=\"leatherBot\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#581c87\"/>\n      <stop offset=\"50%\" stop-color=\"#3b0764\"/>\n      <stop offset=\"100%\" stop-color=\"#1e1b4b\"/>\n    </linearGradient>\n    <linearGradient id=\"pitchGlaze\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n      <stop offset=\"0%\" stop-color=\"#ea580c\" stop-opacity=\"0.8\"/>\n      <stop offset=\"50%\" stop-color=\"#f59e0b\" stop-opacity=\"0.9\"/>\n      <stop offset=\"100%\" stop-color=\"#b45309\" stop-opacity=\"0.7\"/>\n    </linearGradient>\n    <linearGradient id=\"bone4\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#ffffff\"/>\n      <stop offset=\"100%\" stop-color=\"#cbd5e1\"/>\n    </linearGradient>\n    <filter id=\"drop1404\" x=\"-15%\" y=\"-15%\" width=\"130%\" height=\"130%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"4\" flood-color=\"#000000\" flood-opacity=\"0.8\"/>\n    </filter>\n    <pattern id=\"grid1404\" width=\"20\" height=\"20\" patternUnits=\"userSpaceOnUse\">\n      <path d=\"M 20 0 L 0 0 0 20\" fill=\"none\" stroke=\"#16202c\" stroke-width=\"0.6\"/>\n    </pattern>\n  </defs>\n\n  <!-- Background -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bg1404)\"/>\n  <rect width=\"400\" height=\"400\" fill=\"url(#grid1404)\"/>\n  <rect x=\"8\" y=\"8\" width=\"384\" height=\"384\" fill=\"none\" stroke=\"#253342\" stroke-width=\"1\"/>\n\n  <!-- Top Header (Label 1) -->\n  <rect x=\"16\" y=\"14\" width=\"368\" height=\"28\" rx=\"2\" fill=\"#0f1722\" stroke=\"#2c3e50\" stroke-width=\"1\"/>\n  <text x=\"26\" y=\"32\" fill=\"#fde68a\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">FIG. 04 // SADDLE STITCHING &amp; PITCH SEALING</text>\n\n  <!-- Main Leather Cross-Section & Saddle Stitching Display -->\n  <g filter=\"url(#drop1404)\">\n    <!-- Top Leather Layer -->\n    <path d=\"M 30 140 L 370 140 L 370 190 L 30 190 Z\" fill=\"url(#leatherTop)\" stroke=\"#a16207\" stroke-width=\"1.2\"/>\n    <!-- Bottom Overlapping Leather Layer (Offset seam) -->\n    <path d=\"M 30 170 L 370 170 L 370 220 L 30 220 Z\" fill=\"#292524\" stroke=\"#57534e\" stroke-width=\"1.2\" opacity=\"0.95\"/>\n\n    <!-- Pre-punched 5mm Holes Line -->\n    <!-- Hole 1 -->\n    <circle cx=\"70\" cy=\"180\" r=\"4.5\" fill=\"#0c0a09\" stroke=\"#e02424\" stroke-width=\"1.2\"/>\n    <!-- Hole 2 -->\n    <circle cx=\"130\" cy=\"180\" r=\"4.5\" fill=\"#0c0a09\" stroke=\"#e02424\" stroke-width=\"1.2\"/>\n    <!-- Hole 3 -->\n    <circle cx=\"190\" cy=\"180\" r=\"4.5\" fill=\"#0c0a09\" stroke=\"#e02424\" stroke-width=\"1.2\"/>\n    <!-- Hole 4 -->\n    <circle cx=\"250\" cy=\"180\" r=\"4.5\" fill=\"#0c0a09\" stroke=\"#e02424\" stroke-width=\"1.2\"/>\n    <!-- Hole 5 -->\n    <circle cx=\"310\" cy=\"180\" r=\"4.5\" fill=\"#0c0a09\" stroke=\"#e02424\" stroke-width=\"1.2\"/>\n\n    <!-- Saddle Stitch Sinew Thread Paths (Dual Cross Threads) -->\n    <!-- Front Thread (Gold) -->\n    <path d=\"M 50 180 Q 70 160 130 180 Q 190 160 250 180 Q 310 160 340 180\" fill=\"none\" stroke=\"#fde68a\" stroke-width=\"3\" stroke-linecap=\"round\"/>\n    <!-- Back Thread (Silver White Cross) -->\n    <path d=\"M 50 180 Q 70 200 130 180 Q 190 200 250 180 Q 310 200 340 180\" fill=\"none\" stroke=\"#f1f5f9\" stroke-width=\"2.5\" stroke-dasharray=\"6 3\" stroke-linecap=\"round\"/>\n\n    <!-- Bone Needles in Action (Left needle plunging down, right needle coming up) -->\n    <!-- Needle A (Top to Down) -->\n    <path d=\"M 175 110 L 190 175 L 187 177 L 172 112 Z\" fill=\"url(#bone4)\" stroke=\"#475569\" stroke-width=\"1\"/>\n    <ellipse cx=\"174\" cy=\"114\" rx=\"2\" ry=\"3.5\" fill=\"#020617\"/>\n    <!-- Thread coming out of Needle A -->\n    <path d=\"M 174 114 Q 155 95 130 180\" fill=\"none\" stroke=\"#fde68a\" stroke-width=\"2\"/>\n\n    <!-- Needle B (Bottom to Up) -->\n    <path d=\"M 205 250 L 190 185 L 193 183 L 208 248 Z\" fill=\"url(#bone4)\" stroke=\"#475569\" stroke-width=\"1\"/>\n    <ellipse cx=\"206\" cy=\"246\" rx=\"2\" ry=\"3.5\" fill=\"#020617\"/>\n    <!-- Thread coming out of Needle B -->\n    <path d=\"M 206 246 Q 225 265 250 180\" fill=\"none\" stroke=\"#f1f5f9\" stroke-width=\"2\"/>\n\n    <!-- 5mm Gauge Indicator Graphic -->\n    <line x1=\"70\" y1=\"148\" x2=\"130\" y2=\"148\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n    <line x1=\"70\" y1=\"144\" x2=\"70\" y2=\"152\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n    <line x1=\"130\" y1=\"144\" x2=\"130\" y2=\"152\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n  </g>\n\n  <!-- Label 2: 5mm Awl Pre-Punched Holes -->\n  <rect x=\"25\" y=\"55\" width=\"230\" height=\"22\" rx=\"2\" fill=\"#141a23\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"33\" y=\"70\" fill=\"#fde68a\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">부싯돌 송곳 5mm 간격 예비 가죽 천공</text>\n\n  <!-- Label 3: Saddle Stitch Dual Cross -->\n  <rect x=\"180\" y=\"85\" width=\"205\" height=\"22\" rx=\"2\" fill=\"#141a23\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"188\" y=\"100\" fill=\"#94a3b8\" font-family=\"monospace\" font-size=\"9.5\" font-weight=\"bold\">힘줄 실 양방향 교차(Saddle Stitch) 봉제</text>\n\n  <!-- Heated Pine Pitch Sealing Glaze Section (Lower Half) -->\n  <g filter=\"url(#drop1404)\">\n    <!-- Sealed Seam Line with Translucent Melted Resin Glaze -->\n    <path d=\"M 40 270 L 360 270 L 360 295 L 40 295 Z\" fill=\"#1c1917\" stroke=\"#44403c\" stroke-width=\"1\"/>\n    <!-- Pitch Coating Layer -->\n    <path d=\"M 40 278 C 100 273 200 282 360 276 L 360 292 C 240 296 120 288 40 293 Z\" fill=\"url(#pitchGlaze)\" stroke=\"#ea580c\" stroke-width=\"1\"/>\n    <!-- Glistening gloss highlight line on resin -->\n    <path d=\"M 50 282 C 120 278 220 284 350 280\" stroke=\"#fef08a\" stroke-width=\"1.5\" stroke-linecap=\"round\" opacity=\"0.8\"/>\n\n    <!-- Waterproof Shield Graphic Indicator -->\n    <path d=\"M 190 310 L 200 305 L 210 310 L 210 325 C 210 335 200 342 200 342 C 200 342 190 335 190 325 Z\" fill=\"#0284c7\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n    <path d=\"M 196 322 L 199 325 L 205 318\" fill=\"none\" stroke=\"#ffffff\" stroke-width=\"1.5\"/>\n  </g>\n\n  <!-- Label 4: Pine Pitch Seam Glaze -->\n  <rect x=\"25\" y=\"320\" width=\"190\" height=\"22\" rx=\"2\" fill=\"#141a23\" stroke=\"#334155\" stroke-width=\"1\"/>\n  <text x=\"33\" y=\"335\" fill=\"#fde68a\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">소나무 송진 고약 솔기 방수 코팅</text>\n\n  <!-- Label 5: Step 4 Core Summary -->\n  <rect x=\"16\" y=\"368\" width=\"368\" height=\"22\" rx=\"2\" fill=\"#1e293b\" stroke=\"#e02424\" stroke-width=\"1\"/>\n  <text x=\"24\" y=\"383\" fill=\"#ffffff\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">[4단계 핵심] 힘줄 건조 수축으로 바늘구멍 완전 밀폐</text>\n</svg>","content/svgs/step-01.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg class=\"w-full max-w-[320px] h-auto\" viewBox=\"0 0 280 190\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n  <!-- Grid background lines -->\n  <line x1=\"20\" y1=\"20\" x2=\"260\" y2=\"20\" stroke=\"#222\" stroke-width=\"0.75\" stroke-dasharray=\"2 2\"></line>\n  <line x1=\"20\" y1=\"95\" x2=\"260\" y2=\"95\" stroke=\"#222\" stroke-width=\"0.75\" stroke-dasharray=\"2 2\"></line>\n  <line x1=\"20\" y1=\"170\" x2=\"260\" y2=\"170\" stroke=\"#222\" stroke-width=\"0.75\" stroke-dasharray=\"2 2\"></line>\n  <line x1=\"140\" y1=\"10\" x2=\"140\" y2=\"180\" stroke=\"#222\" stroke-width=\"0.75\" stroke-dasharray=\"2 2\"></line>\n\n  <!-- Bottle / Cylinder Cone Outer Contour -->\n  <path d=\"M70 25 L210 25 L180 145 L155 165 L125 165 L100 145 Z\" stroke=\"#F5F5F5\" stroke-width=\"1.5\" fill=\"#161616\"></path>\n\n  <!-- Flow direction arrows on top (Raw water input) -->\n  <path d=\"M140 8 L140 22 M136 18 L140 22 L144 18\" stroke=\"#FFFFFF\" stroke-width=\"1.2\"></path>\n  <text x=\"148\" y=\"18\" fill=\"#AAAAAA\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\">흙탕물 붓기</text>\n\n  <!-- Layer 1: Pebbles (Top) -->\n  <path d=\"M74 38 L206 38 L197 62 L83 62 Z\" fill=\"#222222\" stroke=\"#444\" stroke-width=\"0.75\"></path>\n  <!-- Gravel particles -->\n  <circle cx=\"100\" cy=\"48\" r=\"4.5\" stroke=\"#FFFFFF\" stroke-width=\"1\" fill=\"none\"></circle>\n  <circle cx=\"120\" cy=\"52\" r=\"5\" stroke=\"#FFFFFF\" stroke-width=\"1\" fill=\"none\"></circle>\n  <circle cx=\"140\" cy=\"46\" r=\"4\" stroke=\"#FFFFFF\" stroke-width=\"1\" fill=\"none\"></circle>\n  <circle cx=\"160\" cy=\"53\" r=\"5.5\" stroke=\"#FFFFFF\" stroke-width=\"1\" fill=\"none\"></circle>\n  <circle cx=\"180\" cy=\"47\" r=\"4\" stroke=\"#FFFFFF\" stroke-width=\"1\" fill=\"none\"></circle>\n  <!-- Text label -->\n  <line x1=\"196\" y1=\"50\" x2=\"202\" y2=\"50\" stroke=\"#777\" stroke-width=\"0.8\"></line>\n  <text x=\"275\" y=\"46\" fill=\"#EEEEEE\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7\" text-anchor=\"end\">1. 자갈 (큰 먼지 걸러냄)</text>\n\n  <!-- Layer 2: Fine Sand -->\n  <path d=\"M83 62 L197 62 L189 95 L91 95 Z\" fill=\"#1b1b1b\" stroke=\"#444\" stroke-width=\"0.75\"></path>\n  <!-- Sand stippling lines -->\n  <line x1=\"100\" y1=\"72\" x2=\"180\" y2=\"72\" stroke=\"#666\" stroke-width=\"0.8\" stroke-dasharray=\"1 3\"></line>\n  <line x1=\"96\" y1=\"80\" x2=\"184\" y2=\"80\" stroke=\"#666\" stroke-width=\"0.8\" stroke-dasharray=\"2 2\"></line>\n  <line x1=\"102\" y1=\"88\" x2=\"178\" y2=\"88\" stroke=\"#666\" stroke-width=\"0.8\" stroke-dasharray=\"1 3\"></line>\n  <!-- Text label -->\n  <line x1=\"75\" y1=\"78\" x2=\"88\" y2=\"78\" stroke=\"#777\" stroke-width=\"0.8\"></line>\n  <text x=\"5\" y=\"74\" fill=\"#EEEEEE\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7\">2. 고운 모래 (작은 먼지)</text>\n\n  <!-- Layer 3: Charcoal Powder -->\n  <path d=\"M91 95 L189 95 L180 132 L100 132 Z\" fill=\"#080808\" stroke=\"#555\" stroke-width=\"0.75\"></path>\n  <!-- Charcoal hatch pattern -->\n  <line x1=\"105\" y1=\"104\" x2=\"175\" y2=\"104\" stroke=\"#444\" stroke-width=\"1.2\"></line>\n  <line x1=\"108\" y1=\"113\" x2=\"172\" y2=\"113\" stroke=\"#444\" stroke-width=\"1.2\"></line>\n  <line x1=\"112\" y1=\"122\" x2=\"168\" y2=\"122\" stroke=\"#444\" stroke-width=\"1.2\"></line>\n  <rect x=\"128\" y=\"102\" width=\"24\" height=\"20\" stroke=\"#FFF\" stroke-width=\"0.8\" fill=\"none\"></rect>\n  <text x=\"131\" y=\"115\" fill=\"#FFF\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7\" font-weight=\"bold\">숯가루</text>\n  <!-- Text label -->\n  <line x1=\"185\" y1=\"115\" x2=\"195\" y2=\"115\" stroke=\"#777\" stroke-width=\"0.8\"></line>\n  <text x=\"275\" y=\"111\" fill=\"#EEEEEE\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7\" text-anchor=\"end\">3. 숯가루 (독소·냄새 제거)</text>\n\n  <!-- Layer 4: Cloth Mesh Base -->\n  <path d=\"M100 132 L180 132 L165 152 L115 152 Z\" fill=\"#2d2d2d\" stroke=\"#666\" stroke-width=\"0.75\"></path>\n  <path d=\"M110 142 L170 142\" stroke=\"#FFF\" stroke-width=\"1\" stroke-dasharray=\"2 1\"></path>\n  <!-- Text label -->\n  <line x1=\"108\" y1=\"145\" x2=\"35\" y2=\"145\" stroke=\"#777\" stroke-width=\"0.8\"></line>\n  <text x=\"5\" y=\"148\" fill=\"#EEEEEE\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7.5\">4. 천·이끼 마개 (입구 막기)</text>\n\n  <!-- Dripping water drops (Clear water output) -->\n  <line x1=\"140\" y1=\"165\" x2=\"140\" y2=\"178\" stroke=\"#FFFFFF\" stroke-width=\"1.2\" stroke-dasharray=\"2 2\"></line>\n  <circle cx=\"140\" cy=\"183\" r=\"2.5\" fill=\"#FFFFFF\"></circle>\n</svg>","content/svgs/step-02.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg class=\"w-full max-w-[320px] h-auto\" viewBox=\"0 0 280 150\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n  <!-- Vessel receiving unfiltered and discarding 1st flush -->\n  <!-- Bucket 1 (Discard - Turbid) -->\n  <rect x=\"35\" y=\"65\" width=\"70\" height=\"60\" stroke=\"#666\" stroke-width=\"1.2\" fill=\"#141414\"></rect>\n  <line x1=\"35\" y1=\"95\" x2=\"105\" y2=\"95\" stroke=\"#444\" stroke-width=\"1\"></line>\n  <path d=\"M40 100 Q70 105 100 100\" stroke=\"#777\" stroke-width=\"0.75\" stroke-dasharray=\"2 2\"></path>\n  <text x=\"42\" y=\"85\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\" font-weight=\"bold\">[첫 1~2컵 버리기]</text>\n  <text x=\"44\" y=\"115\" fill=\"#777\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7\">검은 숯가루 섞인 물</text>\n  <line x1=\"70\" y1=\"40\" x2=\"70\" y2=\"60\" stroke=\"#E02424\" stroke-width=\"1.2\" stroke-dasharray=\"2 2\"></line>\n  <path d=\"M68 55 L70 60 L72 55\" stroke=\"#E02424\" stroke-width=\"1.2\"></path>\n\n  <!-- Flow divider symbol -->\n  <text x=\"125\" y=\"85\" fill=\"#FFF\" font-family=\"'JetBrains Mono', monospace\" font-size=\"12\">→</text>\n\n  <!-- Bucket 2 (Keep - Clean Pre-filtered) -->\n  <rect x=\"165\" y=\"65\" width=\"75\" height=\"60\" stroke=\"#FFF\" stroke-width=\"1.5\" fill=\"#181818\"></rect>\n  <line x1=\"165\" y1=\"90\" x2=\"240\" y2=\"90\" stroke=\"#888\" stroke-width=\"1\"></line>\n  <!-- Water level indicator -->\n  <line x1=\"170\" y1=\"105\" x2=\"235\" y2=\"105\" stroke=\"#FFF\" stroke-width=\"0.75\" stroke-dasharray=\"3 2\"></line>\n  <line x1=\"170\" y1=\"115\" x2=\"235\" y2=\"115\" stroke=\"#FFF\" stroke-width=\"0.75\" stroke-dasharray=\"3 2\"></line>\n  <text x=\"175\" y=\"82\" fill=\"#FFFFFF\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\" font-weight=\"bold\">[맑은 물 받아 쓰기]</text>\n  <text x=\"175\" y=\"135\" fill=\"#999\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7\">투명해진 깨끗한 물</text>\n  <line x1=\"202\" y1=\"40\" x2=\"202\" y2=\"60\" stroke=\"#FFFFFF\" stroke-width=\"1.2\"></line>\n  <path d=\"M200 55 L202 60 L204 55\" stroke=\"#FFFFFF\" stroke-width=\"1.2\"></path>\n\n  <!-- Drip speed gauge -->\n  <text x=\"15\" y=\"25\" fill=\"#AAA\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\" text-anchor=\"start\">떨어지는 속도: 1초에 1~2방울</text>\n  <circle cx=\"202\" cy=\"22\" r=\"3\" fill=\"#FFF\"></circle>\n</svg>","content/svgs/step-03.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg class=\"w-full max-w-[320px] h-auto\" viewBox=\"0 0 280 155\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n  <!-- Boiling Pot Diagram -->\n  <rect x=\"30\" y=\"45\" width=\"80\" height=\"60\" stroke=\"#FFF\" stroke-width=\"1.5\" fill=\"#181818\"></rect>\n  <line x1=\"20\" y1=\"55\" x2=\"30\" y2=\"55\" stroke=\"#FFF\" stroke-width=\"1.5\"></line>\n  <line x1=\"110\" y1=\"55\" x2=\"120\" y2=\"55\" stroke=\"#FFF\" stroke-width=\"1.5\"></line>\n  <!-- Rolling boil violent bubbles -->\n  <circle cx=\"50\" cy=\"75\" r=\"4\" stroke=\"#FFF\" stroke-width=\"1\"></circle>\n  <circle cx=\"70\" cy=\"65\" r=\"5\" stroke=\"#FFF\" stroke-width=\"1\"></circle>\n  <circle cx=\"90\" cy=\"72\" r=\"3.5\" stroke=\"#FFF\" stroke-width=\"1\"></circle>\n  <circle cx=\"60\" cy=\"85\" r=\"3\" stroke=\"#FFF\" stroke-width=\"1\"></circle>\n  <circle cx=\"80\" cy=\"88\" r=\"4.5\" stroke=\"#FFF\" stroke-width=\"1\"></circle>\n  <!-- Steam waves -->\n  <path d=\"M50 35 Q55 25 50 15\" stroke=\"#888\" stroke-width=\"1\"></path>\n  <path d=\"M70 35 Q75 25 70 15\" stroke=\"#888\" stroke-width=\"1\"></path>\n  <path d=\"M90 35 Q95 25 90 15\" stroke=\"#888\" stroke-width=\"1\"></path>\n  <!-- Campfire underneath -->\n  <path d=\"M40 115 L70 106 L100 115\" stroke=\"#E02424\" stroke-width=\"1.5\"></path>\n  <path d=\"M55 125 L70 110 L85 125\" stroke=\"#E02424\" stroke-width=\"1.5\"></path>\n  <text x=\"70\" y=\"137\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7.5\" text-anchor=\"middle\">100°C 불에 끓이기</text>\n\n  <!-- Threshold timer graph on right -->\n  <line x1=\"145\" y1=\"120\" x2=\"255\" y2=\"120\" stroke=\"#555\" stroke-width=\"1\"></line>\n  <line x1=\"145\" y1=\"25\" x2=\"145\" y2=\"120\" stroke=\"#555\" stroke-width=\"1\"></line>\n  \n  <!-- Curve -->\n  <path d=\"M145 110 Q175 95 190 40 L250 40\" stroke=\"#FFFFFF\" stroke-width=\"1.5\" fill=\"none\"></path>\n  <line x1=\"190\" y1=\"20\" x2=\"190\" y2=\"120\" stroke=\"#E02424\" stroke-width=\"0.8\" stroke-dasharray=\"2 2\"></line>\n  \n  <text x=\"148\" y=\"35\" fill=\"#AAA\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7\">100°C</text>\n  <text x=\"192\" y=\"32\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7.5\" font-weight=\"bold\">3분 이상 끓이기</text>\n  <text x=\"255\" y=\"65\" fill=\"#4ade80\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7.5\" text-anchor=\"end\">세균 99.9% 제거</text>\n  \n  <text x=\"200\" y=\"133\" fill=\"#888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7\" text-anchor=\"middle\">팔팔 끓이는 시간 (분)</text>\n</svg>","NEXT_TOPIC_PROMPT.md":"# 📌 차기 생존 프로토콜 기획서: PR-15 - 활성탄 숯가루와 모래를 천에 싼 화재·유독가스 방호 간이 방독 마스크 (야전 탄포 마스크)\n\n- **도메인**: 야전 응급 의학 & 유독물 차단 호흡기학 > 다공성 활성탄 미세 흡착 및 3중 물리 여과 (Tier 2)\n- **카테고리**: `MEDICINE` (야전 방호 의학 & 유독 연기·가스 호흡 차단)\n- **위급도**: HIGH\n- **결핍 상황**: 산불 확산, 지하 쉘터 화재, 문명 붕괴 후 건물 화재 및 유독가스 누출 환경에서 유독 연기(그을음 입자 및 유독성 휘발 가스)를 3회 이상 깊게 흡입하면 기도 열상과 호흡 마비로 2~3분 안에 의식을 잃고 질식사합니다. 방독면이나 현대 정밀 마스크가 전무한 야전에서는 [밀폐 토굴 숯가마](/protocol-09.html)에서 고온 건류한 참나무 숯을 빻아 활성화한 '다공성 숯가루(Activated Charcoal Powder)'와, [자연 정수 필터](/protocol-01.html) 원리의 미세 강 모래 및 젖은 천(면포/삼베)을 3중 적층 포장하여 코와 입을 밀착 차단하는 간이 탄포 방독 마스크를 즉시 자급해야 합니다.\n- **과학 원리**: \n  - **다공성 탄소 비표면적 흡착(Adsorption)**: 600~800°C에서 환원 소성된 고밀도 참나무 숯은 그램당 300~500㎡에 달하는 미세 다공성 표면을 지녀 연기 속 유기성 유독 분자와 악취 입자를 강력한 반데르발스 힘으로 흡착 고정합니다.\n  - **3중 샌드위치 입자 차단(Tortuous Path Filtration)**: 젖은 천(대형 그을음 분진 1차 차단) ➔ 고운 모래층(열기 냉각 및 중형 비산재 트랩) ➔ 미세 숯가루층(유독 가스 분자 흡착)의 3중 구조로 분진 투과율을 90% 이상 억제합니다.\n- **투입 자재 (100% 원시 자연물 및 기본 야전재)**:\n  - 고온 건류된 참나무 백탄 숯 2~3덩어리 (`PR-09` 토굴 숯가마 연계)\n  - 깨끗한 물에 헹군 고운 강 모래 1~2컵 (`PR-01` 여과재 연계)\n  - 정사각형 질긴 천(삼베, 무명천, 옷가지 조각) 2장 (가로세로 30cm)\n  - 머리 고정용 [질긴 칡 섬유 끈](/protocol-05.html) 또는 가죽 끈 2줄\n  - 안면 밀착 밀봉용 [소나무 송진 연고](/protocol-10.html) 또는 진흙 풀 약간\n\n---\n\n## 🖼️ [필수 사전 프리뷰] 16:9 초고화질 완성 결과물 도면 (Target Outcome)\n- **도면 파일명**: `pr15-outcome.svg` (16:9 와이드스크린, 800×450)\n- **도면 내용**: 좌측의 절구에서 곱게 빻은 다공성 활성탄 숯가루와 세척된 강 모래의 단면 분석, 중앙의 젖은 천 안쪽에 모래-숯-모래 3중 샌드위치 필터 파우치를 접어 넣는 팩 조립 단면도, 우측의 코와 입 주변에 안면 틈새 없이 밀착되어 칡 섬유 끈으로 머리 뒤에 견고히 묶여 짙은 화재 연기를 들이마셔도 깨끗한 공기만 폐로 공급되는 실전 착용 시연도.\n\n---\n\n## 📋 4단계 도면 및 실행 지침 (테크니컬 라이팅 & 넘버링 규격)\n\n### [Step 01] 고온 참나무 백탄 숯을 선별하여 돌절구에 빻아 소금 알갱이 크기의 다공성 흡착 숯가루 만들기\n- **실행**:\n  1. **고밀도 백탄 선별**: [토굴 숯가마](/protocol-09.html)에서 완전히 탄화되어 두드렸을 때 쇳소리가 나는 **참나무 백탄 숯 2~3덩어리**를 고릅니다.\n  2. **돌절구 분쇄**: 단단한 바위 홈(돌절구)에 숯을 넣고 둥근 돌공이로 빻아 너무 미세한 분진이 호흡기로 들어가지 않도록 **굵은 소금 알갱이 크기(약 1~2mm)**로 균일하게 분쇄합니다.\n  3. **물 세척 및 잔류 분진 거르기**: 빻은 숯가루를 맑은 물에 한 번 통과시켜 미세한 검은 뜬 숯가루를 흘려보내고 물기를 뺍니다.\n- **도면 파일명**: `pr15-step-01.svg`\n\n### [Step 02] 젖은 강 모래를 세척하여 열기 냉각 및 중형 비산재 포집용 완충 완충재 준비하기\n- **실행**:\n  1. **미세 강 모래 채취**: 개울가 바닥에서 진흙과 유기물이 섞이지 않은 **깨끗한 규암질 강 모래 1~2컵**을 채취합니다.\n  2. **물 헹굼 세척**: 코펠이나 [점토 화덕 그릇](/protocol-06.html)에 모래를 담고 물을 부어 휘저으며 탁한 흙탕물을 3회 이상 씻어냅니다.\n  3. **적정 수분 유지**: 손으로 쥐었을 때 뭉쳐지되 물방울이 뚝뚝 떨어지지 않을 정도의 **촉촉한 수분 상태**를 유지하여 고온 유독 연기의 온도를 즉시 식혀주는 냉각층 역할을 부여합니다.\n- **도면 파일명**: `pr15-step-02.svg`\n\n### [Step 03] 질긴 천 위에 모래-숯가루-모래 3중 샌드위치 필터층을 적층하고 마스크 파우치로 접어 포장하기\n- **실행**:\n  1. **바닥 천 전개**: 물에 적신 가로세로 30cm 삼베나 면포를 마름모꼴로 평평한 바위 위에 펼칩니다.\n  2. **3중 필터 적층**: 천 중앙 손바닥 크기 면적에 **세척 모래 1cm ➔ 숯가루 2cm ➔ 세척 모래 1cm** 순서로 샌드위치 적층합니다.\n  3. **파우치 봉투 접기**: 사방의 천 모서리를 중앙으로 접어 모래와 숯가루가 밖으로 새어 나오지 않도록 감싸고, [뼈바늘과 힘줄 실](/protocol-14.html)이나 칡 섬유로 가장자리를 3~4군데 가봉하여 고정합니다.\n- **도면 파일명**: `pr15-step-03.svg`\n\n### [Step 04] 코와 입에 필터 파우치를 완전 밀착하고 칡 섬유 끈으로 귀 위·목 뒤에 이중 결속하여 기밀 탈출하기\n- **실행**:\n  1. **안면 기밀 밀착**: 숯 필터가 코와 입 전체를 완전히 덮도록 안면에 밀착하고, 뺨과 턱 주변의 미세 틈새를 손가락으로 꾹꾹 눌러 성형합니다.\n  2. **이중 결속 끈 묶기**: 마스크 양 끝에 결속한 끈 2가닥 중 윗줄은 **귀 위를 지나 정수리 뒤쪽**, 아랫줄은 **귀 아래를 지나 목덜미 뒤**에서 단단히 매듭짓습니다.\n  3. **음압 호흡 테스트**: 양손으로 마스크 겉면을 가볍게 누른 상태에서 강하게 숨을 들이쉬어, 공기가 틈새로 새지 않고 **천과 숯가루 필터층을 강하게 통과하여 서늘한 공기가 흡입**되는지 확인 후 화재 구역을 15분 안에 신속히 탈출합니다.\n- **도면 파일명**: `pr15-step-04.svg`"};

export function ensureContentAvailable() {
  const defaultProtocolsDir = path.join(projectRoot, 'content/protocols');
  const defaultLocalesDir = path.join(projectRoot, 'content/protocols/locales');
  if (
    fs.existsSync(defaultProtocolsDir) &&
    fs.readdirSync(defaultProtocolsDir).some((f) => f.endsWith('.json')) &&
    fs.existsSync(defaultLocalesDir) &&
    fs.readdirSync(defaultLocalesDir).some((f) => f.endsWith('.es.json'))
  ) {
    return projectRoot;
  }

  const fallbackRoot = path.join(os.tmpdir(), 'survival-bundled-root');
  for (const [relPath, content] of Object.entries(EMBEDDED_CONTENT)) {
    const targetPath = path.join(fallbackRoot, relPath);
    fs.mkdirSync(path.dirname(targetPath), { recursive: true });
    fs.writeFileSync(targetPath, content, 'utf-8');
  }
  process.env.SURVIVAL_ROOT_DIR = fallbackRoot;
  return fallbackRoot;
}
